../src/components/sidebar/tabs/modelLibrary/ModelPreview.vue","../../src/platform/assets/utils/resolveModelNodeFromAsset.ts","../../src/composables/node/startModelNodeDragFromAsset.ts","../../src/composables/useTreeExpansion.ts","../../src/components/sidebar/tabs/ModelLibrarySidebarTab.vue","../../src/platform/assets/composables/openModelLibraryBrowser.ts","../../src/composables/sidebarTabs/useModelLibrarySidebarTab.ts","../../src/components/node/renderNodePreview.ts","../../src/components/sidebar/tabs/nodeLibrary/NodeHelpPage.vue","../../src/stores/workspace/nodeHelpStore.ts","../../src/components/common/ColorCustomizationSelector.vue","../../src/components/common/CustomizationDialog.vue","../../src/components/sidebar/tabs/nodeLibrary/NodeBookmarkTreeExplorer.vue","../../src/components/sidebar/tabs/NodeLibrarySidebarTab.vue","../../src/components/common/FilterDropdown.vue","../../src/composables/usePerTabState.ts","../../src/composables/node/useNodePreviewAndDrag.ts","../../src/components/common/TreeExplorerV2Node.vue","../../src/components/common/TreeExplorerV2.vue","../../src/types/nodeOrganizationTypes.ts","../../src/components/sidebar/tabs/nodeLibrary/AllNodesPanel.vue","../../src/composables/useEssentialTileNodeDef.ts","../../src/components/common/MarqueeLine.vue","../../src/utils/textTickerUtils.ts","../../src/components/common/TextTickerMultiLine.vue","../../src/components/sidebar/tabs/nodeLibrary/EssentialNodeCard.vue","../../src/components/sidebar/tabs/nodeLibrary/EssentialNodesPanel.vue","../../src/components/sidebar/tabs/NodeLibrarySidebarTabV2.vue","../../src/composables/sidebarTabs/useNodeLibrarySidebarTab.ts","../../src/components/common/TextDivider.vue","../../src/components/sidebar/tabs/workflows/WorkflowTreeLeaf.vue","../../src/components/sidebar/tabs/BaseWorkflowsSidebarTab.vue","../../src/components/sidebar/tabs/AppsSidebarTab.vue","../../src/platform/workflow/management/composables/useAppsSidebarTab.ts","../../src/components/sidebar/tabs/WorkflowsSidebarTab.vue","../../src/platform/workflow/management/composables/useWorkflowsSidebarTab.ts","../../src/composables/sidebarTabs/registerCoreSidebarTabs.ts","../../src/composables/useBrowserTabTitle.ts","../../src/utils/gridUtil.ts","../../src/components/widget/SampleModelSelector.vue","../../src/composables/useModelSelectorDialog.ts","../../src/platform/onboarding/onboardingReset.ts","../../src/composables/useCoreCommands.ts","../../src/platform/remote/comfyui/useQueuePolling.ts","../../src/composables/useReconnectQueueRefresh.ts","../../src/composables/useReconnectingNotification.ts","../../src/composables/useProgressFavicon.ts","../../src/platform/workflow/templates/utils/refreshDownloadedTemplateInputBindings.ts","../../src/types/serverArgs.ts","../../src/constants/serverConfig.ts","../../src/platform/assets/components/AssetFilterBar.vue","../../src/platform/assets/components/AssetBadgeGroup.vue","../../src/platform/assets/components/AssetCard.vue","../../src/platform/assets/components/AssetGrid.vue","../../../../../../../../assets/images/civitai.svg","../../../../../../../../assets/images/hf-logo.svg","../../src/platform/assets/components/modelInfo/ModelInfoPanel.vue","../../src/platform/assets/composables/useAssetBrowser.ts","../../src/platform/assets/components/AssetBrowserModal.vue","../../src/components/ui/toast/ToastPanel.vue","../../src/platform/assets/components/AssetExportProgressDialog.vue","../../src/components/toast/ProgressToastItem.vue","../../src/platform/assets/components/ModelImportProgressDialog.vue","../../src/platform/cloud/notification/components/DesktopCloudNotificationController.vue","../../src/platform/settings/components/SettingsWorkspaceHeader.vue","../../src/components/dialog/content/setting/CurrentUserMessage.vue","../../src/platform/settings/components/ColorPaletteMessage.vue","../../src/platform/settings/components/SettingItem.vue","../../src/platform/settings/components/SettingGroup.vue","../../src/platform/settings/components/SettingsPanel.vue","../../src/platform/settings/composables/useSettingSearch.ts","../../src/platform/settings/composables/useSettingUI.ts","../../src/platform/settings/components/SettingDialog.vue","../../src/platform/updates/common/versionCompatibilityStore.ts","../../src/platform/updates/common/useFrontendVersionMismatchWarning.ts","../../src/services/autoQueueService.ts","../../src/components/builder/ViewTypeRadioGroup.vue","../../src/components/builder/BuilderOpensAsPopover.vue","../../src/components/builder/builderViewOptions.ts","../../src/components/builder/ConnectOutputPopover.vue","../../src/components/builder/BuilderSaveDialogContent.vue","../../src/components/builder/useBuilderSave.ts","../../src/components/builder/useBuilderSteps.ts","../../src/components/builder/BuilderFooterToolbar.vue","../../src/components/builder/BuilderMenu.vue","../../src/components/builder/StepBadge.vue","../../src/components/builder/StepLabel.vue","../../src/components/builder/BuilderToolbar.vue","../../src/components/appMode/AppModeToolbar.vue","../../src/renderer/extensions/linearMode/linearRunErrorWarningIds.ts","../../src/renderer/extensions/linearMode/LinearRunErrorWarning.vue","../../src/renderer/extensions/linearMode/PartnerNodeItem.vue","../../src/renderer/extensions/linearMode/PartnerNodesList.vue","../../src/renderer/extensions/linearMode/LinearControls.vue","../../src/components/ui/ZoomPane.vue","../../src/renderer/extensions/linearMode/getExecutionStatusMessage.ts","../../src/renderer/extensions/linearMode/useExecutionStatus.ts","../../src/renderer/extensions/linearMode/ImagePreview.vue","../../src/renderer/extensions/linearMode/LatentPreview.vue","../../src/renderer/extensions/linearMode/LinearWelcome.vue","../../src/renderer/extensions/linearMode/flattenNodeOutput.ts","../../src/renderer/extensions/linearMode/VideoPreview.vue","../../src/renderer/extensions/linearMode/mediaTypes.ts","../../src/renderer/extensions/linearMode/MediaOutputPreview.vue","../../src/renderer/extensions/linearMode/LinearArrange.vue","../../src/renderer/extensions/linearMode/OutputHistoryActiveQueueItem.vue","../../src/renderer/extensions/linearMode/OutputHistoryItem.vue","../../src/renderer/extensions/linearMode/linearOutputStore.ts","../../src/renderer/extensions/linearMode/LinearProgressBar.vue","../../src/renderer/extensions/linearMode/OutputPreviewItem.vue","../../src/renderer/extensions/linearMode/useOutputHistory.ts","../../src/renderer/extensions/linearMode/OutputHistory.vue","../../src/renderer/extensions/linearMode/LinearPreview.vue","../../src/components/common/Dialogue.vue","../../src/renderer/extensions/linearMode/MobileError.vue","../../src/renderer/extensions/linearMode/MobileDisplay.vue","../../src/views/LinearView.vue","../../src/workbench/extensions/manager/components/ManagerProgressToast.vue","../../src/views/GraphView.vue"],"sourcesContent":["/**\n * Cross-browser async utilities for scheduling tasks during browser idle time\n * with proper fallbacks for browsers that don't support requestIdleCallback.\n *\n * Implementation based on:\n * https://github.com/microsoft/vscode/blob/main/src/vs/base/common/async.ts\n */\n\ninterface IdleDeadline {\n  didTimeout: boolean\n  timeRemaining(): number\n}\n\ninterface IDisposable {\n  dispose(): void\n}\ntype GlobalWindow = typeof globalThis\n\n/**\n * Internal implementation function that handles the actual scheduling logic.\n * Uses feature detection to determine whether to use native requestIdleCallback\n * or fall back to setTimeout-based implementation.\n */\nlet _runWhenIdle: (\n  targetWindow: GlobalWindow,\n  callback: (idle: IdleDeadline) => void,\n  timeout?: number\n) => IDisposable\n\n/**\n * Execute the callback during the next browser idle period.\n * Falls back to setTimeout-based scheduling in browsers without native support.\n */\nexport let runWhenGlobalIdle: (\n  callback: (idle: IdleDeadline) => void,\n  timeout?: number\n) => IDisposable\n\n// Self-invoking function to set up the idle callback implementation\n;(function () {\n  const safeGlobal: GlobalWindow = globalThis\n\n  if (\n    typeof safeGlobal.requestIdleCallback !== 'function' ||\n    typeof safeGlobal.cancelIdleCallback !== 'function'\n  ) {\n    // Fallback implementation for browsers without native support (e.g., Safari)\n    _runWhenIdle = (_targetWindow, runner, _timeout?) => {\n      setTimeout(() => {\n        if (disposed) {\n          return\n        }\n\n        // Simulate IdleDeadline - give 15ms window (one frame at ~64fps)\n        const end = Date.now() + 15\n        const deadline: IdleDeadline = {\n          didTimeout: true,\n          timeRemaining() {\n            return Math.max(0, end - Date.now())\n          }\n        }\n\n        runner(Object.freeze(deadline))\n      })\n\n      let disposed = false\n      return {\n        dispose() {\n          if (disposed) {\n            return\n          }\n          disposed = true\n        }\n      }\n    }\n  } else {\n    // Native requestIdleCallback implementation\n    _runWhenIdle = (targetWindow: typeof safeGlobal, runner, timeout?) => {\n      const handle: number = targetWindow.requestIdleCallback(\n        runner,\n        typeof timeout === 'number' ? { timeout } : undefined\n      )\n\n      let disposed = false\n      return {\n        dispose() {\n          if (disposed) {\n            return\n          }\n          disposed = true\n          targetWindow.cancelIdleCallback(handle)\n        }\n      }\n    }\n  }\n\n  runWhenGlobalIdle = (runner, timeout) =>\n    _runWhenIdle(globalThis, runner, timeout)\n})()\n","<template>\n  <div\n    v-show=\"workspaceState.focusMode\"\n    class=\"no-drag fixed top-0 right-0 z-9999 flex flex-row\"\n  >\n    <Button\n      :tooltip=\"$t('menu.showMenu')\"\n      variant=\"muted-textonly\"\n      size=\"lg\"\n      :aria-label=\"$t('menu.showMenu')\"\n      aria-live=\"assertive\"\n      @click=\"exitFocusMode\"\n      @contextmenu=\"showNativeSystemMenu\"\n    >\n      <i class=\"pi pi-bars\" />\n    </Button>\n    <div class=\"window-actions-spacer\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { watchEffect } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { app } from '@/scripts/app'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport { showNativeSystemMenu } from '@/utils/envUtil'\n\nconst workspaceState = useWorkspaceStore()\nconst settingStore = useSettingStore()\nconst exitFocusMode = () => {\n  workspaceState.focusMode = false\n}\n\nwatchEffect(() => {\n  if (settingStore.get('Comfy.UseNewMenu') !== 'Disabled') {\n    return\n  }\n  if (workspaceState.focusMode) {\n    app.ui.menuContainer.style.display = 'none'\n  } else {\n    app.ui.menuContainer.style.display = 'block'\n  }\n})\n</script>\n","<template>\n  <div>\n    <!--\n    UnloadWindowConfirmDialog: This component does not render\n    anything visible. It is used to confirm the user wants to\n    close the window, and if they do, it will call the\n    beforeunload event.\n    -->\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { onBeforeUnmount, onMounted } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\n\nconst settingStore = useSettingStore()\nconst workflowStore = useWorkflowStore()\n\nconst handleBeforeUnload = (event: BeforeUnloadEvent) => {\n  if (\n    settingStore.get('Comfy.Window.UnloadConfirmation') &&\n    workflowStore.modifiedWorkflows.length > 0\n  ) {\n    event.preventDefault()\n    return true\n  }\n  return undefined\n}\n\nonMounted(() => {\n  window.addEventListener('beforeunload', handleBeforeUnload)\n})\n\nonBeforeUnmount(() => {\n  window.removeEventListener('beforeunload', handleBeforeUnload)\n})\n</script>\n","<script setup lang=\"ts\">\nimport type { SplitterGroupEmits, SplitterGroupProps } from 'reka-ui'\nimport { SplitterGroup, useForwardPropsEmits } from 'reka-ui'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  direction = 'horizontal',\n  class: className,\n  ...restProps\n} = defineProps<\n  Omit<SplitterGroupProps, 'direction'> & {\n    direction?: SplitterGroupProps['direction']\n    class?: HTMLAttributes['class']\n  }\n>()\nconst emit = defineEmits<SplitterGroupEmits>()\nconst forwarded = useForwardPropsEmits(restProps, emit)\n</script>\n\n<template>\n  <SplitterGroup\n    v-bind=\"forwarded\"\n    :direction\n    :class=\"\n      cn('flex size-full', direction === 'vertical' && 'flex-col', className)\n    \"\n  >\n    <slot />\n  </SplitterGroup>\n</template>\n","<script setup lang=\"ts\">\nimport type { SplitterPanelEmits, SplitterPanelProps } from 'reka-ui'\nimport { SplitterPanel, useForwardExpose, useForwardPropsEmits } from 'reka-ui'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: className, ...restProps } = defineProps<\n  SplitterPanelProps & { class?: HTMLAttributes['class'] }\n>()\nconst emit = defineEmits<SplitterPanelEmits>()\nconst forwarded = useForwardPropsEmits(restProps, emit)\nconst { forwardRef } = useForwardExpose()\n</script>\n\n<template>\n  <SplitterPanel\n    :ref=\"forwardRef\"\n    v-bind=\"forwarded\"\n    :class=\"cn('min-h-0 min-w-0', className)\"\n  >\n    <slot />\n  </SplitterPanel>\n</template>\n","<script setup lang=\"ts\">\nimport type {\n  SplitterResizeHandleEmits,\n  SplitterResizeHandleProps\n} from 'reka-ui'\nimport { SplitterResizeHandle, useForwardPropsEmits } from 'reka-ui'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: className, ...restProps } = defineProps<\n  SplitterResizeHandleProps & { class?: HTMLAttributes['class'] }\n>()\nconst emit = defineEmits<SplitterResizeHandleEmits>()\nconst forwarded = useForwardPropsEmits(restProps, emit)\n</script>\n\n<template>\n  <SplitterResizeHandle\n    v-bind=\"forwarded\"\n    :class=\"\n      cn(\n        'relative z-10 flex w-px shrink-0 items-center justify-center bg-border-default outline-none',\n        'after:absolute after:inset-y-0 after:left-1/2 after:w-1 after:-translate-x-1/2',\n        'hover:bg-primary-background data-[state=drag]:bg-primary-background',\n        'focus-visible:ring-1 focus-visible:ring-border-default',\n        'data-[orientation=vertical]:h-px data-[orientation=vertical]:w-full',\n        'data-[orientation=vertical]:after:inset-x-0 data-[orientation=vertical]:after:top-1/2 data-[orientation=vertical]:after:h-1 data-[orientation=vertical]:after:w-full data-[orientation=vertical]:after:translate-x-0 data-[orientation=vertical]:after:-translate-y-1/2',\n        className\n      )\n    \"\n  >\n    <slot />\n  </SplitterResizeHandle>\n</template>\n","import { StorageSerializers, useStorage } from '@vueuse/core'\nimport type { SplitterPanel } from 'reka-ui'\nimport { computed, nextTick, shallowRef, toValue, watch } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\ninterface SidePanelSizingConfig {\n  id: string\n  storageKey: MaybeRefOrGetter<string>\n  visible: MaybeRefOrGetter<boolean>\n  minWidth: MaybeRefOrGetter<number>\n  defaultWidth: () => number\n}\n\nexport function usePanelSizing(\n  panelConfigs: readonly [SidePanelSizingConfig, SidePanelSizingConfig],\n  containerWidth: MaybeRefOrGetter<number>,\n  reservedWidth: MaybeRefOrGetter<number>\n) {\n  function storePanel(config: SidePanelSizingConfig) {\n    const width = useStorage<number | null>(\n      config.storageKey,\n      null,\n      undefined,\n      {\n        serializer: StorageSerializers.number\n      }\n    )\n    watch(\n      [width, () => toValue(config.visible)],\n      () => {\n        if (!toValue(config.visible)) return\n        if (\n          width.value === null ||\n          !Number.isFinite(width.value) ||\n          width.value <= 0\n        ) {\n          width.value = config.defaultWidth()\n        }\n      },\n      { immediate: true }\n    )\n    return { ...config, width }\n  }\n  const storedPanels: readonly [\n    ReturnType<typeof storePanel>,\n    ReturnType<typeof storePanel>\n  ] = [storePanel(panelConfigs[0]), storePanel(panelConfigs[1])]\n\n  const panelPercentages = computed<readonly [number, number, number]>(() => {\n    const total = toValue(containerWidth)\n    if (total <= 0) return [20, 60, 20]\n    const minimums: readonly [number, number] = [\n      toValue(storedPanels[0].visible) ? toValue(storedPanels[0].minWidth) : 0,\n      toValue(storedPanels[1].visible) ? toValue(storedPanels[1].minWidth) : 0\n    ]\n    const excesses: readonly [number, number] = [\n      toValue(storedPanels[0].visible)\n        ? Math.max(\n            0,\n            (storedPanels[0].width.value ?? storedPanels[0].defaultWidth()) -\n              minimums[0]\n          )\n        : 0,\n      toValue(storedPanels[1].visible)\n        ? Math.max(\n            0,\n            (storedPanels[1].width.value ?? storedPanels[1].defaultWidth()) -\n              minimums[1]\n          )\n        : 0\n    ]\n    const excess = excesses[0] + excesses[1]\n    const available = Math.max(\n      0,\n      total - toValue(reservedWidth) - minimums[0] - minimums[1]\n    )\n    const scale = excess > 0 ? Math.min(1, available / excess) : 0\n    const first = ((minimums[0] + excesses[0] * scale) / total) * 100\n    const last = ((minimums[1] + excesses[1] * scale) / total) * 100\n    return [first, 100 - first - last, last]\n  })\n\n  const layoutKey = computed(() =>\n    storedPanels\n      .map((panel) => `${toValue(panel.storageKey)}:${toValue(panel.visible)}`)\n      .join(':')\n  )\n  const panelRefs = {\n    first: shallowRef<InstanceType<typeof SplitterPanel>>(),\n    last: shallowRef<InstanceType<typeof SplitterPanel>>()\n  }\n  watch(\n    [() => toValue(containerWidth), layoutKey, panelRefs.first, panelRefs.last],\n    async () => {\n      await nextTick()\n      const updates = [panelRefs.first.value, panelRefs.last.value].flatMap(\n        (splitterPanel, index) => {\n          if (!splitterPanel || !toValue(storedPanels[index].visible)) return []\n          const size = panelPercentages.value[index * 2]\n          return [\n            { splitterPanel, size, delta: size - splitterPanel.getSize() }\n          ]\n        }\n      )\n      for (const { splitterPanel, size } of updates.sort(\n        (a, b) => a.delta - b.delta\n      )) {\n        splitterPanel.resize(size)\n      }\n    },\n    { flush: 'post' }\n  )\n  let gesture:\n    | Array<{\n        index: number\n        element: HTMLElement\n        width: number\n        key: string\n      }>\n    | undefined\n\n  function capturePanel(panelId: string) {\n    if (gesture?.some(({ element }) => !element.isConnected))\n      gesture = undefined\n    if (gesture) return\n    if (!storedPanels.some((panel) => panel.id === panelId)) return\n    gesture = storedPanels.flatMap((panel, index) => {\n      if (!toValue(panel.visible)) return []\n      const element = document.querySelector(`[data-panel-id=\"${panel.id}\"]`)\n      if (!(element instanceof HTMLElement)) return []\n      return [\n        {\n          index,\n          element,\n          width: element.getBoundingClientRect().width,\n          key: toValue(panel.storageKey)\n        }\n      ]\n    })\n  }\n\n  function onResizeStart(event: Event) {\n    const handle =\n      event.target instanceof Element\n        ? event.target.closest(\n            '[data-panel-resize-handle-id][data-orientation=\"horizontal\"]'\n          )\n        : null\n    if (!handle) return\n    const adjacent = [handle.previousElementSibling, handle.nextElementSibling]\n    const panel = storedPanels.find(({ id }) =>\n      adjacent.some((element) => element?.getAttribute('data-panel-id') === id)\n    )\n    if (panel) capturePanel(panel.id)\n  }\n\n  function onResizeDragging(dragging: boolean, panelId: string) {\n    if (dragging) capturePanel(panelId)\n    else onResizeEnd()\n  }\n\n  function onResizeEnd() {\n    if (!gesture) return\n    for (const captured of gesture) {\n      const panel = storedPanels[captured.index]\n      const width = captured.element.getBoundingClientRect().width\n      if (\n        captured.element.isConnected &&\n        width > 0 &&\n        width !== captured.width &&\n        toValue(panel.storageKey) === captured.key\n      ) {\n        panel.width.value = width\n      }\n    }\n    gesture = undefined\n  }\n\n  return {\n    panelPercentages,\n    panelRefs,\n    onResizeStart,\n    onResizeDragging,\n    onResizeEnd\n  }\n}\n","function getStorage() {\n  try {\n    return globalThis.localStorage\n  } catch {\n    return undefined\n  }\n}\n\nexport function loadSplitterSizes(\n  key: string,\n  panelCount: number,\n  storage = getStorage()\n): number[] | undefined {\n  if (!storage) return undefined\n  try {\n    const value: unknown = JSON.parse(storage.getItem(key) ?? 'null')\n    if (\n      !Array.isArray(value) ||\n      !value.every(\n        (size): size is number =>\n          typeof size === 'number' && Number.isFinite(size) && size >= 0\n      ) ||\n      value.reduce((total, size) => total + size, 0) <= 0\n    ) {\n      return undefined\n    }\n    if (value.length === panelCount) return value\n    if (\n      panelCount === 2 &&\n      value.length === 3 &&\n      (key === 'builder-splitter' || key === 'builder-splitter-right')\n    ) {\n      const visible =\n        key === 'builder-splitter' ? value.slice(1) : value.slice(0, 2)\n      const total = visible[0] + visible[1]\n      if (total > 0) return visible.map((size) => (size / total) * 100)\n    }\n  } catch {\n    return undefined\n  }\n  return undefined\n}\n\nexport function saveSplitterSizes(\n  key: string,\n  sizes: number[],\n  storage = getStorage()\n) {\n  try {\n    storage?.setItem(key, JSON.stringify(sizes))\n    return Boolean(storage)\n  } catch {\n    return false\n  }\n}\n","/**\n * A side panel's size (%) from the first usable PrimeVue Splitter state among\n * `stateKeys`, saved before side panels were pinned in pixels. `edge` picks\n * the first or the last panel of the saved sizes, scaled so they sum to 100.\n */\nfunction isPositiveNumber(value: unknown): value is number {\n  return typeof value === 'number' && Number.isFinite(value) && value > 0\n}\n\nexport function savedPanelPercent(\n  readState: (stateKey: string) => string | null,\n  stateKeys: string[],\n  edge: 'first' | 'last'\n): number | null {\n  for (const stateKey of stateKeys) {\n    try {\n      const sizes: unknown = JSON.parse(readState(stateKey) ?? 'null')\n      if (!Array.isArray(sizes) || !sizes.every(isPositiveNumber)) continue\n      const total = sizes.reduce((sum, size) => sum + size, 0)\n      const size = edge === 'first' ? sizes[0] : sizes.at(-1)\n      if (size !== undefined && size < total) return (size / total) * 100\n    } catch {\n      continue\n    }\n  }\n  return null\n}\n","<template>\n  <div\n    class=\"pointer-events-none absolute top-0 left-0 z-999 flex size-full flex-col\"\n  >\n    <slot name=\"workflow-tabs\" />\n\n    <div class=\"pointer-events-none flex min-h-0 flex-1 flex-row\">\n      <div\n        :class=\"\n          cn(\n            'pointer-events-none flex min-w-0 flex-1 overflow-hidden',\n            sidebarLocation === 'left' ? 'flex-row' : 'flex-row-reverse'\n          )\n        \"\n      >\n        <div class=\"side-toolbar-container\">\n          <slot name=\"side-toolbar\" />\n        </div>\n\n        <div\n          ref=\"mainSplitterRef\"\n          class=\"pointer-events-none min-w-0 flex-1 overflow-hidden\"\n        >\n          <SplitterGroup\n            class=\"pointer-events-none border-none bg-transparent\"\n            @keydown.capture=\"onResizeStart\"\n            @keyup=\"onResizeEnd\"\n            @focusout=\"onResizeEnd\"\n            @layout=\"saveMainSplitterLayout\"\n          >\n            <SplitterPanel\n              v-if=\"firstPanelMounted\"\n              v-show=\"firstPanelRendered\"\n              id=\"first-side-panel\"\n              :key=\"isSelectMode ? mainSplitterStateKey : 'first-side-panel'\"\n              :ref=\"panelRefs.first\"\n              :order=\"1\"\n              :class=\"\n                sidebarLocation === 'left'\n                  ? 'side-bar-panel pointer-events-auto bg-comfy-menu-bg focus-visible:outline-hidden'\n                  : 'pointer-events-auto bg-comfy-menu-bg focus-visible:outline-hidden'\n              \"\n              :min-size=\"\n                sidebarLocation === 'left'\n                  ? sidebarMinSize\n                  : isSelectMode\n                    ? BUILDER_MIN_SIZE\n                    : propertiesMinSize\n              \"\n              :default-size=\"firstPanelDefaultSize\"\n              :role=\"sidebarLocation === 'left' ? 'complementary' : undefined\"\n              :aria-label=\"\n                sidebarLocation === 'left'\n                  ? t('sideToolbar.sidebar')\n                  : undefined\n              \"\n            >\n              <slot\n                v-if=\"sidebarLocation === 'left' && sidebarPanelVisible\"\n                name=\"side-bar-panel\"\n              />\n              <slot\n                v-else-if=\"sidebarLocation === 'right'\"\n                name=\"right-side-panel\"\n              />\n            </SplitterPanel>\n            <SplitterResizeHandle\n              v-if=\"firstPanelMounted\"\n              :disabled=\"!firstPanelRendered\"\n              :tabindex=\"firstPanelRendered ? 0 : -1\"\n              :class=\"\n                cn(\n                  'pointer-events-auto',\n                  !firstPanelRendered && 'hidden',\n                  sidebarLocation === 'left' && 'bg-interface-stroke/50'\n                )\n              \"\n              @dragging=\"onResizeDragging($event, 'first-side-panel')\"\n            />\n\n            <SplitterPanel\n              id=\"main-panel\"\n              :order=\"2\"\n              :min-size=\"isSelectMode ? 0 : centerMinSize\"\n              :default-size=\"centerPanelDefaultSize\"\n              class=\"flex flex-col\"\n            >\n              <div\n                :class=\"!graphMeetsAgentPanel && 'mr-(--comfy-canvas-gutter)'\"\n              >\n                <slot name=\"topmenu\" :sidebar-panel-visible />\n              </div>\n\n              <SplitterGroup\n                data-testid=\"graph-canvas-gutter\"\n                :class=\"\n                  cn(\n                    'pointer-events-none mb-(--comfy-canvas-gutter) ml-(--comfy-canvas-gutter) h-auto flex-1 border-none bg-transparent',\n                    !graphMeetsAgentPanel && 'mr-(--comfy-canvas-gutter)'\n                  )\n                \"\n                direction=\"vertical\"\n                style=\"width: auto\"\n                @layout=\"saveBottomPanelLayout\"\n              >\n                <SplitterPanel\n                  id=\"graph-canvas-panel\"\n                  :order=\"1\"\n                  :default-size=\"bottomPanelDefaultSizes[0]\"\n                  class=\"graph-canvas-panel relative overflow-visible [anchor-name:--graph-canvas-panel]\"\n                >\n                  <slot name=\"graph-canvas-panel\" />\n                </SplitterPanel>\n                <SplitterResizeHandle\n                  :disabled=\"!bottomPanelRendered\"\n                  :tabindex=\"bottomPanelRendered ? 0 : -1\"\n                  :class=\"\n                    cn(\n                      'pointer-events-auto translate-y-1 rounded-t-lg',\n                      !bottomPanelRendered && 'hidden'\n                    )\n                  \"\n                  @dragging=\"!$event && flushLayouts()\"\n                />\n                <SplitterPanel\n                  v-show=\"bottomPanelRendered\"\n                  id=\"bottom-panel\"\n                  :order=\"2\"\n                  :default-size=\"bottomPanelDefaultSizes[1]\"\n                  class=\"bottom-panel pointer-events-auto max-w-full overflow-x-auto rounded-lg border border-interface-stroke bg-comfy-menu-bg focus-visible:outline-hidden\"\n                >\n                  <slot name=\"bottom-panel\" />\n                </SplitterPanel>\n              </SplitterGroup>\n            </SplitterPanel>\n\n            <SplitterResizeHandle\n              v-if=\"lastPanelMounted\"\n              :disabled=\"!lastPanelRendered\"\n              :tabindex=\"lastPanelRendered ? 0 : -1\"\n              :class=\"\n                cn(\n                  'pointer-events-auto',\n                  !lastPanelRendered && 'hidden',\n                  sidebarLocation === 'right' && 'bg-interface-stroke/50'\n                )\n              \"\n              @dragging=\"onResizeDragging($event, 'last-side-panel')\"\n            />\n            <SplitterPanel\n              v-if=\"lastPanelMounted\"\n              v-show=\"lastPanelRendered\"\n              id=\"last-side-panel\"\n              :key=\"isSelectMode ? mainSplitterStateKey : 'last-side-panel'\"\n              :ref=\"panelRefs.last\"\n              :order=\"3\"\n              :class=\"\n                sidebarLocation === 'right'\n                  ? 'side-bar-panel pointer-events-auto bg-comfy-menu-bg focus-visible:outline-hidden'\n                  : 'pointer-events-auto bg-comfy-menu-bg focus-visible:outline-hidden'\n              \"\n              :min-size=\"\n                sidebarLocation === 'right'\n                  ? sidebarMinSize\n                  : isSelectMode\n                    ? BUILDER_MIN_SIZE\n                    : propertiesMinSize\n              \"\n              :default-size=\"lastPanelDefaultSize\"\n              :role=\"sidebarLocation === 'right' ? 'complementary' : undefined\"\n              :aria-label=\"\n                sidebarLocation === 'right'\n                  ? t('sideToolbar.sidebar')\n                  : undefined\n              \"\n            >\n              <slot v-if=\"sidebarLocation === 'left'\" name=\"right-side-panel\" />\n              <slot\n                v-else-if=\"sidebarLocation === 'right' && sidebarPanelVisible\"\n                name=\"side-bar-panel\"\n              />\n            </SplitterPanel>\n          </SplitterGroup>\n        </div>\n      </div>\n\n      <slot\n        name=\"agent-panel\"\n        :has-opaque-neighbor=\"agentPanelHasOpaqueNeighbor\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useElementSize } from '@vueuse/core'\nimport { debounce } from 'es-toolkit/compat'\nimport { storeToRefs } from 'pinia'\nimport {\n  computed,\n  onBeforeUnmount,\n  ref,\n  shallowRef,\n  watch,\n  watchEffect\n} from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport SplitterGroup from '@/components/ui/splitter/SplitterGroup.vue'\nimport SplitterPanel from '@/components/ui/splitter/SplitterPanel.vue'\nimport SplitterResizeHandle from '@/components/ui/splitter/SplitterResizeHandle.vue'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { usePanelSizing } from '@/composables/usePanelSizing'\nimport {\n  BUILDER_MIN_SIZE,\n  CENTER_PANEL_MIN_WIDTH,\n  CENTER_PANEL_SIZE,\n  PROPERTIES_PANEL_MIN_WIDTH,\n  SIDEBAR_MIN_SIZE,\n  SIDEBAR_MIN_WIDTH,\n  SIDE_PANEL_SIZE,\n  SIDE_TOOLBAR_WIDTH\n} from '@/constants/splitterConstants'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useBottomPanelStore } from '@/stores/workspace/bottomPanelStore'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport {\n  loadSplitterSizes,\n  saveSplitterSizes\n} from '@/utils/splitterPersistence'\nimport { savedPanelPercent } from '@/utils/splitterWidthUtil'\nimport { useAgentPanelStore } from '@/workbench/extensions/agent/stores/agent/agentPanelStore'\n\nconst workspaceStore = useWorkspaceStore()\nconst settingStore = useSettingStore()\nconst rightSidePanelStore = useRightSidePanelStore()\nconst sidebarTabStore = useSidebarTabStore()\nconst agentPanelStore = useAgentPanelStore()\nconst { t } = useI18n()\nconst sidebarLocation = computed<'left' | 'right'>(() =>\n  settingStore.get('Comfy.Sidebar.Location')\n)\n\nconst unifiedWidth = computed(() =>\n  settingStore.get('Comfy.Sidebar.UnifiedWidth')\n)\n\nconst { focusMode } = storeToRefs(workspaceStore)\nconst { isPickingNodes: agentNodeSelectionActive } =\n  storeToRefs(useCanvasStore())\n\nconst { isSelectMode, isBuilderMode } = useAppMode()\nconst { activeSidebarTabId, activeSidebarTab } = storeToRefs(sidebarTabStore)\nconst { bottomPanelVisible } = storeToRefs(useBottomPanelStore())\nconst { isOpen: rightSidePanelVisible } = storeToRefs(rightSidePanelStore)\nconst { isVisible: agentPanelOpen } = storeToRefs(agentPanelStore)\nconst oppositeSidePanelVisible = computed(\n  () => rightSidePanelVisible.value || isSelectMode.value\n)\n\nconst agentPanelHasOpaqueNeighbor = computed(\n  () =>\n    (sidebarLocation.value === 'right' &&\n      sidebarPanelVisible.value &&\n      !agentNodeSelectionActive.value &&\n      !focusMode.value) ||\n    (sidebarLocation.value === 'left' &&\n      oppositeSidePanelVisible.value &&\n      !agentNodeSelectionActive.value &&\n      !focusMode.value)\n)\n\n/**\n * The graph's right gutter is what separates it from whatever is drawn beside\n * it. When that is the agent panel, the panel's own gutter already spaces the\n * two and a second one reads as a gap.\n */\nconst graphMeetsAgentPanel = computed(\n  () => agentPanelOpen.value && !agentPanelHasOpaqueNeighbor.value\n)\n\nconst sidebarPanelVisible = computed(\n  () => activeSidebarTab.value !== null && !isBuilderMode.value\n)\n\nwatchEffect(() => {\n  agentPanelStore.setReservedWorkspaceWidth(\n    SIDE_TOOLBAR_WIDTH +\n      (sidebarPanelVisible.value &&\n      !focusMode.value &&\n      !agentNodeSelectionActive.value\n        ? SIDEBAR_MIN_WIDTH\n        : 0)\n  )\n})\n\nconst firstPanelVisible = computed(\n  () => sidebarLocation.value === 'left' || oppositeSidePanelVisible.value\n)\nconst lastPanelVisible = computed(\n  () => sidebarLocation.value === 'right' || oppositeSidePanelVisible.value\n)\nconst firstPanelMounted = computed(\n  () =>\n    firstPanelVisible.value &&\n    (sidebarLocation.value === 'right' || sidebarPanelVisible.value)\n)\nconst lastPanelMounted = computed(\n  () =>\n    lastPanelVisible.value &&\n    (sidebarLocation.value === 'left' || sidebarPanelVisible.value)\n)\nconst firstPanelRendered = computed(\n  () =>\n    firstPanelMounted.value &&\n    !focusMode.value &&\n    !agentNodeSelectionActive.value\n)\nconst lastPanelRendered = computed(\n  () =>\n    lastPanelMounted.value &&\n    !focusMode.value &&\n    !agentNodeSelectionActive.value\n)\nconst bottomPanelRendered = computed(\n  () =>\n    bottomPanelVisible.value &&\n    !focusMode.value &&\n    !agentNodeSelectionActive.value\n)\n\nconst bothSidePanelsVisible = computed(\n  () =>\n    !focusMode.value &&\n    sidebarPanelVisible.value &&\n    oppositeSidePanelVisible.value\n)\n\nconst mainSplitterRef = ref<HTMLElement | null>(null)\nconst { width: mainSplitterWidth } = useElementSize(mainSplitterRef)\nconst availableSplitterWidth = computed(() =>\n  Math.max(\n    0,\n    mainSplitterWidth.value -\n      Number(firstPanelRendered.value) -\n      Number(lastPanelRendered.value)\n  )\n)\nconst centerMinSize = computed(() =>\n  availableSplitterWidth.value > 0\n    ? (CENTER_PANEL_MIN_WIDTH / availableSplitterWidth.value) * 100\n    : 0\n)\nconst sidebarMinSize = computed(() =>\n  availableSplitterWidth.value\n    ? (SIDEBAR_MIN_WIDTH / availableSplitterWidth.value) * 100\n    : SIDEBAR_MIN_SIZE\n)\nconst propertiesMinSize = computed(() =>\n  availableSplitterWidth.value\n    ? (PROPERTIES_PANEL_MIN_WIDTH / availableSplitterWidth.value) * 100\n    : BUILDER_MIN_SIZE\n)\n\nconst centerPanelFallbackSize = computed(() =>\n  bothSidePanelsVisible.value ? 100 - 2 * SIDE_PANEL_SIZE : CENTER_PANEL_SIZE\n)\n\nconst sidebarTabKey = computed(() =>\n  unifiedWidth.value\n    ? 'unified-sidebar'\n    : (activeSidebarTabId.value ?? 'default-sidebar')\n)\n\nconst sidebarStateKey = computed(() => {\n  const base = sidebarTabKey.value\n  if (sidebarLocation.value === 'left' && !oppositeSidePanelVisible.value) {\n    return base\n  }\n  const suffix = oppositeSidePanelVisible.value ? '-with-offside' : ''\n  return `${base}-${sidebarLocation.value}${suffix}`\n})\n\nconst mainSplitterStateKey = computed(() =>\n  isSelectMode.value\n    ? sidebarLocation.value === 'left'\n      ? 'builder-splitter'\n      : 'builder-splitter-right'\n    : sidebarStateKey.value\n)\nconst mainPanelCount = computed(\n  () => 1 + Number(firstPanelMounted.value) + Number(lastPanelMounted.value)\n)\nconst savedMainPanelSizes = shallowRef<number[]>()\nconst persistMainLayout = debounce(saveSplitterSizes, 100)\nconst persistBottomLayout = debounce(saveSplitterSizes, 100)\n\nfunction flushLayouts() {\n  persistMainLayout.flush()\n  persistBottomLayout.flush()\n}\n\nonBeforeUnmount(flushLayouts)\nwatch(mainSplitterStateKey, () => persistMainLayout.flush(), { flush: 'sync' })\nwatch(\n  [mainSplitterStateKey, mainPanelCount],\n  ([key, count]) => {\n    savedMainPanelSizes.value = loadSplitterSizes(key, count)\n  },\n  { immediate: true }\n)\nconst sidebarWidthKey = computed(() => {\n  const base =\n    sidebarLocation.value === 'left'\n      ? 'Comfy.Sidebar.LeftWidth'\n      : 'Comfy.Sidebar.RightWidth'\n  return unifiedWidth.value ? base : `${base}.${sidebarTabKey.value}`\n})\nfunction defaultPanelWidth(isSidebarPanel: boolean) {\n  const plainStateKey =\n    sidebarLocation.value === 'left'\n      ? sidebarTabKey.value\n      : `${sidebarTabKey.value}-right`\n  const offsideStateKey = `${sidebarTabKey.value}-${sidebarLocation.value}-with-offside`\n  const stateKeys = isSidebarPanel\n    ? oppositeSidePanelVisible.value\n      ? [offsideStateKey, plainStateKey]\n      : [plainStateKey, offsideStateKey]\n    : [offsideStateKey]\n  const edge =\n    (sidebarLocation.value === 'left') === isSidebarPanel ? 'first' : 'last'\n  const percent =\n    savedPanelPercent((key) => localStorage.getItem(key), stateKeys, edge) ??\n    SIDE_PANEL_SIZE\n  return Math.max(\n    isSidebarPanel ? SIDEBAR_MIN_WIDTH : PROPERTIES_PANEL_MIN_WIDTH,\n    Math.round((percent / 100) * (window.innerWidth - SIDE_TOOLBAR_WIDTH))\n  )\n}\nconst {\n  panelPercentages,\n  panelRefs,\n  onResizeStart,\n  onResizeDragging: updatePanelResize,\n  onResizeEnd: savePanelWidth\n} = usePanelSizing(\n  [\n    {\n      id: 'first-side-panel',\n      storageKey: () =>\n        sidebarLocation.value === 'left'\n          ? sidebarWidthKey.value\n          : 'Comfy.RightSidePanel.Width',\n      visible: () => firstPanelRendered.value && !isSelectMode.value,\n      minWidth: () =>\n        sidebarLocation.value === 'left'\n          ? SIDEBAR_MIN_WIDTH\n          : PROPERTIES_PANEL_MIN_WIDTH,\n      defaultWidth: () => defaultPanelWidth(sidebarLocation.value === 'left')\n    },\n    {\n      id: 'last-side-panel',\n      storageKey: () =>\n        sidebarLocation.value === 'right'\n          ? sidebarWidthKey.value\n          : 'Comfy.RightSidePanel.Width',\n      visible: () => lastPanelRendered.value && !isSelectMode.value,\n      minWidth: () =>\n        sidebarLocation.value === 'right'\n          ? SIDEBAR_MIN_WIDTH\n          : PROPERTIES_PANEL_MIN_WIDTH,\n      defaultWidth: () => defaultPanelWidth(sidebarLocation.value === 'right')\n    }\n  ],\n  availableSplitterWidth,\n  CENTER_PANEL_MIN_WIDTH\n)\n\nfunction onResizeEnd() {\n  savePanelWidth()\n  flushLayouts()\n}\n\nfunction onResizeDragging(dragging: boolean, panelId: string) {\n  updatePanelResize(dragging, panelId)\n  if (!dragging) flushLayouts()\n}\n\nconst firstPanelDefaultSize = computed(() =>\n  !isSelectMode.value\n    ? panelPercentages.value[0]\n    : (savedMainPanelSizes.value?.[0] ??\n      (sidebarLocation.value === 'left'\n        ? Math.max(SIDE_PANEL_SIZE, sidebarMinSize.value)\n        : SIDE_PANEL_SIZE))\n)\nconst centerPanelDefaultSize = computed(() => {\n  if (!isSelectMode.value) return panelPercentages.value[1]\n  const index = firstPanelRendered.value ? 1 : 0\n  return savedMainPanelSizes.value?.[index] ?? centerPanelFallbackSize.value\n})\nconst lastPanelDefaultSize = computed(() =>\n  !isSelectMode.value\n    ? panelPercentages.value[2]\n    : (savedMainPanelSizes.value?.[mainPanelCount.value - 1] ??\n      (sidebarLocation.value === 'right'\n        ? Math.max(SIDE_PANEL_SIZE, sidebarMinSize.value)\n        : SIDE_PANEL_SIZE))\n)\n\nfunction saveMainSplitterLayout(sizes: number[]) {\n  if (!isSelectMode.value || sizes.length === 1) return\n  savedMainPanelSizes.value = sizes\n  persistMainLayout(mainSplitterStateKey.value, sizes)\n}\n\nconst bottomPanelStateKey = 'bottom-panel-splitter'\nconst bottomPanelDefaultSizes = shallowRef(\n  loadSplitterSizes(bottomPanelStateKey, 2) ?? [50, 50]\n)\n\nfunction saveBottomPanelLayout(sizes: number[]) {\n  bottomPanelDefaultSizes.value = sizes\n  persistBottomLayout(bottomPanelStateKey, sizes)\n}\n</script>\n","<template>\n  <div role=\"status\" aria-live=\"polite\">\n    <div\n      v-if=\"gate !== 'none'\"\n      id=\"partner-run-gate-caption\"\n      class=\"mt-2 w-full border-t border-border-subtle bg-comfy-menu-bg px-4 pt-2 select-none\"\n      data-testid=\"partner-run-gate-caption\"\n    >\n      <div class=\"flex w-full items-center justify-center gap-2\">\n        <i\n          class=\"icon-[lucide--info] size-4 text-muted-foreground\"\n          aria-hidden=\"true\"\n        />\n        {{ t('actionbar.partnerRunGate.signInCaption') }}\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport { usePartnerNodesRunGate } from '@/composables/billing/usePartnerNodesRunGate'\n\nconst { t } = useI18n()\nconst { gate } = usePartnerNodesRunGate()\n</script>\n","import { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { clampPercentInt, formatPercent0 } from '@/utils/numberUtil'\n\nconst withDefault = <T>(value: T | null | undefined, fallback: T): T =>\n  value ?? fallback\n\n/**\n * Queue progress composable exposing total/current node progress values and styles.\n */\nexport function useQueueProgress() {\n  const { locale } = useI18n()\n  const executionStore = useExecutionStore()\n\n  const totalPercent = computed(() =>\n    clampPercentInt(\n      Math.round(withDefault(executionStore.executionProgress, 0) * 100)\n    )\n  )\n\n  const totalPercentFormatted = computed(() =>\n    formatPercent0(locale.value, totalPercent.value)\n  )\n\n  const currentNodePercent = computed(() =>\n    clampPercentInt(\n      Math.round((executionStore.executingNodeProgress ?? 0) * 100)\n    )\n  )\n\n  const currentNodePercentFormatted = computed(() =>\n    formatPercent0(locale.value, currentNodePercent.value)\n  )\n\n  const totalProgressStyle = computed(() => ({\n    transform: `scaleX(${totalPercent.value / 100})`,\n    background: 'var(--color-interface-panel-job-progress-primary)'\n  }))\n\n  const currentNodeProgressStyle = computed(() => ({\n    transform: `scaleX(${currentNodePercent.value / 100})`,\n    background: 'var(--color-interface-panel-job-progress-secondary)'\n  }))\n\n  return {\n    totalPercent,\n    totalPercentFormatted,\n    currentNodePercent,\n    currentNodePercentFormatted,\n    totalProgressStyle,\n    currentNodeProgressStyle\n  }\n}\n","<template>\n  <div\n    v-if=\"shouldShow\"\n    data-testid=\"queue-inline-progress\"\n    aria-hidden=\"true\"\n    :class=\"\n      cn('pointer-events-none absolute inset-0 overflow-hidden', radiusClass)\n    \"\n  >\n    <div\n      class=\"pointer-events-none absolute bottom-0 left-0 h-[3px] bg-interface-panel-job-progress-primary transition-[width]\"\n      :style=\"{ width: `${totalPercent}%` }\"\n    />\n    <div\n      data-testid=\"queue-inline-progress-node-fill\"\n      class=\"pointer-events-none absolute bottom-0 left-0 h-[3px] bg-interface-panel-job-progress-secondary transition-[width]\"\n      :style=\"{ width: `${currentNodePercent}%` }\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { useQueueProgress } from '@/composables/queue/useQueueProgress'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { hidden = false, radiusClass = 'rounded-[7px]' } = defineProps<{\n  hidden?: boolean\n  radiusClass?: string\n}>()\n\nconst { totalPercent, currentNodePercent } = useQueueProgress()\n\nconst shouldShow = computed(\n  () => !hidden && (totalPercent.value > 0 || currentNodePercent.value > 0)\n)\n</script>\n","import { computed } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\n\nexport function useQueueFeatureFlags() {\n  const settingStore = useSettingStore()\n\n  const isQueuePanelV2Enabled = computed(() =>\n    settingStore.get('Comfy.Queue.QPOV2')\n  )\n  const isRunProgressBarEnabled = computed(() =>\n    settingStore.get('Comfy.Queue.ShowRunProgressBar')\n  )\n\n  return {\n    isQueuePanelV2Enabled,\n    isRunProgressBarEnabled\n  }\n}\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useFreeTierQuota } from '@/platform/cloud/subscription/composables/useFreeTierQuota'\n\nconst DOT_COLORS = [\n  'bg-destructive-background',\n  'bg-warning-background',\n  'bg-success-background'\n]\n\nconst { isFreeTier, showSubscriptionDialog } = useBillingContext()\nconst { t } = useI18n()\nconst { available, hasInvalidNodes, maxAvailable, quotaEnabled } =\n  useFreeTierQuota()\n\nconst dotColor = computed(() => {\n  const ratio = maxAvailable.value ? available.value / maxAvailable.value : 0\n  return DOT_COLORS[\n    Math.min(Math.floor(ratio * DOT_COLORS.length), DOT_COLORS.length - 1)\n  ]\n})\nconst label = computed(() =>\n  t('actionbar.freeTierRuns', {\n    available: available.value,\n    MAX_AVAILABLE: maxAvailable.value\n  })\n)\n</script>\n<template>\n  <div\n    v-if=\"quotaEnabled && isFreeTier\"\n    class=\"mt-2 w-full cursor-pointer border-t border-border-subtle bg-comfy-menu-bg px-4 pt-2 select-none\"\n    data-testid=\"free-tier-quota\"\n    @click=\"showSubscriptionDialog({ reason: 'free_tier_quota' })\"\n  >\n    <div\n      v-if=\"hasInvalidNodes\"\n      class=\"flex w-full items-center justify-center gap-2\"\n    >\n      <i class=\"icon-[lucide--coins] bg-credit\" />\n      {{ t('actionbar.freeTierPartner') }}\n    </div>\n    <div v-else class=\"flex w-full items-center justify-between\">\n      <div class=\"flex gap-2\" :aria-label=\"label\" role=\"img\">\n        <div\n          v-for=\"index in maxAvailable\"\n          :key=\"index\"\n          :class=\"\n            cn(\n              'size-1.5 rounded-full',\n              index > available ? 'bg-secondary-background-selected' : dotColor\n            )\n          \"\n        />\n      </div>\n      <div v-text=\"label\" />\n    </div>\n  </div>\n</template>\n","import type { Directive } from 'vue'\n\nimport { registerCoachmark, unregisterCoachmark } from './coachmarkRegistry'\nimport type { CoachId } from './onboardingTours'\n\n// The element's `data-coach-id` is the record of what it is registered as.\nfunction sync(el: HTMLElement, id: CoachId | undefined | null) {\n  const prev = el.dataset.coachId as CoachId | undefined\n  if (prev === id) return\n  if (prev) {\n    unregisterCoachmark(prev, el)\n    delete el.dataset.coachId\n  }\n  if (id) {\n    el.dataset.coachId = id\n    registerCoachmark(id, el)\n  }\n}\n\n/**\n * Marks an element as a coach-mark target: registers it in the reactive\n * registry and mirrors the id to `data-coach-id` for e2e locators. A falsy\n * value is a no-op, so it can be bound to a conditional id.\n */\nexport const vCoachmark: Directive<HTMLElement, CoachId | undefined | null> = {\n  mounted: (el, { value }) => sync(el, value),\n  updated: (el, { value }) => sync(el, value),\n  unmounted: (el) => sync(el, null)\n}\n","import { defineAsyncComponent } from 'vue'\n\nimport { isCloud } from '@/platform/distribution/types'\n\nexport default isCloud\n  ? window.__CONFIG__?.subscription_required\n    ? defineAsyncComponent(() => import('./CloudRunButtonWrapper.vue'))\n    : defineAsyncComponent(() => import('./ComfyQueueButton.vue'))\n  : defineAsyncComponent(() => import('./LocalRunButtonWrapper.vue'))\n","<template>\n  <div :class=\"cn('flex h-full items-center', !isDocked && '-ml-2')\">\n    <div\n      v-if=\"isDragging && !isDocked\"\n      :class=\"actionbarClass\"\n      @mouseenter=\"onMouseEnterDropZone\"\n      @mouseleave=\"onMouseLeaveDropZone\"\n    >\n      {{ t('actionbar.dockToTop') }}\n    </div>\n\n    <div ref=\"panelRef\" :style :class=\"panelClass\">\n      <div class=\"relative flex items-center gap-2 select-none\">\n        <span\n          ref=\"dragHandleRef\"\n          :class=\"\n            cn(\n              'drag-handle h-max w-3 cursor-grab',\n              isDragging && 'cursor-grabbing'\n            )\n          \"\n        />\n        <div v-coachmark=\"FIRST_RUN_COACH_IDS.runButton\" class=\"inline-flex\">\n          <Suspense @resolve=\"comfyRunButtonResolved\">\n            <ComfyRunButton />\n          </Suspense>\n        </div>\n        <Button\n          :tooltip=\"t('menu.interrupt')\"\n          tooltip-side=\"bottom\"\n          :variant=\"isExecutionIdle ? 'secondary' : 'destructive'\"\n          size=\"icon\"\n          :disabled=\"isExecutionIdle\"\n          :aria-label=\"t('menu.interrupt')\"\n          @click=\"cancelCurrentJob\"\n        >\n          <i class=\"icon-[lucide--x] size-4\" />\n        </Button>\n        <Button\n          :tooltip=\"queueToggleLabel\"\n          tooltip-side=\"bottom\"\n          variant=\"secondary\"\n          size=\"md\"\n          :aria-pressed=\"\n            isQueuePanelV2Enabled\n              ? activeSidebarTabId === 'job-history'\n              : queueOverlayExpanded\n          \"\n          class=\"relative px-3\"\n          data-testid=\"queue-overlay-toggle\"\n          @click=\"toggleQueueOverlay\"\n          @contextmenu.stop.prevent=\"showQueueContextMenu\"\n        >\n          <span class=\"text-sm font-normal tabular-nums\">\n            {{ activeJobsLabel }}\n          </span>\n          <StatusBadge\n            v-if=\"activeJobsCount > 0\"\n            data-testid=\"active-jobs-indicator\"\n            variant=\"dot\"\n            class=\"pointer-events-none absolute -top-0.5 -right-0.5 animate-pulse\"\n          />\n          <span class=\"sr-only\">{{ queueToggleLabel }}</span>\n        </Button>\n        <ContextMenu ref=\"queueContextMenu\" :model=\"queueContextMenuItems\" />\n      </div>\n      <FreeTierQuota v-if=\"!isDocked\" />\n      <PartnerNodesRunCaption v-if=\"!isDocked\" />\n    </div>\n\n    <Teleport v-if=\"inlineProgressTarget\" :to=\"inlineProgressTarget\">\n      <QueueInlineProgress\n        :hidden=\"shouldHideInlineProgress\"\n        radius-class=\"rounded-xl\"\n        data-testid=\"queue-inline-progress\"\n      />\n    </Teleport>\n  </div>\n</template>\n\n<script lang=\"ts\" setup>\nimport {\n  useDraggable,\n  useEventListener,\n  useLocalStorage,\n  watchDebounced\n} from '@vueuse/core'\nimport { clamp } from 'es-toolkit/compat'\nimport { storeToRefs } from 'pinia'\nimport { computed, nextTick, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport PartnerNodesRunCaption from '@/components/actionbar/PartnerNodesRunCaption.vue'\nimport StatusBadge from '@/components/common/StatusBadge.vue'\nimport QueueInlineProgress from '@/components/queue/QueueInlineProgress.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport ContextMenu from '@/components/ui/menu/ContextMenu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useQueueFeatureFlags } from '@/composables/queue/useQueueFeatureFlags'\nimport FreeTierQuota from '@/platform/cloud/subscription/components/FreeTierQuota.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { FIRST_RUN_COACH_IDS } from '@/platform/onboarding/onboardingTours'\nimport { vCoachmark } from '@/platform/onboarding/vCoachmark'\nimport { useQueueStore } from '@/stores/queueStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport ComfyRunButton from './ComfyRunButton'\n\nconst { dockedProgressContainer, queueOverlayExpanded = false } = defineProps<{\n  /**\n   * Element the inline run-progress bar is teleported into while the actionbar\n   * is docked. Must be the bordered actionbar card, not the inner button row —\n   * the bar is `absolute inset-0` and sits flush with its container's bottom.\n   */\n  dockedProgressContainer?: HTMLElement | null\n  queueOverlayExpanded?: boolean\n}>()\n\nconst emit = defineEmits<{\n  (event: 'update:progressTarget', target: HTMLElement | null): void\n}>()\n\nconst settingStore = useSettingStore()\nconst commandStore = useCommandStore()\nconst executionStore = useExecutionStore()\nconst queueStore = useQueueStore()\nconst sidebarTabStore = useSidebarTabStore()\nconst { t, n } = useI18n()\nconst { isIdle: isExecutionIdle } = storeToRefs(executionStore)\nconst { activeJobsCount } = storeToRefs(queueStore)\nconst { activeSidebarTabId } = storeToRefs(sidebarTabStore)\n\nconst position = computed(() => settingStore.get('Comfy.UseNewMenu'))\nconst visible = computed(() => position.value !== 'Disabled')\nconst { isQueuePanelV2Enabled, isRunProgressBarEnabled } =\n  useQueueFeatureFlags()\n\nconst panelRef = ref<HTMLElement | null>(null)\nconst dragHandleRef = ref<HTMLElement | null>(null)\nconst isDocked = useLocalStorage('Comfy.MenuPosition.Docked', true)\nconst storedPosition = useLocalStorage('Comfy.MenuPosition.Floating', {\n  x: 0,\n  y: 0\n})\nconst { x, y, style, isDragging } = useDraggable(panelRef, {\n  initialValue: { x: 0, y: 0 },\n  handle: dragHandleRef,\n  containerElement: document.body\n})\n\n// Update storedPosition when x or y changes\nwatchDebounced(\n  [x, y],\n  ([newX, newY]) => {\n    storedPosition.value = { x: newX, y: newY }\n  },\n  { debounce: 300 }\n)\n\n// Set initial position to bottom center\nconst setInitialPosition = () => {\n  const panel = panelRef.value\n  if (panel) {\n    const screenWidth = window.innerWidth\n    const screenHeight = window.innerHeight\n    const menuWidth = panel.offsetWidth\n    const menuHeight = panel.offsetHeight\n\n    if (menuWidth === 0 || menuHeight === 0) {\n      return\n    }\n\n    // Check if stored position exists and is within bounds\n    if (storedPosition.value.x !== 0 || storedPosition.value.y !== 0) {\n      // Ensure stored position is within screen bounds\n      x.value = clamp(storedPosition.value.x, 0, screenWidth - menuWidth)\n      y.value = clamp(storedPosition.value.y, 0, screenHeight - menuHeight)\n      captureLastDragState()\n      return\n    }\n\n    // If no stored position or current position, set to bottom center\n    if (x.value === 0 && y.value === 0) {\n      x.value = clamp((screenWidth - menuWidth) / 2, 0, screenWidth - menuWidth)\n      y.value = clamp(\n        screenHeight - menuHeight - 10,\n        0,\n        screenHeight - menuHeight\n      )\n      captureLastDragState()\n    }\n  }\n}\n\n//The ComfyRunButton is a dynamic import. Which means it will not be loaded onMount in this component.\n//So we must use suspense resolve to ensure that is has loaded and updated the DOM before calling setInitialPosition()\nasync function comfyRunButtonResolved() {\n  await nextTick()\n  setInitialPosition()\n}\n\nwatch(visible, async (newVisible) => {\n  if (newVisible) {\n    await nextTick(setInitialPosition)\n  }\n})\n\n/**\n * Track run button handle drag start using mousedown on the drag handle.\n */\nuseEventListener(dragHandleRef, 'mousedown', () => {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'actionbar_run_handle_drag_start',\n    element_group: 'actionbar'\n  })\n})\n\nconst lastDragState = ref({\n  x: x.value,\n  y: y.value,\n  windowWidth: window.innerWidth,\n  windowHeight: window.innerHeight\n})\nconst captureLastDragState = () => {\n  lastDragState.value = {\n    x: x.value,\n    y: y.value,\n    windowWidth: window.innerWidth,\n    windowHeight: window.innerHeight\n  }\n}\nwatch(\n  isDragging,\n  (newIsDragging) => {\n    if (!newIsDragging) {\n      // Stop dragging\n      captureLastDragState()\n    }\n  },\n  { immediate: true }\n)\n\nconst adjustMenuPosition = () => {\n  const panel = panelRef.value\n  if (panel) {\n    const screenWidth = window.innerWidth\n    const screenHeight = window.innerHeight\n    const menuWidth = panel.offsetWidth\n    const menuHeight = panel.offsetHeight\n\n    // Calculate distances to all edges\n    const distanceLeft = lastDragState.value.x\n    const distanceRight =\n      lastDragState.value.windowWidth - (lastDragState.value.x + menuWidth)\n    const distanceTop = lastDragState.value.y\n    const distanceBottom =\n      lastDragState.value.windowHeight - (lastDragState.value.y + menuHeight)\n\n    // Find the smallest distance to determine which edge to anchor to\n    const distances = [\n      { edge: 'left', distance: distanceLeft },\n      { edge: 'right', distance: distanceRight },\n      { edge: 'top', distance: distanceTop },\n      { edge: 'bottom', distance: distanceBottom }\n    ]\n    const closestEdge = distances.reduce((min, curr) =>\n      curr.distance < min.distance ? curr : min\n    )\n\n    // Calculate vertical position as a percentage of screen height\n    const verticalRatio =\n      lastDragState.value.y / lastDragState.value.windowHeight\n    const horizontalRatio =\n      lastDragState.value.x / lastDragState.value.windowWidth\n\n    // Apply positioning based on closest edge\n    if (closestEdge.edge === 'left') {\n      x.value = closestEdge.distance // Maintain exact distance from left\n      y.value = verticalRatio * screenHeight\n    } else if (closestEdge.edge === 'right') {\n      x.value = screenWidth - menuWidth - closestEdge.distance // Maintain exact distance from right\n      y.value = verticalRatio * screenHeight\n    } else if (closestEdge.edge === 'top') {\n      x.value = horizontalRatio * screenWidth\n      y.value = closestEdge.distance // Maintain exact distance from top\n    } else {\n      // bottom\n      x.value = horizontalRatio * screenWidth\n      y.value = screenHeight - menuHeight - closestEdge.distance // Maintain exact distance from bottom\n    }\n\n    // Ensure the menu stays within the screen bounds\n    x.value = clamp(x.value, 0, screenWidth - menuWidth)\n    y.value = clamp(y.value, 0, screenHeight - menuHeight)\n  }\n}\n\nuseEventListener(window, 'resize', adjustMenuPosition)\n\n// Drop zone state\nconst isMouseOverDropZone = ref(false)\n\n// Mouse event handlers for self-contained drop zone\nconst onMouseEnterDropZone = () => {\n  if (isDragging.value) {\n    isMouseOverDropZone.value = true\n  }\n}\n\nconst onMouseLeaveDropZone = () => {\n  if (isDragging.value) {\n    isMouseOverDropZone.value = false\n  }\n}\n\nconst inlineProgressTarget = computed(() => {\n  if (\n    !visible.value ||\n    !isQueuePanelV2Enabled.value ||\n    !isRunProgressBarEnabled.value\n  ) {\n    return null\n  }\n  if (isDocked.value) return dockedProgressContainer ?? null\n  return panelRef.value\n})\nconst shouldHideInlineProgress = computed(\n  () => !isQueuePanelV2Enabled.value && queueOverlayExpanded\n)\nwatch(\n  panelRef,\n  (target) => {\n    emit('update:progressTarget', target)\n  },\n  { immediate: true }\n)\n\n// Handle drag state changes\nwatch(isDragging, (dragging) => {\n  if (dragging) {\n    // Starting to drag - undock if docked\n    if (isDocked.value) {\n      isDocked.value = false\n    }\n  } else {\n    // Stopped dragging - dock if mouse is over drop zone\n    if (isMouseOverDropZone.value) {\n      isDocked.value = true\n    }\n    // Reset drop zone state\n    isMouseOverDropZone.value = false\n  }\n})\n\nconst queueToggleLabel = computed(() =>\n  t(\n    isQueuePanelV2Enabled.value\n      ? 'sideToolbar.queueProgressOverlay.viewJobHistory'\n      : 'sideToolbar.queueProgressOverlay.expandCollapsedQueue'\n  )\n)\nconst activeJobsLabel = computed(() => {\n  const count = activeJobsCount.value\n  return t(\n    'sideToolbar.queueProgressOverlay.activeJobsShort',\n    { count: n(count) },\n    count\n  )\n})\nconst queueContextMenu = ref<InstanceType<typeof ContextMenu> | null>(null)\nconst queueContextMenuItems = computed<MenuItem[]>(() => [\n  {\n    label: t('sideToolbar.queueProgressOverlay.clearQueueTooltip'),\n    icon: 'icon-[lucide--list-x] text-destructive-background',\n    class: '*:text-destructive-background',\n    disabled: queueStore.pendingTasks.length === 0,\n    command: () => {\n      void handleClearQueue()\n    }\n  }\n])\n\nconst cancelCurrentJob = async () => {\n  if (isExecutionIdle.value) return\n  await commandStore.execute('Comfy.Interrupt')\n}\nconst toggleQueueOverlay = () => {\n  if (isQueuePanelV2Enabled.value) {\n    sidebarTabStore.toggleSidebarTab('job-history')\n    return\n  }\n  commandStore.execute('Comfy.Queue.ToggleOverlay')\n}\nconst showQueueContextMenu = (event: MouseEvent) => {\n  queueContextMenu.value?.show(event)\n}\nconst handleClearQueue = async () => {\n  const pendingJobIds = queueStore.pendingTasks\n    .map((task) => task.jobId)\n    .filter((id): id is string => typeof id === 'string' && id.length > 0)\n\n  await commandStore.execute('Comfy.ClearPendingTasks')\n  executionStore.clearInitializationByJobIds(pendingJobIds)\n}\n\nconst actionbarClass = computed(() =>\n  cn(\n    'w-[200px] border-dashed border-blue-500 opacity-80',\n    'm-1.5 flex items-center justify-center self-stretch',\n    'rounded-md before:-ml-50 before:h-full before:w-50',\n    'pointer-events-auto',\n    isMouseOverDropZone.value &&\n      'scale-105 border-[3px] opacity-100 shadow-[0_0_20px] shadow-blue-500'\n  )\n)\nconst panelClass = computed(() =>\n  cn(\n    'actionbar pointer-events-auto',\n    isDragging.value && 'pointer-events-none select-none',\n    !isDocked.value && 'fixed z-1300 floating-panel'\n  )\n)\n</script>\n","<template>\n  <div :class=\"containerClasses\">\n    <slot></slot>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { fullHeight = true } = defineProps<{\n  fullHeight?: boolean\n}>()\n\nconst containerClasses = computed(() =>\n  cn('w-full flex-1', fullHeight && 'h-full')\n)\n</script>\n","<template>\n  <div :class=\"containerClasses\">\n    <slot name=\"top\"></slot>\n    <slot name=\"bottom\"></slot>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  size = 'regular',\n  variant = 'default',\n  rounded = 'md',\n  customAspectRatio,\n  hasBorder = true,\n  hasBackground = true,\n  hasShadow = true,\n  hasCursor = true,\n  class: customClass = ''\n} = defineProps<{\n  size?: 'mini' | 'compact' | 'regular' | 'portrait' | 'tall' | 'auto'\n  variant?: 'default' | 'ghost' | 'outline'\n  rounded?: 'none' | 'md' | 'lg' | 'xl'\n  customAspectRatio?: string\n  hasBorder?: boolean\n  hasBackground?: boolean\n  hasShadow?: boolean\n  hasCursor?: boolean\n  class?: string\n}>()\n\n// Base structure classes\nconst structureClasses = 'flex flex-col overflow-hidden'\n\n// Rounded corners\nconst roundedClasses = {\n  none: 'rounded-none',\n  md: 'rounded',\n  lg: 'rounded-lg',\n  xl: 'rounded-xl'\n} as const\n\nconst containerClasses = computed(() => {\n  // Variant styles\n  const variantClasses = {\n    default: cn(\n      hasBackground && 'bg-modal-card-background',\n      hasBorder && 'border border-border-default',\n      hasShadow && 'shadow-sm',\n      hasCursor && 'cursor-pointer'\n    ),\n    ghost: cn(\n      hasCursor && 'cursor-pointer',\n      'p-2 transition-colors duration-200'\n    ),\n    outline: cn(\n      hasBorder && 'border-2 border-border-subtle',\n      hasCursor && 'cursor-pointer',\n      'transition-colors hover:border-border-subtle/50'\n    )\n  }\n\n  // Size/aspect ratio\n  const aspectRatio = customAspectRatio\n    ? `aspect-[${customAspectRatio}]`\n    : {\n        mini: 'aspect-100/120',\n        compact: 'aspect-240/311',\n        regular: 'aspect-256/308',\n        portrait: 'aspect-256/325',\n        tall: 'aspect-256/353',\n        auto: ''\n      }[size]\n\n  return cn(\n    structureClasses,\n    roundedClasses[rounded],\n    variantClasses[variant],\n    aspectRatio,\n    customClass\n  )\n})\n</script>\n","<template>\n  <div :class=\"topStyle\">\n    <slot class=\"absolute top-0 left-0 size-full\"></slot>\n\n    <div v-if=\"slots['top-left']\" :class=\"slotClasses['top-left']\">\n      <slot name=\"top-left\"></slot>\n    </div>\n\n    <div v-if=\"slots['top-right']\" :class=\"slotClasses['top-right']\">\n      <slot name=\"top-right\"></slot>\n    </div>\n\n    <div v-if=\"slots['center-left']\" :class=\"slotClasses['center-left']\">\n      <slot name=\"center-left\"></slot>\n    </div>\n\n    <div v-if=\"slots['center-right']\" :class=\"slotClasses['center-right']\">\n      <slot name=\"center-right\"></slot>\n    </div>\n\n    <div v-if=\"slots['bottom-left']\" :class=\"slotClasses['bottom-left']\">\n      <slot name=\"bottom-left\"></slot>\n    </div>\n\n    <div v-if=\"slots['bottom-right']\" :class=\"slotClasses['bottom-right']\">\n      <slot name=\"bottom-right\"></slot>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, useSlots } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst slots = useSlots()\n\nconst {\n  ratio = 'square',\n  topLeftClass,\n  topRightClass,\n  centerLeftClass,\n  centerRightClass,\n  bottomLeftClass,\n  bottomRightClass\n} = defineProps<{\n  ratio?: 'square' | 'landscape'\n  topLeftClass?: string\n  topRightClass?: string\n  centerLeftClass?: string\n  centerRightClass?: string\n  bottomLeftClass?: string\n  bottomRightClass?: string\n}>()\n\nconst topStyle = computed(() => {\n  const baseClasses = 'relative p-0 overflow-hidden'\n\n  const ratioClasses = {\n    square: 'aspect-square',\n    landscape: 'aspect-48/27'\n  }\n\n  return `${baseClasses} ${ratioClasses[ratio]}`\n})\n\n// Get default classes for each slot position\nconst defaultSlotClasses = {\n  'top-left': 'absolute top-2 left-2 flex flex-wrap justify-start gap-2',\n  'top-right': 'absolute top-2 right-2 flex flex-wrap justify-end gap-2',\n  'center-left':\n    'absolute top-1/2 left-2 flex -translate-y-1/2 flex-wrap justify-start gap-2',\n  'center-right':\n    'absolute top-1/2 right-2 flex -translate-y-1/2 flex-wrap justify-end gap-2',\n  'bottom-left': 'absolute bottom-2 left-2 flex flex-wrap justify-start gap-2',\n  'bottom-right': 'absolute right-2 bottom-2 flex flex-wrap justify-end gap-2'\n}\n\n// Compute all slot classes once and cache them\nconst slotClasses = computed(() => ({\n  'top-left': cn(defaultSlotClasses['top-left'], topLeftClass),\n  'top-right': cn(defaultSlotClasses['top-right'], topRightClass),\n  'center-left': cn(defaultSlotClasses['center-left'], centerLeftClass),\n  'center-right': cn(defaultSlotClasses['center-right'], centerRightClass),\n  'bottom-left': cn(defaultSlotClasses['bottom-left'], bottomLeftClass),\n  'bottom-right': cn(defaultSlotClasses['bottom-right'], bottomRightClass)\n}))\n</script>\n","<script setup lang=\"ts\">\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport TagRemoveButton from './TagRemoveButton.vue'\nimport { tagVariants } from '@comfyorg/design-system/tag.variants'\nimport type { TagVariants } from '@comfyorg/design-system/tag.variants'\n\nconst {\n  label,\n  shape = 'square',\n  state = 'default',\n  removable = false,\n  removeLabel,\n  removeTooltip,\n  interactive = false,\n  class: className\n} = defineProps<{\n  label: string\n  shape?: TagVariants['shape']\n  state?: TagVariants['state']\n  removable?: boolean\n  removeLabel?: string\n  removeTooltip?: string\n  interactive?: boolean\n  class?: HTMLAttributes['class']\n}>()\n\nconst emit = defineEmits<{\n  remove: [event: Event]\n}>()\n\nfunction handleKeydown(event: KeyboardEvent): void {\n  if (event.target !== event.currentTarget) return\n  if (!interactive) return\n  if (event.key === 'Enter' || event.key === ' ') event.preventDefault()\n  if (event.key === 'Enter' && event.currentTarget instanceof HTMLElement)\n    event.currentTarget.click()\n}\n\nfunction handleKeyup(event: KeyboardEvent): void {\n  if (event.target !== event.currentTarget) return\n  if (!interactive || event.key !== ' ') return\n  event.preventDefault()\n  if (event.currentTarget instanceof HTMLElement) event.currentTarget.click()\n}\n</script>\n\n<template>\n  <span\n    :role=\"interactive ? 'button' : undefined\"\n    :tabindex=\"interactive ? 0 : undefined\"\n    :class=\"\n      cn(tagVariants({ shape, state, removable, interactive }), className)\n    \"\n    @keydown=\"handleKeydown\"\n    @keyup=\"handleKeyup\"\n  >\n    <slot name=\"icon\" />\n    <span class=\"min-w-0 truncate\">{{ label }}</span>\n    <slot />\n    <TagRemoveButton\n      v-if=\"removable\"\n      :label=\"removeLabel ?? $t('g.remove')\"\n      :tooltip=\"removeTooltip\"\n      @click.stop=\"emit('remove', $event)\"\n    />\n  </span>\n</template>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Tag from '@/components/chip/Tag.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\n\nconst { t } = useI18n()\n\nconst tooltipCopy = computed(() => {\n  const title = t('templateWorkflows.paidTemplate.title')\n  const credits = t('templateWorkflows.paidTemplate.credits')\n\n  return {\n    title,\n    credits,\n    label: [title, credits].join(' ')\n  }\n})\n</script>\n\n<template>\n  <Tooltip open-on-click>\n    <TooltipTrigger as-child>\n      <button\n        type=\"button\"\n        :aria-label=\"tooltipCopy.label\"\n        data-testid=\"paid-template-badge\"\n        class=\"cursor-pointer rounded-lg border-none bg-transparent p-0 focus-visible:ring-1 focus-visible:ring-base-foreground focus-visible:outline-none\"\n        @click.stop\n      >\n        <Tag\n          :label=\"$t('templateWorkflows.paidTemplate.badgeLabel')\"\n          shape=\"overlay\"\n          class=\"h-7 rounded-lg bg-black/30 px-2 backdrop-blur-[20px] [&>span]:sr-only\"\n        >\n          <template #icon>\n            <i\n              class=\"icon-[tabler--crown-filled] size-4 text-brand-yellow\"\n              aria-hidden=\"true\"\n            />\n          </template>\n        </Tag>\n      </button>\n    </TooltipTrigger>\n    <TooltipContent side=\"bottom\" class=\"text-left leading-normal\">\n      <p class=\"m-0 font-semibold\">{{ tooltipCopy.title }}</p>\n      <p class=\"m-0\">{{ tooltipCopy.credits }}</p>\n    </TooltipContent>\n  </Tooltip>\n</template>\n","<template>\n  <MultiSelect\n    v-model=\"selectedModels\"\n    v-model:search-query=\"modelSearchText\"\n    size=\"md\"\n    :class=\"triggerClass\"\n    :label=\"modelFilterLabel\"\n    :options=\"modelOptions\"\n    :show-search-box=\"true\"\n    :show-selected-count=\"true\"\n    :show-clear-button=\"true\"\n    actions-placement=\"footer\"\n  />\n\n  <MultiSelect\n    v-model=\"selectedUseCases\"\n    size=\"md\"\n    :class=\"triggerClass\"\n    :label=\"useCaseFilterLabel\"\n    :options=\"useCaseOptions\"\n    :show-search-box=\"true\"\n    :show-selected-count=\"true\"\n    :show-clear-button=\"true\"\n    actions-placement=\"footer\"\n  />\n\n  <MultiSelect\n    v-model=\"selectedRunsOn\"\n    size=\"md\"\n    :class=\"triggerClass\"\n    :label=\"runsOnFilterLabel\"\n    :options=\"runsOnOptions\"\n    :show-search-box=\"true\"\n    :show-selected-count=\"true\"\n    :show-clear-button=\"true\"\n    actions-placement=\"footer\"\n  />\n\n  <SingleSelect\n    v-model=\"sortSelection\"\n    size=\"md\"\n    :class=\"triggerClass\"\n    :label=\"$t('templateWorkflows.sorting')\"\n    :options=\"sortOptions\"\n  >\n    <template #icon>\n      <i class=\"icon-[lucide--arrow-up-down] text-muted-foreground\" />\n    </template>\n  </SingleSelect>\n</template>\n\n<script setup lang=\"ts\">\nimport MultiSelect from '@/components/ui/multi-select/MultiSelect.vue'\nimport type { SelectOption } from '@/components/ui/select/types'\nimport SingleSelect from '@/components/ui/single-select/SingleSelect.vue'\nimport type { TemplateSortMode } from '@/composables/useTemplateFiltering'\n\nconst {\n  modelOptions,\n  useCaseOptions,\n  runsOnOptions,\n  sortOptions,\n  modelFilterLabel,\n  useCaseFilterLabel,\n  runsOnFilterLabel,\n  triggerClass = ''\n} = defineProps<{\n  modelOptions: SelectOption[]\n  useCaseOptions: SelectOption[]\n  runsOnOptions: SelectOption[]\n  sortOptions: SelectOption[]\n  modelFilterLabel: string\n  useCaseFilterLabel: string\n  runsOnFilterLabel: string\n  triggerClass?: string\n}>()\n\nconst selectedModels = defineModel<SelectOption[]>('selectedModels', {\n  required: true\n})\nconst selectedUseCases = defineModel<SelectOption[]>('selectedUseCases', {\n  required: true\n})\nconst selectedRunsOn = defineModel<SelectOption[]>('selectedRunsOn', {\n  required: true\n})\nconst sortSelection = defineModel<TemplateSortMode>('sortSelection', {\n  required: true\n})\nconst modelSearchText = defineModel<string>('modelSearchText', {\n  required: true\n})\n</script>\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useResizeObserver } from '@vueuse/core'\nimport { nextTick, onMounted, ref, useTemplateRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nconst { description } = defineProps<{ description: string }>()\nconst { t } = useI18n()\n\n/** Clipping depends on rendered width, so it is measured rather than counted. */\nconst showFullDescription = ref(false)\nconst descriptionElement =\n  useTemplateRef<HTMLParagraphElement>('descriptionElement')\nconst descriptionOverflows = ref(false)\n\nfunction measureDescriptionOverflow() {\n  const element = descriptionElement.value\n  descriptionOverflows.value =\n    !!element && element.scrollHeight > element.clientHeight + 1\n}\n\nonMounted(measureDescriptionOverflow)\nuseResizeObserver(descriptionElement, measureDescriptionOverflow)\n\n/** A clamped paragraph keeps its height, so the resize observer never fires here. */\nwatch(\n  () => description,\n  () => {\n    showFullDescription.value = false\n    void nextTick(measureDescriptionOverflow)\n  }\n)\n</script>\n\n<template>\n  <p\n    ref=\"descriptionElement\"\n    :class=\"\n      cn(\n        'm-0 max-w-2xl overflow-hidden text-sm/relaxed wrap-break-word text-muted-foreground transition-[max-height] duration-200 ease-out [interpolate-size:allow-keywords] motion-reduce:transition-none',\n        showFullDescription ? 'max-h-max' : 'line-clamp-3 max-h-[3lh]'\n      )\n    \"\n  >\n    {{ description }}\n  </p>\n  <!--\n    Expanding removes the overflow that revealed this control, so the expanded\n    state has to keep it rendered or there is no way back to three lines.\n  -->\n  <button\n    v-if=\"descriptionOverflows || showFullDescription\"\n    type=\"button\"\n    class=\"m-0 flex w-fit cursor-pointer items-center gap-1 border-0 bg-transparent p-0 text-sm text-base-foreground hover:underline\"\n    :aria-expanded=\"showFullDescription\"\n    @click=\"showFullDescription = !showFullDescription\"\n  >\n    {{\n      t(\n        showFullDescription\n          ? 'templateWorkflows.detail.descriptionLess'\n          : 'templateWorkflows.detail.descriptionMore'\n      )\n    }}\n    <i\n      aria-hidden=\"true\"\n      :class=\"\n        cn(\n          'icon-[lucide--chevron-down] size-3.5 transition-transform duration-200 motion-reduce:transition-none',\n          showFullDescription && 'rotate-180'\n        )\n      \"\n    />\n  </button>\n</template>\n","<script setup lang=\"ts\">\nimport { useId } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport type { TemplateModelDownloadState } from '@/platform/workflow/templates/utils/templateModelDownloadState'\n\nconst { state, rowName } = defineProps<{\n  state: Extract<TemplateModelDownloadState, { status: 'failed' }>\n  rowName: string\n}>()\nconst emit = defineEmits<{ retry: [] }>()\nconst { t } = useI18n()\nconst hintId = useId()\n\nfunction failureLabel(): string {\n  return t(\n    state.reason === 'cancelled'\n      ? 'templateWorkflows.detail.downloadCancelled'\n      : 'templateWorkflows.detail.downloadFailed'\n  )\n}\n</script>\n\n<template>\n  <span class=\"col-start-3 row-start-1 flex shrink-0 items-center gap-2\">\n    <Tooltip :disabled=\"state.reason !== 'error'\">\n      <TooltipTrigger as-child>\n        <Badge\n          role=\"status\"\n          :aria-label=\"failureLabel()\"\n          severity=\"danger\"\n          variant=\"compact\"\n        >\n          {{ failureLabel() }}\n        </Badge>\n      </TooltipTrigger>\n      <TooltipContent>\n        {{ t('templateWorkflows.detail.downloadFailedHint') }}\n      </TooltipContent>\n    </Tooltip>\n    <span v-if=\"state.reason === 'error'\" :id=\"hintId\" class=\"sr-only\">\n      {{ t('templateWorkflows.detail.downloadFailedHint') }}\n    </span>\n    <Button\n      :aria-label=\"\n        t(\n          'templateWorkflows.detail.retryDownloadNamed',\n          { model: rowName },\n          { escapeParameter: false }\n        )\n      \"\n      :aria-describedby=\"state.reason === 'error' ? hintId : undefined\"\n      variant=\"outline\"\n      size=\"unset\"\n      class=\"h-6 rounded-md bg-secondary-background px-2 text-xs\"\n      @click=\"emit('retry')\"\n    >\n      {{ t('templateWorkflows.detail.retryDownload') }}\n    </Button>\n  </span>\n</template>\n","<script setup lang=\"ts\">\nimport { nextTick, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport WorkflowTemplateDownloadFailure from '@/components/custom/widget/WorkflowTemplateDownloadFailure.vue'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { TemplateDetailRow } from '@/platform/workflow/templates/types/templateDetail'\nimport type { TemplateModelDownloadState } from '@/platform/workflow/templates/utils/templateModelDownloadState'\nimport { formatSize } from '@/utils/formatUtil'\n\ntype DownloadableStatus = Extract<\n  TemplateDetailRow['status'],\n  { kind: 'downloadable' }\n>\n\nconst { status, rowName } = defineProps<{\n  status: DownloadableStatus\n  rowName: string\n}>()\nconst emit = defineEmits<{ download: [] }>()\nconst { t } = useI18n()\n\n/**\n * The control unmounts on request, dropping focus to the body. Hand it to what\n * replaces it, but only when the user acted here.\n */\nconst statusRegion = ref<HTMLElement | null>(null)\nconst restoreFocus = ref(false)\n\nfunction requestDownload() {\n  restoreFocus.value = true\n  emit('download')\n}\n\nwatch(\n  () => status.downloadState?.status,\n  async () => {\n    if (!restoreFocus.value) return\n    restoreFocus.value = false\n    await nextTick()\n    statusRegion.value?.focus()\n  }\n)\n\ntype DownloadingState = Extract<\n  TemplateModelDownloadState,\n  { status: 'downloading' }\n>\n\nfunction getPassiveDownloadLabel(\n  state: TemplateModelDownloadState | undefined\n): string | undefined {\n  if (state?.status === 'queued') {\n    return t('templateWorkflows.detail.downloadQueued')\n  }\n  if (state?.status === 'starting') {\n    return t('templateWorkflows.detail.downloadStarting')\n  }\n}\n\nfunction getProgressPercent(state: DownloadingState): number | undefined {\n  if (state.fraction === null) return undefined\n  return Math.round(Math.min(1, Math.max(0, state.fraction)) * 100)\n}\n\nfunction getKnownProgressText(state: DownloadingState): string | undefined {\n  if (state.receivedBytes !== null && state.totalBytes !== null) {\n    return `${formatSize(state.receivedBytes)} / ${formatSize(state.totalBytes)}`\n  }\n  if (state.receivedBytes !== null) return formatSize(state.receivedBytes)\n  if (state.totalBytes !== null) return formatSize(state.totalBytes)\n}\n\nfunction getProgressText(state: DownloadingState): string {\n  const knownProgress = getKnownProgressText(state)\n  if (state.activity !== 'paused') {\n    return knownProgress ?? t('templateWorkflows.detail.downloading')\n  }\n  return knownProgress\n    ? t(\n        'templateWorkflows.detail.downloadPausedProgress',\n        { progress: knownProgress },\n        // Byte counts composed with a separator; escaping turns the slash\n        // into an entity in both the label and aria-valuetext.\n        { escapeParameter: false }\n      )\n    : t('templateWorkflows.detail.downloadPaused')\n}\n\nfunction namedLabel(key: string): string {\n  return t(key, { model: rowName }, { escapeParameter: false })\n}\n</script>\n\n<template>\n  <Button\n    v-if=\"!status.downloadState || status.downloadState.status === 'idle'\"\n    :aria-label=\"namedLabel('templateWorkflows.detail.downloadModelNamed')\"\n    :title=\"status.label\"\n    variant=\"textonly\"\n    size=\"unset\"\n    class=\"col-start-3 row-start-1 size-8 shrink-0 rounded-md p-1.5\"\n    @click=\"requestDownload()\"\n  >\n    <i aria-hidden=\"true\" class=\"icon-[tabler--download] size-4\" />\n  </Button>\n  <span\n    v-else-if=\"\n      status.downloadState.status === 'queued' ||\n      status.downloadState.status === 'starting'\n    \"\n    ref=\"statusRegion\"\n    role=\"status\"\n    tabindex=\"-1\"\n    class=\"col-[2/-1] row-start-2 flex min-w-0 items-center gap-3 text-xs text-muted-foreground focus-visible:outline-none\"\n  >\n    <span\n      aria-hidden=\"true\"\n      class=\"h-1 min-w-0 flex-1 overflow-hidden rounded-full bg-secondary-background\"\n    >\n      <span\n        class=\"indeterminate-stripe indeterminate-stripe--drifting block h-full w-full rounded-full text-primary-background\"\n      />\n    </span>\n    <span class=\"shrink-0\">\n      {{ getPassiveDownloadLabel(status.downloadState) }}\n    </span>\n  </span>\n  <span\n    v-else-if=\"status.downloadState.status === 'downloading'\"\n    ref=\"statusRegion\"\n    tabindex=\"-1\"\n    class=\"col-[2/-1] row-start-2 flex min-w-0 items-center gap-3 focus-visible:outline-none\"\n  >\n    <span\n      role=\"progressbar\"\n      :aria-label=\"\n        namedLabel(\n          status.downloadState.activity === 'paused'\n            ? 'templateWorkflows.detail.downloadPausedModel'\n            : 'templateWorkflows.detail.downloadingModel'\n        )\n      \"\n      aria-valuemin=\"0\"\n      aria-valuemax=\"100\"\n      :aria-valuenow=\"getProgressPercent(status.downloadState)\"\n      :aria-valuetext=\"getProgressText(status.downloadState)\"\n      class=\"block h-1 min-w-0 flex-1 overflow-hidden rounded-full bg-secondary-background\"\n    >\n      <span\n        :class=\"\n          cn(\n            'block h-full rounded-full',\n            status.downloadState.fraction === null\n              ? 'indeterminate-stripe w-full text-primary-background'\n              : 'bg-primary-background',\n            status.downloadState.fraction === null &&\n              status.downloadState.activity === 'active' &&\n              'indeterminate-stripe--drifting'\n          )\n        \"\n        :style=\"\n          getProgressPercent(status.downloadState) === undefined\n            ? undefined\n            : {\n                width: `${getProgressPercent(status.downloadState)}%`\n              }\n        \"\n      />\n    </span>\n    <span class=\"shrink-0 text-xs text-muted-foreground\">\n      {{ getProgressText(status.downloadState) }}\n    </span>\n  </span>\n  <Badge\n    v-else-if=\"status.downloadState.status === 'done'\"\n    role=\"status\"\n    :aria-label=\"t('templateWorkflows.detail.downloaded')\"\n    variant=\"compact\"\n    severity=\"success\"\n    class=\"col-start-3 row-start-1\"\n  >\n    {{ t('templateWorkflows.detail.downloaded') }}\n  </Badge>\n  <WorkflowTemplateDownloadFailure\n    v-else\n    :state=\"status.downloadState\"\n    :row-name=\"rowName\"\n    @retry=\"requestDownload()\"\n  />\n</template>\n\n<style scoped>\n/* Tiled, so one tile of travel loops seamlessly. */\n@keyframes template-download-stripe-drift {\n  to {\n    background-position: 0.75rem 0;\n  }\n}\n\n.indeterminate-stripe {\n  background-image: repeating-linear-gradient(\n    135deg,\n    currentColor 0 25%,\n    transparent 25% 50%\n  );\n  background-size: 0.75rem 0.75rem;\n}\n\n.indeterminate-stripe--drifting {\n  animation: template-download-stripe-drift 0.7s linear infinite;\n}\n\n/*\n * Switched off by hand, as `agent-shimmer-outline` does: the global rule only\n * collapses duration, which accelerates an infinite animation rather than\n * stopping it. The stripe still reads as indeterminate while held still.\n */\n.disable-animations .indeterminate-stripe--drifting {\n  animation: none;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .indeterminate-stripe--drifting {\n    animation: none;\n  }\n}\n</style>\n","<script setup lang=\"ts\">\nimport WorkflowTemplateDownloadStatus from '@/components/custom/widget/WorkflowTemplateDownloadStatus.vue'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport type { TemplateDetailRow } from '@/platform/workflow/templates/types/templateDetail'\n\nconst { row } = defineProps<{ row: TemplateDetailRow }>()\nconst emit = defineEmits<{ download: [] }>()\n</script>\n\n<template>\n  <a\n    v-if=\"row.status?.kind === 'manual'\"\n    :href=\"row.status.href\"\n    target=\"_blank\"\n    rel=\"noopener noreferrer\"\n    class=\"col-start-3 row-start-1 shrink-0 text-xs text-base-foreground no-underline hover:underline focus-visible:rounded-sm focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none\"\n  >\n    {{ row.status.label }}\n    <span aria-hidden=\"true\">↗</span>\n  </a>\n  <WorkflowTemplateDownloadStatus\n    v-else-if=\"row.status?.kind === 'downloadable'\"\n    :status=\"row.status\"\n    :row-name=\"row.name\"\n    @download=\"emit('download')\"\n  />\n  <span\n    v-else-if=\"row.status?.kind === 'installed'\"\n    role=\"img\"\n    :aria-label=\"row.status.label\"\n    :title=\"row.status.label\"\n    class=\"col-start-3 row-start-1 flex size-8 shrink-0 items-center justify-center\"\n  >\n    <i\n      aria-hidden=\"true\"\n      class=\"icon-[lucide--circle-check] size-4 text-success-background\"\n    />\n  </span>\n  <span\n    v-else-if=\"row.status\"\n    class=\"col-start-3 row-start-1 flex shrink-0 items-center gap-2\"\n  >\n    <Badge severity=\"secondary\" variant=\"compact\" class=\"text-muted-foreground\">\n      {{ row.status.label }}\n    </Badge>\n  </span>\n</template>\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport WorkflowTemplateModelStatus from '@/components/custom/widget/WorkflowTemplateModelStatus.vue'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport type { TemplateDetailGroup } from '@/platform/workflow/templates/types/templateDetail'\n\nconst { group, titleId } = defineProps<{\n  group: TemplateDetailGroup\n  titleId: string\n}>()\nconst emit = defineEmits<{ 'download-model': [rowId: string] }>()\n</script>\n\n<template>\n  <section\n    :aria-labelledby=\"titleId\"\n    class=\"border-t border-border-subtle/60 pb-2 first:border-t-0\"\n  >\n    <div class=\"flex h-10 items-center gap-2 px-2\">\n      <h3 :id=\"titleId\" class=\"m-0 text-sm font-medium\">{{ group.label }}</h3>\n      <Badge severity=\"secondary\" variant=\"badge\">\n        {{ group.rows.length }}\n      </Badge>\n      <span v-if=\"group.total\" class=\"ml-auto text-sm text-muted-foreground\">\n        {{ group.total }}\n      </span>\n    </div>\n    <ul role=\"list\" class=\"m-0 list-none p-0\">\n      <li\n        v-for=\"row in group.rows\"\n        :key=\"row.id\"\n        :class=\"\n          cn(\n            'grid min-h-14 grid-cols-[2.5rem_minmax(0,1fr)_auto] items-center gap-x-3 gap-y-2 rounded-md p-2',\n            row.status?.kind === 'installed' && 'opacity-60'\n          )\n        \"\n      >\n        <span\n          class=\"col-start-1 row-start-1 flex size-10 shrink-0 items-center justify-center overflow-hidden rounded-md bg-secondary-background text-muted-foreground\"\n        >\n          <img\n            v-if=\"row.kind === 'input' && row.preview?.mediaType === 'image'\"\n            :src=\"row.preview.src\"\n            alt=\"\"\n            loading=\"lazy\"\n            class=\"size-full object-cover\"\n          />\n          <video\n            v-else-if=\"\n              row.kind === 'input' && row.preview?.mediaType === 'video'\n            \"\n            :src=\"row.preview.src\"\n            aria-hidden=\"true\"\n            muted\n            playsinline\n            preload=\"metadata\"\n            class=\"size-full object-cover\"\n          />\n          <i\n            v-else\n            aria-hidden=\"true\"\n            :class=\"\n              row.kind === 'input'\n                ? 'icon-[lucide--file-input] size-4'\n                : 'icon-[comfy--ai-model] size-4'\n            \"\n          />\n        </span>\n        <span class=\"col-start-2 row-start-1 flex min-w-0 flex-col gap-0.5\">\n          <span class=\"truncate text-sm\" :title=\"row.name\">{{ row.name }}</span>\n          <span\n            class=\"truncate text-xs text-muted-foreground\"\n            :title=\"row.description\"\n          >\n            {{ row.description }}\n          </span>\n        </span>\n        <WorkflowTemplateModelStatus\n          :row\n          @download=\"emit('download-model', row.id)\"\n        />\n      </li>\n    </ul>\n  </section>\n</template>\n","<script setup lang=\"ts\">\nimport { computed, ref, useId } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport WorkflowTemplateDescription from '@/components/custom/widget/WorkflowTemplateDescription.vue'\nimport WorkflowTemplateDetailGroup from '@/components/custom/widget/WorkflowTemplateDetailGroup.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type {\n  TemplateDetailGroup,\n  TemplateModelSetup\n} from '@/platform/workflow/templates/types/templateDetail'\n\nconst {\n  title,\n  description,\n  groups,\n  cloudUrl,\n  isPartnerNode = false,\n  openPending = false,\n  modelSetup\n} = defineProps<{\n  title: string\n  description: string\n  groups: readonly TemplateDetailGroup[]\n  cloudUrl?: string\n  isPartnerNode?: boolean\n  openPending?: boolean\n  modelSetup?: TemplateModelSetup\n}>()\n\nconst emit = defineEmits<{\n  'open-template': []\n  'download-models-and-open': []\n  'download-model': [rowId: string]\n}>()\n\nconst { t } = useI18n()\nconst detailRoot = ref<HTMLElement | null>(null)\nconst detailId = useId()\nconst cloudTitleId = `${detailId}-cloud-title`\nconst groupTitleId = (groupId: string) => `${detailId}-group-${groupId}`\nconst offerDownloadAndOpen = computed(() => modelSetup !== undefined)\nconst downloadModelsAndOpenLabel = computed(() => {\n  const size =\n    modelSetup?.state === 'startable' ? modelSetup.remainingSize : undefined\n  return size\n    ? t('templateWorkflows.detail.downloadModelsAndOpenWithSize', { size })\n    : t('templateWorkflows.detail.downloadModelsAndOpen')\n})\n\ndefineExpose({\n  focus: () => detailRoot.value?.focus()\n})\n</script>\n\n<template>\n  <article\n    ref=\"detailRoot\"\n    data-testid=\"template-workflow-detail\"\n    :aria-label=\"title\"\n    tabindex=\"-1\"\n    class=\"@container/template-detail flex size-full min-h-0 flex-1 flex-col overflow-hidden bg-base-background text-base-foreground\"\n  >\n    <div\n      class=\"grid min-h-0 flex-1 grid-cols-1 overflow-hidden border-t border-border-subtle @[48rem]/template-detail:grid-cols-[minmax(20rem,5fr)_minmax(0,6fr)] @[48rem]/template-detail:grid-rows-[auto_minmax(0,1fr)]\"\n    >\n      <aside\n        class=\"flex min-h-0 shrink-0 flex-col gap-6 overflow-y-auto border-b border-border-subtle p-6 @[48rem]/template-detail:row-span-2 @[48rem]/template-detail:gap-8 @[48rem]/template-detail:border-r @[48rem]/template-detail:border-b-0 @[48rem]/template-detail:p-8\"\n      >\n        <div class=\"w-full shrink-0 overflow-hidden rounded-lg\">\n          <slot name=\"preview\" />\n        </div>\n\n        <section\n          v-if=\"cloudUrl\"\n          :aria-labelledby=\"cloudTitleId\"\n          class=\"flex shrink-0 flex-col gap-4 rounded-lg bg-secondary-background/50 p-4\"\n        >\n          <div class=\"flex min-w-0 flex-col gap-2\">\n            <h3 :id=\"cloudTitleId\" class=\"m-0 text-sm font-medium\">\n              {{\n                t(\n                  isPartnerNode\n                    ? 'templateWorkflows.detail.partnerNodeTitle'\n                    : 'templateWorkflows.detail.cloudUpsellTitle'\n                )\n              }}\n            </h3>\n            <p class=\"m-0 text-xs/4 font-normal text-muted-foreground\">\n              {{\n                t(\n                  isPartnerNode\n                    ? 'templateWorkflows.detail.partnerNodeDescription'\n                    : 'templateWorkflows.detail.cloudUpsellDescription'\n                )\n              }}\n            </p>\n          </div>\n          <Button\n            as=\"a\"\n            :href=\"cloudUrl\"\n            target=\"_blank\"\n            rel=\"noopener noreferrer\"\n            variant=\"secondary\"\n            size=\"md\"\n            class=\"w-full text-base-foreground no-underline\"\n          >\n            {{ t('templateWorkflows.detail.openInCloud') }}\n          </Button>\n        </section>\n      </aside>\n\n      <div\n        class=\"flex shrink-0 flex-col gap-2 p-6 @[48rem]/template-detail:p-8\"\n      >\n        <h2 class=\"m-0 text-base font-semibold wrap-break-word\">\n          {{ title }}\n        </h2>\n        <WorkflowTemplateDescription :description />\n      </div>\n\n      <div\n        v-if=\"groups.length > 0\"\n        role=\"region\"\n        :aria-label=\"t('templateWorkflows.detail.requirements')\"\n        tabindex=\"0\"\n        class=\"min-h-0 overflow-y-auto border-t border-border-subtle px-4 py-2 @[48rem]/template-detail:px-6\"\n      >\n        <WorkflowTemplateDetailGroup\n          v-for=\"group in groups\"\n          :key=\"group.id\"\n          :group\n          :title-id=\"groupTitleId(group.id)\"\n          @download-model=\"emit('download-model', $event)\"\n        />\n      </div>\n    </div>\n\n    <footer\n      class=\"flex min-h-15 shrink-0 flex-wrap items-center justify-end gap-3 border-t border-border-subtle px-6 py-4\"\n    >\n      <div class=\"ml-auto flex flex-wrap items-center justify-end gap-3\">\n        <Button\n          v-if=\"offerDownloadAndOpen\"\n          variant=\"outline\"\n          size=\"lg\"\n          :aria-disabled=\"openPending\"\n          @click=\"emit('open-template')\"\n        >\n          {{ t('templateWorkflows.detail.openNow') }}\n        </Button>\n        <Button\n          variant=\"inverted\"\n          size=\"lg\"\n          :loading=\"openPending\"\n          :disabled=\"modelSetup?.state === 'resolving'\"\n          @click=\"\n            offerDownloadAndOpen\n              ? emit('download-models-and-open')\n              : emit('open-template')\n          \"\n        >\n          {{\n            offerDownloadAndOpen\n              ? downloadModelsAndOpenLabel\n              : t('templateWorkflows.detail.openNow')\n          }}\n        </Button>\n      </div>\n    </footer>\n  </article>\n</template>\n","export default \"__VITE_PUBLIC_ASSET__c8cdd13f__\"","<template>\n  <div\n    class=\"relative aspect-square w-full overflow-hidden rounded-t-lg select-none\"\n  >\n    <div\n      v-if=\"!error\"\n      ref=\"contentRef\"\n      data-testid=\"thumbnail-content\"\n      class=\"size-full transform-gpu transition-transform duration-1000 ease-out\"\n      :style=\"\n        isHovered ? { transform: `scale(${1 + hoverZoom / 100})` } : undefined\n      \"\n    >\n      <slot />\n    </div>\n    <div v-else class=\"flex size-full items-center justify-center\">\n      <img\n        src=\"/assets/images/default-template.png\"\n        draggable=\"false\"\n        class=\"size-full transform-gpu object-cover transition-transform duration-300 ease-out\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useEventListener } from '@vueuse/core'\nimport { onMounted, ref } from 'vue'\n\nconst error = ref(false)\nconst contentRef = ref<HTMLElement | null>(null)\n\nconst { hoverZoom = 4 } = defineProps<{\n  hoverZoom?: number\n  isHovered?: boolean\n}>()\n\nonMounted(() => {\n  const images = Array.from(contentRef.value?.getElementsByTagName('img') ?? [])\n  images.forEach((img) => {\n    useEventListener(img, 'error', () => {\n      error.value = true\n    })\n  })\n})\n</script>\n<style scoped>\nimg {\n  transition: transform 1s cubic-bezier(0.2, 0, 0.4, 1);\n}\n</style>\n","<template>\n  <BaseThumbnail>\n    <div\n      class=\"flex size-full items-center justify-center p-4\"\n      :style=\"{\n        backgroundImage: 'url(/assets/images/default-template.png)',\n        backgroundRepeat: 'round'\n      }\"\n    >\n      <audio\n        controls\n        class=\"relative w-full\"\n        :src=\"src\"\n        data-testid=\"audio-player\"\n        @click.stop\n      />\n    </div>\n  </BaseThumbnail>\n</template>\n\n<script setup lang=\"ts\">\nimport BaseThumbnail from '@/components/templates/thumbnails/BaseThumbnail.vue'\n\ndefineProps<{\n  src: string\n}>()\n</script>\n","import { onBeforeUnmount, ref, watch } from 'vue'\nimport type { Ref } from 'vue'\n\ninterface UseIntersectionObserverOptions extends IntersectionObserverInit {\n  immediate?: boolean\n}\n\nexport function useIntersectionObserver(\n  target: Ref<Element | null>,\n  callback: IntersectionObserverCallback,\n  options: UseIntersectionObserverOptions = {}\n) {\n  const { immediate = true, ...observerOptions } = options\n\n  const isSupported =\n    typeof window !== 'undefined' && 'IntersectionObserver' in window\n  const isIntersecting = ref(false)\n\n  let observer: IntersectionObserver | null = null\n\n  const cleanup = () => {\n    if (observer) {\n      observer.disconnect()\n      observer = null\n    }\n  }\n\n  const observe = () => {\n    cleanup()\n\n    if (!isSupported || !target.value) return\n\n    observer = new IntersectionObserver((entries) => {\n      isIntersecting.value = entries.some((entry) => entry.isIntersecting)\n      callback(entries, observer!)\n    }, observerOptions)\n\n    observer.observe(target.value)\n  }\n\n  const unobserve = () => {\n    if (observer && target.value) {\n      observer.unobserve(target.value)\n    }\n  }\n\n  if (immediate) {\n    watch(target, observe, { immediate: true, flush: 'post' })\n  }\n\n  onBeforeUnmount(cleanup)\n\n  return {\n    isSupported,\n    isIntersecting,\n    observe,\n    unobserve,\n    cleanup\n  }\n}\n","import { reactive } from 'vue'\n\ninterface CachedMedia {\n  src: string\n  blob?: Blob\n  objectUrl?: string\n  error?: boolean\n  isLoading: boolean\n  lastAccessed: number\n}\n\ninterface MediaCacheOptions {\n  maxSize?: number\n  maxAge?: number // in milliseconds\n  preloadDistance?: number // pixels from viewport\n}\n\nclass MediaCacheService {\n  public cache = reactive(new Map<string, CachedMedia>())\n  private readonly maxSize: number\n  private readonly maxAge: number\n  private cleanupInterval: number | null = null\n  private urlRefCount = new Map<string, number>()\n\n  constructor(options: MediaCacheOptions = {}) {\n    this.maxSize = options.maxSize ?? 100\n    this.maxAge = options.maxAge ?? 30 * 60 * 1000 // 30 minutes\n\n    // Start cleanup interval\n    this.startCleanupInterval()\n  }\n\n  private startCleanupInterval() {\n    // Clean up every 5 minutes\n    this.cleanupInterval = window.setInterval(\n      () => {\n        this.cleanup()\n      },\n      5 * 60 * 1000\n    )\n  }\n\n  private cleanup() {\n    const now = Date.now()\n    const keysToDelete: string[] = []\n\n    // Find expired entries\n    for (const [key, entry] of Array.from(this.cache.entries())) {\n      if (now - entry.lastAccessed > this.maxAge) {\n        // Only revoke object URL if no components are using it\n        if (entry.objectUrl) {\n          const refCount = this.urlRefCount.get(entry.objectUrl) || 0\n          if (refCount === 0) {\n            URL.revokeObjectURL(entry.objectUrl)\n            this.urlRefCount.delete(entry.objectUrl)\n            keysToDelete.push(key)\n          }\n          // Don't delete cache entry if URL is still in use\n        } else {\n          keysToDelete.push(key)\n        }\n      }\n    }\n\n    // Remove expired entries\n    keysToDelete.forEach((key) => this.cache.delete(key))\n\n    // If still over size limit, remove oldest entries that aren't in use\n    if (this.cache.size > this.maxSize) {\n      const entries = Array.from(this.cache.entries())\n      entries.sort((a, b) => a[1].lastAccessed - b[1].lastAccessed)\n\n      let removedCount = 0\n      const targetRemoveCount = this.cache.size - this.maxSize\n\n      for (const [key, entry] of entries) {\n        if (removedCount >= targetRemoveCount) break\n\n        if (entry.objectUrl) {\n          const refCount = this.urlRefCount.get(entry.objectUrl) || 0\n          if (refCount === 0) {\n            URL.revokeObjectURL(entry.objectUrl)\n            this.urlRefCount.delete(entry.objectUrl)\n            this.cache.delete(key)\n            removedCount++\n          }\n        } else {\n          this.cache.delete(key)\n          removedCount++\n        }\n      }\n    }\n  }\n\n  async getCachedMedia(src: string): Promise<CachedMedia> {\n    let entry = this.cache.get(src)\n\n    if (entry) {\n      // Update last accessed time\n      entry.lastAccessed = Date.now()\n      return entry\n    }\n\n    // Create new entry\n    entry = {\n      src,\n      isLoading: true,\n      lastAccessed: Date.now()\n    }\n\n    // Update cache with loading entry\n    this.cache.set(src, entry)\n\n    try {\n      // Fetch the media\n      const response = await fetch(src, { cache: 'force-cache' })\n      if (!response.ok) {\n        console.error(`Failed to fetch: ${response.status}`)\n        const errorEntry: CachedMedia = {\n          src,\n          error: true,\n          isLoading: false,\n          lastAccessed: Date.now()\n        }\n        this.cache.set(src, errorEntry)\n        return errorEntry\n      }\n\n      const blob = await response.blob()\n      const objectUrl = URL.createObjectURL(blob)\n\n      // Update entry with successful result\n      const updatedEntry: CachedMedia = {\n        src,\n        blob,\n        objectUrl,\n        isLoading: false,\n        lastAccessed: Date.now()\n      }\n\n      this.cache.set(src, updatedEntry)\n      return updatedEntry\n    } catch (error) {\n      console.warn('Failed to cache media:', src, error)\n\n      // Update entry with error\n      const errorEntry: CachedMedia = {\n        src,\n        error: true,\n        isLoading: false,\n        lastAccessed: Date.now()\n      }\n\n      this.cache.set(src, errorEntry)\n      return errorEntry\n    }\n  }\n\n  acquireUrl(src: string): string | undefined {\n    const entry = this.cache.get(src)\n    if (entry?.objectUrl) {\n      const currentCount = this.urlRefCount.get(entry.objectUrl) || 0\n      this.urlRefCount.set(entry.objectUrl, currentCount + 1)\n      return entry.objectUrl\n    }\n    return undefined\n  }\n\n  releaseUrl(src: string): void {\n    const entry = this.cache.get(src)\n    if (entry?.objectUrl) {\n      const count = (this.urlRefCount.get(entry.objectUrl) || 1) - 1\n      if (count <= 0) {\n        URL.revokeObjectURL(entry.objectUrl)\n        this.urlRefCount.delete(entry.objectUrl)\n        // Remove from cache as well\n        this.cache.delete(src)\n      } else {\n        this.urlRefCount.set(entry.objectUrl, count)\n      }\n    }\n  }\n\n  clearCache() {\n    // Revoke all object URLs\n    for (const entry of Array.from(this.cache.values())) {\n      if (entry.objectUrl) {\n        URL.revokeObjectURL(entry.objectUrl)\n      }\n    }\n    this.cache.clear()\n    this.urlRefCount.clear()\n  }\n\n  destroy() {\n    if (this.cleanupInterval) {\n      clearInterval(this.cleanupInterval)\n      this.cleanupInterval = null\n    }\n    this.clearCache()\n  }\n}\n\n// Global instance\nlet mediaCacheInstance: MediaCacheService | null = null\n\nexport function useMediaCache(options?: MediaCacheOptions) {\n  if (!mediaCacheInstance) {\n    mediaCacheInstance = new MediaCacheService(options)\n  }\n\n  const getCachedMedia = (src: string) =>\n    mediaCacheInstance!.getCachedMedia(src)\n  const clearCache = () => mediaCacheInstance!.clearCache()\n  const acquireUrl = (src: string) => mediaCacheInstance!.acquireUrl(src)\n  const releaseUrl = (src: string) => mediaCacheInstance!.releaseUrl(src)\n\n  return {\n    getCachedMedia,\n    clearCache,\n    acquireUrl,\n    releaseUrl,\n    cache: mediaCacheInstance.cache\n  }\n}\n\n// Cleanup on page unload\nif (typeof window !== 'undefined') {\n  window.addEventListener('beforeunload', () => {\n    if (mediaCacheInstance) {\n      mediaCacheInstance.destroy()\n    }\n  })\n}\n","<template>\n  <div\n    ref=\"containerRef\"\n    class=\"relative flex size-full items-center justify-center overflow-hidden\"\n    :class=\"containerClass\"\n  >\n    <Skeleton v-if=\"!isImageLoaded\" class=\"absolute inset-0 size-full\" />\n    <img\n      v-if=\"cachedSrc\"\n      :src=\"cachedSrc\"\n      :alt=\"alt\"\n      draggable=\"false\"\n      :class=\"imageClass\"\n      :style=\"imageStyle\"\n      @load=\"onImageLoad\"\n      @error=\"onImageError\"\n    />\n    <div\n      v-if=\"hasError\"\n      class=\"absolute inset-0 flex items-center justify-center\"\n    >\n      <img\n        src=\"/assets/images/default-template.png\"\n        :alt=\"alt\"\n        draggable=\"false\"\n        :class=\"imageClass\"\n        :style=\"imageStyle\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onUnmounted, ref, watch } from 'vue'\nimport type { StyleValue } from 'vue'\n\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport { useIntersectionObserver } from '@/composables/useIntersectionObserver'\nimport { useMediaCache } from '@/services/mediaCacheService'\n\ntype ClassValue = string | Record<string, boolean> | ClassValue[]\n\nconst {\n  src,\n  alt = '',\n  containerClass = '',\n  imageClass = '',\n  imageStyle,\n  rootMargin = '300px'\n} = defineProps<{\n  src: string\n  alt?: string\n  containerClass?: ClassValue\n  imageClass?: ClassValue\n  imageStyle?: StyleValue\n  rootMargin?: string\n}>()\n\nconst containerRef = ref<HTMLElement | null>(null)\nconst isIntersecting = ref(false)\nconst isImageLoaded = ref(false)\nconst hasError = ref(false)\nconst cachedSrc = ref<string | undefined>(undefined)\n\nconst { getCachedMedia, acquireUrl, releaseUrl } = useMediaCache()\n\n// Use intersection observer to detect when the image container comes into view\nuseIntersectionObserver(\n  containerRef,\n  (entries) => {\n    const entry = entries[0]\n    isIntersecting.value = entry?.isIntersecting ?? false\n  },\n  {\n    rootMargin,\n    threshold: 0.1\n  }\n)\n\n// Only start loading the image when it's in view\nconst shouldLoad = computed(() => isIntersecting.value)\n\nwatch(\n  shouldLoad,\n  async (shouldLoadVal) => {\n    if (shouldLoadVal && src && !cachedSrc.value && !hasError.value) {\n      try {\n        const cachedMedia = await getCachedMedia(src)\n        if (cachedMedia.error) {\n          hasError.value = true\n        } else if (cachedMedia.objectUrl) {\n          const acquiredUrl = acquireUrl(src)\n          cachedSrc.value = acquiredUrl || cachedMedia.objectUrl\n        } else {\n          cachedSrc.value = src\n        }\n      } catch (error) {\n        console.warn('Failed to load cached media:', error)\n        cachedSrc.value = src\n      }\n    } else if (!shouldLoadVal) {\n      if (cachedSrc.value?.startsWith('blob:')) {\n        releaseUrl(src)\n      }\n      // Hide image when out of view\n      isImageLoaded.value = false\n      cachedSrc.value = undefined\n      hasError.value = false\n    }\n  },\n  { immediate: true }\n)\n\nconst onImageLoad = () => {\n  isImageLoaded.value = true\n  hasError.value = false\n}\n\nconst onImageError = () => {\n  hasError.value = true\n  isImageLoaded.value = false\n}\n\nonUnmounted(() => {\n  if (cachedSrc.value?.startsWith('blob:')) {\n    releaseUrl(src)\n  }\n})\n</script>\n","<template>\n  <BaseThumbnail :is-hovered=\"isHovered\">\n    <LazyImage\n      :src=\"baseImageSrc\"\n      :alt=\"alt\"\n      :image-class=\"\n        isVideoType\n          ? 'w-full h-full object-cover'\n          : 'max-w-full max-h-64 object-contain'\n      \"\n    />\n    <div\n      data-testid=\"compare-slider-container\"\n      class=\"absolute inset-0\"\n      @mousemove=\"updateSliderPosition\"\n    >\n      <LazyImage\n        :src=\"overlayImageSrc\"\n        :alt=\"alt\"\n        :image-class=\"\n          isVideoType\n            ? 'w-full h-full object-cover'\n            : 'max-w-full max-h-64 object-contain'\n        \"\n        :image-style=\"{\n          clipPath: `inset(0 ${100 - sliderPosition}% 0 0)`\n        }\"\n      />\n      <div\n        data-testid=\"compare-slider-divider\"\n        class=\"pointer-events-none absolute inset-y-0 z-10 w-0.5 bg-white/30 backdrop-blur-sm\"\n        :style=\"{\n          left: `${sliderPosition}%`\n        }\"\n      />\n    </div>\n  </BaseThumbnail>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\n\nimport LazyImage from '@/components/common/LazyImage.vue'\nimport BaseThumbnail from '@/components/templates/thumbnails/BaseThumbnail.vue'\n\nconst SLIDER_START_POSITION = 50\n\nconst { baseImageSrc, overlayImageSrc, isHovered, isVideo } = defineProps<{\n  baseImageSrc: string\n  overlayImageSrc: string\n  alt: string\n  isHovered?: boolean\n  isVideo?: boolean\n}>()\n\nconst isVideoType =\n  isVideo ||\n  baseImageSrc?.toLowerCase().endsWith('.webp') ||\n  overlayImageSrc?.toLowerCase().endsWith('.webp') ||\n  false\n\nconst sliderPosition = ref(SLIDER_START_POSITION)\n\n/**\n * Update slider position from a local mousemove. Scoped to currentTarget so\n * only the hovered card reads its rect — unlike useMouseInElement which\n * attaches a global mousemove listener and fires for every mounted instance.\n */\nfunction updateSliderPosition(event: MouseEvent) {\n  const el = event.currentTarget as HTMLElement\n  const rect = el.getBoundingClientRect()\n  if (rect.width === 0) return\n  // Clamp to [0, 100] — subpixel rounding or stale rects on hover-in can\n  // push the raw percentage slightly out of range, which would offset the\n  // divider past the container or invert the overlay's clipPath.\n  const raw = ((event.clientX - rect.left) / rect.width) * 100\n  sliderPosition.value = Math.max(0, Math.min(100, raw))\n}\n</script>\n","<template>\n  <BaseThumbnail :hover-zoom=\"hoverZoom\" :is-hovered=\"isHovered\">\n    <LazyImage\n      :src=\"src\"\n      :alt=\"alt\"\n      :image-class=\"[\n        'transform-gpu transition-transform duration-300 ease-out',\n        isVideoType\n          ? 'w-full h-full object-cover'\n          : 'max-w-full max-h-64 object-contain'\n      ]\"\n      :image-style=\"\n        isHovered ? { transform: `scale(${1 + hoverZoom / 100})` } : undefined\n      \"\n    />\n  </BaseThumbnail>\n</template>\n\n<script setup lang=\"ts\">\nimport LazyImage from '@/components/common/LazyImage.vue'\nimport BaseThumbnail from '@/components/templates/thumbnails/BaseThumbnail.vue'\n\nconst { src, isVideo } = defineProps<{\n  src: string\n  alt: string\n  hoverZoom: number\n  isHovered?: boolean\n  isVideo?: boolean\n}>()\n\nconst isVideoType = isVideo ?? (src?.toLowerCase().endsWith('.webp') || false)\n</script>\n","<template>\n  <BaseThumbnail :is-hovered=\"isHovered\">\n    <div class=\"relative size-full\">\n      <div class=\"absolute inset-0\">\n        <LazyImage\n          :src=\"baseImageSrc\"\n          :alt=\"alt\"\n          :image-class=\"baseImageClass\"\n        />\n      </div>\n      <div class=\"absolute inset-0 z-10\">\n        <LazyImage\n          :src=\"overlayImageSrc\"\n          :alt=\"alt\"\n          :image-class=\"overlayImageClass\"\n        />\n      </div>\n    </div>\n  </BaseThumbnail>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport LazyImage from '@/components/common/LazyImage.vue'\nimport BaseThumbnail from '@/components/templates/thumbnails/BaseThumbnail.vue'\n\nconst { baseImageSrc, overlayImageSrc, isVideo, isHovered } = defineProps<{\n  baseImageSrc: string\n  overlayImageSrc: string\n  alt: string\n  isHovered: boolean\n  isVideo?: boolean\n}>()\n\nconst isVideoType =\n  isVideo ||\n  baseImageSrc?.toLowerCase().endsWith('.webp') ||\n  overlayImageSrc?.toLowerCase().endsWith('.webp') ||\n  false\n\nconst baseImageClass = computed(() => {\n  const sizeClasses = isVideoType\n    ? 'size-full object-cover'\n    : 'size-full object-contain'\n  return sizeClasses\n})\n\nconst overlayImageClass = computed(() => {\n  const baseClasses = 'size-full transition-opacity duration-300'\n  const sizeClasses = isVideoType ? 'object-cover' : 'object-contain'\n  const opacityClasses = isHovered ? 'opacity-100' : 'opacity-0'\n  return `${baseClasses} ${sizeClasses} ${opacityClasses}`\n})\n</script>\n","import type {\n  LogoInfo,\n  TemplateInfo,\n  TemplateTypeFilter\n} from '@/platform/workflow/templates/types/template'\n\n/**\n * Whether a template opens in App Mode rather than as a node graph.\n *\n * Reads `isApp`, which `templates/index.json` derives from the workflow's own\n * `extra.linearMode`. That is the author's choice, recorded in the workflow.\n *\n * This previously read `name.endsWith('.app')`, which is wrong in both\n * directions: `templates_all_in_one_image_edit_models.app` carries the suffix but\n * is a node graph, while `template_qwen_image_illustration_lora` and\n * `template_sugar_coated_gummy_style_qwen` are Apps without it. The suffix\n * records how a workflow was saved, not what it is, so no amount of renaming\n * would have fixed the Apps filter.\n */\nexport function isAppTemplate(template: TemplateInfo): boolean {\n  return template.isApp === true\n}\n\nexport function filterTemplatesByType<T extends TemplateInfo>(\n  templates: T[],\n  type: TemplateTypeFilter\n): T[] {\n  if (type === 'all') return templates\n  const wantApp = type === 'apps'\n  return templates.filter((template) => isAppTemplate(template) === wantApp)\n}\n\nconst iconFiles = import.meta.glob(\n  '../../../../../packages/design-system/src/icons/*.svg',\n  { query: '?raw' }\n)\n\nconst AVAILABLE_ICON_SLUGS = new Set(\n  Object.keys(iconFiles).map(\n    (path) => path.split('/').pop()?.replace('.svg', '') ?? ''\n  )\n)\n\n/** Provider names whose slug does not fall out of the name itself. */\nconst PROVIDER_ICON_ALIASES: Record<string, string> = {\n  'black forest labs': 'bfl',\n  google: 'gemini',\n  lightricks: 'ltxv',\n  stability: 'stability-ai'\n}\n\nfunction toSlug(provider: string): string {\n  const normalized = provider.trim().toLowerCase()\n  return (\n    PROVIDER_ICON_ALIASES[normalized] ??\n    normalized.replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')\n  )\n}\n\nexport function getProviderIconClass(provider: string): string | null {\n  const slug = toSlug(provider)\n  return AVAILABLE_ICON_SLUGS.has(slug) ? `icon-mask-[comfy--${slug}]` : null\n}\n\nexport interface ProviderBadge {\n  provider: string\n  iconClass: string | null\n  logoUrl: string\n}\n\nexport interface ProviderBadges {\n  visible: ProviderBadge[]\n  extraProviders: string[]\n}\n\n/** Badges shown before the rest collapse into a \"+N\" chip. */\nconst MAX_VISIBLE_PROVIDERS = 5\n\nexport function getProviderBadges(\n  logo: LogoInfo,\n  getLogoUrl: (provider: string) => string\n): ProviderBadges | null {\n  const providers = Array.isArray(logo.provider)\n    ? logo.provider\n    : [logo.provider]\n  const badges = providers\n    .map((provider) => ({\n      provider,\n      iconClass: getProviderIconClass(provider),\n      logoUrl: getLogoUrl(provider)\n    }))\n    .filter((badge) => badge.iconClass !== null || badge.logoUrl !== '')\n\n  if (badges.length === 0) return null\n\n  return {\n    visible: badges.slice(0, MAX_VISIBLE_PROVIDERS),\n    extraProviders: badges\n      .slice(MAX_VISIBLE_PROVIDERS)\n      .map((badge) => badge.provider)\n  }\n}\n\n/** Tags shown before the rest collapse into a \"+N\" chip. */\nconst MAX_VISIBLE_TAGS = 2\n\nexport interface TemplateTags {\n  visible: string[]\n  hidden: string[]\n}\n\nexport function getTemplateTags(template: TemplateInfo): TemplateTags {\n  const tags = template.tags ?? []\n  return {\n    visible: tags.slice(0, MAX_VISIBLE_TAGS),\n    hidden: tags.slice(MAX_VISIBLE_TAGS)\n  }\n}\n","<template>\n  <div\n    v-for=\"logo in validLogos\"\n    :key=\"logo.key\"\n    :class=\"cn('absolute z-10', logo.position ?? defaultPosition)\"\n  >\n    <div\n      v-show=\"!hasAllFailed(logo.badges)\"\n      data-testid=\"logo-pill\"\n      class=\"flex items-center gap-1\"\n    >\n      <Tooltip v-for=\"badge in logo.badges\" :key=\"badge.provider\" open-on-click>\n        <TooltipTrigger as-child>\n          <button\n            type=\"button\"\n            :aria-label=\"badge.provider\"\n            data-testid=\"logo-badge\"\n            class=\"flex size-7 cursor-pointer items-center justify-center rounded-full border-none bg-black/30 p-0 backdrop-blur-[20px] focus-visible:ring-1 focus-visible:ring-white focus-visible:outline-none\"\n            @click.stop\n          >\n            <i\n              v-if=\"badge.iconClass\"\n              data-testid=\"logo-icon\"\n              :class=\"cn('size-3.5 text-white', badge.iconClass)\"\n              aria-hidden=\"true\"\n            />\n            <img\n              v-else\n              data-testid=\"logo-img\"\n              :src=\"badge.logoUrl\"\n              alt=\"\"\n              class=\"size-4 rounded-full object-cover\"\n              draggable=\"false\"\n              @error=\"onImageError(badge.provider)\"\n            />\n          </button>\n        </TooltipTrigger>\n        <TooltipContent>{{ badge.provider }}</TooltipContent>\n      </Tooltip>\n      <Tooltip v-if=\"logo.extraProviders.length\" open-on-click>\n        <TooltipTrigger as-child>\n          <button\n            type=\"button\"\n            :aria-label=\"logo.extraProviders.join(', ')\"\n            data-testid=\"logo-extra\"\n            class=\"flex h-7 min-w-7 cursor-pointer items-center justify-center rounded-full border-none bg-black/30 px-1.5 text-xs font-medium text-white backdrop-blur-[20px] focus-visible:ring-1 focus-visible:ring-white focus-visible:outline-none\"\n            @click.stop\n          >\n            +{{ logo.extraProviders.length }}\n          </button>\n        </TooltipTrigger>\n        <TooltipContent>{{ logo.extraProviders.join(', ') }}</TooltipContent>\n      </Tooltip>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\n\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport type { LogoInfo } from '@/platform/workflow/templates/types/template'\nimport type { ProviderBadge } from '@/platform/workflow/templates/utils/templateDisplay'\nimport { getProviderBadges } from '@/platform/workflow/templates/utils/templateDisplay'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  logos,\n  getLogoUrl,\n  defaultPosition = 'top-2 left-2'\n} = defineProps<{\n  logos: LogoInfo[]\n  getLogoUrl: (provider: string) => string\n  defaultPosition?: string\n}>()\n\nconst failedLogos = ref(new Set<string>())\n\nfunction onImageError(provider: string) {\n  failedLogos.value = new Set([...failedLogos.value, provider])\n}\n\nfunction hasAllFailed(badges: ProviderBadge[]): boolean {\n  return (\n    badges.length > 0 &&\n    badges.every(\n      (badge) => !badge.iconClass && failedLogos.value.has(badge.provider)\n    )\n  )\n}\n\ninterface ValidatedLogo {\n  key: string\n  badges: ProviderBadge[]\n  extraProviders: string[]\n  position: string | undefined\n}\n\nconst validLogos = computed<ValidatedLogo[]>(() =>\n  logos.flatMap((logo) => {\n    const badges = getProviderBadges(logo, getLogoUrl)\n    if (!badges) return []\n\n    const providerKey = badges.visible.map((b) => b.provider).join('-')\n    return {\n      key: `${providerKey}-${logo.position ?? ''}`,\n      badges: badges.visible,\n      extraProviders: badges.extraProviders,\n      position: logo.position\n    }\n  })\n)\n</script>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport AudioThumbnail from '@/components/templates/thumbnails/AudioThumbnail.vue'\nimport CompareSliderThumbnail from '@/components/templates/thumbnails/CompareSliderThumbnail.vue'\nimport DefaultThumbnail from '@/components/templates/thumbnails/DefaultThumbnail.vue'\nimport HoverDissolveThumbnail from '@/components/templates/thumbnails/HoverDissolveThumbnail.vue'\nimport LogoOverlay from '@/components/templates/thumbnails/LogoOverlay.vue'\nimport type { TemplateInfo } from '@/platform/workflow/templates/types/template'\n\nconst {\n  template,\n  isHovered,\n  hoverZoom = 0\n} = defineProps<{\n  template: TemplateInfo\n  baseImageSrc: string\n  overlayImageSrc: string\n  alt: string\n  getLogoUrl: (provider: string) => string\n  /** Owned by the parent, which tracks what the pointer is over. */\n  isHovered: boolean\n  hoverZoom?: number\n}>()\nconst isVideo = computed(\n  () => template.mediaType === 'video' || template.mediaSubtype === 'webp'\n)\n</script>\n\n<template>\n  <div class=\"relative size-full overflow-hidden rounded-lg\">\n    <AudioThumbnail v-if=\"template.mediaType === 'audio'\" :src=\"baseImageSrc\" />\n    <CompareSliderThumbnail\n      v-else-if=\"template.thumbnailVariant === 'compareSlider'\"\n      :base-image-src=\"baseImageSrc\"\n      :overlay-image-src=\"overlayImageSrc\"\n      :alt=\"alt\"\n      :is-hovered=\"isHovered\"\n      :is-video=\"isVideo\"\n    />\n    <HoverDissolveThumbnail\n      v-else-if=\"template.thumbnailVariant === 'hoverDissolve'\"\n      :base-image-src=\"baseImageSrc\"\n      :overlay-image-src=\"overlayImageSrc\"\n      :alt=\"alt\"\n      :is-hovered=\"isHovered\"\n      :is-video=\"isVideo\"\n    />\n    <DefaultThumbnail\n      v-else\n      :src=\"baseImageSrc\"\n      :alt=\"alt\"\n      :is-hovered=\"isHovered\"\n      :is-video=\"isVideo\"\n      :hover-zoom=\"hoverZoom\"\n    />\n    <LogoOverlay\n      v-if=\"template.logos?.length\"\n      :logos=\"template.logos\"\n      :get-logo-url=\"getLogoUrl\"\n      default-position=\"right-2 bottom-2\"\n    />\n    <slot name=\"overlay\" />\n  </div>\n</template>\n","import { computed, ref, shallowRef, watch } from 'vue'\nimport type { Ref } from 'vue'\n\ninterface LazyPaginationOptions {\n  itemsPerPage?: number\n  initialPage?: number\n}\n\nexport function useLazyPagination<T>(\n  items: Ref<T[]> | T[],\n  options: LazyPaginationOptions = {}\n) {\n  const { itemsPerPage = 12, initialPage = 1 } = options\n\n  const currentPage = ref(initialPage)\n  const isLoading = ref(false)\n  const loadedPages = shallowRef(new Set<number>([]))\n\n  // Get reactive items array\n  const itemsArray = computed(() => {\n    const itemData = 'value' in items ? items.value : items\n    return Array.isArray(itemData) ? itemData : []\n  })\n\n  // Simulate pagination by slicing the items\n  const paginatedItems = computed(() => {\n    const itemData = itemsArray.value\n    if (itemData.length === 0) {\n      return []\n    }\n\n    const loadedPageNumbers = Array.from(loadedPages.value).sort(\n      (a, b) => a - b\n    )\n    const maxLoadedPage = Math.max(...loadedPageNumbers, 0)\n    const endIndex = maxLoadedPage * itemsPerPage\n    return itemData.slice(0, endIndex)\n  })\n\n  const hasMoreItems = computed(() => {\n    const itemData = itemsArray.value\n    if (itemData.length === 0) {\n      return false\n    }\n\n    const loadedPagesArray = Array.from(loadedPages.value)\n    const maxLoadedPage = Math.max(...loadedPagesArray, 0)\n    return maxLoadedPage * itemsPerPage < itemData.length\n  })\n\n  const totalPages = computed(() => {\n    const itemData = itemsArray.value\n    if (itemData.length === 0) {\n      return 0\n    }\n    return Math.ceil(itemData.length / itemsPerPage)\n  })\n\n  const loadNextPage = async () => {\n    if (isLoading.value || !hasMoreItems.value) return\n\n    isLoading.value = true\n    const loadedPagesArray = Array.from(loadedPages.value)\n    const nextPage = Math.max(...loadedPagesArray, 0) + 1\n\n    // Simulate network delay\n    // await new Promise((resolve) => setTimeout(resolve, 5000))\n\n    const newLoadedPages = new Set(loadedPages.value)\n    newLoadedPages.add(nextPage)\n    loadedPages.value = newLoadedPages\n    currentPage.value = nextPage\n    isLoading.value = false\n  }\n\n  // Initialize with first page\n  watch(\n    () => itemsArray.value.length,\n    (length) => {\n      if (length > 0 && loadedPages.value.size === 0) {\n        loadedPages.value = new Set([1])\n      }\n    },\n    { immediate: true }\n  )\n\n  const reset = () => {\n    currentPage.value = initialPage\n    loadedPages.value = new Set([])\n    isLoading.value = false\n\n    // Immediately load first page if we have items\n    const itemData = itemsArray.value\n    if (itemData.length > 0) {\n      loadedPages.value = new Set([1])\n    }\n  }\n\n  return {\n    paginatedItems,\n    isLoading,\n    hasMoreItems,\n    currentPage,\n    totalPages,\n    loadNextPage,\n    reset\n  }\n}\n","// Ceiling of the authored 0-1000 range (workflow_templates docs/SPEC.md).\nconst SEARCH_RANK_SATURATION = 1000\n\n// Spans the retired 1-10 scale's demote band; no legacy value flips to promote.\nconst SEARCH_RANK_DEAD_ZONE = 5\n\n/**\n * Curator intent as a signed strength in [-1, 1]. Unset, non-numeric, and any\n * rank within the dead zone are the same neutral baseline — most of the catalog\n * ships an explicit `\"searchRank\": 0` meaning \"not curated\", so 0 must not\n * demote. Promotion starts once the rank exceeds the dead zone and demotion\n * once it falls below the negative of it, each saturating at the cap.\n */\nexport function searchRankBoost(searchRank: number | undefined): number {\n  if (!searchRank || Math.abs(searchRank) <= SEARCH_RANK_DEAD_ZONE) return 0\n  const magnitude = Math.min(\n    1,\n    Math.log1p(Math.abs(searchRank)) / Math.log1p(SEARCH_RANK_SATURATION)\n  )\n  return Math.sign(searchRank) * magnitude\n}\n","import { uniqBy } from 'es-toolkit'\nimport MiniSearch from 'minisearch'\nimport type { SearchResult } from 'minisearch'\n\nimport { searchRankBoost } from './templateRanking'\n\nexport interface SearchableTemplate {\n  name: string\n  title?: string\n  description?: string\n  localizedTitle?: string\n  localizedDescription?: string\n  tags?: string[]\n  models?: string[]\n  searchRank?: number\n  usage?: number\n}\n\n// MiniSearch serializes the index but not the search options, so the tokenizer\n// and field list live here and are used at both index and query time.\n\nconst SEARCH_FIELDS = [\n  'title',\n  'description',\n  'tags',\n  'models',\n  'name'\n] as const\n\n// Usage only reorders hits within this fraction of the top score, so popularity\n// never overrides a clearly-better text match. 5% tuned empirically.\nconst USAGE_TIEBREAK_BAND = 0.05\n\n// ~6 tiebreak bands of headroom: enough to lift a near-equal match, never\n// enough to surface a weak one.\nconst SEARCH_RANK_RELEVANCE_WEIGHT = 0.3\n\n// Script-matched so spaced neighbors like Korean fall to the word tokenizer.\nconst CJK = /[\\p{scx=Han}\\p{scx=Hiragana}\\p{scx=Katakana}]/u\nconst CJK_RUN = new RegExp(`${CJK.source}+`, 'gu')\n\n// Unigrams + bigrams so any substring of an unspaced run lands on a token.\nfunction cjkGrams(word: string): string[] {\n  const grams: string[] = []\n  for (const run of word.match(CJK_RUN) ?? []) {\n    const characters = run.split('')\n    grams.push(...characters)\n    for (let i = 1; i < characters.length; i++) {\n      grams.push(characters[i - 1] + characters[i])\n    }\n  }\n  return grams\n}\n\n/**\n * Emits sub-parts so a term matches however it's typed: `-`/`_` splits, a\n * trailing version (`wan2.7` → `wan`, `2.7`), and CJK character grams.\n */\nexport function tokenize(text: string): string[] {\n  const tokens = new Set<string>()\n  for (const word of text.toLowerCase().split(/\\s+/).filter(Boolean)) {\n    for (const gram of cjkGrams(word)) tokens.add(gram)\n    // A pure-CJK run has no whole-word token — its grams already cover it.\n    if (CJK.test(word) && !/[a-z0-9]/.test(word)) continue\n    tokens.add(word)\n    for (const part of word.split(/[-_]/)) {\n      if (part) tokens.add(part)\n    }\n    const version = word.match(/^([a-z][a-z.]*?)(\\d+(?:\\.\\d+)*)$/)\n    if (version) {\n      tokens.add(version[1].replace(/\\.$/, ''))\n      tokens.add(version[2])\n    }\n  }\n  return [...tokens]\n}\n\n// Exact for ≤3-char and digit-bearing terms; otherwise 20% of length, so a typo\n// is forgiven but `upscale` can't fuzzy-match the shorter `scale`.\nexport function termFuzziness(term: string): number | false {\n  return term.length <= 3 || /\\d/.test(term) ? false : 0.2\n}\n\nfunction searchOptions(combineWith: 'AND' | 'OR' = 'AND') {\n  // Description demoted below default so an incidental prose mention never\n  // outranks a real title/model match.\n  return {\n    boost: { title: 3, models: 2, tags: 2, description: 0.5 },\n    prefix: true,\n    fuzzy: termFuzziness,\n    combineWith,\n    tokenize\n  }\n}\n\n// `{X}2{Y}` shorthand expanded by structure (t2i, txt2img, …) rather than one\n// entry per spelling.\nconst MODALITY_STEMS: Record<string, string> = {\n  t: 'text',\n  txt: 'text',\n  text: 'text',\n  i: 'image',\n  img: 'image',\n  image: 'image',\n  v: 'video',\n  vid: 'video',\n  video: 'video',\n  a: 'audio',\n  s: 'audio',\n  m: 'music'\n}\n\nconst SAME_MODALITY_EDIT: Record<string, string> = {\n  image: 'image edit',\n  video: 'video edit',\n  audio: 'audio edit'\n}\n\nconst ACRONYMS: Record<string, string> = {\n  cn: 'controlnet'\n}\n\nexport function expandAbbreviation(token: string): string | null {\n  const lower = token.trim().toLowerCase()\n  if (ACRONYMS[lower]) return ACRONYMS[lower]\n\n  const match = lower.match(/^([a-z]+)2([a-z]+)$/)\n  if (!match) return null\n  const left = MODALITY_STEMS[match[1]]\n  const right = MODALITY_STEMS[match[2]]\n  if (!left || !right) return null\n  if (left === right) return SAME_MODALITY_EDIT[left] ?? left\n  return `${left} ${right}`\n}\n\n/** Expands shorthand tokens (`wan i2v` → `wan image video`); null if none expand. */\nexport function expandQuery(query: string): string | null {\n  const expandedTokens = query\n    .split(/\\s+/)\n    .filter(Boolean)\n    .map((token) => {\n      const expansion = expandAbbreviation(token.toLowerCase())\n      return { token: expansion ?? token, expanded: expansion !== null }\n    })\n  if (!expandedTokens.some(({ expanded }) => expanded)) return null\n  return expandedTokens.map(({ token }) => token).join(' ')\n}\n\nexport function createTemplateSearchIndex(\n  templates: SearchableTemplate[]\n): MiniSearch<SearchableTemplate> {\n  const index = new MiniSearch<SearchableTemplate>({\n    idField: 'name',\n    fields: [...SEARCH_FIELDS],\n    // Returned on each hit so ranking can read usage and curation without a\n    // second lookup.\n    storeFields: ['usage', 'searchRank'],\n    // Index the localized strings the card actually shows, so a match explains\n    // a visible result.\n    extractField: (template, field) => {\n      if (field === 'title') return template.localizedTitle ?? template.title\n      if (field === 'description') {\n        return template.localizedDescription ?? template.description\n      }\n      const value = template[field as keyof SearchableTemplate]\n      return Array.isArray(value) ? value.join(' ') : (value as string)\n    },\n    tokenize,\n    searchOptions: searchOptions('AND')\n  })\n  // Custom-node templates are named by filename, so two packs can share a name;\n  // a duplicate ID makes MiniSearch throw and leaves search showing everything.\n  index.addAll(uniqBy(templates, (template) => template.name))\n  return index\n}\n\nfunction searchRankMultiplier(searchRank: number | undefined): number {\n  return 1 + searchRankBoost(searchRank) * SEARCH_RANK_RELEVANCE_WEIGHT\n}\n\n// Rank by curated relevance, with usage breaking ties inside a score band.\n// Scores are bucketed so the ordering is a stable total order (a pairwise\n// relative-band compare is intransitive). log1p dampens heavy-tailed usage.\nexport function rankByRelevanceThenUsage(hits: SearchResult[]): SearchResult[] {\n  const ranked = hits.map((hit) => ({\n    hit,\n    score: hit.score * searchRankMultiplier(Number(hit.searchRank ?? 0))\n  }))\n  const bandSize =\n    ranked.reduce((max, entry) => Math.max(max, entry.score), 0) *\n    USAGE_TIEBREAK_BAND\n  const bucket = (score: number) =>\n    bandSize > 0 ? Math.round(score / bandSize) : 0\n  return ranked\n    .sort((a, b) => {\n      if (bucket(a.score) !== bucket(b.score)) return b.score - a.score\n      return (\n        Math.log1p(Number(b.hit.usage ?? 0)) -\n        Math.log1p(Number(a.hit.usage ?? 0))\n      )\n    })\n    .map((entry) => entry.hit)\n}\n\n/** Ordered template names for a query: literal matches first, then dedup'd expansion matches. */\nexport function searchTemplates(\n  index: MiniSearch<SearchableTemplate>,\n  query: string\n): string[] {\n  const trimmed = query.trim()\n  if (!trimmed) return []\n\n  const andThenOr = (q: string): SearchResult[] => {\n    const and = index.search(q, searchOptions('AND'))\n    const hits = and.length > 0 ? and : index.search(q, searchOptions('OR'))\n    return rankByRelevanceThenUsage(hits)\n  }\n\n  const ordered: string[] = []\n  const seen = new Set<string>()\n  const collect = (hits: SearchResult[]) => {\n    for (const hit of hits) {\n      const id = String(hit.id)\n      if (!seen.has(id)) {\n        seen.add(id)\n        ordered.push(id)\n      }\n    }\n  }\n\n  collect(andThenOr(trimmed))\n  const expanded = expandQuery(trimmed)\n  if (expanded) collect(andThenOr(expanded))\n\n  return ordered\n}\n","import { debounce } from 'es-toolkit/compat'\nimport { onScopeDispose, watch } from 'vue'\nimport type { Ref } from 'vue'\n\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { SearchSurface } from '@/platform/telemetry/types'\n\nconst DEBOUNCE_MS = 500\nconst MAX_QUERY_CHARS = 100\n\n/**\n * Fires `app:search_query` for the given surface, debounced 500ms.\n * Empty queries are skipped. `results` is read at fire time and only its\n * `.length` is observed, so callers can pass any reactive array (filtered\n * suggestions, displayed results, etc.). The pending debounced call is\n * cancelled on scope dispose so a user who types-and-closes within the\n * window doesn't emit a stale event.\n *\n * The captured `query` is truncated to MAX_QUERY_CHARS to cap PII\n * exposure (mirrors GTM provider's sanitizeProperties cap). `query_length`\n * remains the full pre-truncation length so we keep the distributional\n * signal.\n */\nexport function useSearchQueryTracking(\n  surface: SearchSurface,\n  query: Ref<string>,\n  results: Ref<{ length: number }>\n): void {\n  const fire = debounce((value: string) => {\n    const trimmed = value.trim()\n    if (!trimmed) return\n    const count = results.value.length\n    useTelemetry()?.trackSearchQuery({\n      surface,\n      query: trimmed.slice(0, MAX_QUERY_CHARS),\n      query_length: trimmed.length,\n      result_count: count,\n      has_results: count > 0\n    })\n  }, DEBOUNCE_MS)\n\n  watch(query, fire)\n  onScopeDispose(() => fire.cancel())\n}\n","/**\n * Store for template ranking scores.\n * Loads pre-computed usage scores from static JSON.\n * Internal ranks come from template.searchRank in index.json.\n * See docs/TEMPLATE_RANKING.md for details.\n */\n\nimport { defineStore } from 'pinia'\nimport { ref } from 'vue'\n\nimport { searchRankBoost } from '@comfyorg/shared-frontend-utils/templateRanking'\n\nexport const useTemplateRankingStore = defineStore('templateRanking', () => {\n  const largestUsageScore = ref<number>()\n\n  const normalizeUsageScore = (usage: number): number => {\n    const largest = largestUsageScore.value\n    return largest ? usage / largest : 0\n  }\n\n  /**\n   * Compute freshness score based on template date.\n   * Returns 1.0 for brand new, decays to 0.1 over ~6 months.\n   */\n  const computeFreshness = (dateStr: string | undefined): number => {\n    if (!dateStr) return 0.5 // Default for templates without dates\n\n    const date = new Date(dateStr)\n    if (isNaN(date.getTime())) return 0.5\n\n    const daysSinceAdded = (Date.now() - date.getTime()) / (1000 * 60 * 60 * 24)\n    return Math.max(0.1, 1.0 / (1 + daysSinceAdded / 90))\n  }\n\n  /**\n   * Compute composite score for \"recommended\" sort.\n   * Formula: usage × 0.5 + curation × 0.3 + freshness × 0.2\n   */\n  const computeDefaultScore = (\n    dateStr: string | undefined,\n    searchRank: number | undefined,\n    usage: number = 0\n  ): number => {\n    // searchRankBoost is [-1, 1]; shift to [0, 1] so neutral stays the midpoint.\n    const curation = (searchRankBoost(searchRank) + 1) / 2\n    const freshness = computeFreshness(dateStr)\n\n    return normalizeUsageScore(usage) * 0.5 + curation * 0.3 + freshness * 0.2\n  }\n\n  return {\n    largestUsageScore,\n    computeFreshness,\n    computeDefaultScore\n  }\n})\n","import { watchDebounced } from '@vueuse/core'\nimport { computed, ref, watch } from 'vue'\nimport type { Ref } from 'vue'\n\nimport {\n  createTemplateSearchIndex,\n  searchTemplates\n} from '@comfyorg/shared-frontend-utils/templateSearch'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useSearchQueryTracking } from '@/platform/telemetry/searchQuery/useSearchQueryTracking'\nimport { TemplateIncludeOnDistributionEnum } from '@/platform/workflow/templates/types/template'\nimport type { TemplateInfo } from '@/platform/workflow/templates/types/template'\nimport { useSystemStatsStore } from '@/stores/systemStatsStore'\nimport { useTemplateRankingStore } from '@/stores/templateRankingStore'\nimport { debounce } from 'es-toolkit/compat'\n\ntype TemplateBrowseSort =\n  | 'default'\n  | 'recommended'\n  | 'popular'\n  | 'alphabetical'\n  | 'newest'\n  | 'vram-low-to-high'\n  | 'model-size-low-to-high'\n\nexport type TemplateSortMode = TemplateBrowseSort | 'relevance'\n\nconst SEARCH_DEFAULT_SORT: TemplateSortMode = 'popular'\n\n/** The title shown on the card, trimmed for stable sorting. */\nfunction displayTitle(template: TemplateInfo): string {\n  return (\n    template.localizedTitle ||\n    template.title ||\n    template.name ||\n    ''\n  ).trim()\n}\n\n/** A→Z by displayed title, with number-prefixed titles grouped after letters. */\nfunction compareAlphabetical(a: TemplateInfo, b: TemplateInfo): number {\n  const titleA = displayTitle(a)\n  const titleB = displayTitle(b)\n  const numericA = /^\\d/.test(titleA)\n  const numericB = /^\\d/.test(titleB)\n  if (numericA !== numericB) return numericA ? 1 : -1\n  return titleA.localeCompare(titleB, undefined, {\n    numeric: true,\n    sensitivity: 'base'\n  })\n}\n\n/**\n * Checks whether a template is visible for the given set of distributions.\n * Templates without `includeOnDistributions` are visible everywhere.\n */\nfunction isTemplateVisibleForDistributions(\n  template: TemplateInfo,\n  distributions: TemplateIncludeOnDistributionEnum[]\n): boolean {\n  if (!template.includeOnDistributions?.length) return true\n  return distributions.some((d) => template.includeOnDistributions!.includes(d))\n}\n\nexport function useTemplateFiltering<T extends TemplateInfo>(\n  templates: Ref<T[]> | T[]\n) {\n  const settingStore = useSettingStore()\n  const systemStatsStore = useSystemStatsStore()\n  const rankingStore = useTemplateRankingStore()\n\n  const searchQuery = ref('')\n  const selectedModels = ref<string[]>(\n    settingStore.get('Comfy.Templates.SelectedModels')\n  )\n  const selectedUseCases = ref<string[]>(\n    settingStore.get('Comfy.Templates.SelectedUseCases')\n  )\n  const selectedRunsOn = ref<string[]>(\n    settingStore.get('Comfy.Templates.SelectedRunsOn')\n  )\n  const sortBy = ref<TemplateBrowseSort>(\n    settingStore.get('Comfy.Templates.SortBy')\n  )\n\n  const templatesArray = computed(() => {\n    const templateData = 'value' in templates ? templates.value : templates\n    return Array.isArray(templateData) ? templateData : []\n  })\n\n  const distributions = computed<TemplateIncludeOnDistributionEnum[]>(() => {\n    switch (__DISTRIBUTION__) {\n      case 'cloud':\n        return [TemplateIncludeOnDistributionEnum.Cloud]\n      case 'localhost':\n        return [TemplateIncludeOnDistributionEnum.Local]\n      case 'desktop':\n      default:\n        if (systemStatsStore.systemStats?.system.os === 'darwin') {\n          return [\n            TemplateIncludeOnDistributionEnum.Desktop,\n            TemplateIncludeOnDistributionEnum.Mac\n          ]\n        }\n        return [\n          TemplateIncludeOnDistributionEnum.Desktop,\n          TemplateIncludeOnDistributionEnum.Windows\n        ]\n    }\n  })\n\n  const visibleTemplates = computed(() => {\n    return templatesArray.value.filter((t) =>\n      isTemplateVisibleForDistributions(t, distributions.value)\n    )\n  })\n\n  const searchIndex = computed(() =>\n    createTemplateSearchIndex(visibleTemplates.value)\n  )\n\n  const availableModels = computed(() => {\n    const modelSet = new Set<string>()\n    visibleTemplates.value.forEach((template) => {\n      if (Array.isArray(template.models)) {\n        template.models.forEach((model) => modelSet.add(model))\n      }\n    })\n    return Array.from(modelSet).sort()\n  })\n\n  const availableUseCases = computed(() => {\n    const tagSet = new Set<string>()\n    visibleTemplates.value.forEach((template) => {\n      if (template.tags && Array.isArray(template.tags)) {\n        template.tags.forEach((tag) => tagSet.add(tag))\n      }\n    })\n    return Array.from(tagSet).sort()\n  })\n\n  const availableRunsOn = computed(() => {\n    return ['ComfyUI', 'External or Remote API']\n  })\n\n  // Compute which selected filters are actually applicable to the current scope\n  const activeModels = computed(() =>\n    selectedModels.value.filter((model) =>\n      availableModels.value.includes(model)\n    )\n  )\n\n  const activeUseCases = computed(() =>\n    selectedUseCases.value.filter((useCase) =>\n      availableUseCases.value.includes(useCase)\n    )\n  )\n\n  const inactiveModels = computed(() =>\n    selectedModels.value.filter(\n      (model) => !availableModels.value.includes(model)\n    )\n  )\n\n  const inactiveUseCases = computed(() =>\n    selectedUseCases.value.filter(\n      (useCase) => !availableUseCases.value.includes(useCase)\n    )\n  )\n\n  const hasActiveQuery = computed(() => searchQuery.value.trim().length > 0)\n  const searchSort = ref<TemplateSortMode>(SEARCH_DEFAULT_SORT)\n  watch(hasActiveQuery, (searching) => {\n    if (searching) searchSort.value = SEARCH_DEFAULT_SORT\n  })\n  const activeSort = computed(() =>\n    hasActiveQuery.value ? searchSort.value : sortBy.value\n  )\n\n  const sortSelection = computed<TemplateSortMode>({\n    get: () => activeSort.value,\n    set: (value) => {\n      // relevance is search-only; a browse sort chosen mid-search stays ephemeral.\n      if (value === 'relevance' || hasActiveQuery.value)\n        searchSort.value = value\n      else sortBy.value = value\n    }\n  })\n\n  const filteredBySearch = computed(() => {\n    if (!hasActiveQuery.value) {\n      return visibleTemplates.value\n    }\n\n    const templatesByName = new Map(\n      visibleTemplates.value.map((template) => [template.name, template])\n    )\n    return searchTemplates(searchIndex.value, searchQuery.value)\n      .map((name) => templatesByName.get(name))\n      .filter((template): template is T => template !== undefined)\n  })\n\n  const filteredByModels = computed(() => {\n    // Use active models instead of selected models for filtering\n    if (activeModels.value.length === 0) {\n      return filteredBySearch.value\n    }\n\n    return filteredBySearch.value.filter((template) => {\n      if (!template.models || !Array.isArray(template.models)) {\n        return false\n      }\n      return activeModels.value.some((activeModel) =>\n        template.models?.includes(activeModel)\n      )\n    })\n  })\n\n  const filteredByUseCases = computed(() => {\n    // Use active use cases instead of selected use cases for filtering\n    if (activeUseCases.value.length === 0) {\n      return filteredByModels.value\n    }\n\n    return filteredByModels.value.filter((template) => {\n      if (!template.tags || !Array.isArray(template.tags)) {\n        return false\n      }\n      return activeUseCases.value.some((activeUseCase) =>\n        template.tags?.includes(activeUseCase)\n      )\n    })\n  })\n\n  const filteredByRunsOn = computed(() => {\n    // RunsOn filters are scope-independent\n    if (selectedRunsOn.value.length === 0) {\n      return filteredByUseCases.value\n    }\n\n    return filteredByUseCases.value.filter((template) => {\n      // Use openSource field to determine where template runs\n      // openSource === false -> External/Remote API\n      // openSource !== false -> ComfyUI (includes true and undefined)\n      const isExternalAPI = template.openSource === false\n      const isComfyUI = template.openSource !== false\n\n      return selectedRunsOn.value.some((runsOn) => {\n        if (runsOn === 'External or Remote API') {\n          return isExternalAPI\n        } else if (runsOn === 'ComfyUI') {\n          return isComfyUI\n        }\n        return false\n      })\n    })\n  })\n\n  watch(\n    filteredByRunsOn,\n    (templates) => {\n      rankingStore.largestUsageScore = templates.reduce(\n        (max, template) => Math.max(max, template.usage ?? 0),\n        0\n      )\n    },\n    { immediate: true }\n  )\n\n  const sortedTemplates = computed(() => {\n    const templates = [...filteredByRunsOn.value]\n\n    switch (activeSort.value) {\n      case 'relevance':\n        return templates\n      case 'recommended':\n        // Curated: usage × 0.5 + internal × 0.3 + freshness × 0.2\n        return templates.sort((a, b) => {\n          const scoreA = rankingStore.computeDefaultScore(\n            a.date,\n            a.searchRank,\n            a.usage\n          )\n          const scoreB = rankingStore.computeDefaultScore(\n            b.date,\n            b.searchRank,\n            b.usage\n          )\n          return scoreB - scoreA\n        })\n      case 'popular':\n        return templates.sort((a, b) => (b.usage ?? 0) - (a.usage ?? 0))\n      case 'alphabetical':\n        return templates.sort(compareAlphabetical)\n      case 'newest':\n        return templates.sort((a, b) => {\n          const dateA = new Date(a.date || '1970-01-01')\n          const dateB = new Date(b.date || '1970-01-01')\n          return dateB.getTime() - dateA.getTime()\n        })\n      case 'model-size-low-to-high':\n        return templates.sort((a, b) => {\n          const sizeA =\n            typeof a.size === 'number' ? a.size : Number.POSITIVE_INFINITY\n          const sizeB =\n            typeof b.size === 'number' ? b.size : Number.POSITIVE_INFINITY\n          if (sizeA === sizeB) return 0\n          return sizeA - sizeB\n        })\n      case 'default':\n      default:\n        return templates\n    }\n  })\n\n  const filteredTemplates = computed(() => sortedTemplates.value)\n\n  const resetFilters = () => {\n    searchQuery.value = ''\n    selectedModels.value = []\n    selectedUseCases.value = []\n    selectedRunsOn.value = []\n    sortBy.value = 'default'\n    searchSort.value = SEARCH_DEFAULT_SORT\n  }\n\n  const removeModelFilter = (model: string) => {\n    selectedModels.value = selectedModels.value.filter((m) => m !== model)\n  }\n\n  const removeUseCaseFilter = (tag: string) => {\n    selectedUseCases.value = selectedUseCases.value.filter((t) => t !== tag)\n  }\n\n  const removeRunsOnFilter = (runsOn: string) => {\n    selectedRunsOn.value = selectedRunsOn.value.filter((r) => r !== runsOn)\n  }\n\n  const filteredCount = computed(() => filteredTemplates.value.length)\n  const totalCount = computed(() => visibleTemplates.value.length)\n  useSearchQueryTracking('templates', searchQuery, filteredTemplates)\n\n  // Template filter tracking (debounced to avoid excessive events)\n  const debouncedTrackFilterChange = debounce(() => {\n    useTelemetry()?.trackTemplateFilterChanged({\n      search_query: searchQuery.value || undefined,\n      selected_models: selectedModels.value,\n      selected_use_cases: selectedUseCases.value,\n      selected_runs_on: selectedRunsOn.value,\n      sort_by: activeSort.value,\n      filtered_count: filteredCount.value,\n      total_count: totalCount.value\n    })\n  }, 500)\n\n  // Watch for filter changes and track them\n  watch(\n    [searchQuery, selectedModels, selectedUseCases, selectedRunsOn, activeSort],\n    () => {\n      // Only track if at least one filter is active (to avoid tracking initial state)\n      const hasActiveFilters =\n        searchQuery.value.trim() !== '' ||\n        selectedModels.value.length > 0 ||\n        selectedUseCases.value.length > 0 ||\n        selectedRunsOn.value.length > 0 ||\n        activeSort.value !== 'default'\n\n      if (hasActiveFilters) {\n        debouncedTrackFilterChange()\n      }\n    },\n    { deep: true }\n  )\n\n  // Persist filter changes to settings (debounced to avoid excessive saves)\n  watchDebounced(\n    selectedModels,\n    (newValue) => {\n      void settingStore.set('Comfy.Templates.SelectedModels', newValue)\n    },\n    { debounce: 500, deep: true }\n  )\n\n  watchDebounced(\n    selectedUseCases,\n    (newValue) => {\n      void settingStore.set('Comfy.Templates.SelectedUseCases', newValue)\n    },\n    { debounce: 500, deep: true }\n  )\n\n  watchDebounced(\n    selectedRunsOn,\n    (newValue) => {\n      void settingStore.set('Comfy.Templates.SelectedRunsOn', newValue)\n    },\n    { debounce: 500, deep: true }\n  )\n\n  watchDebounced(\n    sortBy,\n    (newValue) => {\n      void settingStore.set('Comfy.Templates.SortBy', newValue)\n    },\n    { debounce: 500 }\n  )\n\n  return {\n    // State\n    searchQuery,\n    selectedModels,\n    selectedUseCases,\n    selectedRunsOn,\n    sortBy,\n    sortSelection,\n    hasActiveQuery,\n\n    // Computed - Active filters (actually applied)\n    activeModels,\n    activeUseCases,\n\n    // Computed - Inactive filters (selected but not applicable)\n    inactiveModels,\n    inactiveUseCases,\n\n    // Computed\n    filteredTemplates,\n    availableModels,\n    availableUseCases,\n    availableRunsOn,\n    filteredCount,\n    totalCount,\n\n    // Methods\n    resetFilters,\n    removeModelFilter,\n    removeUseCaseFilter,\n    removeRunsOnFilter\n  }\n}\n","const ACRONYM_TAGS = new Set(['VAE', 'CLIP', 'GLIGEN'])\n\nexport function formatCategoryLabel(raw?: string): string {\n  if (!raw) return 'Models'\n\n  // Special display name mappings\n  if (raw === 'diffusion_models') return 'Diffusion'\n\n  return raw\n    .split('_')\n    .map((segment) => {\n      const upper = segment.toUpperCase()\n      if (ACRONYM_TAGS.has(upper)) return upper\n\n      const lower = segment.toLowerCase()\n      return lower.charAt(0).toUpperCase() + lower.slice(1)\n    })\n    .join(' ')\n}\n","import type { ModelFile } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { getModelFileKey } from '@/platform/workflow/core/utils/modelRequirements'\n\ntype TemplateModelAvailabilityStatus = 'installed' | 'missing' | 'unknown'\n\ntype TemplateModelInventoryEntry = {\n  directory: string\n  name: string\n}\n\nexport type TemplateModelInventorySnapshot = {\n  isComplete: boolean\n  models: readonly TemplateModelInventoryEntry[]\n}\n\nexport type ResolvedTemplateModelAvailability = {\n  model: ModelFile\n  status: TemplateModelAvailabilityStatus\n}\n\nexport function resolveTemplateModelAvailability(\n  models: readonly ModelFile[],\n  inventory: TemplateModelInventorySnapshot\n): ResolvedTemplateModelAvailability[] {\n  const installedModelKeys = new Set(\n    inventory.models.map((model) =>\n      getModelFileKey({\n        directory: model.directory,\n        name: model.name.replaceAll('\\\\', '/')\n      })\n    )\n  )\n\n  return models.map((model) => ({\n    model,\n    status: installedModelKeys.has(\n      getModelFileKey({\n        directory: model.directory,\n        name: model.name.replaceAll('\\\\', '/')\n      })\n    )\n      ? 'installed'\n      : inventory.isComplete\n        ? 'missing'\n        : 'unknown'\n  }))\n}\n","import { debounce } from 'es-toolkit'\nimport { defineStore } from 'pinia'\nimport { computed, onScopeDispose, reactive, ref, watch } from 'vue'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport type { ModelFile } from '@/platform/assets/schemas/assetSchema'\nimport { assetService } from '@/platform/assets/services/assetService'\nimport { isCloud } from '@/platform/distribution/types'\nimport { api } from '@/scripts/api'\n\n/** (Internal helper) finds a value in a metadata object from any of a list of keys. */\nfunction _findInMetadata(\n  metadata: Record<string, string | null>,\n  ...keys: string[]\n): string | null {\n  for (const key of keys) {\n    if (key in metadata) {\n      const value = metadata[key]\n      return value || null\n    }\n    for (const k in metadata) {\n      if (k.endsWith(key)) {\n        const value = metadata[k]\n        return value || null\n      }\n    }\n  }\n  return null\n}\n\n/** Defines and holds metadata for a model */\nexport class ComfyModelDef {\n  /** Path to the model */\n  readonly path_index: number\n  /** Proper filename of the model */\n  readonly file_name: string\n  /** Normalized filename of the model, with all backslashes replaced with forward slashes */\n  readonly normalized_file_name: string\n  /** Directory containing the model, eg 'checkpoints' */\n  readonly directory: string\n  /** Simplified copy of name, used as a default title. Excludes the directory and the '.safetensors' file extension */\n  readonly simplified_file_name: string\n  /** Key for the model, used to uniquely identify the model. */\n  readonly key: string\n  /** Title / display name of the model, sometimes same as the name but not always */\n  title: string\n  /** Metadata: architecture ID for the model, such as 'stable-diffusion-xl-v1-base' */\n  architecture_id: string = ''\n  /** Metadata: author of the model */\n  author: string = ''\n  /** Metadata: resolution of the model, eg '1024x1024' */\n  resolution: string = ''\n  /** Metadata: description of the model */\n  description: string = ''\n  /** Metadata: usage hint for the model */\n  usage_hint: string = ''\n  /** Metadata: trigger phrase for the model */\n  trigger_phrase: string = ''\n  /** Metadata: tags list for the model */\n  tags: string[] = []\n  /** Metadata: image for the model */\n  image: string = ''\n  /** Whether the model metadata has been loaded from the server, used for `load()` */\n  has_loaded_metadata: boolean = false\n  /** If true, a metadata load request has been triggered, but may or may not yet have finished loading */\n  is_load_requested: boolean = false\n  /** A string full of auto-computed lowercase-only searchable text for this model */\n  searchable: string = ''\n\n  constructor(name: string, directory: string, pathIndex: number) {\n    this.path_index = pathIndex\n    this.file_name = name\n    this.normalized_file_name = name.replaceAll('\\\\', '/')\n    this.simplified_file_name = this.normalized_file_name.split('/').pop() ?? ''\n    if (this.simplified_file_name.endsWith('.safetensors')) {\n      this.simplified_file_name = this.simplified_file_name.slice(\n        0,\n        -'.safetensors'.length\n      )\n    }\n    this.title = this.simplified_file_name\n    this.directory = directory\n    this.key = `${directory}/${this.normalized_file_name}`\n    this.updateSearchable()\n  }\n\n  updateSearchable() {\n    this.searchable = [\n      this.file_name,\n      this.title,\n      this.author,\n      this.description,\n      this.trigger_phrase,\n      this.tags.join(', ')\n    ]\n      .join('\\n')\n      .toLowerCase()\n  }\n\n  /** Loads the model metadata from the server, filling in this object if data is available */\n  async load(): Promise<void> {\n    if (this.has_loaded_metadata || this.is_load_requested) {\n      return\n    }\n    // viewMetadata reads the safetensors header off local disk; on Cloud the\n    // model bytes live in object storage so there is nothing to read.\n    if (isCloud) {\n      return\n    }\n    this.is_load_requested = true\n    try {\n      const metadata = await api.viewMetadata(this.directory, this.file_name)\n      if (!metadata) {\n        return\n      }\n      this.title =\n        _findInMetadata(\n          metadata,\n          'modelspec.title',\n          'title',\n          'display_name',\n          'name'\n        ) || this.title\n      this.architecture_id =\n        _findInMetadata(metadata, 'modelspec.architecture', 'architecture') ||\n        ''\n      this.author =\n        _findInMetadata(metadata, 'modelspec.author', 'author') || ''\n      this.description =\n        _findInMetadata(metadata, 'modelspec.description', 'description') || ''\n      this.resolution =\n        _findInMetadata(metadata, 'modelspec.resolution', 'resolution') || ''\n      this.usage_hint =\n        _findInMetadata(metadata, 'modelspec.usage_hint', 'usage_hint') || ''\n      this.trigger_phrase =\n        _findInMetadata(\n          metadata,\n          'modelspec.trigger_phrase',\n          'trigger_phrase'\n        ) || ''\n      this.image =\n        _findInMetadata(\n          metadata,\n          'modelspec.thumbnail',\n          'thumbnail',\n          'image',\n          'icon'\n        ) || ''\n      const tagsCommaSeparated =\n        _findInMetadata(metadata, 'modelspec.tags', 'tags') || ''\n      this.tags = tagsCommaSeparated.split(',').map((tag) => tag.trim())\n      this.has_loaded_metadata = true\n      this.updateSearchable()\n    } catch (error) {\n      console.error('Error loading model metadata', this.file_name, this, error)\n    }\n  }\n}\n\nexport enum ResourceState {\n  Uninitialized,\n  Loading,\n  Loaded\n}\n\n/**\n * Resolves the preview image for a model: embedded metadata thumbnail when\n * loaded, otherwise the server-rendered `.webp` preview. The preview endpoint\n * reads a rendered thumbnail off local disk, which is unavailable on Cloud\n * (model bytes live in object storage), so Cloud resolves to no preview.\n */\nexport function getModelPreviewUrl(model: ComfyModelDef): string {\n  if (model.image) return model.image\n  if (isCloud) return ''\n  const extension = model.file_name.split('.').pop()\n  const filename = model.file_name.replace(`.${extension}`, '.webp')\n  const encodedFilename = encodeURIComponent(filename).replace(/%2F/g, '/')\n  return `/api/experiment/models/preview/${encodeURIComponent(model.directory)}/${model.path_index}/${encodedFilename}`\n}\n\n/**\n * FE-owned copy of core's default `supported_pt_extensions`, applied to\n * match-all folders (empty registered allowlist) so they don't surface\n * README/config noise. Accepted to go stale across core version bumps; the\n * whole surface is expected to be short-lived.\n */\nconst DEFAULT_MODEL_EXTENSIONS = [\n  '.ckpt',\n  '.pt',\n  '.pt2',\n  '.bin',\n  '.pth',\n  '.safetensors',\n  '.pkl',\n  '.sft'\n]\n\n/**\n * Real (`.`-prefixed) entries of a registered allowlist. Non-prefixed\n * entries (`'folder'`, `''`) are backend sentinels, not extensions — a list\n * containing only sentinels means match-all, the same as an empty list.\n */\nfunction realExtensions(extensions: string[]): string[] {\n  return extensions.filter((ext) => ext.startsWith('.'))\n}\n\n/**\n * Resolves a folder's display allowlist from its raw registered `extensions`\n * (`/experiment/models`): a list with real extensions is used verbatim; a\n * match-all list (empty, sentinel-only, or absent on older backends) takes\n * the FE default list, reproducing the legacy sidebar's global-set behavior\n * so nothing that used to be hidden starts showing.\n */\nexport function effectiveModelExtensions(\n  extensions: string[] | undefined\n): string[] {\n  if (extensions && realExtensions(extensions).length > 0) return extensions\n  return DEFAULT_MODEL_EXTENSIONS\n}\n\n/**\n * Whether a model file belongs in a folder given its display allowlist. A\n * list with no real extensions leaves the folder unfiltered.\n */\nexport function matchesModelExtension(\n  fileName: string,\n  extensions: string[]\n): boolean {\n  const real = realExtensions(extensions)\n  if (real.length === 0) return true\n  const lower = fileName.toLowerCase()\n  return real.some((ext) => lower.endsWith(ext.toLowerCase()))\n}\n\nexport class ModelFolder {\n  /** Models in this folder */\n  models: Record<string, ComfyModelDef> = {}\n  state: ResourceState = ResourceState.Uninitialized\n\n  constructor(\n    public directory: string,\n    private getModelsFunc: (folder: string) => Promise<ModelFile[]>,\n    public readonly extensions: string[] = []\n  ) {}\n\n  get key(): string {\n    return this.directory + '/'\n  }\n\n  /**\n   * Loads the models in this folder from the server\n   */\n  async load() {\n    if (this.state !== ResourceState.Uninitialized) {\n      return this\n    }\n    this.state = ResourceState.Loading\n    try {\n      const models = await this.getModelsFunc(this.directory)\n      for (const model of models) {\n        if (!matchesModelExtension(model.name, this.extensions)) continue\n        this.models[`${model.pathIndex}/${model.name}`] = new ComfyModelDef(\n          model.name,\n          this.directory,\n          model.pathIndex\n        )\n      }\n      this.state = ResourceState.Loaded\n      return this\n    } catch (error) {\n      // Reset instead of sticking at Loading so the guard above does not\n      // permanently block a retry after a transient failure.\n      this.state = ResourceState.Uninitialized\n      throw error\n    }\n  }\n}\n\n/** Model store handler, wraps individual per-folder model stores */\nexport const useModelStore = defineStore('models', () => {\n  const { flags } = useFeatureFlags()\n  const modelFolderNames = ref<string[]>([])\n  const modelFolderByName = ref<Record<string, ModelFolder>>({})\n  const modelFolders = computed<ModelFolder[]>(() =>\n    modelFolderNames.value.map(\n      (folderName) => modelFolderByName.value[folderName]\n    )\n  )\n  const models = computed<ComfyModelDef[]>(() =>\n    modelFolders.value.flatMap((folder) => Object.values(folder.models))\n  )\n  /**\n   * Folders worth showing in the sidebar. Asset mode hides folders that\n   * loaded empty — the registry lists every registered folder type, most of\n   * which have no models on a given install; they reappear live when a scan\n   * discovers a first model. The legacy path keeps its historical\n   * all-registered-folders view.\n   */\n  const visibleModelFolders = computed<ModelFolder[]>(() =>\n    flags.assetsEnabled\n      ? modelFolders.value.filter(\n          (folder) =>\n            folder.state !== ResourceState.Loaded ||\n            Object.keys(folder.models).length > 0\n        )\n      : modelFolders.value\n  )\n\n  function createGetModelsFunc(): (folder: string) => Promise<ModelFile[]> {\n    return flags.assetsEnabled\n      ? (folder) => assetService.getAssetModels(folder)\n      : (folder) => api.getModels(folder)\n  }\n\n  const modelSource = computed(() =>\n    !flags.assetsEnabled\n      ? 'legacy-api'\n      : flags.supportsModelTypeTags\n        ? 'asset-model-type-tags'\n        : 'asset-legacy-tags'\n  )\n  let committedSource = modelSource.value\n  let modelFoldersRequestId = 0\n\n  /**\n   * Whether anything has consumed this store's model data (sidebar loads,\n   * folder refreshes). The boot-registered scan subscription uses this to\n   * skip background reloads nothing is displaying.\n   */\n  let modelDataConsumed = false\n\n  interface PreparedModelFolders {\n    requestId: number\n    source: typeof modelSource.value\n    names: string[]\n    folders: Record<string, ModelFolder>\n  }\n\n  /**\n   * Fetches the folder structure and builds a fresh, uncommitted folder map.\n   *\n   * The folder list (and its registration order) always comes from\n   * `/experiment/models`, the source of truth for which model folders exist;\n   * only the per-folder contents differ between the asset API and legacy paths.\n   * Concurrent loads (manual refresh racing the scan-complete reload) commit\n   * only the newest request, so returns null when superseded — a slow stale\n   * response cannot overwrite a fresher folder structure.\n   */\n  async function prepareModelFolders(): Promise<PreparedModelFolders | null> {\n    const requestId = ++modelFoldersRequestId\n    const resData = await api.getModelFolders()\n    if (requestId !== modelFoldersRequestId) return null\n    const getModelsFunc = createGetModelsFunc()\n    const folders = reactive<Record<string, ModelFolder>>({})\n    for (const folder of resData) {\n      folders[folder.name] = new ModelFolder(\n        folder.name,\n        getModelsFunc,\n        // Display filtering applies to the asset walk only; the legacy\n        // listing keeps its historical server-side (global-set) filtering.\n        flags.assetsEnabled ? effectiveModelExtensions(folder.extensions) : []\n      )\n    }\n    return {\n      requestId,\n      source: modelSource.value,\n      names: resData.map((folder) => folder.name),\n      folders\n    }\n  }\n\n  function commitModelFolders({\n    names,\n    folders,\n    source\n  }: PreparedModelFolders): void {\n    modelFolderNames.value = names\n    modelFolderByName.value = folders\n    committedSource = source\n  }\n\n  /** Loads the model folder structure from the server; false when superseded. */\n  async function loadModelFolders(): Promise<boolean> {\n    const prepared = await prepareModelFolders()\n    if (!prepared) return false\n    while (prepared.requestId === modelFoldersRequestId) {\n      const pendingFolders = modelFolders.value\n        .filter(\n          (folder) =>\n            folder.state !== ResourceState.Uninitialized &&\n            folder.directory in prepared.folders\n        )\n        .map((folder) => prepared.folders[folder.directory])\n        .filter((folder) => folder.state === ResourceState.Uninitialized)\n      if (pendingFolders.length === 0) {\n        commitModelFolders(prepared)\n        return true\n      }\n      if (prepared.source !== committedSource) commitModelFolders(prepared)\n      await Promise.all(pendingFolders.map((folder) => folder.load()))\n    }\n    return false\n  }\n\n  async function getLoadedModelFolder(\n    folderName: string\n  ): Promise<ModelFolder | null> {\n    modelDataConsumed = true\n    const folder = Object.hasOwn(modelFolderByName.value, folderName)\n      ? modelFolderByName.value[folderName]\n      : undefined\n    return folder ? await folder.load() : null\n  }\n\n  /**\n   * Loads all model folders' contents from the server. Loads the folder\n   * structure first when it has not arrived yet — eager loading can run\n   * before app boot's own loadModelFolders call resolves, and iterating an\n   * empty folder list would silently load nothing.\n   */\n  async function loadModels() {\n    modelDataConsumed = true\n    // A load superseded by a newer concurrent one commits nothing, which\n    // would leave the folder list empty and silently load no models; retry\n    // until a load of ours commits (even a genuinely empty result) or a\n    // concurrent one has populated the list. Bounded as a safety net.\n    for (let attempt = 0; attempt < 3; attempt++) {\n      if (modelFolderNames.value.length > 0) break\n      if (await loadModelFolders()) break\n    }\n    return Promise.all(modelFolders.value.map((folder) => folder.load()))\n  }\n\n  /**\n   * Discards the cache for a single folder and re-loads its contents.\n   * Use when on-disk contents of that folder have changed (e.g. after upload).\n   * Falls back to refreshing the whole library when the folder is unknown so\n   * a newly-introduced folder type is picked up without dropping other\n   * folders' loaded contents.\n   */\n  const folderRefreshIds = new Map<string, number>()\n\n  async function refreshModelFolder(folderName: string) {\n    modelDataConsumed = true\n    assetService.invalidateModelBuckets()\n    if (!(folderName in modelFolderByName.value)) {\n      await refresh()\n      return\n    }\n    const requestId = modelFoldersRequestId\n    const refreshId = (folderRefreshIds.get(folderName) ?? 0) + 1\n    folderRefreshIds.set(folderName, refreshId)\n    const priorFolder = modelFolderByName.value[folderName]\n    const folder = new ModelFolder(\n      folderName,\n      createGetModelsFunc(),\n      priorFolder.extensions\n    )\n    await folder.load()\n    // A full reload may have rebuilt the folder structure while this folder\n    // refreshed, and a newer refresh of the same folder may have already\n    // committed; committing then would resurrect a stale folder object. The\n    // identity check also covers a rebuild whose folder load started before\n    // this refresh snapshotted the request id.\n    if (requestId !== modelFoldersRequestId) return\n    if (folderRefreshIds.get(folderName) !== refreshId) return\n    if (modelFolderByName.value[folderName] !== priorFolder) return\n    modelFolderByName.value[folderName] = folder\n  }\n\n  async function reloadModels(): Promise<boolean> {\n    assetService.invalidateModelBuckets()\n    return loadModelFolders()\n  }\n\n  /**\n   * Asks the backend to rescan the model roots so files added on disk since\n   * startup become assets. Skipped on Cloud (models are ingested via uploads,\n   * not scanned from disk) and on the legacy listing path (which reads the\n   * filesystem live on every request).\n   */\n  async function requestModelScan() {\n    if (isCloud) return\n    if (!flags.assetsEnabled) return\n    try {\n      await assetService.seedModelAssets()\n    } catch (error) {\n      console.warn('Unable to start model asset scan', error)\n    }\n  }\n\n  /**\n   * Manual refresh (\"r\" key, sidebar refresh button): kicks off a backend\n   * rescan and immediately re-loads the currently known server state; the\n   * scan completion subscription below re-loads again with whatever the\n   * scan discovered. The scan is deliberately not awaited so it runs\n   * concurrently with the reload. False means a newer concurrent load\n   * superseded this one, not a failure.\n   */\n  async function refresh(): Promise<boolean> {\n    modelDataConsumed = true\n    void requestModelScan()\n    return await reloadModels()\n  }\n\n  /**\n   * Scan completions and capability changes can land in bursts; coalesce\n   * them into one trailing reload instead of one full library walk per event.\n   */\n  const MODEL_RELOAD_DEBOUNCE_MS = 500\n\n  const scheduleModelReload = debounce(async () => {\n    try {\n      await reloadModels()\n    } catch (error) {\n      console.error('Failed to reload the model library', error)\n    }\n  }, MODEL_RELOAD_DEBOUNCE_MS)\n\n  const unsubscribeModelsScanned = assetService.onModelsScanned(() => {\n    // A scan changes bucket contents even when no UI has read this store\n    // yet; drop the cache so the eventual first read walks fresh data, but\n    // skip the reload nothing is displaying.\n    assetService.invalidateModelBuckets()\n    if (!modelDataConsumed) return\n    scheduleModelReload()\n  })\n  onScopeDispose(() => {\n    scheduleModelReload.cancel()\n    unsubscribeModelsScanned()\n  })\n\n  /**\n   * The WS `feature_flags` handshake can land after createGetModelsFunc()\n   * already captured its data-source choice at store-init time, so a flag\n   * flip after boot must force a reload to switch the sidebar's source.\n   */\n  watch([() => flags.assetsEnabled, () => flags.supportsModelTypeTags], () =>\n    scheduleModelReload()\n  )\n\n  return {\n    models,\n    modelFolders,\n    visibleModelFolders,\n    loadModelFolders,\n    loadModels,\n    getLoadedModelFolder,\n    refreshModelFolder,\n    refresh\n  }\n})\n","import type { ModelFile } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { resolveTemplateModelAvailability } from '@/platform/workflow/templates/utils/templateModelAvailability'\nimport { ResourceState, useModelStore } from '@/stores/modelStore'\n\nexport function useTemplateModelAvailability() {\n  const modelStore = useModelStore()\n\n  async function resolveAvailability(models: readonly ModelFile[]) {\n    const directories = [...new Set(models.map((model) => model.directory))]\n    let isComplete = directories.length === 0\n\n    try {\n      if (directories.length > 0 && modelStore.modelFolders.length === 0) {\n        await modelStore.loadModelFolders()\n      }\n\n      const folderResults = await Promise.allSettled(\n        directories.map((directory) =>\n          modelStore.getLoadedModelFolder(directory)\n        )\n      )\n      const failure = folderResults.find(\n        (result): result is PromiseRejectedResult =>\n          result.status === 'rejected'\n      )\n      if (failure) {\n        reportError(failure.reason, {\n          surface: 'graph',\n          errorType: 'workflow_template_model_inventory_failed',\n          level: 'warning'\n        })\n      }\n      isComplete = folderResults.every(\n        (result) =>\n          result.status === 'fulfilled' &&\n          result.value?.state === ResourceState.Loaded\n      )\n    } catch (error) {\n      reportError(error, {\n        surface: 'graph',\n        errorType: 'workflow_template_model_inventory_failed',\n        level: 'warning'\n      })\n    }\n\n    return resolveTemplateModelAvailability(models, {\n      isComplete,\n      models: modelStore.models.map((model) => ({\n        directory: model.directory,\n        name: model.normalized_file_name\n      }))\n    })\n  }\n\n  return { resolveAvailability }\n}\n","import type { ComfyTemplateInputDownloadProgress } from '@comfyorg/comfyui-desktop-bridge-types'\n\ninterface TemplateInputDownloadGraphSyncDependencies {\n  getReferencedInputNames: () => ReadonlySet<string>\n  refreshGraphBindings: (completedInputNames: string[]) => Promise<void>\n  reportError: (error: unknown) => void\n}\n\nfunction createTemplateInputDownloadGraphSync({\n  getReferencedInputNames,\n  refreshGraphBindings,\n  reportError\n}: TemplateInputDownloadGraphSyncDependencies) {\n  const completedInputNames = new Set<string>()\n  let disposed = false\n  /**\n   * Read through a call rather than the binding. The early return in\n   * `syncCurrentGraph` narrows `disposed` to `false` for the rest of that\n   * function, but the loop below resumes after an await, by which point\n   * `dispose` may have flipped it.\n   */\n  const isDisposed = () => disposed\n  let scheduled = false\n  let rerunRequested = false\n  let inFlight: Promise<void> | null = null\n\n  async function flushCurrentGraph() {\n    const referenced = getReferencedInputNames()\n    const matched = [...completedInputNames].filter((filename) =>\n      referenced.has(filename)\n    )\n    if (!matched.length) return\n\n    try {\n      await refreshGraphBindings(matched)\n    } catch (error) {\n      // Keep the names: the files are on disk, and the next sync - another\n      // completion or another template opening - is the only thing that can\n      // rebind them.\n      reportError(error)\n      return\n    }\n\n    const currentReferences = getReferencedInputNames()\n    for (const filename of matched) {\n      if (currentReferences.has(filename)) completedInputNames.delete(filename)\n    }\n  }\n\n  function scheduleSync() {\n    if (disposed || scheduled) return\n    scheduled = true\n    queueMicrotask(() => {\n      scheduled = false\n      if (!disposed) void syncCurrentGraph()\n    })\n  }\n\n  function syncCurrentGraph(): Promise<void> {\n    if (disposed) return Promise.resolve()\n    if (inFlight) {\n      rerunRequested = true\n      return inFlight\n    }\n\n    // Reruns stay inside this awaited block so callers do not continue before\n    // every requested refresh attempt has settled.\n    const trackedRun = (async () => {\n      await flushCurrentGraph()\n      while (rerunRequested && !isDisposed()) {\n        rerunRequested = false\n        await flushCurrentGraph()\n      }\n    })().finally(() => {\n      if (inFlight === trackedRun) inFlight = null\n    })\n    inFlight = trackedRun\n    return trackedRun\n  }\n\n  function handleProgress(progress: ComfyTemplateInputDownloadProgress) {\n    if (progress.status !== 'completed') return\n    completedInputNames.add(progress.filename)\n    scheduleSync()\n  }\n\n  function dispose() {\n    disposed = true\n  }\n\n  return { handleProgress, syncCurrentGraph, dispose }\n}\n\ntype TemplateInputDownloadGraphSync = ReturnType<\n  typeof createTemplateInputDownloadGraphSync\n>\n\nlet activeGraphSync: TemplateInputDownloadGraphSync | null = null\n\nexport function startTemplateInputDownloadGraphSync(\n  dependencies: TemplateInputDownloadGraphSyncDependencies\n) {\n  activeGraphSync?.dispose()\n  const graphSync = createTemplateInputDownloadGraphSync(dependencies)\n  activeGraphSync = graphSync\n\n  return {\n    handleProgress: graphSync.handleProgress,\n    syncCurrentGraph: graphSync.syncCurrentGraph,\n    dispose() {\n      graphSync.dispose()\n      if (activeGraphSync === graphSync) activeGraphSync = null\n    }\n  }\n}\n\nexport function syncCompletedTemplateInputsWithCurrentGraph(): Promise<void> {\n  return activeGraphSync?.syncCurrentGraph() ?? Promise.resolve()\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { reportError } from '@/platform/telemetry/reportError'\n\nconst DISMISSED_SETTING = 'Comfy.PartnerNodesEducation.Dismissed'\n\n/**\n * Requests the partner-nodes education card after a paid template loads,\n * keyed to the workflow that triggered it so the card retires when a different\n * workflow becomes active. Shows on every paid-template load until the user\n * closes it, then never again.\n */\nexport const usePartnerNodesEducationStore = defineStore(\n  'partnerNodesEducation',\n  () => {\n    const settingStore = useSettingStore()\n    const requestedForWorkflowKey = ref<string | undefined>(undefined)\n\n    const isCardRequested = computed(\n      () => requestedForWorkflowKey.value !== undefined\n    )\n\n    const requestCard = (workflowKey: string) => {\n      if (settingStore.get(DISMISSED_SETTING)) return\n      requestedForWorkflowKey.value = workflowKey\n    }\n\n    const retireCard = () => {\n      requestedForWorkflowKey.value = undefined\n    }\n\n    const dismissCard = () => {\n      retireCard()\n      settingStore.set(DISMISSED_SETTING, true).catch((error: unknown) =>\n        reportError(error, {\n          errorType: 'partner_nodes_education_dismiss_save_failed',\n          surface: 'platform',\n          level: 'warning'\n        })\n      )\n    }\n\n    return {\n      requestedForWorkflowKey,\n      isCardRequested,\n      requestCard,\n      retireCard,\n      dismissCard\n    }\n  }\n)\n","import { zUploadImageResponse } from '@comfyorg/ingest-types/zod'\nimport { z } from 'zod'\n\nimport type {\n  ComfyNode,\n  ComfyWorkflowJSON\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { isWidgetValue } from '@/lib/litegraph/src/types/widgets'\nimport type { TWidgetValue } from '@/lib/litegraph/src/types/widgets'\nimport { api } from '@/scripts/api'\n\nimport { zTemplateInput } from '../schemas/templateSchema'\n\nconst INPUT_BASE =\n  'https://raw.githubusercontent.com/Comfy-Org/workflow_templates/'\nconst INPUT_WIDGETS: Readonly<Record<string, string>> = {\n  LoadImage: 'image',\n  LoadImageMask: 'image',\n  LoadVideo: 'file',\n  LoadAudio: 'audio'\n}\nconst zWidgetValue = z.custom<TWidgetValue>(isWidgetValue)\nconst zValues = z.union([\n  z.array(zWidgetValue),\n  z.record(z.string(), zWidgetValue)\n])\nconst zNamedValues = z.record(z.string(), zWidgetValue)\n\ntype PreparationResult = {\n  workflow: ComfyWorkflowJSON\n  uploadedCount: number\n  errors: unknown[]\n}\n\nfunction getInputBinding(node: ComfyNode, restoreNamed: boolean) {\n  const widget = INPUT_WIDGETS[node.type]\n  if (!widget) return\n  const values = zValues.parse(node.widgets_values ?? [])\n  const named = zNamedValues.optional().parse(node.widgets_values_named)\n  const file =\n    restoreNamed && named\n      ? named[widget]\n      : Array.isArray(values)\n        ? values[0]\n        : values[widget]\n  if (typeof file !== 'string') return\n  return { node, widget, file, values, named }\n}\n\nfunction isSampleFilename(file: string): boolean {\n  return file === file.trim() && !file.includes('..') && !/[\\\\/:%?#]/.test(file)\n}\n\nasync function uploadTemplateInput(\n  file: string,\n  sourceRevision: string,\n  signal: AbortSignal\n): Promise<{ ok: true; path: string } | { ok: false; error: Error }> {\n  const requestSignal = AbortSignal.any([signal, AbortSignal.timeout(120_000)])\n  let operation = 'download'\n  function failure(cause: unknown): { ok: false; error: Error } {\n    return {\n      ok: false,\n      error: new Error(\n        `Template sample ${operation} failed: ${file} (${sourceRevision})`,\n        { cause }\n      )\n    }\n  }\n\n  try {\n    const response = await fetch(\n      `${INPUT_BASE}${sourceRevision}/input/${encodeURIComponent(file)}`,\n      { signal: requestSignal }\n    )\n    if (!response.ok) return failure(new Error(`HTTP ${response.status}`))\n    const bytes = await response.arrayBuffer()\n    requestSignal.throwIfAborted()\n    const body = new FormData()\n    body.append('image', new File([bytes], file))\n    body.append('type', 'input')\n    operation = 'upload'\n    const uploaded = await api.fetchApi('/upload/image', {\n      method: 'POST',\n      body,\n      signal: requestSignal\n    })\n    if (!uploaded.ok) return failure(new Error(`HTTP ${uploaded.status}`))\n    const result = zUploadImageResponse.parse(await uploaded.json())\n    if (!result.name)\n      return failure(new Error('No saved filename in upload response'))\n    return {\n      ok: true,\n      path: result.subfolder\n        ? `${result.subfolder}/${result.name}`\n        : result.name\n    }\n  } catch (cause) {\n    signal.throwIfAborted()\n    return failure(cause)\n  }\n}\n\nfunction getTemplateInputFiles(\n  inputs: unknown,\n  bindings: NonNullable<ReturnType<typeof getInputBinding>>[]\n) {\n  const files = new Map<string, string>()\n  const errors: unknown[] = []\n  const entries = z.array(z.unknown()).safeParse(inputs)\n  if (!entries.success) {\n    errors.push(entries.error)\n    return { files, errors }\n  }\n  for (const entry of entries.data) {\n    const parsed = zTemplateInput.safeParse(entry)\n    if (!parsed.success) {\n      errors.push(parsed.error)\n      continue\n    }\n    const input = parsed.data\n    if (!input.sourceRevision) continue\n    if (\n      !bindings.some(\n        ({ node, file }) =>\n          node.id === input.nodeId &&\n          node.type === input.nodeType &&\n          file === input.file\n      )\n    )\n      continue\n    if (!isSampleFilename(input.file)) {\n      errors.push(\n        new Error(`Unsupported template input filename: ${input.file}`)\n      )\n      continue\n    }\n    files.set(input.file, input.sourceRevision)\n  }\n  return { files, errors }\n}\n\nexport async function prepareTemplateInputs(\n  workflow: ComfyWorkflowJSON,\n  inputs: unknown,\n  signal: AbortSignal,\n  restoreNamed: boolean,\n  onStart?: () => void\n): Promise<PreparationResult> {\n  const errors: unknown[] = []\n  const prepared = structuredClone(workflow)\n  const bindings = prepared.nodes.flatMap((node) => {\n    try {\n      const binding = getInputBinding(node, restoreNamed)\n      return binding ? [binding] : []\n    } catch (error) {\n      errors.push(error)\n      return []\n    }\n  })\n  const { files, errors: declarationErrors } = getTemplateInputFiles(\n    inputs,\n    bindings\n  )\n  errors.push(...declarationErrors)\n  signal.throwIfAborted()\n  if (!files.size) return { workflow, uploadedCount: 0, errors }\n  onStart?.()\n  let uploadedCount = 0\n  for (const [file, sourceRevision] of files) {\n    signal.throwIfAborted()\n    try {\n      const uploaded = await uploadTemplateInput(file, sourceRevision, signal)\n      signal.throwIfAborted()\n      if (!uploaded.ok) {\n        errors.push(uploaded.error)\n        continue\n      }\n      const path = uploaded.path\n      for (const { node, widget, values, named } of bindings.filter(\n        (binding) => binding.file === file\n      )) {\n        node.widgets_values = Array.isArray(values)\n          ? [path, ...values.slice(1)]\n          : { ...values, [widget]: path }\n        if (named) node.widgets_values_named = { ...named, [widget]: path }\n      }\n      uploadedCount++\n    } catch (error) {\n      signal.throwIfAborted()\n      errors.push(error)\n    }\n  }\n  return {\n    workflow: uploadedCount > 0 ? prepared : workflow,\n    uploadedCount,\n    errors\n  }\n}\n","import { computed, onScopeDispose, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { createToastId } from '@/types/toastId'\nimport { isCloud, isDesktop } from '@/platform/distribution/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useSurveyFeatureTracking } from '@/platform/surveys/useSurveyFeatureTracking'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type { TemplateInput } from '@/platform/workflow/templates/schemas/templateSchema'\nimport { syncCompletedTemplateInputsWithCurrentGraph } from '@/platform/workflow/templates/composables/useTemplateInputDownloadGraphSync'\nimport { useWorkflowTemplatesStore } from '@/platform/workflow/templates/repositories/workflowTemplatesStore'\nimport { usePartnerNodesEducationStore } from '@/platform/workflow/templates/stores/partnerNodesEducationStore'\nimport type {\n  TemplateGroup,\n  TemplateInfo,\n  WorkflowTemplates\n} from '@/platform/workflow/templates/types/template'\nimport {\n  resolveTemplateInputAssets,\n  startMissingTemplateInputDownloads\n} from '@/platform/workflow/templates/utils/templateInputAssets'\nimport type {\n  ComfyWorkflowJSON,\n  LegacyLoadableWorkflow\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport {\n  validateComfyWorkflow,\n  zLegacyLoadableWorkflow\n} from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { api } from '@/scripts/api'\nimport { app } from '@/scripts/app'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nimport { prepareTemplateInputs } from '../services/templateInputService'\n\ntype TemplateLoadResult = 'loaded' | 'graph-failed' | 'not-started'\n\nexport type PreparedWorkflowTemplate = {\n  id: string\n  sourceModule: string\n  workflowName: string\n  controller: AbortController\n  data: {\n    json: ComfyWorkflowJSON | LegacyLoadableWorkflow\n    template:\n      | ReturnType<\n          typeof useWorkflowTemplatesStore\n        >['enhancedTemplates'][number]\n      | undefined\n  }\n}\n\nfunction updateTemplateEducation(\n  isPartnerNode: boolean | undefined,\n  loadedWorkflow: Awaited<ReturnType<typeof app.loadGraphData>>\n) {\n  const educationStore = usePartnerNodesEducationStore()\n  if (isPartnerNode && typeof loadedWorkflow === 'object') {\n    educationStore.requestCard(loadedWorkflow.key)\n  } else {\n    educationStore.retireCard()\n  }\n}\n\nexport function useTemplateWorkflows() {\n  const { t } = useI18n()\n  const workflowTemplatesStore = useWorkflowTemplatesStore()\n  const dialogStore = useDialogStore()\n  const { trackFeatureUsed } = useSurveyFeatureTracking('example-workflows')\n\n  // State\n  const selectedTemplate = ref<WorkflowTemplates | null>(null)\n  let ownedLoadController: AbortController | undefined\n  const loadingTemplateId = computed(\n    () => workflowTemplatesStore.loadingTemplateId\n  )\n  onScopeDispose(() => {\n    workflowTemplatesStore.cancelTemplateLoad(ownedLoadController)\n  })\n\n  // Computed\n  const isTemplatesLoaded = computed(() => workflowTemplatesStore.isLoaded)\n  const allTemplateGroups = computed<TemplateGroup[]>(\n    () => workflowTemplatesStore.groupedTemplates\n  )\n\n  /**\n   * Loads all template workflows from the API\n   */\n  const loadTemplates = async () => {\n    if (!workflowTemplatesStore.isLoaded) {\n      await workflowTemplatesStore.loadWorkflowTemplates()\n    }\n    return workflowTemplatesStore.isLoaded\n  }\n\n  /**\n   * Selects the first template category as default\n   */\n  const selectFirstTemplateCategory = () => {\n    if (allTemplateGroups.value.length > 0) {\n      const firstCategory = allTemplateGroups.value[0].modules[0]\n      selectTemplateCategory(firstCategory)\n    }\n  }\n\n  /**\n   * Selects a template category\n   */\n  const selectTemplateCategory = (category: WorkflowTemplates | null) => {\n    selectedTemplate.value = category\n    return category !== null\n  }\n\n  /**\n   * Gets template thumbnail URL\n   */\n  const getTemplateThumbnailUrl = (\n    template: TemplateInfo,\n    sourceModule: string,\n    index = '1'\n  ) => {\n    const basePath =\n      sourceModule === 'default'\n        ? api.fileURL(`/templates/${template.name}`)\n        : api.apiURL(`/workflow_templates/${sourceModule}/${template.name}`)\n\n    const indexSuffix = sourceModule === 'default' && index ? `-${index}` : ''\n    return `${basePath}${indexSuffix}.${template.mediaSubtype}`\n  }\n\n  /**\n   * Gets formatted template title\n   */\n  const getTemplateTitle = (template: TemplateInfo, sourceModule: string) => {\n    const fallback = template.title ?? template.name\n    return sourceModule === 'default'\n      ? (template.localizedTitle ?? fallback)\n      : fallback\n  }\n\n  /**\n   * Gets formatted template description\n   */\n  const getTemplateDescription = (template: TemplateInfo) => {\n    return (template.localizedDescription || template.description)\n      .replace(/[-_]/g, ' ')\n      .trim()\n  }\n\n  function resolveTemplateSource(id: string, sourceModule: string) {\n    if (sourceModule !== 'all') return sourceModule\n\n    const group = allTemplateGroups.value.find(\n      (group) =>\n        group.label ===\n        t('templateWorkflows.category.ComfyUI Examples', 'ComfyUI Examples')\n    )\n    const category = group?.modules.find(\n      (module) => module.moduleName === 'all'\n    )\n    const template = category?.templates.find(\n      (template) => template.name === id\n    )\n    return template?.sourceModule\n  }\n\n  function startTemplateInputDownloads(id: string, sourceModule: string) {\n    if (!isDesktop || sourceModule !== 'default') return\n\n    void resolveTemplateInputAssets(id, () => window.__comfyDesktop2).then(\n      (assets) => {\n        startMissingTemplateInputDownloads(id, assets, {\n          getBridge: () => window.__comfyDesktop2,\n          reportError: (error) => {\n            reportError(error, {\n              surface: 'graph',\n              errorType: 'workflow_template_input_download_failed',\n              level: 'warning'\n            })\n          }\n        })\n      }\n    )\n  }\n\n  function releasePreparedLoad(controller: AbortController) {\n    workflowTemplatesStore.finishTemplateLoad(controller)\n    if (ownedLoadController === controller) ownedLoadController = undefined\n  }\n\n  function showTemplateError(detail: string) {\n    useToast().error(t('g.error'), { description: detail })\n  }\n\n  function reportTemplateError(error: unknown) {\n    reportError(error, {\n      surface: 'graph',\n      errorType: 'error_loading_template'\n    })\n    showTemplateError(t('templateWorkflows.error.loading'))\n  }\n\n  async function withPreparedSampleInputs(\n    workflow: ComfyWorkflowJSON,\n    inputs: TemplateInput[],\n    signal: AbortSignal\n  ) {\n    const toast = useToast()\n    const progressToastId = createToastId()\n    let preparedJson: ComfyWorkflowJSON | LegacyLoadableWorkflow = workflow\n    const errors: unknown[] = []\n    try {\n      const result = await prepareTemplateInputs(\n        workflow,\n        inputs,\n        signal,\n        useSettingStore().get('Comfy.Workflow.NamedValuesRestore'),\n        () => {\n          toast.loading(t('templateWorkflows.preparingMedia'), {\n            id: progressToastId\n          })\n        }\n      )\n      errors.push(...result.errors)\n      preparedJson = result.workflow\n      if (result.uploadedCount > 0) {\n        await useAssetsStore().inputAssets.invalidate()\n        await app.reloadNodeDefs()\n      }\n      signal.throwIfAborted()\n    } catch (error) {\n      signal.throwIfAborted()\n      errors.push(error)\n    } finally {\n      toast.dismiss(progressToastId)\n    }\n    if (errors.length) {\n      reportError(\n        new AggregateError(errors, 'Template sample preparation failed'),\n        {\n          surface: 'graph',\n          errorType: 'error_loading_template_media'\n        }\n      )\n      toast.warning(t('g.warning'), {\n        description: t('templateWorkflows.error.preparingMedia'),\n        duration: 8000\n      })\n    }\n    return preparedJson\n  }\n\n  async function loadTemplateData(\n    id: string,\n    sourceModule: string,\n    signal: AbortSignal\n  ) {\n    const fetched = await fetchTemplateJson(id, sourceModule, signal)\n    signal.throwIfAborted()\n    if (!fetched) return null\n    const { json } = fetched\n\n    const template = workflowTemplatesStore.enhancedTemplates.find(\n      (template) =>\n        template.name === id && template.sourceModule === sourceModule\n    )\n    const inputs = template?.io?.inputs\n    if (isCloud || sourceModule !== 'default' || !inputs?.length)\n      return { json, template }\n\n    return {\n      json: fetched.strict\n        ? await withPreparedSampleInputs(fetched.json, inputs, signal)\n        : json,\n      template\n    }\n  }\n\n  async function loadTemplateGraph(\n    {\n      json,\n      template\n    }: NonNullable<Awaited<ReturnType<typeof loadTemplateData>>>,\n    workflowName: string,\n    sourceModule: string\n  ): Promise<TemplateLoadResult> {\n    try {\n      const loadedWorkflow = await app.loadGraphData(\n        json as ComfyWorkflowJSON,\n        true,\n        true,\n        workflowName,\n        { openSource: 'template' }\n      )\n      if (loadedWorkflow === false) return 'graph-failed'\n      if (loadedWorkflow === undefined) return 'not-started'\n\n      updateTemplateEducation(template?.isPartnerNode, loadedWorkflow)\n      await syncCompletedTemplateInputsWithCurrentGraph()\n      if (sourceModule === 'default') trackFeatureUsed()\n      return 'loaded'\n    } catch (error) {\n      reportTemplateError(error)\n      return 'graph-failed'\n    }\n  }\n\n  async function resolveTemplatePayload(\n    id: string,\n    sourceModule: string,\n    signal: AbortSignal\n  ) {\n    const source = resolveTemplateSource(id, sourceModule)\n    if (!source) {\n      showTemplateError(\n        t('templateWorkflows.error.templateNotFound', { templateName: id })\n      )\n      return null\n    }\n    const data = await loadTemplateData(id, source, signal)\n    signal.throwIfAborted()\n    if (!data) {\n      showTemplateError(t('templateWorkflows.error.loading'))\n      return null\n    }\n    return { source, data }\n  }\n\n  async function prepareWorkflowTemplate(\n    id: string,\n    sourceModule: string\n  ): Promise<PreparedWorkflowTemplate | null> {\n    if (!isTemplatesLoaded.value) {\n      showTemplateError(t('templateWorkflows.error.loading'))\n      return null\n    }\n    const controller = workflowTemplatesStore.startTemplateLoad(id)\n    if (!controller) return null\n    ownedLoadController = controller\n    try {\n      const payload = await resolveTemplatePayload(\n        id,\n        sourceModule,\n        controller.signal\n      )\n      if (!payload) {\n        releasePreparedLoad(controller)\n        return null\n      }\n      return {\n        id,\n        sourceModule: payload.source,\n        workflowName:\n          payload.source === 'default'\n            ? t(`templateWorkflows.template.${id}`, id)\n            : id,\n        controller,\n        data: payload.data\n      }\n    } catch (error) {\n      if (!controller.signal.aborted) reportTemplateError(error)\n      releasePreparedLoad(controller)\n      return null\n    }\n  }\n\n  async function openPreparedWorkflowTemplate(\n    prepared: PreparedWorkflowTemplate\n  ): Promise<TemplateLoadResult> {\n    const { id, sourceModule, workflowName, controller, data } = prepared\n    try {\n      if (!workflowTemplatesStore.startTemplateGraphLoad(controller))\n        return 'not-started'\n\n      useTelemetry()?.trackTemplate({\n        workflow_name: id,\n        template_source: sourceModule\n      })\n\n      dialogStore.closeDialog()\n      startTemplateInputDownloads(id, sourceModule)\n      return await loadTemplateGraph(data, workflowName, sourceModule)\n    } catch (error) {\n      if (!controller.signal.aborted) reportTemplateError(error)\n      return 'not-started'\n    } finally {\n      releasePreparedLoad(controller)\n    }\n  }\n\n  function discardPreparedWorkflowTemplate(\n    prepared: PreparedWorkflowTemplate | null\n  ) {\n    if (!prepared) return\n    workflowTemplatesStore.cancelTemplateLoad(prepared.controller)\n    if (ownedLoadController === prepared.controller)\n      ownedLoadController = undefined\n  }\n\n  async function loadWorkflowTemplate(\n    id: string,\n    sourceModule: string\n  ): Promise<TemplateLoadResult> {\n    const prepared = await prepareWorkflowTemplate(id, sourceModule)\n    if (!prepared) return 'not-started'\n    return openPreparedWorkflowTemplate(prepared)\n  }\n\n  /**\n   * Fetches template JSON from the appropriate endpoint\n   */\n  /**\n   * The payload plus whether strict validation accepted it. Sample-input\n   * preparation needs a strictly valid workflow, and carrying the answer out\n   * of here keeps it from parsing the same payload a second time - which also\n   * reported the schema warning twice for a legacy template.\n   */\n  type FetchedTemplate =\n    | { strict: true; json: ComfyWorkflowJSON }\n    | { strict: false; json: LegacyLoadableWorkflow }\n\n  async function fetchTemplateJson(\n    id: string,\n    sourceModule: string,\n    signal: AbortSignal\n  ): Promise<FetchedTemplate | null> {\n    // Default templates provided by frontend are served on this separate endpoint\n    const url =\n      sourceModule === 'default'\n        ? api.fileURL(`/templates/${id}.json`)\n        : api.apiURL(`/workflow_templates/${sourceModule}/${id}.json`)\n\n    const response = await fetch(url, { signal })\n    if (!response.ok) {\n      reportError(`Failed to fetch workflow template ${id}`, {\n        surface: 'graph',\n        errorType: 'error_fetching_workflow_template'\n      })\n      return null\n    }\n\n    const json: unknown = await response.json()\n    let schemaMismatch: string | undefined\n    const validated = await validateComfyWorkflow(json, (detail) => {\n      schemaMismatch = detail\n    })\n    if (validated) return { strict: true, json: validated }\n\n    const legacy = zLegacyLoadableWorkflow.safeParse(json)\n    if (!legacy.success) {\n      reportError(`Workflow template ${id} is not a loadable workflow`, {\n        surface: 'graph',\n        errorType: 'error_validating_workflow_template'\n      })\n      return null\n    }\n    if (schemaMismatch) {\n      reportError(new Error(schemaMismatch), {\n        surface: 'graph',\n        errorType: 'error_validating_workflow_template_schema',\n        level: 'warning'\n      })\n    }\n    return { strict: false, json: legacy.data }\n  }\n\n  return {\n    // State\n    selectedTemplate,\n    loadingTemplateId,\n\n    // Computed\n    isTemplatesLoaded,\n    allTemplateGroups,\n\n    // Methods\n    loadTemplates,\n    selectFirstTemplateCategory,\n    selectTemplateCategory,\n    getTemplateThumbnailUrl,\n    getTemplateTitle,\n    getTemplateDescription,\n    prepareWorkflowTemplate,\n    openPreparedWorkflowTemplate,\n    discardPreparedWorkflowTemplate,\n    loadWorkflowTemplate\n  }\n}\n","import type { ModelWithUrl } from '@/platform/missingModel/missingModelDownload'\nimport type {\n  TemplateModelMetadataBatchResult,\n  TemplateModelMetadataEntry\n} from '@/platform/workflow/templates/utils/templateModelMetadata'\nimport type { ResolvedTemplateModelAvailability } from '@/platform/workflow/templates/utils/templateModelAvailability'\nimport type { TemplateModelRequirementDetail } from '@/platform/workflow/templates/utils/templateModelRequirements'\nimport type { ModelFile } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { getModelFileKey } from '@/platform/workflow/core/utils/modelRequirements'\n\ntype TemplateModelSetupStatus =\n  | 'installed'\n  | 'downloadable'\n  | 'manual'\n  | 'unavailable'\n  | 'unknown'\n\ntype TemplateModelSetupRowBase = {\n  model: ModelFile\n  usedBy: readonly string[]\n  fileSize: number | null\n  /** Unformatted; the view labels it. */\n  modelDirectory: string\n}\n\nexport type TemplateModelSetupRow =\n  | (TemplateModelSetupRowBase & {\n      status: 'manual'\n      href: string\n    })\n  | (TemplateModelSetupRowBase & {\n      status: Exclude<TemplateModelSetupStatus, 'manual'>\n    })\n\ntype TemplateModelDeclarationTotal = {\n  bytes: number\n  isComplete: boolean\n}\n\nexport type TemplateModelSetupResult = {\n  rows: readonly TemplateModelSetupRow[]\n  declarationTotal: TemplateModelDeclarationTotal\n}\n\ntype TemplateModelSetupOptions = {\n  isDownloadable: (model: ModelWithUrl) => boolean\n}\n\nfunction indexByIdentity<T extends { model: ModelWithUrl }>(\n  entries: readonly T[]\n): Map<string, T> {\n  const indexed = new Map<string, T>()\n  for (const entry of entries) {\n    const identity = getModelFileKey(entry.model)\n    if (!indexed.has(identity)) indexed.set(identity, entry)\n  }\n  return indexed\n}\n\nfunction normalizeFileSize(fileSize: number | null | undefined): number | null {\n  return typeof fileSize === 'number' &&\n    Number.isFinite(fileSize) &&\n    fileSize >= 0\n    ? fileSize\n    : null\n}\n\nfunction deriveRow(\n  { model, usedBy }: TemplateModelRequirementDetail,\n  availability: ResolvedTemplateModelAvailability | undefined,\n  metadata: TemplateModelMetadataEntry | undefined,\n  isDownloadable: (model: ModelWithUrl) => boolean\n): TemplateModelSetupRow {\n  const row = {\n    model,\n    usedBy,\n    fileSize: normalizeFileSize(metadata?.fileSize),\n    modelDirectory: model.directory.trim()\n  }\n\n  if (availability?.status === 'installed') {\n    return { ...row, status: 'installed' }\n  }\n  if (availability?.status !== 'missing') {\n    return { ...row, status: 'unknown' }\n  }\n  if (!metadata) {\n    return { ...row, status: 'unknown' }\n  }\n  const gatedRepoUrl = metadata.gatedRepoUrl?.trim()\n  if (gatedRepoUrl) {\n    return { ...row, status: 'manual', href: gatedRepoUrl }\n  }\n  return {\n    ...row,\n    status: isDownloadable(model) ? 'downloadable' : 'unavailable'\n  }\n}\n\nfunction totalDeclarations(\n  rows: readonly TemplateModelSetupRow[]\n): TemplateModelDeclarationTotal {\n  const seen = new Set<string>()\n  let bytes = 0\n  let isComplete = true\n\n  for (const row of rows) {\n    const identity = getModelFileKey(row.model)\n    if (seen.has(identity)) continue\n\n    seen.add(identity)\n    if (row.fileSize === null) {\n      isComplete = false\n    } else {\n      bytes += row.fileSize\n    }\n  }\n\n  return { bytes, isComplete }\n}\n\n/** The state a row's own download is in, as the view's row-downloads reports it. */\ntype RowDownloadStatus = { status: string }\n\n/** A row the bulk action would actually start. */\nexport function isModelDownloadCandidate(\n  row: TemplateModelSetupRow,\n  stateFor: (model: ModelWithUrl) => RowDownloadStatus\n): boolean {\n  if (row.status !== 'downloadable') return false\n  const state = stateFor(row.model)\n  return state.status === 'idle' || state.status === 'failed'\n}\n\n/** Nothing left to satisfy: already on disk, or downloaded in this session. */\nexport function isModelRowComplete(\n  row: TemplateModelSetupRow,\n  stateFor: (model: ModelWithUrl) => RowDownloadStatus\n): boolean {\n  if (row.status === 'installed') return true\n  return stateFor(row.model).status === 'done'\n}\n\n/**\n * What a bulk click would transfer. Shares `totalDeclarations`' identity dedupe\n * so this and the group header cannot count the same model differently.\n */\nexport function remainingModelDownloadTotal(\n  rows: readonly TemplateModelSetupRow[],\n  stateFor: (model: ModelWithUrl) => RowDownloadStatus\n): TemplateModelDeclarationTotal {\n  return totalDeclarations(\n    rows.filter((row) => isModelDownloadCandidate(row, stateFor))\n  )\n}\n\nexport function deriveTemplateModelSetup(\n  requirements: readonly TemplateModelRequirementDetail[],\n  availability: readonly ResolvedTemplateModelAvailability[],\n  metadata: TemplateModelMetadataBatchResult,\n  { isDownloadable }: TemplateModelSetupOptions\n): TemplateModelSetupResult {\n  const availabilityByIdentity = indexByIdentity(availability)\n  const metadataByIdentity = indexByIdentity(\n    metadata.status === 'completed' ? metadata.entries : []\n  )\n  const rows = requirements.map((requirement) => {\n    const identity = getModelFileKey(requirement.model)\n    return deriveRow(\n      requirement,\n      availabilityByIdentity.get(identity),\n      metadataByIdentity.get(identity),\n      isDownloadable\n    )\n  })\n\n  return {\n    rows,\n    declarationTotal: totalDeclarations(rows)\n  }\n}\n","<template>\n  <BaseModalLayout\n    ref=\"modalLayout\"\n    :content-title=\"$t('templateWorkflows.title', 'Workflow Templates')\"\n    content-padding=\"none\"\n    size=\"md\"\n    close-button-variant=\"textonly\"\n  >\n    <template #leftPanelHeaderTitle>\n      <i class=\"icon-[comfy--template]\" />\n      <h2 class=\"text-base font-semibold text-base-foreground\">\n        {{ $t('sideToolbar.templates', 'Templates') }}\n      </h2>\n    </template>\n    <template #leftPanel>\n      <LeftSidePanel\n        :model-value=\"selectedNavItem\"\n        :nav-items=\"navItems\"\n        @update:model-value=\"onSelectNavItem\"\n      />\n    </template>\n\n    <template #header>\n      <nav\n        v-show=\"activeDetail\"\n        :aria-label=\"$t('templateWorkflows.detail.breadcrumbLabel')\"\n        class=\"flex min-w-0 flex-1 items-center gap-2\"\n      >\n        <Button\n          :aria-label=\"backToTemplatesLabel\"\n          :disabled=\"openPending\"\n          size=\"unset\"\n          variant=\"muted-textonly\"\n          class=\"shrink-0 gap-2 text-sm font-medium text-muted-foreground hover:bg-transparent\"\n          @click=\"onBackToTemplates\"\n        >\n          <i aria-hidden=\"true\" class=\"icon-[lucide--arrow-left] size-4\" />\n          {{ pageTitle }}\n        </Button>\n      </nav>\n      <div\n        v-show=\"!activeDetail\"\n        class=\"flex min-w-0 flex-1 items-center gap-2\"\n      >\n        <h2\n          class=\"m-0 hidden shrink-0 truncate text-base font-medium text-base-foreground min-[880px]:block\"\n        >\n          {{ pageTitle }}\n        </h2>\n        <AsyncSearchInput\n          v-model=\"searchInput\"\n          :searcher=\"applySearchQuery\"\n          :debounce-ms=\"400\"\n          :debounce-max-wait-ms=\"4000\"\n          class=\"h-9 w-full min-w-0 flex-1 border border-border-subtle bg-transparent min-[880px]:ml-auto min-[880px]:max-w-96\"\n          autofocus\n        />\n      </div>\n    </template>\n\n    <template #contentFilter>\n      <div\n        v-show=\"!activeDetail\"\n        :class=\"\n          cn(\n            '@container/filters relative px-6',\n            hasActiveFilters ? 'pb-2' : 'pb-4'\n          )\n        \"\n        data-testid=\"template-filter-bar\"\n      >\n        <div class=\"flex items-center gap-3\">\n          <div class=\"flex min-w-0 shrink items-center gap-2\">\n            <Button\n              v-for=\"tab in typeTabs\"\n              :key=\"tab.value\"\n              size=\"md\"\n              :variant=\"selectedType === tab.value ? 'inverted' : 'secondary'\"\n              :aria-pressed=\"selectedType === tab.value\"\n              :aria-label=\"tab.icon ? tab.label : undefined\"\n              class=\"h-8 shrink-0 px-3 text-xs @max-[30rem]/filters:px-2.5\"\n              @click=\"selectedType = tab.value\"\n            >\n              <i v-if=\"tab.icon\" :class=\"cn(tab.icon, 'size-3.5')\" />\n              <span :class=\"cn(tab.icon && '@max-[30rem]/filters:sr-only')\">{{\n                tab.label\n              }}</span>\n            </Button>\n          </div>\n\n          <div\n            class=\"ml-auto hidden min-w-0 shrink items-center justify-end gap-2 @[58rem]/filters:flex\"\n          >\n            <TemplateFilterControls\n              v-bind=\"filterControlBindings\"\n              trigger-class=\"min-w-0 shrink basis-40 border border-border-subtle bg-transparent\"\n            />\n          </div>\n\n          <Button\n            size=\"md\"\n            :variant=\"mobileFiltersOpen ? 'inverted' : 'secondary'\"\n            :aria-expanded=\"mobileFiltersOpen\"\n            aria-controls=\"template-mobile-filters\"\n            :aria-label=\"$t('templateWorkflows.filtersButton')\"\n            class=\"ml-auto h-8 shrink-0 px-3 text-xs @[58rem]/filters:hidden\"\n            @click=\"mobileFiltersOpen = !mobileFiltersOpen\"\n          >\n            <i class=\"icon-[lucide--sliders-horizontal] size-3.5\" />\n            <span>{{ $t('templateWorkflows.filtersButton') }}</span>\n            <span v-if=\"activeFilterCount > 0\" :class=\"selectCountBadgeClass\">\n              {{ activeFilterCount }}\n            </span>\n          </Button>\n        </div>\n\n        <div\n          v-show=\"mobileFiltersOpen\"\n          id=\"template-mobile-filters\"\n          class=\"mt-3 flex flex-col gap-2 @[58rem]/filters:hidden\"\n        >\n          <div class=\"grid grid-cols-2 gap-2 @max-[26rem]/filters:grid-cols-1\">\n            <TemplateFilterControls\n              v-bind=\"filterControlBindings\"\n              trigger-class=\"w-full border border-border-subtle bg-transparent\"\n            />\n          </div>\n        </div>\n\n        <div v-if=\"hasActiveFilters\" class=\"flex items-center pt-5\">\n          <span\n            v-if=\"activeFilterCount > 0\"\n            class=\"text-xs font-medium text-muted-foreground\"\n          >\n            {{\n              $t('templateWorkflows.filtersApplied', {\n                count: activeFilterCount\n              })\n            }}\n          </span>\n          <Button\n            variant=\"link\"\n            size=\"unset\"\n            class=\"ml-auto text-xs font-normal text-base-foreground underline opacity-70 hover:opacity-100\"\n            @click=\"resetFilters\"\n          >\n            {{ $t('templateWorkflows.clearAllFilters') }}\n          </Button>\n        </div>\n      </div>\n    </template>\n\n    <template #content>\n      <!-- No Results State (only show when loaded and no results) -->\n      <div\n        v-if=\"!activeDetail && !isLoading && filteredTemplates.length === 0\"\n        class=\"flex h-64 flex-col items-center justify-center px-6 text-neutral-500\"\n      >\n        <i class=\"mb-4 icon-[lucide--search] size-12 opacity-50\" />\n        <p class=\"mb-2 text-lg\">\n          {{ $t('templateWorkflows.noResults', 'No templates found') }}\n        </p>\n        <p class=\"text-sm\">\n          {{\n            $t(\n              'templateWorkflows.noResultsHint',\n              'Try adjusting your search or filters'\n            )\n          }}\n        </p>\n      </div>\n      <div v-else v-show=\"!activeDetail\" class=\"px-6\">\n        <!-- Title -->\n        <span\n          v-if=\"isLoading\"\n          class=\"inline-block h-8 w-48 animate-pulse rounded-sm bg-dialog-surface\"\n        ></span>\n\n        <!-- Template Cards Grid -->\n        <div\n          :key=\"templateListKey\"\n          class=\"-mx-2 grid grid-cols-[repeat(auto-fill,minmax(15rem,1fr))] items-stretch gap-2\"\n          data-testid=\"template-workflows-content\"\n        >\n          <!-- Loading Skeletons (show while loading initial data) -->\n          <CardContainer\n            v-for=\"n in isLoading ? 12 : 0\"\n            :key=\"`initial-skeleton-${n}`\"\n            size=\"compact\"\n            variant=\"ghost\"\n            rounded=\"lg\"\n            class=\"hover:bg-base-background\"\n          >\n            <template #top>\n              <CardTop ratio=\"landscape\">\n                <template #default>\n                  <div class=\"size-full animate-pulse bg-dialog-surface\"></div>\n                </template>\n              </CardTop>\n            </template>\n            <template #bottom>\n              <CardBottom>\n                <div class=\"px-4 py-3\">\n                  <div\n                    class=\"mb-2 h-6 animate-pulse rounded-sm bg-dialog-surface\"\n                  ></div>\n                  <div\n                    class=\"h-4 animate-pulse rounded-sm bg-dialog-surface\"\n                  ></div>\n                </div>\n              </CardBottom>\n            </template>\n          </CardContainer>\n\n          <!-- Actual Template Cards -->\n          <CardContainer\n            v-for=\"{ template, tags } in isLoading ? [] : displayTemplates\"\n            :key=\"template.name\"\n            ref=\"cardRefs\"\n            size=\"auto\"\n            variant=\"ghost\"\n            rounded=\"lg\"\n            :data-testid=\"`template-workflow-${template.name}`\"\n            class=\"group/card h-full transition-colors hover:bg-secondary-background/50\"\n            @mouseenter=\"hoveredTemplate = template.name\"\n            @mouseleave=\"hoveredTemplate = null\"\n            @click=\"onLoadWorkflow(template, $event)\"\n          >\n            <template #top>\n              <CardTop ratio=\"square\">\n                <template #default>\n                  <!-- Template Thumbnail -->\n                  <TemplatePreview\n                    :template=\"template\"\n                    :base-image-src=\"getBaseThumbnailSrc(template)\"\n                    :overlay-image-src=\"getOverlayThumbnailSrc(template)\"\n                    :alt=\"\n                      getTemplateTitle(\n                        template,\n                        getEffectiveSourceModule(template)\n                      )\n                    \"\n                    :get-logo-url=\"workflowTemplatesStore.getLogoUrl\"\n                    :is-hovered=\"hoveredTemplate === template.name\"\n                    :hover-zoom=\"0\"\n                  >\n                    <template #overlay>\n                      <Spinner\n                        v-if=\"loadingTemplateId === template.name\"\n                        class=\"absolute inset-0 z-10 m-auto size-12\"\n                      />\n                    </template>\n                  </TemplatePreview>\n                </template>\n                <template #top-left>\n                  <div\n                    class=\"flex h-6 items-center gap-1 rounded-md bg-zinc-700/50 px-2 backdrop-blur-[20px]\"\n                  >\n                    <i\n                      :class=\"\n                        isAppTemplate(template)\n                          ? 'icon-[lucide--app-window]'\n                          : 'icon-[comfy--workflow]'\n                      \"\n                      class=\"size-3 text-white\"\n                    />\n                    <span\n                      class=\"text-xs font-medium whitespace-nowrap text-white\"\n                    >\n                      {{\n                        isAppTemplate(template)\n                          ? $t('builderToolbar.app')\n                          : $t('builderToolbar.nodeGraph')\n                      }}\n                    </span>\n                  </div>\n                </template>\n                <template\n                  v-if=\"template.isPartnerNode || template.tutorialUrl\"\n                  #top-right\n                >\n                  <Button\n                    v-if=\"template.tutorialUrl\"\n                    :tooltip=\"$t('g.seeTutorial')\"\n                    tooltip-side=\"bottom\"\n                    :aria-label=\"$t('g.seeTutorial')\"\n                    variant=\"inverted\"\n                    size=\"icon\"\n                    class=\"not-group-hover/card:opacity-0\"\n                    @click.stop=\"openTutorial(template)\"\n                  >\n                    <i class=\"icon-[lucide--info] size-4\" />\n                  </Button>\n                  <PaidTemplateBadge v-if=\"template.isPartnerNode\" />\n                </template>\n              </CardTop>\n            </template>\n            <template #bottom>\n              <CardBottom :full-height=\"false\">\n                <div class=\"flex flex-col gap-2 pt-2\">\n                  <h3\n                    class=\"m-0 line-clamp-1 text-sm font-semibold\"\n                    :title=\"\n                      getTemplateTitle(\n                        template,\n                        getEffectiveSourceModule(template)\n                      )\n                    \"\n                  >\n                    {{\n                      getTemplateTitle(\n                        template,\n                        getEffectiveSourceModule(template)\n                      )\n                    }}\n                  </h3>\n                  <div\n                    v-if=\"tags.visible.length\"\n                    class=\"flex items-center gap-2 py-1\"\n                  >\n                    <Tag\n                      v-for=\"tag in tags.visible\"\n                      :key=\"tag\"\n                      :label=\"tag\"\n                      shape=\"square\"\n                      class=\"bg-charcoal-500/50 opacity-80\"\n                    />\n                    <Tooltip v-if=\"tags.hidden.length\" open-on-click>\n                      <TooltipTrigger as-child>\n                        <button\n                          type=\"button\"\n                          :aria-label=\"tags.hidden.join(', ')\"\n                          class=\"cursor-pointer rounded-sm border-none bg-transparent p-0 focus-visible:ring-1 focus-visible:ring-base-foreground focus-visible:outline-none\"\n                          @click.stop\n                        >\n                          <Tag\n                            :label=\"`+${tags.hidden.length}`\"\n                            shape=\"square\"\n                            class=\"bg-charcoal-500/50 opacity-80\"\n                          />\n                        </button>\n                      </TooltipTrigger>\n                      <TooltipContent>{{\n                        tags.hidden.join(', ')\n                      }}</TooltipContent>\n                    </Tooltip>\n                  </div>\n                </div>\n              </CardBottom>\n            </template>\n          </CardContainer>\n\n          <!-- Loading More Skeletons -->\n          <CardContainer\n            v-for=\"n in isLoadingMore ? 6 : 0\"\n            :key=\"`skeleton-${n}`\"\n            size=\"compact\"\n            variant=\"ghost\"\n            rounded=\"lg\"\n            class=\"hover:bg-base-background\"\n          >\n            <template #top>\n              <CardTop ratio=\"square\">\n                <template #default>\n                  <div class=\"size-full animate-pulse bg-dialog-surface\"></div>\n                </template>\n              </CardTop>\n            </template>\n            <template #bottom>\n              <CardBottom>\n                <div class=\"px-4 py-3\">\n                  <div\n                    class=\"mb-2 h-6 animate-pulse rounded-sm bg-dialog-surface\"\n                  ></div>\n                  <div\n                    class=\"h-4 animate-pulse rounded-sm bg-dialog-surface\"\n                  ></div>\n                </div>\n              </CardBottom>\n            </template>\n          </CardContainer>\n        </div>\n      </div>\n\n      <!-- Load More Trigger -->\n      <div\n        v-if=\"!isLoading && hasMoreTemplates\"\n        v-show=\"!activeDetail\"\n        ref=\"loadTrigger\"\n        class=\"mt-4 flex h-4 w-full items-center justify-center px-6\"\n      >\n        <div v-if=\"isLoadingMore\" class=\"text-sm text-muted\">\n          {{ $t('templateWorkflows.loadingMore', 'Loading more...') }}\n        </div>\n      </div>\n\n      <!-- Results Summary -->\n      <div\n        v-if=\"!isLoading\"\n        v-show=\"!activeDetail\"\n        class=\"mt-6 px-6 pb-10 text-sm text-muted\"\n      >\n        {{\n          $t('templateWorkflows.resultsCount', {\n            count: filteredCount,\n            total: totalCount\n          })\n        }}\n      </div>\n\n      <WorkflowTemplateDetail\n        v-if=\"activeDetail\"\n        ref=\"detailView\"\n        :title=\"activeDetailTitle\"\n        :description=\"getTemplateDescription(activeDetail.template)\"\n        :groups=\"activeDetailGroups\"\n        :cloud-url=\"activeDetailCloudUrl\"\n        :is-partner-node=\"activeDetail.template.openSource === false\"\n        :open-pending=\"openPending\"\n        :model-setup=\"activeDetailModelSetup\"\n        @open-template=\"onOpenTemplate\"\n        @download-models-and-open=\"onDownloadModelsAndOpen\"\n        @download-model=\"onDownloadModel\"\n      >\n        <template #preview>\n          <TemplatePreview\n            :template=\"activeDetail.template\"\n            :base-image-src=\"getBaseThumbnailSrc(activeDetail.template)\"\n            :overlay-image-src=\"getOverlayThumbnailSrc(activeDetail.template)\"\n            :alt=\"activeDetailTitle\"\n            :get-logo-url=\"workflowTemplatesStore.getLogoUrl\"\n            :hover-zoom=\"0\"\n            :is-hovered=\"detailPreviewHovered\"\n            data-testid=\"detail-preview\"\n            @mouseenter=\"detailPreviewHovered = true\"\n            @mouseleave=\"detailPreviewHovered = false\"\n          />\n        </template>\n      </WorkflowTemplateDetail>\n    </template>\n  </BaseModalLayout>\n</template>\n\n<script setup lang=\"ts\">\nimport { useAsyncState } from '@vueuse/core'\nimport {\n  computed,\n  markRaw,\n  nextTick,\n  onBeforeUnmount,\n  onMounted,\n  provide,\n  ref,\n  watch\n} from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport type { ComfyTemplateInputAsset } from '@comfyorg/comfyui-desktop-bridge-types'\n\nimport CardBottom from '@/components/card/CardBottom.vue'\nimport CardContainer from '@/components/card/CardContainer.vue'\nimport CardTop from '@/components/card/CardTop.vue'\nimport Tag from '@/components/chip/Tag.vue'\nimport PaidTemplateBadge from '@/components/custom/widget/PaidTemplateBadge.vue'\nimport TemplateFilterControls from '@/components/custom/widget/TemplateFilterControls.vue'\nimport WorkflowTemplateDetail from '@/components/custom/widget/WorkflowTemplateDetail.vue'\nimport AsyncSearchInput from '@/components/ui/search-input/AsyncSearchInput.vue'\nimport TemplatePreview from '@/components/templates/thumbnails/TemplatePreview.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { selectCountBadgeClass } from '@comfyorg/design-system/select.variants'\nimport type { SelectOption } from '@/components/ui/select/types'\nimport Spinner from '@/components/ui/spinner/Spinner.vue'\nimport BaseModalLayout from '@/components/widget/layout/BaseModalLayout.vue'\nimport LeftSidePanel from '@/components/widget/panel/LeftSidePanel.vue'\nimport { useIntersectionObserver } from '@/composables/useIntersectionObserver'\nimport { useLazyPagination } from '@/composables/useLazyPagination'\nimport { useTemplateFiltering } from '@/composables/useTemplateFiltering'\nimport type { TemplateSortMode } from '@/composables/useTemplateFiltering'\nimport { getComfyCloudBaseUrl } from '@/config/comfyApi'\nimport { formatCategoryLabel } from '@/platform/assets/utils/categoryLabel'\nimport { isCloud, isDesktop } from '@/platform/distribution/types'\nimport { loadFolderPathsOnce } from '@/platform/missingModel/folderPathCache'\nimport {\n  isModelDownloadable,\n  modelDownloadNeedsFolderPaths\n} from '@/platform/missingModel/missingModelDownload'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { getModelFileKey } from '@/platform/workflow/core/utils/modelRequirements'\nimport { useTemplateModelAvailability } from '@/platform/workflow/templates/composables/useTemplateModelAvailability'\nimport { useTemplateModelRowDownloads } from '@/platform/workflow/templates/composables/useTemplateModelRowDownloads'\nimport { useTemplateWorkflows } from '@/platform/workflow/templates/composables/useTemplateWorkflows'\nimport type { PreparedWorkflowTemplate } from '@/platform/workflow/templates/composables/useTemplateWorkflows'\nimport type {\n  TemplateInfo,\n  TemplateTypeFilter\n} from '@/platform/workflow/templates/types/template'\nimport { TemplateIncludeOnDistributionEnum } from '@/platform/workflow/templates/types/template'\nimport type {\n  TemplateDetailGroup,\n  TemplateDetailRow,\n  TemplateModelSetup\n} from '@/platform/workflow/templates/types/templateDetail'\nimport { useWorkflowTemplatesStore } from '@/platform/workflow/templates/repositories/workflowTemplatesStore'\nimport {\n  filterTemplatesByType,\n  getTemplateTags,\n  isAppTemplate\n} from '@/platform/workflow/templates/utils/templateDisplay'\nimport { resolveTemplateModelMetadata } from '@/platform/workflow/templates/utils/templateModelMetadata'\nimport { extractTemplateModelRequirementDetails } from '@/platform/workflow/templates/utils/templateModelRequirements'\nimport type { TemplateModelRequirementDetail } from '@/platform/workflow/templates/utils/templateModelRequirements'\nimport type { ResolvedTemplateModelAvailability } from '@/platform/workflow/templates/utils/templateModelAvailability'\nimport {\n  deriveTemplateModelSetup,\n  isModelDownloadCandidate,\n  isModelRowComplete,\n  remainingModelDownloadTotal\n} from '@/platform/workflow/templates/utils/templateModelSetup'\nimport type {\n  TemplateModelSetupResult,\n  TemplateModelSetupRow\n} from '@/platform/workflow/templates/utils/templateModelSetup'\nimport { resolveTemplateInputAssets } from '@/platform/workflow/templates/utils/templateInputAssets'\nimport type { NavGroupData, NavItemData } from '@/types/navTypes'\nimport { OnCloseKey } from '@/types/widgetTypes'\nimport { formatSize } from '@/utils/formatUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\n\nconst { onClose: originalOnClose, initialCategory = 'all' } = defineProps<{\n  onClose: () => void\n  initialCategory?: string\n}>()\n\n// Track session time for telemetry\nconst sessionStartTime = ref<number>(0)\nconst templateWasSelected = ref(false)\nconst detailPreviewHovered = ref(false)\n\nonMounted(() => {\n  sessionStartTime.value = Date.now()\n})\n\n// Wrap onClose to track session end\nconst onClose = () => {\n  activeDetail.value?.modelSetup.rowDownloads.dispose()\n  invalidateDetailWork()\n  const timeSpentSeconds = Math.floor(\n    (Date.now() - sessionStartTime.value) / 1000\n  )\n\n  useTelemetry()?.trackTemplateLibraryClosed({\n    template_selected: templateWasSelected.value,\n    time_spent_seconds: timeSpentSeconds\n  })\n\n  originalOnClose()\n}\n\nprovide(OnCloseKey, onClose)\n\n// Workflow templates store and composable\nconst workflowTemplatesStore = useWorkflowTemplatesStore()\nconst {\n  loadTemplates,\n  loadingTemplateId,\n  getTemplateThumbnailUrl,\n  getTemplateTitle,\n  getTemplateDescription,\n  openPreparedWorkflowTemplate,\n  prepareWorkflowTemplate,\n  discardPreparedWorkflowTemplate\n} = useTemplateWorkflows()\n\nconst getEffectiveSourceModule = (template: TemplateInfo) =>\n  template.sourceModule || 'default'\n\nconst getBaseThumbnailSrc = (template: TemplateInfo) => {\n  const sm = getEffectiveSourceModule(template)\n  return getTemplateThumbnailUrl(template, sm, sm === 'default' ? '1' : '')\n}\n\nconst getOverlayThumbnailSrc = (template: TemplateInfo) => {\n  const sm = getEffectiveSourceModule(template)\n  return getTemplateThumbnailUrl(template, sm, sm === 'default' ? '2' : '')\n}\n\n// Open tutorial in new tab\nconst openTutorial = (template: TemplateInfo) => {\n  if (template.tutorialUrl) {\n    window.open(template.tutorialUrl, '_blank')\n  }\n}\n\n// Get navigation items from the store, with skeleton items while loading\nconst navItems = computed<(NavItemData | NavGroupData)[]>(() => {\n  // Show skeleton navigation items while loading\n  if (isLoading.value) {\n    return [\n      {\n        id: 'skeleton-all',\n        label: 'All Templates',\n        icon: 'icon-[lucide--layout-grid]'\n      },\n      {\n        id: 'skeleton-basics',\n        label: 'Basics',\n        icon: 'icon-[lucide--graduation-cap]'\n      },\n      {\n        title: 'Generation Type',\n        items: [\n          { id: 'skeleton-1', label: '...', icon: 'icon-[lucide--loader-2]' },\n          { id: 'skeleton-2', label: '...', icon: 'icon-[lucide--loader-2]' }\n        ]\n      },\n      {\n        title: 'Closed Source Models',\n        items: [\n          { id: 'skeleton-3', label: '...', icon: 'icon-[lucide--loader-2]' }\n        ]\n      }\n    ]\n  }\n  return workflowTemplatesStore.navGroupedTemplates\n})\n\n// Get enhanced templates for better filtering\nconst allTemplates = computed(() => {\n  return workflowTemplatesStore.enhancedTemplates\n})\n\n// Navigation\nconst selectedNavItem = ref<string | null>(initialCategory)\n\n// Filter templates based on selected navigation item\nconst navigationFilteredTemplates = computed(() => {\n  if (!selectedNavItem.value) {\n    return allTemplates.value\n  }\n\n  return workflowTemplatesStore.filterTemplatesByCategory(selectedNavItem.value)\n})\n\nconst selectedType = ref<TemplateTypeFilter>('all')\n\nconst typeTabs = computed<\n  { value: TemplateTypeFilter; label: string; icon?: string }[]\n>(() => [\n  { value: 'all', label: t('g.all') },\n  {\n    value: 'nodeGraph',\n    label: t('builderToolbar.nodeGraph'),\n    icon: 'icon-[comfy--workflow]'\n  },\n  {\n    value: 'apps',\n    label: t('builderToolbar.app'),\n    icon: 'icon-[lucide--app-window]'\n  }\n])\n\nconst typeFilteredTemplates = computed(() =>\n  filterTemplatesByType(navigationFilteredTemplates.value, selectedType.value)\n)\n\n// Template filtering with scope awareness\nconst {\n  searchQuery,\n  selectedModels,\n  selectedUseCases,\n  selectedRunsOn,\n  sortSelection,\n  hasActiveQuery,\n  activeModels,\n  activeUseCases,\n  filteredTemplates,\n  availableModels,\n  availableUseCases,\n  availableRunsOn,\n  filteredCount,\n  totalCount,\n  resetFilters\n} = useTemplateFiltering(typeFilteredTemplates)\n\n/**\n * Raw search input bound to the search box. The actual `searchQuery` consumed\n * by the filtering composable is only updated via `applySearchQuery` after the\n * debounce settles, keeping search/grid re-renders off the keystroke critical path.\n */\nconst searchInput = ref(searchQuery.value)\n\nconst applySearchQuery = async (query: string) => {\n  searchQuery.value = query\n}\n\n/**\n * Sync the visible search input when `searchQuery` is reset externally\n * (e.g. via the \"Clear all filters\" action).\n */\nwatch(searchQuery, (value) => {\n  if (value !== searchInput.value) searchInput.value = value\n})\n\n/**\n * Coordinates state between the selected navigation item and the sort order to\n * create deterministic, predictable behavior.\n * @param source The origin of the change ('nav' or 'sort').\n */\nconst coordinateNavAndSort = (source: 'nav' | 'sort') => {\n  if (hasActiveQuery.value) return\n\n  const isPopularNav = selectedNavItem.value === 'popular'\n  const isPopularSort = sortSelection.value === 'popular'\n\n  if (source === 'nav') {\n    if (isPopularNav && !isPopularSort) {\n      sortSelection.value = 'popular'\n    } else if (!isPopularNav && isPopularSort) {\n      sortSelection.value = 'default'\n    }\n  } else if (source === 'sort') {\n    // When sort is changed away from 'Popular' while in the 'Popular' category,\n    // reset the category to 'All Templates' to avoid a confusing state.\n    if (isPopularNav && !isPopularSort) {\n      selectedNavItem.value = 'all'\n    }\n  }\n}\n\n// Watch for changes from the two sources ('nav' and 'sort') and trigger the coordinator.\nwatch(selectedNavItem, () => coordinateNavAndSort('nav'), {\n  immediate: selectedNavItem.value === 'popular'\n})\nwatch(sortSelection, () => coordinateNavAndSort('sort'))\n\n// Convert between string array and object array for MultiSelect component\n// Only show selected items that exist in the current scope\nconst toSelectOptions = (values: string[]): SelectOption[] =>\n  values.map((value) => ({ name: value, value }))\n\n// active* hides out-of-scope model/use-case selections; availableRunsOn is\n// static so runs-on selections are always in scope and need no filtering.\nconst selectedModelObjects = computed({\n  get: () => toSelectOptions(activeModels.value),\n  set: (value: SelectOption[]) => {\n    selectedModels.value = value.map((item) => item.value)\n  }\n})\n\nconst selectedUseCaseObjects = computed({\n  get: () => toSelectOptions(activeUseCases.value),\n  set: (value: SelectOption[]) => {\n    selectedUseCases.value = value.map((item) => item.value)\n  }\n})\n\nconst selectedRunsOnObjects = computed({\n  get: () => toSelectOptions(selectedRunsOn.value),\n  set: (value: SelectOption[]) => {\n    selectedRunsOn.value = value.map((item) => item.value)\n  }\n})\n\nconst activeFilterCount = computed(\n  () =>\n    selectedModelObjects.value.length +\n    selectedUseCaseObjects.value.length +\n    selectedRunsOnObjects.value.length\n)\n\n// Any filter chip or search query is set. Keyed off intent rather than the\n// result-count delta so the clear row still shows when a filter happens to\n// match every template (filteredCount === totalCount).\nconst hasActiveFilters = computed(\n  () => activeFilterCount.value > 0 || hasActiveQuery.value\n)\n\n// UI state\nconst mobileFiltersOpen = ref(false)\nconst hoveredTemplate = ref<string | null>(null)\nconst cardRefs = ref<HTMLElement[]>([])\ntype TemplateModelRowDownloads = ReturnType<typeof useTemplateModelRowDownloads>\n\ntype ActiveTemplateModelSetup = {\n  result: TemplateModelSetupResult\n  pending: boolean\n  rowDownloads: TemplateModelRowDownloads\n}\n\nconst modalLayout = ref<InstanceType<typeof BaseModalLayout> | null>(null)\nconst detailView = ref<InstanceType<typeof WorkflowTemplateDetail> | null>(null)\nconst activeDetail = ref<{\n  template: TemplateInfo\n  prepared: PreparedWorkflowTemplate\n  modelSetup: ActiveTemplateModelSetup\n  inputAssets: readonly ComfyTemplateInputAsset[]\n} | null>(null)\nconst openPending = ref(false)\nlet detailGeneration = 0\nlet preparedInFlight: PreparedWorkflowTemplate | null = null\nlet modelMetadataController: AbortController | undefined\nlet detailOrigin: HTMLElement | null = null\nlet listScrollTop = 0\n\nconst { resolveAvailability: resolveModelAvailability } =\n  useTemplateModelAvailability()\n\n// Force re-render key for templates when sorting changes\nconst templateListKey = ref(0)\n\n// Search text for model filter\nconst modelSearchText = ref<string>('')\n\n// Filter options\nconst modelOptions = computed(() =>\n  availableModels.value.map((model) => ({\n    name: model,\n    value: model\n  }))\n)\n\nconst useCaseOptions = computed(() =>\n  availableUseCases.value.map((useCase) => ({\n    name: useCase,\n    value: useCase\n  }))\n)\n\nconst runsOnOptions = computed(() =>\n  availableRunsOn.value.map((runsOn) => ({\n    name: runsOn,\n    value: runsOn\n  }))\n)\n\n// Filter labels\nconst modelFilterLabel = computed(() => {\n  if (selectedModelObjects.value.length === 0) {\n    return t('templateWorkflows.modelFilter', 'Model Filter')\n  } else if (selectedModelObjects.value.length === 1) {\n    return selectedModelObjects.value[0].name\n  } else {\n    return t('templateWorkflows.modelsSelected', {\n      count: selectedModelObjects.value.length\n    })\n  }\n})\n\nconst useCaseFilterLabel = computed(() => {\n  if (selectedUseCaseObjects.value.length === 0) {\n    return t('templateWorkflows.useCaseFilter', 'Use Case')\n  } else if (selectedUseCaseObjects.value.length === 1) {\n    return selectedUseCaseObjects.value[0].name\n  } else {\n    return t('templateWorkflows.useCasesSelected', {\n      count: selectedUseCaseObjects.value.length\n    })\n  }\n})\n\nconst runsOnFilterLabel = computed(() => {\n  if (selectedRunsOnObjects.value.length === 0) {\n    return t('templateWorkflows.runsOnFilter', 'Runs On')\n  } else if (selectedRunsOnObjects.value.length === 1) {\n    return selectedRunsOnObjects.value[0].name\n  } else {\n    return t('templateWorkflows.runsOnSelected', {\n      count: selectedRunsOnObjects.value.length\n    })\n  }\n})\n\nconst sortOptions = computed(() => [\n  ...(hasActiveQuery.value\n    ? [\n        {\n          name: t('templateWorkflows.sort.relevance', 'Relevance'),\n          value: 'relevance'\n        }\n      ]\n    : []),\n  {\n    name: t('templateWorkflows.sort.default', 'Default'),\n    value: 'default'\n  },\n  {\n    name: t('templateWorkflows.sort.recommended', 'Recommended'),\n    value: 'recommended'\n  },\n  {\n    name: t('templateWorkflows.sort.popular', 'Popular'),\n    value: 'popular'\n  },\n  { name: t('templateWorkflows.sort.newest', 'Newest'), value: 'newest' },\n  {\n    name: t(\n      'templateWorkflows.sort.modelSizeLowToHigh',\n      'Model Size (Low to High)'\n    ),\n    value: 'model-size-low-to-high'\n  },\n  {\n    name: t('templateWorkflows.sort.alphabetical', 'Alphabetical (A-Z)'),\n    value: 'alphabetical'\n  }\n])\n\nconst filterControlBindings = computed(() => ({\n  selectedModels: selectedModelObjects.value,\n  'onUpdate:selectedModels': (value: SelectOption[]) => {\n    selectedModelObjects.value = value\n  },\n  selectedUseCases: selectedUseCaseObjects.value,\n  'onUpdate:selectedUseCases': (value: SelectOption[]) => {\n    selectedUseCaseObjects.value = value\n  },\n  selectedRunsOn: selectedRunsOnObjects.value,\n  'onUpdate:selectedRunsOn': (value: SelectOption[]) => {\n    selectedRunsOnObjects.value = value\n  },\n  sortSelection: sortSelection.value,\n  'onUpdate:sortSelection': (value: TemplateSortMode) => {\n    sortSelection.value = value\n  },\n  modelSearchText: modelSearchText.value,\n  'onUpdate:modelSearchText': (value: string) => {\n    modelSearchText.value = value\n  },\n  modelOptions: modelOptions.value,\n  useCaseOptions: useCaseOptions.value,\n  runsOnOptions: runsOnOptions.value,\n  sortOptions: sortOptions.value,\n  modelFilterLabel: modelFilterLabel.value,\n  useCaseFilterLabel: useCaseFilterLabel.value,\n  runsOnFilterLabel: runsOnFilterLabel.value\n}))\n\n// Lazy pagination setup\nconst loadTrigger = ref<HTMLElement | null>(null)\nconst shouldUsePagination = computed(() => !searchQuery.value.trim())\n\nconst {\n  paginatedItems: paginatedTemplates,\n  isLoading: isLoadingMore,\n  hasMoreItems: hasMoreTemplates,\n  loadNextPage,\n  reset: resetPagination\n} = useLazyPagination(filteredTemplates, { itemsPerPage: 24 }) // Load 24 items per page\n\n// Display templates (all when searching, paginated when not)\nconst displayTemplates = computed(() =>\n  (shouldUsePagination.value\n    ? paginatedTemplates.value\n    : filteredTemplates.value\n  ).map((template) => ({ template, tags: getTemplateTags(template) }))\n)\n\n// Set up intersection observer for lazy loading\nuseIntersectionObserver(loadTrigger, (entries) => {\n  if (!entries.some((entry) => entry.isIntersecting)) return\n\n  if (\n    shouldUsePagination.value &&\n    hasMoreTemplates.value &&\n    !isLoadingMore.value\n  ) {\n    void loadNextPage()\n  }\n})\n\n// Reset pagination when filters change\nwatch(\n  [\n    filteredTemplates,\n    selectedNavItem,\n    selectedType,\n    sortSelection,\n    selectedModels,\n    selectedUseCases,\n    selectedRunsOn\n  ],\n  () => {\n    activeDetail.value?.modelSetup.rowDownloads.dispose()\n    invalidateDetailWork()\n    activeDetail.value = null\n    resetPagination()\n    templateListKey.value++\n  }\n)\n\n// Methods\nfunction releasePreparedDetail() {\n  const owned = preparedInFlight ?? activeDetail.value?.prepared ?? null\n  preparedInFlight = null\n  discardPreparedWorkflowTemplate(owned)\n}\n\nfunction invalidateDetailWork() {\n  modelMetadataController?.abort()\n  modelMetadataController = undefined\n  detailGeneration++\n  releasePreparedDetail()\n}\n\nfunction getModelTypeLabel(row: TemplateModelSetupRow): string {\n  return formatCategoryLabel(row.modelDirectory)\n}\n\nfunction getModelDetailDescription(row: TemplateModelSetupRow): string {\n  const parts = [getModelTypeLabel(row)]\n  if (row.fileSize !== null) parts.push(formatSize(row.fileSize))\n  if (row.usedBy.length > 0) {\n    parts.push(\n      t(\n        'templateWorkflows.detail.usedBy',\n        { nodes: row.usedBy.join(', ') },\n        { escapeParameter: false }\n      )\n    )\n  }\n  return parts.filter(Boolean).join(' · ')\n}\n\nfunction toModelDetailRow(\n  row: TemplateModelSetupRow,\n  rowDownloads: TemplateModelRowDownloads\n): TemplateDetailRow {\n  const detailRow: TemplateDetailRow = {\n    id: `model:${getModelFileKey(row.model)}`,\n    kind: 'model',\n    name: row.model.name,\n    description: getModelDetailDescription(row)\n  }\n\n  switch (row.status) {\n    case 'installed':\n      return {\n        ...detailRow,\n        status: {\n          kind: 'installed',\n          label: t('templateWorkflows.detail.installed')\n        }\n      }\n    case 'downloadable':\n      return {\n        ...detailRow,\n        status: {\n          kind: 'downloadable',\n          label: t('templateWorkflows.detail.downloadModel'),\n          downloadState: rowDownloads.stateFor(row.model)\n        }\n      }\n    case 'manual':\n      return {\n        ...detailRow,\n        status: {\n          kind: 'manual',\n          label: t('templateWorkflows.detail.getItManually'),\n          href: row.href\n        }\n      }\n    case 'unavailable':\n      return {\n        ...detailRow,\n        status: {\n          kind: 'unavailable',\n          label: t('templateWorkflows.detail.unavailable')\n        }\n      }\n    case 'unknown':\n      return {\n        ...detailRow,\n        status: {\n          kind: 'unknown',\n          label: t('templateWorkflows.detail.unknown')\n        }\n      }\n    default:\n      return row satisfies never\n  }\n}\n\nfunction toInputDetailRow(asset: ComfyTemplateInputAsset): TemplateDetailRow {\n  return {\n    id: `input:${asset.assetId}`,\n    kind: 'input',\n    name: t(`templateWorkflows.detail.inputMediaTypes.${asset.mediaType}`),\n    description: asset.filename,\n    ...(asset.previewUrl && {\n      preview: { src: asset.previewUrl, mediaType: asset.mediaType }\n    })\n  }\n}\n\nfunction buildTemplateDetailGroups(\n  setup: TemplateModelSetupResult,\n  rowDownloads: TemplateModelRowDownloads,\n  inputAssets: readonly ComfyTemplateInputAsset[]\n): readonly TemplateDetailGroup[] {\n  const groups: TemplateDetailGroup[] = []\n\n  if (setup.rows.length > 0) {\n    groups.push({\n      id: 'models',\n      label: t('templateWorkflows.detail.models'),\n      ...(setup.declarationTotal.isComplete && {\n        total: formatSize(setup.declarationTotal.bytes)\n      }),\n      rows: setup.rows.map((row) => toModelDetailRow(row, rowDownloads))\n    })\n  }\n\n  if (inputAssets.length > 0) {\n    groups.push({\n      id: 'input-assets',\n      label: t('templateWorkflows.detail.inputAssets'),\n      rows: inputAssets.map(toInputDetailRow)\n    })\n  }\n\n  return groups\n}\n\nconst activeDetailGroups = computed<readonly TemplateDetailGroup[]>(() => {\n  const detail = activeDetail.value\n  if (!detail) return []\n\n  return buildTemplateDetailGroups(\n    detail.modelSetup.result,\n    detail.modelSetup.rowDownloads,\n    detail.inputAssets\n  )\n})\n\n/** The rows this click would start. */\nconst activeDetailModelDownloadCandidates = computed<\n  readonly TemplateModelSetupRow[]\n>(() => {\n  const setup = activeDetail.value?.modelSetup\n  if (!setup || setup.pending) return []\n  return setup.result.rows.filter((row) =>\n    isModelDownloadCandidate(row, setup.rowDownloads.stateFor)\n  )\n})\n\nconst activeDetailModelDownloadsAvailable = computed(\n  () => activeDetailModelDownloadCandidates.value.length > 0\n)\n\n/** Withheld unless every candidate declares a size: a partial total reads as complete. */\nconst activeDetailModelRequirementsMet = computed(() => {\n  const setup = activeDetail.value?.modelSetup\n  return Boolean(\n    setup &&\n    setup.result.rows.every((row) =>\n      isModelRowComplete(row, setup.rowDownloads.stateFor)\n    )\n  )\n})\n\nconst activeDetailModelSetup = computed<TemplateModelSetup | undefined>(() => {\n  const setup = activeDetail.value?.modelSetup\n  if (!setup) return undefined\n  if (setup.pending) return { state: 'resolving' }\n  if (activeDetailModelRequirementsMet.value) return undefined\n  if (!activeDetailModelDownloadsAvailable.value) return undefined\n\n  const total = remainingModelDownloadTotal(\n    setup.result.rows,\n    setup.rowDownloads.stateFor\n  )\n  return {\n    state: 'startable',\n    remainingSize: total.isComplete ? formatSize(total.bytes) : undefined\n  }\n})\n\nfunction applyTemplateModelMetadata(\n  generation: number,\n  requirements: readonly TemplateModelRequirementDetail[],\n  availability: readonly ResolvedTemplateModelAvailability[],\n  metadata: Awaited<ReturnType<typeof resolveTemplateModelMetadata>>\n) {\n  if (metadata.status === 'aborted' || generation !== detailGeneration) return\n  const setup = activeDetail.value?.modelSetup\n  if (!setup) return\n\n  setup.result = deriveTemplateModelSetup(\n    requirements,\n    availability,\n    metadata,\n    { isDownloadable: isModelDownloadable }\n  )\n  setup.pending = false\n}\n\nfunction handleTemplateModelMetadataError(\n  error: unknown,\n  generation: number,\n  controller: AbortController\n) {\n  if (controller.signal.aborted || generation !== detailGeneration) return\n  const setup = activeDetail.value?.modelSetup\n  if (setup) setup.pending = false\n  reportError(error, {\n    surface: 'graph',\n    errorType: 'workflow_template_model_metadata_failed',\n    level: 'warning'\n  })\n}\n\nasync function updateTemplateModelMetadata(\n  generation: number,\n  controller: AbortController,\n  requirements: readonly TemplateModelRequirementDetail[],\n  availability: readonly ResolvedTemplateModelAvailability[]\n) {\n  try {\n    const metadata = await resolveTemplateModelMetadata(\n      requirements.map(({ model }) => model),\n      { signal: controller.signal }\n    )\n    applyTemplateModelMetadata(generation, requirements, availability, metadata)\n  } catch (error) {\n    handleTemplateModelMetadataError(error, generation, controller)\n  } finally {\n    if (modelMetadataController === controller) {\n      modelMetadataController = undefined\n    }\n  }\n}\n\nasync function openPreparedTemplate(\n  prepared: PreparedWorkflowTemplate,\n  generation: number\n): Promise<void> {\n  if (openPending.value || generation !== detailGeneration) return\n\n  openPending.value = true\n  try {\n    const result = await openPreparedWorkflowTemplate(prepared)\n    if (result === 'not-started') return\n\n    templateWasSelected.value = result === 'loaded'\n    onClose()\n  } finally {\n    openPending.value = false\n  }\n}\n\nasync function showModelSetupIfNeeded(\n  template: TemplateInfo,\n  prepared: PreparedWorkflowTemplate,\n  generation: number\n): Promise<boolean> {\n  if (!isDesktop) return false\n\n  const requirements = extractTemplateModelRequirementDetails(\n    prepared.data.json\n  )\n  const inputAssetsPromise =\n    prepared.sourceModule === 'default'\n      ? resolveTemplateInputAssets(template.name, () => window.__comfyDesktop2)\n      : Promise.resolve<readonly ComfyTemplateInputAsset[]>([])\n  if (requirements.length === 0) return false\n\n  // Only the Electron path needs real directories, and resolving them here\n  // rather than mid-dispatch keeps a download from depending on a lookup that\n  // can finish after this view is gone.\n  const [availability, folderPaths] = await Promise.all([\n    resolveModelAvailability(requirements.map(({ model }) => model)),\n    modelDownloadNeedsFolderPaths()\n      ? loadFolderPathsOnce().catch(() => ({}))\n      : Promise.resolve({})\n  ])\n  if (generation !== detailGeneration) return true\n  if (!availability.some(({ status }) => status === 'missing')) return false\n\n  const inputAssets = await inputAssetsPromise\n  if (generation !== detailGeneration) return true\n\n  const rowDownloads = useTemplateModelRowDownloads({ folderPaths })\n  activeDetail.value = {\n    template,\n    prepared: markRaw(prepared),\n    inputAssets,\n    modelSetup: {\n      result: deriveTemplateModelSetup(\n        requirements,\n        availability,\n        { status: 'aborted' },\n        { isDownloadable: isModelDownloadable }\n      ),\n      pending: true,\n      rowDownloads\n    }\n  }\n  const controller = new AbortController()\n  modelMetadataController = controller\n  await nextTick()\n  if (generation !== detailGeneration) return true\n  detailView.value?.focus()\n\n  void updateTemplateModelMetadata(\n    generation,\n    controller,\n    requirements,\n    availability\n  )\n  return true\n}\n\nconst onLoadWorkflow = async (template: TemplateInfo, event: MouseEvent) => {\n  if (openPending.value) return\n\n  invalidateDetailWork()\n  const generation = detailGeneration\n  detailOrigin =\n    event.currentTarget instanceof HTMLElement ? event.currentTarget : null\n  listScrollTop = modalLayout.value?.getContentScrollTop() ?? 0\n  const prepared = await prepareWorkflowTemplate(\n    template.name,\n    getEffectiveSourceModule(template)\n  )\n  if (!prepared) return\n  preparedInFlight = prepared\n  if (generation !== detailGeneration) {\n    releasePreparedDetail()\n    return\n  }\n\n  const didShowModelSetup = await showModelSetupIfNeeded(\n    template,\n    prepared,\n    generation\n  )\n  if (!didShowModelSetup) await openPreparedTemplate(prepared, generation)\n}\n\nasync function onBackToTemplates() {\n  if (openPending.value) return\n\n  activeDetail.value?.modelSetup.rowDownloads.dispose()\n  invalidateDetailWork()\n  activeDetail.value = null\n  await nextTick()\n  modalLayout.value?.setContentScrollTop(listScrollTop)\n  detailOrigin?.focus()\n}\n\nfunction onDownloadModel(rowId: string) {\n  const setup = activeDetail.value?.modelSetup\n  if (!setup) return\n\n  const row = setup.result.rows.find(\n    (candidate) =>\n      candidate.status === 'downloadable' &&\n      `model:${getModelFileKey(candidate.model)}` === rowId\n  )\n  if (row?.status === 'downloadable') setup.rowDownloads.request(row.model)\n}\n\nasync function onDownloadModelsAndOpen() {\n  const detail = activeDetail.value\n  const setup = detail?.modelSetup\n  if (!detail || !setup || setup.pending || openPending.value) return\n\n  for (const row of activeDetailModelDownloadCandidates.value) {\n    setup.rowDownloads.request(row.model)\n  }\n\n  await onOpenTemplate()\n}\n\nfunction onSelectNavItem(value: string | null) {\n  if (openPending.value) return\n\n  activeDetail.value?.modelSetup.rowDownloads.dispose()\n  invalidateDetailWork()\n  activeDetail.value = null\n  selectedNavItem.value = value\n}\n\nconst onOpenTemplate = async () => {\n  const detail = activeDetail.value\n  if (!detail || openPending.value) return\n\n  await openPreparedTemplate(detail.prepared, detailGeneration)\n}\n\nconst pageTitle = computed(() => {\n  const navItem = navItems.value.find((item) =>\n    'id' in item\n      ? item.id === selectedNavItem.value\n      : item.items?.some((sub) => sub.id === selectedNavItem.value)\n  )\n\n  if (!navItem) {\n    return t('templateWorkflows.allTemplates', 'All Templates')\n  }\n\n  return 'id' in navItem\n    ? navItem.label\n    : navItem.items?.find((i) => i.id === selectedNavItem.value)?.label ||\n        t('templateWorkflows.allTemplates', 'All Templates')\n})\n\nconst backToTemplatesLabel = computed(() =>\n  t(\n    'templateWorkflows.detail.backToTemplates',\n    { category: pageTitle.value },\n    { escapeParameter: false }\n  )\n)\n\nconst activeDetailTitle = computed(() => {\n  const detail = activeDetail.value\n  return detail\n    ? getTemplateTitle(detail.template, detail.prepared.sourceModule)\n    : ''\n})\n\nconst activeDetailCloudUrl = computed(() => {\n  const detail = activeDetail.value\n  if (\n    isCloud ||\n    !detail ||\n    detail.prepared.sourceModule !== 'default' ||\n    (detail.template.includeOnDistributions?.length &&\n      !detail.template.includeOnDistributions.includes(\n        TemplateIncludeOnDistributionEnum.Cloud\n      ))\n  ) {\n    return undefined\n  }\n\n  const url = new URL(getComfyCloudBaseUrl())\n  url.searchParams.set('template', detail.template.name)\n  return url.toString()\n})\n\n// Initialize templates loading with useAsyncState\nconst { isLoading } = useAsyncState(\n  async () => {\n    await Promise.all([\n      loadTemplates(),\n      workflowTemplatesStore.loadWorkflowTemplates()\n    ])\n    return true\n  },\n  false, // initial state\n  {\n    immediate: true // Start loading immediately\n  }\n)\n\nonBeforeUnmount(() => {\n  activeDetail.value?.modelSetup.rowDownloads.dispose()\n  invalidateDetailWork()\n  detailOrigin = null\n  cardRefs.value = [] // Release DOM refs\n})\n</script>\n","import { ref, shallowRef } from 'vue'\nimport { createSharedComposable } from '@vueuse/core'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { reportError } from '@/platform/telemetry/reportError'\n\nfunction hasV2DraftHistory(raw: string | null): boolean {\n  if (!raw) return false\n  let parsed: unknown\n  try {\n    parsed = JSON.parse(raw)\n  } catch {\n    reportError(new Error('Workflow draft index is not valid JSON'), {\n      surface: 'graph',\n      errorType: 'error_parsing_workflow_draft_index',\n      level: 'warning',\n      context: { length: raw.length }\n    })\n    return false\n  }\n  if (!parsed || typeof parsed !== 'object') return false\n  const { order, entries } = parsed as { order?: unknown; entries?: unknown }\n  const orderLength = Array.isArray(order) ? order.length : 0\n  const entriesCount =\n    entries && typeof entries === 'object' ? Object.keys(entries).length : 0\n  return orderLength > 0 || entriesCount > 0\n}\n\nfunction _useNewUserService() {\n  const settingStore = useSettingStore()\n  const pendingCallbacks = shallowRef<Array<() => Promise<void>>>([])\n  const isNewUserDetermined = ref(false)\n  const isNewUserCached = ref<boolean | null>(null)\n\n  function reset() {\n    pendingCallbacks.value = []\n    isNewUserDetermined.value = false\n    isNewUserCached.value = null\n  }\n\n  function checkIsNewUser(): boolean {\n    const isNewUserSettings =\n      Object.keys(settingStore.settingValues).length === 0 ||\n      !settingStore.get('Comfy.TutorialCompleted')\n\n    // Legacy keys (pre-V1 and V1 persistence)\n    const hasNoLegacyWorkflow =\n      !localStorage.getItem('workflow') &&\n      !localStorage.getItem('Comfy.PreviousWorkflow')\n\n    // V1 draft store keys\n    const hasNoV1Drafts =\n      !localStorage.getItem('Comfy.Workflow.Drafts') &&\n      !localStorage.getItem('Comfy.Workflow.DraftOrder')\n\n    // V2 draft index key (scoped to personal workspace; cloud workspace id\n    // comes from sessionStorage which may not be set yet at this point).\n    // Check for actual draft history rather than key existence: an empty\n    // index can be written for genuine new users during startup, so key\n    // presence alone is not evidence of prior usage.\n    const hasNoV2DraftIndex = !hasV2DraftHistory(\n      localStorage.getItem('Comfy.Workflow.DraftIndex.v2:personal')\n    )\n\n    return (\n      isNewUserSettings &&\n      hasNoLegacyWorkflow &&\n      hasNoV1Drafts &&\n      hasNoV2DraftIndex\n    )\n  }\n\n  async function registerInitCallback(callback: () => Promise<void>) {\n    if (isNewUserDetermined.value) {\n      if (isNewUserCached.value) {\n        try {\n          await callback()\n        } catch (error) {\n          console.error('New user initialization callback failed:', error)\n        }\n      }\n    } else {\n      pendingCallbacks.value = [...pendingCallbacks.value, callback]\n    }\n  }\n\n  async function initializeIfNewUser() {\n    if (isNewUserDetermined.value) return\n\n    isNewUserCached.value = checkIsNewUser()\n    isNewUserDetermined.value = true\n\n    if (!isNewUserCached.value) {\n      pendingCallbacks.value = []\n      return\n    }\n\n    await settingStore.set(\n      'Comfy.InstalledVersion',\n      __COMFYUI_FRONTEND_VERSION__\n    )\n\n    for (const callback of pendingCallbacks.value) {\n      try {\n        await callback()\n      } catch (error) {\n        console.error('New user initialization callback failed:', error)\n      }\n    }\n\n    pendingCallbacks.value = []\n  }\n\n  function isNewUser(): boolean | null {\n    return isNewUserDetermined.value ? isNewUserCached.value : null\n  }\n\n  return {\n    registerInitCallback,\n    initializeIfNewUser,\n    isNewUser,\n    reset\n  }\n}\n\nexport const useNewUserService = createSharedComposable(_useNewUserService)\n","import WorkflowTemplateSelectorDialog from '@/components/custom/widget/WorkflowTemplateSelectorDialog.vue'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { TemplateLibraryMetadata } from '@/platform/telemetry/types'\nimport { useDialogService } from '@/services/dialogService'\nimport { useNewUserService } from '@/services/useNewUserService'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst DIALOG_KEY = 'global-workflow-template-selector'\nconst POPULAR_CATEGORY_ID = 'popular'\n\nexport const useWorkflowTemplateSelectorDialog = () => {\n  const dialogService = useDialogService()\n  const dialogStore = useDialogStore()\n  const newUserService = useNewUserService()\n\n  function hide() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  function show(\n    source: TemplateLibraryMetadata['source'] = 'command',\n    options?: { initialCategory?: string; afterClose?: () => void }\n  ) {\n    useTelemetry()?.trackTemplateLibraryOpened({ source })\n\n    const initialCategory =\n      options?.initialCategory ??\n      (newUserService.isNewUser() ? POPULAR_CATEGORY_ID : 'all')\n\n    dialogService.showLayoutDialog({\n      key: DIALOG_KEY,\n      component: WorkflowTemplateSelectorDialog,\n      props: {\n        onClose: () => {\n          hide()\n          options?.afterClose?.()\n        },\n        initialCategory\n      }\n    })\n  }\n\n  return {\n    show,\n    hide\n  }\n}\n","<template>\n  <div\n    class=\"flex w-xl max-w-full min-w-116 flex-col rounded-2xl border border-border-default bg-base-background shadow-lg\"\n  >\n    <!-- Header -->\n    <div\n      class=\"flex h-12 items-center justify-between border-b border-border-default px-4\"\n    >\n      <div class=\"flex items-center gap-2\">\n        <slot name=\"header-icon\" />\n        <DialogTitle\n          as=\"h2\"\n          class=\"m-0 text-sm font-normal text-base-foreground\"\n        >\n          <slot name=\"title\" />\n        </DialogTitle>\n      </div>\n      <Button\n        v-if=\"showClose\"\n        variant=\"muted-textonly\"\n        class=\"-mr-1\"\n        :aria-label=\"$t('g.close')\"\n        @click=\"$emit('close')\"\n      >\n        <i class=\"pi pi-times size-4\" />\n      </Button>\n    </div>\n\n    <!-- Body -->\n    <div class=\"flex flex-1 flex-col gap-4 p-4\">\n      <slot />\n    </div>\n\n    <!-- Footer -->\n    <div class=\"flex items-center justify-end gap-4 p-4\">\n      <slot name=\"footer\" />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport DialogTitle from '@/components/ui/dialog/DialogTitle.vue'\n\nconst { showClose = true } = defineProps<{\n  showClose?: boolean\n}>()\n\ndefineEmits<{\n  close: []\n}>()\n</script>\n","<template>\n  <BuilderDialog\n    data-testid=\"builder-empty-workflow-dialog\"\n    :show-close=\"false\"\n  >\n    <template #title>\n      {{ $t('builderToolbar.emptyWorkflowTitle') }}\n    </template>\n\n    <div class=\"flex flex-col gap-2\">\n      <p class=\"m-0 text-sm text-muted-foreground\">\n        {{ $t('linearMode.emptyWorkflowExplanation') }}\n      </p>\n      <p class=\"m-0 text-sm text-muted-foreground\">\n        {{ $t('builderToolbar.emptyWorkflowPrompt') }}\n      </p>\n    </div>\n\n    <template #footer>\n      <Button\n        variant=\"muted-textonly\"\n        size=\"lg\"\n        data-testid=\"builder-empty-workflow-back\"\n        @click=\"$emit('backToWorkflow')\"\n      >\n        {{ $t('linearMode.backToWorkflow') }}\n      </Button>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        data-testid=\"builder-empty-workflow-load-template\"\n        @click=\"$emit('loadTemplate')\"\n      >\n        {{ $t('linearMode.loadTemplate') }}\n      </Button>\n    </template>\n  </BuilderDialog>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nimport BuilderDialog from './BuilderDialog.vue'\n\ndefineEmits<{\n  backToWorkflow: []\n  loadTemplate: []\n}>()\n</script>\n","import { useWorkflowTemplateSelectorDialog } from '@/composables/useWorkflowTemplateSelectorDialog'\nimport { app } from '@/scripts/app'\nimport { useDialogService } from '@/services/dialogService'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nimport EmptyWorkflowDialogContent from './EmptyWorkflowDialogContent.vue'\n\nconst DIALOG_KEY = 'builder-empty-workflow'\n\nexport function useEmptyWorkflowDialog() {\n  const dialogService = useDialogService()\n  const dialogStore = useDialogStore()\n  const templateSelectorDialog = useWorkflowTemplateSelectorDialog()\n\n  function show(options: {\n    onEnterBuilder: () => void\n    onDismiss: () => void\n  }) {\n    dialogService.showLayoutDialog({\n      key: DIALOG_KEY,\n      component: EmptyWorkflowDialogContent,\n      props: {\n        onBackToWorkflow: () => {\n          closeDialog()\n          options.onDismiss()\n        },\n        onLoadTemplate: () => {\n          closeDialog()\n          templateSelectorDialog.show('appbuilder', {\n            afterClose: () => {\n              if (app.rootGraphOrUndefined?.nodes.length)\n                options.onEnterBuilder()\n            }\n          })\n        }\n      }\n    })\n  }\n\n  function closeDialog() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  return { show }\n}\n","import { useAppMode } from '@/composables/useAppMode'\nimport { useAppModeStore } from '@/stores/appModeStore'\n\nimport { useEmptyWorkflowDialog } from './useEmptyWorkflowDialog'\n\nexport function useEnterBuilder() {\n  const appModeStore = useAppModeStore()\n  const { setMode } = useAppMode()\n  const emptyWorkflowDialog = useEmptyWorkflowDialog()\n\n  function enterBuilder() {\n    if (!appModeStore.hasNodes) {\n      emptyWorkflowDialog.show({\n        onEnterBuilder: appModeStore.enterBuilder,\n        onDismiss: () => setMode('graph')\n      })\n      return\n    }\n    appModeStore.enterBuilder()\n  }\n\n  return { enterBuilder }\n}\n","export async function openDeployToComfyApiDialog() {\n  const { useDeployToComfyApiDialog } =\n    await import('@/platform/workflow/deploy/composables/useDeployToComfyApiDialog')\n  useDeployToComfyApiDialog().show()\n}\n","export const DEPLOY_TO_COMFY_API_ACTION_ID = 'deploy-as-api'\n","export function prefetchShareDialog() {\n  importShareDialog().catch((error) => {\n    console.error(error)\n  })\n}\n\nexport async function openShareDialog() {\n  const { useShareDialog } = await importShareDialog()\n  useShareDialog().show()\n}\n\nfunction importShareDialog() {\n  return import('@/platform/workflow/sharing/composables/useShareDialog')\n}\n","import type { ComputedRef, Ref } from 'vue'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useEnterBuilder } from '@/components/builder/useEnterBuilder'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { isCloud } from '@/platform/distribution/types'\nimport { openDeployToComfyApiDialog } from '@/platform/workflow/deploy/composables/lazyDeployToComfyApiDialog'\nimport { DEPLOY_TO_COMFY_API_ACTION_ID } from '@/platform/workflow/deploy/constants'\nimport { openShareDialog } from '@/platform/workflow/sharing/composables/lazyShareDialog'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\nimport {\n  useWorkflowBookmarkStore,\n  useWorkflowStore\n} from '@/platform/workflow/management/stores/workflowStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useMenuItemStore } from '@/stores/menuItemStore'\nimport { useSubgraphStore } from '@/stores/subgraphStore'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport type {\n  WorkflowMenuAction,\n  WorkflowMenuItem\n} from '@/types/workflowMenuItem'\n\ninterface WorkflowActionsMenuOptions {\n  /** Whether this is the root workflow level. Defaults to true. */\n  isRoot?: boolean\n  /** Whether to include the delete workflow action. Defaults to true. */\n  includeDelete?: boolean\n  /** Override the workflow to operate on. If not provided, uses activeWorkflow. */\n  workflow?: Ref<ComfyWorkflow | null> | ComputedRef<ComfyWorkflow | null>\n}\n\ninterface AddItemOptions {\n  id: string\n  label: string\n  icon: string\n  command: () => void\n  visible?: boolean\n  disabled?: boolean\n  prependSeparator?: boolean\n  newItemBadge?: string\n}\n\nexport function useWorkflowActionsMenu(\n  startRename: () => void,\n  options: WorkflowActionsMenuOptions = {}\n) {\n  const { isRoot = true, includeDelete = true, workflow } = options\n  const { t } = useI18n()\n  const workflowStore = useWorkflowStore()\n  const workflowService = useWorkflowService()\n  const bookmarkStore = useWorkflowBookmarkStore()\n  const commandStore = useCommandStore()\n  const subgraphStore = useSubgraphStore()\n  const menuItemStore = useMenuItemStore()\n  const { flags } = useFeatureFlags()\n  const appModeStore = useAppModeStore()\n  const { pruneLinearData } = appModeStore\n  const { enterBuilder } = useEnterBuilder()\n  const { toastErrorHandler } = useErrorHandling()\n\n  const targetWorkflow = computed(\n    () => workflow?.value ?? workflowStore.activeWorkflow\n  )\n\n  /** Switch to the target workflow tab if it's not already active */\n  const ensureWorkflowActive = async (wf: ComfyWorkflow | null) => {\n    if (!wf || wf === workflowStore.activeWorkflow) return true\n    return await workflowService.openWorkflow(wf)\n  }\n\n  const menuItems = computed<WorkflowMenuItem[]>(() => {\n    const workflow = targetWorkflow.value\n    const isBlueprint = workflow\n      ? subgraphStore.isSubgraphBlueprint(workflow)\n      : false\n\n    const items: WorkflowMenuItem[] = []\n\n    const addItem = ({\n      id,\n      label,\n      icon,\n      command,\n      visible = true,\n      disabled = false,\n      prependSeparator = false,\n      newItemBadge\n    }: AddItemOptions) => {\n      if (prependSeparator && visible) items.push({ separator: true })\n      const item: WorkflowMenuAction = { id, label, icon, command, disabled }\n      if (!visible) item.visible = false\n      if (newItemBadge) {\n        item.isNew = true\n        item.badge = newItemBadge\n      }\n      items.push(item)\n    }\n\n    const workflowMode =\n      workflow?.activeMode ?? workflow?.initialMode ?? 'graph'\n    const isLinearMode = workflowMode === 'app'\n    const showAppModeItems =\n      isRoot && (menuItemStore.hasSeenLinear || flags.linearToggleEnabled)\n    const isBookmarked = bookmarkStore.isBookmarked(workflow?.path ?? '')\n\n    const toggleLinear = async () => {\n      await ensureWorkflowActive(targetWorkflow.value)\n      await commandStore.execute('Comfy.ToggleLinear', {\n        metadata: { source: 'breadcrumb_menu' }\n      })\n    }\n    addItem({\n      id: 'rename',\n      label: t('g.rename'),\n      icon: 'pi pi-pencil',\n      command: async () => {\n        await ensureWorkflowActive(targetWorkflow.value)\n        startRename()\n      },\n      disabled: isRoot && !workflow?.isPersisted\n    })\n\n    addItem({\n      id: 'duplicate',\n      label: t('breadcrumbsMenu.duplicate'),\n      icon: 'pi pi-copy',\n      command: async () => {\n        if (workflow) {\n          await workflowService.duplicateWorkflow(workflow)\n        }\n      },\n      visible: isRoot && !isBlueprint\n    })\n\n    addItem({\n      id: 'toggle-bookmark',\n      label: isBookmarked\n        ? t('tabMenu.removeFromBookmarks')\n        : t('tabMenu.addToBookmarks'),\n      icon: 'pi pi-bookmark' + (isBookmarked ? '-fill' : ''),\n      command: async () => {\n        if (workflow?.path) {\n          await bookmarkStore.toggleBookmarked(workflow.path)\n        }\n      },\n      visible: isRoot,\n      disabled: workflow?.isTemporary ?? false\n    })\n\n    addItem({\n      id: 'save',\n      label: t('menuLabels.Save'),\n      icon: 'pi pi-save',\n      command: async () => {\n        await ensureWorkflowActive(workflow)\n        await commandStore.execute('Comfy.SaveWorkflow')\n      },\n      visible: isRoot,\n      prependSeparator: true\n    })\n\n    addItem({\n      id: 'save-as',\n      label: t('menuLabels.Save As'),\n      icon: 'pi pi-save',\n      command: async () => {\n        await ensureWorkflowActive(workflow)\n        await commandStore.execute('Comfy.SaveWorkflowAs')\n      },\n      visible: isRoot\n    })\n\n    addItem({\n      id: 'export',\n      label: t('menuLabels.Export'),\n      icon: 'pi pi-download',\n      command: async () => {\n        await ensureWorkflowActive(workflow)\n        await commandStore.execute('Comfy.ExportWorkflow')\n      },\n      visible: isRoot,\n      prependSeparator: true\n    })\n\n    addItem({\n      id: 'export-api',\n      label: t('menuLabels.Export (API)'),\n      icon: 'pi pi-download',\n      command: async () => {\n        await ensureWorkflowActive(workflow)\n        await commandStore.execute('Comfy.ExportWorkflowAPI')\n      },\n      visible: isRoot\n    })\n\n    addItem({\n      id: 'share',\n      label: t('breadcrumbsMenu.share'),\n      icon: 'icon-[comfy--send]',\n      command: () => openShareDialog().catch(toastErrorHandler),\n      visible: isCloud\n    })\n\n    addItem({\n      id: DEPLOY_TO_COMFY_API_ACTION_ID,\n      label: t('deployToComfyApi.buttonLabel'),\n      icon: 'icon-[lucide--rocket]',\n      command: async () => {\n        if (!(await ensureWorkflowActive(targetWorkflow.value))) return\n        await openDeployToComfyApiDialog().catch(toastErrorHandler)\n      },\n      visible: isRoot,\n      newItemBadge: t('g.new')\n    })\n\n    addItem({\n      id: 'enter-app-mode',\n      label: t('breadcrumbsMenu.enterAppMode'),\n      icon: 'icon-[lucide--panels-top-left]',\n      command: toggleLinear,\n      visible: showAppModeItems && !isLinearMode,\n      prependSeparator: true,\n      newItemBadge: t('g.experimental')\n    })\n\n    addItem({\n      id: 'exit-app-mode',\n      label: t('breadcrumbsMenu.exitAppMode'),\n      icon: 'icon-[comfy--workflow]',\n      command: toggleLinear,\n      visible: isLinearMode,\n      prependSeparator: true\n    })\n\n    if (!workflow) return items\n    const isActive = workflow === workflowStore.activeWorkflow\n    const getLinearData = (\n      tracker: typeof workflow.changeTracker | undefined\n    ) => {\n      if (!tracker) return undefined\n      return tracker.activeState.extra?.linearData\n    }\n    const rawLd = isActive\n      ? {\n          inputs: appModeStore.selectedInputs,\n          outputs: appModeStore.selectedOutputs\n        }\n      : getLinearData(workflow.changeTracker)\n    let hasLinearData: boolean\n    if (rawLd) {\n      const { inputs, outputs } = pruneLinearData(rawLd)\n      hasLinearData = inputs.length > 0 || outputs.length > 0\n    } else {\n      hasLinearData = workflow.path.endsWith('.app.json')\n    }\n\n    addItem({\n      id: 'enter-builder-mode',\n      label: hasLinearData\n        ? t('breadcrumbsMenu.editBuilderMode')\n        : t('breadcrumbsMenu.enterBuilderMode'),\n      icon: 'icon-[lucide--hammer]',\n      command: async () => {\n        await ensureWorkflowActive(targetWorkflow.value)\n        enterBuilder()\n      },\n      visible: showAppModeItems,\n      newItemBadge: t('g.experimental')\n    })\n\n    addItem({\n      id: 'clear-workflow',\n      label: t('breadcrumbsMenu.clearWorkflow'),\n      icon: 'pi pi-trash',\n      command: async () => {\n        await ensureWorkflowActive(workflow)\n        await commandStore.execute('Comfy.ClearWorkflow')\n      },\n      prependSeparator: true\n    })\n\n    addItem({\n      id: 'publish',\n      label: t('subgraphStore.publish'),\n      icon: 'pi pi-upload',\n      command: async () => await workflowService.saveWorkflowAs(workflow),\n      visible: isRoot && isBlueprint,\n      prependSeparator: true\n    })\n\n    addItem({\n      id: 'delete',\n      label: isBlueprint\n        ? t('breadcrumbsMenu.deleteBlueprint')\n        : t('breadcrumbsMenu.deleteWorkflow'),\n      icon: 'pi pi-times',\n      command: async () => await workflowService.deleteWorkflow(workflow),\n      visible: isRoot && includeDelete,\n      prependSeparator: true\n    })\n\n    return items\n  })\n\n  return {\n    menuItems\n  }\n}\n","import { unref } from 'vue'\nimport type { MaybeRef } from 'vue'\n\nimport type {\n  LGraph,\n  LGraphNode,\n  Subgraph\n} from '@/lib/litegraph/src/litegraph'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { collectAllNodes } from '@/utils/graphTraversalUtil'\n\nexport type NodeDefLookup = Record<string, ComfyNodeDefImpl | undefined>\n\nconst isNodeMissingDefinition = (\n  node: LGraphNode,\n  nodeDefsByName: NodeDefLookup\n) => {\n  const nodeName = node.type\n  if (!nodeName) return false\n  return !nodeDefsByName[nodeName]\n}\n\nexport const collectMissingNodes = (\n  graph: LGraph | Subgraph | null | undefined,\n  nodeDefsByName: MaybeRef<NodeDefLookup>\n): LGraphNode[] => {\n  if (!graph) return []\n  const lookup = unref(nodeDefsByName)\n  return collectAllNodes(graph, (node) => isNodeMissingDefinition(node, lookup))\n}\n\nexport const graphHasMissingNodes = (\n  graph: LGraph | Subgraph | null | undefined,\n  nodeDefsByName: MaybeRef<NodeDefLookup>\n) => {\n  return collectMissingNodes(graph, nodeDefsByName).length > 0\n}\n","<template>\n  <DefineTrigger>\n    <Button\n      variant=\"textonly\"\n      size=\"unset\"\n      :tooltip=\"tooltipText\"\n      tooltip-side=\"bottom\"\n      :data-testid=\"`subgraph-breadcrumb-item-${item.key}`\"\n      :data-active=\"isActive ? '' : undefined\"\n      draggable=\"false\"\n      :class=\"\n        cn(\n          'p-breadcrumb-item-link flex h-8 cursor-pointer appearance-none items-center justify-start gap-0 overflow-hidden border-none bg-transparent px-2 py-0 text-inherit select-none [font:inherit] hover:bg-transparent',\n          isActive &&\n            'p-breadcrumb-item-link-icon-visible gap-1 text-text-primary',\n          menuOpen && 'p-breadcrumb-item-link-menu-visible'\n        )\n      \"\n      @click=\"handleClick\"\n      @keydown=\"handleKeydown\"\n    >\n      <i\n        v-if=\"hasMissingNodes && isRoot\"\n        data-testid=\"subgraph-breadcrumb-missing-nodes-icon\"\n        class=\"icon-[lucide--triangle-alert] text-warning-background\"\n      />\n      <span\n        ref=\"labelRef\"\n        class=\"p-breadcrumb-item-label max-w-72 truncate px-2\"\n      >\n        {{ item.label }}\n      </span>\n      <Badge\n        v-if=\"item.isBlueprint\"\n        data-testid=\"subgraph-breadcrumb-blueprint-tag\"\n        severity=\"primary\"\n      >\n        {{ t('breadcrumbsMenu.blueprint') }}\n      </Badge>\n      <i v-if=\"isActive\" class=\"pi pi-angle-down text-2xs\"></i>\n    </Button>\n  </DefineTrigger>\n  <Menu\n    v-if=\"isActive\"\n    :open=\"menuOpen\"\n    :items=\"menuItems\"\n    :data-testid=\"`subgraph-breadcrumb-menu-${item.key}`\"\n    @update:open=\"menuOpen = Boolean($event && !isEditing)\"\n    @close-auto-focus=\"onMenuCloseAutoFocus\"\n  >\n    <template #trigger><ReuseTrigger /></template>\n  </Menu>\n  <ReuseTrigger v-else />\n  <Input\n    v-if=\"isEditing\"\n    ref=\"itemInputRef\"\n    v-model=\"itemLabel\"\n    data-testid=\"subgraph-breadcrumb-rename-input\"\n    class=\"fixed z-10000 w-50 p-2 text-[.8rem]\"\n    @blur=\"inputBlur(false)\"\n    @click.stop\n    @keydown.enter=\"inputBlur(true)\"\n    @keydown.esc=\"inputBlur(false)\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { createReusableTemplate } from '@vueuse/core'\nimport { computed, nextTick, ref, toValue } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Input from '@/components/ui/input/Input.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItemAction } from '@/components/ui/menu/types'\nimport { useWorkflowActionsMenu } from '@/composables/useWorkflowActionsMenu'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport {\n  ComfyWorkflow,\n  useWorkflowStore\n} from '@/platform/workflow/management/stores/workflowStore'\nimport { app } from '@/scripts/app'\nimport { useDialogService } from '@/services/dialogService'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { isMissingWarningVisible } from '@/platform/settings/missingWarningVisibility'\nimport { useSubgraphNavigationStore } from '@/stores/subgraphNavigationStore'\nimport { ensureWorkflowSuffix, getWorkflowSuffix } from '@/utils/formatUtil'\nimport { graphHasMissingNodes } from '@/workbench/extensions/manager/utils/graphHasMissingNodes'\n\nexport interface BreadcrumbItem extends MenuItemAction {\n  isBlueprint?: boolean\n  updateTitle?: (title: string) => void\n}\n\ninterface Props {\n  item: BreadcrumbItem\n  isActive?: boolean\n}\n\nconst { item, isActive } = defineProps<Props>()\nconst [DefineTrigger, ReuseTrigger] = createReusableTemplate()\n\nconst nodeDefStore = useNodeDefStore()\nconst hasMissingNodes = computed(\n  () =>\n    isMissingWarningVisible('nodes') &&\n    graphHasMissingNodes(app.rootGraph, nodeDefStore.nodeDefsByName)\n)\n\nconst { t } = useI18n()\nconst menuOpen = ref(false)\nconst dialogService = useDialogService()\nconst workflowStore = useWorkflowStore()\nconst workflowService = useWorkflowService()\nconst isEditing = ref(false)\nconst itemLabel = ref<string>()\nconst itemInputRef = ref<InstanceType<typeof Input>>()\nconst labelRef = ref<HTMLSpanElement>()\n\nconst rename = async (\n  newName: string | null | undefined,\n  initialName: string\n) => {\n  if (newName && newName !== initialName) {\n    // Synchronize the node titles with the new name\n    item.updateTitle?.(newName)\n\n    if (workflowStore.activeSubgraph) {\n      workflowStore.activeSubgraph.name = newName\n    } else if (workflowStore.activeWorkflow) {\n      try {\n        const suffix = getWorkflowSuffix(workflowStore.activeWorkflow.suffix)\n        await workflowService.renameWorkflow(\n          workflowStore.activeWorkflow,\n          ComfyWorkflow.basePath + ensureWorkflowSuffix(newName, suffix)\n        )\n      } catch (error) {\n        console.error(error)\n        dialogService.showErrorDialog(error)\n        return\n      }\n    }\n\n    // Force the navigation stack to recompute the labels\n    // TODO: investigate if there is a better way to do this\n    const navigationStore = useSubgraphNavigationStore()\n    navigationStore.restoreState(navigationStore.exportState())\n  }\n}\n\nconst isRoot = item.key === 'root'\n\nconst tooltipText = computed(() => {\n  if (hasMissingNodes.value && isRoot) {\n    return t('breadcrumbsMenu.missingNodesWarning')\n  }\n  return toValue(item.label)\n})\n\nconst startRename = async () => {\n  // Check if element is hidden (collapsed breadcrumb)\n  // When collapsed, root item is hidden via CSS display:none, so use rename command\n  if (isRoot && labelRef.value?.offsetParent === null) {\n    await useCommandStore().execute('Comfy.RenameWorkflow')\n    return\n  }\n\n  isEditing.value = true\n  itemLabel.value = item.label as string\n  void nextTick(() => {\n    itemInputRef.value?.focus()\n    itemInputRef.value?.select()\n  })\n}\n\nconst { menuItems } = useWorkflowActionsMenu(startRename, { isRoot })\n\nfunction onMenuCloseAutoFocus(event: Event) {\n  if (isEditing.value) event.preventDefault()\n}\n\nfunction handleKeydown(event: KeyboardEvent) {\n  if (isActive || isEditing.value || !['Enter', ' '].includes(event.key)) return\n  event.preventDefault()\n  event.stopPropagation()\n  item.command?.({ item, originalEvent: event })\n}\n\nconst handleClick = (event: MouseEvent) => {\n  if (isEditing.value) {\n    return\n  }\n\n  if (event.detail === 1) {\n    if (!isActive) {\n      item.command?.({ item: item, originalEvent: event })\n    }\n  } else if (isActive && event.detail === 2) {\n    menuOpen.value = false\n    event.stopPropagation()\n    event.preventDefault()\n    void startRename()\n  }\n}\n\nconst inputBlur = async (doRename: boolean) => {\n  if (doRename) {\n    await rename(itemLabel.value, item.label as string)\n  }\n\n  isEditing.value = false\n}\n</script>\n","import type { MaybeRefOrGetter } from 'vue'\nimport { computed, toValue } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type {\n  WorkflowMenuAction,\n  WorkflowMenuItem\n} from '@/types/workflowMenuItem'\n\nfunction getNewActions(items: WorkflowMenuItem[]): WorkflowMenuAction[] {\n  return items\n    .filter((i): i is WorkflowMenuAction => !('separator' in i && i.separator))\n    .filter((i) => i.isNew)\n}\n\nexport function useNewMenuItemIndicator(\n  menuItems: MaybeRefOrGetter<WorkflowMenuItem[]>\n) {\n  const settingStore = useSettingStore()\n\n  const newActions = computed(() => getNewActions(toValue(menuItems)))\n\n  const seenItems = computed<string[]>(() =>\n    settingStore.get('Comfy.WorkflowActions.SeenItems')\n  )\n\n  const hasUnseenItems = computed(() => {\n    const seen = new Set(seenItems.value)\n    return newActions.value\n      .filter((i) => i.visible !== false)\n      .some((i) => !seen.has(i.id))\n  })\n\n  function markAsSeen() {\n    const actions = newActions.value\n    if (!actions.length) return\n\n    const seen = new Set(seenItems.value)\n    const visibleIds = actions\n      .filter((i) => i.visible !== false)\n      .map((i) => i.id)\n    const retainedIds = actions\n      .filter((i) => i.visible === false && seen.has(i.id))\n      .map((i) => i.id)\n\n    const nextSeen = [...visibleIds, ...retainedIds]\n    if (nextSeen.length === seen.size && nextSeen.every((id) => seen.has(id)))\n      return\n\n    void settingStore.set('Comfy.WorkflowActions.SeenItems', nextSeen)\n  }\n\n  return { hasUnseenItems, markAsSeen }\n}\n","<script lang=\"ts\">\n// A segment switch unmounts the focused toggle instance and mounts a fresh\n// one in the other mode's host, so the focus handoff is tracked at module\n// scope where both instances can reach it.\nlet restoreFocusOnMount = false\n</script>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { computed, nextTick, onMounted, ref, useTemplateRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport { useNewMenuItemIndicator } from '@/composables/useNewMenuItemIndicator'\nimport { useWorkflowActionsMenu } from '@/composables/useWorkflowActionsMenu'\nimport { useKeybindingStore } from '@/platform/keybindings/keybindingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport type { ViewMode } from '@/utils/appMode'\n\ninterface ViewModeSegment {\n  mode: ViewMode\n  icon: string\n  label: string\n  switchLabel: string\n  switchTooltip: string\n  /** Drives behavior and aria; flips as soon as the mode changes. */\n  active: boolean\n  /** Frame-lagged mirror of {@link active} that drives the morph order. */\n  displayActive: boolean\n}\n\nconst { source, align = 'start' } = defineProps<{\n  source: string\n  align?: 'start' | 'center' | 'end'\n}>()\n\nconst { t } = useI18n()\nconst keybindingStore = useKeybindingStore()\nconst dropdownOpen = ref(false)\nconst appModeStore = useAppModeStore()\n\nconst { menuItems } = useWorkflowActionsMenu(\n  () => useCommandStore().execute('Comfy.RenameWorkflow'),\n  { isRoot: true }\n)\nconst { hasUnseenItems, markAsSeen } = useNewMenuItemIndicator(\n  () => menuItems.value\n)\n\nconst toggleShortcut = computed(() => {\n  const shortcut = keybindingStore\n    .getKeybindingByCommandId('Comfy.ToggleLinear')\n    ?.combo.toString()\n  return shortcut ? t('g.shortcutSuffix', { shortcut }) : ''\n})\n\nconst segments = computed<ViewModeSegment[]>(() =>\n  (\n    [\n      {\n        mode: 'graph',\n        icon: 'icon-[comfy--workflow]',\n        label: t('breadcrumbsMenu.graph'),\n        switchLabel: t('breadcrumbsMenu.enterNodeGraph'),\n        switchTooltip:\n          t('breadcrumbsMenu.enterNodeGraph') + toggleShortcut.value\n      },\n      {\n        mode: 'app',\n        icon: 'icon-[lucide--panels-top-left]',\n        label: t('breadcrumbsMenu.app'),\n        switchLabel: t('breadcrumbsMenu.enterAppMode'),\n        switchTooltip: t('breadcrumbsMenu.enterAppMode') + toggleShortcut.value\n      }\n    ] as const\n  ).map((seg) => ({\n    ...seg,\n    active: appModeStore.viewMode === seg.mode,\n    displayActive: appModeStore.displayViewMode === seg.mode\n  }))\n)\n\n// Display-inactive segment first (left), display-active last (right). The\n// reorder on mode switch is what TransitionGroup FLIP-animates.\nconst orderedSegments = computed(() => {\n  const [graph, app] = segments.value\n  return graph.displayActive ? [app, graph] : [graph, app]\n})\n\nfunction onOpenChange(open: boolean) {\n  dropdownOpen.value = open\n  if (!open) return\n  markAsSeen()\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: source,\n    element_group: 'workflow_actions'\n  })\n}\n\nfunction switchMode() {\n  dropdownOpen.value = false\n  restoreFocusOnMount = true\n  void useCommandStore().execute('Comfy.ToggleLinear', {\n    metadata: { source }\n  })\n}\n\nfunction segmentLabel(seg: ViewModeSegment) {\n  return seg.active\n    ? t('breadcrumbsMenu.activeModeWorkflowActions', { mode: seg.label })\n    : seg.switchLabel\n}\n\nfunction segmentTooltip(seg: ViewModeSegment) {\n  return seg.active ? t('breadcrumbsMenu.workflowActions') : seg.switchTooltip\n}\n\nfunction onSegmentClick(seg: ViewModeSegment, event: MouseEvent) {\n  if (seg.active) return\n  event.stopPropagation()\n  switchMode()\n}\n\n/** Keys the reka trigger opens the menu on; other keys bubble on so app-level\n *  keybindings keep working while a segment has focus. */\nconst MENU_TRIGGER_KEYS = new Set(['Enter', ' ', 'ArrowDown'])\n\nfunction onSegmentKeydown(seg: ViewModeSegment, event: KeyboardEvent) {\n  if (!seg.active && MENU_TRIGGER_KEYS.has(event.key)) event.stopPropagation()\n}\n\nconst toggleRef = useTemplateRef<HTMLDivElement>('toggleRef')\n\n// The trigger div carries role=\"group\" (permitting the aria-label, prohibited\n// on a plain div, that names the menu via reka's aria-labelledby) and\n// tabindex=\"-1\" so reka's close-focus (e.g. Escape closing the menu) lands\n// there; its @focus forwards focus here, to the active segment. Also called\n// when this instance mounts to replace the one unmounted by a\n// segment-initiated mode switch.\nfunction focusActiveSegment() {\n  toggleRef.value\n    ?.querySelector<HTMLButtonElement>('button[aria-haspopup]')\n    ?.focus()\n}\n\nonMounted(async () => {\n  if (!restoreFocusOnMount) return\n  restoreFocusOnMount = false\n  await nextTick()\n  focusActiveSegment()\n})\n</script>\n\n<template>\n  <Menu\n    v-model:open=\"dropdownOpen\"\n    :items=\"menuItems\"\n    :modal=\"false\"\n    :align\n    :side-offset=\"8\"\n    :collision-padding=\"10\"\n    class=\"min-w-56\"\n    @update:open=\"onOpenChange\"\n  >\n    <template #trigger>\n      <div\n        ref=\"toggleRef\"\n        data-testid=\"view-mode-toggle\"\n        role=\"group\"\n        tabindex=\"-1\"\n        :aria-label=\"t('breadcrumbsMenu.workflowActions')\"\n        class=\"group pointer-events-auto relative inline-block shrink-0 floating-panel\"\n        @focus=\"focusActiveSegment\"\n      >\n        <TransitionGroup\n          tag=\"div\"\n          move-class=\"transition-[background-color,color,transform] duration-200\"\n          class=\"flex items-center gap-1\"\n        >\n          <div v-for=\"seg in orderedSegments\" :key=\"seg.mode\" class=\"flex\">\n            <Button\n              :tooltip=\"segmentTooltip(seg)\"\n              tooltip-side=\"bottom\"\n              type=\"button\"\n              variant=\"textonly\"\n              size=\"unset\"\n              :aria-label=\"segmentLabel(seg)\"\n              :aria-haspopup=\"seg.active ? 'menu' : undefined\"\n              :aria-expanded=\"seg.active ? dropdownOpen : undefined\"\n              :class=\"\n                cn(\n                  'relative flex h-8 items-center gap-0 rounded-lg font-normal transition-[background-color,color,transform] duration-200',\n                  seg.displayActive\n                    ? 'bg-secondary-background pr-2 pl-2.5 text-base-foreground group-data-[state=open]:bg-secondary-background-hover group-data-[state=open]:shadow-interface hover:bg-secondary-background'\n                    : 'w-8 justify-center bg-transparent text-muted-foreground hover:bg-secondary-background hover:text-base-foreground'\n                )\n              \"\n              @click=\"onSegmentClick(seg, $event)\"\n              @keydown=\"onSegmentKeydown(seg, $event)\"\n            >\n              <i :class=\"cn('size-4 shrink-0', seg.icon)\" aria-hidden=\"true\" />\n              <span\n                :class=\"\n                  cn(\n                    'grid transition-[grid-template-columns,opacity] duration-200',\n                    seg.displayActive\n                      ? 'ml-1.5 grid-cols-[1fr] opacity-100'\n                      : 'grid-cols-[0fr] opacity-0'\n                  )\n                \"\n              >\n                <span\n                  class=\"flex min-w-0 items-center overflow-hidden text-sm leading-none whitespace-nowrap\"\n                >\n                  {{ seg.label }}\n                  <i\n                    class=\"ml-1 icon-[lucide--chevron-down] size-4 shrink-0 text-muted-foreground\"\n                    aria-hidden=\"true\"\n                  />\n                </span>\n              </span>\n              <span\n                v-if=\"seg.active && hasUnseenItems\"\n                aria-hidden=\"true\"\n                class=\"absolute -top-0.5 -right-0.5 size-2 rounded-full bg-primary-background\"\n              />\n            </Button>\n          </div>\n        </TransitionGroup>\n      </div>\n    </template>\n  </Menu>\n</template>\n","import { useMutationObserver, useResizeObserver } from '@vueuse/core'\nimport { debounce } from 'es-toolkit/compat'\nimport { readonly, ref, toValue } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\n/**\n * Observes an element for overflow changes and optionally debounces the check\n * @param element - The element to observe\n * @param options - The options for the observer\n * @param options.debounceTime - The time to debounce the check in milliseconds\n * @param options.useMutationObserver - Whether to use a mutation observer to check for overflow\n * @param options.useResizeObserver - Whether to use a resize observer to check for overflow\n * @returns An object containing the isOverflowing state and the checkOverflow function to manually trigger\n */\nexport const useOverflowObserver = (\n  element: MaybeRefOrGetter<HTMLElement | null | undefined>,\n  options?: {\n    debounceTime?: number\n    useMutationObserver?: boolean\n    useResizeObserver?: boolean\n    onCheck?: (isOverflowing: boolean) => void\n  }\n) => {\n  options = {\n    debounceTime: 25,\n    useMutationObserver: true,\n    useResizeObserver: true,\n    ...options\n  }\n\n  const isOverflowing = ref(false)\n  const disposeFns: (() => void)[] = []\n  const disposed = ref(false)\n\n  const checkOverflowFn = () => {\n    const resolvedElement = toValue(element)\n    isOverflowing.value = resolvedElement\n      ? resolvedElement.scrollWidth > resolvedElement.clientWidth\n      : false\n    options.onCheck?.(isOverflowing.value)\n  }\n\n  const checkOverflow = options.debounceTime\n    ? debounce(checkOverflowFn, options.debounceTime)\n    : checkOverflowFn\n\n  if (options.useMutationObserver) {\n    disposeFns.push(\n      useMutationObserver(element, checkOverflow, {\n        subtree: true,\n        childList: true\n      }).stop\n    )\n  }\n  if (options.useResizeObserver) {\n    disposeFns.push(useResizeObserver(element, checkOverflow).stop)\n  }\n\n  return {\n    isOverflowing: readonly(isOverflowing),\n    disposed: readonly(disposed),\n    checkOverflow,\n    dispose: () => {\n      disposed.value = true\n      disposeFns.forEach((fn) => fn())\n    }\n  }\n}\n","<template>\n  <div\n    data-testid=\"subgraph-breadcrumb\"\n    :class=\"\n      cn(\n        'subgraph-breadcrumb flex w-auto items-center drop-shadow-(--interface-panel-drop-shadow)',\n        {\n          'subgraph-breadcrumb-collapse': collapseTabs,\n          'subgraph-breadcrumb-overflow': overflowingTabs\n        }\n      )\n    \"\n    :style=\"{\n      '--breadcrumb-item-margin': `${ITEM_GAP / 2}px`,\n      '--breadcrumb-item-min-width': `${MIN_WIDTH}px`,\n      '--breadcrumb-item-padding': `${ITEM_PADDING}px`\n    }\"\n  >\n    <WorkflowActionsDropdown\n      v-if=\"!canvasStore.linearMode\"\n      source=\"breadcrumb_subgraph_menu_selected\"\n    />\n    <Button\n      v-if=\"isInSubgraph\"\n      class=\"back-button pointer-events-auto ml-1.5 size-8 shrink-0 border border-transparent bg-transparent p-0 transition-all hover:rounded-lg hover:border-interface-stroke hover:bg-comfy-menu-bg\"\n      data-testid=\"subgraph-breadcrumb-back\"\n      variant=\"muted-textonly\"\n      size=\"icon\"\n      @click=\"handleBackClick\"\n    >\n      <i class=\"icon-[lucide--undo-2]\" />\n    </Button>\n    <nav\n      ref=\"breadcrumbRef\"\n      :class=\"\n        cn('p-breadcrumb w-fit rounded-lg p-0', !isInSubgraph && 'hidden')\n      \"\n      :aria-label=\"$t('g.graphNavigation')\"\n    >\n      <ol\n        class=\"p-breadcrumb-list m-0 flex list-none items-center p-0 text-muted\"\n      >\n        <template v-for=\"(item, index) in items\" :key=\"item.key\">\n          <li\n            class=\"p-breadcrumb-item pointer-events-auto hover:text-base-foreground\"\n          >\n            <SubgraphBreadcrumbItem\n              :item\n              :is-active=\"item.key === activeItemKey\"\n            />\n          </li>\n          <li\n            v-if=\"index < items.length - 1\"\n            class=\"p-breadcrumb-separator\"\n            aria-hidden=\"true\"\n          >\n            <span class=\"scale-150\">/</span>\n          </li>\n        </template>\n      </ol>\n    </nav>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { computed, onBeforeUnmount, onMounted, onUpdated, ref } from 'vue'\n\nimport SubgraphBreadcrumbItem from '@/components/breadcrumb/SubgraphBreadcrumbItem.vue'\nimport type { BreadcrumbItem } from '@/components/breadcrumb/SubgraphBreadcrumbItem.vue'\nimport WorkflowActionsDropdown from '@/components/common/WorkflowActionsDropdown.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useOverflowObserver } from '@/composables/element/useOverflowObserver'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useSubgraphNavigationStore } from '@/stores/subgraphNavigationStore'\nimport { useSubgraphStore } from '@/stores/subgraphStore'\nimport { forEachSubgraphNode } from '@/utils/graphTraversalUtil'\n\nconst MIN_WIDTH = 28\nconst ITEM_GAP = 8\nconst ITEM_PADDING = 8\nconst ICON_WIDTH = 20\n\nconst workflowStore = useWorkflowStore()\nconst navigationStore = useSubgraphNavigationStore()\nconst canvasStore = useCanvasStore()\nconst breadcrumbRef = ref<HTMLElement | null>(null)\nconst workflowName = computed(() => workflowStore.activeWorkflow?.filename)\nconst isBlueprint = computed(() =>\n  useSubgraphStore().isSubgraphBlueprint(workflowStore.activeWorkflow)\n)\nconst collapseTabs = ref(false)\nconst overflowingTabs = ref(false)\n\nconst isInSubgraph = computed(() => navigationStore.navigationStack.length > 0)\n\nconst home = computed(() => ({\n  label: workflowName.value,\n  icon: 'pi pi-home',\n  key: 'root',\n  isBlueprint: isBlueprint.value,\n  command: () => {\n    useTelemetry()?.trackUiButtonClicked({\n      button_id: 'breadcrumb_subgraph_root_selected',\n      element_group: 'breadcrumb'\n    })\n    const canvas = canvasStore.getCanvas()\n    if (!canvas.graph) throw new TypeError('Canvas has no graph')\n\n    canvas.setGraph(canvas.graph.rootGraph)\n  }\n}))\n\nconst items = computed(() => {\n  const items = navigationStore.navigationStack.map<BreadcrumbItem>(\n    (subgraph) => ({\n      label: subgraph.name,\n      key: `subgraph-${subgraph.id}`,\n      command: () => {\n        useTelemetry()?.trackUiButtonClicked({\n          button_id: 'breadcrumb_subgraph_item_selected',\n          element_group: 'breadcrumb'\n        })\n        const canvas = canvasStore.getCanvas()\n        if (!canvas.graph) throw new TypeError('Canvas has no graph')\n\n        canvas.setGraph(subgraph)\n      },\n      updateTitle: (title: string) => {\n        const rootGraph = canvasStore.getCanvas().graph?.rootGraph\n        if (!rootGraph) return\n\n        forEachSubgraphNode(rootGraph, subgraph.id, (node) => {\n          node.title = title\n        })\n      }\n    })\n  )\n\n  return [home.value, ...items]\n})\n\nconst activeItemKey = computed(() => items.value.at(-1)?.key)\n\nconst handleBackClick = () => {\n  void useCommandStore().execute('Comfy.Graph.ExitSubgraph')\n}\n\n// Check for overflow on breadcrumb items and collapse/expand the breadcrumb to fit\nlet overflowObserver: ReturnType<typeof useOverflowObserver> | undefined\nonMounted(() => {\n  const el =\n    breadcrumbRef.value?.querySelector<HTMLElement>('.p-breadcrumb-list')\n  if (!el) return\n\n  overflowObserver = useOverflowObserver(el, {\n    onCheck: (isOverflowing) => {\n      overflowingTabs.value = isOverflowing\n\n      if (collapseTabs.value) {\n        // Items are currently hidden, check if we can show them\n        if (!isOverflowing) {\n          const items = [\n            ...el.querySelectorAll('.p-breadcrumb-item')\n          ] as HTMLElement[]\n\n          if (items.length < 3) return\n\n          const itemsWithIcon = items.filter((item) =>\n            item.querySelector('.p-breadcrumb-item-link-icon-visible')\n          ).length\n          const separators = el.querySelectorAll(\n            '.p-breadcrumb-separator'\n          ) as NodeListOf<HTMLElement>\n          const separator = separators[separators.length - 1] as HTMLElement\n          const separatorWidth = separator.offsetWidth\n\n          // items + separators + gaps + icons\n          const itemsWidth =\n            (MIN_WIDTH + ITEM_PADDING + ITEM_PADDING) * items.length +\n            itemsWithIcon * ICON_WIDTH\n          const separatorsWidth = (items.length - 1) * separatorWidth\n          const gapsWidth = (items.length - 1) * (ITEM_GAP * 2)\n          const totalWidth = itemsWidth + separatorsWidth + gapsWidth\n          const containerWidth = el.clientWidth\n\n          if (totalWidth <= containerWidth) {\n            collapseTabs.value = false\n          }\n        }\n      } else if (isOverflowing) {\n        collapseTabs.value = true\n      }\n    }\n  })\n})\n\nonBeforeUnmount(() => overflowObserver?.dispose())\n\n// If e.g. the workflow name changes, we need to check the overflow again\nonUpdated(() => {\n  if (!overflowObserver?.disposed.value) {\n    overflowObserver?.checkOverflow()\n  }\n})\n</script>\n\n<style scoped>\n.subgraph-breadcrumb:not(:empty) {\n  flex: auto;\n  flex-shrink: 10000;\n  min-width: 120px;\n}\n\n.subgraph-breadcrumb,\n:deep(.p-breadcrumb) {\n  overflow: hidden;\n}\n\n:deep(.p-breadcrumb) {\n  width: 100%;\n  background-color: transparent;\n}\n\n:deep(.p-breadcrumb-item) {\n  display: flex;\n  align-items: center;\n  overflow: hidden;\n  height: calc(var(--spacing) * 8);\n  min-width: calc(var(--breadcrumb-item-min-width) + 1rem);\n  border: 1px solid transparent;\n  background-color: transparent;\n  transition: all 0.2s;\n  /* Collapse middle items first */\n  flex-shrink: 10000;\n}\n\n:deep(.p-breadcrumb-separator) {\n  border: 1px solid transparent;\n  background-color: transparent;\n  display: flex;\n  padding: 0 var(--breadcrumb-item-margin);\n}\n\n:deep(.p-breadcrumb-item-link) {\n  padding: 0\n    calc(var(--breadcrumb-item-margin) + var(--breadcrumb-item-padding));\n}\n\n:deep(.p-breadcrumb-item:hover) {\n  border-radius: var(--radius-lg);\n  border-color: var(--interface-stroke);\n  background-color: var(--comfy-menu-bg);\n}\n\n:deep(.p-breadcrumb-item:has(.p-breadcrumb-item-link-icon-visible)) {\n  min-width: calc(var(--breadcrumb-item-min-width) + 1rem + 20px);\n}\n\n:deep(.p-breadcrumb-item:first-child) {\n  /* Then collapse the root workflow */\n  flex-shrink: 5000;\n\n  .p-breadcrumb-item-link {\n    padding-left: var(--breadcrumb-item-padding);\n  }\n}\n\n:deep(.p-breadcrumb-item:last-child) {\n  /* Then collapse the active item */\n  flex-shrink: 1;\n}\n\n:deep(.p-breadcrumb-item-link-menu-visible) {\n  background-color: color-mix(\n    in srgb,\n    var(--fg-color) 10%,\n    var(--comfy-menu-bg)\n  );\n  color: var(--fg-color);\n}\n</style>\n\n<style>\n.subgraph-breadcrumb-collapse .p-breadcrumb-list {\n  .p-breadcrumb-item,\n  .p-breadcrumb-separator {\n    display: none;\n  }\n\n  .p-breadcrumb-item:nth-last-child(3),\n  .p-breadcrumb-separator:nth-last-child(2),\n  .p-breadcrumb-item:nth-last-child(1) {\n    display: flex;\n  }\n}\n</style>\n","<template>\n  <div v-if=\"shouldShow\" class=\"flex justify-end\">\n    <div\n      class=\"flex items-center text-[0.75rem] leading-[normal] whitespace-nowrap drop-shadow-[1px_1px_8px_rgba(0,0,0,0.4)]\"\n      role=\"status\"\n      aria-live=\"polite\"\n      aria-atomic=\"true\"\n    >\n      <div class=\"flex items-center text-base-foreground\">\n        <span class=\"font-normal\">\n          {{ t('sideToolbar.queueProgressOverlay.inlineTotalLabel') }}:\n        </span>\n        <span class=\"w-[5ch] shrink-0 text-right font-bold tabular-nums\">\n          {{ totalPercentFormatted }}\n        </span>\n      </div>\n\n      <div class=\"flex items-center text-muted-foreground\">\n        <span\n          class=\"w-[16ch] shrink-0 truncate text-right\"\n          :title=\"currentNodeName\"\n        >\n          {{ currentNodeName }}:\n        </span>\n        <span class=\"w-[5ch] shrink-0 text-right tabular-nums\">\n          {{ currentNodePercentFormatted }}\n        </span>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useQueueProgress } from '@/composables/queue/useQueueProgress'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { resolveNodeDisplayName } from '@/utils/nodeTitleUtil'\n\nconst props = defineProps<{\n  hidden?: boolean\n}>()\n\nconst { t } = useI18n()\n\nconst executionStore = useExecutionStore()\nconst {\n  totalPercent,\n  totalPercentFormatted,\n  currentNodePercent,\n  currentNodePercentFormatted\n} = useQueueProgress()\n\nconst currentNodeName = computed(() => {\n  return resolveNodeDisplayName(executionStore.executingNode, {\n    emptyLabel: t('g.emDash'),\n    untitledLabel: t('g.untitled')\n  })\n})\n\nconst shouldShow = computed(\n  () =>\n    !props.hidden &&\n    (!executionStore.isIdle ||\n      totalPercent.value > 0 ||\n      currentNodePercent.value > 0)\n)\n</script>\n","<template>\n  <div class=\"inline-flex overflow-hidden rounded-lg bg-secondary-background\">\n    <div class=\"flex items-center gap-2 p-1 pr-3\">\n      <div\n        :class=\"\n          cn(\n            'relative shrink-0 items-center rounded-[4px]',\n            showsCompletionPreview && showThumbnails\n              ? 'flex h-8 overflow-visible p-0'\n              : showsCompletionPreview\n                ? 'flex size-8 justify-center overflow-hidden p-0'\n                : 'flex size-8 justify-center p-1'\n          )\n        \"\n      >\n        <template v-if=\"showThumbnails\">\n          <div class=\"flex h-8 shrink-0 items-center\">\n            <div\n              v-for=\"(thumbnailUrl, index) in thumbnailUrls\"\n              :key=\"`completion-preview-${index}`\"\n              :class=\"\n                cn(\n                  'relative size-8 shrink-0 overflow-hidden rounded-[4px]',\n                  index > 0 && '-ml-3 ring-2 ring-secondary-background'\n                )\n              \"\n            >\n              <img\n                :src=\"thumbnailUrl\"\n                :alt=\"t('sideToolbar.queueProgressOverlay.preview')\"\n                class=\"size-full object-cover\"\n              />\n            </div>\n          </div>\n        </template>\n        <div\n          v-else-if=\"showCompletionGradientFallback\"\n          class=\"size-full bg-linear-to-br from-coral-500 via-coral-500 to-azure-600\"\n        />\n        <i\n          v-else\n          :class=\"cn(iconClass, 'size-4', iconColorClass)\"\n          aria-hidden=\"true\"\n          data-testid=\"notification-icon\"\n        />\n      </div>\n      <div class=\"flex h-full items-center\">\n        <span\n          class=\"overflow-hidden text-center font-inter text-[12px] leading-normal font-normal text-ellipsis text-base-foreground\"\n        >\n          {{ bannerText }}\n        </span>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { QueueNotificationBanner } from '@/composables/queue/useQueueNotificationBanners'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { notification } = defineProps<{\n  notification: QueueNotificationBanner\n}>()\n\nconst { t, n } = useI18n()\n\nconst thumbnailUrls = computed(() => {\n  if (notification.type !== 'completed') {\n    return []\n  }\n  return notification.thumbnailUrls?.slice(0, 2) ?? []\n})\n\nconst showThumbnails = computed(() => {\n  if (notification.type !== 'completed') {\n    return false\n  }\n  return thumbnailUrls.value.length > 0\n})\n\nconst showCompletionGradientFallback = computed(\n  () => notification.type === 'completed' && !showThumbnails.value\n)\n\nconst showsCompletionPreview = computed(\n  () => showThumbnails.value || showCompletionGradientFallback.value\n)\n\nconst bannerText = computed(() => {\n  const count = notification.count\n  if (notification.type === 'queuedPending') {\n    return t('queue.jobQueueing')\n  }\n  if (notification.type === 'queued') {\n    if (count === 1) {\n      return t('queue.jobAddedToQueue')\n    }\n    return t(\n      'sideToolbar.queueProgressOverlay.jobsAddedToQueue',\n      { count: n(count) },\n      count\n    )\n  }\n  if (notification.type === 'failed') {\n    if (count === 1) {\n      return t('sideToolbar.queueProgressOverlay.jobFailed')\n    }\n    return t(\n      'sideToolbar.queueProgressOverlay.jobsFailed',\n      { count: n(count) },\n      count\n    )\n  }\n  if (count === 1) {\n    return t('sideToolbar.queueProgressOverlay.jobCompleted')\n  }\n  return t(\n    'sideToolbar.queueProgressOverlay.jobsCompleted',\n    { count: n(count) },\n    count\n  )\n})\n\nconst iconClass = computed(() => {\n  if (notification.type === 'queuedPending') {\n    return 'icon-[lucide--loader-circle]'\n  }\n  if (notification.type === 'queued') {\n    return 'icon-[lucide--check]'\n  }\n  if (notification.type === 'failed') {\n    return 'icon-[lucide--circle-alert]'\n  }\n  return 'icon-[lucide--image]'\n})\n\nconst iconColorClass = computed(() => {\n  if (notification.type === 'queuedPending') {\n    return 'animate-spin text-text-secondary'\n  }\n  if (notification.type === 'failed') {\n    return 'text-danger-200'\n  }\n  return 'text-text-secondary'\n})\n</script>\n","import type { TaskItemImpl } from '@/stores/queueStore'\nimport type { JobState } from '@/types/queue'\n\n/**\n * Checks if a job state represents an active (in-progress) job.\n */\nexport function isActiveJobState(state: JobState): boolean {\n  return (\n    state === 'pending' || state === 'initialization' || state === 'running'\n  )\n}\n\n/**\n * Map a task to a UI job state, including initialization override.\n *\n * @param task Task item from the queue store\n * @param isInitializing True if the prompt is currently initializing\n * @returns JobState for UI\n */\nexport const jobStateFromTask = (\n  task: TaskItemImpl,\n  isInitializing: boolean\n): JobState => {\n  if (isInitializing) return 'initialization'\n  const status = task.displayStatus\n  switch (status) {\n    case 'Running':\n      return 'running'\n    case 'Pending':\n      return 'pending'\n    case 'Completed':\n      return 'completed'\n    case 'Failed':\n    case 'Cancelled':\n      return 'failed'\n  }\n  return 'failed'\n}\n","import { computed, nextTick, onUnmounted, ref, watch } from 'vue'\n\nimport { api } from '@/scripts/api'\nimport type {\n  PromptQueuedEventPayload,\n  PromptQueueingEventPayload\n} from '@/scripts/api'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useQueueStore } from '@/stores/queueStore'\nimport { resultItemUrlWithTimestamp } from '@/utils/resultItemUrl'\nimport { isImageResult } from '@/utils/resultItem'\nimport { jobStateFromTask } from '@/utils/queueUtil'\n\nconst BANNER_DISMISS_DELAY_MS = 4000\nconst MAX_COMPLETION_THUMBNAILS = 2\n\ntype QueueQueuedNotificationType = 'queuedPending' | 'queued'\n\ntype QueueQueuedNotification = {\n  type: QueueQueuedNotificationType\n  count: number\n  requestId?: number\n}\n\ntype QueueCompletedNotification = {\n  type: 'completed'\n  count: number\n  thumbnailUrls?: string[]\n}\n\ntype QueueFailedNotification = {\n  type: 'failed'\n  count: number\n}\n\nexport type QueueNotificationBanner =\n  | QueueQueuedNotification\n  | QueueCompletedNotification\n  | QueueFailedNotification\n\nconst isRunAcknowledgement = (notification: QueueNotificationBanner) =>\n  notification.type === 'queuedPending' || notification.type === 'queued'\n\nconst isOutcome = (notification: QueueNotificationBanner) =>\n  notification.type === 'completed' || notification.type === 'failed'\n\nconst sanitizeCount = (value: number | undefined) => {\n  if (!(typeof value === 'number' && value > 0)) {\n    return 1\n  }\n  return Math.floor(value)\n}\n\nexport const useQueueNotificationBanners = () => {\n  const queueStore = useQueueStore()\n  const executionStore = useExecutionStore()\n\n  const pendingNotifications = ref<QueueNotificationBanner[]>([])\n  const activeNotification = ref<QueueNotificationBanner | null>(null)\n  const dismissTimer = ref<number | null>(null)\n  const lastActiveStartTs = ref<number | null>(null)\n  let stopIdleHistoryWatch: (() => void) | null = null\n  let idleCompletionScheduleToken = 0\n  const isQueueActive = computed(\n    () =>\n      queueStore.pendingTasks.length > 0 ||\n      queueStore.runningTasks.length > 0 ||\n      !executionStore.isIdle\n  )\n\n  const clearIdleCompletionHooks = () => {\n    idleCompletionScheduleToken++\n    if (!stopIdleHistoryWatch) {\n      return\n    }\n    stopIdleHistoryWatch()\n    stopIdleHistoryWatch = null\n  }\n\n  const clearDismissTimer = () => {\n    if (dismissTimer.value === null) {\n      return\n    }\n    clearTimeout(dismissTimer.value)\n    dismissTimer.value = null\n  }\n\n  const dismissActiveNotification = () => {\n    activeNotification.value = null\n    dismissTimer.value = null\n    showNextNotification()\n  }\n\n  const showNextNotification = () => {\n    if (\n      activeNotification.value !== null ||\n      pendingNotifications.value.length === 0\n    ) {\n      return\n    }\n    const [nextNotification, ...rest] = pendingNotifications.value\n    pendingNotifications.value = rest\n\n    activeNotification.value = nextNotification\n    clearDismissTimer()\n    dismissTimer.value = window.setTimeout(\n      dismissActiveNotification,\n      BANNER_DISMISS_DELAY_MS\n    )\n  }\n\n  const queuePositionFor = (notification: QueueNotificationBanner) => {\n    if (!isRunAcknowledgement(notification)) {\n      return pendingNotifications.value.length\n    }\n    const firstOutcome = pendingNotifications.value.findIndex(isOutcome)\n    return firstOutcome === -1\n      ? pendingNotifications.value.length\n      : firstOutcome\n  }\n\n  const queueNotification = (notification: QueueNotificationBanner) => {\n    if (isRunAcknowledgement(notification)) {\n      const active = activeNotification.value\n      if (active === null || isOutcome(active)) {\n        clearDismissTimer()\n        activeNotification.value = null\n        pendingNotifications.value = [\n          notification,\n          ...pendingNotifications.value\n        ]\n        showNextNotification()\n        return\n      }\n    }\n\n    const pending = [...pendingNotifications.value]\n    pending.splice(queuePositionFor(notification), 0, notification)\n    pendingNotifications.value = pending\n    showNextNotification()\n  }\n\n  const toQueueLifecycleNotification = (\n    type: QueueQueuedNotificationType,\n    count: number,\n    requestId?: number\n  ): QueueQueuedNotification => {\n    if (requestId === undefined) {\n      return {\n        type,\n        count\n      }\n    }\n    return {\n      type,\n      count,\n      requestId\n    }\n  }\n\n  const toCompletedNotification = (\n    count: number,\n    thumbnailUrls: string[]\n  ): QueueCompletedNotification => ({\n    type: 'completed',\n    count,\n    thumbnailUrls: thumbnailUrls.slice(0, MAX_COMPLETION_THUMBNAILS)\n  })\n\n  const toFailedNotification = (count: number): QueueFailedNotification => ({\n    type: 'failed',\n    count\n  })\n\n  const convertQueuedPendingToQueued = (\n    requestId: number | undefined,\n    count: number\n  ) => {\n    if (\n      activeNotification.value?.type === 'queuedPending' &&\n      (requestId === undefined ||\n        activeNotification.value.requestId === requestId)\n    ) {\n      activeNotification.value = toQueueLifecycleNotification(\n        'queued',\n        count,\n        requestId\n      )\n      return true\n    }\n\n    const pendingIndex = pendingNotifications.value.findIndex(\n      (notification) =>\n        notification.type === 'queuedPending' &&\n        (requestId === undefined || notification.requestId === requestId)\n    )\n\n    if (pendingIndex === -1) {\n      return false\n    }\n\n    const queuedPendingNotification = pendingNotifications.value[pendingIndex]\n    if (queuedPendingNotification.type !== 'queuedPending') {\n      return false\n    }\n\n    pendingNotifications.value = [\n      ...pendingNotifications.value.slice(0, pendingIndex),\n      toQueueLifecycleNotification(\n        'queued',\n        count,\n        queuedPendingNotification.requestId\n      ),\n      ...pendingNotifications.value.slice(pendingIndex + 1)\n    ]\n\n    return true\n  }\n\n  const handlePromptQueueing = (\n    event: CustomEvent<PromptQueueingEventPayload>\n  ) => {\n    const payload = event.detail\n    const count = sanitizeCount(payload.batchCount)\n    queueNotification(\n      toQueueLifecycleNotification('queuedPending', count, payload.requestId)\n    )\n  }\n\n  const handlePromptQueued = (event: CustomEvent<PromptQueuedEventPayload>) => {\n    const payload = event.detail\n    const count = sanitizeCount(payload.batchCount)\n    const handled = convertQueuedPendingToQueued(payload.requestId, count)\n    if (!handled) {\n      queueNotification(\n        toQueueLifecycleNotification('queued', count, payload.requestId)\n      )\n    }\n  }\n\n  api.addEventListener('promptQueueing', handlePromptQueueing)\n  api.addEventListener('promptQueued', handlePromptQueued)\n\n  const queueCompletionBatchNotifications = () => {\n    const startTs = lastActiveStartTs.value ?? 0\n    const finishedTasks = queueStore.historyTasks.filter((task) => {\n      const ts = task.executionEndTimestamp\n      return typeof ts === 'number' && ts >= startTs\n    })\n\n    if (!finishedTasks.length) {\n      return false\n    }\n\n    let completedCount = 0\n    let failedCount = 0\n    const imagePreviews: string[] = []\n\n    for (const task of finishedTasks) {\n      const state = jobStateFromTask(task, false)\n      if (state === 'completed') {\n        completedCount++\n        const preview = task.previewOutput\n        if (preview && isImageResult(preview)) {\n          imagePreviews.push(resultItemUrlWithTimestamp(preview))\n        }\n      } else if (state === 'failed') {\n        failedCount++\n      }\n    }\n\n    if (completedCount > 0) {\n      queueNotification(toCompletedNotification(completedCount, imagePreviews))\n    }\n\n    if (failedCount > 0) {\n      queueNotification(toFailedNotification(failedCount))\n    }\n\n    return completedCount > 0 || failedCount > 0\n  }\n\n  const scheduleIdleCompletionBatchNotifications = () => {\n    clearIdleCompletionHooks()\n    const scheduleToken = idleCompletionScheduleToken\n    const startTsSnapshot = lastActiveStartTs.value\n\n    const isStillSameIdleWindow = () =>\n      scheduleToken === idleCompletionScheduleToken &&\n      !isQueueActive.value &&\n      lastActiveStartTs.value === startTsSnapshot\n\n    stopIdleHistoryWatch = watch(\n      () => queueStore.historyTasks,\n      () => {\n        if (!isStillSameIdleWindow()) {\n          clearIdleCompletionHooks()\n          return\n        }\n        queueCompletionBatchNotifications()\n        clearIdleCompletionHooks()\n      }\n    )\n\n    void nextTick(() => {\n      if (!isStillSameIdleWindow()) {\n        clearIdleCompletionHooks()\n        return\n      }\n\n      const hasShownNotifications = queueCompletionBatchNotifications()\n      if (hasShownNotifications) {\n        clearIdleCompletionHooks()\n      }\n    })\n  }\n\n  watch(\n    isQueueActive,\n    (active, prev) => {\n      if (!prev && active) {\n        clearIdleCompletionHooks()\n        lastActiveStartTs.value = Date.now()\n        return\n      }\n      if (prev && !active) {\n        scheduleIdleCompletionBatchNotifications()\n      }\n    },\n    { immediate: true }\n  )\n\n  onUnmounted(() => {\n    api.removeEventListener('promptQueueing', handlePromptQueueing)\n    api.removeEventListener('promptQueued', handlePromptQueued)\n    clearIdleCompletionHooks()\n    clearDismissTimer()\n    pendingNotifications.value = []\n    activeNotification.value = null\n    lastActiveStartTs.value = null\n  })\n\n  const currentNotification = computed(() => activeNotification.value)\n\n  return {\n    currentNotification\n  }\n}\n","<template>\n  <div\n    v-if=\"currentNotification\"\n    class=\"flex justify-end\"\n    role=\"status\"\n    aria-live=\"polite\"\n    aria-atomic=\"true\"\n    data-testid=\"queue-notification-banner\"\n  >\n    <QueueNotificationBanner :notification=\"currentNotification\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport QueueNotificationBanner from '@/components/queue/QueueNotificationBanner.vue'\nimport { useQueueNotificationBanners } from '@/composables/queue/useQueueNotificationBanners'\n\nconst { currentNotification } = useQueueNotificationBanners()\n</script>\n","<template>\n  <div class=\"flex flex-col gap-3 p-2\">\n    <div class=\"flex flex-col gap-1\">\n      <div\n        class=\"relative h-2 w-full overflow-hidden rounded-full border border-interface-stroke bg-interface-panel-surface\"\n      >\n        <div\n          class=\"absolute inset-0 h-full origin-left rounded-full will-change-transform motion-safe:transition-transform\"\n          :style=\"totalProgressStyle\"\n        />\n        <div\n          data-testid=\"queue-progress-node-fill\"\n          class=\"absolute inset-0 h-full origin-left rounded-full will-change-transform motion-safe:transition-transform\"\n          :style=\"currentNodeProgressStyle\"\n        />\n      </div>\n      <div class=\"flex items-start justify-end gap-4 text-[12px] leading-none\">\n        <div class=\"flex items-center gap-1 text-text-primary opacity-90\">\n          <i18n-t keypath=\"sideToolbar.queueProgressOverlay.total\">\n            <template #percent>\n              <span class=\"font-bold\">{{ totalPercentFormatted }}</span>\n            </template>\n          </i18n-t>\n        </div>\n        <div class=\"flex items-center gap-1 text-text-secondary\">\n          <span>{{ t('sideToolbar.queueProgressOverlay.currentNode') }}</span>\n          <span class=\"inline-block max-w-40 truncate\">{{\n            currentNodeName\n          }}</span>\n          <span class=\"flex items-center gap-1\">\n            <span>{{ currentNodePercentFormatted }}</span>\n          </span>\n        </div>\n      </div>\n    </div>\n\n    <div :class=\"bottomRowClass\">\n      <div class=\"flex items-center gap-4 text-[12px] text-text-primary\">\n        <div class=\"flex items-center gap-2\">\n          <span class=\"opacity-90\">\n            <span class=\"font-bold\">{{ runningCount }}</span>\n            <span class=\"ml-1\">{{\n              t('sideToolbar.queueProgressOverlay.running')\n            }}</span>\n          </span>\n          <Button\n            v-if=\"runningCount > 0\"\n            :tooltip=\"t('sideToolbar.queueProgressOverlay.cancelJobTooltip')\"\n            variant=\"destructive\"\n            size=\"icon\"\n            :aria-label=\"t('sideToolbar.queueProgressOverlay.interruptAll')\"\n            @click=\"$emit('interruptAll')\"\n          >\n            <i\n              class=\"icon-[lucide--x] block size-4 leading-none text-text-primary\"\n            />\n          </Button>\n        </div>\n\n        <div class=\"flex items-center gap-2\">\n          <span class=\"opacity-90\">\n            <span class=\"font-bold\">{{ queuedCount }}</span>\n            <span class=\"ml-1\">{{\n              t('sideToolbar.queueProgressOverlay.queuedSuffix')\n            }}</span>\n          </span>\n          <Button\n            v-if=\"queuedCount > 0\"\n            :tooltip=\"t('sideToolbar.queueProgressOverlay.clearQueueTooltip')\"\n            variant=\"destructive\"\n            size=\"icon\"\n            :aria-label=\"t('sideToolbar.queueProgressOverlay.clearQueued')\"\n            @click=\"$emit('clearQueued')\"\n          >\n            <i\n              class=\"icon-[lucide--list-x] block size-4 leading-none text-text-primary\"\n            />\n          </Button>\n        </div>\n      </div>\n\n      <Button\n        class=\"min-w-30 flex-1 px-2 py-0\"\n        variant=\"secondary\"\n        size=\"md\"\n        @click=\"$emit('viewAllJobs')\"\n      >\n        {{ t('sideToolbar.queueProgressOverlay.viewAllJobs') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\n\ndefineProps<{\n  totalProgressStyle: Record<string, string>\n  currentNodeProgressStyle: Record<string, string>\n  totalPercentFormatted: string\n  currentNodePercentFormatted: string\n  currentNodeName: string\n  runningCount: number\n  queuedCount: number\n  bottomRowClass: string\n}>()\n\ndefineEmits<{\n  (e: 'interruptAll'): void\n  (e: 'clearQueued'): void\n  (e: 'viewAllJobs'): void\n}>()\n\nconst { t } = useI18n()\n</script>\n","import { computed } from 'vue'\n\nimport { downloadFile } from '@/base/common/downloadUtil'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport type { JobListItem } from '@/composables/queue/useJobList'\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { st, t } from '@/i18n'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { withNodeAddSource } from '@/platform/telemetry/nodeAdded/nodeAddSource'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type { ResultItem } from '@/platform/remote/comfyui/execution/types'\nimport { api } from '@/scripts/api'\nimport { downloadBlob } from '@/scripts/utils'\nimport { useDialogService } from '@/services/dialogService'\nimport { getJobWorkflow } from '@/services/jobOutputCache'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useQueueStore } from '@/stores/queueStore'\nimport type { TaskItemImpl } from '@/stores/queueStore'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemUrl } from '@/utils/resultItemUrl'\nimport { isAudioResult, isImageResult, isVideoResult } from '@/utils/resultItem'\nimport { createAnnotatedPath } from '@/utils/createAnnotatedPath'\nimport { appendJsonExt } from '@/utils/formatUtil'\nimport { isResultItemType } from '@/utils/typeGuardUtil'\n\n/**\n * Provides job context menu entries and actions.\n *\n * @param currentMenuItem Getter for the currently targeted job list item\n * @param onInspectAsset Callback to trigger when inspecting a completed job's asset\n */\nexport function useJobMenu(\n  currentMenuItem: () => JobListItem | null = () => null,\n  onInspectAsset?: (item: JobListItem) => void\n) {\n  const workflowStore = useWorkflowStore()\n  const workflowService = useWorkflowService()\n  const queueStore = useQueueStore()\n  const executionStore = useExecutionStore()\n  const { copyToClipboard } = useCopyToClipboard()\n  const { wrapWithErrorHandlingAsync } = useErrorHandling()\n  const litegraphService = useLitegraphService()\n  const nodeDefStore = useNodeDefStore()\n\n  const resolveItem = (item?: JobListItem | null): JobListItem | null =>\n    item ?? currentMenuItem()\n\n  const openJobWorkflow = async (item?: JobListItem | null) => {\n    const target = resolveItem(item)\n    if (!target) return\n    const data = await getJobWorkflow(target.id)\n    if (!data) return\n    const filename = `Job ${target.id}.json`\n    const temp = workflowStore.createTemporary(filename, data)\n    try {\n      await workflowService.openWorkflow(temp)\n    } catch (error) {\n      useDialogService().showErrorDialog(error, {\n        title: t('errorDialog.queueOpenWorkflowFailedTitle'),\n        reportType: 'queueOpenWorkflowError'\n      })\n    }\n  }\n\n  const copyJobId = async (item?: JobListItem | null) => {\n    const target = resolveItem(item)\n    if (!target) return\n    await copyToClipboard(target.id)\n  }\n\n  const cancelJob = async (item?: JobListItem | null) => {\n    const target = resolveItem(item)\n    if (!target) return\n    if (\n      target.state === 'running' ||\n      target.state === 'initialization' ||\n      target.state === 'pending'\n    ) {\n      // State-agnostic cancel (see api.ts cancelJob for the runtime-parity caveat).\n      await api.cancelJob(target.id)\n    }\n    executionStore.clearInitializationByJobId(target.id)\n    await queueStore.update()\n  }\n\n  const copyErrorMessage = async (item?: JobListItem | null) => {\n    const target = resolveItem(item)\n    const message = target?.taskRef?.errorMessage\n    if (message) await copyToClipboard(message)\n  }\n\n  const reportError = (item?: JobListItem | null) => {\n    const target = resolveItem(item)\n    if (!target) return\n\n    // Use execution_error from list response if available\n    const executionError = target.taskRef?.executionError\n\n    if (executionError) {\n      useDialogService().showExecutionErrorDialog(executionError)\n      return\n    }\n\n    // Fall back to simple error dialog\n    const message = target.taskRef?.errorMessage\n    if (message) {\n      useDialogService().showErrorDialog(new Error(message), {\n        reportType: 'queueJobError'\n      })\n    }\n  }\n\n  // This is very magical only because it matches the respective backend implementation\n  // There is or will be a better way to do this\n  const addOutputLoaderNode = async () => {\n    const item = currentMenuItem()\n    if (!item) return\n    const result: AugmentedResultItem | undefined = item.taskRef?.previewOutput\n    if (!result) return\n\n    let nodeType: 'LoadImage' | 'LoadVideo' | 'LoadAudio' | null = null\n    let widgetName: 'image' | 'file' | 'audio' | null = null\n    if (isImageResult(result)) {\n      nodeType = 'LoadImage'\n      widgetName = 'image'\n    } else if (isVideoResult(result)) {\n      nodeType = 'LoadVideo'\n      widgetName = 'file'\n    } else if (isAudioResult(result)) {\n      nodeType = 'LoadAudio'\n      widgetName = 'audio'\n    }\n    if (!nodeType || !widgetName) return\n\n    const nodeDef = Object.hasOwn(nodeDefStore.nodeDefsByName, nodeType)\n      ? nodeDefStore.nodeDefsByName[nodeType]\n      : undefined\n    if (!nodeDef) return\n    const node = withNodeAddSource('programmatic', () =>\n      litegraphService.addNodeOnGraph(nodeDef, {\n        pos: litegraphService.getCanvasCenter()\n      })\n    )\n\n    if (!node) return\n\n    const apiItem: ResultItem = {\n      filename: result.filename,\n      subfolder: result.subfolder,\n      type: isResultItemType(result.type) ? result.type : 'output'\n    }\n\n    const annotated = createAnnotatedPath(apiItem)\n    const widget = node.widgets?.find((w) => w.name === widgetName)\n    if (widget) {\n      widget.value = annotated\n      widget.callback?.(annotated)\n    }\n    node.graph?.setDirtyCanvas(true, true)\n  }\n\n  /**\n   * Trigger a download of the job's previewable output asset.\n   */\n  const downloadPreviewAsset = () => {\n    const item = currentMenuItem()\n    if (!item) return\n    const result: AugmentedResultItem | undefined = item.taskRef?.previewOutput\n    if (!result) return\n    downloadFile(resultItemUrl(result))\n  }\n\n  /**\n   * Export the workflow JSON attached to the job.\n   */\n  const exportJobWorkflow = async () => {\n    const item = currentMenuItem()\n    if (!item) return\n    const data = await getJobWorkflow(item.id)\n    if (!data) return\n\n    const settingStore = useSettingStore()\n    let filename = `Job ${item.id}.json`\n\n    if (settingStore.get('Comfy.PromptFilename')) {\n      const input = await useDialogService().prompt({\n        title: t('workflowService.exportWorkflow'),\n        message: t('workflowService.enterFilenamePrompt'),\n        defaultValue: filename\n      })\n      if (!input) return\n      filename = appendJsonExt(input)\n    }\n\n    const json = JSON.stringify(data, null, 2)\n    const blob = new Blob([json], { type: 'application/json' })\n    downloadBlob(filename, blob)\n  }\n\n  const removeFailedJob = async (task?: TaskItemImpl | null) => {\n    const target = task ?? currentMenuItem()?.taskRef\n    if (!target) return\n    await queueStore.delete(target)\n  }\n\n  const jobMenuOpenWorkflowLabel = computed(() =>\n    st('queue.jobMenu.openAsWorkflowNewTab', 'Open as workflow in new tab')\n  )\n  const jobMenuOpenWorkflowFailedLabel = computed(() =>\n    st('queue.jobMenu.openWorkflowNewTab', 'Open workflow in new tab')\n  )\n  const jobMenuCopyJobIdLabel = computed(() =>\n    st('queue.jobMenu.copyJobId', 'Copy job ID')\n  )\n  const jobMenuCancelLabel = computed(() =>\n    st('queue.jobMenu.cancelJob', 'Cancel job')\n  )\n\n  const jobMenuEntries = computed<MenuItem[]>(() => {\n    const item = currentMenuItem()\n    const state = item?.state\n    if (!state) return []\n    const hasPreviewAsset = !!item.taskRef?.previewOutput\n    if (state === 'completed') {\n      return handleErrors([\n        {\n          key: 'inspect-asset',\n          label: st('queue.jobMenu.inspectAsset', 'Inspect asset'),\n          icon: 'icon-[lucide--zoom-in]',\n          disabled: !hasPreviewAsset || !onInspectAsset,\n          command: onInspectAsset\n            ? () => {\n                const item = currentMenuItem()\n                if (item) onInspectAsset(item)\n              }\n            : undefined\n        },\n        {\n          key: 'add-to-current',\n          label: st(\n            'queue.jobMenu.addToCurrentWorkflow',\n            'Add to current workflow'\n          ),\n          icon: 'icon-[comfy--node]',\n          disabled: !hasPreviewAsset,\n          command: () => addOutputLoaderNode()\n        },\n        {\n          key: 'download',\n          label: st('queue.jobMenu.download', 'Download'),\n          icon: 'icon-[lucide--download]',\n          disabled: !hasPreviewAsset,\n          command: () => downloadPreviewAsset()\n        },\n        { separator: true, key: 'd1' },\n        {\n          key: 'open-workflow',\n          label: jobMenuOpenWorkflowLabel.value,\n          icon: 'icon-[comfy--workflow]',\n          command: () => openJobWorkflow()\n        },\n        {\n          key: 'export-workflow',\n          label: st('queue.jobMenu.exportWorkflow', 'Export workflow'),\n          icon: 'icon-[comfy--file-output]',\n          command: () => exportJobWorkflow()\n        },\n        { separator: true, key: 'd2' },\n        {\n          key: 'copy-id',\n          label: jobMenuCopyJobIdLabel.value,\n          icon: 'icon-[lucide--copy]',\n          command: () => copyJobId()\n        }\n      ])\n    }\n    if (state === 'failed') {\n      return handleErrors([\n        {\n          key: 'open-workflow',\n          label: jobMenuOpenWorkflowFailedLabel.value,\n          icon: 'icon-[comfy--workflow]',\n          command: () => openJobWorkflow()\n        },\n        { separator: true, key: 'd1' },\n        {\n          key: 'copy-id',\n          label: jobMenuCopyJobIdLabel.value,\n          icon: 'icon-[lucide--copy]',\n          command: () => copyJobId()\n        },\n        {\n          key: 'copy-error',\n          label: st('queue.jobMenu.copyErrorMessage', 'Copy error message'),\n          icon: 'icon-[lucide--copy]',\n          command: () => copyErrorMessage()\n        },\n        {\n          key: 'report-error',\n          label: st('queue.jobMenu.reportError', 'Report error'),\n          icon: 'icon-[lucide--message-circle-warning]',\n          command: () => reportError()\n        },\n        { separator: true, key: 'd2' },\n        {\n          key: 'delete',\n          label: st('queue.jobMenu.removeJob', 'Remove job'),\n          icon: 'icon-[lucide--circle-minus]',\n          command: () => removeFailedJob()\n        }\n      ])\n    }\n    return handleErrors([\n      {\n        key: 'open-workflow',\n        label: jobMenuOpenWorkflowLabel.value,\n        icon: 'icon-[comfy--workflow]',\n        command: () => openJobWorkflow()\n      },\n      { separator: true, key: 'd1' },\n      {\n        key: 'copy-id',\n        label: jobMenuCopyJobIdLabel.value,\n        icon: 'icon-[lucide--copy]',\n        command: () => copyJobId()\n      },\n      { separator: true, key: 'd2' },\n      {\n        key: 'cancel-job',\n        label: jobMenuCancelLabel.value,\n        icon: 'icon-[lucide--x]',\n        command: () => cancelJob()\n      }\n    ])\n  })\n\n  const handleErrors = (items: MenuItem[]): MenuItem[] =>\n    items.map((item) =>\n      item.command\n        ? { ...item, command: wrapWithErrorHandlingAsync(item.command) }\n        : item\n    )\n\n  return {\n    jobMenuEntries,\n    openJobWorkflow,\n    copyJobId,\n    cancelJob,\n    removeFailedJob\n  }\n}\n","<template>\n  <Menu v-model:open=\"open\" :items=\"items\" align=\"end\">\n    <template #trigger>\n      <Button\n        :tooltip=\"t('g.more')\"\n        variant=\"muted-textonly\"\n        size=\"icon\"\n        :aria-label=\"t('sideToolbar.queueProgressOverlay.moreOptions')\"\n        icon=\"icon-[lucide--more-horizontal]\"\n      />\n    </template>\n  </Menu>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useQueueFeatureFlags } from '@/composables/queue/useQueueFeatureFlags'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useSurveyFeatureTracking } from '@/platform/surveys/useSurveyFeatureTracking'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\n\nconst emit = defineEmits<{\n  (e: 'clearHistory'): void\n}>()\n\nconst { t } = useI18n()\nconst settingStore = useSettingStore()\nconst sidebarTabStore = useSidebarTabStore()\nconst { trackFeatureUsed } = useSurveyFeatureTracking('queue-progress-overlay')\n\nconst { isQueuePanelV2Enabled, isRunProgressBarEnabled } =\n  useQueueFeatureFlags()\nconst open = ref(false)\nconst items = computed<MenuItem[]>(() => [\n  {\n    label: t('sideToolbar.queueProgressOverlay.dockedJobHistory'),\n    icon: 'icon-[lucide--panel-left-close]',\n    checked: isQueuePanelV2Enabled.value,\n    command: onToggleDockedJobHistory\n  },\n  {\n    label: t('sideToolbar.queueProgressOverlay.showRunProgressBar'),\n    icon: 'icon-[lucide--hourglass]',\n    checked: isRunProgressBarEnabled.value,\n    command: onToggleRunProgressBar\n  },\n  { separator: true, visible: !isCloud },\n  {\n    label: t('sideToolbar.queueProgressOverlay.clearHistory'),\n    description: t(\n      'sideToolbar.queueProgressOverlay.clearHistoryMenuAssetsNote'\n    ),\n    icon: 'icon-[lucide--trash-2]',\n    variant: 'destructive',\n    visible: !isCloud,\n    command: () => emit('clearHistory')\n  }\n])\n\nasync function onToggleDockedJobHistory() {\n  trackFeatureUsed()\n  open.value = false\n\n  try {\n    if (isQueuePanelV2Enabled.value) {\n      await settingStore.setMany({\n        'Comfy.Queue.QPOV2': false,\n        'Comfy.Queue.History.Expanded': true\n      })\n      return\n    }\n\n    sidebarTabStore.activeSidebarTabId = 'job-history'\n    await settingStore.set('Comfy.Queue.QPOV2', true)\n  } catch {\n    return\n  }\n}\n\nasync function onToggleRunProgressBar() {\n  trackFeatureUsed()\n  await settingStore.set(\n    'Comfy.Queue.ShowRunProgressBar',\n    !isRunProgressBarEnabled.value\n  )\n}\n</script>\n","<template>\n  <div\n    class=\"flex h-12 items-center gap-2 border-b border-interface-stroke px-2\"\n  >\n    <div class=\"min-w-0 flex-1 px-2 text-[14px] font-normal text-text-primary\">\n      <span>{{ headerTitle }}</span>\n    </div>\n    <div\n      class=\"inline-flex h-6 items-center gap-2 text-[12px] leading-none text-text-primary\"\n    >\n      <span :class=\"{ 'opacity-50': queuedCount === 0 }\">{{\n        t('sideToolbar.queueProgressOverlay.clearQueueTooltip')\n      }}</span>\n      <Button\n        :tooltip=\"t('sideToolbar.queueProgressOverlay.clearAllJobsTooltip')\"\n        variant=\"destructive\"\n        size=\"icon\"\n        :aria-label=\"t('sideToolbar.queueProgressOverlay.clearQueued')\"\n        :disabled=\"queuedCount === 0\"\n        @click=\"$emit('clearQueued')\"\n      >\n        <i class=\"icon-[lucide--list-x] size-4\" />\n      </Button>\n    </div>\n    <JobHistoryActionsMenu @clear-history=\"$emit('clearHistory')\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport JobHistoryActionsMenu from '@/components/queue/JobHistoryActionsMenu.vue'\nimport Button from '@/components/ui/button/Button.vue'\n\ndefineProps<{\n  headerTitle: string\n  queuedCount: number\n}>()\n\ndefineEmits<{\n  (e: 'clearHistory'): void\n  (e: 'clearQueued'): void\n}>()\n\nconst { t } = useI18n()\n</script>\n","import { computed } from 'vue'\nimport type { ComputedRef } from 'vue'\n\nimport type { ExecutionErrorDialogInput } from '@/services/dialogService'\nimport type { TaskItemImpl } from '@/stores/queueStore'\n\ntype CopyHandler = (value: string) => void | Promise<unknown>\n\nexport type JobErrorDialogService = {\n  showExecutionErrorDialog: (executionError: ExecutionErrorDialogInput) => void\n  showErrorDialog: (\n    error: Error,\n    options?: {\n      reportType?: string\n      [key: string]: unknown\n    }\n  ) => void\n}\n\ntype UseJobErrorReportingOptions = {\n  taskForJob: ComputedRef<TaskItemImpl | null>\n  copyToClipboard: CopyHandler\n  dialog: JobErrorDialogService\n}\n\nexport const useJobErrorReporting = ({\n  taskForJob,\n  copyToClipboard,\n  dialog\n}: UseJobErrorReportingOptions) => {\n  const errorMessageValue = computed(() => taskForJob.value?.errorMessage ?? '')\n\n  const copyErrorMessage = () => {\n    if (errorMessageValue.value) {\n      void copyToClipboard(errorMessageValue.value)\n    }\n  }\n\n  const reportJobError = () => {\n    const executionError = taskForJob.value?.executionError\n    if (executionError) {\n      dialog.showExecutionErrorDialog(executionError)\n      return\n    }\n\n    if (errorMessageValue.value) {\n      dialog.showErrorDialog(new Error(errorMessageValue.value), {\n        reportType: 'queueJobError'\n      })\n    }\n  }\n\n  return {\n    errorMessageValue,\n    copyErrorMessage,\n    reportJobError\n  }\n}\n","import { computed } from 'vue'\nimport type { ComputedRef, Ref } from 'vue'\n\nimport type { useExecutionStore } from '@/stores/executionStore'\nimport type { TaskItemImpl, useQueueStore } from '@/stores/queueStore'\nimport type { JobState } from '@/types/queue'\n\ntype QueueStore = ReturnType<typeof useQueueStore>\ntype ExecutionStore = ReturnType<typeof useExecutionStore>\n\nexport type UseQueueEstimatesOptions = {\n  queueStore: QueueStore\n  executionStore: ExecutionStore\n  taskForJob: ComputedRef<TaskItemImpl | null>\n  jobState: ComputedRef<JobState | null>\n  firstSeenTs: ComputedRef<number | undefined>\n  jobsAhead: ComputedRef<number | null>\n  nowTs: Ref<number>\n}\n\ntype EstimateRange = [number, number]\n\nexport const formatElapsedTime = (ms: number): string => {\n  const totalSec = Math.max(0, Math.floor(ms / 1000))\n  const minutes = Math.floor(totalSec / 60)\n  const seconds = totalSec % 60\n  return `${minutes}m ${seconds}s`\n}\n\nconst pickRecentDurations = (queueStore: QueueStore) =>\n  queueStore.historyTasks\n    .map((task: TaskItemImpl) => Number(task.executionTimeInSeconds))\n    .filter(\n      (value: number | undefined) =>\n        typeof value === 'number' && !Number.isNaN(value)\n    )\n\nexport const useQueueEstimates = ({\n  queueStore,\n  executionStore,\n  taskForJob,\n  jobState,\n  firstSeenTs,\n  jobsAhead,\n  nowTs\n}: UseQueueEstimatesOptions) => {\n  const runningWorkflowCount = computed(\n    () => executionStore.runningWorkflowCount\n  )\n\n  const showParallelQueuedStats = computed(\n    () =>\n      jobState.value === 'pending' &&\n      !!firstSeenTs.value &&\n      runningWorkflowCount.value > 1\n  )\n\n  const recentDurations = computed<number[]>(() =>\n    pickRecentDurations(queueStore).slice(-20)\n  )\n\n  const runningRemainingRangeSeconds = computed<EstimateRange | null>(() => {\n    const durations = recentDurations.value\n    if (!durations.length) return null\n    const sorted = durations.slice().sort((a, b) => a - b)\n    const avg = sorted.reduce((sum, value) => sum + value, 0) / sorted.length\n    const p75 =\n      sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * 0.75))]\n    const running = queueStore.runningTasks\n    const now = nowTs.value\n    const remaining = running\n      .map((task) => task.executionStartTimestamp)\n      .filter((timestamp): timestamp is number => typeof timestamp === 'number')\n      .map((startTs) => {\n        const elapsed = Math.max(0, Math.floor((now - startTs) / 1000))\n        return {\n          lo: Math.max(0, Math.round(avg - elapsed)),\n          hi: Math.max(0, Math.round(p75 - elapsed))\n        }\n      })\n    if (!remaining.length) return null\n    const minLo = remaining.reduce(\n      (min, range) => Math.min(min, range.lo),\n      Infinity\n    )\n    const minHi = remaining.reduce(\n      (min, range) => Math.min(min, range.hi),\n      Infinity\n    )\n    return [minLo, minHi]\n  })\n\n  const estimateRangeSeconds = computed<EstimateRange | null>(() => {\n    const durations = recentDurations.value\n    if (!durations.length) return null\n    const ahead = jobsAhead.value\n    if (ahead == null) return null\n    const sorted = durations.slice().sort((a, b) => a - b)\n    const avg = sorted.reduce((sum, value) => sum + value, 0) / sorted.length\n    const p75 =\n      sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * 0.75))]\n    if (ahead <= 0) {\n      return runningRemainingRangeSeconds.value ?? [0, 0]\n    }\n    const runningCount = Math.max(1, runningWorkflowCount.value || 1)\n    const batches = Math.ceil(ahead / runningCount)\n    return [Math.round(avg * batches), Math.round(p75 * batches)]\n  })\n\n  const estimateRemainingRangeSeconds = computed<EstimateRange | null>(() => {\n    const durations = recentDurations.value\n    if (!durations.length) return null\n    const sorted = durations.slice().sort((a, b) => a - b)\n    const avg = sorted.reduce((sum, value) => sum + value, 0) / sorted.length\n    const p75 =\n      sorted[Math.min(sorted.length - 1, Math.floor(sorted.length * 0.75))]\n    const execStart =\n      jobState.value === 'running'\n        ? taskForJob.value?.executionStartTimestamp\n        : undefined\n    const baseTs = execStart ?? firstSeenTs.value\n    const elapsed = baseTs\n      ? Math.max(0, Math.floor((nowTs.value - baseTs) / 1000))\n      : 0\n    const lo = Math.max(0, Math.round(avg - elapsed))\n    const hi = Math.max(0, Math.round(p75 - elapsed))\n    return [lo, hi]\n  })\n\n  const timeElapsedValue = computed(() => {\n    const execStart =\n      jobState.value === 'running'\n        ? taskForJob.value?.executionStartTimestamp\n        : undefined\n    const baseTs = execStart ?? firstSeenTs.value\n    if (!baseTs) return ''\n    return formatElapsedTime(nowTs.value - baseTs)\n  })\n\n  return {\n    runningWorkflowCount,\n    showParallelQueuedStats,\n    estimateRangeSeconds,\n    estimateRemainingRangeSeconds,\n    timeElapsedValue\n  }\n}\n","<template>\n  <div\n    class=\"w-[300px] min-w-[260px] rounded-lg border border-interface-stroke bg-interface-panel-surface shadow-md\"\n  >\n    <div class=\"flex items-center border-b border-interface-stroke p-4\">\n      <span class=\"text-sm/normal font-normal text-text-primary\">{{\n        t('queue.jobDetails.header')\n      }}</span>\n    </div>\n    <div class=\"flex flex-col gap-6 p-4\">\n      <div class=\"grid grid-cols-2 items-center gap-2\">\n        <template v-for=\"row in baseRows\" :key=\"row.label\">\n          <div\n            class=\"flex items-center text-xs/normal font-normal text-text-primary\"\n          >\n            {{ row.label }}\n          </div>\n          <div\n            class=\"flex min-w-0 items-center text-xs/normal font-normal text-text-secondary\"\n          >\n            <span class=\"block min-w-0 truncate\">{{ row.value }}</span>\n            <Button\n              v-if=\"row.canCopy\"\n              size=\"icon\"\n              variant=\"muted-textonly\"\n              :aria-label=\"copyAriaLabel\"\n              @click.stop=\"copyJobId\"\n            >\n              <i class=\"icon-[lucide--copy] size-4\" />\n            </Button>\n          </div>\n        </template>\n      </div>\n\n      <div v-if=\"extraRows.length\" class=\"grid grid-cols-2 items-center gap-2\">\n        <template v-for=\"row in extraRows\" :key=\"row.label\">\n          <div\n            class=\"flex items-center text-xs/normal font-normal text-text-primary\"\n          >\n            {{ row.label }}\n          </div>\n          <div\n            class=\"flex min-w-0 items-center text-xs/normal font-normal text-text-secondary\"\n          >\n            <span class=\"block min-w-0 truncate\">{{ row.value }}</span>\n          </div>\n        </template>\n      </div>\n\n      <div v-if=\"jobState === 'failed'\" class=\"grid grid-cols-2 gap-x-2\">\n        <div\n          class=\"flex items-center text-xs/normal font-normal text-text-primary\"\n        >\n          {{ t('queue.jobDetails.errorMessage') }}\n        </div>\n        <div class=\"flex items-center justify-between gap-4\">\n          <Button\n            class=\"justify-start px-0\"\n            variant=\"muted-textonly\"\n            size=\"sm\"\n            icon-position=\"right\"\n            @click.stop=\"copyErrorMessage\"\n          >\n            <span>{{ copyAriaLabel }}</span>\n            <i class=\"icon-[lucide--copy] block size-3.5 leading-none\" />\n          </Button>\n          <Button\n            class=\"justify-start px-0\"\n            variant=\"muted-textonly\"\n            size=\"sm\"\n            icon-position=\"right\"\n            @click.stop=\"reportJobError\"\n          >\n            <span>{{ t('queue.jobDetails.report') }}</span>\n            <i\n              class=\"icon-[lucide--message-circle-warning] block size-3.5 leading-none\"\n            />\n          </Button>\n        </div>\n        <div\n          class=\"col-span-2 mt-2 max-h-96 overflow-y-auto rounded-sm bg-interface-panel-hover-surface px-4 py-2 text-xs/normal wrap-break-word whitespace-pre-wrap text-text-secondary\"\n        >\n          {{ errorMessageValue }}\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onMounted, onUnmounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useDialogService } from '@/services/dialogService'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useQueueStore } from '@/stores/queueStore'\nimport type { TaskItemImpl } from '@/stores/queueStore'\nimport { formatClockTime } from '@/utils/dateTimeUtil'\nimport { jobStateFromTask } from '@/utils/queueUtil'\n\nimport { useJobErrorReporting } from './useJobErrorReporting'\nimport { formatElapsedTime, useQueueEstimates } from './useQueueEstimates'\n\nconst props = defineProps<{\n  jobId: string\n  workflowId?: string\n}>()\n\nconst copyAriaLabel = computed(() => t('g.copy'))\n\nconst workflowStore = useWorkflowStore()\nconst queueStore = useQueueStore()\nconst executionStore = useExecutionStore()\nconst dialog = useDialogService()\nconst { locale, t } = useI18n()\n\nconst workflowValue = computed(() => {\n  const wid = props.workflowId\n  if (!wid) return ''\n  const activeId = workflowStore.activeWorkflow?.activeState?.id\n  if (activeId && activeId === wid) {\n    return workflowStore.activeWorkflow?.filename ?? wid\n  }\n  return wid\n})\nconst jobIdValue = computed(() => props.jobId)\n\nconst { copyToClipboard } = useCopyToClipboard()\nconst copyJobId = () => void copyToClipboard(jobIdValue.value)\n\nconst taskForJob = computed(() => {\n  const pid = props.jobId\n  const findIn = (arr: TaskItemImpl[]) =>\n    arr.find((t) => String(t.jobId ?? '') === String(pid))\n  return (\n    findIn(queueStore.pendingTasks) ||\n    findIn(queueStore.runningTasks) ||\n    findIn(queueStore.historyTasks) ||\n    null\n  )\n})\n\nconst jobState = computed(() => {\n  const task = taskForJob.value\n  if (!task) return null\n  const isInitializing = executionStore.isJobInitializing(String(task?.jobId))\n  return jobStateFromTask(task, isInitializing)\n})\n\nconst firstSeenTs = computed<number | undefined>(() => {\n  const task = taskForJob.value\n  return task?.createTime\n})\n\nconst queuedAtValue = computed(() =>\n  firstSeenTs.value !== undefined\n    ? formatClockTime(firstSeenTs.value, locale.value)\n    : ''\n)\n\nconst currentJobPriority = computed<number | null>(() => {\n  const task = taskForJob.value\n  return task ? Number(task.job.priority) : null\n})\n\nconst jobsAhead = computed<number | null>(() => {\n  const idx = currentJobPriority.value\n  if (idx == null) return null\n  const ahead = queueStore.pendingTasks.filter(\n    (t: TaskItemImpl) => Number(t.job.priority) < idx\n  )\n  return ahead.length\n})\n\nconst queuePositionValue = computed(() => {\n  if (jobsAhead.value == null) return ''\n  const n = jobsAhead.value\n  return t('queue.jobDetails.queuePositionValue', { count: n }, n)\n})\n\nconst nowTs = ref<number>(Date.now())\nlet timer: number | null = null\nonMounted(() => {\n  timer = window.setInterval(() => {\n    nowTs.value = Date.now()\n  }, 1000)\n})\nonUnmounted(() => {\n  if (timer != null) {\n    clearInterval(timer)\n    timer = null\n  }\n})\n\nconst {\n  showParallelQueuedStats,\n  estimateRangeSeconds,\n  estimateRemainingRangeSeconds,\n  timeElapsedValue\n} = useQueueEstimates({\n  queueStore,\n  executionStore,\n  taskForJob,\n  jobState,\n  firstSeenTs,\n  jobsAhead,\n  nowTs\n})\n\nconst formatEta = (lo: number, hi: number): string => {\n  if (hi <= 60) {\n    const hiS = Math.max(1, Math.round(hi))\n    const loS = Math.max(1, Math.min(hiS, Math.round(lo)))\n    if (loS === hiS)\n      return t('queue.jobDetails.eta.seconds', { count: hiS }, hiS)\n    return t('queue.jobDetails.eta.secondsRange', { lo: loS, hi: hiS })\n  }\n  if (lo >= 60 && hi < 90) {\n    return t('queue.jobDetails.eta.minutes', { count: 1 }, 1)\n  }\n  const loM = Math.max(1, Math.floor(lo / 60))\n  const hiM = Math.max(loM, Math.ceil(hi / 60))\n  if (loM === hiM) {\n    return t('queue.jobDetails.eta.minutes', { count: loM }, loM)\n  }\n  return t('queue.jobDetails.eta.minutesRange', { lo: loM, hi: hiM })\n}\n\nconst estimatedStartInValue = computed(() => {\n  const range = estimateRangeSeconds.value\n  if (!range) return ''\n  const [lo, hi] = range\n  return formatEta(lo, hi)\n})\n\nconst estimatedFinishInValue = computed(() => {\n  const range = estimateRemainingRangeSeconds.value\n  if (!range) return ''\n  const [lo, hi] = range\n  return formatEta(lo, hi)\n})\n\ntype DetailRow = { label: string; value: string; canCopy?: boolean }\n\nconst baseRows = computed<DetailRow[]>(() => [\n  { label: t('queue.jobDetails.workflow'), value: workflowValue.value },\n  { label: t('queue.jobDetails.jobId'), value: jobIdValue.value, canCopy: true }\n])\n\nconst extraRows = computed<DetailRow[]>(() => {\n  if (jobState.value === 'pending') {\n    if (!firstSeenTs.value) return []\n    const rows: DetailRow[] = [\n      { label: t('queue.jobDetails.queuedAt'), value: queuedAtValue.value }\n    ]\n    if (showParallelQueuedStats.value) {\n      rows.push(\n        {\n          label: t('queue.jobDetails.queuePosition'),\n          value: queuePositionValue.value\n        },\n        {\n          label: t('queue.jobDetails.timeElapsed'),\n          value: timeElapsedValue.value\n        },\n        {\n          label: t('queue.jobDetails.estimatedStartIn'),\n          value: estimatedStartInValue.value\n        }\n      )\n    }\n    return rows\n  }\n  if (jobState.value === 'running') {\n    if (!firstSeenTs.value) return []\n    return [\n      { label: t('queue.jobDetails.queuedAt'), value: queuedAtValue.value },\n      {\n        label: t('queue.jobDetails.timeElapsed'),\n        value: timeElapsedValue.value\n      },\n      {\n        label: t('queue.jobDetails.estimatedFinishIn'),\n        value: estimatedFinishInValue.value\n      }\n    ]\n  }\n  if (jobState.value === 'completed') {\n    const task = taskForJob.value\n    const endTs: number | undefined = task?.executionEndTimestamp\n    const execMs: number | undefined = task?.executionTime\n    const generatedOnValue = endTs ? formatClockTime(endTs, locale.value) : ''\n    const totalGenTimeValue =\n      execMs !== undefined ? formatElapsedTime(execMs) : ''\n    const computeHoursValue =\n      execMs !== undefined ? (execMs / 3600000).toFixed(3) + ' hours' : ''\n\n    const rows: DetailRow[] = [\n      { label: t('queue.jobDetails.generatedOn'), value: generatedOnValue },\n      {\n        label: t('queue.jobDetails.totalGenerationTime'),\n        value: totalGenTimeValue\n      }\n    ]\n    if (isCloud) {\n      rows.push({\n        label: t('queue.jobDetails.computeHoursUsed'),\n        value: computeHoursValue\n      })\n    }\n    return rows\n  }\n  if (jobState.value === 'failed') {\n    const task = taskForJob.value\n    const execMs: number | undefined = task?.executionTime\n    const failedAfterValue =\n      execMs !== undefined ? formatElapsedTime(execMs) : ''\n    const computeHoursValue =\n      execMs !== undefined ? (execMs / 3600000).toFixed(3) + ' hours' : ''\n    const rows: DetailRow[] = [\n      { label: t('queue.jobDetails.queuedAt'), value: queuedAtValue.value },\n      { label: t('queue.jobDetails.failedAfter'), value: failedAfterValue }\n    ]\n    if (isCloud) {\n      rows.push({\n        label: t('queue.jobDetails.computeHoursUsed'),\n        value: computeHoursValue\n      })\n    }\n    return rows\n  }\n  return []\n})\n\nconst { errorMessageValue, copyErrorMessage, reportJobError } =\n  useJobErrorReporting({\n    taskForJob,\n    copyToClipboard,\n    dialog\n  })\n</script>\n","<template>\n  <Popover :open=\"isOpen\" @update:open=\"onOpenChange\">\n    <PopoverContent\n      v-if=\"hasReference\"\n      :reference=\"referenceElement ?? undefined\"\n      data-testid=\"queue-job-details-popover\"\n      side=\"right\"\n      align=\"start\"\n      :side-offset=\"8\"\n      :collision-padding=\"8\"\n      :avoid-collisions=\"true\"\n      :side-flip=\"true\"\n      :hide-when-detached=\"true\"\n      position-strategy=\"fixed\"\n      sticky=\"always\"\n      class=\"job-details-popover z-1700 max-h-(--reka-popover-content-available-height) w-auto overflow-y-auto border-0 bg-transparent p-0 shadow-none will-change-transform\"\n      @mouseenter=\"$emit('content-enter')\"\n      @mouseleave=\"$emit('content-leave')\"\n      @open-auto-focus.prevent\n      @close-auto-focus.prevent\n    >\n      <JobDetailsPopover\n        v-if=\"jobId\"\n        :job-id=\"jobId\"\n        :workflow-id=\"workflowId\"\n      />\n    </PopoverContent>\n  </Popover>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport JobDetailsPopover from '@/components/queue/job/JobDetailsPopover.vue'\nimport Popover from '@/components/ui/popover/Popover.vue'\nimport PopoverContent from '@/components/ui/popover/PopoverContent.vue'\n\nconst {\n  open,\n  jobId = null,\n  workflowId,\n  referenceElement = null\n} = defineProps<{\n  open: boolean\n  jobId?: string | null\n  workflowId?: string\n  referenceElement?: HTMLElement | null\n}>()\n\nconst emit = defineEmits<{\n  (e: 'content-enter'): void\n  (e: 'content-leave'): void\n  (e: 'update:open', open: boolean): void\n}>()\n\nconst isOpen = computed(() => open && !!jobId)\nconst hasReference = computed(() => !!jobId && !!referenceElement)\n\nfunction onOpenChange(nextOpen: boolean) {\n  emit('update:open', nextOpen)\n}\n</script>\n","type ProgressPercent = number | undefined\n\nconst progressBarContainerClass = 'absolute inset-0'\nconst progressBarBaseClass =\n  'pointer-events-none absolute inset-y-0 left-0 h-full transition-[width]'\nconst progressBarPrimaryClass = `${progressBarBaseClass} bg-interface-panel-job-progress-primary`\nconst progressBarSecondaryClass = `${progressBarBaseClass} bg-interface-panel-job-progress-secondary`\n\nfunction clampPercent(value: number) {\n  return Math.min(100, Math.max(0, value))\n}\n\nfunction normalizeProgressPercent(value: ProgressPercent) {\n  if (value === undefined || !Number.isFinite(value)) return undefined\n\n  return clampPercent(value)\n}\n\nfunction hasProgressPercent(value: ProgressPercent) {\n  return normalizeProgressPercent(value) !== undefined\n}\n\nfunction hasAnyProgressPercent(\n  totalPercent: ProgressPercent,\n  currentPercent: ProgressPercent\n) {\n  return hasProgressPercent(totalPercent) || hasProgressPercent(currentPercent)\n}\n\nfunction progressPercentStyle(value: ProgressPercent) {\n  const normalized = normalizeProgressPercent(value)\n\n  if (normalized === undefined) return undefined\n\n  return { width: `${normalized}%` }\n}\n\nexport function useProgressBarBackground() {\n  return {\n    progressBarContainerClass,\n    progressBarPrimaryClass,\n    progressBarSecondaryClass,\n    hasProgressPercent,\n    hasAnyProgressPercent,\n    progressPercentStyle\n  }\n}\n","<template>\n  <div\n    class=\"relative flex items-center gap-2 overflow-hidden rounded-lg p-2 select-none\"\n    :aria-describedby=\"\n      videoStatus === 'failed' ? videoFailedDescriptionId : undefined\n    \"\n  >\n    <div\n      v-if=\"hasAnyProgressPercent(progressTotalPercent, progressCurrentPercent)\"\n      :class=\"progressBarContainerClass\"\n    >\n      <div\n        v-if=\"hasProgressPercent(progressTotalPercent)\"\n        :class=\"progressBarPrimaryClass\"\n        :style=\"progressPercentStyle(progressTotalPercent)\"\n      />\n      <div\n        v-if=\"hasProgressPercent(progressCurrentPercent)\"\n        :class=\"progressBarSecondaryClass\"\n        :style=\"progressPercentStyle(progressCurrentPercent)\"\n      />\n    </div>\n\n    <div\n      :class=\"\n        cn(\n          'relative z-1 flex size-8 shrink-0 items-center justify-center overflow-hidden rounded-sm bg-secondary-background',\n          iconWrapperClass\n        )\n      \"\n      :aria-label=\"iconAriaLabel || undefined\"\n    >\n      <slot\n        name=\"icon\"\n        :preview-url=\"previewUrl\"\n        :preview-alt=\"previewAlt\"\n        :icon-name=\"iconName\"\n        :icon-class=\"iconClass\"\n        :icon-aria-label=\"iconAriaLabel\"\n      >\n        <div\n          v-if=\"previewUrl\"\n          class=\"relative size-full\"\n          @click=\"emit('preview-click')\"\n        >\n          <template v-if=\"isVideoPreview\">\n            <video\n              v-if=\"videoStatus !== 'failed'\"\n              :src=\"videoSrc\"\n              preload=\"metadata\"\n              muted\n              playsinline\n              class=\"pointer-events-none size-full object-cover\"\n              @error=\"onVideoError\"\n            />\n            <VideoPlayOverlay v-if=\"videoStatus !== 'failed'\" size=\"sm\" />\n            <i\n              v-if=\"videoStatus === 'failed'\"\n              aria-hidden=\"true\"\n              class=\"absolute inset-0 m-auto icon-[lucide--video-off] size-4 text-text-secondary\"\n            />\n          </template>\n          <img\n            v-else-if=\"failedImageUrl !== previewUrl\"\n            :src=\"previewUrl\"\n            :alt=\"previewAlt\"\n            class=\"size-full object-cover\"\n            :draggable=\"false\"\n            @error=\"failedImageUrl = previewUrl\"\n          />\n          <i\n            v-else\n            aria-hidden=\"true\"\n            class=\"absolute inset-0 m-auto icon-[lucide--image] size-4 text-text-secondary\"\n          />\n        </div>\n        <div\n          v-else\n          class=\"flex size-full items-center justify-center\"\n          @click=\"emit('preview-click')\"\n        >\n          <i\n            aria-hidden=\"true\"\n            :class=\"\n              cn(\n                iconName ?? 'icon-[lucide--image]',\n                'size-4 text-text-secondary',\n                iconClass\n              )\n            \"\n          />\n        </div>\n      </slot>\n    </div>\n\n    <div class=\"relative z-1 flex min-w-0 flex-1 flex-col gap-1\">\n      <div\n        v-if=\"$slots.primary || primaryText\"\n        class=\"min-w-0 text-xs leading-none text-text-primary\"\n      >\n        <slot v-if=\"$slots.primary\" name=\"primary\" />\n        <span v-else class=\"block truncate\" :title=\"primaryText\">\n          {{ primaryText }}\n        </span>\n      </div>\n      <div\n        v-if=\"$slots.secondary || secondaryText\"\n        class=\"min-w-0 text-xs leading-none text-text-secondary\"\n      >\n        <slot v-if=\"$slots.secondary\" name=\"secondary\" />\n        <span v-else class=\"block truncate\" :title=\"secondaryText\">\n          {{ secondaryText }}\n        </span>\n      </div>\n    </div>\n\n    <div\n      v-if=\"$slots.actions\"\n      class=\"relative z-1 flex shrink-0 items-center gap-2\"\n    >\n      <slot name=\"actions\" />\n    </div>\n\n    <div\n      v-if=\"typeof stackCount === 'number' && stackCount > 1\"\n      class=\"relative z-1 flex shrink-0 items-center\"\n    >\n      <Button\n        variant=\"secondary\"\n        size=\"md\"\n        class=\"gap-1 font-bold\"\n        :aria-label=\"stackIndicatorLabel\"\n        :aria-expanded=\"stackExpanded\"\n        @click.stop=\"emit('stack-toggle')\"\n      >\n        <i aria-hidden=\"true\" class=\"icon-[lucide--layers] size-4\" />\n        <span class=\"text-xs leading-none\">{{ stackCount }}</span>\n        <i\n          aria-hidden=\"true\"\n          :class=\"\n            cn(\n              stackExpanded\n                ? 'icon-[lucide--chevron-down]'\n                : 'icon-[lucide--chevron-right]',\n              'size-3'\n            )\n          \"\n        />\n      </Button>\n    </div>\n\n    <span\n      v-if=\"videoStatus === 'failed'\"\n      :id=\"videoFailedDescriptionId\"\n      class=\"sr-only\"\n    >\n      {{ $t('g.videoFailedToLoad') }}\n    </span>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, useId } from 'vue'\n\nimport { useRetryableMediaSrc } from '@/composables/media/useRetryableMediaSrc'\nimport { useProgressBarBackground } from '@/composables/useProgressBarBackground'\nimport Button from '@/components/ui/button/Button.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport VideoPlayOverlay from './VideoPlayOverlay.vue'\n\nconst emit = defineEmits<{\n  'stack-toggle': []\n  'preview-click': []\n}>()\n\nconst {\n  previewUrl,\n  previewAlt = '',\n  iconName,\n  iconAriaLabel,\n  iconClass,\n  iconWrapperClass,\n  isVideoPreview = false,\n  primaryText,\n  secondaryText,\n  stackCount,\n  stackIndicatorLabel,\n  stackExpanded = false,\n  progressTotalPercent,\n  progressCurrentPercent\n} = defineProps<{\n  previewUrl?: string\n  previewAlt?: string\n  iconName?: string\n  iconAriaLabel?: string\n  iconClass?: string\n  iconWrapperClass?: string\n  isVideoPreview?: boolean\n  primaryText?: string\n  secondaryText?: string\n  stackCount?: number\n  stackIndicatorLabel?: string\n  stackExpanded?: boolean\n  progressTotalPercent?: number\n  progressCurrentPercent?: number\n}>()\n\nconst {\n  src: videoSrc,\n  status: videoStatus,\n  onError: onVideoError\n} = useRetryableMediaSrc(() => (isVideoPreview ? previewUrl : undefined))\n\nconst videoFailedDescriptionId = useId()\nconst failedImageUrl = ref<string>()\n\nconst {\n  progressBarContainerClass,\n  progressBarPrimaryClass,\n  progressBarSecondaryClass,\n  hasProgressPercent,\n  hasAnyProgressPercent,\n  progressPercentStyle\n} = useProgressBarBackground()\n</script>\n","import type { TaskItemImpl } from '@/stores/queueStore'\nimport { resultItemUrl } from '@/utils/resultItemUrl'\nimport { isImageResult } from '@/utils/resultItem'\nimport type { JobState } from '@/types/queue'\nimport { formatDuration } from '@/utils/formatUtil'\nimport { clampPercentInt, formatPercent0 } from '@/utils/numberUtil'\n\nexport type BuildJobDisplayCtx = {\n  t: (k: string, v?: Record<string, unknown>) => string\n  locale: string\n  formatClockTimeFn: (ts: number, locale: string) => string\n  isActive: boolean\n  totalPercent?: number\n  currentNodePercent?: number\n  currentNodeName?: string\n  showAddedHint?: boolean\n  /** Whether the app is running in cloud distribution */\n  isCloud?: boolean\n}\n\ntype JobDisplay = {\n  iconName: string\n  iconImageUrl?: string\n  primary: string\n  secondary: string\n  showClear: boolean\n}\n\nexport const iconForJobState = (state: JobState): string => {\n  switch (state) {\n    case 'pending':\n      return 'icon-[lucide--loader-circle]'\n    case 'initialization':\n      return 'icon-[lucide--server-crash]'\n    case 'running':\n      return 'icon-[lucide--zap]'\n    case 'completed':\n      return 'icon-[lucide--check-check]'\n    case 'failed':\n      return 'icon-[lucide--alert-circle]'\n    default:\n      return 'icon-[lucide--circle]'\n  }\n}\n\nconst buildTitle = (task: TaskItemImpl, t: (k: string) => string): string => {\n  const prefix = t('g.job')\n  const shortId = task.jobId.split('-')[0]\n  const idx = task.job.priority\n  if (typeof idx === 'number') return `${prefix} #${idx}`\n  if (shortId) return `${prefix} ${shortId}`\n  return prefix\n}\n\nconst buildQueuedTime = (\n  task: TaskItemImpl,\n  locale: string,\n  formatClockTimeFn: (ts: number, locale: string) => string\n): string => {\n  const ts = task.createTime\n  return formatClockTimeFn(ts, locale)\n}\n\nexport const buildJobDisplay = (\n  task: TaskItemImpl,\n  state: JobState,\n  ctx: BuildJobDisplayCtx\n): JobDisplay => {\n  if (state === 'pending') {\n    if (ctx.showAddedHint) {\n      return {\n        iconName: 'icon-[lucide--check]',\n        primary: ctx.t('queue.jobAddedToQueue'),\n        secondary: buildQueuedTime(task, ctx.locale, ctx.formatClockTimeFn),\n        showClear: true\n      }\n    }\n    return {\n      iconName: iconForJobState(state),\n      primary: ctx.t('queue.inQueue'),\n      secondary: buildQueuedTime(task, ctx.locale, ctx.formatClockTimeFn),\n      showClear: true\n    }\n  }\n  if (state === 'initialization') {\n    return {\n      iconName: iconForJobState(state),\n      primary: ctx.t('queue.initializingAlmostReady'),\n      secondary: buildQueuedTime(task, ctx.locale, ctx.formatClockTimeFn),\n      showClear: true\n    }\n  }\n  if (state === 'running') {\n    if (ctx.isActive) {\n      const total = formatPercent0(\n        ctx.locale,\n        clampPercentInt(ctx.totalPercent)\n      )\n      const curr = formatPercent0(\n        ctx.locale,\n        clampPercentInt(ctx.currentNodePercent)\n      )\n      const primary = ctx.t('sideToolbar.queueProgressOverlay.total', {\n        percent: total\n      })\n      const right = ctx.currentNodeName\n        ? `${ctx.currentNodeName} ${ctx.t(\n            'sideToolbar.queueProgressOverlay.colonPercent',\n            { percent: curr }\n          )}`\n        : ''\n      return {\n        iconName: iconForJobState(state),\n        primary,\n        secondary: right,\n        showClear: true\n      }\n    }\n    return {\n      iconName: iconForJobState(state),\n      primary: ctx.t('g.running'),\n      secondary: '',\n      showClear: true\n    }\n  }\n  if (state === 'completed') {\n    const time = task.executionTimeInSeconds\n    const preview = task.previewOutput\n    const iconImageUrl =\n      preview && isImageResult(preview) ? resultItemUrl(preview) : undefined\n\n    // Cloud shows \"Completed in Xh Ym Zs\", non-cloud shows filename\n    const primary = ctx.isCloud\n      ? ctx.t('queue.completedIn', {\n          duration: formatDuration(task.executionTime ?? 0)\n        })\n      : preview?.filename && preview.filename.length\n        ? preview.filename\n        : buildTitle(task, ctx.t)\n\n    return {\n      iconName: iconForJobState(state),\n      iconImageUrl,\n      primary,\n      secondary: time !== undefined ? `${time.toFixed(2)}s` : '',\n      showClear: false\n    }\n  }\n  return {\n    iconName: iconForJobState(state),\n    primary: ctx.t('g.failed'),\n    secondary: ctx.t('g.failed'),\n    showClear: true\n  }\n}\n","import type { JobGroup, JobListItem } from '@/composables/queue/useJobList'\n\nexport type VirtualJobRow =\n  | {\n      key: string\n      type: 'header'\n      label: string\n    }\n  | {\n      key: string\n      type: 'job'\n      job: JobListItem\n    }\n\nexport function buildVirtualJobRows(\n  displayedJobGroups: JobGroup[]\n): VirtualJobRow[] {\n  const rows: VirtualJobRow[] = []\n\n  displayedJobGroups.forEach((group) => {\n    rows.push({\n      key: `header-${group.key}`,\n      type: 'header',\n      label: group.label\n    })\n\n    group.items.forEach((job) => {\n      rows.push({\n        key: `job-${job.id}`,\n        type: 'job',\n        job\n      })\n    })\n  })\n\n  return rows\n}\n","<template>\n  <div\n    ref=\"scrollContainer\"\n    :tabindex=\"hasJobRows ? 0 : -1\"\n    :role=\"hasJobRows ? 'region' : undefined\"\n    :aria-label=\"hasJobRows ? $t('g.jobs') : undefined\"\n    v-bind=\"$attrs\"\n    data-testid=\"job-assets-list\"\n    class=\"h-full overflow-y-auto pb-4\"\n    @scroll=\"onListScroll\"\n  >\n    <div :style=\"virtualWrapperStyle\">\n      <template v-for=\"{ row, virtualItem } in virtualRows\" :key=\"row.key\">\n        <div\n          v-if=\"row.type === 'header'\"\n          class=\"box-border px-3 pb-2 text-xs leading-none text-text-secondary\"\n          :style=\"getVirtualRowStyle(virtualItem)\"\n        >\n          {{ row.label }}\n        </div>\n        <div\n          v-else-if=\"row.type === 'job'\"\n          class=\"box-border px-3\"\n          :style=\"getVirtualRowStyle(virtualItem)\"\n        >\n          <div\n            :data-job-id=\"row.job.id\"\n            class=\"h-12\"\n            @mouseenter=\"onJobEnter(row.job, $event)\"\n            @mouseleave=\"onJobLeave(row.job.id)\"\n          >\n            <AssetsListItem\n              :class=\"\n                cn(\n                  'size-full shrink-0 cursor-default text-text-primary transition-colors hover:bg-secondary-background-hover',\n                  row.job.state === 'running' && 'bg-secondary-background'\n                )\n              \"\n              :preview-url=\"getJobPreviewUrl(row.job)\"\n              :is-video-preview=\"isVideoPreviewJob(row.job)\"\n              :preview-alt=\"row.job.title\"\n              :icon-name=\"row.job.iconName ?? iconForJobState(row.job.state)\"\n              :icon-class=\"getJobIconClass(row.job)\"\n              :primary-text=\"row.job.title\"\n              :secondary-text=\"row.job.meta\"\n              :progress-total-percent=\"row.job.progressTotalPercent\"\n              :progress-current-percent=\"row.job.progressCurrentPercent\"\n              @contextmenu.prevent.stop=\"$emit('menu', row.job, $event)\"\n              @dblclick.stop=\"emitViewItem(row.job)\"\n              @preview-click=\"emitViewItem(row.job)\"\n              @click.stop\n            >\n              <template v-if=\"hoveredJobId === row.job.id\" #actions>\n                <Button\n                  v-if=\"isCancelable(row.job)\"\n                  variant=\"destructive\"\n                  size=\"icon\"\n                  :aria-label=\"t('g.cancel')\"\n                  @click.stop=\"emitCancelItem(row.job)\"\n                >\n                  <i class=\"icon-[lucide--x] size-4\" />\n                </Button>\n                <Button\n                  v-else-if=\"isFailedDeletable(row.job)\"\n                  variant=\"destructive\"\n                  size=\"icon\"\n                  :aria-label=\"t('g.delete')\"\n                  @click.stop=\"emitDeleteItem(row.job)\"\n                >\n                  <i class=\"icon-[lucide--trash-2] size-4\" />\n                </Button>\n                <Button\n                  v-else-if=\"row.job.state === 'completed'\"\n                  variant=\"textonly\"\n                  size=\"sm\"\n                  @click.stop=\"emitCompletedViewItem(row.job)\"\n                >\n                  {{ t('menuLabels.View') }}\n                </Button>\n                <Button\n                  variant=\"secondary\"\n                  size=\"icon\"\n                  :aria-label=\"t('g.more')\"\n                  @click.stop=\"$emit('menu', row.job, $event)\"\n                >\n                  <i class=\"icon-[lucide--ellipsis] size-4\" />\n                </Button>\n              </template>\n            </AssetsListItem>\n          </div>\n        </div>\n      </template>\n    </div>\n  </div>\n\n  <JobDetailsHoverPopover\n    :open=\"isDetailsOpen && !!activeDetails && !!activeRowElement\"\n    :job-id=\"activeDetails?.jobId\"\n    :workflow-id=\"activeDetails?.workflowId\"\n    :reference-element=\"activeRowElement\"\n    @content-enter=\"onPopoverEnter\"\n    @content-leave=\"onPopoverLeave\"\n    @update:open=\"onPopoverOpenChange\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport type { VirtualItem } from '@tanstack/vue-virtual'\nimport type { CSSProperties } from 'vue'\nimport { useVirtualizer } from '@tanstack/vue-virtual'\nimport { useI18n } from 'vue-i18n'\nimport { computed, onBeforeUnmount, ref, watch } from 'vue'\n\nimport JobDetailsHoverPopover from '@/components/queue/job/JobDetailsHoverPopover.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { JobGroup, JobListItem } from '@/composables/queue/useJobList'\nimport { resultItemPreviewUrl } from '@/utils/resultItemUrl'\nimport { isImageResult, isVideoResult } from '@/utils/resultItem'\nimport AssetsListItem from '@/platform/assets/components/AssetsListItem.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { iconForJobState } from '@/utils/queueDisplay'\nimport { isActiveJobState } from '@/utils/queueUtil'\n\nimport { buildVirtualJobRows } from './buildVirtualJobRows'\nimport type { VirtualJobRow } from './buildVirtualJobRows'\n\nconst HEADER_ROW_HEIGHT = 20\nconst GROUP_ROW_GAP = 16\nconst JOB_ROW_HEIGHT = 48\nconst DETAILS_SHOW_DELAY_MS = 200\nconst DETAILS_HIDE_DELAY_MS = 150\n\ndefineOptions({\n  inheritAttrs: false\n})\n\nconst { displayedJobGroups } = defineProps<{ displayedJobGroups: JobGroup[] }>()\n\nconst emit = defineEmits<{\n  (e: 'cancelItem', item: JobListItem): void\n  (e: 'deleteItem', item: JobListItem): void\n  (e: 'menu', item: JobListItem, ev: MouseEvent): void\n  (e: 'viewItem', item: JobListItem): void\n}>()\n\nconst { t } = useI18n()\nconst scrollContainer = ref<HTMLElement | null>(null)\nconst hoveredJobId = ref<string | null>(null)\nconst activeRowElement = ref<HTMLElement | null>(null)\nconst activeDetails = ref<{ jobId: string; workflowId?: string } | null>(null)\nconst isDetailsOpen = ref(false)\nconst hideTimer = ref<number | null>(null)\nconst hideTimerJobId = ref<string | null>(null)\nconst showTimer = ref<number | null>(null)\nconst flatRows = computed(() => buildVirtualJobRows(displayedJobGroups))\nconst hasJobRows = computed(() =>\n  flatRows.value.some((row) => row.type === 'job')\n)\nconst virtualizer = useVirtualizer({\n  get count(): number {\n    return flatRows.value.length\n  },\n  getItemKey(index: number) {\n    return flatRows.value[index]?.key ?? index\n  },\n  estimateSize(index: number) {\n    const row = flatRows.value[index]\n    return row ? getRowHeight(row, index, flatRows.value) : JOB_ROW_HEIGHT\n  },\n  getScrollElement() {\n    return scrollContainer.value\n  },\n  overscan: 12\n})\nconst virtualRows = computed(() => {\n  const rows = flatRows.value\n  return virtualizer.value\n    .getVirtualItems()\n    .flatMap((virtualItem: VirtualItem) => {\n      const row = rows[virtualItem.index]\n      return row ? [{ row, virtualItem }] : []\n    })\n})\nconst virtualWrapperStyle = computed<CSSProperties>(() => ({\n  position: 'relative',\n  width: '100%',\n  ...(flatRows.value.length > 0 && {\n    height: `${virtualizer.value.getTotalSize()}px`\n  })\n}))\nfunction getVirtualRowStyle(virtualItem: VirtualItem): CSSProperties {\n  return {\n    position: 'absolute',\n    top: 0,\n    left: 0,\n    width: '100%',\n    height: `${virtualItem.size}px`,\n    transform: `translateY(${virtualItem.start}px)`,\n    overflowAnchor: 'none'\n  }\n}\n\nfunction getRowHeight(\n  row: VirtualJobRow,\n  index: number,\n  rows: VirtualJobRow[]\n): number {\n  if (row.type === 'header') {\n    return HEADER_ROW_HEIGHT\n  }\n\n  return (\n    JOB_ROW_HEIGHT + (rows[index + 1]?.type === 'header' ? GROUP_ROW_GAP : 0)\n  )\n}\n\nfunction onListScroll() {\n  hoveredJobId.value = null\n  resetActiveDetails()\n}\n\nfunction clearPopoverAnchor() {\n  activeRowElement.value = null\n}\n\nfunction clearHideTimer() {\n  if (hideTimer.value !== null) {\n    clearTimeout(hideTimer.value)\n    hideTimer.value = null\n  }\n  hideTimerJobId.value = null\n}\n\nfunction clearShowTimer() {\n  if (showTimer.value !== null) {\n    clearTimeout(showTimer.value)\n    showTimer.value = null\n  }\n}\n\nfunction clearHoverTimers() {\n  clearHideTimer()\n  clearShowTimer()\n}\n\nfunction resetActiveDetails() {\n  clearHoverTimers()\n  isDetailsOpen.value = false\n  activeDetails.value = null\n  clearPopoverAnchor()\n}\n\nfunction hasDisplayedJob(jobId: string) {\n  return displayedJobGroups.some((group) =>\n    group.items.some((item) => item.id === jobId)\n  )\n}\n\nfunction scheduleDetailsShow(nextActive: {\n  jobId: string\n  workflowId?: string\n}) {\n  clearShowTimer()\n  showTimer.value = window.setTimeout(() => {\n    showTimer.value = null\n    if (!hasDisplayedJob(nextActive.jobId)) return\n\n    activeDetails.value = nextActive\n    isDetailsOpen.value = true\n  }, DETAILS_SHOW_DELAY_MS)\n}\n\nfunction showDetailsNow(nextActive: { jobId: string; workflowId?: string }) {\n  clearHoverTimers()\n  if (!hasDisplayedJob(nextActive.jobId)) return\n\n  activeDetails.value = nextActive\n  isDetailsOpen.value = true\n}\n\nfunction scheduleDetailsHide(jobId?: string) {\n  if (!jobId) return\n\n  clearShowTimer()\n  if (hideTimerJobId.value && hideTimerJobId.value !== jobId) {\n    return\n  }\n\n  clearHideTimer()\n  hideTimerJobId.value = jobId\n  hideTimer.value = window.setTimeout(() => {\n    const currentActive = activeDetails.value\n    if (currentActive?.jobId === jobId) {\n      isDetailsOpen.value = false\n    }\n    hideTimer.value = null\n    hideTimerJobId.value = null\n  }, DETAILS_HIDE_DELAY_MS)\n}\n\nfunction onJobLeave(jobId: string) {\n  if (hoveredJobId.value === jobId) {\n    hoveredJobId.value = null\n  }\n  scheduleDetailsHide(jobId)\n}\n\nfunction onJobEnter(job: JobListItem, event: MouseEvent) {\n  hoveredJobId.value = job.id\n\n  const rowElement = event.currentTarget\n  if (!(rowElement instanceof HTMLElement)) return\n\n  activeRowElement.value = rowElement\n  const nextActive = {\n    jobId: job.id,\n    workflowId: job.taskRef?.workflowId\n  }\n\n  if (isDetailsOpen.value && activeDetails.value?.jobId === job.id) {\n    clearHoverTimers()\n    return\n  }\n\n  const isSwitchingVisibleDetails = isDetailsOpen.value\n  const showDetails = isSwitchingVisibleDetails\n    ? showDetailsNow\n    : scheduleDetailsShow\n\n  showDetails(nextActive)\n}\n\nfunction isCancelable(job: JobListItem) {\n  return job.showClear !== false && isActiveJobState(job.state)\n}\n\nfunction isFailedDeletable(job: JobListItem) {\n  return job.showClear !== false && job.state === 'failed'\n}\n\nfunction getPreviewOutput(job: JobListItem) {\n  return job.taskRef?.previewOutput\n}\n\nfunction getJobPreviewUrl(job: JobListItem) {\n  const preview = getPreviewOutput(job)\n  if (preview && (isImageResult(preview) || isVideoResult(preview))) {\n    return resultItemPreviewUrl(preview)\n  }\n  return job.iconImageUrl\n}\n\nfunction isVideoPreviewJob(job: JobListItem) {\n  const preview = getPreviewOutput(job)\n  return job.state === 'completed' && !!preview && isVideoResult(preview)\n}\n\nfunction isPreviewableCompletedJob(job: JobListItem) {\n  return job.state === 'completed' && !!getPreviewOutput(job)\n}\n\nfunction emitViewItem(job: JobListItem) {\n  if (isPreviewableCompletedJob(job)) {\n    resetActiveDetails()\n    emit('viewItem', job)\n  }\n}\n\nfunction emitCompletedViewItem(job: JobListItem) {\n  resetActiveDetails()\n  emit('viewItem', job)\n}\n\nfunction emitCancelItem(job: JobListItem) {\n  resetActiveDetails()\n  emit('cancelItem', job)\n}\n\nfunction emitDeleteItem(job: JobListItem) {\n  resetActiveDetails()\n  emit('deleteItem', job)\n}\n\nfunction onPopoverEnter() {\n  clearHoverTimers()\n}\n\nfunction onPopoverLeave() {\n  scheduleDetailsHide(activeDetails.value?.jobId)\n}\n\nfunction onPopoverOpenChange(open: boolean) {\n  if (!open) {\n    resetActiveDetails()\n  }\n}\n\nfunction getJobIconClass(job: JobListItem): string | undefined {\n  const iconName = job.iconName ?? iconForJobState(job.state)\n  if (!job.iconImageUrl && iconName === iconForJobState('pending')) {\n    return 'animate-spin'\n  }\n  return undefined\n}\n\nwatch(\n  () => displayedJobGroups,\n  () => {\n    const currentActive = activeDetails.value\n    if (!currentActive) return\n\n    if (!hasDisplayedJob(currentActive.jobId)) {\n      resetActiveDetails()\n    }\n  }\n)\n\nonBeforeUnmount(resetActiveDetails)\n</script>\n","import { refDebounced } from '@vueuse/core'\nimport { orderBy } from 'es-toolkit/array'\nimport { computed, onUnmounted, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useQueueProgress } from '@/composables/queue/useQueueProgress'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useJobPreviewStore } from '@/stores/jobPreviewStore'\nimport { useQueueStore } from '@/stores/queueStore'\nimport type { TaskItemImpl } from '@/stores/queueStore'\nimport type { JobState } from '@/types/queue'\nimport {\n  dateKey,\n  formatClockTime,\n  formatShortMonthDay,\n  isToday,\n  isYesterday\n} from '@/utils/dateTimeUtil'\nimport { resolveNodeDisplayName } from '@/utils/nodeTitleUtil'\nimport { buildJobDisplay } from '@/utils/queueDisplay'\nimport { jobStateFromTask } from '@/utils/queueUtil'\n\nimport type { JobTab } from '@/composables/queue/jobTabs'\n\nexport type { JobTab } from '@/composables/queue/jobTabs'\n\nexport const jobSortModes = ['mostRecent', 'totalGenerationTime'] as const\nexport type JobSortMode = (typeof jobSortModes)[number]\n\n/**\n * UI item in the job list. Mirrors data previously prepared inline.\n */\nexport type JobListItem = {\n  id: string\n  title: string\n  meta: string\n  state: JobState\n  iconName?: string\n  iconImageUrl?: string\n  showClear?: boolean\n  taskRef?: TaskItemImpl\n  progressTotalPercent?: number\n  progressCurrentPercent?: number\n  runningNodeName?: string\n  executionTimeMs?: number\n  computeHours?: number\n}\n\nexport type JobGroup = {\n  key: string\n  label: string\n  items: JobListItem[]\n}\n\nconst ADDED_HINT_DURATION_MS = 3000\nconst relativeTimeFormatterCache = new Map<string, Intl.RelativeTimeFormat>()\nconst optionalValue = <T>(value: T | null | undefined): T | undefined =>\n  value ?? undefined\nconst taskIdToKey = (id: string | number | undefined) => {\n  if (id === undefined) return null\n  const key = String(id)\n  return key.length ? key : null\n}\n\n/**\n * Returns localized Today/Yesterday (capitalized) or localized Mon DD.\n */\nconst dateLabelForTimestamp = (\n  ts: number,\n  locale: string,\n  relativeFormatter: Intl.RelativeTimeFormat\n) => {\n  const formatRelativeDay = (value: number) => {\n    const formatted = relativeFormatter.format(value, 'day')\n    return formatted\n      ? formatted[0].toLocaleUpperCase(locale) + formatted.slice(1)\n      : formatted\n  }\n  if (isToday(ts)) {\n    return formatRelativeDay(0)\n  }\n  if (isYesterday(ts)) {\n    return formatRelativeDay(-1)\n  }\n  return formatShortMonthDay(ts, locale)\n}\n\ntype TaskWithState = {\n  task: TaskItemImpl\n  state: JobState\n}\n\n/**\n * Builds the reactive job list, filters, and grouped view for the queue overlay.\n */\nexport function useJobList() {\n  const { t, locale } = useI18n()\n  const queueStore = useQueueStore()\n  const executionStore = useExecutionStore()\n  const jobPreviewStore = useJobPreviewStore()\n  const workflowStore = useWorkflowStore()\n\n  const seenPendingIds = ref<Set<string>>(new Set())\n  const recentlyAddedPendingIds = ref<Set<string>>(new Set())\n  const addedHintTimeouts = new Map<string, ReturnType<typeof setTimeout>>()\n\n  const clearAddedHintTimeout = (id: string) => {\n    const timeoutId = addedHintTimeouts.get(id)\n    if (timeoutId !== undefined) {\n      clearTimeout(timeoutId)\n      addedHintTimeouts.delete(id)\n    }\n  }\n\n  const scheduleAddedHintExpiry = (id: string) => {\n    clearAddedHintTimeout(id)\n    const timeoutId = setTimeout(() => {\n      addedHintTimeouts.delete(id)\n      const updated = new Set(recentlyAddedPendingIds.value)\n      if (updated.delete(id)) {\n        recentlyAddedPendingIds.value = updated\n      }\n    }, ADDED_HINT_DURATION_MS)\n    addedHintTimeouts.set(id, timeoutId)\n  }\n\n  watch(\n    () =>\n      queueStore.pendingTasks\n        .map((task) => taskIdToKey(task.jobId))\n        .filter((id): id is string => !!id),\n    (pendingIds) => {\n      const pendingSet = new Set(pendingIds)\n      const nextAdded = new Set(recentlyAddedPendingIds.value)\n      const nextSeen = new Set(seenPendingIds.value)\n\n      pendingIds.forEach((id) => {\n        if (!nextSeen.has(id)) {\n          nextSeen.add(id)\n          nextAdded.add(id)\n          scheduleAddedHintExpiry(id)\n        }\n      })\n\n      for (const id of Array.from(nextSeen)) {\n        if (!pendingSet.has(id)) {\n          nextSeen.delete(id)\n          nextAdded.delete(id)\n          clearAddedHintTimeout(id)\n        }\n      }\n\n      recentlyAddedPendingIds.value = nextAdded\n      seenPendingIds.value = nextSeen\n    },\n    { immediate: true }\n  )\n\n  const shouldShowAddedHint = (task: TaskItemImpl, state: JobState) => {\n    if (state !== 'pending') return false\n    const id = taskIdToKey(task.jobId)\n    if (!id) return false\n    return recentlyAddedPendingIds.value.has(id)\n  }\n\n  onUnmounted(() => {\n    addedHintTimeouts.forEach((timeoutId) => clearTimeout(timeoutId))\n    addedHintTimeouts.clear()\n    seenPendingIds.value = new Set<string>()\n    recentlyAddedPendingIds.value = new Set<string>()\n  })\n\n  const { totalPercent, currentNodePercent } = useQueueProgress()\n\n  const relativeTimeFormatter = computed(() => {\n    const localeValue = locale.value\n    let formatter = relativeTimeFormatterCache.get(localeValue)\n    if (!formatter) {\n      formatter = new Intl.RelativeTimeFormat(localeValue, { numeric: 'auto' })\n      relativeTimeFormatterCache.set(localeValue, formatter)\n    }\n    return formatter\n  })\n  const undatedLabel = computed(() => t('queue.jobList.undated') || 'Undated')\n\n  const isJobInitializing = (jobId: string | number | undefined) =>\n    executionStore.isJobInitializing(jobId)\n\n  const currentNodeName = computed(() => {\n    return resolveNodeDisplayName(executionStore.executingNode, {\n      emptyLabel: t('g.emDash'),\n      untitledLabel: t('g.untitled')\n    })\n  })\n\n  const selectedJobTab = ref<JobTab>('All')\n  const selectedWorkflowFilter = ref<'all' | 'current'>('all')\n  const selectedSortMode = ref<JobSortMode>('mostRecent')\n  const searchQuery = ref('')\n  const debouncedSearchQuery = refDebounced(searchQuery, 150)\n\n  const mostRecentTimestamp = (task: TaskItemImpl) =>\n    optionalValue(task.createTime) ?? 0\n\n  const allTasksSorted = computed<TaskItemImpl[]>(() => {\n    const all = [\n      ...queueStore.pendingTasks,\n      ...queueStore.runningTasks,\n      ...queueStore.historyTasks\n    ]\n    return orderBy(all, [mostRecentTimestamp], ['desc'])\n  })\n\n  const tasksWithJobState = computed<TaskWithState[]>(() =>\n    allTasksSorted.value.map((task) => ({\n      task,\n      state: jobStateFromTask(task, isJobInitializing(task.jobId))\n    }))\n  )\n\n  const hasFailedJobs = computed(() =>\n    tasksWithJobState.value.some(({ state }) => state === 'failed')\n  )\n\n  watch(\n    () => hasFailedJobs.value,\n    (hasFailed) => {\n      if (!hasFailed && selectedJobTab.value === 'Failed') {\n        selectedJobTab.value = 'All'\n      }\n    }\n  )\n\n  const filteredTaskEntries = computed<TaskWithState[]>(() => {\n    let entries = tasksWithJobState.value\n    if (selectedJobTab.value === 'Completed') {\n      entries = entries.filter(({ state }) => state === 'completed')\n    } else if (selectedJobTab.value === 'Failed') {\n      entries = entries.filter(({ state }) => state === 'failed')\n    }\n\n    if (selectedWorkflowFilter.value === 'current') {\n      const activeWorkflow = optionalValue<\n        typeof workflowStore.activeWorkflow | null\n      >(workflowStore.activeWorkflow)\n      if (!activeWorkflow) return []\n      const activeId = optionalValue<typeof activeWorkflow.activeState | null>(\n        activeWorkflow.activeState\n      )?.id\n      if (!activeId) return []\n      entries = entries.filter(({ task }) => {\n        const wid = task.workflowId\n        return !!wid && wid === activeId\n      })\n    }\n    return entries\n  })\n\n  const normalizedSearchQuery = computed(() =>\n    debouncedSearchQuery.value.trim().toLocaleLowerCase()\n  )\n\n  const filteredTasks = computed<TaskItemImpl[]>(() =>\n    searchableTaskEntries.value.map(({ task }) => task)\n  )\n\n  const jobItems = computed<JobListItem[]>(() => {\n    return filteredTaskEntries.value.map(({ task, state }) => {\n      const isActive = task.jobId === (executionStore.activeJobId ?? '')\n      const showAddedHint = shouldShowAddedHint(task, state)\n      const promptKey = taskIdToKey(task.jobId)\n      const promptPreviewUrl =\n        state === 'running' && jobPreviewStore.isPreviewEnabled && promptKey\n          ? jobPreviewStore.previewsByPromptId[promptKey]\n          : undefined\n\n      const display = buildJobDisplay(task, state, {\n        t,\n        locale: locale.value,\n        formatClockTimeFn: formatClockTime,\n        isActive,\n        totalPercent: isActive ? totalPercent.value : undefined,\n        currentNodePercent: isActive ? currentNodePercent.value : undefined,\n        currentNodeName: isActive ? currentNodeName.value : undefined,\n        showAddedHint,\n        isCloud\n      })\n\n      return {\n        id: task.jobId,\n        title: display.primary,\n        meta: display.secondary,\n        state,\n        iconName: display.iconName,\n        iconImageUrl: promptPreviewUrl ?? display.iconImageUrl,\n        showClear: display.showClear,\n        taskRef: task,\n        progressTotalPercent:\n          state === 'running' && isActive ? totalPercent.value : undefined,\n        progressCurrentPercent:\n          state === 'running' && isActive\n            ? currentNodePercent.value\n            : undefined,\n        runningNodeName:\n          state === 'running' && isActive ? currentNodeName.value : undefined,\n        executionTimeMs: task.executionTime,\n        computeHours:\n          task.executionTime !== undefined\n            ? task.executionTime / 3_600_000\n            : undefined\n      }\n    })\n  })\n\n  const jobItemById = computed(() => {\n    const m = new Map<string, JobListItem>()\n    jobItems.value.forEach((ji) => m.set(ji.id, ji))\n    return m\n  })\n\n  const searchableTaskEntries = computed<TaskWithState[]>(() => {\n    if (!normalizedSearchQuery.value) return filteredTaskEntries.value\n\n    return filteredTaskEntries.value.filter(({ task }) => {\n      const taskId = task.jobId.toLocaleLowerCase()\n      const item = jobItemById.value.get(task.jobId)\n      if (!item) {\n        return taskId.includes(normalizedSearchQuery.value)\n      }\n\n      const title = item.title.toLocaleLowerCase()\n      const meta = item.meta.toLocaleLowerCase()\n      return (\n        title.includes(normalizedSearchQuery.value) ||\n        meta.includes(normalizedSearchQuery.value) ||\n        taskId.includes(normalizedSearchQuery.value)\n      )\n    })\n  })\n\n  const groupedJobItems = computed<JobGroup[]>(() => {\n    const groups: JobGroup[] = []\n    const index = new Map<string, number>()\n    const localeValue = locale.value\n    for (const { task, state } of searchableTaskEntries.value) {\n      let ts: number | undefined\n      if (state === 'completed' || state === 'failed') {\n        ts = optionalValue(task.executionEndTimestamp ?? task.createTime)\n      } else {\n        ts = optionalValue(task.createTime)\n      }\n      const key = ts === undefined ? 'undated' : dateKey(ts)\n      let groupIdx = index.get(key)\n      if (groupIdx === undefined) {\n        const label =\n          ts === undefined\n            ? undatedLabel.value\n            : dateLabelForTimestamp(\n                ts,\n                localeValue,\n                relativeTimeFormatter.value\n              )\n        groups.push({ key, label, items: [] })\n        groupIdx = groups.length - 1\n        index.set(key, groupIdx)\n      }\n      const ji = jobItemById.value.get(task.jobId)\n      if (ji) groups[groupIdx].items.push(ji)\n    }\n\n    if (selectedSortMode.value === 'totalGenerationTime') {\n      const valueOrDefault = (value: JobListItem['executionTimeMs']) =>\n        typeof value === 'number' && !Number.isNaN(value) ? value : -1\n      const sortByExecutionTimeDesc = (a: JobListItem, b: JobListItem) =>\n        valueOrDefault(b.executionTimeMs) - valueOrDefault(a.executionTimeMs)\n\n      groups.forEach((group) => {\n        group.items.sort(sortByExecutionTimeDesc)\n      })\n    }\n\n    return groups\n  })\n\n  return {\n    // filters/state\n    selectedJobTab,\n    selectedWorkflowFilter,\n    selectedSortMode,\n    searchQuery,\n    hasFailedJobs,\n    // data sources\n    allTasksSorted,\n    filteredTasks,\n    jobItems,\n    groupedJobItems,\n    currentNodeName\n  }\n}\n","<template>\n  <div class=\"flex min-w-0 items-center gap-2\">\n    <SearchInput\n      v-if=\"showSearch\"\n      :model-value=\"searchQuery\"\n      class=\"min-w-0 flex-1\"\n      :placeholder=\"searchPlaceholderText\"\n      @update:model-value=\"onSearchQueryUpdate\"\n    />\n    <div\n      class=\"flex shrink-0 items-center gap-2\"\n      :class=\"{ 'ml-2': !showSearch }\"\n    >\n      <Menu>\n        <template #trigger>\n          <Button\n            :tooltip=\"t('sideToolbar.queueProgressOverlay.filterBy')\"\n            variant=\"secondary\"\n            size=\"icon\"\n            :aria-label=\"t('sideToolbar.queueProgressOverlay.filterJobs')\"\n            icon=\"icon-[lucide--list-filter]\"\n            :indicator=\"selectedWorkflowFilter !== 'all'\"\n          />\n        </template>\n        <MenuRadioGroup\n          v-model=\"selectedWorkflowFilter\"\n          :options=\"workflowFilterOptions\"\n        />\n      </Menu>\n      <Menu>\n        <template #trigger>\n          <Button\n            :tooltip=\"t('sideToolbar.queueProgressOverlay.sortBy')\"\n            variant=\"secondary\"\n            size=\"icon\"\n            :aria-label=\"t('sideToolbar.queueProgressOverlay.sortJobs')\"\n            icon=\"icon-[lucide--arrow-up-down]\"\n            :indicator=\"selectedSortMode !== 'mostRecent'\"\n          />\n        </template>\n        <MenuRadioGroup v-model=\"selectedSortMode\" :options=\"sortOptions\" />\n      </Menu>\n      <Button\n        v-if=\"showAssetsAction\"\n        :tooltip=\"t('sideToolbar.queueProgressOverlay.showAssets')\"\n        variant=\"secondary\"\n        size=\"icon\"\n        :aria-label=\"t('sideToolbar.queueProgressOverlay.showAssetsPanel')\"\n        icon=\"icon-[comfy--image-ai-edit]\"\n        @click=\"emit('showAssets')\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport MenuRadioGroup from '@/components/ui/menu/MenuRadioGroup.vue'\nimport { jobSortModes } from '@/composables/queue/useJobList'\nimport type { JobSortMode } from '@/composables/queue/useJobList'\nimport { useSurveyFeatureTracking } from '@/platform/surveys/useSurveyFeatureTracking'\n\nconst {\n  hideShowAssetsAction = false,\n  showSearch = false,\n  searchPlaceholder\n} = defineProps<{\n  hideShowAssetsAction?: boolean\n  showSearch?: boolean\n  searchPlaceholder?: string\n}>()\n\nconst selectedWorkflowFilter = defineModel<'all' | 'current'>(\n  'selectedWorkflowFilter',\n  { required: true }\n)\nconst selectedSortMode = defineModel<JobSortMode>('selectedSortMode', {\n  required: true\n})\nconst searchQuery = defineModel<string>('searchQuery', { default: '' })\n\nconst emit = defineEmits<{\n  (e: 'showAssets'): void\n}>()\n\nconst { t } = useI18n()\nconst { trackFeatureUsed } = useSurveyFeatureTracking('queue-progress-overlay')\n\nconst showAssetsAction = computed(() => !hideShowAssetsAction)\nconst searchPlaceholderText = computed(\n  () => searchPlaceholder ?? t('sideToolbar.queueProgressOverlay.searchJobs')\n)\n\nconst workflowFilterOptions = computed(() => [\n  {\n    value: 'all' as const,\n    label: t('sideToolbar.queueProgressOverlay.filterAllWorkflows'),\n    command: trackFeatureUsed\n  },\n  {\n    value: 'current' as const,\n    label: t('sideToolbar.queueProgressOverlay.filterCurrentWorkflow'),\n    command: trackFeatureUsed\n  }\n])\nconst sortOptions = computed(() =>\n  jobSortModes.map((value) => ({\n    value,\n    label: sortLabel(value),\n    command: trackFeatureUsed\n  }))\n)\n\nconst onSearchQueryUpdate = (value: string | undefined) => {\n  searchQuery.value = value ?? ''\n}\n\nconst sortLabel = (mode: JobSortMode) => {\n  if (mode === 'mostRecent') {\n    return t('queue.jobList.sortMostRecent')\n  }\n  if (mode === 'totalGenerationTime') {\n    return t('queue.jobList.sortTotalGenerationTime')\n  }\n  return ''\n}\n</script>\n","const jobTabs = ['All', 'Completed', 'Failed'] as const\nexport type JobTab = (typeof jobTabs)[number]\n\nexport const jobTabLabelKeys: Record<JobTab, string> = {\n  All: 'g.all',\n  Completed: 'g.completed',\n  Failed: 'g.failed'\n}\n\nexport function getVisibleJobTabs(hasFailedJobs: boolean): readonly JobTab[] {\n  return jobTabs.filter((tab) => hasFailedJobs || tab !== 'Failed')\n}\n","<template>\n  <div class=\"min-w-0 flex-1 overflow-x-auto\">\n    <div class=\"inline-flex items-center gap-1 whitespace-nowrap\">\n      <Button\n        v-for=\"tab in visibleJobTabs\"\n        :key=\"tab\"\n        :variant=\"selectedJobTab === tab ? 'secondary' : 'muted-textonly'\"\n        size=\"md\"\n        @click=\"$emit('update:selectedJobTab', tab)\"\n      >\n        {{ t(jobTabLabelKeys[tab]) }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { getVisibleJobTabs, jobTabLabelKeys } from '@/composables/queue/jobTabs'\nimport type { JobTab } from '@/composables/queue/jobTabs'\n\nconst { selectedJobTab, hasFailedJobs } = defineProps<{\n  selectedJobTab: JobTab\n  hasFailedJobs: boolean\n}>()\n\ndefineEmits<{\n  (e: 'update:selectedJobTab', value: JobTab): void\n}>()\n\nconst { t } = useI18n()\n\nconst visibleJobTabs = computed(() => getVisibleJobTabs(hasFailedJobs))\n</script>\n","<template>\n  <div class=\"flex items-center justify-between gap-2 px-3\">\n    <JobFilterTabs\n      :selected-job-tab=\"selectedJobTab\"\n      :has-failed-jobs=\"hasFailedJobs\"\n      @update:selected-job-tab=\"$emit('update:selectedJobTab', $event)\"\n    />\n    <JobFilterActions\n      :selected-workflow-filter=\"selectedWorkflowFilter\"\n      :selected-sort-mode=\"selectedSortMode\"\n      :hide-show-assets-action=\"hideShowAssetsAction\"\n      @show-assets=\"$emit('showAssets')\"\n      @update:selected-workflow-filter=\"\n        $emit('update:selectedWorkflowFilter', $event)\n      \"\n      @update:selected-sort-mode=\"$emit('update:selectedSortMode', $event)\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport JobFilterActions from '@/components/queue/job/JobFilterActions.vue'\nimport JobFilterTabs from '@/components/queue/job/JobFilterTabs.vue'\nimport type { JobSortMode, JobTab } from '@/composables/queue/useJobList'\n\nconst {\n  selectedJobTab,\n  selectedWorkflowFilter,\n  selectedSortMode,\n  hasFailedJobs,\n  hideShowAssetsAction\n} = defineProps<{\n  selectedJobTab: JobTab\n  selectedWorkflowFilter: 'all' | 'current'\n  selectedSortMode: JobSortMode\n  hasFailedJobs: boolean\n  hideShowAssetsAction?: boolean\n}>()\n\ndefineEmits<{\n  (e: 'showAssets'): void\n  (e: 'update:selectedJobTab', value: JobTab): void\n  (e: 'update:selectedWorkflowFilter', value: 'all' | 'current'): void\n  (e: 'update:selectedSortMode', value: JobSortMode): void\n}>()\n</script>\n","<template>\n  <div class=\"flex w-full flex-col gap-4\">\n    <QueueOverlayHeader\n      :header-title=\"headerTitle\"\n      :queued-count=\"queuedCount\"\n      @clear-history=\"$emit('clearHistory')\"\n      @clear-queued=\"$emit('clearQueued')\"\n    />\n\n    <JobFiltersBar\n      :selected-job-tab=\"selectedJobTab\"\n      :selected-workflow-filter=\"selectedWorkflowFilter\"\n      :selected-sort-mode=\"selectedSortMode\"\n      :has-failed-jobs=\"hasFailedJobs\"\n      @show-assets=\"$emit('showAssets')\"\n      @update:selected-job-tab=\"onUpdateSelectedJobTab\"\n      @update:selected-workflow-filter=\"\n        $emit('update:selectedWorkflowFilter', $event)\n      \"\n      @update:selected-sort-mode=\"$emit('update:selectedSortMode', $event)\"\n    />\n\n    <div class=\"min-h-0 flex-1\">\n      <JobAssetsList\n        :displayed-job-groups=\"displayedJobGroups\"\n        @cancel-item=\"onCancelItemEvent\"\n        @delete-item=\"onDeleteItemEvent\"\n        @view-item=\"$emit('viewItem', $event)\"\n        @menu=\"onMenuItem\"\n      />\n    </div>\n\n    <ContextMenu ref=\"jobContextMenuRef\" :model=\"jobMenuEntries\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\n\nimport ContextMenu from '@/components/ui/menu/ContextMenu.vue'\nimport type {\n  JobGroup,\n  JobListItem,\n  JobSortMode,\n  JobTab\n} from '@/composables/queue/useJobList'\nimport { useJobMenu } from '@/composables/queue/useJobMenu'\nimport { useSurveyFeatureTracking } from '@/platform/surveys/useSurveyFeatureTracking'\n\nimport QueueOverlayHeader from './QueueOverlayHeader.vue'\nimport JobAssetsList from './job/JobAssetsList.vue'\nimport JobFiltersBar from './job/JobFiltersBar.vue'\n\ndefineProps<{\n  headerTitle: string\n  queuedCount: number\n  selectedJobTab: JobTab\n  selectedWorkflowFilter: 'all' | 'current'\n  selectedSortMode: JobSortMode\n  displayedJobGroups: JobGroup[]\n  hasFailedJobs: boolean\n}>()\n\nconst emit = defineEmits<{\n  (e: 'showAssets'): void\n  (e: 'clearHistory'): void\n  (e: 'clearQueued'): void\n  (e: 'update:selectedJobTab', value: JobTab): void\n  (e: 'update:selectedWorkflowFilter', value: 'all' | 'current'): void\n  (e: 'update:selectedSortMode', value: JobSortMode): void\n  (e: 'cancelItem', item: JobListItem): void\n  (e: 'deleteItem', item: JobListItem): void\n  (e: 'viewItem', item: JobListItem): void\n}>()\n\nconst currentMenuItem = ref<JobListItem | null>(null)\nconst jobContextMenuRef = ref<InstanceType<typeof ContextMenu> | null>(null)\nconst { trackFeatureUsed } = useSurveyFeatureTracking('queue-progress-overlay')\n\nconst { jobMenuEntries } = useJobMenu(\n  () => currentMenuItem.value,\n  (item) => emit('viewItem', item)\n)\nconst onCancelItemEvent = (item: JobListItem) => {\n  emit('cancelItem', item)\n}\n\nconst onDeleteItemEvent = (item: JobListItem) => {\n  emit('deleteItem', item)\n}\n\nconst onUpdateSelectedJobTab = (value: JobTab) => {\n  trackFeatureUsed()\n  emit('update:selectedJobTab', value)\n}\n\nconst onMenuItem = (item: JobListItem, event: Event) => {\n  const isSameClickTarget =\n    event.type === 'click' && currentMenuItem.value?.id === item.id\n  currentMenuItem.value = item\n  if (isSameClickTarget) jobContextMenuRef.value?.toggle(event)\n  else jobContextMenuRef.value?.show(event)\n}\n</script>\n","<!-- A image with placeholder fallback on error -->\n<template>\n  <span v-if=\"!error\" :class=\"cn('contents', contain && 'relative')\">\n    <img\n      v-if=\"contain\"\n      :src=\"src\"\n      :data-test=\"src\"\n      class=\"absolute inset-0 object-cover\"\n      :style=\"{ 'background-image': `url(${src})` }\"\n      :alt=\"alt\"\n    />\n    <img\n      :src=\"src\"\n      :class=\"\n        cn(\n          'z-1 size-full object-cover object-center',\n          contain && 'absolute object-contain backdrop-blur-[10px]',\n          classProp\n        )\n      \"\n      :alt=\"alt\"\n    />\n  </span>\n  <div\n    v-if=\"error\"\n    class=\"m-8 flex size-full flex-col items-center justify-center\"\n  >\n    <i class=\"pi pi-image mb-2 text-5xl\" />\n    <span>{{ $t('g.imageFailedToLoad') }}</span>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { useImageQuiet } from '@/composables/useImageQuiet'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  src,\n  class: classProp,\n  contain = false,\n  alt = 'Image content'\n} = defineProps<{\n  src: string\n  class?:\n    | string\n    | Record<string, boolean>\n    | (string | Record<string, boolean>)[]\n  contain?: boolean\n  alt?: string\n}>()\n\nconst { error } = useImageQuiet(computed(() => ({ src, alt })))\n</script>\n","<template>\n  <div\n    class=\"m-auto w-[min(90vw,42rem)] rounded-2xl bg-base-background/80 p-8 backdrop-blur-sm\"\n  >\n    <WaveAudioPlayer\n      :src=\"resultItemUrl(result)\"\n      variant=\"expanded\"\n      :height=\"120\"\n      :bar-count=\"80\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport WaveAudioPlayer from '@/components/common/WaveAudioPlayer.vue'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemUrl } from '@/utils/resultItemUrl'\n\nconst { result } = defineProps<{\n  result: AugmentedResultItem\n}>()\n</script>\n","<template>\n  <article\n    class=\"m-auto max-h-[80vh] w-[min(90vw,42rem)] scroll-shadows-secondary-background overflow-y-auto rounded-lg bg-secondary-background p-4 whitespace-pre-wrap\"\n  >\n    <span v-if=\"hasError\" class=\"text-muted-foreground\">\n      {{ $t('g.textFailedToLoad') }}\n    </span>\n    <template v-else>{{ textContent }}</template>\n  </article>\n</template>\n\n<script setup lang=\"ts\">\nimport { useTextFileContent } from '@/composables/useTextFileContent'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemUrl } from '@/utils/resultItemUrl'\n\nconst { result } = defineProps<{\n  result: AugmentedResultItem\n}>()\n\nconst { textContent, hasError } = useTextFileContent(() => ({\n  content: result.content,\n  url: resultItemUrl(result)\n}))\n</script>\n","<template>\n  <video controls class=\"max-h-[90vh] max-w-[90vw]\">\n    <source :src=\"url\" :type=\"htmlVideoType\" />\n    {{ $t('g.videoFailedToLoad') }}\n  </video>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useExtensionStore } from '@/stores/extensionStore'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport {\n  resultItemUrl,\n  resultItemVhsAdvancedPreviewUrl\n} from '@/utils/resultItemUrl'\nimport { resultItemHtmlVideoType } from '@/utils/resultItem'\n\n/* MediaLightbox retains this component via KeepAlive include, which matches on\n   the registered component name. */\ndefineOptions({ name: 'ResultVideo' })\n\nconst props = defineProps<{\n  result: AugmentedResultItem\n}>()\n\nconst settingStore = useSettingStore()\nconst { isExtensionInstalled, isExtensionEnabled } = useExtensionStore()\n\nconst vhsAdvancedPreviews = computed(() => {\n  return (\n    isExtensionInstalled('VideoHelperSuite.Core') &&\n    isExtensionEnabled('VideoHelperSuite.Core') &&\n    settingStore.get('VHS.AdvancedPreviews') &&\n    settingStore.get('VHS.AdvancedPreviews') !== 'Never'\n  )\n})\n\nconst url = computed(() =>\n  vhsAdvancedPreviews.value\n    ? resultItemVhsAdvancedPreviewUrl(props.result)\n    : resultItemUrl(props.result)\n)\nconst htmlVideoType = computed(() =>\n  vhsAdvancedPreviews.value\n    ? 'video/webm'\n    : resultItemHtmlVideoType(props.result)\n)\n</script>\n","<template>\n  <Teleport to=\"body\">\n    <div\n      v-if=\"galleryVisible\"\n      ref=\"dialogRef\"\n      role=\"dialog\"\n      aria-modal=\"true\"\n      :aria-label=\"$t('g.gallery')\"\n      tabindex=\"-1\"\n      class=\"fixed inset-0 z-9999 flex items-center justify-center bg-black/90 outline-none\"\n      data-mask\n      @mousedown=\"onMaskMouseDown\"\n      @mouseup=\"onMaskMouseUp\"\n      @keydown.stop=\"handleKeyDown\"\n    >\n      <!-- Close Button -->\n      <Button\n        variant=\"secondary\"\n        size=\"icon-lg\"\n        class=\"absolute top-4 right-4 z-10 rounded-full\"\n        :aria-label=\"$t('g.close')\"\n        @click=\"close\"\n      >\n        <i class=\"icon-[lucide--x] size-5\" />\n      </Button>\n\n      <!-- Previous Button -->\n      <Button\n        v-if=\"hasMultiple\"\n        variant=\"secondary\"\n        size=\"icon-lg\"\n        class=\"fixed top-1/2 left-4 z-10 -translate-y-1/2 rounded-full\"\n        :aria-label=\"$t('g.previous')\"\n        @click=\"navigateImage(-1)\"\n      >\n        <i class=\"icon-[lucide--chevron-left] size-6\" />\n      </Button>\n\n      <!-- Content -->\n      <div class=\"flex max-h-full max-w-full items-center justify-center\">\n        <template v-if=\"activeItem\">\n          <KeepAlive :max=\"RETAINED_VIDEO_COUNT\" include=\"ResultVideo\">\n            <ComfyImage\n              v-if=\"isImageResult(activeItem)\"\n              :key=\"resultItemUrl(activeItem)\"\n              :src=\"resultItemUrl(activeItem)\"\n              :contain=\"false\"\n              :alt=\"activeItem.filename\"\n              class=\"size-auto max-h-[90vh] max-w-[90vw] object-contain\"\n            />\n            <ResultVideo\n              v-else-if=\"isVideoResult(activeItem)\"\n              :key=\"resultItemUrl(activeItem)\"\n              :result=\"activeItem\"\n            />\n            <ResultAudio\n              v-else-if=\"isAudioResult(activeItem)\"\n              :result=\"activeItem\"\n            />\n            <ResultText\n              v-else-if=\"isTextResult(activeItem)\"\n              :result=\"activeItem\"\n            />\n          </KeepAlive>\n        </template>\n      </div>\n\n      <!-- Next Button -->\n      <Button\n        v-if=\"hasMultiple\"\n        variant=\"secondary\"\n        size=\"icon-lg\"\n        class=\"fixed top-1/2 right-4 z-10 -translate-y-1/2 rounded-full\"\n        :aria-label=\"$t('g.next')\"\n        @click=\"navigateImage(1)\"\n      >\n        <i class=\"icon-[lucide--chevron-right] size-6\" />\n      </Button>\n    </div>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, nextTick, ref, watch } from 'vue'\n\nimport ComfyImage from '@/components/common/ComfyImage.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemUrl } from '@/utils/resultItemUrl'\nimport {\n  isAudioResult,\n  isImageResult,\n  isTextResult,\n  isVideoResult\n} from '@/utils/resultItem'\n\nimport ResultAudio from './ResultAudio.vue'\nimport ResultText from './ResultText.vue'\nimport ResultVideo from './ResultVideo.vue'\n\nconst emit = defineEmits<{\n  (e: 'update:activeIndex', value: number): void\n}>()\n\nconst props = defineProps<{\n  allGalleryItems: AugmentedResultItem[]\n  activeIndex: number\n}>()\n\n/* Keeps the active video plus its neighbors buffered across gallery moves. */\nconst RETAINED_VIDEO_COUNT = 3\n\nconst galleryVisible = ref(false)\nconst dialogRef = ref<HTMLElement>()\nlet previouslyFocusedElement: HTMLElement | null = null\nconst hasMultiple = computed(() => props.allGalleryItems.length > 1)\nconst activeItem = computed(() => props.allGalleryItems[props.activeIndex])\n\nwatch(\n  () => props.activeIndex,\n  (index) => {\n    galleryVisible.value = index !== -1\n    if (index !== -1) {\n      previouslyFocusedElement = document.activeElement as HTMLElement | null\n      void nextTick(() => dialogRef.value?.focus())\n    }\n  },\n  { immediate: true }\n)\n\nfunction close() {\n  galleryVisible.value = false\n  emit('update:activeIndex', -1)\n  previouslyFocusedElement?.focus()\n  previouslyFocusedElement = null\n}\n\nfunction navigateImage(direction: number) {\n  const newIndex =\n    (props.activeIndex + direction + props.allGalleryItems.length) %\n    props.allGalleryItems.length\n  emit('update:activeIndex', newIndex)\n}\n\nlet maskMouseDownTarget: EventTarget | null = null\n\nfunction onMaskMouseDown(event: MouseEvent) {\n  maskMouseDownTarget = event.target\n}\n\nfunction onMaskMouseUp(event: MouseEvent) {\n  if (\n    maskMouseDownTarget === event.target &&\n    (event.target as HTMLElement)?.hasAttribute('data-mask')\n  ) {\n    close()\n  }\n}\n\nfunction handleKeyDown(event: KeyboardEvent) {\n  const actions: Record<string, () => void> = {\n    ArrowLeft: () => navigateImage(-1),\n    ArrowRight: () => navigateImage(1),\n    Escape: () => close()\n  }\n\n  const action = actions[event.key]\n  if (action) {\n    event.preventDefault()\n    action()\n  }\n}\n</script>\n","<template>\n  <section\n    class=\"w-[360px] rounded-2xl border border-interface-stroke bg-interface-panel-surface font-inter text-text-primary shadow-interface\"\n  >\n    <header\n      class=\"flex items-center justify-between border-b border-interface-stroke p-4\"\n    >\n      <p class=\"m-0 text-[14px] leading-none font-normal\">\n        {{ t('sideToolbar.queueProgressOverlay.clearHistoryDialogTitle') }}\n      </p>\n      <Button\n        size=\"icon\"\n        variant=\"muted-textonly\"\n        :aria-label=\"t('g.close')\"\n        @click=\"onCancel\"\n      >\n        <i class=\"icon-[lucide--x] block size-4 leading-none\" />\n      </Button>\n    </header>\n\n    <div class=\"flex flex-col gap-4 p-4 text-[14px] text-text-secondary\">\n      <p class=\"m-0\">\n        {{\n          t('sideToolbar.queueProgressOverlay.clearHistoryDialogDescription')\n        }}\n      </p>\n      <p class=\"m-0\">\n        {{ t('sideToolbar.queueProgressOverlay.clearHistoryDialogAssetsNote') }}\n      </p>\n    </div>\n\n    <footer class=\"flex items-center justify-end p-4\">\n      <div class=\"flex items-center gap-4 leading-none\">\n        <Button variant=\"muted-textonly\" size=\"lg\" @click=\"onCancel\">\n          {{ t('g.cancel') }}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          size=\"lg\"\n          :disabled=\"isClearing\"\n          @click=\"onConfirm\"\n          >{{ t('g.clear') }}</Button\n        >\n      </div>\n    </footer>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { useQueueStore } from '@/stores/queueStore'\n\nconst dialogStore = useDialogStore()\nconst queueStore = useQueueStore()\nconst { t } = useI18n()\nconst { wrapWithErrorHandlingAsync } = useErrorHandling()\n\nconst isClearing = ref(false)\n\nconst clearHistory = wrapWithErrorHandlingAsync(\n  async () => {\n    await queueStore.clear(['history'])\n    dialogStore.closeDialog()\n  },\n  undefined,\n  () => {\n    isClearing.value = false\n  }\n)\n\nconst onConfirm = async () => {\n  if (isClearing.value) return\n  isClearing.value = true\n  await clearHistory()\n}\n\nconst onCancel = () => {\n  dialogStore.closeDialog()\n}\n</script>\n","import QueueClearHistoryDialog from '@/components/queue/dialogs/QueueClearHistoryDialog.vue'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nexport const useQueueClearHistoryDialog = () => {\n  const dialogStore = useDialogStore()\n\n  const showQueueClearHistoryDialog = () => {\n    dialogStore.showDialog({\n      key: 'queue-clear-history',\n      component: QueueClearHistoryDialog,\n      dialogComponentProps: {\n        headless: true,\n        closable: false,\n        dismissOnPointerDownOutside: true\n      }\n    })\n  }\n\n  return {\n    showQueueClearHistoryDialog\n  }\n}\n","import { defineAsyncComponent } from 'vue'\n\nimport { LOAD3D_VIEWER_DIALOG_PROPS } from '@/components/load3d/load3dViewerDialog'\nimport { t } from '@/i18n'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport {\n  getImageFilenameFromUrl,\n  toFullResolutionUrl\n} from '@/utils/hdrFormatUtil'\n\nconst HdrViewerContent = defineAsyncComponent(\n  () => import('@/components/hdr/HdrViewerContent.vue')\n)\n\nexport function openHdrViewer(url: string) {\n  const fullResUrl = toFullResolutionUrl(url)\n  useDialogStore().showDialog({\n    key: 'hdr-viewer',\n    title: getImageFilenameFromUrl(fullResUrl) ?? t('hdrViewer.title'),\n    component: HdrViewerContent,\n    props: { imageUrl: fullResUrl },\n    dialogComponentProps: LOAD3D_VIEWER_DIALOG_PROPS\n  })\n}\n","import { ref, shallowRef } from 'vue'\n\nimport type { JobListItem } from '@/composables/queue/useJobList'\nimport { openHdrViewer } from '@/services/hdrViewerService'\nimport { findActiveIndex, getOutputsForTask } from '@/services/jobOutputCache'\nimport type { TaskItemImpl } from '@/stores/queueStore'\nimport { isHdrImageFilename } from '@/utils/hdrFormatUtil'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemUrl } from '@/utils/resultItemUrl'\n\n/**\n * Manages result gallery state and activation for queue items.\n */\nexport function useResultGallery(getFilteredTasks: () => TaskItemImpl[]) {\n  const galleryActiveIndex = ref(-1)\n  const galleryItems = shallowRef<AugmentedResultItem[]>([])\n\n  async function onViewItem(item: JobListItem) {\n    const tasks = getFilteredTasks()\n    if (!tasks.length) return\n\n    const targetTask = item.taskRef\n    const targetOutputs = targetTask\n      ? await getOutputsForTask(targetTask)\n      : null\n\n    // Request was superseded by a newer one\n    if (targetOutputs === null && targetTask) return\n\n    const previewOutput = targetTask?.previewOutput\n    if (previewOutput && isHdrImageFilename(previewOutput.filename)) {\n      openHdrViewer(resultItemUrl(previewOutput))\n      return\n    }\n\n    const items = (\n      targetOutputs?.length\n        ? targetOutputs\n        : tasks.map((t) => t.previewOutput).filter((o) => !!o)\n    ).filter((o) => !isHdrImageFilename(o.filename))\n    if (!items.length) return\n\n    galleryItems.value = items\n    galleryActiveIndex.value = findActiveIndex(\n      items,\n      previewOutput ? resultItemUrl(previewOutput) : undefined\n    )\n  }\n\n  return {\n    galleryActiveIndex,\n    galleryItems,\n    onViewItem\n  }\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport type { AssetId } from '@/platform/assets/schemas/assetSchema'\n\nexport const useAssetSelectionStore = defineStore('assetSelection', () => {\n  // State\n  const selectedAssetIds = ref<Set<AssetId>>(new Set())\n  const lastSelectedIndex = ref<number>(-1)\n  const lastSelectedAssetId = ref<AssetId | null>(null)\n\n  // Getters\n  const selectedCount = computed(() => selectedAssetIds.value.size)\n  const hasSelection = computed(() => selectedAssetIds.value.size > 0)\n  const selectedIdsArray = computed(() => Array.from(selectedAssetIds.value))\n\n  // Actions\n  function addToSelection(assetId: AssetId) {\n    selectedAssetIds.value.add(assetId)\n  }\n\n  function removeFromSelection(assetId: AssetId) {\n    selectedAssetIds.value.delete(assetId)\n  }\n\n  function setSelection(assetIds: AssetId[]) {\n    selectedAssetIds.value = new Set(assetIds)\n  }\n\n  function clearSelection() {\n    selectedAssetIds.value.clear()\n    lastSelectedIndex.value = -1\n    lastSelectedAssetId.value = null\n  }\n\n  function toggleSelection(assetId: AssetId) {\n    if (isSelected(assetId)) {\n      removeFromSelection(assetId)\n    } else {\n      addToSelection(assetId)\n    }\n  }\n\n  function isSelected(assetId: AssetId): boolean {\n    return selectedAssetIds.value.has(assetId)\n  }\n\n  function setLastSelectedIndex(index: number) {\n    lastSelectedIndex.value = index\n  }\n\n  function setLastSelectedAssetId(assetId: AssetId | null) {\n    lastSelectedAssetId.value = assetId\n  }\n\n  return {\n    // State\n    selectedAssetIds: computed(() => selectedAssetIds.value),\n    lastSelectedIndex: computed(() => lastSelectedIndex.value),\n    lastSelectedAssetId: computed(() => lastSelectedAssetId.value),\n\n    // Getters\n    selectedCount,\n    hasSelection,\n    selectedIdsArray,\n\n    // Actions\n    addToSelection,\n    removeFromSelection,\n    setSelection,\n    clearSelection,\n    toggleSelection,\n    isSelected,\n    setLastSelectedIndex,\n    setLastSelectedAssetId\n  }\n})\n","<template>\n  <div\n    v-show=\"isVisible\"\n    :class=\"['flex', 'justify-end', 'w-full', 'pointer-events-none']\"\n  >\n    <div\n      data-testid=\"queue-progress-overlay\"\n      class=\"pointer-events-auto flex max-h-[60vh] w-[350px] min-w-[310px] flex-col overflow-hidden rounded-lg border font-inter transition-colors duration-200 ease-in-out\"\n      :class=\"containerClass\"\n      @mouseenter=\"isHovered = true\"\n      @mouseleave=\"isHovered = false\"\n    >\n      <!-- Expanded state -->\n      <QueueOverlayExpanded\n        v-if=\"isExpanded\"\n        v-model:selected-job-tab=\"selectedJobTab\"\n        v-model:selected-workflow-filter=\"selectedWorkflowFilter\"\n        v-model:selected-sort-mode=\"selectedSortMode\"\n        class=\"min-h-0 flex-1\"\n        :header-title=\"headerTitle\"\n        :queued-count=\"queuedCount\"\n        :displayed-job-groups=\"displayedJobGroups\"\n        :has-failed-jobs=\"hasFailedJobs\"\n        @show-assets=\"toggleAssetsSidebar\"\n        @clear-history=\"onClearHistoryFromMenu\"\n        @clear-queued=\"cancelQueuedWorkflows\"\n        @cancel-item=\"onCancelItem\"\n        @delete-item=\"onDeleteItem\"\n        @view-item=\"inspectJobAsset\"\n      />\n\n      <QueueOverlayActive\n        v-else-if=\"hasActiveJob\"\n        :total-progress-style=\"totalProgressStyle\"\n        :current-node-progress-style=\"currentNodeProgressStyle\"\n        :total-percent-formatted=\"totalPercentFormatted\"\n        :current-node-percent-formatted=\"currentNodePercentFormatted\"\n        :current-node-name=\"currentNodeName\"\n        :running-count=\"runningCount\"\n        :queued-count=\"queuedCount\"\n        :bottom-row-class=\"bottomRowClass\"\n        @interrupt-all=\"interruptAll\"\n        @clear-queued=\"cancelQueuedWorkflows\"\n        @view-all-jobs=\"viewAllJobs\"\n      />\n    </div>\n  </div>\n\n  <MediaLightbox\n    v-model:active-index=\"galleryActiveIndex\"\n    :all-gallery-items=\"galleryItems\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, nextTick, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport QueueOverlayActive from '@/components/queue/QueueOverlayActive.vue'\nimport QueueOverlayExpanded from '@/components/queue/QueueOverlayExpanded.vue'\nimport MediaLightbox from '@/components/sidebar/tabs/queue/MediaLightbox.vue'\nimport { useJobList } from '@/composables/queue/useJobList'\nimport type { JobListItem } from '@/composables/queue/useJobList'\nimport { useQueueClearHistoryDialog } from '@/composables/queue/useQueueClearHistoryDialog'\nimport { useQueueProgress } from '@/composables/queue/useQueueProgress'\nimport { useResultGallery } from '@/composables/queue/useResultGallery'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { useAssetSelectionStore } from '@/platform/assets/composables/useAssetSelectionStore'\nimport { useSurveyFeatureTracking } from '@/platform/surveys/useSurveyFeatureTracking'\nimport { api } from '@/scripts/api'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useQueueStore } from '@/stores/queueStore'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\n\ntype OverlayState = 'hidden' | 'active' | 'expanded'\n\nconst { expanded, menuHovered } = defineProps<{\n  expanded?: boolean\n  menuHovered?: boolean\n}>()\n\nconst emit = defineEmits<{\n  (e: 'update:expanded', value: boolean): void\n}>()\n\nconst { t, n } = useI18n()\nconst queueStore = useQueueStore()\nconst commandStore = useCommandStore()\nconst executionStore = useExecutionStore()\nconst assetsStore = useAssetsStore()\nconst sidebarTabStore = useSidebarTabStore()\nconst assetSelectionStore = useAssetSelectionStore()\nconst { showQueueClearHistoryDialog } = useQueueClearHistoryDialog()\nconst { wrapWithErrorHandlingAsync } = useErrorHandling()\nconst { trackFeatureUsed } = useSurveyFeatureTracking('queue-progress-overlay')\n\nconst {\n  totalPercentFormatted,\n  currentNodePercentFormatted,\n  totalProgressStyle,\n  currentNodeProgressStyle\n} = useQueueProgress()\nconst isHovered = ref(false)\nconst isOverlayHovered = computed(() => isHovered.value || menuHovered)\nconst internalExpanded = ref(false)\nconst isExpanded = computed({\n  get: () => (expanded === undefined ? internalExpanded.value : expanded),\n  set: (value) => {\n    if (expanded === undefined) {\n      internalExpanded.value = value\n    }\n    emit('update:expanded', value)\n  }\n})\n\nconst runningCount = computed(() => queueStore.runningTasks.length)\nconst queuedCount = computed(() => queueStore.pendingTasks.length)\nconst isExecuting = computed(() => !executionStore.isIdle)\nconst hasActiveJob = computed(() => runningCount.value > 0 || isExecuting.value)\n\nconst overlayState = computed<OverlayState>(() => {\n  if (isExpanded.value) return 'expanded'\n  if (hasActiveJob.value) return 'active'\n  return 'hidden'\n})\n\nconst showBackground = computed(\n  () =>\n    overlayState.value === 'expanded' ||\n    (overlayState.value === 'active' && isOverlayHovered.value)\n)\n\nconst isVisible = computed(() => overlayState.value !== 'hidden')\n\nconst containerClass = computed(() =>\n  showBackground.value\n    ? 'border-interface-stroke bg-interface-panel-surface shadow-interface'\n    : 'border-transparent bg-transparent shadow-none'\n)\n\nconst bottomRowClass = computed(\n  () =>\n    `flex items-center justify-end gap-4 transition-opacity duration-200 ease-in-out ${\n      overlayState.value === 'active' && isOverlayHovered.value\n        ? 'opacity-100 pointer-events-auto'\n        : 'opacity-0 pointer-events-none'\n    }`\n)\nconst runningJobsLabel = computed(() =>\n  t('sideToolbar.queueProgressOverlay.runningJobsLabel', {\n    count: n(runningCount.value)\n  })\n)\nconst queuedJobsLabel = computed(() =>\n  t('sideToolbar.queueProgressOverlay.queuedJobsLabel', {\n    count: n(queuedCount.value)\n  })\n)\nconst headerTitle = computed(() => {\n  if (!hasActiveJob.value) {\n    return t('sideToolbar.queueProgressOverlay.jobQueue')\n  }\n\n  if (queuedCount.value === 0) {\n    return runningJobsLabel.value\n  }\n\n  if (runningCount.value === 0) {\n    return queuedJobsLabel.value\n  }\n\n  return t('sideToolbar.queueProgressOverlay.runningQueuedSummary', {\n    running: runningJobsLabel.value,\n    queued: queuedJobsLabel.value\n  })\n})\n\nconst {\n  selectedJobTab,\n  selectedWorkflowFilter,\n  selectedSortMode,\n  hasFailedJobs,\n  filteredTasks,\n  groupedJobItems,\n  currentNodeName\n} = useJobList()\n\nconst displayedJobGroups = computed(() => groupedJobItems.value)\n\nconst onCancelItem = wrapWithErrorHandlingAsync(async (item: JobListItem) => {\n  trackFeatureUsed()\n  const jobId = item.taskRef?.jobId\n  if (!jobId) return\n\n  if (\n    item.state === 'running' ||\n    item.state === 'initialization' ||\n    item.state === 'pending'\n  ) {\n    // State-agnostic cancel (see api.ts cancelJob for the runtime-parity caveat).\n    await api.cancelJob(jobId)\n    executionStore.clearInitializationByJobId(jobId)\n    await queueStore.update()\n  }\n})\n\nconst onDeleteItem = wrapWithErrorHandlingAsync(async (item: JobListItem) => {\n  trackFeatureUsed()\n  if (!item.taskRef) return\n  await queueStore.delete(item.taskRef)\n})\n\nconst {\n  galleryActiveIndex,\n  galleryItems,\n  onViewItem: openResultGallery\n} = useResultGallery(() => filteredTasks.value)\n\nconst setExpanded = (expanded: boolean) => {\n  isExpanded.value = expanded\n}\n\nconst viewAllJobs = () => {\n  trackFeatureUsed()\n  setExpanded(true)\n}\n\nconst toggleAssetsSidebar = () => {\n  trackFeatureUsed()\n  sidebarTabStore.toggleSidebarTab('assets')\n}\n\nconst openAssetsSidebar = () => {\n  sidebarTabStore.activeSidebarTabId = 'assets'\n}\n\nlet assetFocusRequest = 0\n\nconst focusAssetInSidebar = async (item: JobListItem, request: number) => {\n  const task = item.taskRef\n  const jobId = task?.jobId\n  const preview = task?.previewOutput\n  if (!jobId || !preview || request !== assetFocusRequest) return\n\n  const assetId = String(jobId)\n  openAssetsSidebar()\n  await nextTick()\n  const found = await assetsStore.loadOutputAsset(assetId)\n  if (!found || request !== assetFocusRequest) return\n\n  assetSelectionStore.setSelection([assetId])\n  assetSelectionStore.setLastSelectedAssetId(assetId)\n}\n\nconst inspectJobAsset = wrapWithErrorHandlingAsync(\n  async (item: JobListItem) => {\n    const request = ++assetFocusRequest\n    trackFeatureUsed()\n    await openResultGallery(item)\n    await focusAssetInSidebar(item, request)\n  }\n)\n\nconst cancelQueuedWorkflows = wrapWithErrorHandlingAsync(async () => {\n  trackFeatureUsed()\n  // Capture pending jobIds before clearing\n  const pendingJobIds = queueStore.pendingTasks\n    .map((task) => task.jobId)\n    .filter((id): id is string => typeof id === 'string' && id.length > 0)\n\n  await commandStore.execute('Comfy.ClearPendingTasks')\n\n  // Clear initialization state for removed jobs\n  executionStore.clearInitializationByJobIds(pendingJobIds)\n})\n\nconst interruptAll = wrapWithErrorHandlingAsync(async () => {\n  trackFeatureUsed()\n  const tasks = queueStore.runningTasks\n  const jobIds = tasks\n    .map((task) => task.jobId)\n    .filter((id): id is string => typeof id === 'string' && id.length > 0)\n\n  if (!jobIds.length) return\n\n  // State-agnostic batch cancel (see api.ts cancelJobs for the runtime-parity caveat).\n  await api.cancelJobs(jobIds)\n  executionStore.clearInitializationByJobIds(jobIds)\n  await queueStore.update()\n})\n\nconst onClearHistoryFromMenu = () => {\n  trackFeatureUsed()\n  showQueueClearHistoryDialog()\n}\n</script>\n","export function createCancelToken() {\n  let cancelled = false\n\n  return {\n    cancel: () => {\n      cancelled = true\n    },\n    isCancelled: () => cancelled\n  }\n}\n","import type { ErrorCardData, ErrorGroup } from './types'\n\nexport function shouldRenderExecutionItemList(cards: ErrorCardData[]): boolean {\n  return (\n    cards.length > 0 &&\n    cards.every(\n      (card) =>\n        card.nodeId &&\n        card.errors.length > 0 &&\n        card.errors.every(\n          (error) => !error.isRuntimeError && Boolean(error.displayItemLabel)\n        )\n    )\n  )\n}\n\nexport function isExecutionItemListGroup(group: ErrorGroup): boolean {\n  return (\n    group.type === 'execution' && shouldRenderExecutionItemList(group.cards)\n  )\n}\n","import { cn } from '@comfyorg/tailwind-utils'\n\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\n\n// The negative margin and matching padding cancel out, so the background\n// bleeds 6px past the content without shifting the text.\nconst EMPHASIS_CLASS = 'rounded-sm bg-blue-selection -mx-1.5 px-1.5'\n\n// Present even when unhighlighted so the emphasis animates both ways.\nconst TRANSITION_CLASS =\n  'transition-[background-color,margin,padding,border-radius] duration-200'\n\n/** Classes emphasizing rows/cards that belong to the canvas selection. */\nexport function selectionEmphasisClass(highlighted: boolean | undefined) {\n  return cn(TRANSITION_CLASS, highlighted && EMPHASIS_CLASS)\n}\n\n/** True when any node type resolves to a node in the given id set. */\nexport function someNodeTypeInSelection(\n  nodeTypes: MissingNodeType[],\n  nodeIds: Set<string> | undefined\n): boolean {\n  if (!nodeIds?.size) return false\n  return nodeTypes.some(\n    (nodeType) =>\n      typeof nodeType !== 'string' &&\n      nodeType.nodeId != null &&\n      nodeIds.has(String(nodeType.nodeId))\n  )\n}\n","import { storeToRefs } from 'pinia'\n\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\n\nexport function useErrorClassification() {\n  return storeToRefs(useExecutionErrorStore()).errorClassification\n}\n","import { computed, reactive, ref, toValue, watch } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\nimport Fuse from 'fuse.js'\nimport type { IFuseOptions } from 'fuse.js'\n\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useMissingNodesErrorStore } from '@/platform/nodeReplacement/missingNodesErrorStore'\nimport { useComfyRegistryStore } from '@/stores/comfyRegistryStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { app } from '@/scripts/app'\nimport { isCloud } from '@/platform/distribution/types'\nimport { SubgraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\n\nimport {\n  getNodeByExecutionId,\n  getExecutionIdByNode\n} from '@/utils/graphTraversalUtil'\nimport { createCancelToken } from '@/utils/createCancelToken'\nimport { resolveNodeDisplayName } from '@/utils/nodeTitleUtil'\nimport { isLGraphNode } from '@/utils/litegraphUtil'\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\nimport type { ErrorCardData, ErrorGroup, ErrorItem } from './types'\nimport { shouldRenderExecutionItemList } from './executionItemList'\nimport { someNodeTypeInSelection } from './selectionEmphasis'\nimport type { NodeExecutionId } from '@/types/nodeIdentification'\nimport type { MissingModelGroup } from '@/platform/missingModel/types'\nimport type { ResolvedCatalogErrorMessage } from '@/platform/errorCatalog/types'\nimport type { MissingMediaGroup } from '@/platform/missingMedia/types'\nimport {\n  countMissingModels,\n  groupMissingModelCandidates\n} from '@/platform/missingModel/missingModelGrouping'\nimport { groupCandidatesByMediaType } from '@/platform/missingMedia/missingMediaScan'\nimport { countMissingMediaReferences } from '@/platform/missingMedia/missingMediaGrouping'\nimport {\n  resolveMissingErrorMessage,\n  resolveRunErrorMessage\n} from '@/platform/errorCatalog/errorMessageResolver'\nimport {\n  compareExecutionId,\n  tryNormalizeNodeExecutionId\n} from '@/types/nodeIdentification'\n\nimport type { MissingResourceAbsorption } from '@/utils/missingResourceAbsorption'\nimport { useErrorClassification } from './useErrorClassification'\n\nconst PROMPT_CARD_ID = '__prompt__'\n\nconst AGENT_PROMPT_ERROR_TYPE_LIST = [\n  'agent_api_failed',\n  'op_rejected',\n  'prefix_abort',\n  'guard_trip',\n  'apply_failed'\n] as const\n\ntype AgentPromptErrorType = (typeof AGENT_PROMPT_ERROR_TYPE_LIST)[number]\n\nconst AGENT_PROMPT_ERROR_TYPES: ReadonlySet<string> = new Set(\n  AGENT_PROMPT_ERROR_TYPE_LIST\n)\n\nfunction isAgentPromptErrorType(\n  errorType: string\n): errorType is AgentPromptErrorType {\n  return AGENT_PROMPT_ERROR_TYPES.has(errorType)\n}\n\n/** Sentinel: distinguishes \"fetch in-flight\" from \"fetch done, pack not found (null)\". */\nconst RESOLVING = '__RESOLVING__'\n\nexport interface MissingPackGroup {\n  packId: string | null\n  nodeTypes: MissingNodeType[]\n  isResolving: boolean\n}\n\nexport interface SwapNodeGroup {\n  type: string\n  newNodeId: string | undefined\n  nodeTypes: MissingNodeType[]\n}\n\ninterface GroupEntry {\n  type: 'execution'\n  displayTitle: string\n  displayMessage?: string\n  priority: number\n  cards: Map<string, ErrorCardData>\n}\n\ninterface ErrorSearchItem {\n  groupIndex: number\n  cardIndex: number\n  searchableNodeId: string\n  searchableNodeTitle: string\n  searchableRawMessage: string\n  searchableRawDetails: string\n  searchableMessage: string\n  searchableDetails: string\n}\n\ntype CataloguedErrorItem = ErrorItem & ResolvedCatalogErrorMessage\n\n/** Resolve display info for a node by its execution ID. */\nfunction resolveNodeInfo(nodeId: NodeExecutionId) {\n  const rootGraph = app.rootGraphOrUndefined\n  const graphNode = rootGraph ? getNodeByExecutionId(rootGraph, nodeId) : null\n\n  return {\n    title: resolveNodeDisplayName(graphNode, {\n      emptyLabel: '',\n      untitledLabel: ''\n    }),\n    graphNodeId: graphNode ? String(graphNode.id) : undefined\n  }\n}\n\nfunction getOrCreateGroup(\n  groupsMap: Map<string, GroupEntry>,\n  groupKey: string,\n  displayTitle = groupKey,\n  priority = 1,\n  displayMessage?: string\n): Map<string, ErrorCardData> {\n  let entry = groupsMap.get(groupKey)\n  if (!entry) {\n    entry = {\n      type: 'execution',\n      displayTitle,\n      displayMessage,\n      priority,\n      cards: new Map()\n    }\n    groupsMap.set(groupKey, entry)\n  } else if (!entry.displayMessage && displayMessage) {\n    entry.displayMessage = displayMessage\n  }\n  return entry.cards\n}\n\nfunction createErrorCard(\n  nodeId: NodeExecutionId,\n  classType: string,\n  idPrefix: string\n): ErrorCardData {\n  const nodeInfo = resolveNodeInfo(nodeId)\n  return {\n    id: `${idPrefix}-${nodeId}`,\n    title: classType,\n    nodeId,\n    nodeTitle: nodeInfo.title,\n    graphNodeId: nodeInfo.graphNodeId,\n    errors: []\n  }\n}\n\nfunction compareNodeId(a: ErrorCardData, b: ErrorCardData): number {\n  return compareExecutionId(a.nodeId, b.nodeId)\n}\n\nfunction countExecutionCards(cards: ErrorCardData[]): number {\n  if (shouldRenderExecutionItemList(cards)) {\n    return cards.reduce((count, card) => count + card.errors.length, 0)\n  }\n\n  return cards.length\n}\n\nfunction toSortedGroups(groupsMap: Map<string, GroupEntry>): ErrorGroup[] {\n  return Array.from(groupsMap.entries())\n    .map(([rawGroupKey, groupData]) => {\n      const cards = Array.from(groupData.cards.values()).sort(compareNodeId)\n      return {\n        type: 'execution' as const,\n        severity: 'error' as const,\n        groupKey: `execution:${rawGroupKey}`,\n        displayTitle: groupData.displayTitle,\n        displayMessage: groupData.displayMessage,\n        count: countExecutionCards(cards),\n        cards,\n        priority: groupData.priority,\n        blockedLastRun: false\n      }\n    })\n    .sort((a, b) => {\n      if (a.priority !== b.priority) return a.priority - b.priority\n      return a.displayTitle.localeCompare(b.displayTitle)\n    })\n}\n\nfunction searchErrorGroups(groups: ErrorGroup[], query: string) {\n  if (!query) return groups\n\n  const searchableList: ErrorSearchItem[] = []\n  for (let gi = 0; gi < groups.length; gi++) {\n    const group = groups[gi]\n    if (group.type !== 'execution') continue\n    for (let ci = 0; ci < group.cards.length; ci++) {\n      const card = group.cards[ci]\n      searchableList.push({\n        groupIndex: gi,\n        cardIndex: ci,\n        searchableNodeId: card.nodeId ?? '',\n        searchableNodeTitle: card.nodeTitle ?? '',\n        searchableRawMessage: card.errors.map((e) => e.message).join(' '),\n        searchableRawDetails: card.errors\n          .map((e) => e.details)\n          .filter(Boolean)\n          .join(' '),\n        searchableMessage: card.errors\n          .map((e) =>\n            [e.displayTitle, e.displayMessage, e.message]\n              .filter(Boolean)\n              .join(' ')\n          )\n          .join(' '),\n        searchableDetails: card.errors\n          .map((e) => [e.displayDetails, e.details].filter(Boolean).join(' '))\n          .join(' ')\n      })\n    }\n  }\n\n  const fuseOptions: IFuseOptions<ErrorSearchItem> = {\n    keys: [\n      { name: 'searchableRawMessage', weight: 0.3 },\n      { name: 'searchableNodeId', weight: 0.2 },\n      { name: 'searchableNodeTitle', weight: 0.2 },\n      { name: 'searchableMessage', weight: 0.2 },\n      { name: 'searchableRawDetails', weight: 0.1 },\n      { name: 'searchableDetails', weight: 0.1 }\n    ],\n    threshold: 0.3\n  }\n\n  const fuse = new Fuse(searchableList, fuseOptions)\n  const results = fuse.search(query)\n\n  const matchedCardKeys = new Set(\n    results.map((r) => `${r.item.groupIndex}:${r.item.cardIndex}`)\n  )\n\n  return groups\n    .map((group, gi) => {\n      if (group.type !== 'execution') return group\n      const cards = group.cards.filter((_: ErrorCardData, ci: number) =>\n        matchedCardKeys.has(`${gi}:${ci}`)\n      )\n      return {\n        ...group,\n        cards,\n        count: countExecutionCards(cards)\n      }\n    })\n    .filter((group) => group.type !== 'execution' || group.cards.length > 0)\n}\n\nexport function useErrorGroups(searchQuery: MaybeRefOrGetter<string>) {\n  const executionErrorStore = useExecutionErrorStore()\n  const missingNodesStore = useMissingNodesErrorStore()\n  const missingModelStore = useMissingModelStore()\n  const missingMediaStore = useMissingMediaStore()\n  const canvasStore = useCanvasStore()\n  const { inferPackFromNodeName } = useComfyRegistryStore()\n  const collapseState = reactive<Record<string, boolean>>({})\n\n  const errorClassification = useErrorClassification()\n\n  const selectedNodeInfo = computed(() => {\n    const rootGraph = app.rootGraphOrUndefined\n    const items = canvasStore.selectedItems\n    const nodeIds = new Set<string>()\n    const containerExecutionIds = new Set<NodeExecutionId>()\n\n    for (const item of items) {\n      if (!isLGraphNode(item)) continue\n      nodeIds.add(String(item.id))\n      if (rootGraph && item instanceof SubgraphNode) {\n        const execId = getExecutionIdByNode(rootGraph, item)\n        if (execId) containerExecutionIds.add(execId)\n      }\n    }\n\n    return {\n      nodeIds: nodeIds.size > 0 ? nodeIds : null,\n      containerExecutionIds\n    }\n  })\n\n  const hasSelection = computed(() => selectedNodeInfo.value.nodeIds !== null)\n\n  const selectedNodeCount = computed(\n    () => selectedNodeInfo.value.nodeIds?.size ?? 0\n  )\n\n  const selectedNodeTitle = computed(() => {\n    if (selectedNodeCount.value !== 1) return null\n    const node = canvasStore.selectedItems.find(isLGraphNode)\n    if (!node) return null\n    return (\n      resolveNodeDisplayName(node, {\n        emptyLabel: '',\n        untitledLabel: ''\n      }) || null\n    )\n  })\n\n  const errorNodeCache = computed(() => {\n    const map = new Map<string, LGraphNode>()\n    const rootGraph = app.rootGraphOrUndefined\n    if (!rootGraph) return map\n    for (const execId of executionErrorStore.allErrorExecutionIds) {\n      const node = getNodeByExecutionId(rootGraph, execId)\n      if (node) map.set(execId, node)\n    }\n    return map\n  })\n\n  const missingNodeCache = computed(() => {\n    const map = new Map<string, LGraphNode>()\n    const rootGraph = app.rootGraphOrUndefined\n    if (!rootGraph) return map\n    const nodeTypes =\n      missingNodesStore.visibleMissingNodesError?.nodeTypes ?? []\n    for (const nodeType of nodeTypes) {\n      if (typeof nodeType === 'string') continue\n      if (nodeType.nodeId == null) continue\n      const nodeId = String(nodeType.nodeId)\n      const node = getNodeByExecutionId(rootGraph, nodeId)\n      if (node) map.set(nodeId, node)\n    }\n    return map\n  })\n\n  function isErrorInSelection(executionNodeId: NodeExecutionId): boolean {\n    const nodeIds = selectedNodeInfo.value.nodeIds\n    if (!nodeIds) return true\n\n    const graphNode = errorNodeCache.value.get(executionNodeId)\n    if (graphNode && nodeIds.has(String(graphNode.id))) return true\n\n    for (const containerExecId of selectedNodeInfo.value\n      .containerExecutionIds) {\n      if (executionNodeId.startsWith(`${containerExecId}:`)) return true\n    }\n\n    return false\n  }\n\n  function addNodeErrorToGroup(\n    groupsMap: Map<string, GroupEntry>,\n    nodeId: NodeExecutionId,\n    classType: string,\n    idPrefix: string,\n    error: CataloguedErrorItem,\n    filterBySelection = false\n  ) {\n    if (filterBySelection && !isErrorInSelection(nodeId)) return\n    const cards = getOrCreateGroup(\n      groupsMap,\n      error.catalogId,\n      error.displayTitle ?? classType,\n      1,\n      error.displayMessage\n    )\n    if (!cards.has(nodeId)) {\n      cards.set(nodeId, createErrorCard(nodeId, classType, idPrefix))\n    }\n    const card = cards.get(nodeId)\n    if (!card) return\n    card.errors.push(error)\n  }\n\n  function addUnlocatedErrorToGroup(\n    groupsMap: Map<string, GroupEntry>,\n    cardId: string,\n    classType: string,\n    error: CataloguedErrorItem,\n    rawNodeId?: string\n  ) {\n    const cards = getOrCreateGroup(\n      groupsMap,\n      error.catalogId,\n      error.displayTitle ?? classType,\n      1,\n      error.displayMessage\n    )\n    if (!cards.has(cardId)) {\n      cards.set(cardId, {\n        id: cardId,\n        rawNodeId,\n        title: classType,\n        errors: []\n      })\n    }\n    cards.get(cardId)?.errors.push(error)\n  }\n\n  function processPromptError(\n    groupsMap: Map<string, GroupEntry>,\n    filterBySelection = false\n  ): boolean {\n    const classifiedPromptError = errorClassification.value.promptError\n    if (\n      (filterBySelection && selectedNodeInfo.value.nodeIds) ||\n      !classifiedPromptError\n    )\n      return false\n\n    const { error, isAbsorbed } = classifiedPromptError\n    if (isAbsorbed) return true\n\n    const resolvedDisplay = resolveRunErrorMessage({\n      kind: 'prompt',\n      error,\n      isCloud\n    })\n    const groupDisplayTitle = resolvedDisplay.displayTitle ?? error.message\n    const cards = getOrCreateGroup(\n      groupsMap,\n      `prompt:${error.type}`,\n      groupDisplayTitle,\n      0,\n      resolvedDisplay.displayMessage\n    )\n\n    // Prompt errors are not tied to a node, so they bypass addNodeErrorToGroup.\n    cards.set(PROMPT_CARD_ID, {\n      id: PROMPT_CARD_ID,\n      title: groupDisplayTitle,\n      errors: [\n        {\n          message: error.message,\n          ...(isAgentPromptErrorType(error.type)\n            ? { details: error.details }\n            : {}),\n          ...resolvedDisplay\n        }\n      ]\n    })\n    return false\n  }\n\n  function processNodeErrors(\n    groupsMap: Map<string, GroupEntry>,\n    filterBySelection = false\n  ): Set<MissingResourceAbsorption> {\n    const blockedMissingGroups = new Set<MissingResourceAbsorption>()\n\n    for (const classifiedNodeError of errorClassification.value.nodeErrors) {\n      const { rawNodeId, nodeId, nodeError } = classifiedNodeError\n      if (filterBySelection && !nodeId) continue\n      const nodeDisplayName = nodeId\n        ? resolveNodeInfo(nodeId).title || nodeError.class_type\n        : nodeError.class_type\n\n      for (const { error, absorption } of classifiedNodeError.errors) {\n        if (absorption) {\n          blockedMissingGroups.add(absorption)\n          continue\n        }\n\n        const cataloguedError = {\n          message: error.message,\n          details: error.details,\n          ...resolveRunErrorMessage({\n            kind: 'node_validation',\n            error,\n            nodeDisplayName\n          })\n        }\n        if (!nodeId) {\n          addUnlocatedErrorToGroup(\n            groupsMap,\n            `node-${rawNodeId}`,\n            nodeError.class_type,\n            cataloguedError,\n            rawNodeId\n          )\n          continue\n        }\n        addNodeErrorToGroup(\n          groupsMap,\n          nodeId,\n          nodeError.class_type,\n          'node',\n          cataloguedError,\n          filterBySelection\n        )\n      }\n    }\n\n    return blockedMissingGroups\n  }\n\n  function processExecutionError(\n    groupsMap: Map<string, GroupEntry>,\n    filterBySelection = false\n  ) {\n    const classifiedExecutionError = errorClassification.value.executionError\n    if (!classifiedExecutionError) return\n\n    const { error, nodeId, rawNodeId } = classifiedExecutionError\n    if (filterBySelection && !nodeId) return\n    const cataloguedError = {\n      message: `${error.exception_type}: ${error.exception_message}`,\n      details: error.traceback.join('\\n'),\n      isRuntimeError: true,\n      exceptionType: error.exception_type,\n      ...resolveRunErrorMessage({\n        kind: 'execution',\n        error,\n        nodeDisplayName: nodeId\n          ? resolveNodeInfo(nodeId).title || error.node_type\n          : error.node_type\n      })\n    }\n    if (nodeId) {\n      addNodeErrorToGroup(\n        groupsMap,\n        nodeId,\n        error.node_type,\n        'exec',\n        cataloguedError,\n        filterBySelection\n      )\n    } else {\n      addUnlocatedErrorToGroup(\n        groupsMap,\n        `exec-${error.node_id}`,\n        error.node_type,\n        cataloguedError,\n        rawNodeId\n      )\n    }\n  }\n\n  // Async pack-ID resolution for missing node types that lack a cnrId\n  const asyncResolvedIds = ref<Map<string, string | null>>(new Map())\n\n  const pendingTypes = computed(() =>\n    (missingNodesStore.missingNodesError?.nodeTypes ?? []).filter(\n      (n): n is Exclude<MissingNodeType, string> =>\n        typeof n !== 'string' && !n.cnrId\n    )\n  )\n\n  watch(\n    pendingTypes,\n    async (pending, _, onCleanup) => {\n      const toResolve = pending.filter(\n        (n) => asyncResolvedIds.value.get(n.type) === undefined\n      )\n      if (!toResolve.length) return\n\n      const resolvingTypes = toResolve.map((n) => n.type)\n      const { cancel, isCancelled } = createCancelToken()\n      onCleanup(() => {\n        cancel()\n        const next = new Map(asyncResolvedIds.value)\n        for (const type of resolvingTypes) {\n          if (next.get(type) === RESOLVING) next.delete(type)\n        }\n        asyncResolvedIds.value = next\n      })\n\n      const updated = new Map(asyncResolvedIds.value)\n      for (const type of resolvingTypes) updated.set(type, RESOLVING)\n      asyncResolvedIds.value = updated\n\n      const results = await Promise.allSettled(\n        toResolve.map(async (n) => ({\n          type: n.type,\n          packId: (await inferPackFromNodeName.call(n.type))?.id ?? null\n        }))\n      )\n      if (isCancelled()) return\n\n      const final = new Map(asyncResolvedIds.value)\n      for (const r of results) {\n        if (r.status === 'fulfilled') {\n          final.set(r.value.type, r.value.packId)\n        } else {\n          console.warn('Failed to resolve pack ID:', r.reason)\n        }\n      }\n      // Clear any remaining RESOLVING markers for failed lookups\n      for (const type of resolvingTypes) {\n        if (final.get(type) === RESOLVING) final.set(type, null)\n      }\n      asyncResolvedIds.value = final\n    },\n    { immediate: true }\n  )\n\n  // Evict stale entries when missing nodes are cleared\n  watch(\n    () => missingNodesStore.missingNodesError,\n    (error) => {\n      if (!error && asyncResolvedIds.value.size > 0) {\n        asyncResolvedIds.value = new Map()\n      }\n    }\n  )\n\n  const missingPackGroups = computed<MissingPackGroup[]>(() => {\n    const nodeTypes =\n      missingNodesStore.visibleMissingNodesError?.nodeTypes ?? []\n    const map = new Map<\n      string | null,\n      { nodeTypes: MissingNodeType[]; isResolving: boolean }\n    >()\n    const resolvingKeys = new Set<string | null>()\n\n    for (const nodeType of nodeTypes) {\n      if (typeof nodeType !== 'string' && nodeType.isReplaceable) continue\n\n      let packId: string | null\n\n      if (typeof nodeType === 'string') {\n        packId = null\n      } else if (nodeType.cnrId) {\n        packId = nodeType.cnrId\n      } else {\n        const resolved = asyncResolvedIds.value.get(nodeType.type)\n        if (resolved === undefined || resolved === RESOLVING) {\n          packId = null\n          resolvingKeys.add(null)\n        } else {\n          packId = resolved\n        }\n      }\n\n      const existing = map.get(packId)\n      if (existing) {\n        existing.nodeTypes.push(nodeType)\n      } else {\n        map.set(packId, { nodeTypes: [nodeType], isResolving: false })\n      }\n    }\n\n    for (const key of resolvingKeys) {\n      const group = map.get(key)\n      if (group) group.isResolving = true\n    }\n\n    return Array.from(map.entries())\n      .sort(([packIdA], [packIdB]) => {\n        // null (Unknown Pack) always goes last\n        if (packIdA === null) return 1\n        if (packIdB === null) return -1\n        return packIdA.localeCompare(packIdB)\n      })\n      .map(([packId, { nodeTypes, isResolving }]) => ({\n        packId,\n        nodeTypes: [...nodeTypes].sort((a, b) => {\n          const typeA = typeof a === 'string' ? a : a.type\n          const typeB = typeof b === 'string' ? b : b.type\n          const typeCmp = typeA.localeCompare(typeB)\n          if (typeCmp !== 0) return typeCmp\n          const idA = typeof a === 'string' ? '' : String(a.nodeId ?? '')\n          const idB = typeof b === 'string' ? '' : String(b.nodeId ?? '')\n          return idA.localeCompare(idB, undefined, { numeric: true })\n        }),\n        isResolving\n      }))\n  })\n\n  const swapNodeGroups = computed<SwapNodeGroup[]>(() => {\n    const nodeTypes =\n      missingNodesStore.visibleMissingNodesError?.nodeTypes ?? []\n    const map = new Map<string, SwapNodeGroup>()\n\n    for (const nodeType of nodeTypes) {\n      if (typeof nodeType === 'string' || !nodeType.isReplaceable) continue\n\n      const typeName = nodeType.type\n      const existing = map.get(typeName)\n      if (existing) {\n        existing.nodeTypes.push(nodeType)\n      } else {\n        map.set(typeName, {\n          type: typeName,\n          newNodeId: nodeType.replacement?.new_node_id,\n          nodeTypes: [nodeType]\n        })\n      }\n    }\n\n    return Array.from(map.values()).sort((a, b) => a.type.localeCompare(b.type))\n  })\n\n  /**\n   * Builds ErrorGroups from missingNodesError. Returns [] when none present.\n   * `includeGroup` narrows which swap/pack groups are counted (used to scope\n   * emphasis to the canvas selection); groups reduced to zero are omitted.\n   */\n  function buildMissingNodeGroups(\n    blockedLastRun: boolean,\n    includeGroup: (nodeTypes: MissingNodeType[]) => boolean = () => true\n  ): ErrorGroup[] {\n    const error = missingNodesStore.visibleMissingNodesError\n    if (!error) return []\n\n    const groups: ErrorGroup[] = []\n    const swapCount = swapNodeGroups.value.filter((group) =>\n      includeGroup(group.nodeTypes)\n    ).length\n    const packCount = missingPackGroups.value.filter((group) =>\n      includeGroup(group.nodeTypes)\n    ).length\n\n    if (swapCount > 0) {\n      groups.push({\n        type: 'swap_nodes' as const,\n        severity: 'missing' as const,\n        groupKey: 'swap_nodes',\n        count: swapCount,\n        priority: 0,\n        blockedLastRun,\n        ...resolveMissingErrorMessage({\n          kind: 'swap_nodes',\n          nodeTypes: error.nodeTypes,\n          count: swapCount,\n          isCloud\n        })\n      })\n    }\n\n    if (packCount > 0) {\n      groups.push({\n        type: 'missing_node' as const,\n        severity: 'missing' as const,\n        groupKey: 'missing_node',\n        count: packCount,\n        priority: 1,\n        blockedLastRun,\n        ...resolveMissingErrorMessage({\n          kind: 'missing_node',\n          nodeTypes: error.nodeTypes,\n          count: packCount,\n          isCloud\n        })\n      })\n    }\n\n    return groups.sort((a, b) => a.priority - b.priority)\n  }\n\n  const missingModelGroups = computed<MissingModelGroup[]>(() => {\n    return groupMissingModelCandidates(\n      missingModelStore.visibleMissingModelCandidates,\n      isCloud\n    )\n  })\n\n  function buildMissingModelGroups(blockedLastRun: boolean): ErrorGroup[] {\n    if (!missingModelGroups.value.length) return []\n    const count = countMissingModels(missingModelGroups.value)\n    return [\n      {\n        type: 'missing_model' as const,\n        severity: 'missing' as const,\n        groupKey: 'missing_model',\n        count,\n        priority: 2,\n        blockedLastRun,\n        ...resolveMissingErrorMessage({\n          kind: 'missing_model',\n          groups: missingModelGroups.value,\n          count,\n          isCloud\n        })\n      }\n    ]\n  }\n\n  const missingMediaGroups = computed<MissingMediaGroup[]>(() => {\n    const candidates = missingMediaStore.visibleMissingMediaCandidates\n    if (!candidates?.length) return []\n    return groupCandidatesByMediaType(candidates)\n  })\n\n  function buildMissingMediaGroups(blockedLastRun: boolean): ErrorGroup[] {\n    if (!missingMediaGroups.value.length) return []\n    const totalRows = countMissingMediaReferences(missingMediaGroups.value)\n    return [\n      {\n        type: 'missing_media' as const,\n        severity: 'missing' as const,\n        groupKey: 'missing_media',\n        count: totalRows,\n        priority: 3,\n        blockedLastRun,\n        ...resolveMissingErrorMessage({\n          kind: 'missing_media',\n          groups: missingMediaGroups.value,\n          count: totalRows,\n          isCloud\n        })\n      }\n    ]\n  }\n\n  function isAssetErrorInSelection(executionNodeId: NodeExecutionId): boolean {\n    const nodeIds = selectedNodeInfo.value.nodeIds\n    if (!nodeIds) return true\n\n    // Try missing node cache first\n    const cachedNode = missingNodeCache.value.get(executionNodeId)\n    if (cachedNode && nodeIds.has(String(cachedNode.id))) return true\n\n    // Resolve from graph for model/media candidates\n    const rootGraph = app.rootGraphOrUndefined\n    const graphNode = rootGraph\n      ? getNodeByExecutionId(rootGraph, executionNodeId)\n      : null\n    if (graphNode && nodeIds.has(String(graphNode.id))) return true\n\n    for (const containerExecId of selectedNodeInfo.value\n      .containerExecutionIds) {\n      if (executionNodeId.startsWith(`${containerExecId}:`)) return true\n    }\n\n    return false\n  }\n\n  function isAssetCandidateInSelection(nodeId: string | number): boolean {\n    const executionNodeId = tryNormalizeNodeExecutionId(nodeId)\n    return executionNodeId ? isAssetErrorInSelection(executionNodeId) : false\n  }\n\n  const missingModelCandidatesForSelection = computed(() => {\n    if (!hasSelection.value) return []\n    const candidates = missingModelStore.visibleMissingModelCandidates\n    if (!candidates?.length) return []\n    return candidates.filter(\n      (c) =>\n        (c.nodeId != null && isAssetCandidateInSelection(c.nodeId)) ||\n        (c.sourceExecutionId != null &&\n          isAssetCandidateInSelection(c.sourceExecutionId)) ||\n        c.promotedSources?.some((source) =>\n          isAssetCandidateInSelection(source.executionId)\n        )\n    )\n  })\n\n  /** Model groups narrowed to the selection, for emphasis derivation only. */\n  const missingModelGroupsForSelection = computed(() =>\n    groupMissingModelCandidates(\n      missingModelCandidatesForSelection.value,\n      isCloud\n    )\n  )\n\n  /** Media groups narrowed to the selection, for emphasis derivation only. */\n  const missingMediaGroupsForSelection = computed(() => {\n    if (!hasSelection.value) return []\n    const candidates = missingMediaStore.visibleMissingMediaCandidates\n    if (!candidates?.length) return []\n    const matched = candidates.filter((c) =>\n      isAssetCandidateInSelection(c.nodeId)\n    )\n    if (!matched.length) return []\n    return groupCandidatesByMediaType(matched)\n  })\n\n  function buildMissingModelGroupsForSelection(\n    blockedLastRun: boolean\n  ): ErrorGroup[] {\n    if (!missingModelGroupsForSelection.value.length) return []\n    const count = countMissingModels(missingModelGroupsForSelection.value)\n    return [\n      {\n        type: 'missing_model' as const,\n        severity: 'missing' as const,\n        groupKey: 'missing_model',\n        count,\n        priority: 2,\n        blockedLastRun,\n        ...resolveMissingErrorMessage({\n          kind: 'missing_model',\n          groups: missingModelGroupsForSelection.value,\n          count,\n          isCloud\n        })\n      }\n    ]\n  }\n\n  function buildMissingMediaGroupsForSelection(\n    blockedLastRun: boolean\n  ): ErrorGroup[] {\n    if (!missingMediaGroupsForSelection.value.length) return []\n    const totalRows = countMissingMediaReferences(\n      missingMediaGroupsForSelection.value\n    )\n    return [\n      {\n        type: 'missing_media' as const,\n        severity: 'missing' as const,\n        groupKey: 'missing_media',\n        count: totalRows,\n        priority: 3,\n        blockedLastRun,\n        ...resolveMissingErrorMessage({\n          kind: 'missing_media',\n          groups: missingMediaGroupsForSelection.value,\n          count: totalRows,\n          isCloud\n        })\n      }\n    ]\n  }\n\n  const allErrorGroups = computed<ErrorGroup[]>(() => {\n    const groupsMap = new Map<string, GroupEntry>()\n\n    const promptErrorAbsorbed = processPromptError(groupsMap)\n    const blockedMissingGroups = processNodeErrors(groupsMap)\n    processExecutionError(groupsMap)\n\n    return [\n      ...toSortedGroups(groupsMap),\n      ...buildMissingNodeGroups(promptErrorAbsorbed),\n      ...buildMissingModelGroups(blockedMissingGroups.has('missing_model')),\n      ...buildMissingMediaGroups(blockedMissingGroups.has('missing_media'))\n    ]\n  })\n\n  /**\n   * The subset of error groups whose errors belong to the current canvas\n   * selection. Empty when nothing is selected. Display always shows all\n   * groups; this subset only drives selection emphasis (auto-expand, card\n   * highlight, context strip).\n   */\n  const selectionScopedGroups = computed<ErrorGroup[]>(() => {\n    if (!hasSelection.value) return []\n\n    const groupsMap = new Map<string, GroupEntry>()\n    void processPromptError(groupsMap, true)\n    void processNodeErrors(groupsMap, true)\n    processExecutionError(groupsMap, true)\n\n    // Selection groups drive emphasis only; blockedLastRun cannot be computed\n    // selection-accurately here (absorption is a graph-wide fact), so it is\n    // uniformly false rather than a graph-wide flag masquerading as scoped.\n    return [\n      ...toSortedGroups(groupsMap),\n      ...buildMissingNodeGroups(false, (nodeTypes) =>\n        someNodeTypeInSelection(nodeTypes, selectionMatchedAssetNodeIds.value)\n      ),\n      ...buildMissingModelGroupsForSelection(false),\n      ...buildMissingMediaGroupsForSelection(false)\n    ]\n  })\n\n  /**\n   * Execution node ids referenced by any missing-asset candidate (models,\n   * media, missing node types).\n   */\n  const assetNodeIdsWithError = computed<string[]>(() => {\n    const candidateIds = [\n      ...(missingModelStore.visibleMissingModelCandidates ?? []),\n      ...(missingMediaStore.visibleMissingMediaCandidates ?? [])\n    ].map((candidate) => candidate.nodeId)\n    const missingNodeTypeIds = (\n      missingNodesStore.visibleMissingNodesError?.nodeTypes ?? []\n    ).map((nodeType) =>\n      typeof nodeType === 'string' ? undefined : nodeType.nodeId\n    )\n    return [...candidateIds, ...missingNodeTypeIds]\n      .filter((nodeId) => nodeId != null)\n      .map(String)\n  })\n\n  /**\n   * Asset node ids that belong to the current selection. Drives row-level\n   * highlighting inside the missing-* cards.\n   */\n  const selectionMatchedAssetNodeIds = computed<Set<string>>(() => {\n    if (!hasSelection.value) return new Set()\n    const matched = new Set(\n      assetNodeIdsWithError.value.filter(isAssetCandidateInSelection)\n    )\n    for (const candidate of missingModelCandidatesForSelection.value) {\n      if (candidate.nodeId != null) matched.add(String(candidate.nodeId))\n    }\n    return matched\n  })\n\n  const selectionMatchedGroupKeys = computed<Set<string>>(() => {\n    if (!hasSelection.value) return new Set()\n    return new Set(selectionScopedGroups.value.map((group) => group.groupKey))\n  })\n\n  const selectionMatchedCardIds = computed<Set<string>>(() => {\n    if (!hasSelection.value) return new Set()\n    return new Set(\n      selectionScopedGroups.value\n        .flatMap((group) => (group.type === 'execution' ? group.cards : []))\n        .map((card) => card.id)\n    )\n  })\n\n  const selectionErrorCount = computed(() => {\n    if (!hasSelection.value) return 0\n    return selectionScopedGroups.value.reduce(\n      (sum, group) => sum + group.count,\n      0\n    )\n  })\n\n  /** Distinct nodes affected by any error (workflow-level summary). */\n  const errorNodeCount = computed(() => {\n    const executionNodeIds = allErrorGroups.value\n      .flatMap((group) => (group.type === 'execution' ? group.cards : []))\n      .map((card) => card.nodeId ?? card.rawNodeId)\n      .filter((nodeId) => nodeId != null)\n    return new Set([...executionNodeIds, ...assetNodeIdsWithError.value]).size\n  })\n\n  const filteredGroups = computed<ErrorGroup[]>(() => {\n    const query = toValue(searchQuery).trim()\n    return searchErrorGroups(allErrorGroups.value, query)\n  })\n\n  return {\n    allErrorGroups,\n    filteredGroups,\n    collapseState,\n    errorNodeCache,\n    missingNodeCache,\n    missingPackGroups,\n    missingModelGroups,\n    missingMediaGroups,\n    swapNodeGroups,\n    hasSelection,\n    selectedNodeCount,\n    selectedNodeTitle,\n    selectionMatchedGroupKeys,\n    selectionMatchedCardIds,\n    selectionMatchedAssetNodeIds,\n    selectionErrorCount,\n    errorNodeCount\n  }\n}\n","import { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { storeToRefs } from 'pinia'\n\nimport { isIssuesTabEnabled } from '@/platform/settings/missingWarningVisibility'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useErrorGroups } from '@/components/rightSidePanel/errors/useErrorGroups'\nimport type {\n  MissingPackGroup,\n  SwapNodeGroup\n} from '@/components/rightSidePanel/errors/useErrorGroups'\nimport type { ErrorGroup } from '@/components/rightSidePanel/errors/types'\nimport type { MissingMediaGroup } from '@/platform/missingMedia/types'\nimport type { MissingModelGroup } from '@/platform/missingModel/types'\n\ntype OverlayCopy = { title?: string; message: string }\n\nfunction resolveSingleOverlayCopy(group: ErrorGroup): OverlayCopy | undefined {\n  if (group.type === 'execution') {\n    const [card] = group.cards\n    const [error] = card.errors\n    const message = error.toastMessage ?? error.displayMessage ?? error.message\n\n    if (!message) return undefined\n\n    return {\n      title: error.toastTitle ?? error.displayTitle ?? group.displayTitle,\n      message\n    }\n  }\n\n  const message =\n    group.toastMessage ?? group.displayMessage ?? group.displayTitle\n  if (!message) return undefined\n\n  return {\n    title: group.toastTitle ?? group.displayTitle,\n    message\n  }\n}\n\nfunction resolveGroupOverlayCopy(group: ErrorGroup): OverlayCopy | undefined {\n  const message =\n    group.displayMessage ?? group.toastMessage ?? group.displayTitle\n  if (!message) return undefined\n\n  return {\n    title: group.displayTitle,\n    message\n  }\n}\n\nfunction countMissingNodeReferences(groups: MissingPackGroup[]): number {\n  return groups.reduce((count, group) => count + group.nodeTypes.length, 0)\n}\n\nfunction countSwapNodeReferences(groups: SwapNodeGroup[]): number {\n  return groups.reduce((count, group) => count + group.nodeTypes.length, 0)\n}\n\nfunction getMissingModelRows(groups: MissingModelGroup[]) {\n  return groups.flatMap((group) => group.models)\n}\n\nfunction getMissingMediaRows(groups: MissingMediaGroup[]) {\n  return groups.flatMap((group) => group.items)\n}\n\nfunction hasSingleRowWithAtMostOneReference(\n  rows: Array<{ referencingNodes: readonly unknown[] }>\n): boolean {\n  const row = rows[0]\n  return rows.length === 1 && row.referencingNodes.length <= 1\n}\n\ninterface OverlayGroupContext {\n  missingPackGroups: MissingPackGroup[]\n  missingModelGroups: MissingModelGroup[]\n  missingMediaGroups: MissingMediaGroup[]\n  swapNodeGroups: SwapNodeGroup[]\n}\n\nfunction isSingleLeafGroup(\n  group: ErrorGroup,\n  context: OverlayGroupContext\n): boolean {\n  if (group.type === 'execution') {\n    return group.cards.length === 1 && group.cards[0]?.errors.length === 1\n  }\n\n  if (group.type === 'missing_node') {\n    return (\n      context.missingPackGroups.length === 1 &&\n      countMissingNodeReferences(context.missingPackGroups) === 1\n    )\n  }\n\n  if (group.type === 'swap_nodes') {\n    return (\n      context.swapNodeGroups.length === 1 &&\n      countSwapNodeReferences(context.swapNodeGroups) === 1\n    )\n  }\n\n  if (group.type === 'missing_model') {\n    return hasSingleRowWithAtMostOneReference(\n      getMissingModelRows(context.missingModelGroups)\n    )\n  }\n\n  return hasSingleRowWithAtMostOneReference(\n    getMissingMediaRows(context.missingMediaGroups)\n  )\n}\n\nfunction shouldUseAggregateCopyForSingleGroup(\n  group: ErrorGroup,\n  context: OverlayGroupContext\n): boolean {\n  if (group.type === 'missing_node') {\n    return context.missingPackGroups.length > 1\n  }\n\n  if (group.type === 'swap_nodes') {\n    return context.swapNodeGroups.length > 1\n  }\n\n  if (group.type === 'missing_model') {\n    return getMissingModelRows(context.missingModelGroups).length > 1\n  }\n\n  if (group.type === 'missing_media') {\n    return getMissingMediaRows(context.missingMediaGroups).length > 1\n  }\n\n  return false\n}\n\nexport function useErrorOverlayState() {\n  const { t } = useI18n()\n  const executionErrorStore = useExecutionErrorStore()\n  const { isErrorOverlayOpen } = storeToRefs(executionErrorStore)\n  const {\n    allErrorGroups,\n    missingPackGroups,\n    missingModelGroups,\n    missingMediaGroups,\n    swapNodeGroups\n  } = useErrorGroups('')\n\n  const hasError = computed(() =>\n    allErrorGroups.value.some((group) => group.severity === 'error')\n  )\n\n  const totalErrorCount = computed(() =>\n    allErrorGroups.value.reduce((sum, group) => sum + group.count, 0)\n  )\n\n  const multipleIssueCountLabel = computed(() =>\n    t(\n      'errorOverlay.multipleIssueCount',\n      { count: totalErrorCount.value },\n      totalErrorCount.value\n    )\n  )\n\n  const aggregateOverlayCopy = computed<OverlayCopy>(() => ({\n    title: multipleIssueCountLabel.value,\n    message: t('errorOverlay.multipleIssuesMessage')\n  }))\n\n  const overlayCopy = computed<OverlayCopy | undefined>(() => {\n    const groups = allErrorGroups.value\n    if (groups.length === 0) return undefined\n    if (groups.length > 1) return aggregateOverlayCopy.value\n\n    const [group] = groups\n    const context = {\n      missingPackGroups: missingPackGroups.value,\n      missingModelGroups: missingModelGroups.value,\n      missingMediaGroups: missingMediaGroups.value,\n      swapNodeGroups: swapNodeGroups.value\n    }\n\n    if (shouldUseAggregateCopyForSingleGroup(group, context)) {\n      return aggregateOverlayCopy.value\n    }\n\n    if (isSingleLeafGroup(group, context)) {\n      return resolveSingleOverlayCopy(group) ?? resolveGroupOverlayCopy(group)\n    }\n\n    return resolveGroupOverlayCopy(group)\n  })\n\n  const overlayMessage = computed(() => overlayCopy.value?.message ?? '')\n\n  const overlayTitle = computed(() => overlayCopy.value?.title ?? '')\n\n  const isVisible = computed(\n    () =>\n      isErrorOverlayOpen.value &&\n      isIssuesTabEnabled() &&\n      totalErrorCount.value > 0 &&\n      overlayMessage.value.trim().length > 0\n  )\n\n  return {\n    hasError,\n    isVisible,\n    overlayMessage,\n    overlayTitle\n  }\n}\n","import { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\n\nexport function useViewErrorsInGraph() {\n  const canvasStore = useCanvasStore()\n  const executionErrorStore = useExecutionErrorStore()\n  const rightSidePanelStore = useRightSidePanelStore()\n\n  function viewErrorsInGraph() {\n    canvasStore.linearMode = false\n    if (canvasStore.canvas) {\n      canvasStore.canvas.deselectAll()\n    }\n\n    rightSidePanelStore.openPanel('errors')\n    executionErrorStore.dismissErrorOverlay()\n  }\n\n  return { viewErrorsInGraph }\n}\n","<template>\n  <Transition\n    enter-active-class=\"transition-all duration-300 ease-out\"\n    enter-from-class=\"-translate-y-3 opacity-0\"\n    enter-to-class=\"translate-y-0 opacity-100\"\n  >\n    <div v-if=\"isVisible\" class=\"pointer-events-none flex w-full justify-end\">\n      <div\n        role=\"status\"\n        data-testid=\"error-overlay\"\n        :class=\"\n          cn(\n            'pointer-events-auto relative flex w-fit max-w-120 min-w-80 flex-col gap-2 overflow-hidden rounded-lg border border-l-4 border-border-default bg-base-background p-3 shadow-interface transition-colors duration-200 ease-in-out',\n            hasError\n              ? 'border-l-destructive-background'\n              : 'border-l-warning-foreground'\n          )\n        \"\n      >\n        <div class=\"flex w-full items-start gap-2 pr-8\">\n          <i\n            aria-hidden=\"true\"\n            :class=\"\n              cn(\n                'mt-0.5 size-4 shrink-0',\n                hasError\n                  ? 'icon-[lucide--circle-x] text-destructive-background'\n                  : 'icon-[lucide--triangle-alert] text-warning-foreground'\n              )\n            \"\n          />\n          <span class=\"sr-only\">{{\n            t(hasError ? 'g.error' : 'g.warning')\n          }}</span>\n          <span class=\"min-w-0 flex-1 truncate text-sm text-base-foreground\">\n            {{ overlayTitle }}\n          </span>\n        </div>\n\n        <div\n          class=\"flex w-full items-start gap-2 pr-8\"\n          data-testid=\"error-overlay-messages\"\n        >\n          <span class=\"size-4 shrink-0\" aria-hidden=\"true\" />\n          <p\n            class=\"m-0 line-clamp-3 min-w-0 flex-1 text-sm/snug wrap-break-word whitespace-pre-wrap text-muted-foreground\"\n          >\n            {{ overlayMessage }}\n          </p>\n        </div>\n\n        <div class=\"flex w-full items-center justify-end pt-2\">\n          <Button\n            variant=\"secondary\"\n            size=\"unset\"\n            class=\"min-h-8 rounded-lg px-3 py-2 text-xs font-normal\"\n            data-testid=\"error-overlay-see-errors\"\n            @click=\"viewErrorsInGraph\"\n          >\n            {{\n              appMode\n                ? t('linearMode.error.goto')\n                : t('errorOverlay.viewDetails')\n            }}\n          </Button>\n        </div>\n\n        <Button\n          variant=\"muted-textonly\"\n          size=\"icon-sm\"\n          class=\"absolute top-2 right-2 size-6 rounded-sm\"\n          data-testid=\"error-overlay-dismiss\"\n          :aria-label=\"t('g.close')\"\n          @click=\"dismiss\"\n        >\n          <i class=\"icon-[lucide--x] block size-4 leading-none\" />\n        </Button>\n      </div>\n    </div>\n  </Transition>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useErrorOverlayState } from '@/components/error/useErrorOverlayState'\nimport { useViewErrorsInGraph } from '@/composables/useViewErrorsInGraph'\n\nconst { appMode = false } = defineProps<{ appMode?: boolean }>()\n\nconst { t } = useI18n()\nconst executionErrorStore = useExecutionErrorStore()\nconst { viewErrorsInGraph } = useViewErrorsInGraph()\n\nconst { hasError, isVisible, overlayMessage, overlayTitle } =\n  useErrorOverlayState()\n\nfunction dismiss() {\n  executionErrorStore.dismissErrorOverlay()\n}\n</script>\n","import { defineStore } from 'pinia'\nimport { computed } from 'vue'\n\nimport type { ActionBarButton } from '@/types/comfy'\n\nimport { useExtensionStore } from './extensionStore'\n\nexport const useActionBarButtonStore = defineStore('actionBarButton', () => {\n  const extensionStore = useExtensionStore()\n\n  const buttons = computed<ActionBarButton[]>(() =>\n    extensionStore.extensions.flatMap((e) => e.actionBarButtons ?? [])\n  )\n\n  return {\n    buttons\n  }\n})\n","<template>\n  <div\n    data-testid=\"action-bar-buttons\"\n    class=\"flex h-full shrink-0 items-center gap-1 empty:hidden\"\n  >\n    <Button\n      v-for=\"(button, index) in actionBarButtonStore.buttons\"\n      :key=\"index\"\n      :tooltip=\"button.tooltip\"\n      tooltip-side=\"bottom\"\n      :aria-label=\"button.tooltip || button.label\"\n      :class=\"button.class\"\n      variant=\"muted-textonly\"\n      size=\"sm\"\n      class=\"h-7 rounded-full\"\n      @click=\"button.onClick\"\n    >\n      <i :class=\"button.icon\" />\n      <span v-if=\"!isMobile && button.label\">{{ button.label }}</span>\n    </Button>\n  </div>\n</template>\n\n<script lang=\"ts\" setup>\nimport { breakpointsTailwind, useBreakpoints } from '@vueuse/core'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useActionBarButtonStore } from '@/stores/actionBarButtonStore'\n\nconst actionBarButtonStore = useActionBarButtonStore()\n\nconst breakpoints = useBreakpoints(breakpointsTailwind)\nconst isMobile = breakpoints.smaller('sm')\n</script>\n","<!-- A popover that shows current user information and actions -->\n<template>\n  <div data-testid=\"current-user-popover\" class=\"current-user-popover p-2\">\n    <!-- User Info Section -->\n    <div class=\"mb-4 flex flex-col items-center px-0 py-3\">\n      <UserAvatar\n        class=\"mb-1\"\n        :photo-url=\"userPhotoUrl\"\n        icon-class=\"size-6\"\n        size=\"large\"\n      />\n\n      <!-- User Details -->\n      <h3 class=\"my-0 mb-1 truncate text-base font-bold text-base-foreground\">\n        {{ userDisplayName || $t('g.user') }}\n      </h3>\n      <p v-if=\"userEmail\" class=\"my-0 truncate text-sm text-muted\">\n        {{ userEmail }}\n      </p>\n      <span\n        v-if=\"subscriptionTierName\"\n        class=\"my-0 mt-2 rounded-full bg-secondary-background-hover px-2 py-0.5 text-xs font-bold text-base-foreground uppercase\"\n      >\n        {{ subscriptionTierName }}\n      </span>\n    </div>\n\n    <div v-if=\"showWorkspaceSwitcher\" class=\"relative\">\n      <Tooltip v-model:open=\"isWorkspaceTooltipOpen\">\n        <TooltipTrigger as-child>\n          <Button\n            ref=\"workspaceSwitcherTrigger\"\n            variant=\"muted-textonly\"\n            class=\"flex h-auto w-full items-center justify-between rounded-lg px-4 py-2 hover:bg-secondary-background-hover\"\n            :aria-expanded=\"isWorkspaceSwitcherOpen\"\n            aria-haspopup=\"menu\"\n            aria-controls=\"workspace-switcher-panel\"\n            data-testid=\"workspace-switcher-trigger\"\n            @click=\"isWorkspaceSwitcherOpen = !isWorkspaceSwitcherOpen\"\n            @keydown.escape.stop=\"closeWorkspaceSwitcherAndTooltip\"\n          >\n            <div class=\"flex w-0 flex-1 items-center gap-2\">\n              <WorkspaceProfilePic\n                class=\"size-6 shrink-0 text-xs\"\n                :workspace-name\n                :subscription-tier=\"tier\"\n              />\n              <span class=\"truncate text-sm text-base-foreground\">\n                {{ workspaceName }}\n              </span>\n            </div>\n            <i\n              class=\"pi pi-chevron-down shrink-0 text-sm text-muted-foreground\"\n            />\n          </Button>\n        </TooltipTrigger>\n        <TooltipContent>{{ workspaceName }}</TooltipContent>\n      </Tooltip>\n\n      <div\n        v-if=\"isWorkspaceSwitcherOpen\"\n        id=\"workspace-switcher-panel\"\n        ref=\"workspaceSwitcherPanel\"\n        role=\"menu\"\n        class=\"absolute top-0 right-full z-10 mr-4 rounded-lg border border-border-default bg-base-background shadow-[1px_1px_8px_0_rgba(0,0,0,0.4)]\"\n        data-testid=\"workspace-switcher-panel\"\n      >\n        <WorkspaceSwitcherPopover @select=\"isWorkspaceSwitcherOpen = false\" />\n      </div>\n    </div>\n\n    <!-- Credits Section -->\n    <div\n      v-if=\"canAccessSubscriptionFeatures || showWorkspaceSwitcher\"\n      class=\"flex items-center gap-2 px-4 py-2\"\n    >\n      <i class=\"icon-[lucide--coins] text-sm text-credit\" />\n      <Skeleton v-if=\"isLoading\" class=\"h-5 w-16\" />\n      <span v-else class=\"text-base font-semibold text-base-foreground\">{{\n        formattedBalance\n      }}</span>\n      <Button\n        :tooltip=\"$t('credits.unified.tooltip')\"\n        variant=\"muted-textonly\"\n        size=\"icon-sm\"\n        class=\"mr-auto\"\n        :aria-label=\"$t('credits.unified.tooltip')\"\n        data-testid=\"credits-info-button\"\n      >\n        <i class=\"icon-[lucide--circle-help]\" />\n      </Button>\n      <Button\n        v-if=\"showAddCredits\"\n        variant=\"secondary\"\n        size=\"sm\"\n        class=\"text-base-foreground\"\n        data-testid=\"add-credits-button\"\n        @click=\"handleTopUp\"\n      >\n        {{ $t('subscription.addCredits') }}\n      </Button>\n    </div>\n\n    <div class=\"mx-0 my-2 border-t border-interface-stroke\" />\n\n    <div\n      v-if=\"canAccessSubscriptionFeatures\"\n      class=\"flex cursor-pointer items-center gap-2 px-4 py-2 hover:bg-secondary-background-hover\"\n      data-testid=\"partner-nodes-menu-item\"\n      @click=\"handleOpenPartnerNodesInfo\"\n    >\n      <i class=\"icon-[lucide--tag] text-sm text-muted-foreground\" />\n      <span class=\"flex-1 text-sm text-base-foreground\">{{\n        $t('subscription.partnerNodesCredits')\n      }}</span>\n    </div>\n\n    <div\n      v-if=\"canAccessSubscriptionFeatures || showWorkspaceSwitcher\"\n      class=\"flex cursor-pointer items-center gap-2 px-4 py-2 hover:bg-secondary-background-hover\"\n      data-testid=\"manage-plan-menu-item\"\n      @click=\"handleOpenPlanAndCreditsSettings\"\n    >\n      <i class=\"icon-[lucide--coins] size-4 text-muted-foreground\" />\n      <span class=\"flex-1 text-sm text-base-foreground\">{{\n        $t('credits.credits')\n      }}</span>\n    </div>\n\n    <div\n      class=\"flex cursor-pointer items-center gap-2 px-4 py-2 hover:bg-secondary-background-hover\"\n      data-testid=\"user-settings-menu-item\"\n      @click=\"handleOpenUserSettings\"\n    >\n      <i class=\"icon-[lucide--settings-2] text-sm text-muted-foreground\" />\n      <span class=\"flex-1 text-sm text-base-foreground\">{{\n        $t('userSettings.accountSettings')\n      }}</span>\n    </div>\n\n    <div class=\"mx-0 my-2 border-t border-interface-stroke\" />\n\n    <div\n      class=\"flex cursor-pointer items-center gap-2 px-4 py-2 hover:bg-secondary-background-hover\"\n      data-testid=\"logout-menu-item\"\n      @click=\"handleLogout\"\n    >\n      <i class=\"icon-[lucide--log-out] text-sm text-muted-foreground\" />\n      <span class=\"flex-1 text-sm text-base-foreground\">{{\n        $t('auth.signOut.signOut')\n      }}</span>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { onClickOutside } from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\nimport { computed, onMounted, ref, useTemplateRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { formatCreditsFromCents } from '@/base/credits/comfyCredits'\nimport UserAvatar from '@/components/common/UserAvatar.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { paymentIntentSourceForAddCreditsClick } from '@/platform/telemetry/utils/paymentIntentSource'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport WorkspaceProfilePic from '@/platform/workspace/components/WorkspaceProfilePic.vue'\nimport WorkspaceSwitcherPopover from '@/platform/workspace/components/WorkspaceSwitcherPopover.vue'\nimport { useWorkspaceTierLabel } from '@/platform/workspace/composables/useWorkspaceTierLabel'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useBillingDialogs } from '@/composables/billing/useBillingDialogs'\n\nconst emit = defineEmits<{\n  close: []\n}>()\n\nconst { buildDocsUrl, docsPaths } = useExternalLink()\n\nconst { userDisplayName, userEmail, userPhotoUrl, handleSignOut } =\n  useCurrentUser()\nconst settingsDialog = useSettingsDialog()\nconst { showTopUpCreditsDialog } = useBillingDialogs()\nconst {\n  canAccessSubscriptionFeatures,\n  tier,\n  subscription,\n  balance,\n  isLoading,\n  fetchBalance\n} = useBillingContext()\nconst { formatTierName } = useWorkspaceTierLabel()\nconst { locale } = useI18n()\n\nconst { initState, workspaces, workspaceName } = storeToRefs(\n  useTeamWorkspaceStore()\n)\nconst isWorkspaceSwitcherOpen = ref(false)\nconst isWorkspaceTooltipOpen = ref(false)\n\nfunction closeWorkspaceSwitcherAndTooltip() {\n  isWorkspaceSwitcherOpen.value = false\n  isWorkspaceTooltipOpen.value = false\n}\n\nconst workspaceSwitcherTrigger = useTemplateRef('workspaceSwitcherTrigger')\nconst workspaceSwitcherPanel = useTemplateRef('workspaceSwitcherPanel')\n\nonClickOutside(\n  workspaceSwitcherPanel,\n  () => {\n    isWorkspaceSwitcherOpen.value = false\n  },\n  { ignore: [workspaceSwitcherTrigger] }\n)\n\nconst showWorkspaceSwitcher = computed(\n  () => initState.value === 'ready' && workspaces.value.length > 0\n)\n\nconst { canTopUp, canSubscribeSelfServe } = useBillingCapabilities()\nconst showAddCredits = computed(\n  () => canTopUp.value || canSubscribeSelfServe.value\n)\n\nconst subscriptionTierName = computed(() =>\n  formatTierName(tier.value, subscription.value?.duration === 'ANNUAL')\n)\n\nconst formattedBalance = computed(() => {\n  const cents =\n    balance.value?.effectiveBalanceMicros ?? balance.value?.amountMicros ?? 0\n  return formatCreditsFromCents({\n    cents,\n    locale: locale.value,\n    numberOptions: {\n      minimumFractionDigits: 0,\n      maximumFractionDigits: 2\n    }\n  })\n})\n\nconst handleOpenUserSettings = () => {\n  settingsDialog.show('user')\n  emit('close')\n}\n\nconst handleOpenPlanAndCreditsSettings = () => {\n  // 'workspace' is the V1 Plan & Credits panel; the legacy 'credits' panel is\n  // hidden from the settings menu and only reachable by key.\n  settingsDialog.show('workspace')\n  emit('close')\n}\n\nconst handleTopUp = () => {\n  useTelemetry()?.trackAddApiCreditButtonClicked({ source: 'avatar_menu' })\n  showTopUpCreditsDialog({\n    source: paymentIntentSourceForAddCreditsClick('avatar_menu')\n  })\n  emit('close')\n}\n\nconst handleOpenPartnerNodesInfo = () => {\n  window.open(\n    buildDocsUrl(docsPaths.partnerNodesPricing, { includeLocale: true }),\n    '_blank'\n  )\n  emit('close')\n}\n\nconst handleLogout = async () => {\n  await handleSignOut()\n  emit('close')\n}\n\nonMounted(() => {\n  void fetchBalance()\n})\n</script>\n","<!-- A button that shows workspace icon (Cloud) or user avatar -->\n<template>\n  <div>\n    <Button\n      v-if=\"isLoggedIn\"\n      class=\"p-1 hover:bg-transparent\"\n      variant=\"muted-textonly\"\n      :aria-label=\"$t('g.currentUser')\"\n      data-testid=\"current-user-button\"\n      @click=\"popover?.toggle($event)\"\n    >\n      <div\n        :class=\"\n          cn(\n            'flex items-center justify-center gap-1 rounded-full hover:bg-interface-button-hover-surface',\n            compact && 'size-full'\n          )\n        \"\n      >\n        <Skeleton v-if=\"showWorkspaceSkeleton\" class=\"size-8 rounded-full\" />\n        <WorkspaceProfilePic\n          v-else-if=\"showWorkspaceIcon\"\n          :workspace-name=\"workspaceName\"\n          :subscription-tier=\"activeWorkspace?.subscriptionTier\"\n          :class=\"compact && 'size-full'\"\n        />\n        <UserAvatar\n          v-else\n          :photo-url=\"photoURL\"\n          :class=\"compact && 'h-full w-auto'\"\n        />\n\n        <i v-if=\"showArrow\" class=\"icon-[lucide--chevron-down] size-4 px-1\" />\n      </div>\n    </Button>\n\n    <Popover\n      ref=\"popover\"\n      align=\"end\"\n      :content-class=\"\n        cn(\n          'overflow-visible border-border-default shadow-[1px_1px_8px_0_rgba(0,0,0,0.4)]',\n          showWorkspacePopover ? 'w-fit max-w-96 min-w-80' : 'w-80'\n        )\n      \"\n      @show=\"onPopoverShow\"\n    >\n      <CurrentUserPopoverWorkspace\n        v-if=\"showWorkspacePopover\"\n        ref=\"workspacePopoverContent\"\n        :account-actions-only=\"initState !== 'ready'\"\n        @close=\"closePopover\"\n      />\n      <CurrentUserPopoverLegacy v-else @close=\"closePopover\" />\n    </Popover>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport Popover from '@/components/common/ImperativePopover.vue'\nimport { computed, defineAsyncComponent, ref } from 'vue'\n\nimport UserAvatar from '@/components/common/UserAvatar.vue'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport WorkspaceProfilePic from '@/platform/workspace/components/WorkspaceProfilePic.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport CurrentUserPopoverLegacy from './CurrentUserPopoverLegacy.vue'\n\nconst CurrentUserPopoverWorkspace = defineAsyncComponent(\n  () =>\n    import('../../platform/workspace/components/CurrentUserPopoverWorkspace.vue')\n)\n\nconst { showArrow = true, compact = false } = defineProps<{\n  showArrow?: boolean\n  compact?: boolean\n}>()\n\nconst { isLoggedIn, userPhotoUrl } = useCurrentUser()\n\nconst photoURL = computed<string | undefined>(\n  () => userPhotoUrl.value ?? undefined\n)\n\nconst {\n  workspaceName: teamWorkspaceName,\n  initState,\n  isInPersonalWorkspace,\n  activeWorkspace\n} = storeToRefs(useTeamWorkspaceStore())\n\nconst showWorkspaceSkeleton = computed(\n  () => isCloud && initState.value === 'loading'\n)\nconst showWorkspaceIcon = computed(\n  () => initState.value === 'ready' && !isInPersonalWorkspace.value\n)\nconst showWorkspacePopover = computed(\n  () => isCloud || initState.value === 'ready'\n)\n\nconst workspaceName = computed(() => {\n  if (!showWorkspaceIcon.value) return ''\n  return teamWorkspaceName.value\n})\n\nconst popover = ref<InstanceType<typeof Popover> | null>(null)\nconst workspacePopoverContent = ref<{\n  refreshBalance: () => void\n} | null>(null)\n\nconst closePopover = () => {\n  popover.value?.hide()\n}\n\nconst onPopoverShow = () => {\n  workspacePopoverContent.value?.refreshBalance()\n}\n</script>\n","<template>\n  <Button\n    v-if=\"!isLoggedIn\"\n    data-testid=\"login-button\"\n    variant=\"textonly\"\n    size=\"icon\"\n    :class=\"cn('group rounded-full p-0 text-base-foreground', className)\"\n    :aria-label=\"t('g.login')\"\n    @click=\"handleSignIn()\"\n    @mouseenter=\"showPopover\"\n    @mouseleave=\"hidePopover\"\n  >\n    <span\n      class=\"flex size-full items-center justify-center rounded-full bg-secondary-background transition-colors group-hover:bg-transparent\"\n    >\n      <i class=\"icon-[lucide--user] size-4\" />\n    </span>\n  </Button>\n  <Popover\n    ref=\"popoverRef\"\n    class=\"p-2\"\n    @mouseout=\"hidePopover\"\n    @mouseover=\"cancelHidePopover\"\n  >\n    <div data-testid=\"login-button-popover\">\n      <div class=\"mb-1\">{{ t('auth.loginButton.tooltipHelp') }}</div>\n      <a\n        data-testid=\"login-button-popover-learn-more\"\n        :href=\"apiNodesOverviewUrl\"\n        target=\"_blank\"\n        class=\"text-neutral-500 hover:text-primary\"\n        >{{ t('auth.loginButton.tooltipLearnMore') }}</a\n      >\n    </div>\n  </Popover>\n</template>\n\n<script setup lang=\"ts\">\nimport Popover from '@/components/common/ImperativePopover.vue'\nimport type { HTMLAttributes } from 'vue'\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: className } = defineProps<{\n  class?: HTMLAttributes['class']\n}>()\n\nconst { t } = useI18n()\nconst { isLoggedIn, handleSignIn } = useCurrentUser()\nconst { buildDocsUrl } = useExternalLink()\nconst apiNodesOverviewUrl = buildDocsUrl(\n  '/tutorials/api-nodes/overview#api-nodes',\n  {\n    includeLocale: true\n  }\n)\nconst popoverRef = ref<InstanceType<typeof Popover> | null>(null)\nlet hideTimeout: ReturnType<typeof setTimeout> | null = null\nlet showTimeout: ReturnType<typeof setTimeout> | null = null\n\nconst showPopover = (event: Event) => {\n  // Clear any existing timeouts\n  if (hideTimeout) {\n    clearTimeout(hideTimeout)\n    hideTimeout = null\n  }\n  if (showTimeout) {\n    clearTimeout(showTimeout)\n    showTimeout = null\n  }\n\n  showTimeout = setTimeout(() => {\n    if (popoverRef.value) {\n      popoverRef.value.show(event, event.target as HTMLElement)\n    }\n  }, 200)\n}\n\nconst cancelHidePopover = () => {\n  if (hideTimeout) {\n    clearTimeout(hideTimeout)\n    hideTimeout = null\n  }\n}\n\nconst hidePopover = () => {\n  // Clear show timeout if mouse leaves before popover appears\n  if (showTimeout) {\n    clearTimeout(showTimeout)\n    showTimeout = null\n  }\n\n  hideTimeout = setTimeout(() => {\n    if (popoverRef.value) {\n      popoverRef.value.hide()\n    }\n  }, 150) // Minimal delay to allow moving to popover\n}\n</script>\n","<template>\n  <div\n    class=\"flex w-lg max-w-full flex-col overflow-hidden rounded-2xl border border-border-default bg-base-background shadow-lg\"\n  >\n    <header\n      class=\"flex h-12 items-center justify-between gap-2 border-b border-border-default px-4\"\n    >\n      <div class=\"flex items-center gap-2\">\n        <i class=\"icon-[comfy--extensions-blocks]\" />\n        <h2 class=\"m-0 text-base text-base-foreground\">\n          {{ $t('manager.survey.title') }}\n        </h2>\n      </div>\n      <Button size=\"icon\" :aria-label=\"$t('g.close')\" @click=\"onClose\">\n        <i class=\"icon-[lucide--x] size-4\" />\n      </Button>\n    </header>\n\n    <main class=\"px-5 py-4\">\n      <p\n        v-if=\"status !== 'error'\"\n        class=\"mt-1 mb-4 text-sm text-muted-foreground\"\n      >\n        {{ $t('manager.survey.intro') }}\n      </p>\n      <div class=\"relative\">\n        <iframe\n          v-if=\"surveyUrl && status !== 'error'\"\n          :src=\"surveyUrl\"\n          :title=\"$t('manager.survey.title')\"\n          :style=\"{ height: `${iframeHeight}px` }\"\n          sandbox=\"allow-scripts allow-same-origin allow-forms\"\n          data-testid=\"manager-survey-iframe\"\n          class=\"w-full rounded-lg border-0\"\n          @load=\"onIframeLoad\"\n        />\n        <div\n          v-if=\"status === 'loading'\"\n          data-testid=\"manager-survey-loading\"\n          class=\"pointer-events-none absolute inset-0 flex items-center justify-center\"\n        >\n          <i\n            class=\"icon-[lucide--loader-2] size-6 animate-spin text-muted-foreground\"\n          />\n        </div>\n        <div\n          v-else-if=\"status === 'error'\"\n          data-testid=\"manager-survey-error\"\n          class=\"flex min-h-56 flex-col items-center justify-center gap-2 text-center\"\n        >\n          <i\n            class=\"icon-[lucide--triangle-alert] size-6 text-muted-foreground\"\n          />\n          <p class=\"m-0 text-sm text-muted-foreground\">\n            {{ $t('manager.survey.error') }}\n          </p>\n        </div>\n      </div>\n    </main>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useEventListener, useTimeoutFn } from '@vueuse/core'\nimport { computed, ref, watch } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { remoteConfig } from '@/platform/remoteConfig/remoteConfig'\n\nconst DEFAULT_IFRAME_HEIGHT = 460\nconst MAX_IFRAME_HEIGHT = 10000\nconst SURVEY_LOAD_TIMEOUT_MS = 8000\n\ndefineProps<{\n  onClose: () => void\n}>()\n\nconst { resolvedUserInfo } = useCurrentUser()\n\n// The hosted (external) survey URL is provided per environment by cloud config.\nconst surveyUrl = computed(() => {\n  const base = remoteConfig.value.manager_survey_url\n  if (!base) return undefined\n  try {\n    const url = new URL(base)\n    // Link responses to the logged-in user; omit for anonymous responses.\n    const distinctId = resolvedUserInfo.value?.id\n    if (distinctId) url.searchParams.set('distinct_id', distinctId)\n    return url.toString()\n  } catch {\n    // A malformed configured URL falls back to the error state.\n    return undefined\n  }\n})\n\nconst parsedSurveyUrl = computed(() =>\n  surveyUrl.value ? new URL(surveyUrl.value) : undefined\n)\nconst surveyOrigin = computed(() => parsedSurveyUrl.value?.origin)\n// filter(Boolean) tolerates a trailing slash in the configured URL.\nconst surveyId = computed(() =>\n  parsedSurveyUrl.value?.pathname.split('/').filter(Boolean).pop()\n)\n\nconst status = ref<'loading' | 'ready' | 'error'>('loading')\nconst iframeHeight = ref(DEFAULT_IFRAME_HEIGHT)\n\nconst { start: startLoadTimeout, stop: stopLoadTimeout } = useTimeoutFn(\n  () => {\n    if (status.value === 'loading') status.value = 'error'\n  },\n  SURVEY_LOAD_TIMEOUT_MS,\n  { immediate: false }\n)\n\n// Re-derive load state whenever the survey URL changes — e.g. cloud config or\n// the user identity arriving after the dialog opens — so a late URL recovers\n// from the error state instead of staying stuck.\nwatch(\n  surveyUrl,\n  (url) => {\n    if (!url) {\n      stopLoadTimeout()\n      status.value = 'error'\n      return\n    }\n    status.value = 'loading'\n    startLoadTimeout()\n  },\n  { immediate: true }\n)\n\nconst onIframeLoad = () => {\n  if (status.value === 'loading') status.value = 'ready'\n  stopLoadTimeout()\n}\n\n// PostHog's embedded survey posts its content height for auto-resizing.\nuseEventListener(window, 'message', (event: MessageEvent) => {\n  if (event.origin !== surveyOrigin.value) return\n  const data = event.data\n  if (\n    data?.type === 'posthog:survey:height' &&\n    data?.surveyId === surveyId.value\n  ) {\n    const height = Number.parseInt(data.height, 10)\n    if (height > 0 && height < MAX_IFRAME_HEIGHT) iframeHeight.value = height\n  }\n})\n</script>\n","import { useDialogService } from '@/services/dialogService'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport ManagerSurveyDialog from '@/workbench/extensions/manager/components/survey/ManagerSurveyDialog.vue'\n\nconst DIALOG_KEY = 'global-manager-survey'\n\nexport function useManagerSurveyDialog() {\n  const dialogService = useDialogService()\n  const dialogStore = useDialogStore()\n\n  function hide() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  function show() {\n    dialogService.showLayoutDialog({\n      key: DIALOG_KEY,\n      component: ManagerSurveyDialog,\n      props: {\n        onClose: hide\n      }\n    })\n  }\n\n  return {\n    show,\n    hide\n  }\n}\n","<template>\n  <div\n    v-if=\"!workspaceStore.focusMode\"\n    class=\"ml-(--comfy-canvas-gutter) flex flex-col gap-1 pt-(--comfy-canvas-gutter)\"\n    @mouseenter=\"isTopMenuHovered = true\"\n    @mouseleave=\"isTopMenuHovered = false\"\n  >\n    <div class=\"flex gap-x-0.5\">\n      <div\n        :inert=\"isActionBarsHidden\"\n        :aria-hidden=\"isActionBarsHidden\"\n        :class=\"\n          cn(\n            'max-h-16 min-w-0 flex-1 transition-all duration-300 ease-in-out',\n            isActionBarsHidden &&\n              'max-h-0 -translate-x-8 overflow-hidden opacity-0'\n          )\n        \"\n      >\n        <SubgraphBreadcrumb />\n      </div>\n\n      <div class=\"ml-(--comfy-canvas-gutter) flex flex-col items-end gap-1\">\n        <div\n          data-testid=\"top-menu-actionbars\"\n          :inert=\"isActionBarsHidden\"\n          :aria-hidden=\"isActionBarsHidden\"\n          :class=\"\n            cn(\n              'flex max-h-24 items-start gap-2 transition-all duration-300 ease-in-out',\n              isActionBarsHidden &&\n                'max-h-0 translate-x-8 overflow-hidden opacity-0'\n            )\n          \"\n        >\n          <div\n            ref=\"actionbarCardRef\"\n            data-testid=\"action-bar-card\"\n            :class=\"\n              cn(\n                'pointer-events-auto relative z-1 flex flex-col',\n                isActionbarContainerEmpty\n                  ? 'has-[.border-dashed]:floating-panel'\n                  : 'floating-panel'\n              )\n            \"\n          >\n            <div\n              :class=\"\n                cn(\n                  'actionbar-container relative flex items-center gap-2',\n                  isActionbarContainerEmpty &&\n                    'w-0 min-w-0 has-[.border-dashed]:w-auto has-[.border-dashed]:min-w-auto'\n                )\n              \"\n            >\n              <ActionBarButtons />\n              <div\n                ref=\"legacyCommandsContainerRef\"\n                data-testid=\"legacy-topbar-container\"\n                class=\"[&:not(:has(*>*:not(:empty)))]:hidden\"\n              ></div>\n\n              <ComfyActionbar\n                :docked-progress-container=\"actionbarCardRef\"\n                :queue-overlay-expanded=\"isQueueOverlayExpanded\"\n                @update:progress-target=\"updateProgressTarget\"\n              />\n              <CurrentUserButton\n                v-if=\"isLoggedIn && !isIntegratedTabBar\"\n                class=\"shrink-0\"\n              />\n              <LoginButton v-else-if=\"!isIntegratedTabBar\" />\n              <Button\n                v-if=\"managerState.shouldShowExtensionsButton.value\"\n                :tooltip=\"t('menu.manageExtensions')\"\n                tooltip-side=\"bottom\"\n                variant=\"secondary\"\n                size=\"icon\"\n                :aria-label=\"t('menu.manageExtensions')\"\n                @click=\"openCustomNodeManager\"\n              >\n                <i class=\"icon-[comfy--extensions-blocks] size-4\" />\n                <span\n                  v-if=\"shouldShowRedDot\"\n                  class=\"absolute top-0.5 right-1 size-2 rounded-full bg-red-500\"\n                />\n              </Button>\n              <Button\n                v-if=\"isCloud\"\n                :tooltip=\"t('actionbar.shareTooltip')\"\n                tooltip-side=\"bottom\"\n                variant=\"secondary\"\n                size=\"icon\"\n                :aria-label=\"t('actionbar.shareTooltip')\"\n                @click=\"() => openShareDialog().catch(toastErrorHandler)\"\n                @pointerenter=\"prefetchShareDialog\"\n              >\n                <i class=\"icon-[comfy--send] size-4\" />\n              </Button>\n              <div v-if=\"!isRightSidePanelOpen\" class=\"relative\">\n                <Button\n                  :tooltip=\"t('rightSidePanel.togglePanel')\"\n                  tooltip-side=\"bottom\"\n                  :class=\"\n                    cn(\n                      showErrorIndicatorOnPanelButton &&\n                        'outline-1 outline-destructive-background'\n                    )\n                  \"\n                  variant=\"secondary\"\n                  size=\"icon\"\n                  :aria-label=\"t('rightSidePanel.togglePanel')\"\n                  @click=\"openRightSidePanel\"\n                >\n                  <i class=\"icon-[lucide--panel-right] size-4\" />\n                </Button>\n                <StatusBadge\n                  v-if=\"showErrorIndicatorOnPanelButton\"\n                  variant=\"dot\"\n                  severity=\"danger\"\n                  class=\"absolute -top-1 -right-1\"\n                />\n              </div>\n            </div>\n            <FreeTierQuota v-if=\"!isActionbarFloating\" />\n            <!-- Complement of ComfyActionbar's `!isDocked` mount (same storage\n                 key), so at most one caption renders in any menu state. -->\n            <PartnerNodesRunCaption v-if=\"isActionbarDocked\" />\n          </div>\n        </div>\n        <ErrorOverlay v-if=\"!isActionBarsHidden\" />\n        <QueueProgressOverlay\n          v-if=\"isQueueProgressOverlayEnabled\"\n          v-model:expanded=\"isQueueOverlayExpanded\"\n          :menu-hovered=\"isTopMenuHovered\"\n        />\n      </div>\n    </div>\n\n    <div class=\"flex flex-col items-end gap-1\">\n      <Teleport\n        v-if=\"inlineProgressSummaryTarget\"\n        :to=\"inlineProgressSummaryTarget\"\n      >\n        <div\n          class=\"pointer-events-none absolute inset-x-0 top-full mt-1 flex justify-end pr-1\"\n        >\n          <QueueInlineProgressSummary\n            :hidden=\"shouldHideInlineProgressSummary\"\n          />\n        </div>\n      </Teleport>\n      <QueueInlineProgressSummary\n        v-else-if=\"shouldShowInlineProgressSummary && !isActionbarFloating\"\n        class=\"pr-1\"\n        :hidden=\"shouldHideInlineProgressSummary\"\n      />\n      <QueueNotificationBannerHost\n        v-if=\"isActionbarEnabled\"\n        :class=\"cn('pr-1', isActionBarsHidden && 'hidden')\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useLocalStorage, useMutationObserver } from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\nimport { computed, onBeforeUnmount, onMounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ComfyActionbar from '@/components/actionbar/ComfyActionbar.vue'\nimport PartnerNodesRunCaption from '@/components/actionbar/PartnerNodesRunCaption.vue'\nimport SubgraphBreadcrumb from '@/components/breadcrumb/SubgraphBreadcrumb.vue'\nimport QueueInlineProgressSummary from '@/components/queue/QueueInlineProgressSummary.vue'\nimport QueueNotificationBannerHost from '@/components/queue/QueueNotificationBannerHost.vue'\nimport QueueProgressOverlay from '@/components/queue/QueueProgressOverlay.vue'\nimport ErrorOverlay from '@/components/error/ErrorOverlay.vue'\nimport ActionBarButtons from '@/components/topbar/ActionBarButtons.vue'\nimport CurrentUserButton from '@/components/topbar/CurrentUserButton.vue'\nimport LoginButton from '@/components/topbar/LoginButton.vue'\nimport StatusBadge from '@/components/common/StatusBadge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useQueueFeatureFlags } from '@/composables/queue/useQueueFeatureFlags'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport FreeTierQuota from '@/platform/cloud/subscription/components/FreeTierQuota.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { app } from '@/scripts/app'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useActionBarButtonStore } from '@/stores/actionBarButtonStore'\nimport { useQueueUIStore } from '@/stores/queueStore'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport { isCloud } from '@/platform/distribution/types'\nimport {\n  openShareDialog,\n  prefetchShareDialog\n} from '@/platform/workflow/sharing/composables/lazyShareDialog'\nimport { useConflictAcknowledgment } from '@/workbench/extensions/manager/composables/useConflictAcknowledgment'\nimport { useManagerState } from '@/workbench/extensions/manager/composables/useManagerState'\nimport { useManagerSurveyDialog } from '@/workbench/extensions/manager/composables/useManagerSurveyDialog'\nimport { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst settingStore = useSettingStore()\nconst workspaceStore = useWorkspaceStore()\nconst rightSidePanelStore = useRightSidePanelStore()\nconst canvasStore = useCanvasStore()\nconst isActionBarsHidden = computed(() => canvasStore.isPickingNodes)\nconst managerState = useManagerState()\nconst managerSurveyDialog = useManagerSurveyDialog()\nconst { isLoggedIn } = useCurrentUser()\nconst { t } = useI18n()\nconst { toastErrorHandler } = useErrorHandling()\nconst executionErrorStore = useExecutionErrorStore()\nconst actionBarButtonStore = useActionBarButtonStore()\nconst queueUIStore = useQueueUIStore()\nconst { isOverlayExpanded: isQueueOverlayExpanded } = storeToRefs(queueUIStore)\nconst { shouldShowRedDot: shouldShowConflictRedDot } =\n  useConflictAcknowledgment()\nconst isTopMenuHovered = ref(false)\nconst actionbarCardRef = ref<HTMLElement>()\nconst isActionbarDocked = useLocalStorage('Comfy.MenuPosition.Docked', true)\nconst actionbarPosition = computed(() => settingStore.get('Comfy.UseNewMenu'))\nconst isActionbarEnabled = computed(\n  () => actionbarPosition.value !== 'Disabled'\n)\nconst isActionbarFloating = computed(\n  () => isActionbarEnabled.value && !isActionbarDocked.value\n)\n/**\n * Whether the actionbar container has any visible docked buttons\n * (excluding ComfyActionbar, which uses position:fixed when floating\n * and does not contribute to the container's visual layout).\n */\nconst hasDockedButtons = computed(() => {\n  if (actionBarButtonStore.buttons.length > 0) return true\n  if (hasLegacyContent.value) return true\n  if (!isIntegratedTabBar.value) return true\n  if (managerState.shouldShowExtensionsButton.value) return true\n  if (isCloud) return true\n  if (!isRightSidePanelOpen.value) return true\n  return false\n})\nconst isActionbarContainerEmpty = computed(\n  () => isActionbarFloating.value && !hasDockedButtons.value\n)\nconst isIntegratedTabBar = computed(\n  () => settingStore.get('Comfy.UI.TabBarLayout') !== 'Legacy'\n)\nconst { isQueuePanelV2Enabled, isRunProgressBarEnabled } =\n  useQueueFeatureFlags()\nconst isQueueProgressOverlayEnabled = computed(\n  () => !isQueuePanelV2Enabled.value && !isActionBarsHidden.value\n)\nconst shouldShowInlineProgressSummary = computed(\n  () =>\n    isQueuePanelV2Enabled.value &&\n    isActionbarEnabled.value &&\n    isRunProgressBarEnabled.value &&\n    !isActionBarsHidden.value\n)\nconst progressTarget = ref<HTMLElement | null>(null)\nfunction updateProgressTarget(target: HTMLElement | null) {\n  progressTarget.value = target\n}\nconst inlineProgressSummaryTarget = computed(() => {\n  if (!shouldShowInlineProgressSummary.value || !isActionbarFloating.value) {\n    return null\n  }\n  return progressTarget.value\n})\nconst shouldHideInlineProgressSummary = computed(\n  () => isQueueProgressOverlayEnabled.value && isQueueOverlayExpanded.value\n)\n\nconst shouldShowRedDot = computed((): boolean => {\n  return shouldShowConflictRedDot.value\n})\n\nconst { hasAnyError, isErrorOverlayOpen } = storeToRefs(executionErrorStore)\n\nconst isErrorsTabEnabled = computed(() =>\n  settingStore.get('Comfy.RightSidePanel.ShowErrorsTab')\n)\n\nconst showErrorIndicatorOnPanelButton = computed(\n  () =>\n    isErrorsTabEnabled.value &&\n    hasAnyError.value &&\n    !isRightSidePanelOpen.value &&\n    !isErrorOverlayOpen.value\n)\n\n// Right side panel toggle\nconst { isOpen: isRightSidePanelOpen } = storeToRefs(rightSidePanelStore)\n\nfunction openRightSidePanel() {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'right_side_panel_opened',\n    element_group: 'top_menu'\n  })\n  rightSidePanelStore.togglePanel()\n}\n\nconst legacyCommandsContainerRef = ref<HTMLElement>()\nconst hasLegacyContent = ref(false)\nlet legacyContentCheckRafId: number | null = null\n\nfunction checkLegacyContent() {\n  const el = legacyCommandsContainerRef.value\n  if (!el) {\n    hasLegacyContent.value = false\n    return\n  }\n  hasLegacyContent.value =\n    el.querySelector(':scope > * > *:not(:empty)') !== null\n}\n\nuseMutationObserver(\n  legacyCommandsContainerRef,\n  () => {\n    if (legacyContentCheckRafId !== null) return\n    legacyContentCheckRafId = requestAnimationFrame(() => {\n      legacyContentCheckRafId = null\n      checkLegacyContent()\n    })\n  },\n  { childList: true, subtree: true }\n)\n\nonMounted(() => {\n  const container = legacyCommandsContainerRef.value\n  if (!container) return\n  app.menu.element.style.width = 'fit-content'\n  container.appendChild(app.menu.element)\n  checkLegacyContent()\n})\n\nonBeforeUnmount(() => {\n  if (legacyContentCheckRafId === null) return\n  cancelAnimationFrame(legacyContentCheckRafId)\n})\n\nconst openCustomNodeManager = async () => {\n  if (isCloud) {\n    managerSurveyDialog.show()\n    return\n  }\n  try {\n    await managerState.openManager({\n      initialTab: ManagerTab.All,\n      showToastOnLegacyError: false\n    })\n  } catch (error) {\n    try {\n      toastErrorHandler(error)\n    } catch (toastError) {\n      console.error(error)\n      console.error(toastError)\n    }\n  }\n}\n</script>\n","<template>\n  <component :is=\"extension.component\" v-if=\"extension.type === 'vue'\" />\n  <div\n    v-else\n    :ref=\"\n      (el) => {\n        if (el)\n          mountCustomExtension(\n            props.extension as CustomExtension,\n            el as HTMLElement\n          )\n      }\n    \"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { onBeforeUnmount } from 'vue'\n\nimport type { CustomExtension, VueExtension } from '@/types/extensionTypes'\n\nconst props = defineProps<{\n  extension: VueExtension | CustomExtension\n}>()\n\nconst mountCustomExtension = (extension: CustomExtension, el: HTMLElement) => {\n  extension.render(el)\n}\n\nonBeforeUnmount(() => {\n  if (props.extension.type === 'custom' && props.extension.destroy) {\n    props.extension.destroy()\n  }\n})\n</script>\n","<template>\n  <Tabs v-model=\"bottomPanelStore.activeBottomPanelTabId\" class=\"h-full gap-0\">\n    <TabsList variant=\"panel\" class=\"w-full shrink-0\">\n      <div class=\"flex w-full justify-between\">\n        <div class=\"tabs-container font-inter\">\n          <TabsTrigger\n            v-for=\"tab in bottomPanelStore.bottomPanelTabs\"\n            :key=\"tab.id\"\n            :value=\"tab.id\"\n            variant=\"panel\"\n            :class=\"\n              cn(\n                bottomPanelStore.bottomPanelTabs.length === 1 &&\n                  'pointer-events-none data-[state=active]:bg-transparent data-[state=active]:text-muted-foreground'\n              )\n            \"\n          >\n            <span class=\"font-normal\">\n              {{ getTabDisplayTitle(tab) }}\n            </span>\n          </TabsTrigger>\n        </div>\n        <div class=\"flex items-center gap-2\">\n          <Button\n            v-if=\"isShortcutsTabActive\"\n            variant=\"muted-textonly\"\n            size=\"sm\"\n            @click=\"openKeybindingSettings\"\n          >\n            <i class=\"pi pi-cog\" />\n            {{ $t('shortcuts.manageShortcuts') }}\n          </Button>\n          <Button\n            class=\"justify-self-end\"\n            variant=\"muted-textonly\"\n            size=\"sm\"\n            :aria-label=\"t('g.close')\"\n            @click=\"closeBottomPanel\"\n          >\n            <i class=\"pi pi-times\" />\n          </Button>\n        </div>\n      </div>\n    </TabsList>\n    <TabsContent\n      v-if=\"\n        bottomPanelStore.bottomPanelVisible &&\n        bottomPanelStore.activeBottomPanelTab\n      \"\n      :value=\"bottomPanelStore.activeBottomPanelTab.id\"\n      class=\"h-0 grow\"\n    >\n      <ExtensionSlot :extension=\"bottomPanelStore.activeBottomPanelTab\" />\n    </TabsContent>\n  </Tabs>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ExtensionSlot from '@/components/common/ExtensionSlot.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tabs from '@/components/ui/tabs/Tabs.vue'\nimport TabsContent from '@/components/ui/tabs/TabsContent.vue'\nimport TabsList from '@/components/ui/tabs/TabsList.vue'\nimport TabsTrigger from '@/components/ui/tabs/TabsTrigger.vue'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { useBottomPanelStore } from '@/stores/workspace/bottomPanelStore'\nimport type { BottomPanelExtension } from '@/types/extensionTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst bottomPanelStore = useBottomPanelStore()\nconst settingsDialog = useSettingsDialog()\nconst { t } = useI18n()\n\nconst isShortcutsTabActive = computed(() => {\n  const activeTabId = bottomPanelStore.activeBottomPanelTabId\n  return (\n    activeTabId === 'shortcuts-essentials' ||\n    activeTabId === 'shortcuts-view-controls'\n  )\n})\n\nconst shouldCapitalizeTab = (tabId: string): boolean => {\n  return tabId !== 'shortcuts-essentials' && tabId !== 'shortcuts-view-controls'\n}\n\nconst getTabDisplayTitle = (tab: BottomPanelExtension): string => {\n  const title = tab.titleKey ? t(tab.titleKey) : tab.title || ''\n  return shouldCapitalizeTab(tab.id) ? title.toUpperCase() : title\n}\n\nconst openKeybindingSettings = async () => {\n  settingsDialog.show('keybinding')\n}\n\nconst closeBottomPanel = () => {\n  bottomPanelStore.activePanel = null\n}\n</script>\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport EditableText from '@/components/common/EditableText.vue'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useAppModeStore } from '@/stores/appModeStore'\n\nconst { t } = useI18n()\nconst { widget } = defineProps<{\n  widget: IBaseWidget\n  description?: string\n  disabled?: boolean\n  labelClass?: string\n  labelType?: string\n}>()\n\nconst placeholder = computed(() =>\n  t('linearMode.arrange.descriptionPlaceholder')\n)\n\nconst isEditing = ref(false)\nfunction onEditComplete(val: string) {\n  isEditing.value = false\n  const description = val && val !== placeholder.value ? val : undefined\n  useAppModeStore().updateInputConfig(widget, { description })\n}\n</script>\n<template>\n  <EditableText\n    :model-value=\"description || placeholder\"\n    :is-editing\n    :label-class=\"cn('truncate', labelClass)\"\n    :label-type\n    @dblclick=\"!disabled && (isEditing = true)\"\n    @edit=\"onEditComplete\"\n    @cancel=\"isEditing = false\"\n  />\n</template>\n","import { onScopeDispose } from 'vue'\n\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { InputWidgetConfig } from '@/platform/workflow/management/stores/comfyWorkflow'\n\nconst RESIZABLE_SELECTOR = 'textarea, [data-slot=\"drop-zone-indicator\"]'\n\nexport function useAppModeWidgetResizing(\n  onResize: (widget: IBaseWidget, config: InputWidgetConfig) => void\n) {\n  let pendingHandler: (() => void) | null = null\n\n  function clearPendingHandler() {\n    if (!pendingHandler) return\n    window.removeEventListener('pointerup', pendingHandler)\n    window.removeEventListener('pointercancel', pendingHandler)\n    pendingHandler = null\n  }\n\n  onScopeDispose(clearPendingHandler)\n\n  function onPointerDown(widget: IBaseWidget, event: PointerEvent) {\n    const wrapper = event.currentTarget\n    const target = event.target\n    if (!(wrapper instanceof HTMLElement) || !(target instanceof HTMLElement))\n      return\n    const resizable = target.closest<HTMLElement>(RESIZABLE_SELECTOR)\n    if (!resizable || !wrapper.contains(resizable)) return\n\n    clearPendingHandler()\n\n    const startHeight = resizable.offsetHeight\n    const handler = () => {\n      window.removeEventListener('pointerup', handler)\n      window.removeEventListener('pointercancel', handler)\n      pendingHandler = null\n      const height = resizable.offsetHeight\n      if (height === startHeight) return\n      onResize(widget, { height })\n    }\n    pendingHandler = handler\n    window.addEventListener('pointerup', handler)\n    window.addEventListener('pointercancel', handler)\n  }\n\n  return { onPointerDown }\n}\n","import type { MediaKind } from '@/platform/assets/schemas/mediaAssetSchema'\n\nexport function iconForMediaType(mediaType: MediaKind): string {\n  switch (mediaType) {\n    case 'video':\n      return 'icon-[lucide--video]'\n    case 'audio':\n      return 'icon-[lucide--music]'\n    case '3D':\n      return 'icon-[lucide--box]'\n    case 'text':\n      return 'icon-[lucide--text]'\n    case 'other':\n      return 'icon-[lucide--check-check]'\n    default:\n      return 'icon-[lucide--image]'\n  }\n}\n","import { extractWidgetStringValue } from '@/composables/maskeditor/useMaskEditorLoader'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { iconForMediaType } from '@/platform/assets/utils/mediaIconUtil'\nimport { appendCloudResParam } from '@/platform/distribution/cloudPreviewUtil'\nimport { api } from '@/scripts/api'\nimport { app } from '@/scripts/app'\nimport type { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { parseWidgetId } from '@/types/widgetId'\nimport type { WidgetId } from '@/types/widgetId'\nimport { parseImageWidgetValue } from '@/utils/imageUtil'\n\ntype LoaderMediaType = 'image' | 'video' | 'audio'\n\nexport interface LoaderDropIndicator {\n  iconClass: string\n  mediaUrl: string | undefined\n  mediaType: LoaderMediaType\n  label: string | undefined\n  onClick: () => void\n  onMaskEdit: (() => void) | undefined\n}\n\ninterface LoaderMediaConfig {\n  /** Name of the widget holding the selected filename. */\n  widgetName: string\n  mediaType: LoaderMediaType\n  labelKey: string\n}\n\n/**\n * Native loader node types that upload/select a single media file. App mode\n * only renders widgets, so these types are hard-coded here to get the same\n * inline preview as the normal editor. See FE-1344 for the long-term plan of\n * making the preview part of the selection widget itself.\n */\nconst LOADER_MEDIA_CONFIG: Partial<Record<string, LoaderMediaConfig>> = {\n  LoadImage: {\n    widgetName: 'image',\n    mediaType: 'image',\n    labelKey: 'linearMode.dragAndDropImage'\n  },\n  LoadVideo: {\n    widgetName: 'file',\n    mediaType: 'video',\n    labelKey: 'linearMode.dragAndDropVideo'\n  },\n  LoadAudio: {\n    widgetName: 'audio',\n    mediaType: 'audio',\n    labelKey: 'linearMode.dragAndDropAudio'\n  }\n}\n\nfunction buildMediaUrl(\n  mediaType: LoaderMediaType,\n  filename: string,\n  subfolder: string,\n  type: string,\n  previewRevision?: (filename: string) => number\n) {\n  if (!filename) return undefined\n\n  const params = new URLSearchParams({ filename, subfolder, type })\n  appendCloudResParam(params, filename)\n  const revision = previewRevision?.(filename)\n  if (revision) params.set('template_input_revision', String(revision))\n  const previewParam = mediaType === 'image' ? app.getPreviewFormatParam() : ''\n  return api.apiURL(`/view?${params}${previewParam}`)\n}\n\n/**\n * Builds the App mode drop-zone preview for native loader nodes\n * (`LoadImage`, `LoadVideo`, `LoadAudio`). Returns `undefined` for any other\n * node type.\n */\nexport function getLoaderDropIndicator(\n  node: LGraphNode,\n  id: WidgetId,\n  options: {\n    mobile: boolean\n    label: (key: string) => string\n    onMaskEdit: (node: LGraphNode) => void\n    widgetValueStore: Pick<ReturnType<typeof useWidgetValueStore>, 'getWidget'>\n    previewRevision?: (filename: string) => number\n  }\n): LoaderDropIndicator | undefined {\n  const config = LOADER_MEDIA_CONFIG[node.type]\n  if (!config) return undefined\n  if (parseWidgetId(id).name !== config.widgetName) return undefined\n\n  const stringValue = extractWidgetStringValue(\n    options.widgetValueStore.getWidget(id)?.value\n  )\n  const { filename, subfolder, type } = stringValue\n    ? parseImageWidgetValue(stringValue)\n    : { filename: '', subfolder: '', type: 'input' }\n\n  const mediaUrl = buildMediaUrl(\n    config.mediaType,\n    filename,\n    subfolder,\n    type,\n    options.previewRevision\n  )\n\n  return {\n    iconClass: iconForMediaType(config.mediaType),\n    mediaUrl,\n    mediaType: config.mediaType,\n    label: options.mobile ? undefined : options.label(config.labelKey),\n    onClick: () =>\n      node.widgets?.find((w) => w.name === 'upload')?.callback?.(undefined),\n    onMaskEdit:\n      config.mediaType === 'image' && mediaUrl\n        ? () => options.onMaskEdit(node)\n        : undefined\n  }\n}\n","import { useEventListener } from '@vueuse/core'\nimport { computed, shallowRef, triggerRef } from 'vue'\n\nimport { promotedInputWidgets } from '@/core/graph/subgraph/promotedInputWidget'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { InputWidgetConfig } from '@/platform/workflow/management/stores/comfyWorkflow'\nimport { app } from '@/scripts/app'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport type { WidgetId } from '@/types/widgetId'\nimport { isWidgetId, parseWidgetId } from '@/types/widgetId'\n\nexport type ResolvedSelection =\n  | {\n      status: 'resolved'\n      widgetId: WidgetId\n      node: LGraphNode\n      widget: IBaseWidget\n      displayName: string\n      config?: InputWidgetConfig\n    }\n  | {\n      status: 'unknown'\n      widgetId: WidgetId\n      displayName: string\n      config?: InputWidgetConfig\n    }\n\nexport function useResolvedSelectedInputs() {\n  const appModeStore = useAppModeStore()\n  const rootGraph = app.rootGraph\n\n  const graphNodes = shallowRef<LGraphNode[]>([...rootGraph.nodes])\n  const refreshGraphNodes = () => (graphNodes.value = [...rootGraph.nodes])\n  useEventListener(() => rootGraph.events, 'configured', refreshGraphNodes)\n  useEventListener(\n    () => rootGraph.events,\n    'convert-to-subgraph',\n    refreshGraphNodes\n  )\n  useEventListener(\n    () => rootGraph.events,\n    'subgraph-created',\n    refreshGraphNodes\n  )\n  useEventListener(\n    () => rootGraph.events,\n    'node:slot-label:changed',\n    () => triggerRef(graphNodes)\n  )\n\n  return computed<ResolvedSelection[]>(() => {\n    void graphNodes.value\n    return appModeStore.selectedInputs.flatMap(\n      ([widgetId, displayName, config]): ResolvedSelection[] => {\n        if (!isWidgetId(widgetId)) return []\n        const { nodeId, name } = parseWidgetId(widgetId)\n        const node = rootGraph.getNodeById(nodeId)\n        const widgets = node?.isSubgraphNode()\n          ? promotedInputWidgets(node)\n          : node?.widgets\n        const widget =\n          widgets?.find((w) => w.widgetId === widgetId) ??\n          widgets?.find((w) => w.name === name)\n        if (!node || !widget) {\n          return [{ status: 'unknown', widgetId, displayName, config }]\n        }\n        return [\n          { status: 'resolved', widgetId, node, widget, displayName, config }\n        ]\n      }\n    )\n  })\n}\n","<script setup lang=\"ts\">\nimport AudioPreviewPlayer from '@/renderer/extensions/vueNodes/widgets/components/audio/AudioPreviewPlayer.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  mediaType,\n  mediaUrl,\n  label,\n  iconClass,\n  isHovered = false\n} = defineProps<{\n  mediaType: 'image' | 'video' | 'audio'\n  mediaUrl?: string\n  label?: string\n  iconClass?: string\n  isHovered?: boolean\n}>()\n</script>\n<template>\n  <div\n    :class=\"\n      cn(\n        'flex h-full max-w-full flex-col items-center justify-center gap-2 overflow-hidden rounded-[7px] p-3 text-center text-sm/tight transition-colors',\n        isHovered &&\n          !mediaUrl &&\n          'border border-dashed border-component-node-foreground-secondary bg-component-node-widget-background-hovered'\n      )\n    \"\n  >\n    <div v-if=\"mediaUrl\" class=\"max-h-full max-w-full\">\n      <img\n        v-if=\"mediaType === 'image'\"\n        class=\"max-h-full max-w-full rounded-md object-contain\"\n        data-testid=\"drop-zone-media\"\n        :alt=\"label ?? ''\"\n        :src=\"mediaUrl\"\n      />\n      <video\n        v-else-if=\"mediaType === 'video'\"\n        class=\"max-h-full max-w-full rounded-md object-contain\"\n        data-testid=\"drop-zone-media\"\n        :aria-label=\"label ?? ''\"\n        :src=\"mediaUrl\"\n        controls\n        playsinline\n        preload=\"metadata\"\n        @click.stop\n      />\n      <AudioPreviewPlayer\n        v-else\n        data-testid=\"drop-zone-media\"\n        :model-value=\"mediaUrl\"\n        :hide-when-empty=\"false\"\n        @click.stop\n      />\n    </div>\n    <template v-else>\n      <span v-if=\"label\" v-text=\"label\" />\n      <i\n        v-if=\"iconClass\"\n        :class=\"\n          cn('size-4 text-component-node-foreground-secondary', iconClass)\n        \"\n      />\n    </template>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport {\n  DialogClose,\n  DialogContent,\n  DialogDescription,\n  DialogOverlay,\n  DialogPortal,\n  DialogRoot,\n  DialogTitle,\n  VisuallyHidden\n} from 'reka-ui'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\n\nconst open = defineModel<boolean>({ default: false })\n\nconst { src, alt = '' } = defineProps<{\n  src: string\n  alt?: string\n}>()\n\nconst { t } = useI18n()\n</script>\n<template>\n  <DialogRoot v-model:open=\"open\">\n    <DialogPortal>\n      <DialogOverlay\n        class=\"fixed inset-0 z-30 bg-black/60 data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:animate-in data-[state=open]:fade-in-0\"\n      />\n      <DialogContent\n        class=\"fixed top-1/2 left-1/2 z-1700 -translate-1/2 outline-none data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=closed]:zoom-out-50 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-50\"\n        @escape-key-down=\"open = false\"\n      >\n        <VisuallyHidden>\n          <DialogTitle>{{ alt || t('g.imageLightbox') }}</DialogTitle>\n          <DialogDescription v-if=\"alt\">{{ alt }}</DialogDescription>\n        </VisuallyHidden>\n        <DialogClose as-child>\n          <Button\n            :aria-label=\"t('g.close')\"\n            size=\"icon\"\n            variant=\"muted-textonly\"\n            class=\"absolute -top-2 -right-2 z-10 translate-x-full text-white hover:text-white/80\"\n          >\n            <i class=\"icon-[lucide--x] size-5\" />\n          </Button>\n        </DialogClose>\n        <img\n          :src\n          :alt\n          class=\"max-h-[90vh] max-w-[90vw] rounded-sm object-contain\"\n        />\n      </DialogContent>\n    </DialogPortal>\n  </DialogRoot>\n</template>\n","<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ImageLightbox from '@/components/common/ImageLightbox.vue'\n\nconst { mediaUrl, label, onMaskEdit } = defineProps<{\n  mediaUrl: string\n  label?: string\n  onMaskEdit?: () => void\n}>()\n\nconst { t } = useI18n()\nconst lightboxOpen = ref(false)\n</script>\n<template>\n  <div\n    class=\"absolute top-2 right-5 z-10 flex gap-1 opacity-0 transition-opacity duration-200 group-focus-within/dropzone:opacity-100 group-hover/dropzone:opacity-100\"\n  >\n    <button\n      v-if=\"onMaskEdit\"\n      type=\"button\"\n      :aria-label=\"t('maskEditor.openMaskEditor')\"\n      :title=\"t('maskEditor.openMaskEditor')\"\n      class=\"flex cursor-pointer items-center justify-center rounded-lg bg-base-foreground p-2 text-base-background transition-colors hover:bg-base-foreground/90\"\n      @click.stop=\"onMaskEdit()\"\n    >\n      <i class=\"icon-[comfy--mask] size-4\" />\n    </button>\n    <button\n      type=\"button\"\n      :aria-label=\"t('mediaAsset.actions.zoom')\"\n      :title=\"t('mediaAsset.actions.zoom')\"\n      class=\"flex cursor-pointer items-center justify-center rounded-lg bg-base-foreground p-2 text-base-background transition-colors hover:bg-base-foreground/90\"\n      @click.stop=\"lightboxOpen = true\"\n    >\n      <i class=\"icon-[lucide--zoom-in] size-4\" />\n    </button>\n  </div>\n  <ImageLightbox v-model=\"lightboxOpen\" :src=\"mediaUrl\" :alt=\"label ?? ''\" />\n</template>\n","<script setup lang=\"ts\">\nimport { useDropZone } from '@vueuse/core'\nimport { computed, ref } from 'vue'\n\nimport { useClickDragGuard } from '@/composables/useClickDragGuard'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport DropZoneIndicatorContent from './DropZoneIndicatorContent.vue'\nimport DropZoneMediaActions from './DropZoneMediaActions.vue'\n\ndefineOptions({ inheritAttrs: false })\n\nconst {\n  onDragOver,\n  onDragDrop,\n  dropIndicator,\n  forceHovered = false\n} = defineProps<{\n  onDragOver?: (e: DragEvent) => boolean\n  onDragDrop?: (e: DragEvent) => Promise<boolean> | boolean\n  dropIndicator?: {\n    iconClass?: string\n    mediaUrl?: string\n    mediaType?: 'image' | 'video' | 'audio'\n    label?: string\n    onClick?: (e: MouseEvent) => void\n    onMaskEdit?: () => void\n  }\n  forceHovered?: boolean\n}>()\n\nconst mediaType = computed(() => dropIndicator?.mediaType ?? 'image')\n// Video's native controls and AudioPreviewPlayer's buttons are invalid\n// markup nested inside a <button> — render a <div> instead once one is shown.\nconst hasPlayableMedia = computed(\n  () => mediaType.value !== 'image' && !!dropIndicator?.mediaUrl\n)\n\nconst dropZoneRef = ref<HTMLElement | null>(null)\nconst canAcceptDrop = ref(false)\nconst clickGuard = useClickDragGuard(5)\n\nfunction onPointerDown(e: PointerEvent) {\n  clickGuard.recordStart(e)\n}\n\nfunction onIndicatorClick(e: MouseEvent) {\n  const dragged = e.detail !== 0 && clickGuard.wasDragged(e)\n  clickGuard.reset()\n  if (dragged) return\n  dropIndicator?.onClick?.(e)\n}\n\nconst { isOverDropZone } = useDropZone(dropZoneRef, {\n  onDrop: (_files, event) => {\n    // Stop propagation to prevent global handlers from creating a new node\n    event.stopPropagation()\n\n    if (onDragDrop && event) {\n      onDragDrop(event)\n    }\n    canAcceptDrop.value = false\n  },\n  onOver: (_, event) => {\n    if (onDragOver && event) {\n      canAcceptDrop.value = onDragOver(event)\n    }\n  },\n  onLeave: () => {\n    canAcceptDrop.value = false\n  }\n})\n\nconst isHovered = computed(\n  () => forceHovered || (canAcceptDrop.value && isOverDropZone.value)\n)\nconst indicatorTag = computed(() =>\n  dropIndicator?.onClick && !hasPlayableMedia.value ? 'button' : 'div'\n)\n</script>\n<template>\n  <div\n    v-if=\"onDragOver && onDragDrop\"\n    ref=\"dropZoneRef\"\n    v-bind=\"$attrs\"\n    data-slot=\"drop-zone\"\n    :class=\"\n      cn(\n        'rounded-lg transition-colors',\n        isHovered && 'bg-component-node-widget-background-hovered'\n      )\n    \"\n  >\n    <slot />\n    <div v-if=\"dropIndicator\" class=\"group/dropzone relative\">\n      <component\n        :is=\"indicatorTag\"\n        :type=\"indicatorTag === 'button' ? 'button' : undefined\"\n        :aria-label=\"\n          indicatorTag === 'button' ? dropIndicator.label : undefined\n        \"\n        data-slot=\"drop-zone-indicator\"\n        data-testid=\"drop-zone-indicator\"\n        :class=\"\n          cn(\n            'm-3 block h-25 resize-y appearance-none overflow-hidden rounded-lg border border-node-component-border bg-transparent p-1 text-left text-component-node-foreground-secondary transition-colors',\n            indicatorTag === 'button' && 'cursor-pointer'\n          )\n        \"\n        @pointerdown=\"onPointerDown\"\n        @click.prevent=\"onIndicatorClick\"\n      >\n        <DropZoneIndicatorContent\n          :media-type=\"mediaType\"\n          :media-url=\"dropIndicator.mediaUrl\"\n          :label=\"dropIndicator.label\"\n          :icon-class=\"dropIndicator.iconClass\"\n          :is-hovered=\"isHovered\"\n        />\n      </component>\n      <DropZoneMediaActions\n        v-if=\"mediaType === 'image' && dropIndicator.mediaUrl\"\n        :media-url=\"dropIndicator.mediaUrl\"\n        :label=\"dropIndicator.label\"\n        :on-mask-edit=\"dropIndicator.onMaskEdit\"\n      />\n    </div>\n  </div>\n  <slot v-else />\n</template>\n","<script setup lang=\"ts\">\nimport { whenever } from '@vueuse/core'\nimport { onMounted, ref } from 'vue'\n\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { DOMWidget } from '@/scripts/domWidget'\nimport { isDOMWidget } from '@/scripts/domWidget'\nimport { resolveWidgetFromHostNode } from '@/renderer/extensions/vueNodes/widgets/utils/resolvePromotedWidget'\nimport type { NodeId } from '@/types/nodeId'\nimport type { SimplifiedWidget } from '@/types/simplifiedWidget'\n\n// Button widgets don't have a v-model value, they trigger actions\nconst props = defineProps<{\n  widget: SimplifiedWidget<undefined>\n  nodeId: NodeId\n}>()\n\nconst domEl = ref<HTMLElement>()\n\nconst canvasStore = useCanvasStore()\nconst { canvas } = canvasStore\n\nfunction findDOMWidget(): DOMWidget<HTMLElement, object | string> | undefined {\n  const hostNode = canvas?.graph?.getNodeById(props.nodeId) ?? undefined\n  const resolved = resolveWidgetFromHostNode(hostNode, props.widget.name)\n  if (resolved && isDOMWidget(resolved.widget)) return resolved.widget\n\n  return undefined\n}\n\nfunction mountWidgetElement() {\n  if (!domEl.value) return\n  const widget = findDOMWidget()\n  if (!widget) return\n  if (domEl.value.contains(widget.element)) return\n  domEl.value.replaceChildren(widget.element)\n}\n\nonMounted(() => {\n  mountWidgetElement()\n})\n\nwhenever(() => !canvasStore.linearMode, mountWidgetElement)\n</script>\n<template>\n  <div\n    ref=\"domEl\"\n    class=\"flex flex-col *:flex-1\"\n    @pointerdown.stop\n    @pointermove.stop\n    @pointerup.stop\n  />\n</template>\n","import { showNodeOptions } from '@/composables/graph/useMoreOptionsMenu'\nimport { resolvePromotedWidgetSource } from '@/core/graph/subgraph/resolvePromotedWidgetSource'\nimport type { INodeInputSlot } from '@/lib/litegraph/src/types/slots'\nimport type { LGraph, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type {\n  IBaseWidget,\n  IWidgetOptions\n} from '@/lib/litegraph/src/types/widgets'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport type {\n  WidgetGridItem,\n  WidgetSlotMetadata\n} from '@/renderer/extensions/vueNodes/types/widgetGrid'\nimport WidgetDOM from '@/renderer/extensions/vueNodes/widgets/components/WidgetDOM.vue'\nimport WidgetLegacy from '@/renderer/extensions/vueNodes/widgets/components/WidgetLegacy.vue'\nimport { getComponent } from '@/renderer/extensions/vueNodes/widgets/registry/widgetRegistry'\nimport { app } from '@/scripts/app'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport {\n  stripGraphPrefix,\n  useWidgetValueStore\n} from '@/stores/widgetValueStore'\nimport {\n  createNodeExecutionId,\n  createNodeLocatorId\n} from '@/types/nodeIdentification'\nimport type { NodeExecutionId, NodeLocatorId } from '@/types/nodeIdentification'\nimport type { NodeId } from '@/types/nodeId'\nimport type { NodeState } from '@/types/nodeState'\nimport type { LinkTopology } from '@/types/linkTopology'\nimport { getControlWidget } from '@/types/simplifiedWidget'\nimport { isWidgetVisibleOnSurface } from '@/types/widgetVisibility'\nimport type { WidgetVisibilityComponent } from '@/types/widgetVisibility'\nimport type {\n  LinkedUpstreamInfo,\n  SafeControlWidget,\n  SimplifiedWidget,\n  WidgetValue\n} from '@/types/simplifiedWidget'\nimport type { WidgetId } from '@/types/widgetId'\nimport {\n  executionIdFromState,\n  executionIdToNodeLocatorId,\n  getNodeByState,\n  subgraphIdFromState\n} from '@/utils/graphTraversalUtil'\nimport { mapLiveWidgetsById } from '@/utils/litegraphUtil'\n\ntype TooltipValueType = 'asset' | 'combo' | 'number' | 'text'\nfunction isTooltipValueType(val: unknown): val is TooltipValueType {\n  return (\n    val === 'asset' || val === 'combo' || val === 'number' || val === 'text'\n  )\n}\n\ninterface WidgetTooltipSource {\n  name: string\n  tooltip?: string\n}\n\ninterface WidgetErrorTarget {\n  executionId: NodeExecutionId\n  widgetName: string\n}\n\nexport interface ProcessedWidget extends WidgetGridItem {\n  handleContextMenu: (e: PointerEvent) => void\n  hasError: boolean\n  hasLayoutSize: boolean\n  tooltipText: string\n  updateHandler: (value: WidgetValue) => void\n  widgetId: WidgetId\n}\n\nexport interface WidgetUiCallbacks {\n  getTooltipText: (widget: WidgetTooltipSource, fullValue?: string) => string\n  handleNodeRightClick: (e: PointerEvent, nodeId: NodeId) => void\n}\n\nexport interface ComputeProcessedWidgetsOptions {\n  nodeData: NodeState | undefined\n  widgetIds?: readonly WidgetId[]\n  graphId: string | undefined\n  showAdvanced: boolean\n  isGraphReady: boolean\n  rootGraph: LGraph | null\n  ui: WidgetUiCallbacks\n}\n\nfunction normalizeWidgetValue(value: unknown): WidgetValue {\n  if (value === undefined) {\n    return undefined\n  }\n  if (value === null) {\n    return null\n  }\n  if (\n    typeof value === 'string' ||\n    typeof value === 'number' ||\n    typeof value === 'boolean'\n  ) {\n    return value\n  }\n  if (typeof value === 'object') return value\n  console.warn(`Invalid widget value type: ${typeof value}`, value)\n  return undefined\n}\n\nfunction createSlotMetadata(\n  input: INodeInputSlot,\n  index: number,\n  link: LinkTopology | undefined,\n  graphRef: LGraph | null | undefined\n): WidgetSlotMetadata {\n  const originNode = link ? graphRef?.getNodeById(link.originNodeId) : null\n  return {\n    index,\n    linked: link !== undefined,\n    originNodeId: link?.originNodeId,\n    originOutputName: link\n      ? originNode?.outputs[link.originSlot]?.name\n      : undefined,\n    promoted: input.widgetId !== undefined,\n    type: String(input.type)\n  }\n}\n\nfunction getSlotWidgetName(input: INodeInputSlot): string | undefined {\n  return (\n    input.widget?.name ||\n    (input.widgetId !== undefined && input.name ? input.name : undefined)\n  )\n}\n\nfunction buildSlotMetadata(\n  inputs: INodeInputSlot[] | undefined,\n  graphRef: LGraph | null | undefined,\n  nodeId: NodeId\n): Map<string, WidgetSlotMetadata> {\n  const linkStore = useLinkStore()\n  const scope = graphRef ? graphScopeOf(graphRef) : undefined\n  const metadata = new Map<string, WidgetSlotMetadata>()\n  for (const [index, input] of inputs?.entries() ?? []) {\n    const link = scope\n      ? linkStore.getInputSlotLink(scope, nodeId, index)\n      : undefined\n    const widgetName = getSlotWidgetName(input)\n    if (!widgetName || metadata.has(widgetName)) continue\n    metadata.set(widgetName, createSlotMetadata(input, index, link, graphRef))\n  }\n  return metadata\n}\n\nfunction getHostNode(\n  rootGraph: LGraph | null,\n  nodeData: NodeState\n): LGraphNode | null {\n  if (!rootGraph) return null\n  return getNodeByState(rootGraph, nodeData)\n}\n\nfunction isWidgetVisible(\n  visibility: WidgetVisibilityComponent | undefined,\n  showAdvanced: boolean,\n  ignoreAdvanced = false\n): boolean {\n  if (!visibility) return true\n  return isWidgetVisibleOnSurface(visibility, 'vueNode', {\n    showAdvanced: showAdvanced || ignoreAdvanced\n  })\n}\n\nfunction hasWidgetError(\n  widget: { name: string; errorTarget?: WidgetErrorTarget },\n  nodeExecId: NodeExecutionId | null,\n  nodeErrors:\n    | { errors: { extra_info?: { input_name?: string } }[] }\n    | undefined,\n  executionErrorStore: ReturnType<typeof useExecutionErrorStore>,\n  missingModelStore: ReturnType<typeof useMissingModelStore>,\n  missingMediaStore: ReturnType<typeof useMissingMediaStore>\n): boolean {\n  const hasHostError =\n    !!nodeErrors?.errors.some(\n      (e) => e.extra_info?.input_name === widget.name\n    ) ||\n    (nodeExecId !== null &&\n      (missingModelStore.isWidgetMissingModel(nodeExecId, widget.name) ||\n        missingMediaStore.isWidgetMissingMedia(nodeExecId, widget.name)))\n  const target = widget.errorTarget\n  if (!target) return hasHostError\n\n  const sourceErrors = executionErrorStore.lastNodeErrors?.[target.executionId]\n  return (\n    hasHostError ||\n    !!sourceErrors?.errors.some(\n      (e) => e.extra_info?.input_name === target.widgetName\n    ) ||\n    missingModelStore.isWidgetMissingModel(\n      target.executionId,\n      target.widgetName\n    )\n  )\n}\n\nfunction createWidgetUpdateHandler({\n  id,\n  live,\n  errorTarget,\n  nodeExecId,\n  widgetName,\n  widgetOptions,\n  executionErrorStore,\n  widgetValueStore\n}: {\n  id: WidgetId\n  live?: { node: LGraphNode; widget: IBaseWidget }\n  errorTarget?: WidgetErrorTarget\n  nodeExecId: NodeExecutionId | null\n  widgetName: string\n  widgetOptions: IWidgetOptions\n  executionErrorStore: ReturnType<typeof useExecutionErrorStore>\n  widgetValueStore: ReturnType<typeof useWidgetValueStore>\n}): (newValue: WidgetValue) => void {\n  return (newValue: WidgetValue) => {\n    widgetValueStore.setValue(id, newValue)\n    if (live) {\n      const normalized = normalizeWidgetValue(newValue)\n      live.widget.value = normalized\n      live.widget.callback?.(normalized, app.canvas, live.node)\n      live.node.widgets?.forEach((w) => w.triggerDraw?.())\n    }\n\n    const options = { min: widgetOptions.min, max: widgetOptions.max }\n    if (errorTarget) {\n      executionErrorStore.clearWidgetRelatedErrors(\n        errorTarget.executionId,\n        errorTarget.widgetName,\n        errorTarget.widgetName,\n        newValue,\n        options\n      )\n    }\n    if (nodeExecId) {\n      executionErrorStore.clearWidgetRelatedErrors(\n        nodeExecId,\n        widgetName,\n        widgetName,\n        newValue,\n        options\n      )\n    }\n  }\n}\n\nfunction resolveWidgetIds(\n  graphId: string | undefined,\n  nodeId: NodeId,\n  explicitWidgetIds: readonly WidgetId[] | undefined,\n  widgetValueStore: ReturnType<typeof useWidgetValueStore>\n): readonly WidgetId[] {\n  if (explicitWidgetIds) return explicitWidgetIds\n  const bareNodeId = stripGraphPrefix(nodeId)\n  return graphId && bareNodeId\n    ? widgetValueStore.getNodeWidgetIds(graphId, bareNodeId)\n    : []\n}\n\ninterface LiveWidgetContext {\n  live?: { node: LGraphNode; widget: IBaseWidget }\n  errorTarget?: WidgetErrorTarget\n  controlWidget?: SafeControlWidget\n  sourceExecutionId?: NodeExecutionId\n}\n\n/**\n * Resolves the live litegraph widget (and, for promoted subgraph inputs, its\n * interior source) into the control widget and error target the render path\n * needs. Empty when the widget has no live counterpart (e.g. static previews).\n */\nfunction resolveLiveWidgetContext(\n  rootGraph: LGraph | null,\n  hostNode: LGraphNode | null,\n  liveWidget: IBaseWidget | undefined\n): LiveWidgetContext {\n  if (!hostNode || !liveWidget) return {}\n\n  const promotedSource = resolvePromotedWidgetSource(\n    rootGraph,\n    hostNode,\n    liveWidget\n  )\n  const errorTarget: WidgetErrorTarget | undefined =\n    promotedSource?.sourceExecutionId\n      ? {\n          executionId: promotedSource.sourceExecutionId,\n          widgetName: promotedSource.sourceWidgetName\n        }\n      : undefined\n  const controlWidget =\n    getControlWidget(liveWidget) ??\n    (promotedSource?.sourceWidget\n      ? getControlWidget(promotedSource.sourceWidget)\n      : undefined)\n\n  return {\n    live: { node: hostNode, widget: liveWidget },\n    errorTarget,\n    controlWidget,\n    sourceExecutionId: promotedSource?.sourceExecutionId\n  }\n}\n\n/**\n * A promoted widget renders the interior source node's identity, so consumers\n * that resolve a node from the locator reach the source rather than the host.\n */\nfunction widgetNodeLocatorId(\n  ctx: WidgetProcessingContext,\n  bareWidgetId: NodeId | null,\n  sourceExecutionId: NodeExecutionId | undefined\n): NodeLocatorId | undefined {\n  if (sourceExecutionId && ctx.rootGraph) {\n    const sourceLocator = executionIdToNodeLocatorId(\n      ctx.rootGraph,\n      sourceExecutionId\n    )\n    if (sourceLocator) return sourceLocator\n  }\n  if (!bareWidgetId || bareWidgetId.includes(':')) return undefined\n  return createNodeLocatorId(\n    subgraphIdFromState(ctx.nodeData, ctx.rootGraphId),\n    bareWidgetId\n  )\n}\n\ninterface WidgetProcessingContext {\n  nodeData: NodeState\n  showAdvanced: boolean\n  rootGraph: LGraph | null\n  /** Root graph id, known even before `app.isGraphReady`. */\n  rootGraphId: string | undefined\n  hostNode: LGraphNode | null\n  liveWidgets: Map<WidgetId, IBaseWidget>\n  slotMetadata: Map<string, WidgetSlotMetadata>\n  nodeExecId: NodeExecutionId | null\n  nodeErrors: Parameters<typeof hasWidgetError>[2]\n  widgetValueStore: ReturnType<typeof useWidgetValueStore>\n  executionErrorStore: ReturnType<typeof useExecutionErrorStore>\n  missingModelStore: ReturnType<typeof useMissingModelStore>\n  missingMediaStore: ReturnType<typeof useMissingMediaStore>\n  nodeDefStore: ReturnType<typeof useNodeDefStore>\n  ui: WidgetUiCallbacks\n}\n\nfunction processWidget(\n  id: WidgetId,\n  ctx: WidgetProcessingContext\n): ProcessedWidget | null {\n  const widgetState = ctx.widgetValueStore.getWidget(id)\n  if (!widgetState) return null\n\n  const liveWidget = ctx.liveWidgets.get(id)\n  const type = liveWidget?.type ?? widgetState.type\n  const renderState = ctx.widgetValueStore.getWidgetRenderState(id)\n  const visibility = ctx.widgetValueStore.getWidgetVisibility(id)\n  if (!type) return null\n  const options: IWidgetOptions = { ...widgetState.options }\n\n  const { live, errorTarget, controlWidget, sourceExecutionId } =\n    resolveLiveWidgetContext(ctx.rootGraph, ctx.hostNode, liveWidget)\n\n  const slotInfo = ctx.slotMetadata.get(widgetState.name)\n  const visible = isWidgetVisible(\n    visibility,\n    ctx.showAdvanced,\n    slotInfo?.linked || slotInfo?.promoted\n  )\n  const advanced = visibility\n    ? visibility.surfaces.vueNode === 'advanced'\n    : (options.advanced ?? false)\n  const isDisabled = slotInfo?.linked || widgetState.disabled\n  const widgetOptions = isDisabled ? { ...options, disabled: true } : options\n  const value = normalizeWidgetValue(widgetState.value)\n  const bareWidgetId = stripGraphPrefix(widgetState.nodeId)\n  const linkedUpstream: LinkedUpstreamInfo | undefined =\n    slotInfo?.linked && slotInfo.originNodeId\n      ? { nodeId: slotInfo.originNodeId, outputName: slotInfo.originOutputName }\n      : undefined\n\n  const updateHandler = createWidgetUpdateHandler({\n    id,\n    live,\n    errorTarget,\n    nodeExecId: ctx.nodeExecId,\n    widgetName: widgetState.name,\n    widgetOptions,\n    executionErrorStore: ctx.executionErrorStore,\n    widgetValueStore: ctx.widgetValueStore\n  })\n\n  const simplified: SimplifiedWidget = {\n    name: widgetState.name,\n    type,\n    value,\n    borderStyle: advanced\n      ? 'ring ring-component-node-widget-advanced'\n      : undefined,\n    callback: updateHandler,\n    controlWidget,\n    label: widgetState.label,\n    linkedUpstream,\n    nodeLocatorId: widgetNodeLocatorId(ctx, bareWidgetId, sourceExecutionId),\n    options: widgetOptions,\n    spec: live\n      ? ctx.nodeDefStore.getInputSpecForWidget(live.node, live.widget.name)\n      : undefined\n  }\n\n  const fullValue =\n    isTooltipValueType(type) && String(value).length > 10\n      ? String(value)\n      : undefined\n  const tooltipText = ctx.ui.getTooltipText(\n    { name: widgetState.name, tooltip: renderState?.tooltip },\n    fullValue\n  )\n  const handleContextMenu = (e: PointerEvent) => {\n    e.preventDefault()\n    e.stopPropagation()\n    ctx.ui.handleNodeRightClick(e, ctx.nodeData.id)\n    showNodeOptions(e, {\n      nodeId: ctx.nodeData.id,\n      widgetName: widgetState.name\n    })\n  }\n\n  return {\n    handleContextMenu,\n    hasLayoutSize: renderState?.hasLayoutSize ?? false,\n    hasError: hasWidgetError(\n      { name: widgetState.name, errorTarget },\n      ctx.nodeExecId,\n      ctx.nodeErrors,\n      ctx.executionErrorStore,\n      ctx.missingModelStore,\n      ctx.missingMediaStore\n    ),\n    widgetId: id,\n    renderKey: `${id}:${type}`,\n    vueComponent:\n      !renderState?.isDOMWidget && typeof liveWidget?.draw === 'function'\n        ? WidgetLegacy\n        : getComponent(type) ||\n          (renderState?.isDOMWidget ? WidgetDOM : WidgetLegacy),\n    simplified,\n    visible,\n    suppressedByConnection: visibility?.suppression.byConnection ?? false,\n    updateHandler,\n    tooltipText,\n    slotMetadata: slotInfo\n  }\n}\n\nexport function computeProcessedWidgets({\n  nodeData,\n  widgetIds,\n  graphId,\n  showAdvanced,\n  isGraphReady,\n  rootGraph,\n  ui\n}: ComputeProcessedWidgetsOptions): ProcessedWidget[] {\n  if (!nodeData) return []\n\n  const executionErrorStore = useExecutionErrorStore()\n  const missingModelStore = useMissingModelStore()\n  const missingMediaStore = useMissingMediaStore()\n  const widgetValueStore = useWidgetValueStore()\n  const nodeDefStore = useNodeDefStore()\n\n  const nodeExecId =\n    isGraphReady && rootGraph\n      ? executionIdFromState(rootGraph, nodeData)\n      : createNodeExecutionId([nodeData.id])\n\n  const hostNode = getHostNode(rootGraph, nodeData)\n  const liveWidgets = hostNode\n    ? mapLiveWidgetsById(hostNode)\n    : new Map<WidgetId, IBaseWidget>()\n  const orderedIds = resolveWidgetIds(\n    graphId,\n    nodeData.id,\n    widgetIds,\n    widgetValueStore\n  )\n  // Drop ids whose live widget is gone (e.g. removed directly on node.widgets);\n  // when the host node isn't resolvable yet, fall back to the stored order.\n  const ids = hostNode\n    ? orderedIds.filter((id) => liveWidgets.has(id))\n    : orderedIds\n  const graphRef = hostNode?.graph ?? rootGraph\n  const slotMetadata = buildSlotMetadata(\n    hostNode?.inputs,\n    graphRef,\n    nodeData.id\n  )\n  const ctx: WidgetProcessingContext = {\n    nodeData,\n    showAdvanced,\n    rootGraph,\n    rootGraphId: graphId,\n    hostNode,\n    liveWidgets,\n    slotMetadata,\n    nodeExecId,\n    nodeErrors: nodeExecId\n      ? executionErrorStore.lastNodeErrors?.[nodeExecId]\n      : undefined,\n    widgetValueStore,\n    executionErrorStore,\n    missingModelStore,\n    missingMediaStore,\n    nodeDefStore,\n    ui\n  }\n\n  return Array.from(new Set(ids))\n    .map((id) => processWidget(id, ctx))\n    .filter((widget): widget is ProcessedWidget => widget !== null)\n}\n","import { createSharedComposable } from '@vueuse/core'\n\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport { useNodeZIndex } from '@/renderer/extensions/vueNodes/composables/useNodeZIndex'\nimport type { NodeId } from '@/types/nodeId'\n\nfunction useNodeEventHandlersIndividual() {\n  const canvasStore = useCanvasStore()\n  const { shouldHandleNodePointerEvents } = useCanvasInteractions()\n  const { bringNodeToFront } = useNodeZIndex()\n\n  function getNode(nodeId: NodeId) {\n    return canvasStore.currentGraph?.getNodeById(nodeId) ?? undefined\n  }\n\n  /**\n   * Handle node collapse/expand state changes\n   * Uses LiteGraph's native collapse method for proper state management\n   */\n  function handleNodeCollapse(nodeId: NodeId, collapsed: boolean) {\n    if (!shouldHandleNodePointerEvents.value) return\n\n    const node = getNode(nodeId)\n    if (!node) return\n\n    // Use LiteGraph's collapse method if the state needs to change\n    const currentCollapsed = node.flags.collapsed ?? false\n    if (currentCollapsed !== collapsed) {\n      node.collapse()\n    }\n  }\n\n  /**\n   * Handle node title updates\n   * Updates the title in LiteGraph for persistence across sessions\n   */\n  function handleNodeTitleUpdate(nodeId: NodeId, newTitle: string) {\n    if (!shouldHandleNodePointerEvents.value) return\n\n    const node = getNode(nodeId)\n    if (!node) return\n\n    // Update the node title in LiteGraph for persistence\n    node.title = newTitle\n\n    // If this is a subgraph node, sync the subgraph name for breadcrumb reactivity\n    if (node.isSubgraphNode()) {\n      node.subgraph.name = newTitle\n    }\n  }\n\n  /**\n   * Handle node right-click context menu events\n   * Integrates with LiteGraph's context menu system\n   */\n  function handleNodeRightClick(event: MouseEvent, nodeId: NodeId) {\n    if (!shouldHandleNodePointerEvents.value) return\n\n    if (!canvasStore.canvas) return\n\n    const node = getNode(nodeId)\n    if (!node) return\n\n    event.preventDefault()\n\n    const raise = !node.selected && !node.flags.pinned\n    canvasStore.canvas.processSelect(node, event, true)\n    if (raise) bringNodeToFront(nodeId)\n  }\n\n  return {\n    handleNodeCollapse,\n    handleNodeTitleUpdate,\n    handleNodeRightClick\n  }\n}\n\nexport const useNodeEventHandlers = createSharedComposable(\n  useNodeEventHandlersIndividual\n)\n","import type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport { useMissingNodesErrorStore } from '@/platform/nodeReplacement/missingNodesErrorStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport type { NodeState } from '@/types/nodeState'\nimport { locatorIdFromState } from '@/utils/graphTraversalUtil'\nimport type { UUID } from '@/utils/uuid'\n\n/** Reads the error stores directly; `node.has_errors` is untracked and would latch. */\nexport function nodeHasError(\n  state: NodeState,\n  rootGraphId: UUID | undefined,\n  node: LGraphNode | null\n): boolean {\n  const executionErrorStore = useExecutionErrorStore()\n  const missingModelStore = useMissingModelStore()\n  const missingMediaStore = useMissingMediaStore()\n\n  const locatorId = locatorIdFromState(state, rootGraphId)\n  const hasNodeScopedError =\n    locatorId !== null &&\n    !!(\n      executionErrorStore.lastExecutionErrorNodeLocatorId === locatorId ||\n      executionErrorStore.getNodeErrors(locatorId) ||\n      missingModelStore.hasMissingModelOnNode(locatorId) ||\n      missingMediaStore.hasMissingMediaOnNode(locatorId)\n    )\n  if (hasNodeScopedError) return true\n\n  return (\n    node !== null &&\n    (executionErrorStore.isContainerWithInternalError(node) ||\n      useMissingNodesErrorStore().isContainerWithMissingNode(node) ||\n      missingModelStore.isContainerWithMissingModel(node) ||\n      missingMediaStore.isContainerWithMissingMedia(node))\n  )\n}\n\nexport function getNodeErrorSeverity(\n  state: NodeState,\n  rootGraphId: UUID | undefined,\n  node: LGraphNode | null\n): 'none' | 'missing' | 'error' {\n  const locator = locatorIdFromState(state, rootGraphId)\n  if (\n    locator &&\n    useExecutionErrorStore().blockingErrorNodeLocatorIds.has(locator)\n  ) {\n    return 'error'\n  }\n  return nodeHasError(state, rootGraphId, node) ? 'missing' : 'none'\n}\n","import { computed } from 'vue'\n\nimport { useAppMode } from '@/composables/useAppMode'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { LGraphEventMode } from '@/lib/litegraph/src/types/globalEnums'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type {\n  ProcessedWidget,\n  WidgetUiCallbacks\n} from '@/renderer/extensions/vueNodes/composables/processedWidgetRenderModel'\nimport { computeProcessedWidgets } from '@/renderer/extensions/vueNodes/composables/processedWidgetRenderModel'\nimport { useNodeEventHandlers } from '@/renderer/extensions/vueNodes/composables/useNodeEventHandlers'\nimport { useNodeTooltips } from '@/renderer/extensions/vueNodes/composables/useNodeTooltips'\nimport { nodeHasError } from '@/renderer/extensions/vueNodes/utils/nodeErrorState'\nimport { app } from '@/scripts/app'\nimport { nodeTypeValidForApp } from '@/stores/appModeStore'\nimport type { NodeState } from '@/types/nodeState'\nimport type { WidgetId } from '@/types/widgetId'\nimport { getNodeByState } from '@/utils/graphTraversalUtil'\n\nexport { computeProcessedWidgets }\nexport type { ProcessedWidget }\n\nfunction getHostNode(nodeData: NodeState): LGraphNode | null {\n  if (!app.isGraphReady) return null\n  return getNodeByState(app.rootGraph, nodeData)\n}\n\nexport function useProcessedWidgets(\n  nodeDataGetter: () => NodeState | undefined,\n  widgetIdsGetter: () => readonly WidgetId[] | undefined = () => undefined\n) {\n  const canvasStore = useCanvasStore()\n  const settingStore = useSettingStore()\n  const { isSelectInputsMode } = useAppMode()\n  const { handleNodeRightClick } = useNodeEventHandlers()\n\n  const nodeType = computed(() => nodeDataGetter()?.type || '')\n  const { getWidgetTooltip } = useNodeTooltips(nodeType)\n\n  const ui: WidgetUiCallbacks = {\n    getTooltipText: getWidgetTooltip,\n    handleNodeRightClick\n  }\n\n  const showAdvanced = computed(\n    () =>\n      nodeDataGetter()?.showAdvanced ||\n      settingStore.get('Comfy.Node.AlwaysShowAdvancedWidgets')\n  )\n\n  const canSelectInputs = computed(() => {\n    const nodeData = nodeDataGetter()\n    if (!nodeData) return false\n    return (\n      isSelectInputsMode.value &&\n      nodeData.mode === LGraphEventMode.ALWAYS &&\n      nodeTypeValidForApp(nodeData.type) &&\n      !nodeHasError(nodeData, canvasStore.rootGraphId, getHostNode(nodeData))\n    )\n  })\n\n  const processedWidgets = computed((): ProcessedWidget[] =>\n    computeProcessedWidgets({\n      nodeData: nodeDataGetter(),\n      widgetIds: widgetIdsGetter(),\n      graphId: canvasStore.rootGraphId,\n      showAdvanced: showAdvanced.value,\n      isGraphReady: app.isGraphReady,\n      rootGraph: app.isGraphReady ? app.rootGraph : null,\n      ui\n    })\n  )\n\n  return {\n    canSelectInputs,\n    nodeType,\n    processedWidgets\n  }\n}\n","<template>\n  <div v-if=\"renderError\" class=\"node-error p-2 text-sm text-red-500\">\n    {{ st('nodeErrors.widgets', 'Node Widgets Error') }}\n  </div>\n  <WidgetGrid\n    v-else\n    v-bind=\"widgetModel\"\n    :node-id=\"nodeData?.id\"\n    :class=\"\n      shouldHandleNodePointerEvents\n        ? 'pointer-events-auto'\n        : 'pointer-events-none'\n    \"\n    @pointerdown.capture=\"handleBringToFront\"\n    @pointerdown=\"handleWidgetPointerEvent\"\n    @pointermove=\"handleWidgetPointerEvent\"\n    @pointerup=\"handleWidgetPointerEvent\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onErrorCaptured, ref } from 'vue'\n\nimport type { ProcessedWidget } from '@/renderer/extensions/vueNodes/composables/useProcessedWidgets'\nimport type { NodeState } from '@/types/nodeState'\nimport type { WidgetId } from '@/types/widgetId'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { st } from '@/i18n'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport WidgetGrid from '@/renderer/extensions/vueNodes/components/WidgetGrid.vue'\nimport { useNodeZIndex } from '@/renderer/extensions/vueNodes/composables/useNodeZIndex'\nimport { useProcessedWidgets } from '@/renderer/extensions/vueNodes/composables/useProcessedWidgets'\n\ninterface NodeWidgetsProps {\n  nodeData?: NodeState\n  widgetIds?: readonly WidgetId[]\n  processedWidgetModel?: {\n    processedWidgets: ProcessedWidget[]\n    nodeType: string\n    canSelectInputs: boolean\n  }\n}\n\nconst { nodeData, widgetIds, processedWidgetModel } =\n  defineProps<NodeWidgetsProps>()\n\nconst { shouldHandleNodePointerEvents, forwardEventToCanvas } =\n  useCanvasInteractions()\nconst { bringNodeToFront } = useNodeZIndex()\n\nfunction handleWidgetPointerEvent(event: PointerEvent) {\n  if (shouldHandleNodePointerEvents.value) return\n  event.stopPropagation()\n  forwardEventToCanvas(event)\n}\n\nfunction handleBringToFront() {\n  if (nodeData?.id != null) {\n    bringNodeToFront(nodeData.id)\n  }\n}\n\n// Error boundary implementation\nconst renderError = ref<string | null>(null)\n\nconst { toastErrorHandler } = useErrorHandling()\n\nonErrorCaptured((error) => {\n  renderError.value = error.message\n  toastErrorHandler(error)\n  return false\n})\n\nconst fallbackWidgetModel = useProcessedWidgets(\n  () => nodeData,\n  () => widgetIds\n)\nconst widgetModel = computed(\n  () =>\n    processedWidgetModel ?? {\n      processedWidgets: fallbackWidgetModel.processedWidgets.value,\n      nodeType: fallbackWidgetModel.nodeType.value,\n      canSelectInputs: fallbackWidgetModel.canSelectInputs.value\n    }\n)\n</script>\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { NodeSlotType } from '@/lib/litegraph/src/types/globalEnums'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { useDialogService } from '@/services/dialogService'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\n\nexport type WidgetValue = boolean | number | string | object | undefined\n\nexport function getWidgetDefaultValue(\n  spec: InputSpec | undefined\n): WidgetValue {\n  if (!spec) return undefined\n\n  if (spec.default !== undefined) return spec.default as WidgetValue\n\n  switch (spec.type) {\n    case 'INT':\n    case 'FLOAT':\n      return 0\n    case 'BOOLEAN':\n      return false\n    case 'STRING':\n      return ''\n    default:\n      if (Array.isArray(spec.options) && spec.options.length > 0) {\n        return spec.options[0] as WidgetValue\n      }\n      return undefined\n  }\n}\n\n/**\n * Renames a widget: a label-only write across the widget, its store state, and\n * its backing input slot (matched by widgetId). Never touches the widget/input\n * name or widgetId — those are the stable identity a promoted input derives from.\n *\n * @param widget The widget to rename\n * @param node The node containing the widget\n * @param newLabel The new label for the widget (empty string or undefined to clear)\n * @returns true if the rename was successful, false otherwise\n */\nexport function renameWidget(\n  widget: IBaseWidget,\n  node: LGraphNode,\n  newLabel: string\n): boolean {\n  const label = newLabel || undefined\n  // TODO(ecs-widget-label-identity): the `input.label` write below is the interim\n  // on-ramp. End-state is an ECS WidgetIdentity.label serialized field (name =\n  // identity, label = display per ADR-SUBGRAPH-PROMOTION-0009) written via WidgetHandle.setLabel — the\n  // widget entity owns its label, so the socketless/DOM-widget case (no input slot\n  // to carry input.label, e.g. CLIPTextEncode `text`) is fixed by construction.\n  const input =\n    (widget.widgetId &&\n      node.inputs.find((inp) => inp.widgetId === widget.widgetId)) ||\n    node.inputs.find((inp) => inp.widget?.name === widget.name)\n  const widgetState = widget.widgetId\n    ? useWidgetValueStore().getWidget(widget.widgetId)\n    : undefined\n\n  widget.label = label\n  if (widgetState) widgetState.label = label\n  if (input) input.label = label\n\n  // Fires for all node types; listeners guard against non-subgraph nodes.\n  node.graph?.trigger('node:slot-label:changed', {\n    nodeId: node.id,\n    slotType: NodeSlotType.INPUT\n  })\n\n  return true\n}\n\nexport async function promptWidgetLabel(\n  widget: IBaseWidget,\n  t: (key: string) => string\n): Promise<string | null> {\n  return useDialogService().prompt({\n    title: t('g.rename'),\n    message: t('g.enterNewNamePrompt'),\n    defaultValue: widget.label,\n    placeholder: widget.name\n  })\n}\n\nexport async function promptRenameWidget(\n  widget: IBaseWidget,\n  node: LGraphNode,\n  t: (key: string) => string\n): Promise<string | null> {\n  const rawLabel = await promptWidgetLabel(widget, t)\n  if (rawLabel === null) return null\n\n  const normalizedLabel = rawLabel.trim()\n  if (!normalizedLabel) return null\n\n  if (!renameWidget(widget, node, normalizedLabel)) return null\n\n  widget.callback?.(widget.value)\n  useCanvasStore().canvas?.setDirty(true)\n  return normalizedLabel\n}\n","<script setup lang=\"ts\">\nimport { computed, provide, watchEffect } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport WidgetDescription from '@/components/builder/WidgetDescription.vue'\nimport { useAppModeWidgetResizing } from '@/components/builder/useAppModeWidgetResizing'\nimport { getLoaderDropIndicator } from '@/components/builder/useLoaderDropIndicator'\nimport { useResolvedSelectedInputs } from '@/components/builder/useResolvedSelectedInputs'\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { LGraphEventMode } from '@/lib/litegraph/src/types/globalEnums'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { deriveWidgetRenderState } from '@/lib/litegraph/src/utils/widget'\nimport type { WidgetId } from '@/types/widgetId'\nimport { useMaskEditor } from '@/composables/maskeditor/useMaskEditor'\nimport DropZone from '@/renderer/extensions/linearMode/DropZone.vue'\nimport NodeWidgets from '@/renderer/extensions/vueNodes/components/NodeWidgets.vue'\nimport { app } from '@/scripts/app'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useTemplateInputDownloadStore } from '@/stores/templateInputDownloadStore'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { HideLayoutFieldKey, WidgetHeightKey } from '@/types/widgetTypes'\nimport { UNASSIGNED_NODE_ID } from '@/types/nodeId'\nimport { promptRenameWidget } from '@/utils/widgetUtil'\n\ninterface WidgetEntry {\n  key: string\n  persistedHeight: number | undefined\n  nodeData: ReturnType<typeof nodeToNodeData>\n  widgetIds: readonly WidgetId[]\n  action: { widget: IBaseWidget; node: LGraphNode }\n  description?: string\n}\n\nconst { mobile = false, builderMode = false } = defineProps<{\n  mobile?: boolean\n  builderMode?: boolean\n}>()\n\nconst { t } = useI18n()\nconst executionErrorStore = useExecutionErrorStore()\nconst appModeStore = useAppModeStore()\nconst templateInputDownloadStore = useTemplateInputDownloadStore()\nconst widgetValueStore = useWidgetValueStore()\nconst linkStore = useLinkStore()\nconst maskEditor = useMaskEditor()\n\nconst { onPointerDown } = useAppModeWidgetResizing((widget, config) =>\n  appModeStore.updateInputConfig(widget, config)\n)\n\nprovide(HideLayoutFieldKey, true)\nprovide(WidgetHeightKey, mobile ? 'h-10' : 'h-7')\n\nconst resolvedInputs = useResolvedSelectedInputs()\n\nfunction ensureSelectedWidgetState(\n  widgetId: WidgetId,\n  widget: IBaseWidget\n): void {\n  if (widgetValueStore.getWidget(widgetId)) return\n\n  widgetValueStore.registerWidget(\n    widgetId,\n    {\n      type: widget.type,\n      value: widget.value,\n      options: widget.options,\n      label: widget.label,\n      serialize: widget.serialize,\n      disabled: widget.disabled\n    },\n    deriveWidgetRenderState(widget)\n  )\n}\n\nfunction isWidgetInputLinked(node: LGraphNode, widgetName: string): boolean {\n  const graph = node.graph\n  const slot = node.inputs?.findIndex((i) => i.widget?.name === widgetName)\n  if (!graph || slot === undefined || slot < 0) return false\n  return linkStore.isInputSlotConnected(graphScopeOf(graph), node.id, slot)\n}\n\nwatchEffect(() => {\n  for (const entry of resolvedInputs.value) {\n    if (entry.status !== 'resolved') continue\n    if (entry.node.mode !== LGraphEventMode.ALWAYS) continue\n    ensureSelectedWidgetState(entry.widgetId, entry.widget)\n  }\n})\n\nconst mappedSelections = computed((): WidgetEntry[] => {\n  return resolvedInputs.value.flatMap((entry) => {\n    if (entry.status !== 'resolved') return []\n    const { widgetId, node, widget, config } = entry\n    if (node.mode !== LGraphEventMode.ALWAYS) return []\n\n    if (isWidgetInputLinked(node, widget.name)) return []\n    const fullNodeData = nodeToNodeData(node, widgetId)\n\n    return [\n      {\n        key: widgetId,\n        persistedHeight: config?.height,\n        description: config?.description,\n        nodeData: fullNodeData,\n        widgetIds: [widgetId],\n        action: { widget, node }\n      }\n    ]\n  })\n})\n\nfunction getDropIndicator(node: LGraphNode, id: WidgetId) {\n  return getLoaderDropIndicator(node, id, {\n    mobile,\n    label: t,\n    onMaskEdit: maskEditor.openMaskEditor,\n    widgetValueStore,\n    previewRevision: templateInputDownloadStore.previewRevision\n  })\n}\n\nfunction nodeToNodeData(node: LGraphNode, id: WidgetId) {\n  const dropIndicator = getDropIndicator(node, id)\n\n  return {\n    ...node._state,\n    hasErrors: !!executionErrorStore.surfacedNodeErrors?.[node.id],\n    dropIndicator,\n    onDragDrop: node.onDragDrop,\n    onDragOver: node.onDragOver\n  }\n}\n\nasync function handleDragDrop() {\n  const onDragDrop = async (e: DragEvent) => {\n    for (const { nodeData } of mappedSelections.value)\n      if (nodeData?.onDragOver?.(e) && (await nodeData.onDragDrop?.(e)))\n        return true\n    return false\n  }\n\n  app.dragOverNode = { id: UNASSIGNED_NODE_ID, onDragDrop }\n}\n\ndefineExpose({ handleDragDrop })\n</script>\n<template>\n  <div\n    v-for=\"{\n      key,\n      persistedHeight,\n      nodeData,\n      widgetIds,\n      action,\n      description\n    } in mappedSelections\"\n    :key\n    :class=\"\n      cn(\n        builderMode &&\n          'draggable-item drag-handle pointer-events-auto relative cursor-grab [&.is-draggable]:cursor-grabbing'\n      )\n    \"\n    :aria-label=\"\n      builderMode\n        ? `${action.widget.label ?? action.widget.name} — ${action.node.title}`\n        : undefined\n    \"\n    :data-testid=\"builderMode ? 'builder-widget-item' : 'app-mode-widget-item'\"\n    :data-widget-key=\"key\"\n  >\n    <div\n      :class=\"\n        cn(\n          'mt-1.5 flex min-h-8 items-center gap-1 px-3',\n          builderMode && 'drag-handle'\n        )\n      \"\n    >\n      <span\n        :class=\"cn('truncate text-sm/8', builderMode && 'pointer-events-none')\"\n        data-testid=\"builder-widget-label\"\n      >\n        {{ action.widget.label || action.widget.name }}\n      </span>\n      <span\n        v-if=\"builderMode\"\n        class=\"pointer-events-none mx-1 min-w-10 flex-1 truncate text-right text-xs text-muted-foreground\"\n      >\n        {{ action.node.title }}\n      </span>\n      <div v-else class=\"flex-1\" />\n      <Menu\n        :class=\"cn('shrink-0', builderMode && 'pointer-events-auto')\"\n        :items=\"[\n          {\n            label: t('g.rename'),\n            // fallow-ignore-next-line css-token-drift\n            icon: 'icon-[lucide--pencil]',\n            command: () => promptRenameWidget(action.widget, action.node, t)\n          },\n          {\n            label: t('g.remove'),\n            icon: 'icon-[lucide--x]',\n            command: () => appModeStore.removeSelectedInput(action.widget)\n          }\n        ]\"\n      >\n        <template #trigger>\n          <Button\n            variant=\"textonly\"\n            size=\"icon\"\n            data-testid=\"widget-actions-menu\"\n          >\n            <!-- fallow-ignore-next-line css-token-drift -->\n            <i class=\"icon-[lucide--ellipsis]\" />\n          </Button>\n        </template>\n      </Menu>\n    </div>\n    <div\n      v-if=\"description || builderMode\"\n      data-testid=\"app-mode-widget-description\"\n      :class=\"\n        cn(\n          'h-5 px-5',\n          description ? 'text-muted-foreground' : 'text-muted-background'\n        )\n      \"\n    >\n      <WidgetDescription\n        :description\n        label-class=\"drag-handle\"\n        label-type=\"div\"\n        :disabled=\"!builderMode\"\n        :widget=\"action.widget\"\n      />\n    </div>\n    <div\n      :style=\"\n        persistedHeight\n          ? { '--persisted-height': `${persistedHeight}px` }\n          : undefined\n      \"\n      :class=\"\n        cn(\n          builderMode && 'pointer-events-none',\n          persistedHeight &&\n            '**:data-[slot=drop-zone-indicator]:h-(--persisted-height) [&_textarea]:h-(--persisted-height)'\n        )\n      \"\n      :inert=\"builderMode || undefined\"\n      @pointerdown.capture=\"(e) => onPointerDown(action.widget, e)\"\n    >\n      <DropZone\n        :on-drag-over=\"nodeData.onDragOver\"\n        :on-drag-drop=\"nodeData.onDragDrop\"\n        :drop-indicator=\"nodeData.dropIndicator\"\n        class=\"text-muted-foreground\"\n      >\n        <NodeWidgets\n          :node-data\n          :widget-ids\n          :class=\"\n            cn(\n              'gap-y-3 rounded-lg py-1 [&_textarea]:resize-y **:[.col-span-2]:grid-cols-1',\n              nodeData.hasErrors && 'ring-2 ring-node-stroke-error ring-inset'\n            )\n          \"\n        />\n      </DropZone>\n    </div>\n  </div>\n</template>\n","<script setup lang=\"ts\" generic=\"T\">\nimport { onBeforeUnmount, ref, useTemplateRef, watchPostEffect } from 'vue'\n\nimport { DraggableList } from '@/scripts/ui/draggableList'\n\nconst modelValue = defineModel<T[]>({ required: true })\nconst draggableList = ref<DraggableList>()\nconst draggableItems = useTemplateRef('draggableItems')\n\nwatchPostEffect(() => {\n  void modelValue.value.length\n  draggableList.value?.dispose()\n  if (!draggableItems.value?.children?.length) return\n  draggableList.value = new DraggableList(\n    draggableItems.value,\n    '.draggable-item'\n  )\n  draggableList.value.applyNewItemsOrder = function () {\n    if (!this.draggableItem) return\n    const { items, oldPosition } = this.getReorderedItems(this.draggableItem)\n    const newPosition = items.indexOf(this.draggableItem)\n    const itemList = modelValue.value\n    const [item] = itemList.splice(oldPosition, 1)\n    itemList.splice(newPosition, 0, item)\n    modelValue.value = [...itemList]\n  }\n})\n\nonBeforeUnmount(() => {\n  draggableList.value?.dispose()\n})\n</script>\n<template>\n  <div ref=\"draggableItems\" class=\"mt-0.5 space-y-0.5 px-2 pb-2\">\n    <slot\n      drag-class=\"draggable-item drag-handle cursor-grab [&.is-draggable]:cursor-grabbing\"\n    />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\n\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport EditableText from '@/components/common/EditableText.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\n\nconst subTitleTooltip = ref<string | null>(null)\nconst isEditing = ref(false)\n\nfunction isTruncated(e: MouseEvent): boolean {\n  const el = e.currentTarget as HTMLElement\n  return el.scrollWidth > el.clientWidth\n}\nconst { title, canRename, remove } = defineProps<{\n  title: string\n  subTitle?: string\n  canRename?: boolean\n  remove?: () => void\n}>()\n\nconst emit = defineEmits<{\n  rename: [newName: string]\n}>()\n\nfunction onEditComplete(newName: string) {\n  isEditing.value = false\n  const trimmed = newName.trim()\n  if (trimmed && trimmed !== title) emit('rename', trimmed)\n}\n\nconst entries = computed(() => {\n  const items = []\n  if (canRename)\n    items.push({\n      label: t('g.rename'),\n      command: () => (isEditing.value = true),\n      icon: 'icon-[lucide--pencil]'\n    })\n  if (remove)\n    items.push({\n      label: t('g.delete'),\n      command: remove,\n      icon: 'icon-[lucide--trash-2]'\n    })\n  return items\n})\n</script>\n<template>\n  <div\n    class=\"my-2 flex items-center-safe gap-2 rounded-lg p-2\"\n    data-testid=\"builder-io-item\"\n  >\n    <div class=\"drag-handle mr-auto flex w-full min-w-0 flex-col gap-1\">\n      <EditableText\n        :model-value=\"title\"\n        :is-editing=\"isEditing\"\n        :input-attrs=\"{ class: 'p-1' }\"\n        :class=\"\n          cn(\n            'drag-handle h-5 text-sm',\n            isEditing && 'relative -top-0.5 -left-1 -mt-px mb-px -ml-px',\n            !isEditing && 'truncate'\n          )\n        \"\n        data-testid=\"builder-io-item-title\"\n        label-class=\"drag-handle\"\n        label-type=\"div\"\n        @dblclick=\"canRename && (isEditing = true)\"\n        @edit=\"onEditComplete\"\n        @cancel=\"isEditing = false\"\n      />\n      <Tooltip :disabled=\"!subTitleTooltip\">\n        <TooltipTrigger as-child>\n          <div\n            class=\"drag-handle truncate text-xs text-muted-foreground\"\n            data-testid=\"builder-io-item-subtitle\"\n            @mouseenter=\"\n              subTitleTooltip = isTruncated($event) ? (subTitle ?? null) : null\n            \"\n            v-text=\"subTitle\"\n          />\n        </TooltipTrigger>\n        <TooltipContent side=\"left\">{{ subTitleTooltip }}</TooltipContent>\n      </Tooltip>\n    </div>\n    <Menu\n      :items=\"entries\"\n      @close-auto-focus=\"isEditing && $event.preventDefault()\"\n    >\n      <template #trigger>\n        <Button\n          variant=\"muted-textonly\"\n          data-testid=\"widget-actions-menu\"\n          icon=\"icon-[lucide--ellipsis]\"\n          :aria-label=\"$t('g.more')\"\n        />\n      </template>\n    </Menu>\n  </div>\n</template>\n","import { useDebounceFn, useEventListener } from '@vueuse/core'\nimport { ref } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\nimport { isMiddleButtonEvent } from '@/base/pointerUtils'\n\ninterface TransformSettlingOptions {\n  /**\n   * Delay in ms before transform is considered \"settled\" after last interaction\n   * @default 256\n   */\n  settleDelay?: number\n  /**\n   * Whether to use passive event listeners (better performance but can't preventDefault)\n   * @default true\n   */\n  passive?: boolean\n}\n\n/**\n * Tracks when canvas transforms (zoom or pan) are actively changing vs settled.\n *\n * This composable helps optimize rendering quality during transform interactions.\n * When the user is actively zooming or panning, we can reduce rendering quality\n * for better performance. Once the transform \"settles\" (stops changing), we can\n * trigger high-quality re-rasterization.\n *\n * The settling concept prevents constant quality switching during interactions\n * by waiting for a period of inactivity before considering the transform complete.\n *\n * Uses VueUse's useEventListener for automatic cleanup and useDebounceFn for\n * efficient settle detection.\n *\n * @example\n * ```ts\n * const { isTransforming } = useTransformSettling(canvasRef, {\n *   settleDelay: 200\n * })\n *\n * // Use in CSS classes or rendering logic\n * const cssClass = computed(() => ({\n *   'low-quality': isTransforming.value,\n *   'high-quality': !isTransforming.value\n * }))\n * ```\n */\nexport function useTransformSettling(\n  target: MaybeRefOrGetter<HTMLElement | null | undefined>,\n  options: TransformSettlingOptions = {}\n) {\n  const { settleDelay = 256, passive = true } = options\n\n  const isTransforming = ref(false)\n\n  const markTransformSettled = useDebounceFn(() => {\n    isTransforming.value = false\n  }, settleDelay)\n\n  function markInteracting() {\n    isTransforming.value = true\n    void markTransformSettled()\n  }\n\n  const eventOptions = { capture: true, passive }\n\n  useEventListener(target, 'wheel', markInteracting, eventOptions)\n  usePointerDrag(target, markInteracting, eventOptions)\n\n  return {\n    isTransforming\n  }\n}\n\n/**\n * Calls `onDrag` on each pointermove while a pointer is held down.\n */\nfunction usePointerDrag(\n  target: MaybeRefOrGetter<HTMLElement | null | undefined>,\n  onDrag: () => void,\n  eventOptions: AddEventListenerOptions\n) {\n  /** Number of active pointers (supports multi-touch correctly). */\n  const pointerCount = ref(0)\n\n  useEventListener(\n    target,\n    'pointerdown',\n    (e: PointerEvent) => {\n      // Only primary (0) and middle (1) buttons trigger canvas pan.\n      if (e.button === 0 || isMiddleButtonEvent(e)) pointerCount.value++\n    },\n    eventOptions\n  )\n\n  useEventListener(\n    target,\n    'pointermove',\n    () => {\n      if (pointerCount.value > 0) onDrag()\n    },\n    eventOptions\n  )\n\n  // Listen on window so the release is caught even if the pointer\n  // leaves the canvas before the button is released.\n  useEventListener(\n    window,\n    'pointerup',\n    () => {\n      if (pointerCount.value > 0) pointerCount.value--\n    },\n    eventOptions\n  )\n\n  useEventListener(\n    window,\n    'pointercancel',\n    () => {\n      if (pointerCount.value > 0) pointerCount.value--\n    },\n    eventOptions\n  )\n}\n","<template>\n  <div\n    ref=\"transformPaneRef\"\n    data-testid=\"transform-pane\"\n    class=\"ph-no-capture pointer-events-none absolute inset-0 size-full will-change-auto\"\n  >\n    <TooltipProvider\n      :delay-duration=\"settingStore.get('LiteGraph.Node.TooltipDelay')\"\n      :skip-delay-duration=\"0\"\n    >\n      <slot />\n    </TooltipProvider>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useRafFn } from '@vueuse/core'\nimport { computed, useTemplateRef, watch } from 'vue'\n\nimport TooltipProvider from '@/components/ui/tooltip/TooltipProvider.vue'\nimport type { LGraphCanvas } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTransformSettling } from '@/renderer/core/layout/transform/useTransformSettling'\nimport { useTransformState } from '@/renderer/core/layout/transform/useTransformState'\n\ninterface TransformPaneProps {\n  canvas?: LGraphCanvas\n}\n\nconst props = defineProps<TransformPaneProps>()\n\nconst settingStore = useSettingStore()\n\nconst { transformStyle, syncWithCanvas } = useTransformState()\n\nconst canvasElement = computed(() => props.canvas?.canvas)\nconst { isTransforming: isInteracting } = useTransformSettling(canvasElement, {\n  settleDelay: 256\n})\n\nconst transformPaneRef = useTemplateRef('transformPaneRef')\n\n/**\n * Apply transform style and will-change class via direct DOM mutation\n * instead of reactive template bindings (:style / :class).\n *\n * These values change every animation frame during zoom or pan.\n * If they were bound in the template, Vue would diff the entire\n * TransformPane vnode—including all child node slots—on every frame,\n * causing expensive vdom patch work across the full node list.\n * Mutating the DOM directly limits the update to a single element.\n */\n\nwatch([transformStyle, transformPaneRef], ([newStyle, el]) => {\n  if (el) {\n    Object.assign(el.style, newStyle)\n  }\n})\nwatch([isInteracting, transformPaneRef], ([interacting, el]) => {\n  if (el) {\n    el.classList.toggle('will-change-transform', interacting)\n    el.classList.toggle('will-change-auto', !interacting)\n  }\n})\n\nuseRafFn(\n  () => {\n    if (!props.canvas) {\n      return\n    }\n    syncWithCanvas(props.canvas)\n  },\n  { immediate: true }\n)\n</script>\n","<script setup lang=\"ts\">\nimport { remove } from 'es-toolkit'\nimport { computed, ref, toValue } from 'vue'\nimport type { MaybeRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport AppModeWidgetList from '@/components/builder/AppModeWidgetList.vue'\nimport DraggableList from '@/components/common/DraggableList.vue'\nimport IoItem from '@/components/builder/IoItem.vue'\nimport PropertiesAccordionItem from '@/components/rightSidePanel/layout/PropertiesAccordionItem.vue'\nimport { useResolvedSelectedInputs } from '@/components/builder/useResolvedSelectedInputs'\nimport type { ResolvedSelection } from '@/components/builder/useResolvedSelectedInputs'\nimport type { WidgetId } from '@/types/widgetId'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { LGraphCanvas } from '@/lib/litegraph/src/LGraphCanvas'\nimport type { NodeId } from '@/types/nodeId'\nimport {\n  LGraphEventMode,\n  TitleMode\n} from '@/lib/litegraph/src/types/globalEnums'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { BaseWidget } from '@/lib/litegraph/src/widgets/BaseWidget'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport TransformPane from '@/renderer/core/layout/transform/TransformPane.vue'\nimport { app } from '@/scripts/app'\nimport { DOMWidgetImpl } from '@/scripts/domWidget'\nimport { renameWidget } from '@/utils/widgetUtil'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { nodeTypeValidForApp, useAppModeStore } from '@/stores/appModeStore'\nimport { deriveWidgetVisibility } from '@/types/widgetVisibility'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ntype BoundStyle = { top: string; left: string; width: string; height: string }\n\nconst appModeStore = useAppModeStore()\nconst canvasInteractions = useCanvasInteractions()\nconst canvasStore = useCanvasStore()\nconst settingStore = useSettingStore()\nconst workflowStore = useWorkflowStore()\nconst { t } = useI18n()\nconst canvas: LGraphCanvas = canvasStore.getCanvas()\n\nconst { isSelectMode, isSelectInputsMode, isSelectOutputsMode, isArrangeMode } =\n  useAppMode()\nconst hoveringSelectable = ref(false)\n\nworkflowStore.activeWorkflow?.changeTracker?.reset()\n\nconst resolvedInputs = useResolvedSelectedInputs()\n\nconst outputsWithState = computed<[NodeId, string][]>(() =>\n  appModeStore.selectedOutputs.map((nodeId) => [\n    nodeId,\n    app.rootGraph.getNodeById(nodeId)?.title ?? String(nodeId)\n  ])\n)\n\nfunction getHovered(\n  e: MouseEvent\n): undefined | [LGraphNode, undefined] | [LGraphNode, IBaseWidget] {\n  const { graph } = canvas\n  if (!canvas || !graph) return\n\n  if (settingStore.get('Comfy.VueNodes.Enabled')) return undefined\n  if (!e) return\n\n  canvas.adjustMouseEvent(e)\n  const node = graph.getNodeOnPos(e.canvasX, e.canvasY)\n  if (!node) return\n\n  const widget = node.getWidgetOnPos(e.canvasX, e.canvasY, false)\n\n  if (widget || node.constructor.nodeData?.output_node) return [node, widget]\n}\n\nfunction getNodeBounding(nodeId: NodeId) {\n  if (settingStore.get('Comfy.VueNodes.Enabled')) return undefined\n  const node = app.rootGraph.getNodeById(nodeId)\n  if (!node) return\n\n  const titleOffset =\n    node.title_mode === TitleMode.NORMAL_TITLE ? LiteGraph.NODE_TITLE_HEIGHT : 0\n\n  return {\n    width: `${node.size[0]}px`,\n    height: `${node.size[1] + titleOffset}px`,\n    left: `${node.pos[0]}px`,\n    top: `${node.pos[1] - titleOffset}px`\n  }\n}\n\nfunction getWidgetBounding(entry: ResolvedSelection): BoundStyle | undefined {\n  if (settingStore.get('Comfy.VueNodes.Enabled')) return undefined\n  if (entry.status !== 'resolved') return undefined\n  const { node, widget } = entry\n\n  const margin = widget instanceof DOMWidgetImpl ? widget.margin : undefined\n  const marginX = margin ?? BaseWidget.margin\n  const height =\n    (widget.computedHeight !== undefined\n      ? widget.computedHeight - 4\n      : LiteGraph.NODE_WIDGET_HEIGHT) - (margin ? 2 * margin - 4 : 0)\n  return {\n    width: `${node.size[0] - marginX * 2}px`,\n    height: `${height}px`,\n    left: `${node.pos[0] + marginX}px`,\n    top: `${node.pos[1] + widget.y + (margin ?? 0)}px`\n  }\n}\n\nfunction removeSelectedWidgetId(widgetId: WidgetId): void {\n  const index = appModeStore.selectedInputs.findIndex(([id]) => id === widgetId)\n  if (index !== -1) appModeStore.selectedInputs.splice(index, 1)\n}\n\nfunction handleDown(e: MouseEvent) {\n  const [node] = getHovered(e) ?? []\n  if (!node || e.button > 0) canvasInteractions.forwardEventToCanvas(e)\n}\nfunction handleClick(e: MouseEvent) {\n  const [node, widget] = getHovered(e) ?? []\n  if (\n    node?.mode !== LGraphEventMode.ALWAYS ||\n    !nodeTypeValidForApp(node.type) ||\n    node.has_errors\n  )\n    return canvasInteractions.forwardEventToCanvas(e)\n\n  if (!widget) {\n    if (!isSelectOutputsMode.value) return\n    if (!node.constructor.nodeData?.output_node)\n      return canvasInteractions.forwardEventToCanvas(e)\n    const index = appModeStore.selectedOutputs.findIndex((id) => id === node.id)\n    if (index === -1) appModeStore.selectedOutputs.push(node.id)\n    else appModeStore.selectedOutputs.splice(index, 1)\n    return\n  }\n  const visibility = widget.visibility ?? deriveWidgetVisibility(widget)\n  if (!isSelectInputsMode.value || visibility.surfaces.panel === 'never') return\n\n  const widgetId = widget.widgetId\n  if (!widgetId) return\n  const index = appModeStore.selectedInputs.findIndex(([id]) => id === widgetId)\n  if (index === -1)\n    appModeStore.selectedInputs.push([widgetId, widget.name, undefined])\n  else appModeStore.selectedInputs.splice(index, 1)\n}\n\nfunction nodeToDisplayTuple(\n  n: LGraphNode\n): [NodeId, MaybeRef<BoundStyle> | undefined, boolean] {\n  return [\n    n.id,\n    getNodeBounding(n.id),\n    appModeStore.selectedOutputs.some((id) => n.id === id)\n  ]\n}\n\nconst renderedOutputs = computed(() => {\n  void appModeStore.selectedOutputs.length\n  return canvas\n    .graph!.nodes.filter(\n      (n) =>\n        n.constructor.nodeData?.output_node &&\n        n.mode === LGraphEventMode.ALWAYS &&\n        !n.has_errors\n    )\n    .map(nodeToDisplayTuple)\n})\nconst renderedInputs = computed<[string, MaybeRef<BoundStyle> | undefined][]>(\n  () =>\n    resolvedInputs.value.map(\n      (entry) =>\n        [entry.widgetId, getWidgetBounding(entry)] as [\n          string,\n          MaybeRef<BoundStyle> | undefined\n        ]\n    )\n)\n</script>\n<template>\n  <div class=\"flex h-full flex-col\">\n    <div\n      class=\"flex h-12 items-center border-b border-border-subtle px-4 font-bold\"\n    >\n      {{\n        isArrangeMode ? t('nodeHelpPage.inputs') : t('linearMode.builder.title')\n      }}\n    </div>\n    <div class=\"flex min-h-0 flex-1 flex-col overflow-y-auto\">\n      <DraggableList\n        v-if=\"isArrangeMode\"\n        v-model=\"appModeStore.selectedInputs\"\n        class=\"overflow-x-clip\"\n      >\n        <AppModeWidgetList builder-mode />\n      </DraggableList>\n      <PropertiesAccordionItem\n        v-if=\"isSelectInputsMode\"\n        :label=\"t('nodeHelpPage.inputs')\"\n        enable-empty-state\n        :disabled=\"!appModeStore.selectedInputs.length\"\n        :tooltip=\"`${t('linearMode.builder.inputsDesc')}\\n${t('linearMode.builder.inputsExample')}`\"\n      >\n        <template #label>\n          <div class=\"flex gap-3\">\n            {{ t('nodeHelpPage.inputs') }}\n            <i class=\"icon-[lucide--info] bg-muted-foreground\" />\n          </div>\n        </template>\n        <template #empty>\n          <div\n            class=\"p-4 text-muted-foreground\"\n            v-text=\"t('linearMode.builder.promptAddInputs')\"\n          />\n        </template>\n        <DraggableList\n          v-slot=\"{ dragClass }\"\n          v-model=\"appModeStore.selectedInputs\"\n        >\n          <template v-for=\"entry in resolvedInputs\" :key=\"entry.widgetId\">\n            <IoItem\n              v-if=\"entry.status === 'resolved'\"\n              :class=\"\n                cn(dragClass, 'my-2 rounded-lg bg-primary-background/30 p-2')\n              \"\n              :title=\"entry.widget.label ?? entry.displayName\"\n              :sub-title=\"entry.node.title\"\n              can-rename\n              :remove=\"() => appModeStore.removeSelectedInput(entry.widget)\"\n              @rename=\"renameWidget(entry.widget, entry.node, $event)\"\n            />\n            <IoItem\n              v-else\n              :class=\"\n                cn(dragClass, 'my-2 rounded-lg bg-primary-background/30 p-2')\n              \"\n              :title=\"entry.displayName\"\n              :sub-title=\"t('linearMode.builder.unknownWidget')\"\n              :remove=\"() => removeSelectedWidgetId(entry.widgetId)\"\n            />\n          </template>\n        </DraggableList>\n      </PropertiesAccordionItem>\n      <div\n        v-if=\"isSelectInputsMode && !appModeStore.selectedInputs.length\"\n        class=\"m-4 flex flex-1 items-center justify-center rounded-lg border-2 border-dashed border-primary-background bg-primary-background/20 text-center text-sm text-primary-background\"\n      >\n        {{ t('linearMode.builder.inputPlaceholder') }}\n      </div>\n      <PropertiesAccordionItem\n        v-if=\"isSelectOutputsMode\"\n        :label=\"t('nodeHelpPage.outputs')\"\n        enable-empty-state\n        :disabled=\"!appModeStore.selectedOutputs.length\"\n        :tooltip=\"`${t('linearMode.builder.outputsDesc')}\\n${t('linearMode.builder.outputsExample')}`\"\n      >\n        <template #label>\n          <div class=\"flex gap-3\">\n            {{ t('nodeHelpPage.outputs') }}\n            <i class=\"icon-[lucide--info] bg-muted-foreground\" />\n          </div>\n        </template>\n        <template #empty>\n          <div\n            class=\"p-4 text-muted-foreground\"\n            v-text=\"t('linearMode.builder.promptAddOutputs')\"\n          />\n        </template>\n        <DraggableList\n          v-slot=\"{ dragClass }\"\n          v-model=\"appModeStore.selectedOutputs\"\n        >\n          <IoItem\n            v-for=\"([key, title], index) in outputsWithState\"\n            :key\n            :class=\"\n              cn(\n                dragClass,\n                'my-2 rounded-lg bg-warning-background/40 p-2',\n                index === 0 && 'ring-2 ring-warning-background'\n              )\n            \"\n            :title\n            :sub-title=\"String(key)\"\n            :remove=\"\n              () => remove(appModeStore.selectedOutputs, (k) => k === key)\n            \"\n          />\n        </DraggableList>\n      </PropertiesAccordionItem>\n      <div\n        v-if=\"isSelectOutputsMode && !appModeStore.selectedOutputs.length\"\n        data-testid=\"builder-output-placeholder\"\n        class=\"m-4 flex flex-1 flex-col items-center justify-center gap-1 rounded-lg border-2 border-dashed border-warning-background bg-warning-background/20 text-center text-sm text-warning-background\"\n      >\n        {{ t('linearMode.builder.outputPlaceholder') }}\n        <span class=\"font-bold\">\n          {{ t('linearMode.builder.outputRequiredPlaceholder') }}\n        </span>\n      </div>\n    </div>\n  </div>\n\n  <Teleport\n    v-if=\"isSelectMode && !settingStore.get('Comfy.VueNodes.Enabled')\"\n    to=\"body\"\n  >\n    <div\n      data-testid=\"builder-selection-overlay\"\n      :class=\"\n        cn(\n          'pointer-events-auto absolute size-full',\n          hoveringSelectable ? 'cursor-pointer' : 'cursor-grab'\n        )\n      \"\n      @pointerdown=\"handleDown\"\n      @pointermove=\"hoveringSelectable = !!getHovered($event)\"\n      @click=\"handleClick\"\n      @wheel=\"canvasInteractions.forwardEventToCanvas\"\n    >\n      <TransformPane :canvas=\"canvasStore.getCanvas()\">\n        <template v-if=\"isSelectInputsMode\">\n          <div\n            v-for=\"[key, style] in renderedInputs\"\n            :key\n            :style=\"toValue(style)\"\n            class=\"fixed rounded-lg bg-primary-background/30\"\n          />\n        </template>\n        <template v-else>\n          <div\n            v-for=\"[key, style, isSelected] in renderedOutputs\"\n            :key\n            :style=\"toValue(style)\"\n            :class=\"\n              cn(\n                'fixed rounded-2xl ring-5 ring-warning-background',\n                !isSelected && 'ring-warning-background/50'\n              )\n            \"\n          >\n            <div class=\"absolute top-0 right-0 size-8\">\n              <div\n                v-if=\"isSelected\"\n                class=\"pointer-events-auto absolute -top-1/2 -right-1/2 size-full cursor-pointer rounded-lg bg-warning-background p-2\"\n                @click.stop=\"\n                  remove(appModeStore.selectedOutputs, (k) => k === key)\n                \"\n                @pointerdown.stop\n              >\n                <i class=\"icon-[lucide--check] size-full bg-base-foreground\" />\n              </div>\n              <div\n                v-else\n                class=\"pointer-events-auto absolute -top-1/2 -right-1/2 size-full cursor-pointer rounded-lg bg-component-node-background ring-4 ring-warning-background/50 ring-inset\"\n                @click.stop=\"appModeStore.selectedOutputs.push(key)\"\n                @pointerdown.stop\n              />\n            </div>\n          </div>\n        </template>\n      </TransformPane>\n    </div>\n  </Teleport>\n</template>\n","<template>\n  <div\n    role=\"status\"\n    :data-position=\"position\"\n    :class=\"\n      cn(\n        'pointer-events-auto absolute z-1000 flex max-h-96 w-96 flex-col rounded-lg border border-border-default bg-base-background shadow-interface',\n        position === 'bottom-left' && 'bottom-4 left-4',\n        position === 'bottom-right' && 'right-4 bottom-4'\n      )\n    \"\n  >\n    <div class=\"flex min-h-0 flex-1 flex-col gap-4 p-4\">\n      <div class=\"flex items-center gap-4\">\n        <div\n          v-if=\"icon\"\n          class=\"flex shrink-0 items-center justify-center rounded-lg bg-primary-background-hover p-3\"\n        >\n          <i :class=\"cn('size-4 text-white', icon)\" />\n        </div>\n        <div class=\"flex flex-1 flex-col gap-1\">\n          <div class=\"text-sm leading-[1.429] font-normal text-base-foreground\">\n            {{ title }}\n          </div>\n          <div\n            v-if=\"subtitle\"\n            class=\"text-sm leading-[1.21] font-normal text-muted-foreground\"\n          >\n            {{ subtitle }}\n          </div>\n        </div>\n        <Button\n          v-if=\"showClose\"\n          class=\"size-6 shrink-0 self-start\"\n          size=\"icon-sm\"\n          variant=\"muted-textonly\"\n          :aria-label=\"$t('g.close')\"\n          @click=\"emit('close')\"\n        >\n          <i class=\"icon-[lucide--x] size-3.5\" />\n        </Button>\n      </div>\n\n      <div\n        v-if=\"$slots.default\"\n        class=\"min-h-0 flex-1 overflow-y-auto text-sm text-muted-foreground\"\n      >\n        <slot />\n      </div>\n    </div>\n\n    <div\n      v-if=\"$slots['footer-start'] || $slots['footer-end']\"\n      class=\"flex items-center justify-between px-4 pb-4\"\n    >\n      <div>\n        <slot name=\"footer-start\" />\n      </div>\n      <div class=\"flex items-center gap-4\">\n        <slot name=\"footer-end\" />\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  icon,\n  title,\n  subtitle,\n  showClose = false,\n  position = 'bottom-left'\n} = defineProps<{\n  icon?: string\n  title: string\n  subtitle?: string\n  showClose?: boolean\n  position?: 'bottom-left' | 'bottom-right'\n}>()\n\nconst emit = defineEmits<{\n  close: []\n}>()\n</script>\n","<template>\n  <NotificationPopup\n    v-if=\"appModeStore.showVueNodeSwitchPopup && !canvasStore.isPickingNodes\"\n    data-testid=\"linear-vue-node-switch-popup\"\n    :title=\"$t('appBuilder.vueNodeSwitch.title')\"\n    show-close\n    position=\"bottom-left\"\n    @close=\"dismiss\"\n  >\n    {{ $t('appBuilder.vueNodeSwitch.content') }}\n\n    <template #footer-start>\n      <label\n        class=\"flex cursor-pointer items-center gap-2 text-sm text-muted-foreground\"\n      >\n        <input\n          v-model=\"dontShowAgain\"\n          type=\"checkbox\"\n          data-testid=\"linear-vue-node-switch-dont-show-again\"\n          class=\"accent-primary-background\"\n        />\n        {{ $t('appBuilder.vueNodeSwitch.dontShowAgain') }}\n      </label>\n    </template>\n\n    <template #footer-end>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        data-testid=\"linear-vue-node-switch-dismiss\"\n        class=\"font-normal\"\n        @click=\"dismiss\"\n      >\n        {{ $t('appBuilder.vueNodeSwitch.dismiss') }}\n      </Button>\n    </template>\n  </NotificationPopup>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\n\nimport NotificationPopup from '@/components/common/NotificationPopup.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useAppModeStore } from '@/stores/appModeStore'\n\nconst appModeStore = useAppModeStore()\n// Node selection mode keeps the canvas clear of everything but the graph and\n// its own banner, so this popup steps aside for the duration and returns after.\nconst canvasStore = useCanvasStore()\nconst settingStore = useSettingStore()\nconst dontShowAgain = ref(false)\n\nfunction dismiss() {\n  if (dontShowAgain.value) {\n    void settingStore.set('Comfy.AppBuilder.VueNodeSwitchDismissed', true)\n  }\n  appModeStore.showVueNodeSwitchPopup = false\n}\n</script>\n","import type { CSSProperties, Ref } from 'vue'\nimport { ref, watch } from 'vue'\n\nimport { useCanvasPositionConversion } from '@/composables/element/useCanvasPositionConversion'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { PositionConfig } from '@/types/positionConfig'\n\ninterface UseAbsolutePositionReturn {\n  style: Ref<CSSProperties>\n  updatePosition: (config: PositionConfig) => void\n}\n\nexport function useAbsolutePosition(\n  options: { useTransform?: boolean } = {}\n): UseAbsolutePositionReturn {\n  const { useTransform = false } = options\n\n  const canvasStore = useCanvasStore()\n  const lgCanvas = canvasStore.getCanvas()\n  const { canvasPosToClientPos, update: updateCanvasPosition } =\n    useCanvasPositionConversion(lgCanvas.canvas, lgCanvas)\n\n  const settingStore = useSettingStore()\n  watch(\n    [\n      () => settingStore.get('Comfy.Sidebar.Location'),\n      () => settingStore.get('Comfy.Sidebar.Size'),\n      () => settingStore.get('Comfy.UseNewMenu')\n    ],\n    () => updateCanvasPosition(),\n    { flush: 'post' }\n  )\n\n  const style = ref<CSSProperties>({})\n\n  /**\n   * Compute the style of the element based on the position and size.\n   *\n   * @param position\n   */\n  const computeStyle = (position: PositionConfig): CSSProperties => {\n    const { pos, size, scale = lgCanvas.ds.scale } = position\n    const [left, top] = canvasPosToClientPos(pos)\n    const [width, height] = size\n\n    return useTransform\n      ? {\n          position: 'fixed',\n          transformOrigin: '0 0',\n          transform: `scale(${scale})`,\n          left: `${left}px`,\n          top: `${top}px`,\n          width: `${width}px`,\n          height: `${height}px`\n        }\n      : {\n          position: 'fixed',\n          left: `${left}px`,\n          top: `${top}px`,\n          width: `${width * scale}px`,\n          height: `${height * scale}px`\n        }\n  }\n\n  /**\n   * Update the position of the element on the litegraph canvas.\n   *\n   * @param config\n   */\n  const updatePosition = (config: PositionConfig) => {\n    style.value = computeStyle(config)\n  }\n\n  return {\n    style,\n    updatePosition\n  }\n}\n","import type { CSSProperties, Ref } from 'vue'\nimport { ref } from 'vue'\n\ninterface Rect {\n  x: number\n  y: number\n  width: number\n  height: number\n}\n\n/**\n * Finds the intersection between two rectangles\n */\nfunction intersect(a: Rect, b: Rect): [number, number, number, number] | null {\n  const x1 = Math.max(a.x, b.x)\n  const y1 = Math.max(a.y, b.y)\n  const x2 = Math.min(a.x + a.width, b.x + b.width)\n  const y2 = Math.min(a.y + a.height, b.y + b.height)\n\n  if (x1 >= x2 || y1 >= y2) {\n    return null\n  }\n\n  return [x1, y1, x2 - x1, y2 - y1]\n}\n\ninterface ClippingOptions {\n  margin?: number\n}\n\ninterface UseDomClippingReturn {\n  style: Ref<CSSProperties>\n  updateClipPath: (\n    element: HTMLElement,\n    canvasElement: HTMLCanvasElement,\n    isSelected: boolean,\n    selectedArea?: {\n      x: number\n      y: number\n      width: number\n      height: number\n      scale: number\n      offset: [number, number]\n    }\n  ) => void\n}\n\nexport function useDomClipping(\n  options: ClippingOptions = {}\n): UseDomClippingReturn {\n  const style = ref<CSSProperties>({})\n  const { margin = 4 } = options\n\n  /**\n   * Calculates a clip path for an element based on its intersection with a selected area\n   */\n  const calculateClipPath = (\n    elementRect: DOMRect,\n    canvasRect: DOMRect,\n    isSelected: boolean,\n    selectedArea?: {\n      x: number\n      y: number\n      width: number\n      height: number\n      scale: number\n      offset: [number, number]\n    }\n  ): string => {\n    if (!isSelected && selectedArea) {\n      const { scale, offset } = selectedArea\n\n      // Get intersection in browser space\n      const intersection = intersect(\n        {\n          x: elementRect.left - canvasRect.left,\n          y: elementRect.top - canvasRect.top,\n          width: elementRect.width,\n          height: elementRect.height\n        },\n        {\n          x: (selectedArea.x + offset[0] - margin) * scale,\n          y: (selectedArea.y + offset[1] - margin) * scale,\n          width: (selectedArea.width + 2 * margin) * scale,\n          height: (selectedArea.height + 2 * margin) * scale\n        }\n      )\n\n      if (!intersection) {\n        return ''\n      }\n\n      // Convert intersection to canvas scale (element has scale transform)\n      const clipX =\n        (intersection[0] - elementRect.left + canvasRect.left) / scale + 'px'\n      const clipY =\n        (intersection[1] - elementRect.top + canvasRect.top) / scale + 'px'\n      const clipWidth = intersection[2] / scale + 'px'\n      const clipHeight = intersection[3] / scale + 'px'\n\n      return `polygon(0% 0%, 0% 100%, ${clipX} 100%, ${clipX} ${clipY}, calc(${clipX} + ${clipWidth}) ${clipY}, calc(${clipX} + ${clipWidth}) calc(${clipY} + ${clipHeight}), ${clipX} calc(${clipY} + ${clipHeight}), ${clipX} 100%, 100% 100%, 100% 0%)`\n    }\n\n    return ''\n  }\n\n  let pendingRaf = 0\n\n  /**\n   * Updates the clip-path style based on element and selection information.\n   * Batched via requestAnimationFrame to avoid forcing synchronous layout\n   * from getBoundingClientRect() on every reactive state change.\n   */\n  const updateClipPath = (\n    element: HTMLElement,\n    canvasElement: HTMLCanvasElement,\n    isSelected: boolean,\n    selectedArea?: {\n      x: number\n      y: number\n      width: number\n      height: number\n      scale: number\n      offset: [number, number]\n    }\n  ) => {\n    if (pendingRaf) cancelAnimationFrame(pendingRaf)\n    pendingRaf = requestAnimationFrame(() => {\n      pendingRaf = 0\n      const elementRect = element.getBoundingClientRect()\n      const canvasRect = canvasElement.getBoundingClientRect()\n\n      const clipPath = calculateClipPath(\n        elementRect,\n        canvasRect,\n        isSelected,\n        selectedArea\n      )\n\n      style.value = {\n        clipPath: clipPath || 'none',\n        willChange: 'clip-path'\n      }\n    })\n  }\n\n  return {\n    style,\n    updateClipPath\n  }\n}\n","import { reportError } from '@/platform/telemetry/reportError'\nimport type { NodeId } from '@/types/nodeId'\n\nconst MAX_REPORTS_PER_SESSION = 20\n\nconst reportedMessages = new Set<string>()\n\ntype DomWidgetMountContext = {\n  nodeId: NodeId\n  nodeType: string | undefined\n  widgetName: string\n}\n\n/**\n * Whatever breaks `appendChild` for one DOM widget usually breaks it for every\n * DOM widget in the graph, and widgets remount on each visibility flip, so\n * reports are deduplicated by message and capped per session.\n */\nexport function reportDomWidgetMountFailure(\n  error: unknown,\n  context: DomWidgetMountContext\n): void {\n  const message = error instanceof Error ? error.message : String(error)\n  if (reportedMessages.has(message)) return\n  if (reportedMessages.size >= MAX_REPORTS_PER_SESSION) return\n  reportedMessages.add(message)\n\n  reportError(error, {\n    surface: 'graph',\n    errorType: 'canvas_dom_widget_mount_failed',\n    context,\n    level: 'error'\n  })\n}\n","<template>\n  <div\n    v-show=\"widgetState.visible\"\n    ref=\"widgetElement\"\n    class=\"dom-widget size-full\"\n    :title=\"tooltip\"\n    :style=\"style\"\n  >\n    <component\n      :is=\"widget.component\"\n      v-if=\"isComponentWidget(widget)\"\n      class=\"size-full\"\n      :model-value=\"widget.value\"\n      :widget=\"widget\"\n      v-bind=\"widget.props\"\n      @update:model-value=\"emit('update:widgetValue', $event)\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useElementBounding, useEventListener, whenever } from '@vueuse/core'\nimport type { CSSProperties } from 'vue'\nimport { computed, nextTick, onMounted, ref, watch } from 'vue'\n\nimport { useAbsolutePosition } from '@/composables/element/useAbsolutePosition'\nimport { useDomClipping } from '@/composables/element/useDomClipping'\nimport { findFirstNode } from '@/lib/litegraph/src/utils/collections'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { isComponentWidget, isDOMWidget } from '@/scripts/domWidget'\nimport type { DomWidgetState } from '@/stores/domWidgetStore'\n\nimport { reportDomWidgetMountFailure } from './domWidgetMountReporting'\n\nconst { widgetState } = defineProps<{\n  widgetState: DomWidgetState\n}>()\nconst widget = widgetState.widget\n\nconst emit = defineEmits<{\n  'update:widgetValue': [value: string | object]\n}>()\n\nconst widgetElement = ref<HTMLElement | undefined>()\nconst { style: positionStyle, updatePosition } = useAbsolutePosition({\n  useTransform: true\n})\nconst { style: clippingStyle, updateClipPath } = useDomClipping()\n\nconst canvasStore = useCanvasStore()\nconst settingStore = useSettingStore()\nconst enableDomClipping = computed(() =>\n  settingStore.get('Comfy.DOMClippingEnabled')\n)\nconst style = computed<CSSProperties>(() => {\n  const isDisabled = widget.computedDisabled\n\n  return {\n    ...positionStyle.value,\n    ...(enableDomClipping.value ? clippingStyle.value : {}),\n    zIndex: widgetState.zIndex,\n    pointerEvents:\n      !widgetState.visible || widgetState.readonly || isDisabled\n        ? 'none'\n        : 'auto',\n    opacity: isDisabled ? 0.5 : 1\n  }\n})\n\nconst updateDomClipping = () => {\n  const lgCanvas = canvasStore.canvas\n  if (!lgCanvas || !widgetElement.value) return\n\n  const selectedNode = findFirstNode(lgCanvas.selectedItems)\n  if (!selectedNode) {\n    // Clear clipping when no node is selected\n    updateClipPath(widgetElement.value, lgCanvas.canvas, false, undefined)\n    return\n  }\n\n  const isSelected = selectedNode === widgetState.widget.node\n  const renderArea = selectedNode?.renderArea\n  const offset = lgCanvas.ds.offset\n  const scale = lgCanvas.ds.scale\n  const selectedAreaConfig = renderArea\n    ? {\n        x: renderArea[0],\n        y: renderArea[1],\n        width: renderArea[2],\n        height: renderArea[3],\n        scale,\n        offset: [offset[0], offset[1]] as [number, number]\n      }\n    : undefined\n\n  updateClipPath(\n    widgetElement.value,\n    lgCanvas.canvas,\n    isSelected,\n    selectedAreaConfig\n  )\n}\n\n/**\n * @note mapping between canvas position and client position depends on the\n * canvas element's position, so we need to watch the canvas element's position\n * and update the position of the widget accordingly.\n */\nconst { left, top } = useElementBounding(canvasStore.getCanvas().canvas)\n\nwatch(\n  [\n    () => widgetState.pos,\n    () => widgetState.size,\n    // Visibility transitions (e.g. LOD low_quality flipping) must refresh\n    // style: while invisible, DomWidgets.vue does not update widgetState\n    // and ds.offset/ds.scale are non-reactive, so updatePosition must be\n    // re-run against the current viewport when the widget reappears.\n    () => widgetState.visible,\n    left,\n    top,\n    enableDomClipping\n  ],\n  () => {\n    updatePosition(widgetState)\n    if (enableDomClipping.value) {\n      updateDomClipping()\n    }\n  },\n  { immediate: true }\n)\n\nwatch(\n  () => widgetState.visible,\n  (newVisible, oldVisible) => {\n    if (!newVisible && oldVisible) {\n      widget.options.onHide?.(widget)\n    }\n  }\n)\nuseEventListener(document, 'mousedown', (event) => {\n  if (!isDOMWidget(widget) || !widgetState.visible || !widget.element.blur) {\n    return\n  }\n  if (!widget.element.contains(event.target as HTMLElement)) {\n    widget.element.blur()\n  }\n})\n\nonMounted(() => {\n  if (!isDOMWidget(widget)) {\n    return\n  }\n  useEventListener(\n    widget.element,\n    widget.options.selectOn ?? ['focus', 'click'],\n    () => {\n      const lgCanvas = canvasStore.canvas\n      if (!lgCanvas) return\n\n      const ownerNode = widgetState.widget.node\n      lgCanvas.selectNode(ownerNode)\n      lgCanvas.bringToFront(ownerNode)\n    }\n  )\n})\n\nconst inputSpec = widget.node.constructor.nodeData\nconst tooltip = inputSpec?.inputs?.[widget.name]?.tooltip\n\n// Mount DOM element when widget is or becomes visible\nconst mountElementIfVisible = () => {\n  if (!(widgetState.visible && isDOMWidget(widget) && widgetElement.value)) {\n    return\n  }\n  // Only append if not already a child\n  if (widgetElement.value.contains(widget.element)) {\n    return\n  }\n\n  try {\n    widget.element.classList.add('h-full', 'w-full')\n    widgetElement.value.appendChild(widget.element)\n  } catch (error) {\n    reportDomWidgetMountFailure(error, {\n      nodeId: widget.node.id,\n      nodeType: widget.node.type,\n      widgetName: widget.name\n    })\n  }\n}\n\n// Check on mount - but only after next tick to ensure visibility is calculated\nonMounted(() => {\n  void nextTick(mountElementIfVisible)\n})\n\n// And watch for visibility changes\nwatch(\n  () => widgetState.visible,\n  () => {\n    mountElementIfVisible()\n  }\n)\n\nwhenever(() => !canvasStore.linearMode, mountElementIfVisible)\n</script>\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\n\nexport function getDomWidgetZIndex(\n  node: LGraphNode,\n  currentGraph: LGraphNode['graph'] | undefined\n): number {\n  if (!currentGraph) return node.order\n\n  const graphOrder = currentGraph.nodes.indexOf(node)\n  if (graphOrder === -1) return node.order\n\n  return graphOrder\n}\n","<template>\n  <!-- Create a new stacking context for widgets to avoid z-index issues -->\n  <div\n    class=\"isolate\"\n    data-testid=\"dom-widgets\"\n    :inert=\"canvasStore.isPickingNodes\"\n  >\n    <DomWidget\n      v-for=\"widgetState in widgetStates\"\n      :key=\"widgetState.widget.id\"\n      :widget-state=\"widgetState\"\n      @update:widget-value=\"widgetState.widget.value = $event\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { whenever } from '@vueuse/core'\nimport { computed } from 'vue'\n\nimport DomWidget from '@/components/graph/widgets/DomWidget.vue'\nimport { getDomWidgetZIndex } from '@/components/graph/widgets/domWidgetZIndex'\nimport { useChainCallback } from '@/composables/functional/useChainCallback'\nimport { findFirstNode } from '@/lib/litegraph/src/utils/collections'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useDomWidgetStore } from '@/stores/domWidgetStore'\n\nconst domWidgetStore = useDomWidgetStore()\n\nconst widgetStates = computed(() => [...domWidgetStore.widgetStates.values()])\n\n// Track canvas viewport and selected-node bounds between frames.\n// lgCanvas.ds.offset, ds.scale, and node.renderArea are non-reactive plain\n// values, so widgetState.pos needs a new identity to rerun downstream work.\nconst lastViewport = {\n  offsetX: Number.NaN,\n  offsetY: Number.NaN,\n  scale: Number.NaN\n}\nconst lastSelected = {\n  id: undefined as string | number | undefined,\n  x: 0,\n  y: 0,\n  width: 0,\n  height: 0\n}\n\nconst updateWidgets = () => {\n  const lgCanvas = canvasStore.canvas\n  if (!lgCanvas) return\n\n  const lowQuality = lgCanvas.low_quality\n  const currentGraph = lgCanvas.graph\n\n  const viewportOffsetX = lgCanvas.ds.offset[0]\n  const viewportOffsetY = lgCanvas.ds.offset[1]\n  const viewportScale = lgCanvas.ds.scale\n  const viewportChanged =\n    lastViewport.offsetX !== viewportOffsetX ||\n    lastViewport.offsetY !== viewportOffsetY ||\n    lastViewport.scale !== viewportScale\n  lastViewport.offsetX = viewportOffsetX\n  lastViewport.offsetY = viewportOffsetY\n  lastViewport.scale = viewportScale\n\n  const selectedNode = findFirstNode(lgCanvas.selectedItems)\n  const selectedNodeId = selectedNode?.id\n  const selectedArea = selectedNode?.renderArea\n  const selectionChanged =\n    lastSelected.id !== selectedNodeId ||\n    (!!selectedArea &&\n      (lastSelected.x !== selectedArea[0] ||\n        lastSelected.y !== selectedArea[1] ||\n        lastSelected.width !== selectedArea[2] ||\n        lastSelected.height !== selectedArea[3]))\n  lastSelected.id = selectedNodeId\n  lastSelected.x = selectedArea?.[0] ?? 0\n  lastSelected.y = selectedArea?.[1] ?? 0\n  lastSelected.width = selectedArea?.[2] ?? 0\n  lastSelected.height = selectedArea?.[3] ?? 0\n\n  for (const widgetState of widgetStates.value) {\n    const widget = widgetState.widget\n\n    if (!widget.isVisible() || !widgetState.active) {\n      widgetState.visible = false\n      continue\n    }\n\n    const posNode = widget.node\n\n    const isInCorrectGraph = posNode.graph === currentGraph\n    const nodeVisible = lgCanvas.isNodeVisible(posNode)\n\n    widgetState.visible =\n      isInCorrectGraph &&\n      nodeVisible &&\n      !(widget.options.hideOnZoom && lowQuality)\n\n    if (widgetState.visible) {\n      const margin = widget.margin\n      const newPosX = posNode.pos[0] + margin\n      const newPosY = posNode.pos[1] + margin + widget.y\n      if (\n        viewportChanged ||\n        selectionChanged ||\n        widgetState.pos[0] !== newPosX ||\n        widgetState.pos[1] !== newPosY\n      ) {\n        widgetState.pos = [newPosX, newPosY]\n      }\n\n      const newWidth = (widget.width ?? posNode.width) - margin * 2\n      const newHeight = (widget.computedHeight ?? 50) - margin * 2\n      if (\n        widgetState.size[0] !== newWidth ||\n        widgetState.size[1] !== newHeight\n      ) {\n        widgetState.size = [newWidth, newHeight]\n      }\n\n      widgetState.zIndex = getDomWidgetZIndex(posNode, currentGraph)\n      widgetState.readonly = lgCanvas.read_only\n    }\n  }\n}\n\nconst canvasStore = useCanvasStore()\nwhenever(\n  () => canvasStore.canvas,\n  (canvas) =>\n    (canvas.onDrawForeground = useChainCallback(\n      canvas.onDrawForeground,\n      updateWidgets\n    )),\n  { immediate: true }\n)\n</script>\n","import { computed, ref } from 'vue'\n\nexport function useZoomControls() {\n  const isModalVisible = ref(false)\n\n  const showModal = () => {\n    isModalVisible.value = true\n  }\n\n  const hideModal = () => {\n    isModalVisible.value = false\n  }\n\n  const toggleModal = () => {\n    isModalVisible.value = !isModalVisible.value\n  }\n\n  const hasActivePopup = computed(() => isModalVisible.value)\n\n  return {\n    isModalVisible,\n    showModal,\n    hideModal,\n    toggleModal,\n    hasActivePopup\n  }\n}\n","import { readonly, shallowRef } from 'vue'\n\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type { GraphScope } from '@/types/graphScopeId'\nimport type { NodeId } from '@/types/nodeId'\n\ninterface MinimapDecorationTarget extends GraphScope {\n  readonly nodeId: NodeId\n}\n\ninterface MinimapNodeDecoration {\n  readonly target: MinimapDecorationTarget\n  readonly enter?: 'pop'\n}\n\nexport interface MinimapDecorationLayer {\n  replace(rows: readonly MinimapNodeDecoration[]): void\n  dispose(): void\n}\n\nexport interface ResolvedMinimapNodeDecoration extends MinimapNodeDecoration {\n  readonly enteredAt?: number\n}\n\ninterface RegisteredLayer {\n  readonly rows: Map<string, ResolvedMinimapNodeDecoration>\n  disposed: boolean\n}\n\nconst layers = new Map<string, RegisteredLayer>()\nconst revision = shallowRef(0)\n\nfunction targetKey(target: MinimapDecorationTarget): string {\n  return `${target.rootGraphId}:${target.owningGraphId}:${target.nodeId}`\n}\n\nfunction copyDecoration(\n  row: MinimapNodeDecoration,\n  enteredAt?: number\n): ResolvedMinimapNodeDecoration {\n  return {\n    target: { ...row.target },\n    enter: row.enter,\n    enteredAt\n  }\n}\n\nfunction invalidate(): void {\n  revision.value += 1\n}\n\n/**\n * Registers transient, graph-scoped minimap decorations. Producers own which\n * nodes are decorated and when the layer is disposed; the minimap exclusively\n * owns projection, palette, paint order, and animation scheduling.\n */\nexport function registerMinimapDecorationLayer(\n  id: string\n): MinimapDecorationLayer {\n  const stale = layers.get(id)\n  if (stale) {\n    // Still reported: one id held twice at once is a producer bug worth seeing.\n    // But the newest registrant takes the id over, because handing it back a\n    // no-op layer left the *surviving* producer unable to paint anything for\n    // the rest of the session - the outgoing one is the replaced party, so\n    // keeping its layer kept the id claimed and the decoration dead.\n    reportError(new Error(`Minimap decoration layer exists: ${id}`), {\n      surface: 'graph',\n      errorType: 'minimap_decoration_layer_duplicate'\n    })\n    // Marking it disposed is what makes the takeover safe: the outgoing\n    // producer's own `dispose()` then returns early instead of deleting the\n    // replacement's layer, and its `replace()` calls stop mutating anything.\n    stale.disposed = true\n  }\n\n  const layer: RegisteredLayer = { rows: new Map(), disposed: false }\n  layers.set(id, layer)\n  if (stale) invalidate()\n\n  return {\n    replace(rows) {\n      if (layer.disposed) return\n      const next = new Map<string, ResolvedMinimapNodeDecoration>()\n      const now = performance.now()\n      for (const [index, row] of rows.entries()) {\n        const key = targetKey(row.target)\n        const previous = layer.rows.get(key)\n        const enteredAt =\n          row.enter === 'pop'\n            ? (previous?.enteredAt ?? now + Math.min(index, 8) * 50)\n            : undefined\n        next.set(key, copyDecoration(row, enteredAt))\n      }\n      layer.rows.clear()\n      for (const [key, row] of next) layer.rows.set(key, row)\n      invalidate()\n    },\n    dispose() {\n      if (layer.disposed) return\n      layer.disposed = true\n      layers.delete(id)\n      invalidate()\n    }\n  }\n}\n\nexport const minimapDecorationRevision = readonly(revision)\n\nexport function getMinimapDecorations(\n  scope: GraphScope\n): readonly ResolvedMinimapNodeDecoration[] {\n  return [...layers.entries()]\n    .sort(([left], [right]) => left.localeCompare(right))\n    .flatMap(([, layer]) => [...layer.rows.values()])\n    .filter(\n      ({ target }) =>\n        target.rootGraphId === scope.rootGraphId &&\n        target.owningGraphId === scope.owningGraphId\n    )\n    .map((row) => copyDecoration(row, row.enteredAt))\n}\n","import { useThrottleFn } from '@vueuse/core'\nimport { ref } from 'vue'\nimport type { Ref } from 'vue'\n\nimport { useChainCallback } from '@/composables/functional/useChainCallback'\nimport type { LGraphEventMap } from '@/lib/litegraph/src/infrastructure/LGraphEventMap'\nimport type { LGraph, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { api } from '@/scripts/api'\nimport { useExecutionStore } from '@/stores/executionStore'\n\nimport type { UpdateFlags } from '../types'\n\ninterface GraphCallbacks {\n  onConnectionChange?: (node: LGraphNode) => void\n}\n\n/**\n * Fixed-point quantisation for digest input, at eighth-pixel precision.\n * Mixing raw values would truncate at each `| 0`, so a drag or resize that\n * only changes the fractional part would leave the digest unchanged.\n */\nfunction quantise(value: number): number {\n  return Math.round(value * 8)\n}\n\n/**\n * Mixes one term into a rolling digest.\n *\n * The coercion is on the term, not the sum: `(digest + NaN) | 0` is 0, which\n * would discard every node mixed in so far and make an unrelated change\n * invisible for as long as the non-finite value stays in the graph.\n */\nfunction mixIn(digest: number, value: number): number {\n  return (Math.imul(digest, 31) + (Number.isFinite(value) ? value : 0)) | 0\n}\n\n/**\n * Cheap string hash for digest input (colors, execution states).\n */\nfunction hashString(value: string): number {\n  let hash = value.length\n  for (let i = 0; i < value.length; i++) {\n    hash = (Math.imul(hash, 31) + value.charCodeAt(i)) | 0\n  }\n  return hash\n}\n\ninterface GraphDigests {\n  /** Node placement: drives bounds recomputation as well as repaint. */\n  geometry: number\n  /** Everything else the renderer draws: repaint only, bounds untouched. */\n  visual: number\n}\n\n/**\n * Rolling digests over everything the minimap renders, in one allocation-free\n * pass. The digests are the single authority on \"did the picture change\":\n * event hooks and the poll are only signals to compare them, so any input the\n * renderer reads has to be mixed in here or changes to it stop repainting.\n *\n * Digests can in principle collide, which would drop a single refresh -\n * acceptable for an approximate overview, and the next change re-syncs it.\n */\nfunction computeGraphDigests(graph: LGraph): GraphDigests {\n  // Store-side geometry: the renderer reads layoutStore whenever it holds\n  // nodes, so a write whose write-back to the litegraph node has not landed\n  // must still count. Geometry version, not layoutVersion - that counts\n  // operations, and zIndex alone fires one per widget pointerdown.\n  let geometry = mixIn(layoutStore.nodeGeometryVersion, graph._nodes.length)\n  let visual = 0\n\n  for (const node of graph._nodes) {\n    const [x, y] = node.pos\n    const [width, height] = node.renderingSize\n    geometry = mixIn(geometry, quantise(x))\n    geometry = mixIn(geometry, quantise(y))\n    geometry = mixIn(geometry, quantise(width))\n    geometry = mixIn(geometry, quantise(height))\n    visual = mixIn(visual, node.mode)\n    visual = mixIn(visual, node.has_errors ? 1 : 0)\n    visual = mixIn(visual, node.bgcolor ? hashString(node.bgcolor) : 0)\n  }\n\n  for (const group of graph._groups) {\n    visual = mixIn(visual, quantise(group.pos[0]))\n    visual = mixIn(visual, quantise(group.pos[1]))\n    visual = mixIn(visual, quantise(group.size[0]))\n    visual = mixIn(visual, quantise(group.size[1]))\n    visual = mixIn(visual, group.color ? hashString(group.color) : 0)\n  }\n\n  // Execution state is drawn as discrete outline colors, so mixing the state\n  // strings repaints exactly on transitions. Progress percentages are not\n  // rendered, which is what lets the per-progress-message watcher go: the\n  // poll picks up each transition within one tick at no per-message cost.\n  const progressStates = useExecutionStore().nodeProgressStates\n  for (const nodeId in progressStates) {\n    const state = Object.hasOwn(progressStates, nodeId)\n      ? progressStates[nodeId].state\n      : undefined\n    if (!state) continue\n    visual = mixIn(visual, hashString(nodeId))\n    visual = mixIn(visual, hashString(state))\n  }\n\n  return { geometry, visual }\n}\n\n/**\n * Rolling digest of link endpoints and slots. Counting links alone would miss\n * a rewire that keeps the total unchanged, and endpoints alone would miss a\n * link moved to a different slot on the same pair of nodes.\n */\nfunction computeLinkDigest(graph: LGraph): number {\n  let digest = 0\n  for (const link of graph.links.values()) {\n    // Node ids are branded strings and need not be numeric; non-numeric ones\n    // contribute 0 here and are caught instead by the onConnectionChange hook.\n    digest = mixIn(digest, Number(link.origin_id))\n    digest = mixIn(digest, Number(link.target_id))\n    digest = mixIn(digest, link.origin_slot)\n    digest = mixIn(digest, link.target_slot)\n  }\n\n  return digest\n}\n\nexport function useMinimapGraph(\n  graph: Ref<LGraph | null>,\n  onGraphChanged: () => void\n) {\n  // Null rather than a numeric sentinel: 0 is a digest these functions produce\n  // for an empty graph, so a numeric \"no baseline\" would be indistinguishable\n  // from a real first reading.\n  let geometryDigest: number | null = null\n  let visualDigest: number | null = null\n  let linkDigest: number | null = null\n  const updateFlags = ref<UpdateFlags>({\n    bounds: false,\n    nodes: false,\n    connections: false,\n    viewport: false\n  })\n\n  // Cleanup restores originals only when our wrapper is still on top, and\n  // marks any buried wrapper inert via `entry.live` so it can't fire dead work.\n  interface InstalledHooks {\n    originals: GraphCallbacks\n    wrappers: GraphCallbacks\n    live: boolean\n    disposeListeners: () => void\n  }\n  const hooksMap = new Map<string, InstalledHooks>()\n\n  const handleGraphChangedThrottled = useThrottleFn(() => {\n    onGraphChanged()\n  }, 500)\n\n  const setupEventListeners = () => {\n    const g = graph.value\n    if (!g || hooksMap.has(g.id)) return\n\n    const originals: GraphCallbacks = {\n      onConnectionChange: g.onConnectionChange\n    }\n    const wrappers: GraphCallbacks = {}\n\n    const onNodeAdded = () => void handleGraphChangedThrottled()\n\n    const onNodeRemoved = () => {\n      void handleGraphChangedThrottled()\n    }\n\n    // A reload of the same workflow leaves the node count and every geometry\n    // string identical, so change detection alone cannot tell that `bounds` was\n    // last derived mid-configure, from a partially built graph.\n    const onConfigured = () => {\n      clearCache()\n      void handleGraphChangedThrottled()\n    }\n\n    const onPropertyChanged = (\n      e: CustomEvent<LGraphEventMap['node:property:changed']>\n    ) => {\n      const { property } = e.detail\n      if (\n        property === 'mode' ||\n        property === 'bgcolor' ||\n        property === 'color'\n      ) {\n        void handleGraphChangedThrottled()\n      }\n    }\n\n    const entry: InstalledHooks = {\n      originals,\n      wrappers,\n      live: true,\n      disposeListeners: () => {\n        g.events.removeEventListener('node:added', onNodeAdded)\n        g.events.removeEventListener('node:removed', onNodeRemoved)\n        g.events.removeEventListener('configured', onConfigured)\n        g.events.removeEventListener('node:property:changed', onPropertyChanged)\n      }\n    }\n    hooksMap.set(g.id, entry)\n\n    wrappers.onConnectionChange = useChainCallback(\n      originals.onConnectionChange,\n      function () {\n        if (!entry.live) return\n        void handleGraphChangedThrottled()\n      }\n    )\n    g.onConnectionChange = wrappers.onConnectionChange\n\n    g.events.addEventListener('node:added', onNodeAdded)\n    g.events.addEventListener('node:removed', onNodeRemoved)\n    g.events.addEventListener('configured', onConfigured)\n    g.events.addEventListener('node:property:changed', onPropertyChanged)\n  }\n\n  const cleanupEventListeners = (oldGraph?: LGraph) => {\n    const g = oldGraph || graph.value\n    if (!g) return\n    const entry = hooksMap.get(g.id)\n    if (!entry) return\n    const { originals, wrappers } = entry\n\n    if (g.onConnectionChange === wrappers.onConnectionChange)\n      g.onConnectionChange = originals.onConnectionChange\n    entry.disposeListeners()\n\n    entry.live = false\n    hooksMap.delete(g.id)\n  }\n\n  const checkForChangesInternal = () => {\n    const g = graph.value\n    if (!g) return false\n\n    const { geometry, visual } = computeGraphDigests(g)\n    const links = computeLinkDigest(g)\n\n    const geometryChanged = geometry !== geometryDigest\n    const visualChanged = visual !== visualDigest\n    const connectionChanged = links !== linkDigest\n\n    geometryDigest = geometry\n    visualDigest = visual\n    linkDigest = links\n\n    // Only geometry moves the graph's extent; a recolour, group drag or\n    // execution transition repaints without recomputing bounds.\n    if (geometryChanged) {\n      updateFlags.value.bounds = true\n    }\n    if (geometryChanged || visualChanged) {\n      updateFlags.value.nodes = true\n    }\n    if (connectionChanged) {\n      updateFlags.value.connections = true\n    }\n\n    return geometryChanged || visualChanged || connectionChanged\n  }\n\n  const init = () => {\n    setupEventListeners()\n    api.addEventListener('graphChanged', handleGraphChangedThrottled)\n  }\n\n  const destroy = () => {\n    cleanupEventListeners()\n    api.removeEventListener('graphChanged', handleGraphChangedThrottled)\n    clearCache()\n  }\n\n  const clearCache = () => {\n    geometryDigest = null\n    visualDigest = null\n    linkDigest = null\n  }\n\n  return {\n    updateFlags,\n    setupEventListeners,\n    cleanupEventListeners,\n    checkForChanges: checkForChangesInternal,\n    init,\n    destroy,\n    clearCache\n  }\n}\n","import { ref } from 'vue'\nimport type { Ref, ShallowRef } from 'vue'\n\nimport type { MinimapCanvas } from '../types'\n\nexport function useMinimapInteraction(\n  containerRef: Readonly<ShallowRef<HTMLDivElement | null>>,\n  bounds: Ref<{ minX: number; minY: number; width: number; height: number }>,\n  scale: Ref<number>,\n  width: number,\n  height: number,\n  centerViewOn: (worldX: number, worldY: number) => void,\n  canvas: Ref<MinimapCanvas | null>\n) {\n  const isDragging = ref(false)\n  const containerRect = ref({\n    left: 0,\n    top: 0,\n    width: width,\n    height: height\n  })\n\n  const updateContainerRect = () => {\n    if (!containerRef.value) return\n\n    const rect = containerRef.value.getBoundingClientRect()\n    containerRect.value = {\n      left: rect.left,\n      top: rect.top,\n      width: rect.width,\n      height: rect.height\n    }\n  }\n\n  const handlePointerDown = (e: PointerEvent) => {\n    isDragging.value = true\n    updateContainerRect()\n    const target = e.currentTarget\n    if (target instanceof HTMLElement) {\n      target.setPointerCapture(e.pointerId)\n    }\n    handlePointerMove(e)\n  }\n\n  const handlePointerMove = (e: PointerEvent) => {\n    if (!isDragging.value || !canvas.value) return\n\n    const x = e.clientX - containerRect.value.left\n    const y = e.clientY - containerRect.value.top\n\n    const offsetX = (width - bounds.value.width * scale.value) / 2\n    const offsetY = (height - bounds.value.height * scale.value) / 2\n\n    const worldX = (x - offsetX) / scale.value + bounds.value.minX\n    const worldY = (y - offsetY) / scale.value + bounds.value.minY\n\n    centerViewOn(worldX, worldY)\n  }\n\n  const releasePointer = (e?: PointerEvent) => {\n    isDragging.value = false\n    if (!e) return\n\n    const target = e.currentTarget\n    if (\n      target instanceof HTMLElement &&\n      target.hasPointerCapture(e.pointerId)\n    ) {\n      target.releasePointerCapture(e.pointerId)\n    }\n  }\n\n  const handlePointerUp = releasePointer\n\n  const handlePointerCancel = releasePointer\n\n  const handleWheel = (e: WheelEvent) => {\n    e.preventDefault()\n\n    const c = canvas.value\n    if (!c) return\n\n    if (\n      containerRect.value.left === 0 &&\n      containerRect.value.top === 0 &&\n      containerRef.value\n    ) {\n      updateContainerRect()\n    }\n\n    const ds = c.ds\n    const delta = e.deltaY > 0 ? 0.9 : 1.1\n\n    const newScale = ds.scale * delta\n\n    const MIN_SCALE = 0.1\n    const MAX_SCALE = 10\n\n    if (newScale < MIN_SCALE || newScale > MAX_SCALE) return\n\n    const x = e.clientX - containerRect.value.left\n    const y = e.clientY - containerRect.value.top\n\n    const offsetX = (width - bounds.value.width * scale.value) / 2\n    const offsetY = (height - bounds.value.height * scale.value) / 2\n\n    const worldX = (x - offsetX) / scale.value + bounds.value.minX\n    const worldY = (y - offsetY) / scale.value + bounds.value.minY\n\n    ds.scale = newScale\n\n    centerViewOn(worldX, worldY)\n  }\n\n  return {\n    isDragging,\n    containerRect,\n    updateContainerRect,\n    handlePointerDown,\n    handlePointerMove,\n    handlePointerUp,\n    handlePointerCancel,\n    handleWheel\n  }\n}\n","import { ref } from 'vue'\nimport type { Ref, ShallowRef } from 'vue'\n\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport { useExecutionStore } from '@/stores/executionStore'\n\nimport { renderMinimapToCanvas } from '../minimapCanvasRenderer'\nimport type { MinimapRenderContext, UpdateFlags } from '../types'\n\nexport function useMinimapRenderer(\n  canvasRef: Readonly<ShallowRef<HTMLCanvasElement | null>>,\n  graph: Ref<LGraph | null>,\n  bounds: Ref<{ minX: number; minY: number; width: number; height: number }>,\n  scale: Ref<number>,\n  updateFlags: Ref<UpdateFlags>,\n  settings: {\n    nodeColors: Ref<boolean>\n    showLinks: Ref<boolean>\n    showGroups: Ref<boolean>\n    renderBypass: Ref<boolean>\n    renderError: Ref<boolean>\n  },\n  width: number,\n  height: number,\n  decorations: Ref<MinimapRenderContext['decorations']> = ref([])\n) {\n  const executionStore = useExecutionStore()\n  const needsFullRedraw = ref(true)\n  const needsBoundsUpdate = ref(true)\n\n  const renderMinimap = () => {\n    const g = graph.value\n    if (!canvasRef.value || !g) return\n\n    const ctx = canvasRef.value.getContext('2d')\n    if (!ctx) return\n\n    // Fast path for 0 nodes - just show background\n    if (g._nodes.length === 0) {\n      ctx.clearRect(0, 0, width, height)\n      return\n    }\n\n    const needsRedraw =\n      needsFullRedraw.value ||\n      updateFlags.value.nodes ||\n      updateFlags.value.connections\n\n    if (needsRedraw) {\n      renderMinimapToCanvas(canvasRef.value, g, {\n        bounds: bounds.value,\n        scale: scale.value,\n        settings: {\n          nodeColors: settings.nodeColors.value,\n          showLinks: settings.showLinks.value,\n          showGroups: settings.showGroups.value,\n          renderBypass: settings.renderBypass.value,\n          renderError: settings.renderError.value\n        },\n        width,\n        height,\n        decorations: decorations.value,\n        nodeProgressStates: executionStore.nodeLocationProgressStates,\n        now: performance.now()\n      })\n\n      needsFullRedraw.value = false\n      updateFlags.value.nodes = false\n      updateFlags.value.connections = false\n    }\n  }\n\n  const updateMinimap = (\n    updateBounds: () => void,\n    updateViewport: () => void\n  ) => {\n    if (needsBoundsUpdate.value || updateFlags.value.bounds) {\n      updateBounds()\n      needsBoundsUpdate.value = false\n      updateFlags.value.bounds = false\n      needsFullRedraw.value = true\n      // When bounds change, we need to update the viewport position\n      updateFlags.value.viewport = true\n    }\n\n    if (\n      needsFullRedraw.value ||\n      updateFlags.value.nodes ||\n      updateFlags.value.connections\n    ) {\n      renderMinimap()\n    }\n\n    // Update viewport if needed (e.g., after bounds change)\n    if (updateFlags.value.viewport) {\n      updateViewport()\n      updateFlags.value.viewport = false\n    }\n  }\n\n  const forceFullRedraw = () => {\n    needsFullRedraw.value = true\n    updateFlags.value.bounds = true\n    updateFlags.value.nodes = true\n    updateFlags.value.connections = true\n    updateFlags.value.viewport = true\n  }\n\n  return {\n    needsFullRedraw,\n    needsBoundsUpdate,\n    renderMinimap,\n    updateMinimap,\n    forceFullRedraw\n  }\n}\n","import { computed } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\n\n/**\n * Composable for minimap configuration options that are set by the user in the\n * settings. Provides reactive computed properties for the settings.\n */\nexport function useMinimapSettings() {\n  const settingStore = useSettingStore()\n  const colorPaletteStore = useColorPaletteStore()\n\n  const nodeColors = computed(() =>\n    settingStore.get('Comfy.Minimap.NodeColors')\n  )\n  const showLinks = computed(() => settingStore.get('Comfy.Minimap.ShowLinks'))\n  const showGroups = computed(() =>\n    settingStore.get('Comfy.Minimap.ShowGroups')\n  )\n  const renderBypass = computed(() =>\n    settingStore.get('Comfy.Minimap.RenderBypassState')\n  )\n  const renderError = computed(() =>\n    settingStore.get('Comfy.Minimap.RenderErrorState')\n  )\n\n  const width = 253\n  const height = 200\n\n  // Theme-aware colors\n  const isLightTheme = computed(\n    () => colorPaletteStore.completedActivePalette.light_theme\n  )\n\n  const containerStyles = computed(() => ({\n    width: `${width}px`,\n    height: `${height}px`,\n    border: '1px solid var(--interface-stroke)',\n    borderRadius: '8px'\n  }))\n\n  const panelStyles = computed(() => ({\n    width: `210px`,\n    height: `${height}px`,\n    border: '1px solid var(--interface-stroke)',\n    borderRadius: '8px'\n  }))\n\n  return {\n    nodeColors,\n    showLinks,\n    showGroups,\n    renderBypass,\n    renderError,\n    containerStyles,\n    panelStyles,\n    isLightTheme\n  }\n}\n","import { useRafFn } from '@vueuse/core'\nimport { computed, ref } from 'vue'\nimport type { Ref } from 'vue'\n\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport {\n  calculateMinimapScale,\n  enforceMinimumBounds\n} from '@/renderer/core/spatial/boundsCalculator'\nimport { MinimapDataSource } from '@/renderer/extensions/minimap/data/MinimapDataSource'\n\nimport type { MinimapBounds, MinimapCanvas, ViewportTransform } from '../types'\n\nexport function useMinimapViewport(\n  canvas: Ref<MinimapCanvas | null>,\n  graph: Ref<LGraph | null>,\n  width: number,\n  height: number\n) {\n  const bounds = ref<MinimapBounds>({\n    minX: 0,\n    minY: 0,\n    maxX: 0,\n    maxY: 0,\n    width: 0,\n    height: 0\n  })\n\n  const scale = ref(1)\n  const viewportTransform = ref<ViewportTransform>({\n    x: 0,\n    y: 0,\n    width: 0,\n    height: 0\n  })\n\n  const canvasDimensions = ref({\n    width: 0,\n    height: 0\n  })\n\n  const updateCanvasDimensions = () => {\n    const c = canvas.value\n    if (!c) return\n\n    const canvasEl = c.canvas\n    const dpr = c.dpr\n\n    canvasDimensions.value = {\n      width: canvasEl.clientWidth || canvasEl.width / dpr,\n      height: canvasEl.clientHeight || canvasEl.height / dpr\n    }\n  }\n\n  const calculateGraphBounds = (): MinimapBounds => {\n    const dataSource = new MinimapDataSource(graph.value)\n\n    if (!dataSource.hasData()) {\n      return { minX: 0, minY: 0, maxX: 100, maxY: 100, width: 100, height: 100 }\n    }\n\n    const sourceBounds = dataSource.getBounds()\n    return enforceMinimumBounds(sourceBounds)\n  }\n\n  const calculateScale = () => {\n    return calculateMinimapScale(bounds.value, width, height)\n  }\n\n  const updateViewport = () => {\n    const c = canvas.value\n    if (!c) return\n\n    if (\n      canvasDimensions.value.width === 0 ||\n      canvasDimensions.value.height === 0\n    ) {\n      updateCanvasDimensions()\n    }\n\n    const ds = c.ds\n\n    const viewportWidth = canvasDimensions.value.width / ds.scale\n    const viewportHeight = canvasDimensions.value.height / ds.scale\n\n    const worldX = -ds.offset[0]\n    const worldY = -ds.offset[1]\n\n    const centerOffsetX = (width - bounds.value.width * scale.value) / 2\n    const centerOffsetY = (height - bounds.value.height * scale.value) / 2\n\n    const x = (worldX - bounds.value.minX) * scale.value + centerOffsetX\n    const y = (worldY - bounds.value.minY) * scale.value + centerOffsetY\n    const w = viewportWidth * scale.value\n    const h = viewportHeight * scale.value\n\n    const curr = viewportTransform.value\n    if (curr.x === x && curr.y === y && curr.width === w && curr.height === h)\n      return\n\n    viewportTransform.value = { x, y, width: w, height: h }\n  }\n\n  const updateBounds = () => {\n    bounds.value = calculateGraphBounds()\n    scale.value = calculateScale()\n  }\n\n  const centerViewOn = (worldX: number, worldY: number) => {\n    const c = canvas.value\n    if (!c) return\n\n    if (\n      canvasDimensions.value.width === 0 ||\n      canvasDimensions.value.height === 0\n    ) {\n      updateCanvasDimensions()\n    }\n\n    const ds = c.ds\n\n    const viewportWidth = canvasDimensions.value.width / ds.scale\n    const viewportHeight = canvasDimensions.value.height / ds.scale\n\n    ds.offset[0] = -(worldX - viewportWidth / 2)\n    ds.offset[1] = -(worldY - viewportHeight / 2)\n\n    c.setDirty(true, true)\n  }\n  const { resume: startViewportSync, pause: stopViewportSync } =\n    useRafFn(updateViewport)\n\n  return {\n    bounds: computed(() => bounds.value),\n    scale: computed(() => scale.value),\n    viewportTransform: computed(() => viewportTransform.value),\n    canvasDimensions: computed(() => canvasDimensions.value),\n    updateCanvasDimensions,\n    updateViewport,\n    updateBounds,\n    centerViewOn,\n    startViewportSync,\n    stopViewportSync\n  }\n}\n","import {\n  useDocumentVisibility,\n  useIntervalFn,\n  usePreferredReducedMotion,\n  useRafFn\n} from '@vueuse/core'\nimport { computed, nextTick, ref, shallowRef, watch } from 'vue'\nimport type { ShallowRef } from 'vue'\n\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport {\n  getMinimapDecorations,\n  minimapDecorationRevision\n} from '@/platform/canvas/minimapDecorationRegistry'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\n\nimport { MINIMAP_DECORATION_POP_MS } from '../minimapCanvasRenderer'\nimport type { MinimapCanvas, MinimapSettingsKey } from '../types'\nimport { useMinimapGraph } from './useMinimapGraph'\nimport { useMinimapInteraction } from './useMinimapInteraction'\nimport { useMinimapRenderer } from './useMinimapRenderer'\nimport { useMinimapSettings } from './useMinimapSettings'\nimport { useMinimapViewport } from './useMinimapViewport'\n\n/** How often to compare digests for state that emits no event; see the poll. */\nconst CHANGE_DETECTION_INTERVAL_MS = 100\n\nexport function useMinimap({\n  canvasRefMaybe,\n  containerRefMaybe\n}: {\n  canvasRefMaybe?: Readonly<ShallowRef<HTMLCanvasElement | null>>\n  containerRefMaybe?: Readonly<ShallowRef<HTMLDivElement | null>>\n} = {}) {\n  const canvasStore = useCanvasStore()\n  const workflowStore = useWorkflowStore()\n  const settingStore = useSettingStore()\n\n  const minimapRef = ref<HTMLElement | null>(null)\n  const canvasRef = canvasRefMaybe ?? shallowRef(null)\n  const containerRef = containerRefMaybe ?? shallowRef(null)\n\n  const visible = ref(true)\n  const initialized = ref(false)\n  const motionPreference = usePreferredReducedMotion()\n\n  const width = 250\n  const height = 200\n\n  const canvas = computed(() => canvasStore.canvas as MinimapCanvas | null)\n  const graph = computed(() => {\n    // If we're in a subgraph, use that; otherwise use the canvas graph\n    const activeSubgraph = workflowStore.activeSubgraph\n    return (activeSubgraph || canvas.value?.graph) as LGraph | null\n  })\n  const decorations = computed(() => {\n    const revision = minimapDecorationRevision.value\n    void revision\n    if (!graph.value) return []\n    const rows = getMinimapDecorations(graphScopeOf(graph.value))\n    const reducedMotion =\n      settingStore.get('Comfy.Appearance.DisableAnimations') ||\n      motionPreference.value === 'reduce'\n    return reducedMotion\n      ? rows.map((row) => ({\n          ...row,\n          enter: undefined,\n          enteredAt: undefined\n        }))\n      : rows\n  })\n\n  // Settings\n  const settings = useMinimapSettings()\n  const {\n    nodeColors,\n    showLinks,\n    showGroups,\n    renderBypass,\n    renderError,\n    containerStyles,\n    panelStyles\n  } = settings\n\n  const updateOption = async (key: MinimapSettingsKey, value: boolean) => {\n    await settingStore.set(key, value)\n    renderer.forceFullRedraw()\n    renderer.updateMinimap(viewport.updateBounds, viewport.updateViewport)\n  }\n\n  // Viewport management\n  const viewport = useMinimapViewport(canvas, graph, width, height)\n\n  // Interaction handling\n  const interaction = useMinimapInteraction(\n    containerRef,\n    viewport.bounds,\n    viewport.scale,\n    width,\n    height,\n    viewport.centerViewOn,\n    canvas\n  )\n\n  // Two of the three useMinimap() call sites have no canvas. updateBounds()\n  // runs before renderMinimap discovers there is nothing to draw, and it costs\n  // a full layout-map rebuild, so every path that redraws checks this first.\n  const canDraw = computed(() => visible.value && !!canvasRef.value)\n\n  // Graph events are hints to compare the digests, not commands to repaint:\n  // graphChanged fires for plenty the minimap does not draw (zIndex from every\n  // widget pointerdown, widget values, title edits), and the digest is the one\n  // place that knows whether the picture moved.\n  const checkAndRepaint = () => {\n    if (!canDraw.value) return\n    if (graphManager.checkForChanges()) {\n      renderer.updateMinimap(viewport.updateBounds, viewport.updateViewport)\n    }\n  }\n\n  const graphManager = useMinimapGraph(graph, () => checkAndRepaint())\n\n  // Rendering\n  const renderer = useMinimapRenderer(\n    canvasRef,\n    graph,\n    viewport.bounds,\n    viewport.scale,\n    graphManager.updateFlags,\n    settings,\n    width,\n    height,\n    decorations\n  )\n\n  const decorationFrames = useRafFn(\n    () => {\n      const now = performance.now()\n      if (\n        !canDraw.value ||\n        decorations.value.every(\n          ({ enteredAt }) =>\n            enteredAt === undefined ||\n            now - enteredAt >= MINIMAP_DECORATION_POP_MS\n        )\n      ) {\n        decorationFrames.pause()\n        return\n      }\n      renderer.forceFullRedraw()\n      renderer.updateMinimap(viewport.updateBounds, viewport.updateViewport)\n    },\n    { immediate: false }\n  )\n\n  const shouldAnimateDecorations = computed(\n    () =>\n      initialized.value &&\n      canDraw.value &&\n      decorations.value.some(\n        ({ enteredAt }) =>\n          enteredAt !== undefined &&\n          performance.now() - enteredAt < MINIMAP_DECORATION_POP_MS\n      )\n  )\n\n  watch(\n    shouldAnimateDecorations,\n    (active) => {\n      if (!initialized.value || !canDraw.value) {\n        decorationFrames.pause()\n        return\n      }\n      renderer.forceFullRedraw()\n      renderer.updateMinimap(viewport.updateBounds, viewport.updateViewport)\n      if (active) decorationFrames.resume()\n      else decorationFrames.pause()\n    },\n    { immediate: true }\n  )\n\n  // Most edits reach the digest comparison through useMinimapGraph's event\n  // hooks. This loop is the backstop for state that emits no event at all:\n  // snapPoint mutating `_pos` elements in place, extensions assigning\n  // `node.pos[0]` directly (only `size` is Proxy-wrapped against that),\n  // `has_errors`, group drags, and execution-state transitions, which arrive\n  // in executionStore rather than as graph events. Repaints happen only when\n  // the digests move, so idle ticks cost one O(n) comparison and nothing else.\n  const { pause: pauseChangeDetection, resume: resumeChangeDetection } =\n    useIntervalFn(checkAndRepaint, CHANGE_DETECTION_INTERVAL_MS, {\n      immediate: false\n    })\n\n  // Polling is derived state, not something init() decides once. init() runs\n  // synchronously from the immediate canvas watcher - before the template ref\n  // has mounted - so any start decision taken there sees canvasRef as null and\n  // the poll never starts. Deriving from the refs means the loop starts the\n  // moment the canvas mounts and stops the moment any condition lapses.\n  //\n  // Document visibility is part of the condition because rAF was suspended\n  // entirely on a hidden tab while setInterval is only clamped, and a tab that\n  // is hidden at mount (middle-click, session restore) never fires a\n  // visibilitychange to a transition-only watcher.\n  const documentVisibility = useDocumentVisibility()\n  const shouldPoll = computed(\n    () =>\n      initialized.value &&\n      canDraw.value &&\n      documentVisibility.value !== 'hidden'\n  )\n\n  watch(\n    shouldPoll,\n    (active) => {\n      if (active) resumeChangeDetection()\n      else pauseChangeDetection()\n    },\n    { immediate: true }\n  )\n\n  const init = async () => {\n    if (initialized.value) return\n\n    visible.value = settingStore.get('Comfy.Minimap.Visible')\n\n    if (canvas.value && graph.value) {\n      graphManager.init()\n\n      if (containerRef.value) {\n        interaction.updateContainerRect()\n      }\n      viewport.updateCanvasDimensions()\n\n      window.addEventListener('resize', interaction.updateContainerRect)\n      window.addEventListener('scroll', interaction.updateContainerRect)\n      window.addEventListener('resize', viewport.updateCanvasDimensions)\n\n      renderer.forceFullRedraw()\n      renderer.updateMinimap(viewport.updateBounds, viewport.updateViewport)\n      viewport.updateViewport()\n\n      if (visible.value) viewport.startViewportSync()\n      initialized.value = true\n    }\n  }\n\n  const destroy = () => {\n    pauseChangeDetection()\n    decorationFrames.pause()\n    viewport.stopViewportSync()\n    graphManager.destroy()\n\n    window.removeEventListener('resize', interaction.updateContainerRect)\n    window.removeEventListener('scroll', interaction.updateContainerRect)\n    window.removeEventListener('resize', viewport.updateCanvasDimensions)\n\n    initialized.value = false\n  }\n\n  watch(\n    canvas,\n    async (newCanvas, oldCanvas) => {\n      if (oldCanvas) {\n        graphManager.cleanupEventListeners()\n        pauseChangeDetection()\n        viewport.stopViewportSync()\n        graphManager.destroy()\n        window.removeEventListener('resize', interaction.updateContainerRect)\n        window.removeEventListener('scroll', interaction.updateContainerRect)\n        window.removeEventListener('resize', viewport.updateCanvasDimensions)\n      }\n      if (newCanvas && !initialized.value) {\n        await init()\n      }\n    },\n    { immediate: true, flush: 'post' }\n  )\n\n  // Watch for graph changes (e.g., when navigating to/from subgraphs)\n  watch(graph, (newGraph, oldGraph) => {\n    if (newGraph && newGraph !== oldGraph) {\n      graphManager.cleanupEventListeners(oldGraph || undefined)\n      graphManager.setupEventListeners()\n      if (!canDraw.value) return\n      renderer.forceFullRedraw()\n      renderer.updateMinimap(viewport.updateBounds, viewport.updateViewport)\n    }\n  })\n\n  watch(visible, async (isVisible) => {\n    if (isVisible) {\n      if (containerRef.value) {\n        interaction.updateContainerRect()\n      }\n      viewport.updateCanvasDimensions()\n\n      renderer.forceFullRedraw()\n\n      await nextTick()\n      await nextTick()\n\n      renderer.updateMinimap(viewport.updateBounds, viewport.updateViewport)\n      viewport.updateViewport()\n      viewport.startViewportSync()\n    } else {\n      viewport.stopViewportSync()\n    }\n  })\n\n  const toggle = async () => {\n    visible.value = !visible.value\n    await settingStore.set('Comfy.Minimap.Visible', visible.value)\n  }\n\n  const setMinimapRef = (ref: HTMLElement | null) => {\n    minimapRef.value = ref\n  }\n\n  // Dynamic viewport styles based on actual viewport transform\n  const viewportStyles = computed(() => {\n    const transform = viewport.viewportTransform.value\n    return {\n      transform: `translate(${transform.x}px, ${transform.y}px)`,\n      width: `${transform.width}px`,\n      height: `${transform.height}px`,\n      border: `2px solid ${settings.isLightTheme.value ? '#E0E0E0' : '#FFF'}`,\n      backgroundColor: `rgba(255, 255, 255, 0.2)`,\n      willChange: 'transform',\n      backfaceVisibility: 'hidden' as const,\n      perspective: '1000px',\n      pointerEvents: 'none' as const\n    }\n  })\n\n  return {\n    visible: computed(() => visible.value),\n    initialized: computed(() => initialized.value),\n    decorationCount: computed(() => decorations.value.length),\n\n    containerStyles,\n    viewportStyles,\n    panelStyles,\n    width,\n    height,\n\n    nodeColors,\n    showLinks,\n    showGroups,\n    renderBypass,\n    renderError,\n\n    init,\n    destroy,\n    toggle,\n    renderMinimap: renderer.renderMinimap,\n    handlePointerDown: interaction.handlePointerDown,\n    handlePointerMove: interaction.handlePointerMove,\n    handlePointerUp: interaction.handlePointerUp,\n    handlePointerCancel: interaction.handlePointerCancel,\n    handleWheel: interaction.handleWheel,\n    setMinimapRef,\n    updateOption\n  }\n}\n","<template>\n  <Button\n    ref=\"buttonRef\"\n    variant=\"secondary\"\n    class=\"group h-8 rounded-none! bg-transparent p-0 transition-none! hover:rounded-lg! hover:bg-interface-button-hover-surface!\"\n    :style=\"buttonStyles\"\n    :aria-label=\"$t('graphCanvasMenu.canvasMode')\"\n    aria-haspopup=\"menu\"\n    :aria-expanded=\"isOpen\"\n    @click=\"toggle\"\n  >\n    <div class=\"flex items-center gap-1 pr-0.5\">\n      <div\n        class=\"rounded-lg bg-interface-panel-selected-surface p-2 group-hover:bg-interface-button-hover-surface\"\n      >\n        <i :class=\"currentModeIcon\" class=\"block size-4\" aria-hidden=\"true\" />\n      </div>\n      <i\n        class=\"icon-[lucide--chevron-down] block size-4 pr-1.5\"\n        aria-hidden=\"true\"\n      />\n    </div>\n  </Button>\n\n  <Popover\n    ref=\"popover\"\n    side=\"top\"\n    :side-offset=\"8\"\n    :content-class=\"cn(menuContentClass, 'min-w-39 select-none')\"\n    @show=\"onPopoverShow\"\n    @hide=\"onPopoverHide\"\n  >\n    <div\n      ref=\"menuRef\"\n      class=\"flex flex-col\"\n      role=\"menu\"\n      :aria-label=\"$t('graphCanvasMenu.canvasMode')\"\n    >\n      <button\n        type=\"button\"\n        role=\"menuitemradio\"\n        :aria-checked=\"!isCanvasReadOnly\"\n        :tabindex=\"!isCanvasReadOnly ? 0 : -1\"\n        :class=\"cn(menuButtonClass, 'justify-between')\"\n        :aria-label=\"$t('graphCanvasMenu.select')\"\n        @click=\"setMode('select')\"\n        @keydown.arrow-down.prevent=\"focusNextItem\"\n        @keydown.arrow-up.prevent=\"focusPrevItem\"\n        @keydown.escape.prevent=\"closeAndRestoreFocus\"\n      >\n        <div class=\"flex items-center gap-2\">\n          <i class=\"icon-[lucide--mouse-pointer-2] size-4\" aria-hidden=\"true\" />\n          <span>{{ $t('graphCanvasMenu.select') }}</span>\n        </div>\n        <span\n          class=\"text-[9px] text-text-primary\"\n          data-testid=\"shortcut-hint\"\n          >{{ unlockCommandText }}</span\n        >\n      </button>\n\n      <button\n        type=\"button\"\n        role=\"menuitemradio\"\n        :aria-checked=\"isCanvasReadOnly\"\n        :tabindex=\"isCanvasReadOnly ? 0 : -1\"\n        :class=\"cn(menuButtonClass, 'justify-between')\"\n        :aria-label=\"$t('graphCanvasMenu.hand')\"\n        @click=\"setMode('hand')\"\n        @keydown.arrow-down.prevent=\"focusNextItem\"\n        @keydown.arrow-up.prevent=\"focusPrevItem\"\n        @keydown.escape.prevent=\"closeAndRestoreFocus\"\n      >\n        <div class=\"flex items-center gap-2\">\n          <i class=\"icon-[lucide--hand] size-4\" aria-hidden=\"true\" />\n          <span>{{ $t('graphCanvasMenu.hand') }}</span>\n        </div>\n        <span\n          class=\"text-[9px] text-text-primary\"\n          data-testid=\"shortcut-hint\"\n          >{{ lockCommandText }}</span\n        >\n      </button>\n    </div>\n  </Popover>\n</template>\n\n<script setup lang=\"ts\">\nimport Popover from '@/components/common/ImperativePopover.vue'\nimport type { ComponentPublicInstance } from 'vue'\nimport { computed, nextTick, ref } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport {\n  menuButtonClass,\n  menuContentClass\n} from '@/components/ui/menu/menuStyles'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ninterface Props {\n  buttonStyles?: Record<string, string>\n}\n\ndefineProps<Props>()\nconst buttonRef = ref<ComponentPublicInstance | null>(null)\nconst popover = ref<InstanceType<typeof Popover>>()\nconst menuRef = ref<HTMLElement | null>(null)\nconst isOpen = ref(false)\nconst commandStore = useCommandStore()\nconst canvasStore = useCanvasStore()\n\nconst isCanvasReadOnly = computed(() => canvasStore.canvas?.read_only ?? false)\n\nconst currentModeIcon = computed(() =>\n  isCanvasReadOnly.value\n    ? 'icon-[lucide--hand]'\n    : 'icon-[lucide--mouse-pointer-2]'\n)\n\nconst unlockCommandText = computed(() =>\n  commandStore\n    .formatKeySequence(commandStore.getCommand('Comfy.Canvas.Unlock'))\n    .toUpperCase()\n)\n\nconst lockCommandText = computed(() =>\n  commandStore\n    .formatKeySequence(commandStore.getCommand('Comfy.Canvas.Lock'))\n    .toUpperCase()\n)\n\nconst toggle = (event: Event) => {\n  const el = buttonRef.value?.$el || buttonRef.value\n  popover.value?.toggle(event, el)\n}\n\nconst setMode = (mode: 'select' | 'hand') => {\n  if (mode === 'select' && isCanvasReadOnly.value) {\n    void commandStore.execute('Comfy.Canvas.Unlock')\n  } else if (mode === 'hand' && !isCanvasReadOnly.value) {\n    void commandStore.execute('Comfy.Canvas.Lock')\n  }\n  popover.value?.hide()\n}\n\nasync function onPopoverShow() {\n  isOpen.value = true\n  await nextTick()\n  const checkedItem = menuRef.value?.querySelector<HTMLElement>(\n    '[aria-checked=\"true\"]'\n  )\n  checkedItem?.focus()\n}\n\nfunction onPopoverHide() {\n  isOpen.value = false\n}\n\nfunction closeAndRestoreFocus() {\n  popover.value?.hide()\n  const el = buttonRef.value?.$el || buttonRef.value\n  ;(el as HTMLElement)?.focus()\n}\n\nfunction focusNextItem(event: KeyboardEvent) {\n  const items = getMenuItems(event)\n  const index = items.indexOf(event.target as HTMLElement)\n  items[(index + 1) % items.length]?.focus()\n}\n\nfunction focusPrevItem(event: KeyboardEvent) {\n  const items = getMenuItems(event)\n  const index = items.indexOf(event.target as HTMLElement)\n  items[(index - 1 + items.length) % items.length]?.focus()\n}\n\nfunction getMenuItems(event: KeyboardEvent): HTMLElement[] {\n  const menu = (event.target as HTMLElement).closest('[role=\"menu\"]')\n  if (!menu) return []\n  return Array.from(menu.querySelectorAll('[role=\"menuitemradio\"]'))\n}\n</script>\n","<template>\n  <div\n    v-if=\"visible\"\n    ref=\"modalRoot\"\n    class=\"absolute right-0 bottom-[62px] z-1300 flex w-[250px] justify-center border-0! bg-inherit!\"\n  >\n    <div\n      class=\"w-4/5 rounded-lg border border-interface-stroke bg-interface-panel-surface p-2 text-text-primary shadow-lg select-none\"\n      :style=\"filteredMinimapStyles\"\n      @click.stop\n    >\n      <div class=\"flex flex-col gap-1\">\n        <div\n          class=\"flex cursor-pointer items-center justify-between rounded-sm px-3 py-2 text-sm hover:bg-node-component-surface-hovered\"\n          data-testid=\"zoom-in-action\"\n          @mousedown=\"startRepeat('Comfy.Canvas.ZoomIn')\"\n          @mouseup=\"stopRepeat\"\n          @mouseleave=\"stopRepeat\"\n        >\n          <span class=\"font-medium\">{{ $t('graphCanvasMenu.zoomIn') }}</span>\n          <span class=\"text-[9px] text-text-primary\">{{\n            zoomInCommandText\n          }}</span>\n        </div>\n\n        <div\n          class=\"flex cursor-pointer items-center justify-between rounded-sm px-3 py-2 text-sm hover:bg-node-component-surface-hovered\"\n          data-testid=\"zoom-out-action\"\n          @mousedown=\"startRepeat('Comfy.Canvas.ZoomOut')\"\n          @mouseup=\"stopRepeat\"\n          @mouseleave=\"stopRepeat\"\n        >\n          <span class=\"font-medium\">{{ $t('graphCanvasMenu.zoomOut') }}</span>\n          <span class=\"text-[9px] text-text-primary\">{{\n            zoomOutCommandText\n          }}</span>\n        </div>\n\n        <div\n          class=\"flex cursor-pointer items-center justify-between rounded-sm px-3 py-2 text-sm hover:bg-node-component-surface-hovered\"\n          data-testid=\"zoom-to-fit-action\"\n          @click=\"executeCommand('Comfy.Canvas.FitView')\"\n        >\n          <span class=\"font-medium\">{{ $t('zoomControls.zoomToFit') }}</span>\n          <span class=\"text-[9px] text-text-primary\">{{\n            zoomToFitCommandText\n          }}</span>\n        </div>\n\n        <NumberField\n          :model-value=\"canvasStore.appScalePercentage\"\n          :min=\"1\"\n          :max=\"1000\"\n          :format-options=\"{ useGrouping: false, maximumFractionDigits: 0 }\"\n          data-testid=\"zoom-percentage-input\"\n          @update:model-value=\"canvasStore.setAppZoomFromPercentage\"\n        >\n          <NumberFieldDecrement />\n          <NumberFieldInput :aria-label=\"$t('zoomControls.zoomPercentage')\" />\n          <span class=\"shrink-0 text-sm text-text-primary\">%</span>\n          <NumberFieldIncrement />\n        </NumberField>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, nextTick, ref, useTemplateRef, watch } from 'vue'\n\nimport NumberField from '@/components/ui/number-field/NumberField.vue'\nimport NumberFieldDecrement from '@/components/ui/number-field/NumberFieldDecrement.vue'\nimport NumberFieldIncrement from '@/components/ui/number-field/NumberFieldIncrement.vue'\nimport NumberFieldInput from '@/components/ui/number-field/NumberFieldInput.vue'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useMinimap } from '@/renderer/extensions/minimap/composables/useMinimap'\nimport { useCommandStore } from '@/stores/commandStore'\n\nconst minimap = useMinimap()\nconst commandStore = useCommandStore()\nconst canvasStore = useCanvasStore()\nconst { formatKeySequence } = useCommandStore()\n\ninterface Props {\n  visible: boolean\n}\n\nconst props = defineProps<Props>()\n\nconst interval = ref<number | null>(null)\n\nconst executeCommand = (command: string) => {\n  void commandStore.execute(command)\n}\n\nconst startRepeat = (command: string) => {\n  if (interval.value) return\n  const cmd = () => commandStore.execute(command)\n  void cmd()\n  interval.value = window.setInterval(cmd, 100)\n}\n\nconst stopRepeat = () => {\n  if (interval.value) {\n    clearInterval(interval.value)\n    interval.value = null\n  }\n}\nconst filteredMinimapStyles = computed(() => {\n  return {\n    ...minimap.containerStyles.value,\n    height: undefined,\n    width: undefined\n  }\n})\nconst zoomInCommandText = computed(() =>\n  formatKeySequence(commandStore.getCommand('Comfy.Canvas.ZoomIn'))\n)\nconst zoomOutCommandText = computed(() =>\n  formatKeySequence(commandStore.getCommand('Comfy.Canvas.ZoomOut'))\n)\nconst zoomToFitCommandText = computed(() =>\n  formatKeySequence(commandStore.getCommand('Comfy.Canvas.FitView'))\n)\nconst modalRoot = useTemplateRef<HTMLDivElement>('modalRoot')\n\nwatch(\n  () => props.visible,\n  async (visible) => {\n    if (!visible) return\n    await nextTick()\n    modalRoot.value?.querySelector('input')?.focus()\n  }\n)\n</script>\n","<template>\n  <div>\n    <ZoomControlsModal :visible=\"isModalVisible\" @close=\"hideModal\" />\n\n    <!-- Backdrop -->\n    <div\n      v-if=\"hasActivePopup\"\n      class=\"fixed inset-0 z-1200\"\n      @click=\"hideModal\"\n    ></div>\n\n    <!-- Right-anchoring alone lets a toolbar wider than the canvas overhang its\n         left edge and cover the sidebar. Spanning the canvas and pushing with an\n         auto margin pins the toolbar to the right instead, and the width cap keeps\n         any overflow inside the canvas as a scroll. -->\n    <div class=\"pointer-events-none absolute inset-x-0 bottom-0 z-1200 flex\">\n      <div\n        role=\"toolbar\"\n        :aria-label=\"t('graphCanvasMenu.canvasToolbar')\"\n        class=\"pointer-events-auto ml-auto flex max-w-full min-w-0 gap-1 overflow-x-auto floating-panel\"\n        @wheel=\"canvasInteractions.handleWheel\"\n      >\n        <CanvasModeSelector\n          :button-styles=\"stringifiedMinimapStyles.buttonStyles\"\n        />\n\n        <div class=\"h-[27px] w-px self-center bg-node-divider\" />\n\n        <Button\n          :tooltip=\"fitViewLabel\"\n          variant=\"secondary\"\n          :aria-label=\"fitViewLabel\"\n          :style=\"stringifiedMinimapStyles.buttonStyles\"\n          class=\"size-8 bg-transparent p-0 hover:bg-interface-button-hover-surface\"\n          @click=\"() => commandStore.execute('Comfy.Canvas.FitView')\"\n        >\n          <i class=\"icon-[lucide--focus] size-4\" aria-hidden=\"true\" />\n        </Button>\n\n        <Button\n          :tooltip=\"t('zoomControls.label')\"\n          variant=\"secondary\"\n          :class=\"\n            cn(\n              'h-8 w-15 bg-transparent p-0 hover:bg-interface-button-hover-surface',\n              isModalVisible && 'not-active:bg-interface-panel-selected-surface'\n            )\n          \"\n          :aria-label=\"t('zoomControls.label')\"\n          data-testid=\"zoom-controls-button\"\n          :style=\"stringifiedMinimapStyles.buttonStyles\"\n          @click=\"toggleModal\"\n        >\n          <span class=\"inline-flex items-center gap-1 px-2 text-xs\">\n            <span>{{ canvasStore.appScalePercentage }}%</span>\n            <i class=\"icon-[lucide--chevron-down] size-4\" aria-hidden=\"true\" />\n          </span>\n        </Button>\n\n        <div class=\"h-[27px] w-px self-center bg-node-divider\" />\n\n        <Button\n          :tooltip=\"minimapLabel\"\n          variant=\"secondary\"\n          :aria-label=\"minimapLabel\"\n          data-testid=\"toggle-minimap-button\"\n          :style=\"stringifiedMinimapStyles.buttonStyles\"\n          :class=\"\n            cn(\n              'size-8 bg-transparent p-0 hover:bg-interface-button-hover-surface',\n              settingStore.get('Comfy.Minimap.Visible') &&\n                'not-active:bg-interface-panel-selected-surface'\n            )\n          \"\n          @click=\"onMinimapToggleClick\"\n        >\n          <i class=\"icon-[lucide--map] size-4\" aria-hidden=\"true\" />\n        </Button>\n\n        <Button\n          :tooltip=\"linkVisibilityLabel\"\n          variant=\"secondary\"\n          :class=\"\n            cn(\n              'size-8 bg-transparent p-0 hover:bg-interface-button-hover-surface',\n              linkHidden && 'not-active:bg-interface-panel-selected-surface'\n            )\n          \"\n          :aria-label=\"linkVisibilityLabel\"\n          data-testid=\"toggle-link-visibility-button\"\n          :style=\"stringifiedMinimapStyles.buttonStyles\"\n          @click=\"onLinkVisibilityToggleClick\"\n        >\n          <i class=\"icon-[lucide--route-off] size-4\" aria-hidden=\"true\" />\n        </Button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onBeforeUnmount, onMounted } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useZoomControls } from '@/composables/useZoomControls'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport { useMinimap } from '@/renderer/extensions/minimap/composables/useMinimap'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport CanvasModeSelector from './CanvasModeSelector.vue'\nimport ZoomControlsModal from './modals/ZoomControlsModal.vue'\n\nconst { t } = useI18n()\nconst commandStore = useCommandStore()\nconst { formatKeySequence } = useCommandStore()\nconst canvasStore = useCanvasStore()\nconst settingStore = useSettingStore()\nconst canvasInteractions = useCanvasInteractions()\nconst minimap = useMinimap()\n\nconst { isModalVisible, toggleModal, hideModal, hasActivePopup } =\n  useZoomControls()\n\nconst stringifiedMinimapStyles = computed(() => {\n  const buttonKeys = ['borderRadius']\n  const additionalButtonStyles = {\n    border: 'none'\n  }\n\n  const containerStyles = minimap.containerStyles.value\n\n  const buttonStyles = {\n    ...Object.fromEntries(\n      Object.entries(containerStyles).filter(([key]) =>\n        buttonKeys.includes(key)\n      )\n    ),\n    ...additionalButtonStyles\n  }\n  return { buttonStyles }\n})\n\n// Computed properties for reactive states\nconst linkHidden = computed(\n  () => settingStore.get('Comfy.LinkRenderMode') === LiteGraph.HIDDEN_LINK\n)\n\n// Computed properties for command text\nconst fitViewCommandText = computed(() =>\n  formatKeySequence(\n    commandStore.getCommand('Comfy.Canvas.FitView')\n  ).toUpperCase()\n)\nconst minimapCommandText = computed(() =>\n  formatKeySequence(\n    commandStore.getCommand('Comfy.Canvas.ToggleMinimap')\n  ).toUpperCase()\n)\n\n// Computed properties for tooltip and aria-label texts\nconst fitViewLabel = computed(() => {\n  const label = t('graphCanvasMenu.fitView')\n  const shortcut = fitViewCommandText.value\n  return shortcut ? `${label} (${shortcut})` : label\n})\nconst minimapLabel = computed(() => {\n  const label = settingStore.get('Comfy.Minimap.Visible')\n    ? t('zoomControls.hideMinimap')\n    : t('zoomControls.showMinimap')\n  const shortcut = minimapCommandText.value\n  return shortcut ? `${label} (${shortcut})` : label\n})\nconst linkVisibilityLabel = computed(() =>\n  linkHidden.value\n    ? t('graphCanvasMenu.showLinks')\n    : t('graphCanvasMenu.hideLinks')\n)\nonMounted(() => {\n  canvasStore.initScaleSync()\n})\n\n/**\n * Track minimap toggle button click and execute the command.\n */\nconst onMinimapToggleClick = () => {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'graph_menu_minimap_toggle_clicked',\n    element_group: 'graph_menu'\n  })\n  void commandStore.execute('Comfy.Canvas.ToggleMinimap')\n}\n\n/**\n * Track hide/show links button click and execute the command.\n */\nconst onLinkVisibilityToggleClick = () => {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'graph_menu_hide_links_toggle_clicked',\n    element_group: 'graph_menu'\n  })\n  void commandStore.execute('Comfy.Canvas.ToggleLinkVisibility')\n}\n\nonBeforeUnmount(() => {\n  canvasStore.cleanupScaleSync()\n})\n</script>\n","import type {\n  LGraph,\n  LGraphCanvas,\n  LGraphNode\n} from '@/lib/litegraph/src/litegraph'\nimport type { useExecutionStore } from '@/stores/executionStore'\nimport type { NodeLocatorId } from '@/types/nodeIdentification'\n\ntype ProgressStates = Readonly<\n  ReturnType<typeof useExecutionStore>['nodeLocationProgressStates']\n>\ntype ProgressState = ProgressStates[NodeLocatorId]\n\nexport interface NodeProgressCanvasSync {\n  dispose: () => void\n  sync: (\n    states: ProgressStates,\n    canvas: LGraphCanvas | null,\n    graph: LGraph | null\n  ) => void\n}\n\nfunction progressValue(state: ProgressState | undefined) {\n  return state?.state === 'running' ? state.value / state.max : undefined\n}\n\nexport function createNodeProgressCanvasSync(\n  nodeToLocator: (node: LGraphNode) => NodeLocatorId\n): NodeProgressCanvasSync {\n  let activeCanvas: LGraphCanvas | null = null\n  let activeGraph: LGraph | null = null\n  let activeStates: ProgressStates = {}\n  let nodeLocators = new WeakMap<LGraphNode, NodeLocatorId>()\n  const nodesByLocator = new Map<NodeLocatorId, LGraphNode[]>()\n\n  function markDirty() {\n    activeCanvas?.setDirty(true, false)\n  }\n\n  function setNodeProgress(node: LGraphNode, nextProgress: number | undefined) {\n    if (Object.is(node.progress, nextProgress)) return false\n    node.progress = nextProgress\n    return true\n  }\n\n  function addNode(node: LGraphNode) {\n    const locator = nodeToLocator(node)\n    nodeLocators.set(node, locator)\n    const nodes = nodesByLocator.get(locator)\n    if (nodes) nodes.push(node)\n    else nodesByLocator.set(locator, [node])\n    return locator\n  }\n\n  function removeNode(node: LGraphNode) {\n    const locator = nodeLocators.get(node)\n    if (!locator) return\n    const nodes = nodesByLocator.get(locator)\n    if (!nodes) return\n    const nextNodes = nodes.filter((candidate) => candidate !== node)\n    if (nextNodes.length) nodesByLocator.set(locator, nextNodes)\n    else nodesByLocator.delete(locator)\n    nodeLocators.delete(node)\n  }\n\n  function onNodeAdded(event: CustomEvent<{ node: LGraphNode }>) {\n    const node = event.detail.node\n    const locator = addNode(node)\n    if (setNodeProgress(node, progressValue(activeStates[locator]))) markDirty()\n  }\n\n  function onNodeRemoved(event: CustomEvent<{ node: LGraphNode }>) {\n    removeNode(event.detail.node)\n  }\n\n  function detachGraph() {\n    activeGraph?.events.removeEventListener('node:added', onNodeAdded)\n    activeGraph?.events.removeEventListener(\n      'node:before-removed',\n      onNodeRemoved\n    )\n  }\n\n  function replaceGraph(graph: LGraph | null) {\n    detachGraph()\n    activeGraph = graph\n    nodesByLocator.clear()\n    nodeLocators = new WeakMap()\n    if (!graph) return false\n\n    let progressChanged = false\n    for (const node of graph.nodes) {\n      const locator = addNode(node)\n      progressChanged =\n        setNodeProgress(node, progressValue(activeStates[locator])) ||\n        progressChanged\n    }\n    graph.events.addEventListener('node:added', onNodeAdded)\n    graph.events.addEventListener('node:before-removed', onNodeRemoved)\n    return progressChanged\n  }\n\n  function sync(\n    states: ProgressStates,\n    canvas: LGraphCanvas | null,\n    graph: LGraph | null\n  ) {\n    const previousStates = activeStates\n    activeCanvas = canvas\n    activeStates = states\n\n    if (graph !== activeGraph) {\n      if (replaceGraph(graph)) markDirty()\n      return\n    }\n\n    let progressChanged = false\n    const changedLocators = new Set([\n      ...Object.keys(previousStates),\n      ...Object.keys(states)\n    ] as NodeLocatorId[])\n    for (const locator of changedLocators) {\n      const previousProgress = progressValue(previousStates[locator])\n      const nextProgress = progressValue(states[locator])\n      if (Object.is(previousProgress, nextProgress)) continue\n      for (const node of nodesByLocator.get(locator) ?? []) {\n        progressChanged = setNodeProgress(node, nextProgress) || progressChanged\n      }\n    }\n    if (progressChanged) markDirty()\n  }\n\n  function dispose() {\n    detachGraph()\n    activeCanvas = null\n    activeGraph = null\n    activeStates = {}\n    nodesByLocator.clear()\n    nodeLocators = new WeakMap()\n  }\n\n  return { dispose, sync }\n}\n","<template>\n  <canvas\n    ref=\"canvasRef\"\n    class=\"pointer-events-none absolute inset-0 size-full\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport type { LGraphCanvas } from '@/lib/litegraph/src/LGraphCanvas'\n\nimport { useRafFn } from '@vueuse/core'\nimport { onBeforeUnmount, onMounted, ref } from 'vue'\n\nconst { canvas } = defineProps<{\n  canvas: LGraphCanvas\n}>()\n\nconst emit = defineEmits<{\n  ready: [canvas: HTMLCanvasElement]\n  dispose: []\n}>()\n\nconst canvasRef = ref<HTMLCanvasElement | null>(null)\n\nuseRafFn(() => {\n  const el = canvasRef.value\n  const mainCanvas = canvas.canvas\n  if (!el || !mainCanvas) return\n\n  if (el.width !== mainCanvas.width || el.height !== mainCanvas.height) {\n    el.width = mainCanvas.width\n    el.height = mainCanvas.height\n  }\n})\n\nonMounted(() => {\n  if (canvasRef.value) emit('ready', canvasRef.value)\n})\n\nonBeforeUnmount(() => {\n  emit('dispose')\n})\n</script>\n","<template>\n  <div\n    v-show=\"tooltipText\"\n    ref=\"tooltipRef\"\n    class=\"node-tooltip\"\n    :style=\"{ left, top }\"\n  >\n    {{ tooltipText }}\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useEventListener } from '@vueuse/core'\nimport { nextTick, ref } from 'vue'\n\nimport { resolveNodeDefSlotText, resolveNodeDefText } from '@/i18n'\nimport {\n  LiteGraph,\n  isOverNodeInput,\n  isOverNodeOutput\n} from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { app as comfyApp } from '@/scripts/app'\nimport { isDOMWidget } from '@/scripts/domWidget'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\n\nlet idleTimeout: number\nconst nodeDefStore = useNodeDefStore()\nconst settingStore = useSettingStore()\nconst tooltipRef = ref<HTMLDivElement | undefined>()\nconst tooltipText = ref('')\nconst left = ref<string>()\nconst top = ref<string>()\n\nfunction hideTooltip() {\n  if (!tooltipText.value) return\n  tooltipText.value = ''\n}\n\nasync function showTooltip(tooltip: string | null | undefined) {\n  if (!tooltip) return\n\n  left.value = comfyApp.canvas.mouse[0] + 'px'\n  top.value = comfyApp.canvas.mouse[1] + 'px'\n  tooltipText.value = tooltip\n\n  await nextTick()\n\n  const rect = tooltipRef.value?.getBoundingClientRect()\n  if (!rect) return\n\n  if (rect.right > window.innerWidth) {\n    left.value = comfyApp.canvas.mouse[0] - rect.width + 'px'\n  }\n\n  if (rect.top < 0) {\n    top.value = comfyApp.canvas.mouse[1] + rect.height + 'px'\n  }\n}\n\nfunction onIdle() {\n  const { canvas } = comfyApp\n  const node = canvas?.node_over\n  if (!node || node.flags?.ghost) return\n\n  const ctor = node.constructor as { title_mode?: 0 | 1 | 2 | 3 }\n  const nodeType = node.type ?? ''\n  const nodeDef = nodeDefStore.nodeDefsByName[nodeType]\n\n  if (\n    ctor.title_mode !== LiteGraph.NO_TITLE &&\n    canvas.graph_mouse[1] < node.pos[1] // If we are over a node, but not within the node then we are on its title\n  ) {\n    return showTooltip(\n      resolveNodeDefText('description', nodeType, nodeDef?.description)\n    )\n  }\n\n  if (node.flags?.collapsed) return\n\n  const inputSlot = isOverNodeInput(\n    node,\n    canvas.graph_mouse[0],\n    canvas.graph_mouse[1],\n    [0, 0]\n  )\n  if (inputSlot !== -1) {\n    const inputName = node.inputs[inputSlot].name\n    return showTooltip(\n      resolveNodeDefSlotText(\n        'tooltip',\n        nodeType,\n        inputName,\n        nodeDef?.inputs[inputName]?.tooltip\n      )\n    )\n  }\n\n  const outputSlot = isOverNodeOutput(\n    node,\n    canvas.graph_mouse[0],\n    canvas.graph_mouse[1],\n    [0, 0]\n  )\n  if (outputSlot !== -1) {\n    return showTooltip(\n      resolveNodeDefSlotText(\n        'tooltip',\n        nodeType,\n        outputSlot,\n        nodeDef?.outputs[outputSlot]?.tooltip\n      )\n    )\n  }\n\n  const widget = comfyApp.canvas.getWidgetAtCursor()\n  // Dont show for DOM widgets, these use native browser tooltips as we dont get proper mouse events on these\n  if (widget && !isDOMWidget(widget)) {\n    const translatedTooltip = resolveNodeDefSlotText(\n      'tooltip',\n      nodeType,\n      widget.name,\n      nodeDef?.inputs[widget.name]?.tooltip\n    )\n    // Widget tooltip can be set dynamically, current translation collection does not support this.\n    return showTooltip(widget.tooltip ?? translatedTooltip)\n  }\n}\n\nconst onMouseMove = (e: MouseEvent) => {\n  hideTooltip()\n  clearTimeout(idleTimeout)\n\n  if ((e.target as Node).nodeName !== 'CANVAS') return\n  idleTimeout = window.setTimeout(\n    onIdle,\n    settingStore.get('LiteGraph.Node.TooltipDelay')\n  )\n}\n\nuseEventListener(window, 'mousemove', onMouseMove)\nuseEventListener(window, 'click', hideTooltip)\n</script>\n\n<style lang=\"css\" scoped>\n.node-tooltip {\n  pointer-events: none;\n  background: var(--comfy-input-bg);\n  border-radius: 5px;\n  box-shadow: 0 0 5px rgb(0 0 0 / 0.4);\n  color: var(--input-text);\n  left: 0;\n  max-width: 30vw;\n  padding: 4px 8px;\n  position: absolute;\n  top: 0;\n  transform: translate(5px, calc(-100% - 5px));\n  white-space: pre-wrap;\n  z-index: 99999;\n}\n</style>\n","<template>\n  <ContextMenu\n    ref=\"contextMenu\"\n    :model=\"menuItems\"\n    :reference=\"menuReference\"\n    @show=\"onMenuShow\"\n    @hide=\"onMenuHide\"\n  >\n    <template #item=\"{ item, hasSubmenu }\">\n      <div class=\"flex w-full items-center gap-2\">\n        <span\n          v-if=\"getItemColor(item)\"\n          class=\"size-5 rounded-full border border-border-default\"\n          :style=\"{ backgroundColor: getItemColor(item) }\"\n        />\n        <i v-else-if=\"item.icon\" :class=\"cn(item.icon, 'size-4')\" />\n        <span class=\"flex-1\">{{ item.label }}</span>\n        <span\n          v-if=\"item.shortcut\"\n          class=\"ml-auto rounded-sm border border-border-default bg-secondary-background p-1 text-xs text-nowrap text-muted\"\n        >\n          {{ item.shortcut }}\n        </span>\n        <i\n          v-if=\"hasSubmenu\"\n          class=\"icon-[lucide--chevron-right] size-4 opacity-60\"\n        />\n      </div>\n    </template>\n  </ContextMenu>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { computed, onMounted, onUnmounted, ref } from 'vue'\n\nimport ContextMenu from '@/components/ui/menu/ContextMenu.vue'\nimport { getMenuAnchorPosition } from '@/components/ui/menu/menuAnchor'\nimport type {\n  MenuItem,\n  MenuItemAction,\n  MenuItemRadioGroup,\n  MenuItemSeparator,\n  MenuItemSubmenu\n} from '@/components/ui/menu/types'\nimport {\n  registerNodeOptionsInstance,\n  useMoreOptionsMenu\n} from '@/composables/graph/useMoreOptionsMenu'\nimport type { MenuOption } from '@/composables/graph/useMoreOptionsMenu'\nimport { useNodeCustomization } from '@/composables/graph/useNodeCustomization'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\nconst contextMenu = ref<InstanceType<typeof ContextMenu>>()\nconst isOpen = ref(false)\n\nconst { menuOptions, bump } = useMoreOptionsMenu()\nconst { getCurrentShape } = useNodeCustomization()\nconst canvasStore = useCanvasStore()\n\ninterface NodeMenuMetadata {\n  color?: string\n}\n\ntype NodeMenuAction = MenuItemAction & NodeMenuMetadata\n\ntype NodeMenuSubmenu = Omit<MenuItemSubmenu, 'items'> &\n  NodeMenuMetadata & {\n    items: NodeMenuItem[]\n  }\n\ntype NodeMenuItem =\n  | MenuItemSeparator\n  | NodeMenuAction\n  | NodeMenuSubmenu\n  | MenuItemRadioGroup\n\nfunction getItemColor(item: MenuItem): string | undefined {\n  return 'color' in item && typeof item.color === 'string'\n    ? item.color\n    : undefined\n}\n\nconst worldPosition = ref({ x: 0, y: 0 })\n\nconst lgCanvas = canvasStore.getCanvas()\nconst menuReference = {\n  contextElement: lgCanvas.canvas,\n  getBoundingClientRect() {\n    const { scale, offset } = lgCanvas.ds\n    const { left, top } = lgCanvas.canvas.getBoundingClientRect()\n    return new DOMRect(\n      (worldPosition.value.x + offset[0]) * scale + left,\n      (worldPosition.value.y + offset[1]) * scale + top,\n      1,\n      1\n    )\n  }\n}\n\nfunction convertToMenuItem(option: MenuOption): NodeMenuItem {\n  if (option.type === 'divider') return { separator: true }\n\n  if (option.isShapePicker && option.submenu) {\n    return {\n      label: option.label,\n      icon: option.icon,\n      radioGroup: {\n        value: getCurrentShape()?.localizedName ?? '',\n        options: option.submenu.map((sub) => ({\n          value: sub.label,\n          label: sub.label,\n          command: sub.action\n        }))\n      }\n    }\n  }\n\n  if (option.hasSubmenu && option.submenu) {\n    return {\n      label: option.label,\n      icon: option.icon,\n      disabled: option.disabled,\n      shortcut: option.shortcut,\n      items: option.submenu.map((sub) => ({\n        label: sub.label,\n        icon: sub.icon,\n        color: sub.color,\n        disabled: sub.disabled,\n        command: sub.action\n      }))\n    }\n  }\n\n  return {\n    label: option.label,\n    icon: option.icon,\n    disabled: option.disabled,\n    shortcut: option.shortcut,\n    command: option.action\n  }\n}\n\nconst menuItems = computed<MenuItem[]>(() =>\n  menuOptions.value.map(convertToMenuItem)\n)\n\nfunction prepareMenu(event: Event) {\n  bump()\n\n  const { x, y } = getMenuAnchorPosition(event)\n  const { left, top } = lgCanvas.canvas.getBoundingClientRect()\n  const { scale, offset } = lgCanvas.ds\n  worldPosition.value = {\n    x: (x - left) / scale - offset[0],\n    y: (y - top) / scale - offset[1]\n  }\n}\n\nfunction show(event: MouseEvent) {\n  prepareMenu(event)\n  contextMenu.value?.show(event)\n}\n\nfunction hide() {\n  contextMenu.value?.hide()\n}\n\nfunction toggle(event: Event) {\n  prepareMenu(event)\n  contextMenu.value?.toggle(event)\n}\n\ndefineExpose({ toggle, hide, isOpen, show })\n\nfunction onMenuShow() {\n  isOpen.value = true\n}\n\nfunction onMenuHide() {\n  isOpen.value = false\n}\n\nonMounted(() => {\n  registerNodeOptionsInstance({ toggle, show, hide, isOpen })\n})\n\nonUnmounted(() => {\n  registerNodeOptionsInstance(null)\n})\n</script>\n","import { ref, shallowRef } from 'vue'\n\nimport { t } from '@/i18n'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { withNodeAddSource } from '@/platform/telemetry/nodeAdded/nodeAddSource'\nimport type { NodeAddSource } from '@/platform/telemetry/types'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { matchesWidgetName } from '@/utils/widgetBinding'\nimport type { WidgetValueBinding } from '@/utils/widgetBinding'\n\ntype DragMode = 'click' | 'native'\ntype Position = { x: number; y: number }\n\ninterface StartDragOptions {\n  mode?: DragMode\n  widgetValues?: readonly WidgetValueBinding[]\n  source?: NodeAddSource\n}\n\nconst isDragging = ref(false)\nconst draggedNode = shallowRef<ComfyNodeDefImpl | null>(null)\nconst dragMode = ref<DragMode>('click')\nconst lastNativeDragPosition = shallowRef<Position>()\nconst pendingWidgetValues = shallowRef<readonly WidgetValueBinding[]>()\nconst pendingSource = ref<NodeAddSource>('sidebar_drag')\nlet listenersSetup = false\n\n// Firefox dragend can report stale clientX/Y and `drag` can fire with\n// (0, 0). dragover on the target reliably reports real client coords.\n// https://bugzilla.mozilla.org/show_bug.cgi?id=1773886\nfunction trackNativeDragPosition(e: DragEvent) {\n  if (dragMode.value !== 'native') return\n  if (e.clientX === 0 && e.clientY === 0) return\n  lastNativeDragPosition.value = { x: e.clientX, y: e.clientY }\n}\n\nfunction applyWidgetValues(\n  node: LGraphNode,\n  values: readonly WidgetValueBinding[]\n) {\n  for (const { selector, value } of values) {\n    const widget = node.widgets?.find((w) =>\n      matchesWidgetName(w.name, selector)\n    )\n    if (!widget) {\n      console.error(`Widget ${selector} not found on node ${node.type}`)\n      useToast().warning(t('g.warning'), {\n        description: t('assetBrowser.failedToSetModelValue')\n      })\n      continue\n    }\n    widget.value = value\n  }\n}\n\nfunction isOverCanvas(clientX: number, clientY: number): boolean {\n  const canvasElement = useCanvasStore().canvas?.canvas\n  if (!canvasElement) return false\n  const rect = canvasElement.getBoundingClientRect()\n  return (\n    clientX >= rect.left &&\n    clientX <= rect.right &&\n    clientY >= rect.top &&\n    clientY <= rect.bottom\n  )\n}\n\nfunction addNodeAtPosition(clientX: number, clientY: number): boolean {\n  const nodeDef = draggedNode.value\n  if (!nodeDef) return false\n  const canvas = useCanvasStore().canvas\n  if (!canvas) return false\n  if (!isOverCanvas(clientX, clientY)) return false\n\n  const pos = canvas.convertEventToCanvasOffset({\n    clientX,\n    clientY\n  } as PointerEvent)\n  const node = withNodeAddSource(pendingSource.value, () =>\n    useLitegraphService().addNodeOnGraph(nodeDef, { pos })\n  )\n  if (!node) {\n    console.error(`Failed to add node to graph: ${nodeDef.name}`)\n    useToast().error(t('g.error'), {\n      description: t('assetBrowser.failedToCreateNode')\n    })\n    return true\n  }\n\n  if (pendingWidgetValues.value)\n    applyWidgetValues(node, pendingWidgetValues.value)\n  canvas.selectItems([node])\n  return true\n}\n\nfunction endDrag(e: PointerEvent) {\n  if (!isDragging.value || !draggedNode.value) return\n  if (dragMode.value !== 'click') return\n\n  try {\n    addNodeAtPosition(e.clientX, e.clientY)\n  } finally {\n    cancelDrag()\n  }\n}\n\nfunction handleKeydown(e: KeyboardEvent) {\n  if (e.key === 'Escape') cancelDrag()\n}\n\n// Prevent LiteGraph's empty-canvas hit-test from deselecting the placed node on pointerup.\nfunction blockCommitPointerDown(e: PointerEvent) {\n  if (!isDragging.value || dragMode.value !== 'click') return\n  if (!isOverCanvas(e.clientX, e.clientY)) return\n  e.stopImmediatePropagation()\n}\n\nfunction setupGlobalListeners() {\n  if (listenersSetup) return\n  listenersSetup = true\n\n  document.addEventListener('pointerdown', blockCommitPointerDown, true)\n  document.addEventListener('pointerup', endDrag, true)\n  document.addEventListener('keydown', handleKeydown)\n  document.addEventListener('dragover', trackNativeDragPosition)\n}\n\nfunction cleanupGlobalListeners() {\n  if (!listenersSetup) return\n  listenersSetup = false\n\n  document.removeEventListener('pointerdown', blockCommitPointerDown, true)\n  document.removeEventListener('pointerup', endDrag, true)\n  document.removeEventListener('keydown', handleKeydown)\n  document.removeEventListener('dragover', trackNativeDragPosition)\n}\n\nfunction cancelDrag() {\n  isDragging.value = false\n  draggedNode.value = null\n  dragMode.value = 'click'\n  lastNativeDragPosition.value = undefined\n  pendingWidgetValues.value = undefined\n  pendingSource.value = 'sidebar_drag'\n  cleanupGlobalListeners()\n}\n\nexport function useNodeDragToCanvas() {\n  function startDrag(\n    nodeDef: ComfyNodeDefImpl,\n    {\n      mode = 'click',\n      widgetValues,\n      source = 'sidebar_drag'\n    }: StartDragOptions = {}\n  ) {\n    isDragging.value = true\n    draggedNode.value = nodeDef\n    dragMode.value = mode\n    pendingWidgetValues.value = widgetValues\n    pendingSource.value = source\n    setupGlobalListeners()\n  }\n\n  function handleNativeDrop(clientX: number, clientY: number) {\n    if (dragMode.value !== 'native') return\n    const tracked = lastNativeDragPosition.value\n    try {\n      addNodeAtPosition(tracked?.x ?? clientX, tracked?.y ?? clientY)\n    } finally {\n      cancelDrag()\n    }\n  }\n\n  return {\n    isDragging,\n    draggedNode,\n    pendingWidgetValues,\n    startDrag,\n    cancelDrag,\n    handleNativeDrop\n  }\n}\n","<template>\n  <Teleport to=\"body\">\n    <div\n      v-if=\"showGhost && rafPosition\"\n      class=\"pointer-events-none fixed top-0 left-0 z-10000 will-change-transform\"\n      :style=\"{\n        transform: `translate(${rafPosition.x + 12}px, ${rafPosition.y + 12}px)`\n      }\"\n    >\n      <div class=\"origin-top-left scale-50 opacity-80\">\n        <LGraphNodePreview\n          :node-def=\"draggedNode!\"\n          :widget-values=\"pendingWidgetValues\"\n          position=\"relative\"\n        />\n      </div>\n    </div>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nimport { useMouse, useRafFn } from '@vueuse/core'\nimport { computed, shallowRef, watch } from 'vue'\n\nimport { useNodeDragToCanvas } from '@/composables/node/useNodeDragToCanvas'\nimport LGraphNodePreview from '@/renderer/extensions/vueNodes/components/LGraphNodePreview.vue'\n\nconst { isDragging, draggedNode, pendingWidgetValues } = useNodeDragToCanvas()\n\nconst { x, y, sourceType } = useMouse({ type: 'client' })\n\nconst showGhost = computed(() => Boolean(isDragging.value && draggedNode.value))\nconst rafPosition = shallowRef<{ x: number; y: number }>()\n\nconst { pause, resume } = useRafFn(\n  () => {\n    if (sourceType.value === null) return\n    const pos = rafPosition.value\n    if (pos && pos.x === x.value && pos.y === y.value) return\n    rafPosition.value = { x: x.value, y: y.value }\n  },\n  { immediate: false }\n)\n\nwatch(\n  showGhost,\n  (show) => {\n    if (show) {\n      resume()\n    } else {\n      pause()\n      rafPosition.value = undefined\n    }\n  },\n  { immediate: true }\n)\n</script>\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { accent } = defineProps<{\n  /** Leading-edge colour, e.g. `border-l-success-background`. */\n  accent: string\n}>()\n</script>\n\n<template>\n  <div\n    :class=\"\n      cn(\n        'pointer-events-auto relative flex items-center gap-12 rounded-lg border border-l-4 border-interface-stroke bg-interface-panel-surface p-4 shadow-interface',\n        accent\n      )\n    \"\n  >\n    <div class=\"flex min-w-0 items-center gap-2\">\n      <slot name=\"icon\" />\n      <div class=\"flex min-w-0 flex-col\">\n        <span class=\"text-sm font-medium wrap-break-word text-base-foreground\">\n          <slot name=\"title\" />\n        </span>\n        <span\n          v-if=\"$slots.description\"\n          class=\"text-sm wrap-break-word text-muted-foreground\"\n        >\n          <slot name=\"description\" />\n        </span>\n      </div>\n    </div>\n    <slot name=\"actions\" />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { useEventListener } from '@vueuse/core'\nimport { useI18n } from 'vue-i18n'\n\nimport CanvasBanner from '@/components/graph/CanvasBanner.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst { t } = useI18n()\nconst canvasInteractions = useCanvasInteractions()\nconst canvasStore = useCanvasStore()\nconst dialogStore = useDialogStore()\n\nuseEventListener(window, 'keydown', (event: KeyboardEvent) => {\n  if (event.key === 'Escape' && dialogStore.dialogStack.length === 0)\n    canvasStore.stopNodePicking()\n})\n</script>\n\n<template>\n  <div\n    class=\"pointer-events-none absolute top-4 left-1/2 z-40 -translate-x-1/2\"\n  >\n    <Transition\n      enter-active-class=\"transition-[transform,opacity] delay-300 duration-150 ease-out\"\n      leave-active-class=\"transition-[transform,opacity] duration-150 ease-out\"\n      enter-from-class=\"-translate-y-full opacity-0\"\n      leave-to-class=\"-translate-y-full opacity-0\"\n    >\n      <CanvasBanner\n        v-if=\"canvasStore.isPickingNodes\"\n        data-testid=\"node-selection-mode-banner\"\n        accent=\"border-l-primary-background\"\n        class=\"max-w-lg\"\n        @wheel=\"canvasInteractions.forwardEventToCanvas\"\n      >\n        <template #title>{{ t('agent.nodeSelection.bannerTitle') }}</template>\n        <template #description>\n          {{ t('agent.nodeSelection.bannerSubtitle') }}\n        </template>\n        <template #actions>\n          <Button\n            variant=\"secondary\"\n            size=\"sm\"\n            @click=\"canvasStore.stopNodePicking()\"\n          >\n            {{ t('agent.nodeSelection.exit') }}\n          </Button>\n        </template>\n      </CanvasBanner>\n    </Transition>\n  </div>\n</template>\n","import { useSelectionState } from '@/composables/graph/useSelectionState'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { TitleMode } from '@/lib/litegraph/src/types/globalEnums'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useLayoutMutations } from '@/renderer/core/layout/operations/layoutMutations'\nimport { LayoutSource } from '@/renderer/core/layout/types'\nimport type { Point } from '@/renderer/core/layout/types'\nimport { app } from '@/scripts/app'\nimport type { NodeId } from '@/types/nodeId'\n\nexport type ArrangeLayout = 'vertical' | 'horizontal' | 'grid'\n\nexport const DEFAULT_ARRANGE_GAP = 12\nexport const MIN_ARRANGE_GAP = 0\nexport const MAX_ARRANGE_GAP = 48\n\ninterface NodeBox {\n  id: NodeId\n  posX: number\n  posY: number\n  visualWidth: number\n  visualHeight: number\n  titleHeight: number\n}\n\ninterface ArrangeUpdate {\n  nodeId: NodeId\n  position: Point\n}\n\nconst titleHeightOf = (node: LGraphNode): number => {\n  const mode = node.title_mode\n  if (mode === TitleMode.TRANSPARENT_TITLE || mode === TitleMode.NO_TITLE) {\n    return 0\n  }\n  return LiteGraph.NODE_TITLE_HEIGHT\n}\n\nconst toBox = (node: LGraphNode): NodeBox => {\n  const titleHeight = titleHeightOf(node)\n  return {\n    id: node.id,\n    posX: node.pos[0],\n    posY: node.pos[1],\n    visualWidth: node.size[0],\n    visualHeight: node.size[1] + titleHeight,\n    titleHeight\n  }\n}\n\nconst byTopDown = (a: NodeBox, b: NodeBox) => a.posY - b.posY || a.posX - b.posX\n\nconst byLeftRight = (a: NodeBox, b: NodeBox) =>\n  a.posX - b.posX || a.posY - b.posY\n\nconst findAnchor = (boxes: NodeBox[]): NodeBox =>\n  boxes.reduce((best, box) =>\n    box.posX + box.posY < best.posX + best.posY ? box : best\n  )\n\nconst cumulativeOffsets = (\n  sizes: number[],\n  origin: number,\n  gap: number\n): number[] => {\n  const offsets: number[] = [origin]\n  for (let i = 1; i < sizes.length; i++) {\n    offsets.push(offsets[i - 1] + sizes[i - 1] + gap)\n  }\n  return offsets\n}\n\nconst arrangeVertical = (\n  boxes: NodeBox[],\n  anchor: NodeBox,\n  gap: number\n): ArrangeUpdate[] => {\n  const sorted = [...boxes].sort(byTopDown)\n  let visualTop = anchor.posY - anchor.titleHeight\n  return sorted.map((box) => {\n    const update: ArrangeUpdate = {\n      nodeId: box.id,\n      position: { x: anchor.posX, y: visualTop + box.titleHeight }\n    }\n    visualTop += box.visualHeight + gap\n    return update\n  })\n}\n\nconst arrangeHorizontal = (\n  boxes: NodeBox[],\n  anchor: NodeBox,\n  gap: number\n): ArrangeUpdate[] => {\n  const sorted = [...boxes].sort(byLeftRight)\n  const visualTop = anchor.posY - anchor.titleHeight\n  let cursorX = anchor.posX\n  return sorted.map((box) => {\n    const update: ArrangeUpdate = {\n      nodeId: box.id,\n      position: { x: cursorX, y: visualTop + box.titleHeight }\n    }\n    cursorX += box.visualWidth + gap\n    return update\n  })\n}\n\nconst arrangeGrid = (\n  boxes: NodeBox[],\n  anchor: NodeBox,\n  gap: number\n): ArrangeUpdate[] => {\n  const sorted = [...boxes].sort(byTopDown)\n  const cols = Math.ceil(Math.sqrt(sorted.length))\n  const rows = Math.ceil(sorted.length / cols)\n\n  const colWidths = Array.from({ length: cols }, () => 0)\n  const rowHeights = Array.from({ length: rows }, () => 0)\n  sorted.forEach((box, i) => {\n    const col = i % cols\n    const row = Math.floor(i / cols)\n    if (box.visualWidth > colWidths[col]) colWidths[col] = box.visualWidth\n    if (box.visualHeight > rowHeights[row]) rowHeights[row] = box.visualHeight\n  })\n\n  const colX = cumulativeOffsets(colWidths, anchor.posX, gap)\n  const rowVisualTop = cumulativeOffsets(\n    rowHeights,\n    anchor.posY - anchor.titleHeight,\n    gap\n  )\n\n  return sorted.map((box, i) => {\n    const col = i % cols\n    const row = Math.floor(i / cols)\n    return {\n      nodeId: box.id,\n      position: {\n        x: colX[col],\n        y: rowVisualTop[row] + box.titleHeight\n      }\n    }\n  })\n}\n\nexport function computeArrangement(\n  nodes: LGraphNode[],\n  layout: ArrangeLayout,\n  gap: number = DEFAULT_ARRANGE_GAP\n): ArrangeUpdate[] {\n  if (nodes.length < 2) return []\n  const boxes = nodes.map(toBox)\n  const anchor = findAnchor(boxes)\n  if (layout === 'vertical') return arrangeVertical(boxes, anchor, gap)\n  if (layout === 'horizontal') return arrangeHorizontal(boxes, anchor, gap)\n  return arrangeGrid(boxes, anchor, gap)\n}\n\ninterface ArrangeOptions {\n  gap?: number\n  captureUndo?: boolean\n}\n\nexport function useArrangeNodes() {\n  const { selectedNodes, hasMultipleSelection } = useSelectionState()\n  const mutations = useLayoutMutations(LayoutSource.Canvas)\n  const workflowStore = useWorkflowStore()\n  const canvasStore = useCanvasStore()\n\n  const arrangeNodes = (\n    layout: ArrangeLayout,\n    { gap = DEFAULT_ARRANGE_GAP, captureUndo = true }: ArrangeOptions = {}\n  ) => {\n    if (!hasMultipleSelection.value) return\n    const { rootGraphId } = canvasStore\n    if (!rootGraphId) return\n\n    const updates = computeArrangement(selectedNodes.value, layout, gap)\n    if (updates.length === 0) return\n\n    mutations.batchMoveNodes(rootGraphId, updates)\n    app.canvas.setDirty(true, true)\n    if (captureUndo) {\n      workflowStore.activeWorkflow?.changeTracker.captureCanvasState()\n    }\n  }\n\n  return { arrangeNodes, canArrange: hasMultipleSelection }\n}\n","import { readonly, ref } from 'vue'\n\nimport {\n  DEFAULT_ARRANGE_GAP,\n  useArrangeNodes\n} from '@/composables/graph/useArrangeNodes'\nimport type { ArrangeLayout } from '@/composables/graph/useArrangeNodes'\n\nexport function useArrangeSession() {\n  const { arrangeNodes } = useArrangeNodes()\n\n  const activeLayout = ref<ArrangeLayout | null>(null)\n  const gap = ref(DEFAULT_ARRANGE_GAP)\n  let pendingFrame: number | null = null\n\n  const cancelPendingFrame = () => {\n    if (pendingFrame === null) return\n    cancelAnimationFrame(pendingFrame)\n    pendingFrame = null\n  }\n\n  const reset = () => {\n    cancelPendingFrame()\n    activeLayout.value = null\n    gap.value = DEFAULT_ARRANGE_GAP\n  }\n\n  const start = (layout: ArrangeLayout) => {\n    gap.value = DEFAULT_ARRANGE_GAP\n    activeLayout.value = layout\n    arrangeNodes(layout, { gap: gap.value, captureUndo: true })\n  }\n\n  const previewGap = (nextGap: number) => {\n    if (activeLayout.value === null) return\n    gap.value = nextGap\n    cancelPendingFrame()\n    pendingFrame = requestAnimationFrame(() => {\n      pendingFrame = null\n      if (activeLayout.value === null) return\n      arrangeNodes(activeLayout.value, { gap: nextGap, captureUndo: false })\n    })\n  }\n\n  const commitGap = (nextGap: number) => {\n    if (activeLayout.value === null) return\n    cancelPendingFrame()\n    gap.value = nextGap\n    arrangeNodes(activeLayout.value, { gap: nextGap, captureUndo: true })\n  }\n\n  return {\n    activeLayout: readonly(activeLayout),\n    gap: readonly(gap),\n    start,\n    previewGap,\n    commitGap,\n    reset\n  }\n}\n","<template>\n  <PopoverRoot v-model:open=\"isOpen\">\n    <PopoverTrigger as-child>\n      <Button\n        :tooltip=\"t('g.arrange')\"\n        variant=\"muted-textonly\"\n        :aria-label=\"t('g.arrange')\"\n      >\n        <div class=\"flex items-center gap-1 px-0\">\n          <i class=\"icon-[lucide--layout-grid]\" />\n          <i class=\"icon-[lucide--chevron-down]\" />\n        </div>\n      </Button>\n    </PopoverTrigger>\n    <PopoverPortal>\n      <PopoverContent\n        side=\"bottom\"\n        :side-offset=\"5\"\n        :collision-padding=\"10\"\n        class=\"z-1700 rounded-lg border border-border-subtle bg-base-background p-2 shadow-sm will-change-[transform,opacity] data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95\"\n      >\n        <div\n          v-if=\"activeLayout\"\n          class=\"flex w-32 flex-row items-center px-2 py-1\"\n        >\n          <Slider\n            :model-value=\"[gap]\"\n            :min=\"MIN_ARRANGE_GAP\"\n            :max=\"MAX_ARRANGE_GAP\"\n            :step=\"1\"\n            :aria-label=\"t('g.arrangeSpacing')\"\n            @update:model-value=\"onSliderUpdate\"\n            @value-commit=\"onSliderCommit\"\n          />\n        </div>\n        <div v-else class=\"flex flex-row gap-1\">\n          <Button\n            :tooltip=\"t('g.arrangeVertically')\"\n            variant=\"muted-textonly\"\n            :aria-label=\"t('g.arrangeVertically')\"\n            @click=\"start('vertical')\"\n          >\n            <i class=\"icon-[lucide--stretch-horizontal]\" />\n          </Button>\n          <Button\n            :tooltip=\"t('g.arrangeHorizontally')\"\n            variant=\"muted-textonly\"\n            :aria-label=\"t('g.arrangeHorizontally')\"\n            @click=\"start('horizontal')\"\n          >\n            <i class=\"icon-[lucide--stretch-vertical]\" />\n          </Button>\n          <Button\n            :tooltip=\"t('g.arrangeAsGrid')\"\n            variant=\"muted-textonly\"\n            :aria-label=\"t('g.arrangeAsGrid')\"\n            @click=\"start('grid')\"\n          >\n            <i class=\"icon-[lucide--grid-3x3]\" />\n          </Button>\n        </div>\n        <PopoverArrow class=\"fill-base-background stroke-border-subtle\" />\n      </PopoverContent>\n    </PopoverPortal>\n  </PopoverRoot>\n</template>\n\n<script setup lang=\"ts\">\nimport {\n  PopoverArrow,\n  PopoverContent,\n  PopoverPortal,\n  PopoverRoot,\n  PopoverTrigger\n} from 'reka-ui'\nimport { ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Slider from '@/components/ui/slider/Slider.vue'\nimport {\n  MAX_ARRANGE_GAP,\n  MIN_ARRANGE_GAP\n} from '@/composables/graph/useArrangeNodes'\nimport { useArrangeSession } from '@/composables/graph/useArrangeSession'\n\nconst { t } = useI18n()\nconst { activeLayout, gap, start, previewGap, commitGap, reset } =\n  useArrangeSession()\n\nconst isOpen = ref(false)\n\nwatch(isOpen, (open) => {\n  if (!open) reset()\n})\n\nconst firstValue = (value: number[] | undefined): number | undefined =>\n  value?.[0]\n\nconst onSliderUpdate = (value: number[] | undefined) => {\n  const next = firstValue(value)\n  if (next !== undefined) previewGap(next)\n}\n\nconst onSliderCommit = (value: number[]) => {\n  const next = firstValue(value)\n  if (next !== undefined) commitGap(next)\n}\n</script>\n","<template>\n  <Button\n    :tooltip=\"$t('commands.Comfy_Canvas_ToggleSelectedNodes_Bypass.label')\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('commands.Comfy_Canvas_ToggleSelectedNodes_Bypass.label')\"\n    data-testid=\"bypass-button\"\n    class=\"hover:bg-secondary-background\"\n    @click=\"toggleBypass\"\n  >\n    <i class=\"icon-[lucide--redo-dot] size-4\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCommandStore } from '@/stores/commandStore'\n\nconst commandStore = useCommandStore()\n\nconst toggleBypass = async () => {\n  await commandStore.execute('Comfy.Canvas.ToggleSelectedNodes.Bypass')\n}\n</script>\n","<template>\n  <div class=\"relative\">\n    <Button\n      :tooltip=\"localizedCurrentColorName ?? t('color.noColor')\"\n      data-testid=\"color-picker-button\"\n      variant=\"muted-textonly\"\n      :aria-label=\"t('g.color')\"\n      @click=\"() => (showColorPicker = !showColorPicker)\"\n    >\n      <div class=\"flex items-center gap-1 px-0\">\n        <i\n          class=\"pi pi-circle-fill\"\n          data-testid=\"color-picker-current-color\"\n          :style=\"{ color: currentColor ?? '' }\"\n        />\n        <i class=\"icon-[lucide--chevron-down]\" />\n      </div>\n    </Button>\n    <div\n      v-if=\"showColorPicker\"\n      class=\"absolute -top-10 left-1/2 -translate-x-1/2\"\n    >\n      <ToggleGroup\n        :model-value=\"selectedColorOption?.name\"\n        type=\"single\"\n        @update:model-value=\"applyColorName\"\n      >\n        <TextTooltip\n          v-for=\"option in colorOptions\"\n          :key=\"option.name\"\n          :text=\"option.localizedName\"\n        >\n          <ToggleGroupItem\n            :value=\"option.name\"\n            :aria-label=\"option.localizedName\"\n            class=\"px-1 py-2 aria-pressed:bg-secondary-background aria-pressed:text-base-foreground\"\n          >\n            <i\n              class=\"pi pi-circle-fill\"\n              :style=\"{\n                color: isLightTheme ? option.value.light : option.value.dark\n              }\"\n              :data-testid=\"option.name\"\n            />\n          </ToggleGroupItem>\n        </TextTooltip>\n      </ToggleGroup>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useEventListener } from '@vueuse/core'\nimport type { Raw } from 'vue'\nimport { computed, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'\nimport TextTooltip from '@/components/ui/tooltip/TextTooltip.vue'\nimport type {\n  ColorOption as CanvasColorOption,\n  LiteGraphCanvasEvent,\n  Positionable\n} from '@/lib/litegraph/src/litegraph'\nimport {\n  LGraphCanvas,\n  LiteGraph,\n  isColorable\n} from '@/lib/litegraph/src/litegraph'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { adjustColor } from '@/utils/colorUtil'\nimport { getItemsColorOption } from '@/utils/litegraphUtil'\n\nconst { t } = useI18n()\nconst canvasStore = useCanvasStore()\nconst colorPaletteStore = useColorPaletteStore()\nconst workflowStore = useWorkflowStore()\nconst isLightTheme = computed(\n  () => colorPaletteStore.completedActivePalette.light_theme\n)\nconst toLightThemeColor = (color: string) =>\n  adjustColor(color, { lightness: 0.5 })\n\nconst showColorPicker = ref(false)\n\ntype ColorOption = {\n  name: string\n  localizedName: string\n  value: {\n    dark: string\n    light: string\n  }\n}\n\nconst NO_COLOR_OPTION: ColorOption = {\n  name: 'noColor',\n  localizedName: t('color.noColor'),\n  value: {\n    dark: LiteGraph.NODE_DEFAULT_BGCOLOR,\n    light: toLightThemeColor(LiteGraph.NODE_DEFAULT_BGCOLOR)\n  }\n}\nconst colorOptions: ColorOption[] = [\n  NO_COLOR_OPTION,\n  ...Object.entries(LGraphCanvas.node_colors).map(([name, color]) => ({\n    name,\n    localizedName: t(`color.${name}`),\n    value: {\n      dark: color.bgcolor,\n      light: toLightThemeColor(color.bgcolor)\n    }\n  }))\n]\n\nconst selectedColorOption = ref<ColorOption | null>(null)\nconst applyColorName = (value: unknown) => {\n  if (typeof value === 'string') {\n    applyColor(colorOptions.find((option) => option.name === value) ?? null)\n  } else {\n    applyColor(null)\n  }\n}\nconst applyColor = (colorOption: ColorOption | null) => {\n  const colorName = colorOption?.name ?? NO_COLOR_OPTION.name\n  const canvasColorOption =\n    colorName === NO_COLOR_OPTION.name\n      ? null\n      : LGraphCanvas.node_colors[colorName]\n\n  for (const item of canvasStore.selectedItems) {\n    if (isColorable(item)) {\n      item.setColorOption(canvasColorOption)\n    }\n  }\n\n  canvasStore.canvas?.setDirty(true, true)\n  selectedColorOption.value = colorOption\n  currentColorOption.value = canvasColorOption\n  showColorPicker.value = false\n  workflowStore.activeWorkflow?.changeTracker?.captureCanvasState()\n}\n\nconst currentColorOption = ref<CanvasColorOption | null>(null)\nconst currentColor = computed(() =>\n  currentColorOption.value\n    ? isLightTheme.value\n      ? toLightThemeColor(currentColorOption.value?.bgcolor)\n      : currentColorOption.value?.bgcolor\n    : null\n)\n\nconst localizedCurrentColorName = computed(() => {\n  if (!currentColorOption.value?.bgcolor) return null\n  const colorOption = colorOptions.find(\n    (option) =>\n      option.value.dark === currentColorOption.value?.bgcolor ||\n      option.value.light === currentColorOption.value?.bgcolor\n  )\n  return colorOption?.localizedName ?? NO_COLOR_OPTION.localizedName\n})\nconst updateColorSelectionFromNode = (\n  newSelectedItems: Raw<Positionable[]>\n) => {\n  showColorPicker.value = false\n  selectedColorOption.value = null\n  currentColorOption.value = getItemsColorOption(newSelectedItems)\n}\nuseEventListener(\n  document,\n  'litegraph:canvas',\n  (event: LiteGraphCanvasEvent) => {\n    if (event.detail.subType === 'after-change') {\n      updateColorSelectionFromNode(canvasStore.selectedItems)\n    }\n  }\n)\nwatch(\n  () => canvasStore.selectedItems,\n  (newSelectedItems) => {\n    updateColorSelectionFromNode(newSelectedItems)\n  },\n  { immediate: true }\n)\n</script>\n","<template>\n  <Button\n    :tooltip=\"$t('commands.Comfy_Graph_EditSubgraphWidgets.label')\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('commands.Comfy_Graph_EditSubgraphWidgets.label')\"\n    @click=\"handleClick\"\n  >\n    <i class=\"icon-[lucide--settings-2]\" />\n  </Button>\n</template>\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\n\nconst rightSidePanelStore = useRightSidePanelStore()\n\nconst handleClick = () => {\n  rightSidePanelStore.openPanel('subgraph')\n}\n</script>\n","<template>\n  <Button\n    v-if=\"isUnpackVisible\"\n    :tooltip=\"$t('commands.Comfy_Graph_UnpackSubgraph.label')\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('commands.Comfy_Graph_UnpackSubgraph.label')\"\n    data-testid=\"convert-to-subgraph-button\"\n    @click=\"() => commandStore.execute('Comfy.Graph.UnpackSubgraph')\"\n  >\n    <i class=\"icon-[lucide--expand] size-4\" />\n  </Button>\n  <Button\n    v-else-if=\"isConvertVisible\"\n    :tooltip=\"$t('commands.Comfy_Graph_ConvertToSubgraph.label')\"\n    variant=\"muted-textonly\"\n    size=\"icon\"\n    :aria-label=\"$t('commands.Comfy_Graph_ConvertToSubgraph.label')\"\n    data-testid=\"convert-to-subgraph-button\"\n    @click=\"() => commandStore.execute('Comfy.Graph.ConvertToSubgraph')\"\n  >\n    <i class=\"icon-[lucide--shrink] size-4\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSelectionState } from '@/composables/graph/useSelectionState'\nimport { useCommandStore } from '@/stores/commandStore'\n\nconst commandStore = useCommandStore()\nconst { isSingleSubgraph, hasAnySelection } = useSelectionState()\n\nconst isUnpackVisible = isSingleSubgraph\nconst isConvertVisible = computed(\n  () => hasAnySelection.value && !isSingleSubgraph.value\n)\n</script>\n","<template>\n  <Button\n    v-if=\"isDeletable\"\n    :tooltip=\"$t('commands.Comfy_Canvas_DeleteSelectedItems.label')\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('commands.Comfy_Canvas_DeleteSelectedItems.label')\"\n    data-testid=\"delete-button\"\n    @click=\"() => commandStore.execute('Comfy.Canvas.DeleteSelectedItems')\"\n  >\n    <i class=\"icon-[lucide--trash-2]\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSelectionState } from '@/composables/graph/useSelectionState'\nimport type { Positionable } from '@/lib/litegraph/src/interfaces'\nimport { useCommandStore } from '@/stores/commandStore'\n\nconst commandStore = useCommandStore()\nconst { selectedItems } = useSelectionState()\n\nconst isDeletable = computed(() =>\n  selectedItems.value.some((x: Positionable) => x.removable !== false)\n)\n</script>\n","<template>\n  <Button\n    :tooltip=\"t('selectionToolbox.executeButton.tooltip')\"\n    variant=\"primary\"\n    :aria-label=\"t('selectionToolbox.executeButton.tooltip')\"\n    @mouseenter=\"() => handleMouseEnter()\"\n    @mouseleave=\"() => handleMouseLeave()\"\n    @click=\"handleClick\"\n  >\n    <i class=\"icon-[lucide--play]\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSelectionState } from '@/composables/graph/useSelectionState'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { isLGraphNode } from '@/utils/litegraphUtil'\nimport { isOutputNode } from '@/utils/nodeFilterUtil'\n\nconst { t } = useI18n()\nconst commandStore = useCommandStore()\nconst canvasStore = useCanvasStore()\nconst { selectedNodes } = useSelectionState()\n\nconst canvas = canvasStore.getCanvas()\nconst buttonHovered = ref(false)\nconst selectedOutputNodes = computed(() =>\n  selectedNodes.value.filter(isLGraphNode).filter(isOutputNode)\n)\n\nfunction outputNodeStokeStyle(this: LGraphNode) {\n  if (\n    this.selected &&\n    this.constructor.nodeData?.output_node &&\n    buttonHovered.value\n  ) {\n    return { color: 'orange', lineWidth: 2, padding: 10 }\n  }\n}\n\nconst handleMouseEnter = () => {\n  buttonHovered.value = true\n  for (const node of selectedOutputNodes.value) {\n    node.strokeStyles['outputNode'] = outputNodeStokeStyle\n  }\n  canvas.setDirty(true)\n}\n\nconst handleMouseLeave = () => {\n  buttonHovered.value = false\n  canvas.setDirty(true)\n}\n\nconst handleClick = async () => {\n  await commandStore.execute('Comfy.QueueSelectedOutputNodes')\n}\n</script>\n","<template>\n  <Button\n    :tooltip=\"label\"\n    variant=\"muted-textonly\"\n    :aria-label=\"label\"\n    @click=\"() => commandStore.execute(command.id)\"\n  >\n    <i\n      :class=\"\n        typeof command.icon === 'function' ? command.icon() : command.icon\n      \"\n    />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { st } from '@/i18n'\nimport type { ComfyCommand } from '@/stores/commandStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { normalizeI18nKey } from '@/utils/formatUtil'\n\nconst { command } = defineProps<{\n  command: ComfyCommand\n}>()\n\nconst commandStore = useCommandStore()\n\nconst label = computed(() =>\n  st(`commands.${normalizeI18nKey(command.id)}.label`, '')\n)\n</script>\n","<template>\n  <Button\n    :tooltip=\"$t('g.info')\"\n    data-testid=\"info-button\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('g.info')\"\n    @click=\"onInfoClick\"\n  >\n    <i class=\"icon-[lucide--info]\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSelectionState } from '@/composables/graph/useSelectionState'\nimport { useTelemetry } from '@/platform/telemetry'\n\nconst { openNodeInfo } = useSelectionState()\n\nconst onInfoClick = () => {\n  if (!openNodeInfo()) return\n\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'selection_toolbox_node_info_opened',\n    element_group: 'selection_toolbox'\n  })\n}\n</script>\n","<template>\n  <Button\n    :tooltip=\"$t('commands.Comfy_3DViewer_Open3DViewer.label')\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('commands.Comfy_3DViewer_Open3DViewer.label')\"\n    @click=\"open3DViewer\"\n  >\n    <i class=\"icon-[lucide--pencil]\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCommandStore } from '@/stores/commandStore'\n\nconst commandStore = useCommandStore()\n\nconst open3DViewer = () => {\n  void commandStore.execute('Comfy.3DViewer.Open3DViewer')\n}\n</script>\n","<template>\n  <Button\n    :tooltip=\"$t('commands.Comfy_MaskEditor_OpenMaskEditor.label')\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('commands.Comfy_MaskEditor_OpenMaskEditor.label')\"\n    @click=\"openMaskEditor\"\n  >\n    <i class=\"icon-[comfy--mask]\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCommandStore } from '@/stores/commandStore'\n\nconst commandStore = useCommandStore()\n\nconst openMaskEditor = () => {\n  void commandStore.execute('Comfy.MaskEditor.OpenMaskEditor')\n}\n</script>\n","import { computed, ref, watchEffect } from 'vue'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { isLGraphNode } from '@/utils/litegraphUtil'\n\ninterface RefreshableItem {\n  refresh: () => Promise<void> | void\n}\n\nconst isRefreshableWidget = (widget: unknown): widget is RefreshableItem =>\n  widget != null &&\n  typeof widget === 'object' &&\n  'refresh' in widget &&\n  typeof widget.refresh === 'function'\n\n/**\n * Tracks selected nodes and their refreshable widgets\n */\nexport const useRefreshableSelection = () => {\n  const graphStore = useCanvasStore()\n  const selectedNodes = ref<LGraphNode[]>([])\n\n  watchEffect(() => {\n    selectedNodes.value = graphStore.selectedItems.filter(isLGraphNode)\n  })\n\n  const refreshableWidgets = computed<RefreshableItem[]>(() =>\n    selectedNodes.value.flatMap((node) => {\n      if (!node.widgets) return []\n      const items: RefreshableItem[] = []\n      for (const widget of node.widgets) {\n        if (isRefreshableWidget(widget)) {\n          items.push(widget)\n        }\n      }\n      return items\n    })\n  )\n\n  const isRefreshable = computed(() => refreshableWidgets.value.length > 0)\n\n  async function refreshSelected() {\n    if (!isRefreshable.value) return\n\n    await Promise.all(refreshableWidgets.value.map((item) => item.refresh()))\n  }\n\n  return {\n    isRefreshable,\n    refreshSelected\n  }\n}\n","<template>\n  <Button\n    v-if=\"isRefreshable\"\n    :tooltip=\"t('g.refreshNode')\"\n    variant=\"muted-textonly\"\n    :aria-label=\"t('g.refreshNode')\"\n    data-testid=\"refresh-button\"\n    @click=\"refreshSelected\"\n  >\n    <i class=\"icon-[lucide--refresh-cw]\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useRefreshableSelection } from '@/composables/useRefreshableSelection'\n\nconst { t } = useI18n()\nconst { isRefreshable, refreshSelected } = useRefreshableSelection()\n</script>\n","<template>\n  <Button\n    :tooltip=\"$t('commands.Comfy_PublishSubgraph.label')\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('commands.Comfy_PublishSubgraph.label')\"\n    @click=\"() => commandStore.execute('Comfy.PublishSubgraph')\"\n  >\n    <i class=\"icon-[lucide--book-open]\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCommandStore } from '@/stores/commandStore'\n\nconst commandStore = useCommandStore()\n</script>\n","import { useElementBounding, useEventListener, useRafFn } from '@vueuse/core'\nimport { computed, onUnmounted, ref, watch, watchEffect } from 'vue'\nimport type { Ref } from 'vue'\n\nimport { useSelectedLiteGraphItems } from '@/composables/canvas/useSelectedLiteGraphItems'\nimport { useVueFeatureFlags } from '@/composables/useVueFeatureFlags'\nimport type { ReadOnlyRect, Rect } from '@/lib/litegraph/src/interfaces'\nimport { LGraphGroup, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { isLGraphGroup, isLGraphNode } from '@/utils/litegraphUtil'\nimport { computeUnionBounds } from '@/utils/mathUtil'\n\n/**\n * Manages the position of the selection toolbox independently.\n * Uses CSS custom properties for performant transform updates.\n */\n\n// Shared signals for auxiliary UI (e.g., MoreOptions) to coordinate hide/restore\nconst moreOptionsOpen = ref(false)\nconst forceCloseMoreOptionsSignal = ref(0)\nconst restoreMoreOptionsSignal = ref(0)\nconst moreOptionsRestorePending = ref(false)\nlet moreOptionsWasOpenBeforeDrag = false\nlet moreOptionsSelectionSignature: string | null = null\n\nfunction buildSelectionSignature(\n  store: ReturnType<typeof useCanvasStore>\n): string | null {\n  const c = store.canvas\n  if (!c) return null\n  const items = Array.from(c.selectedItems)\n  if (items.length !== 1) return null\n  const item = items[0]\n  if (isLGraphNode(item)) return `N:${item.id}`\n  if (isLGraphGroup(item)) return `G:${item.id}`\n  return null\n}\n\nfunction currentSelectionMatchesSignature(\n  store: ReturnType<typeof useCanvasStore>\n) {\n  if (!moreOptionsSelectionSignature) return false\n  return buildSelectionSignature(store) === moreOptionsSelectionSignature\n}\n\nfunction getSelectionBounds(item: LGraphNode | LGraphGroup): ReadOnlyRect {\n  if (item instanceof LGraphGroup) return item.boundingRect\n\n  const bounds: Rect = [0, 0, 0, 0]\n  item.measure(bounds)\n  return bounds\n}\n\nexport function useSelectionToolboxPosition(\n  toolboxRef: Ref<HTMLElement | undefined>\n) {\n  const canvasStore = useCanvasStore()\n  const lgCanvas = canvasStore.getCanvas()\n  const { getSelectableItems } = useSelectedLiteGraphItems()\n  const { shouldRenderVueNodes } = useVueFeatureFlags()\n  const isDraggingLiteGraphItems = ref(lgCanvas.isDragging)\n\n  useEventListener(\n    lgCanvas.canvas,\n    'litegraph:dragging-items-changed',\n    (event: CustomEvent<{ dragging: boolean }>) => {\n      isDraggingLiteGraphItems.value = event.detail.dragging\n    }\n  )\n\n  // World position of selection center\n  const worldPosition = ref({ x: 0, y: 0 })\n\n  const visible = ref(false)\n\n  // Use VueUse to reactively track canvas bounding rect\n  const { left: canvasLeft, top: canvasTop } = useElementBounding(\n    lgCanvas.canvas\n  )\n\n  // Unified dragging state - combines both LiteGraph and Vue node dragging\n  const isDragging = computed((): boolean => {\n    const vueNodeDragging =\n      shouldRenderVueNodes.value && layoutStore.isDraggingVueNodes.value\n    return isDraggingLiteGraphItems.value || vueNodeDragging\n  })\n\n  /**\n   * Update position based on selection\n   */\n  const updateSelectionBounds = () => {\n    const selectableItems = getSelectableItems()\n\n    if (!selectableItems.size) {\n      visible.value = false\n      return\n    }\n\n    // Don't show toolbox while dragging\n    if (isDragging.value) {\n      visible.value = false\n      return\n    }\n\n    visible.value = true\n\n    // Get bounds for all selected items\n    const allBounds: ReadOnlyRect[] = []\n    for (const item of selectableItems) {\n      if (item instanceof LGraphNode || item instanceof LGraphGroup) {\n        allBounds.push(getSelectionBounds(item))\n      }\n    }\n\n    // Compute union bounds\n    const unionBounds = computeUnionBounds(allBounds)\n    if (!unionBounds) return\n\n    worldPosition.value = {\n      x: unionBounds.x + unionBounds.width / 2,\n      // createBounds() applied a default padding of 10px\n      // so adjust Y to maintain visual consistency\n      y: unionBounds.y - 10\n    }\n\n    updateTransform()\n  }\n\n  const updateTransform = () => {\n    if (!visible.value) return\n\n    const { scale, offset } = lgCanvas.ds\n\n    const screenX =\n      (worldPosition.value.x + offset[0]) * scale + canvasLeft.value\n    const screenY =\n      (worldPosition.value.y + offset[1]) * scale + canvasTop.value\n\n    // Update CSS custom properties directly for best performance\n    if (toolboxRef.value) {\n      toolboxRef.value.style.setProperty('--tb-x', `${screenX}px`)\n      toolboxRef.value.style.setProperty('--tb-y', `${screenY}px`)\n    }\n  }\n\n  // Sync with canvas transform\n  const { resume: startSync, pause: stopSync } = useRafFn(updateTransform)\n\n  watchEffect(() => {\n    if (visible.value) {\n      startSync()\n    } else {\n      stopSync()\n    }\n  })\n\n  const handleSelectionMembershipChange = () => {\n    if (!moreOptionsRestorePending.value && !moreOptionsSelectionSignature)\n      return\n\n    moreOptionsRestorePending.value = false\n    moreOptionsWasOpenBeforeDrag = false\n    moreOptionsSelectionSignature = moreOptionsOpen.value\n      ? buildSelectionSignature(canvasStore)\n      : null\n  }\n\n  watch(\n    [() => canvasStore.selectedItems, () => layoutStore.layoutVersion],\n    ([selectedItems], [previousSelectedItems]) => {\n      if (selectedItems !== previousSelectedItems)\n        handleSelectionMembershipChange()\n      updateSelectionBounds()\n    },\n    { immediate: true }\n  )\n  watch(\n    () => moreOptionsOpen.value,\n    (v) => {\n      if (v) {\n        moreOptionsSelectionSignature = buildSelectionSignature(canvasStore)\n      } else if (!isDraggingLiteGraphItems.value) {\n        moreOptionsSelectionSignature = null\n        if (moreOptionsRestorePending.value)\n          moreOptionsRestorePending.value = false\n      }\n    }\n  )\n\n  const handleDragStateChange = (dragging: boolean) => {\n    if (dragging) {\n      handleDragStart()\n      return\n    }\n\n    handleDragEnd()\n  }\n\n  const handleDragStart = () => {\n    visible.value = false\n\n    // Early return if more options wasn't open\n    if (!moreOptionsOpen.value) {\n      moreOptionsRestorePending.value = false\n      moreOptionsWasOpenBeforeDrag = false\n      return\n    }\n\n    // Handle more options cleanup\n    const currentSig = buildSelectionSignature(canvasStore)\n    const selectionChanged = currentSig !== moreOptionsSelectionSignature\n\n    if (selectionChanged) {\n      moreOptionsSelectionSignature = null\n    }\n    moreOptionsOpen.value = false\n    moreOptionsWasOpenBeforeDrag = true\n    moreOptionsRestorePending.value = !!moreOptionsSelectionSignature\n\n    if (moreOptionsRestorePending.value) {\n      forceCloseMoreOptionsSignal.value++\n      return\n    }\n\n    moreOptionsWasOpenBeforeDrag = false\n  }\n\n  const handleDragEnd = () => {\n    requestAnimationFrame(() => {\n      updateSelectionBounds()\n\n      const selectionMatches = currentSelectionMatchesSignature(canvasStore)\n      const shouldRestore =\n        moreOptionsWasOpenBeforeDrag &&\n        visible.value &&\n        moreOptionsRestorePending.value &&\n        selectionMatches\n\n      // Single point of assignment for each ref\n      moreOptionsRestorePending.value =\n        shouldRestore && moreOptionsRestorePending.value\n      moreOptionsWasOpenBeforeDrag = false\n\n      if (shouldRestore) {\n        restoreMoreOptionsSignal.value++\n      }\n    })\n  }\n\n  watch(isDragging, handleDragStateChange)\n\n  onUnmounted(() => {\n    resetMoreOptionsState()\n  })\n\n  return {\n    visible\n  }\n}\n\n// External cleanup utility to be called when SelectionToolbox component unmounts\nfunction resetMoreOptionsState() {\n  moreOptionsOpen.value = false\n  moreOptionsRestorePending.value = false\n  moreOptionsWasOpenBeforeDrag = false\n  moreOptionsSelectionSignature = null\n}\n","<template>\n  <Button\n    :tooltip=\"$t('g.frameNodes')\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('g.frameNodes')\"\n    @click=\"frameNodes\"\n  >\n    <i class=\"icon-[lucide--frame]\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useFrameNodes } from '@/composables/graph/useFrameNodes'\n\nconst { frameNodes } = useFrameNodes()\n</script>\n","<template>\n  <Button\n    :tooltip=\"$t('g.moreOptions')\"\n    data-testid=\"more-options-button\"\n    variant=\"muted-textonly\"\n    :aria-label=\"$t('g.moreOptions')\"\n    @click=\"handleClick\"\n  >\n    <i class=\"icon-[lucide--more-vertical]\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { toggleNodeOptions } from '@/composables/graph/useMoreOptionsMenu'\n\nconst handleClick = (event: Event) => {\n  toggleNodeOptions(event)\n}\n</script>\n","<template>\n  <div class=\"h-6 w-px self-center bg-border-default\" />\n</template>\n","<template>\n  <div\n    ref=\"toolboxRef\"\n    style=\"transform: translate(var(--tb-x), var(--tb-y))\"\n    class=\"pointer-events-none fixed top-0 left-0 z-40\"\n  >\n    <Transition name=\"slide-up\">\n      <div\n        v-if=\"visible\"\n        data-testid=\"selection-toolbox\"\n        class=\"selection-toolbox pointer-events-auto floating-panel\"\n        @wheel=\"canvasInteractions.forwardEventToCanvas\"\n      >\n        <TooltipProvider :delay-duration=\"1000\">\n          <div class=\"flex h-8 flex-row gap-1\">\n            <DeleteButton v-if=\"showDelete\" />\n            <VerticalDivider v-if=\"canOpenNodeInfo && showAnyPrimaryActions\" />\n            <InfoButton v-if=\"canOpenNodeInfo\" />\n\n            <ColorPickerButton v-if=\"showColorPicker\" />\n            <ArrangeButton v-if=\"showArrange\" />\n            <FrameNodes v-if=\"showFrameNodes\" />\n            <ConvertToSubgraphButton v-if=\"showConvertToSubgraph\" />\n            <ConfigureSubgraph v-if=\"showSubgraphButtons\" />\n            <PublishSubgraphButton v-if=\"showSubgraphButtons\" />\n            <MaskEditorButton v-if=\"showMaskEditor\" />\n            <VerticalDivider\n              v-if=\"showAnyPrimaryActions && showAnyControlActions\"\n            />\n\n            <BypassButton v-if=\"showBypass\" />\n            <RefreshSelectionButton v-if=\"showRefresh\" />\n            <Load3DViewerButton v-if=\"showLoad3DViewer\" />\n\n            <ExtensionCommandButton\n              v-for=\"command in extensionToolboxCommands\"\n              :key=\"command.id\"\n              :command\n            />\n            <ExecuteButton v-if=\"showExecute\" />\n            <NodeOptionsButton />\n          </div>\n        </TooltipProvider>\n      </div>\n    </Transition>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\n\nimport ArrangeButton from '@/components/graph/selectionToolbox/ArrangeButton.vue'\nimport BypassButton from '@/components/graph/selectionToolbox/BypassButton.vue'\nimport ColorPickerButton from '@/components/graph/selectionToolbox/ColorPickerButton.vue'\nimport ConfigureSubgraph from '@/components/graph/selectionToolbox/ConfigureSubgraph.vue'\nimport ConvertToSubgraphButton from '@/components/graph/selectionToolbox/ConvertToSubgraphButton.vue'\nimport DeleteButton from '@/components/graph/selectionToolbox/DeleteButton.vue'\nimport ExecuteButton from '@/components/graph/selectionToolbox/ExecuteButton.vue'\nimport ExtensionCommandButton from '@/components/graph/selectionToolbox/ExtensionCommandButton.vue'\nimport InfoButton from '@/components/graph/selectionToolbox/InfoButton.vue'\nimport Load3DViewerButton from '@/components/graph/selectionToolbox/Load3DViewerButton.vue'\nimport MaskEditorButton from '@/components/graph/selectionToolbox/MaskEditorButton.vue'\nimport RefreshSelectionButton from '@/components/graph/selectionToolbox/RefreshSelectionButton.vue'\nimport PublishSubgraphButton from '@/components/graph/selectionToolbox/SaveToSubgraphLibrary.vue'\nimport TooltipProvider from '@/components/ui/tooltip/TooltipProvider.vue'\nimport { useSelectionToolboxPosition } from '@/composables/canvas/useSelectionToolboxPosition'\nimport { useSelectionState } from '@/composables/graph/useSelectionState'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport { useExtensionService } from '@/services/extensionService'\nimport { useCommandStore } from '@/stores/commandStore'\nimport type { ComfyCommandImpl } from '@/stores/commandStore'\n\nimport FrameNodes from './selectionToolbox/FrameNodes.vue'\nimport NodeOptionsButton from './selectionToolbox/NodeOptionsButton.vue'\nimport VerticalDivider from './selectionToolbox/VerticalDivider.vue'\n\nconst commandStore = useCommandStore()\nconst canvasStore = useCanvasStore()\nconst extensionService = useExtensionService()\nconst canvasInteractions = useCanvasInteractions()\n\nconst toolboxRef = ref<HTMLElement | undefined>()\nconst { visible } = useSelectionToolboxPosition(toolboxRef)\n\nconst extensionToolboxCommands = computed<ComfyCommandImpl[]>(() => {\n  const commandIds = new Set<string>(\n    canvasStore.selectedItems\n      .map(\n        (item) =>\n          extensionService\n            .invokeExtensions('getSelectionToolboxCommands', item)\n            .flat() as string[]\n      )\n      .flat()\n  )\n  return Array.from(commandIds)\n    .map((commandId) => commandStore.getCommand(commandId))\n    .filter((command): command is ComfyCommandImpl => command !== undefined)\n})\n\nconst {\n  hasAnySelection,\n  hasGroupedNodesSelection,\n  hasMultipleSelection,\n  isSingleNode,\n  isSingleSubgraph,\n  isSingleImageNode,\n  hasAny3DNodeSelected,\n  hasOutputNodesSelected,\n  canOpenNodeInfo\n} = useSelectionState()\n\nconst showColorPicker = computed(() => hasAnySelection.value)\nconst showConvertToSubgraph = computed(() => hasAnySelection.value)\nconst showArrange = computed(() => hasMultipleSelection.value)\nconst showFrameNodes = computed(() => hasMultipleSelection.value)\nconst showSubgraphButtons = computed(() => isSingleSubgraph.value)\n\nconst showBypass = computed(\n  () =>\n    isSingleNode.value ||\n    isSingleSubgraph.value ||\n    hasMultipleSelection.value ||\n    hasGroupedNodesSelection.value\n)\nconst showLoad3DViewer = computed(() => hasAny3DNodeSelected.value)\nconst showMaskEditor = computed(() => isSingleImageNode.value)\n\nconst showDelete = computed(() => hasAnySelection.value)\nconst showRefresh = computed(() => hasAnySelection.value)\nconst showExecute = computed(() => hasOutputNodesSelected.value)\n\nconst showAnyPrimaryActions = computed(\n  () =>\n    showColorPicker.value ||\n    showConvertToSubgraph.value ||\n    showArrange.value ||\n    showFrameNodes.value ||\n    showSubgraphButtons.value\n)\n\nconst showAnyControlActions = computed(() => showBypass.value)\n</script>\n\n<style scoped>\n.selection-toolbox {\n  transform: translateX(-50%) translateY(-120%);\n}\n\n@keyframes slideUp {\n  0% {\n    transform: translateX(-50%) translateY(-100%);\n    opacity: 0;\n  }\n  50% {\n    transform: translateX(-50%) translateY(-125%);\n    opacity: 0.5;\n  }\n  100% {\n    transform: translateX(-50%) translateY(-120%);\n    opacity: 1;\n  }\n}\n\n.slide-up-enter-active {\n  animation: slideUp 125ms ease-out;\n}\n\n.slide-up-leave-active {\n  animation: slideUp 25ms ease-out reverse;\n}\n</style>\n","<template>\n  <div\n    v-if=\"showInput\"\n    class=\"group-title-editor node-title-editor\"\n    :style=\"inputStyle\"\n  >\n    <EditableText\n      :is-editing=\"showInput\"\n      :model-value=\"editedTitle\"\n      :input-attrs=\"{ 'data-testid': 'node-title-input' }\"\n      @edit=\"onEdit\"\n      @cancel=\"closeEditor\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useEventListener } from '@vueuse/core'\nimport { computed, ref, watch } from 'vue'\nimport type { CSSProperties } from 'vue'\n\nimport EditableText from '@/components/common/EditableText.vue'\nimport { useAbsolutePosition } from '@/composables/element/useAbsolutePosition'\nimport {\n  LGraphGroup,\n  LGraphNode,\n  LiteGraph\n} from '@/lib/litegraph/src/litegraph'\nimport type { LiteGraphCanvasEvent } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport {\n  useCanvasStore,\n  useTitleEditorStore\n} from '@/renderer/core/canvas/canvasStore'\nimport { app } from '@/scripts/app'\n\nconst settingStore = useSettingStore()\n\nconst showInput = ref(false)\nconst editedTitle = ref('')\nconst { style: inputPositionStyle, updatePosition } = useAbsolutePosition()\nconst inputFontStyle = ref<CSSProperties>({})\nconst inputStyle = computed<CSSProperties>(() => ({\n  ...inputPositionStyle.value,\n  ...inputFontStyle.value\n}))\n\nconst titleEditorStore = useTitleEditorStore()\nconst canvasStore = useCanvasStore()\nconst previousCanvasDraggable = ref(true)\n\nconst onEdit = (newValue: string) => {\n  if (titleEditorStore.titleEditorTarget && newValue?.trim()) {\n    const trimmedTitle = newValue.trim()\n    titleEditorStore.titleEditorTarget.title = trimmedTitle\n\n    // If this is a subgraph node, sync the runtime subgraph name for breadcrumb reactivity\n    const target = titleEditorStore.titleEditorTarget\n    if (target instanceof LGraphNode && target.isSubgraphNode?.()) {\n      target.subgraph.name = trimmedTitle\n    }\n\n    app.canvas.setDirty(true, true)\n  }\n  closeEditor()\n}\n\nfunction closeEditor() {\n  showInput.value = false\n  titleEditorStore.titleEditorTarget = null\n  canvasStore.canvas!.allow_dragcanvas = previousCanvasDraggable.value\n}\n\nwatch(\n  () => titleEditorStore.titleEditorTarget,\n  (target) => {\n    if (target === null) {\n      return\n    }\n    editedTitle.value = target.title\n    showInput.value = true\n    const canvas = canvasStore.canvas!\n    previousCanvasDraggable.value = canvas.allow_dragcanvas\n    canvas.allow_dragcanvas = false\n    const scale = canvas.ds.scale\n\n    if (target instanceof LGraphGroup) {\n      const group = target\n      updatePosition({\n        pos: group.pos,\n        size: [group.size[0], group.titleHeight]\n      })\n      inputFontStyle.value = {\n        fontSize: `${LiteGraph.GROUP_TEXT_SIZE * scale}px`\n      }\n    } else if (target instanceof LGraphNode) {\n      const node = target\n      const [x, y] = node.getBounding()\n      updatePosition({\n        pos: [x, y],\n        size: [node.width, LiteGraph.NODE_TITLE_HEIGHT]\n      })\n      inputFontStyle.value = { fontSize: `${12 * scale}px` }\n    }\n  }\n)\n\nconst canvasEventHandler = (event: LiteGraphCanvasEvent) => {\n  if (event.detail.subType === 'group-double-click') {\n    if (!settingStore.get('Comfy.Group.DoubleClickTitleToEdit')) {\n      return\n    }\n\n    const group: LGraphGroup = event.detail.group\n    const [_, y] = group.pos\n\n    const e = event.detail.originalEvent\n    const relativeY = e.canvasY - y\n    // Only allow editing if the click is on the title bar\n    if (relativeY <= group.titleHeight) {\n      titleEditorStore.titleEditorTarget = group\n    }\n  } else if (event.detail.subType === 'node-double-click') {\n    if (!settingStore.get('Comfy.Node.DoubleClickTitleToEdit')) {\n      return\n    }\n\n    const node: LGraphNode = event.detail.node\n    const [_, y] = node.pos\n\n    const e = event.detail.originalEvent\n    const relativeY = e.canvasY - y\n    // Only allow editing if the click is on the title bar\n    if (relativeY <= 0) {\n      titleEditorStore.titleEditorTarget = node\n    }\n  }\n}\n\nuseEventListener(document, 'litegraph:canvas', canvasEventHandler)\n</script>\n\n<style scoped>\n.group-title-editor.node-title-editor {\n  z-index: 9999;\n  padding: 0.25rem;\n}\n\n:deep(.editable-text) {\n  width: 100%;\n  height: 100%;\n}\n\n:deep(.editable-text input) {\n  width: 100%;\n  height: 100%;\n  /* Override the default font size */\n  font-size: inherit;\n}\n</style>\n","import { cva } from 'cva'\n\nexport const tabStateVariants = cva({\n  base: 'cursor-pointer rounded-lg border-none text-sm outline-hidden transition-all duration-200 focus-visible:ring-1 focus-visible:ring-border-default',\n  variants: {\n    active: {\n      true: 'bg-interface-menu-component-surface-hovered text-text-primary',\n      false:\n        'bg-transparent text-text-secondary hover:bg-button-hover-surface focus:bg-button-hover-surface'\n    }\n  },\n  defaultVariants: {\n    active: false\n  }\n})\n","import type { InjectionKey, Ref } from 'vue'\n\ninterface TabListContext {\n  modelValue: Ref<string>\n  select: (value: string) => void\n}\n\nexport const TAB_LIST_INJECTION_KEY: InjectionKey<TabListContext> =\n  Symbol('TabListContext')\n","<template>\n  <button\n    :id=\"`tab-${props.value}`\"\n    role=\"tab\"\n    type=\"button\"\n    :aria-selected=\"isActive\"\n    :aria-controls=\"`tabpanel-${props.value}`\"\n    :data-state=\"isActive ? 'active' : 'inactive'\"\n    :tabindex=\"isActive ? 0 : -1\"\n    :class=\"\n      cn(\n        'flex h-8 shrink-0 items-center justify-center',\n        'px-2.5',\n        tabStateVariants({ active: isActive }),\n        props.class\n      )\n    \"\n    @click=\"handleClick\"\n    @keydown=\"handleKeydown\"\n  >\n    <slot />\n  </button>\n</template>\n\n<script setup lang=\"ts\" generic=\"T extends string = string\">\nimport type { HTMLAttributes } from 'vue'\n\nimport { computed, inject } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { tabStateVariants } from './tab.variants'\nimport { TAB_LIST_INJECTION_KEY } from './tabKeys'\n\nconst props = defineProps<{\n  value: T\n  class?: HTMLAttributes['class']\n}>()\n\nconst context = inject(TAB_LIST_INJECTION_KEY)\n\nconst isActive = computed(() => context?.modelValue.value === props.value)\n\nfunction handleClick() {\n  context?.select(props.value)\n}\n\nfunction handleKeydown(event: KeyboardEvent) {\n  const tablist = (event.currentTarget as HTMLElement).parentElement\n  if (!tablist) return\n\n  const tabs = Array.from(tablist.querySelectorAll<HTMLElement>('[role=\"tab\"]'))\n  const currentIndex = tabs.indexOf(event.currentTarget as HTMLElement)\n\n  let targetIndex = -1\n\n  if (event.key === 'ArrowRight' || event.key === 'ArrowDown') {\n    targetIndex = (currentIndex + 1) % tabs.length\n  } else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') {\n    targetIndex = (currentIndex - 1 + tabs.length) % tabs.length\n  } else if (event.key === 'Home') {\n    targetIndex = 0\n  } else if (event.key === 'End') {\n    targetIndex = tabs.length - 1\n  }\n\n  if (targetIndex !== -1) {\n    event.preventDefault()\n    tabs[targetIndex].focus()\n  }\n}\n</script>\n","<template>\n  <div\n    role=\"tablist\"\n    :class=\"cn('flex w-full items-center gap-2', customClass)\"\n  >\n    <slot />\n  </div>\n</template>\n\n<script setup lang=\"ts\" generic=\"T extends string = string\">\nimport { provide } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { TAB_LIST_INJECTION_KEY } from './tabKeys'\n\nconst { class: customClass = '' } = defineProps<{ class?: string }>()\n\nconst modelValue = defineModel<T>({ required: true })\n\nfunction select(value: string) {\n  modelValue.value = value as T\n}\n\nprovide(TAB_LIST_INJECTION_KEY, {\n  modelValue,\n  select\n})\n</script>\n","import type { LGraphGroup, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { containsCentre, containsRect } from '@/lib/litegraph/src/measure'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\n/**\n * Composable for working with graph hierarchy, specifically group containment.\n */\nexport function useGraphHierarchy() {\n  const canvasStore = useCanvasStore()\n\n  /**\n   * Finds the smallest group that contains the center of a node's bounding box.\n   * When multiple groups contain the node, returns the one with the smallest area.\n   *\n   * TODO: This traverses the entire graph and could be very slow; needs optimization.\n   * Consider spatial indexing or caching for large graphs.\n   *\n   * @param node - The node to find the parent group for\n   * @returns The parent group if found, otherwise null\n   */\n  function findParentGroup(node: LGraphNode): LGraphGroup | null {\n    const graphGroups = canvasStore.canvas?.graph?.groups ?? []\n\n    let parent: LGraphGroup | null = null\n\n    for (const group of graphGroups) {\n      const groupRect = group.boundingRect\n      if (!containsCentre(groupRect, node.boundingRect)) continue\n\n      if (!parent) {\n        parent = group\n        continue\n      }\n\n      const parentRect = parent.boundingRect\n      const candidateInsideParent = containsRect(parentRect, groupRect)\n      const parentInsideCandidate = containsRect(groupRect, parentRect)\n\n      if (candidateInsideParent && !parentInsideCandidate) {\n        parent = group\n        continue\n      }\n\n      const candidateArea = groupRect[2] * groupRect[3]\n      const parentArea = parentRect[2] * parentRect[3]\n\n      if (candidateArea < parentArea) parent = group\n    }\n\n    return parent\n  }\n\n  return {\n    findParentGroup\n  }\n}\n","import type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { NodeSourceType, getNodeSource } from '@/types/nodeSource'\nimport { normalizePackId } from '@/utils/packUtils'\n\nexport function extractCustomNodeName(\n  pythonModule: string | undefined\n): string | null {\n  const modules = pythonModule?.split('.') || []\n  if (modules.length >= 2 && modules[0] === 'custom_nodes') {\n    // Use normalizePackId to remove version suffix\n    return normalizePackId(modules[1])\n  }\n  return null\n}\n\nexport function getNodeHelpBaseUrl(node: ComfyNodeDefImpl): string {\n  const nodeSource = getNodeSource(node.python_module)\n  if (nodeSource.type === NodeSourceType.Blueprint) {\n    return ''\n  }\n  if (nodeSource.type === NodeSourceType.CustomNodes) {\n    const customNodeName = extractCustomNodeName(node.python_module)\n    if (customNodeName) {\n      return `/extensions/${customNodeName}/docs/`\n    }\n  }\n  return `/docs/${node.name}/`\n}\n","import { api } from '@/scripts/api'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { NodeSourceType, getNodeSource } from '@/types/nodeSource'\nimport { extractCustomNodeName } from '@/workbench/utils/nodeHelpUtil'\n\nclass NodeHelpService {\n  async fetchNodeHelp(node: ComfyNodeDefImpl, locale: string): Promise<string> {\n    const nodeSource = getNodeSource(node.python_module)\n\n    if (nodeSource.type === NodeSourceType.Blueprint) {\n      return node.description || ''\n    }\n\n    if (nodeSource.type === NodeSourceType.CustomNodes) {\n      return this.fetchCustomNodeHelp(node, locale)\n    } else {\n      return this.fetchCoreNodeHelp(node, locale)\n    }\n  }\n\n  private async fetchCustomNodeHelp(\n    node: ComfyNodeDefImpl,\n    locale: string\n  ): Promise<string> {\n    const customNodeName = extractCustomNodeName(node.python_module)\n    let lastError: string | undefined\n    if (!customNodeName) {\n      throw new Error('Invalid custom node module')\n    }\n\n    // Try locale-specific path first\n    const localePath = `/extensions/${customNodeName}/docs/${node.name}/${locale}.md`\n    const localeDoc = await this.tryFetchMarkdown(localePath)\n    if (localeDoc.text) return localeDoc.text\n    lastError = localeDoc.errorText\n\n    // Fall back to non-locale path\n    const fallbackPath = `/extensions/${customNodeName}/docs/${node.name}.md`\n    const fallbackDoc = await this.tryFetchMarkdown(fallbackPath)\n    if (fallbackDoc.text) return fallbackDoc.text\n    lastError = fallbackDoc.errorText ?? lastError\n\n    throw new Error(lastError ?? 'Help not found')\n  }\n\n  private async fetchCoreNodeHelp(\n    node: ComfyNodeDefImpl,\n    locale: string\n  ): Promise<string> {\n    const mdUrl = `/docs/${node.name}/${locale}.md`\n    const doc = await this.tryFetchMarkdown(mdUrl)\n    if (!doc.text) {\n      throw new Error(doc.errorText ?? 'Help not found')\n    }\n\n    return doc.text\n  }\n\n  /**\n   * Fetch a markdown file and return its text, guarding against HTML/SPA fallbacks.\n   * Returns null when not OK or when the content type indicates HTML.\n   */\n  private async tryFetchMarkdown(\n    path: string\n  ): Promise<{ text: string | null; errorText?: string }> {\n    const res = await fetch(api.fileURL(path))\n\n    if (!res.ok) {\n      return { text: null, errorText: res.statusText }\n    }\n\n    const contentType = res.headers.get('content-type') ?? ''\n    const text = await res.text()\n\n    const isHtmlContentType = contentType.includes('text/html')\n\n    if (isHtmlContentType) return { text: null, errorText: res.statusText }\n\n    return { text }\n  }\n}\n\n// Export singleton instance\nexport const nodeHelpService = new NodeHelpService()\n","import type { MaybeRefOrGetter } from 'vue'\nimport { computed, ref, toValue, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { nodeHelpService } from '@/services/nodeHelpService'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { renderMarkdownToHtml } from '@/utils/markdownRendererUtil'\nimport { getNodeHelpBaseUrl } from '@/workbench/utils/nodeHelpUtil'\n\n/**\n * Composable for fetching and rendering node help content.\n * Creates independent state for each usage, allowing multiple panels\n * to show help content without interfering with each other.\n *\n * @param nodeRef - Reactive reference to the node to show help for\n * @returns Reactive help content state and rendered HTML\n */\nexport function useNodeHelpContent(\n  nodeRef: MaybeRefOrGetter<ComfyNodeDefImpl | null>\n) {\n  const { locale } = useI18n()\n\n  const helpContent = ref<string>('')\n  const isLoading = ref<boolean>(false)\n  const error = ref<string | null>(null)\n\n  let currentRequest: Promise<string> | null = null\n\n  const baseUrl = computed(() => {\n    const node = toValue(nodeRef)\n    if (!node) return ''\n    return getNodeHelpBaseUrl(node)\n  })\n\n  const renderedHelpHtml = computed(() => {\n    return renderMarkdownToHtml(helpContent.value, baseUrl.value)\n  })\n\n  // Watch for node changes and fetch help content\n  watch(\n    () => toValue(nodeRef),\n    async (node) => {\n      helpContent.value = ''\n      error.value = null\n\n      if (node) {\n        isLoading.value = true\n        const request = (currentRequest = nodeHelpService.fetchNodeHelp(\n          node,\n          locale.value || 'en'\n        ))\n\n        try {\n          const content = await request\n          if (currentRequest !== request) return\n          helpContent.value = content\n        } catch (e: unknown) {\n          if (currentRequest !== request) return\n          error.value = e instanceof Error ? e.message : String(e)\n          helpContent.value = node.description || ''\n        } finally {\n          if (currentRequest === request) {\n            currentRequest = null\n            isLoading.value = false\n          }\n        }\n      }\n    },\n    { immediate: true }\n  )\n\n  return {\n    helpContent,\n    isLoading,\n    error,\n    baseUrl,\n    renderedHelpHtml\n  }\n}\n","<template>\n  <div class=\"node-help-content mx-auto w-full\">\n    <Spinner v-if=\"isLoading\" class=\"m-auto\" :aria-label=\"$t('g.loading')\" />\n    <!-- Markdown fetched successfully -->\n    <SanitizedHtml\n      v-else-if=\"!error\"\n      class=\"markdown-content overflow-visible text-sm leading-(--text-sm--line-height)\"\n      :html=\"renderedHelpHtml\"\n    />\n    <!-- Fallback: markdown not found or fetch error -->\n    <div\n      v-else\n      class=\"fallback-content space-y-6 text-sm leading-(--text-sm--line-height)\"\n    >\n      <p v-if=\"node.description\">\n        <strong>{{ $t('g.description') }}:</strong> {{ node.description }}\n      </p>\n\n      <div v-if=\"inputList.length\">\n        <p>\n          <strong>{{ $t('nodeHelpPage.inputs') }}:</strong>\n        </p>\n        <!-- Using plain HTML table instead of DataTable for consistent styling with markdown content -->\n        <div class=\"overflow-x-auto\">\n          <table>\n            <thead>\n              <tr>\n                <th>{{ $t('g.name') }}</th>\n                <th>{{ $t('nodeHelpPage.type') }}</th>\n                <th>{{ $t('g.description') }}</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr v-for=\"input in inputList\" :key=\"input.name\">\n                <td>\n                  <code>{{ input.name }}</code>\n                </td>\n                <td>{{ input.type }}</td>\n                <td>{{ input.tooltip || '-' }}</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n      <div v-if=\"outputList.length\">\n        <p>\n          <strong>{{ $t('nodeHelpPage.outputs') }}:</strong>\n        </p>\n        <div class=\"overflow-x-auto\">\n          <table>\n            <thead>\n              <tr>\n                <th>{{ $t('g.name') }}</th>\n                <th>{{ $t('nodeHelpPage.type') }}</th>\n                <th>{{ $t('g.description') }}</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr v-for=\"output in outputList\" :key=\"output.name\">\n                <td>\n                  <code>{{ output.name }}</code>\n                </td>\n                <td>{{ output.type }}</td>\n                <td>{{ output.tooltip || '-' }}</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport SanitizedHtml from '@/components/common/SanitizedHtml.vue'\nimport Spinner from '@/components/ui/spinner/Spinner.vue'\nimport { useNodeHelpContent } from '@/composables/useNodeHelpContent'\nimport { flattenInputSpecs } from '@/schemas/nodeDef/inputSpecUtil'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\n\nconst { node } = defineProps<{\n  node: ComfyNodeDefImpl\n}>()\n\nconst { renderedHelpHtml, isLoading, error } = useNodeHelpContent(() => node)\n\nconst inputList = computed(() =>\n  flattenInputSpecs(node.inputs).map((spec) => ({\n    name: spec.name,\n    type: spec.type,\n    tooltip: spec.tooltip || ''\n  }))\n)\n\nconst outputList = computed(() =>\n  node.outputs.map((spec) => ({\n    name: spec.name,\n    type: spec.type,\n    tooltip: spec.tooltip || ''\n  }))\n)\n</script>\n\n<style scoped>\n.node-help-content :deep(:is(img, video)) {\n  display: block;\n  max-width: 100%;\n  height: auto;\n  margin-bottom: calc(var(--spacing) * 4);\n}\n\n.markdown-content :deep(h1),\n.fallback-content h1 {\n  margin-top: calc(var(--spacing) * 8);\n  margin-bottom: calc(var(--spacing) * 4);\n  font-size: var(--text-2xl);\n  font-weight: var(--font-weight-bold);\n}\n\n.markdown-content :deep(h2),\n.fallback-content h2 {\n  margin-top: calc(var(--spacing) * 8);\n  margin-bottom: calc(var(--spacing) * 4);\n  font-size: var(--text-lg);\n  font-weight: var(--font-weight-bold);\n}\n\n.markdown-content :deep(h3),\n.fallback-content h3 {\n  margin-top: calc(var(--spacing) * 8);\n  margin-bottom: calc(var(--spacing) * 4);\n  font-size: var(--text-base);\n  font-weight: var(--font-weight-bold);\n}\n\n.markdown-content :deep(h4),\n.fallback-content h4 {\n  margin-top: calc(var(--spacing) * 8);\n  margin-bottom: calc(var(--spacing) * 4);\n  font-size: var(--text-sm);\n  font-weight: var(--font-weight-bold);\n}\n\n.markdown-content :deep(h5),\n.fallback-content h5 {\n  margin-top: calc(var(--spacing) * 8);\n  margin-bottom: calc(var(--spacing) * 4);\n  font-size: var(--text-sm);\n  font-weight: var(--font-weight-bold);\n}\n\n.markdown-content :deep(h6),\n.fallback-content h6 {\n  margin-top: calc(var(--spacing) * 8);\n  margin-bottom: calc(var(--spacing) * 4);\n  font-size: var(--text-xs);\n  font-weight: var(--font-weight-bold);\n}\n\n.markdown-content :deep(td),\n.fallback-content td {\n  color: var(--drag-text);\n}\n\n.markdown-content :deep(a),\n.fallback-content a {\n  color: var(--drag-text);\n  text-decoration: underline;\n}\n\n.markdown-content :deep(th),\n.fallback-content th {\n  color: var(--fg-color);\n}\n\n.markdown-content :deep(ul),\n.markdown-content :deep(ol),\n.fallback-content ul,\n.fallback-content ol {\n  margin-block: calc(var(--spacing) * 2);\n  padding-left: calc(var(--spacing) * 8);\n}\n\n.markdown-content :deep(ul ul),\n.markdown-content :deep(ol ol),\n.markdown-content :deep(ul ol),\n.markdown-content :deep(ol ul),\n.fallback-content ul ul,\n.fallback-content ol ol,\n.fallback-content ul ol,\n.fallback-content ol ul {\n  margin-block: calc(var(--spacing) * 2);\n  padding-left: calc(var(--spacing) * 6);\n}\n\n.markdown-content :deep(li),\n.fallback-content li {\n  margin-block: calc(var(--spacing) * 2);\n}\n\n.markdown-content :deep(*:first-child),\n.fallback-content > *:first-child {\n  margin-top: 0;\n}\n\n.markdown-content :deep(code),\n.fallback-content code {\n  color: var(--code-text-color);\n  background-color: var(--code-bg-color);\n  border-radius: var(--radius);\n  padding: calc(var(--spacing) * 0.5) calc(var(--spacing) * 1.5);\n}\n\n.markdown-content :deep(table),\n.fallback-content table {\n  border-collapse: collapse;\n}\n\n.fallback-content table {\n  width: 100%;\n}\n\n.markdown-content :deep(th),\n.markdown-content :deep(td),\n.fallback-content th,\n.fallback-content td {\n  padding: calc(var(--spacing) * 2);\n}\n\n.markdown-content :deep(tr),\n.fallback-content tr {\n  border-bottom: 1px solid var(--content-bg);\n}\n\n.markdown-content :deep(tr:last-child),\n.fallback-content tr:last-child {\n  border-bottom: none;\n}\n\n.markdown-content :deep(thead),\n.fallback-content thead {\n  border-bottom: 1px solid var(--p-text-color);\n}\n\n.markdown-content :deep(pre),\n.fallback-content pre {\n  margin-block: calc(var(--spacing) * 4);\n  overflow-x: auto;\n  border-radius: var(--radius);\n  padding: calc(var(--spacing) * 4);\n  background-color: var(--code-block-bg-color);\n\n  code {\n    background-color: transparent;\n    padding: 0;\n    color: var(--p-text-color);\n  }\n}\n\n.markdown-content :deep(table) {\n  display: block;\n  width: 100%;\n  overflow-x: auto;\n}\n</style>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport NodeHelpContent from '@/components/node/NodeHelpContent.vue'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\n\nconst { nodes } = defineProps<{\n  nodes: LGraphNode[]\n}>()\nconst node = computed(() => nodes[0])\n\nconst nodeDefStore = useNodeDefStore()\n\nconst nodeInfo = computed(() => {\n  return nodeDefStore.fromLGraphNode(node.value)\n})\n</script>\n\n<template>\n  <div v-if=\"nodeInfo\" class=\"p-3\">\n    <NodeHelpContent :node=\"nodeInfo\" />\n  </div>\n</template>\n","import type { InjectionKey, MaybeRefOrGetter } from 'vue'\nimport { computed, toValue } from 'vue'\nimport Fuse from 'fuse.js'\nimport type { IFuseOptions } from 'fuse.js'\n\nimport type { Positionable } from '@/lib/litegraph/src/interfaces'\nimport type { LGraphGroup } from '@/lib/litegraph/src/LGraphGroup'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport type { NodeId } from '@/types/nodeId'\nimport {\n  deriveWidgetVisibility,\n  isWidgetVisibleOnSurface\n} from '@/types/widgetVisibility'\nimport { isLGraphGroup, isLGraphNode } from '@/utils/litegraphUtil'\nimport { useSettingStore } from '@/platform/settings/settingStore'\n\nexport const GetNodeParentGroupKey: InjectionKey<\n  (node: LGraphNode) => LGraphGroup | null\n> = Symbol('getNodeParentGroup')\n\nexport type NodeWidgetsList = Array<{ node: LGraphNode; widget: IBaseWidget }>\nexport type NodeWidgetsListList = Array<{\n  node: LGraphNode\n  widgets: NodeWidgetsList\n}>\n\ninterface WidgetSearchItem {\n  index: number\n  searchableLabel: string\n  searchableName: string\n  searchableType: string\n  searchableValue: string\n}\n\n/**\n * Searches widgets in a list using fuzzy search and returns search results.\n * Uses Fuse.js for better matching with typo tolerance and relevance ranking.\n * Filters by name, localized label, type, and user-input value.\n */\nexport function searchWidgets<T extends { widget: IBaseWidget }[]>(\n  list: T,\n  query: string\n): T {\n  if (query.trim() === '') {\n    return list\n  }\n\n  const searchableList: WidgetSearchItem[] = list.map((item, index) => {\n    const searchableItem = {\n      index,\n      searchableLabel: item.widget.label?.toLowerCase() || '',\n      searchableName: item.widget.name.toLowerCase(),\n      searchableType: item.widget.type.toLowerCase(),\n      searchableValue: item.widget.value?.toString().toLowerCase() || ''\n    }\n    return searchableItem\n  })\n\n  const fuseOptions: IFuseOptions<WidgetSearchItem> = {\n    keys: [\n      { name: 'searchableName', weight: 0.4 },\n      { name: 'searchableLabel', weight: 0.3 },\n      { name: 'searchableValue', weight: 0.3 },\n      { name: 'searchableType', weight: 0.2 }\n    ],\n    threshold: 0.3\n  }\n\n  const fuse = new Fuse(searchableList, fuseOptions)\n  const results = fuse.search(query.trim())\n\n  const matchedItems = new Set(results.map((result) => list[result.item.index]))\n\n  return list.filter((item) => matchedItems.has(item)) as T\n}\n\ntype NodeSearchItem = {\n  nodeId: NodeId\n  searchableTitle: string\n}\n\n/**\n * Searches widgets and nodes in a list using fuzzy search and returns search results.\n * Uses Fuse.js for node title matching with typo tolerance and relevance ranking.\n * First checks if the node title matches the query (if so, keeps entire node).\n * Otherwise, filters widgets using searchWidgets.\n */\nexport function searchWidgetsAndNodes(\n  list: NodeWidgetsListList,\n  query: string\n): NodeWidgetsListList {\n  if (query.trim() === '') {\n    return list\n  }\n\n  const searchableList: NodeSearchItem[] = list.map((item) => ({\n    nodeId: item.node.id,\n    searchableTitle: (item.node.getTitle() ?? item.node.type).toLowerCase()\n  }))\n\n  const fuseOptions: IFuseOptions<NodeSearchItem> = {\n    keys: [{ name: 'searchableTitle', weight: 1.0 }],\n    threshold: 0.3\n  }\n\n  const fuse = new Fuse(searchableList, fuseOptions)\n  const nodeMatches = fuse.search(query.trim())\n  const matchedNodeIds = new Set(\n    nodeMatches.map((result) => result.item.nodeId)\n  )\n\n  return list.flatMap((item) => {\n    if (matchedNodeIds.has(item.node.id)) {\n      return [item]\n    }\n\n    const widgets = searchWidgets(item.widgets, query)\n    return widgets.length > 0 ? [{ ...item, widgets }] : []\n  })\n}\n\ntype MixedSelectionItem = LGraphGroup | LGraphNode\ntype FlatAndCategorizeSelectedItemsResult = {\n  all: MixedSelectionItem[]\n  nodes: LGraphNode[]\n  groups: LGraphGroup[]\n  others: Positionable[]\n  nodeToParentGroup: Map<LGraphNode, LGraphGroup>\n}\n\ntype FlatItemsContext = {\n  nodeToParentGroup: Map<LGraphNode, LGraphGroup>\n  depth: number\n  parentGroup?: LGraphGroup\n}\n\n/**\n * The selected items may contain \"Group\" nodes, which can include child nodes.\n * This function flattens such structures and categorizes items into:\n * - all: all categorizable nodes (does not include nodes in \"others\")\n * - nodes: node items\n * - groups: group items\n * - others: items not currently supported\n * - nodeToParentGroup: a map from each node to its direct parent group (if any)\n * @param items The selected items to flatten and categorize\n * @returns An object containing arrays: all, nodes, groups, others, and nodeToParentGroup map\n */\nexport function flatAndCategorizeSelectedItems(\n  items: Positionable[]\n): FlatAndCategorizeSelectedItemsResult {\n  const ctx: FlatItemsContext = {\n    nodeToParentGroup: new Map<LGraphNode, LGraphGroup>(),\n    depth: 0\n  }\n  const { all, nodes, groups, others } = flatItems(items, ctx)\n  return {\n    all: repeatItems(all),\n    nodes: repeatItems(nodes),\n    groups: repeatItems(groups),\n    others: repeatItems(others),\n    nodeToParentGroup: ctx.nodeToParentGroup\n  }\n}\n\nexport function useFlatAndCategorizeSelectedItems(\n  items: MaybeRefOrGetter<Positionable[]>\n) {\n  const result = computed(() => flatAndCategorizeSelectedItems(toValue(items)))\n\n  return {\n    flattedItems: computed(() => result.value.all),\n    selectedNodes: computed(() => result.value.nodes),\n    selectedGroups: computed(() => result.value.groups),\n    selectedOthers: computed(() => result.value.others),\n    nodeToParentGroup: computed(() => result.value.nodeToParentGroup)\n  }\n}\n\nfunction flatItems(\n  items: Positionable[],\n  ctx: FlatItemsContext\n): Omit<FlatAndCategorizeSelectedItemsResult, 'nodeToParentGroup'> {\n  const result: MixedSelectionItem[] = []\n  const nodes: LGraphNode[] = []\n  const groups: LGraphGroup[] = []\n  const others: Positionable[] = []\n\n  if (ctx.depth > 1000) {\n    return {\n      all: [],\n      nodes: [],\n      groups: [],\n      others: []\n    }\n  }\n\n  for (let i = 0; i < items.length; i++) {\n    const item = items[i]\n\n    if (isLGraphGroup(item)) {\n      result.push(item)\n      groups.push(item)\n\n      const children = Array.from(item.children)\n      const childCtx: FlatItemsContext = {\n        nodeToParentGroup: ctx.nodeToParentGroup,\n        depth: ctx.depth + 1,\n        parentGroup: item\n      }\n      const {\n        all: childAll,\n        nodes: childNodes,\n        groups: childGroups,\n        others: childOthers\n      } = flatItems(children, childCtx)\n      result.push(...childAll)\n      nodes.push(...childNodes)\n      groups.push(...childGroups)\n      others.push(...childOthers)\n    } else if (isLGraphNode(item)) {\n      result.push(item)\n      nodes.push(item)\n      if (ctx.parentGroup) {\n        ctx.nodeToParentGroup.set(item, ctx.parentGroup)\n      }\n    } else {\n      // Other types of items are not supported yet\n      // Do not add to all\n      others.push(item)\n    }\n  }\n  return {\n    all: result,\n    nodes,\n    groups,\n    others\n  }\n}\n\nfunction repeatItems<T>(items: T[]): T[] {\n  const itemSet = new Set<T>()\n  const result: T[] = []\n  for (const item of items) {\n    if (itemSet.has(item)) continue\n    itemSet.add(item)\n    result.push(item)\n  }\n  return result\n}\n\nexport function computedSectionDataList(nodes: MaybeRefOrGetter<LGraphNode[]>) {\n  const settingStore = useSettingStore()\n\n  const includesAdvanced = computed(() =>\n    settingStore.get('Comfy.Node.AlwaysShowAdvancedWidgets')\n  )\n\n  const widgetsSectionDataList = computed((): NodeWidgetsListList => {\n    return toValue(nodes).map((node) => {\n      const { widgets = [] } = node\n      const shownWidgets = widgets\n        .filter((w) =>\n          isWidgetVisibleOnSurface(\n            w.visibility ?? deriveWidgetVisibility(w),\n            'panel',\n            { showAdvanced: includesAdvanced.value }\n          )\n        )\n        .map((widget) => ({ node, widget }))\n      return { widgets: shownWidgets, node }\n    })\n  })\n\n  return {\n    widgetsSectionDataList,\n    includesAdvanced\n  }\n}\n","<script setup lang=\"ts\">\nimport type { ComponentProps } from 'vue-component-type-helpers'\n\nimport AsyncSearchInput from '@/components/ui/search-input/AsyncSearchInput.vue'\n\ntype AsyncSearchInputProps = ComponentProps<typeof AsyncSearchInput>\n\nconst { searcher, updateKey } = defineProps<{\n  searcher?: AsyncSearchInputProps['searcher']\n  updateKey?: AsyncSearchInputProps['updateKey']\n}>()\n\nconst emit = defineEmits<{\n  enter: [event: KeyboardEvent]\n}>()\n\nconst query = defineModel<string>({ default: '' })\n\ndefineOptions({ inheritAttrs: false })\n</script>\n\n<template>\n  <div\n    class=\"flex items-center border-b border-interface-stroke px-4 pt-1 pb-4\"\n  >\n    <AsyncSearchInput\n      v-model=\"query\"\n      :searcher\n      :update-key=\"updateKey\"\n      class=\"flex-1\"\n      @enter=\"emit('enter', $event)\"\n    />\n    <slot />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { isEqual } from 'es-toolkit'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { inputForWidget } from '@/core/graph/subgraph/promotedInputWidget'\nimport { promoteWidget } from '@/core/graph/subgraph/promotionUtils'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { useFavoritedWidgetsStore } from '@/stores/workspace/favoritedWidgetsStore'\nimport { getWidgetDefaultValue, promptWidgetLabel } from '@/utils/widgetUtil'\nimport type { WidgetValue } from '@/utils/widgetUtil'\n\nconst { widget, node, host } = defineProps<{\n  widget: IBaseWidget\n  node: LGraphNode\n  host?: SubgraphNode\n}>()\n\nconst emit = defineEmits<{\n  resetToDefault: [value: WidgetValue]\n}>()\n\nconst label = defineModel<string>('label', { required: true })\n\nconst favoritedWidgetsStore = useFavoritedWidgetsStore()\nconst nodeDefStore = useNodeDefStore()\nconst { t } = useI18n()\n\nconst isLinked = computed(() => {\n  if (!node.isSubgraphNode()) return false\n  return inputForWidget(node, widget)?.widgetId != null\n})\nconst canShowInput = computed(() => host != null && !isLinked.value)\nconst isFavorited = computed(() =>\n  favoritedWidgetsStore.isFavorited(node, widget.name)\n)\n\nconst inputSpec = computed(() =>\n  nodeDefStore.getInputSpecForWidget(node, widget.name)\n)\n\nconst defaultValue = computed(() => getWidgetDefaultValue(inputSpec.value))\n\nconst hasDefault = computed(() => defaultValue.value !== undefined)\n\nconst currentValue = computed(() => {\n  if (!widget.widgetId) return widget.value\n  const state = useWidgetValueStore().getWidget(widget.widgetId)\n  return state ? state.value : widget.value\n})\n\nconst isCurrentValueDefault = computed(() => {\n  if (!hasDefault.value) return true\n  return isEqual(currentValue.value, defaultValue.value)\n})\n\nasync function handleRename() {\n  const newLabel = await promptWidgetLabel(widget, t)\n  if (newLabel !== null) label.value = newLabel\n}\n\nfunction handleShowInput() {\n  if (!host) return\n  promoteWidget(node, widget, [host])\n}\n\nfunction handleToggleFavorite() {\n  useTelemetry()?.trackWidgetFavoriteToggled({\n    node_type: node.type,\n    widget_name: widget.name,\n    widget_type: widget.type,\n    is_favorited: !isFavorited.value,\n    source: 'right_side_panel'\n  })\n  favoritedWidgetsStore.toggleFavorite(node, widget.name)\n}\n\nfunction handleResetToDefault() {\n  if (!hasDefault.value) return\n  emit('resetToDefault', defaultValue.value)\n}\n\nconst menuItems = computed<MenuItem[]>(() => [\n  {\n    label: () => t('g.rename'),\n    icon: 'icon-[lucide--edit]',\n    command: handleRename\n  },\n  {\n    label: () => t('rightSidePanel.showInput'),\n    icon: 'icon-[lucide--eye]',\n    visible: () => canShowInput.value,\n    command: handleShowInput\n  },\n  {\n    label: () =>\n      t(\n        isFavorited.value\n          ? 'rightSidePanel.removeFavorite'\n          : 'rightSidePanel.addFavorite'\n      ),\n    icon: 'icon-[lucide--star]',\n    command: handleToggleFavorite\n  },\n  {\n    label: () => t('rightSidePanel.resetToDefault'),\n    icon: 'icon-[lucide--rotate-ccw]',\n    visible: () => hasDefault.value,\n    disabled: () => isCurrentValueDefault.value,\n    command: handleResetToDefault\n  }\n])\n</script>\n\n<template>\n  <Menu :items=\"menuItems\" align=\"end\">\n    <template #trigger>\n      <Button\n        size=\"icon\"\n        variant=\"muted-textonly\"\n        data-testid=\"widget-actions-menu-button\"\n        icon=\"icon-[lucide--more-vertical]\"\n        :aria-label=\"t('g.more')\"\n      />\n    </template>\n  </Menu>\n</template>\n","<script setup lang=\"ts\">\nimport { computed, customRef, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport EditableText from '@/components/common/EditableText.vue'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport WidgetLegacy from '@/renderer/extensions/vueNodes/widgets/components/WidgetLegacy.vue'\nimport {\n  getComponent,\n  shouldExpand\n} from '@/renderer/extensions/vueNodes/widgets/registry/widgetRegistry'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport {\n  stripGraphPrefix,\n  useWidgetValueStore\n} from '@/stores/widgetValueStore'\nimport { useFavoritedWidgetsStore } from '@/stores/workspace/favoritedWidgetsStore'\nimport { getControlWidget } from '@/types/simplifiedWidget'\nimport type {\n  SimplifiedWidget,\n  WidgetValue as SimplifiedWidgetValue\n} from '@/types/simplifiedWidget'\nimport { widgetId } from '@/types/widgetId'\nimport { resolveNodeDisplayName } from '@/utils/nodeTitleUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { renameWidget } from '@/utils/widgetUtil'\nimport type { WidgetValue } from '@/utils/widgetUtil'\n\nimport WidgetActions from './WidgetActions.vue'\n\nconst {\n  widget,\n  node,\n  isDraggable = false,\n  hiddenFavoriteIndicator = false,\n  hiddenWidgetActions = false,\n  showNodeName = false,\n  parents = [],\n  isShownOnParents = false\n} = defineProps<{\n  widget: IBaseWidget\n  node: LGraphNode\n  isDraggable?: boolean\n  hiddenFavoriteIndicator?: boolean\n  hiddenWidgetActions?: boolean\n  showNodeName?: boolean\n  parents?: SubgraphNode[]\n  isShownOnParents?: boolean\n}>()\n\nconst emit = defineEmits<{\n  'update:widgetValue': [value: WidgetValue]\n  resetToDefault: [value: WidgetValue]\n}>()\n\nconst { t } = useI18n()\n\nconst canvasStore = useCanvasStore()\nconst nodeDefStore = useNodeDefStore()\nconst widgetValueStore = useWidgetValueStore()\nconst favoritedWidgetsStore = useFavoritedWidgetsStore()\nconst linkStore = useLinkStore()\nconst isEditing = ref(false)\n\nconst widgetComponent = computed(() => {\n  const component = getComponent(widget.type)\n  return component || WidgetLegacy\n})\n\nconst isLinked = computed(() => {\n  const graph = node.graph\n  const slot = node.inputs?.findIndex((i) => i.widget?.name === widget.name)\n  if (!graph || slot === undefined || slot < 0) return false\n  return linkStore.isInputSlotConnected(graphScopeOf(graph), node.id, slot)\n})\n\nconst simplifiedWidget = computed((): SimplifiedWidget => {\n  const graphId = node.graph?.rootGraph.id\n  const bareNodeId = stripGraphPrefix(node.id)\n  const widgetState = widget.widgetId\n    ? useWidgetValueStore().getWidget(widget.widgetId)\n    : graphId && bareNodeId\n      ? widgetValueStore.getWidget(widgetId(graphId, bareNodeId, widget.name))\n      : undefined\n  const widgetName = widgetState?.name ?? widget.name\n  const widgetType = widgetState?.type ?? widget.type\n\n  const baseOptions = widgetState?.options ?? widget.options\n  const disabled = isLinked.value || !!widget.disabled || undefined\n  return {\n    name: widgetName,\n    type: widgetType,\n    value: (widgetState\n      ? widgetState.value\n      : widget.value) as SimplifiedWidgetValue,\n    label: widgetState?.label ?? widget.label,\n    options: { ...baseOptions, disabled },\n    callback:\n      widgetType.toLowerCase() === 'button'\n        ? (value) =>\n            widget.callback?.(value, canvasStore.canvas ?? undefined, node)\n        : undefined,\n    spec: nodeDefStore.getInputSpecForWidget(node, widgetName),\n    controlWidget: getControlWidget(widget)\n  }\n})\n\nconst displayNodeName = computed((): string | null => {\n  if (!node) return null\n  const fallbackNodeTitle = t('rightSidePanel.fallbackNodeTitle')\n  return resolveNodeDisplayName(node, {\n    emptyLabel: fallbackNodeTitle,\n    untitledLabel: fallbackNodeTitle\n  })\n})\n\nconst hasParents = computed(() => parents.length > 0)\nconst favoriteNode = computed(() =>\n  isShownOnParents && hasParents.value ? parents[0] : node\n)\n\nconst widgetValue = computed({\n  get: () => widget.value,\n  set: (newValue: WidgetValue) => {\n    emit('update:widgetValue', newValue)\n  }\n})\n\nconst displayLabel = customRef((track, trigger) => {\n  return {\n    get() {\n      track()\n      return widget.label || widget.name\n    },\n    set(newValue: string) {\n      isEditing.value = false\n\n      const trimmedLabel = newValue.trim()\n\n      const success = renameWidget(widget, node, trimmedLabel)\n\n      if (success) {\n        canvasStore.canvas?.setDirty(true)\n        trigger()\n      }\n    }\n  }\n})\n</script>\n\n<template>\n  <div\n    :class=\"\n      cn(\n        'widget-item group col-span-full grid grid-cols-subgrid rounded-lg',\n        isDraggable &&\n          'draggable-item drag-handle cursor-grab bg-comfy-menu-bg outline-comfy-menu-bg will-change-auto! [&.is-draggable]:cursor-grabbing [&.is-draggable]:opacity-70 [&.is-draggable]:outline-4 [&.is-draggable]:outline-offset-0'\n      )\n    \"\n  >\n    <!-- widget header -->\n    <div\n      :class=\"\n        cn(\n          'mb-1.5 flex min-h-8 min-w-0 items-center justify-between gap-1',\n          isDraggable && 'pointer-events-none'\n        )\n      \"\n    >\n      <EditableText\n        v-if=\"widget.name\"\n        :model-value=\"displayLabel\"\n        :is-editing\n        :input-attrs=\"{ placeholder: widget.name }\"\n        class=\"pointer-events-auto m-0 cursor-text truncate p-0 text-sm/8\"\n        @edit=\"displayLabel = $event\"\n        @cancel=\"isEditing = false\"\n        @click=\"isEditing = true\"\n      />\n\n      <span\n        v-if=\"(showNodeName || hasParents) && displayNodeName\"\n        class=\"mx-1 my-0 min-w-10 flex-1 truncate p-0 text-right text-xs text-muted-foreground\"\n      >\n        {{ displayNodeName }}\n      </span>\n      <div\n        v-if=\"!hiddenWidgetActions\"\n        class=\"pointer-events-auto flex shrink-0 items-center gap-1\"\n      >\n        <WidgetActions\n          v-model:label=\"displayLabel\"\n          :widget\n          :node\n          :parents\n          :is-shown-on-parents\n          @reset-to-default=\"emit('resetToDefault', $event)\"\n        />\n      </div>\n    </div>\n    <!-- favorite indicator -->\n    <div\n      v-if=\"\n        !hiddenFavoriteIndicator &&\n        favoritedWidgetsStore.isFavorited(favoriteNode, widget.name)\n      \"\n      class=\"pointer-events-none relative z-2\"\n    >\n      <i\n        class=\"pi pi-star-fill pointer-events-none absolute -top-1 -right-1 text-xs text-muted-foreground\"\n      />\n    </div>\n    <!-- widget content -->\n    <component\n      :is=\"widgetComponent\"\n      v-model=\"widgetValue\"\n      :widget=\"simplifiedWidget\"\n      :node-id=\"node.id\"\n      :node-type=\"node.type\"\n      :class=\"cn('col-span-1', shouldExpand(widget.type) && 'min-h-36')\"\n    />\n    <!-- Drag handle -->\n    <div\n      :class=\"\n        cn(\n          'pointer-events-none mx-auto mt-1.5 h-1 w-1/2 max-w-40 rounded-lg bg-transparent transition-colors duration-150',\n          'group-hover:bg-interface-stroke group-[.is-draggable]:bg-component-node-widget-background-highlighted',\n          !isDraggable && 'opacity-0'\n        )\n      \"\n    />\n  </div>\n</template>\n","import type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\n\nconst widgetRenderKeys = new WeakMap<IBaseWidget, string>()\nlet nextWidgetRenderKeyId = 0\n\nexport function getStableWidgetRenderKey(widget: IBaseWidget): string {\n  const cachedKey = widgetRenderKeys.get(widget)\n  if (cachedKey) return cachedKey\n\n  const key = `widget:${nextWidgetRenderKeyId++}`\n  widgetRenderKeys.set(widget, key)\n  return key\n}\n","<script setup lang=\"ts\">\nimport { watchDebounced } from '@vueuse/core'\nimport {\n  computed,\n  inject,\n  onBeforeUnmount,\n  onMounted,\n  provide,\n  ref,\n  shallowRef,\n  watchEffect\n} from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { resolvePromotedWidgetSource } from '@/core/graph/subgraph/resolvePromotedWidgetSource'\nimport type { LGraphGroup, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { SubgraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { DraggableList } from '@/scripts/ui/draggableList'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { getExecutionIdByNode } from '@/utils/graphTraversalUtil'\nimport { getWidgetDefaultValue } from '@/utils/widgetUtil'\nimport type { WidgetValue } from '@/utils/widgetUtil'\n\nimport PropertiesAccordionItem from '../layout/PropertiesAccordionItem.vue'\nimport { HideLayoutFieldKey, WidgetHeightKey } from '@/types/widgetTypes'\n\nimport { GetNodeParentGroupKey } from '../shared'\nimport WidgetItem from './WidgetItem.vue'\nimport { getStableWidgetRenderKey } from '@/core/graph/subgraph/widgetRenderKey'\n\nconst {\n  label,\n  node,\n  widgets: widgetsProp,\n  showLocateButton = false,\n  isDraggable = false,\n  hiddenFavoriteIndicator = false,\n  showNodeName = false,\n  host,\n  enableEmptyState = false,\n  tooltip\n} = defineProps<{\n  label?: string\n  host?: SubgraphNode\n  node?: LGraphNode\n  widgets: { widget: IBaseWidget; node: LGraphNode }[]\n  showLocateButton?: boolean\n  isDraggable?: boolean\n  hiddenFavoriteIndicator?: boolean\n  showNodeName?: boolean\n  /**\n   * Whether to show the empty state slot when there are no widgets.\n   */\n  enableEmptyState?: boolean\n  tooltip?: string\n}>()\n\nconst collapse = defineModel<boolean>('collapse', { default: false })\n\nconst emit = defineEmits<{\n  reorder: [event: { fromIndex: number; toIndex: number }]\n}>()\n\nconst widgetsContainer = ref<HTMLElement>()\nconst rootElement = ref<HTMLElement>()\n\nconst widgets = shallowRef(widgetsProp)\nwatchEffect(() => (widgets.value = widgetsProp))\n\nconst draggableList = ref<DraggableList | undefined>()\n\nfunction setDraggableState() {\n  draggableList.value?.dispose()\n  draggableList.value = undefined\n\n  if (!isDraggable || collapse.value) return\n  const container = widgetsContainer.value\n  if (!container?.children?.length) return\n\n  const list = new DraggableList(container, '.draggable-item')\n\n  list.applyNewItemsOrder = function () {\n    if (!this.draggableItem) return\n    const { items, oldPosition } = this.getReorderedItems(this.draggableItem)\n\n    if (oldPosition === -1) {\n      console.error('[SectionWidgets] draggableItem not found in items')\n      return\n    }\n\n    const newPosition = items.indexOf(this.draggableItem)\n\n    emit('reorder', { fromIndex: oldPosition, toIndex: newPosition })\n  }\n\n  draggableList.value = list\n}\n\nwatchDebounced(\n  [widgets, () => isDraggable, collapse],\n  () => setDraggableState(),\n  { debounce: 100 }\n)\nonMounted(setDraggableState)\nonBeforeUnmount(() => draggableList.value?.dispose())\n\nprovide(HideLayoutFieldKey, true)\nprovide(WidgetHeightKey, 'h-7')\n\nconst canvasStore = useCanvasStore()\nconst executionErrorStore = useExecutionErrorStore()\nconst rightSidePanelStore = useRightSidePanelStore()\nconst nodeDefStore = useNodeDefStore()\nconst { t } = useI18n()\n\nconst getNodeParentGroup = inject(GetNodeParentGroupKey, null)\n\nconst isEmpty = computed(() => widgets.value.length === 0)\n\nconst displayLabel = computed(\n  () => label ?? (node ? node.title : t('rightSidePanel.inputs'))\n)\n\nconst targetNode = computed<LGraphNode | null>(() => {\n  if (node) return node\n  if (isEmpty.value) return null\n\n  const firstNodeId = widgets.value[0].node.id\n  const allSameNode = widgets.value.every(({ node }) => node.id === firstNodeId)\n\n  return allSameNode ? widgets.value[0].node : null\n})\n\nconst hasDirectError = computed(() => {\n  if (!targetNode.value) return false\n  return executionErrorStore.activeGraphErrorNodeIds.has(\n    String(targetNode.value.id)\n  )\n})\n\nconst hasContainerInternalError = computed(() => {\n  if (!targetNode.value) return false\n  if (!(targetNode.value instanceof SubgraphNode)) return false\n\n  return executionErrorStore.isContainerWithInternalError(targetNode.value)\n})\n\nconst nodeHasError = computed(() => {\n  if (!targetNode.value) return false\n  if (canvasStore.selectedItems.length === 1) return false\n  return hasDirectError.value || hasContainerInternalError.value\n})\n\nconst showSeeError = computed(\n  () =>\n    nodeHasError.value &&\n    useSettingStore().get('Comfy.RightSidePanel.ShowErrorsTab')\n)\n\nconst parentGroup = computed<LGraphGroup | null>(() => {\n  if (!targetNode.value || !getNodeParentGroup) return null\n  return getNodeParentGroup(targetNode.value)\n})\n\nconst canShowLocateButton = computed(\n  () => showLocateButton && targetNode.value !== null\n)\n\nfunction handleLocateNode() {\n  if (!targetNode.value || !canvasStore.canvas) return\n\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'right_side_panel_locate_node_clicked',\n    element_group: 'right_side_panel_nodes'\n  })\n\n  const graphNode = canvasStore.canvas.graph?.getNodeById(targetNode.value.id)\n  if (graphNode) {\n    canvasStore.canvas.animateToBounds(graphNode.boundingRect)\n  }\n}\n\nfunction navigateToErrorTab() {\n  if (!targetNode.value) return\n  if (!useSettingStore().get('Comfy.RightSidePanel.ShowErrorsTab')) return\n  rightSidePanelStore.focusedErrorNodeId = String(targetNode.value.id)\n  rightSidePanelStore.openPanel('errors')\n}\n\nfunction clearWidgetErrors(\n  widgetNode: LGraphNode,\n  widget: IBaseWidget,\n  value: WidgetValue\n) {\n  const rootGraph = widgetNode.graph?.rootGraph\n  if (!rootGraph) return\n\n  const executionId = getExecutionIdByNode(rootGraph, widgetNode)\n  if (!executionId) return\n\n  const options = { min: widget.options?.min, max: widget.options?.max }\n  const source = resolvePromotedWidgetSource(rootGraph, widgetNode, widget)\n  if (source?.sourceExecutionId) {\n    executionErrorStore.clearWidgetRelatedErrors(\n      source.sourceExecutionId,\n      source.sourceWidgetName,\n      source.sourceWidgetName,\n      value,\n      {\n        min: source.sourceWidget.options?.min,\n        max: source.sourceWidget.options?.max\n      }\n    )\n  }\n\n  executionErrorStore.clearWidgetRelatedErrors(\n    executionId,\n    widget.name,\n    widget.name,\n    value,\n    options\n  )\n}\n\nfunction setWidgetValue(\n  widgetNode: LGraphNode,\n  widget: IBaseWidget,\n  value: WidgetValue\n) {\n  // Store-backed widgets (interior node widgets and promoted subgraph inputs)\n  // are addressed by widgetId; writing there keeps the displayed value in sync.\n  if (widget.widgetId) useWidgetValueStore().setValue(widget.widgetId, value)\n  widget.value = value\n  widget.callback?.(value)\n  clearWidgetErrors(widgetNode, widget, value)\n  canvasStore.canvas?.setDirty(true, true)\n}\n\nfunction handleResetAllWidgets() {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'right_side_panel_reset_all_parameters_clicked',\n    element_group: 'right_side_panel_nodes'\n  })\n\n  for (const { widget, node: widgetNode } of widgetsProp) {\n    const spec = nodeDefStore.getInputSpecForWidget(widgetNode, widget.name)\n    const defaultValue = getWidgetDefaultValue(spec)\n    if (defaultValue !== undefined) {\n      setWidgetValue(widgetNode, widget, defaultValue)\n    }\n  }\n}\n\nfunction handleWidgetValueUpdate(\n  widgetNode: LGraphNode,\n  widget: IBaseWidget,\n  newValue: WidgetValue\n) {\n  if (newValue === undefined) return\n  setWidgetValue(widgetNode, widget, newValue)\n}\n\nfunction handleWidgetReset(\n  widgetNode: LGraphNode,\n  widget: IBaseWidget,\n  newValue: WidgetValue\n) {\n  setWidgetValue(widgetNode, widget, newValue)\n}\n\ndefineExpose({\n  widgetsContainer,\n  rootElement\n})\n</script>\n\n<template>\n  <div ref=\"rootElement\">\n    <PropertiesAccordionItem\n      v-model:collapse=\"collapse\"\n      :enable-empty-state\n      :disabled=\"isEmpty\"\n      :tooltip\n      :size=\"showSeeError ? 'lg' : 'default'\"\n    >\n      <template #label>\n        <div class=\"flex min-w-0 flex-1 flex-wrap items-center gap-2\">\n          <span class=\"flex min-w-0 flex-1 items-center gap-2\">\n            <i\n              v-if=\"nodeHasError\"\n              class=\"icon-[lucide--octagon-alert] size-4 shrink-0 text-destructive-background-hover\"\n            />\n            <span\n              :class=\"\n                cn(\n                  'truncate',\n                  nodeHasError && 'text-destructive-background-hover'\n                )\n              \"\n            >\n              <slot name=\"label\">\n                {{ displayLabel }}\n              </slot>\n            </span>\n            <span\n              v-if=\"parentGroup\"\n              class=\"min-w-11 flex-1 truncate text-right text-xs text-muted-foreground\"\n              :title=\"parentGroup.title\"\n            >\n              {{ parentGroup.title }}\n            </span>\n          </span>\n          <Button\n            v-if=\"showSeeError\"\n            variant=\"secondary\"\n            size=\"sm\"\n            class=\"h-8 shrink-0 rounded-lg text-sm\"\n            @click.stop=\"navigateToErrorTab\"\n          >\n            {{ t('rightSidePanel.seeError') }}\n          </Button>\n          <Button\n            v-if=\"!isEmpty\"\n            variant=\"muted-textonly\"\n            size=\"icon-sm\"\n            class=\"subbutton size-8 shrink-0 hover:text-base-foreground\"\n            :title=\"t('rightSidePanel.resetAllParameters')\"\n            :aria-label=\"t('rightSidePanel.resetAllParameters')\"\n            @click.stop=\"handleResetAllWidgets\"\n          >\n            <i class=\"icon-[lucide--rotate-ccw] size-4\" />\n          </Button>\n          <Button\n            v-if=\"canShowLocateButton\"\n            variant=\"muted-textonly\"\n            size=\"icon-sm\"\n            class=\"subbutton mr-3 size-8 shrink-0 hover:text-base-foreground\"\n            :title=\"t('rightSidePanel.locateNode')\"\n            :aria-label=\"t('rightSidePanel.locateNode')\"\n            @click.stop=\"handleLocateNode\"\n          >\n            <i class=\"icon-[lucide--locate] size-4\" />\n          </Button>\n        </div>\n      </template>\n\n      <template #empty><slot name=\"empty\" /></template>\n\n      <div\n        ref=\"widgetsContainer\"\n        data-testid=\"section-widgets-list\"\n        :data-draggable-ready=\"draggableList ? 'true' : undefined\"\n        class=\"relative space-y-2 rounded-lg px-4 pt-1\"\n      >\n        <WidgetItem\n          v-for=\"{ widget, node } in widgets\"\n          :key=\"getStableWidgetRenderKey(widget)\"\n          :widget\n          :node\n          :is-draggable\n          :hidden-favorite-indicator\n          :show-node-name\n          :host\n          @update:widget-value=\"handleWidgetValueUpdate(node, widget, $event)\"\n          @reset-to-default=\"handleWidgetReset(node, widget, $event)\"\n        />\n      </div>\n    </PropertiesAccordionItem>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { computed, ref, shallowRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useFavoritedWidgetsStore } from '@/stores/workspace/favoritedWidgetsStore'\nimport type { ValidFavoritedWidget } from '@/stores/workspace/favoritedWidgetsStore'\n\nimport { searchWidgets } from '../shared'\nimport PanelSearchHeader from './PanelSearchHeader.vue'\nimport SectionWidgets from './SectionWidgets.vue'\n\nconst favoritedWidgetsStore = useFavoritedWidgetsStore()\nconst searchQuery = ref('')\nconst { t } = useI18n()\n\nconst isSearching = ref(false)\n\nconst favoritedWidgets = computed(\n  () => favoritedWidgetsStore.validFavoritedWidgets\n)\n\nconst label = computed(() =>\n  favoritedWidgets.value.length === 0\n    ? t('rightSidePanel.favoritesNone')\n    : t('rightSidePanel.favorites')\n)\n\nconst searchedFavoritedWidgets = shallowRef<ValidFavoritedWidget[]>(\n  favoritedWidgets.value\n)\n\nasync function searcher(query: string) {\n  isSearching.value = query.trim().length > 0\n  searchedFavoritedWidgets.value = searchWidgets(favoritedWidgets.value, query)\n}\n\nfunction handleReorder({\n  fromIndex,\n  toIndex\n}: {\n  fromIndex: number\n  toIndex: number\n}) {\n  const widgets = [...searchedFavoritedWidgets.value]\n  const [moved] = widgets.splice(fromIndex, 1)\n  if (!moved) return\n  widgets.splice(toIndex, 0, moved)\n\n  searchedFavoritedWidgets.value = widgets\n  favoritedWidgetsStore.reorderFavorites(widgets)\n}\n</script>\n\n<template>\n  <PanelSearchHeader\n    v-model=\"searchQuery\"\n    :searcher\n    :update-key=\"favoritedWidgets\"\n  />\n  <SectionWidgets\n    :label\n    :widgets=\"searchedFavoritedWidgets\"\n    :is-draggable=\"!isSearching\"\n    hidden-favorite-indicator\n    show-node-name\n    enable-empty-state\n    class=\"border-b border-interface-stroke\"\n    @reorder=\"handleReorder\"\n  >\n    <template #empty>\n      <div class=\"px-4 py-10 text-center text-sm text-muted-foreground\">\n        <p>\n          {{\n            isSearching\n              ? t('rightSidePanel.noneSearchDesc')\n              : t('rightSidePanel.favoritesNoneDesc')\n          }}\n        </p>\n        <i18n-t\n          v-if=\"!isSearching\"\n          keypath=\"rightSidePanel.favoritesNoneHint\"\n          tag=\"p\"\n          class=\"mt-2 text-xs\"\n        >\n          <template #moreIcon>\n            <span\n              aria-hidden=\"true\"\n              class=\"inline-flex size-5 items-center justify-center rounded-md bg-secondary-background-hover align-middle text-base-foreground\"\n            >\n              <i class=\"icon-[lucide--more-vertical] text-sm\" />\n            </span>\n          </template>\n        </i18n-t>\n      </div>\n    </template>\n  </SectionWidgets>\n</template>\n","<template>\n  <Transition\n    enter-active-class=\"transition-all duration-300 ease-in-out\"\n    enter-from-class=\"max-w-0 opacity-0 ml-0\"\n    enter-to-class=\"max-w-10 opacity-100 ml-2\"\n    leave-active-class=\"transition-all duration-300 ease-in-out\"\n    leave-from-class=\"max-w-10 opacity-100 ml-2\"\n    leave-to-class=\"max-w-0 opacity-0 ml-0\"\n  >\n    <div v-if=\"show\" class=\"ml-2 flex items-center overflow-hidden\">\n      <Button\n        :tooltip=\"isAllCollapsed ? t('g.expandAll') : t('g.collapseAll')\"\n        tooltip-side=\"bottom\"\n        :aria-label=\"isAllCollapsed ? t('g.expandAll') : t('g.collapseAll')\"\n        variant=\"textonly\"\n        size=\"icon-sm\"\n        class=\"size-8 shrink-0 text-muted-foreground hover:text-base-foreground\"\n        @click=\"toggle\"\n      >\n        <i\n          :class=\"\n            cn(\n              'size-4',\n              isAllCollapsed\n                ? 'icon-[lucide--list-tree]'\n                : 'icon-[lucide--list-collapse]'\n            )\n          \"\n        />\n      </Button>\n    </div>\n  </Transition>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport Button from '@/components/ui/button/Button.vue'\n\nconst { t } = useI18n()\n\nconst isAllCollapsed = defineModel<boolean>({ required: true })\n\ndefineProps<{\n  show: boolean\n}>()\n\nfunction toggle() {\n  isAllCollapsed.value = !isAllCollapsed.value\n}\n</script>\n","<script setup lang=\"ts\">\nimport { computed, reactive, ref, shallowRef } from 'vue'\n\nimport CollapseToggleButton from '@/components/rightSidePanel/layout/CollapseToggleButton.vue'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { NodeId } from '@/types/nodeId'\n\nimport { computedSectionDataList, searchWidgetsAndNodes } from '../shared'\nimport type { NodeWidgetsListList } from '../shared'\nimport PanelSearchHeader from './PanelSearchHeader.vue'\nimport SectionWidgets from './SectionWidgets.vue'\n\nconst canvasStore = useCanvasStore()\n\nconst nodes = computed(\n  (): LGraphNode[] => (canvasStore.canvas?.graph?.nodes ?? []) as LGraphNode[]\n)\n\nconst searchQuery = ref('')\n\nconst { widgetsSectionDataList } = computedSectionDataList(nodes)\n\nconst searchedWidgetsSectionDataList = shallowRef<NodeWidgetsListList>(\n  widgetsSectionDataList.value\n)\nconst isSearching = ref(false)\n\nconst collapseMap = reactive<Record<string, boolean>>({})\n\nfunction isSectionCollapsed(nodeId: NodeId): boolean {\n  // Defaults to collapsed when not explicitly set by the user\n  return collapseMap[nodeId] ?? true\n}\n\nfunction setSectionCollapsed(nodeId: NodeId, collapsed: boolean) {\n  collapseMap[nodeId] = collapsed\n}\n\nconst isAllCollapsed = computed({\n  get() {\n    return searchedWidgetsSectionDataList.value.every(({ node }) =>\n      isSectionCollapsed(node.id)\n    )\n  },\n  set(collapse: boolean) {\n    for (const { node } of widgetsSectionDataList.value) {\n      setSectionCollapsed(node.id, collapse)\n    }\n  }\n})\n\nasync function searcher(query: string) {\n  const list = widgetsSectionDataList.value\n  const target = searchedWidgetsSectionDataList\n  isSearching.value = query.trim() !== ''\n  target.value = searchWidgetsAndNodes(list, query)\n}\n</script>\n\n<template>\n  <PanelSearchHeader\n    v-model=\"searchQuery\"\n    :searcher\n    :update-key=\"widgetsSectionDataList\"\n  >\n    <CollapseToggleButton\n      v-model=\"isAllCollapsed\"\n      :show=\"!isSearching && widgetsSectionDataList.length > 1\"\n    />\n  </PanelSearchHeader>\n  <TransitionGroup tag=\"div\" name=\"list-scale\" class=\"relative\">\n    <div\n      v-if=\"isSearching && searchedWidgetsSectionDataList.length === 0\"\n      class=\"px-4 pt-5 pb-15 text-center text-sm text-muted-foreground\"\n    >\n      {{ $t('rightSidePanel.noneSearchDesc') }}\n    </div>\n    <SectionWidgets\n      v-for=\"{ node, widgets } in searchedWidgetsSectionDataList\"\n      :key=\"node.id\"\n      :node\n      :widgets\n      :collapse=\"isSectionCollapsed(node.id) && !isSearching\"\n      :tooltip=\"\n        isSearching || widgets.length\n          ? ''\n          : $t('rightSidePanel.inputsNoneTooltip')\n      \"\n      show-locate-button\n      class=\"border-b border-interface-stroke\"\n      @update:collapse=\"setSectionCollapsed(node.id, $event)\"\n    />\n  </TransitionGroup>\n</template>\n","<script setup lang=\"ts\">\nimport { computed, reactive, ref, shallowRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport CollapseToggleButton from '@/components/rightSidePanel/layout/CollapseToggleButton.vue'\nimport type { NodeId } from '@/types/nodeId'\nimport { deriveWidgetVisibility } from '@/types/widgetVisibility'\n\nimport { computedSectionDataList, searchWidgetsAndNodes } from '../shared'\nimport type { NodeWidgetsListList } from '../shared'\nimport PanelSearchHeader from './PanelSearchHeader.vue'\nimport SectionWidgets from './SectionWidgets.vue'\n\nconst { nodes, mustShowNodeTitle } = defineProps<{\n  mustShowNodeTitle?: boolean\n  nodes: LGraphNode[]\n}>()\n\nconst { t } = useI18n()\nconst searchQuery = ref('')\n\nconst { widgetsSectionDataList, includesAdvanced } = computedSectionDataList(\n  () => nodes\n)\n\nconst advancedWidgetsSectionDataList = computed((): NodeWidgetsListList => {\n  if (includesAdvanced.value) {\n    return []\n  }\n  return nodes\n    .map((node) => {\n      const { widgets = [] } = node\n      const advancedWidgets = widgets\n        .filter((w) => {\n          const visibility = w.visibility ?? deriveWidgetVisibility(w)\n          return (\n            !visibility.suppression.byExtension &&\n            !visibility.suppression.byConnection &&\n            visibility.surfaces.panel === 'advanced'\n          )\n        })\n        .map((widget) => ({ node, widget }))\n      return { widgets: advancedWidgets, node }\n    })\n    .filter(({ widgets }) => widgets.length > 0)\n})\n\nconst isMultipleNodesSelected = computed(\n  () => widgetsSectionDataList.value.length > 1\n)\n\nconst searchedWidgetsSectionDataList = shallowRef<NodeWidgetsListList>(\n  widgetsSectionDataList.value\n)\nconst isSearching = ref(false)\n\nconst collapseMap = reactive<Record<string, boolean>>({})\nconst advancedCollapsed = ref(true)\n\nfunction isSectionCollapsed(nodeId: NodeId): boolean {\n  // When not explicitly set, sections are collapsed if multiple nodes are selected\n  return collapseMap[nodeId] ?? isMultipleNodesSelected.value\n}\n\nfunction setSectionCollapsed(nodeId: NodeId, collapsed: boolean) {\n  collapseMap[nodeId] = collapsed\n}\n\nconst isAllCollapsed = computed({\n  get() {\n    const normalAllCollapsed = searchedWidgetsSectionDataList.value.every(\n      ({ node }) => isSectionCollapsed(node.id)\n    )\n    const hasAdvanced = advancedWidgetsSectionDataList.value.length > 0\n    return hasAdvanced\n      ? normalAllCollapsed && advancedCollapsed.value\n      : normalAllCollapsed\n  },\n  set(collapse: boolean) {\n    for (const { node } of widgetsSectionDataList.value) {\n      setSectionCollapsed(node.id, collapse)\n    }\n    advancedCollapsed.value = collapse\n  }\n})\n\nasync function searcher(query: string) {\n  const list = widgetsSectionDataList.value\n  const target = searchedWidgetsSectionDataList\n  isSearching.value = query.trim() !== ''\n  target.value = searchWidgetsAndNodes(list, query)\n}\n\nconst label = computed(() => {\n  const sections = widgetsSectionDataList.value\n  return !mustShowNodeTitle && sections.length === 1\n    ? sections[0].widgets.length !== 0\n      ? t('rightSidePanel.inputs')\n      : t('rightSidePanel.inputsNone')\n    : undefined // SectionWidgets display node titles by default\n})\n\nconst advancedLabel = computed(() => {\n  return !mustShowNodeTitle && !isMultipleNodesSelected.value\n    ? t('rightSidePanel.advancedInputs')\n    : undefined // SectionWidgets display node titles by default\n})\n</script>\n\n<template>\n  <PanelSearchHeader\n    v-model=\"searchQuery\"\n    :searcher\n    :update-key=\"widgetsSectionDataList\"\n  >\n    <CollapseToggleButton\n      v-model=\"isAllCollapsed\"\n      :show=\"\n        !isSearching &&\n        widgetsSectionDataList.length + advancedWidgetsSectionDataList.length >\n          1\n      \"\n    />\n  </PanelSearchHeader>\n  <TransitionGroup tag=\"div\" name=\"list-scale\" class=\"relative\">\n    <div\n      v-if=\"searchedWidgetsSectionDataList.length === 0\"\n      class=\"px-4 py-10 text-center text-sm text-muted-foreground\"\n    >\n      {{\n        isSearching\n          ? t('rightSidePanel.noneSearchDesc')\n          : t('rightSidePanel.nodesNoneDesc')\n      }}\n    </div>\n    <SectionWidgets\n      v-for=\"{ widgets, node } in searchedWidgetsSectionDataList\"\n      :key=\"node.id\"\n      :node\n      :label\n      :widgets\n      :collapse=\"isSectionCollapsed(node.id) && !isSearching\"\n      :show-locate-button=\"isMultipleNodesSelected\"\n      :tooltip=\"\n        isSearching || widgets.length\n          ? ''\n          : t('rightSidePanel.inputsNoneTooltip')\n      \"\n      class=\"border-b border-interface-stroke\"\n      @update:collapse=\"setSectionCollapsed(node.id, $event)\"\n    />\n  </TransitionGroup>\n  <template v-if=\"advancedWidgetsSectionDataList.length > 0 && !isSearching\">\n    <SectionWidgets\n      v-for=\"{ widgets, node } in advancedWidgetsSectionDataList\"\n      :key=\"`advanced-${node.id}`\"\n      v-model:collapse=\"advancedCollapsed\"\n      :node\n      :label=\"advancedLabel\"\n      :widgets\n      :show-locate-button=\"isMultipleNodesSelected\"\n      class=\"border-b border-interface-stroke\"\n    />\n  </template>\n</template>\n","<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport { computed, nextTick, ref, shallowRef, useTemplateRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { promotedInputWidgets } from '@/core/graph/subgraph/promotedInputWidget'\nimport {\n  isWidgetPromotedOnSubgraphNode,\n  reorderSubgraphInputsByWidgetOrder\n} from '@/core/graph/subgraph/promotionUtils'\nimport type { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport CollapseToggleButton from '@/components/rightSidePanel/layout/CollapseToggleButton.vue'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\nimport {\n  deriveWidgetVisibility,\n  isWidgetVisibleOnSurface\n} from '@/types/widgetVisibility'\n\nimport { searchWidgets } from '../shared'\nimport type { NodeWidgetsList } from '../shared'\nimport PanelSearchHeader from './PanelSearchHeader.vue'\nimport SectionWidgets from './SectionWidgets.vue'\n\nconst { node } = defineProps<{\n  node: SubgraphNode\n}>()\n\nconst { t } = useI18n()\nconst canvasStore = useCanvasStore()\nconst rightSidePanelStore = useRightSidePanelStore()\nconst { focusedSection } = storeToRefs(rightSidePanelStore)\nconst searchQuery = ref('')\n\nconst advancedInputsCollapsed = ref(true)\nconst firstSectionCollapsed = ref(false)\nconst isAllCollapsed = computed({\n  get() {\n    const hasAdvanced = advancedInputsWidgets.value.length > 0\n    return hasAdvanced\n      ? firstSectionCollapsed.value && advancedInputsCollapsed.value\n      : firstSectionCollapsed.value\n  },\n  set(collapse: boolean) {\n    firstSectionCollapsed.value = collapse\n    advancedInputsCollapsed.value = collapse\n  }\n})\nconst advancedInputsSectionRef = useTemplateRef('advancedInputsSectionRef')\n\nwatch(\n  focusedSection,\n  async (section) => {\n    if (section === 'advanced-inputs') {\n      advancedInputsCollapsed.value = false\n      rightSidePanelStore.clearFocusedSection()\n\n      await nextTick()\n\n      await new Promise((resolve) => setTimeout(resolve, 300))\n\n      const sectionComponent = advancedInputsSectionRef.value\n      const sectionElement = sectionComponent?.rootElement\n      if (sectionElement) {\n        sectionElement.scrollIntoView({ behavior: 'smooth', block: 'start' })\n      }\n    }\n  },\n  { immediate: true }\n)\n\nconst widgetsList = computed((): NodeWidgetsList => {\n  return promotedInputWidgets(node).map((widget) => ({ node, widget }))\n})\n\nconst advancedInputsWidgets = computed((): NodeWidgetsList => {\n  const interiorNodes = node.subgraph.nodes\n\n  const allInteriorWidgets = interiorNodes.flatMap((interiorNode) => {\n    const { widgets = [] } = interiorNode\n    return widgets\n      .filter((widget) =>\n        isWidgetVisibleOnSurface(\n          widget.visibility ?? deriveWidgetVisibility(widget),\n          'panel',\n          { showAdvanced: true }\n        )\n      )\n      .map((widget) => ({ node: interiorNode, widget }))\n  })\n\n  return allInteriorWidgets.filter(\n    ({ node: interiorNode, widget }) =>\n      !isWidgetPromotedOnSubgraphNode(node, {\n        sourceNodeId: interiorNode.id,\n        sourceWidgetName: widget.name\n      })\n  )\n})\n\nconst searchedWidgetsList = shallowRef<NodeWidgetsList>(widgetsList.value)\nconst isSearching = ref(false)\n\nasync function searcher(query: string) {\n  isSearching.value = query.trim() !== ''\n  searchedWidgetsList.value = searchWidgets(widgetsList.value, query)\n}\n\nfunction handleReorder({\n  fromIndex,\n  toIndex\n}: {\n  fromIndex: number\n  toIndex: number\n}) {\n  const widgets = searchedWidgetsList.value.map((row) => row.widget)\n  const [moved] = widgets.splice(fromIndex, 1)\n  if (!moved) return\n  widgets.splice(toIndex, 0, moved)\n\n  reorderSubgraphInputsByWidgetOrder(node, widgets)\n  canvasStore.canvas?.setDirty(true, true)\n}\n\nconst label = computed(() => {\n  return searchedWidgetsList.value.length !== 0\n    ? t('rightSidePanel.inputs')\n    : t('rightSidePanel.inputsNone')\n})\n</script>\n\n<template>\n  <PanelSearchHeader v-model=\"searchQuery\" :searcher :update-key=\"widgetsList\">\n    <CollapseToggleButton\n      v-model=\"isAllCollapsed\"\n      :show=\"!isSearching && advancedInputsWidgets.length > 0\"\n    />\n  </PanelSearchHeader>\n  <SectionWidgets\n    :collapse=\"firstSectionCollapsed && !isSearching\"\n    :node\n    :label\n    :host=\"node\"\n    :widgets=\"searchedWidgetsList\"\n    :is-draggable=\"!isSearching\"\n    :enable-empty-state=\"isSearching\"\n    :tooltip=\"\n      isSearching || searchedWidgetsList.length\n        ? ''\n        : t('rightSidePanel.inputsNoneTooltip')\n    \"\n    class=\"border-b border-interface-stroke\"\n    @update:collapse=\"(v) => (firstSectionCollapsed = v)\"\n    @reorder=\"handleReorder\"\n  >\n    <template #empty>\n      <div class=\"px-4 pt-5 pb-15 text-center text-sm text-muted-foreground\">\n        {{ t('rightSidePanel.noneSearchDesc') }}\n      </div>\n    </template>\n  </SectionWidgets>\n  <SectionWidgets\n    v-if=\"advancedInputsWidgets.length > 0\"\n    ref=\"advancedInputsSectionRef\"\n    v-model:collapse=\"advancedInputsCollapsed\"\n    :label=\"t('rightSidePanel.advancedInputs')\"\n    :host=\"node\"\n    :widgets=\"advancedInputsWidgets\"\n    show-node-name\n    class=\"border-b border-interface-stroke\"\n  />\n</template>\n","import { useTelemetry } from '@/platform/telemetry'\nimport type { RightSidePanelTab } from '@/stores/workspace/rightSidePanelStore'\n\n/**\n * Tabs whose opening we want discoverability telemetry for, mapped to the\n * button_id reported on `trackUiButtonClicked`. Tabs not listed here are\n * intentionally left untracked.\n */\nconst TAB_OPENED_BUTTON_IDS: Partial<Record<RightSidePanelTab, string>> = {\n  settings: 'right_side_panel_settings_tab_opened',\n  info: 'right_side_panel_info_tab_opened'\n}\n\n/**\n * Fires a `trackUiButtonClicked` event when the right side panel switches to\n * a tab tracked in {@link TAB_OPENED_BUTTON_IDS}. No-op for any other tab.\n */\nexport function trackRightSidePanelTabOpened(tab: RightSidePanelTab): void {\n  const buttonId = TAB_OPENED_BUTTON_IDS[tab]\n  if (!buttonId) return\n\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: buttonId,\n    element_group: 'right_side_panel'\n  })\n}\n","<script setup lang=\"ts\">\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\ndefineProps<{\n  label: string\n  tooltip?: string\n  singleline?: boolean\n}>()\n</script>\n\n<template>\n  <div\n    :class=\"\n      cn('flex gap-2', singleline ? 'items-center justify-between' : 'flex-col')\n    \"\n  >\n    <Tooltip :disabled=\"!tooltip\">\n      <TooltipTrigger as-child>\n        <span\n          :class=\"\n            cn(\n              'group truncate text-sm text-muted-foreground',\n              tooltip ? 'cursor-help' : '',\n              singleline ? 'flex-1' : ''\n            )\n          \"\n        >\n          {{ label }}\n\n          <i\n            v-if=\"tooltip\"\n            class=\"relative top-px ml-0.5 icon-[lucide--info] size-3 group-hover:text-primary\"\n          />\n        </span>\n      </TooltipTrigger>\n      <TooltipContent side=\"left\">{{ tooltip }}</TooltipContent>\n    </Tooltip>\n    <slot />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport Switch from '@/components/ui/switch/Switch.vue'\n\nimport LayoutField from './LayoutField.vue'\n\ndefineProps<{\n  id?: string\n  label: string\n  tooltip?: string\n}>()\n\nconst modelValue = defineModel<boolean>({ default: false })\n</script>\n\n<template>\n  <LayoutField singleline :label :tooltip>\n    <Switch\n      :id\n      v-model=\"modelValue\"\n      :aria-label=\"label\"\n      class=\"transition-transform active:scale-90\"\n    />\n  </LayoutField>\n</template>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Slider from '@/components/ui/slider/Slider.vue'\nimport SingleSelect from '@/components/ui/single-select/SingleSelect.vue'\nimport NumberField from '@/components/ui/number-field/NumberField.vue'\nimport NumberFieldInput from '@/components/ui/number-field/NumberFieldInput.vue'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { LinkRenderType } from '@/lib/litegraph/src/types/globalEnums'\nimport { LinkMarkerShape } from '@/lib/litegraph/src/types/globalEnums'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { WidgetInputBaseClass } from '@/renderer/extensions/vueNodes/widgets/components/layout'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport PropertiesAccordionItem from '../layout/PropertiesAccordionItem.vue'\nimport FieldSwitch from './FieldSwitch.vue'\nimport LayoutField from './LayoutField.vue'\n\nconst { t } = useI18n()\nconst settingStore = useSettingStore()\nconst settingsDialog = useSettingsDialog()\n\n// NODES settings\nconst showAdvancedParameters = computed({\n  get: () => settingStore.get('Comfy.Node.AlwaysShowAdvancedWidgets'),\n  set: (value) =>\n    settingStore.set('Comfy.Node.AlwaysShowAdvancedWidgets', value)\n})\n\nconst showToolbox = computed({\n  get: () => settingStore.get('Comfy.Canvas.SelectionToolbox'),\n  set: (value) => settingStore.set('Comfy.Canvas.SelectionToolbox', value)\n})\n\nconst nodes2Enabled = computed({\n  get: () => settingStore.get('Comfy.VueNodes.Enabled'),\n  set: (value) => settingStore.set('Comfy.VueNodes.Enabled', value)\n})\n\n// CANVAS settings\nconst gridSpacing = computed({\n  get: () => settingStore.get('Comfy.SnapToGrid.GridSize'),\n  set: (value) => settingStore.set('Comfy.SnapToGrid.GridSize', value)\n})\n\nconst snapToGrid = computed({\n  get: () => settingStore.get('pysssss.SnapToGrid'),\n  set: (value) => settingStore.set('pysssss.SnapToGrid', value)\n})\n\n// CONNECTION LINKS settings\nconst linkShape = computed({\n  get: () => settingStore.get('Comfy.Graph.LinkMarkers'),\n  set: (value) => settingStore.set('Comfy.Graph.LinkMarkers', value)\n})\n\nconst linkShapeOptions = computed(() => [\n  { value: LinkMarkerShape.None, name: t('g.none') },\n  { value: LinkMarkerShape.Circle, name: t('shape.circle') },\n  { value: LinkMarkerShape.Arrow, name: t('shape.arrow') }\n])\n\nlet theOldLinkRenderMode: LinkRenderType = LiteGraph.SPLINE_LINK\nconst showConnectedLinks = computed({\n  get: () => settingStore.get('Comfy.LinkRenderMode') !== LiteGraph.HIDDEN_LINK,\n  set: (value) => {\n    let oldLinkRenderMode = settingStore.get('Comfy.LinkRenderMode')\n    if (oldLinkRenderMode !== LiteGraph.HIDDEN_LINK) {\n      theOldLinkRenderMode = oldLinkRenderMode\n    }\n    const newMode = value ? theOldLinkRenderMode : LiteGraph.HIDDEN_LINK\n    settingStore.set('Comfy.LinkRenderMode', newMode)\n  }\n})\n\nconst GRID_SIZE_MIN = 1\nconst GRID_SIZE_MAX = 100\nconst GRID_SIZE_STEP = 1\n\nfunction updateGridSpacingFromSlider(values?: number[]) {\n  if (!values?.length) return\n  gridSpacing.value = values[0]\n}\n\nfunction openFullSettings() {\n  settingsDialog.show()\n}\n</script>\n\n<template>\n  <div class=\"flex flex-col border-t border-interface-stroke\">\n    <!-- NODES Section -->\n    <PropertiesAccordionItem class=\"border-b border-interface-stroke\">\n      <template #label>\n        {{ t('rightSidePanel.globalSettings.nodes') }}\n      </template>\n      <div class=\"space-y-4 px-4 py-3\">\n        <FieldSwitch\n          v-model=\"showAdvancedParameters\"\n          :label=\"t('rightSidePanel.globalSettings.showAdvanced')\"\n          :tooltip=\"t('settings.Comfy_Node_AlwaysShowAdvancedWidgets.tooltip')\"\n        />\n        <FieldSwitch\n          v-model=\"showToolbox\"\n          :label=\"t('rightSidePanel.globalSettings.showToolbox')\"\n          :tooltip=\"t('settings.Comfy_Canvas_SelectionToolbox.tooltip')\"\n        />\n        <FieldSwitch\n          v-model=\"nodes2Enabled\"\n          :label=\"t('rightSidePanel.globalSettings.nodes2')\"\n          :tooltip=\"t('settings.Comfy_VueNodes_Enabled.tooltip')\"\n        />\n      </div>\n    </PropertiesAccordionItem>\n\n    <!-- CANVAS Section -->\n    <PropertiesAccordionItem class=\"border-b border-interface-stroke\">\n      <template #label>\n        {{ t('rightSidePanel.globalSettings.canvas') }}\n      </template>\n      <div class=\"space-y-4 px-4 py-3\">\n        <LayoutField :label=\"t('rightSidePanel.globalSettings.gridSpacing')\">\n          <div\n            :class=\"\n              cn(WidgetInputBaseClass, 'flex h-7 items-center gap-2 pr-2 pl-3')\n            \"\n          >\n            <Slider\n              :model-value=\"[gridSpacing]\"\n              class=\"grow text-xs\"\n              :min=\"GRID_SIZE_MIN\"\n              :max=\"GRID_SIZE_MAX\"\n              :step=\"GRID_SIZE_STEP\"\n              @update:model-value=\"updateGridSpacingFromSlider\"\n            />\n            <NumberField\n              v-model=\"gridSpacing\"\n              class=\"h-auto w-16 shrink-0 bg-transparent hover:bg-transparent\"\n              :min=\"GRID_SIZE_MIN\"\n              :max=\"GRID_SIZE_MAX\"\n              :step=\"GRID_SIZE_STEP\"\n              :format-options=\"{ maximumFractionDigits: 0 }\"\n            >\n              <NumberFieldInput\n                :aria-label=\"t('rightSidePanel.globalSettings.gridSpacing')\"\n                class=\"text-xs\"\n              />\n            </NumberField>\n          </div>\n        </LayoutField>\n        <FieldSwitch\n          v-model=\"snapToGrid\"\n          :label=\"t('rightSidePanel.globalSettings.snapNodesToGrid')\"\n          :tooltip=\"t('settings.pysssss_SnapToGrid.tooltip')\"\n        />\n      </div>\n    </PropertiesAccordionItem>\n\n    <!-- CONNECTION LINKS Section -->\n    <PropertiesAccordionItem class=\"border-b border-interface-stroke\">\n      <template #label>\n        {{ t('rightSidePanel.globalSettings.connectionLinks') }}\n      </template>\n      <div class=\"space-y-4 px-4 py-3\">\n        <LayoutField :label=\"t('rightSidePanel.globalSettings.linkShape')\">\n          <SingleSelect\n            v-model=\"linkShape\"\n            :options=\"linkShapeOptions\"\n            :label=\"t('rightSidePanel.globalSettings.linkShape')\"\n            :class=\"cn(WidgetInputBaseClass, 'w-full text-xs')\"\n            size=\"md\"\n            data-capture-wheel=\"true\"\n          />\n        </LayoutField>\n        <FieldSwitch\n          v-model=\"showConnectedLinks\"\n          :label=\"t('rightSidePanel.globalSettings.showConnectedLinks')\"\n          :tooltip=\"t('settings.Comfy_LinkRenderMode.tooltip')\"\n        />\n      </div>\n    </PropertiesAccordionItem>\n\n    <!-- View all settings button -->\n    <div\n      class=\"flex items-center justify-center border-b border-interface-stroke p-4\"\n    >\n      <Button\n        variant=\"muted-textonly\"\n        size=\"sm\"\n        class=\"gap-2 text-sm\"\n        @click=\"openFullSettings\"\n      >\n        {{ t('rightSidePanel.globalSettings.viewAllSettings') }}\n        <i class=\"icon-[lucide--settings] size-4\" />\n      </Button>\n    </div>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\n\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { LGraphCanvas, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { ColorOption } from '@/lib/litegraph/src/litegraph'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { adjustColor } from '@/utils/colorUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport LayoutField from './LayoutField.vue'\n\n/**\n * Good design limits dependencies and simplifies the interface of the abstraction layer.\n * Here, we only care about the getColorOption and setColorOption methods,\n * and do not concern ourselves with other methods.\n */\ntype PickedNode = Pick<LGraphNode, 'getColorOption' | 'setColorOption'>\n\nconst { nodes } = defineProps<{ nodes: PickedNode[] }>()\nconst emit = defineEmits<{ (e: 'changed'): void }>()\n\nconst { t } = useI18n()\n\nconst colorPaletteStore = useColorPaletteStore()\n\ntype NodeColorOption = {\n  name: string\n  localizedName: () => string\n  value: {\n    dark: string\n    light: string\n    ringDark: string\n    ringLight: string\n  }\n}\n\nconst nodeColorEntries = Object.entries(LGraphCanvas.node_colors)\n\nfunction getColorValue(color: string): NodeColorOption['value'] {\n  return {\n    dark: adjustColor(color, { lightness: 0.3 }),\n    light: adjustColor(color, { lightness: 0.4 }),\n    ringDark: adjustColor(color, { lightness: 0.5 }),\n    ringLight: adjustColor(color, { lightness: 0.1 })\n  }\n}\n\nconst NO_COLOR_OPTION: NodeColorOption = {\n  name: 'noColor',\n  localizedName: () => t('color.noColor'),\n  value: getColorValue(LiteGraph.NODE_DEFAULT_BGCOLOR)\n}\n\nconst colorOptions: NodeColorOption[] = [\n  NO_COLOR_OPTION,\n  ...nodeColorEntries.map(([name, color]) => ({\n    name,\n    localizedName: () => t(`color.${name}`),\n    value: getColorValue(color.bgcolor)\n  }))\n]\n\nconst isLightTheme = computed(\n  () => colorPaletteStore.completedActivePalette.light_theme\n)\n\nconst nodeColor = computed<NodeColorOption['name'] | null>({\n  get() {\n    if (nodes.length === 0) return null\n    const theColorOptions = nodes.map((item) => item.getColorOption())\n\n    let colorOption: ColorOption | null | false = theColorOptions[0]\n    if (!theColorOptions.every((option) => option === colorOption)) {\n      colorOption = false\n    }\n\n    if (colorOption === false) return null\n    if (colorOption == null || (!colorOption.bgcolor && !colorOption.color))\n      return NO_COLOR_OPTION.name\n    return (\n      nodeColorEntries.find(\n        ([_, color]) =>\n          color.bgcolor === colorOption.bgcolor &&\n          color.color === colorOption.color\n      )?.[0] ?? null\n    )\n  },\n  set(colorName) {\n    if (colorName === null) return\n\n    const canvasColorOption =\n      colorName === NO_COLOR_OPTION.name\n        ? null\n        : LGraphCanvas.node_colors[colorName]\n\n    for (const item of nodes) {\n      item.setColorOption(canvasColorOption)\n    }\n\n    emit('changed')\n  }\n})\n</script>\n\n<template>\n  <LayoutField :label=\"t('rightSidePanel.color')\">\n    <div\n      class=\"grid grid-cols-5 justify-items-center gap-1 rounded-lg border-none bg-secondary-background p-1\"\n    >\n      <Tooltip v-for=\"option of colorOptions\" :key=\"option.name\">\n        <TooltipTrigger as-child>\n          <button\n            :aria-label=\"option.localizedName()\"\n            :class=\"\n              cn(\n                'flex size-8 cursor-pointer items-center justify-center rounded-lg border-0 bg-transparent text-left ring-0 outline-0',\n                option.name === nodeColor\n                  ? 'bg-interface-menu-component-surface-selected'\n                  : 'hover:bg-interface-menu-component-surface-selected'\n              )\n            \"\n            @click=\"nodeColor = option.name\"\n          >\n            <div\n              :class=\"cn('size-4 rounded-full ring-2 ring-gray-500/10')\"\n              :style=\"{\n                backgroundColor: isLightTheme\n                  ? option.value.light\n                  : option.value.dark,\n                '--tw-ring-color':\n                  option.name === nodeColor\n                    ? isLightTheme\n                      ? option.value.ringLight\n                      : option.value.ringDark\n                    : undefined\n              }\"\n              :data-testid=\"option.name\"\n            />\n          </button>\n        </TooltipTrigger>\n        <TooltipContent>{{ option.localizedName() }}</TooltipContent>\n      </Tooltip>\n    </div>\n  </LayoutField>\n</template>\n","<template>\n  <div\n    :class=\"\n      cn(WidgetInputBaseClass, 'flex w-full min-w-0 items-center gap-1 p-1')\n    \"\n  >\n    <button\n      v-for=\"(option, index) in options\"\n      :key=\"getOptionValue(option, index)\"\n      :class=\"\n        cn(\n          'flex h-6 min-w-0 flex-1 items-center justify-center gap-1 truncate rounded-sm px-5 py-[5px] transition-all duration-150 ease-in-out',\n          'border-none bg-transparent',\n          'text-center text-xs font-normal',\n          {\n            'bg-interface-menu-component-surface-selected':\n              isSelected(index) && !disabled,\n            'hover:bg-interface-menu-component-surface-selected/50':\n              !isSelected(index) && !disabled,\n            'cursor-not-allowed opacity-50': disabled,\n            'cursor-pointer': !disabled\n          },\n          isSelected(index) && !disabled\n            ? 'text-text-primary'\n            : 'text-text-secondary'\n        )\n      \"\n      :disabled=\"disabled\"\n      @click=\"handleSelect(index)\"\n    >\n      {{ getOptionLabel(option) }}\n    </button>\n  </div>\n</template>\n\n<script\n  setup\n  lang=\"ts\"\n  generic=\"\n    T extends string | number | { label: string; value: string | number }\n  \"\n>\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { WidgetInputBaseClass } from '../layout'\n\ntype ModelValue = T extends object ? T['value'] : T\n\ninterface Props {\n  modelValue: ModelValue | null | undefined\n  options: T[]\n  optionLabel?: string // PrimeVue compatible prop\n  optionValue?: string // PrimeVue compatible prop\n  disabled?: boolean\n}\n\ninterface Emits {\n  'update:modelValue': [value: ModelValue]\n}\n\nconst {\n  modelValue,\n  options,\n  optionLabel = 'label',\n  optionValue = 'value',\n  disabled\n} = defineProps<Props>()\n\nconst emit = defineEmits<Emits>()\n\n// handle both string/number arrays and object arrays with PrimeVue compatibility\nconst getOptionValue = (option: T, index: number): ModelValue => {\n  if (typeof option !== 'object') {\n    return option as ModelValue\n  }\n\n  const valueField = optionValue\n  const optionRecord = option as Record<string, unknown>\n  const value =\n    optionRecord[valueField] ??\n    option.value ??\n    optionRecord.name ??\n    option.label ??\n    index\n  return value as ModelValue\n}\n\n// for display with PrimeVue compatibility\nconst getOptionLabel = (option: T): string => {\n  if (typeof option === 'object' && option !== null) {\n    const labelField = optionLabel\n    const optionRecord = option as Record<string, unknown>\n    return String(\n      optionRecord[labelField] ??\n        option.label ??\n        optionRecord.name ??\n        option.value ??\n        option\n    )\n  }\n  return String(option)\n}\n\nconst isSelected = (index: number): boolean => {\n  const optVal = getOptionValue(options[index], index)\n  return String(optVal) === String(modelValue ?? '')\n}\n\nconst handleSelect = (index: number) => {\n  if (disabled) return\n\n  const optVal = getOptionValue(options[index], index)\n  emit('update:modelValue', optVal)\n}\n</script>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { LGraphEventMode } from '@/lib/litegraph/src/litegraph'\nimport FormSelectButton from '@/renderer/extensions/vueNodes/widgets/components/form/FormSelectButton.vue'\n\nimport LayoutField from './LayoutField.vue'\n\n/**\n * Good design limits dependencies and simplifies the interface of the abstraction layer.\n * Here, we only care about the mode method,\n * and do not concern ourselves with other methods.\n */\ntype PickedNode = Pick<LGraphNode, 'mode'>\n\nconst { nodes } = defineProps<{ nodes: PickedNode[] }>()\nconst emit = defineEmits<{ (e: 'changed'): void }>()\n\nconst { t } = useI18n()\n\nconst nodeState = computed({\n  get() {\n    let mode: LGraphNode['mode'] | null = null\n\n    if (nodes.length === 0) return null\n\n    // For multiple nodes, if all nodes have the same mode, return that mode, otherwise return null\n    if (nodes.length > 1) {\n      mode = nodes[0].mode\n      if (!nodes.every((node) => node.mode === mode)) {\n        mode = null\n      }\n    } else {\n      mode = nodes[0].mode\n    }\n\n    return mode\n  },\n  set(value: LGraphNode['mode']) {\n    nodes.forEach((node) => {\n      node.mode = value\n    })\n    emit('changed')\n  }\n})\n</script>\n\n<template>\n  <LayoutField :label=\"t('rightSidePanel.nodeState')\">\n    <FormSelectButton\n      v-model=\"nodeState\"\n      class=\"w-full\"\n      :options=\"[\n        {\n          label: t('rightSidePanel.normal'),\n          value: LGraphEventMode.ALWAYS\n        },\n        {\n          label: t('rightSidePanel.bypass'),\n          value: LGraphEventMode.BYPASS\n        },\n        {\n          label: t('rightSidePanel.mute'),\n          value: LGraphEventMode.NEVER\n        }\n      ]\"\n    />\n  </LayoutField>\n</template>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\n\nimport FieldSwitch from './FieldSwitch.vue'\n\ntype PickedNode = Pick<LGraphNode, 'pinned' | 'pin'>\n\n/**\n * Good design limits dependencies and simplifies the interface of the abstraction layer.\n * Here, we only care about the pinned and pin methods,\n * and do not concern ourselves with other methods.\n */\nconst { nodes } = defineProps<{ nodes: PickedNode[] }>()\nconst emit = defineEmits<{ (e: 'changed'): void }>()\n\nconst { t } = useI18n()\n\n// Pinned state\nconst isPinned = computed<boolean>({\n  get() {\n    return nodes.some((node) => node.pinned)\n  },\n  set(value) {\n    nodes.forEach((node) => node.pin(value))\n    emit('changed')\n  }\n})\n</script>\n\n<template>\n  <FieldSwitch v-model=\"isPinned\" :label=\"t('rightSidePanel.pinned')\" />\n</template>\n","<template>\n  <div class=\"space-y-4 text-sm text-muted-foreground\">\n    <SetNodeState\n      v-if=\"isNodes(targetNodes)\"\n      :nodes=\"targetNodes\"\n      @changed=\"handleChanged\"\n    />\n    <SetNodeColor :nodes=\"targetNodes\" @changed=\"handleChanged\" />\n    <SetPinned :nodes=\"targetNodes\" @changed=\"handleChanged\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { shallowRef, watchEffect } from 'vue'\n\nimport type { LGraphGroup, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { isLGraphGroup } from '@/utils/litegraphUtil'\n\nimport SetNodeColor from './SetNodeColor.vue'\nimport SetNodeState from './SetNodeState.vue'\nimport SetPinned from './SetPinned.vue'\n\nconst props = defineProps<{\n  /**\n   * - If the item is a Group, Node State cannot be set\n   * as Groups do not have a 'mode' property.\n   *\n   * - The nodes array can contain either all Nodes or all Groups,\n   * but it must not be a mix of both.\n   */\n  nodes?: LGraphNode[] | LGraphGroup[]\n}>()\n\nconst targetNodes = shallowRef<LGraphNode[] | LGraphGroup[]>([])\nwatchEffect(() => {\n  if (props.nodes) {\n    targetNodes.value = props.nodes\n  } else {\n    targetNodes.value = []\n  }\n})\n\nconst canvasStore = useCanvasStore()\n\nfunction isNodes(nodes: LGraphNode[] | LGraphGroup[]): nodes is LGraphNode[] {\n  return !nodes.some((node) => isLGraphGroup(node))\n}\n\nfunction handleChanged() {\n  /**\n   * This is not a random comment—it's crucial.\n   * Otherwise, the UI cannot update correctly.\n   * There is a bug with triggerRef here, so we can't use triggerRef.\n   * We'll work around it for now and later submit a Vue issue and pull request to fix it.\n   */\n  targetNodes.value = targetNodes.value.slice()\n\n  canvasStore.canvas?.setDirty(true, true)\n}\n</script>\n","<template>\n  <div v-if=\"isOnlyHasNodes\" class=\"p-4\">\n    <NodeSettings :nodes=\"theNodes\" />\n  </div>\n  <div v-else class=\"border-t border-interface-stroke\">\n    <PropertiesAccordionItem\n      v-if=\"hasNodes\"\n      class=\"border-b border-interface-stroke\"\n      :label=\"$t('rightSidePanel.nodes')\"\n    >\n      <NodeSettings :nodes=\"theNodes\" class=\"p-4\" />\n    </PropertiesAccordionItem>\n    <PropertiesAccordionItem\n      v-if=\"hasGroups\"\n      class=\"border-b border-interface-stroke\"\n      :label=\"$t('rightSidePanel.groups')\"\n    >\n      <NodeSettings :nodes=\"theGroups\" class=\"p-4\" />\n    </PropertiesAccordionItem>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\n/**\n * If we only need to show settings for Nodes,\n * there's no need to wrap them in PropertiesAccordionItem,\n * making the UI cleaner.\n * But if there are multiple types of settings,\n * it's better to wrap them; otherwise,\n * the UI would look messy.\n */\nimport { computed } from 'vue'\nimport type { Raw } from 'vue'\n\nimport type { LGraphGroup } from '@/lib/litegraph/src/LGraphGroup'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { Positionable } from '@/lib/litegraph/src/interfaces'\nimport { isLGraphGroup, isLGraphNode } from '@/utils/litegraphUtil'\n\nimport PropertiesAccordionItem from '../layout/PropertiesAccordionItem.vue'\nimport NodeSettings from './NodeSettings.vue'\n\nconst props = defineProps<{\n  nodes: Raw<Positionable>[]\n}>()\n\nconst theNodes = computed<LGraphNode[]>(() =>\n  props.nodes.filter((node) => isLGraphNode(node))\n)\n\nconst theGroups = computed<LGraphGroup[]>(() =>\n  props.nodes.filter((node) => isLGraphGroup(node))\n)\n\nconst hasGroups = computed(() => theGroups.value.length > 0)\nconst hasNodes = computed(() => theNodes.value.length > 0)\nconst isOnlyHasNodes = computed(() => hasNodes.value && !hasGroups.value)\n</script>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport type { ClassValue } from '@comfyorg/tailwind-utils'\n\nconst {\n  nodeTitle,\n  widgetName,\n  isDraggable = false,\n  isPhysical = false,\n  isShown = false,\n  class: className\n} = defineProps<{\n  nodeTitle: string\n  widgetName: string\n  isDraggable?: boolean\n  isPhysical?: boolean\n  isShown?: boolean\n  class?: ClassValue\n}>()\ndefineEmits<{ toggleVisibility: [] }>()\n\nconst icon = computed(() =>\n  isPhysical\n    ? 'icon-[lucide--link]'\n    : isShown\n      ? 'icon-[lucide--eye]'\n      : 'icon-[lucide--eye-off]'\n)\n</script>\n\n<template>\n  <div\n    :class=\"\n      cn(\n        'flex items-center gap-1 rounded-sm px-2 py-1 break-all',\n        'bg-node-component-surface',\n        isDraggable && 'ring-accent-background hover:ring-1',\n        className\n      )\n    \"\n    data-testid=\"subgraph-widget-item\"\n  >\n    <div class=\"pointer-events-none flex-1\">\n      <div\n        class=\"line-clamp-1 text-xs text-text-secondary\"\n        data-testid=\"subgraph-widget-node-name\"\n      >\n        {{ nodeTitle }}\n      </div>\n      <div class=\"line-clamp-1 text-sm/8\" data-testid=\"subgraph-widget-label\">\n        {{ widgetName }}\n      </div>\n    </div>\n    <Button\n      variant=\"muted-textonly\"\n      size=\"sm\"\n      data-testid=\"subgraph-widget-toggle\"\n      :disabled=\"isPhysical\"\n      @click.stop=\"$emit('toggleVisibility')\"\n    >\n      <i :class=\"icon\" :data-testid=\"isPhysical ? 'icon-link' : 'icon-eye'\" />\n    </Button>\n    <div\n      v-if=\"isDraggable\"\n      data-testid=\"subgraph-widget-drag-handle\"\n      class=\"pointer-events-none icon-[lucide--grip-vertical] size-4\"\n    />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { useEventListener } from '@vueuse/core'\nimport { computed, onMounted, ref, shallowRef, watch } from 'vue'\n\nimport DraggableList from '@/components/common/DraggableList.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useVueFeatureFlags } from '@/composables/useVueFeatureFlags'\nimport {\n  demoteWidget,\n  getPromotableWidgets,\n  isRecommendedWidget,\n  promoteWidget,\n  pruneDisconnected,\n  refreshPromotedWidgetRendering,\n  reorderSubgraphInputsByWidgetOrder\n} from '@/core/graph/subgraph/promotionUtils'\nimport {\n  promotedInputSource,\n  promotedInputWidget\n} from '@/core/graph/subgraph/promotedInputWidget'\nimport type { PromotedSource } from '@/core/graph/subgraph/promotedInputWidget'\nimport type { WidgetItem } from '@/core/graph/subgraph/promotionUtils'\nimport type { PreviewExposure } from '@/core/schemas/previewExposureSchema'\nimport type {\n  INodeInputSlot,\n  ISubgraphInput\n} from '@/lib/litegraph/src/types/slots'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport AsyncSearchInput from '@/components/ui/search-input/AsyncSearchInput.vue'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport {\n  getPreviewExposureHostLocator,\n  usePreviewExposureStore\n} from '@/stores/previewExposureStore'\nimport { deriveWidgetVisibility } from '@/types/widgetVisibility'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport SubgraphNodeWidget from './SubgraphNodeWidget.vue'\n\ntype PromotedRow = {\n  kind: 'promoted'\n  node: LGraphNode\n  input: INodeInputSlot & Partial<ISubgraphInput>\n  widget: IBaseWidget\n}\ntype PreviewRow = {\n  kind: 'preview'\n  node: LGraphNode\n  exposure: PreviewExposure\n  realWidget?: IBaseWidget\n}\ntype ActiveRow = PromotedRow | PreviewRow\n\nconst canvasStore = useCanvasStore()\nconst previewExposureStore = usePreviewExposureStore()\nconst searchQuery = ref('')\nconst { shouldRenderVueNodes } = useVueFeatureFlags()\n\nconst activeNode = computed(() => {\n  const node = canvasStore.selectedItems[0]\n  if (node instanceof SubgraphNode) return node\n  return undefined\n})\n\nconst promotedRows = shallowRef<readonly PromotedRow[]>([])\nfunction buildPromotedRows(node: SubgraphNode): PromotedRow[] {\n  return node.inputs.flatMap((input): PromotedRow[] => {\n    const widget = promotedInputWidget(input)\n    if (!widget) return []\n    const source = promotedInputSource(node, input)\n    if (!source) return []\n    const sourceNode = node.subgraph._nodes_by_id[source.nodeId]\n    if (!sourceNode) return []\n    return [{ kind: 'promoted', node: sourceNode, input, widget }]\n  })\n}\nfunction refreshPromotedRows() {\n  const node = activeNode.value\n  promotedRows.value = node ? buildPromotedRows(node) : []\n}\nwatch(activeNode, refreshPromotedRows, { immediate: true })\nuseEventListener(\n  () => activeNode.value?.subgraph.events,\n  [\n    'widget-promoted',\n    'widget-demoted',\n    'input-added',\n    'removing-input',\n    'inputs-reordered'\n  ],\n  refreshPromotedRows\n)\n\nfunction promotedRowSource(row: PromotedRow): PromotedSource | undefined {\n  const node = activeNode.value\n  return node ? promotedInputSource(node, row.input) : undefined\n}\n\nconst activeRows = computed<ActiveRow[]>(() => {\n  const node = activeNode.value\n  if (!node) return []\n  return [...promotedRows.value, ...getActivePreviewRows(node)]\n})\n\nconst activePromotedRows = computed<PromotedRow[]>({\n  get() {\n    return [...promotedRows.value]\n  },\n  set(value: PromotedRow[]) {\n    updateActivePromotedRows(value, activePromotedRows.value)\n  }\n})\n\nfunction getActivePreviewRows(node: SubgraphNode): PreviewRow[] {\n  const hostLocator = getPreviewExposureHostLocator(node)\n  if (!hostLocator) return []\n  const rootGraphId = node.rootGraph.id\n  const exposures = previewExposureStore.getExposures(rootGraphId, hostLocator)\n  return exposures.flatMap((exposure): PreviewRow[] => {\n    const sourceNode = node.subgraph.getNodeById(exposure.sourceNodeId)\n    if (!sourceNode) return []\n    const realWidget = getPromotableWidgets(sourceNode).find(\n      (candidate) => candidate.name === exposure.sourcePreviewName\n    )\n    return [{ kind: 'preview', node: sourceNode, exposure, realWidget }]\n  })\n}\n\nfunction updateActivePromotedRows(\n  value: PromotedRow[],\n  currentItems: PromotedRow[]\n) {\n  const node = activeNode.value\n  if (!node) {\n    console.error('Attempted to toggle widgets with no node selected')\n    return\n  }\n  const currentKeys = new Set(currentItems.map(promotedRowKey))\n  const nextKeys = new Set(value.map(promotedRowKey))\n  for (const item of value) {\n    if (!currentKeys.has(promotedRowKey(item))) promotePromotedRow(item)\n  }\n  for (const item of currentItems) {\n    if (!nextKeys.has(promotedRowKey(item))) demoteRow(item)\n  }\n  if (currentKeys.size === nextKeys.size) {\n    reorderSubgraphInputsByWidgetOrder(\n      node,\n      value.map((row) => ({ widgetId: row.widget.widgetId }))\n    )\n  }\n  refreshActiveNodeRendering()\n}\n\nconst interiorWidgets = computed<WidgetItem[]>(() => {\n  const node = activeNode.value\n  if (!node) return []\n  const { updatePreviews } = useLitegraphService()\n  const interiorNodes = node.subgraph.nodes\n  for (const node of interiorNodes) {\n    node.updateComputedDisabled()\n    updatePreviews(node)\n  }\n  return interiorNodes\n    .flatMap(nodeWidgets)\n    .filter(([_, w]: WidgetItem) => !w.computedDisabled)\n})\n\nfunction activeRowSourceKey(row: ActiveRow): string {\n  if (row.kind !== 'promoted')\n    return `${row.exposure.sourceNodeId}:${row.exposure.sourcePreviewName}`\n\n  const source = promotedRowSource(row)\n  return `${source?.nodeId ?? row.node.id}:${source?.widgetName ?? ''}`\n}\n\nconst candidateWidgets = computed<WidgetItem[]>(() => {\n  const node = activeNode.value\n  if (!node) return []\n  const promotedSourceKeys = new Set(activeRows.value.map(activeRowSourceKey))\n  return interiorWidgets.value\n    .filter(([n, w]) => !promotedSourceKeys.has(`${n.id}:${w.name}`))\n    .filter(([, widget]) => {\n      const visibility = widget.visibility ?? deriveWidgetVisibility(widget)\n      return (\n        widget.name.startsWith('$$') ||\n        !(shouldRenderVueNodes.value && visibility.surfaces.vueNode === 'never')\n      )\n    })\n})\nconst filteredCandidates = computed<WidgetItem[]>(() => {\n  const query = searchQuery.value.toLowerCase()\n  if (!query) return candidateWidgets.value\n  return candidateWidgets.value.filter(\n    ([n, w]: WidgetItem) =>\n      n.title.toLowerCase().includes(query) ||\n      w.name.toLowerCase().includes(query)\n  )\n})\n\nconst recommendedWidgets = computed(() => {\n  const node = activeNode.value\n  if (!node) return []\n  return filteredCandidates.value.filter(isRecommendedWidget)\n})\n\nfunction rowMatchesQuery(row: ActiveRow, query: string): boolean {\n  return (\n    row.node.title.toLowerCase().includes(query) ||\n    rowDisplayName(row).toLowerCase().includes(query)\n  )\n}\n\nconst filteredActive = computed<ActiveRow[]>(() => {\n  const query = searchQuery.value.toLowerCase()\n  if (!query) return activeRows.value\n  return activeRows.value.filter((row) => rowMatchesQuery(row, query))\n})\n\nconst filteredActivePromoted = computed<PromotedRow[]>(() =>\n  filteredActive.value.filter(\n    (row): row is PromotedRow => row.kind === 'promoted'\n  )\n)\n\nconst filteredActivePreviews = computed<PreviewRow[]>(() =>\n  filteredActive.value.filter(\n    (row): row is PreviewRow => row.kind === 'preview'\n  )\n)\n\nfunction refreshActiveNodeRendering() {\n  const node = activeNode.value\n  if (!node) return\n\n  refreshPromotedWidgetRendering([node])\n}\n\nfunction rowDisplayName(row: ActiveRow): string {\n  if (row.kind === 'promoted') {\n    return row.widget.label || row.widget.name\n  }\n  return (\n    row.realWidget?.label ||\n    row.realWidget?.name ||\n    row.exposure.sourcePreviewName\n  )\n}\n\nfunction isRowLinked(row: ActiveRow): boolean {\n  return row.kind === 'promoted'\n}\n\nfunction promotedRowKey(row: PromotedRow): string {\n  return `${row.node.id}: ${row.widget.name}`\n}\n\nfunction rowKey(row: ActiveRow): string {\n  return row.kind === 'promoted'\n    ? promotedRowKey(row)\n    : `${row.node.id}: ${row.exposure.name}`\n}\n\nfunction nodeWidgets(n: LGraphNode): WidgetItem[] {\n  return getPromotableWidgets(n).map((w) => [n, w])\n}\n\nfunction demoteRow(row: ActiveRow) {\n  const subgraphNode = activeNode.value\n  if (!subgraphNode) return\n  if (row.kind === 'promoted') {\n    const subgraphSlot = row.input._subgraphSlot\n    if (subgraphSlot) {\n      const inputIndex = subgraphNode.inputs.indexOf(row.input)\n      if (subgraphNode.isInputConnected(inputIndex)) subgraphSlot.disconnect()\n      else subgraphNode.subgraph.removeInput(subgraphSlot)\n    }\n    refreshActiveNodeRendering()\n    return\n  }\n  if (row.realWidget) {\n    demoteWidget(row.node, row.realWidget, [subgraphNode])\n    return\n  }\n  const hostLocator = getPreviewExposureHostLocator(subgraphNode)\n  if (!hostLocator) return\n  previewExposureStore.removeExposure(\n    subgraphNode.rootGraph.id,\n    hostLocator,\n    row.exposure.name\n  )\n  refreshActiveNodeRendering()\n}\n\nfunction promotePromotedRow(row: PromotedRow) {\n  const subgraphNode = activeNode.value\n  if (!subgraphNode) return\n  const source = promotedRowSource(row)\n  const sourceWidget = source\n    ? row.node.widgets?.find((widget) => widget.name === source.widgetName)\n    : undefined\n  if (sourceWidget) promoteWidget(row.node, sourceWidget, [subgraphNode])\n}\n\nfunction promoteCandidate([node, widget]: WidgetItem) {\n  const subgraphNode = activeNode.value\n  if (!subgraphNode) return\n  promoteWidget(node, widget, [subgraphNode])\n  refreshPromotedRows()\n}\n\nfunction showAll() {\n  for (const item of filteredCandidates.value) {\n    promoteCandidate(item)\n  }\n}\nfunction hideAll() {\n  for (const row of filteredActive.value) {\n    if (String(row.node.id) === '-1') continue\n    demoteRow(row)\n  }\n}\nfunction showRecommended() {\n  for (const item of recommendedWidgets.value) {\n    promoteCandidate(item)\n  }\n}\n\nonMounted(() => {\n  if (activeNode.value) pruneDisconnected(activeNode.value)\n})\n</script>\n\n<template>\n  <div v-if=\"activeNode\" class=\"subgraph-edit-section flex h-full flex-col\">\n    <div class=\"flex gap-2 border-b border-interface-stroke px-4 pt-1 pb-4\">\n      <AsyncSearchInput v-model=\"searchQuery\" />\n    </div>\n\n    <div class=\"flex-1\">\n      <div\n        v-if=\"\n          searchQuery &&\n          filteredActive.length === 0 &&\n          filteredCandidates.length === 0\n        \"\n        class=\"px-4 py-10 text-center text-sm text-muted-foreground\"\n      >\n        {{ $t('rightSidePanel.noneSearchDesc') }}\n      </div>\n\n      <div\n        v-if=\"filteredActive.length\"\n        data-testid=\"subgraph-editor-shown-section\"\n        class=\"flex flex-col border-b border-interface-stroke\"\n      >\n        <div\n          class=\"sticky top-0 z-10 flex min-h-12 items-center justify-between px-4 backdrop-blur-xl\"\n        >\n          <div class=\"line-clamp-1 text-sm font-semibold uppercase\">\n            {{ $t('subgraphStore.shown') }}\n          </div>\n          <a\n            class=\"cursor-pointer text-right text-xs font-normal whitespace-nowrap text-text-secondary hover:text-azure-600\"\n            @click.stop=\"hideAll\"\n          >\n            {{ $t('subgraphStore.hideAll') }}</a\n          >\n        </div>\n        <DraggableList v-slot=\"{ dragClass }\" v-model=\"activePromotedRows\">\n          <SubgraphNodeWidget\n            v-for=\"row in filteredActivePromoted\"\n            :key=\"rowKey(row)\"\n            :data-nodeid=\"row.node.id\"\n            :class=\"cn(!searchQuery && dragClass, 'bg-comfy-menu-bg')\"\n            :node-title=\"row.node.title\"\n            :widget-name=\"rowDisplayName(row)\"\n            :is-physical=\"isRowLinked(row)\"\n            :is-draggable=\"!searchQuery\"\n            is-shown\n            @toggle-visibility=\"demoteRow(row)\"\n          />\n        </DraggableList>\n        <div class=\"mt-0.5 space-y-0.5 px-2 pb-2\">\n          <SubgraphNodeWidget\n            v-for=\"row in filteredActivePreviews\"\n            :key=\"rowKey(row)\"\n            :data-nodeid=\"row.node.id\"\n            class=\"bg-comfy-menu-bg\"\n            :node-title=\"row.node.title\"\n            :widget-name=\"rowDisplayName(row)\"\n            :is-physical=\"isRowLinked(row)\"\n            :is-draggable=\"false\"\n            is-shown\n            @toggle-visibility=\"demoteRow(row)\"\n          />\n        </div>\n      </div>\n\n      <div\n        v-if=\"filteredCandidates.length\"\n        data-testid=\"subgraph-editor-hidden-section\"\n        class=\"flex flex-col border-b border-interface-stroke\"\n      >\n        <div\n          class=\"sticky top-0 z-10 flex min-h-12 items-center justify-between px-4 backdrop-blur-xl\"\n        >\n          <div class=\"line-clamp-1 text-sm font-semibold uppercase\">\n            {{ $t('subgraphStore.hidden') }}\n          </div>\n          <a\n            class=\"cursor-pointer text-right text-xs font-normal whitespace-nowrap text-text-secondary hover:text-azure-600\"\n            @click.stop=\"showAll\"\n          >\n            {{ $t('subgraphStore.showAll') }}</a\n          >\n        </div>\n        <div class=\"mt-0.5 space-y-0.5 px-2 pb-2\">\n          <SubgraphNodeWidget\n            v-for=\"[node, widget] in filteredCandidates\"\n            :key=\"`${node.id}:${widget.name}`\"\n            :data-nodeid=\"node.id\"\n            class=\"bg-comfy-menu-bg\"\n            :node-title=\"node.title\"\n            :widget-name=\"widget.name\"\n            @toggle-visibility=\"promoteCandidate([node, widget])\"\n          />\n        </div>\n      </div>\n\n      <div\n        v-if=\"recommendedWidgets.length\"\n        class=\"flex justify-center border-b border-interface-stroke py-4\"\n      >\n        <Button\n          size=\"sm\"\n          class=\"rounded-sm border-none px-3 py-0.5\"\n          @click.stop=\"showRecommended\"\n        >\n          {{ $t('subgraphStore.showRecommended') }}\n        </Button>\n      </div>\n    </div>\n  </div>\n</template>\n","import { nextTick } from 'vue'\n\nimport { visibleCanvasViewport } from '@/composables/canvas/visibleCanvasViewport'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { app } from '@/scripts/app'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useSubgraphNavigationStore } from '@/stores/subgraphNavigationStore'\nimport { getNodeByExecutionId } from '@/utils/graphTraversalUtil'\n\nasync function waitForAnimationFrame() {\n  await new Promise<void>((resolve) => {\n    const timeoutId = window.setTimeout(resolve, 100)\n    requestAnimationFrame(() => {\n      window.clearTimeout(timeoutId)\n      resolve()\n    })\n  })\n}\n\nasync function waitForCanvasNavigation() {\n  await nextTick()\n\n  // Double frame waits for LiteGraph's internal canvas cycle. The timeout\n  // keeps focus calls from hanging while the document is backgrounded.\n  await waitForAnimationFrame()\n  await waitForAnimationFrame()\n}\n\nexport function useFocusNode() {\n  const canvasStore = useCanvasStore()\n  const navigationStore = useSubgraphNavigationStore()\n\n  async function focusNodeInstance(node: LGraphNode) {\n    const canvas = canvasStore.canvas\n    if (!canvas || !node.graph) return\n\n    const graphChanged = canvas.graph !== node.graph\n    const navigated = await navigationStore.navigateToGraph(node.graph)\n    if (!navigated) return\n    if (graphChanged) await waitForCanvasNavigation()\n\n    const activeCanvas = canvasStore.canvas\n    if (\n      !activeCanvas ||\n      activeCanvas.graph !== node.graph ||\n      !node.graph.nodes.includes(node)\n    ) {\n      return\n    }\n    activeCanvas.animateToBounds(node.boundingRect, {\n      viewport: visibleCanvasViewport(activeCanvas)\n    })\n  }\n\n  /* Locate and focus a node on the canvas by its execution ID. */\n  async function focusNode(\n    nodeId: string,\n    executionIdMap?: Map<string, LGraphNode>\n  ) {\n    if (!canvasStore.canvas) return\n\n    const graphNode = executionIdMap\n      ? executionIdMap.get(nodeId)\n      : getNodeByExecutionId(app.rootGraph, nodeId)\n    if (!graphNode?.graph) return\n\n    await focusNodeInstance(graphNode)\n  }\n\n  return {\n    focusNode,\n    focusNodeInstance\n  }\n}\n","<template>\n  <section :class=\"cn('group flex min-w-0 flex-col py-2', className)\">\n    <div class=\"flex min-h-8 w-full items-center gap-2 px-3\">\n      <button\n        type=\"button\"\n        class=\"flex min-w-0 flex-1 cursor-pointer items-center gap-2 rounded-sm border-0 bg-transparent p-0 text-left outline-none focus-visible:ring-1 focus-visible:ring-border-default\"\n        :aria-expanded=\"!collapse\"\n        :aria-controls=\"bodyId\"\n        @click=\"collapse = !collapse\"\n      >\n        <span\n          data-testid=\"error-section-count-badge\"\n          :data-severity=\"severity\"\n          :class=\"\n            cn(\n              'flex h-4 min-w-4 shrink-0 items-center justify-center rounded-full px-1 text-2xs/none font-semibold tabular-nums',\n              severity === 'error'\n                ? 'bg-destructive-background-hover text-white'\n                : 'bg-warning-background text-warning-on-background'\n            )\n          \"\n        >\n          {{ count }}\n        </span>\n        <span class=\"min-w-0 truncate text-sm text-base-foreground\">\n          {{ title }}\n        </span>\n        <slot name=\"title-badge\" />\n      </button>\n      <slot name=\"actions\" />\n      <button\n        type=\"button\"\n        class=\"flex size-8 shrink-0 cursor-pointer items-center justify-center rounded-sm border-0 bg-transparent p-0 outline-none focus-visible:ring-1 focus-visible:ring-border-default\"\n        :aria-expanded=\"!collapse\"\n        :aria-controls=\"bodyId\"\n        :aria-label=\"\n          collapse ? t('rightSidePanel.expand') : t('rightSidePanel.collapse')\n        \"\n        @click=\"collapse = !collapse\"\n      >\n        <i\n          aria-hidden=\"true\"\n          :class=\"\n            cn(\n              'icon-[lucide--chevron-up] size-4 text-muted-foreground transition-transform group-hover:text-base-foreground',\n              collapse && '-rotate-180'\n            )\n          \"\n        />\n      </button>\n    </div>\n    <TransitionCollapse>\n      <div v-if=\"!collapse\" :id=\"bodyId\">\n        <slot />\n      </div>\n    </TransitionCollapse>\n  </section>\n</template>\n\n<script setup lang=\"ts\">\nimport { useId } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport TransitionCollapse from '@/components/rightSidePanel/layout/TransitionCollapse.vue'\nimport type { ErrorGroupSeverity } from '@/components/rightSidePanel/errors/types'\n\nconst {\n  title,\n  count,\n  severity,\n  class: className\n} = defineProps<{\n  title: string\n  count: number\n  severity: ErrorGroupSeverity\n  class?: string\n}>()\n\nconst collapse = defineModel<boolean>('collapse', { default: false })\n\nconst bodyId = useId()\nconst { t } = useI18n()\n</script>\n","<template>\n  <Button\n    variant=\"textonly\"\n    size=\"icon-sm\"\n    class=\"size-8 shrink-0 text-muted-foreground hover:text-base-foreground focus-visible:ring-inset\"\n    :aria-label=\"label\"\n    @click.stop=\"emit('locate')\"\n  >\n    <i aria-hidden=\"true\" class=\"icon-[lucide--locate] size-4\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nconst { label } = defineProps<{\n  label: string\n}>()\n\nconst emit = defineEmits<{\n  locate: []\n}>()\n</script>\n","import { useCommandStore } from '@/stores/commandStore'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useTelemetry } from '@/platform/telemetry'\n\nexport function useErrorActions() {\n  const telemetry = useTelemetry()\n  const commandStore = useCommandStore()\n  const { staticUrls } = useExternalLink()\n\n  function openGitHubIssues() {\n    telemetry?.trackUiButtonClicked({\n      button_id: 'error_tab_github_issues_clicked',\n      element_group: 'errors_panel'\n    })\n    window.open(staticUrls.githubIssues, '_blank', 'noopener,noreferrer')\n  }\n\n  function contactSupport() {\n    telemetry?.trackHelpResourceClicked({\n      resource_type: 'help_feedback',\n      is_external: true,\n      source: 'error_dialog'\n    })\n    return commandStore.execute('Comfy.ContactSupport')\n  }\n\n  function findOnGitHub(errorMessage: string) {\n    telemetry?.trackUiButtonClicked({\n      button_id: 'error_tab_find_existing_issues_clicked',\n      element_group: 'errors_panel'\n    })\n    const query = encodeURIComponent(errorMessage + ' is:issue')\n    window.open(\n      `${staticUrls.githubIssues}?q=${query}`,\n      '_blank',\n      'noopener,noreferrer'\n    )\n  }\n\n  return { openGitHubIssues, contactSupport, findOnGitHub }\n}\n","import { computed, reactive, toValue, watch } from 'vue'\n\nimport type { MaybeRefOrGetter } from 'vue'\n\nimport { until } from '@vueuse/core'\n\nimport { api } from '@/scripts/api'\nimport { app } from '@/scripts/app'\nimport { useSystemStatsStore } from '@/stores/systemStatsStore'\nimport { createCancelToken } from '@/utils/createCancelToken'\nimport { generateErrorReport } from '@/utils/errorReportUtil'\n\nimport type { ErrorCardData } from './types'\n\n/** Fallback exception type for error reports when the backend does not provide one. Not i18n'd: used in diagnostic reports only. */\nconst FALLBACK_EXCEPTION_TYPE = 'Runtime Error'\n\nexport function useErrorReport(cardSource: MaybeRefOrGetter<ErrorCardData>) {\n  const systemStatsStore = useSystemStatsStore()\n  const enrichedDetails = reactive<Partial<Record<number, string>>>({})\n\n  const displayedDetailsMap = computed(() => {\n    const card = toValue(cardSource)\n    return Object.fromEntries(\n      card.errors.map((error, idx) => [\n        idx,\n        enrichedDetails[idx] ?? error.displayDetails ?? error.details\n      ])\n    )\n  })\n\n  watch(\n    () => toValue(cardSource),\n    async (card, _, onCleanup) => {\n      const { cancel, isCancelled } = createCancelToken()\n      onCleanup(cancel)\n\n      for (const key of Object.keys(enrichedDetails)) {\n        delete enrichedDetails[key as unknown as number]\n      }\n\n      const runtimeErrors = card.errors\n        .map((error, idx) => ({ error, idx }))\n        .filter(({ error }) => error.isRuntimeError)\n\n      if (runtimeErrors.length === 0) return\n\n      if (!systemStatsStore.systemStats) {\n        if (systemStatsStore.isLoading) {\n          await until(() => systemStatsStore.isLoading).toBe(false)\n        } else {\n          try {\n            await systemStatsStore.refetchSystemStats()\n          } catch (e) {\n            console.warn('Failed to fetch system stats for error report:', e)\n            return\n          }\n        }\n      }\n      if (!systemStatsStore.systemStats || isCancelled()) return\n\n      const logs = await api\n        .getLogs()\n        .catch(() => 'Failed to retrieve server logs')\n      if (isCancelled()) return\n\n      const workflow = (() => {\n        try {\n          return app.rootGraph.serialize()\n        } catch (e) {\n          console.warn('Failed to serialize workflow for error report:', e)\n          return null\n        }\n      })()\n      if (!workflow) return\n\n      for (const { error, idx } of runtimeErrors) {\n        try {\n          const report = generateErrorReport({\n            exceptionType: error.exceptionType ?? FALLBACK_EXCEPTION_TYPE,\n            exceptionMessage: error.message,\n            traceback: error.details,\n            nodeId: card.nodeId,\n            nodeType: card.title,\n            systemStats: systemStatsStore.systemStats,\n            serverLogs: logs,\n            workflow\n          })\n          enrichedDetails[idx] = report\n        } catch (e) {\n          console.warn('Failed to generate error report:', e)\n        }\n      }\n    },\n    { immediate: true }\n  )\n\n  return { displayedDetailsMap }\n}\n","<template>\n  <div class=\"flex min-h-0 flex-1 flex-col gap-2 overflow-hidden\">\n    <div v-if=\"card.nodeId\" class=\"flex min-h-8 flex-wrap items-center gap-2\">\n      <span class=\"flex min-w-0 flex-1\">\n        <button\n          v-if=\"hasRuntimeError && (card.nodeTitle || card.title)\"\n          type=\"button\"\n          class=\"m-0 max-w-full min-w-0 cursor-pointer appearance-none truncate rounded-sm border-0 bg-transparent p-0 text-left text-xs font-normal text-base-foreground outline-none focus:outline-none focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none focus-visible:ring-inset\"\n          @click=\"handleLocateNode\"\n        >\n          {{ card.nodeTitle || card.title }}\n        </button>\n        <span\n          v-else-if=\"card.nodeTitle || card.title\"\n          class=\"max-w-full min-w-0 truncate text-xs font-normal text-base-foreground\"\n        >\n          {{ card.nodeTitle || card.title }}\n        </span>\n      </span>\n      <div class=\"flex shrink-0 items-center\">\n        <Button\n          v-if=\"hasRuntimeError\"\n          variant=\"textonly\"\n          size=\"icon-sm\"\n          :class=\"\n            cn(\n              'size-8 shrink-0 text-muted-foreground hover:text-base-foreground focus-visible:ring-inset',\n              runtimeDetailsExpanded &&\n                'bg-secondary-background-selected text-base-foreground hover:bg-secondary-background-selected'\n            )\n          \"\n          :aria-label=\"t('g.details')\"\n          :aria-controls=\"runtimeDetailsControlIds || undefined\"\n          :aria-expanded=\"runtimeDetailsExpanded\"\n          @click.stop=\"toggleRuntimeDetails\"\n        >\n          <i class=\"icon-[lucide--monitor-x] size-4\" />\n        </Button>\n        <LocateNodeButton :label=\"locateLabel\" @locate=\"handleLocateNode\" />\n      </div>\n    </div>\n\n    <div\n      class=\"flex min-h-0 flex-1 flex-col space-y-2 divide-y divide-interface-stroke/20\"\n    >\n      <div\n        v-for=\"(error, idx) in card.errors\"\n        :key=\"idx\"\n        class=\"flex min-h-0 flex-col gap-1\"\n      >\n        <p\n          v-if=\"getInlineMessage(error)\"\n          class=\"m-0 max-h-[4lh] overflow-y-auto px-0.5 text-xs/relaxed wrap-break-word whitespace-pre-wrap\"\n        >\n          {{ getInlineMessage(error) }}\n        </p>\n\n        <ul\n          v-if=\"getInlineItemLabel(error)\"\n          class=\"m-0 list-disc space-y-1 pl-5 text-xs/relaxed text-muted-foreground marker:text-muted-foreground\"\n        >\n          <li class=\"min-w-0 wrap-break-word\">\n            <button\n              v-if=\"card.nodeId\"\n              type=\"button\"\n              class=\"m-0 inline max-w-full cursor-pointer appearance-none rounded-sm border-0 bg-transparent p-0 text-left text-sm/relaxed font-normal wrap-break-word text-muted-foreground outline-none hover:text-base-foreground focus:outline-none focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none focus-visible:ring-inset\"\n              @click=\"handleLocateNode\"\n            >\n              {{ getInlineItemLabel(error) }}\n            </button>\n            <span v-else>\n              {{ getInlineItemLabel(error) }}\n            </span>\n          </li>\n        </ul>\n\n        <div\n          v-if=\"!error.isRuntimeError && getInlineDetails(error, idx)\"\n          :class=\"\n            cn(\n              'overflow-y-auto rounded-lg bg-base-foreground/5 p-3',\n              'max-h-[6lh]'\n            )\n          \"\n        >\n          <p\n            class=\"m-0 text-xs/normal wrap-break-word whitespace-pre-wrap text-base-foreground/50\"\n          >\n            {{ getInlineDetails(error, idx) }}\n          </p>\n        </div>\n\n        <TransitionCollapse>\n          <div\n            v-if=\"error.isRuntimeError && runtimeDetailsExpanded\"\n            :id=\"getRuntimeDetailsId(idx)\"\n            role=\"region\"\n            data-testid=\"runtime-error-panel\"\n            :aria-label=\"t('rightSidePanel.errorLog')\"\n            class=\"flex min-h-0 flex-col gap-1\"\n          >\n            <div\n              v-if=\"getInlineDetails(error, idx)\"\n              class=\"flex flex-col gap-3 rounded-lg bg-base-foreground/5 p-3\"\n            >\n              <div class=\"flex flex-col gap-2\">\n                <div class=\"flex items-center justify-between gap-1 py-1\">\n                  <span\n                    class=\"text-xs font-semibold text-base-foreground uppercase\"\n                  >\n                    {{ t('rightSidePanel.errorLog') }}\n                  </span>\n                  <Button\n                    variant=\"textonly\"\n                    size=\"icon-sm\"\n                    class=\"size-7 shrink-0 text-muted-foreground hover:text-base-foreground focus-visible:ring-inset\"\n                    :aria-label=\"t('g.copy')\"\n                    data-testid=\"error-card-copy\"\n                    @click=\"handleCopyError(idx)\"\n                  >\n                    <i class=\"icon-[lucide--copy] size-4\" />\n                  </Button>\n                </div>\n                <div class=\"max-h-[15lh] overflow-y-auto\">\n                  <p\n                    class=\"m-0 text-xs/normal wrap-break-word whitespace-pre-wrap text-base-foreground/50\"\n                  >\n                    {{ getInlineDetails(error, idx) }}\n                  </p>\n                </div>\n              </div>\n\n              <div aria-hidden=\"true\" class=\"h-px w-full bg-interface-stroke\" />\n\n              <div class=\"flex items-center justify-between gap-2\">\n                <Button\n                  :tooltip=\"t('rightSidePanel.getHelpTooltip')\"\n                  variant=\"textonly\"\n                  size=\"sm\"\n                  class=\"justify-start gap-1 px-0 text-xs hover:bg-transparent hover:text-base-foreground focus-visible:ring-inset\"\n                  @click=\"handleGetHelp\"\n                >\n                  <i class=\"icon-[lucide--external-link] size-4\" />\n                  {{ t('g.getHelpAction') }}\n                </Button>\n                <Button\n                  :tooltip=\"t('rightSidePanel.findOnGithubTooltip')\"\n                  variant=\"textonly\"\n                  size=\"sm\"\n                  class=\"justify-end gap-1 px-0 text-xs hover:bg-transparent hover:text-base-foreground focus-visible:ring-inset\"\n                  data-testid=\"error-card-find-on-github\"\n                  @click=\"handleCheckGithub(error)\"\n                >\n                  <i class=\"icon-[lucide--github] size-4\" />\n                  {{ t('g.findOnGithub') }}\n                </Button>\n              </div>\n            </div>\n          </div>\n        </TransitionCollapse>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport LocateNodeButton from './LocateNodeButton.vue'\nimport TransitionCollapse from '../layout/TransitionCollapse.vue'\n\nimport type { ErrorCardData, ErrorItem } from './types'\nimport { useErrorActions } from './useErrorActions'\nimport { useErrorReport } from './useErrorReport'\n\nconst { card } = defineProps<{\n  card: ErrorCardData\n}>()\n\nconst emit = defineEmits<{\n  locateNode: [nodeId: string]\n  copyToClipboard: [text: string]\n}>()\n\nconst { t } = useI18n()\nconst { displayedDetailsMap } = useErrorReport(() => card)\nconst { findOnGitHub, contactSupport: handleGetHelp } = useErrorActions()\nconst runtimeDetailsExpanded = ref(true)\nconst hasRuntimeError = computed(() =>\n  card.errors.some((error) => error.isRuntimeError)\n)\nconst locateLabel = computed(() => {\n  const item = card.nodeTitle || card.title\n  return item\n    ? t('rightSidePanel.locateNodeFor', { item }, { escapeParameter: false })\n    : t('rightSidePanel.locateNode')\n})\nconst runtimeDetailsControlIds = computed(() =>\n  card.errors\n    .map((error, idx) => (error.isRuntimeError ? getRuntimeDetailsId(idx) : ''))\n    .filter(Boolean)\n    .join(' ')\n)\n\nfunction toggleRuntimeDetails() {\n  runtimeDetailsExpanded.value = !runtimeDetailsExpanded.value\n}\n\nfunction handleLocateNode() {\n  if (card.nodeId) {\n    emit('locateNode', card.nodeId)\n  }\n}\n\nfunction handleCopyError(idx: number) {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'error_tab_copy_error_clicked',\n    element_group: 'errors_panel'\n  })\n  const details = displayedDetailsMap.value[idx]\n  const message = getCopyMessage(card.errors[idx])\n  emit('copyToClipboard', [message, details].filter(Boolean).join('\\n\\n'))\n}\n\nfunction handleCheckGithub(error: ErrorItem) {\n  findOnGitHub(error.message)\n}\n\nfunction getCopyMessage(error: ErrorItem | undefined) {\n  return error?.displayMessage ?? error?.message\n}\n\nfunction getInlineMessage(error: ErrorItem | undefined) {\n  if (!error || error.displayMessage) return undefined\n  return error.message\n}\n\nfunction getInlineItemLabel(error: ErrorItem | undefined) {\n  if (!error || error.isRuntimeError) return undefined\n  return error.displayItemLabel\n}\n\nfunction getInlineDetails(error: ErrorItem | undefined, idx: number) {\n  if (getInlineItemLabel(error)) return undefined\n  return displayedDetailsMap.value[idx]\n}\n\nfunction getRuntimeDetailsId(idx: number) {\n  return `${card.id}-runtime-details-${idx}`\n}\n</script>\n","import { createSharedComposable, useEventListener } from '@vueuse/core'\nimport { ref } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { api } from '@/scripts/api'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useConflictDetection } from '@/workbench/extensions/manager/composables/useConflictDetection'\nimport { useComfyManagerService } from '@/workbench/extensions/manager/services/comfyManagerService'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\n\nexport const useApplyChanges = createSharedComposable(() => {\n  const comfyManagerStore = useComfyManagerStore()\n  const settingStore = useSettingStore()\n  const { runFullConflictAnalysis } = useConflictDetection()\n\n  const isRestarting = ref(false)\n  const isRestartCompleted = ref(false)\n\n  async function applyChanges(onClose?: () => void) {\n    if (isRestarting.value) return\n\n    isRestarting.value = true\n    isRestartCompleted.value = false\n\n    const originalToastSetting = settingStore.get(\n      'Comfy.Toast.DisableReconnectingToast'\n    )\n    const onReconnect = async () => {\n      try {\n        comfyManagerStore.setStale()\n        await useCommandStore().execute('Comfy.RefreshNodeDefinitions')\n        await useWorkflowService().reloadCurrentWorkflow()\n        runFullConflictAnalysis().catch((err) => {\n          console.error('[useApplyChanges] Conflict analysis failed:', err)\n        })\n      } catch (err) {\n        console.error('[useApplyChanges] Post-reconnect tasks failed:', err)\n      } finally {\n        try {\n          await settingStore.set(\n            'Comfy.Toast.DisableReconnectingToast',\n            originalToastSetting\n          )\n        } catch (err) {\n          console.error(\n            '[useApplyChanges] Failed to restore reconnect toast setting:',\n            err\n          )\n        }\n        isRestarting.value = false\n        isRestartCompleted.value = true\n\n        setTimeout(() => {\n          onClose?.()\n        }, 3000)\n      }\n    }\n\n    let hasReconnected = false\n    const stopReconnectListener = useEventListener(\n      api,\n      'reconnected',\n      () => {\n        clearTimeout(reconnectTimeout)\n        hasReconnected = true\n        void onReconnect()\n      },\n      { once: true }\n    )\n\n    const RECONNECT_TIMEOUT_MS = 120_000 // 2 minutes\n    let reconnectTimeout: ReturnType<typeof setTimeout> | undefined\n\n    try {\n      await settingStore.set('Comfy.Toast.DisableReconnectingToast', true)\n      await useComfyManagerService().rebootComfyUI()\n      reconnectTimeout = setTimeout(async () => {\n        if (hasReconnected) return\n        stopReconnectListener()\n        try {\n          await settingStore.set(\n            'Comfy.Toast.DisableReconnectingToast',\n            originalToastSetting\n          )\n        } catch (err) {\n          console.error(\n            '[useApplyChanges] Failed to restore reconnect toast setting:',\n            err\n          )\n        }\n        isRestarting.value = false\n        isRestartCompleted.value = false\n        console.error('[useApplyChanges] Reconnect timed out')\n      }, RECONNECT_TIMEOUT_MS)\n    } catch (error) {\n      stopReconnectListener()\n      try {\n        await settingStore.set(\n          'Comfy.Toast.DisableReconnectingToast',\n          originalToastSetting\n        )\n      } catch (restoreErr) {\n        console.error(\n          '[useApplyChanges] Failed to restore reconnect toast setting:',\n          restoreErr\n        )\n      } finally {\n        isRestarting.value = false\n        isRestartCompleted.value = false\n        onClose?.()\n      }\n      throw error\n    }\n  }\n\n  return { isRestarting, isRestartCompleted, applyChanges }\n})\n","<template>\n  <div class=\"mb-1 flex w-full flex-col gap-0.5 last:mb-0\">\n    <div\n      :aria-current=\"highlighted ? 'true' : undefined\"\n      :class=\"\n        cn(\n          'flex min-h-8 items-center gap-1',\n          selectionEmphasisClass(highlighted)\n        )\n      \"\n    >\n      <Button\n        v-if=\"hasMultipleNodeTypes\"\n        data-testid=\"missing-node-pack-expand\"\n        variant=\"textonly\"\n        size=\"unset\"\n        :aria-label=\"\n          expanded\n            ? t('rightSidePanel.missingNodePacks.collapse')\n            : t('rightSidePanel.missingNodePacks.expand')\n        \"\n        :aria-expanded=\"expanded\"\n        class=\"h-8 w-4 shrink-0 p-0 hover:bg-transparent focus-visible:ring-inset\"\n        @click=\"toggleExpand\"\n      >\n        <i\n          aria-hidden=\"true\"\n          :class=\"\n            cn(\n              'icon-[lucide--chevron-right] size-4 text-muted-foreground transition-transform duration-200',\n              expanded && 'rotate-90'\n            )\n          \"\n        />\n      </Button>\n      <i\n        v-if=\"isUnknownPack\"\n        class=\"icon-[lucide--triangle-alert] size-4 shrink-0 text-warning-background\"\n      />\n      <span class=\"flex min-w-0 flex-1 items-center gap-2\">\n        <span class=\"flex min-w-0 items-center gap-2.5\">\n          <button\n            v-if=\"hasMultipleNodeTypes && !group.isResolving\"\n            type=\"button\"\n            :class=\"\n              cn(\n                packTextButtonClass,\n                isUnknownPack\n                  ? 'text-warning-background'\n                  : 'text-base-foreground'\n              )\n            \"\n            :aria-expanded=\"expanded\"\n            @click=\"toggleExpand\"\n          >\n            {{ packDisplayName }}\n          </button>\n          <button\n            v-else-if=\"primaryLocatableNodeType\"\n            type=\"button\"\n            :class=\"\n              cn(\n                packTextButtonClass,\n                isUnknownPack\n                  ? 'text-warning-background'\n                  : 'text-base-foreground'\n              )\n            \"\n            @click=\"handleLocateNode(primaryLocatableNodeType)\"\n          >\n            {{ packDisplayName }}\n          </button>\n          <span\n            v-else\n            class=\"min-w-0 truncate text-xs/relaxed font-normal\"\n            :class=\"\n              isUnknownPack ? 'text-warning-background' : 'text-base-foreground'\n            \"\n          >\n            <span v-if=\"group.isResolving\" class=\"text-muted-foreground italic\">\n              {{ t('g.loading') }}...\n            </span>\n            <span v-else>\n              {{ packDisplayName }}\n            </span>\n          </span>\n          <Button\n            v-if=\"showInfoButton && group.packId !== null\"\n            variant=\"textonly\"\n            size=\"icon-sm\"\n            class=\"size-6 shrink-0 text-muted-foreground hover:bg-transparent hover:text-base-foreground focus-visible:ring-inset\"\n            :aria-label=\"t('rightSidePanel.missingNodePacks.viewInManager')\"\n            @click=\"emit('openManagerInfo', group.packId ?? '')\"\n          >\n            <i class=\"icon-[lucide--info] size-4\" />\n          </Button>\n          <span\n            v-if=\"showNodeCount\"\n            data-testid=\"missing-node-pack-count\"\n            class=\"flex h-4 min-w-4 shrink-0 items-center justify-center rounded-sm bg-secondary-background-hover px-1 text-2xs font-semibold text-base-foreground\"\n          >\n            {{ group.nodeTypes.length }}\n          </span>\n        </span>\n      </span>\n      <div v-if=\"showInstallAction\" class=\"ml-auto shrink-0\">\n        <Button\n          variant=\"secondary\"\n          size=\"sm\"\n          class=\"shrink-0 focus-visible:ring-inset\"\n          :disabled=\"isPackInstalled || isInstalling\"\n          @click=\"handlePackInstallClick\"\n        >\n          <DotSpinner\n            v-if=\"isInstalling\"\n            duration=\"1s\"\n            :size=\"12\"\n            class=\"mr-1.5 shrink-0\"\n          />\n          <span class=\"min-w-0 truncate text-base-foreground\">\n            {{\n              isInstalling\n                ? t('rightSidePanel.missingNodePacks.installing')\n                : isPackInstalled\n                  ? t('rightSidePanel.missingNodePacks.installed')\n                  : t('g.install')\n            }}\n          </span>\n        </Button>\n      </div>\n      <div\n        v-else-if=\"showLoadingAction\"\n        class=\"ml-auto flex h-6 shrink-0 cursor-not-allowed items-center justify-center overflow-hidden rounded-sm bg-secondary-background px-2 py-1 text-xs opacity-60 select-none\"\n      >\n        <DotSpinner duration=\"1s\" :size=\"12\" class=\"mr-1.5 shrink-0\" />\n        <span class=\"min-w-0 truncate text-xs text-base-foreground\">\n          {{ t('g.loading') }}\n        </span>\n      </div>\n      <div v-else-if=\"showSearchAction\" class=\"ml-auto shrink-0\">\n        <Button\n          variant=\"secondary\"\n          size=\"sm\"\n          class=\"shrink-0 focus-visible:ring-inset\"\n          @click=\"\n            openManager({\n              initialTab: ManagerTab.All,\n              initialPackId: group.packId!\n            })\n          \"\n        >\n          <span class=\"min-w-0 truncate text-base-foreground\">\n            {{ t('g.search') }}\n          </span>\n        </Button>\n      </div>\n      <LocateNodeButton\n        v-if=\"primaryLocatableNodeType\"\n        :label=\"\n          t(\n            'rightSidePanel.locateNodeFor',\n            {\n              item: getLabel(primaryLocatableNodeType)\n            },\n            { escapeParameter: false }\n          )\n        \"\n        @locate=\"handleLocateNode(primaryLocatableNodeType)\"\n      />\n    </div>\n\n    <TransitionCollapse>\n      <ul\n        v-if=\"showNodeTypeList\"\n        :class=\"\n          cn(\n            'm-0 list-none p-0',\n            (hasMultipleNodeTypes || isUnknownPack) && 'pl-5'\n          )\n        \"\n      >\n        <li\n          v-for=\"nodeType in group.nodeTypes\"\n          :key=\"getKey(nodeType)\"\n          class=\"min-w-0\"\n        >\n          <div class=\"flex min-w-0 items-center gap-2\">\n            <span class=\"flex min-w-0 flex-1 items-center gap-1\">\n              <button\n                v-if=\"isLocatableNodeType(nodeType)\"\n                type=\"button\"\n                :class=\"\n                  cn(\n                    packTextButtonClass,\n                    'text-muted-foreground hover:text-base-foreground'\n                  )\n                \"\n                @click=\"handleLocateNode(nodeType)\"\n              >\n                {{ getLabel(nodeType) }}\n              </button>\n              <span\n                v-else\n                class=\"text-xs/relaxed wrap-break-word text-muted-foreground\"\n              >\n                {{ getLabel(nodeType) }}\n              </span>\n            </span>\n            <LocateNodeButton\n              v-if=\"isLocatableNodeType(nodeType)\"\n              :label=\"\n                t(\n                  'rightSidePanel.locateNodeFor',\n                  { item: getLabel(nodeType) },\n                  { escapeParameter: false }\n                )\n              \"\n              @locate=\"handleLocateNode(nodeType)\"\n            />\n          </div>\n        </li>\n      </ul>\n    </TransitionCollapse>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { selectionEmphasisClass } from './selectionEmphasis'\nimport Button from '@/components/ui/button/Button.vue'\nimport DotSpinner from '@/components/common/DotSpinner.vue'\nimport LocateNodeButton from '@/components/rightSidePanel/errors/LocateNodeButton.vue'\nimport TransitionCollapse from '@/components/rightSidePanel/layout/TransitionCollapse.vue'\nimport { useMissingNodes } from '@/workbench/extensions/manager/composables/nodePack/useMissingNodes'\nimport { usePackInstall } from '@/workbench/extensions/manager/composables/nodePack/usePackInstall'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { useManagerState } from '@/workbench/extensions/manager/composables/useManagerState'\nimport { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\nimport type { MissingPackGroup } from '@/components/rightSidePanel/errors/useErrorGroups'\n\nconst { group, showInfoButton, highlighted } = defineProps<{\n  group: MissingPackGroup\n  showInfoButton: boolean\n  /** Emphasize the header row (pack containing the canvas selection). */\n  highlighted?: boolean\n}>()\n\nconst emit = defineEmits<{\n  locateNode: [nodeId: string]\n  openManagerInfo: [packId: string]\n}>()\n\nconst { t } = useI18n()\nconst expandedOverride = ref<boolean | null>(null)\n\nconst packTextButtonClass =\n  'm-0 inline max-w-full cursor-pointer appearance-none border-0 bg-transparent p-0 text-left text-xs/relaxed font-normal wrap-break-word outline-none focus:outline-none rounded-sm focus-visible:ring-1 focus-visible:ring-border-default focus-visible:ring-inset focus-visible:outline-none'\n\nconst { missingNodePacks, isLoading } = useMissingNodes()\nconst comfyManagerStore = useComfyManagerStore()\nconst { shouldShowManagerButtons, openManager } = useManagerState()\n\nconst nodePack = computed(() => {\n  if (!group.packId) return null\n  return missingNodePacks.value.find((p) => p.id === group.packId) ?? null\n})\n\nconst { isInstalling, installAllPacks } = usePackInstall(() =>\n  nodePack.value ? [nodePack.value] : []\n)\n\nconst isUnknownPack = computed(\n  () => group.packId === null && !group.isResolving\n)\n\nconst packDisplayName = computed(() => {\n  if (group.packId === null) {\n    return t('rightSidePanel.missingNodePacks.unknownPack')\n  }\n  return nodePack.value?.name ?? group.packId\n})\n\nconst isPackInstalled = computed(\n  () => group.packId !== null && comfyManagerStore.isPackInstalled(group.packId)\n)\n\nconst showInstallAction = computed(\n  () =>\n    shouldShowManagerButtons.value &&\n    group.packId !== null &&\n    (nodePack.value !== null || isPackInstalled.value)\n)\n\nconst showLoadingAction = computed(\n  () =>\n    shouldShowManagerButtons.value &&\n    group.packId !== null &&\n    !showInstallAction.value &&\n    isLoading.value\n)\n\nconst showSearchAction = computed(\n  () =>\n    shouldShowManagerButtons.value &&\n    group.packId !== null &&\n    !showInstallAction.value &&\n    !showLoadingAction.value\n)\n\nconst hasMultipleNodeTypes = computed(() => group.nodeTypes.length > 1)\nconst showNodeCount = computed(() => group.nodeTypes.length !== 1)\nconst expanded = computed(\n  () =>\n    expandedOverride.value ??\n    (isUnknownPack.value && hasMultipleNodeTypes.value)\n)\nconst showNodeTypeList = computed(\n  () =>\n    (isUnknownPack.value && group.nodeTypes.length === 1) ||\n    (hasMultipleNodeTypes.value && expanded.value)\n)\nconst primaryLocatableNodeType = computed(() => {\n  if (group.isResolving) return null\n  if (isUnknownPack.value) return null\n  if (group.nodeTypes.length !== 1) return null\n  const [nodeType] = group.nodeTypes\n  return isLocatableNodeType(nodeType) ? nodeType : null\n})\n\nfunction handlePackInstallClick() {\n  if (!group.packId) return\n  if (!isPackInstalled.value) {\n    void installAllPacks()\n  }\n}\n\nfunction toggleExpand() {\n  expandedOverride.value = !expanded.value\n}\n\nfunction getKey(nodeType: MissingNodeType): string {\n  if (typeof nodeType === 'string') return nodeType\n  return nodeType.nodeId != null ? String(nodeType.nodeId) : nodeType.type\n}\n\nfunction getLabel(nodeType: MissingNodeType): string {\n  return typeof nodeType === 'string' ? nodeType : nodeType.type\n}\n\nfunction isLocatableNodeType(\n  nodeType: MissingNodeType\n): nodeType is Exclude<MissingNodeType, string> & { nodeId: string | number } {\n  return typeof nodeType !== 'string' && nodeType.nodeId != null\n}\n\nfunction handleLocateNode(nodeType: MissingNodeType) {\n  if (!isLocatableNodeType(nodeType)) return\n  emit('locateNode', String(nodeType.nodeId))\n}\n</script>\n","<template>\n  <div data-testid=\"missing-node-card\" class=\"px-3\">\n    <!-- Core node version warning (OSS only) -->\n    <div\n      v-if=\"!isCloud && hasMissingCoreNodes\"\n      role=\"alert\"\n      class=\"mb-3 flex gap-2.5 rounded-lg border border-warning-background/30 bg-warning-background/10 p-3\"\n    >\n      <i\n        aria-hidden=\"true\"\n        class=\"mt-0.5 icon-[lucide--triangle-alert] size-4 shrink-0 text-warning-background\"\n      />\n      <div class=\"flex flex-col gap-1.5 text-xs/relaxed text-muted-foreground\">\n        <p class=\"m-0\">\n          {{\n            currentComfyUIVersion\n              ? t('loadWorkflowWarning.newerVersionRequired', {\n                  version: currentComfyUIVersion\n                })\n              : t('loadWorkflowWarning.newerVersionRequiredGeneric')\n          }}\n        </p>\n        <div\n          v-for=\"[version, nodes] in sortedMissingCoreNodes\"\n          :key=\"version\"\n          class=\"ml-2\"\n        >\n          <span class=\"font-medium\">\n            {{\n              t('loadWorkflowWarning.coreNodesFromVersion', {\n                version: version || t('loadWorkflowWarning.unknownVersion')\n              })\n            }}\n          </span>\n          <span class=\"ml-1\">{{ getUniqueNodeNames(nodes).join(', ') }}</span>\n        </div>\n      </div>\n    </div>\n    <!-- Manager disabled hint: shown on OSS when manager is not active -->\n    <i18n-t\n      v-if=\"showManagerHint\"\n      keypath=\"rightSidePanel.missingNodePacks.ossManagerDisabledHint\"\n      tag=\"p\"\n      class=\"m-0 pb-5 text-sm/relaxed text-muted-foreground\"\n    >\n      <template #pipCmd>\n        <code\n          class=\"rounded-sm bg-comfy-menu-bg px-1 py-0.5 font-mono text-xs text-comfy-input-foreground\"\n          >pip install -U --pre comfyui-manager</code\n        >\n      </template>\n      <template #flag>\n        <code\n          class=\"rounded-sm bg-comfy-menu-bg px-1 py-0.5 font-mono text-xs text-comfy-input-foreground\"\n          >--enable-manager</code\n        >\n      </template>\n    </i18n-t>\n    <div class=\"-mx-1.5 flex flex-col gap-1 overflow-hidden px-1.5\">\n      <MissingPackGroupRow\n        v-for=\"group in missingPackGroups\"\n        :key=\"group.packId ?? '__unknown__'\"\n        :group=\"group\"\n        :show-info-button=\"showInfoButton\"\n        :highlighted=\"\n          someNodeTypeInSelection(group.nodeTypes, highlightedNodeIds)\n        \"\n        @locate-node=\"emit('locateNode', $event)\"\n        @open-manager-info=\"emit('openManagerInfo', $event)\"\n      />\n    </div>\n  </div>\n\n  <!-- Apply Changes: shown when manager enabled and at least one pack install succeeded -->\n  <div v-if=\"shouldShowManagerButtons\" class=\"px-4\">\n    <Button\n      v-if=\"hasInstalledPacksPendingRestart\"\n      variant=\"secondary\"\n      size=\"sm\"\n      :disabled=\"isRestarting\"\n      class=\"mt-2 h-8 w-full min-w-0 rounded-md text-xs\"\n      @click=\"applyChanges()\"\n    >\n      <DotSpinner v-if=\"isRestarting\" duration=\"1s\" :size=\"12\" />\n      <i\n        v-else\n        aria-hidden=\"true\"\n        class=\"icon-[lucide--refresh-cw] size-4 shrink-0\"\n      />\n      <span class=\"min-w-0 truncate\">{{\n        t('rightSidePanel.missingNodePacks.applyChanges')\n      }}</span>\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { compare, valid } from 'semver'\nimport Button from '@/components/ui/button/Button.vue'\nimport DotSpinner from '@/components/common/DotSpinner.vue'\nimport { useApplyChanges } from '@/workbench/extensions/manager/composables/useApplyChanges'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useManagerState } from '@/workbench/extensions/manager/composables/useManagerState'\nimport { useMissingNodes } from '@/workbench/extensions/manager/composables/nodePack/useMissingNodes'\nimport { useSystemStatsStore } from '@/stores/systemStatsStore'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { MissingPackGroup } from '@/components/rightSidePanel/errors/useErrorGroups'\nimport MissingPackGroupRow from '@/components/rightSidePanel/errors/MissingPackGroupRow.vue'\nimport { someNodeTypeInSelection } from '@/components/rightSidePanel/errors/selectionEmphasis'\n\nconst { showInfoButton, missingPackGroups } = defineProps<{\n  showInfoButton: boolean\n  missingPackGroups: MissingPackGroup[]\n  /** Execution node ids to emphasize (current canvas selection). */\n  highlightedNodeIds?: Set<string>\n}>()\n\nconst emit = defineEmits<{\n  locateNode: [nodeId: string]\n  openManagerInfo: [packId: string]\n}>()\n\nconst { t } = useI18n()\n\nconst { missingCoreNodes } = useMissingNodes()\nconst systemStatsStore = useSystemStatsStore()\n\nconst hasMissingCoreNodes = computed(\n  () => Object.keys(missingCoreNodes.value).length > 0\n)\n\nconst currentComfyUIVersion = computed<string | null>(() => {\n  if (!hasMissingCoreNodes.value) return null\n  return systemStatsStore.systemStats?.system?.comfyui_version ?? null\n})\n\nconst sortedMissingCoreNodes = computed(() =>\n  Object.entries(missingCoreNodes.value).sort(([a], [b]) => {\n    const aValid = valid(a)\n    const bValid = valid(b)\n    if (!aValid && !bValid) return 0\n    if (!aValid) return 1\n    if (!bValid) return -1\n    return compare(b, a)\n  })\n)\n\nfunction getUniqueNodeNames(nodes: LGraphNode[]): string[] {\n  const types = new Set(nodes.map((node) => node.type).filter(Boolean))\n  return [...types].sort()\n}\n\nconst comfyManagerStore = useComfyManagerStore()\nconst { isRestarting, applyChanges } = useApplyChanges()\nconst { shouldShowManagerButtons } = useManagerState()\n\n/**\n * Show the --enable-manager hint when:\n * - Not on Cloud (OSS/local only)\n * - Manager is disabled (showInfoButton is false)\n */\nconst showManagerHint = computed(() => !isCloud && !showInfoButton)\n\n/**\n * Show Apply Changes when any pack from the error group is already installed\n * on disk but ComfyUI hasn't restarted yet to load it.\n * This is server-state based → persists across browser refreshes.\n */\nconst hasInstalledPacksPendingRestart = computed(() =>\n  missingPackGroups.some(\n    (g) => g.packId !== null && comfyManagerStore.isPackInstalled(g.packId)\n  )\n)\n</script>\n","<template>\n  <div class=\"mb-1 flex w-full flex-col gap-0.5 last:mb-0\">\n    <div\n      :aria-current=\"highlighted ? 'true' : undefined\"\n      :class=\"\n        cn(\n          'flex min-h-8 items-center gap-1',\n          selectionEmphasisClass(highlighted)\n        )\n      \"\n    >\n      <Button\n        v-if=\"hasMultipleNodeTypes\"\n        data-testid=\"swap-node-group-expand\"\n        variant=\"textonly\"\n        size=\"unset\"\n        :aria-label=\"\n          expanded\n            ? t('rightSidePanel.missingNodePacks.collapse', 'Collapse')\n            : t('rightSidePanel.missingNodePacks.expand', 'Expand')\n        \"\n        :aria-expanded=\"expanded\"\n        class=\"h-8 w-4 shrink-0 p-0 hover:bg-transparent focus-visible:ring-inset\"\n        @click=\"toggleExpand\"\n      >\n        <i\n          aria-hidden=\"true\"\n          :class=\"\n            cn(\n              'icon-[lucide--chevron-right] size-4 text-muted-foreground transition-transform duration-200',\n              expanded && 'rotate-90'\n            )\n          \"\n        />\n      </Button>\n\n      <span class=\"flex min-w-0 flex-1 flex-col gap-0\">\n        <span class=\"flex min-w-0 items-center gap-2\">\n          <span class=\"flex min-w-0 items-center gap-2.5\">\n            <button\n              v-if=\"hasMultipleNodeTypes\"\n              type=\"button\"\n              class=\"m-0 inline max-w-full cursor-pointer appearance-none rounded-sm border-0 bg-transparent p-0 text-left text-xs/relaxed font-normal wrap-break-word text-base-foreground outline-none hover:text-base-foreground focus:outline-none focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none focus-visible:ring-inset\"\n              :title=\"group.type\"\n              :aria-label=\"titleToggleAriaLabel\"\n              :aria-expanded=\"expanded\"\n              @click=\"toggleExpand\"\n            >\n              {{ group.type }}\n            </button>\n            <button\n              v-else-if=\"primaryLocatableNodeType\"\n              type=\"button\"\n              class=\"m-0 inline max-w-full cursor-pointer appearance-none rounded-sm border-0 bg-transparent p-0 text-left text-xs/relaxed font-normal wrap-break-word text-base-foreground outline-none hover:text-base-foreground focus:outline-none focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none focus-visible:ring-inset\"\n              :title=\"group.type\"\n              @click=\"handleLocateNode(primaryLocatableNodeType)\"\n            >\n              {{ group.type }}\n            </button>\n            <span\n              v-else\n              class=\"min-w-0 truncate text-xs/relaxed font-normal text-base-foreground\"\n              :title=\"group.type\"\n            >\n              {{ group.type }}\n            </span>\n            <span\n              v-if=\"hasMultipleNodeTypes\"\n              data-testid=\"swap-node-group-count\"\n              role=\"img\"\n              class=\"flex h-4 min-w-4 shrink-0 items-center justify-center rounded-sm bg-secondary-background-hover px-1 text-2xs font-semibold text-base-foreground\"\n              :aria-label=\"t('g.nodesCount', group.nodeTypes.length)\"\n            >\n              {{ group.nodeTypes.length }}\n            </span>\n          </span>\n        </span>\n        <span class=\"min-w-0 text-xs/relaxed text-muted-foreground\">\n          {{\n            t(\n              'nodeReplacement.willBeReplacedBy',\n              'This node will be replaced by:'\n            )\n          }}\n          <span\n            class=\"inline-flex rounded-sm bg-modal-card-tag-background px-1.5 py-0.5 text-xs/none font-medium text-modal-card-tag-foreground\"\n          >\n            {{ replacementLabel }}\n          </span>\n        </span>\n      </span>\n\n      <Button\n        variant=\"secondary\"\n        size=\"sm\"\n        class=\"shrink-0 focus-visible:ring-inset\"\n        @click=\"handleReplaceNode\"\n      >\n        <i\n          aria-hidden=\"true\"\n          class=\"mr-1 icon-[lucide--repeat] size-4 shrink-0 text-base-foreground\"\n        />\n        <span class=\"min-w-0 truncate text-base-foreground\">\n          {{ t('nodeReplacement.replaceNode', 'Replace Node') }}\n        </span>\n      </Button>\n\n      <Button\n        v-if=\"primaryLocatableNodeType\"\n        variant=\"textonly\"\n        size=\"icon-sm\"\n        class=\"size-8 shrink-0 text-muted-foreground hover:text-base-foreground focus-visible:ring-inset\"\n        :aria-label=\"locateNodeLabel\"\n        @click=\"handleLocateNode(primaryLocatableNodeType)\"\n      >\n        <i aria-hidden=\"true\" class=\"icon-[lucide--locate] size-4\" />\n      </Button>\n    </div>\n\n    <TransitionCollapse>\n      <ul v-if=\"expanded\" class=\"m-0 list-none space-y-1 p-0 pl-5\">\n        <li\n          v-for=\"(nodeType, index) in group.nodeTypes\"\n          :key=\"getKey(nodeType, index)\"\n          class=\"min-w-0\"\n        >\n          <div class=\"flex min-w-0 items-center gap-2\">\n            <span class=\"flex min-w-0 flex-1 items-center gap-1\">\n              <button\n                v-if=\"isLocatableNodeType(nodeType)\"\n                type=\"button\"\n                class=\"m-0 inline max-w-full cursor-pointer appearance-none rounded-sm border-0 bg-transparent p-0 text-left text-xs/relaxed font-normal wrap-break-word text-muted-foreground outline-none hover:text-base-foreground focus:outline-none focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none focus-visible:ring-inset\"\n                @click=\"handleLocateNode(nodeType)\"\n              >\n                {{ getLabel(nodeType) }}\n              </button>\n              <span\n                v-else\n                class=\"text-xs/relaxed wrap-break-word text-muted-foreground\"\n              >\n                {{ getLabel(nodeType) }}\n              </span>\n            </span>\n            <Button\n              v-if=\"isLocatableNodeType(nodeType)\"\n              variant=\"textonly\"\n              size=\"icon-sm\"\n              class=\"size-8 shrink-0 text-muted-foreground hover:text-base-foreground focus-visible:ring-inset\"\n              :aria-label=\"locateNodeLabel\"\n              @click=\"handleLocateNode(nodeType)\"\n            >\n              <i aria-hidden=\"true\" class=\"icon-[lucide--locate] size-4\" />\n            </Button>\n          </div>\n        </li>\n      </ul>\n    </TransitionCollapse>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { selectionEmphasisClass } from '@/components/rightSidePanel/errors/selectionEmphasis'\nimport { useI18n } from 'vue-i18n'\nimport Button from '@/components/ui/button/Button.vue'\nimport TransitionCollapse from '@/components/rightSidePanel/layout/TransitionCollapse.vue'\nimport type { MissingNodeType } from '@/platform/nodeReplacement/types'\nimport type { SwapNodeGroup } from '@/components/rightSidePanel/errors/useErrorGroups'\n\nconst { group, highlighted } = defineProps<{\n  group: SwapNodeGroup\n  /** Emphasize the header row (group containing the canvas selection). */\n  highlighted?: boolean\n}>()\n\nconst emit = defineEmits<{\n  'locate-node': [nodeId: string]\n  replace: [group: SwapNodeGroup]\n}>()\n\nconst { t } = useI18n()\n\nconst expanded = ref(false)\nconst hasMultipleNodeTypes = computed(() => group.nodeTypes.length > 1)\nconst replacementLabel = computed(\n  () => group.newNodeId ?? t('nodeReplacement.unknownNode', 'Unknown')\n)\nconst locateNodeLabel = computed(() =>\n  t('rightSidePanel.locateNode', 'Locate node on canvas')\n)\nconst titleToggleAriaLabel = computed(\n  () =>\n    `${\n      expanded.value\n        ? t('rightSidePanel.missingNodePacks.collapse', 'Collapse')\n        : t('rightSidePanel.missingNodePacks.expand', 'Expand')\n    } ${group.type}`\n)\nconst primaryLocatableNodeType = computed(() => {\n  if (group.nodeTypes.length !== 1) return null\n  const [nodeType] = group.nodeTypes\n  return isLocatableNodeType(nodeType) ? nodeType : null\n})\n\nfunction toggleExpand() {\n  expanded.value = !expanded.value\n}\n\nfunction getKey(nodeType: MissingNodeType, index: number): string {\n  if (typeof nodeType === 'string') return `${nodeType}-${index}`\n  return nodeType.nodeId != null\n    ? String(nodeType.nodeId)\n    : `${nodeType.type}-${index}`\n}\n\nfunction getLabel(nodeType: MissingNodeType): string {\n  return typeof nodeType === 'string' ? nodeType : nodeType.type\n}\n\nfunction isLocatableNodeType(\n  nodeType: MissingNodeType\n): nodeType is Exclude<MissingNodeType, string> & { nodeId: string | number } {\n  return typeof nodeType !== 'string' && nodeType.nodeId != null\n}\n\nfunction handleLocateNode(nodeType: MissingNodeType) {\n  if (!isLocatableNodeType(nodeType)) return\n  emit('locate-node', String(nodeType.nodeId))\n}\n\nfunction handleReplaceNode() {\n  emit('replace', group)\n}\n</script>\n","<template>\n  <div class=\"px-3\">\n    <SwapNodeGroupRow\n      v-for=\"group in swapNodeGroups\"\n      :key=\"group.type\"\n      :group=\"group\"\n      :highlighted=\"\n        someNodeTypeInSelection(group.nodeTypes, highlightedNodeIds)\n      \"\n      @locate-node=\"emit('locate-node', $event)\"\n      @replace=\"emit('replace', $event)\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { someNodeTypeInSelection } from '@/components/rightSidePanel/errors/selectionEmphasis'\nimport type { SwapNodeGroup } from '@/components/rightSidePanel/errors/useErrorGroups'\nimport SwapNodeGroupRow from '@/platform/nodeReplacement/components/SwapNodeGroupRow.vue'\n\nconst { swapNodeGroups } = defineProps<{\n  swapNodeGroups: SwapNodeGroup[]\n  /** Execution node ids to emphasize (current canvas selection). */\n  highlightedNodeIds?: Set<string>\n}>()\n\nconst emit = defineEmits<{\n  'locate-node': [nodeId: string]\n  replace: [group: SwapNodeGroup]\n}>()\n</script>\n","import { resolveNodeDisplayName } from '@/utils/nodeTitleUtil'\nimport type { UploadModelSuccess } from '@/platform/assets/composables/useUploadModelWizard'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { useAssetDownloadStore } from '@/stores/assetDownloadStore'\nimport { useModelToNodeStore } from '@/stores/modelToNodeStore'\nimport { app } from '@/scripts/app'\nimport { getNodeByExecutionId } from '@/utils/graphTraversalUtil'\nimport type { MissingModelViewModel } from '@/platform/missingModel/types'\n\nexport function getModelStateKey(\n  modelName: string,\n  directory: string | null,\n  isAssetSupported: boolean\n): string {\n  const prefix = isAssetSupported ? 'supported' : 'unsupported'\n  return `${prefix}::${directory ?? ''}::${modelName}`\n}\n\nexport function getNodeDisplayLabel(\n  nodeId: string | number,\n  fallback: string\n): string {\n  const graph = app.rootGraphOrUndefined\n  if (!graph) return fallback\n  const node = getNodeByExecutionId(graph, String(nodeId))\n  return resolveNodeDisplayName(node, {\n    emptyLabel: fallback,\n    untitledLabel: fallback\n  })\n}\n\nexport function useMissingModelInteractions() {\n  const store = useMissingModelStore()\n  const assetsStore = useAssetsStore()\n  const assetDownloadStore = useAssetDownloadStore()\n  const modelToNodeStore = useModelToNodeStore()\n\n  function toggleModelExpand(key: string) {\n    store.modelExpandState[key] = !isModelExpanded(key)\n  }\n\n  function isModelExpanded(key: string): boolean {\n    return store.modelExpandState[key] ?? false\n  }\n\n  /** Apply selected model to referencing nodes, removing only that model from the error list. */\n  function confirmLibrarySelect(\n    key: string,\n    modelName: string,\n    referencingNodes: MissingModelViewModel['referencingNodes'],\n    directory: string | null\n  ) {\n    const value = store.selectedLibraryModel[key]\n    if (!value) return\n\n    const graph = app.rootGraphOrUndefined\n    if (!graph) return\n\n    if (directory) {\n      const providers = modelToNodeStore.getAllNodeProviders(directory)\n      void Promise.allSettled(\n        providers.map((provider) =>\n          assetsStore.updateModelsForNodeType(provider.nodeDef.name)\n        )\n      ).then((results) => {\n        for (const r of results) {\n          if (r.status === 'rejected') {\n            console.warn(\n              '[Missing Model] Failed to refresh model cache:',\n              r.reason\n            )\n          }\n        }\n      })\n    }\n\n    for (const ref of referencingNodes) {\n      const node = getNodeByExecutionId(graph, String(ref.nodeId))\n      if (node) {\n        const widget = node.widgets?.find((w) => w.name === ref.widgetName)\n        if (widget) {\n          widget.value = value\n          widget.callback?.(value)\n        }\n        node.graph?.setDirtyCanvas(true, true)\n      }\n    }\n\n    delete store.selectedLibraryModel[key]\n    delete store.importTaskIds[key]\n    const nodeIdSet = new Set(referencingNodes.map((ref) => String(ref.nodeId)))\n    store.removeMissingModelByNameOnNodes(modelName, nodeIdSet)\n  }\n\n  function getDownloadStatus(key: string) {\n    const taskId = store.importTaskIds[key]\n    if (!taskId) return null\n    return (\n      assetDownloadStore.downloadList.find((d) => d.taskId === taskId) ?? null\n    )\n  }\n\n  function handleAsyncPending(\n    key: string,\n    taskId: string,\n    modelType: string | undefined,\n    filename: string\n  ) {\n    store.importTaskIds[key] = taskId\n    if (modelType) {\n      assetDownloadStore.trackDownload(taskId, modelType, filename)\n    }\n  }\n\n  function handleAsyncCompleted(modelType: string | undefined) {\n    if (modelType) {\n      assetsStore.invalidateModelsForCategory(modelType)\n      void assetsStore.updateModelsForTag(modelType)\n    }\n  }\n\n  function handleUploadedModelImport(key: string, result: UploadModelSuccess) {\n    if (result.taskId) {\n      handleAsyncPending(key, result.taskId, result.modelType, result.filename)\n    } else if (result.status === 'success') {\n      handleAsyncCompleted(result.modelType)\n    }\n\n    store.selectedLibraryModel[key] = result.filename\n  }\n\n  return {\n    toggleModelExpand,\n    isModelExpanded,\n    confirmLibrarySelect,\n    getDownloadStatus,\n    handleUploadedModelImport\n  }\n}\n","import {\n  downloadModel,\n  isTrustedHuggingFaceUrl,\n  openGatedRepoPage\n} from '@/platform/missingModel/missingModelDownload'\nimport type { ModelWithUrl } from '@/platform/missingModel/missingModelDownload'\nimport { fetchAndStoreModelMetadata } from '@/platform/missingModel/missingModelMetadata'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\n\nexport function useMissingModelDownload() {\n  const store = useMissingModelStore()\n\n  function fileSizeFor(url: string): number | undefined {\n    return store.fileSizes[url]\n  }\n\n  function gatedRepoUrlFor(url: string): string | undefined {\n    return store.gatedRepoUrls[url]\n  }\n\n  async function prefetchModelMetadata(url: string): Promise<void> {\n    if (fileSizeFor(url) !== undefined || gatedRepoUrlFor(url)) return\n\n    await fetchAndStoreModelMetadata(url, store)\n  }\n\n  function downloadMissingModel(model: ModelWithUrl): void {\n    downloadModel(model, store.folderPaths)\n  }\n\n  // Always try the bridge: it opens in the user's Electron session. isRemote()\n  // describes the backend server, not the user, so it must not gate this. The\n  // anchor fallback inside Electron hits shell.openExternal and strands the\n  // provider cookies in the system browser.\n  async function openModelAccessPage(repoUrl: string): Promise<void> {\n    if (!isTrustedHuggingFaceUrl(repoUrl)) {\n      console.warn('[missingModelDownload] Blocked untrusted access URL')\n      return\n    }\n\n    const bridge = window.__comfyDesktop2\n    if (bridge?.openModelAccessPage) {\n      try {\n        if (await bridge.openModelAccessPage(repoUrl)) return\n      } catch (error: unknown) {\n        console.error('Failed to open model access page in Desktop:', error)\n      }\n    }\n\n    openGatedRepoPage(repoUrl)\n  }\n\n  return {\n    fileSizeFor,\n    gatedRepoUrlFor,\n    prefetchModelMetadata,\n    downloadMissingModel,\n    openModelAccessPage\n  }\n}\n","<template>\n  <div class=\"mb-1 flex w-full flex-col gap-0.5 last:mb-0\">\n    <div\n      :aria-current=\"highlighted ? 'true' : undefined\"\n      :class=\"\n        cn(\n          'flex min-h-8 items-center gap-1',\n          selectionEmphasisClass(highlighted)\n        )\n      \"\n    >\n      <Button\n        v-if=\"hasMultipleReferences\"\n        data-testid=\"missing-model-expand\"\n        variant=\"textonly\"\n        size=\"unset\"\n        :aria-label=\"\n          expanded\n            ? t('rightSidePanel.missingModels.collapseNodes')\n            : t('rightSidePanel.missingModels.expandNodes')\n        \"\n        :aria-expanded=\"expanded\"\n        class=\"h-8 w-4 shrink-0 p-0 hover:bg-transparent focus-visible:ring-inset\"\n        @click=\"handleToggleExpand\"\n      >\n        <i\n          aria-hidden=\"true\"\n          :class=\"\n            cn(\n              'icon-[lucide--chevron-right] size-4 text-muted-foreground transition-transform duration-200',\n              expanded && 'rotate-90'\n            )\n          \"\n        />\n      </Button>\n\n      <span class=\"flex min-w-0 flex-1 flex-col gap-0\">\n        <span class=\"flex min-w-0 items-center gap-1 text-xs/tight\">\n          <button\n            v-if=\"hasModelLabelControl\"\n            ref=\"modelLabelControl\"\n            type=\"button\"\n            class=\"m-0 min-w-0 cursor-pointer appearance-none rounded-sm border-0 bg-transparent p-0 text-left font-normal wrap-break-word text-base-foreground outline-none hover:text-base-foreground focus:outline-none focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none focus-visible:ring-inset\"\n            :title=\"displayModelName\"\n            @click=\"handleModelLabelClick\"\n          >\n            {{ displayModelName }}\n          </button>\n          <span\n            v-else\n            class=\"min-w-0 font-normal wrap-break-word text-base-foreground\"\n            :title=\"displayModelName\"\n          >\n            {{ displayModelName }}\n          </span>\n          <span\n            v-if=\"hasMultipleReferences\"\n            data-testid=\"missing-model-reference-count\"\n            class=\"inline-flex h-4 min-w-4 shrink-0 items-center justify-center rounded-sm bg-secondary-background-hover px-1 text-2xs font-semibold text-base-foreground\"\n          >\n            {{ model.referencingNodes.length }}\n          </span>\n          <Button\n            variant=\"textonly\"\n            size=\"icon-sm\"\n            class=\"size-6 shrink-0 text-muted-foreground hover:bg-transparent hover:text-base-foreground focus-visible:ring-inset\"\n            :aria-label=\"linkLabel\"\n            :title=\"linkLabel\"\n            @click=\"copyModelLink\"\n          >\n            <i aria-hidden=\"true\" class=\"icon-[lucide--link] size-4\" />\n          </Button>\n        </span>\n        <span\n          v-if=\"modelMetadataLabel\"\n          class=\"block text-2xs/tight\"\n          :class=\"\n            isUnknownCategory\n              ? 'text-warning-background'\n              : 'text-muted-foreground'\n          \"\n        >\n          {{ modelMetadataLabel }}\n        </span>\n      </span>\n\n      <template v-if=\"isCloud && canCloudImport\">\n        <Button\n          v-if=\"!isCloudImportDownloadActive\"\n          data-testid=\"missing-model-import\"\n          variant=\"secondary\"\n          size=\"sm\"\n          class=\"shrink-0 focus-visible:ring-inset\"\n          @click=\"showUploadDialog\"\n        >\n          {{ t('g.import') }}\n        </Button>\n        <div\n          v-else\n          ref=\"cloudProgress\"\n          role=\"progressbar\"\n          :aria-label=\"t('rightSidePanel.missingModels.importing')\"\n          :aria-valuenow=\"cloudImportProgressPercent\"\n          aria-valuemin=\"0\"\n          aria-valuemax=\"100\"\n          tabindex=\"-1\"\n          class=\"flex h-8 w-16 shrink-0 items-center\"\n        >\n          <span\n            class=\"block h-1.5 w-full overflow-hidden rounded-full bg-secondary-background-selected\"\n          >\n            <span\n              class=\"block h-full rounded-full bg-primary-background transition-all duration-200 ease-linear\"\n              :style=\"{ width: `${cloudImportProgressPercent}%` }\"\n            />\n          </span>\n        </div>\n        <span\n          v-if=\"isCloudImportDownloadActive\"\n          role=\"status\"\n          aria-live=\"polite\"\n          class=\"sr-only\"\n        >\n          {{ t('rightSidePanel.missingModels.importing') }}\n        </span>\n      </template>\n\n      <template v-else>\n        <Button\n          v-if=\"showGatedRepoAction\"\n          :tooltip=\"t('rightSidePanel.missingModels.gatedModelTooltip')\"\n          :as=\"usesNativeModelAccess ? 'button' : 'a'\"\n          :type=\"usesNativeModelAccess ? 'button' : undefined\"\n          :href=\"usesNativeModelAccess ? undefined : gatedRepoUrl\"\n          :target=\"usesNativeModelAccess ? undefined : '_blank'\"\n          :rel=\"usesNativeModelAccess ? undefined : 'noopener noreferrer'\"\n          data-testid=\"missing-model-gated-access\"\n          variant=\"muted-textonly\"\n          size=\"icon\"\n          class=\"size-8 shrink-0 text-warning-background hover:text-warning-background focus-visible:ring-inset\"\n          :aria-label=\"\n            t(\n              usesNativeModelAccess\n                ? 'rightSidePanel.missingModels.openHuggingFaceRepoDesktop'\n                : 'rightSidePanel.missingModels.openHuggingFaceRepoNewTab',\n              { model: model.name },\n              { escapeParameter: false }\n            )\n          \"\n          @click=\"handleOpenGatedRepo\"\n        >\n          <i aria-hidden=\"true\" class=\"icon-[lucide--lock] size-4\" />\n        </Button>\n        <Button\n          v-if=\"showDownloadAction\"\n          data-testid=\"missing-model-download\"\n          variant=\"secondary\"\n          size=\"sm\"\n          class=\"shrink-0 focus-visible:ring-inset\"\n          :aria-label=\"\n            t(\n              'rightSidePanel.missingModels.downloadModel',\n              { model: model.name },\n              { escapeParameter: false }\n            )\n          \"\n          :aria-describedby=\"\n            showGatedRepoAction ? gatedDownloadDescriptionId : undefined\n          \"\n          @click=\"handleDownload\"\n        >\n          {{ t('g.download') }}\n        </Button>\n        <span\n          v-if=\"showGatedRepoAction\"\n          :id=\"gatedDownloadDescriptionId\"\n          hidden\n        >\n          {{ t('rightSidePanel.missingModels.gatedModelDownloadTooltip') }}\n        </span>\n      </template>\n\n      <Button\n        v-if=\"!hasMultipleReferences && !isUnknownCategory && primaryReference\"\n        data-testid=\"missing-model-locate\"\n        variant=\"textonly\"\n        size=\"icon-sm\"\n        :aria-label=\"t('rightSidePanel.missingModels.locateNode')\"\n        class=\"size-8 shrink-0 text-muted-foreground hover:text-base-foreground focus-visible:ring-inset\"\n        @click=\"handleLocatePrimary\"\n      >\n        <i aria-hidden=\"true\" class=\"icon-[lucide--locate] size-4\" />\n      </Button>\n    </div>\n\n    <TransitionCollapse>\n      <ul\n        v-if=\"showReferenceList\"\n        :class=\"\n          cn(\n            'm-0 list-none p-0',\n            (hasMultipleReferences || isUnknownCategory) && 'pl-5'\n          )\n        \"\n      >\n        <li\n          v-for=\"ref in model.referencingNodes\"\n          :key=\"`${String(ref.nodeId)}::${ref.widgetName}`\"\n          class=\"min-w-0\"\n        >\n          <div class=\"flex min-h-8 min-w-0 items-center gap-2\">\n            <button\n              type=\"button\"\n              class=\"m-0 inline max-w-full cursor-pointer appearance-none rounded-sm border-0 bg-transparent p-0 text-left text-xs/tight font-normal wrap-break-word text-muted-foreground outline-none hover:text-base-foreground focus:outline-none focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none focus-visible:ring-inset\"\n              @click=\"emit('locateModel', String(ref.nodeId))\"\n            >\n              {{\n                getNodeDisplayLabel(ref.nodeId, model.representative.nodeType)\n              }}\n            </button>\n            <Button\n              data-testid=\"missing-model-locate\"\n              variant=\"textonly\"\n              size=\"icon-sm\"\n              :aria-label=\"t('rightSidePanel.missingModels.locateNode')\"\n              class=\"ml-auto size-8 shrink-0 text-muted-foreground hover:text-base-foreground focus-visible:ring-inset\"\n              @click=\"emit('locateModel', String(ref.nodeId))\"\n            >\n              <i aria-hidden=\"true\" class=\"icon-[lucide--locate] size-4\" />\n            </Button>\n          </div>\n        </li>\n      </ul>\n    </TransitionCollapse>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport {\n  computed,\n  nextTick,\n  onMounted,\n  useId,\n  useTemplateRef,\n  watch\n} from 'vue'\nimport { storeToRefs } from 'pinia'\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { selectionEmphasisClass } from '@/components/rightSidePanel/errors/selectionEmphasis'\nimport Button from '@/components/ui/button/Button.vue'\nimport TransitionCollapse from '@/components/rightSidePanel/layout/TransitionCollapse.vue'\nimport type { MissingModelViewModel } from '@/platform/missingModel/types'\nimport type { UploadModelDialogContext } from '@/platform/assets/composables/useUploadModelWizard'\n\nimport { useModelUpload } from '@/platform/assets/composables/useModelUpload'\nimport {\n  useMissingModelInteractions,\n  getModelStateKey,\n  getNodeDisplayLabel\n} from '@/platform/missingModel/composables/useMissingModelInteractions'\nimport { useMissingModelDownload } from '@/platform/missingModel/composables/useMissingModelDownload'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { isCloud } from '@/platform/distribution/types'\nimport {\n  isModelDownloadable,\n  isTrustedHuggingFaceUrl,\n  toBrowsableUrl\n} from '@/platform/missingModel/missingModelDownload'\nimport { formatSize } from '@/utils/formatUtil'\n\nconst {\n  model,\n  directory,\n  isAssetSupported,\n  canCloudImport = true,\n  highlighted\n} = defineProps<{\n  model: MissingModelViewModel\n  directory: string | null\n  isAssetSupported: boolean\n  canCloudImport?: boolean\n  /** Emphasize the header row (model referenced by the canvas selection). */\n  highlighted?: boolean\n}>()\n\nconst emit = defineEmits<{\n  locateModel: [nodeId: string]\n}>()\n\nconst { t } = useI18n()\nconst { copyToClipboard } = useCopyToClipboard()\n\nconst modelKey = computed(() =>\n  getModelStateKey(model.name, directory, isAssetSupported)\n)\n\nconst downloadStatus = computed(() => getDownloadStatus(modelKey.value))\nconst isUnknownCategory = computed(() => directory === null)\nconst isDownloadActive = computed(\n  () =>\n    downloadStatus.value?.status === 'running' ||\n    downloadStatus.value?.status === 'created'\n)\nconst isCloudImportDownloadActive = computed(\n  () => isCloud && canCloudImport && isDownloadActive.value\n)\nconst cloudImportProgressPercent = computed(() =>\n  Math.round((downloadStatus.value?.progress ?? 0) * 100)\n)\nconst hasMultipleReferences = computed(() => model.referencingNodes.length > 1)\nconst primaryReference = computed(() => model.referencingNodes[0])\nconst hasModelLabelControl = computed(\n  () =>\n    hasMultipleReferences.value ||\n    (!isUnknownCategory.value && !!primaryReference.value)\n)\nconst linkLabel = computed(() =>\n  model.representative.url\n    ? t('rightSidePanel.missingModels.copyUrl')\n    : t('rightSidePanel.missingModels.copyModelName')\n)\n\nconst store = useMissingModelStore()\nconst { selectedLibraryModel } = storeToRefs(store)\nconst cloudProgress = useTemplateRef<HTMLElement>('cloudProgress')\nconst modelLabelControl = useTemplateRef<HTMLButtonElement>('modelLabelControl')\nconst {\n  fileSizeFor,\n  gatedRepoUrlFor,\n  prefetchModelMetadata,\n  downloadMissingModel,\n  openModelAccessPage\n} = useMissingModelDownload()\n\nconst expanded = computed(\n  () =>\n    store.modelExpandState[modelKey.value] ??\n    (isUnknownCategory.value && hasMultipleReferences.value)\n)\nconst showReferenceList = computed(\n  () =>\n    (isUnknownCategory.value && model.referencingNodes.length === 1) ||\n    (hasMultipleReferences.value && expanded.value)\n)\n\nconst displayModelName = computed(() => {\n  if (!isCloudImportDownloadActive.value) return model.name\n\n  return (\n    downloadStatus.value?.assetName ??\n    selectedLibraryModel.value[modelKey.value] ??\n    model.name\n  )\n})\n\nconst downloadable = computed(() => {\n  const rep = model.representative\n  return !!(\n    rep.url &&\n    rep.directory &&\n    isModelDownloadable({\n      name: rep.name,\n      url: rep.url,\n      directory: rep.directory\n    })\n  )\n})\n\nconst showDownloadAction = computed(() => !isCloud && downloadable.value)\nconst gatedRepoUrl = computed(() => {\n  const url = model.representative.url\n  const repoUrl = url ? gatedRepoUrlFor(url) : undefined\n  return repoUrl && isTrustedHuggingFaceUrl(repoUrl) ? repoUrl : undefined\n})\nconst showGatedRepoAction = computed(\n  () => showDownloadAction.value && !!gatedRepoUrl.value\n)\nconst usesNativeModelAccess = !!window.__comfyDesktop2?.openModelAccessPage\nconst gatedDownloadDescriptionId = useId()\n\nconst downloadSizeLabel = computed(() => {\n  if (!showDownloadAction.value) return undefined\n\n  const url = model.representative.url\n  const size = url ? fileSizeFor(url) : undefined\n  return size ? formatSize(size) : undefined\n})\nconst modelTypeLabel = computed(\n  () => directory ?? t('rightSidePanel.missingModels.unknownCategory')\n)\nconst modelMetadataLabel = computed(() =>\n  [modelTypeLabel.value, downloadSizeLabel.value].filter(Boolean).join(' · ')\n)\n\nconst missingModelUploadContext = computed<\n  UploadModelDialogContext | undefined\n>(() => {\n  if (!canCloudImport || !directory) return undefined\n\n  return {\n    kind: 'missing-model-resolution',\n    missingModelName: model.name,\n    requiredModelType: directory,\n    replacementTargets: model.referencingNodes.map((ref) => ({\n      nodeId: String(ref.nodeId),\n      nodeLabel: getNodeDisplayLabel(ref.nodeId, model.representative.nodeType),\n      widgetName: ref.widgetName\n    }))\n  }\n})\n\nconst { showUploadDialog } = useModelUpload(\n  (result) => {\n    handleUploadedModelImport(modelKey.value, result)\n\n    if (result.status === 'success') {\n      handleLibrarySelect()\n    }\n  },\n  () => missingModelUploadContext.value\n)\n\nonMounted(() => {\n  if (isCloud) return\n\n  const url = model.representative.url\n  if (url && downloadable.value) {\n    void prefetchModelMetadata(url)\n  }\n})\n\nfunction handleDownload() {\n  const rep = model.representative\n  if (rep.url && rep.directory) {\n    downloadMissingModel({\n      name: rep.name,\n      url: rep.url,\n      directory: rep.directory\n    })\n  } else {\n    console.warn('[MissingModelRow] Cannot download: missing url or directory')\n  }\n}\n\nfunction handleOpenGatedRepo() {\n  if (!usesNativeModelAccess) return\n\n  const repoUrl = gatedRepoUrl.value\n  if (repoUrl) void openModelAccessPage(repoUrl)\n}\n\nfunction handleLocatePrimary() {\n  const ref = primaryReference.value\n  if (ref) emit('locateModel', String(ref.nodeId))\n}\n\nfunction copyModelLink() {\n  const url = model.representative.url\n  copyToClipboard(url ? toBrowsableUrl(url) : model.name)\n}\n\nconst { confirmLibrarySelect, getDownloadStatus, handleUploadedModelImport } =\n  useMissingModelInteractions()\n\nfunction handleToggleExpand() {\n  store.modelExpandState[modelKey.value] = !expanded.value\n}\n\nfunction handleModelLabelClick() {\n  if (hasMultipleReferences.value) {\n    handleToggleExpand()\n    return\n  }\n\n  handleLocatePrimary()\n}\n\nwatch(\n  () => downloadStatus.value?.status,\n  (status) => {\n    if (!isCloud || status !== 'completed') return\n    const completedAssetName = downloadStatus.value?.assetName\n    if (completedAssetName) {\n      selectedLibraryModel.value[modelKey.value] = completedAssetName\n    }\n    handleLibrarySelect()\n  },\n  { immediate: true }\n)\n\nwatch(isCloudImportDownloadActive, async (isActive, wasActive) => {\n  await nextTick()\n  if (isActive) {\n    cloudProgress.value?.focus()\n  } else if (wasActive) {\n    modelLabelControl.value?.focus()\n  }\n})\n\nfunction handleLibrarySelect() {\n  confirmLibrarySelect(\n    modelKey.value,\n    model.name,\n    model.referencingNodes,\n    directory\n  )\n}\n</script>\n","import type { MissingModelGroup } from '@/platform/missingModel/types'\nimport { isModelDownloadable } from '@/platform/missingModel/missingModelDownload'\nimport type { ModelWithUrl } from '@/platform/missingModel/missingModelDownload'\n\nexport function toDownloadableModel(\n  model: MissingModelGroup['models'][number]\n): ModelWithUrl | null {\n  const { name, url, directory } = model.representative\n  if (!url || !directory) return null\n\n  const downloadableModel = { name, url, directory }\n  return isModelDownloadable(downloadableModel) ? downloadableModel : null\n}\n\nexport function getDownloadableModels(\n  groups: MissingModelGroup[]\n): ModelWithUrl[] {\n  return groups.flatMap((group) =>\n    group.models.flatMap((model) => toDownloadableModel(model) ?? [])\n  )\n}\n","<template>\n  <div class=\"px-3\">\n    <div\n      v-if=\"showGatedModelsHint\"\n      :id=\"gatedHintId\"\n      data-testid=\"missing-model-gated-hint\"\n      role=\"note\"\n      class=\"mb-2 flex gap-2 rounded-md border border-warning-background/30 bg-warning-background/10 p-2.5\"\n    >\n      <i\n        aria-hidden=\"true\"\n        class=\"mt-0.5 icon-[lucide--lock] size-4 shrink-0 text-warning-background\"\n      />\n      <p class=\"m-0 text-xs/relaxed text-warning-background\">\n        <span class=\"font-semibold\">\n          {{ t('rightSidePanel.missingModels.gatedModelsHintLabel') }}\n        </span>\n        {{ t('rightSidePanel.missingModels.gatedModelsHint', gatedModelCount) }}\n      </p>\n    </div>\n    <span role=\"status\" aria-live=\"polite\" class=\"sr-only\">\n      {{ gatedModelsAnnouncement }}\n    </span>\n\n    <div\n      v-if=\"importableModelRows.length > 0\"\n      data-testid=\"missing-model-importable-rows\"\n      class=\"-mx-1.5 flex flex-col gap-1 overflow-hidden px-1.5\"\n    >\n      <MissingModelRow\n        v-for=\"row in importableModelRows\"\n        :key=\"row.key\"\n        :model=\"row.model\"\n        :directory=\"row.directory\"\n        :is-asset-supported=\"row.isAssetSupported\"\n        :can-cloud-import=\"true\"\n        :highlighted=\"isRowHighlighted(row)\"\n        @locate-model=\"emit('locateModel', $event)\"\n      />\n    </div>\n\n    <div\n      v-if=\"unsupportedModelRows.length > 0\"\n      data-testid=\"missing-model-import-not-supported-section\"\n      class=\"flex flex-col gap-1 border-t border-secondary-background pt-3\"\n    >\n      <div class=\"mb-1\">\n        <p class=\"m-0 text-sm font-semibold text-warning-background\">\n          {{ t('rightSidePanel.missingModels.importNotSupported') }}\n        </p>\n        <p class=\"m-0 mt-1 text-xs/relaxed text-muted-foreground\">\n          {{ t('rightSidePanel.missingModels.customNodeDownloadDisabled') }}\n        </p>\n      </div>\n      <MissingModelRow\n        v-for=\"row in unsupportedModelRows\"\n        :key=\"row.key\"\n        :model=\"row.model\"\n        :directory=\"row.directory\"\n        :is-asset-supported=\"row.isAssetSupported\"\n        :can-cloud-import=\"false\"\n        :highlighted=\"isRowHighlighted(row)\"\n        @locate-model=\"emit('locateModel', $event)\"\n      />\n    </div>\n\n    <div\n      v-if=\"downloadableModels.length > 0\"\n      data-testid=\"missing-model-actions\"\n      class=\"flex items-center pt-2\"\n    >\n      <Button\n        data-testid=\"missing-model-download-all\"\n        variant=\"secondary\"\n        size=\"sm\"\n        class=\"h-8 min-w-0 flex-1 rounded-md text-xs\"\n        :aria-describedby=\"showGatedModelsHint ? gatedHintId : undefined\"\n        @click=\"downloadAllModels\"\n      >\n        <i aria-hidden=\"true\" class=\"icon-[lucide--download] size-4 shrink-0\" />\n        <span class=\"truncate\">{{ downloadAllLabel }}</span>\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref, useId, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport type { MissingModelGroup } from '@/platform/missingModel/types'\nimport { isCloud } from '@/platform/distribution/types'\nimport MissingModelRow from '@/platform/missingModel/components/MissingModelRow.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useMissingModelDownload } from '@/platform/missingModel/composables/useMissingModelDownload'\nimport { isTrustedHuggingFaceUrl } from '@/platform/missingModel/missingModelDownload'\nimport { getDownloadableModels } from '@/platform/missingModel/missingModelViewUtils'\nimport { formatSize } from '@/utils/formatUtil'\n\ninterface MissingModelRowEntry {\n  key: string\n  model: MissingModelGroup['models'][number]\n  directory: string | null\n  isAssetSupported: boolean\n}\n\nconst MODEL_TYPE_SORT_ORDER = [\n  'checkpoints',\n  'loras',\n  'vae',\n  'text_encoders',\n  'diffusion_models'\n] as const\n\nconst { missingModelGroups, highlightedNodeIds } = defineProps<{\n  missingModelGroups: MissingModelGroup[]\n  /** Execution node ids to emphasize (current canvas selection). */\n  highlightedNodeIds?: Set<string>\n}>()\n\nconst emit = defineEmits<{\n  locateModel: [nodeId: string]\n}>()\n\nconst { t } = useI18n()\nconst gatedHintId = useId()\nconst { downloadMissingModel, fileSizeFor, gatedRepoUrlFor } =\n  useMissingModelDownload()\n\nconst sortedModelRows = computed(() =>\n  missingModelGroups\n    .flatMap((group) =>\n      group.models.map((model, index) => ({\n        key: getModelRowKey(group, model, index),\n        model,\n        directory: group.directory,\n        isAssetSupported: group.isAssetSupported\n      }))\n    )\n    .sort((a, b) => compareModelRows(a, b))\n)\n\nconst importableModelRows = computed(() =>\n  sortedModelRows.value.filter((row) => !isCloud || canCloudImport(row))\n)\n\nconst unsupportedModelRows = computed(() =>\n  isCloud ? sortedModelRows.value.filter((row) => !canCloudImport(row)) : []\n)\n\nconst downloadableModels = computed(() => {\n  if (isCloud) return []\n\n  return getDownloadableModels(missingModelGroups)\n})\n\nconst gatedModelCount = computed(\n  () =>\n    downloadableModels.value.filter((model) => {\n      const repoUrl = gatedRepoUrlFor(model.url)\n      return !!repoUrl && isTrustedHuggingFaceUrl(repoUrl)\n    }).length\n)\nconst showGatedModelsHint = computed(() => gatedModelCount.value > 0)\nconst gatedModelsAnnouncement = ref('')\n\nwatch(showGatedModelsHint, (isVisible, wasVisible) => {\n  if (!isVisible) {\n    gatedModelsAnnouncement.value = ''\n    return\n  }\n  if (wasVisible) return\n\n  gatedModelsAnnouncement.value = `${t(\n    'rightSidePanel.missingModels.gatedModelsHintLabel'\n  )} ${t(\n    'rightSidePanel.missingModels.gatedModelsHint',\n    gatedModelCount.value\n  )}`\n})\n\nconst downloadAllLabel = computed(() => {\n  const base = t('rightSidePanel.missingModels.downloadAll')\n  const total = downloadableModels.value.reduce(\n    (sum, model) => sum + (fileSizeFor(model.url) ?? 0),\n    0\n  )\n  return total > 0 ? `${base} (${formatSize(total)})` : base\n})\n\nfunction downloadAllModels() {\n  for (const model of downloadableModels.value) {\n    downloadMissingModel(model)\n  }\n}\n\nfunction getModelRowKey(\n  group: MissingModelGroup,\n  model: MissingModelGroup['models'][number],\n  index: number\n) {\n  const supportKey = group.isAssetSupported ? 'supported' : 'unsupported'\n  return [\n    supportKey,\n    group.directory ?? '__unknown__',\n    model.name,\n    String(index)\n  ].join('::')\n}\n\nfunction compareModelRows(a: MissingModelRowEntry, b: MissingModelRowEntry) {\n  return (\n    getModelTypeSortIndex(a.directory) - getModelTypeSortIndex(b.directory) ||\n    (a.directory ?? '').localeCompare(b.directory ?? '') ||\n    a.model.name.localeCompare(b.model.name)\n  )\n}\n\nfunction getModelTypeSortIndex(directory: string | null) {\n  if (directory === null) return Number.MAX_SAFE_INTEGER\n  const index = MODEL_TYPE_SORT_ORDER.indexOf(\n    directory as (typeof MODEL_TYPE_SORT_ORDER)[number]\n  )\n  return index === -1 ? MODEL_TYPE_SORT_ORDER.length : index\n}\n\nfunction canCloudImport(row: MissingModelRowEntry) {\n  return row.isAssetSupported && row.directory !== null\n}\n\nfunction isRowHighlighted(row: MissingModelRowEntry) {\n  if (!highlightedNodeIds?.size) return false\n  return row.model.referencingNodes.some((ref) =>\n    highlightedNodeIds.has(String(ref.nodeId))\n  )\n}\n</script>\n","<template>\n  <div class=\"px-3\">\n    <TransitionGroup\n      tag=\"ul\"\n      name=\"list-scale\"\n      class=\"relative m-0 list-none space-y-1 p-0\"\n    >\n      <li\n        v-for=\"item in missingMediaItems\"\n        :key=\"item.key\"\n        data-testid=\"missing-media-row\"\n        :aria-current=\"\n          highlightedNodeIds?.has(item.nodeId) ? 'true' : undefined\n        \"\n        class=\"min-w-0\"\n      >\n        <!-- Emphasis lives on an inner element: the li is a TransitionGroup\n             child, and the emphasis transition-property would override the\n             list-scale move/enter/leave transitions. -->\n        <div\n          :class=\"\n            cn(\n              'flex min-w-0 items-center gap-2',\n              selectionEmphasisClass(highlightedNodeIds?.has(item.nodeId))\n            )\n          \"\n        >\n          <span class=\"flex min-w-0 flex-1\">\n            <button\n              type=\"button\"\n              class=\"m-0 inline max-w-full cursor-pointer appearance-none rounded-sm border-0 bg-transparent p-0 text-left text-xs/relaxed font-normal wrap-break-word text-muted-foreground outline-none hover:text-base-foreground focus:outline-none focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none focus-visible:ring-inset\"\n              @click=\"emit('locateNode', item.nodeId)\"\n            >\n              {{ item.displayItemLabel }}\n            </button>\n          </span>\n          <Button\n            data-testid=\"missing-media-locate-button\"\n            variant=\"textonly\"\n            size=\"icon-sm\"\n            class=\"size-8 shrink-0 text-muted-foreground hover:text-base-foreground focus-visible:ring-inset\"\n            :aria-label=\"\n              t(\n                'rightSidePanel.locateNodeFor',\n                {\n                  item: item.displayItemLabel\n                },\n                { escapeParameter: false }\n              )\n            \"\n            @click.stop=\"emit('locateNode', item.nodeId)\"\n          >\n            <i aria-hidden=\"true\" class=\"icon-[lucide--locate] size-4\" />\n          </Button>\n        </div>\n      </li>\n    </TransitionGroup>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { selectionEmphasisClass } from '@/components/rightSidePanel/errors/selectionEmphasis'\nimport { resolveMissingMediaItemLabel } from '@/platform/errorCatalog/errorMessageResolver'\nimport { getMissingMediaReferences } from '@/platform/missingMedia/missingMediaGrouping'\nimport type { MissingMediaGroup } from '@/platform/missingMedia/types'\nimport { app } from '@/scripts/app'\nimport { getNodeByExecutionId } from '@/utils/graphTraversalUtil'\nimport { resolveNodeDisplayName } from '@/utils/nodeTitleUtil'\n\nconst { missingMediaGroups } = defineProps<{\n  missingMediaGroups: MissingMediaGroup[]\n  /** Execution node ids to emphasize (current canvas selection). */\n  highlightedNodeIds?: Set<string>\n}>()\n\nconst emit = defineEmits<{\n  locateNode: [nodeId: string]\n}>()\n\nconst { t } = useI18n()\n\ninterface MissingMediaItemEntry {\n  key: string\n  nodeId: string\n  displayItemLabel: string\n}\n\nconst missingMediaItems = computed(() => {\n  return getMissingMediaReferences(missingMediaGroups)\n    .map(({ mediaItem, nodeRef }) => {\n      const nodeId = String(nodeRef.nodeId)\n      return {\n        key: `${nodeId}:${nodeRef.widgetName}:${mediaItem.name}`,\n        nodeId,\n        displayItemLabel: getDisplayItemLabel(\n          nodeId,\n          nodeRef.nodeType ?? mediaItem.representative.nodeType,\n          nodeRef.widgetName\n        )\n      }\n    })\n    .sort(compareMissingMediaItems)\n})\n\nfunction getDisplayItemLabel(\n  nodeId: string,\n  nodeType: string,\n  widgetName: string\n) {\n  const nodeDisplayName = getNodeDisplayLabel(nodeId, '')\n  return resolveMissingMediaItemLabel({\n    nodeDisplayName,\n    nodeType,\n    widgetName\n  }).displayItemLabel\n}\n\nfunction compareMissingMediaItems(\n  a: MissingMediaItemEntry,\n  b: MissingMediaItemEntry\n) {\n  return (\n    a.nodeId.localeCompare(b.nodeId, undefined, { numeric: true }) ||\n    a.displayItemLabel.localeCompare(b.displayItemLabel)\n  )\n}\n\nfunction getNodeDisplayLabel(nodeId: string, fallback: string): string {\n  const graph = app.rootGraph\n  if (!graph) return fallback\n  const node = getNodeByExecutionId(graph, nodeId)\n  return resolveNodeDisplayName(node, {\n    emptyLabel: fallback,\n    untitledLabel: fallback\n  })\n}\n</script>\n","import {\n  canTransferReplacementOwnership,\n  transferReplacementOwnership\n} from '@/core/graph/nodeShell/nodeShellState'\nimport type { LGraph, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { inputLinkId, outputLinks } from '@/lib/litegraph/src/node/slotLinks'\nimport type { LLink } from '@/lib/litegraph/src/LLink'\nimport type { ISerialisedNode } from '@/lib/litegraph/src/types/serialisation'\nimport { NodeSlotType } from '@/lib/litegraph/src/types/globalEnums'\nimport type { TWidgetValue } from '@/lib/litegraph/src/types/widgets'\nimport { isNodeBindable } from '@/lib/litegraph/src/utils/type'\nimport { t } from '@/i18n'\nimport { useMissingNodesErrorStore } from '@/platform/nodeReplacement/missingNodesErrorStore'\nimport type {\n  MissingNodeType,\n  NodeReplacement\n} from '@/platform/nodeReplacement/types'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport {\n  removePendingMissingNodeTypesByType,\n  updatePendingWarnings\n} from '@/platform/workflow/core/utils/pendingWarnings'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { app, sanitizeNodeName } from '@/scripts/app'\nimport { clearNodeOwnedStoreState } from '@/stores/clearNodeOwnedStoreState'\nimport type { EndpointPatch, EndpointUpdate } from '@/stores/linkStore'\nimport { useLinkStore } from '@/stores/linkStore'\nimport { graphScopeOf } from '@/types/graphScopeId'\nimport type { LinkId } from '@/types/linkId'\nimport type { LinkTopology } from '@/types/linkTopology'\nimport { collectAllNodes } from '@/utils/graphTraversalUtil'\n\ninterface ReplacementGroup {\n  type: string\n  nodeTypes: MissingNodeType[]\n}\n\n/** Compares sanitized type strings to match placeholder → missing node type. */\nfunction findMatchingType(\n  node: LGraphNode,\n  selectedTypes: MissingNodeType[]\n): Extract<MissingNodeType, { type: string }> | undefined {\n  const nodeType = node.type\n  for (const selected of selectedTypes) {\n    if (typeof selected !== 'object' || !selected.isReplaceable) continue\n    if (sanitizeNodeName(selected.type) === nodeType) return selected\n  }\n  return undefined\n}\n\ninterface ReplacementTopologyPlan {\n  error?: string\n  updates: EndpointUpdate[]\n  removals: {\n    link: LLink\n    topology: LinkTopology\n    connection: Pick<\n      ReturnType<LLink['resolve']>,\n      'input' | 'inputNode' | 'output' | 'outputNode'\n    >\n  }[]\n}\n\nfunction planReplacementTopology(\n  oldNode: LGraphNode,\n  newNode: LGraphNode,\n  replacement: NodeReplacement,\n  graph: LGraph\n): ReplacementTopologyPlan {\n  const linkStore = useLinkStore()\n  const scope = graphScopeOf(graph)\n  const oldNodeId = String(oldNode.id)\n  const updates = new Map<LinkId, EndpointUpdate>()\n  const addUpdate = (link: LLink, patch: EndpointPatch) => {\n    const topology = linkStore.getTopology(scope.rootGraphId, link.id)\n    if (!topology) return\n    const existing = updates.get(link.id)\n    updates.set(link.id, {\n      topology,\n      patch: { ...existing?.patch, ...patch }\n    })\n  }\n\n  for (const inputMap of replacement.input_mapping ?? []) {\n    if (!('old_id' in inputMap) || isDotNotation(inputMap.new_id)) continue\n    const oldSlot = oldNode.inputs.findIndex(\n      (input) => input.name === inputMap.old_id\n    )\n    const newSlot = newNode.inputs.findIndex(\n      (input) => input.name === inputMap.new_id\n    )\n    if (oldSlot === -1 || newSlot === -1) continue\n    const linkId = inputLinkId(graph, oldNode.id, oldSlot)\n    const link = linkId == null ? undefined : graph.links.get(linkId)\n    if (link) addUpdate(link, { targetSlot: newSlot })\n  }\n\n  for (const outputMap of replacement.output_mapping ?? []) {\n    if (!newNode.outputs[outputMap.new_idx]) continue\n    for (const link of outputLinks(graph, oldNode.id, outputMap.old_idx)) {\n      addUpdate(link, { originSlot: outputMap.new_idx })\n    }\n  }\n\n  let error: string | undefined\n  const removals = [...graph.links.values()].flatMap((link) => {\n    if (\n      link.origin_id === oldNodeId &&\n      replacement.output_mapping == null &&\n      !newNode.outputs[link.origin_slot]\n    ) {\n      error ??= `output slot ${link.origin_slot} cannot preserve link ${link.id}`\n    }\n    if (\n      link.target_id === oldNodeId &&\n      replacement.input_mapping == null &&\n      !newNode.inputs[link.target_slot]\n    ) {\n      error ??= `input slot ${link.target_slot} cannot preserve link ${link.id}`\n    }\n    const update = updates.get(link.id)\n    const removesOrigin =\n      link.origin_id === oldNodeId &&\n      replacement.output_mapping != null &&\n      update?.patch.originSlot == null\n    const removesTarget =\n      link.target_id === oldNodeId &&\n      replacement.input_mapping != null &&\n      update?.patch.targetSlot == null\n    if (!removesOrigin && !removesTarget) return []\n    const topology = linkStore.getTopology(scope.rootGraphId, link.id)\n    const outputNode = graph.getNodeById(link.origin_id) ?? undefined\n    const inputNode = graph.getNodeById(link.target_id) ?? undefined\n    return topology\n      ? [\n          {\n            link,\n            topology,\n            connection: {\n              inputNode,\n              outputNode,\n              input: inputNode?.inputs[link.target_slot],\n              output: outputNode?.outputs[link.origin_slot]\n            }\n          }\n        ]\n      : []\n  })\n  return { error, updates: [...updates.values()], removals }\n}\n\n/** Uses old_widget_ids as name→index lookup into widgets_values. */\nfunction transferWidgetValue(\n  serialized: ISerialisedNode,\n  oldWidgetIds: string[] | null,\n  oldInputName: string,\n  newNode: LGraphNode,\n  newInputName: string\n): void {\n  if (!oldWidgetIds || !serialized.widgets_values) return\n\n  const oldWidgetIdx = oldWidgetIds.indexOf(oldInputName)\n  if (oldWidgetIdx === -1) return\n\n  const oldValue = serialized.widgets_values[oldWidgetIdx]\n  if (oldValue === undefined) return\n\n  const newWidget = newNode.widgets?.find((w) => w.name === newInputName)\n  if (newWidget) {\n    try {\n      newWidget.value = oldValue\n      newWidget.callback?.(oldValue)\n    } catch (error) {\n      console.error(`Failed to transfer widget ${newInputName}`, error)\n    }\n  }\n}\n\nfunction applySetValue(\n  newNode: LGraphNode,\n  inputName: string,\n  value: unknown\n): void {\n  const widget = newNode.widgets?.find((w) => w.name === inputName)\n  if (widget) {\n    try {\n      widget.value = value as TWidgetValue\n      widget.callback?.(widget.value)\n    } catch (error) {\n      console.error(`Failed to set widget ${inputName}`, error)\n    }\n  }\n}\n\nfunction isDotNotation(id: string): boolean {\n  return id.includes('.')\n}\n\n/** Auto-generates identity mapping by name for same-structure replacements without backend mapping. */\nfunction generateDefaultMapping(\n  serialized: ISerialisedNode,\n  newNode: LGraphNode\n): Pick<\n  NodeReplacement,\n  'input_mapping' | 'output_mapping' | 'old_widget_ids'\n> {\n  const oldInputNames = new Set(serialized.inputs?.map((i) => i.name) ?? [])\n\n  const inputMapping: { old_id: string; new_id: string }[] = []\n  for (const newInput of newNode.inputs) {\n    if (oldInputNames.has(newInput.name)) {\n      inputMapping.push({ old_id: newInput.name, new_id: newInput.name })\n    }\n  }\n\n  const oldWidgetIds = (newNode.widgets ?? []).map((w) => w.name)\n  for (const widget of newNode.widgets ?? []) {\n    if (!oldInputNames.has(widget.name)) {\n      inputMapping.push({ old_id: widget.name, new_id: widget.name })\n    }\n  }\n\n  const outputMapping: { old_idx: number; new_idx: number }[] = []\n  for (const [oldIdx, oldOutput] of (serialized.outputs ?? []).entries()) {\n    const newIdx = newNode.outputs.findIndex((o) => o.name === oldOutput.name)\n    if (newIdx !== -1) {\n      outputMapping.push({ old_idx: oldIdx, new_idx: newIdx })\n    }\n  }\n\n  return {\n    input_mapping: inputMapping.length > 0 ? inputMapping : null,\n    output_mapping: outputMapping.length > 0 ? outputMapping : null,\n    old_widget_ids: oldWidgetIds.length > 0 ? oldWidgetIds : null\n  }\n}\n\nfunction replaceWithMapping(\n  node: LGraphNode,\n  newNode: LGraphNode,\n  replacement: NodeReplacement,\n  nodeGraph: LGraph,\n  idx: number\n): boolean {\n  const order = node.order\n  newNode.id = node.id\n  newNode.order = order\n  newNode.mode = node.mode\n  newNode.flags = { ...node.flags }\n\n  if (\n    nodeGraph._nodes[idx] !== node ||\n    nodeGraph._nodes_by_id[node.id] !== node ||\n    !canTransferReplacementOwnership(node, newNode)\n  ) {\n    console.error(`Cannot replace node ${node.id}: ownership is invalid`)\n    return false\n  }\n\n  const serialized = node.last_serialization ?? node.serialize()\n  if (serialized.title != null) newNode.title = serialized.title\n  if (serialized.properties) {\n    newNode.properties = { ...newNode.properties, ...serialized.properties }\n    if ('Node name for S&R' in newNode.properties) {\n      newNode.properties['Node name for S&R'] = replacement.new_node_id\n    }\n  }\n\n  const topologyPlan = planReplacementTopology(\n    node,\n    newNode,\n    replacement,\n    nodeGraph\n  )\n  newNode.has_errors = false\n\n  if (topologyPlan.error) {\n    console.error(`Cannot replace node ${node.id}: ${topologyPlan.error}`)\n    return false\n  }\n\n  const linkStore = useLinkStore()\n  const scope = graphScopeOf(nodeGraph)\n  const removalTopologies = topologyPlan.removals.map(\n    ({ topology }) => topology\n  )\n  const endpointError = linkStore.validateEndpointUpdates(\n    scope,\n    topologyPlan.updates,\n    removalTopologies\n  )\n  if (endpointError) {\n    console.error(`Cannot replace node ${node.id}: ${endpointError.message}`)\n    return false\n  }\n\n  if (\n    nodeGraph._nodes[idx] !== node ||\n    nodeGraph._nodes_by_id[node.id] !== node ||\n    !canTransferReplacementOwnership(node, newNode) ||\n    !transferReplacementOwnership(node, newNode)\n  ) {\n    console.error(\n      `Cannot replace node ${node.id}: ownership changed during removal`\n    )\n    return false\n  }\n\n  const topologyResult = linkStore.updateEndpoints(\n    scope,\n    topologyPlan.updates,\n    removalTopologies\n  )\n  if (!topologyResult.ok) {\n    transferReplacementOwnership(newNode, node)\n    console.error(\n      `Cannot replace node ${node.id}: ${topologyResult.error.message}`\n    )\n    return false\n  }\n\n  for (const { connection, link, topology } of topologyPlan.removals) {\n    link.disconnect(nodeGraph)\n    nodeGraph.incrementVersion()\n    if (connection.inputNode && connection.input) {\n      try {\n        connection.inputNode.onConnectionsChange?.(\n          NodeSlotType.INPUT,\n          topology.targetSlot,\n          false,\n          link,\n          connection.input\n        )\n      } catch (error) {\n        console.error(`Failed to notify disconnected link ${link.id}`, error)\n      }\n    }\n    if (connection.outputNode && connection.output) {\n      try {\n        connection.outputNode.onConnectionsChange?.(\n          NodeSlotType.OUTPUT,\n          topology.originSlot,\n          false,\n          link,\n          connection.output\n        )\n      } catch (error) {\n        console.error(`Failed to notify disconnected link ${link.id}`, error)\n      }\n    }\n  }\n\n  try {\n    node.onRemoved?.()\n  } catch (error) {\n    console.error(`Failed to remove replaced node ${node.id}`, error)\n  }\n  clearNodeOwnedStoreState(node)\n\n  nodeGraph._nodes[idx] = newNode\n  newNode.graph = nodeGraph\n  node.graph = null\n  nodeGraph._nodes_by_id[newNode.id] = newNode\n\n  if (replacement.input_mapping) {\n    for (const inputMap of replacement.input_mapping) {\n      if ('old_id' in inputMap) {\n        if (isDotNotation(inputMap.new_id)) continue\n        transferWidgetValue(\n          serialized,\n          replacement.old_widget_ids,\n          inputMap.old_id,\n          newNode,\n          inputMap.new_id\n        )\n      } else if (!isDotNotation(inputMap.new_id)) {\n        applySetValue(newNode, inputMap.new_id, inputMap.set_value)\n      }\n    }\n  }\n  for (const widget of newNode.widgets ?? []) {\n    if (!isNodeBindable(widget)) continue\n    try {\n      widget.setNodeId(newNode.id)\n    } catch (error) {\n      console.error(`Failed to bind replacement widget ${widget.name}`, error)\n    }\n  }\n\n  try {\n    nodeGraph.onNodeAdded?.(newNode)\n  } catch (error) {\n    console.error(`Failed to notify replacement node ${newNode.id}`, error)\n  }\n  try {\n    nodeGraph.events.dispatch('node:added', { node: newNode })\n  } catch (error) {\n    console.error(`Failed to dispatch replacement node ${newNode.id}`, error)\n  }\n  return true\n}\n\nfunction removeReplacedMissingNodeTypes(types: string[]): void {\n  // Remove from the rendered store directly rather than re-projecting the\n  // cache into it: entries surfaced outside the load path (e.g. the\n  // missing_node_type rescan) exist only in the store, and a projection from\n  // a cache that never saw them would wipe them.\n  useMissingNodesErrorStore().removeMissingNodesByType(types)\n\n  const activeWorkflow = useWorkflowStore().activeWorkflow\n  if (!activeWorkflow) return\n\n  updatePendingWarnings(activeWorkflow, {\n    missingNodeTypes: removePendingMissingNodeTypesByType(\n      activeWorkflow.pendingWarnings?.missingNodeTypes,\n      types\n    )\n  })\n}\n\nexport function useNodeReplacement() {\n  const toast = useToast()\n\n  function replaceNodesInPlace(selectedTypes: MissingNodeType[]): string[] {\n    const replacedTypes: string[] = []\n    const failedTypes = new Set<string>()\n    let replacementFailed: true | undefined\n    let anyNodeReplaced = false\n    const graph = app.rootGraph\n    const recordReplacementFailure = (type: string) => {\n      replacementFailed = true\n      failedTypes.add(type)\n      const replacedTypeIndex = replacedTypes.indexOf(type)\n      if (replacedTypeIndex !== -1) {\n        replacedTypes.splice(replacedTypeIndex, 1)\n      }\n    }\n\n    const changeTracker =\n      useWorkflowStore().activeWorkflow?.changeTracker ?? null\n    changeTracker?.beforeChange()\n\n    // Target types come from node_replacements fetched at workflow load time\n    // and the missing nodes detected at that point — not from the current\n    // registered_node_types. This ensures replacement still works even if\n    // the user has since installed the missing node pack.\n    // Also include sanitized variants so that when the fallback path reads\n    // n.type (which app.ts may have already run through sanitizeNodeName),\n    // we can still match against the original type stored in selectedTypes.\n    const targetTypes = new Set([\n      ...selectedTypes.map((t) => (typeof t === 'string' ? t : t.type)),\n      ...selectedTypes.map((t) =>\n        sanitizeNodeName(typeof t === 'string' ? t : t.type)\n      )\n    ])\n\n    try {\n      const placeholders = collectAllNodes(graph, (n) => {\n        if (!n.last_serialization) return false\n        // Prefer the original serialized type; fall back to the live type\n        // for nodes whose serialization predates the type field.\n        // n.type may have been sanitized by app.ts (HTML special chars stripped);\n        // the sanitized variants in targetTypes ensure we still match correctly.\n        const originalType = n.last_serialization.type || n.type\n        return !!originalType && targetTypes.has(originalType)\n      })\n\n      for (const node of placeholders) {\n        const match = findMatchingType(node, selectedTypes)\n        if (!match?.replacement) continue\n\n        const replacement = match.replacement\n        const nodeGraph = node.graph\n        if (!nodeGraph) {\n          recordReplacementFailure(match.type)\n          continue\n        }\n\n        const idx = nodeGraph._nodes.indexOf(node)\n        if (idx === -1) {\n          recordReplacementFailure(match.type)\n          continue\n        }\n\n        const newNode = LiteGraph.createNode(replacement.new_node_id)\n        if (!newNode) {\n          recordReplacementFailure(match.type)\n          continue\n        }\n\n        const hasMapping =\n          replacement.input_mapping != null ||\n          replacement.output_mapping != null\n\n        const effectiveReplacement = hasMapping\n          ? replacement\n          : {\n              ...replacement,\n              ...generateDefaultMapping(\n                node.last_serialization ?? node.serialize(),\n                newNode\n              )\n            }\n        const replaced = replaceWithMapping(\n          node,\n          newNode,\n          effectiveReplacement,\n          nodeGraph,\n          idx\n        )\n        if (!replaced) {\n          recordReplacementFailure(match.type)\n          continue\n        }\n        anyNodeReplaced = true\n\n        if (\n          !failedTypes.has(match.type) &&\n          !replacedTypes.includes(match.type)\n        ) {\n          replacedTypes.push(match.type)\n        }\n      }\n\n      if (anyNodeReplaced) {\n        graph.updateExecutionOrder()\n        graph.setDirtyCanvas(true, true)\n      }\n\n      if (replacedTypes.length > 0) {\n        toast.success(t('g.success'), {\n          description: t('nodeReplacement.replacedAllNodes', {\n            count: replacedTypes.length\n          }),\n          duration: 3000\n        })\n      }\n      if (replacementFailed) {\n        toast.error(t('g.error'), {\n          description: t('nodeReplacement.replaceFailed')\n        })\n      }\n    } catch (error) {\n      console.error('Failed to replace nodes:', error)\n      if (anyNodeReplaced) {\n        graph.updateExecutionOrder()\n        graph.setDirtyCanvas(true, true)\n      }\n      toast.error(t('g.error'), {\n        description: t('nodeReplacement.replaceFailed')\n      })\n      return replacedTypes\n    } finally {\n      changeTracker?.afterChange()\n    }\n\n    return replacedTypes\n  }\n\n  /**\n   * Replaces all nodes in a single swap group and removes successfully\n   * replaced types from pending warnings and rendered state.\n   */\n  function replaceGroup(group: ReplacementGroup): void {\n    const replaced = replaceNodesInPlace(group.nodeTypes)\n    if (replaced.length > 0) {\n      removeReplacedMissingNodeTypes(replaced)\n    }\n  }\n\n  /**\n   * Replaces every available node across all swap groups and removes\n   * the succeeded types from pending warnings and rendered state.\n   */\n  function replaceAllGroups(groups: ReplacementGroup[]): void {\n    const allNodeTypes = groups.flatMap((g) => g.nodeTypes)\n    const replaced = replaceNodesInPlace(allNodeTypes)\n    if (replaced.length > 0) {\n      removeReplacedMissingNodeTypes(replaced)\n    }\n  }\n\n  return {\n    replaceNodesInPlace,\n    replaceGroup,\n    replaceAllGroups\n  }\n}\n","<template>\n  <div class=\"flex min-w-0 flex-col\">\n    <!-- Search bar + collapse toggle -->\n    <div\n      class=\"flex min-w-0 shrink-0 items-center border-b border-interface-stroke px-4 pt-1 pb-4\"\n    >\n      <AsyncSearchInput v-model=\"searchQuery\" class=\"flex-1\" />\n      <CollapseToggleButton\n        v-model=\"isAllCollapsed\"\n        :show=\"!isSearching && allErrorGroups.length > 1\"\n      />\n    </div>\n\n    <div class=\"min-w-0 flex-1 overflow-y-auto bg-interface-panel-surface p-3\">\n      <div\n        v-if=\"filteredGroups.length === 0\"\n        role=\"status\"\n        class=\"px-1 pt-5 pb-15 text-center text-sm text-muted-foreground\"\n      >\n        {{\n          searchQuery.trim()\n            ? t('rightSidePanel.noneSearchDesc')\n            : t('rightSidePanel.noErrors')\n        }}\n      </div>\n\n      <div\n        v-else\n        class=\"overflow-hidden rounded-lg border border-secondary-background\"\n      >\n        <!-- Errors summary hero -->\n        <div data-testid=\"errors-summary-hero\" class=\"bg-base-foreground/5\">\n          <div role=\"status\" class=\"flex items-center gap-2 p-2\">\n            <span v-if=\"hasMixedSeverityTotals\" class=\"sr-only\">\n              {{\n                t('rightSidePanel.severityCountsStatus', {\n                  errors: errorCount,\n                  setup: missingCount\n                })\n              }}\n            </span>\n            <span\n              :class=\"\n                cn(\n                  'flex h-12 min-w-9 shrink-0 items-center justify-center px-1 text-[2rem]/none font-extrabold tabular-nums',\n                  hero.countClass\n                )\n              \"\n            >\n              {{ hero.count }}\n            </span>\n            <span\n              aria-hidden=\"true\"\n              class=\"h-9 w-px shrink-0 bg-interface-stroke\"\n            />\n            <div class=\"flex min-w-0 flex-1 flex-col gap-1 px-2\">\n              <span class=\"text-xs/tight font-semibold text-base-foreground\">\n                {{ hero.title }}\n              </span>\n              <span class=\"text-xs/tight text-muted-foreground\">\n                {{ hero.description }}\n              </span>\n            </div>\n          </div>\n          <div\n            v-if=\"hasMixedSeverityTotals\"\n            data-testid=\"errors-summary-filters\"\n            class=\"flex flex-wrap items-center gap-2 px-2 pb-2\"\n          >\n            <Button\n              v-for=\"chip in severityChips\"\n              :key=\"chip.severity\"\n              type=\"button\"\n              variant=\"outline\"\n              size=\"sm\"\n              :data-testid=\"'errors-summary-filter-' + chip.severity\"\n              :aria-pressed=\"chip.active\"\n              :class=\"\n                cn(\n                  'h-7 shrink-0 gap-1 rounded-lg px-3 text-xs font-semibold hover:bg-transparent',\n                  chip.active && 'gap-2 pr-2',\n                  SEVERITY_CHIP_CLASS[chip.severity][\n                    chip.active ? 'active' : 'idle'\n                  ]\n                )\n              \"\n              @click=\"toggleSeverityFilter(chip.severity)\"\n            >\n              {{ chip.label }}\n              <i\n                v-if=\"chip.active\"\n                aria-hidden=\"true\"\n                class=\"icon-[lucide--x] size-3.5\"\n              />\n            </Button>\n          </div>\n        </div>\n\n        <!-- Context strip: workflow summary, or the selection's errors -->\n        <div\n          data-testid=\"selection-context-strip\"\n          role=\"status\"\n          class=\"flex items-center border-t border-secondary-background px-3 pt-3.5 pb-1.5\"\n        >\n          <i18n-t\n            :keypath=\"strip.keypath\"\n            :plural=\"strip.count\"\n            tag=\"span\"\n            :class=\"\n              cn(\n                'min-w-0 flex-1 truncate text-xs font-semibold transition-colors duration-200',\n                hasSelectionEmphasis\n                  ? 'text-primary-background-hover'\n                  : 'text-muted-foreground'\n              )\n            \"\n          >\n            <template #node>{{ selectionStripNodeLabel }}</template>\n            <template #nodes>{{ strip.nodes }}</template>\n            <template #count>{{ strip.count }}</template>\n          </i18n-t>\n        </div>\n\n        <!-- In-block so the chips stay mounted as the release control -->\n        <div\n          v-if=\"visibleGroups.length === 0\"\n          role=\"status\"\n          class=\"border-t border-secondary-background px-1 pt-5 pb-15 text-center text-sm text-muted-foreground\"\n        >\n          {{ t('rightSidePanel.noneSearchDesc') }}\n        </div>\n\n        <!-- Group by Class Type -->\n        <TransitionGroup tag=\"div\" name=\"list-scale\" class=\"relative\">\n          <ErrorCardSection\n            v-for=\"group in visibleGroups\"\n            :key=\"group.groupKey\"\n            :data-testid=\"'error-group-' + group.type.replaceAll('_', '-')\"\n            :title=\"group.displayTitle\"\n            :count=\"group.count\"\n            :severity=\"group.severity\"\n            :collapse=\"isSectionCollapsed(group.groupKey) && !isSearching\"\n            class=\"border-t border-secondary-background first:border-t-0\"\n            @update:collapse=\"setSectionCollapsed(group.groupKey, $event)\"\n          >\n            <template #title-badge>\n              <span\n                v-if=\"group.blockedLastRun\"\n                data-testid=\"blocked-last-run-indicator\"\n                class=\"flex shrink-0 items-center rounded-full bg-warning-background px-2 py-0.5 text-2xs font-medium text-warning-on-background\"\n              >\n                {{ t('rightSidePanel.blockedLastRun') }}\n              </span>\n            </template>\n            <template #actions>\n              <Button\n                v-if=\"\n                  group.type === 'missing_node' &&\n                  missingNodePacks.length > 0 &&\n                  shouldShowInstallButton\n                \"\n                variant=\"secondary\"\n                size=\"sm\"\n                class=\"shrink-0\"\n                :disabled=\"isInstallingAll\"\n                @click.stop=\"installAll\"\n              >\n                <DotSpinner v-if=\"isInstallingAll\" duration=\"1s\" :size=\"12\" />\n                {{\n                  isInstallingAll\n                    ? t('rightSidePanel.missingNodePacks.installing')\n                    : t('rightSidePanel.missingNodePacks.installAll')\n                }}\n              </Button>\n              <Button\n                v-else-if=\"group.type === 'swap_nodes'\"\n                :tooltip=\"\n                  t(\n                    'nodeReplacement.replaceAllWarning',\n                    'Replaces all available nodes in this group.'\n                  )\n                \"\n                variant=\"secondary\"\n                size=\"sm\"\n                class=\"shrink-0\"\n                @click.stop=\"handleReplaceAll()\"\n              >\n                {{ t('nodeReplacement.replaceAll', 'Replace All') }}\n              </Button>\n              <Button\n                v-else-if=\"\n                  group.type === 'missing_model' &&\n                  showMissingModelHeaderRefresh\n                \"\n                data-testid=\"missing-model-header-refresh\"\n                variant=\"muted-textonly\"\n                size=\"icon\"\n                class=\"shrink-0 rounded-lg hover:bg-transparent hover:text-base-foreground\"\n                :aria-label=\"t('rightSidePanel.missingModels.refresh')\"\n                :aria-busy=\"missingModelStore.isRefreshingMissingModels\"\n                :aria-disabled=\"missingModelStore.isRefreshingMissingModels\"\n                @click.stop=\"handleMissingModelRefresh\"\n              >\n                <DotSpinner\n                  v-if=\"missingModelStore.isRefreshingMissingModels\"\n                  aria-hidden=\"true\"\n                  duration=\"1s\"\n                  :size=\"12\"\n                />\n                <i\n                  v-else\n                  aria-hidden=\"true\"\n                  class=\"icon-[lucide--refresh-cw] size-4 shrink-0\"\n                />\n              </Button>\n              <span\n                v-if=\"\n                  group.type === 'missing_model' &&\n                  showMissingModelHeaderRefresh\n                \"\n                role=\"status\"\n                aria-live=\"polite\"\n                class=\"sr-only\"\n              >\n                {{\n                  missingModelStore.isRefreshingMissingModels\n                    ? t('rightSidePanel.missingModels.refreshing')\n                    : ''\n                }}\n              </span>\n            </template>\n\n            <div\n              v-if=\"group.displayMessage\"\n              data-testid=\"error-group-display-message\"\n              class=\"px-3 py-1\"\n            >\n              <p\n                class=\"m-0 text-xs/normal wrap-break-word whitespace-pre-wrap text-base-foreground/50\"\n              >\n                {{ group.displayMessage }}\n              </p>\n            </div>\n\n            <!-- Missing Node Packs -->\n            <MissingNodeCard\n              v-if=\"group.type === 'missing_node'\"\n              :show-info-button=\"shouldShowManagerButtons\"\n              :missing-pack-groups=\"missingPackGroups\"\n              :highlighted-node-ids=\"selectionMatchedAssetNodeIds\"\n              @locate-node=\"handleLocateMissingNode\"\n              @open-manager-info=\"handleOpenManagerInfo\"\n            />\n\n            <!-- Swap Nodes -->\n            <SwapNodesCard\n              v-if=\"group.type === 'swap_nodes'\"\n              :swap-node-groups=\"swapNodeGroups\"\n              :highlighted-node-ids=\"selectionMatchedAssetNodeIds\"\n              @locate-node=\"handleLocateMissingNode\"\n              @replace=\"handleReplaceGroup\"\n            />\n\n            <!-- Execution Errors -->\n            <div v-if=\"isExecutionItemListGroup(group)\" class=\"px-3\">\n              <ul class=\"m-0 list-none space-y-1 p-0\">\n                <li\n                  v-for=\"item in getExecutionItemList(group)\"\n                  :key=\"item.key\"\n                  :aria-current=\"\n                    isCardInSelection(item.cardId) ? 'true' : undefined\n                  \"\n                  :class=\"\n                    cn(\n                      'min-w-0',\n                      selectionEmphasisClass(isCardInSelection(item.cardId))\n                    )\n                  \"\n                >\n                  <div class=\"flex min-w-0 items-center gap-2\">\n                    <span class=\"flex min-w-0 flex-1 items-center gap-1\">\n                      <Tooltip :disabled=\"!item.displayDetails\">\n                        <TooltipTrigger as-child>\n                          <button\n                            type=\"button\"\n                            class=\"m-0 inline max-w-full cursor-pointer appearance-none rounded-sm border-0 bg-transparent p-0 text-left text-xs/relaxed font-normal wrap-break-word text-muted-foreground outline-none hover:text-base-foreground focus:outline-none focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none focus-visible:ring-inset\"\n                            @click=\"handleLocateNode(item.nodeId)\"\n                          >\n                            {{ item.label }}\n                          </button>\n                        </TooltipTrigger>\n                        <TooltipContent>{{\n                          item.displayDetails\n                        }}</TooltipContent>\n                      </Tooltip>\n                      <Button\n                        v-if=\"item.displayDetails\"\n                        variant=\"textonly\"\n                        size=\"icon-sm\"\n                        :class=\"\n                          cn(\n                            'size-6 shrink-0 text-muted-foreground hover:text-base-foreground focus-visible:ring-inset',\n                            isExecutionItemDetailExpanded(item.key) &&\n                              'bg-secondary-background-selected text-base-foreground hover:bg-secondary-background-selected'\n                          )\n                        \"\n                        :aria-label=\"\n                          t(\n                            'rightSidePanel.infoFor',\n                            { item: item.label },\n                            { escapeParameter: false }\n                          )\n                        \"\n                        :aria-controls=\"getExecutionItemDetailId(item.key)\"\n                        :aria-expanded=\"isExecutionItemDetailExpanded(item.key)\"\n                        @click.stop=\"toggleExecutionItemDetail(item.key)\"\n                      >\n                        <i class=\"icon-[lucide--info] size-3.5\" />\n                      </Button>\n                    </span>\n                    <LocateNodeButton\n                      :label=\"\n                        t(\n                          'rightSidePanel.locateNodeFor',\n                          {\n                            item: item.label\n                          },\n                          { escapeParameter: false }\n                        )\n                      \"\n                      @locate=\"handleLocateNode(item.nodeId)\"\n                    />\n                  </div>\n                  <TransitionCollapse>\n                    <p\n                      v-if=\"\n                        item.displayDetails &&\n                        isExecutionItemDetailExpanded(item.key)\n                      \"\n                      :id=\"getExecutionItemDetailId(item.key)\"\n                      class=\"m-0 mt-0.5 pr-10 text-2xs/relaxed wrap-break-word whitespace-pre-wrap text-muted-foreground\"\n                    >\n                      {{ item.displayDetails }}\n                    </p>\n                  </TransitionCollapse>\n                </li>\n              </ul>\n            </div>\n            <div v-else-if=\"group.type === 'execution'\" class=\"space-y-3 px-3\">\n              <ErrorNodeCard\n                v-for=\"card in group.cards\"\n                :key=\"card.id\"\n                :card=\"card\"\n                :aria-current=\"isCardInSelection(card.id) ? 'true' : undefined\"\n                :class=\"\n                  cn(\n                    selectionEmphasisClass(isCardInSelection(card.id)),\n                    isCardInSelection(card.id) && '-my-1 py-1'\n                  )\n                \"\n                @locate-node=\"handleLocateNode\"\n                @copy-to-clipboard=\"copyToClipboard\"\n              />\n            </div>\n\n            <!-- Missing Models -->\n            <MissingModelCard\n              v-if=\"group.type === 'missing_model'\"\n              :missing-model-groups=\"missingModelGroups\"\n              :highlighted-node-ids=\"selectionMatchedAssetNodeIds\"\n              @locate-model=\"handleLocateAssetNode\"\n            />\n\n            <!-- Missing Media -->\n            <MissingMediaCard\n              v-if=\"group.type === 'missing_media'\"\n              :missing-media-groups=\"missingMediaGroups\"\n              :highlighted-node-ids=\"selectionMatchedAssetNodeIds\"\n              @locate-node=\"handleLocateAssetNode\"\n            />\n          </ErrorCardSection>\n        </TransitionGroup>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\n\nimport { computed, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { useFocusNode } from '@/composables/canvas/useFocusNode'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\nimport { useManagerState } from '@/workbench/extensions/manager/composables/useManagerState'\nimport { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\nimport CollapseToggleButton from '../layout/CollapseToggleButton.vue'\nimport TransitionCollapse from '../layout/TransitionCollapse.vue'\nimport AsyncSearchInput from '@/components/ui/search-input/AsyncSearchInput.vue'\nimport ErrorCardSection from './ErrorCardSection.vue'\nimport ErrorNodeCard from './ErrorNodeCard.vue'\nimport LocateNodeButton from './LocateNodeButton.vue'\nimport MissingNodeCard from './MissingNodeCard.vue'\nimport SwapNodesCard from '@/platform/nodeReplacement/components/SwapNodesCard.vue'\nimport MissingModelCard from '@/platform/missingModel/components/MissingModelCard.vue'\nimport MissingMediaCard from '@/platform/missingMedia/components/MissingMediaCard.vue'\nimport { isCloud } from '@/platform/distribution/types'\nimport Button from '@/components/ui/button/Button.vue'\nimport DotSpinner from '@/components/common/DotSpinner.vue'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport { usePackInstall } from '@/workbench/extensions/manager/composables/nodePack/usePackInstall'\nimport { useMissingNodes } from '@/workbench/extensions/manager/composables/nodePack/useMissingNodes'\nimport { useErrorGroups } from './useErrorGroups'\nimport type { SwapNodeGroup } from './useErrorGroups'\nimport type { ErrorGroup, ErrorGroupSeverity } from './types'\nimport { isExecutionItemListGroup } from './executionItemList'\nimport { selectionEmphasisClass } from './selectionEmphasis'\nimport { useNodeReplacement } from '@/platform/nodeReplacement/useNodeReplacement'\n\ninterface ExecutionItemListEntry {\n  key: string\n  cardId: string\n  nodeId: string\n  label: string\n  displayDetails?: string\n}\n\ninterface ContextStrip {\n  keypath: string\n  count: number\n  nodes: number\n}\n\n/** Count-only `none` keys keep node-less errors from reading as \"0 nodes\". */\nconst SUMMARY_KEYPATHS = {\n  error: {\n    none: 'rightSidePanel.errorsSummary',\n    single: 'rightSidePanel.errorNodeSummary',\n    multiple: 'rightSidePanel.errorNodesSummary'\n  },\n  setup: {\n    none: 'rightSidePanel.setupSummary',\n    single: 'rightSidePanel.setupNodeSummary',\n    multiple: 'rightSidePanel.setupNodesSummary'\n  }\n} as const\n\nconst HIDDEN_BY_FILTER = { error: 'missing', missing: 'error' } as const\n\nconst SEVERITY_CHIP_CLASS = {\n  error: {\n    idle: 'border-interface-stroke text-destructive-background-hover',\n    active:\n      'border-destructive-background-hover/50 text-destructive-background-hover'\n  },\n  missing: {\n    idle: 'border-interface-stroke text-warning-foreground',\n    active: 'border-warning-background/50 text-warning-foreground'\n  }\n} as const\n\nconst { t } = useI18n()\nconst { copyToClipboard } = useCopyToClipboard()\nconst { focusNode } = useFocusNode()\nconst rightSidePanelStore = useRightSidePanelStore()\nconst missingModelStore = useMissingModelStore()\nconst { shouldShowManagerButtons, shouldShowInstallButton, openManager } =\n  useManagerState()\nconst { missingNodePacks } = useMissingNodes()\nconst { isInstalling: isInstallingAll, installAllPacks: installAll } =\n  usePackInstall(() => missingNodePacks.value)\nconst { replaceGroup, replaceAllGroups } = useNodeReplacement()\n\nconst searchQuery = ref('')\nconst expandedExecutionItemDetailKeys = ref(new Set<string>())\nconst isSearching = computed(() => searchQuery.value.trim() !== '')\n\nfunction getExecutionItemList(group: ErrorGroup): ExecutionItemListEntry[] {\n  if (group.type !== 'execution') return []\n\n  const items: ExecutionItemListEntry[] = []\n  for (const card of group.cards) {\n    if (!card.nodeId) continue\n    for (let idx = 0; idx < card.errors.length; idx++) {\n      const error = card.errors[idx]\n      const label = error.displayItemLabel\n      if (!label) continue\n      items.push({\n        key: `${card.id}:${idx}`,\n        cardId: card.id,\n        nodeId: card.nodeId,\n        label,\n        displayDetails: error.displayDetails\n      })\n    }\n  }\n  return items.sort(compareExecutionItemListEntry)\n}\n\nfunction compareExecutionItemListEntry(\n  a: ExecutionItemListEntry,\n  b: ExecutionItemListEntry\n) {\n  return (\n    a.nodeId.localeCompare(b.nodeId, undefined, { numeric: true }) ||\n    a.label.localeCompare(b.label)\n  )\n}\n\nfunction isExecutionItemDetailExpanded(key: string) {\n  return expandedExecutionItemDetailKeys.value.has(key)\n}\n\nfunction toggleExecutionItemDetail(key: string) {\n  const nextKeys = new Set(expandedExecutionItemDetailKeys.value)\n  if (nextKeys.has(key)) {\n    nextKeys.delete(key)\n  } else {\n    nextKeys.add(key)\n    useTelemetry()?.trackUiButtonClicked({\n      button_id: 'error_tab_info_opened',\n      element_group: 'errors_panel'\n    })\n  }\n  expandedExecutionItemDetailKeys.value = nextKeys\n}\n\nfunction getExecutionItemDetailId(key: string) {\n  return `execution-item-detail-${key}`\n}\n\nconst {\n  allErrorGroups,\n  filteredGroups,\n  collapseState,\n  errorNodeCache,\n  missingNodeCache,\n  missingPackGroups,\n  missingModelGroups,\n  missingMediaGroups,\n  swapNodeGroups,\n  hasSelection,\n  selectedNodeCount,\n  selectedNodeTitle,\n  selectionMatchedGroupKeys,\n  selectionMatchedCardIds,\n  selectionMatchedAssetNodeIds,\n  selectionErrorCount,\n  errorNodeCount\n} = useErrorGroups(searchQuery)\n\nconst errorCount = computed(() =>\n  filteredGroups.value\n    .filter((group) => group.severity === 'error')\n    .reduce((sum, group) => sum + group.count, 0)\n)\nconst missingCount = computed(() =>\n  filteredGroups.value\n    .filter((group) => group.severity === 'missing')\n    .reduce((sum, group) => sum + group.count, 0)\n)\nconst hasMixedSeverity = computed(\n  () => errorCount.value > 0 && missingCount.value > 0\n)\n\nconst severityTotals = computed(() => {\n  const totals: Record<ErrorGroupSeverity, number> = { error: 0, missing: 0 }\n  for (const group of allErrorGroups.value) {\n    totals[group.severity] += group.count\n  }\n  return totals\n})\n\nconst severityFilter = ref<ErrorGroupSeverity | null>(null)\n// Workflow-wide, not search-scoped: a search emptying one severity must not\n// disable an engaged filter.\nconst hasMixedSeverityTotals = computed(\n  () => severityTotals.value.error > 0 && severityTotals.value.missing > 0\n)\nconst activeSeverityFilter = computed(() =>\n  hasMixedSeverityTotals.value ? severityFilter.value : null\n)\nconst visibleGroups = computed(() => {\n  const severity = activeSeverityFilter.value\n  if (!severity) return filteredGroups.value\n  return filteredGroups.value.filter((group) => group.severity === severity)\n})\n\nfunction toggleSeverityFilter(severity: ErrorGroupSeverity) {\n  severityFilter.value = severityFilter.value === severity ? null : severity\n}\n\n/**\n * Dedupes the Set-valued computed (fresh reference per recompute) so the\n * watchers below only fire when the matched membership changes.\n */\nconst selectionEmphasisSignature = computed(() =>\n  hasSelection.value\n    ? [\n        ...selectionMatchedGroupKeys.value,\n        ...selectionMatchedCardIds.value,\n        ...selectionMatchedAssetNodeIds.value\n      ]\n        .sort()\n        .join('\\n')\n    : ''\n)\n\n/** Issue identity per severity — membership, so same-count replacements are visible. */\nconst severityIssueKeys = computed<Record<ErrorGroupSeverity, Set<string>>>(\n  () => ({\n    error: new Set(\n      allErrorGroups.value\n        .filter((group) => group.type === 'execution')\n        .flatMap((group) =>\n          group.cards.flatMap((card) =>\n            card.errors.map(\n              (error, index) =>\n                `${group.groupKey}|${card.id}|${error.message}#${index}`\n            )\n          )\n        )\n    ),\n    missing: new Set([\n      ...missingPackGroups.value.flatMap((pack) =>\n        pack.nodeTypes.map(\n          (nodeType) =>\n            `pack|${pack.packId}|${typeof nodeType === 'string' ? nodeType : `${nodeType.type}|${nodeType.nodeId}`}`\n        )\n      ),\n      ...swapNodeGroups.value.flatMap((swap) =>\n        swap.nodeTypes.map(\n          (nodeType) =>\n            `swap|${swap.type}|${typeof nodeType === 'string' ? nodeType : nodeType.nodeId}`\n        )\n      ),\n      ...missingModelGroups.value.flatMap((group) =>\n        group.models.flatMap((model) =>\n          model.referencingNodes.map(\n            (ref) =>\n              `model|${group.directory}|${model.name}|${ref.nodeId}|${ref.widgetName}`\n          )\n        )\n      ),\n      ...missingMediaGroups.value.flatMap((group) =>\n        group.items.flatMap((item) =>\n          item.referencingNodes.map(\n            (ref) =>\n              `media|${group.mediaType}|${item.name}|${ref.nodeId}|${ref.widgetName}`\n          )\n        )\n      )\n    ])\n  })\n)\n\n// Release-only, never auto-select; an unchanged selection does not release,\n// since engaging the filter against it is the user's explicit call.\nwatch(severityIssueKeys, (next, prev) => {\n  const active = severityFilter.value\n  if (!active) return\n  const hidden = HIDDEN_BY_FILTER[active]\n  const hiddenGainedMember = [...next[hidden]].some(\n    (key) => !prev[hidden].has(key)\n  )\n  if (hiddenGainedMember || next[active].size === 0) {\n    severityFilter.value = null\n  }\n})\n\nwatch(selectionEmphasisSignature, () => {\n  const active = severityFilter.value\n  if (!active) return\n  const matchedKeys = selectionMatchedGroupKeys.value\n  if (matchedKeys.size === 0) return\n  const hidden = HIDDEN_BY_FILTER[active]\n  const selectionHasHiddenSeverity = allErrorGroups.value.some(\n    (group) => matchedKeys.has(group.groupKey) && group.severity === hidden\n  )\n  if (selectionHasHiddenSeverity) severityFilter.value = null\n})\n\nconst hero = computed(() => {\n  if (hasMixedSeverity.value) {\n    const total = errorCount.value + missingCount.value\n    return {\n      count: total,\n      countClass: 'text-base-foreground',\n      title: t('rightSidePanel.issuesDetected', total),\n      description: t('rightSidePanel.resolveBeforeRun')\n    }\n  }\n  if (missingCount.value > 0) {\n    return {\n      count: missingCount.value,\n      countClass: 'text-warning-foreground',\n      title: t('rightSidePanel.setupRequired'),\n      description: t('rightSidePanel.finishSetupBeforeRun')\n    }\n  }\n  return {\n    count: errorCount.value,\n    countClass: 'text-destructive-background-hover',\n    title: t('rightSidePanel.errorsDetected', errorCount.value),\n    description: t('rightSidePanel.resolveErrorsBeforeRun')\n  }\n})\n\nconst severityChips = computed(() => [\n  {\n    severity: 'error' as const,\n    active: activeSeverityFilter.value === 'error',\n    label:\n      activeSeverityFilter.value === 'error'\n        ? t('rightSidePanel.errorsFilterActive', errorCount.value)\n        : t('rightSidePanel.errorsFilter', errorCount.value)\n  },\n  {\n    severity: 'missing' as const,\n    active: activeSeverityFilter.value === 'missing',\n    label: t('rightSidePanel.setupFilter', missingCount.value)\n  }\n])\n\nconst hasSelectionEmphasis = computed(\n  () => hasSelection.value && selectionErrorCount.value > 0\n)\nconst selectionStripNodeLabel = computed(\n  () => selectedNodeTitle.value ?? t('g.untitled')\n)\n\n// The strip is a status line, not a view of the current filter — summary\n// numbers are workflow-wide, never search-filtered.\nconst workflowErrorCount = computed(\n  () => severityTotals.value.error + severityTotals.value.missing\n)\nconst workflowBlockingErrorCount = computed(() => severityTotals.value.error)\nconst hasErrorSeverity = computed(() => severityTotals.value.error > 0)\nconst hasMissingSeverity = computed(() => severityTotals.value.missing > 0)\n\nconst strip = computed<ContextStrip>(() => {\n  if (hasSelectionEmphasis.value) {\n    return {\n      keypath:\n        selectedNodeCount.value === 1\n          ? 'rightSidePanel.selectedNodeErrors'\n          : 'rightSidePanel.selectedNodesErrors',\n      nodes: selectedNodeCount.value,\n      count: selectionErrorCount.value\n    }\n  }\n  if (hasErrorSeverity.value && hasMissingSeverity.value) {\n    return {\n      keypath:\n        errorNodeCount.value === 0\n          ? 'rightSidePanel.errorsSummary'\n          : 'rightSidePanel.nodesAffected',\n      nodes: errorNodeCount.value,\n      count:\n        errorNodeCount.value === 0\n          ? workflowBlockingErrorCount.value\n          : errorNodeCount.value\n    }\n  }\n  const keypaths = hasErrorSeverity.value\n    ? SUMMARY_KEYPATHS.error\n    : SUMMARY_KEYPATHS.setup\n  const nodeCountKey =\n    errorNodeCount.value === 0\n      ? 'none'\n      : errorNodeCount.value === 1\n        ? 'single'\n        : 'multiple'\n\n  return {\n    keypath: keypaths[nodeCountKey],\n    nodes: errorNodeCount.value,\n    count: workflowErrorCount.value\n  }\n})\n\nfunction isCardInSelection(cardId: string): boolean {\n  return selectionMatchedCardIds.value.has(cardId)\n}\n\n/**\n * Selection acts as emphasis, not a filter: expand the groups containing\n * the selected nodes' errors and collapse the rest. When the emphasis ends\n * (selection cleared or moved to a node without errors), re-expand all\n * groups so the tab reads as the workflow overview again.\n */\nwatch(\n  selectionEmphasisSignature,\n  (signature, previousSignature) => {\n    if (!signature) {\n      if (!previousSignature) return\n      for (const groupKey of Object.keys(collapseState)) {\n        setSectionCollapsed(groupKey, false)\n      }\n      return\n    }\n    const matchedKeys = selectionMatchedGroupKeys.value\n    for (const group of allErrorGroups.value) {\n      setSectionCollapsed(group.groupKey, !matchedKeys.has(group.groupKey))\n    }\n  },\n  { immediate: true }\n)\n\nconst showMissingModelHeaderRefresh = computed(\n  () => !isCloud && missingModelGroups.value.length > 0\n)\n\nfunction handleMissingModelRefresh() {\n  if (missingModelStore.isRefreshingMissingModels) return\n\n  void missingModelStore.refreshMissingModels()\n}\n\nconst isAllCollapsed = computed({\n  get() {\n    return filteredGroups.value.every((g) => isSectionCollapsed(g.groupKey))\n  },\n  set(collapse: boolean) {\n    for (const group of allErrorGroups.value) {\n      setSectionCollapsed(group.groupKey, collapse)\n    }\n  }\n})\n\nfunction isSectionCollapsed(groupKey: string): boolean {\n  // Defaults to expanded when not explicitly set by the user\n  return collapseState[groupKey] ?? false\n}\n\nfunction setSectionCollapsed(groupKey: string, collapsed: boolean) {\n  collapseState[groupKey] = collapsed\n}\n\n/**\n * When an external trigger (e.g. \"See Error\" button in SectionWidgets)\n * sets focusedErrorNodeId, expand only the group containing the target\n * node and collapse all others so the user sees the relevant errors\n * immediately.\n */\nwatch(\n  () => rightSidePanelStore.focusedErrorNodeId,\n  (graphNodeId) => {\n    if (!graphNodeId) return\n    const prefix = `${graphNodeId}:`\n    for (const group of allErrorGroups.value) {\n      if (group.type !== 'execution') continue\n\n      const hasMatch = group.cards.some(\n        (card) =>\n          card.graphNodeId === graphNodeId ||\n          (card.nodeId?.startsWith(prefix) ?? false)\n      )\n      setSectionCollapsed(group.groupKey, !hasMatch)\n    }\n    rightSidePanelStore.focusedErrorNodeId = null\n  },\n  { immediate: true }\n)\n\nfunction handleLocateNode(nodeId: string) {\n  focusNode(nodeId, errorNodeCache.value)\n}\n\nfunction handleLocateMissingNode(nodeId: string) {\n  focusNode(nodeId, missingNodeCache.value)\n}\n\nfunction handleLocateAssetNode(nodeId: string) {\n  focusNode(nodeId)\n}\n\nfunction handleOpenManagerInfo(packId: string) {\n  const isKnownToRegistry = missingNodePacks.value.some((p) => p.id === packId)\n  if (isKnownToRegistry) {\n    openManager({ initialTab: ManagerTab.Missing, initialPackId: packId })\n  } else {\n    openManager({ initialTab: ManagerTab.All, initialPackId: packId })\n  }\n}\n\nfunction handleReplaceGroup(group: SwapNodeGroup) {\n  replaceGroup(group)\n}\n\nfunction handleReplaceAll() {\n  replaceAllGroups(swapNodeGroups.value)\n}\n</script>\n","<template>\n  <div class=\"flex h-full min-w-0 flex-col\">\n    <ErrorGroupList class=\"min-h-0 flex-1\" />\n\n    <ErrorPanelSurveyCta v-if=\"ErrorPanelSurveyCta\" />\n\n    <!-- Fixed Footer: Help Links -->\n    <div\n      class=\"min-w-0 shrink-0 border-t border-interface-stroke bg-interface-panel-surface p-4\"\n    >\n      <i18n-t\n        keypath=\"rightSidePanel.errorHelp\"\n        tag=\"p\"\n        class=\"m-0 text-sm/tight wrap-break-word text-muted-foreground\"\n      >\n        <template #github>\n          <Button\n            variant=\"textonly\"\n            size=\"unset\"\n            class=\"inline text-sm whitespace-nowrap text-inherit underline\"\n            @click=\"openGitHubIssues\"\n          >\n            {{ t('rightSidePanel.errorHelpGithub') }}\n          </Button>\n        </template>\n        <template #support>\n          <Button\n            variant=\"textonly\"\n            size=\"unset\"\n            class=\"inline text-sm whitespace-nowrap text-inherit underline\"\n            @click=\"contactSupport\"\n          >\n            {{ t('rightSidePanel.errorHelpSupport') }}\n          </Button>\n        </template>\n      </i18n-t>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { defineAsyncComponent } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { isCloud, isDesktop, isNightly } from '@/platform/distribution/types'\n\nimport ErrorGroupList from './ErrorGroupList.vue'\nimport { useErrorActions } from './useErrorActions'\n\nconst ErrorPanelSurveyCta =\n  isNightly && !isCloud && !isDesktop\n    ? defineAsyncComponent(\n        () => import('@/platform/surveys/ErrorPanelSurveyCta.vue')\n      )\n    : undefined\n\nconst { t } = useI18n()\nconst { openGitHubIssues, contactSupport } = useErrorActions()\n</script>\n","import { computed } from 'vue'\n\nimport { useErrorClassification } from './useErrorClassification'\n\nexport function useHasBlockingError() {\n  const errorClassification = useErrorClassification()\n\n  return computed(() => errorClassification.value.hasBlockingError)\n}\n","<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport { computed, provide, ref, watchEffect } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport EditableText from '@/components/common/EditableText.vue'\nimport Tab from '@/components/tab/Tab.vue'\nimport TabList from '@/components/tab/TabList.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useGraphHierarchy } from '@/composables/graph/useGraphHierarchy'\nimport { app } from '@/scripts/app'\nimport {\n  getActiveGraphNodeIds,\n  getExecutionIdByNode\n} from '@/utils/graphTraversalUtil'\nimport { SubgraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useMissingNodesErrorStore } from '@/platform/nodeReplacement/missingNodesErrorStore'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\nimport type { RightSidePanelTab } from '@/stores/workspace/rightSidePanelStore'\nimport { resolveNodeDisplayName } from '@/utils/nodeTitleUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport TabInfo from './info/TabInfo.vue'\nimport TabGlobalParameters from './parameters/TabGlobalParameters.vue'\nimport TabNodes from './parameters/TabNodes.vue'\nimport TabNormalInputs from './parameters/TabNormalInputs.vue'\nimport TabSubgraphInputs from './parameters/TabSubgraphInputs.vue'\nimport { trackRightSidePanelTabOpened } from './rightSidePanelTabTelemetry'\nimport TabGlobalSettings from './settings/TabGlobalSettings.vue'\nimport TabSettings from './settings/TabSettings.vue'\nimport {\n  GetNodeParentGroupKey,\n  useFlatAndCategorizeSelectedItems\n} from './shared'\nimport SubgraphEditor from './subgraph/SubgraphEditor.vue'\nimport TabErrors from './errors/TabErrors.vue'\nimport { useHasBlockingError } from './errors/useHasBlockingError'\n\nconst canvasStore = useCanvasStore()\nconst workflowStore = useWorkflowStore()\nconst executionErrorStore = useExecutionErrorStore()\nconst missingModelStore = useMissingModelStore()\nconst missingMediaStore = useMissingMediaStore()\nconst missingNodesErrorStore = useMissingNodesErrorStore()\nconst rightSidePanelStore = useRightSidePanelStore()\nconst settingStore = useSettingStore()\nconst { t } = useI18n()\n\nconst { hasAnyError, allErrorExecutionIds } = storeToRefs(executionErrorStore)\n\nconst activeMissingNodeGraphIds = computed<Set<string>>(() => {\n  if (!app.isGraphReady) return new Set()\n  return getActiveGraphNodeIds(\n    app.rootGraph,\n    canvasStore.currentGraph ?? app.rootGraph,\n    missingNodesErrorStore.missingAncestorExecutionIds\n  )\n})\n\nconst { activeMissingModelGraphIds } = storeToRefs(missingModelStore)\nconst { activeMissingMediaGraphIds } = storeToRefs(missingMediaStore)\n\nconst { findParentGroup } = useGraphHierarchy()\n\nconst { selectedItems: directlySelectedItems } = storeToRefs(canvasStore)\nconst { activeTab, isEditingSubgraph } = storeToRefs(rightSidePanelStore)\n\nconst sidebarLocation = computed<'left' | 'right'>(() =>\n  settingStore.get('Comfy.Sidebar.Location')\n)\n\n// Panel is on the left when sidebar is on the right, and vice versa\nconst panelIcon = computed(() =>\n  sidebarLocation.value === 'right'\n    ? 'icon-[lucide--panel-left]'\n    : 'icon-[lucide--panel-right]'\n)\n\nconst { flattedItems, selectedNodes, selectedGroups, nodeToParentGroup } =\n  useFlatAndCategorizeSelectedItems(directlySelectedItems)\n\nconst shouldShowGroupNames = computed(() => {\n  return !(\n    directlySelectedItems.value.length === 1 &&\n    (selectedGroups.value.length === 1 || selectedNodes.value.length === 1)\n  )\n})\n\nprovide(GetNodeParentGroupKey, (node: LGraphNode) => {\n  if (!shouldShowGroupNames.value) return null\n  return nodeToParentGroup.value.get(node) ?? findParentGroup(node)\n})\n\nconst hasSelection = computed(() => flattedItems.value.length > 0)\n\nconst selectedSingleNode = computed(() => {\n  return selectedNodes.value.length === 1 && flattedItems.value.length === 1\n    ? selectedNodes.value[0]\n    : null\n})\n\nconst isSingleSubgraphNode = computed(() => {\n  return selectedSingleNode.value instanceof SubgraphNode\n})\n\nconst workflowKey = computed(() => workflowStore.activeWorkflow?.path ?? '')\n\nconst selectedNodesKey = computed(() => {\n  const nodeIds = selectedNodes.value.map((n) => n.id).join(',')\n  const groupIds = selectedGroups.value.map((g) => g.id).join(',')\n  return `${workflowKey.value}|${nodeIds}|${groupIds}`\n})\n\nconst singleSubgraphKey = computed(() =>\n  selectedSingleNode.value\n    ? `${workflowKey.value}:${selectedSingleNode.value.id}`\n    : ''\n)\n\nfunction closePanel() {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'right_side_panel_closed',\n    element_group: 'right_side_panel'\n  })\n  rightSidePanelStore.closePanel()\n}\n\nfunction handleTabChange(newTab: RightSidePanelTab) {\n  trackRightSidePanelTabOpened(newTab)\n  rightSidePanelStore.openPanel(newTab)\n}\n\ntype RightSidePanelTabList = Array<{\n  label: () => string\n  value: RightSidePanelTab\n  icon?: {\n    className: string\n    label: () => string\n  }\n}>\n\nconst hasDirectNodeError = computed(() =>\n  selectedNodes.value.some((node) =>\n    executionErrorStore.activeGraphErrorNodeIds.has(String(node.id))\n  )\n)\n\nconst hasContainerInternalError = computed(() => {\n  if (allErrorExecutionIds.value.length === 0) return false\n  return selectedNodes.value.some((node) => {\n    if (!(node instanceof SubgraphNode)) return false\n    return executionErrorStore.isContainerWithInternalError(node)\n  })\n})\n\nconst hasMissingNodeSelected = computed(\n  () =>\n    hasSelection.value &&\n    selectedNodes.value.some((node) =>\n      activeMissingNodeGraphIds.value.has(String(node.id))\n    )\n)\n\nconst hasMissingModelSelected = computed(\n  () =>\n    hasSelection.value &&\n    selectedNodes.value.some((node) =>\n      activeMissingModelGraphIds.value.has(String(node.id))\n    )\n)\n\nconst hasMissingMediaSelected = computed(\n  () =>\n    hasSelection.value &&\n    selectedNodes.value.some((node) =>\n      activeMissingMediaGraphIds.value.has(String(node.id))\n    )\n)\n\nconst hasRelevantErrors = computed(() => {\n  if (!hasSelection.value) return hasAnyError.value\n  return (\n    hasDirectNodeError.value ||\n    hasContainerInternalError.value ||\n    hasMissingNodeSelected.value ||\n    hasMissingModelSelected.value ||\n    hasMissingMediaSelected.value\n  )\n})\n\nconst hasPendingErrorScanSelected = computed(() => {\n  const nodes = selectedNodes.value\n  if (!app.isGraphReady) return false\n  const rootGraph = app.rootGraph\n  return nodes.some((node) => {\n    const executionId = getExecutionIdByNode(rootGraph, node)\n    return (\n      executionId !== null &&\n      executionErrorStore.hasPendingAddedNodeErrorScan(rootGraph, executionId)\n    )\n  })\n})\n\nconst hasBlockingError = useHasBlockingError()\n\nconst tabs = computed<RightSidePanelTabList>(() => {\n  const list: RightSidePanelTabList = []\n\n  if (\n    settingStore.get('Comfy.RightSidePanel.ShowErrorsTab') &&\n    (hasRelevantErrors.value ||\n      (activeTab.value === 'errors' && hasPendingErrorScanSelected.value))\n  ) {\n    list.push({\n      label: () => t('rightSidePanel.errors'),\n      value: 'errors',\n      // No icon while the tab is only retained by a pending scan: with both\n      // severities absent there is no state for it to describe.\n      icon: hasRelevantErrors.value\n        ? {\n            className: cn(\n              'ml-1',\n              hasBlockingError.value\n                ? 'icon-[lucide--octagon-alert] bg-node-stroke-error'\n                : 'icon-[lucide--triangle-alert] bg-warning-foreground'\n            ),\n            label: () =>\n              t(\n                hasBlockingError.value\n                  ? 'rightSidePanel.severityErrorLabel'\n                  : 'rightSidePanel.severitySetupLabel'\n              )\n          }\n        : undefined\n    })\n  }\n\n  list.push({\n    label: () =>\n      flattedItems.value.length > 1\n        ? t('rightSidePanel.nodes')\n        : t('rightSidePanel.parameters'),\n    value: 'parameters'\n  })\n\n  if (!hasSelection.value) {\n    list.push({\n      label: () => t('rightSidePanel.nodes'),\n      value: 'nodes'\n    })\n  }\n\n  if (hasSelection.value) {\n    if (selectedSingleNode.value && !isSingleSubgraphNode.value) {\n      list.push({\n        label: () => t('rightSidePanel.info'),\n        value: 'info'\n      })\n    }\n  }\n\n  list.push({\n    label: () =>\n      hasSelection.value\n        ? t('g.settings')\n        : t('rightSidePanel.globalSettings.title'),\n    value: 'settings'\n  })\n\n  return list\n})\n\nfunction isActiveTabAvailable() {\n  return (\n    tabs.value.some((tab) => tab.value === activeTab.value) ||\n    (activeTab.value === 'subgraph' && isSingleSubgraphNode.value)\n  )\n}\n\nwatchEffect(() => {\n  if (!isActiveTabAvailable()) {\n    rightSidePanelStore.openPanel(tabs.value[0].value)\n  }\n})\n\nfunction resolveTitle() {\n  const items = flattedItems.value\n  const nodes = selectedNodes.value\n  const groups = selectedGroups.value\n\n  if (items.length === 0) {\n    return t('rightSidePanel.workflowOverview')\n  }\n  if (directlySelectedItems.value.length === 1) {\n    if (groups.length === 1) {\n      return groups[0].title || t('rightSidePanel.fallbackGroupTitle')\n    }\n    if (nodes.length === 1) {\n      const fallbackNodeTitle = t('rightSidePanel.fallbackNodeTitle')\n      return resolveNodeDisplayName(nodes[0], {\n        emptyLabel: fallbackNodeTitle,\n        untitledLabel: fallbackNodeTitle\n      })\n    }\n  }\n  return t('rightSidePanel.title', { count: items.length })\n}\n\nconst panelTitle = ref(resolveTitle())\nwatchEffect(() => (panelTitle.value = resolveTitle()))\n\nconst isEditing = ref(false)\n\nconst allowTitleEdit = computed(() => {\n  return (\n    directlySelectedItems.value.length === 1 &&\n    (selectedGroups.value.length === 1 || selectedNodes.value.length === 1)\n  )\n})\n\nfunction handleTitleEdit(newTitle: string) {\n  isEditing.value = false\n\n  const trimmedTitle = newTitle.trim()\n  if (!trimmedTitle) return\n\n  const node = selectedGroups.value[0] || selectedNodes.value[0]\n  if (!node) return\n\n  if (trimmedTitle === node.title) return\n\n  node.title = trimmedTitle\n  panelTitle.value = trimmedTitle\n  canvasStore.canvas?.setDirty(true, true)\n}\n\nfunction handleTitleCancel() {\n  isEditing.value = false\n}\n</script>\n\n<template>\n  <div\n    data-testid=\"properties-panel\"\n    class=\"flex size-full flex-col bg-comfy-menu-bg\"\n  >\n    <!-- Panel Header -->\n    <section class=\"pt-1\">\n      <div class=\"flex items-center justify-between pr-3 pl-4\">\n        <h3 class=\"my-3.5 line-clamp-2 cursor-default text-sm font-semibold\">\n          <template v-if=\"allowTitleEdit\">\n            <EditableText\n              :model-value=\"panelTitle\"\n              :is-editing=\"isEditing\"\n              :input-attrs=\"{ 'data-testid': 'node-title-input' }\"\n              class=\"cursor-text\"\n              @edit=\"handleTitleEdit\"\n              @cancel=\"handleTitleCancel\"\n              @click=\"isEditing = true\"\n            />\n            <Button\n              v-if=\"!isEditing\"\n              variant=\"link\"\n              size=\"unset\"\n              :aria-label=\"t('rightSidePanel.editTitle')\"\n              class=\"relative top-[2px] ml-2 shrink-0\"\n              @click=\"isEditing = true\"\n            >\n              <i aria-hidden=\"true\" class=\"icon-[lucide--pencil] size-4\" />\n            </Button>\n          </template>\n          <template v-else>\n            {{ panelTitle }}\n          </template>\n        </h3>\n\n        <div class=\"flex gap-2\">\n          <Button\n            v-if=\"isSingleSubgraphNode\"\n            variant=\"secondary\"\n            size=\"icon\"\n            data-testid=\"subgraph-editor-toggle\"\n            :aria-label=\"t('rightSidePanel.editSubgraph')\"\n            :class=\"cn(isEditingSubgraph && 'bg-secondary-background-selected')\"\n            @click=\"\n              rightSidePanelStore.openPanel(\n                isEditingSubgraph ? 'parameters' : 'subgraph'\n              )\n            \"\n          >\n            <i class=\"icon-[lucide--settings-2]\" />\n          </Button>\n          <Button\n            variant=\"secondary\"\n            size=\"icon\"\n            :aria-pressed=\"rightSidePanelStore.isOpen\"\n            :aria-label=\"t('rightSidePanel.togglePanel')\"\n            @click=\"closePanel\"\n          >\n            <i :class=\"cn(panelIcon, 'size-4')\" />\n          </Button>\n        </div>\n      </div>\n      <nav class=\"overflow-x-auto px-4 pt-1 pb-2\">\n        <TabList :model-value=\"activeTab\" @update:model-value=\"handleTabChange\">\n          <Tab\n            v-for=\"tab in tabs\"\n            :key=\"tab.value\"\n            class=\"px-2 py-1 font-inter text-sm transition-all active:scale-95\"\n            :value=\"tab.value\"\n            :data-testid=\"`panel-tab-${tab.value}`\"\n          >\n            {{ tab.label() }}\n            <i\n              v-if=\"tab.icon\"\n              role=\"img\"\n              :aria-label=\"tab.icon.label()\"\n              data-testid=\"panel-tab-icon\"\n              :class=\"cn(tab.icon.className, 'size-4')\"\n            />\n          </Tab>\n        </TabList>\n      </nav>\n    </section>\n\n    <!-- Panel Content -->\n    <div class=\"flex-1 scrollbar-thin overflow-y-auto\">\n      <TabErrors v-if=\"activeTab === 'errors'\" />\n      <template v-else-if=\"!hasSelection\">\n        <TabGlobalParameters\n          v-if=\"activeTab === 'parameters'\"\n          :key=\"workflowKey\"\n        />\n        <TabNodes v-else-if=\"activeTab === 'nodes'\" :key=\"workflowKey\" />\n        <TabGlobalSettings v-else-if=\"activeTab === 'settings'\" />\n      </template>\n      <SubgraphEditor\n        v-else-if=\"isSingleSubgraphNode && isEditingSubgraph\"\n        :key=\"singleSubgraphKey\"\n        :node=\"selectedSingleNode\"\n      />\n      <template v-else>\n        <TabSubgraphInputs\n          v-if=\"activeTab === 'parameters' && isSingleSubgraphNode\"\n          :key=\"singleSubgraphKey\"\n          :node=\"selectedSingleNode as SubgraphNode\"\n        />\n        <TabNormalInputs\n          v-else-if=\"activeTab === 'parameters'\"\n          :key=\"selectedNodesKey\"\n          :nodes=\"selectedNodes\"\n          :must-show-node-title=\"selectedGroups.length > 0\"\n        />\n        <TabInfo v-else-if=\"activeTab === 'info'\" :nodes=\"selectedNodes\" />\n        <TabSettings\n          v-else-if=\"activeTab === 'settings'\"\n          :nodes=\"flattedItems\"\n        />\n      </template>\n    </div>\n  </div>\n</template>\n","import type { Component, ComputedRef } from 'vue'\nimport { computed, defineAsyncComponent, watch } from 'vue'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useAgentPanelStore } from '@/workbench/extensions/agent/stores/agent/agentPanelStore'\n\nimport { useBillingIdentity } from './useBillingIdentity'\n\ninterface AgentDockMount {\n  docked: ComputedRef<boolean>\n  DockedAgentPanel: Component | null\n}\n\n/**\n * The one distribution seam for the dock mounts. The literal comparison is\n * what dead-code-eliminates the store and both panel component chunks from\n * OSS builds; on cloud the async component is only requested once the gate\n * enables and opens the panel, so a flag-off session fetches no agent chunk.\n */\nexport function useAgentDockMount(): AgentDockMount {\n  // The local agent harness (VITE_AGENT_STANDALONE) mounts the panel in any\n  // distribution; production keeps it cloud-only.\n  if (\n    __DISTRIBUTION__ !== 'cloud' &&\n    import.meta.env.VITE_AGENT_STANDALONE !== 'true'\n  ) {\n    return { docked: computed(() => false), DockedAgentPanel: null }\n  }\n  const agentPanelStore = useAgentPanelStore()\n  const { subscription } = useBillingContext()\n\n  // This composable is owned by the persistent graph/linear hosts, unlike the\n  // dock component, which is unmounted whenever the panel closes. Keep the\n  // exhaustion episode synchronized here so funds recovery while closed can\n  // re-arm the next impression.\n  watch(\n    () => subscription.value?.agentHasFunds,\n    (hasFunds) => {\n      if (hasFunds === true) agentPanelStore.reportedExhaustionIdentity = null\n    },\n    { immediate: true }\n  )\n\n  const billingIdentity = useBillingIdentity()\n\n  watch(\n    [billingIdentity, () => subscription.value?.agentScopedHasFunds],\n    ([identity, scopedHasFunds]) => {\n      if (scopedHasFunds === undefined) return\n      agentPanelStore.observeAgentScopedFunds(identity, scopedHasFunds)\n    },\n    { immediate: true }\n  )\n\n  return {\n    docked: computed(() => agentPanelStore.isVisible),\n    DockedAgentPanel: defineAsyncComponent(\n      () =>\n        import('@/workbench/extensions/agent/components/agent/DockedAgentPanel.vue')\n    )\n  }\n}\n","import { isEqual } from 'es-toolkit'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { InputSpec as InputSpecV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport {\n  dynamicComboOptionTypes,\n  inputSpecTree\n} from '@/schemas/nodeDef/inputSpecTree'\n\n/**\n * Select DynamicCombo options so that `node` exposes a socket of `wantedType`.\n *\n * Node search reports the union of every DynamicCombo option's input types, so\n * a node can be offered for a link type whose socket only exists under an\n * option the node was not created with.\n *\n * Only reports success once the socket actually exists. A combo option's types\n * include types reachable through a *nested* combo, which selecting the outer\n * option alone does not materialize, so the result is verified rather than\n * assumed; any selection made while failing is rolled back so a failed reveal\n * leaves the node exactly as it was.\n *\n * @returns whether the node now exposes `wantedType`\n */\nexport function revealDynamicInputSlot(\n  node: LGraphNode,\n  wantedType: string\n): boolean {\n  if (node.findInputByType(wantedType)) return false\n\n  const defInputs = node.constructor.nodeData?.inputs\n  if (!defInputs) return false\n\n  // Each root input is attempted independently so a root that fails cannot\n  // leave a combo selected on the way to a different root that succeeds.\n  for (const rootSpec of Object.values(defInputs)) {\n    if (revealWithin(node, rootSpec, wantedType)) return true\n  }\n\n  return false\n}\n\nfunction revealWithin(\n  node: LGraphNode,\n  rootSpec: InputSpecV2,\n  wantedType: string\n): boolean {\n  const comboSpecs = inputSpecTree(rootSpec).filter(\n    (spec) => spec.type === 'COMFY_DYNAMICCOMBO_V3'\n  )\n  return revealFromCombo(node, comboSpecs, wantedType, 0, new Set())\n}\n\nfunction revealFromCombo(\n  node: LGraphNode,\n  comboSpecs: InputSpecV2[],\n  wantedType: string,\n  startIndex: number,\n  usedWidgets: Set<IBaseWidget>\n): boolean {\n  const widgets = node.widgets\n  if (!widgets) return false\n\n  for (let index = startIndex; index < comboSpecs.length; index++) {\n    const spec = comboSpecs[index]\n    const options = dynamicComboOptionTypes(spec)\n    const matchingOptions = options.filter(({ types }) =>\n      types.includes(wantedType)\n    )\n    if (!matchingOptions.length) continue\n\n    const candidates = matchingWidgets(\n      widgets,\n      spec,\n      options.map(({ key }) => key),\n      usedWidgets\n    )\n\n    for (const option of matchingOptions) {\n      for (const widget of candidates) {\n        if (\n          tryOption(\n            node,\n            comboSpecs,\n            wantedType,\n            index,\n            usedWidgets,\n            widget,\n            option.key\n          )\n        )\n          return true\n      }\n    }\n  }\n  return false\n}\n\nfunction matchingWidgets(\n  widgets: IBaseWidget[],\n  spec: InputSpecV2,\n  keys: string[],\n  usedWidgets: Set<IBaseWidget>\n): IBaseWidget[] {\n  return widgets\n    .filter(\n      (widget) =>\n        !usedWidgets.has(widget) &&\n        (widget.name === spec.name || isEqual(widget.options.values, keys))\n    )\n    .sort((a, b) => Number(b.name === spec.name) - Number(a.name === spec.name))\n}\n\nfunction tryOption(\n  node: LGraphNode,\n  comboSpecs: InputSpecV2[],\n  wantedType: string,\n  index: number,\n  usedWidgets: Set<IBaseWidget>,\n  widget: IBaseWidget,\n  optionKey: string\n): boolean {\n  const previousValue = widget.value\n  widget.value = optionKey\n\n  const revealed =\n    Boolean(node.findInputByType(wantedType)) ||\n    revealFromCombo(\n      node,\n      comboSpecs,\n      wantedType,\n      index + 1,\n      new Set(usedWidgets).add(widget)\n    )\n\n  if (!revealed) widget.value = previousValue\n  return revealed\n}\n","import { useMouse } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { computed, ref, shallowRef } from 'vue'\n\nimport type NodeSearchBoxPopover from '@/components/searchbox/NodeSearchBoxPopover.vue'\nimport type { LGraphCanvas } from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\nexport const useSearchBoxStore = defineStore('searchBox', () => {\n  const settingStore = useSettingStore()\n  const canvasStore = useCanvasStore()\n  const { x, y } = useMouse({ type: 'client' })\n\n  const useSearchBoxV2 = computed(\n    () => settingStore.get('Comfy.NodeSearchBoxImpl') === 'default'\n  )\n\n  const newSearchBoxEnabled = computed(\n    () => settingStore.get('Comfy.NodeSearchBoxImpl') !== 'litegraph (legacy)'\n  )\n\n  type SearchBoxPopover = Pick<\n    InstanceType<typeof NodeSearchBoxPopover>,\n    'showSearchBox'\n  >\n  const popoverRef = shallowRef<SearchBoxPopover | null>(null)\n\n  function setPopoverRef(popover: SearchBoxPopover | null) {\n    popoverRef.value = popover\n  }\n\n  const visible = ref(false)\n  function toggleVisible() {\n    if (newSearchBoxEnabled.value) {\n      visible.value = !visible.value\n      return\n    }\n    if (!popoverRef.value) return\n    const event = new PointerEvent('click', {\n      clientX: x.value,\n      clientY: y.value\n    })\n    const canvas: LGraphCanvas = canvasStore.getCanvas()\n    canvas.adjustMouseEvent(event)\n    popoverRef.value.showSearchBox(event)\n  }\n\n  return {\n    useSearchBoxV2,\n    newSearchBoxEnabled,\n    setPopoverRef,\n    toggleVisible,\n    visible\n  }\n})\n","export enum LinkReleaseTriggerAction {\n  CONTEXT_MENU = 'context menu',\n  SEARCH_BOX = 'search box',\n  NO_ACTION = 'no action'\n}\n","<template>\n  <span v-if=\"nodeDef.api_node && priceLabel\">\n    <CreditBadge :text=\"priceLabel\" />\n  </span>\n</template>\n\n<script setup lang=\"ts\">\nimport { evaluateNodeDefPricing } from '@comfyorg/shared-frontend-utils/nodePricing'\nimport { ref, watch } from 'vue'\n\nimport CreditBadge from '@/components/node/CreditBadge.vue'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\n\nconst { nodeDef } = defineProps<{\n  nodeDef: ComfyNodeDefImpl\n}>()\n\nconst priceLabel = ref('')\n\nwatch(\n  () => nodeDef.name,\n  (name) => {\n    if (!nodeDef.api_node) {\n      priceLabel.value = ''\n      return\n    }\n    const capturedName = name\n    evaluateNodeDefPricing(nodeDef)\n      .then((label) => {\n        if (nodeDef.name === capturedName) priceLabel.value = label\n      })\n      .catch((e) => {\n        console.error('[NodePricingBadge] pricing evaluation failed:', e)\n      })\n  },\n  { immediate: true }\n)\n</script>\n","<template>\n  <span\n    data-testid=\"badge-pill\"\n    :class=\"\n      cn(\n        'flex items-center gap-1 rounded-sm border px-1.5 py-0.5 text-2xs',\n        textColorClass\n      )\n    \"\n    :style=\"customStyle\"\n  >\n    <i\n      v-if=\"icon\"\n      data-testid=\"badge-icon\"\n      :class=\"cn(icon, 'size-2.5', iconClass)\"\n    />\n    <slot>{{ text }}</slot>\n  </span>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { borderStyle, filled } = defineProps<{\n  text?: string\n  icon?: string\n  iconClass?: string\n  borderStyle?: string\n  filled?: boolean\n}>()\n\nconst textColorClass = computed(() =>\n  borderStyle && filled ? '' : 'text-base-foreground'\n)\n\nconst customStyle = computed(() => {\n  if (!borderStyle) {\n    return { borderColor: 'var(--border-color)' }\n  }\n\n  const isGradient = borderStyle.includes('linear-gradient')\n  if (isGradient) {\n    return {\n      borderColor: 'transparent',\n      backgroundImage: `linear-gradient(var(--base-background), var(--base-background)), ${borderStyle}`,\n      backgroundOrigin: 'border-box',\n      backgroundClip: 'padding-box, border-box'\n    }\n  }\n\n  if (filled) {\n    return {\n      borderColor: borderStyle,\n      backgroundColor: `${borderStyle}33`,\n      color: borderStyle\n    }\n  }\n\n  return { borderColor: borderStyle }\n})\n</script>\n","<template>\n  <BadgePill\n    v-if=\"nodeDef.api_node && providerName\"\n    :text=\"providerName\"\n    :icon=\"getProviderIcon(providerName)\"\n    :border-style=\"getProviderBorderStyle(providerName)\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport BadgePill from '@/components/common/BadgePill.vue'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport {\n  getProviderBorderStyle,\n  getProviderIcon,\n  getProviderName\n} from '@/utils/categoryUtil'\n\nconst { nodeDef } = defineProps<{\n  nodeDef: ComfyNodeDefImpl\n}>()\n\nconst providerName = computed(() => getProviderName(nodeDef.category))\n</script>\n","<template>\n  <div\n    class=\"flex flex-col overflow-hidden rounded-lg border border-border-default bg-base-background\"\n    :style=\"{ width: `${BASE_WIDTH_PX * (scaleFactor / BASE_SCALE)}px` }\"\n    data-testid=\"node-preview-card\"\n  >\n    <div ref=\"previewContainerRef\" class=\"overflow-hidden p-3\">\n      <div\n        ref=\"previewWrapperRef\"\n        class=\"origin-top-left\"\n        :style=\"{ transform: `scale(${scaleFactor})` }\"\n      >\n        <LGraphNodePreview :node-def=\"nodeDef\" position=\"relative\" />\n      </div>\n    </div>\n\n    <!-- Content Section -->\n    <div class=\"flex flex-col gap-2 p-3 pt-1\">\n      <!-- Title -->\n      <h3 class=\"m-0 text-xs font-semibold text-base-foreground\">\n        {{ nodeDef.display_name }}\n      </h3>\n\n      <!-- Category Path -->\n      <p\n        v-if=\"showCategoryPath && nodeDef.category\"\n        class=\"-mt-1 truncate text-xs text-muted-foreground\"\n      >\n        {{ categoryPath }}\n      </p>\n\n      <!-- Badges -->\n      <div class=\"flex flex-wrap gap-2 overflow-hidden empty:hidden\">\n        <NodePricingBadge class=\"max-w-full truncate\" :node-def=\"nodeDef\" />\n        <NodeProviderBadge :node-def=\"nodeDef\" />\n      </div>\n\n      <!-- Description -->\n      <p\n        v-if=\"nodeDef.description\"\n        class=\"m-0 max-h-[30vh] overflow-y-auto text-2xs/normal font-normal text-muted-foreground\"\n      >\n        {{ nodeDef.description }}\n      </p>\n\n      <!-- Divider -->\n      <div\n        v-if=\"(inputs.length > 0 || outputs.length > 0) && showInputsAndOutputs\"\n        class=\"border-t border-border-default\"\n      />\n\n      <!-- Inputs Section -->\n      <div\n        v-if=\"inputs.length > 0 && showInputsAndOutputs\"\n        class=\"flex flex-col gap-1\"\n        data-testid=\"node-preview-inputs\"\n      >\n        <h4\n          class=\"m-0 text-2xs font-semibold tracking-wide text-muted-foreground uppercase\"\n        >\n          {{ $t('nodeHelpPage.inputs') }}\n        </h4>\n        <div\n          v-for=\"input in inputs\"\n          :key=\"input.name\"\n          class=\"flex items-center justify-between gap-2 text-2xs\"\n        >\n          <span class=\"shrink-0 text-base-foreground\">{{ input.name }}</span>\n          <span class=\"min-w-0 truncate text-muted-foreground\">{{\n            input.type\n          }}</span>\n        </div>\n      </div>\n\n      <!-- Outputs Section -->\n      <div\n        v-if=\"outputs.length > 0 && showInputsAndOutputs\"\n        class=\"flex flex-col gap-1\"\n      >\n        <h4\n          class=\"m-0 text-2xs font-semibold tracking-wide text-muted-foreground uppercase\"\n        >\n          {{ $t('nodeHelpPage.outputs') }}\n        </h4>\n        <div\n          v-for=\"output in outputs\"\n          :key=\"output.name\"\n          class=\"flex items-center justify-between gap-2 text-2xs\"\n        >\n          <span class=\"shrink-0 text-base-foreground\">{{ output.name }}</span>\n          <span class=\"min-w-0 truncate text-muted-foreground\">{{\n            output.type\n          }}</span>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useResizeObserver } from '@vueuse/core'\nimport { computed, ref } from 'vue'\n\nimport NodePricingBadge from '@/components/node/NodePricingBadge.vue'\nimport NodeProviderBadge from '@/components/node/NodeProviderBadge.vue'\nimport LGraphNodePreview from '@/renderer/extensions/vueNodes/components/LGraphNodePreview.vue'\nimport { flattenInputSpecs } from '@/schemas/nodeDef/inputSpecUtil'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\n\nconst BASE_WIDTH_PX = 200\nconst BASE_SCALE = 0.5\nconst PREVIEW_CONTAINER_PADDING_PX = 24\n\nconst {\n  nodeDef,\n  showInputsAndOutputs = true,\n  showCategoryPath = false,\n  scaleFactor = 0.5\n} = defineProps<{\n  nodeDef: ComfyNodeDefImpl\n  showInputsAndOutputs?: boolean\n  showCategoryPath?: boolean\n  scaleFactor?: number\n}>()\n\nconst previewContainerRef = ref<HTMLElement>()\nconst previewWrapperRef = ref<HTMLElement>()\n\nuseResizeObserver(previewWrapperRef, (entries) => {\n  const entry = entries[0]\n  if (entry && previewContainerRef.value) {\n    const scaledHeight = entry.contentRect.height * scaleFactor\n    previewContainerRef.value.style.height = `${scaledHeight + PREVIEW_CONTAINER_PADDING_PX}px`\n  }\n})\n\nconst categoryPath = computed(() => nodeDef.category?.replaceAll('/', ' / '))\n\nconst inputs = computed(() => {\n  if (!nodeDef.inputs) return []\n  return flattenInputSpecs(nodeDef.inputs)\n    .filter((input) => !input.hidden)\n    .map((input) => ({\n      name: input.name,\n      type: input.type\n    }))\n})\n\nconst outputs = computed(() => {\n  if (!nodeDef.outputs) return []\n  return nodeDef.outputs.map((output) => ({\n    name: output.name,\n    type: output.type\n  }))\n})\n</script>\n","<template>\n  <PopoverRoot v-model:open=\"open\" @update:open=\"onOpenChange\">\n    <PopoverTrigger as-child>\n      <slot />\n    </PopoverTrigger>\n    <PopoverContent\n      side=\"bottom\"\n      :side-offset=\"4\"\n      :collision-padding=\"10\"\n      class=\"z-1001 w-64 rounded-lg border border-border-default bg-base-background px-4 py-1 shadow-interface will-change-[transform,opacity] data-[side=bottom]:slide-in-from-top-2 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95\"\n      @open-auto-focus=\"onOpenAutoFocus\"\n      @close-auto-focus=\"onCloseAutoFocus\"\n      @escape-key-down.prevent\n      @keydown.escape.stop=\"closeWithEscape\"\n    >\n      <ListboxRoot\n        multiple\n        selection-behavior=\"toggle\"\n        :model-value=\"selectedValues\"\n        @update:model-value=\"onSelectionChange\"\n      >\n        <div\n          class=\"mt-2 flex h-8 items-center gap-2 rounded-sm border border-border-default px-2\"\n        >\n          <i\n            class=\"icon-[lucide--search] size-4 shrink-0 text-muted-foreground\"\n          />\n          <ListboxFilter\n            ref=\"searchFilterRef\"\n            v-model=\"searchQuery\"\n            :placeholder=\"t('g.search')\"\n            class=\"size-full border-none bg-transparent font-inter text-sm text-base-foreground outline-none placeholder:text-muted-foreground\"\n          />\n        </div>\n\n        <div class=\"flex items-center justify-between py-3\">\n          <span class=\"text-sm text-muted-foreground\">\n            {{\n              t(\n                'g.itemsSelected',\n                { count: selectedValues.length },\n                selectedValues.length\n              )\n            }}\n          </span>\n          <button\n            v-if=\"selectedValues.length > 0\"\n            type=\"button\"\n            class=\"cursor-pointer border-none bg-transparent font-inter text-sm text-base-foreground\"\n            @click=\"emit('clear')\"\n          >\n            {{ t('g.clearAll') }}\n          </button>\n        </div>\n\n        <div class=\"h-px bg-border-default\" />\n\n        <ListboxContent class=\"max-h-64 overflow-y-auto py-3\">\n          <ListboxItem\n            v-for=\"option in filteredOptions\"\n            :key=\"option\"\n            :value=\"option\"\n            data-testid=\"filter-option\"\n            class=\"flex cursor-pointer items-center gap-2 rounded-sm px-1 py-2 text-sm text-base-foreground outline-none data-highlighted:bg-secondary-background-hover\"\n          >\n            <span\n              :class=\"\n                cn(\n                  'flex size-4 shrink-0 items-center justify-center rounded-sm border border-border-default',\n                  selectedSet.has(option) &&\n                    'border-primary-background bg-primary-background text-base-background'\n                )\n              \"\n            >\n              <i\n                v-if=\"selectedSet.has(option)\"\n                class=\"icon-[lucide--check] size-3\"\n              />\n            </span>\n            <span class=\"truncate\">{{ option }}</span>\n            <span\n              class=\"mr-1 ml-auto text-lg leading-none\"\n              :style=\"{ color: getLinkTypeColor(option) }\"\n            >\n              &bull;\n            </span>\n          </ListboxItem>\n          <div\n            v-if=\"filteredOptions.length === 0\"\n            class=\"px-1 py-4 text-center text-sm text-muted-foreground\"\n          >\n            {{ t('g.noResults') }}\n          </div>\n        </ListboxContent>\n      </ListboxRoot>\n    </PopoverContent>\n  </PopoverRoot>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport type { AcceptableValue } from 'reka-ui'\nimport {\n  ListboxContent,\n  ListboxFilter,\n  ListboxItem,\n  ListboxRoot,\n  PopoverContent,\n  PopoverRoot,\n  PopoverTrigger\n} from 'reka-ui'\n\nimport type { FilterChip } from '@/components/searchbox/v2/NodeSearchFilterBar.vue'\nimport { getLinkTypeColor } from '@/utils/litegraphUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { chip, selectedValues } = defineProps<{\n  chip: FilterChip\n  selectedValues: string[]\n}>()\n\nconst emit = defineEmits<{\n  toggle: [value: string]\n  clear: []\n  escapeClose: []\n}>()\n\nconst { t } = useI18n()\nconst open = ref(false)\nconst closedWithEscape = ref(false)\nconst searchQuery = ref('')\nconst searchFilterRef = ref<InstanceType<typeof ListboxFilter>>()\n\nfunction onOpenChange(isOpen: boolean) {\n  if (!isOpen) searchQuery.value = ''\n}\n\nconst selectedSet = computed(() => new Set(selectedValues))\n\nfunction onSelectionChange(value: AcceptableValue) {\n  const newValues = value as string[]\n  const added = newValues.find((v) => !selectedSet.value.has(v))\n  const removed = selectedValues.find((v) => !newValues.includes(v))\n  const toggled = added ?? removed\n  if (toggled) emit('toggle', toggled)\n}\n\nconst filteredOptions = computed(() => {\n  const { fuseSearch } = chip.filter\n  if (searchQuery.value) {\n    return fuseSearch.search(searchQuery.value).slice(0, 64)\n  }\n  return fuseSearch.data.slice().sort()\n})\n\nfunction closeWithEscape() {\n  closedWithEscape.value = true\n  open.value = false\n}\n\nfunction onOpenAutoFocus(event: Event) {\n  event.preventDefault()\n  const el = searchFilterRef.value?.$el as HTMLInputElement | undefined\n  el?.focus()\n}\n\nfunction onCloseAutoFocus(event: Event) {\n  if (closedWithEscape.value) {\n    event.preventDefault()\n    closedWithEscape.value = false\n    emit('escapeClose')\n  }\n}\n</script>\n","import { BLUEPRINT_CATEGORY } from '@/types/nodeSource'\n\nexport const RootCategory = {\n  Favorites: 'favorites',\n  Comfy: 'comfy',\n  Custom: 'custom',\n  Essentials: 'essentials',\n  PartnerNodes: 'partner-nodes',\n  Blueprint: BLUEPRINT_CATEGORY\n} as const\n\nexport type RootCategoryId = (typeof RootCategory)[keyof typeof RootCategory]\n","<template>\n  <div class=\"flex min-w-0 items-center gap-2.5 pl-3\">\n    <button\n      type=\"button\"\n      data-testid=\"toggle-category-sidebar\"\n      aria-controls=\"node-search-category-sidebar\"\n      :aria-expanded=\"isSidebarOpen\"\n      :aria-label=\"isSidebarOpen ? t('g.hideLeftPanel') : t('g.showLeftPanel')\"\n      :class=\"chipClass(isSidebarOpen)\"\n      @click=\"isSidebarOpen = !isSidebarOpen\"\n    >\n      <i class=\"icon-[lucide--panel-left] size-4\" />\n    </button>\n\n    <div class=\"h-5 w-px shrink-0 bg-border-subtle\" />\n\n    <div\n      data-testid=\"filter-chips-scroll\"\n      class=\"flex min-w-0 flex-1 items-center gap-2.5 overflow-x-auto pr-3\"\n    >\n      <!-- Category filter buttons -->\n      <button\n        v-for=\"btn in categoryButtons\"\n        :key=\"btn.id\"\n        type=\"button\"\n        :data-testid=\"`search-category-${btn.id}`\"\n        :aria-pressed=\"activeCategory === btn.id\"\n        :class=\"chipClass(activeCategory === btn.id)\"\n        @click=\"emit('selectCategory', btn.id)\"\n      >\n        {{ btn.label }}\n      </button>\n\n      <div class=\"h-5 w-px shrink-0 bg-border-subtle\" />\n\n      <!-- Type filter popovers (Input / Output) -->\n      <NodeSearchTypeFilterPopover\n        v-for=\"tf in typeFilters\"\n        :key=\"tf.chip.key\"\n        :chip=\"tf.chip\"\n        :selected-values=\"tf.values\"\n        @toggle=\"(v) => emit('toggleFilter', tf.chip.filter, v)\"\n        @clear=\"emit('clearFilterGroup', tf.chip.filter.id)\"\n        @escape-close=\"emit('focusSearch')\"\n      >\n        <button\n          type=\"button\"\n          :data-testid=\"`search-filter-${tf.chip.key}`\"\n          :class=\"chipClass(false, tf.values.length > 0)\"\n        >\n          <span v-if=\"tf.values.length > 0\" class=\"flex items-center\">\n            <span\n              v-for=\"val in tf.values.slice(0, MAX_VISIBLE_DOTS)\"\n              :key=\"val\"\n              class=\"mx-[-2px] text-lg leading-none\"\n              :style=\"{ color: getLinkTypeColor(val) }\"\n              >&bull;</span\n            >\n          </span>\n          {{ tf.chip.label }}\n          <i class=\"icon-[lucide--chevron-down] size-3.5\" />\n        </button>\n      </NodeSearchTypeFilterPopover>\n    </div>\n  </div>\n</template>\n\n<script lang=\"ts\">\nimport type { FuseFilter } from '@/utils/fuseUtil'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\n\nexport interface FilterChip {\n  key: string\n  label: string\n  filter: FuseFilter<ComfyNodeDefImpl, string>\n}\n</script>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport NodeSearchTypeFilterPopover from '@/components/searchbox/v2/NodeSearchTypeFilterPopover.vue'\nimport { RootCategory } from '@/components/searchbox/v2/rootCategories'\nimport type { RootCategoryId } from '@/components/searchbox/v2/rootCategories'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport type { FuseFilterWithValue } from '@/utils/fuseUtil'\nimport { getLinkTypeColor } from '@/utils/litegraphUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  filters = [],\n  activeCategory = null,\n  hasFavorites = false,\n  hasEssentialNodes = false,\n  hasBlueprintNodes = false,\n  hasPartnerNodes = false,\n  hasCustomNodes = false\n} = defineProps<{\n  filters?: FuseFilterWithValue<ComfyNodeDefImpl, string>[]\n  activeCategory?: string | null\n  hasFavorites?: boolean\n  hasEssentialNodes?: boolean\n  hasBlueprintNodes?: boolean\n  hasPartnerNodes?: boolean\n  hasCustomNodes?: boolean\n}>()\n\nconst isSidebarOpen = defineModel<boolean>('isSidebarOpen', { default: true })\n\nconst emit = defineEmits<{\n  toggleFilter: [filterDef: FuseFilter<ComfyNodeDefImpl, string>, value: string]\n  clearFilterGroup: [filterId: string]\n  focusSearch: []\n  selectCategory: [category: RootCategoryId]\n}>()\n\nconst { t } = useI18n()\nconst nodeDefStore = useNodeDefStore()\n\nconst MAX_VISIBLE_DOTS = 4\n\nconst categoryButtons = computed(() => {\n  const buttons: { id: RootCategoryId; label: string }[] = []\n  if (hasFavorites) {\n    buttons.push({ id: RootCategory.Favorites, label: t('g.bookmarked') })\n  }\n  if (hasBlueprintNodes) {\n    buttons.push({ id: RootCategory.Blueprint, label: t('g.blueprints') })\n  }\n  buttons.push({ id: RootCategory.Comfy, label: t('g.comfy') })\n  if (hasEssentialNodes) {\n    buttons.push({ id: RootCategory.Essentials, label: t('g.essentials') })\n  }\n  if (hasPartnerNodes) {\n    buttons.push({ id: RootCategory.PartnerNodes, label: t('g.partner') })\n  }\n  if (hasCustomNodes) {\n    buttons.push({ id: RootCategory.Custom, label: t('g.extensions') })\n  }\n  return buttons\n})\n\nconst inputChip = computed<FilterChip>(() => ({\n  key: 'input',\n  label: t('g.input'),\n  filter: nodeDefStore.nodeSearchService.inputTypeFilter\n}))\n\nconst outputChip = computed<FilterChip>(() => ({\n  key: 'output',\n  label: t('g.output'),\n  filter: nodeDefStore.nodeSearchService.outputTypeFilter\n}))\n\nconst selectedInputValues = computed(() =>\n  filters.filter((f) => f.filterDef.id === 'input').map((f) => f.value)\n)\n\nconst selectedOutputValues = computed(() =>\n  filters.filter((f) => f.filterDef.id === 'output').map((f) => f.value)\n)\n\nconst typeFilters = computed(() => [\n  { chip: inputChip.value, values: selectedInputValues.value },\n  { chip: outputChip.value, values: selectedOutputValues.value }\n])\n\nfunction chipClass(isActive: boolean, hasSelections = false) {\n  return cn(\n    'flex shrink-0 cursor-pointer items-center justify-center gap-1 rounded-md border border-secondary-background px-3 py-1 font-inter text-sm transition-colors',\n    isActive\n      ? 'border-base-foreground bg-base-foreground text-base-background'\n      : hasSelections\n        ? 'border-base-foreground/60 bg-transparent text-base-foreground/60 hover:border-base-foreground/60 hover:text-base-foreground/60'\n        : 'bg-transparent text-muted-foreground hover:border-base-foreground/60 hover:text-base-foreground/60'\n  )\n}\n</script>\n","<template>\n  <div\n    :class=\"\n      cn(\n        selectedCategory === node.key &&\n          isExpanded &&\n          node.children?.length &&\n          'rounded-lg bg-secondary-background'\n      )\n    \"\n  >\n    <RovingFocusItem as-child>\n      <Button\n        ref=\"buttonEl\"\n        type=\"button\"\n        role=\"treeitem\"\n        :data-testid=\"`category-${node.key}`\"\n        :aria-current=\"selectedCategory === node.key || undefined\"\n        :aria-expanded=\"node.children?.length ? isExpanded : undefined\"\n        :style=\"{ paddingLeft: `${0.75 + depth * 1.25}rem` }\"\n        :class=\"\n          cn(\n            'h-auto w-full gap-2 bg-transparent py-2.5 pr-3 text-left text-sm font-normal',\n            selectedCategory === node.key\n              ? CATEGORY_SELECTED_CLASS\n              : CATEGORY_UNSELECTED_CLASS\n          )\n        \"\n        @click=\"$emit('select', node.key)\"\n        @keydown.right.prevent=\"handleRight\"\n        @keydown.left.prevent=\"handleLeft\"\n      >\n        <i\n          v-if=\"!hideChevrons\"\n          :class=\"\n            cn(\n              'size-4 shrink-0 text-muted-foreground transition-[transform,opacity] duration-150',\n              node.children?.length\n                ? 'icon-[lucide--chevron-down] opacity-0 group-hover/categories:opacity-100 group-has-focus-visible/categories:opacity-100'\n                : '',\n              node.children?.length && !isExpanded && '-rotate-90'\n            )\n          \"\n        />\n        <span class=\"flex-1 truncate\">{{ node.label }}</span>\n      </Button>\n    </RovingFocusItem>\n    <div v-if=\"isExpanded && node.children?.length\" role=\"group\">\n      <NodeSearchCategoryTreeNode\n        v-for=\"child in node.children\"\n        :key=\"child.key\"\n        ref=\"childRefs\"\n        :node=\"child\"\n        :depth=\"depth + 1\"\n        :selected-category=\"selectedCategory\"\n        :expanded-category=\"expandedCategory\"\n        :hide-chevrons=\"hideChevrons\"\n        :focus-parent=\"focusSelf\"\n        @select=\"$emit('select', $event)\"\n        @collapse=\"$emit('collapse', $event)\"\n      />\n    </div>\n  </div>\n</template>\n\n<script lang=\"ts\">\nexport interface CategoryNode {\n  key: string\n  label: string\n  children?: CategoryNode[]\n}\n\nexport const CATEGORY_SELECTED_CLASS =\n  'bg-secondary-background-hover text-base-foreground'\nexport const CATEGORY_UNSELECTED_CLASS =\n  'text-muted-foreground hover:bg-secondary-background-hover hover:text-base-foreground'\n</script>\n\n<script setup lang=\"ts\">\nimport { computed, nextTick, ref } from 'vue'\n\nimport { RovingFocusItem } from 'reka-ui'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  node,\n  depth = 0,\n  selectedCategory,\n  expandedCategory,\n  hideChevrons = false,\n  focusParent\n} = defineProps<{\n  node: CategoryNode\n  depth?: number\n  selectedCategory: string\n  expandedCategory: string\n  hideChevrons?: boolean\n  focusParent?: () => void\n}>()\n\nconst emit = defineEmits<{\n  select: [key: string]\n  collapse: [key: string]\n}>()\n\nconst buttonEl = ref<InstanceType<typeof Button>>()\nconst childRefs = ref<{ focus?: () => void }[]>([])\n\nfunction focusSelf() {\n  const el = buttonEl.value?.$el as HTMLElement | undefined\n  el?.focus()\n}\n\ndefineExpose({ focus: focusSelf })\n\nconst isExpanded = computed(\n  () =>\n    expandedCategory === node.key || expandedCategory.startsWith(node.key + '/')\n)\n\nfunction handleRight() {\n  if (!node.children?.length) return\n  if (!isExpanded.value) {\n    emit('select', node.key)\n    return\n  }\n  nextTick(() => {\n    childRefs.value[0]?.focus?.()\n  })\n}\n\nfunction handleLeft() {\n  if (node.children?.length && isExpanded.value) {\n    if (expandedCategory.startsWith(node.key + '/')) {\n      emit('collapse', node.key)\n    } else {\n      emit('select', node.key)\n    }\n    return\n  }\n  focusParent?.()\n}\n</script>\n","import { t } from '@/i18n'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { buildNodeDefTree } from '@/stores/nodeDefStore'\nimport type {\n  NodeGroupingStrategy,\n  NodeOrganizationOptions,\n  NodeSection,\n  NodeSortStrategy\n} from '@/types/nodeOrganizationTypes'\nimport { NodeSourceType } from '@/types/nodeSource'\nimport type { TreeNode } from '@/types/treeExplorerTypes'\nimport { sortedTree, unwrapTreeRoot } from '@/utils/treeUtil'\n\nconst DEFAULT_ICON = 'pi pi-sort'\n\nfunction categoryPathExtractor(nodeDef: ComfyNodeDefImpl): string[] {\n  const category = nodeDef.category || ''\n  const categoryParts = category ? category.split('/').filter(Boolean) : []\n  return [...categoryParts, nodeDef.name]\n}\n\nfunction isBlueprint(node: ComfyNodeDefImpl): boolean {\n  return (\n    node.nodeSource.type === NodeSourceType.Blueprint ||\n    node.python_module.startsWith('blueprint')\n  )\n}\n\nexport const DEFAULT_GROUPING_ID = 'category' as const\nexport const DEFAULT_SORTING_ID = 'original' as const\nexport const DEFAULT_TAB_ID = 'all' as const\n\nclass NodeOrganizationService {\n  private readonly groupingStrategies: NodeGroupingStrategy[] = [\n    {\n      id: 'category',\n      label: 'sideToolbar.nodeLibraryTab.groupStrategies.category',\n      icon: 'pi pi-folder',\n      description: 'sideToolbar.nodeLibraryTab.groupStrategies.categoryDesc',\n      getNodePath: categoryPathExtractor\n    },\n    {\n      id: 'module',\n      label: 'sideToolbar.nodeLibraryTab.groupStrategies.module',\n      icon: 'pi pi-box',\n      description: 'sideToolbar.nodeLibraryTab.groupStrategies.moduleDesc',\n      getNodePath: (nodeDef: ComfyNodeDefImpl) => {\n        const pythonModule = nodeDef.python_module || ''\n\n        if (!pythonModule) {\n          return ['unknown_module', nodeDef.name]\n        }\n\n        // Split the module path into components\n        const parts = pythonModule.split('.')\n\n        // Remove common prefixes and organize\n        if (parts[0] === 'nodes') {\n          // Core nodes - just use 'core'\n          return ['core', nodeDef.name]\n        } else if (parts[0] === 'custom_nodes') {\n          // Custom nodes - use the package name as the folder\n          if (parts.length > 1) {\n            // Return the custom node package name\n            return [parts[1], nodeDef.name]\n          }\n          return ['custom_nodes', nodeDef.name]\n        }\n\n        // For other modules, use the full path structure plus node name\n        return [...parts, nodeDef.name]\n      }\n    },\n    {\n      id: 'source',\n      label: 'sideToolbar.nodeLibraryTab.groupStrategies.source',\n      icon: 'pi pi-server',\n      description: 'sideToolbar.nodeLibraryTab.groupStrategies.sourceDesc',\n      getNodePath: (nodeDef: ComfyNodeDefImpl) => {\n        if (nodeDef.api_node) {\n          return ['API nodes', nodeDef.name]\n        } else if (nodeDef.nodeSource.type === NodeSourceType.Core) {\n          return ['Core', nodeDef.name]\n        } else if (nodeDef.nodeSource.type === NodeSourceType.CustomNodes) {\n          return ['Custom nodes', nodeDef.name]\n        } else {\n          return ['Unknown', nodeDef.name]\n        }\n      }\n    }\n  ]\n\n  private readonly sortingStrategies: NodeSortStrategy[] = [\n    {\n      id: 'original',\n      label: 'sideToolbar.nodeLibraryTab.sortBy.original',\n      icon: 'pi pi-sort-alt',\n      description: 'sideToolbar.nodeLibraryTab.sortBy.originalDesc',\n      compare: () => 0\n    },\n    {\n      id: 'alphabetical',\n      label: 'sideToolbar.nodeLibraryTab.sortBy.alphabetical',\n      icon: 'pi pi-sort-alpha-down',\n      description: 'sideToolbar.nodeLibraryTab.sortBy.alphabeticalDesc',\n      compare: (a: ComfyNodeDefImpl, b: ComfyNodeDefImpl) =>\n        a.display_name.localeCompare(b.display_name)\n    }\n  ]\n\n  getGroupingStrategies(): NodeGroupingStrategy[] {\n    return [...this.groupingStrategies]\n  }\n\n  getGroupingStrategy(id: string): NodeGroupingStrategy | undefined {\n    return this.groupingStrategies.find((strategy) => strategy.id === id)\n  }\n\n  getSortingStrategies(): NodeSortStrategy[] {\n    return [...this.sortingStrategies]\n  }\n\n  getSortingStrategy(id: string): NodeSortStrategy | undefined {\n    return this.sortingStrategies.find((strategy) => strategy.id === id)\n  }\n\n  organizeNodesTab(nodes: ComfyNodeDefImpl[]): NodeSection[] {\n    const {\n      myBlueprints,\n      comfyBlueprints,\n      partnerNodes,\n      comfyNodes,\n      extensions\n    } = this.classifyNodes(nodes)\n\n    const blueprintTree = this.buildBlueprintTree(\n      myBlueprints,\n      comfyBlueprints,\n      categoryPathExtractor\n    )\n\n    const sections: NodeSection[] = []\n\n    if (blueprintTree.children?.length) {\n      sections.push({ category: 'blueprints', tree: blueprintTree })\n    }\n    if (comfyNodes.length > 0) {\n      sections.push({\n        category: 'comfyNodes',\n        tree: buildNodeDefTree(comfyNodes, {\n          pathExtractor: categoryPathExtractor\n        })\n      })\n    }\n    if (partnerNodes.length > 0) {\n      sections.push({\n        category: 'partnerNodes',\n        tree: unwrapTreeRoot(\n          buildNodeDefTree(partnerNodes, {\n            pathExtractor: categoryPathExtractor\n          })\n        )\n      })\n    }\n    if (extensions.length > 0) {\n      sections.push({\n        category: 'extensions',\n        tree: buildNodeDefTree(extensions, {\n          pathExtractor: categoryPathExtractor\n        })\n      })\n    }\n\n    return sections\n  }\n\n  private classifyNodes(nodes: ComfyNodeDefImpl[]): {\n    myBlueprints: ComfyNodeDefImpl[]\n    comfyBlueprints: ComfyNodeDefImpl[]\n    partnerNodes: ComfyNodeDefImpl[]\n    comfyNodes: ComfyNodeDefImpl[]\n    extensions: ComfyNodeDefImpl[]\n  } {\n    const myBlueprints: ComfyNodeDefImpl[] = []\n    const comfyBlueprints: ComfyNodeDefImpl[] = []\n    const partnerNodes: ComfyNodeDefImpl[] = []\n    const comfyNodes: ComfyNodeDefImpl[] = []\n    const extensions: ComfyNodeDefImpl[] = []\n\n    for (const node of nodes) {\n      if (isBlueprint(node)) {\n        if (node.isGlobal) comfyBlueprints.push(node)\n        else myBlueprints.push(node)\n      } else if (node.api_node || node.category.startsWith('api node')) {\n        partnerNodes.push(node)\n      } else if (\n        node.nodeSource.type === NodeSourceType.Core ||\n        node.nodeSource.type === NodeSourceType.Essentials\n      ) {\n        comfyNodes.push(node)\n      } else {\n        extensions.push(node)\n      }\n    }\n\n    return {\n      myBlueprints,\n      comfyBlueprints,\n      partnerNodes,\n      comfyNodes,\n      extensions\n    }\n  }\n\n  private buildBlueprintTree(\n    myBlueprints: ComfyNodeDefImpl[],\n    comfyBlueprints: ComfyNodeDefImpl[],\n    pathExtractor: (nodeDef: ComfyNodeDefImpl) => string[]\n  ): TreeNode<ComfyNodeDefImpl> {\n    const children: TreeNode<ComfyNodeDefImpl>[] = []\n    if (myBlueprints.length > 0) {\n      const tree = unwrapTreeRoot(\n        buildNodeDefTree(myBlueprints, { pathExtractor })\n      )\n      children.push({\n        key: 'root/my-blueprints',\n        label: t('sideToolbar.nodeLibraryTab.sections.myBlueprints'),\n        children: tree.children\n      })\n    }\n    if (comfyBlueprints.length > 0) {\n      const tree = unwrapTreeRoot(\n        buildNodeDefTree(comfyBlueprints, { pathExtractor })\n      )\n      children.push({\n        key: 'root/comfy-blueprints',\n        label: t('sideToolbar.nodeLibraryTab.sections.comfyBlueprints'),\n        children: tree.children\n      })\n    }\n    return { key: 'root', label: '', children }\n  }\n\n  organizeNodes(\n    nodes: ComfyNodeDefImpl[],\n    options: NodeOrganizationOptions = {}\n  ): TreeNode<ComfyNodeDefImpl> {\n    const { groupBy = DEFAULT_GROUPING_ID, sortBy = DEFAULT_SORTING_ID } =\n      options\n\n    const groupingStrategy = this.getGroupingStrategy(groupBy)\n    const sortingStrategy = this.getSortingStrategy(sortBy)\n\n    if (!groupingStrategy) {\n      throw new Error(`Unknown grouping strategy: ${groupBy}`)\n    }\n\n    if (!sortingStrategy) {\n      throw new Error(`Unknown sorting strategy: ${sortBy}`)\n    }\n\n    const sortedNodes =\n      sortingStrategy.id === 'original'\n        ? nodes\n        : [...nodes].sort(sortingStrategy.compare)\n\n    const tree = buildNodeDefTree(sortedNodes, {\n      pathExtractor: groupingStrategy.getNodePath\n    })\n\n    if (sortBy === 'alphabetical') {\n      return sortedTree(tree, { groupLeaf: true })\n    }\n\n    return tree\n  }\n\n  getGroupingIcon(groupingId: string): string {\n    const strategy = this.getGroupingStrategy(groupingId)\n    return strategy?.icon || DEFAULT_ICON\n  }\n\n  getSortingIcon(sortingId: string): string {\n    const strategy = this.getSortingStrategy(sortingId)\n    return strategy?.icon || DEFAULT_ICON\n  }\n}\n\nexport const nodeOrganizationService = new NodeOrganizationService()\n","<template>\n  <RovingFocusGroup\n    as=\"div\"\n    orientation=\"vertical\"\n    :loop=\"true\"\n    class=\"group/categories flex min-h-0 flex-col overflow-y-auto py-2.5 select-none\"\n  >\n    <!-- Preset categories -->\n    <div v-if=\"!hidePresets\" class=\"flex flex-col px-3\">\n      <RovingFocusItem\n        v-for=\"preset in topCategories\"\n        :key=\"preset.id\"\n        as-child\n      >\n        <Button\n          type=\"button\"\n          :data-testid=\"`category-${preset.id}`\"\n          :aria-current=\"selectedCategory === preset.id || undefined\"\n          :class=\"categoryBtnClass(preset.id)\"\n          @click=\"selectCategory(preset.id)\"\n        >\n          {{ preset.label }}\n        </Button>\n      </RovingFocusItem>\n    </div>\n\n    <!-- Category tree -->\n    <div\n      role=\"tree\"\n      :aria-label=\"t('g.category')\"\n      :class=\"\n        cn(\n          'flex flex-col px-3',\n          !hidePresets && 'mt-2 border-t border-border-subtle pt-2'\n        )\n      \"\n    >\n      <NodeSearchCategoryTreeNode\n        v-for=\"category in categoryTree\"\n        :key=\"category.key\"\n        :node=\"category\"\n        :selected-category=\"selectedCategory\"\n        :expanded-category=\"expandedCategory\"\n        :hide-chevrons=\"hideChevrons\"\n        @select=\"selectCategory\"\n        @collapse=\"collapseCategory\"\n      />\n    </div>\n  </RovingFocusGroup>\n</template>\n\n<script lang=\"ts\">\nexport const DEFAULT_CATEGORY = 'most-relevant'\n</script>\n\n<script setup lang=\"ts\">\nimport { computed, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { RovingFocusGroup, RovingFocusItem } from 'reka-ui'\n\nimport NodeSearchCategoryTreeNode, {\n  CATEGORY_SELECTED_CLASS,\n  CATEGORY_UNSELECTED_CLASS\n} from '@/components/searchbox/v2/NodeSearchCategoryTreeNode.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { CategoryNode } from '@/components/searchbox/v2/NodeSearchCategoryTreeNode.vue'\nimport { nodeOrganizationService } from '@/services/nodeOrganizationService'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport type { TreeNode } from '@/types/treeExplorerTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  hideChevrons = false,\n  hidePresets = false,\n  nodeDefs,\n  rootLabel,\n  rootKey\n} = defineProps<{\n  hideChevrons?: boolean\n  hidePresets?: boolean\n  nodeDefs?: ComfyNodeDefImpl[]\n  rootLabel?: string\n  rootKey?: string\n}>()\n\nconst selectedCategory = defineModel<string>('selectedCategory', {\n  required: true\n})\n\nconst emit = defineEmits<{\n  autoExpand: [key: string]\n}>()\n\nconst { t } = useI18n()\nconst nodeDefStore = useNodeDefStore()\n\nconst topCategories = computed(() => [\n  { id: DEFAULT_CATEGORY, label: t('g.mostRelevant') }\n])\n\nconst categoryTree = computed<CategoryNode[]>(() => {\n  const defs = nodeDefs ?? nodeDefStore.visibleNodeDefs\n  const tree = nodeOrganizationService.organizeNodes(defs, {\n    groupBy: 'category'\n  })\n\n  const stripRootPrefix = (key: string) => key.replace(/^root\\//, '')\n\n  function mapNode(node: TreeNode<ComfyNodeDefImpl>): CategoryNode {\n    const children = node.children?.filter((child) => !child.leaf).map(mapNode)\n    return {\n      key: stripRootPrefix(node.key),\n      label: node.label,\n      ...(children?.length ? { children } : {})\n    }\n  }\n\n  const nodes = (tree.children ?? []).filter((node) => !node.leaf).map(mapNode)\n\n  if (rootLabel && nodes.length > 1) {\n    const key = rootKey ?? rootLabel.toLowerCase()\n    function prefixKeys(node: CategoryNode): CategoryNode {\n      return {\n        key: key + '/' + node.key,\n        label: node.label,\n        ...(node.children?.length\n          ? { children: node.children.map(prefixKeys) }\n          : {})\n      }\n    }\n    return [{ key, label: rootLabel, children: nodes.map(prefixKeys) }]\n  }\n\n  return nodes\n})\n\n// Notify parent when there is only a single root category to auto-expand\nwatch(\n  categoryTree,\n  (nodes) => {\n    if (nodes.length === 1 && nodes[0].children?.length) {\n      const rootKey = nodes[0].key\n      if (\n        selectedCategory.value !== rootKey &&\n        !selectedCategory.value.startsWith(rootKey + '/')\n      ) {\n        emit('autoExpand', rootKey)\n      }\n    }\n  },\n  { immediate: true }\n)\n\nfunction categoryBtnClass(id: string) {\n  return cn(\n    'h-auto justify-start bg-transparent py-2.5 pr-3 text-sm font-normal',\n    hideChevrons ? 'pl-3' : 'pl-9',\n    selectedCategory.value === id\n      ? CATEGORY_SELECTED_CLASS\n      : CATEGORY_UNSELECTED_CLASS\n  )\n}\n\nconst expandedCategory = ref(selectedCategory.value)\n// Skips the watch when selectCategory/collapseCategory set selectedCategory,\n// so their expandedCategory toggle isn't immediately undone.\nlet lastEmittedCategory = ''\n\nwatch(selectedCategory, (val) => {\n  if (val !== lastEmittedCategory) {\n    expandedCategory.value = val\n  }\n  lastEmittedCategory = ''\n})\n\nfunction parentCategory(key: string): string {\n  const i = key.lastIndexOf('/')\n  return i > 0 ? key.slice(0, i) : ''\n}\n\nfunction selectCategory(categoryId: string) {\n  if (expandedCategory.value === categoryId) {\n    expandedCategory.value = parentCategory(categoryId)\n  } else {\n    expandedCategory.value = categoryId\n  }\n  lastEmittedCategory = categoryId\n  selectedCategory.value = categoryId\n}\n\nfunction collapseCategory(categoryId: string) {\n  expandedCategory.value = parentCategory(categoryId)\n  lastEmittedCategory = categoryId\n  selectedCategory.value = categoryId\n}\n</script>\n","<template>\n  <div class=\"p-3\">\n    <TagsInputRoot\n      :model-value=\"tagValues\"\n      delimiter=\"\"\n      class=\"flex cursor-text flex-wrap items-center gap-2 rounded-lg bg-secondary-background px-4 py-3\"\n      @remove-tag=\"onRemoveTag\"\n      @click=\"inputRef?.focus()\"\n    >\n      <!-- Applied filter chips -->\n      <TagsInputItem\n        v-for=\"filter in filters\"\n        :key=\"filterKey(filter)\"\n        :value=\"filterKey(filter)\"\n        data-testid=\"filter-chip\"\n        class=\"-my-1 inline-flex items-center gap-1 rounded-lg bg-base-background px-2 py-1 data-[state=active]:ring-2 data-[state=active]:ring-primary\"\n      >\n        <span class=\"text-sm opacity-80\">\n          {{ t(`g.${filter.filterDef.id}`) }}:\n        </span>\n        <span :style=\"{ color: getLinkTypeColor(filter.value) }\"> &bull; </span>\n        <span class=\"text-sm\">{{ filter.value }}</span>\n        <TagsInputItemDelete\n          as=\"button\"\n          type=\"button\"\n          data-testid=\"chip-delete\"\n          :aria-label=\"$t('g.remove')\"\n          class=\"ml-1 flex aspect-square cursor-pointer items-center justify-center rounded-full border-none bg-transparent text-muted-foreground hover:text-base-foreground\"\n        >\n          <i class=\"icon-[lucide--x] size-3\" />\n        </TagsInputItemDelete>\n      </TagsInputItem>\n      <TagsInputInput as-child>\n        <input\n          ref=\"inputRef\"\n          v-model=\"searchQuery\"\n          type=\"text\"\n          autofocus\n          role=\"combobox\"\n          aria-autocomplete=\"list\"\n          :aria-expanded=\"true\"\n          aria-controls=\"results-list\"\n          :aria-label=\"t('g.addNode')\"\n          :placeholder=\"t('g.addNode')\"\n          class=\"h-6 min-w-[min(300px,80vw)] flex-1 border-none bg-transparent font-inter text-sm text-base-foreground outline-none placeholder:text-muted-foreground\"\n          @keydown.enter.prevent=\"emit('selectCurrent')\"\n          @keydown.down.prevent=\"emit('navigateDown')\"\n          @keydown.up.prevent=\"emit('navigateUp')\"\n        />\n      </TagsInputInput>\n    </TagsInputRoot>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport {\n  TagsInputInput,\n  TagsInputItem,\n  TagsInputItemDelete,\n  TagsInputRoot\n} from 'reka-ui'\n\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport type { FuseFilterWithValue } from '@/utils/fuseUtil'\nimport { getLinkTypeColor } from '@/utils/litegraphUtil'\n\nconst { filters } = defineProps<{\n  filters: FuseFilterWithValue<ComfyNodeDefImpl, string>[]\n}>()\n\nconst searchQuery = defineModel<string>('searchQuery', { required: true })\n\nconst emit = defineEmits<{\n  removeFilter: [filter: FuseFilterWithValue<ComfyNodeDefImpl, string>]\n  navigateDown: []\n  navigateUp: []\n  selectCurrent: []\n}>()\n\nconst { t } = useI18n()\nconst inputRef = ref<HTMLInputElement>()\n\nconst tagValues = computed(() => filters.map(filterKey))\n\nfunction filterKey(filter: FuseFilterWithValue<ComfyNodeDefImpl, string>) {\n  return `${filter.filterDef.id}:${filter.value}`\n}\n\nfunction onRemoveTag(tagValue: string) {\n  const filter = filters.find((f) => filterKey(f) === tagValue)\n  if (filter) emit('removeFilter', filter)\n}\n\nfunction focus() {\n  inputRef.value?.focus()\n}\n\ndefineExpose({ focus })\n</script>\n","<template>\n  <div\n    ref=\"containerRef\"\n    :class=\"\n      cn('overflow-hidden whitespace-nowrap', !isScrolling && 'text-ellipsis')\n    \"\n  >\n    <slot />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useElementHover, useElementSize, useRafFn } from '@vueuse/core'\nimport { ref, watch } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { speed = 70 } = defineProps<{\n  /** Scroll speed in pixels per second */\n  speed?: number\n}>()\n\nconst containerRef = ref<HTMLElement | null>(null)\nconst isHovered = useElementHover(containerRef, { delayEnter: 350 })\nconst { width: containerWidth } = useElementSize(containerRef)\nconst isScrolling = ref(false)\nlet scrollStartTime = 0\nlet overflowAmount = 0\n\nconst { pause, resume } = useRafFn(\n  ({ timestamp }) => {\n    const el = containerRef.value\n    if (!el || overflowAmount <= 0) return pause()\n\n    const elapsed = timestamp - scrollStartTime\n    const duration = (overflowAmount / speed) * 1000\n    const progress = Math.min(elapsed / duration, 1)\n    el.scrollLeft = overflowAmount * progress\n\n    if (progress >= 1) pause()\n  },\n  { immediate: false }\n)\n\nfunction startScroll() {\n  const el = containerRef.value\n  if (!el) return\n\n  overflowAmount = el.scrollWidth - containerWidth.value\n  if (overflowAmount <= 0) return\n\n  isScrolling.value = true\n  scrollStartTime = performance.now()\n  resume()\n}\n\nfunction stopScroll() {\n  pause()\n  if (containerRef.value) {\n    containerRef.value.scrollLeft = 0\n  }\n  isScrolling.value = false\n}\n\nwatch(isHovered, (hovered) => {\n  if (hovered) startScroll()\n  else stopScroll()\n})\n</script>\n","<template>\n  <template v-for=\"(part, index) in highlightQuery(text, query)\" :key=\"index\">\n    <span v-if=\"part.highlighted\" class=\"highlight\">{{ part.text }}</span>\n    <template v-else>{{ part.text }}</template>\n  </template>\n</template>\n\n<script setup lang=\"ts\">\nimport { highlightQuery } from '@/utils/formatUtil'\n\nconst { text, query } = defineProps<{\n  text: string\n  query: string\n}>()\n</script>\n","import { clone } from 'es-toolkit/compat'\nimport { defineStore } from 'pinia'\nimport { computed } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { BookmarkCustomization } from '@/platform/settings/types'\nimport type { TreeNode } from '@/types/treeExplorerTypes'\n\nimport {\n  buildNodeDefTree,\n  createDummyFolderNodeDef,\n  useNodeDefStore\n} from './nodeDefStore'\nimport type { ComfyNodeDefImpl } from './nodeDefStore'\n\nconst BOOKMARK_SETTING_ID = 'Comfy.NodeLibrary.Bookmarks.V2'\n\nexport const useNodeBookmarkStore = defineStore('nodeBookmark', () => {\n  const settingStore = useSettingStore()\n  const nodeDefStore = useNodeDefStore()\n  const bookmarks = computed<string[]>(() =>\n    settingStore.get(BOOKMARK_SETTING_ID)\n  )\n\n  const bookmarksSet = computed<Set<string>>(() => new Set(bookmarks.value))\n\n  const bookmarkedRoot = computed<TreeNode<ComfyNodeDefImpl>>(() =>\n    buildBookmarkTree(bookmarks.value)\n  )\n\n  // For a node in custom bookmark folders, check if its nodePath is in bookmarksSet\n  // For a node in the nodeDefStore, check if its name is bookmarked at top level\n  const isBookmarked = (node: ComfyNodeDefImpl) =>\n    bookmarksSet.value.has(node.nodePath) || bookmarksSet.value.has(node.name)\n\n  const toggleBookmark = async (node: ComfyNodeDefImpl) => {\n    if (isBookmarked(node)) {\n      await deleteBookmark(node.nodePath)\n      // Delete the bookmark at the top level if it exists\n      // This is used for clicking the bookmark button in the node library, i.e.\n      // the node is inside original/standard node library tree node\n      await deleteBookmark(node.name)\n    } else {\n      await addBookmark(node.name)\n    }\n  }\n\n  const buildBookmarkTree = (bookmarks: string[]) => {\n    const bookmarkNodes = bookmarks\n      .map((bookmark: string) => {\n        if (bookmark.endsWith('/')) return createDummyFolderNodeDef(bookmark)\n\n        const parts = bookmark.split('/')\n        const name = parts.pop() ?? ''\n        const category = parts.join('/')\n        const srcNodeDef = nodeDefStore.getNodeDefByName(name)\n        if (!srcNodeDef) return null\n        const nodeDef = clone(srcNodeDef)\n        nodeDef.category = category\n        return nodeDef\n      })\n      .filter((nodeDef) => nodeDef !== null)\n    return buildNodeDefTree(bookmarkNodes)\n  }\n\n  const addBookmark = async (nodePath: string) => {\n    await settingStore.set(BOOKMARK_SETTING_ID, [...bookmarks.value, nodePath])\n  }\n\n  const deleteBookmark = async (nodePath: string) => {\n    await settingStore.set(\n      BOOKMARK_SETTING_ID,\n      bookmarks.value.filter((b: string) => b !== nodePath)\n    )\n  }\n\n  const addNewBookmarkFolder = async (\n    parent: ComfyNodeDefImpl | undefined,\n    folderName: string\n  ) => {\n    const parentPath = parent ? parent.nodePath : ''\n    const newFolderPath = parentPath + folderName + '/'\n    await addBookmark(newFolderPath)\n    return newFolderPath\n  }\n\n  const renameBookmarkFolder = async (\n    folderNode: ComfyNodeDefImpl,\n    newName: string\n  ) => {\n    if (!folderNode.isDummyFolder) {\n      throw new Error('Cannot rename non-folder node')\n    }\n\n    if (newName.includes('/')) {\n      throw new Error('Folder name cannot contain \"/\"')\n    }\n\n    const newNodePath =\n      folderNode.category.split('/').slice(0, -1).concat(newName).join('/') +\n      '/'\n\n    if (newNodePath === folderNode.nodePath) {\n      return\n    }\n\n    if (bookmarks.value.some((b: string) => b.startsWith(newNodePath))) {\n      throw new Error(`Folder name \"${newNodePath}\" already exists`)\n    }\n\n    await settingStore.set(\n      BOOKMARK_SETTING_ID,\n      bookmarks.value.map((b: string) =>\n        b.startsWith(folderNode.nodePath)\n          ? b.replace(folderNode.nodePath, newNodePath)\n          : b\n      )\n    )\n    await renameBookmarkCustomization(folderNode.nodePath, newNodePath)\n  }\n\n  const deleteBookmarkFolder = async (folderNode: ComfyNodeDefImpl) => {\n    if (!folderNode.isDummyFolder) {\n      throw new Error('Cannot delete non-folder node')\n    }\n    await settingStore.set(\n      BOOKMARK_SETTING_ID,\n      bookmarks.value.filter(\n        (b: string) =>\n          b !== folderNode.nodePath && !b.startsWith(folderNode.nodePath)\n      )\n    )\n    await deleteBookmarkCustomization(folderNode.nodePath)\n  }\n\n  const bookmarksCustomization = computed<\n    Record<string, BookmarkCustomization>\n  >(() => settingStore.get('Comfy.NodeLibrary.BookmarksCustomization'))\n\n  const updateBookmarkCustomization = async (\n    nodePath: string,\n    customization: BookmarkCustomization\n  ) => {\n    const currentCustomization =\n      nodePath in bookmarksCustomization.value\n        ? bookmarksCustomization.value[nodePath]\n        : {}\n    const newCustomization = { ...currentCustomization, ...customization }\n\n    // Remove attributes that are set to default values\n    if (newCustomization.icon === defaultBookmarkIcon) {\n      delete newCustomization.icon\n    }\n    if (newCustomization.color === defaultBookmarkColor) {\n      delete newCustomization.color\n    }\n\n    // If the customization is empty, remove it entirely\n    if (Object.keys(newCustomization).length === 0) {\n      await deleteBookmarkCustomization(nodePath)\n    } else {\n      await settingStore.set('Comfy.NodeLibrary.BookmarksCustomization', {\n        ...bookmarksCustomization.value,\n        [nodePath]: newCustomization\n      })\n    }\n  }\n\n  const deleteBookmarkCustomization = async (nodePath: string) => {\n    await settingStore.set('Comfy.NodeLibrary.BookmarksCustomization', {\n      ...bookmarksCustomization.value,\n      [nodePath]: undefined\n    } as Record<string, BookmarkCustomization>)\n  }\n\n  const renameBookmarkCustomization = async (\n    oldNodePath: string,\n    newNodePath: string\n  ) => {\n    const updatedCustomization = { ...bookmarksCustomization.value }\n    if (oldNodePath in updatedCustomization) {\n      updatedCustomization[newNodePath] = updatedCustomization[oldNodePath]\n      delete updatedCustomization[oldNodePath]\n    }\n    await settingStore.set(\n      'Comfy.NodeLibrary.BookmarksCustomization',\n      updatedCustomization\n    )\n  }\n\n  const defaultBookmarkIcon = 'pi-bookmark-fill'\n  const defaultBookmarkColor = '#a1a1aa'\n\n  return {\n    bookmarks,\n    bookmarkedRoot,\n    isBookmarked,\n    toggleBookmark,\n    addBookmark,\n    addNewBookmarkFolder,\n    renameBookmarkFolder,\n    deleteBookmarkFolder,\n\n    bookmarksCustomization,\n    updateBookmarkCustomization,\n    deleteBookmarkCustomization,\n    renameBookmarkCustomization,\n    defaultBookmarkIcon,\n    defaultBookmarkColor\n  }\n})\n","<template>\n  <div\n    class=\"option-container flex w-full cursor-pointer items-center justify-between overflow-hidden\"\n  >\n    <div class=\"flex min-w-0 flex-1 flex-col gap-1 overflow-hidden\">\n      <!-- Row 1: Name (left) + badges (right) -->\n      <div class=\"flex items-center gap-2 text-sm text-base-foreground\">\n        <span\n          v-if=\"isBookmarked && !hideBookmarkIcon\"\n          role=\"img\"\n          :aria-label=\"$t('g.bookmarked')\"\n        >\n          <i aria-hidden=\"true\" class=\"pi pi-bookmark-fill mr-1 text-sm\" />\n        </span>\n        <span class=\"truncate\">\n          <HighlightedText :text=\"nodeDef.display_name\" :query=\"currentQuery\" />\n        </span>\n        <span\n          v-if=\"showIdName\"\n          data-testid=\"node-id-badge\"\n          class=\"shrink-0 rounded-sm bg-secondary-background px-1.5 py-0.5 text-xs text-muted-foreground\"\n        >\n          <HighlightedText :text=\"nodeDef.name\" :query=\"currentQuery\" />\n        </span>\n\n        <template v-if=\"showDescription\">\n          <div class=\"flex-1\" />\n          <div class=\"flex shrink-0 items-center gap-1\">\n            <span v-if=\"showSourceBadge && isCore\" :class=\"badgePillClass\">\n              <span class=\"truncate text-2xs\">{{ $t('g.comfy') }}</span>\n            </span>\n            <span\n              v-else-if=\"\n                showSourceBadge &&\n                nodeDef.nodeSource.type !== NodeSourceType.Unknown\n              \"\n              :class=\"badgePillClass\"\n            >\n              <span class=\"truncate text-2xs\">\n                {{ nodeDef.nodeSource.displayText }}\n              </span>\n            </span>\n\n            <span v-if=\"isEssential\" :class=\"badgePillClass\">\n              <span class=\"truncate text-2xs\">{{ $t('g.essentials') }}</span>\n            </span>\n\n            <span\n              v-if=\"nodeDef.api_node && providerName\"\n              :class=\"badgePillClass\"\n            >\n              <i\n                aria-hidden=\"true\"\n                class=\"icon-[lucide--coins] size-3 text-amber-400\"\n              />\n              <i\n                aria-hidden=\"true\"\n                :class=\"cn(getProviderIcon(providerName), 'size-3')\"\n              />\n            </span>\n          </div>\n        </template>\n        <template v-else>\n          <NodePricingBadge :node-def=\"nodeDef\" />\n          <NodeProviderBadge v-if=\"nodeDef.api_node\" :node-def=\"nodeDef\" />\n        </template>\n      </div>\n\n      <div\n        v-if=\"showDescription\"\n        class=\"flex min-w-0 items-center gap-1.5 text-xs text-muted-foreground\"\n      >\n        <span v-if=\"showCategory\" class=\"max-w-2/5 shrink-0 truncate\">\n          {{ nodeDef.category.replaceAll('/', ' / ') }}\n        </span>\n        <span\n          v-if=\"nodeDef.description && showCategory\"\n          class=\"h-3 w-px shrink-0 bg-border-default\"\n        />\n        <TextTicker v-if=\"nodeDef.description\" class=\"min-w-0 flex-1\">\n          {{ nodeDef.description }}\n        </TextTicker>\n      </div>\n    </div>\n    <div v-if=\"!showDescription\" class=\"flex items-center gap-1\">\n      <span\n        v-if=\"nodeDef.deprecated\"\n        class=\"rounded-sm bg-red-500/20 px-1.5 py-0.5 text-xs text-red-400\"\n      >\n        {{ $t('g.deprecated') }}\n      </span>\n      <span\n        v-if=\"nodeDef.experimental\"\n        class=\"rounded-sm bg-blue-500/20 px-1.5 py-0.5 text-xs text-blue-400\"\n      >\n        {{ $t('g.experimental') }}\n      </span>\n      <span\n        v-if=\"nodeDef.dev_only\"\n        class=\"rounded-sm bg-cyan-500/20 px-1.5 py-0.5 text-xs text-cyan-400\"\n      >\n        {{ $t('g.devOnly') }}\n      </span>\n      <span\n        v-if=\"showNodeFrequency && nodeFrequency > 0\"\n        data-testid=\"frequency-badge\"\n        class=\"rounded-sm bg-secondary-background px-1.5 py-0.5 text-xs text-muted-foreground\"\n      >\n        {{ formatNumberWithSuffix(nodeFrequency, { roundToInt: true }) }}\n      </span>\n      <span\n        v-if=\"nodeDef.nodeSource.type !== NodeSourceType.Unknown\"\n        class=\"rounded-sm bg-secondary-background px-2 py-0.5 text-sm text-muted-foreground\"\n      >\n        {{ nodeDef.nodeSource.displayText }}\n      </span>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport TextTicker from '@/components/common/TextTicker.vue'\nimport NodePricingBadge from '@/components/node/NodePricingBadge.vue'\nimport NodeProviderBadge from '@/components/node/NodeProviderBadge.vue'\nimport HighlightedText from '@/components/searchbox/HighlightedText.vue'\nimport { NODE_TO_ESSENTIALS_CATEGORY } from '@/constants/essentialsNodes'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useNodeBookmarkStore } from '@/stores/nodeBookmarkStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeFrequencyStore } from '@/stores/nodeDefStore'\nimport { CORE_NODE_MODULES, NodeSourceType } from '@/types/nodeSource'\nimport { getProviderIcon, getProviderName } from '@/utils/categoryUtil'\nimport { formatNumberWithSuffix } from '@/utils/formatUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  nodeDef,\n  currentQuery,\n  showDescription = false,\n  showSourceBadge = false,\n  hideBookmarkIcon = false\n} = defineProps<{\n  nodeDef: ComfyNodeDefImpl\n  currentQuery: string\n  showDescription?: boolean\n  showSourceBadge?: boolean\n  hideBookmarkIcon?: boolean\n}>()\n\nconst badgePillClass =\n  'flex h-[18px] max-w-28 shrink-0 items-center justify-center gap-1 rounded-full bg-secondary-background-hover/80 px-2'\n\nconst settingStore = useSettingStore()\nconst showCategory = computed(() =>\n  settingStore.get('Comfy.NodeSearchBoxImpl.ShowCategory')\n)\nconst showIdName = computed(\n  () =>\n    settingStore.get('Comfy.NodeSearchBoxImpl.ShowIdName') &&\n    nodeDef.nodeSource.type !== NodeSourceType.Blueprint\n)\nconst showNodeFrequency = computed(() =>\n  settingStore.get('Comfy.NodeSearchBoxImpl.ShowNodeFrequency')\n)\nconst nodeFrequencyStore = useNodeFrequencyStore()\nconst nodeFrequency = computed(() =>\n  nodeFrequencyStore.getNodeFrequency(nodeDef)\n)\n\nconst nodeBookmarkStore = useNodeBookmarkStore()\nconst isBookmarked = computed(() => nodeBookmarkStore.isBookmarked(nodeDef))\nconst providerName = computed(() => getProviderName(nodeDef.category))\nconst isCore = computed(() =>\n  CORE_NODE_MODULES.includes(nodeDef.python_module.split('.')[0])\n)\nconst isEssential = computed(() => !!NODE_TO_ESSENTIALS_CATEGORY[nodeDef.name])\n</script>\n","<template>\n  <div\n    ref=\"dialogRef\"\n    class=\"flex h-[min(80vh,750px)] w-full flex-col overflow-hidden rounded-lg border border-interface-stroke bg-base-background\"\n  >\n    <!-- Search input row -->\n    <NodeSearchInput\n      ref=\"searchInputRef\"\n      v-model:search-query=\"searchQuery\"\n      :filters=\"filters\"\n      @remove-filter=\"emit('removeFilter', $event)\"\n      @navigate-down=\"navigateResults(1)\"\n      @navigate-up=\"navigateResults(-1)\"\n      @select-current=\"selectCurrentResult\"\n      @focusin=\"onSearchFocus\"\n    />\n\n    <!-- Filter header row -->\n    <div class=\"flex items-center\">\n      <NodeSearchFilterBar\n        v-model:is-sidebar-open=\"isSidebarOpen\"\n        class=\"flex-1\"\n        :filters=\"filters\"\n        :active-category=\"rootFilter\"\n        :has-favorites=\"nodeBookmarkStore.bookmarks.length > 0\"\n        :has-essential-nodes=\"nodeAvailability.essential\"\n        :has-blueprint-nodes=\"nodeAvailability.blueprint\"\n        :has-partner-nodes=\"nodeAvailability.partner\"\n        :has-custom-nodes=\"nodeAvailability.custom\"\n        @toggle-filter=\"onToggleFilter\"\n        @clear-filter-group=\"onClearFilterGroup\"\n        @focus-search=\"nextTick(() => searchInputRef?.focus())\"\n        @select-category=\"onSelectCategory\"\n      />\n    </div>\n\n    <!-- Content area -->\n    <div class=\"relative flex min-h-0 flex-1 overflow-hidden\">\n      <NodeSearchCategorySidebar\n        v-show=\"isSidebarOpen\"\n        id=\"node-search-category-sidebar\"\n        v-model:selected-category=\"sidebarCategory\"\n        :aria-label=\"isMobile ? t('g.categories') : undefined\"\n        class=\"w-52 shrink-0 max-md:absolute max-md:inset-y-0 max-md:left-0 max-md:z-20 max-md:bg-base-background max-md:shadow-interface\"\n        :hide-chevrons=\"!anyTreeCategoryHasChildren\"\n        :hide-presets=\"rootFilter !== null\"\n        :node-defs=\"rootFilteredNodeDefs\"\n        :root-label=\"rootFilterLabel\"\n        :root-key=\"rootFilter ?? undefined\"\n        @auto-expand=\"selectedCategory = $event\"\n      />\n\n      <!-- Mobile overlay backdrop to close sidebar on outside click -->\n      <div\n        v-if=\"isMobile && isSidebarOpen\"\n        data-testid=\"sidebar-backdrop\"\n        class=\"absolute inset-0 z-10 md:hidden\"\n        @click=\"isSidebarOpen = false\"\n      />\n\n      <!-- Results list -->\n      <div\n        id=\"results-list\"\n        role=\"listbox\"\n        tabindex=\"-1\"\n        class=\"flex-1 overflow-y-auto py-2 pr-3 pl-1 select-none\"\n        @pointermove=\"onPointerMove\"\n      >\n        <div\n          v-for=\"(node, index) in displayedResults\"\n          :id=\"`result-item-${index}`\"\n          :key=\"node.name\"\n          role=\"option\"\n          data-testid=\"result-item\"\n          :tabindex=\"index === selectedIndex ? 0 : -1\"\n          :aria-selected=\"index === selectedIndex\"\n          :class=\"\n            cn(\n              'flex h-14 cursor-pointer items-center rounded-lg px-4 outline-none focus-visible:ring-2 focus-visible:ring-primary',\n              index === selectedIndex && 'bg-secondary-background'\n            )\n          \"\n          @click=\"emit('addNode', node, $event)\"\n          @keydown.down.prevent=\"navigateResults(1, true)\"\n          @keydown.up.prevent=\"navigateResults(-1, true)\"\n          @keydown.enter.prevent=\"selectCurrentResult\"\n        >\n          <NodeSearchListItem\n            :node-def=\"node\"\n            :current-query=\"searchQuery\"\n            show-description\n            :show-source-badge=\"rootFilter !== RootCategory.Essentials\"\n            :hide-bookmark-icon=\"selectedCategory === RootCategory.Favorites\"\n          />\n        </div>\n        <div\n          v-if=\"displayedResults.length === 0\"\n          data-testid=\"no-results\"\n          class=\"px-4 py-8 text-center text-muted-foreground\"\n        >\n          {{ $t('g.noResults') }}\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { breakpointsTailwind, useBreakpoints } from '@vueuse/core'\nimport { computed, nextTick, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport NodeSearchFilterBar from '@/components/searchbox/v2/NodeSearchFilterBar.vue'\nimport NodeSearchCategorySidebar, {\n  DEFAULT_CATEGORY\n} from '@/components/searchbox/v2/NodeSearchCategorySidebar.vue'\nimport NodeSearchInput from '@/components/searchbox/v2/NodeSearchInput.vue'\nimport NodeSearchListItem from '@/components/searchbox/v2/NodeSearchListItem.vue'\nimport { RootCategory } from '@/components/searchbox/v2/rootCategories'\nimport type { RootCategoryId } from '@/components/searchbox/v2/rootCategories'\nimport { useSearchQueryTracking } from '@/platform/telemetry/searchQuery/useSearchQueryTracking'\nimport { useNodeBookmarkStore } from '@/stores/nodeBookmarkStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeDefStore, useNodeFrequencyStore } from '@/stores/nodeDefStore'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport {\n  BLUEPRINT_CATEGORY,\n  isCustomNode,\n  isEssentialNode,\n  NodeSourceType\n} from '@/types/nodeSource'\nimport type { FuseFilter, FuseFilterWithValue } from '@/utils/fuseUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst sourceCategoryFilters: Record<string, (n: ComfyNodeDefImpl) => boolean> =\n  {\n    [RootCategory.Essentials]: isEssentialNode,\n    [RootCategory.Comfy]: (n) => n.nodeSource.type === NodeSourceType.Core,\n    [RootCategory.Custom]: isCustomNode\n  }\n\nconst { filters } = defineProps<{\n  filters: FuseFilterWithValue<ComfyNodeDefImpl, string>[]\n}>()\n\nconst emit = defineEmits<{\n  addNode: [nodeDef: ComfyNodeDefImpl, dragEvent?: MouseEvent]\n  addFilter: [filter: FuseFilterWithValue<ComfyNodeDefImpl, string>]\n  removeFilter: [filter: FuseFilterWithValue<ComfyNodeDefImpl, string>]\n  hoverNode: [nodeDef: ComfyNodeDefImpl | null]\n}>()\n\nconst { t } = useI18n()\nconst { flags } = useFeatureFlags()\nconst nodeDefStore = useNodeDefStore()\nconst nodeFrequencyStore = useNodeFrequencyStore()\nconst nodeBookmarkStore = useNodeBookmarkStore()\n\nconst nodeAvailability = computed(() => {\n  let essential = false\n  let blueprint = false\n  let partner = false\n  let custom = false\n  for (const n of nodeDefStore.visibleNodeDefs) {\n    if (!essential && flags.nodeLibraryEssentialsEnabled && isEssentialNode(n))\n      essential = true\n    if (!blueprint && n.category.startsWith(BLUEPRINT_CATEGORY))\n      blueprint = true\n    if (!partner && n.api_node) partner = true\n    if (!custom && isCustomNode(n)) custom = true\n    if (essential && blueprint && partner && custom) break\n  }\n  return { essential, blueprint, partner, custom }\n})\n\nconst dialogRef = ref<HTMLElement>()\nconst searchInputRef = ref<InstanceType<typeof NodeSearchInput>>()\n\nconst searchQuery = ref('')\nconst selectedCategory = ref(DEFAULT_CATEGORY)\nconst selectedIndex = ref(0)\n\nconst isMobile = useBreakpoints(breakpointsTailwind).smaller('md')\nconst isSidebarOpen = ref(!isMobile.value)\nwatch(isMobile, (mobile) => {\n  // On transitioning to mobile state, close the sidebar\n  if (mobile) isSidebarOpen.value = false\n})\n\nfunction onSearchFocus() {\n  if (isMobile.value) isSidebarOpen.value = false\n}\n\n// Root filter from filter bar category buttons (radio toggle)\nconst rootFilter = ref<RootCategoryId | null>(null)\n\nconst rootFilterLabel = computed(() => {\n  switch (rootFilter.value) {\n    case RootCategory.Favorites:\n      return t('g.bookmarked')\n    case RootCategory.Blueprint:\n      return t('g.blueprints')\n    case RootCategory.PartnerNodes:\n      return t('g.partner')\n    case RootCategory.Essentials:\n      return t('g.essentials')\n    case RootCategory.Comfy:\n      return t('g.comfy')\n    case RootCategory.Custom:\n      return t('g.extensions')\n    default:\n      return undefined\n  }\n})\n\nconst rootFilteredNodeDefs = computed(() => {\n  if (!rootFilter.value) return nodeDefStore.visibleNodeDefs\n  const allNodes = nodeDefStore.visibleNodeDefs\n  const sourceFilter = sourceCategoryFilters[rootFilter.value]\n  if (sourceFilter) return allNodes.filter(sourceFilter)\n  switch (rootFilter.value) {\n    case RootCategory.Favorites:\n      return allNodes.filter((n) => nodeBookmarkStore.isBookmarked(n))\n    case RootCategory.Blueprint:\n      return allNodes.filter((n) => n.category.startsWith(BLUEPRINT_CATEGORY))\n    case RootCategory.PartnerNodes:\n      return allNodes.filter((n) => n.api_node)\n    default:\n      return allNodes\n  }\n})\n\nfunction onToggleFilter(\n  filterDef: FuseFilter<ComfyNodeDefImpl, string>,\n  value: string\n) {\n  const existing = filters.find(\n    (f) => f.filterDef.id === filterDef.id && f.value === value\n  )\n  if (existing) {\n    emit('removeFilter', existing)\n  } else {\n    emit('addFilter', { filterDef, value })\n  }\n}\n\nfunction onClearFilterGroup(filterId: string) {\n  for (const f of filters.filter((f) => f.filterDef.id === filterId)) {\n    emit('removeFilter', f)\n  }\n}\n\nfunction onSelectCategory(category: RootCategoryId) {\n  if (rootFilter.value === category) {\n    rootFilter.value = null\n  } else {\n    rootFilter.value = category\n  }\n  selectedCategory.value = DEFAULT_CATEGORY\n  nextTick(() => searchInputRef.value?.focus())\n}\n\nconst searchResults = computed(() => {\n  if (!searchQuery.value && filters.length === 0) {\n    return nodeFrequencyStore.topNodeDefs\n  }\n  return nodeDefStore.nodeSearchService.searchNode(searchQuery.value, filters, {\n    limit: 64\n  })\n})\n\nconst sidebarCategory = computed({\n  get: () => selectedCategory.value,\n  set: (category: string) => {\n    selectedCategory.value = category\n  }\n})\n\n// Check if any tree category has children (for chevron visibility)\nconst anyTreeCategoryHasChildren = computed(() =>\n  rootFilteredNodeDefs.value.some((n) => n.category.includes('/'))\n)\n\nfunction getMostRelevantResults(baseNodes: ComfyNodeDefImpl[]) {\n  if (searchQuery.value || filters.length > 0) {\n    const searched = searchResults.value\n    if (!rootFilter.value) return searched\n    const rootSet = new Set(baseNodes.map((n) => n.name))\n    return searched.filter((n) => rootSet.has(n.name))\n  }\n  return rootFilter.value ? baseNodes : nodeFrequencyStore.topNodeDefs\n}\n\nfunction getCategoryResults(baseNodes: ComfyNodeDefImpl[], category: string) {\n  if (rootFilter.value && category === rootFilter.value) return baseNodes\n  const rootPrefix = rootFilter.value ? rootFilter.value + '/' : ''\n  const categoryPath = category.startsWith(rootPrefix)\n    ? category.slice(rootPrefix.length)\n    : category\n  return baseNodes.filter((n) => {\n    const nodeCategory = n.category.startsWith(rootPrefix)\n      ? n.category.slice(rootPrefix.length)\n      : n.category\n    return (\n      nodeCategory === categoryPath ||\n      nodeCategory.startsWith(categoryPath + '/')\n    )\n  })\n}\n\nconst displayedResults = computed<ComfyNodeDefImpl[]>(() => {\n  const baseNodes = rootFilteredNodeDefs.value\n  const category = selectedCategory.value\n\n  if (category === DEFAULT_CATEGORY) return getMostRelevantResults(baseNodes)\n\n  const hasSearch = searchQuery.value || filters.length > 0\n  let source: ComfyNodeDefImpl[]\n  if (hasSearch) {\n    const searched = searchResults.value\n    if (rootFilter.value) {\n      const rootSet = new Set(baseNodes.map((n) => n.name))\n      source = searched.filter((n) => rootSet.has(n.name))\n    } else {\n      source = searched\n    }\n  } else {\n    source = baseNodes\n  }\n\n  const sourceFilter = sourceCategoryFilters[category]\n  if (sourceFilter) return source.filter(sourceFilter)\n  return getCategoryResults(source, category)\n})\n\nconst hoveredNodeDef = computed(\n  () => displayedResults.value[selectedIndex.value] ?? null\n)\n\nuseSearchQueryTracking('node_modal', searchQuery, displayedResults)\n\nwatch(\n  hoveredNodeDef,\n  (newVal) => {\n    emit('hoverNode', newVal)\n  },\n  { immediate: true }\n)\n\nwatch([selectedCategory, searchQuery, rootFilter, () => filters.length], () => {\n  selectedIndex.value = 0\n})\n\nfunction onPointerMove(event: PointerEvent) {\n  const item = (event.target as HTMLElement).closest('[role=option]')\n  if (!item) return\n  const index = Number(item.id.replace('result-item-', ''))\n  if (!isNaN(index) && index !== selectedIndex.value)\n    selectedIndex.value = index\n}\n\nfunction navigateResults(direction: number, focusItem = false) {\n  const newIndex = selectedIndex.value + direction\n  if (newIndex >= 0 && newIndex < displayedResults.value.length) {\n    selectedIndex.value = newIndex\n    nextTick(() => {\n      const el = dialogRef.value?.querySelector(\n        `#result-item-${newIndex}`\n      ) as HTMLElement | null\n      el?.scrollIntoView({ block: 'nearest' })\n      if (focusItem) el?.focus()\n    })\n  }\n}\n\nfunction selectCurrentResult() {\n  const node = displayedResults.value[selectedIndex.value]\n  if (node) emit('addNode', node)\n}\n</script>\n","<template>\n  <div class=\"flex flex-col gap-2\">\n    <ToggleGroup\n      v-model=\"selectedFilterName\"\n      type=\"single\"\n      :allow-empty=\"false\"\n    >\n      <ToggleGroupItem\n        v-for=\"filter in filters\"\n        :key=\"filter.name\"\n        :value=\"filter.name\"\n      >\n        {{ filter.name }}\n      </ToggleGroupItem>\n    </ToggleGroup>\n    <SingleSelect\n      v-model=\"selectedFilterValue\"\n      :options=\"filterValues\"\n      searchable\n    />\n  </div>\n  <div class=\"flex flex-col items-end pt-4\">\n    <Button type=\"button\" @click=\"submit\">{{ $t('g.add') }}</Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref, watch } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport SingleSelect from '@/components/ui/single-select/SingleSelect.vue'\nimport { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport type { FuseFilter, FuseFilterWithValue } from '@/utils/fuseUtil'\n\nconst nodeDefStore = useNodeDefStore()\nconst filters = computed(() => nodeDefStore.nodeSearchService.nodeFilters)\nconst selectedFilterName = ref(filters.value[0]?.name)\nconst selectedFilter = computed<\n  FuseFilter<ComfyNodeDefImpl, string> | undefined\n>(() =>\n  filters.value.find((filter) => filter.name === selectedFilterName.value)\n)\nconst filterValues = computed(() =>\n  (selectedFilter.value?.fuseSearch.data ?? []).map((value) => ({\n    name: value,\n    value\n  }))\n)\nconst selectedFilterValue = ref<string>('')\n\nconst emit = defineEmits<{\n  (\n    event: 'addFilter',\n    filterAndValue: FuseFilterWithValue<ComfyNodeDefImpl, string>\n  ): void\n}>()\n\nconst updateSelectedFilterValue = () => {\n  if (\n    filterValues.value.some(({ value }) => value === selectedFilterValue.value)\n  ) {\n    return\n  }\n  selectedFilterValue.value = String(filterValues.value[0]?.value ?? '')\n}\n\nwatch(selectedFilterName, updateSelectedFilterValue, { immediate: true })\n\nconst submit = () => {\n  if (!selectedFilter.value) {\n    return\n  }\n  emit('addFilter', {\n    filterDef: selectedFilter.value,\n    value: selectedFilterValue.value\n  })\n}\n</script>\n","<template>\n  <div\n    class=\"option-container flex w-full cursor-pointer items-center justify-between overflow-hidden px-2 py-0\"\n  >\n    <div class=\"option-display-name flex flex-col font-semibold\">\n      <div>\n        <span v-if=\"isBookmarked\">\n          <i class=\"pi pi-bookmark-fill mr-1 text-sm\" />\n        </span>\n        <span>\n          <HighlightedText :text=\"nodeDef.display_name\" :query=\"currentQuery\" />\n        </span>\n        <span>&nbsp;</span>\n        <Badge v-if=\"showIdName\" severity=\"secondary\">\n          <span>\n            <HighlightedText :text=\"nodeDef.name\" :query=\"currentQuery\" />\n          </span>\n        </Badge>\n      </div>\n      <div\n        v-if=\"showCategory\"\n        class=\"option-category truncate text-sm font-light text-muted\"\n      >\n        {{ nodeDef.category.replaceAll('/', ' > ') }}\n      </div>\n    </div>\n    <div class=\"option-badges\">\n      <Badge v-if=\"nodeDef.deprecated\" severity=\"danger\">\n        {{ $t('g.deprecated') }}\n      </Badge>\n      <Badge v-if=\"nodeDef.experimental\" severity=\"primary\">\n        {{ $t('g.experimental') }}\n      </Badge>\n      <Badge v-if=\"nodeDef.dev_only\" severity=\"info\">\n        {{ $t('g.devOnly') }}\n      </Badge>\n      <Badge v-if=\"showNodeFrequency && nodeFrequency > 0\" severity=\"secondary\">\n        {{ formatNumberWithSuffix(nodeFrequency, { roundToInt: true }) }}\n      </Badge>\n      <Badge\n        v-if=\"nodeDef.nodeSource.type !== NodeSourceType.Unknown\"\n        variant=\"chip\"\n        class=\"text-sm font-light\"\n      >\n        {{ nodeDef.nodeSource.displayText }}\n      </Badge>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport HighlightedText from '@/components/searchbox/HighlightedText.vue'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useNodeBookmarkStore } from '@/stores/nodeBookmarkStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeFrequencyStore } from '@/stores/nodeDefStore'\nimport { NodeSourceType } from '@/types/nodeSource'\nimport { formatNumberWithSuffix } from '@/utils/formatUtil'\n\nconst settingStore = useSettingStore()\nconst showCategory = computed(() =>\n  settingStore.get('Comfy.NodeSearchBoxImpl.ShowCategory')\n)\nconst showIdName = computed(() =>\n  settingStore.get('Comfy.NodeSearchBoxImpl.ShowIdName')\n)\nconst showNodeFrequency = computed(() =>\n  settingStore.get('Comfy.NodeSearchBoxImpl.ShowNodeFrequency')\n)\nconst nodeFrequencyStore = useNodeFrequencyStore()\nconst nodeFrequency = computed(() =>\n  nodeFrequencyStore.getNodeFrequency(props.nodeDef)\n)\n\nconst nodeBookmarkStore = useNodeBookmarkStore()\nconst isBookmarked = computed(() =>\n  nodeBookmarkStore.isBookmarked(props.nodeDef)\n)\n\nconst props = defineProps<{\n  nodeDef: ComfyNodeDefImpl\n  currentQuery: string\n}>()\n</script>\n\n<style scoped>\n:deep(.highlight) {\n  background-color: var(--p-primary-color);\n  color: var(--p-primary-contrast-color);\n  font-weight: 700;\n  border-radius: 0.25rem;\n  padding: 0 0.125rem;\n  margin: -0.125rem 0.125rem;\n}\n</style>\n","<template>\n  <Badge\n    variant=\"chip\"\n    removable\n    :remove-label=\"$t('g.removeFilter', { label: `${badge}: ${text}` })\"\n    @remove=\"emit('remove', $event)\"\n  >\n    <Badge variant=\"badge\" :class=\"semanticBadgeClass\">\n      {{ badge }}\n    </Badge>\n    {{ text }}\n  </Badge>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Badge from '@/components/ui/badge/Badge.vue'\n\nexport interface SearchFilter {\n  text: string\n  badge: string\n  badgeClass: string\n  id: string | number\n}\n\nconst semanticClassMap: Record<string, string> = {\n  'i-badge': 'bg-green-500 text-white',\n  'o-badge': 'bg-red-500 text-white',\n  'c-badge': 'bg-blue-500 text-white',\n  's-badge': 'bg-yellow-500'\n}\n\nconst props = defineProps<Omit<SearchFilter, 'id'>>()\nconst emit = defineEmits<{\n  (e: 'remove', event: Event): void\n}>()\n\nconst semanticBadgeClass = computed(() => {\n  return semanticClassMap[props.badgeClass] ?? props.badgeClass\n})\n</script>\n","<template>\n  <div\n    class=\"comfy-vue-node-search-container flex w-full min-w-96 items-center justify-center\"\n  >\n    <div\n      v-if=\"enableNodePreview && hoveredSuggestion\"\n      class=\"comfy-vue-node-preview-container absolute top-[50px] left-[-375px] z-50 cursor-pointer\"\n      @mousedown.stop=\"onAddNode(hoveredSuggestion!, $event)\"\n    >\n      <NodePreview\n        :key=\"hoveredSuggestion?.name || ''\"\n        :node-def=\"hoveredSuggestion\"\n      />\n    </div>\n\n    <Button\n      variant=\"secondary\"\n      :aria-label=\"$t('g.addNodeFilterCondition')\"\n      class=\"filter-button z-10\"\n      @click=\"filterVisible = true\"\n    >\n      <i class=\"pi pi-filter\" />\n    </Button>\n    <Dialog :open=\"filterVisible\" @update:open=\"onFilterDialogOpenChange\">\n      <DialogPortal>\n        <DialogOverlay\n          v-reka-z-index\n          data-testid=\"node-search-filter-overlay\"\n          @pointerdown.self.stop=\"filterVisible = false\"\n        />\n        <DialogContent\n          v-reka-z-index\n          class=\"min-w-96\"\n          @escape-key-down=\"$event.isComposing && $event.preventDefault()\"\n          @pointer-down-outside=\"(e) => onRekaPointerDownOutside({}, e)\"\n          @close-auto-focus=\"onFilterDialogCloseAutoFocus\"\n        >\n          <DialogHeader>\n            <DialogTitle>{{ $t('g.addNodeFilterCondition') }}</DialogTitle>\n            <DialogClose />\n          </DialogHeader>\n          <div class=\"px-4 py-2\">\n            <NodeSearchFilter @add-filter=\"onAddFilter\" />\n          </div>\n        </DialogContent>\n      </DialogPortal>\n    </Dialog>\n\n    <SearchAutocomplete\n      ref=\"searchAutocomplete\"\n      v-model=\"currentQuery\"\n      class=\"comfy-vue-node-search-box z-10 grow\"\n      anchor-class=\"h-auto min-h-8 flex-wrap\"\n      :content-style=\"{ maxHeight: '40vh' }\"\n      :placeholder=\"placeholder\"\n      :input-id=\"inputId\"\n      :suggestions=\"suggestions\"\n      :loading=\"!nodeFrequencyStore.isLoaded\"\n      open-on-focus\n      :update-model-on-select=\"false\"\n      option-label=\"display_name\"\n      option-key=\"name\"\n      @select=\"onAddNode\"\n      @highlight=\"setHoverSuggestion\"\n    >\n      <template #suggestion=\"{ suggestion }\">\n        <NodeSearchItem :node-def=\"suggestion\" :current-query=\"currentQuery\" />\n      </template>\n      <template #leading>\n        <div v-if=\"filters.length\" class=\"ml-8 flex flex-wrap gap-1 py-1\">\n          <template\n            v-for=\"filter in filters\"\n            :key=\"`${filter.filterDef?.id}-${filter.value}`\"\n          >\n            <SearchFilterChip\n              v-if=\"filter.filterDef && filter.value\"\n              data-testid=\"node-search-filter-chip\"\n              :text=\"filter.value\"\n              :badge=\"filter.filterDef.invokeSequence.toUpperCase()\"\n              :badge-class=\"filter.filterDef.invokeSequence + '-badge'\"\n              @remove=\"onRemoveFilter($event, filter)\"\n            />\n          </template>\n        </div>\n      </template>\n    </SearchAutocomplete>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { debounce } from 'es-toolkit/compat'\nimport { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { vRekaZIndex } from '@/components/dialog/vRekaZIndex'\nimport { onRekaPointerDownOutside } from '@/components/dialog/dialogDismissGuards'\nimport NodePreview from '@/components/node/NodePreview.vue'\nimport NodeSearchFilter from '@/components/searchbox/NodeSearchFilter.vue'\nimport NodeSearchItem from '@/components/searchbox/NodeSearchItem.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Dialog from '@/components/ui/dialog/Dialog.vue'\nimport DialogClose from '@/components/ui/dialog/DialogClose.vue'\nimport DialogContent from '@/components/ui/dialog/DialogContent.vue'\nimport DialogHeader from '@/components/ui/dialog/DialogHeader.vue'\nimport DialogOverlay from '@/components/ui/dialog/DialogOverlay.vue'\nimport DialogPortal from '@/components/ui/dialog/DialogPortal.vue'\nimport DialogTitle from '@/components/ui/dialog/DialogTitle.vue'\nimport SearchAutocomplete from '@/components/ui/search-input/SearchAutocomplete.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useSearchQueryTracking } from '@/platform/telemetry/searchQuery/useSearchQueryTracking'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeDefStore, useNodeFrequencyStore } from '@/stores/nodeDefStore'\nimport type { FuseFilterWithValue } from '@/utils/fuseUtil'\n\nimport SearchFilterChip from '../common/SearchFilterChip.vue'\n\nconst settingStore = useSettingStore()\nconst { t } = useI18n()\nconst telemetry = useTelemetry()\n\nconst enableNodePreview = computed(() =>\n  settingStore.get('Comfy.NodeSearchBoxImpl.NodePreview')\n)\n\nconst { filters, searchLimit = 64 } = defineProps<{\n  filters: FuseFilterWithValue<ComfyNodeDefImpl, string>[]\n  searchLimit?: number\n}>()\n\nconst searchAutocomplete = ref<{\n  focus: () => void\n  open: () => void\n} | null>(null)\nconst filterVisible = defineModel<boolean>('filterVisible', { required: true })\nconst inputId = `comfy-vue-node-search-box-input-${Math.random()}`\nconst suggestions = ref<ComfyNodeDefImpl[]>([])\nconst hoveredSuggestion = ref<ComfyNodeDefImpl | null>(null)\nconst currentQuery = ref('')\nconst placeholder = computed(() => {\n  return filters.length === 0\n    ? t('g.searchPlaceholder', { subject: t('g.nodes') })\n    : ''\n})\n\nconst nodeDefStore = useNodeDefStore()\nconst nodeFrequencyStore = useNodeFrequencyStore()\n\nuseSearchQueryTracking('node_modal', currentQuery, suggestions)\n\n// Debounced search tracking (500ms as per implementation plan)\nconst debouncedTrackSearch = debounce((query: string) => {\n  if (query.trim()) {\n    telemetry?.trackNodeSearch({ query })\n  }\n}, 500)\n\nconst search = (query: string) => {\n  const queryIsEmpty = query === '' && filters.length === 0\n  currentQuery.value = query\n  suggestions.value = queryIsEmpty\n    ? nodeFrequencyStore.topNodeDefs\n    : [\n        ...nodeDefStore.nodeSearchService.searchNode(query, filters, {\n          limit: searchLimit\n        })\n      ]\n\n  // Track search queries with debounce\n  debouncedTrackSearch(query)\n}\n\nconst debouncedSearch = debounce(search, 100)\nwatch(currentQuery, debouncedSearch)\nonUnmounted(() => {\n  debouncedSearch.cancel()\n  debouncedTrackSearch.cancel()\n})\n\nconst emit = defineEmits<{\n  addFilter: [filter: FuseFilterWithValue<ComfyNodeDefImpl, string>]\n  removeFilter: [filter: FuseFilterWithValue<ComfyNodeDefImpl, string>]\n  addNode: [nodeDef: ComfyNodeDefImpl, dragEvent?: MouseEvent]\n}>()\n\n// Track node selection and emit addNode event\nfunction onAddNode(nodeDef: ComfyNodeDefImpl, event?: MouseEvent) {\n  telemetry?.trackNodeSearchResultSelected({\n    node_type: nodeDef.name,\n    last_query: currentQuery.value\n  })\n  emit('addNode', nodeDef, event)\n}\n\nconst reFocusInput = async () => {\n  search(currentQuery.value)\n  await nextTick()\n  searchAutocomplete.value?.focus()\n  searchAutocomplete.value?.open()\n}\n\nfunction onFilterDialogOpenChange(open: boolean) {\n  filterVisible.value = open\n}\n\nfunction onFilterDialogCloseAutoFocus(event: Event) {\n  event.preventDefault()\n  void reFocusInput()\n}\n\nonMounted(() => {\n  search('')\n  void nextTick(() => {\n    searchAutocomplete.value?.focus()\n    searchAutocomplete.value?.open()\n  })\n})\nconst onAddFilter = (\n  filterAndValue: FuseFilterWithValue<ComfyNodeDefImpl, string>\n) => {\n  filterVisible.value = false\n  emit('addFilter', filterAndValue)\n}\nconst onRemoveFilter = async (\n  event: Event,\n  filterAndValue: FuseFilterWithValue<ComfyNodeDefImpl, string>\n) => {\n  event.stopPropagation()\n  event.preventDefault()\n  emit('removeFilter', filterAndValue)\n  await nextTick()\n  await reFocusInput()\n}\nconst setHoverSuggestion = (suggestion: ComfyNodeDefImpl | undefined) => {\n  hoveredSuggestion.value = suggestion ?? null\n}\n</script>\n","<template>\n  <div>\n    <Dialog v-model:open=\"visible\">\n      <DialogPortal>\n        <DialogOverlay v-reka-z-index />\n        <DialogContent\n          v-reka-z-index\n          :class=\"\n            cn(\n              'border-0 bg-transparent p-0 shadow-none duration-100',\n              useSearchBoxV2\n                ? 'w-full max-w-4xl min-w-lg overflow-visible max-md:min-w-0 sm:max-w-4xl'\n                : 'top-1/4 ml-[200px] w-3/5 max-w-3xl min-w-96 translate-y-0 max-md:ml-0 sm:max-w-3xl'\n            )\n          \"\n          @pointer-down-outside=\"\n            (e) =>\n              onRekaPointerDownOutside(\n                { dismissOnPointerDownOutside: dismissable },\n                e\n              )\n          \"\n          @escape-key-down=\"\n            (filterVisible || $event.isComposing) && $event.preventDefault()\n          \"\n        >\n          <DialogTitle class=\"sr-only\">{{ $t('g.searchNodes') }}</DialogTitle>\n          <div v-if=\"useSearchBoxV2\" role=\"search\" class=\"relative\">\n            <NodeSearchContent\n              :filters=\"nodeFilters\"\n              @add-filter=\"addFilter\"\n              @remove-filter=\"removeFilter\"\n              @add-node=\"addNode\"\n              @hover-node=\"hoveredNodeDef = $event\"\n            />\n            <NodePreviewCard\n              v-if=\"hoveredNodeDef && enableNodePreview\"\n              :key=\"hoveredNodeDef.name\"\n              :node-def=\"hoveredNodeDef\"\n              :scale-factor=\"0.625\"\n              show-category-path\n              inert\n              class=\"absolute top-0 left-full ml-3\"\n            />\n          </div>\n          <NodeSearchBox\n            v-else\n            v-model:filter-visible=\"filterVisible\"\n            :filters=\"nodeFilters\"\n            @keydown.escape=\"!$event.isComposing && closeDialog()\"\n            @add-filter=\"addFilter\"\n            @remove-filter=\"removeFilter\"\n            @add-node=\"addNode\"\n          />\n        </DialogContent>\n      </DialogPortal>\n    </Dialog>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useEventListener, useWindowSize } from '@vueuse/core'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { storeToRefs } from 'pinia'\nimport { computed, ref, toRaw, watch, watchEffect } from 'vue'\n\nimport { revealDynamicInputSlot } from '@/core/graph/widgets/revealDynamicInputSlot'\nimport type { Point } from '@/lib/litegraph/src/interfaces'\nimport { onRekaPointerDownOutside } from '@/components/dialog/dialogDismissGuards'\nimport { vRekaZIndex } from '@/components/dialog/vRekaZIndex'\nimport Dialog from '@/components/ui/dialog/Dialog.vue'\nimport DialogContent from '@/components/ui/dialog/DialogContent.vue'\nimport DialogOverlay from '@/components/ui/dialog/DialogOverlay.vue'\nimport DialogPortal from '@/components/ui/dialog/DialogPortal.vue'\nimport DialogTitle from '@/components/ui/dialog/DialogTitle.vue'\nimport type { LiteGraphCanvasEvent } from '@/lib/litegraph/src/litegraph'\nimport { LGraphNode, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { CanvasPointerEvent } from '@/lib/litegraph/src/types/events'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useSurveyFeatureTracking } from '@/platform/surveys/useSurveyFeatureTracking'\nimport { withNodeAddSource } from '@/platform/telemetry/nodeAdded/nodeAddSource'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useSearchBoxStore } from '@/stores/workspace/searchBoxStore'\nimport { LinkReleaseTriggerAction } from '@/types/searchBoxTypes'\nimport type { FuseFilterWithValue } from '@/utils/fuseUtil'\n\nimport NodePreviewCard from '@/components/node/NodePreviewCard.vue'\n\nimport NodeSearchContent from './v2/NodeSearchContent.vue'\nimport NodeSearchBox from './NodeSearchBox.vue'\n\nlet triggerEvent: CanvasPointerEvent | null = null\nlet listenerController: AbortController | null = null\nlet disconnectOnReset = false\n\nconst settingStore = useSettingStore()\nconst searchBoxStore = useSearchBoxStore()\nconst litegraphService = useLitegraphService()\nconst { trackFeatureUsed } = useSurveyFeatureTracking('node-search')\n\nconst { visible, newSearchBoxEnabled, useSearchBoxV2 } =\n  storeToRefs(searchBoxStore)\nconst dismissable = ref(true)\nconst filterVisible = ref(false)\nconst hoveredNodeDef = ref<ComfyNodeDefImpl | null>(null)\nconst { width: windowWidth } = useWindowSize()\n// Minimum viewport width for the preview panel to fit beside the dialog\nconst MIN_WIDTH_FOR_PREVIEW = 1320\nconst enableNodePreview = computed(\n  () =>\n    useSearchBoxV2.value &&\n    settingStore.get('Comfy.NodeSearchBoxImpl.NodePreview') &&\n    windowWidth.value >= MIN_WIDTH_FOR_PREVIEW\n)\nfunction getNewNodeLocation(): Point {\n  return triggerEvent\n    ? [triggerEvent.canvasX, triggerEvent.canvasY]\n    : litegraphService.getCanvasCenter()\n}\nconst nodeFilters = ref<FuseFilterWithValue<ComfyNodeDefImpl, string>[]>([])\nfunction addFilter(filter: FuseFilterWithValue<ComfyNodeDefImpl, string>) {\n  const isDuplicate = nodeFilters.value.some(\n    (f) => f.filterDef.id === filter.filterDef.id && f.value === filter.value\n  )\n  if (!isDuplicate) nodeFilters.value.push(filter)\n}\nfunction removeFilter(filter: FuseFilterWithValue<ComfyNodeDefImpl, string>) {\n  nodeFilters.value = nodeFilters.value.filter(\n    (f) => toRaw(f) !== toRaw(filter)\n  )\n}\nfunction clearFilters() {\n  nodeFilters.value = []\n  filterVisible.value = false\n  hoveredNodeDef.value = null\n}\n\nfunction closeDialog() {\n  visible.value = false\n}\nconst canvasStore = useCanvasStore()\n\nfunction addNode(nodeDef: ComfyNodeDefImpl, dragEvent?: MouseEvent) {\n  const followCursor = settingStore.get('Comfy.NodeSearchBoxImpl.FollowCursor')\n  const node = withNodeAddSource('search_modal', () =>\n    litegraphService.addNodeOnGraph(\n      nodeDef,\n      { pos: getNewNodeLocation() },\n      { ghost: useSearchBoxV2.value && followCursor, dragEvent }\n    )\n  )\n  if (!node) return\n\n  if (disconnectOnReset && triggerEvent) {\n    revealSlotForDroppedLink(node)\n    canvasStore.getCanvas().linkConnector.connectToNode(node, triggerEvent)\n  } else if (!triggerEvent) {\n    console.warn('The trigger event was undefined when addNode was called.')\n  }\n\n  disconnectOnReset = false\n\n  // Notify changeTracker - new step should be added\n  useWorkflowStore().activeWorkflow?.changeTracker?.captureCanvasState()\n  window.requestAnimationFrame(closeDialog)\n}\n\nfunction showSearchBox(e: CanvasPointerEvent | null) {\n  if (newSearchBoxEnabled.value) {\n    if (e?.pointerType === 'touch') {\n      setTimeout(() => {\n        showNewSearchBox(e)\n      }, 128)\n    } else {\n      showNewSearchBox(e)\n    }\n  } else {\n    canvasStore.getCanvas().showSearchBox(e)\n  }\n}\n\nfunction getFirstLink() {\n  return canvasStore.getCanvas().linkConnector.renderLinks.at(0)\n}\n\n/**\n * Node search offers nodes whose socket for the dragged type only exists under\n * an unselected DynamicCombo option. Both link-release paths -- the search box\n * and the context menu -- must ask for that option before connecting, or the\n * link is dropped with only a console warning.\n */\nfunction revealSlotForDroppedLink(node: LGraphNode) {\n  const link = getFirstLink()\n  const droppedType = link?.fromSlot.type?.toString()\n  if (link?.toType === 'input' && droppedType) {\n    revealDynamicInputSlot(node, droppedType)\n  }\n}\n\nconst nodeDefStore = useNodeDefStore()\nfunction showNewSearchBox(e: CanvasPointerEvent | null) {\n  trackFeatureUsed()\n  const firstLink = getFirstLink()\n  if (firstLink) {\n    const filter =\n      firstLink.toType === 'input'\n        ? nodeDefStore.nodeSearchService.inputTypeFilter\n        : nodeDefStore.nodeSearchService.outputTypeFilter\n\n    const dataType = firstLink.fromSlot.type?.toString() ?? ''\n    addFilter({\n      filterDef: filter,\n      value: dataType\n    })\n  }\n\n  visible.value = true\n  triggerEvent = e\n\n  // Prevent the dialog from being dismissed immediately\n  dismissable.value = false\n  setTimeout(() => {\n    dismissable.value = true\n  }, 300)\n}\n\nfunction showContextMenu(e: CanvasPointerEvent) {\n  const firstLink = getFirstLink()\n  if (!firstLink) return\n\n  const { node, fromSlot, toType } = firstLink\n  const commonOptions = {\n    e,\n    allow_searchbox: true,\n    showSearchBox: () => {\n      cancelResetOnContextClose()\n      showSearchBox(e)\n    }\n  }\n  const afterRerouteId = firstLink.fromReroute?.id\n  const connectionOptions =\n    toType === 'input'\n      ? { nodeFrom: node, slotFrom: fromSlot, afterRerouteId }\n      : { nodeTo: node, slotTo: fromSlot, afterRerouteId }\n\n  const canvas = canvasStore.getCanvas()\n  const menu = canvas.showConnectionMenu({\n    ...connectionOptions,\n    ...commonOptions\n  })\n\n  if (!menu) {\n    console.warn('No menu was returned from showConnectionMenu')\n    return\n  }\n\n  triggerEvent = e\n  listenerController = new AbortController()\n  const { signal } = listenerController\n  const options = { once: true, signal }\n\n  // Connect the node after it is created via context menu\n  useEventListener(\n    canvas.canvas,\n    'connect-new-default-node',\n    (createEvent) => {\n      if (!(createEvent instanceof CustomEvent)) {\n        console.error('Invalid event')\n        return\n      }\n\n      const node: unknown = createEvent.detail?.node\n      if (!(node instanceof LGraphNode)) {\n        console.error('Invalid node')\n        return\n      }\n\n      disconnectOnReset = false\n      createEvent.preventDefault()\n      revealSlotForDroppedLink(node)\n      canvas.linkConnector.connectToNode(node, e)\n    },\n    options\n  )\n\n  // Reset when the context menu is closed\n  const cancelResetOnContextClose = useEventListener(\n    menu.controller.signal,\n    'abort',\n    reset,\n    options\n  )\n}\n\n// Disable litegraph's default behavior of release link and search box.\nwatchEffect(() => {\n  const { canvas } = canvasStore\n  if (!canvas) return\n\n  LiteGraph.release_link_on_empty_shows_menu = false\n  canvas.allow_searchbox = false\n\n  useEventListener(\n    canvas.linkConnector.events,\n    'dropped-on-canvas',\n    handleDroppedOnCanvas\n  )\n})\n\nfunction canvasEventHandler(e: LiteGraphCanvasEvent) {\n  if (e.detail.subType === 'empty-double-click') {\n    showSearchBox(e.detail.originalEvent)\n  } else if (e.detail.subType === 'group-double-click') {\n    const group = e.detail.group\n    const [_, y] = group.pos\n    const relativeY = e.detail.originalEvent.canvasY - y\n    // Show search box if the click is NOT on the title bar\n    if (relativeY > group.titleHeight) {\n      showSearchBox(e.detail.originalEvent)\n    }\n  }\n}\n\nconst linkReleaseAction = computed(() =>\n  settingStore.get('Comfy.LinkRelease.Action')\n)\n\nconst linkReleaseActionShift = computed(() =>\n  settingStore.get('Comfy.LinkRelease.ActionShift')\n)\n\n// Prevent normal LinkConnector reset (called by CanvasPointer.finally)\nfunction preventDefault(e: Event) {\n  return e.preventDefault()\n}\nfunction cancelNextReset(e: CustomEvent<CanvasPointerEvent>) {\n  e.preventDefault()\n\n  const canvas = canvasStore.getCanvas()\n  canvas.linkConnector.state.snapLinksPos = [e.detail.canvasX, e.detail.canvasY]\n  useEventListener(canvas.linkConnector.events, 'reset', preventDefault, {\n    once: true\n  })\n}\n\nfunction handleDroppedOnCanvas(e: CustomEvent<CanvasPointerEvent>) {\n  disconnectOnReset = true\n  const action = e.detail.shiftKey\n    ? linkReleaseActionShift.value\n    : linkReleaseAction.value\n  switch (action) {\n    case LinkReleaseTriggerAction.SEARCH_BOX:\n      cancelNextReset(e)\n      showSearchBox(e.detail)\n      break\n    case LinkReleaseTriggerAction.CONTEXT_MENU:\n      cancelNextReset(e)\n      showContextMenu(e.detail)\n      break\n    case LinkReleaseTriggerAction.NO_ACTION:\n    default:\n      break\n  }\n}\n\n// Resets litegraph state\nfunction reset() {\n  listenerController?.abort()\n  listenerController = null\n  triggerEvent = null\n\n  const canvas = canvasStore.getCanvas()\n  canvas.linkConnector.events.removeEventListener('reset', preventDefault)\n  if (disconnectOnReset) canvas.linkConnector.disconnectLinks()\n\n  canvas.linkConnector.reset()\n  canvas.setDirty(true, true)\n}\n\n// Reset connecting links when the search box is closed\nwatch(visible, () => {\n  if (visible.value) return\n  clearFilters()\n  reset()\n})\n\nuseEventListener(document, 'litegraph:canvas', canvasEventHandler)\ndefineExpose({ showSearchBox })\n</script>\n","import { defineStore } from 'pinia'\nimport { ref } from 'vue'\n\nexport const useHelpCenterStore = defineStore('helpCenter', () => {\n  const isVisible = ref(false)\n\n  const toggle = () => {\n    isVisible.value = !isVisible.value\n  }\n\n  const show = () => {\n    isVisible.value = true\n  }\n\n  const hide = () => {\n    isVisible.value = false\n  }\n\n  return {\n    isVisible,\n    toggle,\n    show,\n    hide\n  }\n})\n","import { storeToRefs } from 'pinia'\nimport { computed, onMounted } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useReleaseStore } from '@/platform/updates/common/releaseStore'\nimport { useHelpCenterStore } from '@/stores/helpCenterStore'\nimport { useConflictAcknowledgment } from '@/workbench/extensions/manager/composables/useConflictAcknowledgment'\nimport { useConflictDetection } from '@/workbench/extensions/manager/composables/useConflictDetection'\nimport { useNodeConflictDialog } from '@/workbench/extensions/manager/composables/useNodeConflictDialog'\n\nexport function useHelpCenter() {\n  const settingStore = useSettingStore()\n  const releaseStore = useReleaseStore()\n  const helpCenterStore = useHelpCenterStore()\n  const { isVisible: isHelpCenterVisible } = storeToRefs(helpCenterStore)\n  const { shouldShowRedDot: showReleaseRedDot } = storeToRefs(releaseStore)\n\n  const conflictDetection = useConflictDetection()\n  const { show: showNodeConflictDialog } = useNodeConflictDialog()\n\n  // Use conflict acknowledgment state from composable - call only once\n  const { shouldShowRedDot: shouldShowConflictRedDot, markConflictsAsSeen } =\n    useConflictAcknowledgment()\n\n  // Use either release red dot or conflict red dot\n  const shouldShowRedDot = computed((): boolean => {\n    const releaseRedDot = showReleaseRedDot.value\n    return releaseRedDot || shouldShowConflictRedDot.value\n  })\n\n  const sidebarLocation = computed(() =>\n    settingStore.get('Comfy.Sidebar.Location')\n  )\n\n  /**\n   * Toggle Help Center and track UI button click.\n   */\n  const toggleHelpCenter = () => {\n    useTelemetry()?.trackUiButtonClicked({\n      button_id: 'sidebar_help_center_toggled',\n      element_group: 'sidebar'\n    })\n    helpCenterStore.toggle()\n  }\n\n  const closeHelpCenter = () => {\n    helpCenterStore.hide()\n  }\n\n  /**\n   * Handle What's New popup dismissal\n   * Check if conflict modal should be shown after ComfyUI update\n   */\n  const handleWhatsNewDismissed = async () => {\n    try {\n      // Check if conflict modal should be shown after update\n      const shouldShow =\n        await conflictDetection.shouldShowConflictModalAfterUpdate()\n      if (shouldShow) {\n        showConflictModal()\n      }\n    } catch (error) {\n      console.error('[HelpCenter] Error checking conflict modal:', error)\n    }\n  }\n\n  /**\n   * Show the node conflict dialog with current conflict data\n   */\n  const showConflictModal = () => {\n    showNodeConflictDialog({\n      showAfterWhatsNew: true,\n      dialogComponentProps: {\n        onClose: () => {\n          markConflictsAsSeen()\n        }\n      }\n    })\n  }\n\n  // Initialize release store on mount\n  onMounted(async () => {\n    // Initialize release store to fetch releases for toast and popup\n    await releaseStore.initialize()\n  })\n\n  return {\n    isHelpCenterVisible,\n    shouldShowRedDot,\n    sidebarLocation,\n    toggleHelpCenter,\n    closeHelpCenter,\n    handleWhatsNewDismissed\n  }\n}\n","<template>\n  <div v-if=\"shouldShow\" class=\"release-toast-popup\">\n    <NotificationPopup\n      icon=\"icon-[lucide--rocket]\"\n      :title=\"$t('releaseToast.newVersionAvailable')\"\n      :subtitle=\"latestRelease?.version\"\n      :position\n    >\n      <SanitizedHtml\n        class=\"pl-14 text-sm leading-[1.21] font-normal text-muted-foreground\"\n        :html=\"formattedContent\"\n      />\n\n      <template #footer-start>\n        <a\n          class=\"flex items-center gap-2 py-1 text-sm font-normal text-muted-foreground hover:text-base-foreground\"\n          :href=\"changelogUrl\"\n          target=\"_blank\"\n          rel=\"noopener noreferrer\"\n          @click=\"handleLearnMore\"\n        >\n          <i class=\"icon-[lucide--external-link] size-4\"></i>\n          {{ $t('releaseToast.whatsNew') }}\n        </a>\n      </template>\n\n      <template #footer-end>\n        <Button\n          variant=\"link\"\n          size=\"unset\"\n          class=\"h-6 px-0 text-sm font-normal\"\n          @click=\"handleSkip\"\n        >\n          {{ $t('releaseToast.skip') }}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          size=\"lg\"\n          class=\"font-normal\"\n          @click=\"handleUpdate\"\n        >\n          {{ $t('releaseToast.update') }}\n        </Button>\n      </template>\n    </NotificationPopup>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { default as DOMPurify } from 'dompurify'\nimport { computed, onMounted, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport NotificationPopup from '@/components/common/NotificationPopup.vue'\nimport SanitizedHtml from '@/components/common/SanitizedHtml.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { isDesktop } from '@/platform/distribution/types'\nimport { formatVersionAnchor } from '@/utils/formatUtil'\nimport { renderMarkdownToHtml } from '@/utils/markdownRendererUtil'\n\nimport type { ReleaseNote } from '../common/releaseService'\nimport { useReleaseStore } from '../common/releaseStore'\n\nconst { position = 'bottom-left', isVisible = true } = defineProps<{\n  position?: 'bottom-left' | 'bottom-right'\n  isVisible?: boolean\n}>()\n\nconst { buildDocsUrl } = useExternalLink()\nconst { toastErrorHandler } = useErrorHandling()\nconst releaseStore = useReleaseStore()\nconst { t } = useI18n()\n\n// Local state for dismissed status\nconst isDismissed = ref(false)\n\n// Get latest release from store\nconst latestRelease = computed<ReleaseNote | null>(() => {\n  return releaseStore.recentRelease\n})\n\n// Show toast when new version available and not dismissed\nconst shouldShow = computed(\n  () => releaseStore.shouldShowToast && !isDismissed.value && isVisible\n)\n\n// Generate changelog URL with version anchor (language-aware)\nconst changelogUrl = computed(() => {\n  const changelogBaseUrl = buildDocsUrl('/changelog', { includeLocale: true })\n  if (latestRelease.value?.version) {\n    const versionAnchor = formatVersionAnchor(latestRelease.value.version)\n    return `${changelogBaseUrl}#${versionAnchor}`\n  }\n  return changelogBaseUrl\n})\n\nconst formattedContent = computed(() => {\n  if (!latestRelease.value?.content) {\n    return DOMPurify.sanitize(`<p>${t('releaseToast.description')}</p>`)\n  }\n\n  try {\n    const markdown = latestRelease.value.content\n    // Remove the h1 title line and images for toast mode\n    const contentWithoutTitle = markdown.replace(/^# .+$/m, '')\n    const contentWithoutImages = contentWithoutTitle.replace(\n      /!\\[.*?\\]\\(.*?\\)/g,\n      ''\n    )\n\n    // Check if there's meaningful content left after cleanup\n    const trimmedContent = contentWithoutImages.trim()\n    if (!trimmedContent || trimmedContent.replace(/\\s+/g, '') === '') {\n      return DOMPurify.sanitize(`<p>${t('releaseToast.description')}</p>`)\n    }\n\n    // renderMarkdownToHtml already sanitizes with DOMPurify, so this is safe\n    return renderMarkdownToHtml(contentWithoutImages)\n  } catch (error) {\n    console.error('Error parsing markdown:', error)\n    // Fallback to plain text with line breaks - sanitize the HTML we create\n    const fallbackContent = latestRelease.value.content.replace(/\\n/g, '<br>')\n    return fallbackContent.trim()\n      ? DOMPurify.sanitize(fallbackContent)\n      : DOMPurify.sanitize(`<p>${t('releaseToast.description')}</p>`)\n  }\n})\n\n// Auto-hide timer\nlet hideTimer: ReturnType<typeof setTimeout> | null = null\n\nconst startAutoHide = () => {\n  if (hideTimer) clearTimeout(hideTimer)\n  hideTimer = setTimeout(() => {\n    dismissToast()\n  }, 8000) // 8 second auto-hide\n}\n\nconst clearAutoHide = () => {\n  if (hideTimer) {\n    clearTimeout(hideTimer)\n    hideTimer = null\n  }\n}\n\nconst dismissToast = () => {\n  isDismissed.value = true\n  clearAutoHide()\n}\n\nconst handleSkip = () => {\n  if (latestRelease.value) {\n    void releaseStore.handleSkipRelease(latestRelease.value.version)\n  }\n  dismissToast()\n}\n\nconst handleLearnMore = () => {\n  if (latestRelease.value) {\n    void releaseStore.handleShowChangelog(latestRelease.value.version)\n  }\n  // Do not dismiss; anchor will navigate in new tab but keep toast? spec maybe wants dismiss? We'll dismiss.\n  dismissToast()\n}\n\nconst handleUpdate = async () => {\n  if (isDesktop) {\n    try {\n      await useCommandStore().execute('Comfy-Desktop.CheckForUpdates')\n      dismissToast()\n    } catch (error) {\n      toastErrorHandler(error)\n    }\n    return\n  }\n\n  window.open(\n    buildDocsUrl('/installation/update_comfyui', { includeLocale: true }),\n    '_blank'\n  )\n  dismissToast()\n}\n\n// Start auto-hide when toast becomes visible\nwatch(shouldShow, (isVisible) => {\n  if (isVisible) {\n    startAutoHide()\n  } else {\n    clearAutoHide()\n  }\n})\n\n// Initialize on mount\nonMounted(async () => {\n  // Fetch releases if not already loaded\n  if (!releaseStore.releases.length) {\n    await releaseStore.fetchReleases()\n  }\n})\n\n// Expose methods for testing\ndefineExpose({\n  handleSkip,\n  handleLearnMore,\n  handleUpdate\n})\n</script>\n","<template>\n  <div v-if=\"shouldShow\" class=\"whats-new-popup-container left-4\">\n    <div class=\"whats-new-popup\" @click.stop>\n      <!-- Close Button -->\n      <Button\n        class=\"close-button absolute top-2 right-2 z-10 size-8 rounded-lg p-2 opacity-50\"\n        :aria-label=\"$t('g.close')\"\n        size=\"icon-sm\"\n        variant=\"muted-textonly\"\n        @click=\"closePopup\"\n      >\n        <i class=\"icon-[lucide--x]\" />\n      </Button>\n\n      <!-- Modal Body -->\n      <div class=\"modal-body flex flex-1 flex-col gap-4 px-0 pt-0 pb-2\">\n        <!-- Release Content -->\n        <SanitizedHtml\n          class=\"content-text max-h-96 overflow-y-auto\"\n          :html=\"formattedContent\"\n        />\n      </div>\n\n      <!-- Modal Footer -->\n      <div\n        class=\"modal-footer flex items-center justify-between gap-4 px-4 pb-4\"\n      >\n        <a\n          class=\"learn-more-link flex items-center gap-2 py-1 text-sm font-normal\"\n          :href=\"changelogUrl\"\n          target=\"_blank\"\n          rel=\"noopener noreferrer\"\n          @click=\"closePopup\"\n        >\n          <i class=\"icon-[lucide--external-link]\"></i>\n          {{ $t('whatsNewPopup.learnMore') }}\n        </a>\n        <div class=\"footer-actions flex items-center gap-4\">\n          <Button\n            class=\"h-8\"\n            size=\"sm\"\n            variant=\"muted-textonly\"\n            @click=\"closePopup\"\n          >\n            {{ $t('whatsNewPopup.later') }}\n          </Button>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { default as DOMPurify } from 'dompurify'\nimport { computed, onMounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport SanitizedHtml from '@/components/common/SanitizedHtml.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { formatVersionAnchor } from '@/utils/formatUtil'\nimport { renderMarkdownToHtml } from '@/utils/markdownRendererUtil'\n\nimport type { ReleaseNote } from '../common/releaseService'\nimport { useReleaseStore } from '../common/releaseStore'\n\nconst { buildDocsUrl } = useExternalLink()\nconst releaseStore = useReleaseStore()\nconst { t } = useI18n()\n\n// Define emits\nconst emit = defineEmits<{\n  'whats-new-dismissed': []\n}>()\n\n// Local state for dismissed status\nconst isDismissed = ref(false)\n\n// Get latest release from store\nconst latestRelease = computed<ReleaseNote | null>(() => {\n  return releaseStore.recentRelease\n})\n\n// Show popup when on latest version and not dismissed\nconst shouldShow = computed(\n  () => releaseStore.shouldShowPopup && !isDismissed.value\n)\n\n// Generate changelog URL with version anchor (language-aware)\nconst changelogUrl = computed(() => {\n  const changelogBaseUrl = buildDocsUrl('/changelog', { includeLocale: true })\n  if (latestRelease.value?.version) {\n    const versionAnchor = formatVersionAnchor(latestRelease.value.version)\n    return `${changelogBaseUrl}#${versionAnchor}`\n  }\n  return changelogBaseUrl\n})\n\nconst formattedContent = computed(() => {\n  if (!latestRelease.value?.content) {\n    return DOMPurify.sanitize(`<p>${t('whatsNewPopup.noReleaseNotes')}</p>`)\n  }\n\n  try {\n    const markdown = latestRelease.value.content\n\n    // Check if content is meaningful (not just whitespace)\n    const trimmedContent = markdown.trim()\n    if (!trimmedContent || trimmedContent.replace(/\\s+/g, '') === '') {\n      return DOMPurify.sanitize(`<p>${t('whatsNewPopup.noReleaseNotes')}</p>`)\n    }\n\n    // Extract image and remaining content separately\n    const imageMatch = markdown.match(/!\\[.*?\\]\\(.*?\\)/)\n    const image = imageMatch ? imageMatch[0] : ''\n\n    // Remove image from content but keep original title\n    const contentWithoutImage = markdown.replace(/!\\[.*?\\]\\(.*?\\)/, '').trim()\n\n    // Reorder: image first, then original content\n    const reorderedContent = [image, contentWithoutImage]\n      .filter(Boolean)\n      .join('\\n\\n')\n\n    // renderMarkdownToHtml already sanitizes with DOMPurify, so this is safe\n    return renderMarkdownToHtml(reorderedContent)\n  } catch (error) {\n    console.error('Error parsing markdown:', error)\n    // Fallback to plain text with line breaks - sanitize the HTML we create\n    const fallbackContent = latestRelease.value.content.replace(/\\n/g, '<br>')\n    return fallbackContent.trim()\n      ? DOMPurify.sanitize(fallbackContent)\n      : DOMPurify.sanitize(`<p>${t('whatsNewPopup.noReleaseNotes')}</p>`)\n  }\n})\n\nconst show = () => {\n  isDismissed.value = false\n}\n\nconst hide = () => {\n  isDismissed.value = true\n  emit('whats-new-dismissed')\n}\n\nconst closePopup = async () => {\n  // Mark \"what's new\" seen when popup is closed\n  if (latestRelease.value) {\n    await releaseStore.handleWhatsNewSeen(latestRelease.value.version)\n  }\n  hide()\n}\n\n// Initialize on mount\nonMounted(async () => {\n  // Fetch releases if not already loaded\n  if (!releaseStore.releases.length) {\n    await releaseStore.fetchReleases()\n  }\n})\n\n// Expose methods for parent component and tests\ndefineExpose({\n  show,\n  hide,\n  closePopup\n})\n</script>\n\n<style scoped>\n/* Popup container - positioning handled by parent */\n.whats-new-popup-container {\n  --whats-new-popup-bottom: 1rem;\n\n  position: absolute;\n  bottom: var(--whats-new-popup-bottom);\n  z-index: 1000;\n  pointer-events: auto;\n}\n\n.whats-new-popup {\n  background: var(--interface-menu-surface);\n  border-radius: 8px;\n  max-width: 400px;\n  width: 400px;\n  border: 1px solid var(--interface-menu-stroke);\n  box-shadow: 1px 1px 8px 0 rgb(0 0 0 / 0.2);\n  position: relative;\n  display: flex;\n  flex-direction: column;\n}\n\n/* Modal Body */\n.modal-body {\n  display: flex;\n  flex-direction: column;\n  gap: 1rem;\n  padding: 0;\n  flex: 1;\n}\n\n.modal-header {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n}\n\n.content-text {\n  color: var(--text-primary);\n  font-size: 14px;\n  line-height: 1.5;\n  word-wrap: break-word;\n  padding: 0 1rem;\n}\n\n/* Style the markdown content */\n/* Title */\n.content-text :deep(*) {\n  box-sizing: border-box;\n}\n\n.content-text :deep(h1) {\n  color: var(--text-secondary);\n  font-family: Inter, sans-serif;\n  font-size: 14px;\n  font-weight: 400;\n  margin-top: 1rem;\n  margin-bottom: 8px;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n}\n\n/* What's new title - targets h2 or strong text after h1 */\n.content-text :deep(h2),\n/* stylelint-disable-next-line selector-max-type -- generated markdown offers no class hooks */\n.content-text :deep(h1 + p strong) {\n  color: var(--text-primary);\n  font-family: Inter, sans-serif;\n  font-size: 14px;\n  font-weight: 600;\n  margin: 0 0 8px;\n  line-height: 1.429;\n}\n\n/* Regular paragraphs - short description */\n.content-text :deep(p) {\n  color: var(--text-secondary);\n  font-family: Inter, sans-serif;\n  margin: 1rem 0;\n}\n\n/* List */\n.content-text :deep(ul),\n.content-text :deep(ol) {\n  margin-bottom: 0;\n  padding-left: 0;\n  list-style: none;\n}\n\n.content-text :deep(ul:first-child),\n.content-text :deep(ol:first-child) {\n  margin-top: 0;\n}\n\n.content-text :deep(ul:last-child),\n.content-text :deep(ol:last-child) {\n  margin-bottom: 0;\n}\n\n.content-text :deep(li) {\n  margin-bottom: 6px;\n  position: relative;\n  padding-left: 18px;\n  color: var(--text-secondary);\n  font-family: Inter, sans-serif;\n  font-size: 14px;\n  font-weight: 400;\n  line-height: 1.2102;\n}\n\n.content-text :deep(li:last-child) {\n  margin-bottom: 0;\n}\n\n.content-text :deep(li::before) {\n  content: '';\n  position: absolute;\n  left: 4px;\n  top: 7px;\n  width: 6px;\n  height: 6px;\n  border: 2px solid var(--text-secondary);\n  border-radius: 50%;\n  background: transparent;\n}\n\n.content-text :deep(li strong) {\n  color: var(--text-secondary);\n  font-family: Inter, sans-serif;\n  font-size: 14px;\n  font-weight: 400;\n  line-height: 1.2102;\n  margin-right: 4px;\n}\n\n.content-text :deep(li p) {\n  margin: 2px 0 0;\n  display: inline;\n}\n\n/* Code styling */\n.content-text :deep(code) {\n  background-color: var(--input-surface);\n  border: 1px solid var(--interface-menu-stroke);\n  border-radius: 4px;\n  padding: 2px 6px;\n  color: var(--text-primary);\n  white-space: nowrap;\n}\n\n.content-text :deep(img) {\n  width: 100%;\n  height: 200px;\n  margin: 0 0 16px;\n  object-fit: cover;\n  display: block;\n  border-radius: 8px;\n}\n\n.content-text :deep(img:first-child) {\n  margin: -1rem -1rem 16px;\n  width: calc(100% + 2rem);\n  border-top-left-radius: 8px;\n  border-top-right-radius: 8px;\n  border-bottom-left-radius: 0;\n  border-bottom-right-radius: 0;\n}\n\n/* Add border to content when image is present */\n.content-text:has(img:first-child) {\n  border-left: 1px solid var(--interface-menu-stroke);\n  border-right: 1px solid var(--interface-menu-stroke);\n  border-top: 1px solid var(--interface-menu-stroke);\n  border-bottom-left-radius: 8px;\n  border-bottom-right-radius: 8px;\n  margin: -1px;\n  margin-bottom: 0;\n}\n\n.content-text :deep(img + h1) {\n  margin-top: 0;\n}\n\n/* Secondary headings */\n.content-text :deep(h3) {\n  color: var(--text-primary);\n  font-family: Inter, sans-serif;\n  font-size: 16px;\n  font-weight: 600;\n  margin: 16px 0 8px;\n  line-height: 1.4;\n}\n\n/* Modal Footer */\n.modal-footer {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 16px;\n  padding: 16px;\n  border-top: none;\n}\n\n.footer-actions {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n.learn-more-link {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  color: var(--text-secondary);\n  font-size: 14px;\n  font-weight: 400;\n  line-height: 1.2102;\n  text-decoration: none;\n  padding: 4px 0;\n}\n\n.learn-more-link:hover {\n  color: var(--text-primary);\n}\n\n.learn-more-link i {\n  width: 16px;\n  height: 16px;\n}\n\n.action-secondary {\n  height: 32px;\n  padding: 4px 0;\n  background: transparent;\n  border: none;\n  color: var(--text-secondary);\n  font-size: 14px;\n  font-weight: 400;\n  line-height: 1.2102;\n  cursor: pointer;\n  border-radius: 4px;\n}\n\n.action-secondary:hover {\n  color: var(--text-primary);\n}\n\n.action-primary {\n  height: 40px;\n  padding: 8px 16px;\n  background: var(--interface-menu-component-surface-hovered);\n  border-radius: 8px;\n  border: none;\n  color: var(--text-primary);\n  font-size: 14px;\n  font-weight: 400;\n  line-height: 1.2102;\n  cursor: pointer;\n}\n\n.action-primary:hover {\n  background: var(--button-hover-surface);\n}\n</style>\n","<template>\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    :width=\"size\"\n    :height=\"size\"\n    viewBox=\"0 0 16 16\"\n    fill=\"none\"\n    :class=\"iconClass\"\n  >\n    <g clip-path=\"url(#clip0_1099_16244)\">\n      <path\n        d=\"M4.99992 3.00016C4.99992 2.07969 5.74611 1.3335 6.66658 1.3335C7.58706 1.3335 8.33325 2.07969 8.33325 3.00016V4.00016H8.99992C9.9318 4.00016 10.3977 4.00016 10.7653 4.1524C11.2553 4.35539 11.6447 4.74474 11.8477 5.2348C11.9999 5.60234 11.9999 6.06828 11.9999 7.00016H12.9999C13.9204 7.00016 14.6666 7.74635 14.6666 8.66683C14.6666 9.5873 13.9204 10.3335 12.9999 10.3335H11.9999V11.4668C11.9999 12.5869 11.9999 13.147 11.7819 13.5748C11.5902 13.9511 11.2842 14.2571 10.9079 14.4488C10.4801 14.6668 9.92002 14.6668 8.79992 14.6668H8.33325V13.5002C8.33325 12.6717 7.66168 12.0002 6.83325 12.0002C6.00482 12.0002 5.33325 12.6717 5.33325 13.5002V14.6668H4.53325C3.41315 14.6668 2.85309 14.6668 2.42527 14.4488C2.04895 14.2571 1.74299 13.9511 1.55124 13.5748C1.33325 13.147 1.33325 12.5869 1.33325 11.4668V10.3335H2.33325C3.25373 10.3335 3.99992 9.5873 3.99992 8.66683C3.99992 7.74635 3.25373 7.00016 2.33325 7.00016H1.33325C1.33325 6.06828 1.33325 5.60234 1.48549 5.2348C1.68848 4.74474 2.07783 4.35539 2.56789 4.1524C2.93543 4.00016 3.40137 4.00016 4.33325 4.00016H4.99992V3.00016Z\"\n        :stroke=\"color\"\n        stroke-width=\"1.2\"\n        stroke-linecap=\"round\"\n        stroke-linejoin=\"round\"\n      />\n    </g>\n    <defs>\n      <clipPath id=\"clip0_1099_16244\">\n        <rect width=\"16\" height=\"16\" fill=\"white\" />\n      </clipPath>\n    </defs>\n  </svg>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\ninterface Props {\n  size?: number | string\n  color?: string\n  class?: string\n}\nconst {\n  size = 16,\n  color = 'currentColor',\n  class: className\n} = defineProps<Props>()\nconst iconClass = computed(() => className || '')\n</script>\n","<template>\n  <div\n    class=\"help-center-menu flex flex-col items-start gap-1\"\n    role=\"menu\"\n    :aria-label=\"$t('help.helpCenterMenu')\"\n  >\n    <!-- Main Menu Items -->\n    <div class=\"w-full\">\n      <nav class=\"flex w-full flex-col gap-2\" role=\"menubar\">\n        <button\n          v-for=\"menuItem in menuItems\"\n          v-show=\"menuItem.visible !== false\"\n          :key=\"menuItem.key\"\n          type=\"button\"\n          class=\"help-menu-item\"\n          :class=\"{ 'more-item': menuItem.key === 'more' }\"\n          :data-testid=\"`help-menu-item-${menuItem.key}`\"\n          role=\"menuitem\"\n          @click=\"menuItem.action\"\n          @mouseenter=\"onMenuItemHover(menuItem.key, $event)\"\n          @mouseleave=\"onMenuItemLeave(menuItem.key)\"\n        >\n          <div class=\"help-menu-icon-container\">\n            <div class=\"help-menu-icon\">\n              <component\n                :is=\"menuItem.icon\"\n                v-if=\"typeof menuItem.icon === 'object'\"\n                :size=\"16\"\n              />\n              <i v-else :class=\"menuItem.icon\" />\n            </div>\n            <div v-if=\"menuItem.showRedDot\" class=\"menu-red-dot\" />\n          </div>\n          <span class=\"menu-label\">{{ menuItem.label }}</span>\n          <i\n            v-if=\"menuItem.showExternalIcon\"\n            class=\"ml-auto icon-[lucide--external-link] size-4 text-primary\"\n          />\n          <i\n            v-if=\"menuItem.key === 'more'\"\n            class=\"pi pi-chevron-right ml-auto\"\n          />\n        </button>\n      </nav>\n      <div\n        class=\"flex h-4 flex-col items-center justify-between self-stretch p-2\"\n      >\n        <div class=\"w-full border-b border-interface-menu-stroke\" />\n      </div>\n    </div>\n\n    <!-- More Submenu -->\n    <Teleport to=\"body\">\n      <div\n        v-if=\"isSubmenuVisible\"\n        ref=\"submenuRef\"\n        class=\"more-submenu\"\n        :style=\"submenuStyle\"\n        @mouseenter=\"onSubmenuHover\"\n        @mouseleave=\"onSubmenuLeave\"\n      >\n        <template\n          v-for=\"submenuItem in moreMenuItem?.items\"\n          :key=\"submenuItem.key\"\n        >\n          <div\n            v-if=\"submenuItem.type === 'divider'\"\n            v-show=\"submenuItem.visible !== false\"\n            class=\"submenu-divider\"\n          />\n          <button\n            v-else\n            v-show=\"submenuItem.visible !== false\"\n            type=\"button\"\n            class=\"help-menu-item submenu-item\"\n            role=\"menuitem\"\n            @click=\"submenuItem.action\"\n          >\n            <span class=\"menu-label\">{{ submenuItem.label }}</span>\n          </button>\n        </template>\n      </div>\n    </Teleport>\n\n    <!-- What's New Section -->\n    <section\n      v-if=\"showVersionUpdates\"\n      class=\"w-full\"\n      data-testid=\"whats-new-section\"\n    >\n      <h3\n        class=\"section-description flex items-center gap-2.5 self-stretch px-8 py-2\"\n      >\n        {{ $t('helpCenter.whatsNew') }}\n      </h3>\n\n      <!-- Release Items -->\n      <div\n        v-if=\"hasReleases\"\n        role=\"group\"\n        :aria-label=\"$t('help.recentReleases')\"\n      >\n        <article\n          v-for=\"release in releaseStore.recentReleases\"\n          :key=\"release.id || release.version\"\n          class=\"release-menu-item flex h-12 min-h-6 cursor-pointer items-center gap-2 self-stretch rounded-sm p-2 transition-colors hover:bg-interface-menu-component-surface-hovered\"\n          :data-testid=\"`help-release-item-${release.version}`\"\n          role=\"button\"\n          tabindex=\"0\"\n          @click=\"onReleaseClick(release)\"\n          @keydown.enter=\"onReleaseClick(release)\"\n          @keydown.space.prevent=\"onReleaseClick(release)\"\n        >\n          <i class=\"help-menu-icon icon-[lucide--package]\" aria-hidden=\"true\" />\n          <div class=\"release-content\">\n            <span class=\"release-title\">\n              {{\n                $t('g.releaseTitle', {\n                  package: 'Comfy',\n                  version: release.version\n                })\n              }}\n            </span>\n            <time class=\"release-date\" :datetime=\"release.published_at\">\n              <span class=\"normal-state\">\n                {{ formatReleaseDate(release.published_at) }}\n              </span>\n              <span class=\"hover-state\">\n                {{ $t('helpCenter.clickToLearnMore') }}\n              </span>\n            </time>\n          </div>\n        </article>\n      </div>\n\n      <!-- Loading State -->\n      <div\n        v-else-if=\"releaseStore.isLoading\"\n        class=\"help-menu-item\"\n        role=\"status\"\n        aria-live=\"polite\"\n      >\n        <i class=\"pi pi-spin pi-spinner help-menu-icon\" aria-hidden=\"true\" />\n        <span>{{ $t('helpCenter.loadingReleases') }}</span>\n      </div>\n\n      <!-- No Releases State -->\n      <div v-else class=\"help-menu-item\" role=\"status\">\n        <i class=\"pi pi-info-circle help-menu-icon\" aria-hidden=\"true\" />\n        <span>{{ $t('helpCenter.noRecentReleases') }}</span>\n      </div>\n    </section>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'\nimport type { CSSProperties, Component } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport PuzzleIcon from '@/components/icons/PuzzleIcon.vue'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { isCloud, isDesktop, isNightly } from '@/platform/distribution/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { buildFeedbackTypeformUrl } from '@/platform/support/config'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type { ReleaseNote } from '@/platform/updates/common/releaseService'\nimport { useReleaseStore } from '@/platform/updates/common/releaseStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { getErrorMessage } from '@/utils/errorUtil'\nimport { electronAPI } from '@/utils/envUtil'\nimport { formatVersionAnchor } from '@/utils/formatUtil'\nimport { useConflictAcknowledgment } from '@/workbench/extensions/manager/composables/useConflictAcknowledgment'\nimport { useManagerState } from '@/workbench/extensions/manager/composables/useManagerState'\nimport { useComfyManagerService } from '@/workbench/extensions/manager/services/comfyManagerService'\nimport { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\n// Types\ninterface MenuItem {\n  key: string\n  icon?: string | Component\n  label?: string\n  action?: () => void\n  visible?: boolean\n  type?: 'item' | 'divider'\n  items?: MenuItem[]\n  showRedDot?: boolean\n  showExternalIcon?: boolean\n}\n\n// Constants\nconst TIME_UNITS = {\n  MINUTE: 60 * 1000,\n  HOUR: 60 * 60 * 1000,\n  DAY: 24 * 60 * 60 * 1000,\n  WEEK: 7 * 24 * 60 * 60 * 1000,\n  MONTH: 30 * 24 * 60 * 60 * 1000,\n  YEAR: 365 * 24 * 60 * 60 * 1000\n} as const\n\nconst SUBMENU_CONFIG = {\n  DELAY_MS: 100,\n  OFFSET_PX: 8,\n  Z_INDEX: 10001\n} as const\n\n// Composables\nconst { t } = useI18n()\nconst toast = useToast()\nconst { staticUrls, buildDocsUrl } = useExternalLink()\nconst releaseStore = useReleaseStore()\nconst commandStore = useCommandStore()\nconst settingStore = useSettingStore()\nconst telemetry = useTelemetry()\n\n// Track when help center was opened\nconst openedAt = ref(Date.now())\n\n// Emits\nconst emit = defineEmits<{\n  close: []\n}>()\n\n// State\nconst isSubmenuVisible = ref(false)\nconst submenuRef = ref<HTMLElement | null>(null)\nconst submenuStyle = ref<CSSProperties>({})\nlet hoverTimeout: number | null = null\n\n// Computed\nconst hasReleases = computed(() => releaseStore.releases.length > 0)\nconst showVersionUpdates = computed(() =>\n  settingStore.get('Comfy.Notification.ShowVersionUpdates')\n)\nconst isDevMode = computed(() => settingStore.get('Comfy.DevMode'))\n\n// Use conflict acknowledgment state from composable\nconst { shouldShowRedDot: shouldShowManagerRedDot } =\n  useConflictAcknowledgment()\nconst { isNewManagerUI } = useManagerState()\n\nconst moreItems = computed<MenuItem[]>(() => {\n  const allMoreItems: MenuItem[] = [\n    {\n      key: 'desktop-guide',\n      type: 'item',\n      label: t('helpCenter.desktopUserGuide'),\n      visible: isDesktop,\n      action: () => {\n        trackResourceClick('docs', true)\n        openExternalLink(\n          buildDocsUrl('/installation/desktop', {\n            includeLocale: true,\n            platform: true\n          })\n        )\n        emit('close')\n      }\n    },\n    {\n      key: 'dev-tools',\n      type: 'item',\n      label: t('helpCenter.openDevTools'),\n      visible: isDesktop,\n      action: () => {\n        openDevTools()\n        emit('close')\n      }\n    },\n    {\n      key: 'divider-1',\n      type: 'divider',\n      visible: isDesktop\n    },\n    {\n      key: 'reinstall',\n      type: 'item',\n      label: t('helpCenter.reinstall'),\n      visible: isDesktop,\n      action: () => {\n        onReinstall()\n        emit('close')\n      }\n    },\n    {\n      key: 'replay-onboarding',\n      type: 'item',\n      label: t('commands.Comfy_Onboarding_Replay.label'),\n      visible: isDevMode.value,\n      action: () => {\n        void commandStore.execute('Comfy.Onboarding.Replay')\n        emit('close')\n      }\n    }\n  ]\n\n  // Filter for visible items only\n  return allMoreItems.filter((item) => item.visible !== false)\n})\n\nconst hasVisibleMoreItems = computed(() => {\n  return !!moreItems.value.length\n})\n\nconst moreMenuItem = computed(() =>\n  menuItems.value.find((item) => item.key === 'more')\n)\n\nconst menuItems = computed<MenuItem[]>(() => {\n  const items: MenuItem[] = [\n    {\n      key: 'feedback',\n      type: 'item',\n      icon: 'icon-[lucide--clipboard-pen]',\n      label: t('helpCenter.feedback'),\n      showExternalIcon: isCloud || isNightly,\n      action: () => {\n        trackResourceClick('help_feedback', isCloud || isNightly)\n        if (isCloud || isNightly) {\n          window.open(\n            buildFeedbackTypeformUrl('help-center'),\n            '_blank',\n            'noopener,noreferrer'\n          )\n        } else {\n          void commandStore.execute('Comfy.ContactSupport')\n        }\n        emit('close')\n      }\n    },\n    {\n      key: 'help',\n      type: 'item',\n      icon: 'icon-[lucide--message-circle-question]',\n      label: t('helpCenter.help'),\n      action: () => {\n        trackResourceClick('help_feedback', false)\n        void commandStore.execute('Comfy.ContactSupport')\n        emit('close')\n      }\n    },\n    {\n      key: 'docs',\n      type: 'item',\n      icon: 'icon-[lucide--book-open]',\n      label: t('helpCenter.docs'),\n      showExternalIcon: true,\n      action: () => {\n        trackResourceClick('docs', true)\n        const path = isCloud ? '/get_started/cloud' : '/'\n        openExternalLink(buildDocsUrl(path, { includeLocale: true }))\n        emit('close')\n      }\n    },\n    {\n      key: 'discord',\n      type: 'item',\n      icon: 'pi pi-discord',\n      label: 'Discord',\n      showExternalIcon: true,\n      action: () => {\n        trackResourceClick('discord', true)\n        openExternalLink(staticUrls.discord)\n        emit('close')\n      }\n    },\n    {\n      key: 'github',\n      type: 'item',\n      icon: 'icon-[lucide--github]',\n      label: t('helpCenter.github'),\n      showExternalIcon: true,\n      action: () => {\n        trackResourceClick('github', true)\n        openExternalLink(staticUrls.github)\n        emit('close')\n      }\n    }\n  ]\n\n  // System status page - only in cloud distributions\n  if (isCloud) {\n    items.push({\n      key: 'status',\n      type: 'item',\n      icon: 'icon-[lucide--activity]',\n      label: t('helpCenter.systemStatus'),\n      showExternalIcon: true,\n      action: () => {\n        trackResourceClick('status', true)\n        openExternalLink(staticUrls.status)\n        emit('close')\n      }\n    })\n  }\n\n  // Extension manager - only in non-cloud distributions\n  if (!isCloud) {\n    items.push({\n      key: 'manager',\n      type: 'item',\n      icon: PuzzleIcon,\n      label: t('helpCenter.managerExtension'),\n      showRedDot: shouldShowManagerRedDot.value,\n      action: async () => {\n        trackResourceClick('manager', false)\n        await useManagerState().openManager({\n          initialTab: ManagerTab.All,\n          showToastOnLegacyError: false\n        })\n        emit('close')\n      }\n    })\n  }\n  // Update ComfyUI - only for non-desktop, non-cloud with new manager UI\n  if (!isDesktop && !isCloud && isNewManagerUI.value) {\n    items.push({\n      key: 'update-comfyui',\n      type: 'item',\n      icon: 'icon-[lucide--download]',\n      label: t('helpCenter.updateComfyUI'),\n      action: () => {\n        onUpdateComfyUI()\n        emit('close')\n      }\n    })\n  }\n\n  items.push({\n    key: 'more',\n    type: 'item',\n    icon: '',\n    label: t('helpCenter.more'),\n    visible: hasVisibleMoreItems.value,\n    action: () => {}, // No action for more item\n    items: moreItems.value\n  })\n\n  return items\n})\n\n// Utility Functions\nconst trackResourceClick = (\n  resourceType:\n    | 'docs'\n    | 'discord'\n    | 'github'\n    | 'help_feedback'\n    | 'manager'\n    | 'release_notes'\n    | 'status',\n  isExternal: boolean\n): void => {\n  telemetry?.trackHelpResourceClicked({\n    resource_type: resourceType,\n    is_external: isExternal,\n    source: 'help_center'\n  })\n}\n\nconst openExternalLink = (url: string): void => {\n  window.open(url, '_blank', 'noopener,noreferrer')\n}\n\nconst clearHoverTimeout = (): void => {\n  if (hoverTimeout) {\n    clearTimeout(hoverTimeout)\n    hoverTimeout = null\n  }\n}\n\nconst calculateSubmenuPosition = (button: HTMLElement): CSSProperties => {\n  const rect = button.getBoundingClientRect()\n  const submenuWidth = 210 // Width defined in CSS\n\n  // Get actual submenu height if available, otherwise estimate based on visible item count\n  const visibleItemCount =\n    moreMenuItem.value?.items?.filter((item) => item.visible !== false)\n      .length || 0\n  const estimatedHeight = visibleItemCount * 48 + 16 // ~48px per item + padding\n  const submenuHeight = submenuRef.value?.offsetHeight || estimatedHeight\n\n  // Get viewport dimensions\n  const viewportWidth = window.innerWidth\n  const viewportHeight = window.innerHeight\n\n  // Calculate basic position (aligned with button)\n  let top = rect.top\n  let left = rect.right + SUBMENU_CONFIG.OFFSET_PX\n\n  // Check if submenu would overflow viewport on the right\n  if (left + submenuWidth > viewportWidth) {\n    // Position submenu to the left of the button instead\n    left = rect.left - submenuWidth - SUBMENU_CONFIG.OFFSET_PX\n  }\n\n  // Check if submenu would overflow viewport at the bottom\n  if (top + submenuHeight > viewportHeight) {\n    // Position submenu above the button, aligned to bottom\n    top = Math.max(\n      SUBMENU_CONFIG.OFFSET_PX, // Minimum distance from top of viewport\n      rect.bottom - submenuHeight\n    )\n  }\n\n  // Ensure submenu doesn't go above viewport\n  if (top < SUBMENU_CONFIG.OFFSET_PX) {\n    top = SUBMENU_CONFIG.OFFSET_PX\n  }\n\n  top -= 8\n\n  return {\n    position: 'fixed',\n    top: `${top}px`,\n    left: `${left}px`,\n    zIndex: SUBMENU_CONFIG.Z_INDEX\n  }\n}\n\nconst formatReleaseDate = (dateString?: string): string => {\n  if (!dateString) return 'date'\n\n  const date = new Date(dateString)\n  const now = new Date()\n  const diffTime = Math.abs(now.getTime() - date.getTime())\n\n  const timeUnits = [\n    { unit: TIME_UNITS.YEAR, key: 'yearsAgo' },\n    { unit: TIME_UNITS.MONTH, key: 'monthsAgo' },\n    { unit: TIME_UNITS.WEEK, key: 'weeksAgo' },\n    { unit: TIME_UNITS.DAY, key: 'daysAgo' },\n    { unit: TIME_UNITS.HOUR, key: 'hoursAgo' },\n    { unit: TIME_UNITS.MINUTE, key: 'minutesAgo' }\n  ]\n\n  for (const { unit, key } of timeUnits) {\n    const value = Math.floor(diffTime / unit)\n    if (value > 0) {\n      return t(`g.relativeTime.${key}`, { count: value })\n    }\n  }\n\n  return t('g.relativeTime.now')\n}\n\n// Event Handlers\nconst onMenuItemHover = async (\n  key: string,\n  event: MouseEvent\n): Promise<void> => {\n  if (key !== 'more' || !moreMenuItem.value?.items) return\n\n  // Don't show submenu if all items are hidden\n  const hasVisibleItems = moreMenuItem.value.items.some(\n    (item) => item.visible !== false\n  )\n  if (!hasVisibleItems) return\n\n  clearHoverTimeout()\n\n  const moreButton = event.currentTarget as HTMLElement\n\n  // Calculate initial position before showing submenu\n  submenuStyle.value = calculateSubmenuPosition(moreButton)\n\n  // Show submenu with correct position\n  isSubmenuVisible.value = true\n\n  // After submenu is rendered, refine position if needed\n  await nextTick()\n  if (submenuRef.value) {\n    submenuStyle.value = calculateSubmenuPosition(moreButton)\n  }\n}\n\nconst onMenuItemLeave = (key: string): void => {\n  if (key !== 'more') return\n\n  hoverTimeout = window.setTimeout(() => {\n    isSubmenuVisible.value = false\n  }, SUBMENU_CONFIG.DELAY_MS)\n}\n\nconst onSubmenuHover = (): void => {\n  clearHoverTimeout()\n}\n\nconst onSubmenuLeave = (): void => {\n  isSubmenuVisible.value = false\n}\n\nconst openDevTools = (): void => {\n  if (isDesktop) {\n    electronAPI().openDevTools()\n  }\n}\n\nconst onReinstall = (): void => {\n  if (isDesktop) {\n    void electronAPI().reinstall()\n  }\n}\n\nconst onUpdateComfyUI = async (): Promise<void> => {\n  const { updateComfyUI, startQueue, rebootComfyUI, error } =\n    useComfyManagerService()\n\n  toast.info(t('helpCenter.updateComfyUIStarted'), {\n    description: t('helpCenter.updateComfyUIStartedDetail'),\n    duration: 3000\n  })\n\n  try {\n    const result = await updateComfyUI({ is_stable: true })\n    if (result !== null) await startQueue()\n\n    if (result === null || error.value) {\n      toast.error(t('g.error'), {\n        description: error.value || t('helpCenter.updateComfyUIFailed')\n      })\n      return\n    }\n\n    toast.success(t('helpCenter.updateComfyUISuccess'), {\n      description: t('helpCenter.updateComfyUISuccessDetail'),\n      duration: 3000\n    })\n\n    await rebootComfyUI()\n  } catch (err) {\n    toast.error(t('g.error'), {\n      description: getErrorMessage(err) ?? t('g.unknownError')\n    })\n  }\n}\n\nconst onReleaseClick = (release: ReleaseNote): void => {\n  trackResourceClick('release_notes', true)\n  void releaseStore.handleShowChangelog(release.version)\n  const versionAnchor = formatVersionAnchor(release.version)\n  const changelogUrl = `${buildDocsUrl('/changelog', { includeLocale: true })}#${versionAnchor}`\n  openExternalLink(changelogUrl)\n  emit('close')\n}\n\n// Lifecycle\nonMounted(async () => {\n  telemetry?.trackHelpCenterOpened({ source: 'sidebar' })\n  if (!hasReleases.value) {\n    await releaseStore.fetchReleases()\n  }\n})\n\nonBeforeUnmount(() => {\n  const timeSpentSeconds = Math.round((Date.now() - openedAt.value) / 1000)\n  telemetry?.trackHelpCenterClosed({ time_spent_seconds: timeSpentSeconds })\n})\n</script>\n\n<style scoped>\n.help-center-menu {\n  width: 256px;\n  max-height: 500px;\n  overflow-y: auto;\n  background: var(--interface-menu-surface);\n  border-radius: 8px;\n  box-shadow: 0 2px 12px 0 rgb(0 0 0 / 0.1);\n  border: 1px solid var(--interface-menu-stroke);\n  padding: 12px 8px;\n  position: relative;\n}\n\n.help-menu-item {\n  display: flex;\n  align-items: center;\n  width: 100%;\n  height: 32px;\n  min-height: 24px;\n  padding: 8px;\n  gap: 8px;\n  background: transparent;\n  border: none;\n  border-radius: 4px;\n  cursor: pointer;\n  transition: background-color 0.2s;\n  font-size: 0.9rem;\n  color: var(--text-primary);\n  text-align: left;\n}\n\n.help-menu-item:hover {\n  background-color: var(--interface-menu-component-surface-hovered);\n}\n\n.help-menu-item:focus,\n.help-menu-item:focus-visible {\n  outline: none;\n  box-shadow: none;\n}\n\n.help-menu-icon-container {\n  position: relative;\n  width: 16px;\n  height: 16px;\n  flex-shrink: 0;\n}\n\n.help-menu-icon {\n  width: 16px;\n  height: 16px;\n  font-size: 16px;\n  color: var(--text-primary);\n  display: flex;\n  justify-content: center;\n  align-items: center;\n  flex-shrink: 0;\n}\n\n.help-menu-icon svg {\n  width: 16px;\n  height: 16px;\n  color: var(--text-primary);\n}\n\n.menu-red-dot {\n  position: absolute;\n  top: -2px;\n  right: -2px;\n  width: 8px;\n  height: 8px;\n  background: #ff3b30;\n  border-radius: 50%;\n  border: 1.5px solid var(--p-content-background);\n  z-index: 1;\n}\n\n.menu-label {\n  flex: 1;\n}\n\n.more-item {\n  justify-content: space-between;\n}\n\n.section-description {\n  color: var(--text-secondary);\n  font-family: var(--font-inter);\n  font-size: 12px;\n  font-style: normal;\n  font-weight: 700;\n  line-height: normal;\n  margin: 0;\n  text-transform: uppercase;\n  letter-spacing: 0.5px;\n}\n\n.release-menu-item {\n  position: relative;\n}\n\n.release-content {\n  flex: 1;\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  min-width: 0;\n}\n\n.release-title {\n  font-size: 0.9rem;\n  line-height: 1.2;\n  font-weight: 500;\n  color: var(--text-primary);\n}\n\n.release-date {\n  height: 16px;\n  color: var(--text-secondary);\n  font-family: var(--font-inter);\n  font-size: 12px;\n  font-style: normal;\n  font-weight: 400;\n  line-height: normal;\n  overflow: hidden;\n  text-overflow: ellipsis;\n  display: -webkit-box;\n  -webkit-line-clamp: 1;\n  -webkit-box-orient: vertical;\n}\n\n.release-date .hover-state {\n  display: none;\n}\n\n.release-menu-item:hover .release-date .normal-state,\n.release-menu-item:focus-within .release-date .normal-state {\n  display: none;\n}\n\n.release-menu-item:hover .release-date .hover-state,\n.release-menu-item:focus-within .release-date .hover-state {\n  display: inline;\n}\n\n/* Submenu Styles */\n.more-submenu {\n  width: 210px;\n  padding: 12px 8px;\n  background: var(--interface-menu-surface);\n  border-radius: 8px;\n  border: 1px solid var(--interface-menu-stroke);\n  box-shadow: 0 2px 12px 0 rgb(0 0 0 / 0.1);\n  overflow: hidden;\n  transition: opacity 0.15s ease-out;\n}\n\n.submenu-item {\n  padding: 8px;\n  height: 32px;\n  min-height: 24px;\n  border-radius: 4px;\n  color: var(--text-primary);\n  font-size: 0.9rem;\n  font-weight: inherit;\n  line-height: inherit;\n}\n\n.submenu-item:hover {\n  background-color: var(--interface-menu-component-surface-hovered);\n}\n\n.submenu-item:focus,\n.submenu-item:focus-visible {\n  outline: none;\n  box-shadow: none;\n}\n\n.submenu-divider {\n  height: 1px;\n  background: var(--interface-menu-stroke);\n  margin: 4px 0;\n}\n\n/* Scrollbar Styling */\n.help-center-menu::-webkit-scrollbar {\n  width: 6px;\n}\n\n.help-center-menu::-webkit-scrollbar-track {\n  background: transparent;\n}\n\n.help-center-menu::-webkit-scrollbar-thumb {\n  background: var(--interface-menu-stroke);\n  border-radius: 3px;\n}\n\n.help-center-menu::-webkit-scrollbar-thumb:hover {\n  background: var(--text-secondary);\n}\n\n/* Reduced Motion */\n@media (prefers-reduced-motion: reduce) {\n  .help-menu-item {\n    transition: none;\n  }\n}\n</style>\n","<template>\n  <!-- Help Center Popup positioned within canvas area -->\n  <Teleport to=\"body\">\n    <div\n      v-if=\"isHelpCenterVisible\"\n      class=\"help-center-popup\"\n      data-testid=\"help-center-popup\"\n      :class=\"{\n        'sidebar-left': sidebarLocation === 'left',\n        'sidebar-right': sidebarLocation === 'right',\n        'small-sidebar': isSmall\n      }\"\n    >\n      <HelpCenterMenuContent @close=\"closeHelpCenter\" />\n    </div>\n  </Teleport>\n\n  <!-- Release Notification Toast positioned within canvas area -->\n  <Teleport to=\"#graph-canvas-container\">\n    <ReleaseNotificationToast\n      :is-visible=\"!canvasStore.isPickingNodes\"\n      :position=\"sidebarLocation === 'right' ? 'bottom-right' : 'bottom-left'\"\n    />\n  </Teleport>\n\n  <!-- WhatsNew Popup positioned within canvas area -->\n  <Teleport to=\"#graph-canvas-container\">\n    <WhatsNewPopup\n      :class=\"{\n        'sidebar-left': sidebarLocation === 'left',\n        'sidebar-right': sidebarLocation === 'right',\n        'small-sidebar': isSmall\n      }\"\n      @whats-new-dismissed=\"handleWhatsNewDismissed\"\n    />\n  </Teleport>\n\n  <!-- Backdrop to close popup when clicking outside -->\n  <Teleport to=\"body\">\n    <div\n      v-if=\"isHelpCenterVisible\"\n      class=\"help-center-backdrop\"\n      data-testid=\"help-center-backdrop\"\n      @click=\"closeHelpCenter\"\n    />\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nimport { useHelpCenter } from '@/composables/useHelpCenter'\nimport ReleaseNotificationToast from '@/platform/updates/components/ReleaseNotificationToast.vue'\nimport WhatsNewPopup from '@/platform/updates/components/WhatsNewPopup.vue'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\nimport HelpCenterMenuContent from './HelpCenterMenuContent.vue'\n\nconst canvasStore = useCanvasStore()\nconst { isSmall = false } = defineProps<{\n  isSmall?: boolean\n}>()\n\nconst {\n  isHelpCenterVisible,\n  sidebarLocation,\n  closeHelpCenter,\n  handleWhatsNewDismissed\n} = useHelpCenter()\n</script>\n\n<style scoped>\n.help-center-backdrop {\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  bottom: 0;\n  z-index: 9999;\n  background: transparent;\n}\n\n.help-center-popup {\n  position: absolute;\n  bottom: 1rem;\n  z-index: 10000;\n  animation: slideInUp 0.2s ease-out;\n  pointer-events: auto;\n}\n\n.help-center-popup.sidebar-left {\n  left: 1rem;\n}\n\n.help-center-popup.sidebar-left.small-sidebar {\n  left: 1rem;\n}\n\n.help-center-popup.sidebar-right {\n  right: 1rem;\n}\n\n@keyframes slideInUp {\n  from {\n    opacity: 0;\n    transform: translateY(20px);\n  }\n\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n</style>\n","<template>\n  <svg\n    :class=\"iconClass\"\n    :width=\"size\"\n    :height=\"size\"\n    viewBox=\"0 0 18 18\"\n    xmlns=\"http://www.w3.org/2000/svg\"\n  >\n    <path\n      d=\"M14.8193 0.600586C15.1248 0.600586 15.3296 0.70893 15.459 0.881836C15.5914 1.05888 15.6471 1.33774 15.5527 1.66895L14.8037 4.30176C14.7063 4.64386 14.4729 4.97024 14.1641 5.21191C13.8544 5.45415 13.496 5.58984 13.1699 5.58984H13.1689L9.5791 5.59668H7.90625C7.52654 5.59668 7.19496 5.84986 7.09082 6.21289L5.69434 11.0889C5.63007 11.3133 5.66134 11.5534 5.77734 11.7529L5.83203 11.8359C5.99177 12.0491 6.24252 12.1758 6.50977 12.1758H6.51074L8.88281 12.1709H11.4971C11.7643 12.171 11.9541 12.254 12.084 12.3906L12.1357 12.4521C12.2685 12.6295 12.3249 12.9089 12.2305 13.2402L11.4805 15.8721C11.383 16.2144 11.1498 16.5415 10.8408 16.7832C10.5314 17.0252 10.1736 17.161 9.84766 17.1611H9.84668L6.25684 17.168H3.64258C3.33762 17.1679 3.13349 17.0588 3.00391 16.8857C2.87135 16.7087 2.81482 16.43 2.90918 16.0986L3.39551 14.3887C3.46841 14.1327 3.41794 13.8576 3.25879 13.6445V13.6436C3.09901 13.4303 2.84745 13.3037 2.58008 13.3037H1.18066C0.875088 13.3037 0.670398 13.1953 0.541016 13.0225C0.408483 12.8451 0.351891 12.5655 0.446289 12.2344L2.11914 6.38965L2.30371 5.74707V5.74609C2.40139 5.40341 2.63456 5.07671 2.94336 4.83496C3.25302 4.59258 3.61143 4.45705 3.9375 4.45703H5.6123C5.94484 4.45703 6.24083 4.26316 6.37891 3.9707L6.42773 3.83984L6.98145 1.89551C7.07894 1.55317 7.31212 1.22614 7.62109 0.984375C7.93074 0.742127 8.2892 0.606445 8.61523 0.606445H8.61621L12.1982 0.600586H14.8193Z\"\n      v-bind=\"attributes\"\n    />\n  </svg>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\ninterface Props {\n  size?: number | string\n  color?: string\n  class?: string\n  mode?: 'outline' | 'fill'\n}\nconst {\n  size = 16,\n  color = 'currentColor',\n  mode = 'outline',\n  class: className\n} = defineProps<Props>()\nconst iconClass = computed(() => className || '')\nconst attributes = computed(() => ({\n  stroke: mode === 'outline' ? color : undefined,\n  strokeWidth: mode === 'outline' ? 1 : undefined,\n  fill: mode === 'fill' ? color : 'none'\n}))\n</script>\n","<template>\n  <Menu :items=\"translatedItems\" class=\"comfy-command-menu\">\n    <template #trigger=\"{ open }\">\n      <Button\n        variant=\"textonly\"\n        size=\"unset\"\n        :tooltip=\"t('sideToolbar.labels.menu')\"\n        tooltip-side=\"right\"\n        data-testid=\"comfy-menu-button\"\n        type=\"button\"\n        :aria-label=\"t('sideToolbar.labels.menu')\"\n        :class=\"\n          cn(\n            'flex h-(--sidebar-item-height) w-(--sidebar-width) shrink-0 flex-col rounded-none p-2 hover:bg-interface-panel-hover-surface',\n            open &&\n              'bg-interface-panel-selected-surface hover:bg-interface-panel-selected-surface'\n          )\n        \"\n        @click=\"onLogoMenuClick\"\n      >\n        <div class=\"grid place-items-center-safe gap-0.5\">\n          <i\n            class=\"col-span-full row-span-full icon-[lucide--chevron-down] size-3 translate-x-4 text-muted-foreground\"\n          />\n          <ComfyLogo\n            alt=\"ComfyUI Logo\"\n            class=\"comfyui-logo col-span-full row-span-full size-4.5\"\n            mode=\"fill\"\n          />\n        </div>\n      </Button>\n    </template>\n  </Menu>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport ComfyLogo from '@/components/icons/ComfyLogo.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useWorkflowTemplateSelectorDialog } from '@/composables/useWorkflowTemplateSelectorDialog'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { SettingPanelType } from '@/platform/settings/types'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useColorPaletteService } from '@/services/colorPaletteService'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { useMenuItemStore } from '@/stores/menuItemStore'\nimport type { AppMenuItem, CommandMenuItem } from '@/stores/menuItemStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { normalizeI18nKey } from '@/utils/formatUtil'\nimport { useManagerState } from '@/workbench/extensions/manager/composables/useManagerState'\nimport { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\nconst { t } = useI18n()\nconst menuItemStore = useMenuItemStore()\nconst colorPaletteStore = useColorPaletteStore()\nconst colorPaletteService = useColorPaletteService()\nconst settingsDialog = useSettingsDialog()\nconst managerState = useManagerState()\nconst settingStore = useSettingStore()\n\nconst nodes2Enabled = computed(\n  () => settingStore.get('Comfy.VueNodes.Enabled') ?? false\n)\n\nconst telemetry = useTelemetry()\n\nfunction onLogoMenuClick() {\n  telemetry?.trackUiButtonClicked({\n    button_id: 'sidebar_comfy_menu_opened',\n    element_group: 'sidebar'\n  })\n}\n\nconst translateMenuItem = (item: AppMenuItem): AppMenuItem => {\n  const label = typeof item.label === 'function' ? item.label() : item.label\n  const translatedLabel = label\n    ? t(`menuLabels.${normalizeI18nKey(label)}`, label)\n    : undefined\n\n  return item.items\n    ? {\n        ...item,\n        label: translatedLabel,\n        items: item.items.map(translateMenuItem)\n      }\n    : { ...item, label: translatedLabel }\n}\n\nconst showSettings = (defaultPanel?: SettingPanelType) => {\n  settingsDialog.show(defaultPanel)\n}\n\nconst showManageExtensions = async () => {\n  await managerState.openManager({\n    initialTab: ManagerTab.All,\n    showToastOnLegacyError: false\n  })\n}\n\nconst themeMenuItems = computed(() => {\n  return colorPaletteStore.palettes.map<CommandMenuItem>((palette) => ({\n    key: `theme-${palette.id}`,\n    label: palette.name,\n    commandId: `theme-${palette.id}`,\n    checked: () => colorPaletteStore.activePaletteId === palette.id,\n    command: async () => {\n      await colorPaletteService.loadColorPalette(palette.id)\n    }\n  }))\n})\n\nconst extraMenuItems = computed<MenuItem[]>(() => [\n  { separator: true },\n  {\n    key: 'theme',\n    label: t('menu.theme'),\n    items: themeMenuItems.value\n  },\n  {\n    key: 'nodes-2.0-toggle',\n    label: 'Nodes 2.0',\n    checked: nodes2Enabled.value,\n    presentation: 'switch',\n    class: 'select-none',\n    command: () => onNodes2ToggleChange(!nodes2Enabled.value)\n  },\n  { separator: true },\n  {\n    key: 'browse-templates',\n    label: t('menuLabels.Browse Templates'),\n    icon: 'icon-[comfy--template]',\n    command: () => useWorkflowTemplateSelectorDialog().show('menu')\n  },\n  {\n    key: 'settings',\n    label: t('g.settings'),\n    icon: 'icon-[lucide--settings]',\n    command: () => {\n      telemetry?.trackUiButtonClicked({\n        button_id: 'sidebar_settings_menu_opened',\n        element_group: 'sidebar'\n      })\n      showSettings()\n    }\n  },\n  {\n    key: 'manage-extensions',\n    label: t('menu.manageExtensions'),\n    icon: 'icon-[comfy--extensions-blocks]',\n    command: showManageExtensions\n  }\n])\n\nconst menuSeparator: MenuItem = { separator: true }\n\nconst translatedItems = computed<AppMenuItem[]>(() => {\n  const items = menuItemStore.menuItems.map(translateMenuItem)\n  let helpIndex = items.findIndex((item) => item.key === 'Help')\n  let helpItem: MenuItem | undefined\n\n  if (helpIndex !== -1) {\n    items[helpIndex].icon = 'mdi mdi-help-circle-outline'\n    // If help is not the last item (i.e. we have extension commands), separate them\n    const isLastItem = helpIndex !== items.length - 1\n    helpItem = items.splice(\n      helpIndex,\n      1,\n      ...(isLastItem ? [menuSeparator] : [])\n    )[0]\n  }\n  helpIndex = items.length\n\n  items.splice(\n    helpIndex,\n    0,\n    ...extraMenuItems.value,\n    ...(helpItem ? [menuSeparator, helpItem] : [])\n  )\n\n  return items\n})\n\nconst onNodes2ToggleChange = async (value: boolean) => {\n  await settingStore.set('Comfy.VueNodes.Enabled', value)\n  telemetry?.trackUiButtonClicked({\n    button_id: `menu_nodes_2.0_toggle_${value ? 'enabled' : 'disabled'}`,\n    element_group: 'sidebar'\n  })\n}\n</script>\n","<template>\n  <Button\n    :tooltip=\"computedTooltip\"\n    tooltip-side=\"right\"\n    :class=\"\n      cn(\n        'side-bar-button h-(--sidebar-item-height) w-(--sidebar-width) shrink-0 rounded-none p-2 text-xs',\n        selected && 'side-bar-button-selected'\n      )\n    \"\n    variant=\"muted-textonly\"\n    size=\"unset\"\n    :aria-label=\"computedTooltip\"\n    @click=\"emit('click', $event)\"\n  >\n    <div class=\"side-bar-button-content flex flex-col items-center gap-2\">\n      <slot name=\"icon\">\n        <div class=\"sidebar-icon-wrapper relative\">\n          <i\n            v-if=\"typeof icon === 'string'\"\n            :class=\"icon + ' side-bar-button-icon'\"\n          />\n          <component\n            :is=\"icon\"\n            v-else-if=\"typeof icon === 'object'\"\n            class=\"side-bar-button-icon\"\n          />\n          <span\n            v-if=\"shouldShowBadge\"\n            :class=\"\n              cn(\n                'sidebar-icon-badge absolute min-w-[16px] rounded-full bg-primary-background py-0.25 text-2xs leading-[14px] font-medium text-base-foreground',\n                badgeClass || '-top-1 -right-1'\n              )\n            \"\n          >\n            {{ overlayValue }}\n          </span>\n        </div>\n      </slot>\n      <!-- w-max sizes the label to the rail instead of the padding-inset\n           button content box, which is too narrow for one-line labels -->\n      <span\n        v-if=\"label && !isSmall\"\n        class=\"side-bar-button-label line-clamp-2 w-max max-w-[calc(var(--sidebar-width)-var(--sidebar-padding))] text-center text-2xs leading-none wrap-break-word whitespace-normal\"\n        >{{ st(label, label) }}</span\n      >\n    </div>\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport type { Component } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { st } from '@/i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  icon = '',\n  selected = false,\n  tooltip = '',\n  tooltipSuffix = '',\n  iconBadge = '',\n  badgeClass = '',\n  label = '',\n  isSmall = false\n} = defineProps<{\n  icon?: string | Component\n  selected?: boolean\n  tooltip?: string\n  tooltipSuffix?: string\n  iconBadge?: string | (() => string | null)\n  badgeClass?: string\n  label?: string\n  isSmall?: boolean\n}>()\n\nconst emit = defineEmits<{\n  (e: 'click', event: MouseEvent): void\n}>()\nconst overlayValue = computed(() =>\n  typeof iconBadge === 'function' ? (iconBadge() ?? '') : iconBadge\n)\nconst shouldShowBadge = computed(() => !!overlayValue.value)\n/**\n * Falls back to the label when no tooltip is provided, so labels clamped\n * to two lines can always be recovered in full on hover.\n */\nconst computedTooltip = computed(() => {\n  const text = tooltip || label\n  return st(text, text) + tooltipSuffix\n})\n</script>\n\n<style>\n.side-bar-button-icon {\n  font-size: var(--sidebar-icon-size) !important;\n}\n\n.side-bar-button-selected {\n  background-color: var(--interface-panel-selected-surface);\n  color: var(--content-hover-fg);\n}\n.side-bar-button:hover {\n  background-color: var(--interface-panel-hover-surface);\n  color: var(--content-hover-fg);\n}\n</style>\n","<template>\n  <SidebarIcon\n    icon=\"icon-[ph--terminal-bold]\"\n    :label=\"$t('sideToolbar.labels.console')\"\n    :tooltip=\"$t('menu.toggleBottomPanel')\"\n    :selected=\"bottomPanelStore.activePanel == 'terminal'\"\n    @click=\"toggleConsole\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useBottomPanelStore } from '@/stores/workspace/bottomPanelStore'\n\nimport SidebarIcon from './SidebarIcon.vue'\n\nconst bottomPanelStore = useBottomPanelStore()\n\n/**\n * Toggle console bottom panel and track UI button click.\n */\nconst toggleConsole = () => {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'sidebar_bottom_panel_console_toggled',\n    element_group: 'sidebar'\n  })\n  bottomPanelStore.toggleBottomPanel()\n}\n</script>\n","<template>\n  <SidebarIcon\n    icon=\"icon-[lucide--settings]\"\n    :label=\"$t('g.settings')\"\n    :tooltip=\"tooltipText\"\n    @click=\"showSettingsDialog\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useCommandStore } from '@/stores/commandStore'\n\nimport SidebarIcon from './SidebarIcon.vue'\n\nconst { t } = useI18n()\nconst { getCommand, formatKeySequence } = useCommandStore()\nconst command = getCommand('Comfy.ShowSettingsDialog')\n\nconst tooltipText = computed(\n  () => `${t('g.settings')} (${formatKeySequence(command)})`\n)\n\n/**\n * Toggle keyboard shortcuts panel and track UI button click.\n */\nconst showSettingsDialog = () => {\n  command.function()\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'sidebar_settings_button_clicked',\n    element_group: 'sidebar'\n  })\n}\n</script>\n","<template>\n  <SidebarIcon\n    icon=\"icon-[lucide--keyboard]\"\n    :label=\"$t('shortcuts.shortcuts')\"\n    :tooltip=\"tooltipText\"\n    :selected=\"isShortcutsPanelVisible\"\n    @click=\"toggleShortcutsPanel\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useBottomPanelStore } from '@/stores/workspace/bottomPanelStore'\n\nimport SidebarIcon from './SidebarIcon.vue'\n\nconst { t } = useI18n()\nconst bottomPanelStore = useBottomPanelStore()\nconst commandStore = useCommandStore()\nconst command = commandStore.getCommand('Workspace.ToggleBottomPanel.Shortcuts')\nconst { formatKeySequence } = commandStore\n\nconst isShortcutsPanelVisible = computed(\n  () => bottomPanelStore.activePanel === 'shortcuts'\n)\n\nconst tooltipText = computed(\n  () => `${t('shortcuts.keyboardShortcuts')} (${formatKeySequence(command)})`\n)\n\n/**\n * Toggle keyboard shortcuts panel and track UI button click.\n */\nconst toggleShortcutsPanel = () => {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'sidebar_shortcuts_panel_toggled',\n    element_group: 'sidebar'\n  })\n  bottomPanelStore.togglePanel('shortcuts')\n}\n</script>\n","export const APP_MODE_FEEDBACK_TYPEFORM_ID = 'jmmzmlKw'\n\nexport const APP_MODE_FEEDBACK_FORM_URL = `https://form.typeform.com/to/${APP_MODE_FEEDBACK_TYPEFORM_ID}`\n","<template>\n  <Popover\n    v-if=\"linearMode\"\n    :side=\"sidebarOnLeft ? 'right' : 'left'\"\n    :side-offset=\"8\"\n  >\n    <template #button>\n      <SidebarIcon\n        icon=\"pi pi-question-circle\"\n        class=\"comfy-help-center-btn\"\n        data-testid=\"help-center-button\"\n        :label=\"$t('menu.help')\"\n        :tooltip=\"$t('linearMode.giveFeedback')\"\n        :is-small\n      />\n    </template>\n    <div\n      v-if=\"typeformError || !isValidTypeformId\"\n      class=\"p-4 text-sm text-destructive-background\"\n    >\n      {{ $t('linearMode.feedbackLoadError') }}\n    </div>\n    <div\n      v-else\n      ref=\"feedbackRef\"\n      data-testid=\"feedback-embed\"\n      data-tf-auto-resize\n      :data-tf-widget=\"APP_MODE_FEEDBACK_TYPEFORM_ID\"\n    />\n  </Popover>\n  <SidebarIcon\n    v-else\n    icon=\"pi pi-question-circle\"\n    class=\"comfy-help-center-btn\"\n    data-testid=\"help-center-button\"\n    :label=\"$t('menu.help')\"\n    :tooltip=\"$t('sideToolbar.helpCenter')\"\n    :icon-badge=\"shouldShowRedDot ? '•' : ''\"\n    badge-class=\"-top-1 -right-1 min-w-2 w-2 h-2 p-0 rounded-full text-[0px] bg-[#ff3b30]\"\n    :is-small\n    @click=\"toggleHelpCenter()\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport { computed, useTemplateRef } from 'vue'\n\nimport Popover from '@/components/ui/Popover.vue'\nimport { useHelpCenter } from '@/composables/useHelpCenter'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { APP_MODE_FEEDBACK_TYPEFORM_ID } from '@/platform/surveys/appModeFeedback'\nimport { useTypeformEmbed } from '@/platform/surveys/useTypeformEmbed'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\nimport SidebarIcon from './SidebarIcon.vue'\n\ndefineProps<{\n  isSmall: boolean\n}>()\n\nconst { shouldShowRedDot, toggleHelpCenter } = useHelpCenter()\nconst { linearMode } = storeToRefs(useCanvasStore())\n\nconst settingStore = useSettingStore()\nconst sidebarOnLeft = computed(\n  () => settingStore.get('Comfy.Sidebar.Location') === 'left'\n)\n\nconst feedbackRef = useTemplateRef<HTMLDivElement>('feedbackRef')\nconst { typeformError, isValidTypeformId } = useTypeformEmbed(\n  feedbackRef,\n  APP_MODE_FEEDBACK_TYPEFORM_ID\n)\n</script>\n","<template>\n  <SidebarIcon\n    icon=\"pi pi-sign-out\"\n    :tooltip=\"tooltip\"\n    :label=\"$t('sideToolbar.logout')\"\n    @click=\"logout\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useUserStore } from '@/stores/userStore'\n\nimport SidebarIcon from './SidebarIcon.vue'\n\nconst { t } = useI18n()\nconst userStore = useUserStore()\n\nconst tooltip = computed(\n  () => `${t('sideToolbar.logout')} (${userStore.currentUser?.username})`\n)\nconst logout = async () => {\n  await userStore.logout()\n  window.location.reload()\n}\n</script>\n","<template>\n  <div v-coachmark=\"FIRST_RUN_COACH_IDS.templatesButton\" class=\"flex\">\n    <SidebarIcon\n      icon=\"icon-[comfy--template]\"\n      :tooltip=\"$t('sideToolbar.templates')\"\n      :label=\"$t('sideToolbar.labels.templates')\"\n      :is-small=\"isSmall\"\n      class=\"templates-tab-button\"\n      @click=\"openTemplates\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { useWorkflowTemplateSelectorDialog } from '@/composables/useWorkflowTemplateSelectorDialog'\nimport { FIRST_RUN_COACH_IDS } from '@/platform/onboarding/onboardingTours'\nimport { vCoachmark } from '@/platform/onboarding/vCoachmark'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\n\nimport SidebarIcon from './SidebarIcon.vue'\n\nconst settingStore = useSettingStore()\n\nconst isSmall = computed(\n  () => settingStore.get('Comfy.Sidebar.Size') === 'small'\n)\n\n/**\n * Open templates dialog from sidebar and track UI button click.\n */\nconst openTemplates = () => {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'sidebar_templates_dialog_opened',\n    element_group: 'sidebar'\n  })\n  useWorkflowTemplateSelectorDialog().show('sidebar')\n}\n</script>\n","<template>\n  <nav\n    ref=\"sideToolbarRef\"\n    data-testid=\"side-toolbar\"\n    :inert=\"isHidden\"\n    :aria-hidden=\"isHidden\"\n    :class=\"\n      cn(\n        'side-tool-bar-container flex h-full flex-col items-center bg-transparent transition-[max-width,opacity,transform] duration-300 ease-in-out',\n        {\n          'small-sidebar': isSmall,\n          'connected-sidebar pointer-events-auto': isConnected,\n          'floating-sidebar py-(--comfy-canvas-gutter)': !isConnected,\n          'ml-(--comfy-canvas-gutter)':\n            !isConnected && !isHidden && sidebarLocation === 'left',\n          'mr-(--comfy-canvas-gutter)':\n            !isConnected && !isHidden && sidebarLocation === 'right',\n          'overflowing-sidebar': isOverflowing,\n          'overflow-hidden border-r border-interface-stroke/50 shadow-interface':\n            isConnected,\n          'pointer-events-none overflow-hidden opacity-0': isHidden,\n          '-translate-x-8': isHidden && sidebarLocation === 'left',\n          'translate-x-8': isHidden && sidebarLocation === 'right'\n        }\n      )\n    \"\n    :style=\"{ maxWidth: isHidden ? '0px' : 'var(--sidebar-width)' }\"\n  >\n    <div\n      :class=\"\n        isOverflowing\n          ? 'side-tool-bar-container overflow-y-auto'\n          : 'flex h-full flex-col'\n      \"\n    >\n      <div\n        ref=\"topToolbarRef\"\n        data-testid=\"sidebar-top-group\"\n        :class=\"groupClasses\"\n      >\n        <ComfyMenuButton />\n        <SidebarIcon\n          v-for=\"tab in tabs\"\n          :key=\"tab.id\"\n          :icon=\"tab.icon\"\n          :icon-badge=\"tab.iconBadge\"\n          :tooltip=\"tab.tooltip\"\n          :tooltip-suffix=\"getTabTooltipSuffix(tab)\"\n          :label=\"tab.label || tab.title\"\n          :is-small\n          :selected=\"tab.id === selectedTab?.id\"\n          :data-testid=\"`${tab.id}-tab-button`\"\n          @click=\"onTabClick(tab)\"\n        />\n        <SidebarTemplatesButton />\n      </div>\n\n      <div ref=\"bottomToolbarRef\" :class=\"cn('mt-auto', groupClasses)\">\n        <SidebarLogoutIcon v-if=\"userStore.isMultiUserServer\" :is-small />\n        <SidebarHelpCenterIcon :is-small />\n        <SidebarBottomPanelToggleButton\n          v-if=\"!isCloud && !hideWorkspaceToggles\"\n          :is-small\n        />\n        <SidebarShortcutsToggleButton v-if=\"!hideWorkspaceToggles\" :is-small />\n        <SidebarSettingsButton :is-small />\n      </div>\n    </div>\n    <HelpCenterPopups :is-small />\n    <Suspense v-if=\"NightlySurveyController\">\n      <component :is=\"NightlySurveyController\" />\n    </Suspense>\n  </nav>\n</template>\n\n<script setup lang=\"ts\">\nimport { useResizeObserver } from '@vueuse/core'\nimport { debounce } from 'es-toolkit/compat'\nimport {\n  computed,\n  defineAsyncComponent,\n  nextTick,\n  onBeforeUnmount,\n  onMounted,\n  ref,\n  watch\n} from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport HelpCenterPopups from '@/components/helpcenter/HelpCenterPopups.vue'\nimport ComfyMenuButton from '@/components/sidebar/ComfyMenuButton.vue'\nimport SidebarBottomPanelToggleButton from '@/components/sidebar/SidebarBottomPanelToggleButton.vue'\nimport SidebarSettingsButton from '@/components/sidebar/SidebarSettingsButton.vue'\nimport SidebarShortcutsToggleButton from '@/components/sidebar/SidebarShortcutsToggleButton.vue'\nimport { isCloud, isDesktop, isNightly } from '@/platform/distribution/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useKeybindingStore } from '@/platform/keybindings/keybindingStore'\nimport { useUserStore } from '@/stores/userStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport type { SidebarTabExtension } from '@/types/extensionTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport SidebarHelpCenterIcon from './SidebarHelpCenterIcon.vue'\nimport SidebarIcon from './SidebarIcon.vue'\nimport SidebarLogoutIcon from './SidebarLogoutIcon.vue'\nimport SidebarTemplatesButton from './SidebarTemplatesButton.vue'\n\nconst {\n  visibleTabIds,\n  forceConnected = false,\n  hideWorkspaceToggles = false\n} = defineProps<{\n  visibleTabIds?: string[]\n  forceConnected?: boolean\n  hideWorkspaceToggles?: boolean\n}>()\n\nconst NightlySurveyController =\n  isNightly && !isCloud && !isDesktop\n    ? defineAsyncComponent(\n        () => import('@/platform/surveys/NightlySurveyController.vue')\n      )\n    : undefined\n\nconst { t } = useI18n()\nconst workspaceStore = useWorkspaceStore()\nconst settingStore = useSettingStore()\nconst userStore = useUserStore()\nconst commandStore = useCommandStore()\nconst canvasStore = useCanvasStore()\nconst sideToolbarRef = ref<HTMLElement>()\nconst topToolbarRef = ref<HTMLElement>()\nconst bottomToolbarRef = ref<HTMLElement>()\n\nconst isSmall = computed(\n  () => settingStore.get('Comfy.Sidebar.Size') === 'small'\n)\nconst sidebarLocation = computed<'left' | 'right'>(() =>\n  settingStore.get('Comfy.Sidebar.Location')\n)\nconst sidebarStyle = computed(() => settingStore.get('Comfy.Sidebar.Style'))\nconst isConnected = computed(\n  () =>\n    forceConnected ||\n    selectedTab.value ||\n    isOverflowing.value ||\n    sidebarStyle.value === 'connected'\n)\n\nconst tabs = computed(() => {\n  const all = workspaceStore.getSidebarTabs()\n  return visibleTabIds\n    ? all.filter((tab) => visibleTabIds.includes(tab.id))\n    : all\n})\nconst selectedTab = computed(() => workspaceStore.sidebarTab.activeSidebarTab)\nconst isHidden = computed(() => canvasStore.isPickingNodes)\n\n/**\n * Handle sidebar tab icon click.\n * - Emits UI button telemetry for known tabs\n * - Delegates to the corresponding toggle command\n */\nconst onTabClick = async (item: SidebarTabExtension) => {\n  const telemetry = useTelemetry()\n\n  const isNodeLibraryTab = item.id === 'node-library'\n  const isModelLibraryTab = item.id === 'model-library'\n  const isWorkflowsTab = item.id === 'workflows'\n  const isAssetsTab = item.id === 'assets'\n\n  if (isNodeLibraryTab)\n    telemetry?.trackUiButtonClicked({\n      button_id: 'sidebar_tab_node_library_selected',\n      element_group: 'sidebar'\n    })\n  else if (isModelLibraryTab)\n    telemetry?.trackUiButtonClicked({\n      button_id: 'sidebar_tab_model_library_selected',\n      element_group: 'sidebar'\n    })\n  else if (isWorkflowsTab)\n    telemetry?.trackUiButtonClicked({\n      button_id: 'sidebar_tab_workflows_selected',\n      element_group: 'sidebar'\n    })\n  else if (isAssetsTab)\n    telemetry?.trackUiButtonClicked({\n      button_id: 'sidebar_tab_assets_media_selected',\n      element_group: 'sidebar'\n    })\n\n  await commandStore.commands\n    .find((cmd) => cmd.id === `Workspace.ToggleSidebarTab.${item.id}`)\n    ?.function?.()\n}\n\nconst keybindingStore = useKeybindingStore()\nconst getTabTooltipSuffix = (tab: SidebarTabExtension) => {\n  const shortcut = keybindingStore\n    .getKeybindingByCommandId(`Workspace.ToggleSidebarTab.${tab.id}`)\n    ?.combo.toString()\n  return shortcut ? t('g.shortcutSuffix', { shortcut }) : ''\n}\n\nconst isOverflowing = ref(false)\nconst groupClasses = computed(() =>\n  cn(\n    'sidebar-item-group flex shrink-0 flex-col items-center overflow-hidden',\n    isConnected.value\n      ? 'border border-transparent'\n      : 'pointer-events-auto floating-panel p-0'\n  )\n)\n\nconst CANVAS_GUTTER_VAR = '--comfy-canvas-gutter'\n\n/**\n * The canvas gutter in pixels. Custom properties come back from\n * `getComputedStyle` unresolved, so the token is measured through a length\n * property the browser does resolve.\n */\nfunction canvasGutter(): number {\n  const probe = document.createElement('div')\n  probe.style.position = 'absolute'\n  probe.style.visibility = 'hidden'\n  probe.style.marginLeft = `var(${CANVAS_GUTTER_VAR})`\n  document.body.append(probe)\n  const px = parseFloat(getComputedStyle(probe).marginLeft)\n  probe.remove()\n  return Number.isFinite(px) ? px : 0\n}\n\nconst ENTER_OVERFLOW_MARGIN = 20\nconst EXIT_OVERFLOW_MARGIN = 50\n\nconst checkOverflow = debounce(() => {\n  if (!sideToolbarRef.value || !topToolbarRef.value || !bottomToolbarRef.value)\n    return\n\n  const containerHeight = sideToolbarRef.value.clientHeight\n  const topHeight = topToolbarRef.value.scrollHeight\n  const bottomHeight = bottomToolbarRef.value.scrollHeight\n  const contentHeight = topHeight + bottomHeight\n\n  if (isOverflowing.value) {\n    isOverflowing.value = containerHeight < contentHeight + EXIT_OVERFLOW_MARGIN\n  } else {\n    isOverflowing.value =\n      containerHeight < contentHeight + ENTER_OVERFLOW_MARGIN\n  }\n}, 16)\n\nonMounted(() => {\n  if (!sideToolbarRef.value) return\n\n  const overflowObserver = useResizeObserver(\n    sideToolbarRef.value,\n    checkOverflow\n  )\n\n  checkOverflow()\n\n  onBeforeUnmount(() => {\n    overflowObserver.stop()\n  })\n\n  watch(\n    [isSmall, sidebarLocation],\n    async () => {\n      if (canvasStore.canvas) {\n        if (sidebarLocation.value === 'left') {\n          await nextTick()\n          const sidebarRight =\n            sideToolbarRef.value?.getBoundingClientRect()?.right\n          canvasStore.canvas.fpsInfoLocation = [\n            sidebarRight === undefined\n              ? undefined\n              : sidebarRight + canvasGutter(),\n            null\n          ]\n        } else {\n          canvasStore.canvas.fpsInfoLocation = null\n        }\n        canvasStore.canvas.setDirty(false, true)\n      }\n    },\n    { immediate: true }\n  )\n})\n</script>\n\n<style>\n/* Global CSS variables for sidebar\n * These variables need to be global (not scoped) because they are used by\n * teleported components like WhatsNewPopup that render outside the sidebar\n * but need to reference sidebar dimensions for proper positioning.\n */\n:root {\n  --sidebar-padding: 4px;\n  --sidebar-icon-size: 1rem;\n\n  --sidebar-default-floating-width: 48px;\n  --sidebar-default-connected-width: calc(\n    var(--sidebar-default-floating-width) + var(--sidebar-padding) * 2\n  );\n  --sidebar-default-item-height: 56px;\n\n  --sidebar-small-floating-width: 48px;\n  --sidebar-small-connected-width: calc(\n    var(--sidebar-small-floating-width) + var(--sidebar-padding) * 2\n  );\n  --sidebar-small-item-height: 48px;\n\n  --sidebar-width: var(--sidebar-default-floating-width);\n  --sidebar-item-height: var(--sidebar-default-item-height);\n}\n\n:root:has(.side-tool-bar-container.small-sidebar) {\n  --sidebar-width: var(--sidebar-small-floating-width);\n  --sidebar-item-height: var(--sidebar-small-item-height);\n}\n\n:root:has(.side-tool-bar-container.connected-sidebar) {\n  --sidebar-width: var(--sidebar-default-connected-width);\n}\n\n:root:has(.side-tool-bar-container.small-sidebar.connected-sidebar) {\n  --sidebar-width: var(--sidebar-small-connected-width);\n}\n</style>\n\n<style scoped>\n.connected-sidebar {\n  padding: var(--sidebar-padding) 0;\n  background-color: var(--comfy-menu-bg);\n}\n</style>\n","<template>\n  <Button\n    variant=\"outline\"\n    size=\"sm\"\n    :class=\"\n      cn(\n        'group no-drag shrink-0 gap-1 rounded-lg',\n        active && 'bg-secondary-background-hover',\n        inviting && !active && 'agent-shimmer-outline'\n      )\n    \"\n    :aria-pressed=\"active\"\n  >\n    <i\n      :class=\"\n        cn(\n          'size-3 transition-transform duration-300 ease-out group-hover:rotate-360 group-hover:duration-500 motion-reduce:transition-none',\n          active ? 'icon-[comfy--astroid-filled]' : 'icon-[lucide--astroid]'\n        )\n      \"\n    />\n    <span>{{ $t('agent.entryButton') }}</span>\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\n\nconst { active = false, inviting = false } = defineProps<{\n  active?: boolean\n  /** Draw attention to the button for a user who has never opened the panel. */\n  inviting?: boolean\n}>()\n</script>\n","import { defineStore } from 'pinia'\nimport { computed } from 'vue'\n\nimport type { TopbarBadge } from '@/types/comfy'\n\nimport { useExtensionStore } from './extensionStore'\n\nexport const useTopbarBadgeStore = defineStore('topbarBadge', () => {\n  const extensionStore = useExtensionStore()\n\n  const badges = computed<TopbarBadge[]>(() =>\n    extensionStore.extensions.flatMap((e) => e.topbarBadges ?? [])\n  )\n\n  return {\n    badges\n  }\n})\n","<template>\n  <div class=\"flex h-full shrink-0 items-center\">\n    <TopbarBadge\n      v-for=\"badge in topbarBadgeStore.badges\"\n      :key=\"badge.text\"\n      :badge\n      :display-mode=\"displayMode\"\n      :reverse-order=\"reverseOrder\"\n      :no-padding=\"noPadding\"\n    />\n  </div>\n</template>\n\n<script lang=\"ts\" setup>\nimport { breakpointsTailwind, useBreakpoints } from '@vueuse/core'\nimport { computed } from 'vue'\n\nimport { useTopbarBadgeStore } from '@/stores/topbarBadgeStore'\n\nimport TopbarBadge from './TopbarBadge.vue'\n\nconst { reverseOrder, noPadding } = defineProps<{\n  reverseOrder?: boolean\n  noPadding?: boolean\n}>()\n\nconst breakpoints = useBreakpoints(breakpointsTailwind)\nconst isXl = breakpoints.greaterOrEqual('xl')\nconst isLg = breakpoints.greaterOrEqual('lg')\n\nconst displayMode = computed<'full' | 'compact' | 'icon-only'>(() => {\n  if (isXl.value) return 'full'\n  if (isLg.value) return 'compact'\n  return 'icon-only'\n})\n\nconst topbarBadgeStore = useTopbarBadgeStore()\n</script>\n","<template>\n  <Button\n    v-if=\"isCloud && isFreeTier && !subscribeToRunPromptVisible\"\n    class=\"mr-2 shrink-0 whitespace-nowrap\"\n    variant=\"subscribe\"\n    size=\"sm\"\n    data-testid=\"topbar-subscribe-button\"\n    @click=\"handleClick\"\n  >\n    {{ $t('subscription.subscribeForMore') }}\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useSubscribeToRunPromptPresence } from '@/platform/cloud/subscription/composables/useSubscribeCtaPresence'\nimport { useSubscriptionDialog } from '@/platform/cloud/subscription/composables/useSubscriptionDialog'\nimport { isCloud } from '@/platform/distribution/types'\n\nconst { isFreeTier } = useBillingContext()\nconst subscribeToRunPromptVisible = useSubscribeToRunPromptPresence()\nconst subscriptionDialog = useSubscriptionDialog()\n\nfunction handleClick() {\n  subscriptionDialog.showPricingTable({ reason: 'subscribe_now_button' })\n}\n</script>\n","import { defineStore } from 'pinia'\nimport { ref } from 'vue'\n\n/**\n * Cross-feature workflow-tab activity, keyed by tab path. Feature extensions\n * (the agent panel) write it; the topbar reads it, so the topbar never has to\n * import feature internals.\n */\nexport const useWorkflowTabActivityStore = defineStore(\n  'workflowTabActivity',\n  () => {\n    const editingTabPath = ref<string | null>(null)\n    const creatingTab = ref(false)\n    const unseenModifiedPaths = ref<Set<string>>(new Set())\n    function setEditing(path: string | null): void {\n      editingTabPath.value = path\n    }\n\n    function setCreating(creating: boolean): void {\n      creatingTab.value = creating\n    }\n\n    function markModified(path: string): void {\n      unseenModifiedPaths.value.add(path)\n    }\n\n    function markSeen(path: string): void {\n      unseenModifiedPaths.value.delete(path)\n    }\n\n    function pruneClosed(openPaths: string[]): void {\n      const open = new Set(openPaths)\n      if (editingTabPath.value !== null && !open.has(editingTabPath.value))\n        editingTabPath.value = null\n      for (const path of unseenModifiedPaths.value)\n        if (!open.has(path)) unseenModifiedPaths.value.delete(path)\n    }\n\n    function clearAgentActivity(): void {\n      editingTabPath.value = null\n      creatingTab.value = false\n      unseenModifiedPaths.value.clear()\n    }\n\n    return {\n      editingTabPath,\n      creatingTab,\n      unseenModifiedPaths,\n      setEditing,\n      setCreating,\n      markModified,\n      markSeen,\n      pruneClosed,\n      clearAgentActivity\n    }\n  }\n)\n","<template>\n  <Popover\n    ref=\"popoverRef\"\n    side=\"bottom\"\n    :side-offset=\"8\"\n    content-class=\"workflow-popover-fade w-fit rounded-xl border-none bg-transparent p-0 shadow-lg transition-opacity duration-150 ease-out\"\n    @mouseleave=\"hidePopover\"\n  >\n    <div\n      class=\"flex max-w-62.5 flex-col overflow-hidden rounded-xl bg-interface-menu-surface text-text-primary\"\n    >\n      <div\n        v-if=\"thumbnailUrl && !isActiveTab\"\n        class=\"workflow-preview-thumbnail relative p-2\"\n      >\n        <img\n          :src=\"thumbnailUrl\"\n          class=\"block h-50 rounded-lg bg-secondary-background object-cover p-2 shadow-lg\"\n          :style=\"{ width: `${POPOVER_WIDTH}px` }\"\n        />\n      </div>\n      <div class=\"px-3 pt-1 pb-2\">\n        <span class=\"block truncate text-sm font-medium text-text-primary\">\n          {{ workflowFilename }}\n        </span>\n      </div>\n    </div>\n  </Popover>\n</template>\n\n<script setup lang=\"ts\">\nimport Popover from '@/components/common/ImperativePopover.vue'\nimport { ref, toRefs } from 'vue'\n\nconst POPOVER_WIDTH = 250\n\ninterface Props {\n  workflowFilename: string\n  thumbnailUrl?: string\n  isActiveTab: boolean\n}\n\nconst props = defineProps<Props>()\nconst { thumbnailUrl, isActiveTab } = toRefs(props)\nconst popoverRef = ref<InstanceType<typeof Popover> | null>(null)\nlet hideTimeout: ReturnType<typeof setTimeout> | null = null\nlet showTimeout: ReturnType<typeof setTimeout> | null = null\n\nconst showPopover = (event: Event) => {\n  if (hideTimeout) {\n    clearTimeout(hideTimeout)\n    hideTimeout = null\n  }\n  if (showTimeout) {\n    clearTimeout(showTimeout)\n    showTimeout = null\n  }\n\n  const target = event.currentTarget\n  showTimeout = setTimeout(() => {\n    popoverRef.value?.show(event, target)\n  }, 200)\n}\n\nconst hidePopover = () => {\n  if (showTimeout) {\n    clearTimeout(showTimeout)\n    showTimeout = null\n  }\n\n  hideTimeout = setTimeout(() => {\n    if (popoverRef.value) {\n      popoverRef.value.hide()\n    }\n  }, 100)\n}\n\nconst togglePopover = (event: Event) => {\n  if (popoverRef.value) {\n    popoverRef.value.toggle(event)\n  }\n}\n\ndefineExpose({\n  showPopover,\n  hidePopover,\n  togglePopover\n})\n</script>\n","<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { useAgentPanelStore } from '@/workbench/extensions/agent/stores/agent/agentPanelStore'\n\nconst { workflowPath } = defineProps<{ workflowPath: string }>()\nconst { t } = useI18n()\nconst agentPanelStore = useAgentPanelStore()\n</script>\n\n<template>\n  <Tooltip\n    v-if=\"\n      agentPanelStore.enabled &&\n      agentPanelStore.selectedWorkflow?.path === workflowPath\n    \"\n  >\n    <TooltipTrigger as-child>\n      <span\n        role=\"img\"\n        :aria-label=\"t('agent.targetForThisChat')\"\n        class=\"inline-flex size-2.5 shrink-0 text-brand-yellow\"\n      >\n        <i class=\"icon-[comfy--comfy-c] size-full\" />\n      </span>\n    </TooltipTrigger>\n    <TooltipContent side=\"right\">{{\n      t('agent.targetForThisChat')\n    }}</TooltipContent>\n  </Tooltip>\n</template>\n","<template>\n  <ContextMenuRoot :modal=\"false\">\n    <ContextMenuTrigger as-child>\n      <div\n        ref=\"workflowTabRef\"\n        data-testid=\"workflow-tab\"\n        :class=\"\n          cn(\n            'workflow-tab group/tab relative h-full min-w-22.5 motion-safe:transition-[flex-shrink] motion-safe:duration-200 motion-safe:ease-out',\n            isActiveTab ? 'shrink-0' : 'shrink'\n          )\n        \"\n        v-bind=\"$attrs\"\n        @mouseenter=\"handleMouseEnter\"\n        @mouseleave=\"handleMouseLeave\"\n        @click=\"handleClick\"\n      >\n        <TabsTrigger\n          :value=\"workflowOption.workflow.path\"\n          class=\"h-full w-full py-2 pr-2 pl-3\"\n        >\n          <template v-if=\"showModeIcon\">\n            <i\n              v-if=\"isBuilderState\"\n              data-testid=\"workflow-mode-icon\"\n              class=\"icon-[lucide--hammer] bg-muted-foreground\"\n            />\n            <i\n              v-else-if=\"workflowOption.workflow.initialMode === 'app'\"\n              data-testid=\"workflow-mode-icon\"\n              class=\"icon-[lucide--panels-top-left] bg-primary-background\"\n            />\n          </template>\n          <WorkflowAgentTargetIndicator\n            :workflow-path=\"workflowOption.workflow.path\"\n          />\n          <span\n            class=\"workflow-label inline-block max-w-[150px] truncate font-inter text-sm leading-none font-normal text-inherit\"\n          >\n            {{ workflowOption.workflow.filename }}\n          </span>\n          <span\n            :class=\"\n              cn(\n                'relative size-4 shrink-0 group-focus-within/tab:invisible',\n                revealsCloseOnHover && 'group-hover/tab:invisible'\n              )\n            \"\n          >\n            <i\n              v-if=\"isAgentEditing\"\n              role=\"img\"\n              :aria-label=\"t('g.agentWorking')\"\n              class=\"absolute top-1/2 left-1/2 z-10 icon-[lucide--loader-circle] size-4 -translate-1/2 text-smoke-800 motion-safe:animate-spin\"\n            />\n            <span\n              v-else-if=\"showUnseenAgentDot\"\n              role=\"img\"\n              :aria-label=\"t('g.agentModified')\"\n              data-testid=\"agent-modified-indicator\"\n              class=\"absolute top-1/2 left-1/2 z-10 size-2 -translate-1/2 rounded-full bg-primary-background\"\n            />\n            <i\n              v-else-if=\"workflowStatus\"\n              role=\"img\"\n              :aria-label=\"workflowStatusLabel\"\n              :class=\"\n                cn(\n                  'absolute top-1/2 left-1/2 z-10 size-4 -translate-1/2',\n                  workflowStatusIconClasses[workflowStatus]\n                )\n              \"\n            />\n            <span\n              v-else-if=\"shouldShowUnsavedIndicator\"\n              data-testid=\"workflow-dirty-indicator\"\n              :class=\"\n                cn(\n                  'absolute top-1/2 left-1/2 z-10 size-2 -translate-1/2 rounded-full',\n                  isActiveTab ? 'bg-base-foreground' : 'bg-smoke-800'\n                )\n              \"\n            />\n          </span>\n        </TabsTrigger>\n        <Button\n          :class=\"\n            cn(\n              'close-button absolute top-1/2 right-2 size-4 -translate-y-1/2 rounded-none p-0 text-smoke-800 group-focus-within/tab:visible',\n              isActiveTab && !hasStatusIndicator ? 'visible' : 'invisible',\n              revealsCloseOnHover && 'group-hover/tab:visible'\n            )\n          \"\n          variant=\"muted-textonly\"\n          size=\"unset\"\n          :aria-label=\"t('g.close')\"\n          data-testid=\"close-workflow-button\"\n          @click.stop=\"onCloseWorkflow(workflowOption)\"\n        >\n          <i\n            data-testid=\"close-workflow-icon\"\n            class=\"icon-[lucide--x] size-4\"\n          />\n        </Button>\n      </div>\n    </ContextMenuTrigger>\n    <ContextMenuPortal>\n      <ContextMenuContent :class=\"cn(menuContentClass, 'min-w-56')\">\n        <MenuItems :items=\"contextMenuItems\" />\n      </ContextMenuContent>\n    </ContextMenuPortal>\n  </ContextMenuRoot>\n  <WorkflowTabPopover\n    ref=\"popoverRef\"\n    :workflow-filename=\"workflowOption.workflow.filename\"\n    :thumbnail-url=\"thumbnailUrl\"\n    :is-active-tab=\"isActiveTab\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport {\n  ContextMenuContent,\n  ContextMenuPortal,\n  ContextMenuRoot,\n  ContextMenuTrigger\n} from 'reka-ui'\nimport { computed, onUnmounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport MenuItems from '@/components/ui/menu/MenuItems.vue'\nimport { menuContentClass } from '@/components/ui/menu/menuStyles'\nimport TabsTrigger from '@/components/ui/tabs/TabsTrigger.vue'\nimport {\n  usePragmaticDraggable,\n  usePragmaticDroppable\n} from '@/composables/usePragmaticDragAndDrop'\nimport { useWorkflowActionsMenu } from '@/composables/useWorkflowActionsMenu'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useWorkflowThumbnail } from '@/renderer/core/thumbnail/useWorkflowThumbnail'\nimport { useCommandStore } from '@/stores/commandStore'\nimport type { WorkflowExecutionStatus } from '@/stores/executionStore'\nimport {\n  useExecutionStore,\n  WORKFLOW_STATUS_I18N_KEYS\n} from '@/stores/executionStore'\nimport { useWorkflowTabActivityStore } from '@/stores/workflowTabActivityStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport type { WorkflowMenuItem } from '@/types/workflowMenuItem'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport WorkflowTabPopover from './WorkflowTabPopover.vue'\nimport WorkflowAgentTargetIndicator from './WorkflowAgentTargetIndicator.vue'\n\ndefineOptions({ inheritAttrs: false })\n\ninterface WorkflowOption {\n  value: string\n  workflow: ComfyWorkflow\n}\n\nconst {\n  workflowOption,\n  isFirst,\n  isLast,\n  compact = false\n} = defineProps<{\n  workflowOption: WorkflowOption\n  isFirst: boolean\n  isLast: boolean\n  compact?: boolean\n}>()\n\nconst emit = defineEmits<{\n  closeToLeft: []\n  closeToRight: []\n  closeOthers: []\n}>()\n\nconst { t } = useI18n()\n\nconst workspaceStore = useWorkspaceStore()\nconst workflowStore = useWorkflowStore()\nconst settingStore = useSettingStore()\nconst executionStore = useExecutionStore()\nconst workflowTabRef = ref<HTMLElement | null>(null)\nconst popoverRef = ref<InstanceType<typeof WorkflowTabPopover> | null>(null)\nconst workflowThumbnail = useWorkflowThumbnail()\n\n// Use computed refs to cache autosave settings\nconst autoSaveSetting = computed(() =>\n  settingStore.get('Comfy.Workflow.AutoSave')\n)\nconst autoSaveDelay = computed(() =>\n  settingStore.get('Comfy.Workflow.AutoSaveDelay')\n)\n\nconst shouldShowUnsavedIndicator = computed(() => {\n  if (workspaceStore.shiftDown) {\n    // Branch 1: Shift key is held down, do not show the status indicator.\n    return false\n  }\n  if (!workflowOption.workflow.isPersisted) {\n    // Branch 2: Workflow is not persisted, show the status indicator.\n    return true\n  }\n  if (workflowOption.workflow.isModified) {\n    // Branch 3: Workflow is modified.\n    if (autoSaveSetting.value === 'off') {\n      // Sub-branch 3a: Autosave is off, so show the status indicator.\n      return true\n    }\n    if (autoSaveSetting.value === 'after delay' && autoSaveDelay.value > 3000) {\n      // Sub-branch 3b: Autosave delay is too high, so show the status indicator.\n      return true\n    }\n    // Sub-branch 3c: Workflow is modified but no condition applies, do not show the status indicator.\n    return false\n  }\n  // Default: do not show the status indicator. This should not be reachable.\n  return false\n})\n\nconst isBuilderState = computed(() => {\n  const currentMode = workflowOption.workflow.activeMode\n  return typeof currentMode === 'string' && currentMode.startsWith('builder:')\n})\n\nconst isActiveTab = computed(() => {\n  return workflowStore.isActive(workflowOption.workflow)\n})\n\nconst showModeIcon = computed(() => !compact || isActiveTab.value)\n\nconst workflowStatusIconClasses: Record<WorkflowExecutionStatus, string> = {\n  running:\n    'text-base-foreground icon-[lucide--loader-circle] motion-safe:animate-spin',\n  completed: 'icon-[lucide--circle-check] text-success-background',\n  failed: 'icon-[lucide--octagon-alert] text-destructive-background'\n}\n\nconst tabActivity = useWorkflowTabActivityStore()\n\nconst isAgentEditing = computed(\n  () => tabActivity.editingTabPath === workflowOption.workflow.path\n)\n\n// The active tab doesn't badge its own status - the user is already looking\n// at it. Background tabs surface the recorded execution status.\nconst workflowStatus = computed(() =>\n  isActiveTab.value\n    ? undefined\n    : executionStore.getWorkflowStatus(workflowOption.workflow)\n)\n\n// A failed run outranks the unseen-changes dot so the failure isn't masked.\nconst showUnseenAgentDot = computed(\n  () =>\n    tabActivity.unseenModifiedPaths.has(workflowOption.workflow.path) &&\n    workflowStatus.value !== 'failed'\n)\n\nconst workflowStatusLabel = computed(() =>\n  workflowStatus.value\n    ? t(WORKFLOW_STATUS_I18N_KEYS[workflowStatus.value])\n    : undefined\n)\n\nconst hasStatusIndicator = computed(\n  () =>\n    isAgentEditing.value ||\n    showUnseenAgentDot.value ||\n    workflowStatus.value !== undefined ||\n    shouldShowUnsavedIndicator.value\n)\n\nconst revealsCloseOnHover = computed(\n  () => isActiveTab.value || !compact || !hasStatusIndicator.value\n)\n\nconst thumbnailUrl = computed(() => {\n  return workflowThumbnail.getThumbnail(workflowOption.workflow.key)\n})\n\n// Event handlers that delegate to the popover component\nconst handleMouseEnter = (event: Event) => {\n  popoverRef.value?.showPopover(event)\n}\n\nconst handleMouseLeave = () => {\n  popoverRef.value?.hidePopover()\n}\n\nconst handleClick = (event: Event) => {\n  popoverRef.value?.togglePopover(event)\n}\n\nconst closeWorkflows = async (options: WorkflowOption[]) => {\n  for (const opt of options) {\n    if (\n      !(await useWorkflowService().closeWorkflow(opt.workflow, {\n        warnIfUnsaved: !workspaceStore.shiftDown,\n        hint: t('sideToolbar.workflowTab.dirtyCloseHint')\n      }))\n    ) {\n      // User cancelled, or the replacement load failed\n      break\n    }\n  }\n}\n\nconst onCloseWorkflow = async (option: WorkflowOption) => {\n  await closeWorkflows([option])\n}\n\nconst commandStore = useCommandStore()\nconst workflow = computed(() => workflowOption.workflow)\n\nconst { menuItems: baseMenuItems } = useWorkflowActionsMenu(\n  () => commandStore.execute('Comfy.RenameWorkflow'),\n  { includeDelete: false, workflow }\n)\n\nconst contextMenuItems = computed<WorkflowMenuItem[]>(() => [\n  ...baseMenuItems.value,\n  { separator: true },\n  {\n    id: 'close-tab',\n    label: t('tabMenu.closeTab'),\n    icon: 'pi pi-times',\n    command: () => onCloseWorkflow(workflowOption)\n  },\n  {\n    id: 'close-tabs-to-left',\n    label: t('tabMenu.closeTabsToLeft'),\n    overlayIcon: {\n      mainIcon: 'pi pi-times',\n      subIcon: 'pi pi-arrow-left',\n      positionX: 'right',\n      positionY: 'bottom',\n      subIconScale: 0.5\n    },\n    command: () => emit('closeToLeft'),\n    disabled: isFirst\n  },\n  {\n    id: 'close-tabs-to-right',\n    label: t('tabMenu.closeTabsToRight'),\n    overlayIcon: {\n      mainIcon: 'pi pi-times',\n      subIcon: 'pi pi-arrow-right',\n      positionX: 'right',\n      positionY: 'bottom',\n      subIconScale: 0.5\n    },\n    command: () => emit('closeToRight'),\n    disabled: isLast\n  },\n  {\n    id: 'close-other-tabs',\n    label: t('tabMenu.closeOtherTabs'),\n    overlayIcon: {\n      mainIcon: 'pi pi-times',\n      subIcon: 'pi pi-arrows-h',\n      positionX: 'right',\n      positionY: 'bottom',\n      subIconScale: 0.5\n    },\n    command: () => emit('closeOthers'),\n    disabled: isFirst && isLast\n  }\n])\n\nconst tabGetter = () => workflowTabRef.value as HTMLElement\n\nusePragmaticDraggable(tabGetter, {\n  getInitialData: () => {\n    return {\n      workflowKey: workflowOption.workflow.key\n    }\n  }\n})\n\nusePragmaticDroppable(tabGetter, {\n  getData: () => {\n    return {\n      workflowKey: workflowOption.workflow.key\n    }\n  },\n  onDrop: (e) => {\n    const fromIndex = workflowStore.openWorkflows.findIndex(\n      (wf) => wf.key === e.source.data.workflowKey\n    )\n    const toIndex = workflowStore.openWorkflows.findIndex(\n      (wf) => wf.key === e.location.current.dropTargets[0]?.data.workflowKey\n    )\n    if (fromIndex !== toIndex) {\n      workflowStore.reorderWorkflows(fromIndex, toIndex)\n    }\n  }\n})\n\nonUnmounted(() => {\n  popoverRef.value?.hidePopover()\n})\n</script>\n","import { watch } from 'vue'\n\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useExecutionStore } from '@/stores/executionStore'\n\nexport function useWorkflowStatusDismissal() {\n  const workflowStore = useWorkflowStore()\n  const executionStore = useExecutionStore()\n\n  watch(\n    () => {\n      const workflow = workflowStore.activeWorkflow\n      return [workflow, executionStore.getWorkflowStatus(workflow)] as const\n    },\n    ([workflow, status]) => {\n      if (workflow && status !== undefined && status !== 'running') {\n        executionStore.clearWorkflowStatus(workflow)\n      }\n    },\n    { immediate: true }\n  )\n}\n","export const AGENT_DOCS_URL = 'https://docs.comfy.org/agent-tools/in-app-agent'\n","export const AGENT_CONSENT_SETTING_ID =\n  'Comfy.AgentPanel.ConsentAccepted' as const\n","import type {\n  GlobalSetting,\n  GlobalSettingKey,\n  GlobalSettingValue\n} from '@comfyorg/ingest-types'\nimport { zErrorResponse, zGlobalSetting } from '@comfyorg/ingest-types/zod'\n\nimport { getComfyApiBaseUrl } from '@/config/comfyApi'\nimport {\n  fetchWithUnifiedRemint,\n  shouldRemintCloudRequest\n} from '@/platform/auth/unified/remintRetry'\nimport { isCloud } from '@/platform/distribution/types'\nimport { api } from '@/scripts/api'\nimport type { WebSessionSend } from '@/platform/auth/session/webSessionFetch'\nimport type { AuthHeader } from '@/types/authTypes'\n\nexport class GlobalSettingsApiError extends Error {\n  constructor(\n    message: string,\n    readonly status?: number\n  ) {\n    super(message)\n    this.name = 'GlobalSettingsApiError'\n  }\n}\n\nfunction globalSettingsUrl(key?: GlobalSettingKey): string {\n  const path = `/global-settings${key ? `/${encodeURIComponent(key)}` : ''}`\n  return isCloud ? api.apiURL(path) : `${getComfyApiBaseUrl()}/api${path}`\n}\n\nasync function responseBody(response: Response): Promise<unknown> {\n  try {\n    return await response.json()\n  } catch {\n    throw new GlobalSettingsApiError(\n      'Global setting returned invalid JSON',\n      response.status\n    )\n  }\n}\n\ntype GlobalSettingsAuth = AuthHeader | WebSessionSend\n\nfunction sendGlobalSetting(\n  url: string,\n  init: RequestInit,\n  auth: GlobalSettingsAuth,\n  headers: Record<string, string> = {}\n): Promise<Response> {\n  if (typeof auth === 'function') return auth(url, { ...init, headers })\n  return shouldRemintCloudRequest().then((remint) =>\n    fetchWithUnifiedRemint(\n      url,\n      { ...init, headers: { ...headers, ...auth } },\n      remint\n    )\n  )\n}\n\nasync function storedSetting(response: Response): Promise<GlobalSetting> {\n  if (!response.ok) {\n    throw new GlobalSettingsApiError(\n      `Global setting request failed: ${response.status}`,\n      response.status\n    )\n  }\n  const payload = zGlobalSetting.safeParse(await responseBody(response))\n  if (!payload.success) {\n    throw new GlobalSettingsApiError(\n      'Global setting returned an invalid response',\n      response.status\n    )\n  }\n  return payload.data\n}\n\nexport async function getGlobalSetting(\n  key: GlobalSettingKey,\n  auth: GlobalSettingsAuth\n): Promise<GlobalSetting | undefined> {\n  const response = await sendGlobalSetting(\n    globalSettingsUrl(key),\n    { cache: 'no-store' },\n    auth\n  )\n  if (response.status === 404) {\n    const error = zErrorResponse.safeParse(await responseBody(response))\n    if (error.success && error.data.code === 'NOT_FOUND') return undefined\n  }\n  return storedSetting(response)\n}\n\nexport async function setGlobalSetting(\n  setting: GlobalSettingValue,\n  auth: GlobalSettingsAuth\n): Promise<GlobalSetting> {\n  const response = await sendGlobalSetting(\n    globalSettingsUrl(),\n    { method: 'POST', body: JSON.stringify(setting) },\n    auth,\n    { 'Content-Type': 'application/json' }\n  )\n  return storedSetting(response)\n}\n","import { defineStore } from 'pinia'\nimport { computed, ref, watch } from 'vue'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport {\n  webSessionRequests,\n  webSessionSend\n} from '@/platform/auth/session/webSessionFetch'\nimport { AGENT_CONSENT_SETTING_ID } from '@/platform/settings/constants/agent'\nimport {\n  getGlobalSetting,\n  setGlobalSetting\n} from '@/platform/settings/globalSettingsApi'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useAuthStore } from '@/stores/authStore'\n\nclass AgentConsentAuthenticationError extends Error {\n  override name = 'AgentConsentAuthenticationError'\n}\n\nexport const useAgentConsentStore = defineStore('agentConsent', () => {\n  const authStore = useAuthStore()\n  const workspaceStore = useTeamWorkspaceStore()\n  const { resolvedUserInfo } = useCurrentUser()\n  const loadedIdentity = ref<string | null>(null)\n  const acceptedIdentity = ref<string | null>(null)\n  const checkSettled = ref(false)\n  const isChecking = computed(\n    () => Boolean(currentUserId()) && !checkSettled.value\n  )\n  let session = 0\n  let pendingLoad: { identity: string; result: Promise<boolean> } | null = null\n\n  function currentUserId(): string | undefined {\n    return resolvedUserInfo.value?.id\n  }\n\n  function currentIdentity(): string | null {\n    const userId = currentUserId()\n    const workspaceId = workspaceStore.activeWorkspaceId\n    if (!userId || !workspaceId || workspaceStore.isSwitching) return null\n    return JSON.stringify([\n      userId,\n      workspaceId,\n      workspaceStore.workspaceTransitionGeneration\n    ])\n  }\n  const identity = computed(currentIdentity)\n  const accepted = computed(\n    () =>\n      currentIdentity() !== null && acceptedIdentity.value === currentIdentity()\n  )\n\n  watch(\n    currentIdentity,\n    () => {\n      session += 1\n      pendingLoad = null\n      loadedIdentity.value = null\n      acceptedIdentity.value = null\n      checkSettled.value = false\n    },\n    { flush: 'sync' }\n  )\n\n  async function ensureScope(): Promise<string | null> {\n    const userId = currentUserId()\n    if (!userId) {\n      throw new AgentConsentAuthenticationError(\n        'Comfy account authentication is required'\n      )\n    }\n    const generation = workspaceStore.workspaceTransitionGeneration\n    if (!workspaceStore.activeWorkspaceId && !workspaceStore.isSwitching) {\n      await workspaceStore.initialize()\n    }\n    if (\n      currentUserId() !== userId ||\n      workspaceStore.workspaceTransitionGeneration !== generation ||\n      workspaceStore.isSwitching\n    )\n      return null\n    const scope = currentIdentity()\n    if (!scope) {\n      throw new AgentConsentAuthenticationError(\n        'Comfy workspace authentication is required'\n      )\n    }\n    return scope\n  }\n\n  function stillOwns(sessionId: number, identity: string): boolean {\n    return session === sessionId && currentIdentity() === identity\n  }\n\n  async function requireAuth(sessionId: number, identity: string) {\n    const send = webSessionRequests() ? await webSessionSend() : undefined\n    const auth = send ?? (await authStore.getWorkspaceAuthHeader())\n    if (!stillOwns(sessionId, identity)) return null\n    if (!auth) {\n      throw new AgentConsentAuthenticationError(\n        'Comfy account authentication is required'\n      )\n    }\n    return auth\n  }\n\n  async function readConsent(\n    sessionId: number,\n    identity: string\n  ): Promise<boolean> {\n    try {\n      const auth = await requireAuth(sessionId, identity)\n      if (!auth) return false\n      const stored = await getGlobalSetting(AGENT_CONSENT_SETTING_ID, auth)\n      if (!stillOwns(sessionId, identity)) return false\n      if (loadedIdentity.value === identity) return accepted.value\n\n      loadedIdentity.value = identity\n      acceptedIdentity.value = stored?.value === true ? identity : null\n      return accepted.value\n    } catch (error) {\n      if (!stillOwns(sessionId, identity)) return false\n      throw error\n    } finally {\n      if (stillOwns(sessionId, identity)) checkSettled.value = true\n    }\n  }\n\n  async function load(): Promise<boolean> {\n    const initialSession = session\n    let identity: string | null\n    try {\n      identity = await ensureScope()\n    } catch (error) {\n      if (session === initialSession) checkSettled.value = true\n      throw error\n    }\n    if (!identity) return false\n    if (loadedIdentity.value === identity) return accepted.value\n    if (pendingLoad?.identity === identity) return pendingLoad.result\n\n    const result = readConsent(session, identity)\n    const request = { identity, result }\n    pendingLoad = request\n    try {\n      return await result\n    } finally {\n      if (pendingLoad === request) pendingLoad = null\n    }\n  }\n\n  async function accept(expectedIdentity?: string): Promise<boolean> {\n    const identity = await ensureScope()\n    if (!identity) return false\n    if (expectedIdentity && identity !== expectedIdentity) return false\n\n    const sessionId = session\n    try {\n      const auth = await requireAuth(sessionId, identity)\n      if (!auth) return false\n      await setGlobalSetting(\n        { key: AGENT_CONSENT_SETTING_ID, value: true },\n        auth\n      )\n      if (!stillOwns(sessionId, identity)) return false\n\n      loadedIdentity.value = identity\n      acceptedIdentity.value = identity\n      checkSettled.value = true\n      return true\n    } catch (error) {\n      if (!stillOwns(sessionId, identity)) return false\n      throw error\n    }\n  }\n\n  return { accepted, identity, isChecking, ensureScope, load, accept }\n})\n","import { defineAsyncComponent } from 'vue'\nimport { storeToRefs } from 'pinia'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { i18n } from '@/i18n'\nimport { useTelemetry } from '@/platform/telemetry'\nimport type {\n  AgentConsentDecision,\n  AgentConsentOfferExit,\n  AgentConsentTrigger\n} from '@/platform/telemetry/types'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useAuthDialogs } from '@/composables/auth/useAuthDialogs'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { AGENT_DOCS_URL } from '@/workbench/extensions/agent/agentDocs'\nimport { useAgentConsentStore } from '@/workbench/extensions/agent/stores/agent/agentConsentStore'\n\nexport const CONSENT_DIALOG_KEY = 'agent-consent'\nconst CONSENT_MEDIA_BASE = 'https://media.comfy.org/website/comfy-agent'\nconst CONSENT_VIDEO_SOURCES = [\n  {\n    src: `${CONSENT_MEDIA_BASE}/agent-consent-v2-1280.webm`,\n    type: 'video/webm'\n  },\n  {\n    src: `${CONSENT_MEDIA_BASE}/agent-consent-v2-1280.mp4`,\n    type: 'video/mp4'\n  }\n]\nconst CONSENT_POSTER_SRC = `${CONSENT_MEDIA_BASE}/agent-consent-v2-poster.jpg`\n\nconst AgentConsentCard = defineAsyncComponent(\n  () =>\n    import('@/workbench/extensions/agent/components/agent/AgentConsentCard.vue')\n)\n\nexport interface ConsentOfferHooks {\n  onShown?: () => void\n  /** Asked right before the card mounts, after every await that precedes it. */\n  canShow?: () => boolean\n}\n\nexport function useAgentConsent() {\n  const dialogStore = useDialogStore()\n  const { showSignInDialog } = useAuthDialogs()\n  const consentStore = useAgentConsentStore()\n  const toast = useToast()\n  const { isLoggedIn } = useCurrentUser()\n  const { accepted, identity, isChecking } = storeToRefs(consentStore)\n  const { t } = i18n.global\n\n  /**\n   * Names an ending of the consent request that produced neither a card on\n   * screen nor a decision.\n   *\n   * These are the last silent endings on the automatic consent chain.\n   * `agent_consent_not_offered` means a named surface is holding the offer and\n   * will retry it, and `agent_consent_offer_exited`'s other stages all stop\n   * before the consent scope is resolved - so an attempt that got as far as\n   * asking and still ended with nothing was indistinguishable in product\n   * analytics from a user who was never offered. The failing ones do reach\n   * Sentry and RUM through `reportError`, which is why they were easy to\n   * believe were covered; `reportError` has no PostHog sink, so none of them\n   * were in the funnel denominator `agent_consent_not_offered` is read against.\n   *\n   * `retry_armed` is reported false rather than read, and that is a code reading\n   * rather than a tested fact: `offerConsentUnprompted` calls `dropHold()`\n   * immediately before `withConsent`, the only caller that can re-arm is the\n   * `canShow` hook, and `canShow` runs after every exit reported here. A\n   * re-entrant offer cannot re-arm either - it exits on `autoShowInFlight`\n   * before reaching a hold. If that ordering changes, this becomes wrong\n   * silently, so the property's doc says which ordering it depends on.\n   */\n  function reportRequestExit(\n    exit: AgentConsentOfferExit,\n    trigger: AgentConsentTrigger\n  ): void {\n    useTelemetry()?.trackAgentConsentOfferExited({\n      exit,\n      stage: 'request',\n      retry_armed: false,\n      trigger\n    })\n  }\n\n  function showConsentDialog(\n    trigger: AgentConsentTrigger,\n    persistOnAccept = true,\n    expectedIdentity?: string,\n    { onShown, canShow }: ConsentOfferHooks = {}\n  ): Promise<boolean> {\n    return new Promise<boolean>((resolve) => {\n      if (canShow && !canShow()) {\n        resolve(false)\n        return\n      }\n      let settled = false\n      let saving = false\n      let shown = false\n      let saveErrorShown = false\n\n      /**\n       * One outcome per card that was on screen, so this event and\n       * `agent_consent_shown` stay 1:1 and a shown card with no outcome is a\n       * defect rather than a dismissal. `accepted` and `rejected` keep exactly\n       * the meaning they already had.\n       */\n      const reportOutcome = (decision: AgentConsentDecision): void => {\n        useTelemetry()?.trackAgentConsentResolved({\n          decision,\n          save_error_shown: saveErrorShown\n        })\n      }\n\n      const closeWith = (result: boolean): void => {\n        if (settled) return\n        settled = true\n        dialogStore.closeDialog({ key: CONSENT_DIALOG_KEY })\n        resolve(result)\n      }\n\n      function handleSaveFailure(error: unknown): void {\n        if (settled) return\n        saving = false\n        // Not an outcome: the card stays open, retryable, with the error on it.\n        // The ending it eventually reaches carries this flag instead, which is\n        // what separates giving up after a failed save from walking away.\n        saveErrorShown = true\n        reportError(error, {\n          surface: 'agent',\n          errorType: 'agent_consent_setting_write_failure'\n        })\n        dialogStore.updateDialog({\n          key: CONSENT_DIALOG_KEY,\n          contentProps: {\n            accepting: false,\n            error: t('agent.consent.saveError')\n          },\n          dialogComponentProps: {\n            closable: true,\n            dismissOnPointerDownOutside: true\n          }\n        })\n      }\n\n      const accept = async (): Promise<void> => {\n        if (saving || settled) return\n        saving = true\n        dialogStore.updateDialog({\n          key: CONSENT_DIALOG_KEY,\n          contentProps: { accepting: true, error: '' },\n          dialogComponentProps: {\n            closable: false,\n            dismissOnPointerDownOutside: false\n          }\n        })\n\n        try {\n          const saved = persistOnAccept\n            ? await consentStore.accept(expectedIdentity)\n            : true\n          // Only a persisted acceptance is `accepted`. Without\n          // `persistOnAccept` this card is the first half of the signed-out\n          // flow, which still has a sign-in and a real save to clear before\n          // consent exists, so that path still reports its own `accepted` once\n          // those land - `accepted_pending_sign_in` records that the card half\n          // is done without claiming consent that does not exist yet.\n          //\n          // A save that resolved false neither stored consent nor raised, so it\n          // shows no error and closes the card: the user believes they\n          // consented. That is the ending this event could not tell from a\n          // dismissal, and the whole reason the two are named separately.\n          if (!persistOnAccept) reportOutcome('accepted_pending_sign_in')\n          else reportOutcome(saved ? 'accepted' : 'accept_not_persisted')\n          closeWith(saved)\n        } catch (error) {\n          handleSaveFailure(error)\n        }\n      }\n\n      dialogStore.showDialog({\n        key: CONSENT_DIALOG_KEY,\n        component: AgentConsentCard,\n        props: {\n          title: t('agent.consent.title'),\n          titleId: CONSENT_DIALOG_KEY,\n          paragraphs: [t('agent.consent.body1'), t('agent.consent.body2')],\n          videoSources: CONSENT_VIDEO_SOURCES,\n          posterSrc: CONSENT_POSTER_SRC,\n          docsUrl: AGENT_DOCS_URL,\n          accepting: false,\n          error: '',\n          onVnodeMounted: () => {\n            shown = true\n            useTelemetry()?.trackAgentConsentShown({ trigger })\n            if (expectedIdentity && identity.value !== expectedIdentity) return\n            onShown?.()\n          },\n          onAccept: () => void accept(),\n          onReject: () => {\n            reportOutcome('rejected')\n            closeWith(false)\n          }\n        },\n        dialogComponentProps: {\n          dismissOnPointerDownOutside: true,\n          headless: true,\n          onClose: () => {\n            if (settled) return\n            settled = true\n            // Escape, the overlay mask, or a programmatic close. Reached only\n            // when nothing else settled first, so it is exactly the ending that\n            // used to emit `agent_consent_shown` and then nothing at all.\n            //\n            // Before the card renders there is no impression to resolve, and\n            // reporting a dismissal against one would break this event's 1:1\n            // agreement with `agent_consent_shown` in the other direction - so\n            // that window is an ending of the request instead. It is narrow (the\n            // card is an async component, so it is the chunk's load time) and\n            // its production frequency is unknown rather than assumed to be\n            // zero.\n            if (shown) reportOutcome('dismissed')\n            else reportRequestExit('card_closed_before_mount', trigger)\n            resolve(false)\n          }\n        }\n      })\n    })\n  }\n\n  async function acceptAfterSignIn(\n    trigger: AgentConsentTrigger,\n    hooks: ConsentOfferHooks\n  ): Promise<string | null> {\n    if (!(await showConsentDialog(trigger, false, undefined, hooks)))\n      return null\n    try {\n      if (!(await showSignInDialog())) return null\n    } catch (error) {\n      reportError(error, {\n        surface: 'agent',\n        errorType: 'agent_consent_sign_in_failure'\n      })\n      toast.error(t('g.error'), {\n        description: t('agent.consent.signInError')\n      })\n      return null\n    }\n\n    try {\n      const decisionIdentity = await consentStore.ensureScope()\n      if (!decisionIdentity || !(await consentStore.accept(decisionIdentity))) {\n        useTelemetry()?.trackAgentConsentResolved({\n          decision: 'accept_not_persisted',\n          save_error_shown: false\n        })\n        return null\n      }\n      // The second half of the signed-out flow, so this is the moment consent\n      // becomes stored rather than the card's own ending - the card already\n      // reported `accepted_pending_sign_in`. No save error can have been shown\n      // on it: its accept ran with `persistOnAccept` false and never wrote.\n      useTelemetry()?.trackAgentConsentResolved({\n        decision: 'accepted',\n        save_error_shown: false\n      })\n      return decisionIdentity\n    } catch (error) {\n      reportError(error, {\n        surface: 'agent',\n        errorType: 'agent_consent_setting_write_failure'\n      })\n      toast.error(t('g.error'), {\n        description: t('agent.consent.saveError')\n      })\n      return null\n    }\n  }\n\n  async function requestConsentForCurrentUser(\n    trigger: AgentConsentTrigger,\n    hooks: ConsentOfferHooks\n  ): Promise<string | null> {\n    let decisionIdentity: string | null\n    // Which call is in flight, so the catch can tell a scope probe that failed\n    // from a consent read that failed. The error cannot carry that: both raise\n    // `AgentConsentAuthenticationError` with the same \"account authentication is\n    // required\" message, `ensureScope` from its own missing user and `load` from\n    // the auth header its read needs.\n    let reading = false\n    try {\n      decisionIdentity = await consentStore.ensureScope()\n      if (!decisionIdentity) {\n        reportRequestExit('scope_changed_before_read', trigger)\n        return null\n      }\n      reading = true\n      await consentStore.load()\n    } catch (error) {\n      reportRequestExit(\n        reading ? 'consent_read_failed' : 'scope_probe_failed',\n        trigger\n      )\n      reportError(error, {\n        surface: 'agent',\n        errorType: 'agent_consent_setting_load_failure'\n      })\n      toast.error(t('g.error'), {\n        description: t('agent.consent.loadError')\n      })\n      return null\n    }\n\n    if (identity.value !== decisionIdentity) {\n      reportRequestExit('scope_changed_after_read', trigger)\n      return null\n    }\n    // Two endings report nothing here, and both are successes rather than\n    // silences. `showConsentDialog` returning false because `canShow` said no is\n    // already named by the surface that took the screen - the caller's hook\n    // holds the offer and `agent_consent_not_offered` carries the reason, so\n    // naming it again would double-count one deferral. And consent that is\n    // already stored skips the card entirely: this runs on to `onAccept`, which\n    // for the automatic offer is the only producer of\n    // `agent_panel_opened(source=automatic_consent)`. Reading the absence of a\n    // card as a failed offer is the error that mis-ranked gc-17.\n    if (\n      !accepted.value &&\n      !(await showConsentDialog(trigger, true, decisionIdentity, hooks))\n    )\n      return null\n    return decisionIdentity\n  }\n\n  async function withConsent(\n    trigger: AgentConsentTrigger,\n    onAccept: () => void,\n    hooks: ConsentOfferHooks = {}\n  ): Promise<void> {\n    const decisionIdentity = isLoggedIn.value\n      ? await requestConsentForCurrentUser(trigger, hooks)\n      : await acceptAfterSignIn(trigger, hooks)\n    if (\n      !decisionIdentity ||\n      identity.value !== decisionIdentity ||\n      !accepted.value\n    )\n      return\n    onAccept()\n  }\n\n  return { accepted, isChecking, withConsent }\n}\n","<template>\n  <div class=\"shrink-0 self-center\">\n    <Menu :items=\"menuItems\" max-height=\"viewport\">\n      <template #trigger>\n        <Button\n          :tooltip=\"$t('g.moreWorkflows')\"\n          variant=\"muted-textonly\"\n          size=\"icon\"\n          :aria-label=\"$t('g.moreWorkflows')\"\n          icon=\"icon-[lucide--ellipsis]\"\n        />\n      </template>\n      <template #item=\"{ item }\">\n        <i v-if=\"item.icon\" :class=\"item.icon\" />\n        <WorkflowAgentTargetIndicator\n          v-if=\"item.key\"\n          :workflow-path=\"item.key\"\n        />\n        <span>{{ item.label }}</span>\n      </template>\n    </Menu>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\n\nimport WorkflowAgentTargetIndicator from './WorkflowAgentTargetIndicator.vue'\n\nconst props = defineProps<{\n  workflows: ComfyWorkflow[]\n  activeWorkflow: ComfyWorkflow | null\n}>()\n\nconst workflowService = useWorkflowService()\n\nconst menuItems = computed(() =>\n  props.workflows.map((workflow: ComfyWorkflow) => ({\n    label: workflow.filename,\n    key: workflow.path,\n    icon:\n      props.activeWorkflow?.key === workflow.key ? 'pi pi-check' : undefined,\n    command: () => {\n      void workflowService.openWorkflow(workflow)\n    }\n  }))\n)\n</script>\n","<template>\n  <div\n    :class=\"\n      cn(\n        'workflow-tabs-container flex h-full flex-auto flex-row gap-1 overflow-hidden bg-comfy-menu-bg px-1',\n        isDesktop ? 'max-w-[env(titlebar-area-width,100vw)]' : 'max-w-full'\n      )\n    \"\n  >\n    <div\n      ref=\"tabStripRef\"\n      data-testid=\"workflow-tab-strip\"\n      class=\"no-drag scrollbar-thin scrollbar-thumb-alpha-smoke-500-50 scrollbar-track-transparent overflow-x-auto overflow-y-hidden\"\n      @wheel=\"handleWheel\"\n      @transitionend=\"handleTabResize\"\n    >\n      <Tabs\n        class=\"h-full\"\n        :model-value=\"workflowStore.activeWorkflow?.path ?? ''\"\n        activation-mode=\"manual\"\n        @update:model-value=\"openWorkflowByPath\"\n      >\n        <TabsList\n          :class=\"cn('workflow-tabs h-full flex-nowrap gap-1', props.class)\"\n        >\n          <WorkflowTab\n            v-for=\"(option, index) in options\"\n            :key=\"option.value\"\n            :workflow-option=\"option\"\n            :is-first=\"index === 0\"\n            :is-last=\"index === options.length - 1\"\n            :compact=\"isOverflowing\"\n            @click.middle=\"onCloseWorkflow(option)\"\n            @close-to-left=\"closeWorkflows(options.slice(0, index))\"\n            @close-to-right=\"closeWorkflows(options.slice(index + 1))\"\n            @close-others=\"\n              closeWorkflows([\n                ...options.slice(index + 1),\n                ...options.slice(0, index)\n              ])\n            \"\n          />\n        </TabsList>\n      </Tabs>\n    </div>\n    <WorkflowOverflowMenu\n      v-if=\"isOverflowing\"\n      :workflows=\"workflowStore.openWorkflows\"\n      :active-workflow=\"workflowStore.activeWorkflow\"\n    />\n    <Button\n      :tooltip=\"$t('sideToolbar.newBlankWorkflow')\"\n      class=\"new-blank-workflow-button no-drag shrink-0 self-center rounded-lg\"\n      variant=\"muted-textonly\"\n      size=\"icon\"\n      :aria-label=\"$t('sideToolbar.newBlankWorkflow')\"\n      @click=\"() => commandStore.execute('Comfy.NewBlankWorkflow')\"\n    >\n      <i class=\"pi pi-plus\" />\n    </Button>\n    <div\n      v-if=\"isIntegratedTabBar\"\n      data-testid=\"integrated-tab-bar-actions\"\n      :data-agent-gate-settled=\"agentPanelStore.gateSettled || undefined\"\n      :data-agent-flags-settled=\"agentPanelStore.flagsSettled || undefined\"\n      class=\"ml-auto flex shrink-0 items-center gap-2 px-2\"\n    >\n      <TopbarBadges />\n      <TopbarSubscribeButton />\n      <div\n        v-if=\"topbarBadgeStore.badges.length\"\n        data-testid=\"environment-badge-separator\"\n        class=\"h-5 w-px shrink-0 bg-border-subtle\"\n      />\n      <Button\n        v-if=\"isCloud || isNightly\"\n        :tooltip=\"$t('actionbar.feedbackTooltip')\"\n        variant=\"muted-textonly\"\n        size=\"icon\"\n        class=\"size-6 shrink-0 rounded-sm p-0\"\n        :aria-label=\"$t('actionbar.feedback')\"\n        @click=\"openFeedback\"\n      >\n        <i class=\"icon-[lucide--megaphone] size-4\" />\n      </Button>\n      <CurrentUserButton v-if=\"showCurrentUser\" compact class=\"shrink-0 p-1\" />\n      <LoginButton v-else class=\"p-1\" />\n      <template v-if=\"showAgentEntry\">\n        <div\n          data-testid=\"agent-entry-separator\"\n          class=\"h-5 w-px shrink-0 bg-border-subtle\"\n        />\n        <AgentEntryButton\n          :active=\"agentPanelStore.isVisible\"\n          :inviting=\"!agentPanelStore.hasEverOpened\"\n          @click=\"onAgentEntryClick\"\n        />\n      </template>\n    </div>\n    <div v-else class=\"ml-auto flex h-full shrink-0 items-center\">\n      <TopbarBadges />\n      <TopbarSubscribeButton />\n    </div>\n    <div\n      v-if=\"isDesktop\"\n      class=\"window-actions-spacer app-drag min-w-[min(75px,env(titlebar-area-width,0)*9999)] flex-auto shrink-0\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useResizeObserver } from '@vueuse/core'\nimport { computed, nextTick, ref, watch } from 'vue'\n\nimport AgentEntryButton from '@/components/topbar/AgentEntryButton.vue'\nimport CurrentUserButton from '@/components/topbar/CurrentUserButton.vue'\nimport LoginButton from '@/components/topbar/LoginButton.vue'\nimport TopbarBadges from '@/components/topbar/TopbarBadges.vue'\nimport TopbarSubscribeButton from '@/components/topbar/TopbarSubscribeButton.vue'\nimport WorkflowTab from '@/components/topbar/WorkflowTab.vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Tabs from '@/components/ui/tabs/Tabs.vue'\nimport TabsList from '@/components/ui/tabs/TabsList.vue'\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useWorkflowStatusDismissal } from '@/composables/useWorkflowStatusDismissal'\nimport { useOverflowObserver } from '@/composables/element/useOverflowObserver'\nimport { isCloud, isDesktop, isNightly } from '@/platform/distribution/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { openFeedbackDialog } from '@/platform/support/feedbackDialog'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useTopbarBadgeStore } from '@/stores/topbarBadgeStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport { useAgentConsent } from '@/workbench/extensions/agent/composables/agent/useAgentConsent'\nimport { useAgentPanelStore } from '@/workbench/extensions/agent/stores/agent/agentPanelStore'\n\nimport WorkflowOverflowMenu from './WorkflowOverflowMenu.vue'\n\ninterface WorkflowOption {\n  value: string\n  workflow: ComfyWorkflow\n}\n\nconst props = defineProps<{\n  class?: string\n}>()\n\nconst settingStore = useSettingStore()\nconst workspaceStore = useWorkspaceStore()\nconst workflowStore = useWorkflowStore()\nconst workflowService = useWorkflowService()\nconst commandStore = useCommandStore()\nconst agentPanelStore = useAgentPanelStore()\nconst topbarBadgeStore = useTopbarBadgeStore()\nconst { withConsent, isChecking } = useAgentConsent()\nconst isOpeningAgent = ref(false)\nconst { isLoggedIn } = useCurrentUser()\n\nconst showAgentEntry = computed(\n  () => agentPanelStore.enabled && !(agentPanelStore.isOpen && isChecking.value)\n)\n\nasync function onAgentEntryClick(): Promise<void> {\n  if (isOpeningAgent.value) return\n  isOpeningAgent.value = true\n\n  try {\n    if (agentPanelStore.isVisible) {\n      useTelemetry()?.trackAgentEntryButtonClicked({\n        resulting_state: 'closed'\n      })\n      agentPanelStore.toggle()\n      return\n    }\n\n    agentPanelStore.suppressRestoredOpen()\n    await withConsent('button_click', () => {\n      if (!agentPanelStore.enabled) return\n      useTelemetry()?.trackAgentEntryButtonClicked({\n        resulting_state: 'opened'\n      })\n      agentPanelStore.open()\n    })\n  } finally {\n    isOpeningAgent.value = false\n  }\n}\n\n// Dismiss a tab's terminal status badge once it has been viewed\nuseWorkflowStatusDismissal()\n\nconst isIntegratedTabBar = computed(\n  () => settingStore.get('Comfy.UI.TabBarLayout') !== 'Legacy'\n)\nconst showCurrentUser = computed(() => isCloud || isLoggedIn.value)\n\nfunction openFeedback() {\n  openFeedbackDialog('topbar')\n}\n\nconst tabStripRef = ref<HTMLElement | null>(null)\n\nconst options = computed<WorkflowOption[]>(() =>\n  workflowStore.openWorkflows.map((workflow) => ({\n    value: workflow.path,\n    workflow\n  }))\n)\n\nasync function openWorkflowByPath(path: string | number) {\n  const option = options.value.find(({ value }) => value === path)\n  if (!option) return\n  await workflowService.openWorkflow(option.workflow)\n}\n\nconst closeWorkflows = async (options: WorkflowOption[]) => {\n  for (const opt of options) {\n    if (\n      !(await workflowService.closeWorkflow(opt.workflow, {\n        warnIfUnsaved: !workspaceStore.shiftDown\n      }))\n    ) {\n      // User cancelled, or the replacement load failed\n      break\n    }\n  }\n}\n\nconst onCloseWorkflow = async (option: WorkflowOption) => {\n  await closeWorkflows([option])\n}\n\nconst WHEEL_LINE_HEIGHT_PX = 16\n\nfunction handleWheel(event: WheelEvent) {\n  if (event.ctrlKey || event.metaKey) return\n  if (Math.abs(event.deltaX) >= Math.abs(event.deltaY)) return\n  event.preventDefault()\n  const unit =\n    event.deltaMode === WheelEvent.DOM_DELTA_LINE\n      ? WHEEL_LINE_HEIGHT_PX\n      : event.deltaMode === WheelEvent.DOM_DELTA_PAGE\n        ? (tabStripRef.value?.clientWidth ?? 0)\n        : 1\n  tabStripRef.value?.scrollBy({ left: event.deltaY * unit })\n}\n\nasync function revealActiveTab() {\n  await nextTick()\n  tabStripRef.value\n    ?.querySelector('[role=\"tab\"][aria-selected=\"true\"]')\n    ?.scrollIntoView({ block: 'nearest', inline: 'nearest' })\n}\n\nconst { isOverflowing, checkOverflow } = useOverflowObserver(tabStripRef, {\n  useResizeObserver: false\n})\n\nuseResizeObserver(tabStripRef, () => {\n  checkOverflow()\n  void revealActiveTab()\n})\n\nwatch(\n  () => workflowStore.activeWorkflow,\n  async () => {\n    await revealActiveTab()\n    checkOverflow()\n  },\n  { immediate: true }\n)\n\nfunction handleTabResize(event: TransitionEvent) {\n  if (event.propertyName !== 'flex-shrink') return\n  checkOverflow()\n  void revealActiveTab()\n}\n</script>\n","import { showNodeOptions } from '@/composables/graph/useMoreOptionsMenu'\nimport { getCanvasContextMenuTarget } from '@/lib/litegraph/src/canvas/getCanvasContextMenuTarget'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { LGraphCanvas, LiteGraph } from '@/lib/litegraph/src/litegraph'\n\nfunction shouldUseLegacyContextMenu(\n  canvas: LGraphCanvas,\n  node: LGraphNode | undefined\n) {\n  return Boolean(node) || !LiteGraph.vueNodesMode || !canvas.graph\n}\n\n/**\n * Routes Nodes 2.0 group right-clicks to Vue while nodes, reroutes,\n * background, and legacy mode stay on litegraph.\n */\nexport function useGroupContextMenu() {\n  const original = LGraphCanvas.prototype.processContextMenu\n\n  function processContextMenuWithVueGroupMenu(\n    this: LGraphCanvas,\n    ...args: Parameters<typeof original>\n  ): void {\n    const [node, event] = args\n\n    if (shouldUseLegacyContextMenu(this, node)) {\n      original.apply(this, args)\n      return\n    }\n\n    const { reroute, link, group } = getCanvasContextMenuTarget(\n      this,\n      event.canvasX,\n      event.canvasY\n    )\n    if (reroute || link || !group) {\n      original.apply(this, args)\n      return\n    }\n\n    const groupIsOnlySelection =\n      this.selectedItems.size === 1 && this.selectedItems.has(group)\n\n    if (!groupIsOnlySelection && !this.selectOnly) {\n      this.deselectAll()\n      this.select(group, { selectGroupChildren: false })\n      this.onSelectionChange?.(this.selected_nodes)\n      this.setDirty(true)\n    }\n    showNodeOptions(event)\n  }\n\n  LGraphCanvas.prototype.processContextMenu = processContextMenuWithVueGroupMenu\n}\n","/**\n * Moves the missing-media error surface between the interior widget and its\n * host as promotion transfers value ownership.\n */\nimport type {\n  LGraphNode,\n  Subgraph,\n  SubgraphEventMap,\n  SubgraphNode\n} from '@/lib/litegraph/src/litegraph'\n\ninterface PromotionErrorReconcilerHandlers {\n  /** Drops candidates whose widget is no longer the editable value owner. */\n  dropOutOfScope: () => void\n  /** Rescans a host and its interior nodes for missing media. */\n  rescanHost: (subgraphNode: SubgraphNode) => void\n  /** Removes the host-keyed candidate for a widget that is being demoted. */\n  removeHostWidgetCandidate: (\n    subgraphNode: SubgraphNode,\n    widgetName: string\n  ) => void\n}\n\nexport interface PromotionErrorReconciler {\n  /** Subscribes a subgraph host and every definition nested inside it. */\n  attachNode: (node: LGraphNode) => void\n  /** Releases a subgraph host's subscriptions, and its nested ones. */\n  detachNode: (node: LGraphNode) => void\n  /** Subscribes a subgraph definition directly, for hooks installed on one. */\n  attach: (subgraph: Subgraph) => void\n  /** Releases everything still subscribed. */\n  dispose: () => void\n}\n\ninterface Subscription {\n  unsubscribe: () => void\n  hostCount: number\n}\n\nexport function createPromotionErrorReconciler({\n  dropOutOfScope,\n  rescanHost,\n  removeHostWidgetCandidate\n}: PromotionErrorReconcilerHandlers): PromotionErrorReconciler {\n  const subscriptions = new Map<Subgraph, Subscription>()\n  /** Hosts already counted, since onNodeAdded is replayed for existing nodes. */\n  const attachedHosts = new WeakSet<LGraphNode>()\n\n  /** Re-derives both sides once ownership has settled. */\n  const reconcile = (subgraphNode: SubgraphNode) => {\n    queueMicrotask(() => {\n      dropOutOfScope()\n      rescanHost(subgraphNode)\n    })\n  }\n\n  const subscribe = (subgraph: Subgraph): (() => void) => {\n    const onDemoted = (\n      event: CustomEvent<SubgraphEventMap['widget-demoted']>\n    ) => {\n      const { subgraphNode, widget } = event.detail\n      // Fires before the widget leaves the host input, so the scope filter\n      // cannot see it gone yet.\n      removeHostWidgetCandidate(subgraphNode, widget.name)\n      reconcile(subgraphNode)\n    }\n    const onPromoted = (\n      event: CustomEvent<SubgraphEventMap['widget-promoted']>\n    ) => {\n      reconcile(event.detail.subgraphNode)\n    }\n\n    subgraph.events.addEventListener('widget-demoted', onDemoted)\n    subgraph.events.addEventListener('widget-promoted', onPromoted)\n    return () => {\n      subgraph.events.removeEventListener('widget-demoted', onDemoted)\n      subgraph.events.removeEventListener('widget-promoted', onPromoted)\n    }\n  }\n\n  const attach = (subgraph: Subgraph): void => {\n    const existing = subscriptions.get(subgraph)\n    if (existing) {\n      existing.hostCount += 1\n      return\n    }\n\n    subscriptions.set(subgraph, {\n      unsubscribe: subscribe(subgraph),\n      hostCount: 1\n    })\n    for (const node of subgraph.nodes) attachNode(node)\n  }\n\n  const detach = (subgraph: Subgraph): void => {\n    const subscription = subscriptions.get(subgraph)\n    if (!subscription) return\n\n    subscription.hostCount -= 1\n    if (subscription.hostCount > 0) return\n\n    subscription.unsubscribe()\n    subscriptions.delete(subgraph)\n    for (const node of subgraph.nodes) detachNode(node)\n  }\n\n  const attachNode = (node: LGraphNode): void => {\n    if (!node.isSubgraphNode()) return\n    if (attachedHosts.has(node)) return\n    attachedHosts.add(node)\n    attach(node.subgraph)\n  }\n\n  const detachNode = (node: LGraphNode): void => {\n    if (!node.isSubgraphNode()) return\n    if (!attachedHosts.delete(node)) return\n    detach(node.subgraph)\n  }\n\n  const dispose = (): void => {\n    for (const { unsubscribe } of subscriptions.values()) unsubscribe()\n    subscriptions.clear()\n  }\n\n  return { attachNode, detachNode, attach, dispose }\n}\n","/**\n * Installs per-node error-clearing callbacks (onConnectionsChange,\n * onWidgetChanged) on all current and future nodes in a graph.\n *\n * Decoupled from the Vue rendering lifecycle so that error auto-clearing\n * works in legacy canvas mode as well.\n */\nimport { useChainCallback } from '@/composables/functional/useChainCallback'\nimport { resolvePromotedWidgetSource } from '@/core/graph/subgraph/resolvePromotedWidgetSource'\nimport { createPromotionErrorReconciler } from '@/core/graph/subgraph/createPromotionErrorReconciler'\nimport type {\n  NodeBeforeRemovedEvent,\n  NodeLifecycleEvent\n} from '@/lib/litegraph/src/infrastructure/LGraphEventMap'\nimport { LiteGraph, Subgraph } from '@/lib/litegraph/src/litegraph'\nimport type { LGraph, LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport {\n  LGraphEventMode,\n  NodeSlotType\n} from '@/lib/litegraph/src/types/globalEnums'\nimport type { LGraphTriggerEvent } from '@/lib/litegraph/src/types/graphTriggers'\nimport { ChangeTracker } from '@/scripts/changeTracker'\nimport { assetService } from '@/platform/assets/services/assetService'\nimport type { MissingMediaCandidate } from '@/platform/missingMedia/types'\nimport type { MissingModelCandidate } from '@/platform/missingModel/types'\nimport {\n  scanNodeModelCandidates,\n  verifyAssetSupportedCandidates\n} from '@/platform/missingModel/missingModelScan'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport {\n  isMissingMediaCandidateActive,\n  isMissingMediaCandidateScopeActive,\n  scanNodeMediaCandidates,\n  verifyMediaCandidates\n} from '@/platform/missingMedia/missingMediaScan'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport { useMissingNodesErrorStore } from '@/platform/nodeReplacement/missingNodesErrorStore'\nimport { useNodeReplacementStore } from '@/platform/nodeReplacement/nodeReplacementStore'\nimport { getCnrIdFromNode } from '@/platform/nodeReplacement/cnrIdUtil'\nimport { app } from '@/scripts/app'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { toNodeId } from '@/types/nodeId'\nimport type { NodeId } from '@/types/nodeId'\nimport { useModelToNodeStore } from '@/stores/modelToNodeStore'\nimport {\n  collectAllNodes,\n  getExecutionIdByNode,\n  getExecutionIdForNodeInGraph,\n  getNodeByExecutionId,\n  isExecutionPathActive,\n  isMissingCandidateActive\n} from '@/utils/graphTraversalUtil'\nimport { getParentExecutionIds } from '@/types/nodeIdentification'\n\nconst hookedNodes = new WeakSet<LGraphNode>()\n\ntype OriginalCallbacks = {\n  onConnectionsChange: LGraphNode['onConnectionsChange']\n  onWidgetChanged: LGraphNode['onWidgetChanged']\n}\n\nconst originalCallbacks = new WeakMap<LGraphNode, OriginalCallbacks>()\n\nfunction getRemovedNodeExecutionId(graph: LGraph, nodeId: NodeId): string {\n  const rootGraph = app.rootGraphOrUndefined\n  if (!rootGraph) return String(nodeId)\n\n  return (\n    getExecutionIdForNodeInGraph(rootGraph, graph, nodeId) ?? String(nodeId)\n  )\n}\n\nfunction installNodeHooks(node: LGraphNode): void {\n  if (hookedNodes.has(node)) return\n  hookedNodes.add(node)\n\n  originalCallbacks.set(node, {\n    onConnectionsChange: node.onConnectionsChange,\n    onWidgetChanged: node.onWidgetChanged\n  })\n\n  node.onConnectionsChange = useChainCallback(\n    node.onConnectionsChange,\n    function (type, slotIndex: number | undefined, isConnected) {\n      if (type !== NodeSlotType.INPUT || slotIndex === undefined) return\n      const rootGraph = app.rootGraphOrUndefined\n      if (!rootGraph) return\n      const slotName = node.inputs.at(slotIndex)?.name\n      if (!slotName) return\n      const execId = getExecutionIdByNode(rootGraph, node)\n      if (!execId) return\n      if (isConnected) {\n        useExecutionErrorStore().clearSimpleNodeErrors(execId, slotName)\n      }\n      queueMicrotask(() => {\n        if (!app.rootGraphOrUndefined || ChangeTracker.isLoadingGraph) return\n        dropOutOfScopeMissingMedia()\n        if (!isConnected) scanSingleNodeMedia(node)\n      })\n    }\n  )\n\n  node.onWidgetChanged = useChainCallback(\n    node.onWidgetChanged,\n    function (name, newValue, _oldValue, widget) {\n      const rootGraph = app.rootGraphOrUndefined\n      if (!rootGraph) return\n      const hostExecId = getExecutionIdByNode(rootGraph, node)\n      if (!hostExecId) return\n\n      const options = { min: widget.options.min, max: widget.options.max }\n      const source = resolvePromotedWidgetSource(rootGraph, node, widget)\n      if (source?.sourceExecutionId) {\n        useExecutionErrorStore().clearWidgetRelatedErrors(\n          source.sourceExecutionId,\n          source.sourceWidgetName,\n          source.sourceWidgetName,\n          newValue,\n          options\n        )\n      }\n\n      useExecutionErrorStore().clearWidgetRelatedErrors(\n        hostExecId,\n        name,\n        widget.name,\n        newValue,\n        options\n      )\n    }\n  )\n}\n\nfunction restoreNodeHooks(node: LGraphNode): void {\n  const originals = originalCallbacks.get(node)\n  if (!originals) return\n  node.onConnectionsChange = originals.onConnectionsChange\n  node.onWidgetChanged = originals.onWidgetChanged\n  originalCallbacks.delete(node)\n  hookedNodes.delete(node)\n}\n\nfunction installNodeHooksRecursive(node: LGraphNode): void {\n  installNodeHooks(node)\n  if (node.isSubgraphNode()) {\n    for (const innerNode of node.subgraph._nodes) {\n      installNodeHooksRecursive(innerNode)\n    }\n  }\n}\n\nfunction restoreNodeHooksRecursive(node: LGraphNode): void {\n  restoreNodeHooks(node)\n  if (node.isSubgraphNode()) {\n    for (const innerNode of node.subgraph._nodes) {\n      restoreNodeHooksRecursive(innerNode)\n    }\n  }\n}\n\nfunction isNodeInactive(mode: number): boolean {\n  return mode === LGraphEventMode.NEVER || mode === LGraphEventMode.BYPASS\n}\n\nfunction scanNodeErrorTargets(\n  node: LGraphNode,\n  scanNode: (node: LGraphNode) => void\n): void {\n  if (!app.rootGraphOrUndefined) return\n\n  if (node.isSubgraphNode()) {\n    scanNode(node)\n    for (const innerNode of collectAllNodes(node.subgraph)) {\n      if (isNodeInactive(innerNode.mode)) continue\n      scanNode(innerNode)\n    }\n    return\n  }\n\n  scanNode(node)\n}\n\nfunction getActiveExecutionId(node: LGraphNode): string | null {\n  const rootGraph = app.rootGraphOrUndefined\n  if (!rootGraph) return null\n  // Skip when any enclosing subgraph is muted/bypassed. Callers only\n  // verify each node's own mode, so an active node added inside a\n  // bypassed subgraph reaches this point without the ancestor check.\n  // A null execId means the node has no current graph (e.g. detached\n  // mid lifecycle) — also skip, since we cannot verify its scope.\n  const execId = getExecutionIdByNode(rootGraph, node)\n  if (!execId || !isExecutionPathActive(rootGraph, execId)) return null\n  return execId\n}\n\n/** Scan a single node and add confirmed missing model/media to stores.\n *  For subgraph containers, also scans all active interior nodes. */\nfunction scanAndAddNodeErrors(node: LGraphNode): void {\n  scanNodeErrorTargets(node, scanSingleNodeErrors)\n}\n\nfunction scanSingleNodeErrors(node: LGraphNode): void {\n  scanSingleNodeModelsAndTypes(node)\n  scanSingleNodeMedia(node)\n}\n\nfunction scanSingleNodeModelsAndTypes(\n  node: LGraphNode,\n  pendingVerifications?: Promise<void>[],\n  signal?: AbortSignal\n): void {\n  const rootGraph = app.rootGraphOrUndefined\n  if (!rootGraph) return\n  const execId = getActiveExecutionId(node)\n  if (!execId) return\n\n  const modelCandidates = scanNodeModelCandidates(\n    rootGraph,\n    node,\n    assetService.shouldUseWidgetAssetPicker,\n    (nodeType) => useModelToNodeStore().getCategoryForNodeType(nodeType)\n  )\n  const confirmedModels = modelCandidates.filter((c) => c.isMissing === true)\n  if (confirmedModels.length) {\n    useMissingModelStore().addMissingModels(confirmedModels)\n  }\n  // Cloud scans return isMissing: undefined for asset-browser-supported\n  // widgets until async verification resolves. Without this, realtime\n  // add/un-bypass paths would silently drop those candidates.\n  const pendingModels = modelCandidates.filter((c) => c.isMissing === undefined)\n  if (pendingModels.length) {\n    const verification = verifyAndAddPendingModels(pendingModels, signal)\n    if (pendingVerifications) pendingVerifications.push(verification)\n    else void verification\n  }\n\n  if (node.isSubgraphNode()) return\n\n  const originalType = node.last_serialization?.type ?? node.type\n  if (!(originalType in LiteGraph.registered_node_types)) {\n    const nodeReplacementStore = useNodeReplacementStore()\n    const replacement = nodeReplacementStore.getReplacementFor(originalType)\n    const store = useMissingNodesErrorStore()\n    const existing = store.missingNodesError?.nodeTypes ?? []\n    store.surfaceMissingNodes([\n      ...existing,\n      {\n        type: originalType,\n        nodeId: execId,\n        cnrId: getCnrIdFromNode(node),\n        isReplaceable: replacement !== null,\n        replacement: replacement ?? undefined\n      }\n    ])\n  }\n}\n\nfunction scanSingleNodeMedia(\n  node: LGraphNode,\n  pendingVerifications?: Promise<void>[],\n  signal?: AbortSignal\n): void {\n  const rootGraph = app.rootGraphOrUndefined\n  if (!rootGraph) return\n  if (!getActiveExecutionId(node)) return\n\n  const mediaCandidates = scanNodeMediaCandidates(rootGraph, node)\n  const confirmedMedia = mediaCandidates.filter((c) => c.isMissing === true)\n  if (confirmedMedia.length) {\n    useMissingMediaStore().addMissingMedia(confirmedMedia)\n  }\n  // Cloud media scans return pending for asset verification. OSS scans only\n  // return pending for generated output media.\n  const pendingMedia = mediaCandidates.filter((c) => c.isMissing === undefined)\n  if (pendingMedia.length) {\n    const verification = verifyAndAddPendingMedia(pendingMedia, signal)\n    if (pendingVerifications) pendingVerifications.push(verification)\n    else void verification\n  }\n}\n\n/**\n * True when the candidate's node still exists in the current root graph\n * and is active. Filters out late verification results for nodes that\n * have been bypassed, deleted, or belong to a workflow that is no\n * longer current — any of which would reintroduce stale errors.\n */\nfunction isModelCandidateStillMissingAndActive(\n  candidate: MissingModelCandidate\n): boolean {\n  const rootGraph = app.rootGraphOrUndefined\n  if (!isMissingCandidateActive(rootGraph, candidate)) return false\n  if (!rootGraph || candidate.nodeId == null) return true\n\n  const node = getNodeByExecutionId(rootGraph, String(candidate.nodeId))\n  const widget = node?.widgets?.find(\n    (candidateWidget) => candidateWidget.name === candidate.widgetName\n  )\n  if (!node || !widget || widget.value !== candidate.name) return false\n  if (node.getSlotFromWidget(widget)?.link != null) return false\n  if (!node.isSubgraphNode()) return true\n\n  return (\n    resolvePromotedWidgetSource(rootGraph, node, widget)?.sourceExecutionId ===\n    candidate.sourceExecutionId\n  )\n}\n\nfunction hasSameNodeOwner(\n  rootGraph: LGraph,\n  candidate: { nodeId?: string | number | null },\n  ownerAtScan: LGraphNode | null | undefined\n): boolean {\n  return (\n    candidate.nodeId == null ||\n    ownerAtScan === getNodeByExecutionId(rootGraph, String(candidate.nodeId))\n  )\n}\n\nasync function verifyAndAddPendingModels(\n  pending: MissingModelCandidate[],\n  signal?: AbortSignal\n): Promise<void> {\n  // Capture rootGraph at scan time so a late verification for workflow\n  // A cannot leak into workflow B after a switch — execution IDs (esp.\n  // root-level like \"1\") collide across workflows.\n  const rootGraphAtScan = app.rootGraphOrUndefined\n  const ownersAtScan = new Map(\n    pending.map((candidate) => [\n      candidate,\n      candidate.nodeId == null || rootGraphAtScan === undefined\n        ? null\n        : getNodeByExecutionId(rootGraphAtScan, String(candidate.nodeId))\n    ])\n  )\n  try {\n    await verifyAssetSupportedCandidates(pending, signal)\n    if (\n      signal?.aborted ||\n      !rootGraphAtScan ||\n      app.rootGraphOrUndefined !== rootGraphAtScan\n    )\n      return\n    const verified = pending.filter(\n      (candidate) =>\n        hasSameNodeOwner(\n          rootGraphAtScan,\n          candidate,\n          ownersAtScan.get(candidate)\n        ) && isModelCandidateStillMissingAndActive(candidate)\n    )\n    if (verified.length) useMissingModelStore().addMissingModels(verified)\n  } catch (error: unknown) {\n    console.warn('[useErrorClearingHooks] model verification failed:', error)\n  }\n}\n\nasync function verifyAndAddPendingMedia(\n  pending: MissingMediaCandidate[],\n  signal?: AbortSignal\n): Promise<void> {\n  const rootGraphAtScan = app.rootGraphOrUndefined\n  const ownersAtScan = new Map(\n    pending.map((candidate) => [\n      candidate,\n      rootGraphAtScan\n        ? getNodeByExecutionId(rootGraphAtScan, String(candidate.nodeId))\n        : null\n    ])\n  )\n  try {\n    await verifyMediaCandidates(pending, { signal })\n    if (\n      signal?.aborted ||\n      !rootGraphAtScan ||\n      app.rootGraphOrUndefined !== rootGraphAtScan\n    )\n      return\n    const verified = pending.filter(\n      (candidate) =>\n        hasSameNodeOwner(\n          rootGraphAtScan,\n          candidate,\n          ownersAtScan.get(candidate)\n        ) && isMissingMediaCandidateActive(rootGraphAtScan, candidate)\n    )\n    if (verified.length) useMissingMediaStore().addMissingMedia(verified)\n  } catch (error: unknown) {\n    console.warn('[useErrorClearingHooks] media verification failed:', error)\n  }\n}\n\nfunction scanAddedNode(\n  rootGraph: LGraph,\n  node: LGraphNode,\n  scanNode: (node: LGraphNode) => void\n): void {\n  if (app.rootGraphOrUndefined !== rootGraph || ChangeTracker.isLoadingGraph)\n    return\n  if (isNodeInactive(node.mode)) return\n  scanNodeErrorTargets(node, scanNode)\n}\n\nasync function runAddedNodeScan(\n  rootGraph: LGraph,\n  node: LGraphNode,\n  signal: AbortSignal\n): Promise<void> {\n  const pendingVerifications: Promise<void>[] = []\n\n  try {\n    await Promise.resolve()\n    if (signalAborted(signal) || app.rootGraphOrUndefined !== rootGraph) return\n    scanAddedNode(rootGraph, node, (target) =>\n      scanSingleNodeModelsAndTypes(target, pendingVerifications, signal)\n    )\n\n    // Paste/drop handlers need another microtask to mark upload state before\n    // media detection reads the widget value.\n    await Promise.resolve()\n    if (signalAborted(signal) || app.rootGraphOrUndefined !== rootGraph) return\n    scanAddedNode(rootGraph, node, (target) =>\n      scanSingleNodeMedia(target, pendingVerifications, signal)\n    )\n  } finally {\n    await Promise.allSettled(pendingVerifications)\n  }\n}\n\ninterface PendingScanControl {\n  cancel: () => void\n  finish: () => void\n}\n\nfunction signalAborted(signal: AbortSignal): boolean {\n  return signal.aborted\n}\n\nfunction scheduleAddedNodeScan(\n  node: LGraphNode,\n  pendingScans: Map<LGraphNode, Set<PendingScanControl>>\n): void {\n  const rootGraph = app.rootGraphOrUndefined\n  if (!rootGraph || ChangeTracker.isLoadingGraph) return\n  if (isNodeInactive(node.mode)) return\n\n  const executionId = getExecutionIdByNode(rootGraph, node)\n  if (!executionId) return\n\n  const finishPendingScan = useExecutionErrorStore().beginAddedNodeErrorScan(\n    rootGraph,\n    executionId\n  )\n  const abortController = new AbortController()\n  const existingScans = pendingScans.get(node)\n  const scansForNode = existingScans ?? new Set<PendingScanControl>()\n  if (!existingScans) {\n    pendingScans.set(node, scansForNode)\n  }\n\n  function finish() {\n    finishPendingScan()\n    scansForNode.delete(control)\n    if (scansForNode.size === 0) pendingScans.delete(node)\n  }\n\n  function cancel() {\n    abortController.abort()\n    finish()\n  }\n\n  const control = { cancel, finish }\n  scansForNode.add(control)\n  void runAddedNodeScan(rootGraph, node, abortController.signal)\n    .catch((error: unknown) => {\n      console.warn('[useErrorClearingHooks] added-node scan failed:', error)\n    })\n    .finally(finish)\n}\n\nfunction handleNodeModeChange(\n  localGraph: LGraph,\n  nodeId: NodeId,\n  oldMode: number,\n  newMode: number\n): void {\n  const rootGraph = app.rootGraphOrUndefined\n  if (!rootGraph) return\n\n  const wasInactive = isNodeInactive(oldMode)\n  const isNowInactive = isNodeInactive(newMode)\n\n  if (wasInactive === isNowInactive) return\n\n  // Find the node by local ID in the graph that fired the event,\n  // then compute its execution ID relative to the root graph.\n  const node = localGraph.getNodeById(nodeId)\n  if (!node) return\n\n  const execId = getExecutionIdByNode(rootGraph, node)\n  if (!execId) return\n\n  if (isNowInactive) {\n    removeNodeErrors(node, execId)\n    dropOutOfScopeMissingMedia()\n  } else {\n    scanAndAddNodeErrors(node)\n    scanAncestorSubgraphHosts(execId)\n    const executionErrorStore = useExecutionErrorStore()\n    if (executionErrorStore.hasMissingError) {\n      executionErrorStore.showErrorOverlay()\n    }\n  }\n}\n\nfunction scanAncestorSubgraphHosts(execId: string): void {\n  const rootGraph = app.rootGraphOrUndefined\n  if (!rootGraph) return\n  for (const ancestorId of getParentExecutionIds(execId)) {\n    if (!isExecutionPathActive(rootGraph, ancestorId)) continue\n    const ancestor = getNodeByExecutionId(rootGraph, ancestorId)\n    if (ancestor?.isSubgraphNode()) scanSingleNodeErrors(ancestor)\n  }\n}\n\n/** Remove all missing asset errors for a node and, if it's a subgraph\n *  container, for all interior nodes (prefix match on execution ID). */\nfunction removeNodeErrors(node: LGraphNode, execId: string): void {\n  const modelStore = useMissingModelStore()\n  const mediaStore = useMissingMediaStore()\n  const nodesStore = useMissingNodesErrorStore()\n\n  modelStore.removeMissingModelsByNodeId(execId)\n  modelStore.removeMissingModelsBySourceScope(execId)\n  mediaStore.removeMissingMediaByNodeId(execId)\n  nodesStore.removeMissingNodesByNodeId(execId)\n\n  // For subgraph containers, also remove errors from interior nodes.\n  // The trailing colon in the prefix is load-bearing: it prevents sibling\n  // IDs sharing a numeric prefix (e.g. \"705\" vs \"70\") from being matched.\n  if (node.isSubgraphNode()) {\n    const prefix = `${execId}:`\n    modelStore.removeMissingModelsByPrefix(prefix)\n    mediaStore.removeMissingMediaByPrefix(prefix)\n    nodesStore.removeMissingNodesByPrefix(prefix)\n  }\n}\n\n/** Removes candidates whose widget is no longer the editable value owner. */\nfunction dropOutOfScopeMissingMedia(): void {\n  const rootGraph = app.rootGraphOrUndefined\n  if (!rootGraph || ChangeTracker.isLoadingGraph) return\n\n  const mediaStore = useMissingMediaStore()\n  const candidates = mediaStore.missingMediaCandidates\n  if (!candidates) return\n  const inScope = candidates.filter((candidate) =>\n    isMissingMediaCandidateScopeActive(rootGraph, candidate)\n  )\n  if (inScope.length === candidates.length) return\n  mediaStore.setMissingMedia(inScope)\n}\n\nexport function installErrorClearingHooks(graph: LGraph): () => void {\n  const pendingScans = new Map<LGraphNode, Set<PendingScanControl>>()\n  let disposed = false\n  let pendingOutOfScopeDrop = false\n\n  /**\n   * Coalesces `dropOutOfScopeMissingMedia` across a burst of removals, which\n   * would otherwise re-walk every candidate's topology once per removed node.\n   */\n  const scheduleDropOutOfScopeMissingMedia = (): void => {\n    if (pendingOutOfScopeDrop) return\n    pendingOutOfScopeDrop = true\n    queueMicrotask(() => {\n      pendingOutOfScopeDrop = false\n      if (disposed) return\n      dropOutOfScopeMissingMedia()\n    })\n  }\n\n  const promotionErrors = createPromotionErrorReconciler({\n    dropOutOfScope: dropOutOfScopeMissingMedia,\n    rescanHost: (subgraphNode) =>\n      scanNodeErrorTargets(subgraphNode, scanSingleNodeMedia),\n    removeHostWidgetCandidate: (subgraphNode, widgetName) => {\n      const rootGraph = app.rootGraphOrUndefined\n      if (!rootGraph) return\n      const executionId = getExecutionIdByNode(rootGraph, subgraphNode)\n      if (!executionId) return\n      useMissingMediaStore().removeMissingMediaByWidget(executionId, widgetName)\n    }\n  })\n\n  if (graph instanceof Subgraph) promotionErrors.attach(graph)\n  for (const node of graph._nodes) {\n    installNodeHooksRecursive(node)\n    promotionErrors.attachNode(node)\n  }\n\n  const onNodeAdded = ({ detail: { node } }: NodeLifecycleEvent) => {\n    if (disposed) return\n    installNodeHooksRecursive(node)\n    promotionErrors.attachNode(node)\n    scheduleAddedNodeScan(node, pendingScans)\n  }\n\n  // `node:before-removed` covers both single removals and graph.clear();\n  // `node:removed` fires only from LGraph.remove.\n  const onNodeRemoved = ({ detail: { node } }: NodeBeforeRemovedEvent) => {\n    if (disposed) return\n    for (const scan of pendingScans.get(node) ?? []) scan.cancel()\n    // Derive the execution ID from the graph the hook is installed on plus\n    // node.id. For subgraph interior nodes this yields the full\n    // \"parentId:...:nodeId\" path that matches how missing asset errors are\n    // keyed; without this, removal falls back to the local ID and misses\n    // subgraph entries.\n    const execId = getRemovedNodeExecutionId(graph, node.id)\n    removeNodeErrors(node, execId)\n    scheduleDropOutOfScopeMissingMedia()\n    restoreNodeHooksRecursive(node)\n    promotionErrors.detachNode(node)\n  }\n\n  graph.events.addEventListener('node:added', onNodeAdded)\n  graph.events.addEventListener('node:before-removed', onNodeRemoved)\n\n  const originalOnTrigger = graph.onTrigger\n  graph.onTrigger = (event: LGraphTriggerEvent) => {\n    if (disposed) {\n      originalOnTrigger?.(event)\n      return\n    }\n    if (event.type === 'node:property:changed' && event.property === 'mode') {\n      handleNodeModeChange(\n        graph,\n        toNodeId(event.nodeId),\n        event.oldValue as number,\n        event.newValue as number\n      )\n    }\n    originalOnTrigger?.(event)\n  }\n\n  return () => {\n    if (disposed) return\n    disposed = true\n    for (const scans of pendingScans.values()) {\n      for (const scan of scans) scan.finish()\n    }\n    for (const node of graph._nodes) {\n      restoreNodeHooksRecursive(node)\n    }\n    graph.events.removeEventListener('node:added', onNodeAdded)\n    graph.events.removeEventListener('node:before-removed', onNodeRemoved)\n    graph.onTrigger = originalOnTrigger || undefined\n    promotionErrors.dispose()\n  }\n}\n","import { computed, onMounted, watch } from 'vue'\n\nimport { useNodePricing } from '@/composables/node/useNodePricing'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { app } from '@/scripts/app'\nimport { useExtensionStore } from '@/stores/extensionStore'\nimport { installNodeBadges } from '@/systems/badgeSystem'\n\n/**\n * Bootstraps badge derivation: installs it as the legacy canvas's row\n * source and keeps the legacy canvas redrawing when badge sources change.\n */\nexport const useNodeBadge = () => {\n  const settingStore = useSettingStore()\n  const extensionStore = useExtensionStore()\n  const canvasStore = useCanvasStore()\n\n  const showApiPricingBadge = computed(() =>\n    settingStore.get('Comfy.NodeBadge.ShowApiPricing')\n  )\n\n  watch(\n    [\n      () => settingStore.get('Comfy.NodeBadge.NodeSourceBadgeMode'),\n      () => settingStore.get('Comfy.NodeBadge.NodeIdBadgeMode'),\n      () => settingStore.get('Comfy.NodeBadge.NodeLifeCycleBadgeMode'),\n      showApiPricingBadge\n    ],\n    () => {\n      canvasStore.canvas?.setDirty(true, true)\n    }\n  )\n\n  onMounted(() => {\n    if (extensionStore.isExtensionInstalled('Comfy.NodeBadge')) return\n\n    const nodePricing = useNodePricing()\n\n    watch(\n      () => nodePricing.pricingRevision.value,\n      () => {\n        if (!showApiPricingBadge.value) return\n        canvasStore.canvas?.setDirty(true, true)\n      }\n    )\n\n    extensionStore.registerExtension({\n      name: 'Comfy.NodeBadge',\n      init() {\n        installNodeBadges()\n        app.canvas.canvas.addEventListener<'litegraph:set-graph'>(\n          'litegraph:set-graph',\n          () => {\n            canvasStore.canvas?.setDirty(true, true)\n          }\n        )\n      }\n    })\n  })\n}\n","import type { Ref } from 'vue'\n\nimport { useSharedCanvasPositionConversion } from '@/composables/element/useCanvasPositionConversion'\nimport { usePragmaticDroppable } from '@/composables/usePragmaticDragAndDrop'\nimport type { LGraphNode, Point } from '@/lib/litegraph/src/litegraph'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { withNodeAddSource } from '@/platform/telemetry/nodeAdded/nodeAddSource'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\nimport { app as comfyApp } from '@/scripts/app'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport { ComfyModelDef } from '@/stores/modelStore'\nimport type { ModelNodeProvider } from '@/stores/modelToNodeStore'\nimport { useModelToNodeStore } from '@/stores/modelToNodeStore'\nimport { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport type { RenderedTreeExplorerNode } from '@/types/treeExplorerTypes'\nimport { isSelectOnly } from '@/utils/litegraphUtil'\nimport { matchesWidgetName } from '@/utils/widgetBinding'\n\nexport const useCanvasDrop = (dropTargetRef: Ref<HTMLElement | null>) => {\n  const modelToNodeStore = useModelToNodeStore()\n  const litegraphService = useLitegraphService()\n  const workflowService = useWorkflowService()\n\n  usePragmaticDroppable(() => dropTargetRef.value, {\n    getDropEffect: (args): Exclude<DataTransfer['dropEffect'], 'none'> =>\n      args.source.data.type === 'tree-explorer-node' ? 'copy' : 'move',\n    onDrop: async (event) => {\n      if (isSelectOnly(comfyApp.canvas)) return\n      const loc = event.location.current.input\n      const dndData = event.source.data\n\n      if (dndData.type === 'tree-explorer-node') {\n        const node = dndData.data as RenderedTreeExplorerNode\n        const conv = useSharedCanvasPositionConversion()\n        const basePos = conv.clientPosToCanvasPos([loc.clientX, loc.clientY])\n\n        if (node.data instanceof ComfyNodeDefImpl) {\n          const nodeDef = node.data\n          const pos: Point = [...basePos]\n          // Add an offset on y to make sure after adding the node, the cursor\n          // is on the node (top left corner)\n          pos[1] += LiteGraph.NODE_TITLE_HEIGHT\n          withNodeAddSource('sidebar_drag', () =>\n            litegraphService.addNodeOnGraph(nodeDef, { pos })\n          )\n        } else if (node.data instanceof ComfyModelDef) {\n          const model = node.data\n          const pos = basePos\n          const nodeAtPos = comfyApp.canvas.graph?.getNodeOnPos(pos[0], pos[1])\n          let targetProvider: ModelNodeProvider | null = null\n          let targetGraphNode: LGraphNode | null = null\n          if (nodeAtPos) {\n            const providers = modelToNodeStore.getAllNodeProviders(\n              model.directory\n            )\n            for (const provider of providers) {\n              if (provider.nodeDef.name === nodeAtPos.comfyClass) {\n                targetGraphNode = nodeAtPos\n                targetProvider = provider\n              }\n            }\n          }\n          if (!targetGraphNode) {\n            const provider = modelToNodeStore.getNodeProvider(model.directory)\n            if (provider) {\n              targetGraphNode = withNodeAddSource('sidebar_drag', () =>\n                litegraphService.addNodeOnGraph(provider.nodeDef, { pos })\n              )\n              targetProvider = provider\n            }\n          }\n          if (targetGraphNode && targetProvider) {\n            const { key } = targetProvider\n            const widget = targetGraphNode.widgets?.find((widget) =>\n              matchesWidgetName(widget.name, key)\n            )\n            if (widget) {\n              widget.value = model.file_name\n            }\n          }\n        } else if (node.data instanceof ComfyWorkflow) {\n          const workflow = node.data\n          await workflowService.insertWorkflow(workflow, { position: basePos })\n        }\n      }\n    }\n  })\n}\n","import { resolveNodeDefText, st, te } from '@/i18n'\nimport { legacyMenuCompat } from '@/lib/litegraph/src/contextMenuCompat'\nimport type {\n  IContextMenuOptions,\n  IContextMenuValue,\n  INodeInputSlot,\n  IWidget\n} from '@/lib/litegraph/src/litegraph'\nimport { LGraphCanvas, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { app } from '@/scripts/app'\n\nexport function translateContextMenuItems(\n  values: readonly (IContextMenuValue | string | null)[] | undefined,\n  options: IContextMenuOptions\n) {\n  if (!values) return\n  const reInput = /Convert (.*) to input/\n  const reWidget = /Convert (.*) to widget/\n  const cvt = st('contextMenu.Convert ', 'Convert ')\n  const tinp = st('contextMenu. to input', ' to input')\n  const twgt = st('contextMenu. to widget', ' to widget')\n  for (const value of values) {\n    if (typeof value === 'string') continue\n\n    translateContextMenuItems(value?.submenu?.options, options)\n    if (!value?.content) continue\n    if (te(`contextMenu.${value.content}`)) {\n      value.content = st(`contextMenu.${value.content}`, value.content)\n    }\n\n    const extraInfo = (options.extra || options.parentMenu?.options.extra) as\n      | { inputs?: INodeInputSlot[]; widgets?: IWidget[] }\n      | undefined\n    const inputs = extraInfo?.inputs ?? []\n    const widgets = extraInfo?.widgets ?? []\n    const labelFor = (name: string) =>\n      inputs.find((input) => input.name === name)?.label ??\n      widgets.find((widget) => widget.name === name)?.label ??\n      name\n    const matchInput = value.content.match(reInput)\n    if (matchInput) {\n      value.content = cvt + labelFor(matchInput[1]) + tinp\n      continue\n    }\n    const matchWidget = value.content.match(reWidget)\n    if (matchWidget) {\n      value.content = cvt + labelFor(matchWidget[1]) + twgt\n    }\n  }\n}\n\n/**\n * Add translation for litegraph context menu.\n */\nexport const useContextMenuTranslation = () => {\n  // Install compatibility layer BEFORE any extensions load\n  legacyMenuCompat.install(LGraphCanvas.prototype, 'getCanvasMenuOptions')\n\n  const { getCanvasMenuOptions } = LGraphCanvas.prototype\n  const getCanvasCenterMenuOptions = function (\n    this: LGraphCanvas,\n    ...args: Parameters<typeof getCanvasMenuOptions>\n  ) {\n    const res: (IContextMenuValue | null)[] = getCanvasMenuOptions.apply(\n      this,\n      args\n    )\n\n    // Add items from new extension API\n    const newApiItems = app.collectCanvasMenuItems(this)\n    for (const item of newApiItems) {\n      res.push(item)\n    }\n\n    // Add legacy monkey-patched items\n    const legacyItems = legacyMenuCompat.extractLegacyItems(\n      'getCanvasMenuOptions',\n      this,\n      ...args\n    )\n    for (const item of legacyItems) {\n      res.push(item)\n    }\n\n    // Translate all items\n    for (const item of res) {\n      if (item?.content) {\n        item.content = st(`contextMenu.${item.content}`, item.content)\n      }\n    }\n    return res\n  }\n\n  LGraphCanvas.prototype.getCanvasMenuOptions = getCanvasCenterMenuOptions\n\n  legacyMenuCompat.registerWrapper(\n    'getCanvasMenuOptions',\n    getCanvasCenterMenuOptions,\n    getCanvasMenuOptions,\n    LGraphCanvas.prototype\n  )\n\n  // Install compatibility layer for getNodeMenuOptions\n  legacyMenuCompat.install(LGraphCanvas.prototype, 'getNodeMenuOptions')\n\n  // Wrap getNodeMenuOptions to add new API items\n  const nodeMenuFn = LGraphCanvas.prototype.getNodeMenuOptions\n  const getNodeMenuOptionsWithExtensions = function (\n    this: LGraphCanvas,\n    ...args: Parameters<typeof nodeMenuFn>\n  ) {\n    const res = nodeMenuFn.apply(this, args) as (IContextMenuValue | null)[]\n\n    // Add items from new extension API\n    const node = args[0]\n    const newApiItems = app.collectNodeMenuItems(node)\n    for (const item of newApiItems) {\n      res.push(item)\n    }\n\n    // Add legacy monkey-patched items\n    const legacyItems = legacyMenuCompat.extractLegacyItems(\n      'getNodeMenuOptions',\n      this,\n      ...args\n    )\n    for (const item of legacyItems) {\n      res.push(item)\n    }\n\n    return res\n  }\n\n  LGraphCanvas.prototype.getNodeMenuOptions = getNodeMenuOptionsWithExtensions\n\n  legacyMenuCompat.registerWrapper(\n    'getNodeMenuOptions',\n    getNodeMenuOptionsWithExtensions,\n    nodeMenuFn,\n    LGraphCanvas.prototype\n  )\n\n  const OriginalContextMenu = LiteGraph.ContextMenu\n  function ContextMenu(\n    values: (IContextMenuValue | string)[],\n    options: IContextMenuOptions\n  ) {\n    if (options.title) {\n      options.title = resolveNodeDefText('display_name', options.title)\n    }\n    translateContextMenuItems(values, options)\n    const ctx = new OriginalContextMenu(values, options)\n    return ctx\n  }\n\n  LiteGraph.ContextMenu = ContextMenu as unknown as typeof LiteGraph.ContextMenu\n  LiteGraph.ContextMenu.prototype = OriginalContextMenu.prototype\n}\n","import {\n  ContextMenu,\n  DragAndScale,\n  LGraph,\n  LGraphBadge,\n  LGraphCanvas,\n  LGraphGroup,\n  LGraphNode,\n  LLink,\n  LiteGraph\n} from '@/lib/litegraph/src/litegraph'\n\n/**\n * Assign all properties of LiteGraph to window to make it backward compatible.\n */\nexport const useGlobalLitegraph = () => {\n  window.LiteGraph = LiteGraph\n  window.LGraph = LGraph\n  window.LLink = LLink\n  window.LGraphNode = LGraphNode\n  window.LGraphGroup = LGraphGroup\n  window.DragAndScale = DragAndScale\n  window.LGraphCanvas = LGraphCanvas\n  window.ContextMenu = ContextMenu\n  window.LGraphBadge = LGraphBadge\n}\n","import { watch, watchEffect } from 'vue'\n\nimport {\n  CanvasPointer,\n  LGraphNode,\n  LiteGraph\n} from '@/lib/litegraph/src/litegraph'\nimport { useSettingStore } from '@/platform/settings/settingStore'\n// oxlint-disable-next-line comfy/no-restricted-paths\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\n/**\n * Watch for changes in the setting store and update the LiteGraph settings accordingly.\n */\nexport const useLitegraphSettings = () => {\n  const settingStore = useSettingStore()\n  const canvasStore = useCanvasStore()\n\n  watch(\n    [\n      () => settingStore.get('Comfy.Graph.CanvasInfo'),\n      () => canvasStore.canvas,\n      () => canvasStore.isPickingNodes\n    ],\n    ([canvasInfoEnabled, canvas, picking]) => {\n      if (canvas) {\n        canvas.show_info = canvasInfoEnabled && !picking\n        canvas.draw(false, true)\n      }\n    },\n    { immediate: true }\n  )\n\n  watchEffect(() => {\n    const zoomSpeed = settingStore.get('Comfy.Graph.ZoomSpeed')\n    if (canvasStore.canvas) {\n      canvasStore.canvas.zoom_speed = zoomSpeed\n    }\n  })\n\n  watchEffect(() => {\n    const autoPanSpeed = settingStore.get('Comfy.Graph.AutoPanSpeed')\n    if (canvasStore.canvas) {\n      canvasStore.canvas.auto_pan_speed = autoPanSpeed\n    }\n  })\n\n  watchEffect(() => {\n    LiteGraph.snaps_for_comfy = settingStore.get(\n      'Comfy.Node.AutoSnapLinkToSlot'\n    )\n  })\n\n  watchEffect(() => {\n    LiteGraph.snap_highlights_node = settingStore.get(\n      'Comfy.Node.SnapHighlightsNode'\n    )\n  })\n\n  watchEffect(() => {\n    LGraphNode.keepAllLinksOnBypass = settingStore.get(\n      'Comfy.Node.BypassAllLinksOnDelete'\n    )\n  })\n\n  watchEffect(() => {\n    LiteGraph.middle_click_slot_add_default_node = settingStore.get(\n      'Comfy.Node.MiddleClickRerouteNode'\n    )\n  })\n\n  watch(\n    [() => settingStore.get('Comfy.LinkRenderMode'), () => canvasStore.canvas],\n    ([linkRenderMode, canvas]) => {\n      if (canvas) {\n        canvas.links_render_mode = linkRenderMode\n        canvas.setDirty(false, true)\n      }\n    },\n    { immediate: true }\n  )\n\n  watch(\n    [\n      () => settingStore.get('LiteGraph.Canvas.MinFontSizeForLOD'),\n      () => canvasStore.canvas\n    ],\n    ([minFontSizeForLOD, canvas]) => {\n      if (canvas) {\n        canvas.min_font_size_for_lod = minFontSizeForLOD\n        canvas.setDirty(true, true)\n      }\n    },\n    { immediate: true }\n  )\n\n  watch(\n    [\n      () => settingStore.get('Comfy.Graph.LinkMarkers'),\n      () => canvasStore.canvas\n    ],\n    ([linkMarkerShape, canvas]) => {\n      if (canvas) {\n        canvas.linkMarkerShape = linkMarkerShape\n        canvas.setDirty(false, true)\n      }\n    },\n    { immediate: true }\n  )\n\n  watchEffect(() => {\n    const maximumFps = settingStore.get('LiteGraph.Canvas.MaximumFps')\n    const { canvas } = canvasStore\n    if (canvas) canvas.maximumFps = maximumFps\n  })\n\n  watchEffect(() => {\n    const dragZoomEnabled = settingStore.get('Comfy.Graph.CtrlShiftZoom')\n    const { canvas } = canvasStore\n    if (canvas) canvas.dragZoomEnabled = dragZoomEnabled\n  })\n\n  watchEffect(() => {\n    const liveSelection = settingStore.get('Comfy.Graph.LiveSelection')\n    const { canvas } = canvasStore\n    if (canvas) canvas.liveSelection = liveSelection\n  })\n\n  watchEffect(() => {\n    CanvasPointer.doubleClickTime = settingStore.get(\n      'Comfy.Pointer.DoubleClickTime'\n    )\n  })\n\n  watchEffect(() => {\n    CanvasPointer.maxClickDrift = settingStore.get('Comfy.Pointer.ClickDrift')\n  })\n\n  watchEffect(() => {\n    LiteGraph.CANVAS_GRID_SIZE = settingStore.get('Comfy.SnapToGrid.GridSize')\n  })\n\n  watchEffect(() => {\n    LiteGraph.alwaysSnapToGrid = settingStore.get('pysssss.SnapToGrid')\n  })\n\n  watchEffect(() => {\n    LiteGraph.context_menu_scaling = settingStore.get(\n      'LiteGraph.ContextMenu.Scaling'\n    )\n  })\n\n  watchEffect(() => {\n    LiteGraph.Reroute.maxSplineOffset = settingStore.get(\n      'LiteGraph.Reroute.SplineOffset'\n    )\n  })\n\n  watchEffect(() => {\n    const navigationMode = settingStore.get('Comfy.Canvas.NavigationMode') as\n      | 'standard'\n      | 'legacy'\n      | 'custom'\n\n    LiteGraph.canvasNavigationMode = navigationMode\n    LiteGraph.macTrackpadGestures = navigationMode === 'standard'\n  })\n\n  watchEffect(() => {\n    const leftMouseBehavior = settingStore.get(\n      'Comfy.Canvas.LeftMouseClickBehavior'\n    ) as 'panning' | 'select'\n    LiteGraph.leftMouseClickBehavior = leftMouseBehavior\n  })\n\n  watchEffect(() => {\n    const mouseWheelScroll = settingStore.get(\n      'Comfy.Canvas.MouseWheelScroll'\n    ) as 'panning' | 'zoom'\n    LiteGraph.mouseWheelScroll = mouseWheelScroll\n  })\n\n  watchEffect(() => {\n    LiteGraph.saveViewportWithGraph = settingStore.get(\n      'Comfy.EnableWorkflowViewRestore'\n    )\n  })\n  watchEffect(() => {\n    LiteGraph.namedValuesRestore = settingStore.get(\n      'Comfy.Workflow.NamedValuesRestore'\n    )\n  })\n\n  watchEffect(() => {\n    const selectChildren = settingStore.get(\n      'LiteGraph.Group.SelectChildrenOnClick'\n    )\n    if (canvasStore.canvas)\n      canvasStore.canvas.groupSelectChildren = selectChildren\n  })\n}\n","import { LinkMarkerShape, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport {\n  getDefaultLocale,\n  SUPPORTED_LOCALE_OPTIONS\n} from '@/locales/localeConfig'\nimport { isCloud, isDesktop, isNightly } from '@/platform/distribution/types'\nimport { TOUR_SEEN_SETTING } from '@/platform/onboarding/onboardingTours'\nimport { CANVAS_NAVIGATION_PRESETS } from '@/platform/settings/constants/canvasNavigation'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { SettingParams } from '@/platform/settings/types'\nimport type { Keybinding } from '@/platform/keybindings/types'\nimport { NodeBadgeMode } from '@/types/nodeSource'\nimport { LinkReleaseTriggerAction } from '@/types/searchBoxTypes'\nimport { breakpointsTailwind } from '@vueuse/core'\n\n/**\n * Core settings are essential configuration parameters required for ComfyUI's basic functionality.\n * These settings must be present in the settings store and cannot be omitted.\n *\n * IMPORTANT: To prevent ID conflicts, settings should be marked as deprecated rather than removed\n * when they are no longer needed.\n */\nexport const CORE_SETTINGS: SettingParams[] = [\n  {\n    id: 'Comfy.Memory.AllowManualUnload',\n    name: 'Allow manual unload of models and execution cache via user command',\n    type: 'hidden',\n    defaultValue: isCloud ? false : true,\n    versionAdded: '1.18.0'\n  },\n  {\n    id: 'Comfy.Validation.Workflows',\n    name: 'Validate workflows',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.NodeSearchBoxImpl',\n    category: ['Comfy', 'Node Search Box', 'Implementation'],\n    experimental: true,\n    name: 'Node search box implementation',\n    type: 'combo',\n    options: ['default', 'v1 (legacy)', 'litegraph (legacy)'],\n    defaultValue: 'default'\n  },\n  {\n    id: 'Comfy.LinkRelease.Action',\n    category: ['LiteGraph', 'LinkRelease', 'Action'],\n    name: 'Action on link release (No modifier)',\n    type: 'combo',\n    options: Object.values(LinkReleaseTriggerAction),\n    defaultValue: LinkReleaseTriggerAction.CONTEXT_MENU,\n    defaultsByInstallVersion: {\n      '1.24.1': LinkReleaseTriggerAction.SEARCH_BOX\n    }\n  },\n  {\n    id: 'Comfy.LinkRelease.ActionShift',\n    category: ['LiteGraph', 'LinkRelease', 'ActionShift'],\n    name: 'Action on link release (Shift)',\n    type: 'combo',\n    options: Object.values(LinkReleaseTriggerAction),\n    defaultValue: LinkReleaseTriggerAction.SEARCH_BOX,\n    defaultsByInstallVersion: {\n      '1.24.1': LinkReleaseTriggerAction.CONTEXT_MENU\n    }\n  },\n  {\n    id: 'Comfy.NodeSearchBoxImpl.NodePreview',\n    category: ['Comfy', 'Node Search Box', 'NodePreview'],\n    name: 'Node preview',\n    tooltip: 'Only applies to the default implementation',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.NodeSearchBoxImpl.FollowCursor',\n    category: ['Comfy', 'Node Search Box', 'FollowCursor'],\n    name: 'Added nodes follow the cursor',\n    tooltip:\n      'When enabled, nodes added from the search box follow the cursor until clicked to place. Only applies to the default implementation.',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.44.4'\n  },\n  {\n    id: 'Comfy.NodeSearchBoxImpl.ShowCategory',\n    category: ['Comfy', 'Node Search Box', 'ShowCategory'],\n    name: 'Show node category in search results',\n    tooltip: 'Only applies to v1 (legacy)',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.NodeSearchBoxImpl.ShowIdName',\n    category: ['Comfy', 'Node Search Box', 'ShowIdName'],\n    name: 'Show node id name in search results',\n    tooltip: 'Does not apply to litegraph (legacy)',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.NodeSearchBoxImpl.ShowNodeFrequency',\n    category: ['Comfy', 'Node Search Box', 'ShowNodeFrequency'],\n    name: 'Show node frequency in search results',\n    tooltip: 'Only applies to v1 (legacy)',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.Sidebar.Location',\n    category: ['Appearance', 'Sidebar', 'Location'],\n    name: 'Sidebar location',\n    type: 'combo',\n    options: ['left', 'right'],\n    defaultValue: 'left'\n  },\n  {\n    id: 'Comfy.Sidebar.Size',\n    category: ['Appearance', 'Sidebar', 'Size'],\n    name: 'Sidebar size',\n    type: 'combo',\n    options: ['normal', 'small'],\n    // Default to small if the window is less than 1536px(2xl) wide.\n    defaultValue: () => (window.innerWidth < 1536 ? 'small' : 'normal')\n  },\n  {\n    id: 'Comfy.Sidebar.UnifiedWidth',\n    category: ['Appearance', 'Sidebar', 'UnifiedWidth'],\n    name: 'Unified sidebar width',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.18.1'\n  },\n  {\n    id: 'Comfy.Sidebar.Style',\n    category: ['Appearance', 'Sidebar', 'Style'],\n    name: 'Sidebar style',\n    type: 'combo',\n    options: ['floating', 'connected'],\n    defaultValue: 'connected'\n  },\n  {\n    id: 'Comfy.TextareaWidget.FontSize',\n    category: ['Appearance', 'Node Widget', 'TextareaWidget', 'FontSize'],\n    name: 'Textarea widget font size',\n    type: 'slider',\n    defaultValue: 10,\n    attrs: {\n      min: 8,\n      max: 24\n    }\n  },\n  {\n    id: 'Comfy.TextareaWidget.Spellcheck',\n    category: ['Comfy', 'Node Widget', 'TextareaWidget', 'Spellcheck'],\n    name: 'Textarea widget spellcheck',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.Workflow.SortNodeIdOnSave',\n    name: 'Sort node IDs when saving workflow',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.Workflow.NamedValuesRestore',\n    name: 'Restore widget values by name',\n    type: 'boolean',\n    defaultValue: false,\n    experimental: true\n  },\n  {\n    id: 'Comfy.Canvas.NavigationMode',\n    category: ['LiteGraph', 'Canvas Navigation', 'NavigationMode'],\n    name: 'Navigation Mode',\n    defaultValue: 'legacy',\n    type: 'combo',\n    sortOrder: 100,\n    options: [\n      { value: 'standard', text: 'Standard (New)' },\n      { value: 'legacy', text: 'Drag Navigation' },\n      { value: 'custom', text: 'Custom' }\n    ],\n    versionAdded: '1.25.0',\n    defaultsByInstallVersion: {\n      '1.25.0': 'legacy'\n    },\n    onChange: async (val: unknown, old?: unknown) => {\n      if (!old || typeof val !== 'string') return\n      const preset = CANVAS_NAVIGATION_PRESETS[val]\n      if (!preset) return\n\n      await useSettingStore().setMany(preset)\n    }\n  },\n  {\n    id: 'Comfy.Canvas.LeftMouseClickBehavior',\n    category: ['LiteGraph', 'Canvas Navigation', 'LeftMouseClickBehavior'],\n    name: 'Left Mouse Click Behavior',\n    defaultValue: 'panning',\n    type: 'radio',\n    sortOrder: 50,\n    options: [\n      { value: 'panning', text: 'Panning' },\n      { value: 'select', text: 'Select' }\n    ],\n    versionAdded: '1.27.4',\n    onChange: async (val: unknown) => {\n      const newValue = val as string\n      const settingStore = useSettingStore()\n\n      const navigationMode = settingStore.get('Comfy.Canvas.NavigationMode')\n\n      if (navigationMode !== 'custom') {\n        if (\n          (newValue === 'select' && navigationMode === 'standard') ||\n          (newValue === 'panning' && navigationMode === 'legacy')\n        ) {\n          return\n        }\n\n        // only set to custom if it doesn't match the preset modes\n        await settingStore.set('Comfy.Canvas.NavigationMode', 'custom')\n      }\n    }\n  },\n  {\n    id: 'Comfy.Canvas.MouseWheelScroll',\n    category: ['LiteGraph', 'Canvas Navigation', 'MouseWheelScroll'],\n    name: 'Mouse Wheel Scroll',\n    defaultValue: 'zoom',\n    type: 'radio',\n    options: [\n      { value: 'panning', text: 'Panning' },\n      { value: 'zoom', text: 'Zoom in/out' }\n    ],\n    versionAdded: '1.27.4',\n    onChange: async (val: unknown) => {\n      const newValue = val as string\n      const settingStore = useSettingStore()\n\n      const navigationMode = settingStore.get('Comfy.Canvas.NavigationMode')\n\n      if (navigationMode !== 'custom') {\n        if (\n          (newValue === 'panning' && navigationMode === 'standard') ||\n          (newValue === 'zoom' && navigationMode === 'legacy')\n        ) {\n          return\n        }\n\n        // only set to custom if it doesn't match the preset modes\n        await settingStore.set('Comfy.Canvas.NavigationMode', 'custom')\n      }\n    }\n  },\n  {\n    id: 'Comfy.Graph.CanvasInfo',\n    category: ['LiteGraph', 'Canvas', 'CanvasInfo'],\n    name: 'Show canvas info on bottom left corner (fps, etc.)',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.Node.ShowDeprecated',\n    name: 'Show deprecated nodes in search',\n    tooltip:\n      'Deprecated nodes are hidden by default in the UI, but remain functional in existing workflows that use them.',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.Node.ShowExperimental',\n    name: 'Show experimental nodes in search',\n    tooltip:\n      'Experimental nodes are marked as such in the UI and may be subject to significant changes or removal in future versions. Use with caution in production workflows',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.Node.Opacity',\n    category: ['Appearance', 'Node', 'Opacity'],\n    name: 'Node opacity',\n    type: 'slider',\n    defaultValue: 1,\n    attrs: {\n      min: 0.01,\n      max: 1,\n      step: 0.01\n    }\n  },\n  {\n    id: 'Comfy.Workflow.WarnBlueprintOverwrite',\n    name: 'Require confirmation to overwrite an existing subgraph blueprint',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.Desktop.CloudNotificationShown',\n    name: 'Cloud notification shown',\n    type: 'hidden',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.Graph.ZoomSpeed',\n    category: ['LiteGraph', 'Canvas', 'ZoomSpeed'],\n    name: 'Canvas zoom speed',\n    type: 'slider',\n    defaultValue: 1.1,\n    attrs: {\n      min: 1.01,\n      max: 2.5,\n      step: 0.01\n    }\n  },\n  {\n    id: 'Comfy.Graph.AutoPanSpeed',\n    category: ['LiteGraph', 'Canvas', 'AutoPanSpeed'],\n    name: 'Auto-pan speed',\n    tooltip:\n      'Maximum speed when auto-panning by dragging to the canvas edge. Set to 0 to disable auto-panning.',\n    type: 'slider',\n    defaultValue: 15,\n    attrs: {\n      min: 0,\n      max: 30,\n      step: 1\n    }\n  },\n  // Bookmarks are stored in the settings store.\n  {\n    id: 'Comfy.NodeLibrary.NewDesign',\n    category: ['Comfy', 'Node Library', 'NewDesign'],\n    name: 'New Node Library Design',\n    type: 'boolean',\n    tooltip:\n      'Enable the redesigned node library sidebar with tabs (Essential, All, Custom), improved search, and hover previews.',\n    defaultValue: true,\n    experimental: true\n  },\n  // Bookmarks are in format of category/display_name. e.g. \"conditioning/CLIPTextEncode\"\n  {\n    id: 'Comfy.NodeLibrary.Bookmarks',\n    name: 'Node library bookmarks with display name (deprecated)',\n    type: 'hidden',\n    defaultValue: [],\n    deprecated: true\n  },\n  {\n    id: 'Comfy.NodeLibrary.Bookmarks.V2',\n    name: 'Node library bookmarks v2 with unique name',\n    type: 'hidden',\n    defaultValue: []\n  },\n  // Stores mapping from bookmark folder name to its customization.\n  {\n    id: 'Comfy.NodeLibrary.BookmarksCustomization',\n    name: 'Node library bookmarks customization',\n    type: 'hidden',\n    defaultValue: {}\n  },\n  {\n    id: 'Comfy.GroupSelectedNodes.Padding',\n    category: ['LiteGraph', 'Group', 'Padding'],\n    name: 'Group selected nodes padding',\n    type: 'slider',\n    defaultValue: 10,\n    attrs: {\n      min: 0,\n      max: 100\n    }\n  },\n  {\n    id: 'Comfy.Node.DoubleClickTitleToEdit',\n    category: ['LiteGraph', 'Node', 'DoubleClickTitleToEdit'],\n    name: 'Double click node title to edit',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.Node.AllowImageSizeDraw',\n    category: ['LiteGraph', 'Node Widget', 'AllowImageSizeDraw'],\n    name: 'Show width × height below the image preview',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.Group.DoubleClickTitleToEdit',\n    category: ['LiteGraph', 'Group', 'DoubleClickTitleToEdit'],\n    name: 'Double click group title to edit',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.Window.UnloadConfirmation',\n    name: 'Show confirmation when closing window',\n    type: 'boolean',\n    defaultValue: true,\n    versionModified: '1.7.12'\n  },\n  {\n    id: 'Comfy.TreeExplorer.ItemPadding',\n    category: ['Appearance', 'Tree Explorer', 'ItemPadding'],\n    name: 'Tree explorer item padding',\n    type: 'slider',\n    defaultValue: 8,\n    attrs: {\n      min: 0,\n      max: 8,\n      step: 1\n    }\n  },\n  {\n    id: 'Comfy.ModelLibrary.AutoLoadAll',\n    name: 'Automatically load all model folders',\n    tooltip:\n      'If true, all folders will load as soon as you open the model library (this may cause delays while it loads). If false, root level model folders will only load once you click on them.',\n    type: isCloud ? 'hidden' : 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.ModelLibrary.NameFormat',\n    name: 'What name to display in the model library tree view',\n    tooltip:\n      'Select \"filename\" to render a simplified view of the raw filename (without directory or \".safetensors\" extension) in the model list. Select \"title\" to display the configurable model metadata title.',\n    type: 'combo',\n    options: ['filename', 'title'],\n    defaultValue: 'title'\n  },\n  {\n    id: 'Comfy.Locale',\n    name: 'Language',\n    type: 'combo',\n    options: SUPPORTED_LOCALE_OPTIONS,\n    defaultValue: getDefaultLocale\n  },\n  {\n    id: 'Comfy.NodeBadge.NodeSourceBadgeMode',\n    category: ['LiteGraph', 'Node', 'NodeSourceBadgeMode'],\n    name: 'Node source badge mode',\n    type: 'combo',\n    options: Object.values(NodeBadgeMode),\n    defaultValue: NodeBadgeMode.HideBuiltIn\n  },\n  {\n    id: 'Comfy.NodeBadge.NodeIdBadgeMode',\n    category: ['LiteGraph', 'Node', 'NodeIdBadgeMode'],\n    name: 'Node ID badge mode',\n    type: 'combo',\n    options: [NodeBadgeMode.None, NodeBadgeMode.ShowAll],\n    defaultValue: NodeBadgeMode.None\n  },\n  {\n    id: 'Comfy.NodeBadge.NodeLifeCycleBadgeMode',\n    category: ['LiteGraph', 'Node', 'NodeLifeCycleBadgeMode'],\n    name: 'Node life cycle badge mode',\n    type: 'combo',\n    options: [NodeBadgeMode.None, NodeBadgeMode.ShowAll],\n    defaultValue: NodeBadgeMode.ShowAll\n  },\n  {\n    id: 'Comfy.NodeBadge.ShowApiPricing',\n    category: ['Comfy', 'API Nodes'],\n    name: 'Show API node pricing badge',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.20.3'\n  },\n  {\n    id: 'Comfy.Notification.ShowVersionUpdates',\n    category: ['Comfy', 'Notification Preferences'],\n    name: 'Show version updates',\n    tooltip: 'Show updates for new models, and major new features.',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.ConfirmClear',\n    category: ['Comfy', 'Workflow', 'ConfirmClear'],\n    name: 'Require confirmation when clearing workflow',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.PromptFilename',\n    category: ['Comfy', 'Workflow', 'PromptFilename'],\n    name: 'Prompt for filename when saving workflow',\n    type: 'boolean',\n    defaultValue: true\n  },\n  /**\n   * file format for preview\n   *\n   * format;quality\n   *\n   * ex)\n   * webp;50 -> webp, quality 50\n   * jpeg;80 -> rgb, jpeg, quality 80\n   *\n   * @type {string}\n   */\n  {\n    id: 'Comfy.PreviewFormat',\n    category: ['LiteGraph', 'Node Widget', 'PreviewFormat'],\n    name: 'Preview image format',\n    tooltip:\n      'When displaying a preview in the image widget, convert it to a lightweight image, e.g. webp, jpeg, webp;50, etc.',\n    type: 'text',\n    defaultValue: ''\n  },\n  {\n    id: 'Comfy.DisableSliders',\n    category: ['LiteGraph', 'Node Widget', 'DisableSliders'],\n    name: 'Disable node widget sliders',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.DisableFloatRounding',\n    category: ['LiteGraph', 'Node Widget', 'DisableFloatRounding'],\n    name: 'Disable default float widget rounding.',\n    tooltip:\n      '(requires page reload) Cannot disable round when round is set by the node in the backend.',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.FloatRoundingPrecision',\n    category: ['LiteGraph', 'Node Widget', 'FloatRoundingPrecision'],\n    name: 'Float widget rounding decimal places [0 = auto].',\n    tooltip: '(requires page reload)',\n    type: 'slider',\n    attrs: {\n      min: 0,\n      max: 6,\n      step: 1\n    },\n    defaultValue: 0\n  },\n  {\n    id: 'LiteGraph.Node.TooltipDelay',\n    name: 'Tooltip Delay',\n    type: 'number',\n    attrs: {\n      min: 100,\n      max: 3000,\n      step: 50\n    },\n    defaultValue: 500,\n    versionAdded: '1.9.0'\n  },\n  {\n    id: 'Comfy.EnableTooltips',\n    category: ['LiteGraph', 'Node', 'EnableTooltips'],\n    name: 'Enable Tooltips',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.DevMode',\n    name: 'Enable dev mode options (API save, etc.)',\n    type: 'boolean',\n    defaultValue: false,\n    onChange: (value) => {\n      const element = document.getElementById('comfy-dev-save-api-button')\n      if (element) {\n        element.style.display = value ? 'flex' : 'none'\n      }\n    }\n  },\n  {\n    id: 'Comfy.UI.TabBarLayout',\n    category: ['Appearance', 'General'],\n    name: 'Tab Bar Layout',\n    type: 'combo',\n    options: ['Default', 'Legacy'],\n    tooltip: 'Controls the elements contained in the integrated tab bar.',\n    defaultValue: 'Default',\n    migrateDeprecatedValue: (value: unknown) =>\n      value === 'Integrated' ? 'Default' : value\n  },\n  {\n    id: 'Comfy.Appearance.DisableAnimations',\n    category: ['Appearance', 'General'],\n    name: 'Disable animations',\n    type: 'boolean',\n    defaultValue: window.matchMedia('(prefers-reduced-motion: reduce)').matches,\n    tooltip:\n      'Turns off most CSS animations and transitions. Speeds up inference when the display GPU is also used for generation.',\n    onChange: (value: unknown) => {\n      document.body.classList.toggle('disable-animations', !!value)\n    },\n    versionAdded: '1.43.0'\n  },\n  {\n    id: 'Comfy.UseNewMenu',\n    category: ['Comfy', 'Menu', 'UseNewMenu'],\n    defaultValue: 'Top',\n    name: 'Use new menu',\n    type: 'combo',\n    options: ['Disabled', 'Top'],\n    tooltip: 'Enable the redesigned top menu bar.',\n    migrateDeprecatedValue: (val: unknown) => {\n      const value = val as string\n      // Floating is now supported by dragging the docked actionbar off.\n      if (value === 'Floating') {\n        return 'Top'\n      } else if (value === 'Bottom') {\n        return 'Top'\n      }\n      return value\n    }\n  },\n  {\n    id: 'Comfy.Workflow.WorkflowTabsPosition',\n    name: 'Opened workflows position',\n    type: 'combo',\n    options: ['Sidebar', 'Topbar'],\n    defaultValue: 'Topbar',\n    migrateDeprecatedValue: (val: unknown) => {\n      const value = val as string\n      if (value === 'Topbar (2nd-row)') {\n        return 'Topbar'\n      }\n      return value\n    }\n  },\n  {\n    id: 'Comfy.Graph.CanvasMenu',\n    category: ['LiteGraph', 'Canvas', 'CanvasMenu'],\n    name: 'Show graph canvas menu',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.QueueButton.BatchCountLimit',\n    name: 'Batch count limit',\n    tooltip:\n      'The maximum number of tasks added to the queue at one button click',\n    type: 'number',\n    defaultValue: 100,\n    versionAdded: '1.3.5'\n  },\n  {\n    id: 'Comfy.Keybinding.UnsetBindings',\n    name: 'Keybindings unset by the user',\n    type: 'hidden',\n    defaultValue: [] as Keybinding[],\n    versionAdded: '1.3.7',\n    versionModified: '1.7.3',\n    migrateDeprecatedValue: (val: unknown) => {\n      const value = val as (Keybinding & { targetSelector?: string })[]\n      return value.map((keybinding) => {\n        if (keybinding.targetSelector === '#graph-canvas') {\n          keybinding.targetElementId = 'graph-canvas-container'\n        }\n        return keybinding\n      })\n    }\n  },\n  {\n    id: 'Comfy.Keybinding.NewBindings',\n    name: 'Keybindings set by the user',\n    type: 'hidden',\n    defaultValue: [] as Keybinding[],\n    versionAdded: '1.3.7'\n  },\n  {\n    id: 'Comfy.Keybinding.CurrentPreset',\n    name: 'Current keybinding preset name',\n    type: 'hidden',\n    defaultValue: 'default',\n    versionAdded: '1.8.8'\n  },\n  {\n    id: 'Comfy.Extension.Disabled',\n    name: 'Disabled extension names',\n    type: 'hidden',\n    defaultValue: [] as string[],\n    versionAdded: '1.3.11'\n  },\n  {\n    id: 'Comfy.LinkRenderMode',\n    category: ['LiteGraph', 'Graph', 'LinkRenderMode'],\n    name: 'Link Render Mode',\n    tooltip:\n      'Controls the appearance and visibility of connection links between nodes on the canvas.',\n    defaultValue: 2,\n    type: 'combo',\n    options: [\n      { value: LiteGraph.STRAIGHT_LINK, text: 'Straight' },\n      { value: LiteGraph.LINEAR_LINK, text: 'Linear' },\n      { value: LiteGraph.SPLINE_LINK, text: 'Spline' },\n      { value: LiteGraph.HIDDEN_LINK, text: 'Hidden' }\n    ]\n  },\n  {\n    id: 'Comfy.Node.AutoSnapLinkToSlot',\n    category: ['LiteGraph', 'Node', 'AutoSnapLinkToSlot'],\n    name: 'Auto snap link to node slot',\n    tooltip:\n      'When dragging a link over a node, the link automatically snap to a viable input slot on the node',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.3.29'\n  },\n  {\n    id: 'Comfy.Node.SnapHighlightsNode',\n    category: ['LiteGraph', 'Node', 'SnapHighlightsNode'],\n    name: 'Snap highlights node',\n    tooltip:\n      'When dragging a link over a node with viable input slot, highlight the node',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.3.29'\n  },\n  {\n    id: 'Comfy.Node.BypassAllLinksOnDelete',\n    category: ['LiteGraph', 'Node', 'BypassAllLinksOnDelete'],\n    name: 'Keep all links when deleting nodes',\n    tooltip:\n      'When deleting a node, attempt to reconnect all of its input and output links (bypassing the deleted node)',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.3.40'\n  },\n  {\n    id: 'Comfy.Node.MiddleClickRerouteNode',\n    category: ['LiteGraph', 'Node', 'MiddleClickRerouteNode'],\n    name: 'Middle-click creates a new Reroute node',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.3.42'\n  },\n  {\n    id: 'Comfy.Graph.LinkMarkers',\n    category: ['LiteGraph', 'Link', 'LinkMarkers'],\n    name: 'Link midpoint markers',\n    defaultValue: LinkMarkerShape.Circle,\n    type: 'combo',\n    options: [\n      { value: LinkMarkerShape.None, text: 'None' },\n      { value: LinkMarkerShape.Circle, text: 'Circle' },\n      { value: LinkMarkerShape.Arrow, text: 'Arrow' }\n    ],\n    versionAdded: '1.3.42'\n  },\n  {\n    id: 'Comfy.DOMClippingEnabled',\n    category: ['LiteGraph', 'Node', 'DOMClippingEnabled'],\n    name: 'Enable DOM element clipping (enabling may reduce performance)',\n    type: 'boolean',\n    defaultValue: true\n  },\n  {\n    id: 'Comfy.Graph.CtrlShiftZoom',\n    category: ['LiteGraph', 'Canvas', 'CtrlShiftZoom'],\n    name: 'Enable fast-zoom shortcut (Ctrl + Shift + Drag)',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.4.0'\n  },\n  {\n    id: 'Comfy.Graph.LiveSelection',\n    category: ['LiteGraph', 'Canvas', 'LiveSelection'],\n    name: 'Live selection',\n    tooltip:\n      'When enabled, nodes are selected/deselected in real-time as you drag the selection rectangle, similar to other design tools.',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.36.1'\n  },\n  {\n    id: 'Comfy.Pointer.ClickDrift',\n    category: ['LiteGraph', 'Pointer', 'ClickDrift'],\n    name: 'Pointer click drift (maximum distance)',\n    tooltip:\n      'If the pointer moves more than this distance while holding a button down, it is considered dragging (rather than clicking).\\n\\nHelps prevent objects from being unintentionally nudged if the pointer is moved whilst clicking.',\n    experimental: true,\n    type: 'slider',\n    attrs: {\n      min: 0,\n      max: 20,\n      step: 1\n    },\n    defaultValue: 6,\n    versionAdded: '1.4.3'\n  },\n  {\n    id: 'Comfy.Pointer.ClickBufferTime',\n    name: 'Pointer click drift delay (deprecated)',\n    type: 'hidden',\n    deprecated: true,\n    defaultValue: 32,\n    versionAdded: '1.4.3',\n    versionModified: '1.54.3'\n  },\n  {\n    id: 'Comfy.Pointer.DoubleClickTime',\n    category: ['LiteGraph', 'Pointer', 'DoubleClickTime'],\n    name: 'Double click interval (maximum)',\n    tooltip:\n      'The maximum time in milliseconds between the two clicks of a double-click.  Increasing this value may assist if double-clicks are sometimes not registered.',\n    type: 'slider',\n    attrs: {\n      min: 100,\n      max: 1000,\n      step: 50\n    },\n    defaultValue: 300,\n    versionAdded: '1.4.3'\n  },\n  {\n    id: 'Comfy.SnapToGrid.GridSize',\n    category: ['LiteGraph', 'Canvas', 'GridSize'],\n    name: 'Snap to grid size',\n    type: 'slider',\n    attrs: {\n      min: 1,\n      max: 500\n    },\n    tooltip:\n      'When dragging and resizing nodes while holding shift they will be aligned to the grid, this controls the size of that grid.',\n    defaultValue: LiteGraph.CANVAS_GRID_SIZE\n  },\n  // Keep the 'pysssss.SnapToGrid' setting id so we don't need to migrate setting values.\n  // Using a new setting id can cause existing users to lose their existing settings.\n  {\n    id: 'pysssss.SnapToGrid',\n    category: ['LiteGraph', 'Canvas', 'AlwaysSnapToGrid'],\n    name: 'Always snap to grid',\n    tooltip:\n      'When enabled, nodes will automatically align to the grid when moved or resized.',\n    type: 'boolean',\n    defaultValue: false,\n    versionAdded: '1.3.13'\n  },\n  {\n    id: 'Comfy.Server.ServerConfigValues',\n    name: 'Server config values for frontend display',\n    tooltip: 'Server config values used for frontend display only',\n    type: 'hidden',\n    // Mapping from server config id to value.\n    defaultValue: {},\n    versionAdded: '1.4.8'\n  },\n  {\n    id: 'Comfy.Server.LaunchArgs',\n    name: 'Server launch arguments',\n    tooltip:\n      'These are the actual arguments that are passed to the server when it is launched.',\n    type: 'hidden',\n    defaultValue: {},\n    versionAdded: '1.4.8'\n  },\n  {\n    id: 'Comfy.Queue.MaxHistoryItems',\n    name: 'Queue history size',\n    tooltip: 'The maximum number of tasks that show in the queue history.',\n    type: 'slider',\n    attrs: {\n      min: 2,\n      max: 256,\n      step: 2\n    },\n    defaultValue: 64,\n    versionAdded: '1.4.12'\n  },\n  {\n    id: 'Comfy.Queue.History.Expanded',\n    name: 'Queue history expanded',\n    type: 'hidden',\n    defaultValue: false,\n    versionAdded: '1.37.0'\n  },\n  {\n    id: 'Comfy.WorkflowActions.SeenItems',\n    name: 'Seen new workflow action items',\n    type: 'hidden',\n    defaultValue: [] as string[],\n    versionAdded: '1.41.5'\n  },\n  {\n    id: 'Comfy.Execution.PreviewMethod',\n    category: ['Comfy', 'Execution', 'PreviewMethod'],\n    name: 'Live preview method',\n    tooltip:\n      'Live preview method during image generation. \"default\" uses the server CLI setting.',\n    type: 'combo',\n    options: ['default', 'none', 'auto', 'latent2rgb', 'taesd'],\n    defaultValue: 'default',\n    versionAdded: '1.36.0'\n  },\n  {\n    id: 'LiteGraph.Canvas.MaximumFps',\n    name: 'Maximum FPS',\n    tooltip:\n      'The maximum frames per second that the canvas is allowed to render. Caps GPU usage at the cost of smoothness. If 0, the screen refresh rate is used. Default: 0',\n    type: 'slider',\n    attrs: {\n      min: 0,\n      max: 120\n    },\n    defaultValue: 0,\n    versionAdded: '1.5.1'\n  },\n  {\n    id: 'Comfy.EnableWorkflowViewRestore',\n    category: ['Comfy', 'Workflow', 'EnableWorkflowViewRestore'],\n    name: 'Save and restore canvas position and zoom level in workflows',\n    type: 'boolean',\n    defaultValue: true,\n    versionModified: '1.5.4'\n  },\n  {\n    id: 'Comfy.Workflow.ConfirmDelete',\n    name: 'Show confirmation when deleting workflows',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.5.6'\n  },\n  {\n    id: 'Comfy.ColorPalette',\n    name: 'The active color palette id',\n    type: 'hidden',\n    defaultValue: 'dark',\n    versionModified: '1.6.7',\n    telemetry: { trackChanges: true, includeValues: true },\n    migrateDeprecatedValue(val: unknown) {\n      const value = val as string\n      // Legacy custom palettes were prefixed with 'custom_'\n      return value.startsWith('custom_') ? value.replace('custom_', '') : value\n    }\n  },\n  {\n    id: 'Comfy.CustomColorPalettes',\n    name: 'Custom color palettes',\n    type: 'hidden',\n    defaultValue: {},\n    versionModified: '1.6.7'\n  },\n  {\n    id: 'Comfy.WidgetControlMode',\n    category: ['Comfy', 'Node Widget', 'WidgetControlMode'],\n    name: 'Widget control mode',\n    tooltip:\n      'Controls when widget values are updated (randomize/increment/decrement), either before the prompt is queued or after.',\n    type: 'combo',\n    defaultValue: 'after',\n    options: ['before', 'after'],\n    versionModified: '1.6.10'\n  },\n  {\n    id: 'Comfy.TutorialCompleted',\n    name: 'Tutorial completed',\n    type: 'hidden',\n    defaultValue: false,\n    versionAdded: '1.8.7'\n  },\n  {\n    id: TOUR_SEEN_SETTING,\n    name: 'Onboarding coachmark tours the user has already seen',\n    type: 'hidden',\n    defaultValue: [],\n    versionAdded: '1.48.0'\n  },\n  {\n    id: 'Comfy.InstalledVersion',\n    name: 'The frontend version that was running when the user first installed ComfyUI',\n    type: 'hidden',\n    defaultValue: null,\n    versionAdded: '1.24.0'\n  },\n  {\n    id: 'LiteGraph.ContextMenu.Scaling',\n    name: 'Scale node combo widget menus (lists) when zoomed in',\n    defaultValue: false,\n    type: 'boolean',\n    versionAdded: '1.8.8'\n  },\n\n  {\n    id: 'LiteGraph.Canvas.LowQualityRenderingZoomThreshold',\n    type: 'hidden',\n    deprecated: true,\n    name: 'Low quality rendering zoom threshold (deprecated)',\n    tooltip:\n      'Zoom level threshold for performance mode. Lower values (0.1) = quality at all zoom levels. Higher values (1.0) = performance mode even when zoomed in. Performance mode simplifies rendering by hiding text labels, shadows, and details.',\n    attrs: {\n      min: 0.1,\n      max: 1,\n      step: 0.01\n    },\n    defaultValue: 0.6,\n    versionAdded: '1.9.1',\n    versionModified: '1.26.7'\n  },\n  {\n    id: 'LiteGraph.Canvas.MinFontSizeForLOD',\n    name: 'Zoom Node Level of Detail - font size threshold',\n    tooltip:\n      'Controls when the nodes switch to low quality LOD rendering. Uses font size in pixels to determine when to switch. Set to 0 to disable. Values 1-24 set the minimum font size threshold for LOD - higher values (24px) = switch nodes to simplified rendering sooner when zooming out, lower values (1px) = maintain full node quality longer.',\n    type: 'slider',\n    attrs: {\n      min: 0,\n      max: 24,\n      step: 1\n    },\n    defaultValue: 8,\n    versionAdded: '1.26.7',\n    hideInVueNodes: true\n  },\n  {\n    id: 'Comfy.Canvas.SelectionToolbox',\n    category: ['LiteGraph', 'Canvas', 'SelectionToolbox'],\n    name: 'Show selection toolbox',\n    tooltip:\n      'Display a floating toolbar when nodes are selected, providing quick access to common actions.',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.10.5'\n  },\n  {\n    id: 'LiteGraph.Reroute.SplineOffset',\n    name: 'Reroute spline offset',\n    tooltip: 'The bezier control point offset from the reroute centre point',\n    type: 'slider',\n    defaultValue: 20,\n    attrs: {\n      min: 0,\n      max: 400\n    },\n    versionAdded: '1.15.7'\n  },\n  {\n    id: 'Comfy.Toast.DisableReconnectingToast',\n    name: 'Disable toasts when reconnecting or reconnected',\n    type: 'hidden',\n    defaultValue: false,\n    versionAdded: '1.15.12'\n  },\n  {\n    id: 'Comfy.Minimap.Visible',\n    name: 'Display minimap on canvas',\n    type: 'hidden',\n    defaultValue: window.innerWidth >= breakpointsTailwind.lg,\n    versionAdded: '1.25.0'\n  },\n  {\n    id: 'Comfy.Minimap.NodeColors',\n    name: 'Display node with its original color on minimap',\n    type: 'hidden',\n    defaultValue: false,\n    versionAdded: '1.26.0'\n  },\n  {\n    id: 'Comfy.Minimap.ShowLinks',\n    name: 'Display links on minimap',\n    type: 'hidden',\n    defaultValue: true,\n    versionAdded: '1.26.0'\n  },\n  {\n    id: 'Comfy.Minimap.ShowGroups',\n    name: 'Display node groups on minimap',\n    type: 'hidden',\n    defaultValue: true,\n    versionAdded: '1.26.0'\n  },\n  {\n    id: 'Comfy.Minimap.RenderBypassState',\n    name: 'Render bypass state on minimap',\n    type: 'hidden',\n    defaultValue: true,\n    versionAdded: '1.26.0'\n  },\n  {\n    id: 'Comfy.Minimap.RenderErrorState',\n    name: 'Render error state on minimap',\n    type: 'hidden',\n    defaultValue: true,\n    versionAdded: '1.26.0'\n  },\n  {\n    id: 'Comfy.Workflow.AutoSaveDelay',\n    name: 'Auto Save Delay (ms)',\n    defaultValue: 1000,\n    type: 'number',\n    tooltip: 'Only applies if Auto Save is set to \"after delay\".',\n    versionAdded: '1.16.0'\n  },\n  {\n    id: 'Comfy.Workflow.AutoSave',\n    name: 'Auto Save',\n    type: 'combo',\n    options: ['off', 'after delay'], // Room for other options like on focus change, tab change, window change\n    defaultValue: 'off', // Popular request by users (https://github.com/Comfy-Org/ComfyUI_frontend/issues/1584#issuecomment-2536610154)\n    versionAdded: '1.16.0'\n  },\n  {\n    id: 'Comfy.Workflow.Persist',\n    name: 'Persist workflow state and restore on page (re)load',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.16.1'\n  },\n  {\n    id: 'LiteGraph.Node.DefaultPadding',\n    name: 'Always shrink new nodes',\n    tooltip:\n      'Resize nodes to the smallest possible size when created. When disabled, a newly added node will be widened slightly to show widget values.',\n    type: 'boolean',\n    defaultValue: false,\n    versionAdded: '1.18.0'\n  },\n  {\n    id: 'Comfy.Canvas.BackgroundImage',\n    category: ['Appearance', 'Canvas', 'Background'],\n    name: 'Canvas background image',\n    type: 'backgroundImage',\n    tooltip:\n      'Image URL for the canvas background. You can right-click an image in the outputs panel and select \"Set as Background\" to use it, or upload your own image using the upload button.',\n    defaultValue: '',\n    versionAdded: '1.20.4',\n    versionModified: '1.20.5'\n  },\n  // Release data stored in settings\n  {\n    id: 'Comfy.Release.Version',\n    name: 'Last seen release version',\n    type: 'hidden',\n    defaultValue: ''\n  },\n  {\n    id: 'Comfy.Release.Status',\n    name: 'Release status',\n    type: 'hidden',\n    defaultValue: 'skipped'\n  },\n  {\n    id: 'Comfy.Release.Timestamp',\n    name: 'Release seen timestamp',\n    type: 'hidden',\n    defaultValue: 0\n  },\n\n  /**\n   * Template Library Filter Settings\n   */\n  {\n    id: 'Comfy.Templates.SelectedModels',\n    name: 'Template library - Selected model filters',\n    type: 'hidden',\n    defaultValue: []\n  },\n  {\n    id: 'Comfy.Templates.SelectedUseCases',\n    name: 'Template library - Selected use case filters',\n    type: 'hidden',\n    defaultValue: []\n  },\n  {\n    id: 'Comfy.Templates.SelectedRunsOn',\n    name: 'Template library - Selected runs on filters',\n    type: 'hidden',\n    defaultValue: []\n  },\n  {\n    id: 'Comfy.Templates.SortBy',\n    name: 'Template library - Sort preference',\n    type: 'hidden',\n    defaultValue: 'default'\n  },\n\n  /**\n   * Nodes 2.0 Settings\n   */\n  {\n    id: 'Comfy.VueNodes.Enabled',\n    category: ['Comfy', 'Nodes 2.0', 'VueNodesEnabled'],\n    name: 'Modern Node Design (Nodes 2.0)',\n    type: 'boolean',\n    tooltip:\n      'Modern: DOM-based rendering with enhanced interactivity, native browser features, and updated visual design. Classic: Traditional canvas rendering.',\n    defaultValue: false,\n    defaultsByInstallVersion: { '1.41.0': isCloud || isDesktop },\n    sortOrder: 100,\n    experimental: true,\n    versionAdded: '1.27.1'\n  },\n  {\n    id: 'Comfy.AppBuilder.VueNodeSwitchDismissed',\n    name: 'App Builder Vue Node switch dismissed',\n    type: 'hidden',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.PartnerNodesEducation.Dismissed',\n    name: 'Partner nodes education card dismissed',\n    type: 'hidden',\n    defaultValue: false\n  },\n  {\n    id: 'Comfy.ModelLibrary.UseAssetBrowser',\n    name: 'Use the asset browser for the model library',\n    type: 'hidden',\n    tooltip:\n      'When the backend supports assets, the model library opens the asset browser instead of the sidebar tree.',\n    defaultValue: isCloud ? true : false,\n    experimental: true\n  },\n  {\n    id: 'Comfy.VersionCompatibility.DisableWarnings',\n    name: 'Disable version compatibility warnings',\n    type: 'hidden',\n    defaultValue: false,\n    versionAdded: '1.34.1'\n  },\n  {\n    id: 'Comfy.RightSidePanel.IsOpen',\n    name: 'Right side panel open state',\n    type: 'hidden',\n    defaultValue: false,\n    versionAdded: '1.37.0'\n  },\n  {\n    id: 'Comfy.Queue.QPOV2',\n    category: ['Comfy', 'Queue', 'Layout'],\n    name: 'Docked job history/queue panel',\n    type: 'boolean',\n    tooltip:\n      'Replaces the floating job queue panel with an equivalent job queue embedded in the job history side panel. You can disable this to return to the floating panel layout.',\n    defaultValue: isNightly,\n    experimental: true\n  },\n  {\n    id: 'Comfy.Queue.ShowRunProgressBar',\n    name: 'Show run progress bar',\n    type: 'hidden',\n    defaultValue: true,\n    versionAdded: '1.41.3'\n  },\n  {\n    id: 'Comfy.Node.AlwaysShowAdvancedWidgets',\n    category: ['LiteGraph', 'Node Widget', 'AlwaysShowAdvancedWidgets'],\n    name: 'Always show advanced widgets on all nodes',\n    tooltip:\n      'When enabled, advanced widgets are always visible on all nodes without needing to expand them individually.',\n    type: 'boolean',\n    defaultValue: false,\n    versionAdded: '1.39.0'\n  },\n  {\n    id: 'Comfy.NodeReplacement.Enabled',\n    category: ['Comfy', 'Workflow', 'NodeReplacement'],\n    name: 'Enable node replacement suggestions',\n    tooltip:\n      'When enabled, missing nodes with known replacements will be shown as replaceable in the missing nodes dialog, allowing you to review and apply replacements.',\n    type: 'boolean',\n    defaultValue: true,\n    experimental: false,\n    versionAdded: '1.40.0',\n    versionModified: '1.44.5'\n  },\n  {\n    id: 'Comfy.Graph.DeduplicateSubgraphNodeIds',\n    category: ['Comfy', 'Graph', 'Subgraph'],\n    name: 'Deduplicate subgraph node IDs',\n    tooltip:\n      'Automatically reassign duplicate node IDs in subgraphs when loading a workflow.',\n    type: 'boolean',\n    deprecated: true,\n    defaultValue: true,\n    experimental: true,\n    versionAdded: '1.40.0'\n  },\n  {\n    id: 'Comfy.RightSidePanel.ShowErrorsTab',\n    category: ['Comfy', 'Error System', 'IssuesTab'],\n    name: 'Show issues tab in side panel',\n    tooltip:\n      'When enabled, the Issues tab is displayed in the right side panel to show blocking errors and missing resources that need setup.',\n    type: 'boolean',\n    defaultValue: true,\n    experimental: true,\n    versionAdded: '1.40.0'\n  },\n  {\n    id: 'Comfy.Workflow.ShowMissingNodesWarning',\n    category: ['Comfy', 'Error System', 'MissingNodes'],\n    sortOrder: -1,\n    name: 'Show missing nodes in the issues tab',\n    tooltip:\n      'When disabled, missing node packs are not listed in the issues tab and their nodes are not highlighted. The workflow still cannot run until they are installed.',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.55.0'\n  },\n  {\n    id: 'Comfy.ErrorSystem.ShowMissingModels',\n    category: ['Comfy', 'Error System', 'MissingModels'],\n    sortOrder: -2,\n    name: 'Show missing models in the issues tab',\n    tooltip:\n      'When disabled, model files that are not found are not listed in the issues tab and their nodes are not highlighted.',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.55.0'\n  },\n  {\n    id: 'Comfy.Workflow.ShowMissingMediaWarning',\n    category: ['Comfy', 'Error System', 'MissingMedia'],\n    sortOrder: -3,\n    name: 'Show missing media in the issues tab',\n    tooltip:\n      'When disabled, input images, videos and audio that are not found are not listed in the issues tab and their nodes are not highlighted.',\n    type: 'boolean',\n    defaultValue: true,\n    versionAdded: '1.55.0'\n  },\n  {\n    id: 'LiteGraph.Group.SelectChildrenOnClick',\n    category: ['LiteGraph', 'Group', 'SelectChildrenOnClick'],\n    name: 'Select group children on click',\n    tooltip:\n      'When enabled, clicking a group selects all nodes and items inside it',\n    type: 'boolean',\n    defaultValue: false,\n    versionAdded: '1.42.0'\n  }\n]\n","import { computed, onUnmounted, watch } from 'vue'\n\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { api } from '@/scripts/api'\n\nexport function useWorkflowAutoSave() {\n  const workflowStore = useWorkflowStore()\n  const settingStore = useSettingStore()\n  const workflowService = useWorkflowService()\n\n  // Use computed refs to cache autosave settings\n  const autoSaveSetting = computed(() =>\n    settingStore.get('Comfy.Workflow.AutoSave')\n  )\n  const autoSaveDelay = computed(() =>\n    settingStore.get('Comfy.Workflow.AutoSaveDelay')\n  )\n\n  let autoSaveTimeout: NodeJS.Timeout | null = null\n  let isSaving = false\n  let needsAutoSave = false\n\n  const scheduleAutoSave = () => {\n    // Clear any existing timeout\n    if (autoSaveTimeout) {\n      clearTimeout(autoSaveTimeout)\n      autoSaveTimeout = null\n    }\n\n    // If autosave is enabled\n    if (autoSaveSetting.value === 'after delay') {\n      // If a save is in progress, mark that we need an autosave after saving\n      if (isSaving) {\n        needsAutoSave = true\n        return\n      }\n      const delay = autoSaveDelay.value\n      autoSaveTimeout = setTimeout(async () => {\n        const activeWorkflow = workflowStore.activeWorkflow\n        if (activeWorkflow?.isModified && activeWorkflow.isPersisted) {\n          try {\n            isSaving = true\n            await workflowService.saveWorkflow(activeWorkflow)\n          } catch (err) {\n            console.error('Auto save failed:', err)\n          } finally {\n            isSaving = false\n            if (needsAutoSave) {\n              needsAutoSave = false\n              scheduleAutoSave()\n            }\n          }\n        }\n      }, delay)\n    }\n  }\n\n  // Watch for autosave setting changes\n  watch(\n    autoSaveSetting,\n    (newSetting) => {\n      // Clear any existing timeout when settings change\n      if (autoSaveTimeout) {\n        clearTimeout(autoSaveTimeout)\n        autoSaveTimeout = null\n      }\n\n      // If there's an active modified workflow and autosave is enabled, schedule a save\n      if (\n        newSetting === 'after delay' &&\n        workflowStore.activeWorkflow?.isModified\n      ) {\n        scheduleAutoSave()\n      }\n    },\n    { immediate: true }\n  )\n\n  // Listen for graph changes and schedule autosave when they occur\n  const onGraphChanged = () => {\n    scheduleAutoSave()\n  }\n\n  api.addEventListener('graphChanged', onGraphChanged)\n\n  onUnmounted(() => {\n    if (autoSaveTimeout) {\n      clearTimeout(autoSaveTimeout)\n      autoSaveTimeout = null\n    }\n    api.removeEventListener('graphChanged', onGraphChanged)\n  })\n}\n","/**\n * Tab State Management - Per-tab workflow pointers in sessionStorage.\n *\n * Uses api.clientId to scope pointers per browser tab.\n * Includes workspaceId for validation to prevent cross-workspace contamination.\n */\n\nimport type { ActivePathPointer, OpenPathsPointer } from '../base/draftTypes'\nimport { getWorkspaceId } from '../base/storageKeys'\nimport {\n  clearActivePath,\n  readActivePath,\n  readOpenPaths,\n  writeActivePath,\n  writeOpenPaths\n} from '../base/storageIO'\nimport { api } from '@/scripts/api'\n\n/**\n * Gets the current client ID for browser tab identification.\n * Falls back to initialClientId if clientId is not yet set.\n */\nfunction getClientId(): string | null {\n  return api.clientId ?? api.initialClientId ?? null\n}\n\n/**\n * Composable for managing per-tab workflow state in sessionStorage.\n */\nexport function useWorkflowTabState() {\n  /**\n   * Gets the active workflow path for the current tab.\n   * Returns null if no pointer exists or workspaceId doesn't match.\n   */\n  function getActivePath(): string | null {\n    const clientId = getClientId()\n    const workspaceId = getWorkspaceId()\n    if (!clientId) return null\n\n    const pointer = readActivePath(clientId, workspaceId)\n    return pointer?.path ?? null\n  }\n\n  /**\n   * Sets the active workflow path for the current tab.\n   */\n  function setActivePath(path: string): void {\n    const clientId = getClientId()\n    const workspaceId = getWorkspaceId()\n    if (!clientId) return\n\n    const pointer: ActivePathPointer = {\n      workspaceId,\n      path\n    }\n    writeActivePath(clientId, pointer)\n  }\n\n  /** Forgets the active workflow, so nothing is restored on the next boot. */\n  function clearActivePathPointer(): void {\n    const clientId = getClientId()\n    if (!clientId) return\n\n    clearActivePath(clientId, getWorkspaceId())\n  }\n\n  /**\n   * Gets the open workflow paths for the current tab.\n   * Returns null if no pointer exists or workspaceId doesn't match.\n   */\n  function getOpenPaths(): { paths: string[]; activeIndex: number } | null {\n    const clientId = getClientId()\n    const workspaceId = getWorkspaceId()\n    if (!clientId) return null\n\n    const pointer = readOpenPaths(clientId, workspaceId)\n    if (!pointer) return null\n\n    return { paths: pointer.paths, activeIndex: pointer.activeIndex }\n  }\n\n  /**\n   * Sets the open workflow paths for the current tab.\n   */\n  function setOpenPaths(paths: string[], activeIndex: number): void {\n    const clientId = getClientId()\n    const workspaceId = getWorkspaceId()\n    if (!clientId) return\n\n    const pointer: OpenPathsPointer = {\n      workspaceId,\n      paths,\n      activeIndex\n    }\n    writeOpenPaths(clientId, pointer)\n  }\n\n  return {\n    getActivePath,\n    setActivePath,\n    clearActivePathPointer,\n    getOpenPaths,\n    setOpenPaths\n  }\n}\n","<template>\n  <div\n    data-testid=\"open-shared-workflow-dialog\"\n    class=\"flex w-176 max-w-full flex-col overflow-hidden rounded-2xl border border-border-default bg-base-background shadow-lg\"\n    :aria-busy=\"isOpening\"\n  >\n    <header\n      class=\"flex h-12 items-center justify-between gap-2 border-b border-border-default px-4\"\n    >\n      <h2\n        data-testid=\"open-shared-workflow-title\"\n        class=\"text-sm text-base-foreground\"\n      >\n        {{ $t('openSharedWorkflow.dialogTitle') }}\n      </h2>\n      <Button\n        data-testid=\"open-shared-workflow-close\"\n        size=\"icon\"\n        :aria-label=\"$t('g.close')\"\n        @click=\"onCancel\"\n      >\n        <i class=\"icon-[lucide--x] size-4\" />\n      </Button>\n    </header>\n\n    <template v-if=\"isLoading\">\n      <main class=\"flex gap-8 px-8 pt-4 pb-6\">\n        <div role=\"status\" class=\"flex min-w-0 flex-1 flex-col gap-12 py-4\">\n          <Skeleton class=\"h-8 w-3/5\" />\n          <Skeleton class=\"h-4 w-4/5\" />\n        </div>\n        <div class=\"flex w-84 shrink-0 flex-col gap-2 py-4\">\n          <Skeleton class=\"h-4 w-full\" />\n          <Skeleton class=\"h-20 w-full rounded-lg\" />\n        </div>\n      </main>\n      <footer\n        class=\"flex items-center justify-end gap-2.5 border-t border-border-default px-8 py-4\"\n      >\n        <Skeleton class=\"h-10 w-24 rounded-md\" />\n        <Skeleton class=\"h-10 w-40 rounded-md\" />\n      </footer>\n    </template>\n\n    <template v-else-if=\"error\">\n      <main class=\"flex flex-col items-center gap-4 p-8\">\n        <i\n          class=\"icon-[lucide--circle-alert] size-8 text-warning-background\"\n          aria-hidden=\"true\"\n        />\n        <p class=\"m-0 text-center text-sm text-muted-foreground\">\n          {{ $t('openSharedWorkflow.loadError') }}\n        </p>\n      </main>\n      <footer\n        class=\"flex items-center justify-end gap-2.5 border-t border-border-default px-8 py-4\"\n      >\n        <Button\n          data-testid=\"open-shared-workflow-error-close\"\n          variant=\"secondary\"\n          size=\"lg\"\n          @click=\"onCancel\"\n        >\n          {{ $t('g.close') }}\n        </Button>\n      </footer>\n    </template>\n\n    <template v-else-if=\"sharedWorkflow\">\n      <main :class=\"cn('flex gap-8 px-8 pt-4 pb-6', !hasAssets && 'flex-col')\">\n        <div class=\"flex min-w-0 flex-1 flex-col gap-12 py-4\">\n          <h2\n            class=\"m-0 text-2xl font-semibold wrap-anywhere text-base-foreground\"\n          >\n            {{ workflowName }}\n          </h2>\n          <p\n            role=\"status\"\n            aria-live=\"polite\"\n            class=\"m-0 flex items-center gap-2 text-sm text-muted-foreground\"\n          >\n            <i\n              v-if=\"isOpening\"\n              class=\"icon-[lucide--loader-circle] size-4 motion-safe:animate-spin\"\n              aria-hidden=\"true\"\n            />\n            <span>\n              {{\n                isOpening\n                  ? $t('openSharedWorkflow.opening')\n                  : $t('openSharedWorkflow.copyDescription')\n              }}\n            </span>\n          </p>\n        </div>\n\n        <div v-if=\"hasAssets\" class=\"flex w-96 shrink-0 flex-col gap-2 py-4\">\n          <CollapsibleRoot\n            v-model:open=\"isWarningExpanded\"\n            class=\"overflow-hidden rounded-lg bg-secondary-background\"\n          >\n            <CollapsibleTrigger as-child>\n              <Button\n                variant=\"secondary\"\n                class=\"w-full justify-between px-4 py-1 text-sm\"\n              >\n                <i\n                  class=\"icon-[lucide--circle-alert] size-4 shrink-0 text-warning-background\"\n                  aria-hidden=\"true\"\n                />\n                <span\n                  class=\"m-0 flex-1 text-left text-sm text-muted-foreground\"\n                >\n                  {{ $t('openSharedWorkflow.nonPublicAssetsWarningLine1') }}\n                </span>\n                <i\n                  :class=\"\n                    cn(\n                      'icon-[lucide--chevron-right] size-4 shrink-0 text-muted-foreground transition-transform',\n                      isWarningExpanded && 'rotate-90'\n                    )\n                  \"\n                />\n              </Button>\n            </CollapsibleTrigger>\n\n            <CollapsibleContent\n              class=\"overflow-hidden data-[state=closed]:animate-collapsible-up data-[state=open]:animate-collapsible-down\"\n            >\n              <AssetSectionList :items=\"nonOwnedAssets\" />\n            </CollapsibleContent>\n          </CollapsibleRoot>\n        </div>\n      </main>\n\n      <footer\n        class=\"flex items-center justify-end gap-2.5 border-t border-border-default px-8 py-4\"\n      >\n        <Button\n          data-testid=\"open-shared-workflow-cancel\"\n          variant=\"secondary\"\n          size=\"lg\"\n          :disabled=\"isOpening\"\n          @click=\"onCancel\"\n        >\n          {{ $t('g.cancel') }}\n        </Button>\n        <Button\n          v-if=\"hasAssets\"\n          data-testid=\"open-shared-workflow-open-without-importing\"\n          variant=\"secondary\"\n          size=\"lg\"\n          :loading=\"openingAction === 'open-only'\"\n          :disabled=\"isOpening\"\n          @click=\"onOpenWithoutImporting(sharedWorkflow)\"\n        >\n          {{ $t('openSharedWorkflow.openWithoutImporting') }}\n        </Button>\n        <Button\n          data-testid=\"open-shared-workflow-confirm\"\n          variant=\"primary\"\n          size=\"lg\"\n          :loading=\"openingAction === 'copy-and-open'\"\n          :disabled=\"isOpening\"\n          @click=\"onConfirm(sharedWorkflow)\"\n        >\n          {{\n            hasAssets\n              ? $t('openSharedWorkflow.copyAssetsAndOpen')\n              : $t('openSharedWorkflow.openWorkflow')\n          }}\n        </Button>\n      </footer>\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useAsyncState } from '@vueuse/core'\nimport {\n  CollapsibleContent,\n  CollapsibleRoot,\n  CollapsibleTrigger\n} from 'reka-ui'\nimport { computed, ref } from 'vue'\n\nimport type { SharedWorkflowPayload } from '@/platform/workflow/sharing/types/shareTypes'\nimport AssetSectionList from '@/platform/workflow/sharing/components/AssetSectionList.vue'\nimport { useWorkflowShareService } from '@/platform/workflow/sharing/services/workflowShareService'\nimport Button from '@/components/ui/button/Button.vue'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ntype OpeningAction = 'copy-and-open' | 'open-only'\n\nconst {\n  shareId,\n  openingAction = null,\n  onConfirm,\n  onOpenWithoutImporting,\n  onCancel\n} = defineProps<{\n  shareId: string\n  openingAction?: OpeningAction | null\n  onConfirm: (payload: SharedWorkflowPayload) => void\n  onOpenWithoutImporting: (payload: SharedWorkflowPayload) => void\n  onCancel: () => void\n}>()\n\nconst workflowShareService = useWorkflowShareService()\nconst isWarningExpanded = ref(true)\n\nconst {\n  state: sharedWorkflow,\n  isLoading,\n  error\n} = useAsyncState(() => workflowShareService.getSharedWorkflow(shareId), null)\n\nconst nonOwnedAssets = computed(\n  () => sharedWorkflow.value?.assets.filter((a) => !a.in_library) ?? []\n)\n\nconst hasAssets = computed(() => nonOwnedAssets.value.length > 0)\nconst isOpening = computed(() => openingAction !== null)\n\nconst workflowName = computed(() => {\n  if (!sharedWorkflow.value) return ''\n  if (sharedWorkflow.value.name) return sharedWorkflow.value.name\n  const jsonName = (\n    sharedWorkflow.value.workflowJson as Record<string, unknown>\n  ).name\n  if (typeof jsonName === 'string' && jsonName) return jsonName\n  return ''\n})\n</script>\n","import { useToast } from '@/components/ui/toast/toastStore'\nimport { useI18n } from 'vue-i18n'\nimport { useRoute, useRouter } from 'vue-router'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useWorkflowTemplateSelectorDialog } from '@/composables/useWorkflowTemplateSelectorDialog'\nimport { useTelemetry } from '@/platform/telemetry'\nimport OpenSharedWorkflowDialogContent from '@/platform/workflow/sharing/components/OpenSharedWorkflowDialogContent.vue'\nimport type { SharedWorkflowPayload } from '@/platform/workflow/sharing/types/shareTypes'\nimport {\n  clearPreservedQuery,\n  hydratePreservedQuery,\n  mergePreservedQueryIntoQuery\n} from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport { useWorkflowShareService } from '@/platform/workflow/sharing/services/workflowShareService'\nimport { isValidShareId } from '@/platform/workflow/sharing/utils/shareAuthAttribution'\nimport { app } from '@/scripts/app'\nimport { useDialogService } from '@/services/dialogService'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nexport type SharedWorkflowUrlLoadStatus =\n  | 'not-present'\n  | 'loaded'\n  | 'loaded-without-assets'\n  | 'cancelled'\n  | 'failed'\n\ntype DialogResult =\n  | { action: 'copy-and-open'; payload: SharedWorkflowPayload }\n  | { action: 'open-only'; payload: SharedWorkflowPayload }\n  | { action: 'cancel' }\n\ntype OpeningAction = Exclude<DialogResult['action'], 'cancel'>\n\nconst OPEN_SHARED_WORKFLOW_DIALOG_KEY = 'open-shared-workflow'\n\nexport function useSharedWorkflowUrlLoader() {\n  const route = useRoute()\n  const router = useRouter()\n  const toast = useToast()\n  const { t } = useI18n()\n  const workflowShareService = useWorkflowShareService()\n  const dialogService = useDialogService()\n  const dialogStore = useDialogStore()\n  const templateSelectorDialog = useWorkflowTemplateSelectorDialog()\n  const { isLoggedIn } = useCurrentUser()\n  const { mode, isAppMode } = useAppMode()\n  const SHARE_NAMESPACE = PRESERVED_QUERY_NAMESPACES.SHARE\n\n  async function ensureShareQueryFromIntent() {\n    hydratePreservedQuery(SHARE_NAMESPACE)\n    const mergedQuery = mergePreservedQueryIntoQuery(\n      SHARE_NAMESPACE,\n      route.query\n    )\n\n    if (mergedQuery) {\n      await router.replace({ query: mergedQuery })\n    }\n\n    return mergedQuery ?? route.query\n  }\n\n  function cleanupUrlParams() {\n    const newQuery = { ...route.query }\n    delete newQuery.share\n    void router.replace({ query: newQuery })\n  }\n\n  function clearShareIntent() {\n    cleanupUrlParams()\n    clearPreservedQuery(SHARE_NAMESPACE)\n  }\n\n  function showOpenSharedWorkflowDialog(\n    shareId: string\n  ): Promise<DialogResult> {\n    function setOpeningAction(openingAction: OpeningAction) {\n      dialogStore.updateDialog({\n        key: OPEN_SHARED_WORKFLOW_DIALOG_KEY,\n        contentProps: { openingAction }\n      })\n    }\n\n    return new Promise<DialogResult>((resolve) => {\n      dialogService.showLayoutDialog({\n        key: OPEN_SHARED_WORKFLOW_DIALOG_KEY,\n        component: OpenSharedWorkflowDialogContent,\n        props: {\n          shareId,\n          openingAction: null,\n          onConfirm: (payload: SharedWorkflowPayload) => {\n            setOpeningAction('copy-and-open')\n            resolve({ action: 'copy-and-open', payload })\n          },\n          onOpenWithoutImporting: (payload: SharedWorkflowPayload) => {\n            setOpeningAction('open-only')\n            resolve({ action: 'open-only', payload })\n          },\n          onCancel: () => {\n            resolve({ action: 'cancel' })\n            dialogStore.closeDialog({ key: OPEN_SHARED_WORKFLOW_DIALOG_KEY })\n          }\n        },\n        dialogComponentProps: {\n          onClose: () => resolve({ action: 'cancel' })\n        }\n      })\n    })\n  }\n\n  async function loadSharedWorkflowFromUrl(): Promise<SharedWorkflowUrlLoadStatus> {\n    const query = await ensureShareQueryFromIntent()\n    const shareParam = query.share\n\n    if (shareParam == null) {\n      return 'not-present'\n    }\n\n    if (typeof shareParam !== 'string') {\n      clearShareIntent()\n      return 'not-present'\n    }\n\n    if (!isValidShareId(shareParam)) {\n      console.warn(\n        `[useSharedWorkflowUrlLoader] Invalid share parameter format: ${shareParam}`\n      )\n      toast.error(t('g.error'), { description: t('shareWorkflow.loadFailed') })\n      clearShareIntent()\n      return 'failed'\n    }\n\n    useTelemetry()?.trackShareLinkOpened({\n      share_id: shareParam,\n      is_authenticated: isLoggedIn.value,\n      view_mode: mode.value,\n      is_app_mode: isAppMode.value\n    })\n\n    const result = await showOpenSharedWorkflowDialog(shareParam)\n\n    if (result.action === 'cancel') {\n      clearPreservedQuery(PRESERVED_QUERY_NAMESPACES.SHARE_AUTH)\n      clearShareIntent()\n      return 'cancelled'\n    }\n\n    templateSelectorDialog.hide()\n\n    try {\n      const { payload } = result\n      const workflowName = payload.name || t('openSharedWorkflow.dialogTitle')\n      const nonOwnedAssets = payload.assets.filter((a) => !a.in_library)\n      let importFailed = false\n\n      if (result.action === 'copy-and-open' && nonOwnedAssets.length > 0) {\n        try {\n          await workflowShareService.importPublishedAssets(\n            nonOwnedAssets.map((a) => a.id),\n            payload.shareId\n          )\n        } catch (importError) {\n          importFailed = true\n          console.error(\n            '[useSharedWorkflowUrlLoader] Failed to import assets:',\n            importError\n          )\n          toast.error(t('g.error'), {\n            description: t('openSharedWorkflow.importFailed')\n          })\n        }\n      }\n\n      try {\n        await app.loadGraphData(\n          payload.workflowJson,\n          true,\n          true,\n          workflowName,\n          {\n            openSource: 'shared_url',\n            shareId: payload.shareId\n          }\n        )\n      } catch (error) {\n        console.error(\n          '[useSharedWorkflowUrlLoader] Failed to load workflow graph:',\n          error\n        )\n        toast.error(t('g.error'), {\n          description: t('shareWorkflow.loadFailed')\n        })\n        clearShareIntent()\n        return 'failed'\n      }\n\n      clearShareIntent()\n      return importFailed ? 'loaded-without-assets' : 'loaded'\n    } finally {\n      dialogStore.closeDialog({ key: OPEN_SHARED_WORKFLOW_DIALOG_KEY })\n    }\n  }\n\n  return {\n    loadSharedWorkflowFromUrl\n  }\n}\n","import { useI18n } from 'vue-i18n'\nimport { useRoute, useRouter } from 'vue-router'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { clearPreservedQuery } from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport { useTelemetry } from '@/platform/telemetry'\n// oxlint-disable-next-line comfy/no-restricted-paths\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\nimport { useTemplateWorkflows } from './useTemplateWorkflows'\n\n/**\n * Composable for loading templates from URL query parameters\n *\n * Supports URLs like:\n * - /?template=flux_simple (loads with default source)\n * - /?template=flux_simple&source=custom (loads from custom source)\n * - /?template=flux_simple&mode=linear (loads template in linear mode)\n *\n * Input validation:\n * - Template, source, and mode parameters must match: ^[a-zA-Z0-9_-]+$\n * - Invalid formats are rejected with console warnings\n */\nexport function useTemplateUrlLoader() {\n  const route = useRoute()\n  const router = useRouter()\n  const { t } = useI18n()\n  const toast = useToast()\n  const templateWorkflows = useTemplateWorkflows()\n  const canvasStore = useCanvasStore()\n  const TEMPLATE_NAMESPACE = PRESERVED_QUERY_NAMESPACES.TEMPLATE\n  const SUPPORTED_MODES = ['linear'] as const\n  type SupportedMode = (typeof SUPPORTED_MODES)[number]\n\n  /**\n   * Validates parameter format to prevent path traversal and injection attacks\n   * Allows: letters, numbers, underscores, hyphens, and dots (for version numbers)\n   * Blocks: path separators (/, \\), special chars that could enable injection\n   */\n  const isValidParameter = (param: string): boolean => {\n    return /^[a-zA-Z0-9_.-]+$/.test(param)\n  }\n\n  /**\n   * Type guard to check if a value is a supported mode\n   */\n  const isSupportedMode = (mode: string): mode is SupportedMode => {\n    return SUPPORTED_MODES.includes(mode as SupportedMode)\n  }\n\n  /**\n   * Removes template, source, and mode parameters from URL\n   */\n  const cleanupUrlParams = () => {\n    const newQuery = { ...route.query }\n    delete newQuery.template\n    delete newQuery.source\n    delete newQuery.mode\n    void router.replace({ query: newQuery })\n  }\n\n  /**\n   * Loads template from URL query parameters if present\n   * Handles errors internally and shows appropriate user feedback\n   * @returns the id of the template that loaded, if one did\n   */\n  const loadTemplateFromUrl = async (): Promise<string | undefined> => {\n    const templateParam = route.query.template\n\n    if (!templateParam || typeof templateParam !== 'string') {\n      return\n    }\n\n    if (!isValidParameter(templateParam)) {\n      console.warn(\n        `[useTemplateUrlLoader] Invalid template parameter format: ${templateParam}`\n      )\n      return\n    }\n\n    const sourceParam = (route.query.source as string | undefined) || 'default'\n\n    if (!isValidParameter(sourceParam)) {\n      console.warn(\n        `[useTemplateUrlLoader] Invalid source parameter format: ${sourceParam}`\n      )\n      return\n    }\n\n    const modeParam = route.query.mode as string | undefined\n\n    if (\n      modeParam &&\n      (typeof modeParam !== 'string' || !isValidParameter(modeParam))\n    ) {\n      console.warn(\n        `[useTemplateUrlLoader] Invalid mode parameter format: ${modeParam}`\n      )\n      return\n    }\n\n    if (modeParam && !isSupportedMode(modeParam)) {\n      console.warn(\n        `[useTemplateUrlLoader] Unsupported mode parameter: ${modeParam}. Supported modes: ${SUPPORTED_MODES.join(', ')}`\n      )\n    }\n\n    try {\n      await templateWorkflows.loadTemplates()\n\n      const result = await templateWorkflows.loadWorkflowTemplate(\n        templateParam,\n        sourceParam\n      )\n\n      if (result !== 'loaded') return\n\n      if (modeParam === 'linear') {\n        // Set linear mode after successful template load\n        useTelemetry()?.trackEnterLinear({ source: 'template_url' })\n        canvasStore.linearMode = true\n      }\n      return sourceParam === 'default' ? templateParam : undefined\n    } catch (error) {\n      console.error(\n        '[useTemplateUrlLoader] Failed to load template from URL:',\n        error\n      )\n      toast.error(t('g.error'), {\n        description: t('templateWorkflows.error.loading')\n      })\n    } finally {\n      cleanupUrlParams()\n      clearPreservedQuery(TEMPLATE_NAMESPACE)\n    }\n  }\n\n  return {\n    loadTemplateFromUrl\n  }\n}\n","/**\n * V2 Workflow Persistence Composable\n *\n * Key changes from V1:\n * - Uses V2 draft store with per-draft keys\n * - Uses tab state composable for session pointers\n * - Adds 512ms debounce on graph change persistence\n */\n\nimport { debounce } from 'es-toolkit'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { tryOnScopeDispose, whenever } from '@vueuse/core'\nimport { computed, nextTick, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { useRoute, useRouter } from 'vue-router'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport {\n  hydratePreservedQuery,\n  mergePreservedQueryIntoQuery\n} from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport {\n  ComfyWorkflow,\n  useWorkflowStore\n} from '@/platform/workflow/management/stores/workflowStore'\nimport { PERSIST_DEBOUNCE_MS } from '../base/draftTypes'\nimport type { StartupOutcome } from '../base/draftTypes'\nimport {\n  clearAllWorkspaceStorage,\n  completeWorkflowLogoutTransition,\n  prepareWorkflowLogoutTransition,\n  registerWorkflowPersistenceFlush\n} from '../base/storageIO'\nimport { useWorkflowDraftStoreV2 } from '../stores/workflowDraftStoreV2'\nimport { useWorkflowTabState } from './useWorkflowTabState'\nimport { useSharedWorkflowUrlLoader } from '@/platform/workflow/sharing/composables/useSharedWorkflowUrlLoader'\nimport { useTemplateUrlLoader } from '@/platform/workflow/templates/composables/useTemplateUrlLoader'\nimport { api } from '@/scripts/api'\nimport { app as comfyApp } from '@/scripts/app'\n\nexport function useWorkflowPersistenceV2() {\n  const { t } = useI18n()\n  const workflowStore = useWorkflowStore()\n  const settingStore = useSettingStore()\n  const route = useRoute()\n  const router = useRouter()\n  const sharedWorkflowUrlLoader = useSharedWorkflowUrlLoader()\n  const templateUrlLoader = useTemplateUrlLoader()\n  const TEMPLATE_NAMESPACE = PRESERVED_QUERY_NAMESPACES.TEMPLATE\n  const SHARE_NAMESPACE = PRESERVED_QUERY_NAMESPACES.SHARE\n  const draftStore = useWorkflowDraftStoreV2()\n  const tabState = useWorkflowTabState()\n  const toast = useToast()\n  const { onUserLogout, onUserResolved } = useCurrentUser()\n  const teamWorkspaceStore = useTeamWorkspaceStore()\n  let stopWorkspaceReadinessWatcher: (() => void) | undefined\n\n  function stopPendingWorkspaceReadinessWatcher(): void {\n    stopWorkspaceReadinessWatcher?.()\n    stopWorkspaceReadinessWatcher = undefined\n  }\n\n  const ensureTemplateQueryFromIntent = async () => {\n    hydratePreservedQuery(TEMPLATE_NAMESPACE)\n    const mergedQuery = mergePreservedQueryIntoQuery(\n      TEMPLATE_NAMESPACE,\n      route.query\n    )\n\n    if (mergedQuery) {\n      await router.replace({ query: mergedQuery })\n    }\n\n    return mergedQuery ?? route.query\n  }\n\n  const workflowPersistenceEnabled = computed(() =>\n    settingStore.get('Comfy.Workflow.Persist')\n  )\n\n  const lastSavedJsonByPath = ref<Record<string, string>>({})\n\n  watch(workflowPersistenceEnabled, (enabled) => {\n    if (!enabled) {\n      draftStore.reset()\n      lastSavedJsonByPath.value = {}\n    }\n  })\n\n  const persistCurrentWorkflow = () => {\n    if (!workflowPersistenceEnabled.value) return\n    const activeWorkflow = workflowStore.activeWorkflow\n    if (!activeWorkflow) return\n\n    const graphData = comfyApp.rootGraph.serialize()\n    const workflowJson = JSON.stringify(graphData)\n    const workflowPath = activeWorkflow.path\n\n    // Skip if unchanged\n    if (workflowJson === lastSavedJsonByPath.value[workflowPath]) return\n\n    // Save to V2 draft store\n    const saved = draftStore.saveDraft(workflowPath, workflowJson, {\n      name: activeWorkflow.key,\n      isTemporary: activeWorkflow.isTemporary\n    })\n\n    if (!saved) {\n      toast.error(t('g.error'), {\n        description: t('toastMessages.failedToSaveDraft')\n      })\n      return\n    }\n\n    // Update session pointer\n    tabState.setActivePath(workflowPath)\n\n    lastSavedJsonByPath.value[workflowPath] = workflowJson\n\n    // Clean up draft if workflow is saved and unmodified\n    if (!activeWorkflow.isTemporary && !activeWorkflow.isModified) {\n      draftStore.removeDraft(workflowPath)\n    }\n  }\n\n  // Debounced version for graphChanged events\n  const debouncedPersist = debounce(persistCurrentWorkflow, PERSIST_DEBOUNCE_MS)\n\n  function flushPendingPersistence() {\n    debouncedPersist.flush()\n  }\n\n  const unregisterPersistenceFlush = registerWorkflowPersistenceFlush(\n    flushPendingPersistence\n  )\n  window.addEventListener('pagehide', flushPendingPersistence)\n\n  onUserLogout(() => {\n    if (!isCloud) return\n    stopPendingWorkspaceReadinessWatcher()\n    debouncedPersist.cancel()\n    prepareWorkflowLogoutTransition()\n    clearAllWorkspaceStorage()\n  })\n  onUserResolved(() => {\n    if (!isCloud) return\n    stopPendingWorkspaceReadinessWatcher()\n\n    // Release the fence once initialization concludes either way: a resolved\n    // workspace, or a permanent init failure. Waiting on 'ready' alone would\n    // leave writes blocked for the rest of the session if init settles on\n    // 'error' (e.g. no workspaces available, retries exhausted).\n    const isWorkspaceInitConcluded = () =>\n      (teamWorkspaceStore.initState === 'ready' &&\n        teamWorkspaceStore.activeWorkspaceId !== null) ||\n      teamWorkspaceStore.initState === 'error'\n    if (isWorkspaceInitConcluded()) {\n      completeWorkflowLogoutTransition()\n      return\n    }\n\n    stopWorkspaceReadinessWatcher = whenever(\n      isWorkspaceInitConcluded,\n      () => {\n        stopWorkspaceReadinessWatcher = undefined\n        completeWorkflowLogoutTransition()\n      },\n      { once: true }\n    )\n  })\n\n  const loadPreviousWorkflowFromStorage = async () => {\n    const sessionPath = tabState.getActivePath()\n\n    // 1. Try draft for session path\n    if (\n      sessionPath &&\n      (await draftStore.loadPersistedWorkflow({\n        preferredPath: sessionPath\n      }))\n    )\n      return true\n\n    // 2. Try saved workflow by path (draft may not exist for saved+unmodified workflows)\n    if (sessionPath) {\n      const saved = workflowStore.getWorkflowByPath(sessionPath)\n      if (saved) {\n        await useWorkflowService().openWorkflow(saved)\n        return true\n      }\n    }\n\n    // 3. Fall back to most recent draft\n    return await draftStore.loadPersistedWorkflow({\n      fallbackToLatestDraft: true\n    })\n  }\n\n  /**\n   * The blank canvas startup opens for itself is not the user's work, but the\n   * active-workflow watcher has already saved it. Drop the draft and the\n   * pointer to it, or the next boot restores it and reports `restored`.\n   */\n  const discardStartupBlankDraft = () => {\n    const blank = workflowStore.activeWorkflow\n    if (!blank?.isTemporary || blank.isModified) return\n\n    debouncedPersist.cancel()\n    draftStore.removeDraft(blank.path)\n    delete lastSavedJsonByPath.value[blank.path]\n    tabState.clearActivePathPointer()\n  }\n\n  const hasPreservedIntent = (namespace: string, key: string) => {\n    if (typeof route.query[key] === 'string') return true\n    hydratePreservedQuery(namespace)\n    const merged = mergePreservedQueryIntoQuery(namespace, route.query)\n    return typeof merged?.[key] === 'string'\n  }\n\n  const hasSharedWorkflowIntent = () =>\n    hasPreservedIntent(SHARE_NAMESPACE, 'share')\n\n  const hasTemplateUrlIntent = () =>\n    hasPreservedIntent(TEMPLATE_NAMESPACE, 'template')\n\n  const resolveStartupOutcome = async (): Promise<StartupOutcome> => {\n    if (settingStore.get('Comfy.TutorialCompleted')) {\n      await comfyApp.loadGraphData()\n      return 'restored'\n    }\n\n    await useWorkflowService().loadBlankWorkflow()\n    await nextTick()\n    discardStartupBlankDraft()\n    return hasSharedWorkflowIntent() || hasTemplateUrlIntent()\n      ? 'url-intent'\n      : 'fresh'\n  }\n\n  const getRestorableTabState = () => {\n    const storedTabState = tabState.getOpenPaths()\n    const paths = storedTabState?.paths ?? []\n    const activeIndex = storedTabState?.activeIndex ?? -1\n\n    if (paths.length === 0 || activeIndex < 0 || activeIndex >= paths.length) {\n      return null\n    }\n\n    return { paths, activeIndex }\n  }\n\n  const initializeWorkflow = async (): Promise<StartupOutcome> => {\n    if (!workflowPersistenceEnabled.value) {\n      return await resolveStartupOutcome()\n    }\n\n    try {\n      if (getRestorableTabState()) {\n        // GraphCanvas calls restoreWorkflowTabsState next; skip the single-workflow\n        // fallback here so the saved tab order and active index drive startup.\n        return 'restored'\n      }\n\n      await workflowStore.loadWorkflows()\n      const restored = await loadPreviousWorkflowFromStorage()\n      return restored ? 'restored' : await resolveStartupOutcome()\n    } catch (err) {\n      console.error('Error loading previous workflow', err)\n      return await resolveStartupOutcome()\n    }\n  }\n\n  const loadTemplateFromUrlIfPresent = async () => {\n    const query = await ensureTemplateQueryFromIntent()\n    const hasTemplateUrl = query.template && typeof query.template === 'string'\n\n    return hasTemplateUrl\n      ? await templateUrlLoader.loadTemplateFromUrl()\n      : undefined\n  }\n\n  const loadSharedWorkflowFromUrlIfPresent = async () => {\n    return await sharedWorkflowUrlLoader.loadSharedWorkflowFromUrl()\n  }\n\n  // Setup watchers\n  watch(\n    () => workflowStore.activeWorkflow?.key,\n    (activeWorkflowKey) => {\n      if (!activeWorkflowKey) return\n      // Flush any pending persistence from the previous workflow\n      debouncedPersist.flush()\n      // Persist the new workflow immediately\n      persistCurrentWorkflow()\n    }\n  )\n\n  // Debounced persistence on graph changes\n  api.addEventListener('graphChanged', debouncedPersist)\n\n  // Clean up event listener when component unmounts\n  tryOnScopeDispose(() => {\n    api.removeEventListener('graphChanged', debouncedPersist)\n    window.removeEventListener('pagehide', flushPendingPersistence)\n    unregisterPersistenceFlush()\n    debouncedPersist.cancel()\n    stopPendingWorkspaceReadinessWatcher()\n  })\n\n  // Restore workflow tabs states\n  const openWorkflows = computed(() => workflowStore.openWorkflows)\n  const activeWorkflow = computed(() => workflowStore.activeWorkflow)\n  const restoreState = computed<{ paths: string[]; activeIndex: number }>(\n    () => {\n      const active = getActiveWorkflow()\n      if (!active) return { paths: [], activeIndex: -1 }\n      const paths = openWorkflows.value\n        .map((workflow) => workflow.path)\n        .filter(\n          (path): path is string =>\n            typeof path === 'string' && path.startsWith(ComfyWorkflow.basePath)\n        )\n      const activeIndex = paths.indexOf(active.path)\n\n      return { paths, activeIndex }\n    }\n  )\n\n  function getActiveWorkflow(): ComfyWorkflow | null {\n    return activeWorkflow.value\n  }\n\n  // Track whether tab state has been properly restored to avoid\n  // overwriting with stale data during initialization\n  let tabStateRestored = false\n\n  watch(restoreState, ({ paths, activeIndex }) => {\n    // Only persist after tab state has been restored to avoid\n    // writing leaked data from wrong workspace during init\n    if (workflowPersistenceEnabled.value && tabStateRestored) {\n      tabState.setOpenPaths(paths, activeIndex)\n    }\n  })\n\n  /**\n   * Restores saved workflow tabs after initializeWorkflow skips the single-workflow fallback.\n   * GraphCanvas must call this during startup when workflow persistence is enabled.\n   */\n  const restoreWorkflowTabsState = async () => {\n    if (!workflowPersistenceEnabled.value) {\n      tabStateRestored = true\n      return\n    }\n\n    try {\n      await workflowStore.loadWorkflows()\n    } catch (err) {\n      console.error('Error loading workflows for tab restore', err)\n      await resolveStartupOutcome()\n      tabStateRestored = true\n      return\n    }\n\n    const restorableTabState = getRestorableTabState()\n    if (!restorableTabState) {\n      tabStateRestored = true\n      return\n    }\n    const { paths: storedWorkflows, activeIndex: storedActiveIndex } =\n      restorableTabState\n\n    storedWorkflows.forEach((path: string) => {\n      if (workflowStore.getWorkflowByPath(path)) return\n      const draft = draftStore.getDraft(path)\n      if (!draft?.isTemporary) return\n      try {\n        const workflowData = JSON.parse(draft.data)\n        workflowStore.createTemporary(draft.name, workflowData)\n      } catch (err) {\n        console.warn(\n          'Failed to parse workflow draft, creating with default',\n          err\n        )\n        draftStore.removeDraft(path)\n        workflowStore.createTemporary(draft.name)\n      }\n    })\n\n    workflowStore.openWorkflowsInBackground({\n      left: storedWorkflows.slice(0, storedActiveIndex),\n      right: storedWorkflows.slice(storedActiveIndex)\n    })\n\n    tabStateRestored = true\n\n    // Activate the correct workflow at storedActiveIndex\n    const activePath = storedWorkflows[storedActiveIndex]\n    const workflow = activePath\n      ? workflowStore.getWorkflowByPath(activePath)\n      : null\n    if (workflow) {\n      await useWorkflowService().openWorkflow(workflow)\n    }\n  }\n\n  return {\n    initializeWorkflow,\n    loadSharedWorkflowFromUrlIfPresent,\n    loadTemplateFromUrlIfPresent,\n    restoreWorkflowTabsState\n  }\n}\n","import type { LGraphCanvas } from '@/lib/litegraph/src/litegraph'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { LayoutSource } from '@/renderer/core/layout/types'\n\nexport function notifyLayoutChanges(canvas: LGraphCanvas): () => void {\n  const stopOperations = layoutStore.onChange((change) => {\n    const graph = canvas.graph\n    if (\n      !graph ||\n      change.operation.graphId !== graph.rootGraph.id ||\n      change.source === LayoutSource.Canvas\n    ) {\n      return\n    }\n\n    for (const nodeId of change.sizeChangedNodeIds) {\n      const node = graph.getNodeById(nodeId)\n      node?.onResize?.(node.size)\n    }\n  })\n  const stopGeometry = layoutStore.onGeometryChange((graphIds) => {\n    const graph = canvas.graph\n    if (!graph || !graphIds.has(graph.rootGraph.id)) return\n\n    canvas.setDirty(true, true)\n  })\n\n  return () => {\n    stopOperations()\n    stopGeometry()\n  }\n}\n","import type {\n  CURATED_TEMPLATE_IDS,\n  FALLBACK_TEMPLATE_IDS\n} from '../gettingStarted/tutorialCards'\n\n/** Every id the Getting Started grid can offer, so no card can ship unpinned. */\nexport type SupportedTemplateId =\n  | (typeof CURATED_TEMPLATE_IDS)[number]\n  | (typeof FALLBACK_TEMPLATE_IDS)[number]\n\nexport type TourMediaKind = 'image' | 'video'\n\n/**\n * The kind a sink node type produces, so the drift guard can hold the two in\n * step. Video sinks are listed because they are fed IMAGE frames, so the slot\n * type alone would call their output an image.\n */\nexport const MEDIA_KIND_BY_SINK_TYPE: Record<string, TourMediaKind> = {\n  SaveImage: 'image',\n  SaveImageAdvanced: 'image',\n  SaveVideo: 'video',\n  SaveAnimatedWEBP: 'video',\n  SaveAnimatedPNG: 'video',\n  SaveWEBM: 'video',\n  VHS_VideoCombine: 'video'\n}\n\n/**\n * A pinned node. The type is pinned alongside the id so an upstream renumber\n * that leaves the id occupied by a different node fails the drift guard.\n */\nexport interface RolePin {\n  id: number\n  type: string\n}\n\nexport interface RolePins {\n  /** Absent for text-to-image, which has nothing to upload. */\n  source?: RolePin\n  /** Absent when the template exposes no prompt the user can edit. */\n  prompt?: RolePin\n  sink: RolePin\n  mediaKind: TourMediaKind\n}\n\n/**\n * The templates the tour supports, pinned by hand. A prompt pinned inside a\n * subgraph is spotlit through the root-graph node hosting it.\n */\nexport const TOUR_ROLE_PINS: Record<SupportedTemplateId, RolePins> = {\n  image_krea2_turbo_t2i: {\n    prompt: { id: 19, type: 'PrimitiveStringMultiline' },\n    sink: { id: 29, type: 'SaveImage' },\n    mediaKind: 'image'\n  },\n  image_z_image_turbo: {\n    prompt: { id: 27, type: 'CLIPTextEncode' },\n    sink: { id: 9, type: 'SaveImage' },\n    mediaKind: 'image'\n  },\n  video_ltx2_3_i2v: {\n    source: { id: 269, type: 'LoadImage' },\n    prompt: { id: 319, type: 'PrimitiveStringMultiline' },\n    sink: { id: 75, type: 'SaveVideo' },\n    mediaKind: 'video'\n  },\n  video_wan2_2_14B_i2v: {\n    source: { id: 97, type: 'LoadImage' },\n    prompt: { id: 93, type: 'CLIPTextEncode' },\n    sink: { id: 108, type: 'SaveVideo' },\n    mediaKind: 'video'\n  },\n  'templates-image_to_real': {\n    source: { id: 14, type: 'LoadImage' },\n    sink: { id: 18, type: 'SaveImage' },\n    mediaKind: 'image'\n  },\n  image_qwen_image_edit_2509: {\n    source: { id: 78, type: 'LoadImage' },\n    prompt: { id: 111, type: 'TextEncodeQwenImageEditPlus' },\n    sink: { id: 469, type: 'SaveImageAdvanced' },\n    mediaKind: 'image'\n  },\n  flux_fill_inpaint_example: {\n    source: { id: 17, type: 'LoadImage' },\n    prompt: { id: 23, type: 'CLIPTextEncode' },\n    sink: { id: 9, type: 'SaveImage' },\n    mediaKind: 'image'\n  },\n  video_ltx2_i2v_distilled: {\n    source: { id: 98, type: 'LoadImage' },\n    prompt: { id: 3, type: 'CLIPTextEncode' },\n    sink: { id: 75, type: 'SaveVideo' },\n    mediaKind: 'video'\n  }\n}\n","import { resolveSubgraphInputTarget } from '@/core/graph/subgraph/resolveSubgraphInputTarget'\nimport type { LGraph } from '@/lib/litegraph/src/LGraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport {\n  collectAllNodes,\n  getExecutionIdByNode,\n  isExecutionPathActive\n} from '@/utils/graphTraversalUtil'\nimport { filterOutputNodes } from '@/utils/nodeFilterUtil'\n\nimport { MEDIA_KIND_BY_SINK_TYPE } from './tourRolePins'\nimport type { TourMediaKind } from './tourRolePins'\n\n/** Roles read off a graph nobody pinned. Host-mapping stays the caller's job. */\ninterface HeuristicRoles {\n  source: LGraphNode | null\n  prompt: LGraphNode | null\n  sink: LGraphNode | null\n  mediaKind: TourMediaKind\n}\n\nconst MEDIA_KIND_BY_SLOT_TYPE: Partial<Record<string, TourMediaKind>> = {\n  IMAGE: 'image',\n  VIDEO: 'video'\n}\n\n/** `neg` alone is the abbreviation; anything longer must be `negative*`, or\n * `negate`, `negligible` and Spanish `negro` disqualify a real prompt. */\nconst DISQUALIFYING = ['negative', 'neg', 'system', 'undesired', 'avoid']\n\n/** `anti` names the negative box only next to the noun — `Anti-prompt`,\n * `AntiPrompt`, `ANTIPROMPT` — since `anti_aliasing` and `antique` are ordinary\n * words a real prompt carries. Read off the normalised label, not its words, so\n * the pair survives the separator and camelCase spellings alike. */\nconst ANTI_PROMPT = /\\banti ?prompts?\\b/\n\nfunction disqualified(word: string): boolean {\n  return DISQUALIFYING.includes(word) || word.startsWith('negative')\n}\n\nfunction readsAsAntiPrompt(label: string | undefined): boolean {\n  return ANTI_PROMPT.test(labelWords(label).join(' '))\n}\n\n/** Real templates ship nodes with no title and widgets with no name. */\nfunction labelWords(label: string | undefined): string[] {\n  return (label ?? '')\n    .replace(/([a-z0-9])([A-Z])/g, '$1 $2')\n    .toLowerCase()\n    .replace(/[^a-z0-9]+/g, ' ')\n    .split(' ')\n    .filter(Boolean)\n}\n\nfunction slotType(slot: { type?: unknown }): string {\n  return String(slot.type ?? '').toUpperCase()\n}\n\n/** Multiline is what separates a prompt box from a seed or a filename. */\nfunction promptWidgets(node: LGraphNode) {\n  return (node.widgets ?? []).filter(\n    (widget) => widget.type === 'customtext' || widget.options.multiline\n  )\n}\n\nfunction consumerInputNames(nodes: LGraphNode[]): Map<LGraphNode, string[]> {\n  const names = new Map<LGraphNode, string[]>()\n\n  for (const consumer of nodes) {\n    if (consumer.isVirtualNode) continue\n    const inputs = consumer.inputs\n    inputs.forEach((input, slot) => {\n      const producer = consumer.getInputNode(slot)\n      if (producer)\n        names.set(producer, [...(names.get(producer) ?? []), input.name])\n    })\n  }\n\n  return names\n}\n\n/** A text node inside a subgraph is titled nothing useful; its port is not. */\nfunction exposedInputNames(nodes: LGraphNode[]): Map<LGraphNode, string[]> {\n  const names = new Map<LGraphNode, string[]>()\n\n  for (const host of nodes) {\n    if (!host.isSubgraphNode()) continue\n\n    for (const input of host.inputs) {\n      const target = resolveSubgraphInputTarget(host, input.name)\n      const inner = target && host.subgraph.getNodeById(target.nodeId)\n      if (inner) names.set(inner, [...(names.get(inner) ?? []), input.name])\n    }\n  }\n\n  return names\n}\n\n/**\n * Ranks a text node on its title, its widget's name, any subgraph port wired to\n * it, and the input name it feeds one hop on, normalised for case and\n * separators. Anything reading as a negative prompt disqualifies.\n */\nfunction promptScore(labels: string[], fedInputNames: string[]): number {\n  const words = labels.flatMap(labelWords)\n  const fed = fedInputNames.flatMap(labelWords)\n\n  if ([...words, ...fed].some(disqualified)) return -1\n  if ([...labels, ...fedInputNames].some(readsAsAntiPrompt)) return -1\n  if (fed.includes('positive')) return 3\n  if (words.includes('positive')) return 2\n  if (words.includes('prompt')) return 1\n  return 0\n}\n\n/**\n * Each node scores on its best prompt widget, so one carrying both a positive\n * and a negative box is not disqualified by widget order. A tie at the top\n * resolves to nothing; a lone text box wins by being alone. Virtual nodes are\n * skipped: a note never runs, and a subgraph host's promoted widgets mirror an\n * interior node that host-maps back to it, tying a prompt against itself.\n */\nfunction findPrompt(nodes: LGraphNode[]): LGraphNode | null {\n  const consumers = consumerInputNames(nodes)\n  const exposed = exposedInputNames(nodes)\n\n  const ranked = nodes\n    .flatMap((node) => {\n      if (node.isVirtualNode) return []\n      const widgets = promptWidgets(node)\n      if (!widgets.length) return []\n      const fed = consumers.get(node) ?? []\n      const shared = [node.title, ...(exposed.get(node) ?? [])]\n      const scores = widgets.map((w) => promptScore([...shared, w.name], fed))\n      return [{ node, score: Math.max(...scores) }]\n    })\n    .sort((a, b) => b.score - a.score)\n\n  const best = ranked.at(0)\n  const runnerUp = ranked.at(1)\n  if (!best || best.score < 0) return null\n  return !runnerUp || best.score > runnerUp.score ? best.node : null\n}\n\n/** Produces an image and consumes nothing. Two of them is a coin flip. */\nfunction findSource(nodes: LGraphNode[]): LGraphNode | null {\n  const sources = nodes.filter(\n    (node) =>\n      !node.isVirtualNode &&\n      !node.inputs.some((input) => input.link != null) &&\n      node.outputs.some((output) => slotType(output) === 'IMAGE')\n  )\n\n  return sources.length === 1 ? sources[0] : null\n}\n\n/** Any output node fed media can show the result; disagreeing kinds cannot. */\nfunction findSink(\n  nodes: LGraphNode[]\n): { node: LGraphNode; mediaKind: TourMediaKind } | null {\n  const sinks = filterOutputNodes(nodes).flatMap((node) => {\n    for (const input of node.inputs) {\n      const slotKind = MEDIA_KIND_BY_SLOT_TYPE[slotType(input)]\n      if (input.link == null || !slotKind) continue\n      const mediaKind = MEDIA_KIND_BY_SINK_TYPE[node.type] ?? slotKind\n      return [{ node, slotKind, mediaKind }]\n    }\n    return []\n  })\n\n  const first = sinks.at(0)\n  if (!first) return null\n  // Sinks must agree on the data they are fed; a video combine and a still\n  // preview of the same frames do not disagree, they rank — the video is the\n  // result and the preview is scaffolding.\n  if (!sinks.every(({ slotKind }) => slotKind === first.slotKind)) return null\n  return sinks.find(({ mediaKind }) => mediaKind === 'video') ?? first\n}\n\n/** Roles for a shared workflow or an unpinned template. No sink, no tour. */\nexport function heuristicRoles(graph: LGraph): HeuristicRoles | null {\n  const active = collectAllNodes(graph).filter((node) => {\n    const executionId = getExecutionIdByNode(graph, node)\n    return executionId ? isExecutionPathActive(graph, executionId) : false\n  })\n\n  const sink = findSink(active)\n  if (!sink) return null\n\n  return {\n    source: findSource(active),\n    prompt: findPrompt(active),\n    sink: sink.node,\n    mediaKind: sink.mediaKind\n  }\n}\n","import type { LGraph } from '@/lib/litegraph/src/LGraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { NodeId } from '@/types/nodeId'\nimport {\n  getExecutionIdByNode,\n  getRootParentNode\n} from '@/utils/graphTraversalUtil'\nimport { resolveNode } from '@/utils/litegraphUtil'\n\nimport { heuristicRoles } from './heuristicRoles'\nimport { TOUR_ROLE_PINS } from './tourRolePins'\nimport type {\n  RolePin,\n  SupportedTemplateId,\n  TourMediaKind\n} from './tourRolePins'\n\nexport interface ResolvedRoles {\n  source: NodeId | null\n  promptHost: NodeId | null\n  sink: NodeId | null\n  mediaKind: TourMediaKind\n}\n\n/** The root-graph node a role is spotlit through: itself, or the subgraph node holding it. */\nfunction rootHost(\n  node: LGraphNode | null | undefined,\n  root: LGraph\n): NodeId | null {\n  if (!node) return null\n  if (node.graph === root) return node.id\n  const executionId = getExecutionIdByNode(root, node)\n  return executionId ? (getRootParentNode(root, executionId)?.id ?? null) : null\n}\n\n/** The pinned type is the guard: an id alone matches any graph that has it. */\nfunction resolvePin(pin: RolePin | undefined, root: LGraph): NodeId | null {\n  if (!pin) return null\n  const node = resolveNode(pin.id, root)\n  return node?.type === pin.type ? rootHost(node, root) : null\n}\n\n/** Read off the graph itself, then host-mapped the same way pins are. */\nfunction resolveFromGraph(graph: LGraph): ResolvedRoles | null {\n  const roles = heuristicRoles(graph)\n  if (!roles) return null\n\n  return {\n    source: rootHost(roles.source, graph),\n    promptHost: rootHost(roles.prompt, graph),\n    sink: rootHost(roles.sink, graph),\n    mediaKind: roles.mediaKind\n  }\n}\n\n/**\n * Validates a template's pins against the live graph, falling back to reading\n * the roles off the graph for anything unpinned — a shared workflow, or a\n * template URL nobody curated. A pin the graph no longer contains degrades to\n * null so its step is omitted rather than spotlighting a node that is gone.\n */\nexport function resolveTourRoles(\n  graph: LGraph,\n  templateId?: string\n): ResolvedRoles | null {\n  if (templateId === undefined || !Object.hasOwn(TOUR_ROLE_PINS, templateId))\n    return resolveFromGraph(graph)\n  const pins = TOUR_ROLE_PINS[templateId as SupportedTemplateId]\n\n  return {\n    source: resolvePin(pins.source, graph),\n    promptHost: resolvePin(pins.prompt, graph),\n    sink: resolvePin(pins.sink, graph),\n    mediaKind: pins.mediaKind\n  }\n}\n","import type { NodeId } from '@/types/nodeId'\n\nimport type { ResolvedRoles } from './resolveTourRoles'\nimport type { TourMediaKind } from './tourRolePins'\n\nexport type TourStep =\n  | { kind: 'upload'; nodeId: NodeId }\n  | { kind: 'prompt'; nodeId: NodeId }\n  | { kind: 'run' }\n  | { kind: 'result'; nodeId: NodeId; mediaKind: TourMediaKind }\n\n/** A role that did not resolve omits its step; Run targets the toolbar, not the graph. */\nexport function sequenceBuilder({\n  source,\n  promptHost,\n  sink,\n  mediaKind\n}: ResolvedRoles): TourStep[] {\n  return [\n    ...(source ? [{ kind: 'upload' as const, nodeId: source }] : []),\n    ...(promptHost ? [{ kind: 'prompt' as const, nodeId: promptHost }] : []),\n    { kind: 'run' as const },\n    ...(sink ? [{ kind: 'result' as const, nodeId: sink, mediaKind }] : [])\n  ]\n}\n","import type { Placement } from '@floating-ui/vue'\n\nexport interface Viewport {\n  width: number\n  height: number\n}\n\nexport interface BoxStyle {\n  left: string\n  top: string\n  width: string\n  height: string\n}\n\nconst SPOTLIGHT_EDGE_INSET = 2\n\nexport const CARD_WIDTH = 300\nexport const VIEWPORT_MARGIN = 12\nexport const CARD_GAP = 16\n/** Wide enough for the cursor glyph to sit centred between card and target. */\nexport const CURSOR_GAP = 40\n/** The card's travel to a new target; whatever moves that target waits it out. */\nexport const CARD_GLIDE_MS = 300\n// Kept tight so the spotlight glow doesn't spill onto an adjacent clickable control.\nexport const SPOTLIGHT_PAD = 4\n\nexport interface SpotlightRect {\n  x: number\n  y: number\n  width: number\n  height: number\n}\n\nexport function unionRect(a: DOMRectReadOnly, b: DOMRectReadOnly): DOMRect {\n  const left = Math.min(a.left, b.left)\n  const top = Math.min(a.top, b.top)\n  return new DOMRect(\n    left,\n    top,\n    Math.max(a.right, b.right) - left,\n    Math.max(a.bottom, b.bottom) - top\n  )\n}\n\nexport function clampSpotlightRect(\n  r: DOMRect,\n  pad: number,\n  viewport: Viewport\n): SpotlightRect {\n  const left = Math.max(SPOTLIGHT_EDGE_INSET, r.left - pad)\n  const top = Math.max(SPOTLIGHT_EDGE_INSET, r.top - pad)\n  const right = Math.min(viewport.width - SPOTLIGHT_EDGE_INSET, r.right + pad)\n  const bottom = Math.min(\n    viewport.height - SPOTLIGHT_EDGE_INSET,\n    r.bottom + pad\n  )\n  return {\n    x: left,\n    y: top,\n    width: Math.max(0, right - left),\n    height: Math.max(0, bottom - top)\n  }\n}\n\nexport function clampSpotlight(\n  r: DOMRect,\n  pad: number,\n  viewport: Viewport\n): BoxStyle {\n  const { x, y, width, height } = clampSpotlightRect(r, pad, viewport)\n  return {\n    left: `${x}px`,\n    top: `${y}px`,\n    width: `${width}px`,\n    height: `${height}px`\n  }\n}\n\n/** Under `fill-rule=\"evenodd\"`, the hole subpath is what lets input through. */\nexport function hitRegionPath(\n  viewport: Viewport,\n  hole: SpotlightRect | null\n): string {\n  const outer = `M0 0H${viewport.width}V${viewport.height}H0Z`\n  if (!hole) return outer\n  const { x, y, width, height } = hole\n  return `${outer}M${x} ${y}h${width}v${height}h${-width}Z`\n}\n\nexport function noTargetCardLeft(viewportWidth: number): number {\n  return Math.max(VIEWPORT_MARGIN, (viewportWidth - CARD_WIDTH) / 2)\n}\n\n/** Floats the cursor in the gap on the card edge facing the target. */\nconst CURSOR_EDGE_CLASS = {\n  top: '-top-7 left-1/2 -translate-x-1/2 rotate-45',\n  bottom: '-bottom-7 left-1/2 -translate-x-1/2 -rotate-[135deg]',\n  left: '-left-7 top-1/2 -translate-y-1/2 -rotate-45',\n  right: '-right-7 top-1/2 -translate-y-1/2 rotate-[135deg]'\n} as const\n\nconst TARGET_FACING_EDGE = {\n  top: 'bottom',\n  bottom: 'top',\n  left: 'right',\n  right: 'left'\n} as const\n\ntype Side = keyof typeof TARGET_FACING_EDGE\n\nexport function cursorEdgeClass(placement: Placement): string {\n  const side = placement.split('-')[0] as Side\n  return CURSOR_EDGE_CLASS[TARGET_FACING_EDGE[side]]\n}\n\nconst TOP_BAR_HEIGHT_VAR = '--comfy-topbar-height'\n\n/** The top bar's height, read from the theme token, plus the standard gap. */\nexport function topSafeInset(): number {\n  const root = document.documentElement\n  const raw = getComputedStyle(root).getPropertyValue(TOP_BAR_HEIGHT_VAR).trim()\n  const px = raw.endsWith('rem')\n    ? parseFloat(raw) * parseFloat(getComputedStyle(root).fontSize)\n    : parseFloat(raw)\n  return (Number.isFinite(px) ? px : 0) + CARD_GAP\n}\n","import { delay } from 'es-toolkit'\n\nimport type { ReadOnlyRect } from '@/lib/litegraph/src/interfaces'\nimport {\n  CARD_GLIDE_MS,\n  CARD_WIDTH,\n  CURSOR_GAP,\n  topSafeInset\n} from '@/platform/onboarding/coachmarkLayout'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { NodeId } from '@/types/nodeId'\n\nconst FOCUS_DURATION_MS = 450\n/** Never magnify past this: the aim is a node that reads, not one that dominates. */\nexport const MAX_FOCUS_SCALE = 0.65\nconst CARD_COLUMN = CARD_WIDTH + CURSOR_GAP * 2\n\ninterface Viewport {\n  width: number\n  height: number\n}\n\n/**\n * Fill fraction that frames `bounds` beside the card. The fit centres the node\n * and so splits the free space evenly, hence room for a card column on each\n * side, and for the top bar on each end — the canvas runs the full height of\n * the window, underneath that bar, so a node fitted to the whole of it hides\n * its own title behind the workflow tabs. Inverts litegraph's fit, which\n * solves each axis as `(fill * side) / max(bound, 300)` and takes the smaller,\n * so the binding axis has to be handed the larger fill.\n */\nexport function focusFill(bounds: ReadOnlyRect, viewport: Viewport): number {\n  const [, , width, height] = bounds\n  const sideRoom = viewport.width - CARD_COLUMN * 2\n  const usableWidth = sideRoom > 0 ? sideRoom : viewport.width\n  const endRoom = viewport.height - topSafeInset() * 2\n  const usableHeight = endRoom > 0 ? endRoom : viewport.height\n  const scale = Math.min(\n    usableWidth / Math.max(width, 1),\n    usableHeight / Math.max(height, 1),\n    MAX_FOCUS_SCALE\n  )\n  return Math.max(\n    (scale * Math.max(width, 300)) / viewport.width,\n    (scale * Math.max(height, 300)) / viewport.height\n  )\n}\n\nfunction prefersReducedMotion(): boolean {\n  return window.matchMedia('(prefers-reduced-motion: reduce)').matches\n}\n\n/** Re-solves the fill each time: it is a fraction of a viewport that can resize. */\nfunction fitInstantly(bounds: ReadOnlyRect) {\n  const canvas = useCanvasStore().canvas\n  const viewport = canvas?.canvas.getBoundingClientRect()\n  if (!canvas || !viewport?.width || !viewport.height) return\n  canvas.ds.fitToBounds(bounds, { zoom: focusFill(bounds, viewport) })\n  canvas.setDirty(true, true)\n}\n\nconst SETTLED_PX = 8\nconst SETTLED_SCALE = 0.01\n\n/** The scale litegraph's fit lands on: it takes whichever axis binds first. */\nfunction framedScale(bounds: ReadOnlyRect, viewport: Viewport): number {\n  const zoom = focusFill(bounds, viewport)\n  return Math.min(\n    (zoom * viewport.width) / Math.max(bounds[2], 300),\n    (zoom * viewport.height) / Math.max(bounds[3], 300)\n  )\n}\n\n/** Back onto a step already framed would otherwise animate 0px for 750ms. */\nfunction alreadyFramed(\n  bounds: ReadOnlyRect,\n  ds: { offset: ArrayLike<number>; scale: number },\n  viewport: Viewport\n): boolean {\n  const centreX = (bounds[0] + bounds[2] / 2 + ds.offset[0]) * ds.scale\n  const centreY = (bounds[1] + bounds[3] / 2 + ds.offset[1]) * ds.scale\n  return (\n    Math.abs(ds.scale - framedScale(bounds, viewport)) <= SETTLED_SCALE &&\n    Math.abs(centreX - viewport.width / 2) < SETTLED_PX &&\n    Math.abs(centreY - viewport.height / 2) < SETTLED_PX\n  )\n}\n\n/**\n * Brings a node into view for the step that spotlights it. Resolves once the\n * camera has landed, so an opening tour reveals its card on a still view.\n *\n * @param glide Wait out the card's travel to this step first, so only one thing\n * moves at a time. The tour's first card has nowhere to travel from.\n */\nexport async function frameNode(\n  nodeId: NodeId,\n  signal: AbortSignal,\n  { glide = true }: { glide?: boolean } = {}\n): Promise<void> {\n  const canvas = useCanvasStore().canvas\n  const node = canvas?.graph?.getNodeById(nodeId)\n  const viewport = canvas?.canvas.getBoundingClientRect()\n  if (!canvas || !node || !viewport?.width || !viewport.height) return\n\n  const bounds = node.boundingRect\n\n  window.addEventListener('resize', () => fitInstantly(bounds), { signal })\n\n  if (prefersReducedMotion()) return fitInstantly(bounds)\n  if (alreadyFramed(bounds, canvas.ds, viewport)) return\n\n  if (glide) await delay(CARD_GLIDE_MS, { signal })\n  canvas.animateToBounds(bounds, {\n    zoom: focusFill(bounds, viewport),\n    duration: FOCUS_DURATION_MS\n  })\n  await delay(FOCUS_DURATION_MS, { signal })\n}\n","import { useElementBounding, useEventListener } from '@vueuse/core'\nimport { effectScope, watch } from 'vue'\n\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport type { RectTarget } from '@/platform/onboarding/coachmarkRegistry'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { useTransformState } from '@/renderer/core/layout/transform/useTransformState'\nimport type { NodeId } from '@/types/nodeId'\n\n/** A canvas node as a coachmark target, derived from its layout and the camera. */\nexport function canvasNodeTarget(nodeId: NodeId): RectTarget {\n  const { camera } = useTransformState()\n  const canvasStore = useCanvasStore()\n  const resolvedGraph = canvasStore.currentGraph\n  const scope = effectScope(true)\n  const layout = resolvedGraph\n    ? scope.run(() =>\n        layoutStore.getNodeLayoutRef(resolvedGraph.rootGraph.id, nodeId)\n      )\n    : null\n  const canvasBounds = scope.run(() =>\n    useElementBounding(() => canvasStore.canvas?.canvas)\n  )!\n\n  return {\n    getRect: () => {\n      // Node ids are graph-local, so id 6 in another graph is a different node.\n      if (canvasStore.currentGraph !== resolvedGraph) return null\n      // A collapsed node renders no widget for a step to point at.\n      if (canvasStore.currentGraph?.getNodeById(nodeId)?.collapsed) return null\n\n      const bounds = layout?.value?.bounds\n      if (!bounds) return null\n\n      // Bounds are the body box; the node renders a title height above it.\n      const title = LiteGraph.NODE_TITLE_HEIGHT || 0\n      const { x, y, z } = camera\n      return new DOMRect(\n        (bounds.x + x) * z + canvasBounds.left.value,\n        (bounds.y - title + y) * z + canvasBounds.top.value,\n        bounds.width * z,\n        (bounds.height + title) * z\n      )\n    },\n    onMove: (notify) => {\n      const stopWatch = watch(\n        () => [camera.x, camera.y, camera.z, layout?.value],\n        notify,\n        { flush: 'post' }\n      )\n      const stopResize = useEventListener(window, 'resize', notify)\n      return () => {\n        stopWatch()\n        stopResize()\n      }\n    },\n    dispose: () => scope.stop()\n  }\n}\n","import type { RectTarget } from '@/platform/onboarding/coachmarkRegistry'\nimport type { Ref } from 'vue'\n\nimport {\n  registerCoachmark,\n  unregisterCoachmark\n} from '@/platform/onboarding/coachmarkRegistry'\nimport { FIRST_RUN_COACH_IDS } from '@/platform/onboarding/onboardingTours'\nimport type {\n  CoachId,\n  CoachStep,\n  TourResolution\n} from '@/platform/onboarding/onboardingTours'\nimport { app } from '@/scripts/app'\n\nimport { resolveTourRoles } from '../roles/resolveTourRoles'\nimport type { ResolvedRoles } from '../roles/resolveTourRoles'\nimport { sequenceBuilder } from '../roles/tourSequence'\nimport type { TourStep } from '../roles/tourSequence'\nimport { frameNode } from './cameraFraming'\nimport { canvasNodeTarget } from './canvasCoachTarget'\n\n/** How far the run has got, which is all the Run step's copy has to report. */\nexport type RunState = 'idle' | 'generating' | 'succeeded' | 'failed'\n\n/**\n * What the workflow does. The Upload and Prompt steps mean something different\n * in each, so it selects their copy.\n */\ntype TourShape = 't2i' | 'i2v' | 'image-edit' | 'other'\n\nconst COACH_ID: Record<TourStep['kind'], CoachId> = {\n  upload: FIRST_RUN_COACH_IDS.source,\n  prompt: FIRST_RUN_COACH_IDS.prompt,\n  run: FIRST_RUN_COACH_IDS.runButton,\n  result: FIRST_RUN_COACH_IDS.sink\n}\n\n/** Undoes the last registration; the tour holds one target set at a time. */\nlet releaseRegistered = () => {}\n\n/** Drops the canvas targets a finished tour registered. */\nexport function releaseFirstRunTargets() {\n  releaseRegistered()\n  releaseRegistered = () => {}\n}\n\nfunction registerCanvasTargets(sequence: TourStep[]) {\n  const registered: [CoachId, RectTarget][] = []\n  for (const step of sequence) {\n    if (step.kind === 'run') continue\n    const id = COACH_ID[step.kind]\n    const target = canvasNodeTarget(step.nodeId)\n    registerCoachmark(id, target)\n    registered.push([id, target])\n  }\n  releaseRegistered = () => {\n    for (const [id, target] of registered) {\n      unregisterCoachmark(id, target)\n      target.dispose?.()\n    }\n  }\n}\n\nfunction tourShape({\n  source,\n  promptHost,\n  sink,\n  mediaKind\n}: ResolvedRoles): TourShape {\n  if (!promptHost || !sink) return 'other'\n  if (!source) return 't2i'\n  return mediaKind === 'video' ? 'i2v' : 'image-edit'\n}\n\ninterface StepContext {\n  shape: TourShape\n  runState: Readonly<Ref<RunState>>\n}\n\n/**\n * A step's variant is part of its name, so the engine resolves the copy from\n * `onboardingCoachmarks.firstRun.<name>` without knowing what a template is.\n */\nfunction toCoachStep(\n  step: TourStep,\n  index: number,\n  { shape, runState }: StepContext\n): CoachStep {\n  const common = {\n    kind: 'spotlight' as const,\n    coachId: COACH_ID[step.kind],\n    deferTarget: true,\n    cursor: true,\n    interactive: step.kind !== 'result'\n  }\n\n  if (step.kind === 'run')\n    return { ...common, name: 'run', placement: 'bottom', selfAdvancing: true }\n\n  const framed = {\n    ...common,\n    placement: 'auto' as const,\n    onEnter: (signal: AbortSignal) =>\n      frameNode(step.nodeId, signal, { glide: index > 0 })\n  }\n\n  // The run outlives the step that starts it, so Result is where it reports.\n  if (step.kind === 'result')\n    return {\n      ...framed,\n      get name() {\n        if (runState.value === 'generating') return 'result.generating'\n        if (runState.value === 'failed') return 'result.failed'\n        return `result.${step.mediaKind}`\n      }\n    }\n\n  return { ...framed, name: `${step.kind}.${shape}` }\n}\n\n/**\n * Builds the first-run tour for a template, or for whatever is on the canvas\n * when no template id came with it. A graph the roles cannot be read off\n * leaves nothing worth guiding anyone through — \"click Run\" alone is not a\n * tour — so it yields no steps and the engine reports that it did not start.\n */\nexport async function firstRunTourSteps(\n  templateId: string | undefined,\n  runState: Readonly<Ref<RunState>>\n): Promise<TourResolution> {\n  releaseFirstRunTargets()\n  const graph = app.rootGraphOrUndefined\n  if (!graph) return { steps: [], reason: 'no_roles' }\n  const roles = resolveTourRoles(graph, templateId)\n  if (!roles) return { steps: [], reason: 'no_roles' }\n\n  const sequence = sequenceBuilder(roles)\n  if (sequence.every((step) => step.kind === 'run'))\n    return { steps: [], reason: 'run_only' }\n\n  registerCanvasTargets(sequence)\n  const context: StepContext = { shape: tourShape(roles), runState }\n  return {\n    steps: sequence.map((step, index) => toCoachStep(step, index, context))\n  }\n}\n","import {\n  breakpointsTailwind,\n  createSharedComposable,\n  useBreakpoints,\n  useEventListener\n} from '@vueuse/core'\nimport { delay } from 'es-toolkit'\nimport { computed, readonly, ref, shallowRef, watch } from 'vue'\n\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useOnboardingTourStore } from '@/platform/onboarding/onboardingTourStore'\nimport { registerTour } from '@/platform/onboarding/onboardingTours'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { api } from '@/scripts/api'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useExecutionStore } from '@/stores/executionStore'\n\nimport {\n  firstRunTourSteps,\n  releaseFirstRunTargets\n} from './firstRunTourDefinition'\nimport type { RunState } from './firstRunTourDefinition'\n\nconst RUN_BUTTON_SELECTOR =\n  '[data-testid=\"queue-button\"], [data-testid=\"subscribe-to-run-button\"]'\n\n/** An undimmed look at the workflow the user chose, before the tour dims it. */\nconst INTRO_PREVIEW_MS = 500\n\nconst OFFLINE_GRACE_MS = 20_000\n\n/** How long a submitted run has to be accepted before the card stops promising. */\nconst ACCEPT_DEADLINE_MS = 15_000\n\ntype TourStartState =\n  | { phase: 'idle' }\n  | {\n      phase: 'claimed'\n      ownership: symbol\n      restoreRenderer: boolean\n    }\n  | {\n      phase: 'writingRenderer'\n      ownership: symbol\n      restoreRenderer: boolean\n      write: Promise<void>\n    }\n  | {\n      phase: 'previewing'\n      ownership: symbol\n      restoreRenderer: boolean\n    }\n\nfunction useFirstRunTourControllerInternal() {\n  const engine = useOnboardingTourStore()\n  const billing = useBillingContext()\n  const executionStore = useExecutionStore()\n  const executionErrorStore = useExecutionErrorStore()\n  const workflowStore = useWorkflowStore()\n  const canvasStore = useCanvasStore()\n  const settingStore = useSettingStore()\n  const desktopLayout = useBreakpoints(breakpointsTailwind).greaterOrEqual('md')\n  const tourWorkflow = shallowRef<ComfyWorkflow | null>(null)\n  const nudgeArmed = ref(false)\n  let tourStart: TourStartState = { phase: 'idle' }\n  /** Only a tour walked to the end made a first result to be congratulated for. */\n  const tourWasCompleted = ref(false)\n\n  /**\n   * The half of the tour's context that exists before the tour does: a canvas\n   * the steps can point at. Linear mode `display:none`s it entirely, and below\n   * the desktop layout the spotlights are placed against a screen that isn't\n   * there. Split out so it can also serve as the precondition for opening one.\n   */\n  const canvasContextHolds = computed(\n    () => desktopLayout.value && !canvasStore.linearMode\n  )\n\n  // The tour's node ids are graph-local, so they only describe the workflow it\n  // resolved against: swapping workflows leaves it pointing at strangers.\n  const tourContextHolds = computed(\n    () =>\n      canvasContextHolds.value &&\n      workflowStore.activeWorkflow === tourWorkflow.value\n  )\n\n  const onRunStep = computed(\n    () =>\n      engine.activeTour === 'firstRun' &&\n      engine.step?.kind === 'spotlight' &&\n      engine.step.selfAdvancing === true\n  )\n\n  /** Recorded, not derived: the queue clears a status as soon as it turns terminal. */\n  const runState = ref<RunState>('idle')\n  watch(\n    () => [\n      executionStore.getWorkflowStatus(tourWorkflow.value),\n      executionErrorStore.hasNodeError || executionErrorStore.hasPromptError\n    ],\n    ([status, refused], previous) => {\n      if (status !== undefined) stopAcceptDeadline()\n      // Only an actual transition into `running` starts the wait. This source\n      // re-evaluates whenever the `workflowStatus` map is replaced — which\n      // `mutateStatus` does for *any* workflow — or whenever an error flag\n      // flips. Paths that drop a job without clearing its status leave\n      // `running` behind forever (`handleServiceLevelError` is the live one),\n      // so an unconditional branch here would re-read that stale value and put\n      // the card back on \"your result lands right here\" after the watcher\n      // below has already failed the run.\n      if (status === 'running' && previous[0] !== 'running')\n        runState.value = 'generating'\n      else if (status === 'completed') runState.value = 'succeeded'\n      else if (status === 'failed') runState.value = 'failed'\n      // A refused run never queues; a stopped one drops its status rather than\n      // reporting an outcome. Both end the run, and neither says so.\n      else if (refused && runState.value === 'generating')\n        runState.value = 'failed'\n      else if (status === undefined && previous[0] === 'running')\n        runState.value = 'failed'\n    }\n  )\n\n  /**\n   * The queue stores a job the moment it accepts a submission, so a job\n   * carrying this tour's workflow is proof of acceptance. A refused submission\n   * never gets one.\n   *\n   * Deliberately *not* the workflow status: that is only written by\n   * `handleExecutionStart`, and a cloud job sits accepted in\n   * `initializingJobIds` — \"Waiting for a machine\" — with no status at all\n   * while a worker is allocated. Allocation routinely outlasts any deadline\n   * short enough to be useful, so keying on status would fail healthy runs.\n   */\n  const tourRunAccepted = computed(() =>\n    Object.values(executionStore.queuedJobs).some(\n      (job) => job.workflow === tourWorkflow.value\n    )\n  )\n\n  /**\n   * A submission the backend refuses never gets a prompt_id, so no status ever\n   * appears and none of the branches above can fire. Account preconditions —\n   * sign-in, subscription, credits — are deliberately kept out of the error\n   * stores by `ComfyApp.queuePrompt`, so the refusal is invisible there too.\n   *\n   * Give *acceptance* a deadline, not the run. Acceptance arrives on the\n   * queuePrompt response rather than the socket, so this cannot pre-empt the\n   * longer offline grace: a run accepted at all disarms this immediately and\n   * leaves the connection question to `OFFLINE_GRACE_MS`.\n   *\n   * Acceptance is not the only disarm. `resetExecutionState` drops a job from\n   * `queuedJobs` without clearing its status, so a run can report a status\n   * while this reads false. A refusal produces neither signal.\n   *\n   * Losing acceptance is itself a signal, not a re-armed deadline. Two paths\n   * drop the job without ever writing an outcome:\n   *\n   * - an accepted job that disappears with **no status written at all** — the\n   *   cloud \"waiting for a machine\" job that is cancelled or reconciled away\n   * - `handleServiceLevelError` (\"Job has stagnated\"), which drops the job and\n   *   records a prompt error but never touches `workflowStatus`, so the\n   *   `running` written by `handleExecutionStart` outlives the run\n   *\n   * Not the mid-run credits path: #15161 made\n   * `handleAccountPreconditionError` clear the status, so that one already\n   * ends via the `undefined`-after-`running` branch above.\n   *\n   * A finished run leaves the queue too, but reports a terminal status in the\n   * same flush, and the terminal branches above overwrite unconditionally — so\n   * the outcome wins whichever watcher runs first.\n   */\n  watch(tourRunAccepted, (accepted) => {\n    if (accepted) stopAcceptDeadline()\n    else if (runState.value === 'generating') runState.value = 'failed'\n  })\n\n  let acceptTimer: ReturnType<typeof setTimeout> | undefined\n  function stopAcceptDeadline() {\n    clearTimeout(acceptTimer)\n    acceptTimer = undefined\n  }\n  function startAcceptDeadline() {\n    stopAcceptDeadline()\n    if (tourRunAccepted.value) return\n    acceptTimer = setTimeout(() => {\n      stopAcceptDeadline()\n      if (runState.value === 'generating') runState.value = 'failed'\n    }, ACCEPT_DEADLINE_MS)\n  }\n\n  let offlineTimer: ReturnType<typeof setTimeout> | undefined\n  function stopOfflineGrace() {\n    clearTimeout(offlineTimer)\n    offlineTimer = undefined\n  }\n  useEventListener(api, 'reconnecting', () => {\n    if (runState.value !== 'generating' || offlineTimer) return\n    offlineTimer = setTimeout(() => {\n      stopOfflineGrace()\n      if (runState.value === 'generating') runState.value = 'failed'\n    }, OFFLINE_GRACE_MS)\n  })\n  useEventListener(api, 'reconnected', stopOfflineGrace)\n\n  /**\n   * A run outlives the step that starts it, so the click moves the tour on. One\n   * the paywall will refuse never queues, so the tour parks and leaves the\n   * subscribe button to open its own dialog.\n   */\n  useEventListener(\n    document,\n    'click',\n    (event: MouseEvent) => {\n      if (!onRunStep.value) return\n      if (!(event.target instanceof Element)) return\n      if (!event.target.closest(RUN_BUTTON_SELECTOR)) return\n\n      if (!billing.canRunWorkflows.value) {\n        engine.postpone()\n        return\n      }\n\n      runState.value = 'generating'\n      startAcceptDeadline()\n      engine.next()\n    },\n    { capture: true }\n  )\n\n  watch(\n    () => engine.activeTour === 'firstRun',\n    (active) => {\n      if (active) return\n      // Every ending leaves the user somewhere to go next, so every ending arms\n      // the nudge; only what it says depends on how the tour ended.\n      const ending = engine.lastEnding\n      tourWasCompleted.value =\n        ending?.tour === 'firstRun' && ending.outcome === 'completed'\n      nudgeArmed.value = true\n      stopOfflineGrace()\n      stopAcceptDeadline()\n      releaseFirstRunTargets()\n      tourWorkflow.value = null\n      runState.value = 'idle'\n    }\n  )\n\n  function dismissNudge() {\n    nudgeArmed.value = false\n  }\n\n  function ownsTourStart(ownership: symbol): boolean {\n    return tourStart.phase !== 'idle' && tourStart.ownership === ownership\n  }\n\n  function releaseTourStart(ownership: symbol): void {\n    if (ownsTourStart(ownership)) tourStart = { phase: 'idle' }\n  }\n\n  async function writeRenderer(\n    ownership: symbol,\n    enabled: boolean,\n    restoreRenderer: boolean\n  ): Promise<void> {\n    const write = settingStore.set('Comfy.VueNodes.Enabled', enabled)\n    const writingState: TourStartState = {\n      phase: 'writingRenderer',\n      ownership,\n      restoreRenderer,\n      write\n    }\n    tourStart = writingState\n    try {\n      await write\n    } finally {\n      if (tourStart === writingState) {\n        tourStart = { phase: 'claimed', ownership, restoreRenderer }\n      }\n    }\n  }\n\n  async function cleanUpFailedTourStart(\n    ownership: symbol,\n    shouldCancel: () => boolean\n  ) {\n    const currentStart = tourStart\n    if (currentStart.phase === 'idle' || currentStart.ownership !== ownership)\n      return\n    releaseFirstRunTargets()\n    tourWorkflow.value = null\n    const { restoreRenderer } = currentStart\n    if (restoreRenderer && shouldCancel()) return\n    if (restoreRenderer) await writeRenderer(ownership, false, restoreRenderer)\n    releaseTourStart(ownership)\n  }\n\n  function canBeginTour(shouldCancel: () => boolean): boolean {\n    return !shouldCancel() && !engine.activeTour && canvasContextHolds.value\n  }\n\n  async function claimTourStart(ownership: symbol): Promise<boolean> {\n    const previousStart = tourStart\n    const restoreRenderer =\n      previousStart.phase === 'idle'\n        ? !settingStore.get('Comfy.VueNodes.Enabled')\n        : previousStart.restoreRenderer\n\n    if (previousStart.phase === 'writingRenderer') {\n      tourStart = { ...previousStart, ownership }\n      await previousStart.write.catch(() => undefined)\n      if (ownsTourStart(ownership))\n        tourStart = { phase: 'claimed', ownership, restoreRenderer }\n    } else {\n      tourStart = { phase: 'claimed', ownership, restoreRenderer }\n    }\n    return restoreRenderer\n  }\n\n  async function claimRendererForTour(ownership: symbol): Promise<boolean> {\n    const restoreRenderer = await claimTourStart(ownership)\n    if (!ownsTourStart(ownership)) return restoreRenderer\n    if (restoreRenderer && !settingStore.get('Comfy.VueNodes.Enabled'))\n      await writeRenderer(ownership, true, restoreRenderer)\n    return restoreRenderer\n  }\n\n  async function cancelPendingStart(): Promise<void> {\n    const previousStart = tourStart\n    if (previousStart.phase === 'idle') return\n    const ownership = Symbol('cancelled-first-run-tour-start')\n    try {\n      const restoreRenderer = await claimTourStart(ownership)\n      if (\n        ownsTourStart(ownership) &&\n        restoreRenderer &&\n        settingStore.get('Comfy.VueNodes.Enabled')\n      )\n        await writeRenderer(ownership, false, restoreRenderer)\n    } finally {\n      releaseTourStart(ownership)\n    }\n  }\n\n  /** False when there is no tour to give; any renderer switch is undone. */\n  async function beginTour(\n    templateId?: string,\n    shouldCancel: () => boolean = () => false\n  ): Promise<boolean> {\n    const ownership = Symbol('first-run-tour-start')\n    // Holds only ever end a tour that is already running, and only when they\n    // change — a context lost before the tour opens (`?template=X&mode=linear`\n    // boots straight into linear mode) never produces that change. Refused\n    // here, ahead of the renderer switch below, so nothing is left to undo.\n    if (!canBeginTour(shouldCancel)) return false\n\n    const restoreRenderer = await claimRendererForTour(ownership)\n    if (!ownsTourStart(ownership) || shouldCancel()) return false\n\n    tourStart = { phase: 'previewing', ownership, restoreRenderer }\n    tourWorkflow.value = workflowStore.activeWorkflow ?? null\n    runState.value = 'idle'\n    nudgeArmed.value = false\n    registerTour(\n      'firstRun',\n      () => firstRunTourSteps(templateId, runState),\n      tourContextHolds\n    )\n    await delay(INTRO_PREVIEW_MS)\n    // The preview is long enough for the canvas to go away underneath it, and\n    // the holds watcher cannot catch that: there is no active tour to end yet.\n    const contextStillHolds = (): boolean => canvasContextHolds.value\n    const started =\n      ownsTourStart(ownership) &&\n      contextStillHolds() &&\n      !shouldCancel() &&\n      (await engine.startTour('firstRun'))\n    if (!started) {\n      await cleanUpFailedTourStart(ownership, shouldCancel)\n    } else releaseTourStart(ownership)\n    return started\n  }\n\n  return {\n    beginTour,\n    cancelPendingStart,\n    nudgeArmed: readonly(nudgeArmed),\n    tourWasCompleted: readonly(tourWasCompleted),\n    dismissNudge\n  }\n}\n\nexport const useFirstRunTourController = createSharedComposable(\n  useFirstRunTourControllerInternal\n)\n","import {\n  breakpointsTailwind,\n  createSharedComposable,\n  until,\n  useBreakpoints\n} from '@vueuse/core'\nimport { computed, ref, watch } from 'vue'\n\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useSubscription } from '@/platform/cloud/subscription/composables/useSubscription'\nimport { isCloud } from '@/platform/distribution/types'\nimport {\n  consumeFirstRunReplayRequest,\n  isFirstRunReplayRequested\n} from '@/platform/onboarding/onboardingReplay'\nimport { useOnboardingTourStore } from '@/platform/onboarding/onboardingTourStore'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type { StartupOutcome } from '@/platform/workflow/persistence/base/draftTypes'\nimport type { SharedWorkflowUrlLoadStatus } from '@/platform/workflow/sharing/composables/useSharedWorkflowUrlLoader'\nimport { useNewUserService } from '@/services/useNewUserService'\nimport { useAuthStore } from '@/stores/authStore'\nimport { useCommandStore } from '@/stores/commandStore'\n\nimport { useFirstRunTourController } from '../tour/useFirstRunTourController'\n\nconst STARTUP_DECISION_TIMEOUT_MS = 60_000\n\ntype FirstRunScreenState =\n  | { phase: 'released' }\n  | { phase: 'visible' }\n  | { phase: 'handoff'; handoffs: ReadonlySet<symbol> }\n\ntype FirstRunScreenEvent =\n  | { type: 'shown' }\n  | { type: 'dismissed' }\n  | { type: 'released' }\n  | { type: 'handoffStarted'; ownership: symbol }\n  | { type: 'handoffFinished'; ownership: symbol }\n\nfunction finishFirstRunHandoff(\n  state: FirstRunScreenState,\n  ownership: symbol\n): FirstRunScreenState {\n  if (state.phase !== 'handoff' || !state.handoffs.has(ownership)) return state\n  const handoffs = new Set(state.handoffs)\n  handoffs.delete(ownership)\n  return handoffs.size === 0\n    ? { phase: 'released' }\n    : { phase: 'handoff', handoffs }\n}\n\nfunction transitionFirstRunScreen(\n  state: FirstRunScreenState,\n  event: FirstRunScreenEvent\n): FirstRunScreenState {\n  switch (event.type) {\n    case 'shown':\n      return { phase: 'visible' }\n    case 'dismissed':\n      return state.phase === 'visible' ? { phase: 'released' } : state\n    case 'released':\n      return { phase: 'released' }\n    case 'handoffStarted':\n      return {\n        phase: 'handoff',\n        handoffs: new Set([\n          ...(state.phase === 'handoff' ? state.handoffs : []),\n          event.ownership\n        ])\n      }\n    case 'handoffFinished':\n      return finishFirstRunHandoff(state, event.ownership)\n  }\n}\n\nexport const useFirstRunEntry = createSharedComposable(() => {\n  const authStore = useAuthStore()\n  const settingStore = useSettingStore()\n  const firstRunScreen = ref<FirstRunScreenState>({ phase: 'released' })\n  const startupDecided = ref(false)\n  let authGeneration = 0\n  const isDesktopWidth =\n    useBreakpoints(breakpointsTailwind).greaterOrEqual('md')\n\n  const gettingStartedVisible = computed(\n    () => firstRunScreen.value.phase === 'visible'\n  )\n  const firstRunHoldsScreen = computed(\n    () => firstRunScreen.value.phase !== 'released'\n  )\n\n  function dispatchFirstRunScreen(event: FirstRunScreenEvent): void {\n    firstRunScreen.value = transitionFirstRunScreen(firstRunScreen.value, event)\n  }\n\n  watch(\n    () => authStore.userId,\n    (userId, previousUserId) => {\n      if (previousUserId === undefined || userId === previousUserId) return\n      authGeneration++\n      dispatchFirstRunScreen({ type: 'released' })\n      void useFirstRunTourController()\n        .cancelPendingStart()\n        .catch((error) =>\n          reportError(error, {\n            surface: 'platform',\n            errorType: 'failure_restoring_first_run_renderer_setting',\n            level: 'warning'\n          })\n        )\n      const tourStore = useOnboardingTourStore()\n      if (tourStore.activeTour === 'firstRun') tourStore.postpone()\n    },\n    { flush: 'sync' }\n  )\n\n  type FirstRunDecision = 'getting-started' | 'defer' | 'complete'\n\n  function decideFirstRun(): FirstRunDecision {\n    if (!isCloud) return 'complete'\n\n    const isNewUser =\n      isFirstRunReplayRequested(authStore.userId) ||\n      useNewUserService().isNewUser()\n    if (isNewUser === false) return 'complete'\n\n    if (!useFeatureFlags().flags.onboardingTourEnabled) return 'defer'\n    if (!isDesktopWidth.value) return 'defer'\n    if (!useSubscription().isSubscriptionEnabled()) return 'defer'\n    if (isNewUser === null) return 'defer'\n\n    return 'getting-started'\n  }\n\n  function isFirstRunCandidate(): boolean {\n    return decideFirstRun() === 'getting-started'\n  }\n\n  async function handleStartupOutcome(outcome: StartupOutcome) {\n    try {\n      await showFirstRunScreen(outcome)\n    } finally {\n      if (outcome !== 'url-intent') startupDecided.value = true\n    }\n  }\n\n  async function showFirstRunScreen(outcome: StartupOutcome) {\n    const decision = decideFirstRun()\n\n    const isReplay =\n      isFirstRunReplayRequested(authStore.userId) &&\n      decision === 'getting-started'\n    if (!isReplay) {\n      if (outcome === 'restored') return\n      if (settingStore.get('Comfy.TutorialCompleted')) return\n    }\n\n    if (outcome === 'url-intent') {\n      if (decision === 'complete') await markTutorialCompleted()\n      return\n    }\n\n    if (decision === 'getting-started') {\n      dispatchFirstRunScreen({ type: 'shown' })\n      consumeFirstRunReplayRequest(authStore.userId)\n      return\n    }\n\n    if (decision === 'complete') await markTutorialCompleted()\n    await useCommandStore().execute('Comfy.BrowseTemplates')\n  }\n\n  async function handleUrlWorkflow(\n    outcome: StartupOutcome | undefined,\n    templateId?: string,\n    sharedStatus?: SharedWorkflowUrlLoadStatus\n  ) {\n    try {\n      if (!isTourableUrlWorkflow(outcome, templateId, sharedStatus)) return\n      const shareLoaded = isSharedWorkflowLoaded(sharedStatus)\n      const ownerId = authStore.userId\n      const started = await useFirstRunTourController().beginTour(\n        shareLoaded ? undefined : templateId,\n        () => authStore.userId !== ownerId\n      )\n      if (!started) return\n      consumeFirstRunReplayRequest(ownerId)\n      await markTutorialCompleted()\n    } finally {\n      startupDecided.value = true\n    }\n  }\n\n  function isTourableUrlWorkflow(\n    outcome: StartupOutcome | undefined,\n    templateId?: string,\n    sharedStatus?: SharedWorkflowUrlLoadStatus\n  ): boolean {\n    if (outcome !== 'url-intent' || !isFirstRunCandidate()) return false\n    return templateId !== undefined || isSharedWorkflowLoaded(sharedStatus)\n  }\n\n  function isSharedWorkflowLoaded(\n    status: SharedWorkflowUrlLoadStatus | undefined\n  ): boolean {\n    return status === 'loaded' || status === 'loaded-without-assets'\n  }\n\n  let startupDecision: Promise<boolean> | undefined\n  function whenStartupDecided(): Promise<boolean> {\n    if (startupDecided.value) return Promise.resolve(true)\n    startupDecision ??= until(startupDecided).toBe(true, {\n      timeout: STARTUP_DECISION_TIMEOUT_MS,\n      throwOnTimeout: false\n    })\n    return startupDecision\n  }\n\n  async function markTutorialCompleted() {\n    try {\n      await settingStore.set('Comfy.TutorialCompleted', true)\n    } catch (error) {\n      reportError(error, {\n        surface: 'platform',\n        errorType: 'failure_writing_tutorial_completed_setting',\n        level: 'warning'\n      })\n    }\n  }\n\n  async function dismissGettingStarted() {\n    dispatchFirstRunScreen({ type: 'dismissed' })\n    await markTutorialCompleted()\n  }\n\n  async function dismissIntoFirstRunTour(templateId: string): Promise<void> {\n    const ownerId = authStore.userId\n    const ownerGeneration = authGeneration\n    const ownership = Symbol('first-run-tour-handoff')\n    dispatchFirstRunScreen({ type: 'handoffStarted', ownership })\n    try {\n      await dismissGettingStarted()\n      if (authStore.userId !== ownerId || authGeneration !== ownerGeneration)\n        return\n      await useFirstRunTourController().beginTour(\n        templateId,\n        () => authStore.userId !== ownerId || authGeneration !== ownerGeneration\n      )\n    } finally {\n      dispatchFirstRunScreen({ type: 'handoffFinished', ownership })\n    }\n  }\n\n  return {\n    gettingStartedVisible,\n    firstRunHoldsScreen,\n    whenStartupDecided,\n    handleStartupOutcome,\n    handleUrlWorkflow,\n    dismissGettingStarted,\n    dismissIntoFirstRunTour\n  }\n})\n","<template>\n  <div\n    :class=\"\n      cn(\n        'minimap-panel flex flex-col gap-2 bg-comfy-menu-bg p-3 text-sm shadow-interface',\n        isMobile ? 'mb-2' : 'mr-2'\n      )\n    \"\n    :style=\"panelStyles\"\n  >\n    <div class=\"flex items-center gap-2\">\n      <Checkbox\n        id=\"node-colors\"\n        name=\"node-colors\"\n        :model-value=\"nodeColors\"\n        @update:model-value=\"\n          (value) => updateOption('Comfy.Minimap.NodeColors', value)\n        \"\n      />\n      <i class=\"icon-[lucide--palette]\" />\n      <label for=\"node-colors\">{{ $t('minimap.nodeColors') }}</label>\n    </div>\n\n    <div class=\"flex items-center gap-2\">\n      <Checkbox\n        id=\"show-links\"\n        name=\"show-links\"\n        :model-value=\"showLinks\"\n        @update:model-value=\"\n          (value) => updateOption('Comfy.Minimap.ShowLinks', value)\n        \"\n      />\n      <i class=\"icon-[lucide--route]\" />\n      <label for=\"show-links\">{{ $t('minimap.showLinks') }}</label>\n    </div>\n\n    <div class=\"flex items-center gap-2\">\n      <Checkbox\n        id=\"show-groups\"\n        name=\"show-groups\"\n        :model-value=\"showGroups\"\n        @update:model-value=\"\n          (value) => updateOption('Comfy.Minimap.ShowGroups', value)\n        \"\n      />\n      <i class=\"icon-[lucide--frame]\" />\n      <label for=\"show-groups\">{{ $t('minimap.showGroups') }}</label>\n    </div>\n\n    <div class=\"flex items-center gap-2\">\n      <Checkbox\n        id=\"render-bypass\"\n        name=\"render-bypass\"\n        :model-value=\"renderBypass\"\n        @update:model-value=\"\n          (value) => updateOption('Comfy.Minimap.RenderBypassState', value)\n        \"\n      />\n      <i class=\"icon-[lucide--circle-slash-2]\" />\n      <label for=\"render-bypass\">{{ $t('minimap.renderBypassState') }}</label>\n    </div>\n\n    <div class=\"flex items-center gap-2\">\n      <Checkbox\n        id=\"render-error\"\n        name=\"render-error\"\n        :model-value=\"renderError\"\n        @update:model-value=\"\n          (value) => updateOption('Comfy.Minimap.RenderErrorState', value)\n        \"\n      />\n      <i class=\"icon-[lucide--message-circle-warning]\" />\n      <label for=\"render-error\">{{ $t('minimap.renderErrorState') }}</label>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { CSSProperties, Ref } from 'vue'\nimport type { CheckboxRootEmits } from 'reka-ui'\n\nimport Checkbox from '@/components/ui/checkbox/Checkbox.vue'\nimport type { MinimapSettingsKey } from '@/renderer/extensions/minimap/types'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ndefineProps<{\n  panelStyles: CSSProperties\n  nodeColors: boolean\n  showLinks: boolean\n  showGroups: boolean\n  renderBypass: boolean\n  renderError: boolean\n  isMobile: Ref<boolean> | boolean\n}>()\n\nconst emit = defineEmits<{\n  updateOption: [key: MinimapSettingsKey, value: boolean]\n}>()\n\nfunction updateOption(\n  key: MinimapSettingsKey,\n  value: CheckboxRootEmits['update:modelValue'][0]\n) {\n  if (typeof value === 'boolean') emit('updateOption', key, value)\n}\n</script>\n","<template>\n  <div\n    v-if=\"visible && initialized\"\n    ref=\"minimapRef\"\n    :class=\"\n      cn(\n        'minimap-main-container absolute right-0 bottom-[54px] z-1000 flex',\n        isMobile ? 'flex-col' : 'flex-row'\n      )\n    \"\n  >\n    <MiniMapPanel\n      v-if=\"showOptionsPanel\"\n      :panel-styles=\"panelStyles\"\n      :node-colors=\"nodeColors\"\n      :show-links=\"showLinks\"\n      :show-groups=\"showGroups\"\n      :render-bypass=\"renderBypass\"\n      :render-error=\"renderError\"\n      :is-mobile=\"isMobile\"\n      @update-option=\"updateOption\"\n    />\n\n    <div\n      ref=\"containerRef\"\n      class=\"litegraph-minimap relative border border-interface-stroke bg-comfy-menu-bg shadow-interface\"\n      data-testid=\"minimap-container\"\n      :aria-label=\"`${$t('minimap.label')}. ${$t('minimap.highlightedNodes', { count: decorationCount })}`\"\n      :style=\"containerStyles\"\n    >\n      <Button\n        class=\"absolute top-0 left-0 z-10\"\n        size=\"icon\"\n        variant=\"muted-textonly\"\n        :aria-label=\"$t('g.settings')\"\n        @click.stop=\"toggleOptionsPanel\"\n      >\n        <i class=\"icon-[lucide--settings-2]\" />\n      </Button>\n      <Button\n        class=\"absolute top-0 right-0 z-10\"\n        size=\"icon\"\n        variant=\"muted-textonly\"\n        :aria-label=\"$t('g.close')\"\n        data-testid=\"close-minimap-button\"\n        @click.stop=\"() => commandStore.execute('Comfy.Canvas.ToggleMinimap')\"\n      >\n        <i class=\"icon-[lucide--x]\" />\n      </Button>\n\n      <hr\n        class=\"absolute top-6 h-px border-0 bg-node-component-border\"\n        :style=\"{\n          width: containerStyles.width\n        }\"\n      />\n\n      <canvas\n        ref=\"canvasRef\"\n        :width=\"width\"\n        :height=\"height\"\n        class=\"minimap-canvas\"\n        data-testid=\"minimap-canvas\"\n      />\n\n      <div\n        class=\"minimap-viewport\"\n        :style=\"viewportStyles\"\n        data-testid=\"minimap-viewport\"\n      />\n\n      <div\n        class=\"absolute inset-0 touch-none\"\n        data-testid=\"minimap-interaction-overlay\"\n        @pointerdown=\"handlePointerDown\"\n        @pointermove=\"handlePointerMove\"\n        @pointerup=\"handlePointerUp\"\n        @pointerleave=\"handlePointerUp\"\n        @pointercancel=\"handlePointerCancel\"\n        @wheel=\"handleWheel\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { breakpointsTailwind, useBreakpoints } from '@vueuse/core'\nimport { onMounted, onUnmounted, ref, useTemplateRef } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useMinimap } from '@/renderer/extensions/minimap/composables/useMinimap'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport MiniMapPanel from './MiniMapPanel.vue'\n\nconst isMobile = useBreakpoints(breakpointsTailwind).smaller('md')\n\nconst commandStore = useCommandStore()\nconst minimapRef = ref<HTMLDivElement>()\nconst containerRef = useTemplateRef<HTMLDivElement>('containerRef')\nconst canvasRef = useTemplateRef<HTMLCanvasElement>('canvasRef')\n\nconst {\n  initialized,\n  visible,\n  decorationCount,\n  containerStyles,\n  viewportStyles,\n  width,\n  height,\n  panelStyles,\n  nodeColors,\n  showLinks,\n  showGroups,\n  renderBypass,\n  renderError,\n  updateOption,\n  destroy,\n  handlePointerDown,\n  handlePointerMove,\n  handlePointerUp,\n  handlePointerCancel,\n  handleWheel,\n  setMinimapRef\n} = useMinimap({\n  containerRefMaybe: containerRef,\n  canvasRefMaybe: canvasRef\n})\n\nconst showOptionsPanel = ref(false)\n\nconst toggleOptionsPanel = () => {\n  showOptionsPanel.value = !showOptionsPanel.value\n}\n\nonMounted(() => {\n  if (minimapRef.value) {\n    setMinimapRef(minimapRef.value)\n  }\n})\n\nonUnmounted(() => {\n  destroy()\n})\n</script>\n\n<style scoped>\n.litegraph-minimap {\n  overflow: hidden;\n}\n\n.minimap-canvas {\n  display: block;\n  width: 100%;\n  height: 100%;\n  pointer-events: none;\n}\n\n.minimap-viewport {\n  position: absolute;\n  top: 0;\n  left: 0;\n  pointer-events: none;\n}\n</style>\n","/**\n * Parse `#pragma passes N` to get multi-pass count.\n * Mirrors backend _detect_pass_count() in nodes_glsl.py.\n */\nexport function detectPassCount(source: string): number {\n  const match = source.match(/#pragma\\s+passes\\s+(\\d+)/)\n  if (match) return Math.max(1, parseInt(match[1], 10))\n  return 1\n}\n","export interface SharedGLHandle {\n  canvas: OffscreenCanvas\n  gl: WebGL2RenderingContext\n  release: () => void\n}\n\ninterface SharedGL {\n  canvas: OffscreenCanvas\n  gl: WebGL2RenderingContext\n  refs: number\n}\n\nlet current: SharedGL | null = null\n\nfunction loseContext(gl: WebGL2RenderingContext): void {\n  gl.getExtension('WEBGL_lose_context')?.loseContext()\n}\n\nfunction createSharedGL(): SharedGL | null {\n  const canvas = new OffscreenCanvas(1, 1)\n  const gl = canvas.getContext('webgl2', {\n    alpha: true,\n    premultipliedAlpha: false,\n    preserveDrawingBuffer: true\n  })\n  if (!gl) return null\n\n  if (!gl.getExtension('EXT_color_buffer_float')) {\n    loseContext(gl)\n    return null\n  }\n\n  gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true)\n  return { canvas, gl, refs: 0 }\n}\n\nexport function acquireSharedGL(): SharedGLHandle | null {\n  if (current?.gl.isContextLost()) current = null\n\n  current ??= createSharedGL()\n  if (!current) return null\n\n  const entry = current\n  entry.refs++\n  let released = false\n  return {\n    canvas: entry.canvas,\n    gl: entry.gl,\n    release() {\n      if (released) return\n      released = true\n      entry.refs--\n      if (entry.refs > 0) return\n      if (current === entry) current = null\n      loseContext(entry.gl)\n    }\n  }\n}\n","import { detectPassCount } from '@/renderer/glsl/glslUtils'\nimport { acquireSharedGL } from '@/renderer/glsl/sharedGLContext'\n\nimport type { SharedGLHandle } from '@/renderer/glsl/sharedGLContext'\n\nconst VERTEX_SHADER_SOURCE = `#version 300 es\nout vec2 v_texCoord;\nvoid main() {\n    vec2 verts[3] = vec2[](vec2(-1, -1), vec2(3, -1), vec2(-1, 3));\n    v_texCoord = verts[gl_VertexID] * 0.5 + 0.5;\n    gl_Position = vec4(verts[gl_VertexID], 0, 1);\n}\n`\n\nconst MAX_PASSES = 32\n\nexport interface GLSLRendererConfig {\n  maxInputs: number\n  maxFloatUniforms: number\n  maxIntUniforms: number\n  maxBoolUniforms: number\n  maxCurves: number\n}\n\nconst DEFAULT_CONFIG: GLSLRendererConfig = {\n  maxInputs: 5,\n  maxFloatUniforms: 20,\n  maxIntUniforms: 20,\n  maxBoolUniforms: 10,\n  maxCurves: 4\n}\n\ninterface CompileResult {\n  success: boolean\n  log: string\n}\n\nfunction createTexture(gl: WebGL2RenderingContext): WebGLTexture | null {\n  return gl.createTexture()\n}\n\nfunction createFramebuffer(\n  gl: WebGL2RenderingContext\n): WebGLFramebuffer | null {\n  return gl.createFramebuffer()\n}\n\nfunction createProgram(gl: WebGL2RenderingContext): WebGLProgram | null {\n  return gl.createProgram()\n}\n\nfunction compileShader(\n  gl: WebGL2RenderingContext,\n  type: GLenum,\n  source: string\n): WebGLShader {\n  const shader = gl.createShader(type)\n  if (!shader) throw new Error('Failed to create shader')\n\n  gl.shaderSource(shader, source)\n  gl.compileShader(shader)\n\n  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {\n    const log = gl.getShaderInfoLog(shader) ?? 'Compilation failed'\n    gl.deleteShader(shader)\n    throw new Error(log)\n  }\n  return shader\n}\n\nexport function useGLSLRenderer(config: GLSLRendererConfig = DEFAULT_CONFIG) {\n  const {\n    maxInputs,\n    maxFloatUniforms,\n    maxIntUniforms,\n    maxBoolUniforms,\n    maxCurves\n  } = config\n\n  const uniformNames = [\n    'u_resolution',\n    'u_pass',\n    ...Array.from({ length: maxInputs }, (_, i) => `u_image${i}`),\n    ...Array.from({ length: maxFloatUniforms }, (_, i) => `u_float${i}`),\n    ...Array.from({ length: maxIntUniforms }, (_, i) => `u_int${i}`),\n    ...Array.from({ length: maxBoolUniforms }, (_, i) => `u_bool${i}`),\n    ...Array.from({ length: maxCurves }, (_, i) => `u_curve${i}`)\n  ]\n\n  let sharedGL: SharedGLHandle | null = null\n  let canvas: OffscreenCanvas | null = null\n  let gl: WebGL2RenderingContext | null = null\n  let vertexShader: WebGLShader | null = null\n  let program: WebGLProgram | null = null\n  let fragmentShader: WebGLShader | null = null\n  let pingPongFBOs: [WebGLFramebuffer, WebGLFramebuffer] | null = null\n  let pingPongTextures: [WebGLTexture, WebGLTexture] | null = null\n  let fallbackTexture: WebGLTexture | null = null\n  const inputTextures: (WebGLTexture | null)[] = Array.from<null>({\n    length: maxInputs\n  }).fill(null)\n  const curveTextures: (WebGLTexture | null)[] = Array.from<null>({\n    length: maxCurves\n  }).fill(null)\n  const uniformLocations = new Map<string, WebGLUniformLocation | null>()\n  let passCount = 1\n  let disposed = false\n  let lastCompiledSource: string | null = null\n  let fboWidth = 0\n  let fboHeight = 0\n\n  function initPingPongFBOs(\n    ctx: WebGL2RenderingContext,\n    width: number,\n    height: number\n  ): void {\n    const fbos: WebGLFramebuffer[] = []\n    const textures: WebGLTexture[] = []\n\n    try {\n      for (let i = 0; i < 2; i++) {\n        const tex = createTexture(ctx)\n        if (!tex) throw new Error('Failed to create ping-pong texture')\n        ctx.bindTexture(ctx.TEXTURE_2D, tex)\n        ctx.texImage2D(\n          ctx.TEXTURE_2D,\n          0,\n          ctx.RGBA16F,\n          width,\n          height,\n          0,\n          ctx.RGBA,\n          ctx.HALF_FLOAT,\n          null\n        )\n        ctx.texParameteri(ctx.TEXTURE_2D, ctx.TEXTURE_MIN_FILTER, ctx.LINEAR)\n        ctx.texParameteri(ctx.TEXTURE_2D, ctx.TEXTURE_MAG_FILTER, ctx.LINEAR)\n        ctx.texParameteri(ctx.TEXTURE_2D, ctx.TEXTURE_WRAP_S, ctx.CLAMP_TO_EDGE)\n        ctx.texParameteri(ctx.TEXTURE_2D, ctx.TEXTURE_WRAP_T, ctx.CLAMP_TO_EDGE)\n\n        const fbo = createFramebuffer(ctx)\n        if (!fbo) throw new Error('Failed to create ping-pong framebuffer')\n        ctx.bindFramebuffer(ctx.FRAMEBUFFER, fbo)\n        ctx.framebufferTexture2D(\n          ctx.FRAMEBUFFER,\n          ctx.COLOR_ATTACHMENT0,\n          ctx.TEXTURE_2D,\n          tex,\n          0\n        )\n        const status = ctx.checkFramebufferStatus(ctx.FRAMEBUFFER)\n        if (status !== ctx.FRAMEBUFFER_COMPLETE)\n          throw new Error(`Ping-pong framebuffer incomplete: ${status}`)\n\n        fbos.push(fbo)\n        textures.push(tex)\n      }\n    } catch (error) {\n      for (const fbo of fbos) ctx.deleteFramebuffer(fbo)\n      for (const tex of textures) ctx.deleteTexture(tex)\n      ctx.bindFramebuffer(ctx.FRAMEBUFFER, null)\n      ctx.bindTexture(ctx.TEXTURE_2D, null)\n      throw error\n    }\n\n    ctx.bindFramebuffer(ctx.FRAMEBUFFER, null)\n    ctx.bindTexture(ctx.TEXTURE_2D, null)\n\n    pingPongFBOs = fbos as [WebGLFramebuffer, WebGLFramebuffer]\n    pingPongTextures = textures as [WebGLTexture, WebGLTexture]\n  }\n\n  function destroyPingPongFBOs(): void {\n    if (!gl) return\n    if (pingPongFBOs) {\n      for (const fbo of pingPongFBOs) gl.deleteFramebuffer(fbo)\n      pingPongFBOs = null\n    }\n    if (pingPongTextures) {\n      for (const tex of pingPongTextures) gl.deleteTexture(tex)\n      pingPongTextures = null\n    }\n  }\n\n  function cacheUniformLocations(): void {\n    if (!program || !gl) return\n    for (const name of uniformNames) {\n      uniformLocations.set(name, gl.getUniformLocation(program, name))\n    }\n  }\n\n  function getFallbackTexture(): WebGLTexture {\n    if (!gl) throw new Error('Renderer not initialized')\n    if (!fallbackTexture) {\n      const tex = createTexture(gl)\n      if (!tex) throw new Error('Failed to create fallback texture')\n      fallbackTexture = tex\n      gl.bindTexture(gl.TEXTURE_2D, fallbackTexture)\n      gl.texImage2D(\n        gl.TEXTURE_2D,\n        0,\n        gl.RGBA,\n        1,\n        1,\n        0,\n        gl.RGBA,\n        gl.UNSIGNED_BYTE,\n        new Uint8Array([0, 0, 0, 255])\n      )\n    }\n    return fallbackTexture\n  }\n\n  function init(width: number, height: number): boolean {\n    if (disposed) return false\n\n    try {\n      sharedGL = acquireSharedGL()\n      if (!sharedGL) return false\n\n      canvas = sharedGL.canvas\n      gl = sharedGL.gl\n\n      canvas.width = width\n      canvas.height = height\n      gl.viewport(0, 0, width, height)\n\n      vertexShader = compileShader(gl, gl.VERTEX_SHADER, VERTEX_SHADER_SOURCE)\n      initPingPongFBOs(gl, width, height)\n      fboWidth = width\n      fboHeight = height\n      return true\n    } catch {\n      dispose()\n      return false\n    }\n  }\n\n  function compileFragment(source: string): CompileResult {\n    if (disposed || !gl) return { success: false, log: 'Engine disposed' }\n\n    passCount = Math.min(detectPassCount(source), MAX_PASSES)\n\n    if (source === lastCompiledSource && program) {\n      return { success: true, log: '' }\n    }\n    lastCompiledSource = source\n\n    if (fragmentShader) {\n      gl.deleteShader(fragmentShader)\n      fragmentShader = null\n    }\n    if (program) {\n      gl.deleteProgram(program)\n      program = null\n    }\n    uniformLocations.clear()\n\n    try {\n      fragmentShader = compileShader(gl, gl.FRAGMENT_SHADER, source)\n    } catch (e: unknown) {\n      const msg = e instanceof Error ? e.message : String(e)\n      return { success: false, log: msg }\n    }\n\n    const prog = createProgram(gl)\n    if (!prog) return { success: false, log: 'Failed to create program' }\n\n    gl.attachShader(prog, vertexShader!)\n    gl.attachShader(prog, fragmentShader)\n    gl.linkProgram(prog)\n\n    if (!gl.getProgramParameter(prog, gl.LINK_STATUS)) {\n      const log = gl.getProgramInfoLog(prog) ?? 'Link failed'\n      gl.deleteProgram(prog)\n      return { success: false, log }\n    }\n\n    program = prog\n    cacheUniformLocations()\n    return { success: true, log: '' }\n  }\n\n  function setResolution(width: number, height: number): void {\n    if (disposed || !gl || !canvas) return\n    if (canvas.width !== width || canvas.height !== height) {\n      canvas.width = width\n      canvas.height = height\n    }\n    gl.viewport(0, 0, width, height)\n    if (fboWidth !== width || fboHeight !== height) {\n      destroyPingPongFBOs()\n      initPingPongFBOs(gl, width, height)\n      fboWidth = width\n      fboHeight = height\n    }\n  }\n\n  function setFloatUniform(index: number, value: number): void {\n    if (disposed || !program || !gl) return\n    const loc = uniformLocations.get(`u_float${index}`)\n    if (loc != null) {\n      gl.useProgram(program)\n      gl.uniform1f(loc, value)\n    }\n  }\n\n  function setIntUniform(index: number, value: number): void {\n    if (disposed || !program || !gl) return\n    const loc = uniformLocations.get(`u_int${index}`)\n    if (loc != null) {\n      gl.useProgram(program)\n      gl.uniform1i(loc, value)\n    }\n  }\n\n  function setBoolUniform(index: number, value: boolean): void {\n    if (disposed || !program || !gl) return\n    const loc = uniformLocations.get(`u_bool${index}`)\n    if (loc != null) {\n      gl.useProgram(program)\n      gl.uniform1i(loc, value ? 1 : 0)\n    }\n  }\n\n  function bindCurveTexture(index: number, lut: Float32Array): void {\n    if (disposed || !gl) return\n    if (index < 0 || index >= maxCurves) return\n\n    if (curveTextures[index]) {\n      gl.deleteTexture(curveTextures[index])\n      curveTextures[index] = null\n    }\n\n    const texture = createTexture(gl)\n    if (!texture) return\n\n    const unit = maxInputs + index\n    gl.activeTexture(gl.TEXTURE0 + unit)\n    gl.bindTexture(gl.TEXTURE_2D, texture)\n    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, false)\n    gl.texImage2D(\n      gl.TEXTURE_2D,\n      0,\n      gl.R16F,\n      lut.length,\n      1,\n      0,\n      gl.RED,\n      gl.FLOAT,\n      lut\n    )\n    gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true)\n    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)\n    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)\n    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)\n    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)\n\n    curveTextures[index] = texture\n  }\n\n  function bindInputImage(\n    index: number,\n    image: HTMLImageElement | ImageBitmap\n  ): void {\n    if (disposed || !gl) return\n    if (index < 0 || index >= maxInputs) {\n      throw new Error(\n        `Input index ${index} out of range (max ${maxInputs - 1})`\n      )\n    }\n\n    if (inputTextures[index]) {\n      gl.deleteTexture(inputTextures[index])\n      inputTextures[index] = null\n    }\n\n    const texture = createTexture(gl)\n    if (!texture) return\n\n    gl.activeTexture(gl.TEXTURE0 + index)\n    gl.bindTexture(gl.TEXTURE_2D, texture)\n    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)\n    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)\n    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)\n    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)\n    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA, gl.RGBA, gl.UNSIGNED_BYTE, image)\n\n    inputTextures[index] = texture\n  }\n\n  function clearInputImage(index: number): void {\n    if (disposed || !gl) return\n    if (index < 0 || index >= maxInputs) return\n    const texture = inputTextures[index]\n    if (texture) {\n      gl.deleteTexture(texture)\n      inputTextures[index] = null\n    }\n  }\n\n  function isContextLost(): boolean {\n    return gl?.isContextLost() ?? false\n  }\n\n  function render(): void {\n    if (disposed || !program || !pingPongFBOs || !gl || !canvas) return\n\n    if (canvas.width !== fboWidth || canvas.height !== fboHeight) {\n      canvas.width = fboWidth\n      canvas.height = fboHeight\n    }\n    gl.viewport(0, 0, fboWidth, fboHeight)\n\n    gl.useProgram(program)\n    gl.disable(gl.BLEND)\n\n    const resLoc = uniformLocations.get('u_resolution')\n    if (resLoc != null) {\n      gl.uniform2f(resLoc, canvas.width, canvas.height)\n    }\n\n    for (let i = 0; i < maxInputs; i++) {\n      const loc = uniformLocations.get(`u_image${i}`)\n      if (loc != null) {\n        gl.activeTexture(gl.TEXTURE0 + i)\n        gl.bindTexture(gl.TEXTURE_2D, inputTextures[i] ?? getFallbackTexture())\n        gl.uniform1i(loc, i)\n      }\n    }\n\n    for (let i = 0; i < maxCurves; i++) {\n      const loc = uniformLocations.get(`u_curve${i}`)\n      if (loc != null && curveTextures[i]) {\n        const unit = maxInputs + i\n        gl.activeTexture(gl.TEXTURE0 + unit)\n        gl.bindTexture(gl.TEXTURE_2D, curveTextures[i])\n        gl.uniform1i(loc, unit)\n      }\n    }\n\n    for (let pass = 0; pass < passCount; pass++) {\n      const passLoc = uniformLocations.get('u_pass')\n      if (passLoc != null) gl.uniform1i(passLoc, pass)\n\n      const isLastPass = pass === passCount - 1\n      const writeIdx = pass % 2\n\n      if (isLastPass) {\n        gl.bindFramebuffer(gl.FRAMEBUFFER, null)\n        gl.drawBuffers([gl.BACK])\n      } else {\n        gl.bindFramebuffer(gl.FRAMEBUFFER, pingPongFBOs[writeIdx])\n        gl.drawBuffers([gl.COLOR_ATTACHMENT0])\n      }\n\n      // Match backend behavior: pass > 0 binds previous pass output to\n      // texture unit 0, overriding u_image0 so shaders read the previous\n      // pass result via the same sampler.\n      if (pass > 0) {\n        const sourceTexture = pingPongTextures![(pass - 1) % 2]\n        gl.activeTexture(gl.TEXTURE0)\n        gl.bindTexture(gl.TEXTURE_2D, sourceTexture)\n      }\n\n      gl.clearColor(0, 0, 0, 0)\n      gl.clear(gl.COLOR_BUFFER_BIT)\n      gl.drawArrays(gl.TRIANGLES, 0, 3)\n    }\n  }\n\n  function readPixels(): ImageData {\n    if (!gl || !canvas) throw new Error('Renderer not initialized')\n    const w = canvas.width\n    const h = canvas.height\n    const pixels = new Uint8ClampedArray(w * h * 4)\n\n    gl.pixelStorei(gl.PACK_ROW_LENGTH, 0)\n    gl.readPixels(0, 0, w, h, gl.RGBA, gl.UNSIGNED_BYTE, pixels)\n\n    return new ImageData(pixels, w, h)\n  }\n\n  async function toBlob(): Promise<Blob> {\n    if (!canvas) throw new Error('Renderer not initialized')\n    return canvas.convertToBlob({ type: 'image/webp', quality: 0.92 })\n  }\n\n  function dispose(): void {\n    if (disposed) return\n    disposed = true\n    if (!gl) return\n\n    for (const tex of inputTextures) {\n      if (tex) gl.deleteTexture(tex)\n    }\n    inputTextures.fill(null)\n\n    for (const tex of curveTextures) {\n      if (tex) gl.deleteTexture(tex)\n    }\n    curveTextures.fill(null)\n\n    if (fallbackTexture) {\n      gl.deleteTexture(fallbackTexture)\n      fallbackTexture = null\n    }\n\n    destroyPingPongFBOs()\n\n    if (fragmentShader) {\n      gl.deleteShader(fragmentShader)\n      fragmentShader = null\n    }\n    if (vertexShader) {\n      gl.deleteShader(vertexShader)\n      vertexShader = null\n    }\n\n    if (program) {\n      gl.deleteProgram(program)\n      program = null\n    }\n\n    uniformLocations.clear()\n\n    sharedGL?.release()\n    sharedGL = null\n    gl = null\n    canvas = null\n  }\n\n  return {\n    init,\n    compileFragment,\n    setResolution,\n    setFloatUniform,\n    setIntUniform,\n    setBoolUniform,\n    bindCurveTexture,\n    bindInputImage,\n    clearInputImage,\n    isContextLost,\n    render,\n    readPixels,\n    toBlob,\n    dispose\n  }\n}\n","import { computed } from 'vue'\n\nimport type { ComputedRef } from 'vue'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { SUBGRAPH_INPUT_ID } from '@/lib/litegraph/src/constants'\nimport type { Subgraph } from '@/lib/litegraph/src/subgraph/Subgraph'\nimport type { UUID } from '@/utils/uuid'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\n\nimport { isCurveData } from '@/components/curve/curveUtils'\nimport type { CurveData } from '@/components/curve/types'\nimport { createPromotedHostWidgetIdLookup } from '@/core/graph/subgraph/promotionUtils'\nimport type { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport type { GLSLRendererConfig } from '@/renderer/glsl/useGLSLRenderer'\nimport { hexToInt } from '@/utils/colorUtil'\nimport type { NodeId } from '@/types/nodeId'\nimport type { WidgetId } from '@/types/widgetId'\nimport { widgetId } from '@/types/widgetId'\n\ninterface AutogrowGroup {\n  max: number\n  min: number\n  prefix?: string\n}\n\ninterface UniformSource {\n  nodeId: NodeId\n  widgetName: string\n  hostWidgetId?: WidgetId\n  /** Fallback getter for widgets not registered in widgetValueStore (e.g. hidden computed widgets). */\n  directValue: () => unknown\n}\n\ninterface UniformSources {\n  floats: UniformSource[]\n  ints: UniformSource[]\n  bools: UniformSource[]\n  curves: UniformSource[]\n}\n\nexport function getAutogrowLimits(node: LGraphNode): GLSLRendererConfig {\n  const defaults: GLSLRendererConfig = {\n    maxInputs: 5,\n    maxFloatUniforms: 20,\n    maxIntUniforms: 20,\n    maxBoolUniforms: 10,\n    maxCurves: 4\n  }\n\n  if (!('comfyDynamic' in node)) return defaults\n\n  const dynamic: unknown = node.comfyDynamic\n  if (\n    typeof dynamic !== 'object' ||\n    dynamic === null ||\n    !('autogrow' in dynamic)\n  )\n    return defaults\n\n  const groups = dynamic.autogrow as\n    | Record<string, AutogrowGroup | undefined>\n    | undefined\n  if (!groups) return defaults\n\n  const images = groups['images']\n  const floats = groups['floats']\n  const ints = groups['ints']\n  const bools = groups['bools']\n  const curves = groups['curves']\n\n  return {\n    maxInputs: images?.max ?? defaults.maxInputs,\n    maxFloatUniforms: floats?.max ?? defaults.maxFloatUniforms,\n    maxIntUniforms: ints?.max ?? defaults.maxIntUniforms,\n    maxBoolUniforms: bools?.max ?? defaults.maxBoolUniforms,\n    maxCurves: curves?.max ?? defaults.maxCurves\n  }\n}\n\nexport function extractUniformSources(\n  glslNode: LGraphNode,\n  subgraph: Subgraph,\n  subgraphNode?: SubgraphNode\n): UniformSources {\n  const floats: UniformSource[] = []\n  const ints: UniformSource[] = []\n  const bools: UniformSource[] = []\n  const curves: UniformSource[] = []\n\n  const hostWidgetIdForSource = subgraphNode\n    ? createPromotedHostWidgetIdLookup(subgraphNode)\n    : undefined\n\n  for (const [index, input] of glslNode.inputs.entries()) {\n    const link = glslNode.getInputLink(index)\n    if (!link || link.origin_id === SUBGRAPH_INPUT_ID) continue\n\n    const sourceNode = subgraph.getNodeById(link.origin_id)\n    if (!sourceNode?.widgets?.length) continue\n\n    const inputName = input.name\n    const dotIndex = inputName.indexOf('.')\n    if (dotIndex === -1) continue\n\n    const prefix = inputName.slice(0, dotIndex)\n    if (link.origin_slot >= sourceNode.widgets.length) continue\n    const widget = sourceNode.widgets[link.origin_slot]\n    const source: UniformSource = {\n      nodeId: sourceNode.id,\n      widgetName: widget.name,\n      hostWidgetId: hostWidgetIdForSource?.(sourceNode.id, widget.name),\n      directValue: () => widget.value\n    }\n\n    if (prefix === 'floats') floats.push(source)\n    else if (prefix === 'ints') ints.push(source)\n    else if (prefix === 'bools') bools.push(source)\n    else if (prefix === 'curves') curves.push(source)\n  }\n\n  return { floats, ints, bools, curves }\n}\n\nexport function toNumber(v: unknown): number {\n  if (typeof v === 'string' && v.startsWith('#')) return hexToInt(v)\n  return Number(v) || 0\n}\n\nexport function useGLSLUniforms(\n  graphId: ComputedRef<UUID | undefined>,\n  nodeId: ComputedRef<NodeId | undefined>,\n  nodeRef: ComputedRef<LGraphNode | null>,\n  uniformSources: ComputedRef<UniformSources | null>,\n  rendererConfig: ComputedRef<GLSLRendererConfig>\n) {\n  const widgetValueStore = useWidgetValueStore()\n\n  function collectValues<T>(\n    subgraphSources: UniformSource[] | undefined,\n    groupName: string,\n    uniformPrefix: string,\n    maxCount: number,\n    coerce: (value: unknown) => T,\n    defaultValue: T\n  ): T[] {\n    const gId = graphId.value\n    if (!gId) return []\n\n    if (subgraphSources) {\n      return subgraphSources.map(\n        ({ nodeId: nId, widgetName, hostWidgetId, directValue }) => {\n          const widget = widgetValueStore.getWidget(\n            hostWidgetId ?? widgetId(gId, nId, widgetName)\n          )\n          return coerce(widget?.value ?? directValue() ?? defaultValue)\n        }\n      )\n    }\n\n    const nId = nodeId.value\n    const node = nodeRef.value\n    if (nId == null || !node) return []\n\n    const values: T[] = []\n    for (let i = 0; i < maxCount; i++) {\n      const inputName = `${groupName}.${uniformPrefix}${i}`\n      const widget = widgetValueStore.getWidget(widgetId(gId, nId, inputName))\n      if (widget !== undefined) {\n        values.push(coerce(widget.value))\n        continue\n      }\n\n      const slot = node.inputs.findIndex((inp) => inp.name === inputName)\n      if (slot < 0) break\n\n      const link = node.getInputLink(slot)\n      if (!link) break\n      const upstreamNode = node.getInputNode(slot)\n      if (!upstreamNode) break\n      const upstreamWidgets = widgetValueStore.getNodeWidgets(\n        gId,\n        upstreamNode.id\n      )\n      if (\n        upstreamWidgets.length === 0 ||\n        link.origin_slot >= upstreamWidgets.length\n      )\n        break\n      values.push(coerce(upstreamWidgets[link.origin_slot].value))\n    }\n    return values\n  }\n\n  const toBool = (v: unknown): boolean => Boolean(v)\n\n  const floatValues = computed(() =>\n    collectValues(\n      uniformSources.value?.floats,\n      'floats',\n      'u_float',\n      rendererConfig.value.maxFloatUniforms,\n      toNumber,\n      0\n    )\n  )\n\n  const intValues = computed(() =>\n    collectValues(\n      uniformSources.value?.ints,\n      'ints',\n      'u_int',\n      rendererConfig.value.maxIntUniforms,\n      toNumber,\n      0\n    )\n  )\n\n  const boolValues = computed(() =>\n    collectValues(\n      uniformSources.value?.bools,\n      'bools',\n      'u_bool',\n      rendererConfig.value.maxBoolUniforms,\n      toBool,\n      false\n    )\n  )\n\n  const curveValues = computed((): CurveData[] => {\n    const gId = graphId.value\n    if (!gId) return []\n\n    const sources = uniformSources.value?.curves\n    if (sources && sources.length > 0) {\n      return sources\n        .map(({ nodeId: nId, widgetName, hostWidgetId, directValue }) => {\n          const widget = widgetValueStore.getWidget(\n            hostWidgetId ?? widgetId(gId, nId, widgetName)\n          )\n          const value = widget?.value ?? directValue()\n          return isCurveData(value) ? value : null\n        })\n        .filter((v): v is CurveData => v !== null)\n    }\n\n    const node = nodeRef.value\n    const nId = nodeId.value\n    if (nId == null || !node?.inputs) return []\n\n    const values: CurveData[] = []\n    const max = rendererConfig.value.maxCurves\n    for (let i = 0; i < max; i++) {\n      const inputName = `curves.u_curve${i}`\n\n      const widget = widgetValueStore.getWidget(widgetId(gId, nId, inputName))\n      if (widget && isCurveData(widget.value)) {\n        values.push(widget.value)\n        continue\n      }\n\n      const slot = node.inputs.findIndex((inp) => inp.name === inputName)\n      if (slot < 0) break\n\n      const upstreamNode = node.getInputNode(slot)\n      if (!upstreamNode) break\n\n      const upstreamWidgets = widgetValueStore.getNodeWidgets(\n        gId,\n        upstreamNode.id\n      )\n      const curveWidget = upstreamWidgets.find((w) => isCurveData(w.value))\n      if (!curveWidget) break\n      values.push(curveWidget.value as CurveData)\n    }\n    return values\n  })\n\n  return {\n    floatValues,\n    intValues,\n    boolValues,\n    curveValues\n  }\n}\n","import type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { SUBGRAPH_INPUT_ID } from '@/lib/litegraph/src/constants'\n\nexport const GLSL_NODE_TYPE = 'GLSLShader'\nexport const DEBOUNCE_MS = 50\nexport const DEFAULT_SIZE = 512\nconst MAX_PREVIEW_DIMENSION = 1024\n\nexport function normalizeDimension(value: unknown): number {\n  const parsed = Number(value)\n  if (!Number.isFinite(parsed) || parsed <= 0) return DEFAULT_SIZE\n  return parsed\n}\n\nexport function clampResolution(w: number, h: number): [number, number] {\n  const maxDim = Math.max(w, h)\n  if (maxDim <= MAX_PREVIEW_DIMENSION) return [w, h]\n  const scale = MAX_PREVIEW_DIMENSION / maxDim\n  return [Math.round(w * scale), Math.round(h * scale)]\n}\n\nexport function getImageThroughSubgraphBoundary(\n  node: LGraphNode,\n  slot: number,\n  ownerSubgraphNode: LGraphNode\n): HTMLImageElement | undefined {\n  const graph = node.graph\n  if (!graph) return undefined\n\n  const link = node.getInputLink(slot)\n  if (!link || link.origin_id !== SUBGRAPH_INPUT_ID) return undefined\n\n  const outerUpstream = ownerSubgraphNode.getInputNode(link.origin_slot)\n  if (!outerUpstream?.imgs?.length) return undefined\n\n  return outerUpstream.imgs[0]\n}\n","import { debounce } from 'es-toolkit/compat'\nimport { computed, effectScope, onScopeDispose, ref, toValue, watch } from 'vue'\n\nimport type { ComputedRef, EffectScope, MaybeRefOrGetter, Ref } from 'vue'\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport type { Subgraph } from '@/lib/litegraph/src/subgraph/Subgraph'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { widgetId } from '@/types/widgetId'\n\nimport { curveDataToFloatLUT } from '@/components/curve/curveUtils'\nimport type { GLSLRendererConfig } from '@/renderer/glsl/useGLSLRenderer'\nimport { useGLSLRenderer } from '@/renderer/glsl/useGLSLRenderer'\nimport {\n  extractUniformSources,\n  getAutogrowLimits,\n  useGLSLUniforms\n} from '@/renderer/glsl/useGLSLUniforms'\nimport {\n  createSharedObjectUrl,\n  releaseSharedObjectUrl\n} from '@/utils/objectUrlUtil'\n\nimport {\n  clampResolution,\n  DEBOUNCE_MS,\n  DEFAULT_SIZE,\n  getImageThroughSubgraphBoundary,\n  GLSL_NODE_TYPE,\n  normalizeDimension\n} from '@/renderer/glsl/glslPreviewUtils'\n\n/**\n * Two-tier composable for GLSL live preview.\n *\n * Outer tier (always created): only 2 cheap computed refs to detect\n * whether the node is GLSL-related. For non-GLSL nodes this is the\n * only cost — no watchers, store subscriptions, or renderer.\n *\n * Inner tier (lazy): created via effectScope when the node is detected\n * as a GLSLShader or a subgraph containing one. Contains all the\n * expensive logic: store reads, watchers, debounce, WebGL renderer.\n */\nexport function useGLSLPreview(\n  nodeMaybe: MaybeRefOrGetter<LGraphNode | null | undefined>\n) {\n  const lastError = ref<string | null>(null)\n  const hideExecutedOutput = ref(false)\n\n  const nodeRef = computed(() => toValue(nodeMaybe) ?? null)\n\n  const isGLSLNode = computed(() => nodeRef.value?.type === GLSL_NODE_TYPE)\n\n  const isGLSLSubgraphNode = computed(() => {\n    const node = nodeRef.value\n    if (!node?.isSubgraphNode()) return false\n    const subgraph = node.subgraph as Subgraph | undefined\n    return subgraph?.nodes.some((n) => n.type === GLSL_NODE_TYPE) ?? false\n  })\n\n  const isGLSLRelated = computed(\n    () => isGLSLNode.value || isGLSLSubgraphNode.value\n  )\n\n  let innerScope: EffectScope | null = null\n  let innerDispose: (() => void) | null = null\n  const isActive = ref(false)\n\n  watch(\n    isGLSLRelated,\n    (related) => {\n      if (related && !innerScope) {\n        innerScope = effectScope()\n        innerDispose = innerScope.run(() =>\n          createInnerPreview(\n            nodeRef,\n            isGLSLNode,\n            isGLSLSubgraphNode,\n            lastError,\n            isActive,\n            hideExecutedOutput\n          )\n        )!\n      } else if (!related && innerScope) {\n        innerDispose?.()\n        innerScope.stop()\n        innerScope = null\n        innerDispose = null\n        isActive.value = false\n      }\n    },\n    { immediate: true }\n  )\n\n  onScopeDispose(() => {\n    innerDispose?.()\n    innerScope?.stop()\n  })\n\n  return {\n    isActive: computed(() => isActive.value),\n    hideExecutedOutput: computed(() => hideExecutedOutput.value),\n    lastError,\n    dispose() {\n      innerDispose?.()\n      innerScope?.stop()\n      innerScope = null\n      innerDispose = null\n    }\n  }\n}\n\n/**\n * Inner tier: all expensive GLSL preview logic.\n * Runs inside its own effectScope so it can be created/destroyed\n * independently of the component lifecycle.\n * Returns a dispose function.\n */\ntype InputImage = HTMLImageElement | ImageBitmap\n\nfunction loadImageFromUrl(url: string): Promise<HTMLImageElement | null> {\n  return new Promise((resolve) => {\n    const img = new Image()\n    img.onload = () => resolve(img)\n    img.onerror = () => resolve(null)\n    img.src = url\n  })\n}\n\nfunction createInnerPreview(\n  nodeRef: ComputedRef<LGraphNode | null>,\n  isGLSLNode: ComputedRef<boolean>,\n  isGLSLSubgraphNode: ComputedRef<boolean>,\n  lastError: Ref<string | null>,\n  isActiveOut: Ref<boolean>,\n  hideExecutedOutput: Ref<boolean>\n): () => void {\n  const widgetValueStore = useWidgetValueStore()\n  const nodeOutputStore = useNodeOutputStore()\n  const { nodeToNodeLocatorId } = useWorkflowStore()\n\n  let renderer: ReturnType<typeof useGLSLRenderer> | null = null\n  let rendererReady = false\n  let renderRequestId = 0\n\n  const innerGLSLNode = (() => {\n    const node = nodeRef.value\n    if (!node?.isSubgraphNode()) return null\n    const subgraph = node.subgraph as Subgraph | undefined\n    const shaders =\n      subgraph?.nodes.filter((n) => n.type === GLSL_NODE_TYPE) ?? []\n    return shaders.length === 1 ? shaders[0] : null\n  })()\n\n  const ownerSubgraphNode = (() => {\n    const node = nodeRef.value\n    const graph = node?.graph\n    if (!graph) return null\n    const rootGraph = graph.rootGraph\n    if (graph === rootGraph) return null\n\n    return (\n      rootGraph._nodes.find(\n        (n) => n.isSubgraphNode() && n.subgraph === graph\n      ) ?? null\n    )\n  })()\n\n  const graphId = computed(() => nodeRef.value?.graph?.rootGraph.id)\n\n  const nodeId = computed(() => {\n    const id = nodeRef.value?.id\n    return id == null ? undefined : id\n  })\n\n  const hasExecutionOutput = computed(() => {\n    const node = nodeRef.value\n    if (!node) return false\n\n    const outputs = nodeOutputStore.nodeOutputs\n\n    const locatorId = nodeToNodeLocatorId(node)\n    if (outputs[locatorId]?.images?.length) return true\n\n    const inner = innerGLSLNode\n    if (inner) {\n      const innerLocatorId = nodeToNodeLocatorId(inner)\n      if (outputs[innerLocatorId]?.images?.length) return true\n    }\n\n    return false\n  })\n\n  const shouldRender = computed(\n    () =>\n      (isGLSLNode.value || isGLSLSubgraphNode.value) && hasExecutionOutput.value\n  )\n\n  watch(\n    shouldRender,\n    (v) => {\n      isActiveOut.value = v\n    },\n    { immediate: true }\n  )\n\n  const shaderSource = computed(() => {\n    const gId = graphId.value\n    if (!gId) return undefined\n\n    if (isGLSLNode.value) {\n      const nId = nodeId.value\n      if (nId == null) return undefined\n      return widgetValueStore.getWidget(widgetId(gId, nId, 'fragment_shader'))\n        ?.value as string | undefined\n    }\n\n    const inner = innerGLSLNode\n    if (inner) {\n      return widgetValueStore.getWidget(\n        widgetId(gId, inner.id, 'fragment_shader')\n      )?.value as string | undefined\n    }\n\n    return undefined\n  })\n\n  const rendererConfig = computed(() => {\n    const inner = innerGLSLNode\n    if (inner) return getAutogrowLimits(inner)\n\n    const node = nodeRef.value\n    if (!node)\n      return {\n        maxInputs: 5,\n        maxFloatUniforms: 20,\n        maxIntUniforms: 20,\n        maxBoolUniforms: 10,\n        maxCurves: 4\n      }\n    return getAutogrowLimits(node)\n  })\n\n  const uniformSources = computed(() => {\n    const node = nodeRef.value\n    const inner = innerGLSLNode\n    if (!node?.isSubgraphNode() || !inner) return null\n    return extractUniformSources(inner, node.subgraph, node)\n  })\n\n  const { floatValues, intValues, boolValues, curveValues } = useGLSLUniforms(\n    graphId,\n    nodeId,\n    nodeRef,\n    uniformSources,\n    rendererConfig\n  )\n\n  async function resolveSlotImage(\n    node: LGraphNode,\n    slot: number\n  ): Promise<InputImage | null> {\n    const upstreamNode = node.getInputNode(slot)\n    if (upstreamNode?.imgs?.length) return upstreamNode.imgs[0]\n\n    if (upstreamNode) {\n      const url = nodeOutputStore.getNodeImageUrls(upstreamNode)?.[0]\n      if (url) return await loadImageFromUrl(url)\n    }\n\n    const owner = ownerSubgraphNode\n    if (owner) return getImageThroughSubgraphBoundary(node, slot, owner) ?? null\n\n    return null\n  }\n\n  async function resolveInputImages(): Promise<{\n    images: (InputImage | null)[]\n    expected: number\n  }> {\n    const node = nodeRef.value\n    if (!node?.inputs) return { images: [], expected: 0 }\n\n    const images: (InputImage | null)[] = []\n    let expected = 0\n    for (let slot = 0; slot < node.inputs.length; slot++) {\n      const input = node.inputs[slot]\n      const isImageInput = isGLSLSubgraphNode.value\n        ? input.type === 'IMAGE'\n        : input.name.startsWith('images.image')\n      if (!isImageInput) continue\n      if (input.link != null) expected++\n\n      images.push(await resolveSlotImage(node, slot))\n    }\n    return { images, expected }\n  }\n\n  const customResolution = computed((): [number, number] | null => {\n    const gId = graphId.value\n    if (!gId) return null\n\n    const sizeModeNodeId = innerGLSLNode ? innerGLSLNode.id : nodeId.value\n    if (sizeModeNodeId == null) return null\n\n    const sizeMode = widgetValueStore.getWidget(\n      widgetId(gId, sizeModeNodeId, 'size_mode')\n    )\n    if (sizeMode?.value !== 'custom') return null\n\n    const widthWidget = widgetValueStore.getWidget(\n      widgetId(gId, sizeModeNodeId, 'size_mode.width')\n    )\n    const heightWidget = widgetValueStore.getWidget(\n      widgetId(gId, sizeModeNodeId, 'size_mode.height')\n    )\n    if (!widthWidget || !heightWidget) return null\n\n    return clampResolution(\n      normalizeDimension(widthWidget.value),\n      normalizeDimension(heightWidget.value)\n    )\n  })\n\n  function getResolution(images: InputImage[]): [number, number] {\n    const custom = customResolution.value\n    if (custom) return custom\n\n    const img = images.at(0)\n    if (img) {\n      const w = img instanceof ImageBitmap ? img.width : img.naturalWidth\n      const h = img instanceof ImageBitmap ? img.height : img.naturalHeight\n      return clampResolution(w || DEFAULT_SIZE, h || DEFAULT_SIZE)\n    }\n\n    return [DEFAULT_SIZE, DEFAULT_SIZE]\n  }\n\n  let disposed = false\n  const isDisposed = (): boolean => disposed\n  let lastRendererConfig: GLSLRendererConfig | null = null\n\n  function revokePreview(): void {\n    const inner = innerGLSLNode\n    if (inner) {\n      nodeOutputStore.revokePreviewsByLocatorId(nodeToNodeLocatorId(inner))\n      return\n    }\n    const node = nodeRef.value\n    if (node)\n      nodeOutputStore.revokePreviewsByLocatorId(nodeToNodeLocatorId(node))\n  }\n\n  function ensureRenderer(): ReturnType<typeof useGLSLRenderer> {\n    const config = rendererConfig.value\n    if (renderer?.isContextLost()) {\n      renderer.dispose()\n      renderer = null\n      rendererReady = false\n    }\n    if (renderer && lastRendererConfig) {\n      const changed =\n        config.maxInputs !== lastRendererConfig.maxInputs ||\n        config.maxFloatUniforms !== lastRendererConfig.maxFloatUniforms ||\n        config.maxIntUniforms !== lastRendererConfig.maxIntUniforms ||\n        config.maxBoolUniforms !== lastRendererConfig.maxBoolUniforms ||\n        config.maxCurves !== lastRendererConfig.maxCurves\n      if (changed) {\n        renderer.dispose()\n        renderer = null\n        rendererReady = false\n      }\n    }\n    if (!renderer) {\n      renderer = useGLSLRenderer(config)\n      lastRendererConfig = { ...config }\n    }\n    return renderer\n  }\n\n  async function renderPreview(): Promise<void> {\n    const requestId = ++renderRequestId\n    const source = shaderSource.value\n    if (!source || !shouldRender.value) return\n\n    const { images, expected } = await resolveInputImages()\n    if (requestId !== renderRequestId || disposed) return\n\n    const resolved = images.filter((img): img is InputImage => img != null)\n    if (expected > 0 && resolved.length === 0) {\n      revokePreview()\n      if (isGLSLNode.value) hideExecutedOutput.value = false\n      return\n    }\n\n    const r = ensureRenderer()\n\n    try {\n      const [w, h] = getResolution(resolved)\n\n      if (!rendererReady) {\n        if (!r.init(w, h)) {\n          lastError.value = 'WebGL2 not available'\n          return\n        }\n        rendererReady = true\n      }\n\n      const result = r.compileFragment(source)\n      if (!result.success) {\n        lastError.value = result.log\n        console.warn('[GLSL] shader compilation failed:', result.log)\n        return\n      }\n      lastError.value = null\n\n      r.setResolution(w, h)\n\n      for (let i = 0; i < images.length; i++) {\n        const img = images[i]\n        if (img) r.bindInputImage(i, img)\n        else r.clearInputImage(i)\n      }\n\n      for (let i = 0; i < floatValues.value.length; i++) {\n        r.setFloatUniform(i, floatValues.value[i])\n      }\n      for (let i = 0; i < intValues.value.length; i++) {\n        r.setIntUniform(i, intValues.value[i])\n      }\n      for (let i = 0; i < boolValues.value.length; i++) {\n        r.setBoolUniform(i, boolValues.value[i])\n      }\n      const curves = curveValues.value\n      for (let i = 0; i < curves.length; i++) {\n        r.bindCurveTexture(i, curveDataToFloatLUT(curves[i]))\n      }\n\n      r.render()\n\n      const blob = await r.toBlob()\n      if (requestId !== renderRequestId || isDisposed()) return\n      const blobUrl = createSharedObjectUrl(blob)\n      try {\n        const inner = innerGLSLNode\n        if (inner) {\n          const innerLocatorId = nodeToNodeLocatorId(inner)\n          nodeOutputStore.setNodePreviewsByLocatorId(innerLocatorId, [blobUrl])\n        } else {\n          const nId = nodeId.value\n          if (nId != null) {\n            nodeOutputStore.setNodePreviewsByNodeId(nId, [blobUrl])\n          }\n        }\n      } finally {\n        releaseSharedObjectUrl(blobUrl)\n      }\n      if (isGLSLNode.value) hideExecutedOutput.value = true\n    } catch (error) {\n      if (requestId !== renderRequestId) return\n      lastError.value =\n        error instanceof Error ? error.message : 'Failed to render preview'\n    }\n  }\n\n  const debouncedRender = debounce((): void => {\n    void renderPreview()\n  }, DEBOUNCE_MS)\n\n  watch(\n    shouldRender,\n    (active) => {\n      if (isGLSLNode.value) hideExecutedOutput.value = active\n      if (active) debouncedRender()\n    },\n    { immediate: true }\n  )\n\n  watch(\n    () =>\n      [\n        floatValues.value,\n        intValues.value,\n        boolValues.value,\n        curveValues.value,\n        customResolution.value\n      ] as const,\n    () => {\n      if (shouldRender.value) debouncedRender()\n    },\n    { deep: true }\n  )\n\n  watch(shaderSource, () => {\n    if (shouldRender.value) debouncedRender()\n  })\n\n  // Return dispose function for the inner tier\n  return () => {\n    disposed = true\n    hideExecutedOutput.value = false\n    debouncedRender.cancel()\n    renderer?.dispose()\n    renderer = null\n\n    revokePreview()\n  }\n}\n","import type { MaybeRefOrGetter } from 'vue'\nimport { computed, toValue } from 'vue'\n\nimport type { LGraphNode } from '@/lib/litegraph/src/LGraphNode'\nimport { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport type { UUID } from '@/utils/uuid'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport {\n  getPreviewExposureHostLocator,\n  usePreviewExposureStore\n} from '@/stores/previewExposureStore'\nimport type { NodeId } from '@/types/nodeId'\nimport {\n  appendNodeExecutionId,\n  createNodeLocatorId\n} from '@/types/nodeIdentification'\nimport type { NodeExecutionId } from '@/types/nodeIdentification'\n\ninterface PromotedPreview {\n  sourceNodeId: NodeId\n  sourceWidgetName: string\n  type: 'image' | 'video' | 'audio'\n  urls: string[]\n}\n\nconst PREVIEW_TYPES_BY_MEDIA = {\n  video: 'video',\n  audio: 'audio'\n} as const satisfies Partial<Record<string, PromotedPreview['type']>>\n\nfunction getPreviewMediaType(node: LGraphNode): PromotedPreview['type'] {\n  const media = node.previewMediaType\n  if (media && media in PREVIEW_TYPES_BY_MEDIA) {\n    return PREVIEW_TYPES_BY_MEDIA[media as keyof typeof PREVIEW_TYPES_BY_MEDIA]\n  }\n  return 'image'\n}\n\nexport function usePromotedPreviews(\n  lgraphNode: MaybeRefOrGetter<LGraphNode | null | undefined>\n) {\n  const previewExposureStore = usePreviewExposureStore()\n  const nodeOutputStore = useNodeOutputStore()\n\n  /** Touches reactive sources for Vue tracking; `getNodeImageUrls` reads non-reactive app state. */\n  function readReactivePreviewUrls(\n    leafHost: SubgraphNode,\n    leafSourceNodeId: NodeId,\n    leafExecutionId: NodeExecutionId,\n    interiorNode: LGraphNode\n  ): string[] | undefined {\n    const locatorId = createNodeLocatorId(\n      leafHost.subgraph.id,\n      leafSourceNodeId\n    )\n    if (!locatorId) return undefined\n\n    const reactiveOutputs = nodeOutputStore.nodeOutputs[locatorId]\n    const reactivePreviews = nodeOutputStore.nodePreviewImages[locatorId]\n    const reactiveExecutionOutputs =\n      nodeOutputStore.getNodeOutputByExecutionId(leafExecutionId)\n    const reactiveExecutionPreviews =\n      nodeOutputStore.getNodePreviewImagesByExecutionId(leafExecutionId)\n    const hasAnySource =\n      reactiveOutputs?.images?.length ||\n      reactivePreviews?.length ||\n      reactiveExecutionOutputs?.images?.length ||\n      reactiveExecutionPreviews?.length\n    if (!hasAnySource) return undefined\n    return (\n      nodeOutputStore.getNodeImageUrlsByExecutionId(\n        leafExecutionId,\n        interiorNode\n      ) ?? nodeOutputStore.getNodeImageUrls(interiorNode)\n    )\n  }\n\n  const promotedPreviews = computed((): PromotedPreview[] => {\n    const node = toValue(lgraphNode)\n    if (!(node instanceof SubgraphNode)) return []\n    if (node.isDetached) return []\n\n    const rootGraphId = node.rootGraph.id\n    const hostLocator = getPreviewExposureHostLocator(node)\n    if (!hostLocator) return []\n    const exposures = previewExposureStore.getExposures(\n      rootGraphId,\n      hostLocator\n    )\n    if (!exposures.length) return []\n\n    const hostNodesByLocator = new Map<string, SubgraphNode>([\n      [hostLocator, node]\n    ])\n    const hostExecutionsByLocator = new Map<string, string>([\n      [hostLocator, String(node.id)]\n    ])\n\n    function resolveNestedHost(\n      rootGraphId: UUID,\n      currentHostLocator: string,\n      sourceNodeId: NodeId\n    ) {\n      const currentHost = hostNodesByLocator.get(currentHostLocator)\n      const sourceNode = currentHost?.subgraph.getNodeById(sourceNodeId)\n      if (!(sourceNode instanceof SubgraphNode)) return undefined\n\n      const nestedHostLocator = getPreviewExposureHostLocator(sourceNode)\n      if (!nestedHostLocator) return undefined\n      const currentExecutionId = hostExecutionsByLocator.get(currentHostLocator)\n      if (!currentExecutionId) return undefined\n      hostNodesByLocator.set(nestedHostLocator, sourceNode)\n      hostExecutionsByLocator.set(\n        nestedHostLocator,\n        `${currentExecutionId}:${sourceNode.id}`\n      )\n      return { rootGraphId, hostNodeLocator: nestedHostLocator }\n    }\n\n    return exposures.flatMap((exposure): PromotedPreview[] => {\n      const resolved = previewExposureStore.resolveChain(\n        rootGraphId,\n        hostLocator,\n        exposure.name,\n        resolveNestedHost\n      )\n      const leaf = resolved?.leaf ?? {\n        sourceNodeId: exposure.sourceNodeId,\n        sourcePreviewName: exposure.sourcePreviewName\n      }\n      const leafHostLocator =\n        resolved?.steps.at(-1)?.hostNodeLocator ?? hostLocator\n      const leafHost = hostNodesByLocator.get(leafHostLocator) ?? node\n      const leafHostExecutionId =\n        hostExecutionsByLocator.get(leafHostLocator) ?? String(node.id)\n      const interiorNode = leafHost.subgraph.getNodeById(leaf.sourceNodeId)\n      if (!interiorNode) return []\n\n      const leafExecutionId = appendNodeExecutionId(\n        leafHostExecutionId,\n        leaf.sourceNodeId\n      )\n      if (!leafExecutionId) return []\n\n      const urls = readReactivePreviewUrls(\n        leafHost,\n        leaf.sourceNodeId,\n        leafExecutionId,\n        interiorNode\n      )\n      if (!urls?.length) return []\n\n      return [\n        {\n          sourceNodeId: leaf.sourceNodeId,\n          sourceWidgetName: leaf.sourcePreviewName,\n          type: getPreviewMediaType(interiorNode),\n          urls\n        }\n      ]\n    })\n  })\n\n  return { promotedPreviews }\n}\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport NodeBadge from '@/renderer/extensions/vueNodes/components/NodeBadge.vue'\nimport type { NodeBadgeProps } from '@/renderer/extensions/vueNodes/components/NodeBadge.vue'\n\ndefineProps<{\n  hasComfyBadge: boolean\n  hasComfyCloudBadge?: boolean\n  core: NodeBadgeProps[]\n  extension: NodeBadgeProps[]\n}>()\n</script>\n<template>\n  <div\n    v-if=\"hasComfyBadge || core.length || extension.length\"\n    class=\"flex h-5 w-full gap-2 px-2 text-muted-foreground\"\n  >\n    <div\n      v-if=\"core.length\"\n      class=\"flex h-6 items-center justify-center overflow-clip rounded-full bg-component-node-widget-background\"\n    >\n      <template v-for=\"(badge, index) of core\" :key=\"badge.text\">\n        <div\n          v-if=\"index !== 0\"\n          class=\"mr-0.5 h-4 border-r border-muted-foreground pr-0.5\"\n        />\n        <NodeBadge\n          bg-color=\"transparent\"\n          v-bind=\"badge\"\n          class=\"h-6 first:pl-2 last:pr-2\"\n        />\n      </template>\n    </div>\n    <div\n      v-if=\"hasComfyBadge\"\n      data-testid=\"comfy-badge\"\n      class=\"flex size-6 items-center justify-center rounded-full bg-component-node-widget-background\"\n    >\n      <i\n        :class=\"\n          cn(\n            'icon-[comfy--comfy-c] size-3',\n            hasComfyCloudBadge && 'text-brand-yellow'\n          )\n        \"\n      />\n    </div>\n    <div\n      v-if=\"extension.length\"\n      class=\"flex h-6 items-center justify-center overflow-clip rounded-full bg-component-node-widget-background\"\n    >\n      <template v-for=\"(badge, index) of extension\" :key=\"badge.text\">\n        <div\n          v-if=\"index !== 0\"\n          class=\"mr-0.5 h-4 border-r border-muted-foreground pr-0.5\"\n        />\n        <NodeBadge\n          bg-color=\"transparent\"\n          v-bind=\"badge\"\n          class=\"h-6 first:pl-2 last:pr-2\"\n        />\n      </template>\n    </div>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { remove } from 'es-toolkit'\nimport { computed } from 'vue'\n\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { parseNodeId } from '@/types/nodeId'\nimport type { NodeId, SerializedNodeId } from '@/types/nodeId'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { id } = defineProps<{ id: SerializedNodeId }>()\n\nconst appModeStore = useAppModeStore()\nconst parsedId = computed(() => parseNodeId(id))\nconst isPromoted = computed(() =>\n  parsedId.value ? appModeStore.selectedOutputs.some(matchesThis) : false\n)\n\nfunction matchesThis(nodeId: NodeId) {\n  return parsedId.value === nodeId\n}\nfunction togglePromotion() {\n  if (!parsedId.value) return\n  if (isPromoted.value) remove(appModeStore.selectedOutputs, matchesThis)\n  else appModeStore.selectedOutputs.push(parsedId.value)\n}\n</script>\n<template>\n  <div\n    :class=\"\n      cn(\n        'pointer-events-auto absolute z-1 size-full rounded-2xl ring-5 ring-warning-background/50',\n        isPromoted && 'ring-warning-background'\n      )\n    \"\n    @click.capture.stop.prevent\n    @pointerup.capture.stop.prevent\n    @pointermove.capture.stop.prevent\n    @pointerdown.capture.stop=\"togglePromotion\"\n    @contextmenu.capture.stop.prevent\n  >\n    <div class=\"absolute top-0 right-0 size-8\">\n      <div\n        v-if=\"isPromoted\"\n        class=\"absolute -top-1/2 -right-1/2 size-full rounded-lg bg-warning-background p-2\"\n      >\n        <i class=\"icon-[lucide--check] size-full bg-base-foreground\" />\n      </div>\n      <div\n        v-else\n        class=\"absolute -top-1/2 -right-1/2 size-full rounded-lg bg-component-node-background ring-4 ring-warning-background/50 ring-inset\"\n      />\n    </div>\n  </div>\n</template>\n","import { computed } from 'vue'\n\nimport { snapPoint } from '@/lib/litegraph/src/measure'\nimport { useSettingStore } from '@/platform/settings/settingStore'\n\n/**\n * Composable for node snap-to-grid functionality\n *\n * Provides reactive access to snap settings and utilities for applying\n * snap-to-grid behavior to Vue nodes during drag and resize operations.\n */\nexport function useNodeSnap() {\n  const settingStore = useSettingStore()\n\n  // Reactive snap settings\n  const gridSize = computed(() => settingStore.get('Comfy.SnapToGrid.GridSize'))\n  const alwaysSnap = computed(() => settingStore.get('pysssss.SnapToGrid'))\n\n  /**\n   * Determines if snap-to-grid should be applied based on shift key and settings\n   * @param event - The pointer event to check for shift key\n   * @returns true if snapping should be applied\n   */\n  function shouldSnap(event: PointerEvent): boolean {\n    return event.shiftKey || alwaysSnap.value\n  }\n\n  /**\n   * Applies snap-to-grid to a position\n   * @param position - Position object with x, y coordinates\n   * @returns The snapped position as a new object\n   */\n  function applySnapToPosition(position: { x: number; y: number }): {\n    x: number\n    y: number\n  } {\n    const size = gridSize.value\n    if (!size) return { ...position }\n\n    const posArray: [number, number] = [position.x, position.y]\n    if (snapPoint(posArray, size)) {\n      return { x: posArray[0], y: posArray[1] }\n    }\n    return { ...position }\n  }\n\n  /**\n   * Applies snap-to-grid to a size (width/height)\n   * @param size - Size object with width, height\n   * @returns The snapped size as a new object\n   */\n  function applySnapToSize(size: { width: number; height: number }): {\n    width: number\n    height: number\n  } {\n    const gridSizeValue = gridSize.value\n    if (!gridSizeValue) return { ...size }\n\n    const sizeArray: [number, number] = [size.width, size.height]\n    if (snapPoint(sizeArray, gridSizeValue, 'ceil')) {\n      return { width: sizeArray[0], height: sizeArray[1] }\n    }\n    return { ...size }\n  }\n\n  return {\n    gridSize,\n    alwaysSnap,\n    shouldSnap,\n    applySnapToPosition,\n    applySnapToSize\n  }\n}\n","import { tryOnScopeDispose, useEventListener } from '@vueuse/core'\nimport { shallowRef } from 'vue'\n\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\n\nexport function useShiftKeySync() {\n  const shiftKeyState = shallowRef(false)\n  let canvasEl: HTMLCanvasElement | null = null\n\n  /**\n   * Synchronizes shift key state to LiteGraph canvas by dispatching synthetic keyboard events.\n   *\n   * Only dispatches events when shift state actually changes to minimize overhead.\n   * Canvas reference is lazily initialized on first sync.\n   *\n   * @param isShiftPressed - Current shift key state to synchronize\n   */\n  function syncShiftState(isShiftPressed: boolean) {\n    if (isShiftPressed === shiftKeyState.value) return\n\n    // Lazy-initialize canvas reference on first use\n    if (!canvasEl) {\n      canvasEl = useCanvasStore().canvas?.canvas ?? null\n      if (!canvasEl) return // Canvas not ready yet\n    }\n\n    shiftKeyState.value = isShiftPressed\n    canvasEl.dispatchEvent(\n      new KeyboardEvent(isShiftPressed ? 'keydown' : 'keyup', {\n        key: 'Shift',\n        shiftKey: isShiftPressed,\n        bubbles: true\n      })\n    )\n  }\n\n  /**\n   * Tracks shift key state during drag/resize operations and synchronizes to canvas.\n   *\n   * Attaches window-level keyboard event listeners for the duration of the operation.\n   * Listeners are automatically cleaned up when the returned function is called.\n   *\n   * @param initialShiftKey - Shift state when drag/resize begins\n   * @returns Cleanup function that removes event listeners - must be called when operation ends\n   *\n   * @example\n   * ```ts\n   * function startDrag(event: PointerEvent) {\n   *   const stopTracking = trackShiftKey(event.shiftKey)\n   *\n   *   const handlePointerUp = () => {\n   *     stopTracking() // Cleanup listeners\n   *   }\n   * }\n   * ```\n   */\n  function trackShiftKey(initialShiftKey: boolean): () => void {\n    // Sync initial shift state\n    syncShiftState(initialShiftKey)\n\n    // Listen for shift key press/release during the operation\n    const handleKeyEvent = (e: KeyboardEvent) => {\n      if (e.key !== 'Shift') return\n      syncShiftState(e.shiftKey)\n    }\n\n    const stopKeydown = useEventListener(window, 'keydown', handleKeyEvent, {\n      passive: true\n    })\n    const stopKeyup = useEventListener(window, 'keyup', handleKeyEvent, {\n      passive: true\n    })\n\n    // Return cleanup function that stops both listeners\n    return () => {\n      stopKeydown()\n      stopKeyup()\n    }\n  }\n\n  // Cleanup on component unmount\n  tryOnScopeDispose(() => {\n    shiftKeyState.value = false\n    canvasEl = null\n  })\n\n  return { trackShiftKey }\n}\n","import { createSharedComposable } from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\nimport { toValue } from 'vue'\n\nimport type { Positionable } from '@/lib/litegraph/src/interfaces'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { AutoPanController } from '@/renderer/core/canvas/useAutoPan'\nimport { useLayoutMutations } from '@/renderer/core/layout/operations/layoutMutations'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { LayoutSource } from '@/renderer/core/layout/types'\nimport type { NodeBoundsUpdate, Point } from '@/renderer/core/layout/types'\nimport type { NodeId } from '@/types/nodeId'\nimport { useNodeSnap } from '@/renderer/extensions/vueNodes/composables/useNodeSnap'\nimport { useShiftKeySync } from '@/renderer/extensions/vueNodes/composables/useShiftKeySync'\nimport { useTransformState } from '@/renderer/core/layout/transform/useTransformState'\nimport { isLGraphNode } from '@/utils/litegraphUtil'\n\nexport const useNodeDrag = createSharedComposable(() => {\n  const mutations = useLayoutMutations(LayoutSource.Vue)\n  const { selectedNodeIds, selectedItems } = storeToRefs(useCanvasStore())\n\n  // Get transform utilities from TransformPane if available\n  const transformState = useTransformState()\n\n  // Snap-to-grid functionality\n  const { shouldSnap, applySnapToPosition } = useNodeSnap()\n\n  // Shift key sync for LiteGraph canvas preview\n  const { trackShiftKey } = useShiftKeySync()\n\n  const canvasStore = useCanvasStore()\n\n  // Drag state\n  let dragStartPos: Point | null = null\n  let dragStartMouse: Point | null = null\n  let otherSelectedNodesStartPositions: Map<NodeId, Point> | null = null\n  let rafId: number | null = null\n  let stopShiftSync: (() => void) | null = null\n\n  /** `pos` is readonly on Positionable, so absolute targets are reached via `move()`. */\n  let nonNodeStartPositions: Map<Positionable, Point> | null = null\n\n  // Auto-pan state\n  let autoPan: AutoPanController | null = null\n  let lastPointerX = 0\n  let lastPointerY = 0\n\n  function startDrag(\n    event: PointerEvent,\n    nodeId: NodeId,\n    initialShiftKey: boolean\n  ) {\n    const { rootGraphId } = canvasStore\n    if (!rootGraphId) return\n\n    const layout = layoutStore.getNodeLayout(rootGraphId, nodeId)\n    if (!layout) return\n    const position = layout.position\n\n    // Track shift key state and sync to canvas for snap preview\n    stopShiftSync = trackShiftKey(initialShiftKey)\n\n    dragStartPos = { ...position }\n    dragStartMouse = { x: event.clientX, y: event.clientY }\n    lastPointerX = event.clientX\n    lastPointerY = event.clientY\n\n    const selectedNodes = toValue(selectedNodeIds)\n\n    // capture the starting positions of all other selected nodes\n    // Only move other selected items if the dragged node is part of the selection\n    const isDraggedNodeInSelection = selectedNodes.has(nodeId)\n\n    if (isDraggedNodeInSelection && selectedNodes.size > 1) {\n      otherSelectedNodesStartPositions = new Map()\n\n      for (const id of selectedNodes) {\n        // Skip the current node being dragged\n        if (id === nodeId) continue\n\n        const nodeLayout = layoutStore.getNodeLayout(rootGraphId, id)\n        if (nodeLayout) {\n          otherSelectedNodesStartPositions.set(id, { ...nodeLayout.position })\n        }\n      }\n    } else {\n      otherSelectedNodesStartPositions = null\n    }\n\n    // Capture selected groups only if the dragged node is part of the selection\n    // This prevents groups from moving when dragging an unrelated node\n    nonNodeStartPositions = isDraggedNodeInSelection\n      ? new Map(\n          toValue(selectedItems)\n            .filter((item) => !isLGraphNode(item))\n            .map((item) => [item, { x: item.pos[0], y: item.pos[1] }])\n        )\n      : null\n  }\n\n  function startAutoPan(event: PointerEvent, nodeId: NodeId) {\n    if (autoPan) {\n      autoPan.updatePointer(event.clientX, event.clientY)\n      return\n    }\n    const lgCanvas = canvasStore.canvas\n    if (!lgCanvas?.ds) return\n\n    autoPan = new AutoPanController({\n      canvas: lgCanvas.canvas,\n      ds: lgCanvas.ds,\n      maxPanSpeed: lgCanvas.auto_pan_speed,\n      onPan: (panX, panY) => {\n        if (dragStartPos) {\n          dragStartPos.x += panX\n          dragStartPos.y += panY\n        }\n        if (otherSelectedNodesStartPositions) {\n          for (const pos of otherSelectedNodesStartPositions.values()) {\n            pos.x += panX\n            pos.y += panY\n          }\n        }\n        if (nonNodeStartPositions) {\n          for (const start of nonNodeStartPositions.values()) {\n            start.x += panX\n            start.y += panY\n          }\n        }\n        updateNodePositions(nodeId)\n      }\n    })\n    autoPan.updatePointer(event.clientX, event.clientY)\n    autoPan.start()\n  }\n\n  /**\n   * Recalculates all dragged node positions based on the current mouse\n   * position and canvas transform.\n   */\n  function updateNodePositions(nodeId: NodeId) {\n    if (!dragStartPos || !dragStartMouse) return\n\n    const { rootGraphId } = canvasStore\n    if (!rootGraphId) return\n\n    const mouseDelta = {\n      x: lastPointerX - dragStartMouse.x,\n      y: lastPointerY - dragStartMouse.y\n    }\n\n    const canvasOrigin = transformState.screenToCanvas({ x: 0, y: 0 })\n    const canvasWithDelta = transformState.screenToCanvas(mouseDelta)\n    const canvasDelta = {\n      x: canvasWithDelta.x - canvasOrigin.x,\n      y: canvasWithDelta.y - canvasOrigin.y\n    }\n\n    // Move drag updates in one transaction to avoid per-node notify fan-out.\n    const updates = [\n      {\n        nodeId,\n        position: {\n          x: dragStartPos.x + canvasDelta.x,\n          y: dragStartPos.y + canvasDelta.y\n        }\n      }\n    ]\n\n    if (\n      otherSelectedNodesStartPositions &&\n      otherSelectedNodesStartPositions.size > 0\n    ) {\n      for (const [otherNodeId, startPos] of otherSelectedNodesStartPositions) {\n        updates.push({\n          nodeId: otherNodeId,\n          position: {\n            x: startPos.x + canvasDelta.x,\n            y: startPos.y + canvasDelta.y\n          }\n        })\n      }\n    }\n\n    mutations.batchMoveNodes(rootGraphId, updates)\n\n    for (const [item, start] of nonNodeStartPositions ?? []) {\n      // Absolute target every frame, so a dropped frame cannot leave the item\n      // behind and per-frame deltas cannot drift out of step with the nodes.\n      item.move(\n        start.x + canvasDelta.x - item.pos[0],\n        start.y + canvasDelta.y - item.pos[1],\n        true\n      )\n    }\n  }\n\n  function handleDrag(event: PointerEvent, nodeId: NodeId) {\n    if (!dragStartPos || !dragStartMouse) {\n      return\n    }\n    if (canvasStore.isReadOnly) {\n      autoPan?.stop()\n      const canvas = canvasStore.getCanvas()\n      const delta = [event.clientX - lastPointerX, event.clientY - lastPointerY]\n\n      canvas.ds.offset[0] += delta[0] / canvas.ds.scale\n      canvas.ds.offset[1] += delta[1] / canvas.ds.scale\n      canvas.setDirty(true, true)\n      lastPointerX = event.clientX\n      lastPointerY = event.clientY\n      dragStartMouse.x += delta[0]\n      dragStartMouse.y += delta[1]\n      return\n    }\n\n    // Throttle position updates using requestAnimationFrame for better performance\n    if (rafId !== null) return // Skip if frame already scheduled\n\n    lastPointerX = event.clientX\n    lastPointerY = event.clientY\n    startAutoPan(event, nodeId)\n\n    rafId = requestAnimationFrame(() => {\n      rafId = null\n      updateNodePositions(nodeId)\n    })\n  }\n\n  function endDrag(event: PointerEvent, nodeId: NodeId | undefined) {\n    // Apply snap to final position if snap was active (matches LiteGraph behavior)\n    const { rootGraphId } = canvasStore\n    if (shouldSnap(event) && nodeId && rootGraphId) {\n      const boundsUpdates: NodeBoundsUpdate[] = []\n\n      // Snap main node\n      const currentLayout = layoutStore.getNodeLayout(rootGraphId, nodeId)\n      if (currentLayout) {\n        const currentPos = currentLayout.position\n        const snappedPos = applySnapToPosition({ ...currentPos })\n\n        // Only add update if position actually changed\n        if (snappedPos.x !== currentPos.x || snappedPos.y !== currentPos.y) {\n          boundsUpdates.push({\n            nodeId,\n            bounds: {\n              x: snappedPos.x,\n              y: snappedPos.y,\n              width: currentLayout.size.width,\n              height: currentLayout.size.height\n            }\n          })\n        }\n      }\n\n      // Also snap other selected nodes\n      // Capture all positions at the start to ensure consistent state\n      if (\n        otherSelectedNodesStartPositions &&\n        otherSelectedNodesStartPositions.size > 0\n      ) {\n        for (const otherNodeId of otherSelectedNodesStartPositions.keys()) {\n          const nodeLayout = layoutStore.getNodeLayout(rootGraphId, otherNodeId)\n          if (nodeLayout) {\n            const currentPos = { ...nodeLayout.position }\n            const snappedPos = applySnapToPosition(currentPos)\n\n            // Only add update if position actually changed\n            if (\n              snappedPos.x !== currentPos.x ||\n              snappedPos.y !== currentPos.y\n            ) {\n              boundsUpdates.push({\n                nodeId: otherNodeId,\n                bounds: {\n                  x: snappedPos.x,\n                  y: snappedPos.y,\n                  width: nodeLayout.size.width,\n                  height: nodeLayout.size.height\n                }\n              })\n            }\n          }\n        }\n      }\n\n      // Apply all snap updates in a single batched transaction\n      if (boundsUpdates.length > 0) {\n        layoutStore.batchUpdateNodeBounds(rootGraphId, boundsUpdates, {\n          source: LayoutSource.Vue\n        })\n      }\n    }\n\n    resetDragState()\n  }\n\n  function resetDragState() {\n    dragStartPos = null\n    dragStartMouse = null\n    otherSelectedNodesStartPositions = null\n    nonNodeStartPositions = null\n\n    autoPan?.stop()\n    autoPan = null\n\n    stopShiftSync?.()\n    stopShiftSync = null\n\n    if (rafId !== null) {\n      cancelAnimationFrame(rafId)\n      rafId = null\n    }\n  }\n\n  return {\n    startDrag,\n    handleDrag,\n    endDrag,\n    cancelDrag: resetDragState\n  }\n})\n","import { nextTick, onScopeDispose, toValue } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\nimport {\n  isMiddleButtonEvent,\n  isMiddleButtonHeld,\n  isMiddlePointerInput\n} from '@/base/pointerUtils'\nimport { CanvasPointer } from '@/lib/litegraph/src/CanvasPointer'\nimport { captureGesture } from '@/lib/litegraph/src/canvas/captureGesture'\nimport type {\n  GestureEffect,\n  GestureEvent,\n  GestureState\n} from '@/lib/litegraph/src/canvas/reduceGesture'\nimport {\n  idleGesture,\n  reduceGesture\n} from '@/lib/litegraph/src/canvas/reduceGesture'\nimport { LGraphCanvas, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { useNodeZIndex } from '@/renderer/extensions/vueNodes/composables/useNodeZIndex'\nimport { useNodeDrag } from '@/renderer/extensions/vueNodes/layout/useNodeDrag'\nimport type { NodeId } from '@/types/nodeId'\nimport type { NodeState } from '@/types/nodeState'\nimport { isLGraphNode } from '@/utils/litegraphUtil'\n\ninterface Press {\n  nodeId: NodeId\n  event: PointerEvent\n  movingNode: boolean\n  releaseCapture?: () => void\n}\n\nconst pressCancellers = new Map<number, () => void>()\n\nexport function useNodePointerInteractions(\n  nodeStateRef: MaybeRefOrGetter<NodeState>\n) {\n  const canvasStore = useCanvasStore()\n  const { startDrag, endDrag, handleDrag, cancelDrag } = useNodeDrag()\n  const { forwardEventToCanvas, shouldHandleNodePointerEvents } =\n    useCanvasInteractions()\n  const { bringNodeToFront } = useNodeZIndex()\n\n  let gesture: GestureState = idleGesture\n  let press: Press | null = null\n\n  function canDrag() {\n    return !toValue(nodeStateRef).flags.pinned\n  }\n\n  function dispatch(gestureEvent: GestureEvent, event: PointerEvent) {\n    const result = reduceGesture(gesture, gestureEvent)\n    gesture = result.state\n    try {\n      for (const effect of result.effects) runEffect(effect, event)\n    } finally {\n      if (gesture.phase === 'idle') clearPress()\n    }\n  }\n\n  function clearPress() {\n    const completedPress = press\n    press = null\n    if (\n      completedPress &&\n      pressCancellers.get(completedPress.event.pointerId) === cancelPress\n    )\n      pressCancellers.delete(completedPress.event.pointerId)\n    completedPress?.releaseCapture?.()\n    if (completedPress?.movingNode) layoutStore.isDraggingVueNodes.value = false\n  }\n\n  function cancelPress() {\n    if (press) dispatch({ type: 'cancel' }, press.event)\n  }\n\n  function selectNode(activePress: Press, sticky = false) {\n    const { canvas } = canvasStore\n    const node = canvasStore.currentGraph?.getNodeById(activePress.nodeId)\n    if (node) canvas?.processSelect(node, activePress.event, sticky)\n  }\n\n  function startNodeDrag(activePress: Press, event: PointerEvent) {\n    selectNode(activePress, true)\n    if (!canDrag()) return\n    layoutStore.isDraggingVueNodes.value = true\n    activePress.movingNode = true\n    startDrag(activePress.event, activePress.nodeId, event.shiftKey)\n  }\n\n  const effectHandlers: Record<\n    GestureEffect,\n    (activePress: Press, event: PointerEvent) => void\n  > = {\n    click: (activePress) => selectNode(activePress),\n    doubleClick: (activePress) => selectNode(activePress),\n    movePress: () => {},\n    startDrag: startNodeDrag,\n    moveDrag: (activePress, event) => {\n      if (activePress.movingNode && canDrag())\n        handleDrag(event, activePress.nodeId)\n    },\n    endDrag: (activePress, event) => {\n      if (activePress.movingNode)\n        endDrag(event, canDrag() ? activePress.nodeId : undefined)\n    },\n    cancelDrag: (activePress) => {\n      if (activePress.movingNode) cancelDrag()\n    }\n  }\n\n  function runEffect(effect: GestureEffect, event: PointerEvent) {\n    if (press) effectHandlers[effect](press, event)\n  }\n\n  const forwardMiddlePointerIfNeeded = (\n    event: PointerEvent,\n    isMiddleInput: (event: PointerEvent) => boolean\n  ) => {\n    if (!isMiddleInput(event)) return false\n    forwardEventToCanvas(event)\n    return true\n  }\n\n  function shouldCloneOnPress(event: PointerEvent) {\n    return (\n      LiteGraph.alt_drag_do_clone_nodes &&\n      event.altKey &&\n      !event.ctrlKey &&\n      !!canvasStore.canvas?.allow_interaction\n    )\n  }\n\n  function cloneNode(nodeId: NodeId): NodeId | undefined {\n    const node = canvasStore.currentGraph?.getNodeById(nodeId)\n    const clone = node && LGraphCanvas.cloneNodes([node])?.created[0]\n    return isLGraphNode(clone) ? clone.id : undefined\n  }\n\n  function pressNode(event: PointerEvent): NodeId {\n    const nodeId = toValue(nodeStateRef).id\n    const cloneId = shouldCloneOnPress(event) ? cloneNode(nodeId) : undefined\n    if (cloneId === undefined) {\n      if (canDrag()) bringNodeToFront(nodeId)\n      return nodeId\n    }\n    void nextTick(() => bringNodeToFront(cloneId))\n    return cloneId\n  }\n\n  function onPointerdown(event: PointerEvent) {\n    if (forwardMiddlePointerIfNeeded(event, isMiddlePointerInput)) return\n\n    if (!shouldHandleNodePointerEvents.value) {\n      forwardEventToCanvas(event)\n      return\n    }\n\n    if (event.button !== 0) return\n    if (press && press.event.pointerId !== event.pointerId) return\n    pressCancellers.get(event.pointerId)?.()\n\n    const nodeId = pressNode(event)\n    const captureTarget =\n      event.target instanceof Element ? event.target : undefined\n    pressCancellers.set(event.pointerId, cancelPress)\n    press = {\n      nodeId,\n      event,\n      movingNode: false,\n      releaseCapture:\n        canDrag() && captureTarget\n          ? captureGesture(captureTarget, event.pointerId, cancelPress)\n          : undefined\n    }\n    dispatch(\n      {\n        type: 'down',\n        position: { x: event.clientX, y: event.clientY },\n        timeStamp: event.timeStamp,\n        policy: CanvasPointer.gesturePolicy()\n      },\n      event\n    )\n  }\n\n  function dispatchUp(event: PointerEvent) {\n    dispatch(\n      {\n        type: 'up',\n        position: { x: event.clientX, y: event.clientY },\n        acceptsDoubleClick: false\n      },\n      event\n    )\n  }\n\n  function isPressPointer(event: PointerEvent) {\n    return press?.event.pointerId === event.pointerId\n  }\n\n  function onPointermove(event: PointerEvent) {\n    if (forwardMiddlePointerIfNeeded(event, isMiddleButtonHeld)) return\n    if (!isPressPointer(event)) return\n    if (!(event.buttons & 1)) {\n      dispatchUp(event)\n      return\n    }\n    dispatch(\n      {\n        type: 'move',\n        position: { x: event.clientX, y: event.clientY }\n      },\n      event\n    )\n  }\n\n  function onPointerup(event: PointerEvent) {\n    if (forwardMiddlePointerIfNeeded(event, isMiddleButtonEvent)) return\n    if (!shouldHandleNodePointerEvents.value) {\n      forwardEventToCanvas(event)\n      if (!isPressPointer(event)) return\n      if (press?.movingNode) dispatchUp(event)\n      else cancelPress()\n      return\n    }\n    if (!isPressPointer(event) || event.button !== 0) return\n    dispatchUp(event)\n  }\n\n  function onPointercancel(event: PointerEvent) {\n    if (isPressPointer(event)) cancelPress()\n  }\n\n  function onContextmenu(event: MouseEvent) {\n    if (!press?.movingNode) return\n    event.preventDefault()\n    event.stopImmediatePropagation()\n    cancelPress()\n  }\n\n  onScopeDispose(cancelPress)\n\n  const pointerHandlers = {\n    onPointerdown,\n    onPointermove,\n    onPointerup,\n    onPointercancel,\n    onContextmenu\n  } as const\n\n  return {\n    pointerHandlers\n  }\n}\n","import { trim } from 'es-toolkit'\nimport { computed, toValue } from 'vue'\n\nimport type { NodeState } from '@/types/nodeState'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { NodeBadgeProps } from '@/renderer/extensions/vueNodes/components/NodeBadge.vue'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { nodeBadges } from '@/systems/badgeSystem'\nimport { NodeBadgeMode } from '@/types/nodeSource'\nimport { resolveNode } from '@/utils/litegraphUtil'\n\nconst COMFY_CLOUD_PYTHON_MODULE = 'comfy_api_nodes.nodes_comfy_cloud'\n\nfunction splitAroundFirstSpace(text: string): [string, string | undefined] {\n  const index = text.indexOf(' ')\n  if (index === -1) return [text, undefined]\n  return [text.slice(0, index), text.slice(index + 1)]\n}\n\n/**\n * Partitions a node's badge rows into the Vue renderer's chips: core\n * rows, credits rows as pricing entries, and raw `node.badges`\n * extension badges appended last.\n */\nexport function usePartitionedBadges(nodeData: NodeState) {\n  const settingStore = useSettingStore()\n  const canvasStore = useCanvasStore()\n  const nodeDefStore = useNodeDefStore()\n\n  return computed(() => {\n    const rootGraph = canvasStore.currentGraph?.rootGraph\n    const node = rootGraph ? resolveNode(nodeData.id, rootGraph) : undefined\n    const nodeDef = node ? nodeDefStore.fromLGraphNode(node) : null\n    const showComfyLogo =\n      nodeDef?.isCoreNode === true &&\n      settingStore.get('Comfy.NodeBadge.NodeSourceBadgeMode') ===\n        NodeBadgeMode.ShowAll\n    const isComfyCloudNode =\n      nodeDef?.python_module === COMFY_CLOUD_PYTHON_MODULE\n\n    const core: NodeBadgeProps[] = []\n    const extension: NodeBadgeProps[] = []\n    const pricing: { required: string; rest?: string }[] = []\n\n    for (const row of node ? nodeBadges(node) : []) {\n      if (row.kind === 'credits') {\n        const [required, rest] = splitAroundFirstSpace(row.text)\n        pricing.push({ required, rest })\n        continue\n      }\n      if (nodeDef?.isCoreNode && row.part === 'source') continue\n      core.push({\n        text: row.part === 'lifecycle' ? trim(row.text, ['[', ']']) : row.text\n      })\n    }\n\n    for (const badge of (node?.badges ?? []).map(toValue)) {\n      if (!badge.text) continue\n      extension.push(badge)\n    }\n\n    return {\n      hasComfyBadge:\n        (showComfyLogo && pricing.length === 0) || isComfyCloudNode,\n      hasComfyCloudBadge: isComfyCloudNode,\n      core,\n      extension,\n      pricing\n    }\n  })\n}\n","import { storeToRefs } from 'pinia'\nimport { computed, toValue } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\nimport { useExecutionStore } from '@/stores/executionStore'\nimport type { NodeLocatorId } from '@/types/nodeIdentification'\n\n/**\n * Composable for managing execution state of Vue-based nodes\n *\n * Provides reactive access to execution state and progress for a specific node\n * by injecting execution data from the parent GraphCanvas provider.\n *\n * @param nodeLocatorIdMaybe - Locator ID (root or subgraph scoped) of the node to track\n * @returns Object containing reactive execution state and progress\n */\nexport const useNodeExecutionState = (\n  nodeLocatorIdMaybe: MaybeRefOrGetter<NodeLocatorId | undefined>\n) => {\n  const locatorId = computed(() => toValue(nodeLocatorIdMaybe) ?? '')\n  const { nodeLocationProgressStates, isIdle } =\n    storeToRefs(useExecutionStore())\n\n  const progressState = computed(() => {\n    const id = locatorId.value\n    return id ? nodeLocationProgressStates.value[id] : undefined\n  })\n\n  const executing = computed(\n    () => !isIdle.value && progressState.value?.state === 'running'\n  )\n\n  const progress = computed(() => {\n    const state = progressState.value\n    return state && state.max > 0 ? state.value / state.max : undefined\n  })\n\n  const progressPercentage = computed(() => {\n    const prog = progress.value\n    return prog !== undefined ? Math.round(prog * 100) : undefined\n  })\n\n  const executionState = computed(() => {\n    const state = progressState.value\n    if (!state) return 'idle'\n    return state.state\n  })\n\n  return {\n    executing,\n    progress,\n    progressPercentage,\n    progressState,\n    executionState\n  }\n}\n","import { computed, shallowRef, toValue, watch } from 'vue'\nimport type { ComputedRef, MaybeRefOrGetter } from 'vue'\n\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useLayoutMutations } from '@/renderer/core/layout/operations/layoutMutations'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { LayoutSource } from '@/renderer/core/layout/types'\nimport type { NodeLayout, Point } from '@/renderer/core/layout/types'\nimport type { NodeId } from '@/types/nodeId'\n\n/**\n * Composable for individual Vue node components\n * Uses customRef for shared write access with Canvas renderer\n */\nexport function useNodeLayout(nodeIdMaybe: MaybeRefOrGetter<NodeId>) {\n  const nodeId = toValue(nodeIdMaybe)\n  const mutations = useLayoutMutations(LayoutSource.Vue)\n  const canvasStore = useCanvasStore()\n\n  const layoutRef = shallowRef<ComputedRef<NodeLayout | null> | null>(null)\n  watch(\n    () => canvasStore.rootGraphId,\n    (rootGraphId) => {\n      if (!rootGraphId) {\n        layoutRef.value = null\n        return\n      }\n\n      layoutRef.value = layoutStore.getNodeLayoutRef(rootGraphId, nodeId)\n    },\n    { immediate: true }\n  )\n\n  const layout = computed(() => layoutRef.value?.value ?? null)\n\n  // Computed properties for easy access\n  const position = computed(() => layout.value?.position ?? { x: 0, y: 0 })\n  const size = computed(() => layout.value?.size ?? { width: 200, height: 100 })\n\n  const zIndex = computed(() => layout.value?.zIndex ?? 0)\n\n  /**\n   * Update node position directly (without drag)\n   */\n  function moveNodeTo(position: Point) {\n    const { rootGraphId } = canvasStore\n    if (!rootGraphId) return\n\n    mutations.moveNode(rootGraphId, nodeId, position)\n  }\n\n  return {\n    // Reactive state (via customRef)\n    position,\n    size,\n    zIndex,\n\n    // Mutations\n    moveNodeTo\n  }\n}\n","import { storeToRefs } from 'pinia'\nimport { computed, toValue } from 'vue'\nimport type { MaybeRefOrGetter, Ref } from 'vue'\n\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type { NodeId } from '@/types/nodeId'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\n\nexport const useNodePreviewState = (\n  nodeIdMaybe: MaybeRefOrGetter<NodeId>,\n  options?: {\n    isCollapsed?: Ref<boolean>\n  }\n) => {\n  const nodeId = toValue(nodeIdMaybe)\n  const workflowStore = useWorkflowStore()\n  const { nodePreviewImages } = storeToRefs(useNodeOutputStore())\n\n  const locatorId = computed(() => workflowStore.nodeIdToNodeLocatorId(nodeId))\n\n  const previewUrls = computed(() => {\n    const key = locatorId.value\n    if (!key) return undefined\n    const urls = nodePreviewImages.value[key]\n    return urls?.length ? urls : undefined\n  })\n\n  const hasPreview = computed(() => !!previewUrls.value?.length)\n\n  const latestPreviewUrl = computed(() => {\n    const urls = previewUrls.value\n    return urls?.length ? urls.at(-1)! : ''\n  })\n\n  const shouldShowPreviewImg = computed(() => {\n    if (!options?.isCollapsed) {\n      return hasPreview.value\n    }\n    return !options.isCollapsed.value && hasPreview.value\n  })\n\n  return {\n    locatorId,\n    previewUrls,\n    hasPreview,\n    latestPreviewUrl,\n    shouldShowPreviewImg\n  }\n}\n","import { RenderShape } from '@/lib/litegraph/src/types/globalEnums'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { adjustColor } from '@/utils/colorUtil'\n\n/**\n * Applies light theme color adjustments to a color\n */\nexport function applyLightThemeColor(color?: string): string {\n  if (!color) return ''\n\n  if (!useColorPaletteStore().completedActivePalette.light_theme) return color\n\n  return adjustColor(color, { lightness: 0.5 })\n}\n\nexport interface ShapeClassVariants {\n  readonly box: string\n  readonly card: string\n  readonly default: string\n}\n\n/**\n * Picks the class variant matching a node's render shape, treating every\n * shape other than BOX and CARD as the default rounding.\n */\nexport function shapeVariantClass(\n  shape: RenderShape | undefined,\n  variants: ShapeClassVariants\n): string {\n  switch (shape) {\n    case RenderShape.BOX:\n      return variants.box\n    case RenderShape.CARD:\n      return variants.card\n    default:\n      return variants.default\n  }\n}\n","import type { CompassCorners } from '@/lib/litegraph/src/interfaces'\n\ninterface ResizeHandle {\n  readonly corner: CompassCorners\n  readonly positionClasses: string\n  readonly cursorClass: string\n  readonly i18nKey: string\n  readonly svgPositionClasses: string\n  readonly svgTransform: string\n}\n\nexport const RESIZE_HANDLES: ResizeHandle[] = [\n  {\n    corner: 'SE',\n    positionClasses: '-right-1 -bottom-1',\n    cursorClass: 'cursor-se-resize',\n    i18nKey: 'g.resizeFromBottomRight',\n    svgPositionClasses: 'top-1 left-1',\n    svgTransform: ''\n  },\n  {\n    corner: 'NE',\n    positionClasses: '-right-1 -top-1',\n    cursorClass: 'cursor-ne-resize',\n    i18nKey: 'g.resizeFromTopRight',\n    svgPositionClasses: 'bottom-1 left-1',\n    svgTransform: 'scaleY(-1)'\n  },\n  {\n    corner: 'SW',\n    positionClasses: '-left-1 -bottom-1',\n    cursorClass: 'cursor-sw-resize',\n    i18nKey: 'g.resizeFromBottomLeft',\n    svgPositionClasses: 'top-1 right-1',\n    svgTransform: 'scaleX(-1)'\n  },\n  {\n    corner: 'NW',\n    positionClasses: '-left-1 -top-1',\n    cursorClass: 'cursor-nw-resize',\n    i18nKey: 'g.resizeFromTopLeft',\n    svgPositionClasses: 'bottom-1 right-1',\n    svgTransform: 'scale(-1, -1)'\n  }\n] as const\n\n/** True for corners on the left edge of a node (SW, NW) — these move the x-origin when dragged. */\nexport const hasWestEdge = (corner: CompassCorners): boolean =>\n  corner === 'SW' || corner === 'NW'\n\n/** True for corners on the top edge of a node (NE, NW) — these move the y-origin when dragged. */\nexport const hasNorthEdge = (corner: CompassCorners): boolean =>\n  corner === 'NE' || corner === 'NW'\n","import { useEventListener } from '@vueuse/core'\nimport { ref } from 'vue'\n\nimport type { CompassCorners } from '@/lib/litegraph/src/interfaces'\nimport type { Point, Size } from '@/renderer/core/layout/types'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { MIN_NODE_WIDTH } from '@/renderer/core/layout/transform/graphRenderTransform'\nimport { useNodeSnap } from '@/renderer/extensions/vueNodes/composables/useNodeSnap'\nimport { useShiftKeySync } from '@/renderer/extensions/vueNodes/composables/useShiftKeySync'\nimport { useTransformState } from '@/renderer/core/layout/transform/useTransformState'\nimport {\n  hasNorthEdge,\n  hasWestEdge\n} from '@/renderer/extensions/vueNodes/interactions/resize/resizeHandleConfig'\nimport { toNodeId } from '@/types/nodeId'\n\nexport interface ResizeCallbackPayload {\n  size: Size\n  position?: Point\n}\n\n/**\n * Composable for node resizing functionality from any corner.\n *\n * Provides resize handle interaction that integrates with the layout system.\n * Handles pointer capture, coordinate calculations, size constraints,\n * and position adjustments for non-SE corners.\n */\nexport function useNodeResize(\n  resizeCallback: (payload: ResizeCallbackPayload, element: HTMLElement) => void\n) {\n  const transformState = useTransformState()\n\n  const isResizing = ref(false)\n  const resizeStartPointer = ref<Point | null>(null)\n  const resizeStartSize = ref<Size | null>(null)\n  const resizeStartPosition = ref<Point | null>(null)\n  const resizeCorner = ref<CompassCorners>('SE')\n\n  // Snap-to-grid functionality\n  const { shouldSnap, applySnapToPosition, applySnapToSize } = useNodeSnap()\n\n  // Shift key sync for LiteGraph canvas preview\n  const { trackShiftKey } = useShiftKeySync()\n\n  const startResize = (event: PointerEvent, corner: CompassCorners = 'SE') => {\n    event.stopPropagation()\n\n    const target = event.currentTarget\n    if (!(target instanceof HTMLElement)) return\n\n    const nodeElement = target.closest('[data-node-id]')\n    if (!(nodeElement instanceof HTMLElement)) return\n\n    const rawNodeId = nodeElement.dataset.nodeId\n    if (!rawNodeId) return\n    const nodeId = toNodeId(rawNodeId)\n\n    const rect = nodeElement.getBoundingClientRect()\n    const scale = transformState.camera.z\n\n    const startSize: Size = {\n      width: rect.width / scale,\n      height: rect.height / scale\n    }\n\n    const measureMinContentHeight = (candidateWidth: number) => {\n      const savedWidth = nodeElement.style.getPropertyValue('--node-width')\n      const savedHeight = nodeElement.style.getPropertyValue('--node-height')\n      nodeElement.style.setProperty('--node-width', `${candidateWidth}px`)\n      nodeElement.style.setProperty('--node-height', '0px')\n      const measured = nodeElement.getBoundingClientRect().height\n      nodeElement.style.setProperty('--node-height', savedHeight || '')\n      nodeElement.style.setProperty('--node-width', savedWidth || '')\n      const currentScale = transformState.camera.z || 1\n      return measured / currentScale\n    }\n\n    const { rootGraphId } = useCanvasStore()\n    const nodeLayout = rootGraphId\n      ? layoutStore.getNodeLayout(rootGraphId, nodeId)\n      : null\n    const startPosition: Point = nodeLayout\n      ? { ...nodeLayout.position }\n      : { x: 0, y: 0 }\n\n    // Track shift key state and sync to canvas for snap preview\n    const stopShiftSync = trackShiftKey(event.shiftKey)\n\n    // Capture pointer to ensure we get all move/up events\n    target.setPointerCapture(event.pointerId)\n\n    // Mark as resizing to prevent drag from activating\n    layoutStore.isResizingVueNodes.value = true\n    isResizing.value = true\n    resizeStartPointer.value = { x: event.clientX, y: event.clientY }\n    resizeStartSize.value = startSize\n    resizeStartPosition.value = startPosition\n    resizeCorner.value = corner\n\n    const handlePointerMove = (moveEvent: PointerEvent) => {\n      if (\n        !isResizing.value ||\n        !resizeStartPointer.value ||\n        !resizeStartSize.value ||\n        !resizeStartPosition.value\n      ) {\n        return\n      }\n\n      const scale = transformState.camera.z\n      const deltaX =\n        (moveEvent.clientX - resizeStartPointer.value.x) / (scale || 1)\n      const deltaY =\n        (moveEvent.clientY - resizeStartPointer.value.y) / (scale || 1)\n\n      const activeCorner = resizeCorner.value\n      let newWidth: number\n      let newHeight: number\n      let newX = resizeStartPosition.value.x\n      let newY = resizeStartPosition.value.y\n\n      switch (activeCorner) {\n        case 'NE':\n          newY = resizeStartPosition.value.y + deltaY\n          newWidth = resizeStartSize.value.width + deltaX\n          newHeight = resizeStartSize.value.height - deltaY\n          break\n        case 'SW':\n          newX = resizeStartPosition.value.x + deltaX\n          newWidth = resizeStartSize.value.width - deltaX\n          newHeight = resizeStartSize.value.height + deltaY\n          break\n        case 'NW':\n          newX = resizeStartPosition.value.x + deltaX\n          newY = resizeStartPosition.value.y + deltaY\n          newWidth = resizeStartSize.value.width - deltaX\n          newHeight = resizeStartSize.value.height - deltaY\n          break\n        default: // SE\n          newWidth = resizeStartSize.value.width + deltaX\n          newHeight = resizeStartSize.value.height + deltaY\n          break\n      }\n\n      const isWestCorner = hasWestEdge(activeCorner)\n      const isNorthCorner = hasNorthEdge(activeCorner)\n\n      // Apply snap-to-grid\n      if (shouldSnap(moveEvent)) {\n        // Snap position first for N/W corners, then compensate size\n        if (isNorthCorner || isWestCorner) {\n          const originalX = newX\n          const originalY = newY\n          const snapped = applySnapToPosition({ x: newX, y: newY })\n          newX = snapped.x\n          newY = snapped.y\n\n          if (isNorthCorner) {\n            newHeight += originalY - newY\n          }\n          if (isWestCorner) {\n            newWidth += originalX - newX\n          }\n        }\n\n        const snappedSize = applySnapToSize({\n          width: newWidth,\n          height: newHeight\n        })\n        newWidth = snappedSize.width\n        newHeight = snappedSize.height\n      }\n\n      // Enforce minimum size with position compensation (matching litegraph)\n      const minWidth =\n        parseFloat(nodeElement.style.getPropertyValue('min-width') || '0') ||\n        MIN_NODE_WIDTH\n      if (newWidth < minWidth) {\n        if (isWestCorner) {\n          newX =\n            resizeStartPosition.value.x + resizeStartSize.value.width - minWidth\n        }\n        newWidth = minWidth\n      }\n      // Re-measure on each move with the candidate width applied: widget\n      // content (e.g. painter controls) can re-flow taller as width shrinks,\n      // raising the true minimum. Probing with newWidth — not the DOM's\n      // current width — keeps the clamp accurate on the frame that crosses\n      // a responsive breakpoint.\n      const minContentHeight = measureMinContentHeight(newWidth)\n      if (newHeight < minContentHeight) {\n        if (isNorthCorner) {\n          newY =\n            resizeStartPosition.value.y +\n            resizeStartSize.value.height -\n            minContentHeight\n        }\n        newHeight = minContentHeight\n      }\n\n      const payload: ResizeCallbackPayload = {\n        size: { width: newWidth, height: newHeight }\n      }\n\n      // Only include position for non-SE corners\n      if (activeCorner !== 'SE') {\n        payload.position = { x: newX, y: newY }\n      }\n\n      const targetNodeElement = target.closest('[data-node-id]')\n      if (targetNodeElement instanceof HTMLElement) {\n        resizeCallback(payload, targetNodeElement)\n      }\n    }\n\n    const cleanup = () => {\n      if (!isResizing.value) return\n      isResizing.value = false\n      layoutStore.isResizingVueNodes.value = false\n      resizeStartPointer.value = null\n      resizeStartSize.value = null\n      resizeStartPosition.value = null\n\n      // Stop tracking shift key state\n      stopShiftSync()\n\n      stopMoveListen()\n      stopUpListen()\n      stopCancelListen()\n    }\n\n    const handlePointerUp = (upEvent: PointerEvent) => {\n      if (isResizing.value) {\n        try {\n          target.releasePointerCapture(upEvent.pointerId)\n        } catch {\n          // Pointer capture may already be released\n        }\n        cleanup()\n      }\n    }\n\n    const stopMoveListen = useEventListener('pointermove', handlePointerMove)\n    const stopUpListen = useEventListener('pointerup', handlePointerUp)\n    const stopCancelListen = useEventListener('pointercancel', cleanup)\n  }\n\n  return {\n    startResize,\n    isResizing\n  }\n}\n","<template>\n  <template v-if=\"imageUrl\">\n    <div\n      v-if=\"imageError\"\n      class=\"flex size-full flex-col items-center justify-center text-center text-white\"\n    >\n      <i-lucide:image-off class=\"mb-1 size-8 text-smoke-500\" />\n      <p class=\"text-xs text-smoke-400\">{{ $t('g.imageFailedToLoad') }}</p>\n    </div>\n    <img\n      v-else\n      :src=\"imageUrl\"\n      :alt=\"$t('g.liveSamplingPreview')\"\n      class=\"pointer-events-none min-h-55 w-full flex-1 object-contain contain-size\"\n      @load=\"handleImageLoad\"\n      @error=\"handleImageError\"\n    />\n    <div class=\"mt-1 text-center text-xs text-node-component-header\">\n      {{\n        imageError\n          ? $t('g.errorLoadingImage')\n          : actualDimensions || $t('g.calculatingDimensions')\n      }}\n    </div>\n  </template>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, watch } from 'vue'\n\ninterface LivePreviewProps {\n  imageUrl: string\n}\n\nconst props = defineProps<LivePreviewProps>()\n\nconst actualDimensions = ref<string | null>(null)\nconst imageError = ref(false)\n\nwatch(\n  () => props.imageUrl,\n  () => {\n    // Reset error state when URL changes, but keep previous dimensions\n    // to avoid flickering \"Calculating dimensions\" text during live preview\n    imageError.value = false\n  }\n)\n\nconst handleImageLoad = (event: Event) => {\n  if (!event.target || !(event.target instanceof HTMLImageElement)) return\n  const img = event.target\n  imageError.value = false\n  if (img.naturalWidth && img.naturalHeight) {\n    actualDimensions.value = `${img.naturalWidth} x ${img.naturalHeight}`\n  }\n}\n\nconst handleImageError = () => {\n  imageError.value = true\n  actualDimensions.value = null\n}\n</script>\n","<template>\n  <div\n    v-if=\"imageUrls.length > 0\"\n    class=\"video-preview flex size-full min-h-55 min-w-16 flex-col px-2\"\n    @keydown=\"handleKeyDown\"\n  >\n    <!-- Video Wrapper -->\n    <div\n      ref=\"videoWrapperEl\"\n      class=\"relative flex flex-1 overflow-hidden rounded-[5px] bg-node-component-surface\"\n      tabindex=\"0\"\n      role=\"region\"\n      :aria-label=\"$t('g.videoPreview')\"\n      :aria-busy=\"showLoader\"\n      @mouseenter=\"handleMouseEnter\"\n      @mouseleave=\"handleMouseLeave\"\n      @focusin=\"handleFocusIn\"\n      @focusout=\"handleFocusOut\"\n    >\n      <!-- Error State -->\n      <div\n        v-if=\"videoError\"\n        role=\"alert\"\n        class=\"flex flex-auto flex-col items-center justify-center bg-muted-background py-8 text-center text-base-foreground\"\n      >\n        <i class=\"mb-2 icon-[lucide--video-off] size-12 text-base-foreground\" />\n        <p class=\"text-sm text-base-foreground\">\n          {{ $t('g.videoFailedToLoad') }}\n        </p>\n        <p class=\"mt-1 text-xs text-base-foreground\">\n          {{ getVideoFilename(currentVideoUrl) }}\n        </p>\n      </div>\n\n      <!-- Loading State -->\n      <Skeleton\n        v-if=\"showLoader && !videoError\"\n        class=\"absolute inset-0 size-full rounded-md\"\n      />\n\n      <!-- Main Video -->\n      <video\n        v-if=\"!videoError\"\n        :src=\"currentVideoUrl\"\n        :class=\"\n          cn(\n            'absolute inset-0 size-full object-contain',\n            showLoader && 'invisible'\n          )\n        \"\n        preload=\"metadata\"\n        controls\n        loop\n        playsinline\n        @loadeddata=\"handleVideoLoad\"\n        @error=\"handleVideoError\"\n      />\n\n      <!-- Floating Action Buttons (appear on hover) -->\n      <div\n        v-if=\"isHovered || isFocused\"\n        class=\"actions absolute top-2 right-2 flex gap-2.5\"\n      >\n        <!-- Download Button -->\n        <button\n          :class=\"actionButtonClass\"\n          :title=\"$t('g.downloadVideo')\"\n          :aria-label=\"$t('g.downloadVideo')\"\n          @click=\"handleDownload\"\n        >\n          <i class=\"icon-[lucide--download] size-4\" />\n        </button>\n\n        <!-- Close Button -->\n        <button\n          :class=\"actionButtonClass\"\n          :title=\"$t('g.removeVideo')\"\n          :aria-label=\"$t('g.removeVideo')\"\n          @click=\"handleRemove\"\n        >\n          <i class=\"icon-[lucide--x] size-4\" />\n        </button>\n      </div>\n\n      <!-- Multiple Videos Navigation -->\n      <div\n        v-if=\"hasMultipleVideos\"\n        class=\"absolute inset-x-2 bottom-2 flex justify-center gap-1\"\n      >\n        <button\n          v-for=\"(_, index) in imageUrls\"\n          :key=\"index\"\n          :class=\"getNavigationDotClass(index)\"\n          :aria-label=\"\n            $t('g.viewVideoOfTotal', {\n              index: index + 1,\n              total: imageUrls.length\n            })\n          \"\n          @click=\"setCurrentIndex(index)\"\n        />\n      </div>\n    </div>\n\n    <!-- Video Dimensions -->\n    <div class=\"mt-2 text-center text-xs text-muted-foreground\">\n      <span\n        v-if=\"videoError\"\n        class=\"text-red-400\"\n        data-testid=\"error-loading-video\"\n      >\n        {{ $t('g.errorLoadingVideo') }}\n      </span>\n      <span v-else-if=\"showLoader\" class=\"text-smoke-400\">\n        {{ $t('g.loading') }}...\n      </span>\n      <span v-else>\n        {{ actualDimensions || $t('g.calculatingDimensions') }}\n      </span>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { computed, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { downloadFile } from '@/base/common/downloadUtil'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport type { NodeId } from '@/types/nodeId'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ninterface VideoPreviewProps {\n  /** Array of video URLs to display */\n  readonly imageUrls: readonly string[] // Named imageUrls for consistency with parent components\n  /** Optional node ID for context-aware actions */\n  readonly nodeId?: NodeId\n}\n\nconst props = defineProps<VideoPreviewProps>()\n\nconst { t } = useI18n()\nconst nodeOutputStore = useNodeOutputStore()\n\nconst actionButtonClass =\n  'flex h-8 min-h-8 items-center justify-center gap-2.5 rounded-lg border-0 bg-button-surface px-2 py-2 text-button-surface-contrast shadow-sm transition-colors duration-200 hover:bg-button-hover-surface focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-button-surface-contrast focus-visible:ring-offset-2 focus-visible:ring-offset-transparent cursor-pointer'\n\n// Component state\nconst currentIndex = ref(0)\nconst isHovered = ref(false)\nconst isFocused = ref(false)\nconst actualDimensions = ref<string | null>(null)\nconst videoError = ref(false)\nconst showLoader = ref(false)\n\nconst videoWrapperEl = ref<HTMLDivElement>()\n\n// Computed values\nconst currentVideoUrl = computed(() => props.imageUrls[currentIndex.value])\nconst hasMultipleVideos = computed(() => props.imageUrls.length > 1)\n\n// Watch for URL changes and reset state\nwatch(\n  () => props.imageUrls,\n  (newUrls, oldUrls) => {\n    // Only reset state if URLs actually changed (not just array reference)\n    const urlsChanged =\n      !oldUrls ||\n      newUrls.length !== oldUrls.length ||\n      newUrls.some((url, i) => url !== oldUrls[i])\n\n    if (!urlsChanged) return\n\n    // Reset current index if it's out of bounds\n    if (currentIndex.value >= newUrls.length) {\n      currentIndex.value = 0\n    }\n\n    // Reset loading and error states when URLs change\n    actualDimensions.value = null\n    videoError.value = false\n    showLoader.value = newUrls.length > 0\n  },\n  { immediate: true }\n)\n\n// Event handlers\nconst handleVideoLoad = (event: Event) => {\n  if (!event.target || !(event.target instanceof HTMLVideoElement)) return\n  const video = event.target\n  showLoader.value = false\n  videoError.value = false\n  if (video.videoWidth && video.videoHeight) {\n    actualDimensions.value = `${video.videoWidth} x ${video.videoHeight}`\n  }\n}\n\nconst handleVideoError = () => {\n  showLoader.value = false\n  videoError.value = true\n  actualDimensions.value = null\n}\n\nconst handleDownload = () => {\n  try {\n    downloadFile(currentVideoUrl.value)\n  } catch (error) {\n    useToast().error(t('g.error'), {\n      description: t('g.failedToDownloadVideo'),\n      duration: 3000\n    })\n  }\n}\n\nconst handleRemove = () => {\n  if (!props.nodeId) return\n  nodeOutputStore.removeNodeOutputs(props.nodeId)\n}\n\nconst setCurrentIndex = (index: number) => {\n  if (currentIndex.value === index) return\n  if (index >= 0 && index < props.imageUrls.length) {\n    const urlChanged = props.imageUrls[index] !== currentVideoUrl.value\n    currentIndex.value = index\n    videoError.value = false\n    if (urlChanged) {\n      actualDimensions.value = null\n      showLoader.value = true\n    }\n  }\n}\n\nconst handleMouseEnter = () => {\n  isHovered.value = true\n}\n\nconst handleMouseLeave = () => {\n  isHovered.value = false\n}\n\nconst handleFocusIn = () => {\n  isFocused.value = true\n}\n\nconst handleFocusOut = (event: FocusEvent) => {\n  if (!videoWrapperEl.value?.contains(event.relatedTarget as Node)) {\n    isFocused.value = false\n  }\n}\n\nconst getNavigationDotClass = (index: number) =>\n  cn(\n    'size-2 cursor-pointer rounded-full border-0 transition-all duration-200',\n    index === currentIndex.value\n      ? 'bg-base-foreground'\n      : 'bg-base-foreground/50 hover:bg-base-foreground/80'\n  )\n\nconst handleKeyDown = (event: KeyboardEvent) => {\n  if (props.imageUrls.length <= 1) return\n\n  switch (event.key) {\n    case 'ArrowLeft':\n      event.preventDefault()\n      setCurrentIndex(\n        currentIndex.value > 0\n          ? currentIndex.value - 1\n          : props.imageUrls.length - 1\n      )\n      break\n    case 'ArrowRight':\n      event.preventDefault()\n      setCurrentIndex(\n        currentIndex.value < props.imageUrls.length - 1\n          ? currentIndex.value + 1\n          : 0\n      )\n      break\n    case 'Home':\n      event.preventDefault()\n      setCurrentIndex(0)\n      break\n    case 'End':\n      event.preventDefault()\n      setCurrentIndex(props.imageUrls.length - 1)\n      break\n  }\n}\n\nconst getVideoFilename = (url: string): string => {\n  try {\n    return new URL(url).searchParams.get('filename') || 'Unknown file'\n  } catch {\n    return 'Invalid URL'\n  }\n}\n</script>\n","<template>\n  <div v-if=\"audioUrls.length > 0\" class=\"flex flex-col gap-2 px-2\">\n    <audio\n      v-for=\"(url, index) in audioUrls\"\n      :key=\"index\"\n      :src=\"url\"\n      controls\n      preload=\"metadata\"\n      class=\"w-full\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\ninterface AudioPreviewProps {\n  readonly audioUrls: readonly string[]\n}\n\ndefineProps<AudioPreviewProps>()\n</script>\n","<template>\n  <div\n    v-if=\"imageUrls.length > 0\"\n    class=\"image-preview group relative flex size-full min-w-16 flex-col justify-center px-2\"\n    :style=\"{ minHeight: `${IMAGE_PREVIEW_CONTENT_MIN_HEIGHT}px` }\"\n    @keydown=\"handleKeyDown\"\n  >\n    <!-- Grid View -->\n    <div\n      v-if=\"viewMode === 'grid'\"\n      ref=\"gridEl\"\n      data-testid=\"image-grid\"\n      class=\"relative grid w-full flex-1 gap-1 rounded-sm p-1 contain-size\"\n      :style=\"{ gridTemplateColumns: `repeat(${gridCols}, 1fr)` }\"\n    >\n      <Button\n        v-for=\"(url, index) in gridImageUrls\"\n        :key=\"index\"\n        size=\"unset\"\n        class=\"overflow-hidden rounded-none p-0 ring-border-default hover:ring-1 focus-visible:ring-2\"\n        :aria-label=\"\n          $t('g.viewImageOfTotal', {\n            index: index + 1,\n            total: imageUrls.length\n          })\n        \"\n        @click=\"handleGridClick(index)\"\n      >\n        <div\n          v-if=\"!isHdrPlaceholder(imageUrls[index])\"\n          class=\"pointer-events-none relative size-full\"\n        >\n          <img\n            :src=\"url\"\n            :alt=\"`${$t('g.galleryThumbnail')} ${index + 1}`\"\n            draggable=\"false\"\n            class=\"size-full object-contain\"\n            @load=\"updateAspectRatio($event, index)\"\n          />\n        </div>\n        <div\n          v-else\n          class=\"flex size-full flex-col items-center justify-center gap-1 text-base-foreground\"\n        >\n          <i class=\"icon-[lucide--sun] size-6\" />\n          <span class=\"text-xs\">{{ $t('hdrViewer.hdrImage') }}</span>\n        </div>\n      </Button>\n      <div\n        v-if=\"canExportOutputs\"\n        class=\"invisible absolute top-2 right-2 group-focus-within:visible group-hover:visible\"\n      >\n        <button\n          :class=\"actionButtonClass\"\n          :title=\"$t('g.downloadImages')\"\n          :aria-label=\"$t('g.downloadImages')\"\n          @click=\"handleExportOutputs\"\n        >\n          <i class=\"icon-[lucide--folder-down] size-4\" />\n        </button>\n      </div>\n    </div>\n\n    <!-- Gallery View (Image Wrapper) -->\n    <div\n      v-if=\"viewMode === 'gallery'\"\n      ref=\"galleryPanelEl\"\n      class=\"group/panel relative flex min-h-0 w-full flex-1 cursor-pointer overflow-hidden rounded-sm bg-transparent\"\n      tabindex=\"0\"\n      role=\"region\"\n      :aria-roledescription=\"$t('g.imageGallery')\"\n      :aria-label=\"$t('g.imagePreview')\"\n      :aria-busy=\"showLoader\"\n    >\n      <!-- Error State -->\n      <div\n        v-if=\"imageError\"\n        role=\"alert\"\n        class=\"flex size-full flex-1 flex-col items-center justify-around self-center py-8 text-center text-base-foreground\"\n      >\n        <i class=\"mb-2 icon-[lucide--image-off] size-12 text-base-foreground\" />\n        <p class=\"text-sm text-base-foreground\">\n          {{ $t('g.imageFailedToLoad') }}\n        </p>\n        <p class=\"mt-1 text-xs text-base-foreground\">\n          {{ getImageFilename(currentImageUrl) }}\n        </p>\n      </div>\n      <!-- Loading State -->\n      <div\n        v-if=\"showLoader && !imageError && !isHdrPlaceholder(currentImageUrl)\"\n        class=\"size-full\"\n      >\n        <Skeleton class=\"size-full rounded-sm\" />\n      </div>\n      <button\n        v-if=\"!imageError && isHdrPlaceholder(currentImageUrl)\"\n        type=\"button\"\n        data-testid=\"hdr-open-button\"\n        class=\"absolute inset-0 flex cursor-pointer flex-col items-center justify-center gap-3 border-0 bg-transparent text-base-foreground\"\n        @click=\"openHdrViewer(currentImageUrl)\"\n      >\n        <i class=\"icon-[lucide--sun] size-12\" />\n        <span class=\"text-sm\">{{ $t('hdrViewer.hdrImage') }}</span>\n        <span\n          class=\"rounded-md bg-base-foreground px-3 py-1.5 text-sm text-base-background\"\n        >\n          {{ $t('hdrViewer.openInHdrViewer') }}\n        </span>\n      </button>\n      <!-- Main Image -->\n      <img\n        v-if=\"!imageError && !isHdrPlaceholder(currentImageUrl)\"\n        :key=\"currentImageUrl\"\n        data-testid=\"main-image\"\n        :src=\"currentHdrPreviewUrl ?? currentImageUrl\"\n        :data-file-url=\"currentHdrPreviewUrl ? currentImageUrl : undefined\"\n        :alt=\"imageAltText\"\n        draggable=\"false\"\n        class=\"pointer-events-none absolute inset-0 block size-full object-contain\"\n        @load=\"handleImageLoad\"\n        @error=\"handleImageError\"\n      />\n\n      <!-- Floating Action Buttons (appear on hover and focus) -->\n      <div\n        class=\"actions invisible absolute top-2 right-2 flex gap-1 group-focus-within/panel:visible group-hover/panel:visible\"\n      >\n        <!-- Mask/Edit Button -->\n        <button\n          v-if=\"!hasMultipleImages && !imageError && !currentImageIsHdr\"\n          :class=\"actionButtonClass\"\n          :title=\"$t('g.editOrMaskImage')\"\n          :aria-label=\"$t('g.editOrMaskImage')\"\n          @click=\"handleEditMask\"\n        >\n          <i-comfy:mask class=\"size-4\" />\n        </button>\n\n        <button\n          v-if=\"!imageError && currentHdrPreviewUrl\"\n          :class=\"actionButtonClass\"\n          :title=\"$t('hdrViewer.openInHdrViewer')\"\n          :aria-label=\"$t('hdrViewer.openInHdrViewer')\"\n          @click=\"openHdrViewer(currentImageUrl)\"\n        >\n          <i class=\"icon-[lucide--sun] size-4\" />\n        </button>\n\n        <!-- Layer Editor Button -->\n        <button\n          v-if=\"hasMultipleImages && !imageError\"\n          :class=\"actionButtonClass\"\n          :title=\"$t('g.openLayerEditor')\"\n          :aria-label=\"$t('g.openLayerEditor')\"\n          @click=\"handleOpenLayerEditor\"\n        >\n          <i class=\"icon-[lucide--layers] size-4\" />\n        </button>\n\n        <!-- Download Button -->\n        <button\n          v-if=\"!imageError\"\n          :class=\"actionButtonClass\"\n          :title=\"$t('g.downloadImage')\"\n          :aria-label=\"$t('g.downloadImage')\"\n          @click=\"handleDownload\"\n        >\n          <i class=\"icon-[lucide--download] size-4\" />\n        </button>\n\n        <!-- Back to Grid Button -->\n        <button\n          v-if=\"hasMultipleImages\"\n          :class=\"actionButtonClass\"\n          :title=\"$t('g.viewGrid')\"\n          :aria-label=\"$t('g.viewGrid')\"\n          @click=\"viewMode = 'grid'\"\n        >\n          <i class=\"icon-[lucide--layout-grid] size-4\" />\n        </button>\n      </div>\n    </div>\n\n    <!-- Image Dimensions (gallery mode only) -->\n    <div\n      v-if=\"viewMode === 'gallery' && !isHdrPlaceholder(currentImageUrl)\"\n      class=\"pt-2 text-center text-xs text-base-foreground\"\n    >\n      <span\n        v-if=\"imageError\"\n        class=\"text-error\"\n        data-testid=\"error-loading-image\"\n      >\n        {{ $t('g.errorLoadingImage') }}\n      </span>\n      <span v-else-if=\"showLoader\" class=\"text-base-foreground\">\n        {{ $t('g.loading') }}...\n      </span>\n      <span v-else>\n        {{ actualDimensions || $t('g.calculatingDimensions') }}\n      </span>\n    </div>\n\n    <!-- Multiple Images Navigation (gallery mode only) -->\n    <div\n      v-if=\"viewMode === 'gallery' && hasMultipleImages\"\n      class=\"flex flex-wrap items-center justify-center gap-1 pt-4\"\n    >\n      <!-- Back to Grid button -->\n      <button\n        class=\"mr-1 flex cursor-pointer items-center justify-center rounded-sm border-0 bg-transparent p-0.5 text-base-foreground/50 transition-colors hover:text-base-foreground\"\n        :title=\"$t('g.viewGrid')\"\n        :aria-label=\"$t('g.viewGrid')\"\n        @click=\"viewMode = 'grid'\"\n      >\n        <i class=\"icon-[lucide--layout-grid] size-3.5\" />\n      </button>\n\n      <!-- Navigation Dots -->\n      <button\n        v-for=\"(_, index) in imageUrls\"\n        :key=\"index\"\n        :class=\"getNavigationDotClass(index)\"\n        :aria-current=\"index === currentIndex ? 'true' : undefined\"\n        :aria-label=\"\n          $t('g.viewImageOfTotal', {\n            index: index + 1,\n            total: imageUrls.length\n          })\n        \"\n        @click=\"setCurrentIndex(index)\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useElementSize, useTimeoutFn } from '@vueuse/core'\nimport { computed, nextTick, ref, useTemplateRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { downloadFile } from '@/base/common/downloadUtil'\nimport Button from '@/components/ui/button/Button.vue'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport { useMaskEditor } from '@/composables/maskeditor/useMaskEditor'\nimport { useNodeOutputsExport } from '@/platform/assets/composables/useNodeOutputsExport'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { describeImageLoadFailure } from '@/platform/telemetry/imageFailureDiagnostics'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { openHdrViewer } from '@/services/hdrViewerService'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport type { NodeId } from '@/types/nodeId'\nimport { getHdrPreviewUrl, isHdrImageUrl } from '@/utils/hdrFormatUtil'\nimport { getGridThumbnailUrl } from '@/utils/imageUtil'\nimport { resolveNode } from '@/utils/litegraphUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport { IMAGE_PREVIEW_CONTENT_MIN_HEIGHT } from './imagePreviewLayout'\n\ninterface ImagePreviewProps {\n  /** Array of image URLs to display */\n  readonly imageUrls: readonly string[]\n  /** Optional node ID for context-aware actions */\n  readonly nodeId?: NodeId\n}\n\nconst { imageUrls, nodeId } = defineProps<ImagePreviewProps>()\n\nconst { t } = useI18n()\nconst maskEditor = useMaskEditor()\nconst nodeOutputStore = useNodeOutputStore()\nconst { hasMultipleOutputs, showOutputsExportDialog } = useNodeOutputsExport()\nconst toast = useToast()\n\nconst actionButtonClass =\n  'flex h-8 min-h-8 cursor-pointer items-center justify-center rounded-lg border-0 bg-base-foreground p-2 text-base-background shadow-interface transition-colors duration-200 hover:bg-base-foreground/90 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-base-foreground focus-visible:ring-offset-2'\n\ntype ViewMode = 'gallery' | 'grid'\n\nfunction defaultViewMode(urls: readonly string[]): ViewMode {\n  return urls.length > 1 ? 'grid' : 'gallery'\n}\n\nconst { width: gridWidth, height: gridHeight } = useElementSize(\n  useTemplateRef('gridEl')\n)\n\nconst currentIndex = ref(0)\nconst viewMode = ref<ViewMode>(defaultViewMode(imageUrls))\nconst galleryPanelEl = ref<HTMLDivElement>()\nconst actualDimensions = ref<string | null>(null)\nconst imageError = ref(false)\nconst showLoader = ref(false)\nconst imageAspectRatio = ref(1)\n\nconst { start: startDelayedLoader, stop: stopDelayedLoader } = useTimeoutFn(\n  () => {\n    showLoader.value = true\n  },\n  250,\n  // Make sure it doesnt run on component mount\n  { immediate: false }\n)\n\nconst currentImageUrl = computed(() => imageUrls[currentIndex.value] ?? '')\nconst isHdrPlaceholder = (url: string | undefined) =>\n  isHdrImageUrl(url) && !getHdrPreviewUrl(url)\n\nconst currentImageIsHdr = computed(() => isHdrImageUrl(currentImageUrl.value))\nconst currentHdrPreviewUrl = computed(() =>\n  getHdrPreviewUrl(currentImageUrl.value)\n)\nconst gridImageUrls = computed(() =>\n  imageUrls.map((url) => getHdrPreviewUrl(url) ?? getGridThumbnailUrl(url))\n)\nconst hasMultipleImages = computed(() => imageUrls.length > 1)\nconst canExportOutputs = computed(() => {\n  const node = nodeId ? resolveNode(nodeId) : undefined\n  return !!node && hasMultipleOutputs(node)\n})\nconst imageAltText = computed(() =>\n  t('g.viewImageOfTotal', {\n    index: currentIndex.value + 1,\n    total: imageUrls.length\n  })\n)\nconst gridCols = computed(() => {\n  const bias = gridWidth.value / gridHeight.value / imageAspectRatio.value\n  return Math.max(Math.round(Math.sqrt(imageUrls.length * bias)), 1)\n})\n\nwatch(\n  () => imageUrls,\n  (newUrls, oldUrls) => {\n    const key = (url: string) =>\n      imageError.value ? url : (getHdrPreviewUrl(url) ?? url)\n    const urlsChanged =\n      !oldUrls ||\n      newUrls.length !== oldUrls.length ||\n      newUrls.some((url, i) => key(url) !== key(oldUrls[i]))\n\n    if (!urlsChanged) return\n\n    if (currentIndex.value >= newUrls.length) {\n      currentIndex.value = 0\n    }\n\n    actualDimensions.value = null\n\n    viewMode.value = defaultViewMode(newUrls)\n    imageError.value = false\n    if (newUrls.length > 0) startDelayedLoader()\n  },\n  { immediate: true }\n)\n\nfunction handleImageLoad(event: Event) {\n  if (!event.target || !(event.target instanceof HTMLImageElement)) return\n  const img = event.target\n  stopDelayedLoader()\n  showLoader.value = false\n  imageError.value = false\n  if (img.naturalWidth && img.naturalHeight) {\n    actualDimensions.value = `${img.naturalWidth} x ${img.naturalHeight}`\n  }\n\n  if (nodeId) {\n    nodeOutputStore.syncLegacyNodeImgs(nodeId, img, currentIndex.value)\n  }\n}\n\nfunction updateAspectRatio(event: Event, index: number) {\n  if (!(event.target instanceof HTMLImageElement) || index !== 0) return\n  const { naturalWidth, naturalHeight } = event.target\n  if (naturalWidth && naturalHeight) {\n    imageAspectRatio.value = naturalWidth / naturalHeight\n  }\n}\n\nfunction handleImageError() {\n  stopDelayedLoader()\n  showLoader.value = false\n  imageError.value = true\n  actualDimensions.value = null\n\n  // The error UI is already up; the diagnostic probe runs behind it so a slow\n  // or hanging re-request never delays what the user sees.\n  const failedUrl = currentImageUrl.value\n  void describeImageLoadFailure(failedUrl).then((metadata) => {\n    useTelemetry()?.trackImageLoadFailed(metadata)\n  })\n}\n\nfunction handleEditMask() {\n  if (!nodeId) return\n  const node = resolveNode(nodeId)\n  if (!node) return\n  maskEditor.openMaskEditor(node)\n}\n\nasync function handleOpenLayerEditor() {\n  if (!nodeId) return\n  const node = resolveNode(nodeId)\n  if (!node) return\n  const { useLayerEditor } =\n    await import('@/renderer/extensions/layerEditor/composables/useLayerEditor')\n  useLayerEditor().openLayerEditor(node)\n}\n\nfunction handleDownload() {\n  try {\n    downloadFile(currentImageUrl.value)\n  } catch {\n    toast.error(t('g.error'), {\n      description: t('g.failedToDownloadImage')\n    })\n  }\n}\n\nfunction handleExportOutputs() {\n  if (!nodeId) return\n  const node = resolveNode(nodeId)\n  if (!node) return\n  showOutputsExportDialog(node)\n}\n\nfunction setCurrentIndex(index: number) {\n  if (currentIndex.value === index) return\n  if (index >= 0 && index < imageUrls.length) {\n    const urlChanged = imageUrls[index] !== currentImageUrl.value\n    currentIndex.value = index\n    imageError.value = false\n    if (urlChanged) startDelayedLoader()\n  }\n}\n\nasync function openImageInGallery(index: number) {\n  setCurrentIndex(index)\n  viewMode.value = 'gallery'\n  await nextTick()\n  galleryPanelEl.value?.focus()\n}\n\nfunction handleGridClick(index: number) {\n  const url = imageUrls[index]\n  if (isHdrPlaceholder(url)) {\n    openHdrViewer(url)\n    return\n  }\n  void openImageInGallery(index)\n}\n\nfunction getNavigationDotClass(index: number) {\n  return cn(\n    'size-2 cursor-pointer rounded-full border-0 p-0 transition-all duration-200',\n    index === currentIndex.value\n      ? 'bg-base-foreground'\n      : 'bg-base-foreground/50 hover:bg-base-foreground/80'\n  )\n}\n\nfunction handleKeyDown(event: KeyboardEvent) {\n  if (\n    event.key === 'Escape' &&\n    viewMode.value === 'gallery' &&\n    hasMultipleImages.value\n  ) {\n    event.preventDefault()\n    viewMode.value = 'grid'\n    return\n  }\n\n  if (imageUrls.length <= 1 || viewMode.value === 'grid') return\n\n  switch (event.key) {\n    case 'ArrowLeft':\n      event.preventDefault()\n      setCurrentIndex(\n        currentIndex.value > 0 ? currentIndex.value - 1 : imageUrls.length - 1\n      )\n      break\n    case 'ArrowRight':\n      event.preventDefault()\n      setCurrentIndex(\n        currentIndex.value < imageUrls.length - 1 ? currentIndex.value + 1 : 0\n      )\n      break\n    case 'Home':\n      event.preventDefault()\n      setCurrentIndex(0)\n      break\n    case 'End':\n      event.preventDefault()\n      setCurrentIndex(imageUrls.length - 1)\n      break\n  }\n}\n\nfunction getImageFilename(url: string): string {\n  if (!url) return t('g.imageDoesNotExist')\n  try {\n    return new URL(url).searchParams.get('filename') || t('g.unknownFile')\n  } catch {\n    return t('g.imageDoesNotExist')\n  }\n}\n</script>\n","<template>\n  <div v-if=\"renderError\" class=\"node-error p-2 text-sm text-red-500\">\n    {{ st('nodeErrors.content', 'Node Content Error') }}\n  </div>\n  <div\n    v-else\n    class=\"lg-node-content flex flex-auto grow flex-col [content-visibility:auto]\"\n  >\n    <!-- Default slot for custom content -->\n    <slot>\n      <VideoPreview\n        v-if=\"hasMedia && media?.type === 'video'\"\n        :image-urls=\"media.urls\"\n        :node-id=\"nodeId\"\n        class=\"mt-2 flex-auto\"\n      />\n      <AudioPreview\n        v-else-if=\"hasMedia && media?.type === 'audio'\"\n        :audio-urls=\"media.urls\"\n        class=\"mt-2 flex-auto\"\n      />\n      <ImagePreview\n        v-else-if=\"hasMedia && media?.type === 'image'\"\n        :image-urls=\"media.urls\"\n        :node-id=\"nodeId\"\n        class=\"flex-auto\"\n        :style=\"{ marginTop: `${IMAGE_PREVIEW_MARGIN_TOP}px` }\"\n      />\n    </slot>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onErrorCaptured, ref } from 'vue'\n\nimport type { NodeState } from '@/types/nodeState'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { st } from '@/i18n'\n\nimport VideoPreview from '../VideoPreview.vue'\nimport AudioPreview from './AudioPreview.vue'\nimport ImagePreview from './ImagePreview.vue'\nimport { IMAGE_PREVIEW_MARGIN_TOP } from './imagePreviewLayout'\n\ninterface NodeContentProps {\n  nodeData?: NodeState\n  media?: {\n    type: 'image' | 'video' | 'audio'\n    urls: string[]\n  }\n}\n\nconst props = defineProps<NodeContentProps>()\n\nconst hasMedia = computed(() => props.media && props.media.urls.length > 0)\n\nconst nodeId = computed(() => props.nodeData?.id)\n\n// Error boundary implementation\nconst renderError = ref<string | null>(null)\nconst { toastErrorHandler } = useErrorHandling()\n\nonErrorCaptured((error) => {\n  renderError.value = error.message\n  toastErrorHandler(error)\n  return false\n})\n</script>\n","<template>\n  <!-- Case 1: Subgraph + Error (Dual Tabs) -->\n  <div\n    v-if=\"isSubgraph && hasAnyError && showErrorsTabEnabled\"\n    :class=\"errorWrapperStyles\"\n  >\n    <Button\n      variant=\"textonly\"\n      :class=\"\n        cn(\n          tabStyles,\n          'z-10 box-border w-1/2 rounded-none pt-9 pb-3',\n          errorColorClass,\n          errorRadiusClass\n        )\n      \"\n      @pointerup=\"snapshotDragOnPointerUp\"\n      @click.stop=\"emitIfNotDragged('openErrors')\"\n    >\n      <div class=\"flex size-full items-center justify-center gap-2\">\n        <span class=\"truncate\">{{ errorLabel }}</span>\n        <i class=\"icon-[lucide--info] size-4 shrink-0\" />\n      </div>\n    </Button>\n\n    <Button\n      variant=\"textonly\"\n      data-testid=\"subgraph-enter-button\"\n      :class=\"\n        cn(\n          tabStyles,\n          '-ml-5 box-border w-[calc(50%+20px)] rounded-none bg-node-component-header-surface pt-9 pb-3 pl-5 text-node-component-slot-text',\n          enterRadiusClass\n        )\n      \"\n      :style=\"headerColorStyle\"\n      @pointerup=\"snapshotDragOnPointerUp\"\n      @click.stop=\"emitIfNotDragged('enterSubgraph')\"\n    >\n      <div class=\"flex size-full items-center justify-center gap-2\">\n        <span class=\"truncate\">{{ t('g.enter') }}</span>\n        <i class=\"icon-[comfy--workflow] size-4 shrink-0\" />\n      </div>\n    </Button>\n  </div>\n\n  <!-- Case 1b: Advanced + Error (Dual Tabs, Regular Nodes) -->\n  <div\n    v-else-if=\"\n      !isSubgraph &&\n      hasAnyError &&\n      showErrorsTabEnabled &&\n      (showAdvancedInputsButton || showAdvancedState)\n    \"\n    :class=\"errorWrapperStyles\"\n  >\n    <Button\n      variant=\"textonly\"\n      :class=\"\n        cn(\n          tabStyles,\n          'z-10 box-border w-1/2 rounded-none pt-9 pb-3',\n          errorColorClass,\n          errorRadiusClass\n        )\n      \"\n      @pointerup=\"snapshotDragOnPointerUp\"\n      @click.stop=\"emitIfNotDragged('openErrors')\"\n    >\n      <div class=\"flex size-full items-center justify-center gap-2\">\n        <span class=\"truncate\">{{ errorLabel }}</span>\n        <i class=\"icon-[lucide--info] size-4 shrink-0\" />\n      </div>\n    </Button>\n\n    <Button\n      variant=\"textonly\"\n      data-testid=\"advanced-inputs-button\"\n      :class=\"\n        cn(\n          tabStyles,\n          '-ml-5 box-border w-[calc(50%+20px)] rounded-none bg-node-component-header-surface pt-9 pb-3 pl-5 text-node-component-slot-text',\n          enterRadiusClass\n        )\n      \"\n      :style=\"headerColorStyle\"\n      @pointerup=\"snapshotDragOnPointerUp\"\n      @click.stop=\"emitIfNotDragged('toggleAdvanced')\"\n    >\n      <div class=\"flex size-full items-center justify-center gap-2\">\n        <span class=\"truncate\">{{\n          showAdvancedState\n            ? t('rightSidePanel.hideAdvancedShort')\n            : t('rightSidePanel.showAdvancedShort')\n        }}</span>\n        <i\n          :class=\"\n            showAdvancedState\n              ? 'icon-[lucide--chevron-up] size-4 shrink-0'\n              : 'icon-[lucide--settings-2] size-4 shrink-0'\n          \"\n        />\n      </div>\n    </Button>\n  </div>\n\n  <!-- Case 2: Error Only (Full Width) -->\n  <div\n    v-else-if=\"hasAnyError && showErrorsTabEnabled\"\n    :class=\"errorWrapperStyles\"\n  >\n    <Button\n      variant=\"textonly\"\n      :class=\"\n        cn(\n          tabStyles,\n          'box-border w-full rounded-none pt-9 pb-3',\n          errorColorClass,\n          footerRadiusClass\n        )\n      \"\n      @pointerup=\"snapshotDragOnPointerUp\"\n      @click.stop=\"emitIfNotDragged('openErrors')\"\n    >\n      <div class=\"flex size-full items-center justify-center gap-2\">\n        <span class=\"truncate\">{{ errorLabel }}</span>\n        <i class=\"icon-[lucide--info] size-4 shrink-0\" />\n      </div>\n    </Button>\n  </div>\n\n  <!-- Case 3: Subgraph only (Full Width) -->\n  <div\n    v-else-if=\"isSubgraph\"\n    :class=\"\n      cn(\n        footerWrapperBase,\n        hasAnyError ? '-mx-1 -mb-2 w-[calc(100%+8px)] pb-1' : 'w-full'\n      )\n    \"\n  >\n    <Button\n      variant=\"textonly\"\n      data-testid=\"subgraph-enter-button\"\n      :class=\"\n        cn(\n          tabStyles,\n          'box-border w-full rounded-none bg-node-component-header-surface text-node-component-slot-text',\n          hasAnyError ? 'pt-9 pb-3' : 'pt-8 pb-3',\n          footerRadiusClass\n        )\n      \"\n      :style=\"headerColorStyle\"\n      @pointerup=\"snapshotDragOnPointerUp\"\n      @click.stop=\"emitIfNotDragged('enterSubgraph')\"\n    >\n      <div class=\"flex size-full items-center justify-center gap-2\">\n        <span class=\"truncate\">{{ t('g.enterSubgraph') }}</span>\n        <i class=\"icon-[comfy--workflow] size-4 shrink-0\" />\n      </div>\n    </Button>\n  </div>\n\n  <!-- Case 4: Advanced Footer (Regular Nodes) -->\n  <div\n    v-else-if=\"showAdvancedInputsButton || showAdvancedState\"\n    :class=\"\n      cn(\n        footerWrapperBase,\n        hasAnyError ? '-mx-1 -mb-2 w-[calc(100%+8px)] pb-1' : 'w-full'\n      )\n    \"\n  >\n    <Button\n      variant=\"textonly\"\n      data-testid=\"advanced-inputs-button\"\n      :class=\"\n        cn(\n          tabStyles,\n          'box-border w-full rounded-none bg-node-component-header-surface text-node-component-slot-text',\n          hasAnyError ? 'pt-9 pb-3' : 'pt-8 pb-3',\n          footerRadiusClass\n        )\n      \"\n      :style=\"headerColorStyle\"\n      @pointerup=\"snapshotDragOnPointerUp\"\n      @click.stop=\"emitIfNotDragged('toggleAdvanced')\"\n    >\n      <div class=\"flex size-full items-center justify-center gap-2\">\n        <template v-if=\"showAdvancedState\">\n          <span class=\"truncate\">{{\n            t('rightSidePanel.hideAdvancedInputsButton')\n          }}</span>\n          <i class=\"icon-[lucide--chevron-up] size-4 shrink-0\" />\n        </template>\n        <template v-else>\n          <span class=\"truncate\">{{\n            t('rightSidePanel.showAdvancedInputsButton')\n          }}</span>\n          <i class=\"icon-[lucide--settings-2] size-4 shrink-0\" />\n        </template>\n      </div>\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport Button from '@/components/ui/button/Button.vue'\nimport { RenderShape } from '@/lib/litegraph/src/litegraph'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\n\ninterface Props {\n  isSubgraph: boolean\n  errorSeverity: 'none' | 'missing' | 'error'\n  showErrorsTabEnabled: boolean\n  showAdvancedInputsButton?: boolean\n  showAdvancedState?: boolean\n  headerColor?: string\n  shape?: RenderShape\n}\n\nconst {\n  isSubgraph,\n  errorSeverity,\n  showErrorsTabEnabled,\n  showAdvancedInputsButton,\n  showAdvancedState,\n  headerColor,\n  shape\n} = defineProps<Props>()\n\nconst emit = defineEmits<{\n  enterSubgraph: []\n  openErrors: []\n  toggleAdvanced: []\n}>()\n\nconst hasAnyError = computed(() => errorSeverity !== 'none')\nconst errorLabel = computed(() =>\n  t(errorSeverity === 'missing' ? 'rightSidePanel.errors' : 'g.error')\n)\nconst errorColorClass = computed(() =>\n  errorSeverity === 'missing'\n    ? 'bg-warning-background text-warning-on-background hover:bg-warning-background-hover'\n    : 'bg-destructive-background text-white hover:bg-destructive-background-hover'\n)\n\nlet suppressNextClick = false\n\nfunction snapshotDragOnPointerUp() {\n  suppressNextClick = layoutStore.isDraggingVueNodes.value\n}\n\nfunction emitIfNotDragged(\n  name: 'enterSubgraph' | 'openErrors' | 'toggleAdvanced'\n) {\n  const wasDrag = suppressNextClick\n  suppressNextClick = false\n  if (wasDrag) return\n  if (name === 'enterSubgraph') emit('enterSubgraph')\n  else if (name === 'openErrors') emit('openErrors')\n  else emit('toggleAdvanced')\n}\n\nfunction getBottomRadius(\n  nodeShape: RenderShape | undefined,\n  corners: 'both' | 'right' = 'both'\n): string {\n  if (nodeShape === RenderShape.BOX) return ''\n  return nodeShape === RenderShape.CARD || corners === 'right'\n    ? 'rounded-br-xl'\n    : 'rounded-b-xl'\n}\n\nconst footerRadiusClass = computed(() => getBottomRadius(shape))\n\nconst errorRadiusClass = computed(() => getBottomRadius(shape))\n\nconst enterRadiusClass = computed(() => getBottomRadius(shape, 'right'))\n\nconst tabStyles = 'pointer-events-auto h-11 text-xs font-normal'\nconst footerWrapperBase = 'isolate -z-1 -mt-5 box-border flex'\nconst errorWrapperStyles = cn(\n  footerWrapperBase,\n  '-mx-1 -mb-2 w-[calc(100%+8px)] pb-1'\n)\n\nconst headerColorStyle = computed(() =>\n  headerColor ? { backgroundColor: headerColor } : undefined\n)\n</script>\n","<template>\n  <div v-if=\"renderError\" class=\"node-error p-2 text-sm text-red-500\">\n    {{ st('nodeErrors.render', 'Node Render Error') }}\n  </div>\n  <div\n    v-else\n    tabindex=\"0\"\n    :data-node-id=\"nodeData.id\"\n    :data-collapsed=\"isCollapsed || undefined\"\n    :data-ghost=\"nodeData.flags?.ghost || undefined\"\n    :class=\"\n      cn(\n        'group/node lg-node absolute isolate touch-none text-xs',\n        'flex flex-col contain-layout contain-style',\n        isLightTheme\n          ? 'drop-shadow-md drop-shadow-black/15'\n          : 'drop-shadow-xl drop-shadow-black/40',\n        isRerouteNode\n          ? 'h-(--node-height)'\n          : 'min-h-(--node-height) min-w-(--min-node-width)',\n        cursorClass,\n        isSelected && 'outline-node-component-outline',\n        executing && 'outline-node-stroke-executing',\n        shouldHandleNodePointerEvents &&\n          !nodeData.flags?.ghost &&\n          !isGhostPlacing\n          ? 'pointer-events-auto'\n          : 'pointer-events-none'\n      )\n    \"\n    :style=\"{\n      ...nodeSizeStyle,\n      '--min-node-width': `${MIN_NODE_WIDTH}px`,\n      transform: `translate(${position.x ?? 0}px, ${(position.y ?? 0) - LiteGraph.NODE_TITLE_HEIGHT}px)`,\n      zIndex: zIndex,\n      opacity: nodeOpacity\n    }\"\n    :inert=\"isGhostPlacing\"\n    v-bind=\"pointerHandlers\"\n    @wheel=\"handleWheel\"\n    @contextmenu=\"handleContextMenu\"\n    @dragover.prevent=\"handleDragOver\"\n    @dragleave=\"handleDragLeave\"\n    @drop=\"handleDrop\"\n  >\n    <AppOutput\n      v-if=\"\n        lgraphNode?.constructor?.nodeData?.output_node &&\n        isSelectOutputsMode &&\n        nodeData.mode === LGraphEventMode.ALWAYS &&\n        !hasAnyError\n      \"\n      :id=\"nodeId\"\n    />\n    <div\n      v-if=\"isSelected || executing\"\n      data-testid=\"node-state-outline-overlay\"\n      :class=\"\n        cn(\n          'pointer-events-none absolute z-0 border-3 outline-none',\n          selectionShapeClass,\n          hasAnyError ? '-inset-1.75' : '-inset-0.75',\n          isSelected\n            ? 'border-node-component-outline'\n            : 'border-node-stroke-executing'\n        )\n      \"\n    />\n    <div\n      data-testid=\"node-inner-wrapper\"\n      :class=\"\n        cn(\n          'flex flex-1 flex-col bg-node-component-header-surface',\n          'w-(--node-width)',\n          !isRerouteNode && 'min-w-(--min-node-width)',\n          shapeClass,\n          hasAnyError && 'ring-4',\n          errorSeverity === 'missing' && 'ring-warning-background',\n          errorSeverity === 'error' && 'ring-destructive-background',\n          bypassed && bypassOverlayClass,\n          muted && mutedOverlayClass,\n          isDraggingOver && 'bg-primary-500/10 ring-4 ring-primary-500'\n        )\n      \"\n      :style=\"{\n        '--component-node-background': applyLightThemeColor(nodeData.bgcolor),\n        backgroundColor: applyLightThemeColor(nodeData?.color)\n      }\"\n    >\n      <div\n        v-if=\"displayHeader\"\n        class=\"relative flex flex-col items-center justify-center\"\n      >\n        <template v-if=\"isCollapsed\">\n          <SlotConnectionDot\n            v-if=\"hasInputs\"\n            multi\n            class=\"absolute left-0 -translate-x-1/2\"\n          />\n          <SlotConnectionDot\n            v-if=\"nodeData.outputs.length\"\n            multi\n            class=\"absolute right-0 translate-x-1/2\"\n          />\n          <NodeSlots :node-data unified />\n        </template>\n        <NodeHeader\n          :node-data\n          :collapsed=\"isCollapsed\"\n          :price-badges=\"badges.pricing\"\n          @collapse=\"handleCollapse\"\n          @update:title=\"handleHeaderTitleUpdate\"\n        />\n      </div>\n\n      <div\n        v-if=\"isCollapsed && executing && progress !== undefined\"\n        :class=\"\n          cn(\n            'absolute inset-x-4 -bottom-px translate-y-1/2 rounded-full',\n            progressClasses\n          )\n        \"\n        :style=\"{ width: `${Math.min(progress * 100, 100)}%` }\"\n      />\n\n      <template v-if=\"!isCollapsed && isRerouteNode\">\n        <NodeSlots :node-data />\n      </template>\n\n      <template v-else-if=\"!isCollapsed\">\n        <div class=\"relative\">\n          <div\n            v-if=\"executing && progress !== undefined\"\n            :class=\"\n              cn(\n                'absolute inset-x-0 top-1/2 -translate-y-1/2',\n                !!(progress < 1) && 'rounded-r-full',\n                progressClasses\n              )\n            \"\n            :style=\"{ width: `${Math.min(progress * 100, 100)}%` }\"\n          />\n        </div>\n\n        <div\n          :class=\"\n            cn(\n              'flex flex-1 flex-col bg-component-node-background pt-1 pb-3',\n              bodyRoundingClass\n            )\n          \"\n          :style=\"{ rowGap: `${NODE_CONTENT_GAP}px` }\"\n          :data-testid=\"`node-body-${nodeData.id}`\"\n        >\n          <NodeSlots :node-data />\n\n          <NodeWidgets\n            v-if=\"hasRenderableWidgets\"\n            :node-data\n            :processed-widget-model\n          />\n\n          <div\n            v-if=\"hasCustomContent\"\n            :class=\"\n              cn(\n                'flex min-h-0 flex-col',\n                nodeMedia?.type === 'image' && hasExpandingWidget\n                  ? 'shrink-0'\n                  : 'flex-1'\n              )\n            \"\n          >\n            <NodeContent v-if=\"nodeMedia\" :node-data :media=\"nodeMedia\" />\n            <NodeContent\n              v-for=\"preview in promotedPreviews\"\n              :key=\"`${preview.sourceNodeId}-${preview.sourceWidgetName}`\"\n              :node-data\n              :media=\"preview\"\n            />\n          </div>\n          <LivePreview\n            v-if=\"shouldShowPreviewImg && !lgraphNode?.isSubgraphNode()\"\n            :image-url=\"latestPreviewUrl\"\n          />\n          <NodeBadges\n            v-if=\"!isTransparentHeaderless\"\n            v-bind=\"badges\"\n            :pricing=\"undefined\"\n            class=\"mt-auto\"\n          />\n        </div>\n      </template>\n    </div>\n    <NodeFooter\n      v-if=\"!isRerouteNode\"\n      :is-subgraph=\"!!lgraphNode?.isSubgraphNode()\"\n      :error-severity=\"errorSeverity\"\n      :show-errors-tab-enabled=\"showErrorsTabEnabled\"\n      :show-advanced-inputs-button=\"showAdvancedInputsButton\"\n      :show-advanced-state=\"!!nodeData.showAdvanced\"\n      :header-color=\"applyLightThemeColor(nodeData?.color)\"\n      :shape=\"nodeData.shape\"\n      @enter-subgraph=\"handleEnterSubgraph\"\n      @open-errors=\"handleOpenErrors\"\n      @toggle-advanced=\"handleToggleAdvanced\"\n    />\n    <template\n      v-if=\"\n        !isCollapsed &&\n        !isRerouteNode &&\n        nodeData.resizable !== false &&\n        !isSelectMode\n      \"\n    >\n      <div\n        v-for=\"handle in RESIZE_HANDLES\"\n        :key=\"handle.corner\"\n        role=\"button\"\n        :data-corner=\"handle.corner\"\n        :aria-label=\"t(handle.i18nKey)\"\n        :class=\"\n          cn(\n            baseResizeHandleClasses,\n            handle.positionClasses,\n            handle.cursorClass,\n            'group-hover/node:opacity-100'\n          )\n        \"\n        @pointerdown.stop=\"handleResizePointerDown($event, handle.corner)\"\n      >\n        <svg\n          xmlns=\"http://www.w3.org/2000/svg\"\n          viewBox=\"0 0 12 12\"\n          :class=\"cn('absolute size-2/5', handle.svgPositionClasses)\"\n          :style=\"\n            handle.svgTransform ? { transform: handle.svgTransform } : undefined\n          \"\n        >\n          <path\n            d=\"M11 1L1 11M11 6L6 11\"\n            stroke=\"var(--color-muted-foreground)\"\n            stroke-width=\"2\"\n            stroke-linecap=\"round\"\n            stroke-linejoin=\"round\"\n          />\n        </svg>\n      </div>\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport { computed, onErrorCaptured, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { NodeState } from '@/types/nodeState'\nimport { showNodeOptions } from '@/composables/graph/useMoreOptionsMenu'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { hasUnpromotedWidgets } from '@/core/graph/subgraph/promotionUtils'\nimport { st } from '@/i18n'\nimport type { CompassCorners } from '@/lib/litegraph/src/interfaces'\nimport { LGraphEventMode, LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { SubgraphNode } from '@/lib/litegraph/src/subgraph/SubgraphNode'\nimport { TitleMode } from '@/lib/litegraph/src/types/globalEnums'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport { useGLSLPreview } from '@/renderer/glsl/useGLSLPreview'\nimport { usePromotedPreviews } from '@/composables/node/usePromotedPreviews'\nimport NodeBadges from '@/renderer/extensions/vueNodes/components/NodeBadges.vue'\nimport { LayoutSource } from '@/renderer/core/layout/types'\nimport { removeNodeTitleHeight } from '@/renderer/core/layout/utils/nodeSizeUtil'\nimport AppOutput from '@/renderer/extensions/linearMode/AppOutput.vue'\nimport SlotConnectionDot from '@/renderer/extensions/vueNodes/components/SlotConnectionDot.vue'\nimport { useNodeEventHandlers } from '@/renderer/extensions/vueNodes/composables/useNodeEventHandlers'\nimport { useNodePointerInteractions } from '@/renderer/extensions/vueNodes/composables/useNodePointerInteractions'\nimport { usePartitionedBadges } from '@/renderer/extensions/vueNodes/composables/usePartitionedBadges'\nimport { useProcessedWidgets } from '@/renderer/extensions/vueNodes/composables/useProcessedWidgets'\nimport { useVueElementTracking } from '@/renderer/extensions/vueNodes/composables/useVueNodeResizeTracking'\nimport { useNodeExecutionState } from '@/renderer/extensions/vueNodes/execution/useNodeExecutionState'\nimport { useNodeLayout } from '@/renderer/extensions/vueNodes/layout/useNodeLayout'\nimport { useNodePreviewState } from '@/renderer/extensions/vueNodes/preview/useNodePreviewState'\nimport {\n  shouldHideLinkedCoreLoadAudioPlayer,\n  shouldHideLinkedCoreMediaInputPreview\n} from '@/renderer/extensions/vueNodes/utils/linkedCoreMediaUtils'\nimport { nonWidgetedInputs } from '@/renderer/extensions/vueNodes/utils/nodeDataUtils'\nimport { getNodeErrorSeverity } from '@/renderer/extensions/vueNodes/utils/nodeErrorState'\nimport { shouldExpand } from '@/renderer/extensions/vueNodes/widgets/registry/widgetRegistry'\nimport {\n  applyLightThemeColor,\n  shapeVariantClass\n} from '@/renderer/extensions/vueNodes/utils/nodeStyleUtils'\nimport { app } from '@/scripts/app'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport {\n  stripGraphPrefix,\n  useWidgetValueStore\n} from '@/stores/widgetValueStore'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\nimport { isVideoOutput } from '@/utils/litegraphUtil'\nimport {\n  getNodeByLocatorId,\n  locatorIdFromState\n} from '@/utils/graphTraversalUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { isTransparent } from '@/utils/colorUtil'\n\nimport { resizeNodeLayout } from '@/renderer/core/layout/operations/graphLayoutAttachment'\nimport { MIN_NODE_WIDTH } from '@/renderer/core/layout/transform/graphRenderTransform'\n\nimport { RESIZE_HANDLES } from '../interactions/resize/resizeHandleConfig'\nimport { useNodeResize } from '../interactions/resize/useNodeResize'\nimport LivePreview from './LivePreview.vue'\nimport NodeContent from './NodeContent.vue'\nimport NodeHeader from './NodeHeader.vue'\nimport NodeFooter from './NodeFooter.vue'\nimport NodeSlots from './NodeSlots.vue'\nimport NodeWidgets from './NodeWidgets.vue'\nimport {\n  IMAGE_PREVIEW_HEIGHT_RESERVE,\n  NODE_CONTENT_GAP\n} from './imagePreviewLayout'\n\nconst { nodeData } = defineProps<{\n  nodeData: NodeState\n}>()\n\nconst { t } = useI18n()\n\nconst { isSelectMode, isSelectOutputsMode } = useAppMode()\nconst settingStore = useSettingStore()\nconst colorPaletteStore = useColorPaletteStore()\nconst isLightTheme = computed(\n  () => !!colorPaletteStore.completedActivePalette.light_theme\n)\n\nconst { handleNodeCollapse, handleNodeTitleUpdate, handleNodeRightClick } =\n  useNodeEventHandlers()\n\nconst nodeId = computed(() => nodeData.id)\n\nuseVueElementTracking(nodeId.value, 'node')\n\nconst canvasStore = useCanvasStore()\n\nconst { selectedNodeIds, isGhostPlacing } = storeToRefs(useCanvasStore())\nconst isSelected = computed(() => {\n  return selectedNodeIds.value.has(nodeId.value)\n})\n\nconst nodeLocatorId = computed(\n  () => locatorIdFromState(nodeData, canvasStore.rootGraphId) ?? undefined\n)\nconst { executing, progress } = useNodeExecutionState(nodeLocatorId)\nconst errorSeverity = computed(() =>\n  getNodeErrorSeverity(nodeData, canvasStore.rootGraphId, lgraphNode.value)\n)\n\nconst hasAnyError = computed(() => errorSeverity.value !== 'none')\n\nconst showErrorsTabEnabled = computed(() =>\n  settingStore.get('Comfy.RightSidePanel.ShowErrorsTab')\n)\n\nconst displayHeader = computed(() => nodeData.titleMode !== TitleMode.NO_TITLE)\n\nconst isRerouteNode = computed(() => nodeData.type === 'Reroute')\n\nconst isCollapsed = computed(() => nodeData.flags?.collapsed ?? false)\nconst bypassed = computed(\n  (): boolean => nodeData.mode === LGraphEventMode.BYPASS\n)\nconst muted = computed((): boolean => nodeData.mode === LGraphEventMode.NEVER)\n\nconst nodeOpacity = computed(() => {\n  const globalOpacity = settingStore.get('Comfy.Node.Opacity') ?? 1\n\n  if (nodeData.flags?.ghost) return globalOpacity * 0.6\n\n  // For muted/bypassed nodes, apply the 0.5 multiplier on top of global opacity\n  if (bypassed.value || muted.value) {\n    return globalOpacity * 0.5\n  }\n\n  return globalOpacity\n})\n\nconst hasInputs = computed(() => nonWidgetedInputs(nodeData.inputs).length > 0)\n\n// Use canvas interactions for proper wheel event handling and pointer event capture control\nconst { handleWheel, shouldHandleNodePointerEvents } = useCanvasInteractions()\n\n// Error boundary implementation\nconst renderError = ref<string | null>(null)\nconst { toastErrorHandler } = useErrorHandling()\n\nonErrorCaptured((error) => {\n  renderError.value = error.message\n  toastErrorHandler(error)\n  return false // Prevent error propagation\n})\n\nconst { position, size, zIndex } = useNodeLayout(() => nodeData.id)\n\nconst imagePreviewGrowth = computed(() =>\n  nodeMedia.value?.type === 'image' && hasExpandingWidget.value\n    ? IMAGE_PREVIEW_HEIGHT_RESERVE\n    : 0\n)\n\nconst nodeSizeStyle = computed(() =>\n  isCollapsed.value\n    ? {}\n    : {\n        '--node-width': `${size.value.width}px`,\n        '--node-height': `${size.value.height + LiteGraph.NODE_TITLE_HEIGHT + imagePreviewGrowth.value}px`\n      }\n)\n\nconst { pointerHandlers } = useNodePointerInteractions(() => nodeData)\nconst badges = usePartitionedBadges(nodeData)\n\n// Handle right-click context menu\nconst handleContextMenu = (event: MouseEvent) => {\n  event.preventDefault()\n  event.stopPropagation()\n\n  // First handle the standard right-click behavior (selection)\n  handleNodeRightClick(event, nodeData.id)\n\n  // Show the node options menu at the cursor position\n  showNodeOptions(event, { nodeId: nodeData.id })\n}\n\nconst baseResizeHandleClasses =\n  'absolute h-5 w-5 opacity-0 pointer-events-auto focus-visible:outline focus-visible:outline-2 focus-visible:outline-white/40 touch-none'\n\nconst { startResize } = useNodeResize((result) => {\n  if (isCollapsed.value) return\n  const node = resolveLGraphNode()\n  if (!node) return\n\n  resizeNodeLayout(\n    node,\n    {\n      width: Math.max(result.size.width, MIN_NODE_WIDTH),\n      height:\n        removeNodeTitleHeight(result.size.height) - imagePreviewGrowth.value\n    },\n    {\n      position: result.position,\n      source: LayoutSource.Vue\n    }\n  )\n})\n\nconst handleResizePointerDown = (\n  event: PointerEvent,\n  corner: CompassCorners\n) => {\n  if (event.button !== 0) return\n  if (!shouldHandleNodePointerEvents.value) return\n  if (nodeData.flags?.pinned) return\n  if (nodeData.resizable === false) return\n  startResize(event, corner)\n}\n\n// Check if node has custom content (like image/video outputs)\nconst hasCustomContent = computed(() => {\n  if (promotedPreviews.value.length > 0) return true\n  return !!nodeMedia.value && nodeMedia.value.urls.length > 0\n})\n\n// Computed classes and conditions for better reusability\nconst progressClasses = 'h-2 bg-primary-500 transition-all duration-300'\n\nconst { latestPreviewUrl, shouldShowPreviewImg } = useNodePreviewState(\n  () => nodeData.id,\n  {\n    isCollapsed\n  }\n)\n\nconst cursorClass = computed(() => {\n  if (nodeData.flags?.pinned) return 'cursor-default'\n  return layoutStore.isDraggingVueNodes.value\n    ? 'cursor-grabbing'\n    : 'cursor-grab'\n})\n\nconst bodyRoundingClass = computed(() =>\n  shapeVariantClass(nodeData.shape, {\n    box: '',\n    card: 'rounded-br-xl',\n    default: 'rounded-b-xl'\n  })\n)\n\nconst shapeClass = computed(() =>\n  shapeVariantClass(nodeData.shape, {\n    box: '',\n    card: 'rounded-tl-xl rounded-br-xl',\n    default: 'rounded-xl'\n  })\n)\n\nconst isTransparentHeaderless = computed(\n  () =>\n    !displayHeader.value &&\n    !!nodeData.bgcolor &&\n    isTransparent(nodeData.bgcolor)\n)\n\nconst selectionShapeClass = computed(() => {\n  if (isTransparentHeaderless.value) return 'border-0'\n\n  const isExpanded = hasAnyError.value\n  return shapeVariantClass(nodeData.shape, {\n    box: '',\n    card: isExpanded\n      ? 'rounded-tl-[23px] rounded-br-[23px]'\n      : 'rounded-tl-[19px] rounded-br-[19px]',\n    default: isExpanded ? 'rounded-[19px]' : 'rounded-[15px]'\n  })\n})\n\nconst BEFORE_OVERLAY_BASE =\n  'before:pointer-events-none before:absolute before:inset-0'\n\nconst bypassOverlayClass = computed(() =>\n  shapeVariantClass(nodeData.shape, {\n    box: `${BEFORE_OVERLAY_BASE} before:bg-bypass/60`,\n    card: `before:rounded-tl-xl before:rounded-br-xl ${BEFORE_OVERLAY_BASE} before:bg-bypass/60`,\n    default: `before:rounded-xl ${BEFORE_OVERLAY_BASE} before:bg-bypass/60`\n  })\n)\n\nconst mutedOverlayClass = computed(() =>\n  shapeVariantClass(nodeData.shape, {\n    box: BEFORE_OVERLAY_BASE,\n    card: `before:rounded-tl-xl before:rounded-br-xl ${BEFORE_OVERLAY_BASE}`,\n    default: `before:rounded-xl ${BEFORE_OVERLAY_BASE}`\n  })\n)\n\n// Event handlers\nconst handleCollapse = () => {\n  handleNodeCollapse(nodeData.id, !isCollapsed.value)\n}\n\nconst handleHeaderTitleUpdate = (newTitle: string) => {\n  handleNodeTitleUpdate(nodeData.id, newTitle)\n}\n\nconst rightSidePanelStore = useRightSidePanelStore()\n\nconst handleOpenErrors = () => {\n  rightSidePanelStore.openPanel('errors')\n}\n\nconst handleToggleAdvanced = () => {\n  const node = resolveLGraphNode()\n  if (!node) return\n\n  // A subgraph node has no advanced section of its own; the side panel hosts it.\n  if (node instanceof SubgraphNode) {\n    if (rightSidePanelStore.isOpen) rightSidePanelStore.closePanel()\n    else rightSidePanelStore.focusSection('advanced-inputs')\n    return\n  }\n  node.showAdvanced = !node.showAdvanced\n}\n\nconst handleEnterSubgraph = () => {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'graph_node_open_subgraph_clicked',\n    element_group: 'graph_node'\n  })\n  const graph = app.rootGraph\n  if (!graph) {\n    console.warn('LGraphNode: No graph available for subgraph navigation')\n    return\n  }\n\n  const locatorId = nodeLocatorId.value\n  if (!locatorId) return\n\n  const litegraphNode = getNodeByLocatorId(graph, locatorId)\n\n  if (!litegraphNode?.isSubgraphNode() || !('subgraph' in litegraphNode)) {\n    console.warn('LGraphNode: Node is not a valid subgraph node', litegraphNode)\n    return\n  }\n\n  const canvas = app.canvas\n  if (!canvas || typeof canvas.openSubgraph !== 'function') {\n    console.warn('LGraphNode: Canvas or openSubgraph method not available')\n    return\n  }\n\n  canvas.openSubgraph(litegraphNode.subgraph, litegraphNode)\n}\n\nconst nodeOutputs = useNodeOutputStore()\n\nfunction resolveLGraphNode() {\n  const locatorId = nodeLocatorId.value\n  if (!locatorId) return null\n\n  return getNodeByLocatorId(app.rootGraph, locatorId)\n}\n\nconst lgraphNode = computed(resolveLGraphNode)\n\n// TODO: Surface subgraph info more cleanly in NodeState instead of\n// reaching through lgraphNode for promoted preview resolution.\nconst { promotedPreviews } = usePromotedPreviews(lgraphNode)\n\nconst { hideExecutedOutput } = useGLSLPreview(lgraphNode)\n\nconst widgetValueStore = useWidgetValueStore()\nconst widgetIds = computed(() => {\n  const graphId = canvasStore.rootGraphId\n  const bareNodeId = stripGraphPrefix(nodeData.id)\n  if (!graphId || !bareNodeId) return []\n\n  return widgetValueStore.getNodeWidgetIds(graphId, bareNodeId) ?? []\n})\n\nconst renderedWidgetIds = computed(() => {\n  const node = lgraphNode.value\n  if (!node || !shouldHideLinkedCoreLoadAudioPlayer(node))\n    return widgetIds.value\n\n  return widgetIds.value.filter((id) => {\n    const widget = widgetValueStore.getWidget(id)\n    return widget?.name !== 'audioUI' || widget.type !== 'audioUI'\n  })\n})\n\nconst hasRenderableWidgets = computed(() => renderedWidgetIds.value.length > 0)\nconst { canSelectInputs, nodeType, processedWidgets } = useProcessedWidgets(\n  () => nodeData,\n  () => renderedWidgetIds.value\n)\nconst processedWidgetModel = computed(() => ({\n  processedWidgets: processedWidgets.value,\n  nodeType: nodeType.value,\n  canSelectInputs: canSelectInputs.value\n}))\nconst hasExpandingWidget = computed(() =>\n  processedWidgets.value.some(\n    (widget) => widget.visible && shouldExpand(widget.simplified.type)\n  )\n)\n\nconst showAdvancedInputsButton = computed(() => {\n  const node = lgraphNode.value\n  if (!node) return false\n  if (isCollapsed.value) return false\n  if (node instanceof SubgraphNode) {\n    return hasUnpromotedWidgets(node)\n  }\n\n  const hasAdvancedWidgets = widgetIds.value.some((id) => {\n    const visibility = widgetValueStore.getWidgetVisibility(id)\n    if (visibility) return visibility.surfaces.vueNode === 'advanced'\n    return widgetValueStore.getWidget(id)?.options?.advanced\n  })\n  const alwaysShowAdvanced = settingStore.get(\n    'Comfy.Node.AlwaysShowAdvancedWidgets'\n  )\n  return hasAdvancedWidgets && !alwaysShowAdvanced\n})\n\nconst hasVideoInput = computed(() =>\n  nodeData.inputs.some((input) => input.type === 'VIDEO')\n)\n\nconst hasVideoEditWidget = computed(() =>\n  widgetIds.value.some(\n    (id) => widgetValueStore.getWidget(id)?.type === 'videoedit'\n  )\n)\n\nconst nodeMedia = computed(() => {\n  const locatorId = nodeLocatorId.value\n  const newOutputs = locatorId ? nodeOutputs.nodeOutputs[locatorId] : undefined\n  const node = lgraphNode.value\n\n  if (\n    !node ||\n    !newOutputs?.images?.length ||\n    node.hideOutputImages ||\n    hideExecutedOutput.value\n  )\n    return undefined\n\n  if (node instanceof SubgraphNode) return undefined\n  if (shouldHideLinkedCoreMediaInputPreview(node, newOutputs)) return undefined\n\n  const urls = nodeOutputs.getNodeImageUrls(node)\n  if (!urls?.length) return undefined\n\n  const type =\n    isVideoOutput(newOutputs) ||\n    node.previewMediaType === 'video' ||\n    (!node.previewMediaType && hasVideoInput.value)\n      ? 'video'\n      : 'image'\n\n  if (type === 'video' && hasVideoEditWidget.value) return undefined\n\n  return { type, urls } as const\n})\n\n// Drag and drop support\nconst isDraggingOver = ref(false)\n\nfunction handleDragOver(event: DragEvent) {\n  const node = resolveLGraphNode()\n  if (!node || !node.onDragOver) {\n    isDraggingOver.value = false\n    return\n  }\n\n  // Call the litegraph node's onDragOver callback to check if files are valid\n  const canDrop = node.onDragOver(event)\n  isDraggingOver.value = canDrop\n}\n\nfunction handleDragLeave() {\n  isDraggingOver.value = false\n}\n\nfunction handleDrop(event: DragEvent) {\n  isDraggingOver.value = false\n  app.dragOverNode = event.defaultPrevented ? null : resolveLGraphNode()\n}\n</script>\n","import { useSettingStore } from '@/platform/settings/settingStore'\nimport { bootstrapTracer } from '@/platform/telemetry/perf/bootstrapTracer'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { api } from '@/scripts/api'\nimport { useExtensionStore } from '@/stores/extensionStore'\nimport { getErrorMessage } from '@/utils/errorUtil'\n\nconst INLINED_CLOUD_EXTENSIONS = new Set([\n  '/extensions/cloud/rum.js',\n  '/extensions/cloud/sentry.js'\n])\n\nexport function shouldLoadExtension(\n  extension: string,\n  isCloudBuild: boolean\n): boolean {\n  if (extension.includes('extensions/core')) return false\n  return !isCloudBuild || !INLINED_CLOUD_EXTENSIONS.has(extension)\n}\n\nconst MAX_NAMED_FAILED_EXTENSIONS = 10\n\nexport interface ExtensionLoadFailure {\n  ext: string\n  error: unknown\n}\n\n/**\n * Import one backend-provided extension, returning the failure rather than\n * throwing, so one broken pack cannot abort the rest of the parallel load.\n *\n * Reporting deliberately does not happen here. A systemic failure — a backend\n * restart, or a proxy serving HTML for every `.js` — fails every import in the\n * list, and one report per extension is then unbounded. Off cloud that is\n * actively harmful: with no sink live, each report is held in `reportError`'s\n * 25-entry pending buffer, so a handful of broken packs during bootstrap would\n * silently crowd out every later error in the session. The batch is reported\n * once, by `reportExtensionLoadFailures`.\n */\nasync function importCustomExtension(\n  ext: string\n): Promise<ExtensionLoadFailure | undefined> {\n  try {\n    await import(/* @vite-ignore */ api.fileURL(ext))\n  } catch (error) {\n    return { ext, error }\n  }\n}\n\n/**\n * The paths go in the message because `reportError` writes its console line\n * from the error, not from `options.tags`. The count is tagged; backend paths\n * are unbounded and belong in context instead of an indexed facet.\n */\nexport function reportExtensionLoadFailures(\n  failures: ExtensionLoadFailure[]\n): void {\n  if (failures.length === 0) return\n\n  const named = failures.slice(0, MAX_NAMED_FAILED_EXTENSIONS)\n  const elided = failures.length - named.length\n  const paths = named.map(({ ext }) => ext).join(', ')\n  const noun = failures.length === 1 ? 'extension' : 'extensions'\n\n  reportError(\n    new Error(\n      `Error loading ${failures.length} ${noun}: ${paths}` +\n        (elided > 0 ? ` (+${elided} more)` : ''),\n      { cause: failures[0].error }\n    ),\n    {\n      errorType: 'error_loading_extension',\n      surface: 'platform',\n      level: 'warning',\n      tags: { failed_extension_count: failures.length },\n      context: {\n        failures: named.map(({ ext, error }) => ({\n          ext,\n          message: getErrorMessage(error)\n        }))\n      }\n    }\n  )\n}\n\n/**\n * Loads the core extensions, then every extension served by the backend, in\n * parallel. Core extensions load first because custom extensions may depend\n * on them.\n */\nexport async function loadExtensions() {\n  const extensionStore = useExtensionStore()\n  extensionStore.loadDisabledExtensionNames(\n    useSettingStore().get('Comfy.Extension.Disabled')\n  )\n\n  const extensions = await api.getExtensions()\n\n  await bootstrapTracer.settle(\n    'bootstrap/extensions-load-core',\n    () => import('@/extensions/core/index')\n  )\n  extensionStore.captureCoreExtensions()\n  const outcomes = await bootstrapTracer.settle(\n    'bootstrap/extensions-load-custom',\n    () =>\n      Promise.all(\n        extensions\n          .filter((extension) =>\n            shouldLoadExtension(extension, __DISTRIBUTION__ === 'cloud')\n          )\n          .map((ext) => importCustomExtension(ext))\n      )\n  )\n  reportExtensionLoadFailures(outcomes.filter((outcome) => !!outcome))\n}\n","<template>\n  <div\n    v-show=\"isVisible\"\n    data-testid=\"selection-rectangle\"\n    class=\"pointer-events-none absolute z-9999 border border-blue-400 bg-blue-500/20\"\n    :style=\"rectangleStyle\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { useRafFn } from '@vueuse/core'\nimport { computed, ref } from 'vue'\n\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { clipRectToBounds } from '@/utils/mathUtil'\nimport type { RectEdges } from '@/utils/mathUtil'\n\nconst { panelEl } = defineProps<{\n  /** Clip surface owned by the caller; the rectangle renders unclipped when absent. */\n  panelEl?: HTMLElement\n}>()\n\nconst canvasStore = useCanvasStore()\n\nconst selectionRect = ref<{\n  x: number\n  y: number\n  w: number\n  h: number\n} | null>(null)\nconst panelBounds = ref<RectEdges>()\n\nuseRafFn(() => {\n  const canvas = canvasStore.canvas\n  if (!canvas) return\n\n  const { pointer, dragging_rectangle } = canvas\n\n  if (dragging_rectangle && pointer.eDown && pointer.eMove) {\n    if (!selectionRect.value) {\n      panelBounds.value = getCanvasPanelBounds(canvas.canvas)\n    }\n    const x = pointer.eDown.safeOffsetX\n    const y = pointer.eDown.safeOffsetY\n    const w = pointer.eMove.safeOffsetX - x\n    const h = pointer.eMove.safeOffsetY - y\n\n    selectionRect.value = { x, y, w, h }\n  } else {\n    selectionRect.value = null\n    panelBounds.value = undefined\n  }\n})\n\nconst isVisible = computed(() => selectionRect.value !== null)\n\nfunction getCanvasPanelBounds(\n  canvasEl: HTMLCanvasElement\n): RectEdges | undefined {\n  if (!panelEl) return undefined\n\n  const panel = panelEl.getBoundingClientRect()\n  const canvas = canvasEl.getBoundingClientRect()\n  return {\n    left: panel.left - canvas.left,\n    top: panel.top - canvas.top,\n    right: panel.right - canvas.left,\n    bottom: panel.bottom - canvas.top\n  }\n}\n\nconst rectangleStyle = computed(() => {\n  const rect = selectionRect.value\n  if (!rect) return {}\n\n  const edges: RectEdges = {\n    left: rect.w >= 0 ? rect.x : rect.x + rect.w,\n    top: rect.h >= 0 ? rect.y : rect.y + rect.h,\n    right: rect.w >= 0 ? rect.x + rect.w : rect.x,\n    bottom: rect.h >= 0 ? rect.y + rect.h : rect.y\n  }\n  const bounds = panelBounds.value\n  const { left, top, right, bottom } = bounds\n    ? clipRectToBounds(edges, bounds)\n    : edges\n\n  return {\n    left: `${left}px`,\n    top: `${top}px`,\n    width: `${right - left}px`,\n    height: `${bottom - top}px`\n  }\n})\n</script>\n","import { useRoute, useRouter } from 'vue-router'\n\nimport {\n  clearPreservedQuery,\n  hydratePreservedQuery,\n  mergePreservedQueryIntoQuery\n} from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\n\nconst NAMESPACE = PRESERVED_QUERY_NAMESPACES.ASSETS\nconst ASSETS_TAB_ID = 'assets'\n\n/**\n * Opens the Assets sidebar panel from an `?assets=1` deep link, so external\n * surfaces like comfy.org can send a visitor from a saved generation to the\n * library that holds the rest of them.\n *\n * Only `1` opens the panel; any other value is a silent no-op with the param\n * stripped. Survives the login redirect via the preserved-query system, like\n * the settings and top-up URL loaders.\n */\nexport function useAssetsUrlLoader() {\n  const route = useRoute()\n  const router = useRouter()\n  const sidebarTabStore = useSidebarTabStore()\n\n  /** Reads `?assets=`, strips it, and opens the Assets panel. Resolves once\n   * the strip has landed, so the loader that runs next reads a query this one\n   * has already cleaned rather than restoring the param. */\n  async function loadAssetsFromUrl() {\n    hydratePreservedQuery(NAMESPACE)\n    const query =\n      mergePreservedQueryIntoQuery(NAMESPACE, route.query) ?? route.query\n    const param = query.assets\n    if (param === undefined) return\n\n    // Strip the param (even an unrecognized value) and write the clean URL in\n    // a single replace, so the URL is clean even if the replace rejects.\n    const cleanQuery = { ...query }\n    delete cleanQuery.assets\n    const stripped = router.replace({ query: cleanQuery }).catch((error) => {\n      console.warn('[useAssetsUrlLoader] Failed to clean URL params:', error)\n    })\n    clearPreservedQuery(NAMESPACE)\n\n    // Assigned rather than toggled: a deep link must leave the panel open,\n    // including for a visitor who already had it open.\n    if (param === '1') sidebarTabStore.activeSidebarTabId = ASSETS_TAB_ID\n\n    await stripped\n  }\n\n  return {\n    loadAssetsFromUrl\n  }\n}\n","import { useRoute, useRouter } from 'vue-router'\n\nimport {\n  clearPreservedQuery,\n  hydratePreservedQuery,\n  mergePreservedQueryIntoQuery\n} from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { paymentIntentSourceForAddCreditsClick } from '@/platform/telemetry/utils/paymentIntentSource'\nimport { useBillingCapabilities } from '@/platform/workspace/composables/useBillingCapabilities'\nimport { useBillingDialogs } from '@/composables/billing/useBillingDialogs'\n\nconst NAMESPACE = PRESERVED_QUERY_NAMESPACES.TOPUP\n\n/**\n * Opens the credit top-up dialog from a `?topup=1` deep link, to send existing\n * paid users straight to buying more credits (lifecycle emails).\n *\n * Gated to users who can top up; an ineligible user is a silent no-op with the\n * param stripped. Survives the login redirect via the preserved-query system,\n * like the pricing URL loader.\n */\nexport function useTopUpUrlLoader() {\n  const route = useRoute()\n  const router = useRouter()\n  const { showTopUpCreditsDialog } = useBillingDialogs()\n  const { canTopUp, canSubscribeSelfServe, initialize } =\n    useBillingCapabilities()\n  const telemetry = useTelemetry()\n\n  /** Reads `?topup=`, strips it, and opens the dialog when the gate allows. */\n  async function loadTopUpFromUrl() {\n    hydratePreservedQuery(NAMESPACE)\n    const query =\n      mergePreservedQueryIntoQuery(NAMESPACE, route.query) ?? route.query\n    const param = query.topup\n    if (param === undefined) return\n\n    const shouldOpen = typeof param === 'string' && param.length > 0\n    if (shouldOpen) await initialize()\n\n    // Strip any present topup param (even ineligible or malformed values) and\n    // write the clean URL in a single replace once capability loading settles.\n    const cleanQuery = { ...query }\n    delete cleanQuery.topup\n    router.replace({ query: cleanQuery }).catch((error) => {\n      console.warn('[useTopUpUrlLoader] Failed to clean URL params:', error)\n    })\n    clearPreservedQuery(NAMESPACE)\n\n    // Only a non-empty string value opens the dialog; an empty/array param\n    // just gets stripped above.\n    if (!shouldOpen) return\n\n    if (!canTopUp.value && !canSubscribeSelfServe.value) return\n\n    if (canTopUp.value) {\n      telemetry?.trackAddApiCreditButtonClicked({ source: 'deep_link' })\n    }\n\n    void showTopUpCreditsDialog({\n      source: paymentIntentSourceForAddCreditsClick('deep_link')\n    })\n  }\n\n  return {\n    loadTopUpFromUrl\n  }\n}\n","import { useRoute, useRouter } from 'vue-router'\n\nimport {\n  clearPreservedQuery,\n  hydratePreservedQuery,\n  mergePreservedQueryIntoQuery\n} from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport type { SettingPanelType } from '@/platform/settings/types'\n\nconst NAMESPACE = PRESERVED_QUERY_NAMESPACES.SETTINGS\n\nconst DEEP_LINKABLE_PANELS: Record<string, SettingPanelType> = {\n  'plan-credits': 'workspace'\n}\n\n/**\n * Opens the Settings dialog on a named panel from a `?settings=` deep link\n * (e.g. `?settings=plan-credits`), so external surfaces like platform.comfy.org\n * can land users directly on the tab where they complete billing actions.\n *\n * Only values in `DEEP_LINKABLE_PANELS` open a panel; any other value is a\n * silent no-op with the param stripped. Survives the login redirect via the\n * preserved-query system, like the top-up URL loader.\n */\nexport function useSettingsUrlLoader() {\n  const route = useRoute()\n  const router = useRouter()\n  const settingsDialog = useSettingsDialog()\n\n  /** Reads `?settings=`, strips it, and opens the mapped Settings panel.\n   * Resolves once the strip has landed, so the loader that runs next reads a\n   * query this one has already cleaned rather than restoring the param. */\n  async function loadSettingsFromUrl() {\n    hydratePreservedQuery(NAMESPACE)\n    const query =\n      mergePreservedQueryIntoQuery(NAMESPACE, route.query) ?? route.query\n    const param = query.settings\n    if (param === undefined) return\n\n    // Strip any present settings param (even unrecognized or malformed values)\n    // and write the clean URL in a single replace, so a clean URL is\n    // guaranteed even if the replace rejects or no panel matches.\n    const cleanQuery = { ...query }\n    delete cleanQuery.settings\n    const stripped = router.replace({ query: cleanQuery }).catch((error) => {\n      console.warn('[useSettingsUrlLoader] Failed to clean URL params:', error)\n    })\n    clearPreservedQuery(NAMESPACE)\n\n    if (\n      typeof param === 'string' &&\n      param &&\n      Object.hasOwn(DEEP_LINKABLE_PANELS, param)\n    ) {\n      settingsDialog.show(DEEP_LINKABLE_PANELS[param])\n    }\n\n    await stripped\n  }\n\n  return {\n    loadSettingsFromUrl\n  }\n}\n","import { useRoute, useRouter } from 'vue-router'\n\nimport {\n  clearPreservedQuery,\n  hydratePreservedQuery,\n  mergePreservedQueryIntoQuery\n} from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\nimport { useWorkspaceDialogs } from '@/platform/workspace/composables/useWorkspaceDialogs'\n\nconst NAMESPACE = PRESERVED_QUERY_NAMESPACES.CREATE_WORKSPACE\n\n/**\n * Composable for opening the team workspaces dialog via URL query parameter.\n *\n * Supports URLs like:\n * - /?create_workspace=1 (opens the team workspaces dialog)\n *\n * The parameter is preserved through login redirects via the\n * preserved query system (sessionStorage), following the same pattern\n * as the invite URL loader.\n */\nexport function useCreateWorkspaceUrlLoader() {\n  const route = useRoute()\n  const router = useRouter()\n  const { showTeamWorkspacesDialog } = useWorkspaceDialogs()\n\n  /**\n   * Opens the team workspaces dialog if `?create_workspace=1` is present.\n   *\n   * Flow:\n   * 1. Restore preserved query (for post-login redirect)\n   * 2. Check for create_workspace param in route.query\n   * 3. Open the team workspaces dialog\n   * 4. Clean up URL and preserved query\n   */\n  async function loadCreateWorkspaceFromUrl() {\n    hydratePreservedQuery(NAMESPACE)\n    const mergedQuery = mergePreservedQueryIntoQuery(NAMESPACE, route.query)\n    if (mergedQuery) {\n      await router.replace({ query: mergedQuery })\n    }\n\n    const query = mergedQuery ?? route.query\n    const param = query.create_workspace\n    if (!param || typeof param !== 'string') return\n\n    const newQuery = { ...route.query }\n    delete newQuery.create_workspace\n    router.replace({ query: newQuery }).catch((error) => {\n      console.warn(\n        '[useCreateWorkspaceUrlLoader] Failed to clean URL params:',\n        error\n      )\n    })\n    clearPreservedQuery(NAMESPACE)\n\n    try {\n      await showTeamWorkspacesDialog()\n    } catch (error) {\n      console.error(\n        '[useCreateWorkspaceUrlLoader] Failed to open create workspace dialog:',\n        error\n      )\n    }\n  }\n\n  return {\n    loadCreateWorkspaceFromUrl\n  }\n}\n","import { readWorkspaceLink } from '@comfyorg/account-core/workspaceLink'\nimport type { WorkspaceLinkRead } from '@comfyorg/account-core/workspaceLink'\nimport { storeToRefs } from 'pinia'\nimport { useI18n } from 'vue-i18n'\nimport type { LocationQueryRaw } from 'vue-router'\nimport { useRoute, useRouter } from 'vue-router'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport {\n  clearPreservedQuery,\n  hydratePreservedQuery,\n  mergePreservedQueryIntoQuery\n} from '@/platform/navigation/preservedQueryManager'\nimport { PRESERVED_QUERY_NAMESPACES } from '@/platform/navigation/preservedQueryNamespaces'\n\nimport { useWorkspaceSwitch } from './useWorkspaceSwitch'\nimport { useTeamWorkspaceStore } from '../stores/teamWorkspaceStore'\n\nconst NAMESPACE = PRESERVED_QUERY_NAMESPACES.WORKSPACE\n\n/**\n * Reads the `workspace` link from a merged query. `undefined` only when the\n * key itself is absent. A repeated value (still possible when the stash\n * predates router.ts's `rejectRepeated`, or from a caller that bypasses the\n * tracker) joins with `,`, outside any real workspace id's charset, so it\n * still resolves to `invalid`. A bare `?workspace` (no `=`) reaches the\n * router as `null` — present but empty — which readWorkspaceLink can't tell\n * apart from truly absent (both serialize to `''` in a URLSearchParams\n * value), so it's classified `invalid` directly here instead.\n */\nfunction readWorkspaceLinkFromQuery(\n  query: LocationQueryRaw\n): WorkspaceLinkRead | undefined {\n  const raw = query.workspace\n  if (raw === undefined) return undefined\n\n  const values = Array.isArray(raw) ? raw : [raw]\n  if (values.includes(null)) return { status: 'invalid' }\n\n  return readWorkspaceLink(new URLSearchParams({ workspace: values.join(',') }))\n}\n\n/**\n * Opens the workspace a `?workspace=` deep link names, before any other URL\n * action loader runs — so `?settings=plan-credits&workspace=w-1` opens\n * Settings on the requested workspace rather than the active one.\n *\n * A navigation destination: a member switches into the named workspace: a\n * non-member, a gone workspace, or an invalid link stays on the active\n * workspace, but always says which one that is via a toast, per the\n * workspace deep-link contract (`@comfyorg/account-core/workspaceLink`).\n * Absent is a silent no-op. Survives the login redirect via the\n * preserved-query system, like the other loaders — a repeated value is\n * stashed joined with `,` (router.ts's `rejectRepeated`), so it still reads\n * as invalid rather than picking one of the colliding values.\n */\nexport function useWorkspaceUrlLoader() {\n  const route = useRoute()\n  const router = useRouter()\n  const { t } = useI18n()\n  const toast = useToast()\n  const { switchWorkspace } = useWorkspaceSwitch()\n  const { activeWorkspace, workspaceName } = storeToRefs(\n    useTeamWorkspaceStore()\n  )\n\n  function notifyStayed() {\n    toast.info(\n      t(\n        'workspace.deepLinkStayed',\n        { workspaceName: workspaceName.value },\n        { escapeParameter: false }\n      )\n    )\n  }\n\n  /** Strips `workspace`, keeping other params, and clears the stash. Must\n   * complete before a workspace switch reloads the page, or the reload would\n   * re-trigger this loader on the same link. */\n  async function stripParam(query: LocationQueryRaw) {\n    const cleanQuery = { ...query }\n    delete cleanQuery.workspace\n    try {\n      await router.replace({ query: cleanQuery })\n    } catch (error) {\n      console.warn('[useWorkspaceUrlLoader] Failed to clean URL params:', error)\n    }\n    clearPreservedQuery(NAMESPACE)\n  }\n\n  /**\n   * Reads `?workspace=`, strips it, and switches (or explains why not).\n   * Returns `true` when it triggered a switch that will reload the page —\n   * the caller must stop running further loaders immediately: `location.reload()`\n   * doesn't halt the current script, so a later loader's own URL cleanup\n   * (e.g. settings unconditionally strips `?settings=`) can otherwise land\n   * on the still-live page and get baked into the URL the reload re-fetches.\n   */\n  async function loadWorkspaceFromUrl(): Promise<boolean> {\n    hydratePreservedQuery(NAMESPACE)\n    const query =\n      mergePreservedQueryIntoQuery(NAMESPACE, route.query) ?? route.query\n    const link = readWorkspaceLinkFromQuery(query)\n    if (!link) return false\n\n    if (link.status === 'absent') {\n      await stripParam(query)\n      return false\n    }\n\n    if (link.status === 'invalid') {\n      await stripParam(query)\n      notifyStayed()\n      return false\n    }\n\n    // Already there: strip and say nothing, nothing changed.\n    if (link.workspaceId === activeWorkspace.value?.id) {\n      await stripParam(query)\n      return false\n    }\n\n    await stripParam(query)\n    const switched = await switchWorkspace(link.workspaceId)\n    if (!switched) {\n      notifyStayed()\n      return false\n    }\n    return true\n  }\n\n  return {\n    loadWorkspaceFromUrl\n  }\n}\n","import { useRouter } from 'vue-router'\n\nimport { useAssetsUrlLoader } from '@/platform/assets/composables/useAssetsUrlLoader'\nimport { usePaymentReturnUrlLoader } from '@/platform/cloud/subscription/composables/usePaymentReturnUrlLoader'\nimport { usePricingTableUrlLoader } from '@/platform/cloud/subscription/composables/usePricingTableUrlLoader'\nimport { useSubscriptionDialog } from '@/platform/cloud/subscription/composables/useSubscriptionDialog'\nimport { useTopUpUrlLoader } from '@/platform/cloud/subscription/composables/useTopUpUrlLoader'\nimport {\n  BILLING_WEB_RETURN_PARAMS,\n  STRIPE_RETURN_PARAMS\n} from '@/platform/cloud/subscription/utils/paymentReturnUrl'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useSettingsUrlLoader } from '@/platform/settings/composables/useSettingsUrlLoader'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useCreateWorkspaceUrlLoader } from '@/platform/workspace/composables/useCreateWorkspaceUrlLoader'\nimport { useInviteUrlLoader } from '@/platform/workspace/composables/useInviteUrlLoader'\nimport { useWorkspaceUrlLoader } from '@/platform/workspace/composables/useWorkspaceUrlLoader'\n\ninterface UrlActionStep {\n  /** What the loader does, for the failure log — not shown to the customer. */\n  readonly failureMessage: string\n  /** `true` means a reload is already in flight: the loop must stop, since\n   * `location.reload()` doesn't halt the current script and a later step's\n   * own URL cleanup could otherwise land on the still-live page. */\n  readonly run: () => Promise<boolean | void> | boolean | void\n}\n\ntype UrlActionLoaders = {\n  workspaceUrlLoader: ReturnType<typeof useWorkspaceUrlLoader> | null\n  inviteUrlLoader: ReturnType<typeof useInviteUrlLoader> | null\n  createWorkspaceUrlLoader: ReturnType<\n    typeof useCreateWorkspaceUrlLoader\n  > | null\n  pricingTableUrlLoader: ReturnType<typeof usePricingTableUrlLoader> | null\n  topUpUrlLoader: ReturnType<typeof useTopUpUrlLoader> | null\n  settingsUrlLoader: ReturnType<typeof useSettingsUrlLoader> | null\n  assetsUrlLoader: ReturnType<typeof useAssetsUrlLoader> | null\n  paymentReturnUrlLoader: ReturnType<typeof usePaymentReturnUrlLoader> | null\n}\n\n/**\n * Every param a loader below consumes, stripped centrally as a backstop. Most\n * loaders fire their own cleanup replace without waiting for it, so with two\n * deep links in one URL the later navigation can cancel the earlier one and\n * leave its param behind; this sweep removes whatever survived once every\n * loader has had its turn. The Stripe ones are already gone from the address\n * bar by then, but only through `history.replaceState`, which leaves the\n * router's own query holding them — so a replace built from that query would\n * hand them back. `workspace` is included too: its own strip catches a\n * rejected `router.replace` and returns normally, so a failed strip needs\n * this backstop rather than leaving the link live with no retry. A\n * successful switch reloads the page and stops the loop before this step\n * runs, so it never re-strips a live workspace switch.\n */\nconst HANDLED_PARAMS = [\n  'workspace',\n  'invite',\n  'create_workspace',\n  'pricing',\n  'stop',\n  'cycle',\n  'topup',\n  'settings',\n  'assets',\n  ...STRIPE_RETURN_PARAMS,\n  ...BILLING_WEB_RETURN_PARAMS\n]\n\n/**\n * Orders the deep-link loaders: workspace first, so `?invite`,\n * `?create_workspace`, `?pricing`, `?topup`, `?settings`, `?assets` all act\n * on the requested workspace rather than the one the app happened to load\n * with. Only the loaders present (cloud-gated by the caller) become steps.\n */\nfunction buildUrlActionSteps(\n  loaders: UrlActionLoaders,\n  router: ReturnType<typeof useRouter>\n): UrlActionStep[] {\n  const steps: UrlActionStep[] = []\n\n  if (loaders.workspaceUrlLoader) {\n    const loader = loaders.workspaceUrlLoader\n    steps.push({\n      failureMessage: 'Failed to load workspace from URL:',\n      run: () => loader.loadWorkspaceFromUrl()\n    })\n  }\n  if (loaders.inviteUrlLoader) {\n    const loader = loaders.inviteUrlLoader\n    steps.push({\n      failureMessage: 'Failed to load invite from URL:',\n      run: () => loader.loadInviteFromUrl()\n    })\n  }\n  if (loaders.createWorkspaceUrlLoader) {\n    const loader = loaders.createWorkspaceUrlLoader\n    steps.push({\n      failureMessage: 'Failed to load create workspace from URL:',\n      run: () => loader.loadCreateWorkspaceFromUrl()\n    })\n  }\n  if (loaders.pricingTableUrlLoader) {\n    const loader = loaders.pricingTableUrlLoader\n    steps.push({\n      failureMessage: 'Failed to load pricing table from URL:',\n      run: () => loader.loadPricingTableFromUrl()\n    })\n  }\n  // Not gated on the team-workspaces flag: it also drives personal/legacy users.\n  if (loaders.topUpUrlLoader) {\n    const loader = loaders.topUpUrlLoader\n    steps.push({\n      failureMessage: 'Failed to load top-up dialog from URL:',\n      run: () => loader.loadTopUpFromUrl()\n    })\n  }\n  if (loaders.settingsUrlLoader) {\n    const loader = loaders.settingsUrlLoader\n    steps.push({\n      failureMessage: 'Failed to load settings panel from URL:',\n      run: () => loader.loadSettingsFromUrl()\n    })\n  }\n  if (loaders.assetsUrlLoader) {\n    const loader = loaders.assetsUrlLoader\n    steps.push({\n      failureMessage: 'Failed to open assets panel from URL:',\n      run: () => loader.loadAssetsFromUrl()\n    })\n  }\n  // Handles the return leg of a redirect payment (Stripe appends\n  // payment_intent/redirect_status params): strips the params and refreshes\n  // billing status so the pending checkout resumes polling immediately.\n  if (loaders.paymentReturnUrlLoader) {\n    const loader = loaders.paymentReturnUrlLoader\n    steps.push({\n      failureMessage: 'Failed to handle payment return from URL:',\n      run: () => loader.loadPaymentReturnFromUrl()\n    })\n  }\n\n  steps.push({\n    failureMessage: 'Failed to clear handled deep-link params from the URL:',\n    run: async () => {\n      const query = { ...router.currentRoute.value.query }\n      if (!HANDLED_PARAMS.some((param) => param in query)) return\n      for (const param of HANDLED_PARAMS) delete query[param]\n      await router.replace({ query })\n    }\n  })\n\n  return steps\n}\n\n/**\n * Runs each step in order; one loader's failure never blocks the rest. Stops\n * immediately when a step reports a reload already in flight — no further\n * step's URL cleanup should run on a page that's about to be torn down.\n * Returns whether a reload is in flight, so the caller can skip work that\n * would otherwise run against the workspace the app is switching away from.\n */\nasync function runUrlActionSteps(steps: UrlActionStep[]): Promise<boolean> {\n  for (const step of steps) {\n    try {\n      if (await step.run()) return true\n    } catch (error) {\n      console.error(`[UrlActionLoaders] ${step.failureMessage}`, error)\n    }\n  }\n  return false\n}\n\n/**\n * Reopens a checkout that was interrupted by a redirect payment. Called from\n * `onMounted`, not during workspace init, so the first-run and Templates\n * overlays are already settled and the recovered dialog is reachable.\n * Deliberately not awaited: the resume only settles once the recovered\n * operation reaches a terminal status, which for an abandoned checkout can\n * take hours, and the boot chain (emit('ready'), the tour, telemetry) must\n * not wait on it.\n */\nfunction schedulePendingCheckoutRecovery(\n  subscriptionDialog: ReturnType<typeof useSubscriptionDialog> | null\n) {\n  if (!subscriptionDialog) return\n\n  void (async () => subscriptionDialog.resumePendingPricingFlow())().catch(\n    (error) => {\n      reportError(error, {\n        surface: 'platform',\n        errorType: 'billing_pending_checkout_resume_failure'\n      })\n    }\n  )\n}\n\n/** Calls a composable only on the cloud distribution; `null` off it. */\nfunction useIfCloud<T>(create: () => T): T | null {\n  return isCloud ? create() : null\n}\n\n/**\n * Aggregates the query-param \"deep link\" loaders the cloud app checks on mount\n * (`?workspace`, `?invite`, `?create_workspace`, `?pricing`, `?topup`,\n * `?settings`, `?assets`), then recovers an interrupted checkout. The loaders\n * are instantiated in setup so their `useRoute`/`useRouter` resolve; call\n * `runUrlActionLoaders()` from `onMounted` once the app is ready.\n */\nexport function useUrlActionLoaders() {\n  const router = useRouter()\n\n  const workspaceUrlLoader = useIfCloud(useWorkspaceUrlLoader)\n  const inviteUrlLoader = useIfCloud(useInviteUrlLoader)\n  const createWorkspaceUrlLoader = useIfCloud(useCreateWorkspaceUrlLoader)\n  const pricingTableUrlLoader = useIfCloud(usePricingTableUrlLoader)\n  const topUpUrlLoader = useIfCloud(useTopUpUrlLoader)\n  const settingsUrlLoader = useIfCloud(useSettingsUrlLoader)\n  const assetsUrlLoader = useIfCloud(useAssetsUrlLoader)\n  const paymentReturnUrlLoader = useIfCloud(usePaymentReturnUrlLoader)\n  const subscriptionDialog = useIfCloud(useSubscriptionDialog)\n\n  const steps = isCloud\n    ? buildUrlActionSteps(\n        {\n          workspaceUrlLoader,\n          inviteUrlLoader,\n          createWorkspaceUrlLoader,\n          pricingTableUrlLoader,\n          topUpUrlLoader,\n          settingsUrlLoader,\n          assetsUrlLoader,\n          paymentReturnUrlLoader\n        },\n        router\n      )\n    : []\n\n  async function runUrlActionLoaders() {\n    const reloading = await runUrlActionSteps(steps)\n    // A switch reload is already in flight: activeWorkspaceId and its auth\n    // context are already stale, so starting recovery here could adopt or\n    // poll the old workspace's pending checkout. The next boot, once the\n    // reload lands, gets a clean pass at it.\n    if (reloading) return\n    schedulePendingCheckoutRecovery(subscriptionDialog)\n  }\n\n  return { runUrlActionLoaders }\n}\n","<template>\n  <!-- Load splitter overlay only after comfyApp is ready. -->\n  <!-- If load immediately, the top-level splitter stateKey won't be correctly\n  synced with the stateStorage (localStorage). -->\n  <LiteGraphCanvasSplitterOverlay v-if=\"comfyAppReady\">\n    <template v-if=\"showUI\" #workflow-tabs>\n      <div\n        v-if=\"workflowTabsPosition === 'Topbar'\"\n        data-testid=\"topbar-workflow-tabs\"\n        class=\"workflow-tabs-container pointer-events-auto relative flex h-(--workflow-tabs-height) w-full items-center border-b border-interface-stroke/50 bg-comfy-menu-bg shadow-interface\"\n      >\n        <WorkflowTabs />\n      </div>\n    </template>\n    <template #side-toolbar>\n      <SideToolbar v-if=\"showUI && !isBuilderMode && !linearMode\" />\n    </template>\n    <template v-if=\"betaMenuEnabled\" #side-bar-panel>\n      <div\n        :inert=\"canvasStore.isPickingNodes\"\n        class=\"sidebar-content-container size-full overflow-x-hidden overflow-y-auto transition-opacity duration-200 ease-in-out\"\n        :class=\"{ 'opacity-0': canvasStore.isPickingNodes }\"\n      >\n        <ExtensionSlot v-if=\"activeSidebarTab\" :extension=\"activeSidebarTab\" />\n      </div>\n    </template>\n    <template v-if=\"showUI && !isBuilderMode\" #topmenu>\n      <TopMenuSection />\n    </template>\n    <template v-if=\"betaMenuEnabled\" #bottom-panel>\n      <BottomPanel />\n    </template>\n    <template v-if=\"betaMenuEnabled\" #right-side-panel>\n      <AppBuilder v-if=\"isBuilderMode\" />\n      <NodePropertiesPanel v-else />\n    </template>\n    <template v-if=\"showUI\" #agent-panel=\"{ hasOpaqueNeighbor }\">\n      <component\n        :is=\"DockedAgentPanel\"\n        v-if=\"agentDocked && !linearMode\"\n        :has-opaque-neighbor=\"hasOpaqueNeighbor\"\n      />\n    </template>\n    <template #graph-canvas-panel>\n      <div\n        ref=\"canvasPanelBoundsRef\"\n        class=\"pointer-events-none absolute inset-0\"\n      />\n      <GraphCanvasMenu\n        v-if=\"canvasMenuEnabled && !isBuilderMode\"\n        class=\"pointer-events-auto\"\n      />\n      <MiniMap\n        v-if=\"\n          comfyAppReady &&\n          minimapEnabled &&\n          betaMenuEnabled &&\n          !isBuilderMode &&\n          !canvasStore.isPickingNodes\n        \"\n        class=\"pointer-events-auto\"\n      />\n      <NodeSelectionModeBanner />\n    </template>\n  </LiteGraphCanvasSplitterOverlay>\n  <canvas\n    id=\"graph-canvas\"\n    ref=\"canvasRef\"\n    tabindex=\"1\"\n    class=\"absolute inset-0 size-full touch-none\"\n  />\n\n  <!-- TransformPane for Vue node rendering -->\n  <TransformPane\n    v-if=\"shouldRenderVueNodes && comfyApp.canvas && comfyAppReady\"\n    ref=\"transformPaneRef\"\n    :canvas=\"comfyApp.canvas\"\n    :inert=\"canvasStore.isPickingNodes\"\n    @wheel.capture=\"canvasInteractions.forwardEventToCanvas\"\n    @pointerdown.capture=\"forwardPointerDownPanEvent\"\n    @pointerup.capture=\"forwardPointerUpPanEvent\"\n    @pointermove.capture=\"forwardPointerMovePanEvent\"\n    @keydown.space=\"forwardSpaceKeyEvent\"\n  >\n    <!-- Vue nodes rendered based on graph nodes -->\n    <LGraphNode\n      v-for=\"nodeData in allNodes\"\n      :key=\"nodeData.id\"\n      :node-data\n      :data-node-id=\"nodeData.id\"\n    />\n  </TransformPane>\n\n  <LinkOverlayCanvas\n    v-if=\"shouldRenderVueNodes && comfyApp.canvas && comfyAppReady\"\n    :canvas=\"comfyApp.canvas\"\n    @ready=\"onLinkOverlayReady\"\n    @dispose=\"onLinkOverlayDispose\"\n  />\n\n  <!-- Selection rectangle overlay - rendered in DOM layer to appear above DOM widgets -->\n  <SelectionRectangle\n    v-if=\"comfyAppReady\"\n    :panel-el=\"canvasPanelBoundsRef ?? undefined\"\n  />\n\n  <NodeTooltip v-if=\"tooltipEnabled\" />\n  <NodeSearchboxPopover ref=\"nodeSearchboxPopoverRef\" />\n  <NodeDragPreview />\n  <VueNodeSwitchPopup />\n\n  <!-- Initialize components after comfyApp is ready. useAbsolutePosition requires\n  canvasStore.canvas to be initialized. -->\n  <template v-if=\"comfyAppReady\">\n    <TitleEditor />\n    <SelectionToolbox v-if=\"selectionToolboxEnabled\" />\n    <NodeContextMenu />\n    <!-- Render legacy DOM widgets only when Vue nodes are disabled -->\n    <DomWidgets v-if=\"!shouldRenderVueNodes\" />\n  </template>\n</template>\n\n<script setup lang=\"ts\">\nimport { until, useEventListener } from '@vueuse/core'\nimport {\n  computed,\n  nextTick,\n  onMounted,\n  onUnmounted,\n  ref,\n  shallowRef,\n  useTemplateRef,\n  watch,\n  watchEffect\n} from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport {\n  isMiddleButtonEvent,\n  isMiddleButtonHeld,\n  isMiddlePointerInput\n} from '@/base/pointerUtils'\nimport LiteGraphCanvasSplitterOverlay from '@/components/LiteGraphCanvasSplitterOverlay.vue'\nimport TopMenuSection from '@/components/TopMenuSection.vue'\nimport BottomPanel from '@/components/bottomPanel/BottomPanel.vue'\nimport AppBuilder from '@/components/builder/AppBuilder.vue'\nimport VueNodeSwitchPopup from '@/components/builder/VueNodeSwitchPopup.vue'\nimport ExtensionSlot from '@/components/common/ExtensionSlot.vue'\nimport DomWidgets from '@/components/graph/DomWidgets.vue'\nimport GraphCanvasMenu from '@/components/graph/GraphCanvasMenu.vue'\nimport { createNodeProgressCanvasSync } from '@/components/graph/nodeProgressCanvasSync'\nimport LinkOverlayCanvas from '@/components/graph/LinkOverlayCanvas.vue'\nimport NodeTooltip from '@/components/graph/NodeTooltip.vue'\nimport NodeContextMenu from '@/components/graph/NodeContextMenu.vue'\nimport NodeDragPreview from '@/components/graph/NodeDragPreview.vue'\nimport NodeSelectionModeBanner from '@/components/graph/NodeSelectionModeBanner.vue'\nimport SelectionToolbox from '@/components/graph/SelectionToolbox.vue'\nimport TitleEditor from '@/components/graph/TitleEditor.vue'\nimport NodePropertiesPanel from '@/components/rightSidePanel/RightSidePanel.vue'\nimport { useAgentDockMount } from '@/workbench/extensions/agent/composables/useAgentDockMount'\nimport NodeSearchboxPopover from '@/components/searchbox/NodeSearchBoxPopover.vue'\nimport SideToolbar from '@/components/sidebar/SideToolbar.vue'\nimport WorkflowTabs from '@/components/topbar/WorkflowTabs.vue'\nimport { useGroupContextMenu } from '@/composables/graph/useGroupContextMenu'\nimport { installErrorClearingHooks } from '@/composables/graph/useErrorClearingHooks'\nimport type { NodeState } from '@/types/nodeState'\nimport { useNodeBadge } from '@/composables/node/useNodeBadge'\nimport { useCanvasDrop } from '@/composables/useCanvasDrop'\nimport { useContextMenuTranslation } from '@/composables/useContextMenuTranslation'\nimport { useCopy } from '@/composables/useCopy'\nimport { useGlobalLitegraph } from '@/composables/useGlobalLitegraph'\nimport { usePaste } from '@/composables/usePaste'\nimport { useVueFeatureFlags } from '@/composables/useVueFeatureFlags'\nimport type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport { LiteGraph } from '@/lib/litegraph/src/litegraph'\nimport { useLitegraphSettings } from '@/platform/settings/composables/useLitegraphSettings'\nimport { CORE_SETTINGS } from '@/platform/settings/constants/coreSettings'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { bootstrapTracer } from '@/platform/telemetry/perf/bootstrapTracer'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useWorkflowAutoSave } from '@/platform/workflow/persistence/composables/useWorkflowAutoSave'\nimport { useWorkflowPersistenceV2 as useWorkflowPersistence } from '@/platform/workflow/persistence/composables/useWorkflowPersistenceV2'\nimport { useNodeDataStore } from '@/stores/nodeDataStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useCanvasInteractions } from '@/renderer/core/canvas/useCanvasInteractions'\nimport { arrangeForLegacyRender } from '@/renderer/core/canvas/litegraph/arrangeForLegacyRender'\nimport { notifyLayoutChanges } from '@/renderer/core/canvas/litegraph/notifyLayoutChanges'\nimport { layoutStore } from '@/renderer/core/layout/store/layoutStore'\nimport TransformPane from '@/renderer/core/layout/transform/TransformPane.vue'\nimport type { StartupOutcome } from '@/platform/workflow/persistence/base/draftTypes'\nimport { useFirstRunEntry } from '@/renderer/extensions/firstRunTour/gettingStarted/firstRunEntry'\nimport MiniMap from '@/renderer/extensions/minimap/MiniMap.vue'\nimport LGraphNode from '@/renderer/extensions/vueNodes/components/LGraphNode.vue'\nimport { UnauthorizedError } from '@/scripts/api'\nimport { app as comfyApp } from '@/scripts/app'\nimport { ChangeTracker } from '@/scripts/changeTracker'\nimport { IS_CONTROL_WIDGET } from '@/core/graph/widgets/controlWidgetMarker'\nimport { updateControlWidgetLabel } from '@/core/graph/widgets/valueControlWidgets'\nimport { loadExtensions } from '@/services/extensionLoader'\nimport { useColorPaletteService } from '@/services/colorPaletteService'\nimport { useNewUserService } from '@/services/useNewUserService'\nimport {\n  collapseOutsideSelectionOnPrimaryPointerDown,\n  shouldIgnoreCopyPaste\n} from '@/workbench/eventHelpers'\nimport { storeToRefs } from 'pinia'\n\nimport { useBootstrapStore } from '@/stores/bootstrapStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { useSearchBoxStore } from '@/stores/workspace/searchBoxStore'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport { forEachNode } from '@/utils/graphTraversalUtil'\n\nimport SelectionRectangle from './SelectionRectangle.vue'\nimport { useUrlActionLoaders } from '@/composables/useUrlActionLoaders'\n\nconst { t } = useI18n()\nconst emit = defineEmits<{\n  ready: []\n}>()\nconst canvasRef = ref<HTMLCanvasElement | null>(null)\nconst transformPaneRef =\n  useTemplateRef<InstanceType<typeof TransformPane>>('transformPaneRef')\nconst vueNodeDropTarget = computed(() => {\n  const element: unknown = transformPaneRef.value?.$el\n  return element instanceof HTMLElement ? element : null\n})\nconst canvasPanelBoundsRef = useTemplateRef('canvasPanelBoundsRef')\nconst nodeSearchboxPopoverRef = shallowRef<InstanceType<\n  typeof NodeSearchboxPopover\n> | null>(null)\nconst settingStore = useSettingStore()\n// Extensions still listen for `<id>.change` events on the legacy dialog.\nsettingStore.onSettingChanged(({ id, value, oldValue }) =>\n  comfyApp.ui.settings.dispatchChange(id, value, oldValue)\n)\nconst nodeDefStore = useNodeDefStore()\nconst workspaceStore = useWorkspaceStore()\nconst { isBuilderMode } = useAppMode()\nconst canvasStore = useCanvasStore()\nconst workflowStore = useWorkflowStore()\nconst nodeProgressCanvasSync = createNodeProgressCanvasSync(\n  workflowStore.nodeToNodeLocatorId\n)\nconst { linearMode } = storeToRefs(canvasStore)\nconst { docked: agentDocked, DockedAgentPanel } = useAgentDockMount()\nconst executionStore = useExecutionStore()\nconst executionErrorStore = useExecutionErrorStore()\nconst toast = useToast()\nconst colorPaletteStore = useColorPaletteStore()\nconst colorPaletteService = useColorPaletteService()\nconst canvasInteractions = useCanvasInteractions()\nconst bootstrapStore = useBootstrapStore()\nconst { isI18nReady, i18nError } = storeToRefs(bootstrapStore)\nconst { isReady: isSettingsReady, error: settingsError } =\n  storeToRefs(settingStore)\n\nconst betaMenuEnabled = computed(\n  () => settingStore.get('Comfy.UseNewMenu') !== 'Disabled'\n)\nconst workflowTabsPosition = computed(() =>\n  settingStore.get('Comfy.Workflow.WorkflowTabsPosition')\n)\nconst canvasMenuEnabled = computed(() =>\n  settingStore.get('Comfy.Graph.CanvasMenu')\n)\nconst tooltipEnabled = computed(() => settingStore.get('Comfy.EnableTooltips'))\nconst selectionToolboxEnabled = computed(\n  () =>\n    settingStore.get('Comfy.Canvas.SelectionToolbox') &&\n    !canvasStore.isPickingNodes\n)\nconst activeSidebarTab = computed(() => {\n  return workspaceStore.sidebarTab.activeSidebarTab\n})\nconst showUI = computed(\n  () => !workspaceStore.focusMode && betaMenuEnabled.value\n)\n\nconst minimapEnabled = computed(() => settingStore.get('Comfy.Minimap.Visible'))\n\n// Feature flags\nconst { shouldRenderVueNodes } = useVueFeatureFlags()\n\n// Error-clearing hooks run regardless of rendering mode (Vue or legacy canvas).\nlet cleanupErrorHooks: (() => void) | null = null\nwatch(\n  () => canvasStore.currentGraph,\n  (graph) => {\n    cleanupErrorHooks?.()\n    cleanupErrorHooks = graph ? installErrorClearingHooks(graph) : null\n  }\n)\n\nfunction exitToLegacyRendering(graph: LGraph | null) {\n  layoutStore.clearViewGeometry()\n  if (graph) arrangeForLegacyRender(graph)\n  canvasStore.canvas?.setDirty(true, true)\n}\n\nwatch(\n  [shouldRenderVueNodes, () => canvasStore.currentGraph],\n  ([enabled, graph], previous) => {\n    if (previous && previous[0] !== enabled) {\n      LiteGraph.vueNodesMode = enabled\n      if (graph) {\n        forEachNode(graph.rootGraph, (node) => {\n          for (const widget of node.widgets ?? []) {\n            widget.syncLiveVisibilityOptions?.()\n            widget.syncLiveDisabled?.()\n          }\n        })\n      }\n    }\n\n    if (enabled) {\n      layoutStore.clearViewGeometry()\n    } else if (previous?.[0]) {\n      exitToLegacyRendering(graph)\n    }\n  },\n  { immediate: true }\n)\n\nwatchEffect((onCleanup) => {\n  const canvas = canvasStore.canvas\n  if (canvas) onCleanup(notifyLayoutChanges(canvas))\n})\n\nwatch(\n  () => canvasStore.isInSubgraph,\n  (newValue, oldValue) => {\n    if (oldValue && !newValue) {\n      useWorkflowStore().updateActiveGraph()\n    }\n  }\n)\n\nconst nodeDataStore = useNodeDataStore()\nconst allNodes = computed((): NodeState[] => {\n  const { rootGraphId } = canvasStore\n  const graphId = canvasStore.currentGraph?.id\n  if (!rootGraphId || graphId === undefined) return []\n  return nodeDataStore.getGraphNodesFor(rootGraphId, graphId)\n})\nfunction onLinkOverlayReady(el: HTMLCanvasElement) {\n  if (!canvasStore.canvas) return\n  canvasStore.canvas.overlayCanvas = el\n  canvasStore.canvas.overlayCtx = el.getContext('2d')\n}\n\nfunction onLinkOverlayDispose() {\n  if (!canvasStore.canvas) return\n  canvasStore.canvas.overlayCanvas = null\n  canvasStore.canvas.overlayCtx = null\n}\n\nwatchEffect(() => {\n  LiteGraph.nodeOpacity = settingStore.get('Comfy.Node.Opacity')\n})\nwatchEffect(() => {\n  LiteGraph.nodeLightness = colorPaletteStore.completedActivePalette.light_theme\n    ? 0.5\n    : undefined\n})\n\nwatchEffect(() => {\n  nodeDefStore.showDeprecated = settingStore.get('Comfy.Node.ShowDeprecated')\n})\n\nwatchEffect(() => {\n  nodeDefStore.showExperimental = settingStore.get(\n    'Comfy.Node.ShowExperimental'\n  )\n})\n\nwatchEffect(() => {\n  const spellcheckEnabled = settingStore.get('Comfy.TextareaWidget.Spellcheck')\n  const textareas = document.querySelectorAll<HTMLTextAreaElement>(\n    'textarea.comfy-multiline-input'\n  )\n\n  textareas.forEach((textarea: HTMLTextAreaElement) => {\n    textarea.spellcheck = spellcheckEnabled\n    // Force recheck to ensure visual update\n    textarea.focus()\n    textarea.blur()\n  })\n})\n\nwatch(\n  () => settingStore.get('Comfy.WidgetControlMode'),\n  () => {\n    if (!canvasStore.canvas) return\n\n    const rootGraph = comfyApp.rootGraphOrUndefined\n    if (!rootGraph) return\n\n    forEachNode(rootGraph, (n) => {\n      if (!n.widgets) return\n      for (const w of n.widgets) {\n        if (!w[IS_CONTROL_WIDGET]) continue\n        updateControlWidgetLabel(w)\n        if (!w.linkedWidgets) continue\n        for (const l of w.linkedWidgets) {\n          updateControlWidgetLabel(l)\n        }\n      }\n    })\n    canvasStore.canvas.setDirty(true)\n  }\n)\n\nwatch(\n  [() => canvasStore.canvas, () => settingStore.get('Comfy.ColorPalette')],\n  async ([canvas, currentPaletteId]) => {\n    if (!canvas) return\n\n    await colorPaletteService.loadColorPalette(currentPaletteId)\n  }\n)\n\nwatch(\n  () => settingStore.get('Comfy.Canvas.BackgroundImage'),\n  async () => {\n    if (!canvasStore.canvas) return\n    const currentPaletteId = colorPaletteStore.activePaletteId\n    if (!currentPaletteId) return\n\n    // Reload color palette to apply background image\n    await colorPaletteService.loadColorPalette(currentPaletteId)\n    // Mark background canvas as dirty\n    canvasStore.canvas.setDirty(false, true)\n  }\n)\nwatch(\n  () => colorPaletteStore.activePaletteId,\n  async (newValue) => {\n    await settingStore.set('Comfy.ColorPalette', newValue)\n  }\n)\n\n/**\n * Propagates execution progress from the store to LiteGraph node objects\n * and triggers a canvas redraw.\n *\n * No `deep: true` needed — `nodeLocationProgressStates` is a computed that\n * returns a new `Record` object on every progress event (the underlying\n * `nodeProgressStates` ref is replaced wholesale by the WebSocket handler).\n *\n * `currentGraph` triggers this watcher on subgraph navigation so stale\n * progress bars are cleared when returning to the root graph.\n */\nwatch(\n  () =>\n    [\n      executionStore.nodeLocationProgressStates,\n      canvasStore.canvas,\n      canvasStore.currentGraph\n    ] as const,\n  ([nodeLocationProgressStates, canvas]) => {\n    nodeProgressCanvasSync.sync(\n      nodeLocationProgressStates,\n      canvas,\n      canvas?.graph ?? canvasStore.currentGraph\n    )\n  }\n)\n\nonUnmounted(nodeProgressCanvasSync.dispose)\n\n// Repaint canvas when node errors change.\n// Slot error flags are reconciled by reconcileNodeErrorFlags in executionErrorStore.\nwatch(\n  () => executionErrorStore.lastNodeErrors,\n  () => {\n    comfyApp.canvas?.setDirty(true, true)\n  }\n)\n\nuseEventListener(\n  canvasRef,\n  'litegraph:no-items-selected',\n  () => {\n    toast.warning(t('toastMessages.nothingSelected'), { duration: 2000 })\n  },\n  { passive: true }\n)\n\nconst comfyAppReady = ref(false)\nconst workflowPersistence = useWorkflowPersistence()\nconst { runUrlActionLoaders } = useUrlActionLoaders()\nuseCanvasDrop(canvasRef)\nuseCanvasDrop(vueNodeDropTarget)\nuseLitegraphSettings()\nuseNodeBadge()\n\nuseGlobalLitegraph()\nuseContextMenuTranslation()\nuseGroupContextMenu()\nuseCopy()\nusePaste()\nuseWorkflowAutoSave()\n\n// Start watching for locale change after the initial value is loaded.\nwatch(\n  () => settingStore.get('Comfy.Locale'),\n  async (_newLocale, oldLocale) => {\n    if (!oldLocale) return\n    await Promise.all([\n      until(() => isSettingsReady.value || !!settingsError.value).toBe(true),\n      until(() => isI18nReady.value || !!i18nError.value).toBe(true)\n    ])\n    if (settingsError.value || i18nError.value) {\n      console.warn(\n        'Somehow the Locale setting was changed while the settings or i18n had a setup error'\n      )\n    }\n    await useCommandStore().execute('Comfy.RefreshNodeDefinitions')\n    await useWorkflowService().reloadCurrentWorkflow()\n  }\n)\nuseEventListener(\n  () => canvasStore.canvas?.canvas,\n  'litegraph:set-graph',\n  () => {\n    workflowStore.updateActiveGraph()\n  }\n)\n\nonMounted(async () => {\n  comfyApp.vueAppReady = true\n  workspaceStore.spinner = true\n  let startupOutcome: StartupOutcome | undefined\n  let urlTemplateId: string | undefined\n  let bootstrapOutcome: 'completed' | 'failed' = 'failed'\n  try {\n    // ChangeTracker needs to be initialized before setup, as it will overwrite\n    // some listeners of litegraph canvas.\n    ChangeTracker.init()\n\n    await until(() => isSettingsReady.value || !!settingsError.value).toBe(true)\n\n    if (settingsError.value) {\n      if (settingsError.value instanceof UnauthorizedError) {\n        localStorage.removeItem('Comfy.userId')\n        localStorage.removeItem('Comfy.userName')\n        window.location.reload()\n        return\n      }\n      throw settingsError.value\n    }\n\n    // Register core settings immediately after settings are ready\n    CORE_SETTINGS.forEach(settingStore.addSetting)\n\n    await Promise.all([\n      until(() => isI18nReady.value || !!i18nError.value).toBe(true),\n      useNewUserService().initializeIfNewUser()\n    ])\n    if (i18nError.value) {\n      console.warn(\n        '[GraphCanvas] Failed to load custom nodes i18n:',\n        i18nError.value\n      )\n    }\n\n    await bootstrapTracer.settle('bootstrap/extensions-load', loadExtensions)\n\n    const canvas = canvasRef.value\n    if (!canvas) throw new TypeError('GraphCanvas mounted without a canvas')\n    await comfyApp.setup(canvas)\n    canvasStore.canvas = comfyApp.canvas\n    canvasStore.canvas.render_canvas_border = false\n    useSearchBoxStore().setPopoverRef(nodeSearchboxPopoverRef.value)\n\n    window.app = comfyApp\n    window.graph = comfyApp.graph\n\n    comfyAppReady.value = true\n\n    // Install error-clearing hooks on the initial graph\n    if (comfyApp.canvas?.graph) {\n      cleanupErrorHooks = installErrorClearingHooks(comfyApp.canvas.graph)\n    }\n\n    // Load color palette\n    colorPaletteStore.customPalettes = settingStore.get(\n      'Comfy.CustomColorPalettes'\n    )\n\n    // Restore saved workflow and workflow tabs state\n    startupOutcome = await workflowPersistence.initializeWorkflow()\n    await workflowPersistence.restoreWorkflowTabsState()\n    urlTemplateId = await workflowPersistence.loadTemplateFromUrlIfPresent()\n    await useFirstRunEntry().handleStartupOutcome(startupOutcome)\n    bootstrapOutcome = 'completed'\n  } finally {\n    workspaceStore.spinner = false\n    bootstrapTracer.complete(bootstrapOutcome)\n  }\n  const sharedStatus =\n    await workflowPersistence.loadSharedWorkflowFromUrlIfPresent()\n\n  // Run query-param deep-link loaders (?invite, ?create_workspace, ?pricing, ?topup)\n  await runUrlActionLoaders()\n\n  // Initialize release store to fetch releases from comfy-api (fire-and-forget)\n  const { useReleaseStore } =\n    await import('@/platform/updates/common/releaseStore')\n  const releaseStore = useReleaseStore()\n  void releaseStore.initialize()\n\n  emit('ready')\n\n  // The tour draws into an overlay that only mounts once `ready` has flushed.\n  await nextTick()\n  try {\n    await useFirstRunEntry().handleUrlWorkflow(\n      startupOutcome,\n      urlTemplateId,\n      sharedStatus\n    )\n  } catch (error) {\n    console.error('[GraphCanvas] Failed to offer the first-run tour:', error)\n  }\n})\n\nonUnmounted(() => {\n  cleanupErrorHooks?.()\n  cleanupErrorHooks = null\n})\n\nuseEventListener(\n  canvasRef,\n  'pointerdown',\n  collapseOutsideSelectionOnPrimaryPointerDown,\n  { capture: true }\n)\n\nfunction forwardPointerDownPanEvent(e: PointerEvent) {\n  collapseOutsideSelectionOnPrimaryPointerDown(e)\n  forwardPanEvent(e, isMiddlePointerInput)\n}\n\nfunction forwardPointerMovePanEvent(e: PointerEvent) {\n  forwardPanEvent(e, isMiddleButtonHeld)\n}\n\nfunction forwardPointerUpPanEvent(e: PointerEvent) {\n  forwardPanEvent(e, isMiddleButtonEvent)\n}\n\nfunction forwardSpaceKeyEvent(e: KeyboardEvent) {\n  const target = e.target\n  if (\n    !layoutStore.isDraggingVueNodes.value ||\n    target instanceof HTMLInputElement ||\n    target instanceof HTMLTextAreaElement ||\n    target instanceof HTMLSelectElement ||\n    target instanceof HTMLButtonElement ||\n    (target instanceof HTMLElement && target.isContentEditable)\n  )\n    return\n\n  comfyApp.canvas?.processKey(e)\n}\n\nfunction forwardPanEvent(\n  e: PointerEvent,\n  isMiddleInput: (event: PointerEvent) => boolean\n) {\n  if (!isMiddleInput(e)) return\n  if (shouldIgnoreCopyPaste(e.target) && document.activeElement === e.target)\n    return\n\n  canvasInteractions.forwardEventToCanvas(e)\n}\n</script>\n","<template>\n  <div\n    ref=\"root\"\n    :class=\"\n      cn(\n        'relative touch-none overflow-hidden select-none',\n        isDragging ? 'cursor-grabbing' : 'cursor-grab'\n      )\n    \"\n    role=\"group\"\n    :aria-label=\"label\"\n  >\n    <video\n      ref=\"baseVideo\"\n      :src=\"baseSrc\"\n      class=\"pointer-events-none absolute inset-0 size-full object-cover\"\n      :muted=\"baseMuted\"\n      :autoplay=\"motionAllowed\"\n      loop\n      playsinline\n      aria-hidden=\"true\"\n      data-testid=\"compare-clip\"\n    />\n\n    <div\n      class=\"absolute inset-0 overflow-hidden\"\n      :style=\"{ clipPath: `inset(0 ${100 - position}% 0 0)` }\"\n    >\n      <video\n        ref=\"overlayVideo\"\n        :src=\"overlaySrc\"\n        class=\"pointer-events-none absolute inset-0 size-full object-cover\"\n        :muted=\"overlayMuted\"\n        :autoplay=\"motionAllowed\"\n        loop\n        playsinline\n        aria-hidden=\"true\"\n        data-testid=\"compare-clip\"\n      />\n    </div>\n\n    <div\n      class=\"absolute inset-y-0 w-0.5 -translate-x-1/2 bg-white/90 shadow-lg outline-none focus-visible:ring-2 focus-visible:ring-white\"\n      :style=\"{ left: `${position}%` }\"\n      role=\"slider\"\n      tabindex=\"0\"\n      :aria-label=\"label\"\n      aria-valuemin=\"0\"\n      aria-valuemax=\"100\"\n      :aria-valuenow=\"Math.round(position)\"\n      @keydown=\"onKeydown\"\n    >\n      <span\n        class=\"absolute top-1/2 left-1/2 flex size-6 -translate-1/2 items-center justify-center rounded-full bg-white/90 shadow-sm\"\n      >\n        <i\n          class=\"icon-[lucide--chevrons-left-right] size-3.5 text-black\"\n          aria-hidden=\"true\"\n        />\n      </span>\n    </div>\n\n    <slot />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { usePreferredReducedMotion, useEventListener } from '@vueuse/core'\nimport { computed, ref, useTemplateRef, watchEffect } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  baseSrc,\n  overlaySrc,\n  label,\n  baseMuted = true,\n  overlayMuted = true,\n  startPosition = 50\n} = defineProps<{\n  baseSrc: string\n  overlaySrc: string\n  label: string\n  baseMuted?: boolean\n  overlayMuted?: boolean\n  startPosition?: number\n}>()\n\nconst root = useTemplateRef<HTMLElement>('root')\nconst baseVideo = useTemplateRef<HTMLVideoElement>('baseVideo')\nconst overlayVideo = useTemplateRef<HTMLVideoElement>('overlayVideo')\n\n/** Handle position as a 0–100 percentage from the left edge. */\nconst position = ref(startPosition)\n\nfunction setPosition(value: number) {\n  position.value = Math.max(0, Math.min(100, value))\n}\n\nfunction positionFromPointer(event: PointerEvent) {\n  const el = root.value\n  if (!el) return\n  const rect = el.getBoundingClientRect()\n  if (rect.width === 0) return\n  setPosition(((event.clientX - rect.left) / rect.width) * 100)\n}\n\nconst isDragging = ref(false)\n\nuseEventListener(root, 'pointerdown', (event: PointerEvent) => {\n  // Overlay controls (mute, close) live in the slot on top of the videos;\n  // a press on one must click it, not start a compare drag.\n  if ((event.target as HTMLElement).closest('button')) return\n  isDragging.value = true\n  root.value?.setPointerCapture(event.pointerId)\n  positionFromPointer(event)\n})\n\nuseEventListener(root, 'pointermove', (event: PointerEvent) => {\n  if (isDragging.value) positionFromPointer(event)\n})\n\nfunction endDrag(event: PointerEvent) {\n  isDragging.value = false\n  root.value?.releasePointerCapture(event.pointerId)\n}\n\nuseEventListener(root, 'pointerup', endDrag)\nuseEventListener(root, 'pointercancel', endDrag)\n\n/**\n * Respect the OS \"reduce motion\" setting: hold both clips on their first frame\n * instead of looping indefinitely, satisfying WCAG 2.2.2 without extra chrome.\n */\nconst reducedMotion = usePreferredReducedMotion()\nconst motionAllowed = computed(() => reducedMotion.value !== 'reduce')\n\nwatchEffect(() => {\n  if (motionAllowed.value) return\n  baseVideo.value?.pause()\n  overlayVideo.value?.pause()\n})\n\nconst KEY_STEP = 5\n\nfunction onKeydown(event: KeyboardEvent) {\n  if (event.key === 'ArrowLeft') setPosition(position.value - KEY_STEP)\n  else if (event.key === 'ArrowRight') setPosition(position.value + KEY_STEP)\n  else if (event.key === 'Home') setPosition(0)\n  else if (event.key === 'End') setPosition(100)\n  else return\n  event.preventDefault()\n}\n\n/** Realigns the overlay clip to the base clip's timeline so they stay in step. */\nfunction syncPlayback() {\n  if (baseVideo.value && overlayVideo.value) {\n    overlayVideo.value.currentTime = baseVideo.value.currentTime\n  }\n}\n\ndefineExpose({ syncPlayback })\n</script>\n","<template>\n  <Teleport to=\"body\">\n    <Transition\n      enter-active-class=\"motion-safe:transition-opacity duration-300 ease-out\"\n      enter-from-class=\"opacity-0\"\n      enter-to-class=\"opacity-100\"\n      leave-active-class=\"motion-safe:transition-opacity duration-200 ease-in\"\n      leave-from-class=\"opacity-100\"\n      leave-to-class=\"opacity-0\"\n    >\n      <div\n        v-if=\"isVisible\"\n        class=\"pointer-events-none fixed right-0 bottom-0 z-1500\"\n      >\n        <div\n          role=\"dialog\"\n          aria-modal=\"false\"\n          :aria-labelledby=\"pitchId\"\n          data-testid=\"partner-nodes-education-card\"\n          class=\"pointer-events-auto flex w-100 flex-col gap-2 overflow-hidden rounded-2xl border border-white/5 bg-base-background\"\n        >\n          <div class=\"isolate flex h-60 flex-col\">\n            <VideoCompareSlider\n              ref=\"slider\"\n              :base-src=\"PARTNER_MODEL_VIDEO\"\n              :overlay-src=\"OPEN_SOURCE_MODEL_VIDEO\"\n              :base-muted=\"audibleSide !== 'partner'\"\n              :overlay-muted=\"audibleSide !== 'open'\"\n              :label=\"t('partnerNodesEducation.sliderLabel')\"\n              class=\"relative z-2 -mb-5 flex-1 rounded-t-xl\"\n            >\n              <Button\n                variant=\"textonly\"\n                size=\"icon\"\n                class=\"absolute bottom-2 left-2 size-7 rounded-full bg-black/40 text-white backdrop-blur-sm hover:bg-black/60 hover:text-white\"\n                :aria-label=\"\n                  audibleSide === 'open'\n                    ? t('partnerNodesEducation.muteOpen')\n                    : t('partnerNodesEducation.unmuteOpen')\n                \"\n                @click=\"toggleAudio('open')\"\n              >\n                <i\n                  :class=\"\n                    cn(\n                      'size-4',\n                      audibleSide === 'open'\n                        ? 'icon-[lucide--volume-2]'\n                        : 'icon-[lucide--volume-x]'\n                    )\n                  \"\n                />\n              </Button>\n              <Button\n                variant=\"textonly\"\n                size=\"icon\"\n                class=\"absolute right-2 bottom-2 size-7 rounded-full bg-black/40 text-white backdrop-blur-sm hover:bg-black/60 hover:text-white\"\n                :aria-label=\"\n                  audibleSide === 'partner'\n                    ? t('partnerNodesEducation.mutePartner')\n                    : t('partnerNodesEducation.unmutePartner')\n                \"\n                @click=\"toggleAudio('partner')\"\n              >\n                <i\n                  :class=\"\n                    cn(\n                      'size-4',\n                      audibleSide === 'partner'\n                        ? 'icon-[lucide--volume-2]'\n                        : 'icon-[lucide--volume-x]'\n                    )\n                  \"\n                />\n              </Button>\n\n              <Button\n                variant=\"textonly\"\n                size=\"icon\"\n                class=\"absolute top-1.5 right-1.5 size-7 rounded-full bg-charcoal-600/50 text-white opacity-50 transition-opacity hover:bg-charcoal-600/50 hover:opacity-100\"\n                data-testid=\"partner-nodes-education-dismiss\"\n                :aria-label=\"t('g.close')\"\n                @click=\"educationStore.dismissCard\"\n              >\n                <i class=\"icon-[lucide--x] size-4\" />\n              </Button>\n            </VideoCompareSlider>\n\n            <div class=\"z-1 flex h-14 items-start\">\n              <div\n                class=\"flex h-14 flex-1 items-center justify-center gap-1.5 bg-secondary-background px-3 pt-7 pb-1.5 opacity-60 backdrop-blur-md\"\n              >\n                <i class=\"icon-[lucide--boxes] size-4 text-white\" />\n                <span class=\"text-xs font-semibold text-white\">\n                  {{ t('partnerNodesEducation.openTab') }}\n                </span>\n              </div>\n              <div\n                class=\"flex h-14 flex-1 items-center justify-center gap-1.5 bg-secondary-background-hover px-3 pt-7 pb-1.5 backdrop-blur-md\"\n              >\n                <i\n                  class=\"icon-[tabler--crown-filled] size-4 text-brand-yellow\"\n                />\n                <span class=\"text-xs font-semibold text-white\">\n                  {{ t('partnerNodesEducation.partnerTab') }}\n                </span>\n                <Tooltip open-on-click>\n                  <TooltipTrigger as-child>\n                    <button\n                      type=\"button\"\n                      :aria-label=\"t('partnerNodesEducation.tooltip')\"\n                      class=\"flex items-center text-white/60 hover:text-white\"\n                    >\n                      <i class=\"icon-[lucide--info] size-3\" />\n                    </button>\n                  </TooltipTrigger>\n                  <TooltipContent :side-offset=\"8\" class=\"max-w-56\">{{\n                    t('partnerNodesEducation.tooltip')\n                  }}</TooltipContent>\n                </Tooltip>\n              </div>\n            </div>\n          </div>\n\n          <div class=\"flex flex-col gap-3 px-6 pt-4 pb-6\">\n            <div class=\"flex flex-col text-sm/snug\">\n              <span :id=\"pitchId\" class=\"font-semibold text-white\">\n                {{ t('partnerNodesEducation.pitch') }}\n              </span>\n              <span class=\"text-text-secondary\">\n                {{ t('partnerNodesEducation.reassurance') }}\n              </span>\n            </div>\n\n            <div class=\"flex pr-4.5 text-xs font-medium text-muted-foreground\">\n              <span class=\"flex-1\" />\n              <span class=\"w-15 text-center\">\n                {{ t('partnerNodesEducation.openHeader') }}\n              </span>\n              <span class=\"w-15 text-center\">\n                {{ t('partnerNodesEducation.partnerHeader') }}\n              </span>\n            </div>\n\n            <div class=\"flex flex-col gap-2\">\n              <div\n                v-for=\"row in comparisonRows\"\n                :key=\"row.key\"\n                class=\"flex items-center pr-4.5\"\n              >\n                <span class=\"flex-1 text-sm/snug text-text-secondary\">\n                  {{ t(`partnerNodesEducation.benefits.${row.key}`) }}\n                </span>\n                <span\n                  v-for=\"column in [\n                    {\n                      label: t('partnerNodesEducation.openHeader'),\n                      included: row.open\n                    },\n                    {\n                      label: t('partnerNodesEducation.partnerHeader'),\n                      included: row.partner\n                    }\n                  ]\"\n                  :key=\"column.label\"\n                  class=\"flex w-15 justify-center\"\n                >\n                  <i\n                    :class=\"\n                      cn(\n                        'size-4',\n                        column.included\n                          ? 'icon-[lucide--check] text-brand-yellow'\n                          : 'icon-[lucide--minus] text-muted-foreground'\n                      )\n                    \"\n                    aria-hidden=\"true\"\n                  />\n                  <span class=\"sr-only\">\n                    {{ column.label }}:\n                    {{\n                      column.included\n                        ? t('partnerNodesEducation.included')\n                        : t('partnerNodesEducation.notIncluded')\n                    }}\n                  </span>\n                </span>\n              </div>\n            </div>\n\n            <Button\n              v-if=\"gate === 'sign-in'\"\n              variant=\"secondary\"\n              size=\"lg\"\n              class=\"mt-1 h-9 w-full bg-credit/15 text-credit hover:bg-credit/25 focus-visible:ring-credit\"\n              data-testid=\"partner-nodes-education-sign-in\"\n              @click=\"openSignIn\"\n            >\n              {{ t('actionbar.partnerRunGate.signInToRun') }}\n            </Button>\n          </div>\n        </div>\n      </div>\n    </Transition>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport { computed, ref, useId, useTemplateRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport VideoCompareSlider from '@/components/common/VideoCompareSlider.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { usePartnerNodesRunGate } from '@/composables/billing/usePartnerNodesRunGate'\nimport { usePartnerNodesInGraph } from '@/composables/node/usePartnerNodesInGraph'\nimport { useAuthDialogs } from '@/composables/auth/useAuthDialogs'\nimport { usePartnerNodesEducationStore } from '@/platform/workflow/templates/stores/partnerNodesEducationStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ninterface ComparisonRow {\n  key: string\n  open: boolean\n  partner: boolean\n}\n\nconst OPEN_SOURCE_MODEL_VIDEO =\n  'https://media.comfy.org/website/partner-nodes/ltx-open-1280.webm'\nconst PARTNER_MODEL_VIDEO =\n  'https://media.comfy.org/website/partner-nodes/ltx-partner-1280.webm'\n\nconst comparisonRows: ComparisonRow[] = [\n  { key: 'noDownload', open: false, partner: true },\n  { key: 'noVram', open: false, partner: true },\n  { key: 'offline', open: true, partner: false },\n  { key: 'free', open: true, partner: false }\n]\n\nconst { t } = useI18n()\nconst pitchId = useId()\n\nconst slider = useTemplateRef<InstanceType<typeof VideoCompareSlider>>('slider')\nconst audibleSide = ref<'open' | 'partner' | null>(null)\n\nfunction toggleAudio(side: 'open' | 'partner') {\n  audibleSide.value = audibleSide.value === side ? null : side\n  slider.value?.syncPlayback()\n}\n\nconst educationStore = usePartnerNodesEducationStore()\nconst { isCardRequested, requestedForWorkflowKey } = storeToRefs(educationStore)\nconst { hasPartnerNodes } = usePartnerNodesInGraph()\nconst { gate, partnerNodes } = usePartnerNodesRunGate()\nconst { activeWorkflow } = storeToRefs(useWorkflowStore())\nconst { showApiNodesSignInDialog } = useAuthDialogs()\n\nfunction openSignIn() {\n  void showApiNodesSignInDialog(\n    partnerNodes.value.map((node) => node.displayName)\n  )\n}\n\nconst isForRequestedWorkflow = computed(\n  () => activeWorkflow.value?.key === requestedForWorkflowKey.value\n)\n\nconst isVisible = computed(\n  () =>\n    isCardRequested.value &&\n    hasPartnerNodes.value &&\n    isForRequestedWorkflow.value\n)\n\n// Retire the one-off request as soon as its workflow is no longer active, so it\n// neither shows on the wrong workflow nor resurfaces on returning to its own.\nwatch(\n  () => isCardRequested.value && !isForRequestedWorkflow.value,\n  (stale) => {\n    if (stale) educationStore.retireCard()\n  }\n)\n</script>\n","<script setup lang=\"ts\">\nimport { provide } from 'vue'\n\nimport { TOAST_Z_INDEX } from '@/components/dialog/vRekaZIndex'\nimport { overlayZIndexKey } from '@/composables/useModalLiftedZIndex'\n\nprovide(overlayZIndexKey, TOAST_Z_INDEX)\n</script>\n\n<template>\n  <div\n    data-toast-dock\n    :style=\"{ zIndex: TOAST_Z_INDEX }\"\n    class=\"pointer-events-none fixed inset-x-4 bottom-6 flex max-h-[calc(100dvh-3rem)] flex-col items-center gap-2 overflow-y-auto *:pointer-events-auto *:shrink-0 sm:inset-x-0\"\n  >\n    <slot />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport type { DialogDescriptionProps } from 'reka-ui'\nimport { DialogDescription } from 'reka-ui'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: customClass = '', ...delegated } = defineProps<\n  DialogDescriptionProps & { class?: HTMLAttributes['class'] }\n>()\n</script>\n\n<template>\n  <DialogDescription\n    v-bind=\"delegated\"\n    :class=\"cn('text-sm text-muted-foreground', customClass)\"\n  >\n    <slot />\n  </DialogDescription>\n</template>\n","<template>\n  <Dialog :open=\"true\" @update:open=\"(value) => !value && emit('skip')\">\n    <DialogPortal>\n      <DialogOverlay\n        v-reka-z-index\n        data-testid=\"coach-landing-overlay\"\n        class=\"bg-coach-scrim\"\n      />\n      <DialogContent\n        v-reka-z-index\n        data-testid=\"coach-landing\"\n        class=\"w-[800px] max-w-[calc(100vw-2.5rem)] overflow-hidden rounded-2xl border-border-default bg-secondary-background p-0 shadow-[0_24px_80px_rgba(0,0,0,0.85)] md:h-fit md:min-h-100 md:max-w-[800px] md:flex-row\"\n        @pointer-down-outside.prevent\n        @open-auto-focus=\"onOpenAutoFocus\"\n      >\n        <DialogClose as-child>\n          <Button\n            variant=\"muted-textonly\"\n            size=\"icon\"\n            :aria-label=\"t('g.close')\"\n            class=\"absolute top-3 right-3 z-20\"\n          >\n            <i class=\"icon-[lucide--x]\" />\n          </Button>\n        </DialogClose>\n        <div\n          class=\"flex aspect-video items-center justify-center bg-base-background md:aspect-auto md:w-1/2\"\n        >\n          <img\n            v-if=\"image\"\n            :src=\"image\"\n            alt=\"\"\n            class=\"size-full object-cover\"\n          />\n        </div>\n        <div\n          class=\"flex flex-col items-start justify-between self-stretch px-15 pt-15 pb-10 md:w-1/2\"\n        >\n          <div class=\"flex flex-col gap-2.5\">\n            <DialogTitle\n              class=\"m-0 text-[28px] leading-normal font-medium text-base-foreground\"\n            >\n              {{ title }}\n            </DialogTitle>\n            <DialogDescription\n              class=\"flex flex-col items-start gap-2 self-stretch text-base/5 text-muted-foreground\"\n            >\n              {{ message }}\n            </DialogDescription>\n          </div>\n          <div class=\"flex w-full items-center justify-end gap-2\">\n            <Button variant=\"secondary\" size=\"lg\" @click=\"emit('skip')\">\n              {{ skipLabel }}\n            </Button>\n            <Button\n              ref=\"startButtonRef\"\n              variant=\"inverted\"\n              size=\"lg\"\n              class=\"grow\"\n              :disabled=\"waitingForTarget\"\n              @click=\"emit('start')\"\n            >\n              {{ primaryLabel }}\n            </Button>\n          </div>\n        </div>\n      </DialogContent>\n    </DialogPortal>\n  </Dialog>\n</template>\n\n<script setup lang=\"ts\">\nimport { useEventListener } from '@vueuse/core'\nimport { useTemplateRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Dialog from '@/components/ui/dialog/Dialog.vue'\nimport DialogClose from '@/components/ui/dialog/DialogClose.vue'\nimport DialogContent from '@/components/ui/dialog/DialogContent.vue'\nimport DialogDescription from '@/components/ui/dialog/DialogDescription.vue'\nimport DialogOverlay from '@/components/ui/dialog/DialogOverlay.vue'\nimport DialogPortal from '@/components/ui/dialog/DialogPortal.vue'\nimport DialogTitle from '@/components/ui/dialog/DialogTitle.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { vRekaZIndex } from '@/components/dialog/vRekaZIndex'\n\nconst { title, message, image, primaryLabel, skipLabel, waitingForTarget } =\n  defineProps<{\n    title: string\n    message: string\n    image?: string\n    primaryLabel: string\n    skipLabel: string\n    waitingForTarget: boolean\n  }>()\n\nconst emit = defineEmits<{\n  start: []\n  skip: []\n}>()\n\nconst { t } = useI18n()\n\n// The global keybinding handler preventDefaults Escape before Reka's\n// DismissableLayer sees it, so Reka skips its own dismiss; do it explicitly.\nuseEventListener(document, 'keydown', (e) => {\n  if (e.key === 'Escape') emit('skip')\n})\n\nconst startButtonRef = useTemplateRef('startButtonRef')\n\n// Land focus on the primary action, not the close button Reka would pick.\nfunction onOpenAutoFocus(event: Event) {\n  event.preventDefault()\n  const el = startButtonRef.value?.$el as HTMLButtonElement | undefined\n  el?.focus()\n}\n</script>\n","<template>\n  <div\n    class=\"flex w-full flex-col items-start justify-center gap-3 rounded-2xl bg-secondary-background p-4 drop-shadow-[1px_1px_8px_rgba(0,0,0,0.4)]\"\n  >\n    <div\n      v-if=\"image || $slots.image\"\n      class=\"flex h-[146px] flex-col items-start justify-center gap-4 self-stretch overflow-hidden rounded-xl bg-base-background\"\n    >\n      <slot name=\"image\">\n        <img v-if=\"image\" :src=\"image\" alt=\"\" class=\"size-full object-cover\" />\n      </slot>\n    </div>\n    <div class=\"flex flex-col items-end justify-end gap-6 self-stretch\">\n      <div class=\"flex flex-col items-start gap-2 self-stretch\">\n        <p\n          v-if=\"subtitle\"\n          :id=\"subtitleId\"\n          class=\"m-0 text-xs/normal text-base-foreground\"\n        >\n          {{ subtitle }}\n        </p>\n        <h3\n          :id=\"titleId\"\n          class=\"m-0 text-base/normal font-semibold text-base-foreground\"\n        >\n          {{ title }}\n        </h3>\n        <p :id=\"messageId\" class=\"m-0 text-sm/normal text-muted-foreground\">\n          {{ message }}\n        </p>\n      </div>\n      <div v-if=\"$slots.actions\" class=\"flex w-full items-center gap-3\">\n        <slot name=\"actions\" />\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nconst { title, titleId, message, subtitle, subtitleId, image, messageId } =\n  defineProps<{\n    title: string\n    titleId?: string\n    message: string\n    subtitle?: string\n    subtitleId?: string\n    image?: string\n    messageId?: string\n  }>()\n</script>\n","import { autoUpdate, flip, offset, shift, useFloating } from '@floating-ui/vue'\nimport type {\n  Middleware,\n  Placement,\n  Rect,\n  ReferenceElement\n} from '@floating-ui/vue'\nimport { refDebounced, useEventListener } from '@vueuse/core'\nimport { computed, ref, toValue, watchEffect } from 'vue'\nimport type { MaybeRefOrGetter, Ref } from 'vue'\n\nimport {\n  CARD_GAP,\n  CURSOR_GAP,\n  VIEWPORT_MARGIN,\n  topSafeInset\n} from './coachmarkLayout'\nimport {\n  coachmarkElements,\n  isRectTarget,\n  laidOutRect\n} from './coachmarkRegistry'\nimport type { CoachTarget } from './coachmarkRegistry'\nimport type { CoachPlacement, SpotlightStep } from './onboardingTours'\n\n// A target animating in via CSS transform reports through neither scroll nor\n// resize events; poll each frame until its rect holds still this long.\nconst MOTION_SETTLE_MS = 250\n\nconst PLACEMENT: Record<\n  Exclude<CoachPlacement, 'auto' | 'center'>,\n  Placement\n> = {\n  left: 'left-start',\n  right: 'right-start',\n  leftCenter: 'left',\n  rightCenter: 'right',\n  bottom: 'bottom'\n}\n\nfunction floatingPlacement(step: SpotlightStep | null): Placement {\n  const placement = step?.placement\n  if (!placement || placement === 'auto' || placement === 'center')\n    return 'right-start'\n  return PLACEMENT[placement]\n}\n\n// Surfaces the measured target rect so the spotlight can trace it.\nconst captureReference: Middleware = {\n  name: 'captureReference',\n  fn: (state) => ({ data: { rect: state.rects.reference } })\n}\n\nfunction floatingMiddleware(\n  step: SpotlightStep | null,\n  topInset: number\n): Middleware[] {\n  const list: Middleware[] = [offset(step?.cursor ? CURSOR_GAP : CARD_GAP)]\n  if (!step?.placement || step.placement === 'auto') list.push(flip())\n  // shift only guards the main axis by default; crossAxis keeps vertically-\n  // centred placements (leftCenter, rightCenter) on-screen too.\n  list.push(\n    shift({\n      crossAxis: true,\n      padding: {\n        top: topInset,\n        left: VIEWPORT_MARGIN,\n        right: VIEWPORT_MARGIN,\n        bottom: CARD_GAP\n      }\n    }),\n    captureReference\n  )\n  return list\n}\n\n/**\n * A deferred target animates in under its own CSS transform, which reports\n * through neither scroll nor resize: it is still settling until its rect has\n * held still long enough for the debounced copy to catch up.\n */\nexport function isSettling(\n  step: SpotlightStep | null,\n  rect: DOMRect | null,\n  settled: DOMRect | null\n): boolean {\n  return !!step?.deferTarget && rect !== settled\n}\n\n/**\n * Locates a step's target in the registry and positions the card beside it with\n * Floating UI, following the target until its rect settles.\n */\nexport function useCoachmarkTarget(\n  step: MaybeRefOrGetter<SpotlightStep | null>,\n  cardRef: Ref<HTMLElement | null>\n) {\n  const candidates = computed<readonly CoachTarget[]>(() => {\n    const id = toValue(step)?.coachId\n    return id ? coachmarkElements(id) : []\n  })\n\n  const anchor = computed(\n    () => candidates.value.find((candidate) => laidOutRect(candidate)) ?? null\n  )\n\n  const movingAnchor = computed(() =>\n    anchor.value && isRectTarget(anchor.value) ? anchor.value : null\n  )\n\n  const targetMoves = computed(() => !!movingAnchor.value)\n\n  const reference = computed<ReferenceElement | null>(() => {\n    const candidate = anchor.value\n    if (!candidate) return null\n    if (!isRectTarget(candidate)) return candidate\n    return {\n      getBoundingClientRect: () => candidate.getRect() ?? new DOMRect()\n    }\n  })\n\n  // The top bar's height only changes on resize, so read it once and refresh\n  // then — Floating UI re-runs the middleware every frame while tracking motion.\n  const topInset = ref(topSafeInset())\n  useEventListener('resize', () => {\n    topInset.value = topSafeInset()\n  })\n\n  const { floatingStyles, middlewareData, isPositioned, placement, update } =\n    useFloating(reference, cardRef, {\n      open: () => !!cardRef.value,\n      strategy: 'fixed',\n      transform: false,\n      placement: () => floatingPlacement(toValue(step)),\n      middleware: () => floatingMiddleware(toValue(step), topInset.value)\n    })\n\n  watchEffect((onCleanup) => {\n    const candidate = movingAnchor.value\n    if (!candidate) return\n    onCleanup(candidate.onMove(() => update()))\n  })\n\n  const targetRect = computed<DOMRect | null>(() => {\n    const data = middlewareData.value.captureReference as\n      | { rect: Rect }\n      | undefined\n    const rect = data?.rect\n    if (!rect || rect.width === 0) return null\n    return new DOMRect(rect.x, rect.y, rect.width, rect.height)\n  })\n\n  const settledRect = refDebounced(targetRect, MOTION_SETTLE_MS)\n  const trackMotion = computed(() =>\n    isSettling(toValue(step), targetRect.value, settledRect.value)\n  )\n\n  watchEffect((onCleanup) => {\n    const element = anchor.value\n    const floating = cardRef.value\n    if (!element || isRectTarget(element) || !floating) return\n    onCleanup(\n      autoUpdate(element, floating, update, {\n        animationFrame: trackMotion.value\n      })\n    )\n  })\n\n  /** Whether a candidate is anchored — a rect target holds no element. */\n  const hasTarget = computed(() => !!anchor.value)\n\n  return {\n    anchor,\n    hasTarget,\n    targetRect,\n    targetMoves,\n    floatingStyles,\n    isPositioned,\n    placement\n  }\n}\n","<template>\n  <div ref=\"overlayRef\" class=\"pointer-events-none fixed inset-0\">\n    <svg\n      v-if=\"useMaskScrim\"\n      aria-hidden=\"true\"\n      class=\"pointer-events-none absolute inset-0 size-full\"\n    >\n      <mask :id=\"maskId\">\n        <rect width=\"100%\" height=\"100%\" fill=\"white\" />\n        <rect\n          v-if=\"scrimHole\"\n          data-testid=\"coach-mask-hole\"\n          v-bind=\"scrimHole\"\n          rx=\"12\"\n          fill=\"black\"\n          :class=\"\n            !targetMoves &&\n            'motion-safe:transition-[x,y,width,height] motion-safe:duration-300'\n          \"\n        />\n      </mask>\n      <rect\n        width=\"100%\"\n        height=\"100%\"\n        class=\"fill-coach-scrim\"\n        :mask=\"`url(#${maskId})`\"\n      />\n      <path\n        v-if=\"step.interactive\"\n        data-testid=\"coach-hit-region\"\n        :d=\"hitRegion\"\n        fill=\"transparent\"\n        fill-rule=\"evenodd\"\n        class=\"pointer-events-auto\"\n      />\n    </svg>\n    <div\n      v-if=\"!step.interactive\"\n      data-testid=\"coach-blocker\"\n      :class=\"\n        cn(\n          'pointer-events-auto absolute inset-0',\n          !useMaskScrim && !targetRect && 'bg-coach-scrim'\n        )\n      \"\n    />\n    <div\n      aria-hidden=\"true\"\n      data-testid=\"coach-spotlight\"\n      :class=\"\n        cn(\n          'pointer-events-none absolute rounded-xl outline-2 outline-coach-ring',\n          !targetMoves &&\n            'motion-safe:transition-[left,top,width,height,opacity] motion-safe:duration-300',\n          !useMaskScrim && 'shadow-[0_0_0_9999px_var(--color-coach-scrim)]'\n        )\n      \"\n      :style=\"spotlightStyle\"\n    />\n    <FocusScope\n      as-child\n      :trapped=\"!waitingForTarget && !step.interactive\"\n      loop\n      @mount-auto-focus.prevent\n    >\n      <div\n        ref=\"cardRef\"\n        data-testid=\"coach-card\"\n        role=\"dialog\"\n        :aria-modal=\"!step.interactive\"\n        :aria-labelledby=\"titleId\"\n        :aria-describedby=\"`${subtitleId} ${bodyId}`\"\n        :aria-busy=\"!stepSettled\"\n        tabindex=\"-1\"\n        :class=\"\n          cn(\n            'absolute motion-safe:duration-300',\n            glides\n              ? 'motion-safe:transition-[left,top,opacity]'\n              : 'motion-safe:transition-opacity',\n            cardVisible ? 'pointer-events-auto' : 'pointer-events-none'\n          )\n        \"\n        :style=\"cardStyle\"\n      >\n        <i\n          v-if=\"cursorClass\"\n          data-testid=\"coach-cursor\"\n          :class=\"\n            cn(\n              'absolute icon-[lucide--mouse-pointer-2] size-4 text-base-foreground drop-shadow-md',\n              cursorClass\n            )\n          \"\n          aria-hidden=\"true\"\n        />\n        <CoachmarkCard\n          class=\"max-h-[calc(100vh-var(--comfy-topbar-height)-2rem)] overflow-y-auto\"\n          :subtitle=\"\n            t('onboardingCoachmarks.stepLabel', {\n              current: countedStepIdx + 1,\n              total: countedStepsTotal\n            })\n          \"\n          :subtitle-id=\"subtitleId\"\n          :title\n          :title-id=\"titleId\"\n          :message=\"body\"\n          :message-id=\"bodyId\"\n        >\n          <template #actions>\n            <Button\n              v-if=\"showSkip\"\n              ref=\"skipButton\"\n              variant=\"textonly\"\n              size=\"md\"\n              @click=\"emit('skip')\"\n            >\n              {{ skipLabel }}\n            </Button>\n            <div class=\"ml-auto flex items-center gap-3\">\n              <Button\n                v-if=\"canGoBack\"\n                variant=\"secondary\"\n                size=\"md\"\n                class=\"border border-solid border-border-default\"\n                @click=\"emit('back')\"\n              >\n                <i class=\"icon-[lucide--arrow-left]\" />\n                {{ backLabel }}\n              </Button>\n              <Button\n                v-if=\"!step.selfAdvancing\"\n                ref=\"primaryButton\"\n                variant=\"inverted\"\n                size=\"md\"\n                :disabled=\"waitingForTarget\"\n                @click=\"emit('advance')\"\n              >\n                {{ primaryLabel }}\n                <i v-if=\"!isLast\" class=\"icon-[lucide--arrow-right]\" />\n              </Button>\n            </div>\n          </template>\n        </CoachmarkCard>\n      </div>\n    </FocusScope>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useEventListener, useWindowSize } from '@vueuse/core'\nimport { ZIndex } from '@primeuix/utils/zindex'\nimport { FocusScope } from 'reka-ui'\nimport {\n  computed,\n  nextTick,\n  onBeforeUnmount,\n  ref,\n  useId,\n  useTemplateRef,\n  watch\n} from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { MODAL_Z_BASE, MODAL_Z_KEY } from '@/components/dialog/vRekaZIndex'\nimport Button from '@/components/ui/button/Button.vue'\n\nimport CoachmarkCard from './CoachmarkCard.vue'\nimport {\n  CARD_WIDTH,\n  SPOTLIGHT_PAD,\n  VIEWPORT_MARGIN,\n  CARD_GLIDE_MS,\n  clampSpotlightRect,\n  cursorEdgeClass,\n  hitRegionPath,\n  noTargetCardLeft\n} from './coachmarkLayout'\nimport type { SpotlightStep } from './onboardingTours'\nimport { useCoachmarkTarget } from './useCoachmarkTarget'\n\nconst {\n  step,\n  title,\n  body,\n  isLast,\n  canGoBack,\n  primaryLabel,\n  skipLabel,\n  backLabel,\n  countedStepIdx,\n  countedStepsTotal,\n  waitingForTarget,\n  stepSettled\n} = defineProps<{\n  step: SpotlightStep\n  title: string\n  body: string\n  isLast: boolean\n  canGoBack: boolean\n  primaryLabel: string\n  skipLabel: string\n  backLabel: string\n  countedStepIdx: number\n  countedStepsTotal: number\n  waitingForTarget: boolean\n  stepSettled: boolean\n}>()\n\nconst emit = defineEmits<{\n  advance: []\n  back: []\n  skip: []\n}>()\n\nconst { t } = useI18n()\nconst bodyId = useId()\nconst subtitleId = useId()\nconst titleId = useId()\n\nconst overlayRef = ref<HTMLElement | null>(null)\nconst cardRef = ref<HTMLElement | null>(null)\nconst { width: windowWidth, height: windowHeight } = useWindowSize()\n\nconst {\n  targetRect,\n  hasTarget,\n  targetMoves,\n  floatingStyles,\n  isPositioned,\n  placement\n} = useCoachmarkTarget(() => step, cardRef)\n\n// Last step's \"Done\" already dismisses, so hide Skip there.\nconst showSkip = computed(() => !isLast)\n\nconst primaryButton =\n  useTemplateRef<InstanceType<typeof Button>>('primaryButton')\nconst skipButton = useTemplateRef<InstanceType<typeof Button>>('skipButton')\n\nasync function focusPrimary() {\n  await nextTick()\n  const el = (primaryButton.value?.$el ??\n    skipButton.value?.$el ??\n    cardRef.value) as HTMLElement | undefined\n  el?.focus()\n}\n\nuseEventListener(\n  document,\n  'keydown',\n  (e: KeyboardEvent) => {\n    if (e.key !== 'Escape') return\n    e.preventDefault()\n    e.stopPropagation()\n    emit('skip')\n  },\n  { capture: true }\n)\n\nasync function raiseOverlay() {\n  await nextTick()\n  const el = overlayRef.value\n  if (!el) return\n  // ZIndex.set pushes a fresh entry into the shared modal sequence on every\n  // call, so clear the previous one or per-step re-raises leak entries.\n  ZIndex.clear(el)\n  ZIndex.set(MODAL_Z_KEY, el, MODAL_Z_BASE)\n}\n\nwatch(\n  () => step,\n  () => void raiseOverlay(),\n  { immediate: true }\n)\n\nwatch(\n  [() => step, () => waitingForTarget],\n  () => {\n    if (!waitingForTarget) void focusPrimary()\n  },\n  { immediate: true }\n)\n\nonBeforeUnmount(() => {\n  if (overlayRef.value) ZIndex.clear(overlayRef.value)\n})\n\nfunction viewport() {\n  return { width: windowWidth.value, height: windowHeight.value }\n}\n\nconst maskId = useId()\n\nconst useMaskScrim = computed(() => !!step.interactive)\n\nconst scrimHole = computed(() =>\n  targetRect.value\n    ? clampSpotlightRect(targetRect.value, SPOTLIGHT_PAD, viewport())\n    : null\n)\n\nconst spotlightStyle = computed(() => {\n  const hole = scrimHole.value\n  if (!hole?.width || !hole.height) return { opacity: '0' }\n  return {\n    left: `${hole.x}px`,\n    top: `${hole.y}px`,\n    width: `${hole.width}px`,\n    height: `${hole.height}px`,\n    opacity: '1'\n  }\n})\n\nconst hitRegion = computed(() => hitRegionPath(viewport(), scrimHole.value))\n\n/**\n * The card travels to a new target, then rides it — a transition lags a target\n * that moves every frame. Only a change arms travel; the first card makes none.\n */\nconst glides = ref(false)\nwatch([() => step, targetMoves], ([, moves], _previous, onCleanup) => {\n  glides.value = true\n  if (!moves) return\n  const timer = setTimeout(() => (glides.value = false), CARD_GLIDE_MS)\n  onCleanup(() => clearTimeout(timer))\n})\n\n/** Hidden until Floating UI has placed it, so it fades in already sited. */\nconst cardVisible = computed(() => !hasTarget.value || isPositioned.value)\n\nconst cardStyle = computed(() => {\n  const width = `${CARD_WIDTH}px`\n  const maxWidth = `calc(100vw - ${VIEWPORT_MARGIN * 2}px)`\n  const opacity = cardVisible.value ? '1' : '0'\n  if (!hasTarget.value) {\n    return {\n      width,\n      maxWidth,\n      left: `${noTargetCardLeft(windowWidth.value)}px`,\n      top: '30%',\n      opacity\n    }\n  }\n  return { ...floatingStyles.value, width, maxWidth, opacity }\n})\n\nconst cursorClass = computed(() =>\n  step.cursor && hasTarget.value ? cursorEdgeClass(placement.value) : ''\n)\n</script>\n","<template>\n  <CoachmarkLanding\n    v-if=\"tour.step?.kind === 'landing'\"\n    :title=\"tour.title\"\n    :message=\"tour.body\"\n    :image=\"tour.step.image\"\n    :primary-label=\"tour.primaryLabel\"\n    :skip-label=\"tour.skipLabel\"\n    :waiting-for-target=\"tour.waitingForTarget\"\n    @start=\"tour.next\"\n    @skip=\"tour.skip\"\n  />\n  <TourSpotlight\n    v-else-if=\"tour.step?.kind === 'spotlight'\"\n    :step=\"tour.step\"\n    :title=\"tour.title\"\n    :body=\"tour.body\"\n    :is-last=\"tour.isLast\"\n    :can-go-back=\"tour.canGoBack\"\n    :primary-label=\"tour.primaryLabel\"\n    :skip-label=\"tour.skipLabel\"\n    :back-label=\"tour.backLabel\"\n    :counted-step-idx=\"tour.countedStepIdx\"\n    :counted-steps-total=\"tour.countedStepsTotal\"\n    :waiting-for-target=\"tour.waitingForTarget\"\n    :step-settled=\"tour.stepSettled\"\n    @advance=\"tour.next\"\n    @back=\"tour.back\"\n    @skip=\"tour.skip\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport CoachmarkLanding from './CoachmarkLanding.vue'\nimport TourSpotlight from './TourSpotlight.vue'\nimport { useOnboardingTourStore } from './onboardingTourStore'\n\nconst tour = useOnboardingTourStore()\n</script>\n","<template>\n  <div\n    v-if=\"isActive\"\n    :id=\"`tabpanel-${value}`\"\n    role=\"tabpanel\"\n    tabindex=\"0\"\n    :aria-labelledby=\"`tab-${value}`\"\n  >\n    <slot />\n  </div>\n</template>\n\n<script setup lang=\"ts\" generic=\"T extends string = string\">\nimport { computed, inject } from 'vue'\n\nimport { TAB_LIST_INJECTION_KEY } from './tabKeys'\n\nconst { value, modelValue } = defineProps<{\n  value: T\n  modelValue?: T\n}>()\n\nconst context = inject(TAB_LIST_INJECTION_KEY, undefined)\nconst isActive = computed(() =>\n  modelValue !== undefined\n    ? modelValue === value\n    : context?.modelValue.value === value\n)\n</script>\n","<template>\n  <div\n    v-if=\"skeleton\"\n    :data-testid=\"testid\"\n    class=\"relative aspect-square overflow-hidden rounded-2xl\"\n  >\n    <Skeleton class=\"absolute inset-0 rounded-2xl\" />\n    <Skeleton class=\"absolute inset-x-4 bottom-4 h-4 w-2/3 rounded-md\" />\n  </div>\n  <div\n    v-else\n    ref=\"cardRef\"\n    role=\"button\"\n    :tabindex=\"loading ? -1 : 0\"\n    :aria-disabled=\"loading\"\n    :data-testid=\"testid\"\n    :aria-label=\"failed ? t('gettingStarted.retryTemplate', { title }) : title\"\n    :aria-busy=\"loading\"\n    class=\"group/card relative cursor-pointer overflow-hidden rounded-2xl focus-visible:ring-1 focus-visible:ring-border-default focus-visible:outline-none\"\n    @click=\"onSelect\"\n    @keydown.enter.prevent=\"onSelect\"\n    @keydown.space.prevent=\"onSelect\"\n  >\n    <DefaultThumbnail\n      :src=\"imageSrc\"\n      :alt=\"title\"\n      :is-hovered\n      :is-video\n      :hover-zoom=\"5\"\n    />\n    <div\n      aria-hidden=\"true\"\n      class=\"pointer-events-none absolute inset-0 bg-linear-to-b from-black/60 via-black/20 via-50% to-black/70 transition-opacity duration-300 ease-out group-hover/card:opacity-0\"\n    />\n    <div\n      v-if=\"badgeIcon\"\n      aria-hidden=\"true\"\n      class=\"pointer-events-none absolute top-3 right-3 flex size-7 items-center justify-center rounded-full bg-black/50 text-base-foreground backdrop-blur-sm\"\n    >\n      <i :class=\"cn(badgeIcon, 'size-4')\" />\n    </div>\n    <h3\n      class=\"absolute inset-x-0 bottom-0 m-0 truncate p-4 text-sm font-semibold text-base-foreground drop-shadow-md\"\n      :title\n    >\n      {{ title }}\n    </h3>\n    <div\n      v-if=\"loading\"\n      class=\"absolute inset-0 flex items-center justify-center bg-base-background/70 backdrop-blur-md\"\n    >\n      <Loader size=\"md\" />\n    </div>\n    <div\n      v-else-if=\"failed\"\n      class=\"pointer-events-none absolute inset-0 flex flex-col items-center justify-center gap-1 bg-base-background/80 p-4 backdrop-blur-md\"\n    >\n      <span class=\"text-center text-xs font-medium text-base-foreground\">\n        {{ t('gettingStarted.templateFailed') }}\n      </span>\n      <span class=\"text-xs font-semibold text-primary\">\n        {{ t('gettingStarted.retry') }}\n      </span>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useElementHover } from '@vueuse/core'\nimport { useTemplateRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Loader from '@/components/loader/Loader.vue'\nimport DefaultThumbnail from '@/components/templates/thumbnails/DefaultThumbnail.vue'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\n\nconst {\n  imageSrc = '',\n  title = '',\n  loading\n} = defineProps<{\n  imageSrc?: string\n  title?: string\n  loading?: boolean\n  /** Shows an inline error; selecting the card again retries. */\n  failed?: boolean\n  skeleton?: boolean\n  isVideo?: boolean\n  badgeIcon?: string\n  testid?: string\n}>()\n\nconst emit = defineEmits<{ select: [] }>()\n\nconst { t } = useI18n()\n\nconst cardRef = useTemplateRef<HTMLElement>('cardRef')\nconst isHovered = useElementHover(cardRef)\n\nfunction onSelect() {\n  if (loading) return\n  emit('select')\n}\n</script>\n","<template>\n  <GettingStartedCard\n    :image-src=\"thumbnailSrc\"\n    :title\n    :loading\n    :failed\n    :is-video=\"isVideo\"\n    :testid=\"`getting-started-card-${template.name}`\"\n    @select=\"emit('select', template.name)\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport { useTemplateWorkflows } from '@/platform/workflow/templates/composables/useTemplateWorkflows'\nimport type { TemplateInfo } from '@/platform/workflow/templates/types/template'\n\nimport GettingStartedCard from './GettingStartedCard.vue'\n\nconst { template } = defineProps<{\n  template: TemplateInfo\n  loading?: boolean\n  failed?: boolean\n}>()\n\nconst emit = defineEmits<{ select: [id: string] }>()\n\nconst { getTemplateThumbnailUrl, getTemplateTitle } = useTemplateWorkflows()\n\nconst thumbnailSrc = computed(() =>\n  getTemplateThumbnailUrl(template, 'default')\n)\nconst title = computed(() => getTemplateTitle(template, 'default'))\nconst isVideo = computed(\n  () => template.mediaType === 'video' || template.mediaSubtype === 'webp'\n)\n</script>\n","/** The templates the Getting Started grid offers, in order. */\nexport const CURATED_TEMPLATE_IDS = [\n  'image_krea2_turbo_t2i',\n  'image_z_image_turbo',\n  'video_ltx2_3_i2v',\n  'video_wan2_2_14B_i2v'\n] as const\n\n/** Fills the grid, in order, when a curated template is missing from the data. */\nexport const FALLBACK_TEMPLATE_IDS = [\n  'templates-image_to_real',\n  'image_qwen_image_edit_2509',\n  'flux_fill_inpaint_example',\n  'video_ltx2_i2v_distilled'\n] as const\n\nexport const TUTORIAL_BADGE_ICON = 'icon-[lucide--graduation-cap]'\n\nexport interface TutorialCard {\n  id: string\n  titleKey: string\n  url: string\n  thumbnailTemplate: (typeof CURATED_TEMPLATE_IDS)[number]\n}\n\n/**\n * Thumbnails are offset from the Templates tab's order so the two grids don't\n * read as the same four images in the same places.\n */\nexport const tutorialCards: readonly TutorialCard[] = [\n  {\n    id: 'interface-overview',\n    titleKey: 'gettingStarted.tutorials.interfaceOverview',\n    url: 'https://docs.comfy.org/interface/overview',\n    thumbnailTemplate: 'image_z_image_turbo'\n  },\n  {\n    id: 'text-to-image',\n    titleKey: 'gettingStarted.tutorials.textToImage',\n    url: 'https://docs.comfy.org/tutorials/basic/text-to-image',\n    thumbnailTemplate: 'video_ltx2_3_i2v'\n  },\n  {\n    id: 'image-to-image',\n    titleKey: 'gettingStarted.tutorials.imageToImage',\n    url: 'https://docs.comfy.org/tutorials/basic/image-to-image',\n    thumbnailTemplate: 'video_wan2_2_14B_i2v'\n  },\n  {\n    id: 'inpaint',\n    titleKey: 'gettingStarted.tutorials.inpaint',\n    url: 'https://docs.comfy.org/tutorials/basic/inpaint',\n    thumbnailTemplate: 'image_krea2_turbo_t2i'\n  }\n]\n","<template>\n  <Teleport to=\"body\">\n    <FocusScope as-child :trapped=\"!dialogOpen\" loop>\n      <div\n        ref=\"screenRef\"\n        class=\"fixed inset-0 z-1600 flex overflow-y-auto bg-base-background focus:outline-none\"\n        role=\"dialog\"\n        :aria-modal=\"!dialogOpen\"\n        :aria-label=\"t('gettingStarted.title')\"\n        tabindex=\"-1\"\n        @keydown.escape.capture.prevent=\"dismissGettingStarted()\"\n      >\n        <div class=\"m-auto flex w-full flex-col items-center gap-8 px-8 py-16\">\n          <div class=\"flex flex-col items-center gap-3\">\n            <h1\n              class=\"m-0 text-center text-4xl/11 font-medium text-base-foreground\"\n            >\n              {{ t('gettingStarted.title') }}\n            </h1>\n            <p class=\"m-0 text-center text-base/5 text-muted-foreground\">\n              {{ t('gettingStarted.subtitle') }}\n            </p>\n          </div>\n\n          <TabList\n            v-model=\"activeTab\"\n            class=\"w-auto gap-1 rounded-full border border-border-subtle p-0.5\"\n            :aria-label=\"t('gettingStarted.tabsLabel')\"\n          >\n            <Tab\n              v-for=\"tab in tabs\"\n              :key=\"tab.value\"\n              :value=\"tab.value\"\n              class=\"gap-2.5 rounded-full px-3 text-xs font-medium text-base-foreground hover:opacity-100 data-[state=active]:bg-tertiary-background data-[state=inactive]:opacity-70\"\n            >\n              <i :class=\"cn(tab.icon, 'size-3.5')\" aria-hidden=\"true\" />\n              {{ t(tab.labelKey) }}\n            </Tab>\n          </TabList>\n\n          <div class=\"w-full max-w-5xl\">\n            <TabPanel\n              v-for=\"tab in tabs\"\n              :key=\"tab.value\"\n              :value=\"tab.value\"\n              :model-value=\"activeTab\"\n            >\n              <div\n                v-if=\"tab.value === 'templates'\"\n                class=\"grid grid-cols-2 gap-5 sm:grid-cols-3 lg:grid-cols-4\"\n              >\n                <template v-if=\"templatesStore.isLoaded\">\n                  <GettingStartedTemplateCard\n                    v-for=\"template in cards\"\n                    :key=\"template.name\"\n                    :template\n                    :loading=\"loadingTemplateId === template.name\"\n                    :failed=\"failedTemplateId === template.name\"\n                    class=\"min-w-0\"\n                    @select=\"onSelectTemplate\"\n                  />\n                </template>\n                <div\n                  v-else-if=\"catalogFailed\"\n                  class=\"col-span-full flex flex-col items-center gap-4 py-16\"\n                >\n                  <p class=\"m-0 text-center text-sm text-muted-foreground\">\n                    {{ t('gettingStarted.loadFailed') }}\n                  </p>\n                  <Button\n                    variant=\"secondary\"\n                    data-testid=\"getting-started-retry-catalog\"\n                    @click=\"loadCatalog\"\n                  >\n                    {{ t('gettingStarted.retry') }}\n                  </Button>\n                </div>\n                <template v-else>\n                  <GettingStartedCard\n                    v-for=\"id in CURATED_TEMPLATE_IDS\"\n                    :key=\"id\"\n                    skeleton\n                    :testid=\"`getting-started-card-skeleton-${id}`\"\n                    class=\"min-w-0\"\n                  />\n                </template>\n              </div>\n\n              <div\n                v-else\n                class=\"grid grid-cols-2 gap-5 sm:grid-cols-3 lg:grid-cols-4\"\n              >\n                <GettingStartedCard\n                  v-for=\"(tutorial, index) in tutorialCards\"\n                  :key=\"tutorial.id\"\n                  :image-src=\"\n                    tutorialThumbnail(tutorial.thumbnailTemplate, index)\n                  \"\n                  :title=\"t(tutorial.titleKey)\"\n                  :badge-icon=\"TUTORIAL_BADGE_ICON\"\n                  :testid=\"`getting-started-tutorial-${tutorial.id}`\"\n                  class=\"min-w-0\"\n                  @select=\"openTutorial(tutorial.url)\"\n                />\n              </div>\n            </TabPanel>\n          </div>\n\n          <Button\n            variant=\"muted-textonly\"\n            data-testid=\"getting-started-blank\"\n            @click=\"dismissGettingStarted()\"\n          >\n            {{ t('gettingStarted.startBlank') }}\n          </Button>\n        </div>\n      </div>\n    </FocusScope>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nimport { take, uniqBy } from 'es-toolkit'\nimport { FocusScope } from 'reka-ui'\nimport { computed, nextTick, onMounted, ref, useTemplateRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Tab from '@/components/tab/Tab.vue'\nimport TabList from '@/components/tab/TabList.vue'\nimport TabPanel from '@/components/tab/TabPanel.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useTemplateWorkflows } from '@/platform/workflow/templates/composables/useTemplateWorkflows'\nimport { useWorkflowTemplatesStore } from '@/platform/workflow/templates/repositories/workflowTemplatesStore'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nimport GettingStartedCard from './GettingStartedCard.vue'\nimport GettingStartedTemplateCard from './GettingStartedTemplateCard.vue'\nimport { useFirstRunEntry } from './firstRunEntry'\nimport type { TutorialCard } from './tutorialCards'\nimport {\n  CURATED_TEMPLATE_IDS,\n  FALLBACK_TEMPLATE_IDS,\n  TUTORIAL_BADGE_ICON,\n  tutorialCards\n} from './tutorialCards'\n\ntype TabValue = 'templates' | 'tutorials'\n\nconst tabs = [\n  {\n    value: 'templates' as const,\n    labelKey: 'gettingStarted.tabs.templates',\n    icon: 'icon-[lucide--layout-template]'\n  },\n  {\n    value: 'tutorials' as const,\n    labelKey: 'gettingStarted.tabs.tutorials',\n    icon: 'icon-[lucide--tv-minimal-play]'\n  }\n]\n\nconst { t } = useI18n()\n\nconst { dismissGettingStarted, dismissIntoFirstRunTour } = useFirstRunEntry()\nconst templatesStore = useWorkflowTemplatesStore()\nconst dialogStore = useDialogStore()\n\n/** The dialog layer starts at z-1700; sitting below it and releasing the trap keeps any dialog (desktop sign-in approval, invite links) reachable. */\nconst dialogOpen = computed(() => dialogStore.dialogStack.length > 0)\nconst { loadWorkflowTemplate, getTemplateThumbnailUrl, loadingTemplateId } =\n  useTemplateWorkflows()\n\nconst activeTab = ref<TabValue>('templates')\nconst failedTemplateId = ref<string | null>(null)\nconst catalogFailed = ref(false)\n\nconst screenRef = useTemplateRef<HTMLElement>('screenRef')\n\nfunction resolveTemplates(ids: readonly string[]) {\n  return ids\n    .map((id) => templatesStore.getTemplateByName(id))\n    .filter((template) => template !== undefined)\n}\n\n/** Backfills past the pinned ids so a template-package skew cannot empty the grid. */\nconst cards = computed(() =>\n  take(\n    uniqBy(\n      [\n        ...resolveTemplates(CURATED_TEMPLATE_IDS),\n        ...resolveTemplates(FALLBACK_TEMPLATE_IDS),\n        ...templatesStore.enhancedTemplates\n      ],\n      (template) => template.name\n    ),\n    CURATED_TEMPLATE_IDS.length\n  )\n)\n\nasync function loadCatalog() {\n  catalogFailed.value = false\n  await templatesStore.loadWorkflowTemplates()\n  catalogFailed.value = !templatesStore.isLoaded\n}\n\n// Nothing else loads the catalog on this path, so load it (and take focus) on open.\nonMounted(() => {\n  if (!templatesStore.isLoaded) void loadCatalog()\n  void nextTick(() => {\n    if (!dialogOpen.value) screenRef.value?.focus()\n  })\n})\n\nfunction tutorialThumbnail(\n  id: TutorialCard['thumbnailTemplate'],\n  index: number\n) {\n  const fallbacks = cards.value\n  const template =\n    templatesStore.getTemplateByName(id) ??\n    (fallbacks.length ? fallbacks[index % fallbacks.length] : undefined)\n  return template ? getTemplateThumbnailUrl(template, 'default') : ''\n}\n\nfunction openTutorial(url: string) {\n  window.open(url, '_blank', 'noopener,noreferrer')\n}\n\nasync function onSelectTemplate(id: string) {\n  if (loadingTemplateId.value) return\n  failedTemplateId.value = null\n\n  const result = await loadWorkflowTemplate(id, 'default')\n  if (result === 'loaded') {\n    try {\n      await dismissIntoFirstRunTour(id)\n    } catch (error) {\n      console.error('first-run tour failed to start', error)\n    }\n    return\n  }\n\n  failedTemplateId.value = id\n}\n</script>\n","<template>\n  <template v-if=\"onScreen\">\n    <div\n      v-if=\"isPositioned && ringStyle\"\n      aria-hidden=\"true\"\n      data-testid=\"first-run-nudge-ring\"\n      class=\"pointer-events-none fixed z-1000 rounded-lg outline-2 -outline-offset-2 outline-coach-ring\"\n      :style=\"ringStyle\"\n    />\n    <div\n      ref=\"cardRef\"\n      role=\"region\"\n      :aria-labelledby=\"titleId\"\n      data-testid=\"first-run-nudge\"\n      :class=\"\n        cn(\n          'fixed z-1000 w-80 animate-in animation-duration-500 fade-in-0',\n          !isPositioned && 'invisible'\n        )\n      \"\n      :style=\"floatingStyles\"\n    >\n      <i\n        data-testid=\"first-run-nudge-cursor\"\n        :class=\"\n          cn(\n            'absolute icon-[lucide--mouse-pointer-2] size-4 text-base-foreground drop-shadow-md',\n            cursorEdgeClass(placement)\n          )\n        \"\n        aria-hidden=\"true\"\n      />\n      <div\n        class=\"flex flex-col overflow-hidden rounded-xl border border-border-default/50 bg-base-background shadow-lg\"\n      >\n        <div class=\"relative h-50 w-full bg-secondary-background\">\n          <img :src=\"NUDGE_IMAGE\" alt=\"\" class=\"size-full object-cover\" />\n          <Button\n            class=\"absolute top-2 right-2 opacity-50 hover:opacity-100\"\n            variant=\"secondary\"\n            size=\"icon\"\n            :aria-label=\"t('g.close')\"\n            @click=\"dismissNudge\"\n          >\n            <i class=\"icon-[lucide--x] size-4\" aria-hidden=\"true\" />\n          </Button>\n        </div>\n\n        <div\n          class=\"flex flex-col gap-2 border-t border-border-default px-4 pt-6 pb-4\"\n        >\n          <p :id=\"titleId\" class=\"m-0 text-sm/5 font-bold text-base-foreground\">\n            {{ t(`${copyKey}.title`) }}\n          </p>\n          <p class=\"m-0 text-sm text-muted-foreground\">\n            {{ t(`${copyKey}.body`) }}\n          </p>\n        </div>\n\n        <div class=\"flex items-center justify-end gap-4 px-4 pb-4\">\n          <Button\n            variant=\"link\"\n            size=\"unset\"\n            class=\"h-6 text-sm font-normal\"\n            @click=\"dismissNudge\"\n          >\n            {{ t('onboardingCoachmarks.firstRun.nudge.dismiss') }}\n          </Button>\n          <Button\n            variant=\"inverted\"\n            size=\"lg\"\n            class=\"font-normal\"\n            data-testid=\"first-run-nudge-explore\"\n            @click=\"onExplore\"\n          >\n            {{ t('onboardingCoachmarks.firstRun.nudge.explore') }}\n          </Button>\n        </div>\n      </div>\n    </div>\n  </template>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport {\n  breakpointsTailwind,\n  useBreakpoints,\n  onClickOutside,\n  useEventListener,\n  useTimeoutFn\n} from '@vueuse/core'\nimport { computed, ref, useId, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useWorkflowTemplateSelectorDialog } from '@/composables/useWorkflowTemplateSelectorDialog'\nimport { cursorEdgeClass } from '@/platform/onboarding/coachmarkLayout'\nimport { useOnboardingTourStore } from '@/platform/onboarding/onboardingTourStore'\nimport { FIRST_RUN_COACH_IDS } from '@/platform/onboarding/onboardingTours'\nimport type { SpotlightStep } from '@/platform/onboarding/onboardingTours'\nimport { useCoachmarkTarget } from '@/platform/onboarding/useCoachmarkTarget'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\n\nimport { useFirstRunTourController } from '../tour/useFirstRunTourController'\n\nconst NUDGE_IMAGE = '/assets/images/og-image.png'\n\n/** Delayed, so the finished workflow is seen before this fades in over it. */\nconst APPEAR_DELAY_MS = 1500\n\nconst { t } = useI18n()\nconst { nudgeArmed, tourWasCompleted, dismissNudge } =\n  useFirstRunTourController()\nconst dialogStore = useDialogStore()\nconst settingStore = useSettingStore()\nconst sidebarTabStore = useSidebarTabStore()\nconst canvasStore = useCanvasStore()\nconst onboardingTourStore = useOnboardingTourStore()\nconst desktopLayout = useBreakpoints(breakpointsTailwind).greaterOrEqual('md')\nconst telemetry = useTelemetry()\nconst titleId = useId()\n\nconst nudgeStep = computed<SpotlightStep>(() => ({\n  kind: 'spotlight',\n  name: 'nudge',\n  coachId: nudgeArmed.value ? FIRST_RUN_COACH_IDS.templatesButton : undefined,\n  placement:\n    settingStore.get('Comfy.Sidebar.Location') === 'right'\n      ? 'leftCenter'\n      : 'rightCenter',\n  cursor: true\n}))\n\nconst cardRef = ref<HTMLElement | null>(null)\nconst {\n  anchor,\n  hasTarget,\n  targetRect,\n  floatingStyles,\n  isPositioned,\n  placement\n} = useCoachmarkTarget(nudgeStep, cardRef)\nconst ringStyle = computed(() => {\n  const rect = targetRect.value\n  if (!rect) return null\n  return {\n    left: `${rect.left}px`,\n    top: `${rect.top}px`,\n    width: `${rect.width}px`,\n    height: `${rect.height}px`\n  }\n})\n\n// Only a tour walked to the end made a first result to congratulate; every\n// other ending still gets a nudge, pointing at the templates instead.\nconst copyKey = computed(\n  () =>\n    `onboardingCoachmarks.firstRun.nudge.${tourWasCompleted.value ? 'ran' : 'noTour'}`\n)\n\nconst onScreen = ref(false)\nlet reported = false\nconst { start: scheduleAppearance, stop: cancelAppearance } = useTimeoutFn(\n  () => {\n    if (anchor.value instanceof HTMLElement)\n      anchor.value.scrollIntoView({ block: 'nearest' })\n    onScreen.value = true\n    if (reported) return\n    reported = true\n    telemetry?.trackOnboardingTour('nudge_shown', {\n      tour: 'firstRun',\n      tour_completed: tourWasCompleted.value\n    })\n  },\n  APPEAR_DELAY_MS,\n  { immediate: false }\n)\n\nonClickOutside(cardRef, dismissNudge)\n\nuseEventListener(document, 'keydown', (event: KeyboardEvent) => {\n  if (onScreen.value && event.key === 'Escape') dismissNudge()\n})\n\n/** The nudge sits below the modal stack, so it waits for a clear screen. */\nwatch(\n  () =>\n    desktopLayout.value &&\n    dialogStore.dialogStack.length === 0 &&\n    hasTarget.value &&\n    !onboardingTourStore.activeTour &&\n    !canvasStore.isPickingNodes &&\n    !sidebarTabStore.activeSidebarTab,\n  (screenIsClear) => {\n    cancelAppearance()\n    if (!screenIsClear) {\n      onScreen.value = false\n      return\n    }\n    scheduleAppearance()\n  },\n  { immediate: true }\n)\n\nfunction onExplore() {\n  useWorkflowTemplateSelectorDialog().show('first_run_nudge')\n  telemetry?.trackOnboardingTour('explore_templates_clicked', {\n    tour: 'firstRun',\n    tour_completed: tourWasCompleted.value\n  })\n  dismissNudge()\n}\n</script>\n","<template>\n  <GettingStartedScreen v-if=\"gettingStartedVisible\" />\n  <FirstRunTourNudge />\n</template>\n\n<script setup lang=\"ts\">\nimport GettingStartedScreen from './gettingStarted/GettingStartedScreen.vue'\nimport { useFirstRunEntry } from './gettingStarted/firstRunEntry'\nimport FirstRunTourNudge from './nudge/FirstRunTourNudge.vue'\nimport { useFirstRunTourController } from './tour/useFirstRunTourController'\n\nconst { gettingStartedVisible } = useFirstRunEntry()\n\nuseFirstRunTourController()\n</script>\n","import { computed } from 'vue'\nimport type { ComputedRef } from 'vue'\n\nimport type { ComfyCommandImpl } from '@/stores/commandStore'\n\ntype SubcategoryRule = {\n  pattern: string | RegExp\n  subcategory: string\n}\n\ntype SubcategoryConfig = {\n  defaultSubcategory: string\n  rules: SubcategoryRule[]\n}\n\n/**\n * Composable for grouping commands by subcategory based on configurable rules\n */\nexport function useCommandSubcategories(\n  commands: ComputedRef<ComfyCommandImpl[]>,\n  config: SubcategoryConfig\n) {\n  const subcategories = computed(() => {\n    const result: Partial<Record<string, ComfyCommandImpl[]>> = {}\n\n    for (const command of commands.value) {\n      let subcategory = config.defaultSubcategory\n\n      // Find the first matching rule\n      for (const rule of config.rules) {\n        const matches =\n          typeof rule.pattern === 'string'\n            ? command.id.includes(rule.pattern)\n            : rule.pattern.test(command.id)\n\n        if (matches) {\n          subcategory = rule.subcategory\n          break\n        }\n      }\n\n      const commands = (result[subcategory] ||= [])\n      commands.push(command)\n    }\n\n    return result as Record<string, ComfyCommandImpl[]>\n  })\n\n  return {\n    subcategories\n  }\n}\n\n/**\n * Predefined configuration for view controls subcategories\n */\nexport const VIEW_CONTROLS_CONFIG: SubcategoryConfig = {\n  defaultSubcategory: 'view',\n  rules: [\n    { pattern: 'Zoom', subcategory: 'view' },\n    { pattern: 'Fit', subcategory: 'view' },\n    { pattern: 'Panel', subcategory: 'panel-controls' },\n    { pattern: 'Sidebar', subcategory: 'panel-controls' }\n  ]\n}\n\n/**\n * Predefined configuration for essentials subcategories\n */\nexport const ESSENTIALS_CONFIG: SubcategoryConfig = {\n  defaultSubcategory: 'workflow',\n  rules: [\n    { pattern: 'Workflow', subcategory: 'workflow' },\n    { pattern: 'Node', subcategory: 'node' },\n    { pattern: 'Queue', subcategory: 'queue' }\n  ]\n}\n","<template>\n  <div class=\"shortcuts-list flex justify-center\">\n    <div\n      data-testid=\"shortcuts-columns\"\n      class=\"grid h-full w-[90%] grid-cols-1 gap-4 md:grid-cols-3 md:gap-24\"\n    >\n      <div\n        v-for=\"(subcategoryCommands, subcategory) in filteredSubcategories\"\n        :key=\"subcategory\"\n        class=\"flex flex-col\"\n      >\n        <h3\n          class=\"subcategory-title mb-4 text-xs font-bold tracking-wide text-text-secondary uppercase\"\n        >\n          {{ getSubcategoryTitle(subcategory) }}\n        </h3>\n\n        <div class=\"flex flex-col gap-1\">\n          <div\n            v-for=\"command in subcategoryCommands\"\n            :key=\"command.id\"\n            class=\"shortcut-item flex items-center justify-between rounded-sm py-2 transition-colors duration-200\"\n          >\n            <div class=\"shortcut-info grow pr-4\">\n              <div class=\"shortcut-name text-sm font-medium\">\n                {{ t(`commands.${normalizeI18nKey(command.id)}.label`) }}\n              </div>\n            </div>\n\n            <div class=\"keybinding-display shrink-0\">\n              <div\n                class=\"keybinding-combo flex gap-1\"\n                :aria-label=\"`Keyboard shortcut: ${command.keybinding!.combo.getKeySequences().join(' + ')}`\"\n              >\n                <span\n                  v-for=\"key in command.keybinding!.combo.getKeySequences()\"\n                  :key=\"key\"\n                  class=\"key-badge min-w-6 rounded-sm bg-muted-background px-2 py-1 text-center font-mono text-xs\"\n                >\n                  {{ formatKey(key) }}\n                </span>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { ComfyCommandImpl } from '@/stores/commandStore'\nimport { normalizeI18nKey } from '@/utils/formatUtil'\n\nconst { t } = useI18n()\n\nconst { subcategories } = defineProps<{\n  subcategories: Record<string, ComfyCommandImpl[]>\n}>()\n\nconst filteredSubcategories = computed(() => {\n  const result: Record<string, ComfyCommandImpl[]> = {}\n\n  for (const [subcategory, commands] of Object.entries(subcategories)) {\n    result[subcategory] = commands.filter((cmd) => !!cmd.keybinding)\n  }\n\n  return result\n})\n\nconst getSubcategoryTitle = (subcategory: string): string => {\n  const titleMap: Record<string, string> = {\n    workflow: t('shortcuts.subcategories.workflow'),\n    node: t('shortcuts.subcategories.node'),\n    queue: t('shortcuts.subcategories.queue'),\n    view: t('shortcuts.subcategories.view'),\n    'panel-controls': t('shortcuts.subcategories.panelControls')\n  }\n\n  return titleMap[subcategory] || subcategory\n}\n\nconst formatKey = (key: string): string => {\n  const keyMap: Record<string, string> = {\n    Control: 'Ctrl',\n    Meta: 'Cmd',\n    ArrowUp: '↑',\n    ArrowDown: '↓',\n    ArrowLeft: '←',\n    ArrowRight: '→',\n    Backspace: '⌫',\n    Delete: '⌦',\n    Enter: '↵',\n    Escape: 'Esc',\n    Tab: '⇥',\n    ' ': 'Space'\n  }\n\n  return keyMap[key] || key\n}\n</script>\n","<template>\n  <div class=\"flex h-full flex-col p-4\">\n    <div class=\"min-h-0 flex-1 overflow-auto\">\n      <ShortcutsList\n        :commands=\"essentialsCommands\"\n        :subcategories=\"essentialsSubcategories\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport {\n  ESSENTIALS_CONFIG,\n  useCommandSubcategories\n} from '@/composables/bottomPanelTabs/useCommandSubcategories'\nimport { useCommandStore } from '@/stores/commandStore'\n\nimport ShortcutsList from './ShortcutsList.vue'\n\nconst commandStore = useCommandStore()\n\nconst essentialsCommands = computed(() =>\n  commandStore.commands.filter((cmd) => cmd.category === 'essentials')\n)\n\nconst { subcategories: essentialsSubcategories } = useCommandSubcategories(\n  essentialsCommands,\n  ESSENTIALS_CONFIG\n)\n</script>\n","<template>\n  <div class=\"flex h-full flex-col p-4\">\n    <div class=\"min-h-0 flex-1 overflow-auto\">\n      <ShortcutsList\n        :commands=\"viewControlsCommands\"\n        :subcategories=\"viewControlsSubcategories\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport {\n  VIEW_CONTROLS_CONFIG,\n  useCommandSubcategories\n} from '@/composables/bottomPanelTabs/useCommandSubcategories'\nimport { useCommandStore } from '@/stores/commandStore'\n\nimport ShortcutsList from './ShortcutsList.vue'\n\nconst commandStore = useCommandStore()\n\nconst viewControlsCommands = computed(() =>\n  commandStore.commands.filter((cmd) => cmd.category === 'view-controls')\n)\n\nconst { subcategories: viewControlsSubcategories } = useCommandSubcategories(\n  viewControlsCommands,\n  VIEW_CONTROLS_CONFIG\n)\n</script>\n","import { markRaw } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport EssentialsPanel from '@/components/bottomPanel/tabs/shortcuts/EssentialsPanel.vue'\nimport ViewControlsPanel from '@/components/bottomPanel/tabs/shortcuts/ViewControlsPanel.vue'\nimport type { BottomPanelExtension } from '@/types/extensionTypes'\n\nexport const useShortcutsTab = (): BottomPanelExtension[] => {\n  const { t } = useI18n()\n  return [\n    {\n      id: 'shortcuts-essentials',\n      title: t('shortcuts.essentials'), // For command labels (collected by i18n workflow)\n      titleKey: 'shortcuts.essentials', // For dynamic translation in UI\n      component: markRaw(EssentialsPanel),\n      type: 'vue',\n      targetPanel: 'shortcuts'\n    },\n    {\n      id: 'shortcuts-view-controls',\n      title: t('shortcuts.viewControls'), // For command labels (collected by i18n workflow)\n      titleKey: 'shortcuts.viewControls', // For dynamic translation in UI\n      component: markRaw(ViewControlsPanel),\n      type: 'vue',\n      targetPanel: 'shortcuts'\n    }\n  ]\n}\n","import { useShortcutsTab } from '@/composables/bottomPanelTabs/useShortcutsTab'\nimport { isDesktop } from '@/platform/distribution/types'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useBottomPanelStore } from '@/stores/workspace/bottomPanelStore'\n\nexport async function registerCoreBottomPanelTabs() {\n  const bottomPanelStore = useBottomPanelStore()\n\n  for (const tab of useShortcutsTab()) {\n    bottomPanelStore.registerBottomPanelTab(tab)\n  }\n\n  if (__DISTRIBUTION__ === 'cloud') return\n\n  try {\n    const { useLogsTerminalTab, useCommandTerminalTab } =\n      await import('@/composables/bottomPanelTabs/useTerminalTabs')\n    bottomPanelStore.registerBottomPanelTab(useLogsTerminalTab())\n    if (isDesktop) {\n      bottomPanelStore.registerBottomPanelTab(useCommandTerminalTab())\n    }\n  } catch (error) {\n    reportError(error, {\n      errorType: 'error_loading_terminal_tabs',\n      surface: 'platform'\n    })\n  }\n}\n","const HTML_ESCAPE_MAP: Record<string, string> = {\n  '&': '&amp;',\n  '<': '&lt;',\n  '>': '&gt;',\n  '\"': '&quot;',\n  \"'\": '&#39;'\n}\n\n/**\n * Escapes HTML-significant characters (`& < > \" '`) so a raw string displays\n * literally instead of being parsed as markup.\n * @param text - The string to escape\n * @returns The escaped string, safe to feed into an HTML parser as plain text\n * @example\n * escapeHtml('<lora:my_style_v2:0.8>') // returns '&lt;lora:my_style_v2:0.8&gt;'\n */\nexport function escapeHtml(text: string): string {\n  if (!text) return ''\n  return text.replace(/[&<>\"']/g, (char) => HTML_ESCAPE_MAP[char])\n}\n","<template>\n  <div\n    class=\"relative max-h-[200px] min-h-[28px] w-full overflow-y-auto rounded-lg px-4 py-2 text-xs\"\n  >\n    <div class=\"flex items-center gap-2\">\n      <div class=\"flex flex-1 items-center gap-2 break-all\">\n        <SanitizedHtml as=\"span\" :html=\"formattedText\" />\n        <Skeleton\n          v-if=\"isParentNodeExecuting\"\n          data-testid=\"skeleton\"\n          class=\"h-4 flex-1\"\n        />\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { default as DOMPurify } from 'dompurify'\nimport { computed } from 'vue'\n\nimport SanitizedHtml from '@/components/common/SanitizedHtml.vue'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport type { NodeId } from '@/types/nodeId'\nimport { linkifyHtml, nl2br } from '@/utils/formatUtil'\nimport { escapeHtml } from '@/utils/htmlEscape'\n\nconst modelValue = defineModel<string>({ required: true })\nconst props = defineProps<{\n  nodeId: NodeId\n}>()\n\nconst executionStore = useExecutionStore()\nconst isParentNodeExecuting = computed(() => {\n  if (executionStore.isIdle) return false\n  return executionStore.executingNodeIds.includes(props.nodeId)\n})\nconst formattedText = computed(() => {\n  const src = modelValue.value\n  // Turn [[label|url]] into placeholders to avoid interfering with linkifyHtml\n  const tokens: { label: string; url: string }[] = []\n  const holed = src.replace(\n    /\\[\\[([^|\\]]+)\\|([^\\]]+)\\]\\]/g,\n    (_m, label, url) => {\n      tokens.push({ label: String(label), url: String(url) })\n      return `__LNK${tokens.length - 1}__`\n    }\n  )\n\n  // Escape HTML-significant characters BEFORE linkifying so bracket-delimited\n  // text that looks like a tag (e.g. `<lora:my_style_v2:0.8>`) displays\n  // literally instead of being parsed as markup and dropped. linkifyHtml only\n  // matches http(s)/ftp/file/www URLs, none of which contain the escaped\n  // entities, so escaping first doesn't stop real URLs from being linkified.\n  // Keep current behavior otherwise (auto-link bare URLs + \\n -> <br>).\n  let html = nl2br(linkifyHtml(escapeHtml(holed)))\n\n  // Restore placeholders as <a>...</a> (escape label/url for safety)\n  html = html.replace(/__LNK(\\d+)__/g, (_m, i) => {\n    const { label, url } = tokens[+i]\n    const safeHref = escapeHtml(url)\n    const safeLabel = escapeHtml(label)\n    return /^https?:\\/\\//i.test(url)\n      ? `<a href=\"${safeHref}\" target=\"_blank\" rel=\"noopener noreferrer\">${safeLabel}</a>`\n      : safeLabel\n  })\n\n  // Strict allowlist: this widget only needs anchors and line breaks. Raw\n  // websocket progress text flows into modelValue, so we drop every other\n  // tag (img, script, iframe, etc.) to keep the v-html trust boundary tight.\n  return DOMPurify.sanitize(html, {\n    ALLOWED_TAGS: ['a', 'br'],\n    ALLOWED_ATTR: ['href', 'target', 'rel']\n  })\n})\n</script>\n","import TextPreviewWidget from '@/components/graph/widgets/TextPreviewWidget.vue'\nimport { resolveNodeRootGraphId } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport type { InputSpec } from '@/schemas/nodeDef/nodeDefSchemaV2'\nimport { ComponentWidgetImpl, addWidget } from '@/scripts/domWidget'\nimport type { ComponentWidgetStandardProps } from '@/scripts/domWidget'\nimport { useApp } from '@/scripts/appInstance'\nimport type { ComfyWidgetConstructorV2 } from '@/types/widgetConstructor'\nimport type { IBaseWidget } from '@/lib/litegraph/src/types/widgets'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { widgetId } from '@/types/widgetId'\n\ntype TextPreviewCustomProps = Omit<\n  InstanceType<typeof TextPreviewWidget>['$props'],\n  ComponentWidgetStandardProps\n>\n\nconst PADDING = 16\n\nexport function useTextPreviewWidget(\n  options: {\n    minHeight?: number\n  } = {}\n): ComfyWidgetConstructorV2 {\n  function widgetConstructor(\n    node: LGraphNode,\n    inputSpec: InputSpec\n  ): IBaseWidget {\n    const widget = new ComponentWidgetImpl<\n      string | object,\n      TextPreviewCustomProps\n    >({\n      node,\n      name: inputSpec.name,\n      component: TextPreviewWidget,\n      inputSpec,\n      props: {\n        nodeId: node.id\n      },\n      options: {\n        getValue: () => {\n          const value =\n            useWidgetValueStore().getWidget(\n              widgetId(\n                resolveNodeRootGraphId(node, useApp().rootGraph.id),\n                node.id,\n                inputSpec.name\n              )\n            )?.value ?? ''\n          return typeof value === 'number' || typeof value === 'boolean'\n            ? String(value)\n            : value\n        },\n        setValue: (value: string | object) => {\n          const graphId = resolveNodeRootGraphId(node, useApp().rootGraph.id)\n          const widgetState = useWidgetValueStore().getWidget(\n            widgetId(graphId, node.id, inputSpec.name)\n          )\n          if (widgetState)\n            widgetState.value =\n              typeof value === 'string' ? value : String(value)\n        },\n        getMinHeight: () => options.minHeight ?? 42 + PADDING,\n        serialize: false,\n        read_only: true\n      },\n      type: inputSpec.type\n    })\n    widget.serialize = false\n    addWidget(node, widget)\n    return widget\n  }\n\n  return widgetConstructor\n}\n","import { resolveNodeRootGraphId } from '@/lib/litegraph/src/litegraph'\nimport type { LGraphNode } from '@/lib/litegraph/src/litegraph'\nimport { useTextPreviewWidget } from '@/renderer/extensions/vueNodes/widgets/composables/useProgressTextWidget'\nimport { useApp } from '@/scripts/appInstance'\nimport { useWidgetValueStore } from '@/stores/widgetValueStore'\nimport { widgetId } from '@/types/widgetId'\n\nconst TEXT_PREVIEW_WIDGET_NAME = '$$node-text-preview'\n\n/**\n * Composable for handling node text previews\n */\nexport function useNodeProgressText() {\n  const textPreviewWidget = useTextPreviewWidget()\n\n  const findTextPreviewWidget = (node: LGraphNode) =>\n    node.widgets?.find((w) => w.name === TEXT_PREVIEW_WIDGET_NAME)\n\n  const addTextPreviewWidget = (node: LGraphNode) =>\n    textPreviewWidget(node, {\n      name: TEXT_PREVIEW_WIDGET_NAME,\n      type: 'progressText'\n    })\n\n  /**\n   * Shows text preview for a node\n   * @param node The graph node to show the preview for\n   */\n  function showTextPreview(node: LGraphNode, text: string) {\n    const widget = findTextPreviewWidget(node) ?? addTextPreviewWidget(node)\n    widget.value = text\n    node.setDirtyCanvas(true)\n  }\n\n  /**\n   * Removes text preview from a node\n   * @param node The graph node to remove the preview from\n   */\n  function removeTextPreview(node: LGraphNode) {\n    if (!node.widgets) return\n\n    const widgetIdx = node.widgets.findIndex(\n      (w) => w.name === TEXT_PREVIEW_WIDGET_NAME\n    )\n\n    if (widgetIdx > -1) {\n      node.widgets[widgetIdx].onRemove?.()\n      node.widgets.splice(widgetIdx, 1)\n      const graphId = resolveNodeRootGraphId(node, useApp().rootGraph.id)\n      useWidgetValueStore().deleteWidget(\n        widgetId(graphId, node.id, TEXT_PREVIEW_WIDGET_NAME)\n      )\n    }\n  }\n\n  return {\n    showTextPreview,\n    removeTextPreview\n  }\n}\n","import { useEventListener } from '@vueuse/core'\n\nimport { useNodeProgressText } from '@/composables/node/useNodeProgressText'\nimport type { ProgressTextWsMessage } from '@/platform/remote/comfyui/execution/types'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport { api } from '@/scripts/api'\nimport type { QueuedJob } from '@/stores/executionStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { parseNodeId } from '@/types/nodeId'\n\nexport function useProgressTextPreviews() {\n  const executionStore = useExecutionStore()\n  const workflowStore = useWorkflowStore()\n  const canvasStore = useCanvasStore()\n  const { showTextPreview, removeTextPreview } = useNodeProgressText()\n\n  function findNode(currentId: string | undefined) {\n    if (!currentId) return\n    const nodeId = parseNodeId(currentId)\n    if (!nodeId) return\n    return canvasStore.canvas?.graph?.getNodeById(nodeId) ?? undefined\n  }\n\n  function handleProgressText(e: CustomEvent<ProgressTextWsMessage>) {\n    const { nodeId, text, prompt_id } = e.detail\n    if (!text || !nodeId) return\n\n    const activeJobId = executionStore.activeJobId\n    if (prompt_id && activeJobId && prompt_id !== activeJobId) return\n\n    const executionId = String(nodeId)\n    const currentId = executionId.includes(':')\n      ? workflowStore.executionIdToCurrentId(executionId)\n      : executionId\n    const node = findNode(currentId)\n    if (node) showTextPreview(node, text)\n  }\n\n  function clearTextPreviews(job: QueuedJob) {\n    if (!job.workflow || job.workflow !== workflowStore.activeWorkflow) return\n\n    for (const executionId of Object.keys(job.nodes)) {\n      const node = findNode(workflowStore.executionIdToCurrentId(executionId))\n      if (node) removeTextPreview(node)\n    }\n  }\n\n  useEventListener(api, 'progress_text', handleProgressText)\n  executionStore.onJobReset(clearTextPreviews)\n}\n","<template>\n  <div\n    :class=\"\n      cn(\n        'flex shrink-0 cursor-pointer items-center justify-center rounded-lg border-none bg-secondary-background p-0 shadow-sm outline-hidden transition-all duration-200',\n        backgroundClass\n      )\n    \"\n  >\n    <slot></slot>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { backgroundClass } = defineProps<{\n  backgroundClass?: string\n}>()\n</script>\n","/**\n * The drag half of the application-wide asset drag/drop contract.\n *\n * Every surface that lets a user drag an asset out of the assets panel writes\n * the same two flavours, so the drop side stays view-agnostic: the agent\n * composer accepts a drop by looking for {@link MIME_ASSET_INFO} in\n * `dataTransfer.types` alone, and the canvas loads the file from `text/uri-list`.\n * Keeping this in one place is what stops a view mode from silently shipping a\n * row that starts a drag carrying nothing.\n */\nimport { getMediaTypeFromFilename } from '@/utils/formatUtil'\nimport { api } from '@/scripts/api'\n\nimport { getAssetType } from '../composables/media/assetMappers'\nimport { getOutputAssetMetadata } from '../schemas/assetMetadataSchema'\nimport type { AssetItem } from '../schemas/assetSchema'\nimport { MIME_ASSET_INFO } from '../schemas/mediaAssetSchema'\nimport { getAssetUrlFilename } from './assetMetadataUtils'\nimport { resolvePreviewUrl } from './assetPreviewUtil'\nimport { getAssetFileUrl } from './assetUrlUtil'\n\nfunction resolveThumbnailUrl(url: string): URL | null {\n  const source =\n    URL.canParse(url) || url.startsWith('//') ? url : api.apiURL(url)\n  return URL.parse(source, location.href)\n}\n\nfunction assetMediaSources(asset: AssetItem) {\n  const mediaKind = getMediaTypeFromFilename(asset.name)\n  const previewUrl = URL.parse(resolvePreviewUrl(asset), location.href)\n  const playable = mediaKind === 'video' || mediaKind === 'audio'\n  const mediaUrl = playable\n    ? URL.parse(\n        getAssetFileUrl(asset, { disposition: 'inline' }),\n        location.href\n      )\n    : undefined\n  const posterUrl = asset.preview_id\n    ? previewUrl\n    : asset.thumbnail_url && asset.thumbnail_url !== asset.preview_url\n      ? resolveThumbnailUrl(asset.thumbnail_url)\n      : undefined\n  return {\n    media_kind: mediaKind,\n    preview_url:\n      mediaKind === 'image'\n        ? previewUrl?.toString()\n        : mediaKind === 'video'\n          ? posterUrl?.toString()\n          : undefined,\n    media_url: mediaUrl?.toString()\n  }\n}\n\n/**\n * Start a native drag carrying `asset`.\n *\n * Ctrl/Meta cancels the drag rather than carrying the asset: those modifiers\n * belong to panel selection (marquee, range select), and a native drag would\n * swallow the gesture.\n *\n * @param event The `dragstart` event from the dragged row or card\n * @param asset The asset that row or card renders, if it has one yet\n */\nexport function startAssetDrag(\n  event: DragEvent,\n  asset: AssetItem | undefined\n): void {\n  if (event.ctrlKey || event.metaKey) {\n    event.preventDefault()\n    return\n  }\n\n  if (!asset) return\n\n  const { dataTransfer } = event\n  if (!dataTransfer) return\n\n  const output = getOutputAssetMetadata(asset.user_metadata)?.allOutputs?.[0]\n  const assetInfo = {\n    ...(output?.filename\n      ? {\n          filename: output.filename,\n          subfolder: output.subfolder,\n          type: output.type,\n          display_name: output.display_name\n        }\n      : {\n          filename: asset.name,\n          type: getAssetType(asset.tags),\n          display_name: asset.display_name ?? undefined\n        }),\n    attachment_ref: getAssetUrlFilename(asset),\n    ...assetMediaSources(asset)\n  }\n  dataTransfer.setData(MIME_ASSET_INFO, JSON.stringify(assetInfo))\n\n  const fileUrl = URL.parse(getAssetFileUrl(asset), location.href)\n  if (!fileUrl) return\n\n  dataTransfer.setData('text/uri-list', fileUrl.toString())\n}\n","/**\n * Shared workflow actions service\n * Provides reusable workflow operations that can be used by both\n * job menu and media asset actions\n */\n\nimport { downloadBlob } from '@/scripts/utils'\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useDialogService } from '@/services/dialogService'\nimport { appendJsonExt } from '@/utils/formatUtil'\nimport { t } from '@/i18n'\n\n/**\n * Provides shared workflow actions\n * These operations are used by multiple contexts (jobs, assets)\n * to avoid code duplication while maintaining flexibility\n */\nexport function useWorkflowActionsService() {\n  const workflowStore = useWorkflowStore()\n  const workflowService = useWorkflowService()\n  const settingStore = useSettingStore()\n  const dialogService = useDialogService()\n\n  /**\n   * Export workflow as JSON file with optional filename prompt\n   *\n   * @param workflow The workflow data to export\n   * @param defaultFilename Default filename to use\n   * @returns Result of the export operation\n   *\n   * @example\n   * const result = await exportWorkflowAction(workflow, 'MyWorkflow.json')\n   * if (result.success) {\n   *   toast.success('Exported!')\n   * }\n   */\n  const exportWorkflowAction = async (\n    workflow: ComfyWorkflowJSON | null,\n    defaultFilename: string\n  ): Promise<{\n    success: boolean\n    cancelled?: boolean\n    error?: string\n  }> => {\n    if (!workflow) {\n      return { success: false, error: 'No workflow data available' }\n    }\n\n    try {\n      let filename = defaultFilename\n\n      // Optionally prompt for custom filename\n      if (settingStore.get('Comfy.PromptFilename')) {\n        const input = await dialogService.prompt({\n          title: t('workflowService.exportWorkflow'),\n          message: t('workflowService.enterFilenamePrompt'),\n          defaultValue: filename\n        })\n        // User cancelled the prompt\n        if (!input) return { success: false, cancelled: true }\n        filename = appendJsonExt(input)\n      }\n\n      // Convert workflow to formatted JSON\n      const json = JSON.stringify(workflow, null, 2)\n      const blob = new Blob([json], { type: 'application/json' })\n      downloadBlob(filename, blob)\n\n      return { success: true }\n    } catch (error) {\n      return {\n        success: false,\n        error:\n          error instanceof Error ? error.message : 'Failed to export workflow'\n      }\n    }\n  }\n\n  /**\n   * Open workflow in new tab\n   * Creates a temporary workflow and opens it via the workflow service\n   *\n   * @param workflow The workflow data to open\n   * @param filename Filename for the temporary workflow\n   * @returns Result of the open operation\n   *\n   * @example\n   * const result = await openWorkflowAction(workflow, 'Job 123.json')\n   * if (!result.success) {\n   *   toast.error(result.error)\n   * }\n   */\n  const openWorkflowAction = async (\n    workflow: ComfyWorkflowJSON | null,\n    filename: string\n  ): Promise<{\n    success: boolean\n    error?: string\n  }> => {\n    if (!workflow) {\n      return { success: false, error: 'No workflow data available' }\n    }\n\n    try {\n      const temp = workflowStore.createTemporary(filename, workflow)\n      await workflowService.openWorkflow(temp)\n      return { success: true }\n    } catch (error) {\n      return {\n        success: false,\n        error:\n          error instanceof Error ? error.message : 'Failed to open workflow'\n      }\n    }\n  }\n\n  return {\n    exportWorkflowAction,\n    openWorkflowAction\n  }\n}\n","/**\n * Utilities for extracting workflows from different sources\n * Supports both job-based and asset-based workflow extraction\n */\n\nimport type { ComfyWorkflowJSON } from '@/platform/workflow/validation/schemas/workflowSchema'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { getOutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport { getAssetUrl } from '@/platform/assets/utils/assetUrlUtil'\nimport { getWorkflowDataFromFile } from '@/scripts/metadata/parser'\nimport { getJobApiPrompt, getJobWorkflow } from '@/services/jobOutputCache'\nimport { parseJsonWithNonFinite } from '@/utils/jsonUtil'\n\n/**\n * Extract workflow from AssetItem using jobs API\n * For output assets: uses jobs API (getJobWorkflow)\n * For input assets: extracts from file metadata\n *\n * @param asset The asset item to extract workflow from\n * @returns WorkflowSource with workflow and generated filename\n *\n * @example\n * const asset = { name: 'output.png', user_metadata: { jobId: '123' } }\n * const { workflow, filename } = await extractWorkflowFromAsset(asset)\n */\nexport async function extractWorkflowFromAsset(asset: AssetItem): Promise<{\n  workflow: ComfyWorkflowJSON | null\n  filename: string\n}> {\n  const baseFilename = asset.name.replace(/\\.[^/.]+$/, '.json')\n\n  // For output assets: use jobs API (with caching and validation)\n  const metadata = getOutputAssetMetadata(asset.user_metadata)\n  if (metadata?.jobId) {\n    const workflow = await getJobWorkflow(metadata.jobId)\n    return { workflow: workflow ?? null, filename: baseFilename }\n  }\n\n  // For input assets: extract from file metadata (PNG/WEBP/FLAC with embedded workflow)\n  try {\n    const fileUrl = getAssetUrl(asset)\n    const response = await fetch(fileUrl)\n    if (!response.ok) {\n      return { workflow: null, filename: baseFilename }\n    }\n\n    const blob = await response.blob()\n    const file = new File([blob], asset.name, { type: blob.type })\n\n    const workflowData = await getWorkflowDataFromFile(file)\n    if (workflowData?.workflow) {\n      // Handle both string and object workflow data\n      const workflow =\n        typeof workflowData.workflow === 'string'\n          ? parseJsonWithNonFinite<ComfyWorkflowJSON>(workflowData.workflow)\n          : (workflowData.workflow as ComfyWorkflowJSON)\n\n      return {\n        workflow,\n        filename: baseFilename\n      }\n    }\n  } catch (error) {\n    console.error('Failed to extract workflow from asset:', error)\n  }\n\n  return {\n    workflow: null,\n    filename: baseFilename\n  }\n}\n\n/**\n * Extract the API-format graph stored for an output asset's job\n *\n * Only jobs submitted through the API expose one, so this is the fallback for\n * assets whose job embeds no editor workflow. The graph is returned\n * unvalidated — callers gate it with `app.isApiJson` before loading it.\n *\n * @param asset The asset item to extract the API graph from\n * @returns The stored API-format graph, or undefined when there is none\n */\nexport async function extractApiPromptFromAsset(\n  asset: AssetItem\n): Promise<unknown> {\n  const metadata = getOutputAssetMetadata(asset.user_metadata)\n  if (!metadata?.jobId) return undefined\n\n  return await getJobApiPrompt(metadata.jobId)\n}\n\n/**\n * Check if a file format supports embedded workflow metadata\n * Useful for UI to show/hide workflow-related options\n *\n * @param filename The filename to check\n * @returns true if the format can contain workflow metadata\n *\n * @example\n * supportsWorkflowMetadata('image.png') // true\n * supportsWorkflowMetadata('image.jpg') // false\n */\nexport function supportsWorkflowMetadata(filename: string): boolean {\n  const lower = filename.toLowerCase()\n  return (\n    lower.endsWith('.png') ||\n    lower.endsWith('.webp') ||\n    lower.endsWith('.flac') ||\n    lower.endsWith('.json')\n  )\n}\n","import type {\n  LGraph,\n  LGraphNode,\n  Subgraph\n} from '@/lib/litegraph/src/litegraph'\nimport { collectAllNodes } from '@/utils/graphTraversalUtil'\n\n/**\n * Clear cached Load Image / Load Video preview state on any node whose widget\n * value matches one of the given values. Covers:\n *   - the canvas renderer cache (`node.imgs`, `node.videoContainer`)\n *   - the Vue preview source — must be cleared via `removeOutputsForNode`\n *     so the Pinia reactive ref (`nodeOutputStore.nodeOutputs.value`) updates,\n *     not just the legacy `app.nodeOutputs` mirror\n *\n * Comparison is full-string against the widget value as stored — callers must\n * provide the canonical widget-value variants for each deleted asset (e.g.\n * `foo.png`, `foo.png [output]`, `sub/foo.png [output]`, `<hash>`). This\n * avoids false matches when two distinct assets share a basename across\n * input/output sources.\n *\n * Walks the full graph hierarchy via `collectAllNodes`, so Load Image / Load\n * Video nodes inside subgraphs are also matched.\n *\n * FE-230 — invoked after successful asset deletion so the Load Image / Load\n * Video node preview does not keep displaying a thumbnail for an asset that\n * no longer exists.\n */\nexport function clearNodePreviewCacheForValues(\n  rootGraph: LGraph | Subgraph,\n  deletedValues: ReadonlySet<string>,\n  removeOutputsForNode: (node: LGraphNode) => void\n): void {\n  if (deletedValues.size === 0) return\n  for (const node of findNodesReferencingValues(rootGraph, deletedValues)) {\n    removeOutputsForNode(node)\n    node.imgs = undefined\n    node.videoContainer = undefined\n    node.graph?.setDirtyCanvas(true)\n  }\n}\n\n/**\n * Walk the graph hierarchy and yield each leaf node whose widget value matches\n * one of `deletedValues`. Shared by the preview-clearing and value-clearing\n * paths.\n *\n * Skips subgraph wrapper nodes — only their interior nodes are inspected.\n */\nexport function findNodesReferencingValues(\n  rootGraph: LGraph | Subgraph,\n  deletedValues: ReadonlySet<string>\n): LGraphNode[] {\n  if (deletedValues.size === 0) return []\n  const matches: LGraphNode[] = []\n  for (const node of collectAllNodes(rootGraph)) {\n    if (!node.widgets?.length) continue\n    if (typeof node.isSubgraphNode === 'function' && node.isSubgraphNode())\n      continue\n    const referencesDeleted = node.widgets.some(\n      (w) => typeof w.value === 'string' && deletedValues.has(w.value)\n    )\n    if (referencesDeleted) matches.push(node)\n  }\n  return matches\n}\n","import type { LGraph, Subgraph } from '@/lib/litegraph/src/litegraph'\n\nimport { findNodesReferencingValues } from './clearNodePreviewCacheForValues'\n\n/**\n * Clear widget values that reference deleted assets so the persisted workflow\n * JSON stops claiming the deleted asset is in use.\n *\n * Without this, after `useMediaAssetActions.deleteAssets` succeeds the\n * in-memory preview is cleared (`clearNodePreviewCacheForValues`) but the\n * widget value still points at the deleted asset. On reload the workflow JSON\n * is restored verbatim and `useImageUploadWidget` re-fetches the URL — for\n * output assets the file is still served (history-soft-delete), so the\n * preview re-renders despite the asset being \"deleted\" everywhere else.\n *\n * Mutates `widget.value` (which `LGraphNode.serialize` re-reads to rebuild\n * `widgets_values`) and invokes `widget.callback` so widgets like Load Image\n * run their own change-handling (clearing `node.imgs`, calling\n * `setNodeOutputs`, etc.).\n *\n * FE-230 — covers the post-reload case without re-introducing\n * useMissingMediaPreviewSync, which couldn't distinguish deletion from\n * verification false-positives (e.g. mask-editor saved values).\n */\nexport function clearDeletedAssetWidgetValues(\n  rootGraph: LGraph | Subgraph,\n  deletedValues: ReadonlySet<string>\n): void {\n  if (deletedValues.size === 0) return\n  for (const node of findNodesReferencingValues(rootGraph, deletedValues)) {\n    if (!node.widgets) continue\n    for (const widget of node.widgets) {\n      if (typeof widget.value !== 'string') continue\n      if (!deletedValues.has(widget.value)) continue\n      widget.value = ''\n      widget.callback?.('')\n    }\n    node.graph?.setDirtyCanvas(true)\n  }\n}\n","import type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport { LGraphEventMode } from '@/lib/litegraph/src/types/globalEnums'\nimport { scanNodeMediaCandidates } from '@/platform/missingMedia/missingMediaScan'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport type { MissingMediaCandidate } from '@/platform/missingMedia/types'\nimport { collectAllNodes } from '@/utils/graphTraversalUtil'\n\nimport { findNodesReferencingValues } from './clearNodePreviewCacheForValues'\n\n/**\n * After a successful asset deletion, surface the affected Load Image / Load\n * Video / Load Audio nodes through the missing-media store. Without this, UI\n * surfaces that filter against `missingMediaCandidates` (e.g. the Vue node\n * widget dropdown) keep listing the deleted asset because the verification\n * pipeline only runs on workflow load — there is no signal that the live\n * deletion just invalidated some references.\n *\n * Walks the full graph hierarchy (including subgraphs) and skips bypassed /\n * never-execute nodes, mirroring `scanAllMediaCandidates` so the live-delete\n * path stays in lockstep with the workflow-load verification.\n *\n * Comparison is full-string against the widget value, so two distinct assets\n * that share a basename across input/output sources do not cross-match.\n */\nexport function markDeletedAssetsAsMissingMedia(\n  rootGraph: LGraph,\n  deletedValues: ReadonlySet<string>\n): void {\n  if (deletedValues.size === 0) return\n\n  const matchedNodes = [\n    ...findNodesReferencingValues(rootGraph, deletedValues),\n    ...collectAllNodes(rootGraph).filter(\n      (node) =>\n        typeof node.isSubgraphNode === 'function' &&\n        node.isSubgraphNode() &&\n        Array.isArray(node.widgets) &&\n        node.widgets.some(\n          (widget) =>\n            typeof widget.value === 'string' && deletedValues.has(widget.value)\n        )\n    )\n  ]\n  if (!matchedNodes.length) return\n\n  const candidates: MissingMediaCandidate[] = []\n  for (const node of matchedNodes) {\n    if (\n      node.mode === LGraphEventMode.NEVER ||\n      node.mode === LGraphEventMode.BYPASS\n    )\n      continue\n    for (const candidate of scanNodeMediaCandidates(rootGraph, node)) {\n      if (!deletedValues.has(candidate.name)) continue\n      candidates.push({ ...candidate, isMissing: true })\n    }\n  }\n\n  if (candidates.length) {\n    useMissingMediaStore().addMissingMedia(candidates)\n  }\n}\n","import { getOutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { getAssetType } from '@/platform/assets/utils/assetTypeUtil'\nimport { getOutputKey } from '@/platform/assets/utils/outputKeyUtil'\n\ntype SelectedJobOutputs = {\n  expectedCount: number\n  outputKeys: Set<string>\n}\n\nexport function getAssetOutputCount(\n  asset: Pick<AssetItem, 'user_metadata'>\n): number {\n  const count = asset.user_metadata?.outputCount\n  return typeof count === 'number' && count > 0 ? count : 1\n}\n\n/**\n * Counts the unique outputs a selection stands for.\n *\n * An expanded output stack puts a job-level parent and its children in the\n * same selection. The parent stands for every output of its job\n * (`outputCount`); each child stands for exactly one, and the child set never\n * includes the parent's own output. Summing them counts the job twice, so\n * outputs are grouped by job and each job contributes the larger of its\n * parent's `outputCount` and the number of distinct output identities\n * selected from it — the first covers a job-level selection whose children\n * were never expanded, the second a child-only selection.\n *\n * Assets that are not job outputs, and outputs whose metadata names no job,\n * count once each under their own id.\n */\nexport function getTotalAssetOutputCount(assets: readonly AssetItem[]): number {\n  const individualCounts = new Map<string, number>()\n  const outputsByJobId = new Map<string, SelectedJobOutputs>()\n\n  for (const asset of assets) {\n    const assetType = getAssetType(asset)\n    const isJobOutput = assetType === 'output' || assetType === 'temp'\n    const metadata = isJobOutput\n      ? getOutputAssetMetadata(asset.user_metadata)\n      : null\n\n    if (!metadata) {\n      individualCounts.set(\n        asset.id,\n        isJobOutput ? getAssetOutputCount(asset) : 1\n      )\n      continue\n    }\n\n    let selectedOutputs = outputsByJobId.get(metadata.jobId)\n    if (!selectedOutputs) {\n      selectedOutputs = { expectedCount: 0, outputKeys: new Set<string>() }\n      outputsByJobId.set(metadata.jobId, selectedOutputs)\n    }\n\n    selectedOutputs.expectedCount = Math.max(\n      selectedOutputs.expectedCount,\n      getAssetOutputCount(asset)\n    )\n    selectedOutputs.outputKeys.add(\n      getOutputKey({\n        nodeId: metadata.nodeId,\n        subfolder: metadata.subfolder,\n        filename: asset.name\n      }) ?? `asset:${asset.id}`\n    )\n  }\n\n  let total = 0\n  for (const count of individualCounts.values()) total += count\n  for (const { expectedCount, outputKeys } of outputsByJobId.values()) {\n    total += Math.max(expectedCount, outputKeys.size)\n  }\n  return total\n}\n","/**\n * Utilities for detecting and configuring loader nodes\n * Used by both job menu and media asset actions to determine\n * which loader node type to add to the canvas\n */\n\nimport { getMediaTypeFromFilename } from '@comfyorg/shared-frontend-utils/formatUtil'\n\nimport { isHdrImageFilename } from '@/utils/hdrFormatUtil'\n\n/**\n * Detect loader node type from filename extension\n * Uses shared formatUtil for consistent file type detection across the codebase\n *\n * @param filename The filename to check\n * @returns Object with nodeType and widgetName, or nulls if unsupported\n *\n * @example\n * detectNodeTypeFromFilename('image.png') // { nodeType: 'LoadImage', widgetName: 'image' }\n * detectNodeTypeFromFilename('video.mp4') // { nodeType: 'LoadVideo', widgetName: 'file' }\n * detectNodeTypeFromFilename('audio.mp3') // { nodeType: 'LoadAudio', widgetName: 'audio' }\n */\nexport function detectNodeTypeFromFilename(filename: string): {\n  nodeType: 'LoadImage' | 'LoadVideo' | 'LoadAudio' | null\n  widgetName: 'image' | 'file' | 'audio' | null\n} {\n  if (isHdrImageFilename(filename)) {\n    return { nodeType: 'LoadImage', widgetName: 'image' }\n  }\n  const mediaType = getMediaTypeFromFilename(filename)\n\n  switch (mediaType) {\n    case 'image':\n      return { nodeType: 'LoadImage', widgetName: 'image' }\n    case 'video':\n      return { nodeType: 'LoadVideo', widgetName: 'file' }\n    case 'audio':\n      return { nodeType: 'LoadAudio', widgetName: 'audio' }\n    default:\n      // 3D and other types don't have loader nodes\n      return { nodeType: null, widgetName: null }\n  }\n}\n","import { uniqBy } from 'es-toolkit'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { inject } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { isCloud } from '@/platform/distribution/types'\nimport { withNodeAddSource } from '@/platform/telemetry/nodeAdded/nodeAddSource'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useWorkflowActionsService } from '@/platform/workflow/core/services/workflowActionsService'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport {\n  extractApiPromptFromAsset,\n  extractWorkflowFromAsset\n} from '@/platform/workflow/utils/workflowExtractionUtil'\nimport { api } from '@/scripts/api'\nimport { app } from '@/scripts/app'\nimport { useDialogService } from '@/services/dialogService'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { getOutputAssetMetadata } from '../schemas/assetMetadataSchema'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport {\n  getAssetDisplayName,\n  getAssetStoredFilename\n} from '../utils/assetMetadataUtils'\nimport { getAssetType } from '../utils/assetTypeUtil'\nimport { getAssetFileUrl } from '../utils/assetUrlUtil'\nimport { clearDeletedAssetWidgetValues } from '../utils/clearDeletedAssetWidgetValues'\nimport { clearNodePreviewCacheForValues } from '../utils/clearNodePreviewCacheForValues'\nimport { markDeletedAssetsAsMissingMedia } from '../utils/markDeletedAssetsAsMissingMedia'\nimport { getTotalAssetOutputCount } from '../utils/outputAssetCountUtil'\nimport { resolveOutputAssetItems } from '../utils/outputAssetUtil'\nimport { createAnnotatedPath } from '@/utils/createAnnotatedPath'\nimport { detectNodeTypeFromFilename } from '@/utils/loaderNodeUtil'\nimport { isResultItemType } from '@/utils/typeGuardUtil'\n\nimport type { AssetId, AssetItem } from '../schemas/assetSchema'\nimport { MediaAssetKey } from '../schemas/mediaAssetSchema'\nimport { assetService } from '../services/assetService'\nimport { useAssetDownload } from './useAssetDownload'\nimport { useAssetZipExport } from './useAssetZipExport'\nimport type { AssetDownload } from './useAssetDownload'\n\nconst EXCLUDED_TAGS = new Set(['models', 'input', 'output'])\n\nfunction createAssetWidgetPath(asset: AssetItem): string {\n  const metadata = getOutputAssetMetadata(asset.user_metadata)\n  const assetType = getAssetType(asset, 'input')\n\n  return createAnnotatedPath({\n    filename: getAssetStoredFilename(asset),\n    subfolder: metadata?.subfolder ?? '',\n    type: isResultItemType(assetType) ? assetType : undefined\n  })\n}\n\n/**\n * Canonical widget-value strings that may reference this asset, scoped by the\n * asset's source type so basenames cannot cross-match across input/output.\n *\n * Output assets emit `<name> [output]` (and the subfolder-prefixed form when\n * present in metadata). Input/temp assets emit the bare name plus the explicit\n * annotation. The content `hash` is included whenever present, since\n * cloud-stored assets can be referenced by hash.\n */\nfunction widgetValueVariants(\n  name: string | undefined,\n  type: string | undefined,\n  subfolder?: string,\n  hash?: string\n): string[] {\n  const variants: string[] = []\n  if (name) {\n    if (type === 'output') {\n      const path = subfolder ? `${subfolder}/${name}` : name\n      variants.push(`${path} [output]`)\n    } else if (type === 'temp') {\n      variants.push(`${name} [temp]`)\n    } else {\n      variants.push(name)\n      variants.push(`${name} [input]`)\n    }\n  }\n  if (hash) variants.push(hash)\n  return variants\n}\n\nexport function useMediaAssetActions() {\n  const { t } = useI18n()\n  const toast = useToast()\n  const assetsStore = useAssetsStore()\n  const dialogService = useDialogService()\n  const mediaContext = inject(MediaAssetKey, null)\n  const { copyToClipboard } = useCopyToClipboard()\n  const { flags } = useFeatureFlags()\n  const workflowActions = useWorkflowActionsService()\n  const litegraphService = useLitegraphService()\n  const nodeDefStore = useNodeDefStore()\n  const { downloadFiles } = useAssetDownload()\n  const { startZipExport } = useAssetZipExport()\n\n  /**\n   * Download one or more assets.\n   * When the assets system is enabled, creates a ZIP export via the\n   * backend when called with 2+ assets or with any asset whose job has\n   * `outputCount > 1`.\n   * Otherwise downloads each file directly, expanding grouped assets\n   * (`outputCount > 1`) into their individual outputs.\n   * With no argument, uses the asset from `MediaAssetKey` context.\n   */\n  const downloadAssets = (assets?: AssetItem[]) => {\n    const targetAssets =\n      assets ?? (mediaContext?.asset.value ? [mediaContext.asset.value] : [])\n    if (targetAssets.length === 0) return\n\n    const hasMultiOutputJobs = targetAssets.some((a) => {\n      const count = getOutputAssetMetadata(a.user_metadata)?.outputCount\n      return typeof count === 'number' && count > 1\n    })\n\n    if (\n      flags.assetsEnabled &&\n      (targetAssets.length > 1 || hasMultiOutputJobs)\n    ) {\n      void downloadAssetsAsZip(targetAssets)\n      return\n    }\n\n    if (hasMultiOutputJobs) {\n      void downloadAssetsIndividually(targetAssets)\n      return\n    }\n\n    void downloadFiles(targetAssets.map(createAssetDownload))\n  }\n\n  function createAssetDownload(asset: AssetItem): AssetDownload {\n    const url = getAssetFileUrl(asset)\n    const filename = getAssetDisplayName(asset)\n    if (!isCloud) return { mode: 'direct', url, filename }\n\n    // Required: a bare fetch sends no Authorization header and authenticates by\n    // session cookie, which resolves to the personal workspace — an asset owned\n    // by any other workspace then reads as missing.\n    return {\n      mode: 'fetch',\n      url,\n      filename,\n      fetch: (route) => api.fetchApi(route)\n    }\n  }\n\n  async function expandAssetForDownload(\n    asset: AssetItem\n  ): Promise<AssetItem[]> {\n    const metadata = getOutputAssetMetadata(asset.user_metadata)\n    if (\n      !metadata ||\n      typeof metadata.outputCount !== 'number' ||\n      metadata.outputCount <= 1\n    ) {\n      return [asset]\n    }\n\n    try {\n      const resolved = await resolveOutputAssetItems(metadata, {\n        createdAt: asset.created_at\n      })\n      return resolved.length > 0 ? resolved : [asset]\n    } catch (error) {\n      console.error('Failed to expand grouped asset for download:', error)\n      return [asset]\n    }\n  }\n\n  async function downloadAssetsIndividually(assets: AssetItem[]) {\n    const expanded = await Promise.all(assets.map(expandAssetForDownload))\n    const seenAssetIds = new Set<string>()\n    const filesToDownload = expanded.flat().filter((asset) => {\n      if (seenAssetIds.has(asset.id)) return false\n      seenAssetIds.add(asset.id)\n      return true\n    })\n\n    await downloadFiles(filesToDownload.map(createAssetDownload))\n  }\n\n  async function downloadAssetsAsZip(assets: AssetItem[]) {\n    const jobIds: string[] = []\n    const assetIds: string[] = []\n    const namesByJobId = new Map<string, Set<string>>()\n    const wholeJobIds = new Set<string>()\n\n    for (const asset of assets) {\n      const assetType = getAssetType(asset)\n      const metadata = getOutputAssetMetadata(asset.user_metadata)\n      const jobId = metadata?.jobId\n      if (jobId && (assetType === 'output' || assetType === 'temp')) {\n        if (!jobIds.includes(jobId)) {\n          jobIds.push(jobId)\n        }\n        // When outputCount is set, the asset is a job-level selection\n        // from the gallery and the user wants all outputs for that job.\n        if (metadata.outputCount != null) {\n          wholeJobIds.add(jobId)\n        } else if (asset.name) {\n          const names = namesByJobId.get(jobId) ?? new Set<string>()\n          names.add(asset.name)\n          namesByJobId.set(jobId, names)\n        }\n      } else {\n        assetIds.push(asset.id)\n      }\n    }\n\n    // A job-level selection outranks any name filter a sibling child of the\n    // same job contributed, whichever order they were selected in.\n    const jobAssetNameFilters = Object.fromEntries(\n      [...namesByJobId]\n        .filter(([jobId]) => !wholeJobIds.has(jobId))\n        .map(([jobId, names]): [string, string[]] => [jobId, [...names]])\n    )\n\n    const spansMultipleJobs = jobIds.length > 1\n    const namingStrategy = spansMultipleJobs ? 'group_by_job_time' : 'preserve'\n\n    await startZipExport(\n      {\n        ...(jobIds.length > 0 ? { job_ids: jobIds } : {}),\n        ...(assetIds.length > 0 ? { asset_ids: assetIds } : {}),\n        ...(Object.keys(jobAssetNameFilters).length > 0\n          ? { job_asset_name_filters: jobAssetNameFilters }\n          : {}),\n        naming_strategy: namingStrategy,\n        include_previews: true\n      },\n      getTotalAssetOutputCount(assets)\n    )\n  }\n\n  const copyJobId = async (asset?: AssetItem) => {\n    const targetAsset = asset ?? mediaContext?.asset.value\n    if (!targetAsset) return\n\n    const metadata = getOutputAssetMetadata(targetAsset.user_metadata)\n    const jobId =\n      metadata?.jobId ||\n      (getAssetType(targetAsset) === 'output' ? targetAsset.id : undefined)\n\n    if (!jobId) {\n      toast.warning(t('g.warning'), {\n        description: t('mediaAsset.noJobIdFound'),\n        duration: 2000\n      })\n      return\n    }\n\n    await copyToClipboard(jobId)\n  }\n\n  /**\n   * Add a loader node to the current workflow for this asset\n   * Uses shared utility to detect appropriate node type based on file extension\n   */\n  const addWorkflow = async (asset?: AssetItem) => {\n    const targetAsset = asset ?? mediaContext?.asset.value\n    if (!targetAsset) return\n\n    // Detect node type using shared utility\n    const { nodeType, widgetName } = detectNodeTypeFromFilename(\n      targetAsset.name\n    )\n\n    if (!nodeType || !widgetName) {\n      toast.warning(t('g.warning'), {\n        description: t('mediaAsset.unsupportedFileType'),\n        duration: 2000\n      })\n      return\n    }\n\n    const nodeDef = nodeDefStore.nodeDefsByName[nodeType]\n\n    const node = withNodeAddSource('programmatic', () =>\n      litegraphService.addNodeOnGraph(nodeDef, {\n        pos: litegraphService.getCanvasCenter()\n      })\n    )\n\n    if (!node) {\n      toast.error(t('g.error'), {\n        description: t('mediaAsset.failedToCreateNode')\n      })\n      return\n    }\n\n    const annotated = createAssetWidgetPath(targetAsset)\n\n    const widget = node.widgets?.find((w) => w.name === widgetName)\n    if (widget) {\n      widget.value = annotated\n      widget.callback?.(annotated)\n    }\n    node.graph?.setDirtyCanvas(true, true)\n\n    toast.success(t('g.success'), {\n      description: t('mediaAsset.nodeAddedToWorkflow', { nodeType }),\n      duration: 2000\n    })\n  }\n\n  /**\n   * Open the asset's stored API-format graph as a new workflow, the way the\n   * canvas already does when an API-format JSON file is dropped onto it.\n   *\n   * Layout is invented and groups/reroutes cannot survive API format, so the\n   * result is reopenable rather than faithful. It is only handed to the editor\n   * — nothing is written back to the job or the asset.\n   */\n  const openApiPromptAsWorkflow = async (\n    asset: AssetItem,\n    filename: string\n  ): Promise<{ success: boolean; error?: string }> => {\n    try {\n      const apiPrompt = await extractApiPromptFromAsset(asset)\n      if (!app.isApiJson(apiPrompt)) return { success: false }\n\n      await app.loadApiJson(apiPrompt, filename)\n      return { success: true }\n    } catch (error) {\n      console.error('Failed to open API graph as workflow:', error)\n      reportError(error, {\n        surface: 'assets',\n        errorType: 'asset_api_prompt_open_failure'\n      })\n      return {\n        success: false,\n        error: error instanceof Error ? error.message : undefined\n      }\n    }\n  }\n\n  /**\n   * Open an asset's workflow in a new tab, falling back to the stored API\n   * graph for assets whose job embeds no workflow (API submissions)\n   */\n  const openAssetWorkflow = async (asset: AssetItem) => {\n    const { workflow, filename } = await extractWorkflowFromAsset(asset)\n\n    return workflow\n      ? await workflowActions.openWorkflowAction(workflow, filename)\n      : await openApiPromptAsWorkflow(asset, filename)\n  }\n\n  /**\n   * Open the workflow from this asset in a new tab\n   * Uses shared workflow extraction and action service\n   */\n  const openWorkflow = async (asset?: AssetItem) => {\n    const targetAsset = asset ?? mediaContext?.asset.value\n    if (!targetAsset) return\n\n    const result = await openAssetWorkflow(targetAsset)\n\n    if (!result.success) {\n      toast.warning(t('g.warning'), {\n        description: result.error || t('mediaAsset.noWorkflowDataFound'),\n        duration: 2000\n      })\n    } else {\n      toast.success(t('g.success'), {\n        description: t('mediaAsset.workflowOpenedInNewTab'),\n        duration: 2000\n      })\n    }\n  }\n\n  /**\n   * Export the workflow from this asset as a JSON file\n   * Uses shared workflow extraction and action service\n   */\n  const exportWorkflow = async (asset?: AssetItem) => {\n    const targetAsset = asset ?? mediaContext?.asset.value\n    if (!targetAsset) return\n\n    // Extract workflow using shared utility\n    const { workflow, filename } = await extractWorkflowFromAsset(targetAsset)\n\n    // Use shared action service\n    const result = await workflowActions.exportWorkflowAction(\n      workflow,\n      filename\n    )\n\n    if (result.cancelled) return\n\n    if (!result.success) {\n      const kind = result.error?.includes('No workflow') ? 'warning' : 'error'\n      toast[kind](t(`g.${kind}`), {\n        description: result.error || t('mediaAsset.failedToExportWorkflow'),\n        duration: 3000\n      })\n    } else {\n      toast.success(t('g.success'), {\n        description: t('mediaAsset.workflowExportedSuccessfully'),\n        duration: 2000\n      })\n    }\n  }\n\n  /**\n   * Add multiple assets to the current workflow\n   * Creates loader nodes for each asset\n   */\n  const addMultipleToWorkflow = async (assets: AssetItem[]) => {\n    const NODE_OFFSET = 50\n    let nodeIndex = 0\n    let succeeded = 0\n    let failed = 0\n\n    for (const asset of assets) {\n      const { nodeType, widgetName } = detectNodeTypeFromFilename(asset.name)\n\n      if (!nodeType || !widgetName) {\n        failed++\n        continue\n      }\n\n      const nodeDef = nodeDefStore.nodeDefsByName[nodeType]\n\n      const center = litegraphService.getCanvasCenter()\n      const node = withNodeAddSource('programmatic', () =>\n        litegraphService.addNodeOnGraph(nodeDef, {\n          pos: [\n            center[0] + nodeIndex * NODE_OFFSET,\n            center[1] + nodeIndex * NODE_OFFSET\n          ]\n        })\n      )\n\n      if (!node) {\n        failed++\n        continue\n      }\n\n      const annotated = createAssetWidgetPath(asset)\n\n      const widget = node.widgets?.find((w) => w.name === widgetName)\n      if (widget) {\n        widget.value = annotated\n        widget.callback?.(annotated)\n      }\n      node.graph?.setDirtyCanvas(true, true)\n      succeeded++\n      nodeIndex++\n    }\n\n    if (failed === 0) {\n      toast.success(t('g.success'), {\n        description: t('mediaAsset.selection.nodesAddedToWorkflow', {\n          count: succeeded\n        }),\n        duration: 2000\n      })\n    } else if (succeeded === 0) {\n      toast.error(t('g.error'), {\n        description: t('mediaAsset.selection.failedToAddNodes')\n      })\n    } else {\n      toast.warning(t('g.warning'), {\n        description: t('mediaAsset.selection.partialAddNodesSuccess', {\n          succeeded,\n          failed\n        }),\n        duration: 3000\n      })\n    }\n  }\n\n  /**\n   * Open workflows from multiple assets in new tabs\n   */\n  const openMultipleWorkflows = async (assets: AssetItem[]) => {\n    let succeeded = 0\n    let failed = 0\n\n    for (const asset of assets) {\n      try {\n        const result = await openAssetWorkflow(asset)\n\n        if (result.success) {\n          succeeded++\n        } else {\n          failed++\n        }\n      } catch {\n        failed++\n      }\n    }\n\n    if (failed === 0) {\n      toast.success(t('g.success'), {\n        description: t('mediaAsset.selection.workflowsOpened', {\n          count: succeeded\n        }),\n        duration: 2000\n      })\n    } else if (succeeded === 0) {\n      toast.warning(t('g.warning'), {\n        description: t('mediaAsset.selection.noWorkflowsFound'),\n        duration: 3000\n      })\n    } else {\n      toast.warning(t('g.warning'), {\n        description: t('mediaAsset.selection.partialWorkflowsOpened', {\n          succeeded,\n          failed\n        }),\n        duration: 3000\n      })\n    }\n  }\n\n  /**\n   * Export workflows from multiple assets as JSON files\n   */\n  const exportMultipleWorkflows = async (assets: AssetItem[]) => {\n    let succeeded = 0\n    let failed = 0\n\n    for (const asset of assets) {\n      try {\n        const { workflow, filename } = await extractWorkflowFromAsset(asset)\n        const result = await workflowActions.exportWorkflowAction(\n          workflow,\n          filename\n        )\n\n        if (result.success) {\n          succeeded++\n        } else if (!result.cancelled) {\n          failed++\n        }\n      } catch {\n        failed++\n      }\n    }\n\n    // All cancelled\n    if (succeeded === 0 && failed === 0) return\n\n    if (failed === 0) {\n      toast.success(t('g.success'), {\n        description: t('mediaAsset.selection.workflowsExported', {\n          count: succeeded\n        }),\n        duration: 2000\n      })\n    } else if (succeeded === 0) {\n      toast.warning(t('g.warning'), {\n        description: t('mediaAsset.selection.noWorkflowsToExport'),\n        duration: 3000\n      })\n    } else {\n      toast.warning(t('g.warning'), {\n        description: t('mediaAsset.selection.partialWorkflowsExported', {\n          succeeded,\n          failed\n        }),\n        duration: 3000\n      })\n    }\n  }\n\n  /**\n   * Show confirmation dialog and delete asset(s) if confirmed\n   * @param assets Single asset or array of assets to delete\n   * @returns true if user confirmed and deletion was attempted, false if cancelled\n   */\n  async function deleteAssets(input: AssetItem[] | AssetItem) {\n    const assets = Array.isArray(input) ? input : [input]\n    interface BaseDeleteOperation {\n      kind: string\n      dependents?: DeleteOperation[]\n      markDeletionId?: AssetId\n      name?: string\n    }\n    interface AssetDeletion extends BaseDeleteOperation {\n      kind: 'asset'\n      variants: string[]\n      id: AssetId\n      tags?: string[]\n    }\n    interface JobDeletion extends BaseDeleteOperation {\n      kind: 'job'\n      id: string\n    }\n    type DeleteOperation = AssetDeletion | JobDeletion\n\n    function getDeletionPlan(): DeleteOperation[] {\n      if (!flags.assetsEnabled) {\n        const operations: JobDeletion[] = assets.flatMap((asset) => {\n          const markDeletionId = asset.id\n          const { jobId } = getOutputAssetMetadata(asset.user_metadata) ?? {}\n          if (!jobId) return []\n\n          const name = getAssetDisplayName(asset)\n          return [{ kind: 'job', id: jobId, name, markDeletionId }]\n        })\n        return uniqBy(operations, (op) => op.id)\n      }\n      return assets.flatMap((asset) => {\n        const markDeletionId = asset.id\n        const metadata = getOutputAssetMetadata(asset.user_metadata)\n        const childAssets: AssetDeletion[] = (\n          metadata?.allOutputs ?? []\n        ).flatMap((output) => {\n          if (!output.assetId) return []\n\n          const variants = widgetValueVariants(\n            output.filename,\n            output.type,\n            output.subfolder\n          )\n          return {\n            kind: 'asset',\n            markDeletionId,\n            name: output.display_name || output.filename,\n            id: output.assetId,\n            tags: asset.tags,\n            variants\n          }\n        })\n        if (childAssets.length > 0) return childAssets\n\n        const variants = widgetValueVariants(\n          asset.name,\n          getAssetType(asset, 'input'),\n          metadata?.subfolder,\n          asset.hash\n        )\n        return [\n          {\n            kind: 'asset',\n            id: asset.id,\n            markDeletionId,\n            name: getAssetDisplayName(asset),\n            tags: asset.tags,\n            variants\n          }\n        ]\n      })\n    }\n\n    function getNames(operation: DeleteOperation): string[] {\n      return [\n        ...(operation.name ? [operation.name] : []),\n        ...(operation.dependents ? operation.dependents.flatMap(getNames) : [])\n      ]\n    }\n    function getOperationCount(\n      kind: string,\n      operation: DeleteOperation[]\n    ): number {\n      return operation.reduce((tally, op) => {\n        const selfCount = op.kind === kind ? 1 : 0\n        const dependents = getOperationCount(kind, op.dependents ?? [])\n        return tally + selfCount + dependents\n      }, 0)\n    }\n\n    const deletedVariants = new Set<string>()\n    const invalidatedModelTags = new Set<string>()\n\n    let deletedAssetCount = 0\n    async function deleteAsset(operation: AssetDeletion) {\n      await assetService.deleteAsset(operation.id)\n      deletedAssetCount++\n      for (const variant of operation.variants) deletedVariants.add(variant)\n      for (const tag of operation.tags ?? []) {\n        if (!EXCLUDED_TAGS.has(tag) && assetsStore.hasCategory(tag))\n          invalidatedModelTags.add(tag)\n      }\n      void assetsStore.inputAssets.invalidate([operation.id])\n    }\n    let deletedJobCount = 0\n    async function deleteJob(operation: JobDeletion) {\n      await api.deleteItem('history', operation.id)\n      deletedJobCount++\n    }\n    async function performDelete(\n      operation: DeleteOperation\n    ): Promise<unknown[]> {\n      if (operation.markDeletionId)\n        assetsStore.setAssetDeleting(operation.markDeletionId, true)\n      try {\n        if (operation.dependents) {\n          const failedDependents = (\n            await Promise.all(operation.dependents.map(performDelete))\n          ).flat()\n          if (failedDependents.length) return failedDependents\n        }\n\n        try {\n          if (operation.kind === 'asset') await deleteAsset(operation)\n          else await deleteJob(operation)\n        } catch (err) {\n          return [err]\n        }\n      } finally {\n        if (operation.markDeletionId)\n          assetsStore.setAssetDeleting(operation.markDeletionId, false)\n      }\n\n      return []\n    }\n\n    const deletionPlan = getDeletionPlan()\n    if (!deletionPlan.length) return false\n\n    const plannedAssetCount = getOperationCount('asset', deletionPlan)\n    const plannedJobCount = getOperationCount('job', deletionPlan)\n    const deleteConfirmed = await dialogService.confirm({\n      title: t('mediaAsset.deleteItems'),\n      type: 'delete',\n      message: !plannedAssetCount\n        ? t('mediaAsset.deleteHistoryOnly')\n        : flags.assetDeletionEnabled\n          ? t('mediaAsset.deletePermanent')\n          : t('mediaAsset.deleteTombstone'),\n      itemList: deletionPlan.flatMap(getNames)\n    })\n    if (!deleteConfirmed) return false\n\n    const failedDeletions = (\n      await Promise.all(deletionPlan.map(performDelete))\n    ).flat()\n\n    const rootGraph = app.rootGraph\n    if (deletedVariants.size) {\n      const nodeOutputStore = useNodeOutputStore()\n      // Order matters: mark + cache-clear both look up nodes by\n      // current widget.value, so they must run before\n      // clearDeletedAssetWidgetValues blanks those values.\n      markDeletedAssetsAsMissingMedia(rootGraph, deletedVariants)\n      clearNodePreviewCacheForValues(rootGraph, deletedVariants, (node) =>\n        nodeOutputStore.removeNodeOutputsForNode(node)\n      )\n      clearDeletedAssetWidgetValues(rootGraph, deletedVariants)\n      useWorkflowStore().activeWorkflow?.changeTracker.captureCanvasState()\n    }\n\n    for (const category of invalidatedModelTags)\n      assetsStore.invalidateModelsForCategory(category)\n\n    if (!flags.assetsEnabled) {\n      const hasOutputAssets = assets.some((a) => {\n        const type = getAssetType(a)\n        return type === 'output' || type === 'temp'\n      })\n      const hasInputAssets = assets.some((a) => getAssetType(a) === 'input')\n\n      if (hasOutputAssets) {\n        await assetsStore.outputAssets.invalidate()\n      }\n      if (hasInputAssets) {\n        await assetsStore.inputAssets.invalidate()\n      }\n    }\n\n    const outcome =\n      failedDeletions.length === 0\n        ? 'success'\n        : deletedJobCount || deletedAssetCount\n          ? 'warning'\n          : 'error'\n\n    const resultMessages: string[] = []\n    if (plannedAssetCount) {\n      resultMessages.push(\n        t(\n          'mediaAsset.assetsDeleted',\n          { total: plannedAssetCount },\n          deletedAssetCount\n        )\n      )\n    }\n    if (plannedJobCount) {\n      resultMessages.push(\n        t('mediaAsset.jobsDeleted', { total: plannedJobCount }, deletedJobCount)\n      )\n    }\n\n    toast[outcome](t(`mediaAsset.assetDelete.${outcome}`), {\n      description: resultMessages.join('\\n'),\n      duration: outcome === 'success' ? 2000 : 5000\n    })\n    return true\n  }\n\n  return {\n    downloadAssets,\n    deleteAssets,\n    copyJobId,\n    addWorkflow,\n    addMultipleToWorkflow,\n    openWorkflow,\n    openMultipleWorkflows,\n    exportWorkflow,\n    exportMultipleWorkflows\n  }\n}\n","<template>\n  <p\n    class=\"m-0 line-clamp-2 text-sm/tight break-all text-base-foreground\"\n    :title=\"fileName\"\n  >\n    {{ fileName }}\n  </p>\n</template>\n\n<script setup lang=\"ts\">\ndefineProps<{\n  fileName: string\n}>()\n</script>\n","<template>\n  <!--\n    Root @click.stop keeps clicks outside the explicit selection regions from\n    reaching the panel's empty-space deselection handler.\n  -->\n  <div\n    :class=\"\n      cn(\n        'flex cursor-pointer flex-col overflow-hidden rounded-lg p-2 transition-colors duration-200',\n        'group gap-2 select-none',\n        selected\n          ? 'ring-3 ring-modal-card-border-highlighted ring-inset'\n          : 'hover:bg-modal-card-background-hovered/20'\n      )\n    \"\n    :data-selected=\"selected\"\n    :data-asset-id=\"asset?.id\"\n    :draggable=\"true\"\n    @click.stop\n    @contextmenu.prevent.stop=\"handleContextMenu\"\n    @dragstart=\"dragStart\"\n  >\n    <!-- Top Area: Media Preview -->\n    <div\n      class=\"relative aspect-square overflow-hidden p-0\"\n      @click.stop=\"handlePreviewClick\"\n      @dblclick.stop=\"(fileKind === 'image' || isHdr) && handleZoomClick()\"\n    >\n      <!-- Loading State -->\n      <div\n        v-if=\"loading\"\n        class=\"size-full animate-pulse rounded-lg bg-modal-card-placeholder-background\"\n      />\n\n      <!-- Content based on asset type -->\n      <component\n        :is=\"getTopComponent(previewKind)\"\n        v-else-if=\"asset && adaptedAsset\"\n        :asset=\"adaptedAsset\"\n        :context=\"{ type: assetType }\"\n        :show-native-controls=\"\n          fileKind === 'video' ? showNativeVideoControls : undefined\n        \"\n        class=\"absolute inset-0\"\n        @download=\"handleDownload\"\n        @image-loaded=\"handleImageLoaded\"\n      />\n\n      <LoadingOverlay :loading=\"isDeleting\">\n        <i class=\"icon-[lucide--trash-2] size-5\" />\n      </LoadingOverlay>\n\n      <Button\n        v-if=\"asset && !loading && !isDeleting\"\n        variant=\"overlay-white\"\n        size=\"icon\"\n        :class=\"\n          cn(\n            'pointer-events-none absolute top-2 left-2 z-1 size-6 rounded-full opacity-0 transition-opacity',\n            'group-hover:pointer-events-auto group-hover:opacity-100',\n            'focus-visible:pointer-events-auto focus-visible:opacity-100',\n            !selected &&\n              'bg-transparent text-white shadow-sm ring-2 ring-white ring-inset hover:bg-white/20'\n          )\n        \"\n        :aria-label=\"\n          $t('assetBrowser.ariaLabel.assetCard', {\n            name: getAssetDisplayName(asset),\n            type: fileKind\n          })\n        \"\n        :aria-pressed=\"selected ?? false\"\n        @click.stop=\"emit('toggle-selection')\"\n      >\n        <i\n          aria-hidden=\"true\"\n          :class=\"\n            cn('icon-[lucide--check] size-4 shrink-0', !selected && 'opacity-0')\n          \"\n        />\n      </Button>\n\n      <!-- Action buttons overlay (top-right) -->\n      <div\n        v-if=\"asset && !loading && !isDeleting\"\n        :class=\"\n          cn(\n            'absolute top-2 right-2 z-1 flex flex-wrap justify-end gap-2',\n            'pointer-events-none opacity-0 transition-opacity',\n            'group-hover:pointer-events-auto group-hover:opacity-100',\n            'group-has-focus-visible:pointer-events-auto group-has-focus-visible:opacity-100',\n            'touch:pointer-events-auto touch:opacity-100'\n          )\n        \"\n      >\n        <IconGroup background-class=\"bg-white\">\n          <Button\n            variant=\"overlay-white\"\n            size=\"icon\"\n            :aria-label=\"$t('mediaAsset.actions.download')\"\n            @click.stop=\"handleDownload\"\n          >\n            <i class=\"icon-[lucide--download] size-4\" />\n          </Button>\n          <Button\n            variant=\"overlay-white\"\n            size=\"icon\"\n            :aria-label=\"$t('mediaAsset.actions.moreOptions')\"\n            @click.stop=\"handleContextMenu\"\n          >\n            <i class=\"icon-[lucide--ellipsis] size-4\" />\n          </Button>\n        </IconGroup>\n      </div>\n    </div>\n\n    <!-- Bottom Area: Media Info -->\n    <div class=\"flex-1\">\n      <!-- Loading State -->\n      <div v-if=\"loading\" class=\"flex items-start justify-between\">\n        <div class=\"flex flex-col gap-1\">\n          <div\n            class=\"h-4 w-24 animate-pulse rounded-sm bg-modal-card-background\"\n          />\n          <div\n            class=\"h-3 w-20 animate-pulse rounded-sm bg-modal-card-background\"\n          />\n        </div>\n        <div\n          class=\"h-6 w-12 animate-pulse rounded-sm bg-modal-card-background\"\n        />\n      </div>\n\n      <!-- Content -->\n      <div\n        v-else-if=\"asset && adaptedAsset\"\n        class=\"flex items-end justify-between gap-1.5\"\n        @click.stop=\"emit('select')\"\n      >\n        <div class=\"flex min-w-0 flex-col gap-1\">\n          <MediaTitle :file-name=\"fileName\" />\n          <div class=\"flex items-center gap-1.5 text-xs text-muted-foreground\">\n            <span v-if=\"formattedDuration\">{{ formattedDuration }}</span>\n            <span v-if=\"metaInfo\">{{ metaInfo }}</span>\n          </div>\n        </div>\n        <div v-if=\"showOutputCount\" class=\"shrink-0\">\n          <Button\n            :tooltip=\"$t('mediaAsset.actions.seeMoreOutputs')\"\n            :aria-label=\"$t('mediaAsset.actions.seeMoreOutputs')\"\n            variant=\"secondary\"\n            @click.stop=\"handleOutputCountClick\"\n          >\n            <i class=\"icon-[lucide--layers] size-4\" />\n            <span>{{ outputCount }}</span>\n          </Button>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { computed, defineAsyncComponent, provide, ref, toRef } from 'vue'\n\nimport IconGroup from '@/components/button/IconGroup.vue'\nimport LoadingOverlay from '@/components/common/LoadingOverlay.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport {\n  formatDuration,\n  formatSize,\n  getFilenameDetails,\n  getMediaTypeFromFilename,\n  isPreviewableMediaType\n} from '@/utils/formatUtil'\nimport { isHdrImageFilename } from '@/utils/hdrFormatUtil'\n\nimport { getAssetType } from '../composables/media/assetMappers'\nimport { startAssetDrag } from '../utils/assetDragUtil'\nimport { getAssetFileUrl, getAssetUrl } from '../utils/assetUrlUtil'\nimport { useMediaAssetActions } from '../composables/useMediaAssetActions'\nimport type { AssetItem } from '../schemas/assetSchema'\nimport {\n  getAssetDisplayName,\n  resolveDisplayImageDimensions\n} from '../utils/assetMetadataUtils'\nimport type { MediaKind } from '../schemas/mediaAssetSchema'\nimport { MediaAssetKey } from '../schemas/mediaAssetSchema'\nimport MediaTitle from './MediaTitle.vue'\n\ntype PreviewKind = ReturnType<typeof getMediaTypeFromFilename>\n\nconst mediaComponents = {\n  top: {\n    video: defineAsyncComponent(() => import('./MediaVideoTop.vue')),\n    audio: defineAsyncComponent(() => import('./MediaAudioTop.vue')),\n    image: defineAsyncComponent(() => import('./MediaImageTop.vue')),\n    '3D': defineAsyncComponent(() => import('./Media3DTop.vue')),\n    text: defineAsyncComponent(() => import('./MediaTextTop.vue')),\n    other: defineAsyncComponent(() => import('./MediaOtherTop.vue'))\n  }\n}\n\nfunction getTopComponent(kind: PreviewKind) {\n  return mediaComponents.top[kind] || mediaComponents.top.other\n}\n\nconst {\n  asset,\n  loading,\n  selected,\n  showOutputCount,\n  outputCount,\n  showNativeVideoControls = true\n} = defineProps<{\n  asset?: AssetItem\n  loading?: boolean\n  selected?: boolean\n  showOutputCount?: boolean\n  outputCount?: number\n  showNativeVideoControls?: boolean\n}>()\n\nconst assetsStore = useAssetsStore()\n\n// Get deletion state from store\nconst isDeleting = computed(() =>\n  asset ? assetsStore.isAssetDeleting(asset.id) : false\n)\n\nconst emit = defineEmits<{\n  // Image and info clicks use the standard selection rules.\n  select: []\n  // The selection control toggles only this asset in the current selection.\n  'toggle-selection': []\n  zoom: [asset: AssetItem]\n  'output-count-click': []\n  'context-menu': [event: MouseEvent, asset: AssetItem]\n}>()\n\n// Store actual image dimensions\nconst imageDimensions = ref<{ width: number; height: number } | undefined>()\n\nconst actions = useMediaAssetActions()\n\n// Get asset type from tags\nconst assetType = computed(() => {\n  return getAssetType(asset?.tags)\n})\n\n// Determine file type from extension\nconst fileKind = computed((): MediaKind => {\n  return getMediaTypeFromFilename(asset?.name || '')\n})\n\nconst isHdr = computed(() => isHdrImageFilename(asset?.name))\n\nconst previewKind = computed((): PreviewKind => {\n  if (asset?.preview_url && isHdr.value) return 'image'\n  return getMediaTypeFromFilename(asset?.name || '')\n})\n\nconst canInspect = computed(\n  () => isPreviewableMediaType(fileKind.value) || isHdr.value\n)\n\n// Get filename without extension\nconst fileName = computed(() => {\n  return getFilenameDetails(asset ? getAssetDisplayName(asset) : '').filename\n})\n\n// Adapt AssetItem to legacy AssetMeta format for existing components\nconst adaptedAsset = computed(() => {\n  if (!asset) return undefined\n  return {\n    id: asset.id,\n    name: asset.name,\n    display_name: asset.display_name,\n    kind: fileKind.value,\n    src:\n      fileKind.value === '3D'\n        ? getAssetUrl(asset)\n        : asset.thumbnail_url ||\n          asset.preview_url ||\n          (fileKind.value === 'video' || fileKind.value === 'audio'\n            ? getAssetFileUrl(asset, { disposition: 'inline' })\n            : ''),\n    preview_url: asset.preview_url,\n    preview_id: asset.preview_id,\n    size: asset.size,\n    tags: asset.tags || [],\n    created_at: asset.created_at,\n    updated_at: asset.updated_at,\n    duration: asset.user_metadata?.duration\n      ? Number(asset.user_metadata.duration)\n      : undefined,\n    dimensions: imageDimensions.value\n  }\n})\n\nprovide(MediaAssetKey, {\n  asset: toRef(() => adaptedAsset.value),\n  context: toRef(() => ({ type: assetType.value }))\n})\n\nconst formattedDuration = computed(() => {\n  // Check for execution time first (from history API)\n  const executionTime = asset?.user_metadata?.executionTimeInSeconds\n  if (executionTime !== undefined && executionTime !== null) {\n    return `${Number(executionTime).toFixed(2)}s`\n  }\n\n  // Fall back to duration for media files\n  const duration = asset?.user_metadata?.duration\n  if (!duration) return ''\n  return formatDuration(Number(duration))\n})\n\nconst displayImageDimensions = computed(() =>\n  resolveDisplayImageDimensions(asset, imageDimensions.value)\n)\n\nconst format = computed(() => {\n  const suffix = getFilenameDetails(asset?.name ?? '').suffix\n  return suffix ? suffix.toUpperCase() : ''\n})\n\nconst metaInfo = computed(() => {\n  if (!asset) return ''\n  const parts: string[] = []\n  if (format.value) parts.push(format.value)\n\n  if (fileKind.value === 'image' && displayImageDimensions.value) {\n    parts.push(\n      `${displayImageDimensions.value.width}x${displayImageDimensions.value.height}`\n    )\n  } else if (asset.size && ['video', 'audio', '3D'].includes(fileKind.value)) {\n    parts.push(formatSize(asset.size))\n  }\n\n  return parts.join(' ')\n})\n\nfunction handlePreviewClick(event: MouseEvent) {\n  const hasSelectionModifier = event.shiftKey || event.metaKey || event.ctrlKey\n  if (fileKind.value === 'video' && !hasSelectionModifier) return\n  emit('select')\n}\n\nconst handleZoomClick = () => {\n  if (asset && canInspect.value) {\n    emit('zoom', asset)\n  }\n}\n\nconst handleImageLoaded = (width: number, height: number) => {\n  imageDimensions.value = { width, height }\n}\n\nconst handleOutputCountClick = () => {\n  emit('output-count-click')\n}\n\nfunction handleContextMenu(event: MouseEvent) {\n  if (!asset) return\n  emit('context-menu', event, asset)\n}\n\nfunction handleDownload() {\n  if (!asset) return\n  actions.downloadAssets([asset])\n}\n\nfunction dragStart(e: DragEvent) {\n  startAssetDrag(e, asset)\n}\n</script>\n","export const MEDIA_ASSET_GRID_MODE = {\n  gridSmall: 'grid-small',\n  grid: 'grid'\n} as const\n\nexport const MEDIA_ASSET_VIEW_MODE = {\n  list: 'list',\n  ...MEDIA_ASSET_GRID_MODE\n} as const\n\n// TODO: Introduce a shared ValueOf<T> for object-value unions across the codebase.\nexport type MediaAssetGridMode =\n  (typeof MEDIA_ASSET_GRID_MODE)[keyof typeof MEDIA_ASSET_GRID_MODE]\n\nexport type MediaAssetViewMode =\n  (typeof MEDIA_ASSET_VIEW_MODE)[keyof typeof MEDIA_ASSET_VIEW_MODE]\n\nexport function getMediaAssetGridColumns(mode: MediaAssetGridMode): string {\n  const minWidth = mode === MEDIA_ASSET_GRID_MODE.gridSmall ? 128 : 240\n  return `repeat(auto-fill, minmax(min(${minWidth}px, 30vw), 1fr))`\n}\n","<template>\n  <div class=\"flex h-full flex-col\">\n    <!-- Assets Grid -->\n    <VirtualGrid\n      class=\"flex-1\"\n      :items=\"assetItems\"\n      :grid-style\n      :on-load-more\n      :can-load-more\n    >\n      <template #item=\"{ item }\">\n        <MediaAssetCard\n          :asset=\"item.asset\"\n          :selected=\"isSelected(item.asset.id)\"\n          :show-output-count=\"showOutputCount(item.asset)\"\n          :output-count=\"getOutputCount(item.asset)\"\n          :show-native-video-controls=\"\n            gridMode !== MEDIA_ASSET_GRID_MODE.gridSmall\n          \"\n          @select=\"emit('select-asset', item.asset)\"\n          @toggle-selection=\"emit('toggle-asset-selection', item.asset)\"\n          @context-menu=\"emit('context-menu', $event, item.asset)\"\n          @zoom=\"emit('zoom', item.asset)\"\n          @output-count-click=\"emit('output-count-click', item.asset)\"\n        />\n      </template>\n    </VirtualGrid>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport VirtualGrid from '@/components/common/VirtualGrid.vue'\nimport MediaAssetCard from '@/platform/assets/components/MediaAssetCard.vue'\nimport {\n  getMediaAssetGridColumns,\n  MEDIA_ASSET_GRID_MODE\n} from '@/platform/assets/components/mediaAssetViewOptions'\nimport type { MediaAssetGridMode } from '@/platform/assets/components/mediaAssetViewOptions'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\n\nconst { assets, isSelected, showOutputCount, getOutputCount, gridMode } =\n  defineProps<{\n    assets: AssetItem[]\n    isSelected: (assetId: string) => boolean\n    showOutputCount: (asset: AssetItem) => boolean\n    getOutputCount: (asset: AssetItem) => number\n    gridMode: MediaAssetGridMode\n    onLoadMore?: () => unknown\n    canLoadMore?: boolean\n  }>()\n\nconst emit = defineEmits<{\n  (e: 'select-asset', asset: AssetItem): void\n  (e: 'toggle-asset-selection', asset: AssetItem): void\n  (e: 'context-menu', event: MouseEvent, asset: AssetItem): void\n  (e: 'zoom', asset: AssetItem): void\n  (e: 'output-count-click', asset: AssetItem): void\n}>()\n\ntype AssetGridItem = { key: string; asset: AssetItem }\n\nconst assetItems = computed<AssetGridItem[]>(() =>\n  assets.map((asset) => ({\n    key: `asset-${asset.id}`,\n    asset\n  }))\n)\n\nconst gridStyle = computed(() => ({\n  display: 'grid',\n  gridTemplateColumns: getMediaAssetGridColumns(gridMode),\n  padding: '0 0.5rem',\n  gap: '0.5rem'\n}))\n</script>\n","<template>\n  <div class=\"flex h-full flex-col\">\n    <VirtualGrid\n      class=\"flex-1\"\n      :items=\"assetItems\"\n      :grid-style=\"listGridStyle\"\n      :max-columns=\"1\"\n      :default-item-height=\"48\"\n      :on-load-more\n      :can-load-more\n    >\n      <template #item=\"{ item }\">\n        <div class=\"relative\">\n          <LoadingOverlay\n            :loading=\"assetsStore.isAssetDeleting(item.asset.id)\"\n            size=\"sm\"\n          >\n            <i class=\"pi pi-trash text-xs\" />\n          </LoadingOverlay>\n          <AssetsListItem\n            role=\"button\"\n            tabindex=\"0\"\n            :aria-label=\"\n              t('assetBrowser.ariaLabel.assetCard', {\n                name: getAssetDisplayName(item.asset),\n                type: getAssetMediaType(item.asset)\n              })\n            \"\n            :class=\"\n              cn(\n                getAssetCardClass(isSelected(item.asset.id)),\n                item.isChild && 'pl-6'\n              )\n            \"\n            :preview-url=\"getAssetPreviewUrl(item.asset)\"\n            :preview-alt=\"getAssetDisplayName(item.asset)\"\n            :icon-name=\"iconForMediaType(getAssetMediaType(item.asset))\"\n            :is-video-preview=\"isVideoAsset(item.asset)\"\n            :primary-text=\"getAssetPrimaryText(item.asset)\"\n            :secondary-text=\"getAssetSecondaryText(item.asset)\"\n            :stack-count=\"getStackCount(item.asset)\"\n            :stack-indicator-label=\"t('mediaAsset.actions.seeMoreOutputs')\"\n            :stack-expanded=\"isStackExpanded(item.asset)\"\n            :draggable=\"true\"\n            @dragstart=\"startAssetDrag($event, item.asset)\"\n            @mouseenter=\"onAssetEnter(item.asset.id)\"\n            @mouseleave=\"onAssetLeave(item.asset.id)\"\n            @contextmenu.prevent.stop=\"emit('context-menu', $event, item.asset)\"\n            @click.stop=\"emit('select-asset', item.asset, selectableAssets)\"\n            @dblclick.stop=\"emit('preview-asset', item.asset)\"\n            @preview-click=\"emit('preview-asset', item.asset)\"\n            @stack-toggle=\"void toggleStack(item.asset)\"\n          >\n            <template v-if=\"hoveredAssetId === item.asset.id\" #actions>\n              <Button\n                variant=\"secondary\"\n                size=\"icon\"\n                :aria-label=\"t('mediaAsset.actions.moreOptions')\"\n                @click.stop=\"emit('context-menu', $event, item.asset)\"\n              >\n                <i class=\"icon-[lucide--ellipsis] size-4\" />\n              </Button>\n            </template>\n          </AssetsListItem>\n        </div>\n      </template>\n    </VirtualGrid>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport LoadingOverlay from '@/components/common/LoadingOverlay.vue'\nimport VirtualGrid from '@/components/common/VirtualGrid.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport AssetsListItem from '@/platform/assets/components/AssetsListItem.vue'\nimport type { OutputStackListItem } from '@/platform/assets/composables/useOutputStacks'\nimport { getOutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { startAssetDrag } from '@/platform/assets/utils/assetDragUtil'\nimport { getAssetDisplayName } from '@/platform/assets/utils/assetMetadataUtils'\nimport { iconForMediaType } from '@/platform/assets/utils/mediaIconUtil'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport {\n  formatDuration,\n  formatSize,\n  getMediaTypeFromFilename,\n  truncateFilename\n} from '@/utils/formatUtil'\nimport { hdrPreviewAssetUrl, isHdrImageFilename } from '@/utils/hdrFormatUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  assetItems,\n  selectableAssets,\n  isSelected,\n  isStackExpanded,\n  toggleStack\n} = defineProps<{\n  assetItems: OutputStackListItem[]\n  selectableAssets: AssetItem[]\n  isSelected: (assetId: string) => boolean\n  isStackExpanded: (asset: AssetItem) => boolean\n  toggleStack: (asset: AssetItem) => Promise<void>\n  onLoadMore?: () => unknown\n  canLoadMore?: boolean\n}>()\n\nconst assetsStore = useAssetsStore()\n\nconst emit = defineEmits<{\n  (e: 'select-asset', asset: AssetItem, assets?: AssetItem[]): void\n  (e: 'preview-asset', asset: AssetItem): void\n  (e: 'context-menu', event: MouseEvent, asset: AssetItem): void\n}>()\n\nconst { t } = useI18n()\nconst hoveredAssetId = ref<string | null>(null)\n\nconst listGridStyle = {\n  display: 'grid',\n  gridTemplateColumns: 'minmax(0, 1fr)',\n  padding: '0 0.5rem',\n  gap: '0.5rem'\n}\n\nfunction getAssetPrimaryText(asset: AssetItem): string {\n  return truncateFilename(getAssetDisplayName(asset))\n}\n\nfunction getAssetMediaType(asset: AssetItem) {\n  return getMediaTypeFromFilename(asset.name)\n}\n\nfunction isVideoAsset(asset: AssetItem): boolean {\n  return getAssetMediaType(asset) === 'video'\n}\n\nfunction getAssetPreviewUrl(asset: AssetItem): string {\n  const mediaType = getAssetMediaType(asset)\n  if (asset.preview_id && isHdrImageFilename(asset.name))\n    return hdrPreviewAssetUrl(asset.preview_id)\n  if (mediaType === 'image' || mediaType === 'video') {\n    return asset.preview_url || ''\n  }\n  return ''\n}\n\nfunction getAssetSecondaryText(asset: AssetItem): string {\n  const metadata = getOutputAssetMetadata(asset.user_metadata)\n  if (typeof metadata?.executionTimeInSeconds === 'number') {\n    return `${metadata.executionTimeInSeconds.toFixed(2)}s`\n  }\n\n  const duration = asset.user_metadata?.duration\n  if (typeof duration === 'number') {\n    return formatDuration(duration)\n  }\n\n  if (typeof asset.size === 'number') {\n    return formatSize(asset.size)\n  }\n\n  return ''\n}\n\nfunction getStackCount(asset: AssetItem): number | undefined {\n  const metadata = getOutputAssetMetadata(asset.user_metadata)\n  if (typeof metadata?.outputCount === 'number') {\n    return metadata.outputCount\n  }\n\n  if (Array.isArray(metadata?.allOutputs)) {\n    return metadata.allOutputs.length\n  }\n\n  return undefined\n}\n\nfunction getAssetCardClass(selected: boolean): string {\n  return cn(\n    'w-full text-text-primary transition-colors hover:bg-secondary-background-hover',\n    'cursor-pointer',\n    selected &&\n      'bg-secondary-background-hover ring-1 ring-modal-card-border-highlighted ring-inset'\n  )\n}\n\nfunction onAssetEnter(assetId: string) {\n  hoveredAssetId.value = assetId\n}\n\nfunction onAssetLeave(assetId: string) {\n  if (hoveredAssetId.value === assetId) {\n    hoveredAssetId.value = null\n  }\n}\n</script>\n","<template>\n  <Button\n    :tooltip=\"$t('sideToolbar.closeSidebar')\"\n    tooltip-side=\"bottom\"\n    variant=\"muted-textonly\"\n    size=\"icon\"\n    class=\"shrink-0\"\n    data-testid=\"sidebar-close-button\"\n    :aria-label=\"$t('sideToolbar.closeSidebar')\"\n    @click=\"sidebarTabStore.activeSidebarTabId = null\"\n  >\n    <i class=\"icon-[lucide--x] size-4\" />\n  </Button>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\n\nconst sidebarTabStore = useSidebarTabStore()\n</script>\n","<template>\n  <div\n    :class=\"\n      cn(\n        'comfy-vue-side-bar-container group/sidebar-tab flex size-full flex-col',\n        className\n      )\n    \"\n  >\n    <div class=\"comfy-vue-side-bar-header flex flex-col\">\n      <div\n        class=\"flex min-h-16 items-center justify-between border-b border-interface-stroke bg-transparent px-4\"\n      >\n        <div class=\"flex min-w-0 flex-1 items-center overflow-hidden\">\n          <span class=\"truncate font-bold\" :title=\"title\">\n            {{ title }}\n          </span>\n          <slot name=\"alt-title\" />\n        </div>\n        <div class=\"flex items-center gap-2\">\n          <div\n            class=\"flex flex-row gap-2 overflow-hidden transition-all duration-200 has-aria-expanded:w-auto has-aria-expanded:opacity-100 motion-safe:w-0 motion-safe:opacity-0 motion-safe:group-focus-within/sidebar-tab:w-auto motion-safe:group-focus-within/sidebar-tab:opacity-100 motion-safe:group-hover/sidebar-tab:w-auto motion-safe:group-hover/sidebar-tab:opacity-100 touch:w-auto touch:opacity-100 [&_.p-button]:py-1 2xl:[&_.p-button]:py-2\"\n          >\n            <slot name=\"tool-buttons\" />\n          </div>\n          <SidebarTabCloseButton v-if=\"closable\" />\n        </div>\n      </div>\n      <slot name=\"header\" />\n    </div>\n    <div\n      class=\"comfy-vue-side-bar-body scrollbar-custom h-0 grow overflow-x-hidden\"\n    >\n      <slot name=\"body\" />\n    </div>\n    <slot name=\"footer\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport SidebarTabCloseButton from '@/components/sidebar/tabs/SidebarTabCloseButton.vue'\n\nconst {\n  title,\n  class: className,\n  closable = true\n} = defineProps<{\n  title: string\n  class?: string\n  closable?: boolean\n}>()\n</script>\n","<template>\n  <div class=\"flex items-center gap-2 px-4 py-2\">\n    <div class=\"min-w-0 flex-1\">\n      <slot />\n    </div>\n    <div v-if=\"$slots.actions\" class=\"flex shrink-0 items-center gap-2\">\n      <slot name=\"actions\" />\n    </div>\n  </div>\n</template>\n","export type MediaAssetDateFilter = '' | 'today' | 'week' | 'month' | 'year'\n\ninterface FilterOption<T extends string> {\n  value: T\n  label: string\n}\n\nexport const mediaTypeFilterOptions: FilterOption<string>[] = [\n  { value: 'image', label: 'sideToolbar.mediaAssets.filterImage' },\n  { value: 'video', label: 'sideToolbar.mediaAssets.filterVideo' },\n  { value: 'audio', label: 'sideToolbar.mediaAssets.filterAudio' },\n  { value: '3d', label: 'sideToolbar.mediaAssets.filter3D' },\n  { value: 'text', label: 'sideToolbar.mediaAssets.filterText' }\n]\n\nexport const dateFilterOptions: FilterOption<MediaAssetDateFilter>[] = [\n  { value: '', label: 'sideToolbar.mediaAssets.dateAll' },\n  { value: 'today', label: 'sideToolbar.mediaAssets.dateToday' },\n  { value: 'week', label: 'sideToolbar.mediaAssets.datePastWeek' },\n  { value: 'month', label: 'sideToolbar.mediaAssets.datePastMonth' },\n  { value: 'year', label: 'sideToolbar.mediaAssets.dateThisYear' }\n]\n","<template>\n  <div class=\"flex h-8 items-center gap-2 px-2\">\n    <i\n      aria-hidden=\"true\"\n      class=\"icon-[lucide--search] size-4 shrink-0 text-muted-foreground\"\n    />\n    <input\n      ref=\"searchInput\"\n      v-model=\"searchQuery\"\n      type=\"text\"\n      :aria-label=\"$t('assetBrowser.filterBy')\"\n      :placeholder=\"$t('sideToolbar.mediaAssets.filterBy')\"\n      class=\"min-w-0 flex-1 border-none bg-transparent text-sm outline-none placeholder:text-muted-foreground\"\n      @keydown=\"handleSearchKeydown\"\n    />\n  </div>\n  <DropdownMenuSeparator class=\"my-1 h-px bg-border-subtle\" />\n\n  <template v-if=\"isSearching\">\n    <template v-if=\"matchingMediaTypes.length\">\n      <DropdownMenuLabel :class=\"groupLabelClass\">\n        {{ $t('sideToolbar.mediaAssets.filterMediaType') }}\n      </DropdownMenuLabel>\n      <DropdownMenuCheckboxItem\n        v-for=\"filter in matchingMediaTypes\"\n        :key=\"filter.value\"\n        :model-value=\"mediaTypeFilters.includes(filter.value)\"\n        :class=\"menuItemClass\"\n        @click=\"toggleMediaType(filter.value)\"\n        @keydown=\"handleSearchResultKeydown\"\n        @select.prevent\n      >\n        <span class=\"flex-1\">{{ $t(filter.label) }}</span>\n        <DropdownMenuItemIndicator class=\"size-4 shrink-0\">\n          <i class=\"icon-[lucide--check]\" />\n        </DropdownMenuItemIndicator>\n      </DropdownMenuCheckboxItem>\n    </template>\n\n    <template v-if=\"matchingDates.length\">\n      <DropdownMenuLabel :class=\"groupLabelClass\">\n        {{ $t('sideToolbar.mediaAssets.filterDate') }}\n      </DropdownMenuLabel>\n      <DropdownMenuRadioGroup :model-value=\"dateFilter\">\n        <DropdownMenuRadioItem\n          v-for=\"filter in matchingDates\"\n          :key=\"filter.value\"\n          :value=\"filter.value\"\n          :class=\"menuItemClass\"\n          @click=\"dateFilter = filter.value\"\n          @keydown=\"handleSearchResultKeydown\"\n          @select.prevent\n        >\n          <span class=\"flex-1\">{{ $t(filter.label) }}</span>\n          <DropdownMenuItemIndicator class=\"size-4 shrink-0\">\n            <i class=\"icon-[lucide--check]\" />\n          </DropdownMenuItemIndicator>\n        </DropdownMenuRadioItem>\n      </DropdownMenuRadioGroup>\n    </template>\n\n    <div\n      v-if=\"!hasSearchResults\"\n      class=\"px-2 py-1.5 text-sm text-muted-foreground\"\n    >\n      {{ $t('sideToolbar.mediaAssets.filterNoMatches') }}\n    </div>\n  </template>\n\n  <DropdownMenuLabel v-if=\"!isSearching\" :class=\"groupLabelClass\">\n    {{ $t('sideToolbar.mediaAssets.filterGroupAttribute') }}\n  </DropdownMenuLabel>\n\n  <DropdownMenuSub v-if=\"!isSearching\">\n    <DropdownMenuSubTrigger :class=\"menuItemClass\">\n      <i class=\"icon-[lucide--image] size-4 shrink-0 text-muted-foreground\" />\n      <span class=\"flex-1 text-left\">\n        {{ $t('sideToolbar.mediaAssets.filterMediaType') }}\n      </span>\n      <i\n        class=\"icon-[lucide--chevron-right] size-4 shrink-0 text-muted-foreground\"\n      />\n    </DropdownMenuSubTrigger>\n\n    <DropdownMenuPortal>\n      <DropdownMenuSubContent\n        :side-offset=\"8\"\n        :align-offset=\"-9\"\n        :collision-padding=\"10\"\n        :prioritize-position=\"false\"\n        :class=\"submenuClass\"\n      >\n        <DropdownMenuCheckboxItem\n          v-for=\"filter in mediaTypeFilterOptions\"\n          :key=\"filter.value\"\n          :model-value=\"mediaTypeFilters.includes(filter.value)\"\n          :class=\"menuItemClass\"\n          @click=\"toggleMediaType(filter.value)\"\n          @select.prevent\n        >\n          <span class=\"flex-1\">{{ $t(filter.label) }}</span>\n          <DropdownMenuItemIndicator class=\"size-4 shrink-0\">\n            <i class=\"icon-[lucide--check]\" />\n          </DropdownMenuItemIndicator>\n        </DropdownMenuCheckboxItem>\n      </DropdownMenuSubContent>\n    </DropdownMenuPortal>\n  </DropdownMenuSub>\n\n  <DropdownMenuSub v-if=\"!isSearching\">\n    <DropdownMenuSubTrigger :class=\"menuItemClass\">\n      <i\n        class=\"icon-[lucide--calendar] size-4 shrink-0 text-muted-foreground\"\n      />\n      <span class=\"flex-1 text-left\">\n        {{ $t('sideToolbar.mediaAssets.filterDate') }}\n      </span>\n      <i\n        class=\"icon-[lucide--chevron-right] size-4 shrink-0 text-muted-foreground\"\n      />\n    </DropdownMenuSubTrigger>\n\n    <DropdownMenuPortal>\n      <DropdownMenuSubContent\n        :side-offset=\"8\"\n        :align-offset=\"-9\"\n        :collision-padding=\"10\"\n        :prioritize-position=\"false\"\n        :class=\"submenuClass\"\n      >\n        <DropdownMenuRadioGroup :model-value=\"dateFilter\">\n          <DropdownMenuRadioItem\n            v-for=\"filter in dateFilterOptions\"\n            :key=\"filter.value\"\n            :value=\"filter.value\"\n            :class=\"menuItemClass\"\n            @click=\"dateFilter = filter.value\"\n            @select.prevent\n          >\n            <span class=\"flex-1\">{{ $t(filter.label) }}</span>\n            <DropdownMenuItemIndicator class=\"size-4 shrink-0\">\n              <i class=\"icon-[lucide--check]\" />\n            </DropdownMenuItemIndicator>\n          </DropdownMenuRadioItem>\n        </DropdownMenuRadioGroup>\n      </DropdownMenuSubContent>\n    </DropdownMenuPortal>\n  </DropdownMenuSub>\n</template>\n\n<script setup lang=\"ts\">\nimport {\n  DropdownMenuCheckboxItem,\n  DropdownMenuItemIndicator,\n  DropdownMenuLabel,\n  DropdownMenuPortal,\n  DropdownMenuRadioGroup,\n  DropdownMenuRadioItem,\n  DropdownMenuSeparator,\n  DropdownMenuSub,\n  DropdownMenuSubContent,\n  DropdownMenuSubTrigger\n} from 'reka-ui'\nimport { computed, nextTick, onMounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport {\n  menuContentClass,\n  menuItemClass\n} from '@/components/ui/menu/menuStyles'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport {\n  dateFilterOptions,\n  mediaTypeFilterOptions\n} from '@/platform/assets/mediaAssetFilterOptions'\nimport type { MediaAssetDateFilter } from '@/platform/assets/mediaAssetFilterOptions'\n\nconst dateFilter = defineModel<MediaAssetDateFilter>('dateFilter', {\n  required: true\n})\nconst mediaTypeFilters = defineModel<string[]>('mediaTypeFilters', {\n  required: true\n})\n\nconst { t } = useI18n()\nconst searchInput = ref<HTMLInputElement>()\nconst searchQuery = ref('')\nconst normalizedQuery = computed(() => searchQuery.value.trim().toLowerCase())\nconst isSearching = computed(() => normalizedQuery.value.length > 0)\nconst matchingMediaTypes = computed(() =>\n  mediaTypeFilterOptions.filter((filter) =>\n    t(filter.label).toLowerCase().includes(normalizedQuery.value)\n  )\n)\nconst matchingDates = computed(() =>\n  dateFilterOptions.filter((filter) =>\n    t(filter.label).toLowerCase().includes(normalizedQuery.value)\n  )\n)\nconst hasSearchResults = computed(\n  () => matchingMediaTypes.value.length > 0 || matchingDates.value.length > 0\n)\n\nconst groupLabelClass =\n  'px-2 pt-1 pb-1.5 text-xs font-semibold text-muted-foreground uppercase'\nconst submenuClass = cn(menuContentClass, 'min-w-40')\n\nonMounted(() => {\n  void nextTick(() => searchInput.value?.focus())\n})\n\nfunction toggleMediaType(type: string) {\n  if (mediaTypeFilters.value.includes(type)) {\n    mediaTypeFilters.value = mediaTypeFilters.value.filter(\n      (filter) => filter !== type\n    )\n  } else {\n    mediaTypeFilters.value = [...mediaTypeFilters.value, type]\n  }\n}\n\nfunction handleSearchKeydown(event: KeyboardEvent) {\n  if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {\n    const results = getSearchResults()\n    const result = event.key === 'ArrowDown' ? results.at(0) : results.at(-1)\n\n    if (result) {\n      event.preventDefault()\n      event.stopPropagation()\n      result.focus()\n    }\n    return\n  }\n\n  if (\n    event.key.length === 1 &&\n    !event.ctrlKey &&\n    !event.metaKey &&\n    !event.altKey\n  ) {\n    event.stopPropagation()\n  }\n}\n\nfunction handleSearchResultKeydown(event: KeyboardEvent) {\n  const results = getSearchResults()\n  const currentIndex = results.indexOf(event.currentTarget as HTMLElement)\n  const movingPastEnd =\n    event.key === 'ArrowDown' && currentIndex === results.length - 1\n  const movingBeforeStart = event.key === 'ArrowUp' && currentIndex === 0\n\n  if (!movingPastEnd && !movingBeforeStart) return\n\n  event.preventDefault()\n  event.stopPropagation()\n  searchInput.value?.focus()\n}\n\nfunction getSearchResults() {\n  const menu = searchInput.value?.closest('[role=\"menu\"]')\n  return menu\n    ? Array.from(\n        menu.querySelectorAll<HTMLElement>(\n          '[role=\"menuitemcheckbox\"], [role=\"menuitemradio\"]'\n        )\n      )\n    : []\n}\n</script>\n","<template>\n  <div class=\"inline-flex items-center\">\n    <Popover>\n      <template #button>\n        <Button\n          :tooltip=\"$t('sideToolbar.mediaAssets.viewSettings')\"\n          variant=\"secondary\"\n          size=\"icon\"\n          :aria-label=\"$t('sideToolbar.mediaAssets.viewSettings')\"\n        >\n          <i class=\"icon-[lucide--settings-2]\" />\n        </Button>\n      </template>\n      <template #default=\"{ close }\">\n        <slot :close />\n      </template>\n    </Popover>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport Popover from '@/components/ui/Popover.vue'\n</script>\n","<template>\n  <div class=\"flex flex-col\">\n    <Button\n      variant=\"textonly\"\n      class=\"w-full\"\n      @click=\"handleViewModeChange(MEDIA_ASSET_VIEW_MODE.list)\"\n    >\n      <span class=\"flex items-center gap-2\">\n        <i class=\"icon-[lucide--table-of-contents] size-4\" />\n        <span>{{ $t('sideToolbar.queueProgressOverlay.viewList') }}</span>\n      </span>\n      <i\n        class=\"ml-auto icon-[lucide--check] size-4\"\n        :class=\"viewMode !== MEDIA_ASSET_VIEW_MODE.list && 'opacity-0'\"\n      />\n    </Button>\n\n    <Button\n      variant=\"textonly\"\n      class=\"w-full\"\n      @click=\"handleViewModeChange(MEDIA_ASSET_VIEW_MODE.gridSmall)\"\n    >\n      <span class=\"flex items-center gap-2\">\n        <i class=\"icon-[lucide--grid-3x3] size-4\" />\n        <span>{{ $t('sideToolbar.mediaAssets.viewGridSmall') }}</span>\n      </span>\n      <i\n        class=\"ml-auto icon-[lucide--check] size-4\"\n        :class=\"viewMode !== MEDIA_ASSET_VIEW_MODE.gridSmall && 'opacity-0'\"\n      />\n    </Button>\n\n    <Button\n      variant=\"textonly\"\n      class=\"w-full\"\n      @click=\"handleViewModeChange(MEDIA_ASSET_VIEW_MODE.grid)\"\n    >\n      <span class=\"flex items-center gap-2\">\n        <i class=\"icon-[lucide--layout-grid] size-4\" />\n        <span>{{ $t('sideToolbar.mediaAssets.viewGridLarge') }}</span>\n      </span>\n      <i\n        class=\"ml-auto icon-[lucide--check] size-4\"\n        :class=\"viewMode !== MEDIA_ASSET_VIEW_MODE.grid && 'opacity-0'\"\n      />\n    </Button>\n\n    <template v-if=\"showSortOptions\">\n      <div class=\"my-1 w-full border-b border-border-subtle\" />\n\n      <Button\n        variant=\"textonly\"\n        class=\"w-full\"\n        @click=\"handleSortChange('newest')\"\n      >\n        <span>{{ $t('sideToolbar.mediaAssets.sortNewestFirst') }}</span>\n        <i\n          class=\"ml-auto icon-[lucide--check] size-4\"\n          :class=\"sortBy !== 'newest' && 'opacity-0'\"\n        />\n      </Button>\n\n      <Button\n        variant=\"textonly\"\n        class=\"w-full\"\n        @click=\"handleSortChange('oldest')\"\n      >\n        <span>{{ $t('sideToolbar.mediaAssets.sortOldestFirst') }}</span>\n        <i\n          class=\"ml-auto icon-[lucide--check] size-4\"\n          :class=\"sortBy !== 'oldest' && 'opacity-0'\"\n        />\n      </Button>\n\n      <Button variant=\"textonly\" class=\"w-full\" @click=\"handleSortChange('az')\">\n        <span>{{ $t('sideToolbar.mediaAssets.sortAToZ') }}</span>\n        <i\n          class=\"ml-auto icon-[lucide--check] size-4\"\n          :class=\"sortBy !== 'az' && 'opacity-0'\"\n        />\n      </Button>\n\n      <Button variant=\"textonly\" class=\"w-full\" @click=\"handleSortChange('za')\">\n        <span>{{ $t('sideToolbar.mediaAssets.sortZToA') }}</span>\n        <i\n          class=\"ml-auto icon-[lucide--check] size-4\"\n          :class=\"sortBy !== 'za' && 'opacity-0'\"\n        />\n      </Button>\n\n      <template v-if=\"showGenerationTimeSort\">\n        <Button\n          variant=\"textonly\"\n          class=\"w-full\"\n          @click=\"handleSortChange('longest')\"\n        >\n          <span>{{ $t('sideToolbar.mediaAssets.sortLongestFirst') }}</span>\n          <i\n            class=\"ml-auto icon-[lucide--check] size-4\"\n            :class=\"sortBy !== 'longest' && 'opacity-0'\"\n          />\n        </Button>\n\n        <Button\n          variant=\"textonly\"\n          class=\"w-full\"\n          @click=\"handleSortChange('fastest')\"\n        >\n          <span>{{ $t('sideToolbar.mediaAssets.sortFastestFirst') }}</span>\n          <i\n            class=\"ml-auto icon-[lucide--check] size-4\"\n            :class=\"sortBy !== 'fastest' && 'opacity-0'\"\n          />\n        </Button>\n      </template>\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nimport { MEDIA_ASSET_VIEW_MODE } from './mediaAssetViewOptions'\nimport type { MediaAssetViewMode } from './mediaAssetViewOptions'\n\nexport type SortBy = 'newest' | 'oldest' | 'az' | 'za' | 'longest' | 'fastest'\n\nconst { showSortOptions = false, showGenerationTimeSort = false } =\n  defineProps<{\n    showSortOptions?: boolean\n    showGenerationTimeSort?: boolean\n  }>()\n\nconst viewMode = defineModel<MediaAssetViewMode>('viewMode', { required: true })\nconst sortBy = defineModel<SortBy>('sortBy', { required: true })\n\nfunction handleViewModeChange(value: MediaAssetViewMode) {\n  viewMode.value = value\n}\n\nfunction handleSortChange(value: SortBy) {\n  sortBy.value = value\n}\n</script>\n","<template>\n  <div>\n    <SidebarTopArea>\n      <SearchInput\n        v-model=\"searchQuery\"\n        :placeholder=\"\n          $t('g.searchPlaceholder', {\n            subject: $t('sideToolbar.labels.assets')\n          })\n        \"\n      />\n      <template #actions>\n        <Menu v-if=\"isCloud\" :modal=\"false\">\n          <template #trigger>\n            <Button\n              :tooltip=\"$t('assetBrowser.filterBy')\"\n              variant=\"secondary\"\n              size=\"icon\"\n              icon=\"icon-[lucide--list-filter]\"\n              :indicator=\"hasActiveFilters\"\n              :aria-label=\"$t('assetBrowser.filterBy')\"\n            />\n          </template>\n          <MediaAssetFilterMenu\n            v-model:date-filter=\"dateFilter\"\n            v-model:media-type-filters=\"mediaTypeFilters\"\n          />\n        </Menu>\n        <MediaAssetSettingsButton>\n          <template #default>\n            <MediaAssetSettingsMenu\n              v-model:view-mode=\"viewMode\"\n              v-model:sort-by=\"sortBy\"\n              :show-sort-options=\"isCloud\"\n              :show-generation-time-sort\n            />\n          </template>\n        </MediaAssetSettingsButton>\n      </template>\n    </SidebarTopArea>\n\n    <div\n      v-if=\"filterChips.length\"\n      class=\"flex flex-wrap items-center gap-1.5 px-4 pb-2\"\n    >\n      <span\n        v-for=\"chip in filterChips\"\n        :key=\"chip.key\"\n        class=\"inline-flex items-center gap-1 rounded-md bg-secondary-background py-1 pr-1 pl-2 text-xs whitespace-nowrap\"\n      >\n        <span>{{ chip.label }}</span>\n        <Button\n          variant=\"textonly\"\n          size=\"icon\"\n          class=\"size-4 rounded-sm p-0\"\n          :aria-label=\"\n            $t('sideToolbar.mediaAssets.removeFilter', {\n              label: chip.label\n            })\n          \"\n          @click=\"removeFilter(chip.key)\"\n        >\n          <i class=\"icon-[lucide--x] size-3\" />\n        </Button>\n      </span>\n      <Button\n        variant=\"textonly\"\n        class=\"h-6 px-1.5 text-xs text-muted-foreground\"\n        @click=\"clearFilters\"\n      >\n        {{ $t('sideToolbar.mediaAssets.clearFilters') }}\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport SidebarTopArea from '@/components/sidebar/tabs/SidebarTopArea.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport { isCloud } from '@/platform/distribution/types'\nimport {\n  dateFilterOptions,\n  mediaTypeFilterOptions\n} from '@/platform/assets/mediaAssetFilterOptions'\nimport type { MediaAssetDateFilter } from '@/platform/assets/mediaAssetFilterOptions'\n\nimport MediaAssetFilterMenu from './MediaAssetFilterMenu.vue'\nimport MediaAssetSettingsButton from './MediaAssetSettingsButton.vue'\nimport MediaAssetSettingsMenu from './MediaAssetSettingsMenu.vue'\nimport type { SortBy } from './MediaAssetSettingsMenu.vue'\nimport type { MediaAssetViewMode } from './mediaAssetViewOptions'\n\nconst { showGenerationTimeSort = false } = defineProps<{\n  showGenerationTimeSort?: boolean\n}>()\n\nconst searchQuery = defineModel<string>('searchQuery', { required: true })\nconst sortBy = defineModel<SortBy>('sortBy', { required: true })\nconst viewMode = defineModel<MediaAssetViewMode>('viewMode', { required: true })\nconst dateFilter = defineModel<MediaAssetDateFilter>('dateFilter', {\n  required: true\n})\nconst mediaTypeFilters = defineModel<string[]>('mediaTypeFilters', {\n  required: true\n})\n\nconst { t } = useI18n()\n\nfunction labelFor(options: { value: string; label: string }[], value: string) {\n  return t(options.find((option) => option.value === value)?.label ?? value)\n}\n\nconst filterChips = computed(() => {\n  const chips = mediaTypeFilters.value.map((value) => ({\n    key: `media:${value}`,\n    label: labelFor(mediaTypeFilterOptions, value)\n  }))\n\n  if (dateFilter.value) {\n    chips.push({\n      key: 'date',\n      label: labelFor(dateFilterOptions, dateFilter.value)\n    })\n  }\n\n  return chips\n})\n\nconst hasActiveFilters = computed(() => filterChips.value.length > 0)\n\nfunction removeFilter(key: string) {\n  if (key === 'date') {\n    dateFilter.value = ''\n    return\n  }\n\n  const mediaType = key.slice('media:'.length)\n  mediaTypeFilters.value = mediaTypeFilters.value.filter(\n    (value) => value !== mediaType\n  )\n}\n\nfunction clearFilters() {\n  dateFilter.value = ''\n  mediaTypeFilters.value = []\n}\n</script>\n","<template>\n  <div class=\"relative mx-2\">\n    <div\n      data-testid=\"assets-selection-bar\"\n      class=\"absolute bottom-6 left-1/2 z-40 flex w-full max-w-78 -translate-x-1/2 items-center gap-2 rounded-lg bg-base-foreground p-2 text-base-background shadow-interface\"\n    >\n      <Button\n        :tooltip=\"$t('mediaAsset.selection.deselectAll')\"\n        variant=\"inverted\"\n        size=\"icon-lg\"\n        type=\"button\"\n        data-testid=\"assets-deselect-selected\"\n        :aria-label=\"$t('mediaAsset.selection.deselectAll')\"\n        class=\"rounded-lg hover:bg-base-background/10\"\n        @click=\"emit('deselect')\"\n      >\n        <i class=\"icon-[lucide--x] size-4\" />\n      </Button>\n      <span class=\"pr-6 text-sm font-bold whitespace-nowrap tabular-nums\">\n        {{ $t('mediaAsset.selection.selectedCount', { count }) }}\n      </span>\n      <div class=\"ml-auto flex shrink-0 items-center gap-1\">\n        <Button\n          :tooltip=\"$t('mediaAsset.selection.downloadSelected')\"\n          variant=\"inverted\"\n          size=\"icon-lg\"\n          type=\"button\"\n          data-testid=\"assets-download-selected\"\n          :aria-label=\"$t('mediaAsset.selection.downloadSelected')\"\n          class=\"rounded-lg hover:bg-base-background/10\"\n          @click=\"emit('download')\"\n        >\n          <i class=\"icon-[lucide--download] size-4\" />\n        </Button>\n        <template v-if=\"showDelete\">\n          <span class=\"h-6 w-px bg-base-background/20\" aria-hidden=\"true\" />\n          <Button\n            :tooltip=\"$t('mediaAsset.selection.deleteSelected')\"\n            variant=\"inverted\"\n            size=\"icon-lg\"\n            type=\"button\"\n            data-testid=\"assets-delete-selected\"\n            :aria-label=\"$t('mediaAsset.selection.deleteSelected')\"\n            class=\"rounded-lg hover:bg-base-background/10\"\n            @click=\"emit('delete')\"\n          >\n            <i class=\"icon-[lucide--trash-2] size-4\" />\n          </Button>\n        </template>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\n\nconst { count, showDelete = true } = defineProps<{\n  count: number\n  showDelete?: boolean\n}>()\n\nconst emit = defineEmits<{\n  deselect: []\n  download: []\n  delete: []\n}>()\n</script>\n","import type { RectEdges } from '@/utils/mathUtil'\n\nexport interface MarqueeCard {\n  id: string\n  rect: RectEdges\n}\n\nexport function normalizeMarqueeRect(\n  start: { x: number; y: number },\n  end: { x: number; y: number }\n): RectEdges {\n  return {\n    left: Math.min(start.x, end.x),\n    top: Math.min(start.y, end.y),\n    right: Math.max(start.x, end.x),\n    bottom: Math.max(start.y, end.y)\n  }\n}\n\nfunction rectsIntersect(a: RectEdges, b: RectEdges): boolean {\n  return !(\n    a.right < b.left ||\n    a.left > b.right ||\n    a.bottom < b.top ||\n    a.top > b.bottom\n  )\n}\n\n/**\n * Resolve the asset ids a marquee covers, starting from `baseIds` (the selection\n * to preserve when a modifier makes the drag additive). With `subtract`, covered\n * ids are removed from `baseIds` instead of added. A fresh Set is returned;\n * `baseIds` is never mutated.\n */\nexport function selectMarqueeIds(\n  cards: readonly MarqueeCard[],\n  marquee: RectEdges,\n  baseIds: Iterable<string> = [],\n  subtract = false\n): Set<string> {\n  const result = new Set(baseIds)\n  for (const { id, rect } of cards) {\n    if (!rectsIntersect(rect, marquee)) continue\n    if (subtract) result.delete(id)\n    else result.add(id)\n  }\n  return result\n}\n","import { useElementHover, useEventListener } from '@vueuse/core'\nimport type { Ref } from 'vue'\nimport { computed, onScopeDispose, ref } from 'vue'\n\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport {\n  normalizeMarqueeRect,\n  selectMarqueeIds\n} from '@/platform/assets/utils/marqueeSelectionUtil'\nimport { clipRectToBounds } from '@/utils/mathUtil'\nimport type { RectEdges } from '@/utils/mathUtil'\n\nconst DRAG_THRESHOLD_PX = 4\nconst CARD_SELECTOR = '[data-asset-id]'\nconst INTERACTIVE_SELECTOR =\n  'button, input, textarea, select, a[href], [role=\"slider\"], [role=\"tab\"], [contenteditable]'\n\ninterface AssetGridSelectionOptions {\n  marqueeContainerRef: Ref<HTMLElement | undefined>\n  hoverTargetRef: Ref<HTMLElement | undefined>\n  getAssets: () => AssetItem[]\n  getSelectedIds: () => string[]\n  setSelectedIds: (ids: string[], allAssets: AssetItem[]) => void\n  selectAll: (assets: AssetItem[]) => void\n  isEnabled?: () => boolean\n}\n\nfunction isTextEntryTarget(element: Element | null): boolean {\n  return (\n    element instanceof HTMLInputElement ||\n    element instanceof HTMLTextAreaElement ||\n    (element instanceof HTMLElement && element.isContentEditable)\n  )\n}\n\nexport function useAssetGridSelection(options: AssetGridSelectionOptions) {\n  const {\n    marqueeContainerRef,\n    hoverTargetRef,\n    getAssets,\n    getSelectedIds,\n    setSelectedIds,\n    selectAll,\n    isEnabled = () => true\n  } = options\n\n  const marqueeRect = ref<RectEdges | null>(null)\n  const isHoveringPanel = useElementHover(hoverTargetRef)\n\n  let startX = 0\n  let startY = 0\n  let pointerId = 0\n  let baseIds: string[] = []\n  let isSubtractive = false\n  let isTracking = false\n  let isDragging = false\n  let suppressNextClick = false\n  let suppressClickResetTimeout: ReturnType<typeof setTimeout> | null = null\n  let dragCards: { id: string; rect: DOMRect }[] = []\n  let dragBounds: DOMRect | null = null\n  let pointerClientX = 0\n  let pointerClientY = 0\n  let hasPointerSample = false\n\n  function collectCards(container: HTMLElement) {\n    return [...container.querySelectorAll<HTMLElement>(CARD_SELECTOR)].flatMap(\n      (el) => {\n        const id = el.dataset.assetId\n        return id ? [{ id, rect: el.getBoundingClientRect() }] : []\n      }\n    )\n  }\n\n  function snapshotDrag() {\n    const container = marqueeContainerRef.value\n    if (!container) return\n    dragCards = collectCards(container)\n    dragBounds = container.getBoundingClientRect()\n  }\n\n  function applyMarquee(clientX: number, clientY: number) {\n    if (!dragBounds) return\n    const rect = clipRectToBounds(\n      normalizeMarqueeRect(\n        { x: startX, y: startY },\n        { x: clientX, y: clientY }\n      ),\n      dragBounds\n    )\n    marqueeRect.value = rect\n    setSelectedIds(\n      [...selectMarqueeIds(dragCards, rect, baseIds, isSubtractive)],\n      getAssets()\n    )\n  }\n\n  function onPointerMove(e: PointerEvent) {\n    pointerClientX = e.clientX\n    pointerClientY = e.clientY\n    hasPointerSample = true\n    if (!isTracking) return\n    if (\n      !isDragging &&\n      Math.hypot(e.clientX - startX, e.clientY - startY) < DRAG_THRESHOLD_PX\n    ) {\n      return\n    }\n    if (!isDragging) {\n      isDragging = true\n      snapshotDrag()\n      capturePointer()\n    }\n    applyMarquee(e.clientX, e.clientY)\n  }\n\n  function capturePointer() {\n    try {\n      marqueeContainerRef.value?.setPointerCapture(pointerId)\n    } catch {\n      // Stale/invalid pointerId: window listeners still end the drag.\n    }\n  }\n\n  function endDrag() {\n    if (!isTracking) return\n    isTracking = false\n    marqueeRect.value = null\n    dragCards = []\n    dragBounds = null\n    if (isDragging) scheduleSuppressNextClick()\n    isDragging = false\n  }\n\n  function scheduleSuppressNextClick() {\n    suppressNextClick = true\n    clearSuppressTimer()\n    suppressClickResetTimeout = setTimeout(() => {\n      suppressNextClick = false\n      suppressClickResetTimeout = null\n    }, 0)\n  }\n\n  function clearSuppressTimer() {\n    if (suppressClickResetTimeout !== null) {\n      clearTimeout(suppressClickResetTimeout)\n      suppressClickResetTimeout = null\n    }\n  }\n\n  function preventDragStart(e: Event) {\n    if (isTracking) e.preventDefault()\n  }\n\n  function preventTextSelection(e: Event) {\n    if (!isTracking) return\n    const container = marqueeContainerRef.value\n    if (container && e.target instanceof Node && container.contains(e.target)) {\n      e.preventDefault()\n    }\n  }\n\n  function onPointerDown(e: PointerEvent) {\n    if (e.button !== 0) return\n    if (isTracking) return\n    if (!isEnabled()) return\n    suppressNextClick = false\n    clearSuppressTimer()\n    const container = marqueeContainerRef.value\n    if (!container) return\n    if (!container.querySelector(CARD_SELECTOR)) return\n    const target = e.target\n    if (!(target instanceof HTMLElement)) return\n    if (target.closest(INTERACTIVE_SELECTOR)) return\n\n    const onCard = target.closest(CARD_SELECTOR)\n    if (onCard && !e.ctrlKey && !e.metaKey) return\n\n    startX = e.clientX\n    startY = e.clientY\n    pointerId = e.pointerId\n    baseIds = e.shiftKey || e.ctrlKey || e.metaKey ? getSelectedIds() : []\n    isSubtractive = (e.ctrlKey || e.metaKey) && e.shiftKey\n    isDragging = false\n    isTracking = true\n  }\n\n  function onClickCapture(e: MouseEvent) {\n    if (!suppressNextClick) return\n    suppressNextClick = false\n    clearSuppressTimer()\n    e.stopImmediatePropagation()\n    e.preventDefault()\n  }\n\n  // useElementHover latches stale-false when an overlay under the cursor (the\n  // selection bar) unmounts on \"deselect all\"; recheck the live pointer against\n  // the panel rect so Ctrl/Cmd+A still resolves against the panel it is over.\n  function isPointerInsidePanel(): boolean {\n    const el = hoverTargetRef.value\n    if (!el || !hasPointerSample) return false\n    const { left, top, right, bottom } = el.getBoundingClientRect()\n    return (\n      pointerClientX >= left &&\n      pointerClientX <= right &&\n      pointerClientY >= top &&\n      pointerClientY <= bottom\n    )\n  }\n\n  function onKeydown(e: KeyboardEvent) {\n    if (!(e.ctrlKey || e.metaKey) || (e.key !== 'a' && e.key !== 'A')) return\n    if (\n      !(isHoveringPanel.value || isPointerInsidePanel()) ||\n      isTextEntryTarget(document.activeElement) ||\n      document.querySelector('[role=\"dialog\"][aria-modal=\"true\"]')\n    ) {\n      return\n    }\n    e.preventDefault()\n    e.stopImmediatePropagation()\n    selectAll(getAssets())\n  }\n\n  useEventListener(marqueeContainerRef, 'pointerdown', onPointerDown)\n  useEventListener(marqueeContainerRef, 'dragstart', preventDragStart, {\n    capture: true\n  })\n  useEventListener(window, 'pointermove', onPointerMove)\n  useEventListener(window, ['pointerup', 'pointercancel', 'dragend'], endDrag)\n  useEventListener(window, 'click', onClickCapture, { capture: true })\n  useEventListener(window, 'keydown', onKeydown, { capture: true })\n  useEventListener(window, 'selectstart', preventTextSelection, {\n    capture: true\n  })\n\n  onScopeDispose(clearSuppressTimer)\n\n  const marqueeStyle = computed(() => {\n    const rect = marqueeRect.value\n    if (!rect) return null\n    return {\n      left: `${rect.left}px`,\n      top: `${rect.top}px`,\n      width: `${rect.right - rect.left}px`,\n      height: `${rect.bottom - rect.top}px`\n    }\n  })\n\n  return { marqueeStyle }\n}\n","import { useKeyModifier } from '@vueuse/core'\nimport { computed, ref } from 'vue'\n\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { useAssetSelectionStore } from '@/platform/assets/composables/useAssetSelectionStore'\nimport {\n  getAssetOutputCount,\n  getTotalAssetOutputCount\n} from '@/platform/assets/utils/outputAssetCountUtil'\n\nexport function useAssetSelection() {\n  const selectionStore = useAssetSelectionStore()\n\n  // Track whether the asset selection is active (e.g., when sidebar is open)\n  const isActive = ref<boolean>(true)\n\n  // Key modifiers - raw values\n  const shiftKeyRaw = useKeyModifier('Shift')\n  const ctrlKeyRaw = useKeyModifier('Control')\n  const metaKeyRaw = useKeyModifier('Meta')\n\n  // Only respond to key modifiers when active\n  const shiftKey = computed(() => isActive.value && shiftKeyRaw.value)\n  const ctrlKey = computed(() => isActive.value && ctrlKeyRaw.value)\n  const metaKey = computed(() => isActive.value && metaKeyRaw.value)\n  const cmdOrCtrlKey = computed(() => ctrlKey.value || metaKey.value)\n\n  function setAnchor(index: number, assetId: string | null) {\n    selectionStore.setLastSelectedIndex(index)\n    selectionStore.setLastSelectedAssetId(assetId)\n  }\n\n  function syncAnchorFromAssets(assets: AssetItem[]) {\n    const anchorId = selectionStore.lastSelectedAssetId\n    const anchorIndex = anchorId\n      ? assets.findIndex((asset) => asset.id === anchorId)\n      : -1\n\n    if (anchorIndex !== -1) {\n      selectionStore.setLastSelectedIndex(anchorIndex)\n      return\n    }\n\n    setAnchor(-1, null)\n  }\n\n  function toggleAssetSelection(\n    asset: AssetItem,\n    index: number,\n    allAssets: AssetItem[]\n  ) {\n    if (!asset.id || index < 0 || index >= allAssets.length) {\n      console.warn('Invalid asset selection parameters')\n      return\n    }\n\n    selectionStore.toggleSelection(asset.id)\n    setAnchor(index, asset.id)\n  }\n\n  /**\n   * Handle asset click with modifier keys for selection\n   * @param asset The clicked asset\n   * @param index The index of the clicked asset in the current list\n   * @param allAssets All assets in the current view for range selection\n   */\n  function handleAssetClick(\n    asset: AssetItem,\n    index: number,\n    allAssets: AssetItem[]\n  ) {\n    // Input validation\n    if (!asset.id || index < 0 || index >= allAssets.length) {\n      console.warn('Invalid asset selection parameters')\n      return\n    }\n\n    const assetId = asset.id\n\n    // Shift + Click: Range selection\n    if (shiftKey.value && selectionStore.lastSelectedIndex >= 0) {\n      const start = Math.min(selectionStore.lastSelectedIndex, index)\n      const end = Math.max(selectionStore.lastSelectedIndex, index)\n\n      // Select only the range from anchor to clicked item\n      const rangeIds = allAssets.slice(start, end + 1).map((a) => a.id)\n      selectionStore.setSelection(rangeIds)\n\n      // Don't update lastSelectedIndex for shift selection\n      return\n    }\n\n    // Ctrl/Cmd + Click: Toggle individual selection\n    if (cmdOrCtrlKey.value) {\n      toggleAssetSelection(asset, index, allAssets)\n      return\n    }\n\n    // Clicking the only selected asset does not clear the selection\n    if (\n      selectionStore.isSelected(assetId) &&\n      selectionStore.selectedCount === 1\n    ) {\n      return\n    }\n\n    // Otherwise, a normal click collapses the selection to this asset\n    selectionStore.clearSelection()\n    selectionStore.addToSelection(assetId)\n    setAnchor(index, assetId)\n  }\n\n  /**\n   * Select all assets in the current view\n   */\n  function selectAll(allAssets: AssetItem[]) {\n    const allIds = allAssets.map((a) => a.id)\n    selectionStore.setSelection(allIds)\n    if (allAssets.length > 0) {\n      const lastIndex = allAssets.length - 1\n      setAnchor(lastIndex, allAssets[lastIndex].id)\n    }\n  }\n\n  /**\n   * Replace the selection (e.g. from a marquee) and keep the shift-range anchor\n   * on the last selected asset, the same way selectAll maintains it.\n   */\n  function setSelectedIds(ids: string[], allAssets: AssetItem[]) {\n    selectionStore.setSelection(ids)\n    const selected = new Set(ids)\n    const anchorIndex = allAssets.findLastIndex((asset) =>\n      selected.has(asset.id)\n    )\n    setAnchor(anchorIndex, anchorIndex >= 0 ? allAssets[anchorIndex].id : null)\n  }\n\n  /**\n   * Get the actual asset objects for selected IDs\n   */\n  function getSelectedAssets(allAssets: AssetItem[]): AssetItem[] {\n    return allAssets.filter((asset) => selectionStore.isSelected(asset.id))\n  }\n\n  function reconcileSelection(assets: AssetItem[]) {\n    if (selectionStore.selectedAssetIds.size === 0) {\n      return\n    }\n\n    if (assets.length === 0) {\n      selectionStore.clearSelection()\n      return\n    }\n\n    const visibleIds = new Set(assets.map((asset) => asset.id))\n    const nextSelectedIds: string[] = []\n\n    for (const id of selectionStore.selectedAssetIds) {\n      if (visibleIds.has(id)) {\n        nextSelectedIds.push(id)\n      }\n    }\n\n    if (nextSelectedIds.length === selectionStore.selectedAssetIds.size) {\n      syncAnchorFromAssets(assets)\n      return\n    }\n\n    if (nextSelectedIds.length === 0) {\n      selectionStore.clearSelection()\n      return\n    }\n\n    selectionStore.setSelection(nextSelectedIds)\n    syncAnchorFromAssets(assets)\n  }\n\n  /**\n   * Get the output count for a single asset\n   * Same logic as in AssetsSidebarTab.vue\n   */\n  function getOutputCount(item: AssetItem): number {\n    return getAssetOutputCount(item)\n  }\n\n  /**\n   * Get the total output count for given assets\n   */\n  function getTotalOutputCount(assets: AssetItem[]): number {\n    return getTotalAssetOutputCount(assets)\n  }\n\n  /**\n   * Activate key event listeners (when sidebar opens)\n   */\n  function activate() {\n    isActive.value = true\n  }\n\n  /**\n   * Deactivate key event listeners (when sidebar closes)\n   */\n  function deactivate() {\n    isActive.value = false\n    // Reset selection state to ensure clean state when deactivated\n    selectionStore.clearSelection()\n  }\n\n  return {\n    // Selection state\n    selectedIds: computed(() => selectionStore.selectedAssetIds),\n    selectedCount: computed(() => selectionStore.selectedCount),\n    hasSelection: computed(() => selectionStore.hasSelection),\n    isSelected: (assetId: string) => selectionStore.isSelected(assetId),\n\n    // Selection actions\n    handleAssetClick,\n    toggleAssetSelection,\n    selectAll,\n    setSelectedIds,\n    clearSelection: () => selectionStore.clearSelection(),\n    getSelectedAssets,\n    reconcileSelection,\n    getOutputCount,\n    getTotalOutputCount,\n    // Lifecycle management\n    activate,\n    deactivate,\n\n    // Key states (for UI feedback)\n    shiftKey,\n    cmdOrCtrlKey\n  }\n}\n","import { defineStore } from 'pinia'\nimport { ref } from 'vue'\n\nimport type { MediaAssetDateFilter } from '@/platform/assets/mediaAssetFilterOptions'\n\nexport const useMediaAssetFilterStore = defineStore('mediaAssetFilter', () => {\n  const mediaTypeFilters = ref<string[]>([])\n  const dateFilter = ref<MediaAssetDateFilter>('')\n\n  return {\n    mediaTypeFilters,\n    dateFilter\n  }\n})\n","import { refDebounced } from '@vueuse/core'\nimport { sortBy as sortByUtil } from 'es-toolkit'\nimport Fuse from 'fuse.js'\nimport { storeToRefs } from 'pinia'\nimport { computed, toValue, ref } from 'vue'\nimport type { MaybeRef } from 'vue'\n\nimport { useMediaAssetFilterStore } from '@/platform/assets/composables/useMediaAssetFilterStore'\nimport type { MediaAssetDateFilter } from '@/platform/assets/mediaAssetFilterOptions'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { getAssetDisplayName } from '@/platform/assets/utils/assetMetadataUtils'\nimport { getMediaTypeFromFilename } from '@/utils/formatUtil'\n\ntype SortOption = 'newest' | 'oldest' | 'az' | 'za' | 'longest' | 'fastest'\n\n/**\n * Get timestamp from asset (either create_time or created_at)\n */\nconst getAssetTime = (asset: AssetItem): number => {\n  const createTime = asset.user_metadata?.create_time\n  return typeof createTime === 'number'\n    ? createTime\n    : asset.created_at\n      ? new Date(asset.created_at).getTime()\n      : 0\n}\n\n/**\n * Get execution time from asset user_metadata\n */\nconst getAssetExecutionTime = (asset: AssetItem): number => {\n  const executionTime = asset.user_metadata?.executionTimeInSeconds\n  return typeof executionTime === 'number' ? executionTime : 0\n}\n\nfunction getDateThreshold(filter: MediaAssetDateFilter): number | null {\n  const now = Date.now()\n\n  switch (filter) {\n    case 'today': {\n      const startOfToday = new Date(now)\n      startOfToday.setHours(0, 0, 0, 0)\n      return startOfToday.getTime()\n    }\n    case 'week':\n      return now - 7 * 86_400_000\n    case 'month':\n      return now - 30 * 86_400_000\n    case 'year':\n      return new Date(new Date(now).getFullYear(), 0, 1).getTime()\n    default:\n      return null\n  }\n}\n\nconst compareAssetNames = (a: AssetItem, b: AssetItem): number =>\n  getAssetDisplayName(a).localeCompare(getAssetDisplayName(b), undefined, {\n    numeric: true,\n    sensitivity: 'base'\n  })\n\n/**\n * Media Asset Filtering composable\n * Manages search, filter, and sort for media assets\n */\nexport function useMediaAssetFiltering(assets: MaybeRef<readonly AssetItem[]>) {\n  const searchQuery = ref('')\n  const debouncedSearchQuery = refDebounced(searchQuery, 50)\n  const sortBy = ref<SortOption>('newest')\n  const { mediaTypeFilters, dateFilter } = storeToRefs(\n    useMediaAssetFilterStore()\n  )\n\n  const fuseOptions = {\n    keys: ['display_name', 'name'],\n    threshold: 0.4,\n    includeScore: true\n  }\n\n  const fuse = computed(() => new Fuse(toValue(assets), fuseOptions))\n\n  const searchFiltered = computed(() => {\n    if (!debouncedSearchQuery.value.trim()) {\n      return toValue(assets)\n    }\n\n    const results = fuse.value.search(debouncedSearchQuery.value)\n    return results.map((result) => result.item)\n  })\n\n  const filteredAssets = computed(() => {\n    const threshold = getDateThreshold(dateFilter.value)\n    const filtered = searchFiltered.value.filter((asset) => {\n      const matchesMediaType =\n        mediaTypeFilters.value.length === 0 ||\n        mediaTypeFilters.value.includes(\n          getMediaTypeFromFilename(asset.name).toLowerCase()\n        )\n      const matchesDate = threshold === null || getAssetTime(asset) >= threshold\n\n      return matchesMediaType && matchesDate\n    })\n\n    // Sort by create_time (output assets) or created_at (input assets)\n    switch (sortBy.value) {\n      case 'oldest':\n        // Ascending order (oldest first)\n        return sortByUtil(filtered, [getAssetTime])\n      case 'longest':\n        // Descending order (longest execution time first)\n        return sortByUtil(filtered, [(asset) => -getAssetExecutionTime(asset)])\n      case 'fastest':\n        // Ascending order (fastest execution time first)\n        return sortByUtil(filtered, [getAssetExecutionTime])\n      case 'az':\n        return [...filtered].sort(compareAssetNames)\n      case 'za':\n        return [...filtered].sort((a, b) => compareAssetNames(b, a))\n      case 'newest':\n      default:\n        // Descending order (newest first) - negate for descending\n        return sortByUtil(filtered, [(asset) => -getAssetTime(asset)])\n    }\n  })\n\n  return {\n    searchQuery,\n    sortBy,\n    mediaTypeFilters,\n    dateFilter,\n    filteredAssets\n  }\n}\n","import { computed, ref } from 'vue'\nimport type { Ref } from 'vue'\n\nimport { getOutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { resolveOutputAssetItems } from '@/platform/assets/utils/outputAssetUtil'\nimport { getOutputKey } from '@/platform/assets/utils/outputKeyUtil'\n\nexport type OutputStackListItem = {\n  key: string\n  asset: AssetItem\n  isChild?: boolean\n}\n\ntype UseOutputStacksOptions = {\n  assets: Ref<AssetItem[]>\n}\n\nexport function useOutputStacks({ assets }: UseOutputStacksOptions) {\n  const expandedStackJobIds = ref<Set<string>>(new Set())\n  const stackChildrenByJobId = ref<Record<string, AssetItem[]>>({})\n  const loadingStackJobIds = ref<Set<string>>(new Set())\n\n  const assetItems = computed<OutputStackListItem[]>(() => {\n    const items: OutputStackListItem[] = []\n\n    for (const asset of assets.value) {\n      const jobId = getStackJobId(asset)\n      items.push({\n        key: `asset-${asset.id}`,\n        asset\n      })\n\n      if (!jobId || !expandedStackJobIds.value.has(jobId)) {\n        continue\n      }\n\n      const children = stackChildrenByJobId.value[jobId] ?? []\n      for (const child of children) {\n        items.push({\n          key: `asset-${child.id}`,\n          asset: child,\n          isChild: true\n        })\n      }\n    }\n\n    return items\n  })\n\n  const selectableAssets = computed(() =>\n    assetItems.value.map((item) => item.asset)\n  )\n\n  function getStackJobId(asset: AssetItem): string | null {\n    const metadata = getOutputAssetMetadata(asset.user_metadata)\n    return metadata?.jobId ?? null\n  }\n\n  function isStackExpanded(asset: AssetItem): boolean {\n    const jobId = getStackJobId(asset)\n    if (!jobId) return false\n    return expandedStackJobIds.value.has(jobId)\n  }\n\n  async function toggleStack(asset: AssetItem) {\n    const jobId = getStackJobId(asset)\n    if (!jobId) return\n\n    if (expandedStackJobIds.value.has(jobId)) {\n      const next = new Set(expandedStackJobIds.value)\n      next.delete(jobId)\n      expandedStackJobIds.value = next\n      return\n    }\n\n    if (!stackChildrenByJobId.value[jobId]?.length) {\n      if (loadingStackJobIds.value.has(jobId)) {\n        return\n      }\n      const nextLoading = new Set(loadingStackJobIds.value)\n      nextLoading.add(jobId)\n      loadingStackJobIds.value = nextLoading\n\n      const children = await resolveStackChildren(asset)\n\n      const afterLoading = new Set(loadingStackJobIds.value)\n      afterLoading.delete(jobId)\n      loadingStackJobIds.value = afterLoading\n\n      if (!children.length) {\n        return\n      }\n\n      stackChildrenByJobId.value = {\n        ...stackChildrenByJobId.value,\n        [jobId]: children\n      }\n    }\n\n    const nextExpanded = new Set(expandedStackJobIds.value)\n    nextExpanded.add(jobId)\n    expandedStackJobIds.value = nextExpanded\n  }\n\n  async function resolveStackChildren(asset: AssetItem): Promise<AssetItem[]> {\n    const metadata = getOutputAssetMetadata(asset.user_metadata)\n    if (!metadata) {\n      return []\n    }\n\n    const excludeOutputKey =\n      getOutputKey({\n        nodeId: metadata.nodeId,\n        subfolder: metadata.subfolder,\n        filename: asset.name\n      }) ?? undefined\n\n    try {\n      return await resolveOutputAssetItems(metadata, {\n        createdAt: asset.created_at,\n        excludeOutputKey\n      })\n    } catch (error) {\n      console.error('Failed to resolve stack children:', error)\n      return []\n    }\n  }\n\n  return {\n    assetItems,\n    selectableAssets,\n    isStackExpanded,\n    toggleStack\n  }\n}\n","<template>\n  <SidebarTabTemplate\n    ref=\"panelRef\"\n    :title=\"isInFolderView ? '' : $t('sideToolbar.mediaAssets.title')\"\n    :closable\n    v-bind=\"$attrs\"\n  >\n    <template #alt-title>\n      <div\n        v-if=\"isInFolderView\"\n        class=\"flex w-full items-center justify-between gap-2\"\n      >\n        <div class=\"flex min-w-0 flex-1 items-center gap-2\">\n          <Button\n            :tooltip=\"$t('sideToolbar.backToAssets')\"\n            tooltip-side=\"bottom\"\n            variant=\"textonly\"\n            size=\"icon\"\n            type=\"button\"\n            class=\"shrink-0\"\n            :aria-label=\"$t('sideToolbar.backToAssets')\"\n            @click=\"exitFolderView\"\n          >\n            <i class=\"icon-[lucide--arrow-left] size-4\" />\n          </Button>\n          <span class=\"shrink-0 font-bold\">\n            {{ $t('assetBrowser.jobId') }}:\n          </span>\n          <span class=\"min-w-0 truncate text-sm\">{{ folderJobId }}</span>\n          <Button\n            :tooltip=\"$t('g.copyJobId')\"\n            tooltip-side=\"bottom\"\n            variant=\"textonly\"\n            size=\"icon\"\n            type=\"button\"\n            class=\"shrink-0\"\n            :aria-label=\"$t('g.copyJobId')\"\n            @click=\"copyFolderJobId\"\n          >\n            <i class=\"icon-[lucide--copy] size-4\" />\n          </Button>\n        </div>\n        <div class=\"shrink-0\">\n          <span>{{ formattedExecutionTime }}</span>\n        </div>\n      </div>\n    </template>\n    <template #header>\n      <div v-if=\"!isInFolderView\" class=\"overflow-x-auto px-4 pt-2 pb-px\">\n        <TabList v-model=\"activeTab\">\n          <Tab value=\"output\">{{ $t('sideToolbar.labels.generated') }}</Tab>\n          <Tab value=\"input\">{{ $t('sideToolbar.labels.imported') }}</Tab>\n        </TabList>\n      </div>\n      <MediaAssetFilterBar\n        v-model:search-query=\"searchQuery\"\n        v-model:sort-by=\"sortBy\"\n        v-model:view-mode=\"viewMode\"\n        v-model:date-filter=\"dateFilter\"\n        v-model:media-type-filters=\"mediaTypeFilters\"\n        :show-generation-time-sort=\"activeTab === 'output'\"\n      />\n    </template>\n    <template #body>\n      <div v-bind=\"tabPanelAttrs\" class=\"size-full\">\n        <div\n          v-if=\"showLoadingState\"\n          class=\"grid gap-2 p-2\"\n          :style=\"skeletonGridStyle\"\n        >\n          <div\n            v-for=\"n in skeletonCount\"\n            :key=\"`skeleton-${n}`\"\n            class=\"flex flex-col gap-2 p-2\"\n          >\n            <Skeleton class=\"aspect-square w-full rounded-lg\" />\n            <div class=\"flex flex-col gap-1\">\n              <Skeleton class=\"h-4 w-3/4\" />\n              <Skeleton class=\"h-3 w-1/2\" />\n            </div>\n          </div>\n        </div>\n        <div v-else-if=\"showEmptyState\">\n          <NoResultsPlaceholder\n            icon=\"pi pi-info-circle\"\n            :title=\"\n              $t(\n                activeTab === 'input'\n                  ? 'sideToolbar.noImportedFiles'\n                  : 'sideToolbar.noGeneratedFiles'\n              )\n            \"\n            :message=\"$t('sideToolbar.noFilesFoundMessage')\"\n          />\n        </div>\n        <div\n          v-else\n          class=\"relative size-full py-2\"\n          @click=\"handleEmptySpaceClick\"\n        >\n          <AssetsSidebarListView\n            v-if=\"isListView\"\n            :asset-items=\"listViewAssetItems\"\n            :is-selected=\"isSelected\"\n            :selectable-assets=\"listViewSelectableAssets\"\n            :is-stack-expanded=\"isListViewStackExpanded\"\n            :toggle-stack=\"toggleListViewStack\"\n            :on-load-more=\"loadMoreAssets\"\n            :can-load-more=\"canLoadMoreAssets\"\n            @select-asset=\"handleAssetSelect\"\n            @preview-asset=\"handleZoomClick\"\n            @context-menu=\"handleAssetContextMenu\"\n          />\n          <div v-else class=\"size-full\">\n            <AssetsSidebarGridView\n              :assets=\"displayAssets\"\n              :is-selected\n              :show-output-count\n              :get-output-count\n              :grid-mode\n              :on-load-more=\"loadMoreAssets\"\n              :can-load-more=\"canLoadMoreAssets\"\n              @select-asset=\"handleAssetSelect\"\n              @toggle-asset-selection=\"handleAssetSelectionToggle\"\n              @context-menu=\"handleAssetContextMenu\"\n              @zoom=\"handleZoomClick\"\n              @output-count-click=\"enterFolderView\"\n            />\n          </div>\n        </div>\n      </div>\n    </template>\n    <template #footer>\n      <MediaAssetSelectionBar\n        v-if=\"hasSelection\"\n        :count=\"totalOutputCount\"\n        :show-delete=\"shouldShowDeleteButton\"\n        @deselect=\"handleDeselectAll\"\n        @download=\"handleBulkDownload(selectedAssets)\"\n        @delete=\"handleBulkDelete(selectedAssets)\"\n      />\n    </template>\n  </SidebarTabTemplate>\n  <Teleport to=\"body\">\n    <div\n      v-if=\"marqueeStyle\"\n      class=\"pointer-events-none fixed z-9999 border border-primary-background bg-primary-background/20\"\n      :style=\"marqueeStyle\"\n    />\n  </Teleport>\n  <MediaLightbox\n    v-model:active-index=\"galleryActiveIndex\"\n    :all-gallery-items=\"galleryItems\"\n  />\n  <ContextMenu\n    :id=\"contextMenuId\"\n    ref=\"contextMenuRef\"\n    :model=\"contextMenuItems\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { unrefElement, useAsyncState, useStorage } from '@vueuse/core'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport {\n  computed,\n  defineAsyncComponent,\n  onMounted,\n  onUnmounted,\n  ref,\n  toValue,\n  useId,\n  useTemplateRef,\n  watch\n} from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport NoResultsPlaceholder from '@/components/common/NoResultsPlaceholder.vue'\nimport { LOAD3D_VIEWER_DIALOG_PROPS } from '@/components/load3d/load3dViewerDialog'\nimport AssetsSidebarGridView from '@/components/sidebar/tabs/AssetsSidebarGridView.vue'\nimport AssetsSidebarListView from '@/components/sidebar/tabs/AssetsSidebarListView.vue'\nimport SidebarTabTemplate from '@/components/sidebar/tabs/SidebarTabTemplate.vue'\nimport Skeleton from '@/components/ui/skeleton/Skeleton.vue'\nimport MediaLightbox from '@/components/sidebar/tabs/queue/MediaLightbox.vue'\nimport Tab from '@/components/tab/Tab.vue'\nimport TabList from '@/components/tab/TabList.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport ContextMenu from '@/components/ui/menu/ContextMenu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useDismissableOverlay } from '@/composables/useDismissableOverlay'\nimport MediaAssetFilterBar from '@/platform/assets/components/MediaAssetFilterBar.vue'\nimport MediaAssetSelectionBar from '@/platform/assets/components/MediaAssetSelectionBar.vue'\nimport {\n  getMediaAssetGridColumns,\n  MEDIA_ASSET_VIEW_MODE\n} from '@/platform/assets/components/mediaAssetViewOptions'\nimport type {\n  MediaAssetGridMode,\n  MediaAssetViewMode\n} from '@/platform/assets/components/mediaAssetViewOptions'\nimport { getAssetType } from '@/platform/assets/composables/media/assetMappers'\nimport { useAssetGridSelection } from '@/platform/assets/composables/useAssetGridSelection'\nimport { useAssetSelection } from '@/platform/assets/composables/useAssetSelection'\nimport { useMediaAssetActions } from '@/platform/assets/composables/useMediaAssetActions'\nimport { useMediaAssetFiltering } from '@/platform/assets/composables/useMediaAssetFiltering'\nimport { useOutputStacks } from '@/platform/assets/composables/useOutputStacks'\nimport type { OutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport { getOutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { getAssetDisplayName } from '@/platform/assets/utils/assetMetadataUtils'\nimport {\n  getAssetFileUrl,\n  getAssetSubfolder,\n  getAssetViewUrl\n} from '@/platform/assets/utils/assetUrlUtil'\nimport { resolveOutputAssetItems } from '@/platform/assets/utils/outputAssetUtil'\nimport { isCloud } from '@/platform/distribution/types'\nimport { supportsWorkflowMetadata } from '@/platform/workflow/utils/workflowExtractionUtil'\nimport { openHdrViewer } from '@/services/hdrViewerService'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport {\n  formatDuration,\n  getMediaTypeFromFilename,\n  isPreviewableMediaType\n} from '@/utils/formatUtil'\nimport { isHdrImageFilename } from '@/utils/hdrFormatUtil'\nimport { detectNodeTypeFromFilename } from '@/utils/loaderNodeUtil'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\n\nconst Load3dViewerContent = defineAsyncComponent(\n  () => import('@/components/load3d/Load3dViewerContent.vue')\n)\n\nconst { t } = useI18n()\n\nconst { closable = true } = defineProps<{ closable?: boolean }>()\n\nconst emit = defineEmits<{ assetSelected: [asset: AssetItem] }>()\n\nconst activeTab = ref<'input' | 'output'>('output')\nconst folderJobId = ref<string | null>(null)\nconst folderExecutionTime = ref<number | undefined>(undefined)\nconst expectedFolderCount = ref(0)\nconst isInFolderView = computed(() => folderJobId.value !== null)\nconst tabPanelAttrs = computed(() =>\n  isInFolderView.value\n    ? {}\n    : {\n        id: `tabpanel-${activeTab.value}`,\n        role: 'tabpanel',\n        tabindex: 0,\n        'aria-labelledby': `tab-${activeTab.value}`\n      }\n)\nconst viewMode = useStorage<MediaAssetViewMode>(\n  'Comfy.Assets.Sidebar.ViewMode',\n  MEDIA_ASSET_VIEW_MODE.grid\n)\nconst isListView = computed(() => viewMode.value === MEDIA_ASSET_VIEW_MODE.list)\nconst gridMode = computed<MediaAssetGridMode>(() =>\n  viewMode.value === MEDIA_ASSET_VIEW_MODE.gridSmall\n    ? MEDIA_ASSET_VIEW_MODE.gridSmall\n    : MEDIA_ASSET_VIEW_MODE.grid\n)\nconst skeletonGridStyle = computed(() => ({\n  gridTemplateColumns: getMediaAssetGridColumns(gridMode.value)\n}))\n\nconst contextMenuRef = useTemplateRef('contextMenuRef')\nconst contextMenuId = useId()\nconst contextMenuItems = ref<MenuItem[]>([])\n\nuseDismissableOverlay({\n  isOpen: () => contextMenuRef.value?.visible ?? false,\n  getOverlayEl: () => document.getElementById(contextMenuId),\n  onDismiss: () => contextMenuRef.value?.hide(),\n  dismissOnScroll: true\n})\n\n// Determine if delete button should be shown\n// Hide delete button when in input tab and not in cloud (OSS mode - files are from local folders)\nconst shouldShowDeleteButton = computed(() => {\n  if (activeTab.value === 'input' && !isCloud) return false\n  return true\n})\n\nconst showOutputCount = (item: AssetItem): boolean => {\n  if (activeTab.value !== 'output' || isInFolderView.value) {\n    return false\n  }\n  return getOutputCount(item) > 1\n}\n\nconst formattedExecutionTime = computed(() => {\n  if (!folderExecutionTime.value) return ''\n  return formatDuration(folderExecutionTime.value * 1000)\n})\n\nconst toast = useToast()\nconst assetsStore = useAssetsStore()\n\n// Asset selection\nconst {\n  isSelected,\n  selectedIds,\n  handleAssetClick,\n  toggleAssetSelection,\n  selectAll,\n  setSelectedIds,\n  hasSelection,\n  clearSelection,\n  getSelectedAssets,\n  reconcileSelection,\n  getOutputCount,\n  getTotalOutputCount,\n  activate: activateSelection,\n  deactivate: deactivateSelection\n} = useAssetSelection()\n\nconst panelRef = useTemplateRef('panelRef')\nconst marqueePanelRef = computed(() => {\n  const el = unrefElement(panelRef)\n  return el instanceof HTMLElement ? el : undefined\n})\n\nconst {\n  downloadAssets,\n  deleteAssets,\n  addWorkflow,\n  openWorkflow,\n  exportWorkflow,\n  copyJobId,\n  addMultipleToWorkflow,\n  openMultipleWorkflows,\n  exportMultipleWorkflows\n} = useMediaAssetActions()\n\nconst currentAssets = computed(() =>\n  activeTab.value === 'input'\n    ? assetsStore.inputAssets\n    : assetsStore.outputAssets\n)\nconst loading = computed(() => toValue(currentAssets.value.isLoading))\nconst mediaAssets = computed(() => toValue(currentAssets.value.items))\n\nconst galleryActiveIndex = ref(-1)\nconst currentGalleryAssetId = ref<string | null>(null)\n\nconst DEFAULT_SKELETON_COUNT = 6\nconst skeletonCount = computed(() =>\n  expectedFolderCount.value > 0\n    ? expectedFolderCount.value\n    : DEFAULT_SKELETON_COUNT\n)\n\nconst {\n  state: folderAssets,\n  isLoading: folderLoading,\n  error: folderError,\n  execute: loadFolderAssets\n} = useAsyncState(\n  (metadata: OutputAssetMetadata, options: { createdAt?: string } = {}) =>\n    resolveOutputAssetItems(metadata, options),\n  [] as AssetItem[],\n  { immediate: false, resetOnExecute: true }\n)\n\n// Base assets before search filtering\nconst baseAssets = computed(() => {\n  if (isInFolderView.value) {\n    return folderAssets.value\n  }\n  return mediaAssets.value\n})\n\n// Use media asset filtering composable\nconst { searchQuery, sortBy, dateFilter, mediaTypeFilters, filteredAssets } =\n  useMediaAssetFiltering(baseAssets)\n\nconst displayAssets = computed(() => {\n  return filteredAssets.value\n})\n\nconst {\n  assetItems: listViewAssetItems,\n  selectableAssets: listViewSelectableAssets,\n  isStackExpanded: isListViewStackExpanded,\n  toggleStack: toggleListViewStack\n} = useOutputStacks({\n  assets: computed(() => displayAssets.value)\n})\n\nconst visibleAssets = computed(() => {\n  if (!isListView.value) return displayAssets.value\n  return listViewSelectableAssets.value\n})\n\nconst { marqueeStyle } = useAssetGridSelection({\n  marqueeContainerRef: marqueePanelRef,\n  hoverTargetRef: marqueePanelRef,\n  getAssets: () => visibleAssets.value,\n  getSelectedIds: () => [...selectedIds.value],\n  setSelectedIds,\n  selectAll,\n  isEnabled: () => !isListView.value\n})\n\nconst previewableVisibleAssets = computed(() =>\n  visibleAssets.value.filter((asset) =>\n    isPreviewableMediaType(getMediaTypeFromFilename(asset.name))\n  )\n)\n\nconst selectedAssets = computed(() => getSelectedAssets(visibleAssets.value))\n\nconst totalOutputCount = computed(() =>\n  getTotalOutputCount(selectedAssets.value)\n)\n\nconst isFolderLoading = computed(\n  () => isInFolderView.value && folderLoading.value\n)\n\nconst showLoadingState = computed(\n  () =>\n    (loading.value || isFolderLoading.value) && displayAssets.value.length === 0\n)\n\nconst showEmptyState = computed(\n  () =>\n    !loading.value &&\n    !isFolderLoading.value &&\n    !canLoadMoreAssets.value &&\n    displayAssets.value.length === 0\n)\n\nwatch(visibleAssets, (newAssets) => {\n  // Alternative: keep hidden selections and surface them in UI; for now prune\n  // so selection stays consistent with what this view can act on.\n  reconcileSelection(newAssets)\n  if (currentGalleryAssetId.value && galleryActiveIndex.value !== -1) {\n    const newIndex = previewableVisibleAssets.value.findIndex(\n      (asset) => asset.id === currentGalleryAssetId.value\n    )\n    galleryActiveIndex.value = newIndex\n  }\n})\n\nwatch(galleryActiveIndex, (index) => {\n  if (index === -1) {\n    currentGalleryAssetId.value = null\n  }\n})\n\nconst galleryItems = computed<AugmentedResultItem[]>(() => {\n  return previewableVisibleAssets.value.map((asset) => {\n    const mediaType = getMediaTypeFromFilename(asset.name)\n    return {\n      filename: asset.name,\n      subfolder: getAssetSubfolder(asset),\n      type: 'output',\n      nodeId: '0',\n      mediaType: mediaType === 'image' ? 'images' : mediaType,\n      url: asset.preview_url || ''\n    }\n  })\n})\n\nconst refreshAssets = async () => {\n  await currentAssets.value.invalidate()\n}\n\nwatch(\n  activeTab,\n  () => {\n    clearSelection()\n    // Clear search when switching tabs\n    searchQuery.value = ''\n    // Reset pagination state when tab changes\n    void refreshAssets()\n  },\n  { immediate: true }\n)\n\nfunction handleAssetSelect(asset: AssetItem, assets?: AssetItem[]) {\n  const assetList = assets ?? visibleAssets.value\n  const index = assetList.findIndex((a) => a.id === asset.id)\n  emit('assetSelected', asset)\n  handleAssetClick(asset, index, assetList)\n}\n\nfunction handleAssetSelectionToggle(asset: AssetItem) {\n  const index = visibleAssets.value.findIndex((item) => item.id === asset.id)\n  emit('assetSelected', asset)\n  toggleAssetSelection(asset, index, visibleAssets.value)\n}\n\nfunction handleAssetContextMenu(event: MouseEvent, asset: AssetItem) {\n  const assetType = getAssetType(asset.tags)\n  const canDelete =\n    shouldShowDeleteButton.value &&\n    (assetType === 'output' || (assetType === 'input' && isCloud))\n  const selection = selectedAssets.value\n  const isBulk = selection.length > 1 && isSelected(asset.id)\n\n  if (isBulk) {\n    contextMenuItems.value = [\n      {\n        label: t('mediaAsset.selection.multipleSelectedAssets'),\n        disabled: true\n      },\n      {\n        label: t('mediaAsset.selection.insertAllAssetsAsNodes'),\n        icon: 'icon-[comfy--node]',\n        command: () => handleBulkAddToWorkflow(selection)\n      },\n      {\n        label: t('mediaAsset.selection.openWorkflowAll'),\n        icon: 'icon-[comfy--workflow]',\n        command: () => handleBulkOpenWorkflow(selection)\n      },\n      {\n        label: t('mediaAsset.selection.exportWorkflowAll'),\n        icon: 'icon-[lucide--file-output]',\n        command: () => handleBulkExportWorkflow(selection)\n      },\n      {\n        label: t('mediaAsset.selection.downloadSelectedAll'),\n        icon: 'icon-[lucide--download]',\n        command: () => handleBulkDownload(selection)\n      },\n      {\n        label: t('mediaAsset.selection.deleteSelectedAll'),\n        icon: 'icon-[lucide--trash-2]',\n        visible: canDelete,\n        command: () => handleBulkDelete(selection)\n      }\n    ]\n  } else {\n    const hasWorkflow =\n      assetType === 'output' ||\n      (assetType === 'input' && supportsWorkflowMetadata(asset.name))\n    const hasJobId = assetType !== 'input'\n    contextMenuItems.value = [\n      {\n        label: t('mediaAsset.actions.inspect'),\n        icon: 'icon-[lucide--zoom-in]',\n        visible:\n          isPreviewableMediaType(getMediaTypeFromFilename(asset.name)) ||\n          isHdrImageFilename(asset.name),\n        command: () => handleZoomClick(asset)\n      },\n      {\n        label: t('mediaAsset.actions.insertAsNodeInWorkflow'),\n        icon: 'icon-[comfy--node]',\n        visible: detectNodeTypeFromFilename(asset.name).nodeType !== null,\n        command: () => addWorkflow(asset)\n      },\n      {\n        label: t('mediaAsset.actions.download'),\n        icon: 'icon-[lucide--download]',\n        command: () => downloadAssets([asset])\n      },\n      { separator: true, visible: hasWorkflow },\n      {\n        label: t('mediaAsset.actions.openWorkflow'),\n        icon: 'icon-[comfy--workflow]',\n        visible: hasWorkflow,\n        command: () => openWorkflow(asset)\n      },\n      {\n        label: t('mediaAsset.actions.exportWorkflow'),\n        icon: 'icon-[lucide--file-output]',\n        visible: hasWorkflow,\n        command: () => exportWorkflow(asset)\n      },\n      { separator: true, visible: hasJobId },\n      {\n        label: t('mediaAsset.actions.copyJobId'),\n        icon: 'icon-[lucide--copy]',\n        visible: hasJobId,\n        command: () => copyJobId(asset)\n      },\n      { separator: true, visible: canDelete },\n      {\n        label: t('mediaAsset.actions.delete'),\n        icon: 'icon-[lucide--trash-2]',\n        visible: canDelete,\n        command: async () => {\n          if (await deleteAssets(asset)) await refreshAssets()\n        }\n      }\n    ]\n  }\n  contextMenuRef.value?.show(event)\n}\n\nconst handleBulkDownload = (assets: AssetItem[]) => {\n  downloadAssets(assets)\n  clearSelection()\n}\n\nconst handleBulkDelete = async (assets: AssetItem[]) => {\n  if (await deleteAssets(assets)) {\n    clearSelection()\n  }\n}\n\nconst handleBulkAddToWorkflow = async (assets: AssetItem[]) => {\n  await addMultipleToWorkflow(assets)\n  clearSelection()\n}\n\nconst handleBulkOpenWorkflow = async (assets: AssetItem[]) => {\n  await openMultipleWorkflows(assets)\n  clearSelection()\n}\n\nconst handleBulkExportWorkflow = async (assets: AssetItem[]) => {\n  await exportMultipleWorkflows(assets)\n  clearSelection()\n}\n\nconst handleZoomClick = (asset: AssetItem) => {\n  if (isHdrImageFilename(asset.name)) {\n    openHdrViewer(getAssetViewUrl(asset))\n    return\n  }\n\n  const mediaType = getMediaTypeFromFilename(asset.name)\n  if (!isPreviewableMediaType(mediaType)) {\n    return\n  }\n\n  if (mediaType === '3D') {\n    const dialogStore = useDialogStore()\n    dialogStore.showDialog({\n      key: 'asset-3d-viewer',\n      title: getAssetDisplayName(asset),\n      component: Load3dViewerContent,\n      props: {\n        modelUrl: getAssetFileUrl(asset)\n      },\n      dialogComponentProps: LOAD3D_VIEWER_DIALOG_PROPS\n    })\n    return\n  }\n\n  currentGalleryAssetId.value = asset.id\n  const index = previewableVisibleAssets.value.findIndex(\n    (a) => a.id === asset.id\n  )\n  if (index !== -1) {\n    galleryActiveIndex.value = index\n  }\n}\n\nconst enterFolderView = async (asset: AssetItem) => {\n  const metadata = getOutputAssetMetadata(asset.user_metadata)\n  if (!metadata) {\n    console.warn('Invalid output asset metadata')\n    return\n  }\n\n  const { jobId, executionTimeInSeconds } = metadata\n\n  if (!jobId) {\n    console.warn('Missing required folder view data')\n    return\n  }\n\n  folderJobId.value = jobId\n  folderExecutionTime.value = executionTimeInSeconds\n  expectedFolderCount.value = metadata.outputCount ?? 0\n\n  await loadFolderAssets(0, metadata, { createdAt: asset.created_at })\n\n  if (folderError.value) {\n    toast.error(t('sideToolbar.folderView.errorSummary'), {\n      description: t('sideToolbar.folderView.errorDetail')\n    })\n    exitFolderView()\n  }\n}\n\nconst exitFolderView = () => {\n  folderJobId.value = null\n  folderExecutionTime.value = undefined\n  expectedFolderCount.value = 0\n  folderAssets.value = []\n  searchQuery.value = ''\n}\n\nonMounted(() => {\n  activateSelection()\n})\n\nonUnmounted(() => {\n  deactivateSelection()\n})\n\nconst handleDeselectAll = () => {\n  clearSelection()\n}\n\nconst handleEmptySpaceClick = () => {\n  if (hasSelection.value) {\n    clearSelection()\n  }\n}\n\nconst copyFolderJobId = async () => {\n  if (folderJobId.value) {\n    try {\n      await navigator.clipboard.writeText(folderJobId.value)\n      toast.success(t('mediaAsset.jobIdToast.copied'), {\n        description: t('mediaAsset.jobIdToast.jobIdCopied'),\n        duration: 2000\n      })\n    } catch (error) {\n      toast.error(t('mediaAsset.jobIdToast.error'), {\n        description: t('mediaAsset.jobIdToast.jobIdCopyFailed')\n      })\n    }\n  }\n}\n\nconst loadMoreAssets = () => currentAssets.value.loadMore()\nconst canLoadMoreAssets = computed(\n  () => !isInFolderView.value && toValue(currentAssets.value.hasMore)\n)\n</script>\n","import { defineStore } from 'pinia'\nimport { ref, watch } from 'vue'\n\nimport type { TaskItemImpl } from '@/stores/queueStore'\nimport { useQueueStore } from '@/stores/queueStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\n\nconst getAddedAssetCount = (task: TaskItemImpl): number => {\n  const count = task.previewableOutputsCount ?? task.outputsCount\n  if (typeof count === 'number') {\n    return Math.max(count, 0)\n  }\n\n  return task.previewOutput ? 1 : 0\n}\n\nexport const useAssetsSidebarBadgeStore = defineStore(\n  'assetsSidebarBadge',\n  () => {\n    const queueStore = useQueueStore()\n    const sidebarTabStore = useSidebarTabStore()\n\n    const unseenAddedAssetsCount = ref(0)\n    const countedHistoryAssetsByJobId = ref(new Map<string, number>())\n    const hasInitializedHistory = ref(false)\n\n    const markCurrentHistoryAsSeen = () => {\n      countedHistoryAssetsByJobId.value = new Map(\n        queueStore.historyTasks.map((task) => [\n          task.jobId,\n          getAddedAssetCount(task)\n        ])\n      )\n    }\n\n    watch(\n      () =>\n        [\n          queueStore.historyTasks,\n          queueStore.hasFetchedHistorySnapshot\n        ] as const,\n      ([historyTasks, hasFetchedHistorySnapshot]) => {\n        if (!hasFetchedHistorySnapshot) {\n          return\n        }\n\n        if (!hasInitializedHistory.value) {\n          hasInitializedHistory.value = true\n          markCurrentHistoryAsSeen()\n          return\n        }\n\n        const isAssetsTabOpen = sidebarTabStore.activeSidebarTabId === 'assets'\n        const previousCountedAssetsByJobId = countedHistoryAssetsByJobId.value\n        const nextCountedAssetsByJobId = new Map<string, number>()\n\n        for (const task of historyTasks) {\n          const jobId = task.jobId\n          if (!jobId) {\n            continue\n          }\n\n          const countedAssets = previousCountedAssetsByJobId.get(jobId) ?? 0\n          const currentAssets = getAddedAssetCount(task)\n          const hasSeenJob = previousCountedAssetsByJobId.has(jobId)\n\n          if (!isAssetsTabOpen && !hasSeenJob) {\n            unseenAddedAssetsCount.value += currentAssets\n          } else if (!isAssetsTabOpen && currentAssets > countedAssets) {\n            unseenAddedAssetsCount.value += currentAssets - countedAssets\n          }\n\n          nextCountedAssetsByJobId.set(\n            jobId,\n            Math.max(countedAssets, currentAssets)\n          )\n        }\n\n        countedHistoryAssetsByJobId.value = nextCountedAssetsByJobId\n      },\n      { immediate: true }\n    )\n\n    watch(\n      () => sidebarTabStore.activeSidebarTabId,\n      (activeSidebarTabId) => {\n        if (activeSidebarTabId !== 'assets') {\n          return\n        }\n\n        unseenAddedAssetsCount.value = 0\n        markCurrentHistoryAsSeen()\n      }\n    )\n\n    return {\n      unseenAddedAssetsCount\n    }\n  }\n)\n","import { markRaw } from 'vue'\n\nimport AssetsSidebarTab from '@/components/sidebar/tabs/AssetsSidebarTab.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useAssetsSidebarBadgeStore } from '@/stores/workspace/assetsSidebarBadgeStore'\nimport type { SidebarTabExtension } from '@/types/extensionTypes'\n\nexport const useAssetsSidebarTab = (): SidebarTabExtension => {\n  return {\n    id: 'assets',\n    icon: 'icon-[comfy--image-ai-edit]',\n    title: 'sideToolbar.assets',\n    tooltip: 'sideToolbar.assets',\n    label: 'sideToolbar.labels.assets',\n    component: markRaw(AssetsSidebarTab),\n    type: 'vue',\n    iconBadge: () => {\n      const settingStore = useSettingStore()\n\n      if (!settingStore.get('Comfy.Queue.QPOV2')) {\n        return null\n      }\n\n      const assetsSidebarBadgeStore = useAssetsSidebarBadgeStore()\n      const count = assetsSidebarBadgeStore.unseenAddedAssetsCount\n      return count > 0 ? count.toString() : null\n    }\n  }\n}\n","<template>\n  <SidebarTabTemplate\n    data-testid=\"job-history-sidebar\"\n    :title=\"$t('queue.jobHistory')\"\n  >\n    <template #tool-buttons>\n      <JobHistoryActionsMenu @clear-history=\"onClearHistory\" />\n    </template>\n    <template #header>\n      <div class=\"overflow-x-auto px-4 pt-2 pb-px\">\n        <TabList\n          :aria-label=\"$t('queue.jobHistory')\"\n          :model-value=\"selectedJobTab\"\n          @update:model-value=\"onUpdateSelectedJobTab\"\n        >\n          <Tab v-for=\"tab in visibleJobTabs\" :key=\"tab\" :value=\"tab\">\n            {{ t(jobTabLabelKeys[tab]) }}\n          </Tab>\n        </TabList>\n      </div>\n      <JobFilterActions\n        v-model:selected-workflow-filter=\"selectedWorkflowFilter\"\n        v-model:selected-sort-mode=\"selectedSortMode\"\n        v-model:search-query=\"searchQuery\"\n        class=\"px-4 py-2\"\n        :hide-show-assets-action=\"true\"\n        :show-search=\"true\"\n        :search-placeholder=\"t('g.searchPlaceholder', { subject: t('g.jobs') })\"\n      />\n      <div\n        class=\"flex items-center justify-between px-4 pb-2 text-xs leading-none text-text-primary\"\n      >\n        <span class=\"text-text-secondary\">{{ activeQueueSummary }}</span>\n        <div class=\"flex items-center gap-2\">\n          <span class=\"text-xs text-base-foreground\">\n            {{ t('sideToolbar.queueProgressOverlay.clearQueueTooltip') }}\n          </span>\n          <Button\n            variant=\"destructive\"\n            size=\"icon\"\n            :aria-label=\"\n              t('sideToolbar.queueProgressOverlay.clearQueueTooltip')\n            \"\n            :disabled=\"queuedCount === 0\"\n            @click=\"clearQueuedWorkflows\"\n          >\n            <i class=\"icon-[lucide--list-x] size-4\" />\n          </Button>\n        </div>\n      </div>\n    </template>\n    <template #body>\n      <div class=\"flex h-full min-h-0 flex-col\">\n        <div\n          :id=\"`tabpanel-${selectedJobTab}`\"\n          role=\"tabpanel\"\n          :aria-labelledby=\"`tab-${selectedJobTab}`\"\n          class=\"flex min-h-0 flex-1 flex-col\"\n        >\n          <JobAssetsList\n            class=\"scrollbar-custom min-h-0 flex-1\"\n            :displayed-job-groups=\"displayedJobGroups\"\n            @cancel-item=\"onCancelItem\"\n            @delete-item=\"onDeleteItem\"\n            @view-item=\"onViewItem\"\n            @menu=\"onMenuItem\"\n          />\n        </div>\n        <ContextMenu ref=\"jobContextMenuRef\" :model=\"jobMenuEntries\" />\n        <MediaLightbox\n          v-model:active-index=\"galleryActiveIndex\"\n          :all-gallery-items=\"galleryItems\"\n        />\n      </div>\n    </template>\n  </SidebarTabTemplate>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, defineAsyncComponent, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { LOAD3D_VIEWER_DIALOG_PROPS } from '@/components/load3d/load3dViewerDialog'\nimport JobFilterActions from '@/components/queue/job/JobFilterActions.vue'\nimport JobAssetsList from '@/components/queue/job/JobAssetsList.vue'\nimport JobHistoryActionsMenu from '@/components/queue/JobHistoryActionsMenu.vue'\nimport ContextMenu from '@/components/ui/menu/ContextMenu.vue'\nimport { useJobMenu } from '@/composables/queue/useJobMenu'\nimport { getVisibleJobTabs, jobTabLabelKeys } from '@/composables/queue/jobTabs'\nimport type { JobTab } from '@/composables/queue/jobTabs'\nimport { useJobList } from '@/composables/queue/useJobList'\nimport type { JobListItem } from '@/composables/queue/useJobList'\nimport { useQueueClearHistoryDialog } from '@/composables/queue/useQueueClearHistoryDialog'\nimport { useResultGallery } from '@/composables/queue/useResultGallery'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport SidebarTabTemplate from '@/components/sidebar/tabs/SidebarTabTemplate.vue'\nimport MediaLightbox from '@/components/sidebar/tabs/queue/MediaLightbox.vue'\nimport Tab from '@/components/tab/Tab.vue'\nimport TabList from '@/components/tab/TabList.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useSurveyFeatureTracking } from '@/platform/surveys/useSurveyFeatureTracking'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useQueueStore } from '@/stores/queueStore'\nimport { is3DResult } from '@/utils/resultItem'\n\nconst Load3dViewerContent = defineAsyncComponent(\n  () => import('@/components/load3d/Load3dViewerContent.vue')\n)\n\nconst { t, n } = useI18n()\nconst commandStore = useCommandStore()\nconst dialogStore = useDialogStore()\nconst executionStore = useExecutionStore()\nconst queueStore = useQueueStore()\nconst { showQueueClearHistoryDialog } = useQueueClearHistoryDialog()\nconst { wrapWithErrorHandlingAsync } = useErrorHandling()\nconst { trackFeatureUsed } = useSurveyFeatureTracking('queue-progress-overlay')\n\nconst onClearHistory = () => {\n  trackFeatureUsed()\n  showQueueClearHistoryDialog()\n}\n\nconst onUpdateSelectedJobTab = (value: JobTab) => {\n  trackFeatureUsed()\n  selectedJobTab.value = value\n}\nconst {\n  selectedJobTab,\n  selectedWorkflowFilter,\n  selectedSortMode,\n  searchQuery,\n  hasFailedJobs,\n  filteredTasks,\n  groupedJobItems\n} = useJobList()\n\nconst visibleJobTabs = computed(() => getVisibleJobTabs(hasFailedJobs.value))\n\nconst displayedJobGroups = computed(() => groupedJobItems.value)\nconst runningCount = computed(() => queueStore.runningTasks.length)\nconst queuedCount = computed(() => queueStore.pendingTasks.length)\n\nconst runningJobsLabel = computed(() =>\n  t('sideToolbar.queueProgressOverlay.runningJobsLabel', {\n    count: n(runningCount.value)\n  })\n)\nconst queuedJobsLabel = computed(() =>\n  t('sideToolbar.queueProgressOverlay.queuedJobsLabel', {\n    count: n(queuedCount.value)\n  })\n)\nconst activeQueueSummary = computed(() => {\n  if (runningCount.value === 0 && queuedCount.value === 0) {\n    return t('sideToolbar.queueProgressOverlay.noActiveJobs')\n  }\n  if (queuedCount.value === 0) {\n    return runningJobsLabel.value\n  }\n  if (runningCount.value === 0) {\n    return queuedJobsLabel.value\n  }\n  return t('sideToolbar.queueProgressOverlay.runningQueuedSummary', {\n    running: runningJobsLabel.value,\n    queued: queuedJobsLabel.value\n  })\n})\n\nconst clearQueuedWorkflows = wrapWithErrorHandlingAsync(async () => {\n  trackFeatureUsed()\n  const pendingJobIds = queueStore.pendingTasks\n    .map((task) => task.jobId)\n    .filter((id): id is string => typeof id === 'string' && id.length > 0)\n\n  await commandStore.execute('Comfy.ClearPendingTasks')\n  executionStore.clearInitializationByJobIds(pendingJobIds)\n})\n\nconst {\n  galleryActiveIndex,\n  galleryItems,\n  onViewItem: openResultGallery\n} = useResultGallery(() => filteredTasks.value)\n\nconst onViewItem = wrapWithErrorHandlingAsync(async (item: JobListItem) => {\n  trackFeatureUsed()\n  const previewOutput = item.taskRef?.previewOutput\n\n  if (previewOutput && is3DResult(previewOutput)) {\n    dialogStore.showDialog({\n      key: 'asset-3d-viewer',\n      title: item.title,\n      component: Load3dViewerContent,\n      props: {\n        modelUrl: previewOutput.url || ''\n      },\n      dialogComponentProps: LOAD3D_VIEWER_DIALOG_PROPS\n    })\n    return\n  }\n\n  await openResultGallery(item)\n})\n\nconst onInspectAsset = (item: JobListItem) => {\n  void onViewItem(item)\n}\n\nconst currentMenuItem = ref<JobListItem | null>(null)\nconst jobContextMenuRef = ref<InstanceType<typeof ContextMenu> | null>(null)\n\nconst { jobMenuEntries, cancelJob } = useJobMenu(\n  () => currentMenuItem.value,\n  onInspectAsset\n)\nconst onCancelItem = wrapWithErrorHandlingAsync(async (item: JobListItem) => {\n  trackFeatureUsed()\n  await cancelJob(item)\n})\n\nconst onDeleteItem = wrapWithErrorHandlingAsync(async (item: JobListItem) => {\n  trackFeatureUsed()\n  if (!item.taskRef) return\n  await queueStore.delete(item.taskRef)\n})\n\nconst onMenuItem = (item: JobListItem, event: Event) => {\n  const isSameClickTarget =\n    event.type === 'click' && currentMenuItem.value?.id === item.id\n  currentMenuItem.value = item\n  if (isSameClickTarget) jobContextMenuRef.value?.toggle(event)\n  else jobContextMenuRef.value?.show(event)\n}\n</script>\n","import { markRaw } from 'vue'\n\nimport JobHistorySidebarTab from '@/components/sidebar/tabs/JobHistorySidebarTab.vue'\nimport { useQueueStore } from '@/stores/queueStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\nimport type { SidebarTabExtension } from '@/types/extensionTypes'\n\nexport const useJobHistorySidebarTab = (): SidebarTabExtension => {\n  return {\n    id: 'job-history',\n    icon: 'icon-[lucide--history]',\n    title: 'queue.jobHistory',\n    tooltip: 'queue.jobHistory',\n    label: 'queue.jobHistory',\n    component: markRaw(JobHistorySidebarTab),\n    type: 'vue',\n    iconBadge: () => {\n      const sidebarTabStore = useSidebarTabStore()\n      if (sidebarTabStore.activeSidebarTabId === 'job-history') {\n        return null\n      }\n\n      const queueStore = useQueueStore()\n      const count = queueStore.activeJobsCount\n      return count > 0 ? count.toString() : null\n    }\n  }\n}\n","import type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport type { NodeCategoryId } from '@/types/nodeOrganizationTypes'\nimport type { InjectionKey, ModelRef, Ref } from 'vue'\n\nimport type { MenuItem } from '@/components/ui/menu/types'\n\nexport interface TreeNode<T = unknown> {\n  key: string\n  label: string\n  children?: this[]\n  data?: T\n  icon?: string\n  leaf?: boolean\n}\n\nexport interface NodeLibrarySection<T = unknown> {\n  category?: NodeCategoryId\n  title?: string\n  root: RenderedTreeExplorerNode<T>\n}\n\nexport interface TreeExplorerNode<T = unknown> extends TreeNode<T> {\n  /** Extra context menu items */\n  contextMenuItems?:\n    | MenuItem[]\n    | ((targetNode: RenderedTreeExplorerNode<T>) => MenuItem[])\n  /** Whether the node is draggable */\n  draggable?: boolean\n  /** Whether the node is droppable */\n  droppable?: boolean\n  /**\n   * Function to override what text to use for the leaf-count badge on a folder node.\n   * Return undefined to fallback to default badge text, which is the subtree's leaf count.\n   * Return empty string to hide the badge.\n   */\n  getBadgeText?: (this: TreeExplorerNode<T>) => string | undefined\n  /**\n   * Function to override what icon to use for the node.\n   * Return undefined to fallback to {@link icon} property.\n   */\n  getIcon?: (this: TreeExplorerNode<T>) => string | undefined\n  getIconColor?: (this: TreeExplorerNode<T>) => string | undefined\n  getIconImage?: (this: TreeExplorerNode<T>) => string | undefined\n  /** Function to handle adding a folder */\n  handleAddFolder?: (\n    this: TreeExplorerNode<T>,\n    folderName: string\n  ) => void | Promise<void>\n  /** Function to handle clicking a node */\n  handleClick?: (\n    this: TreeExplorerNode<T>,\n    event: MouseEvent\n  ) => void | Promise<void>\n  /** Function to handle deleting the node */\n  handleDelete?: (this: TreeExplorerNode<T>) => void | Promise<void>\n  /** Function to handle dropping a node */\n  handleDrop?: (\n    this: TreeExplorerNode<T>,\n    data: TreeExplorerDragAndDropData<T>\n  ) => void | Promise<void>\n  /** Function to handle errors */\n  handleError?: (this: TreeExplorerNode<T>, error: unknown) => void\n  /** Function to handle renaming the node */\n  handleRename?: (\n    this: TreeExplorerNode<T>,\n    newName: string\n  ) => void | Promise<void>\n  /** Function to render a drag preview */\n  renderDragPreview?: (\n    this: TreeExplorerNode<T>,\n    container: HTMLElement\n  ) => void | (() => void)\n}\n\nexport interface RenderedTreeExplorerNode<\n  T = unknown\n> extends TreeExplorerNode<T> {\n  icon: string\n  /** Total number of leaves in the subtree */\n  totalLeaves: number\n  type: 'folder' | 'node'\n  /** Text to display on the leaf-count badge. Empty string means no badge. */\n  badgeText?: string\n  iconColor?: string\n  iconImage?: string\n  /** Whether the node label is currently being edited */\n  isEditingLabel?: boolean\n}\n\nexport type TreeExplorerDragAndDropData<T = unknown> = {\n  type: 'tree-explorer-node'\n  data: RenderedTreeExplorerNode<T>\n}\n\nexport const InjectKeyHandleEditLabelFunction: InjectionKey<\n  (node: RenderedTreeExplorerNode, newName: string) => void\n> = Symbol()\n\nexport const InjectKeyExpandedKeys: InjectionKey<\n  ModelRef<Record<string, boolean>>\n> = Symbol()\n\nexport const InjectKeyContextMenuNode: InjectionKey<\n  Ref<RenderedTreeExplorerNode<ComfyNodeDefImpl> | null>\n> = Symbol()\n","<template>\n  <div\n    ref=\"container\"\n    :class=\"\n      cn(\n        'tree-node flex w-full items-center justify-between rounded-sm',\n        canDrop && 'ring-1 ring-base-foreground ring-inset'\n      )\n    \"\n    :data-testid=\"`tree-node-${node.key}`\"\n  >\n    <div class=\"node-content flex min-w-0 flex-1 items-center\">\n      <span class=\"node-label block min-w-0 truncate\">\n        <slot name=\"before-label\" :node=\"node\" />\n        <EditableText\n          :model-value=\"node.label\"\n          :is-editing=\"isEditing\"\n          @edit=\"handleRename\"\n        />\n        <slot name=\"after-label\" :node=\"node\" />\n      </span>\n      <Badge\n        v-if=\"showNodeBadgeText\"\n        variant=\"badge\"\n        severity=\"secondary\"\n        class=\"ml-2\"\n        data-testid=\"tree-leaf-count\"\n      >\n        {{ nodeBadgeText }}\n      </Badge>\n    </div>\n    <div\n      class=\"node-actions flex gap-1 motion-safe:opacity-0 motion-safe:group-focus-within/tree-node:opacity-100 motion-safe:group-hover/tree-node:opacity-100 touch:opacity-100\"\n    >\n      <slot name=\"actions\" :node=\"node\" />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\" generic=\"T\">\nimport { setCustomNativeDragPreview } from '@atlaskit/pragmatic-drag-and-drop/element/set-custom-native-drag-preview'\nimport { computed, inject, ref } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport EditableText from '@/components/common/EditableText.vue'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport {\n  usePragmaticDraggable,\n  usePragmaticDroppable\n} from '@/composables/usePragmaticDragAndDrop'\nimport {\n  InjectKeyExpandedKeys,\n  InjectKeyHandleEditLabelFunction\n} from '@/types/treeExplorerTypes'\nimport type {\n  RenderedTreeExplorerNode,\n  TreeExplorerDragAndDropData\n} from '@/types/treeExplorerTypes'\n\nconst { node } = defineProps<{\n  node: RenderedTreeExplorerNode<T>\n}>()\n\nconst emit = defineEmits<{\n  (e: 'dragStart', node: RenderedTreeExplorerNode<T>): void\n  (e: 'dragEnd', node: RenderedTreeExplorerNode<T>): void\n}>()\n\nconst nodeBadgeText = computed<string>(() => {\n  if (node.leaf) {\n    return ''\n  }\n  if (node.badgeText !== undefined && node.badgeText !== null) {\n    return node.badgeText\n  }\n  return node.totalLeaves.toString()\n})\nconst showNodeBadgeText = computed<boolean>(() => nodeBadgeText.value !== '')\n\nconst isEditing = computed<boolean>(() => node.isEditingLabel ?? false)\nconst handleEditLabel = inject(InjectKeyHandleEditLabelFunction)\nconst expandedKeys = inject(InjectKeyExpandedKeys)\nconst handleRename = (newName: string) => {\n  handleEditLabel?.(node as RenderedTreeExplorerNode, newName)\n}\n\nconst container = ref<HTMLElement | null>(null)\nconst canDrop = ref(false)\n\nconst treeNodeElementGetter = () =>\n  container.value?.closest<HTMLElement>('.tree-explorer-item') ?? null\n\nif (node.draggable) {\n  usePragmaticDraggable(treeNodeElementGetter, {\n    getInitialData: () => {\n      return {\n        type: 'tree-explorer-node',\n        data: node\n      }\n    },\n    onDragStart: () => emit('dragStart', node),\n    onDrop: () => emit('dragEnd', node),\n    onGenerateDragPreview: node.renderDragPreview\n      ? ({ nativeSetDragImage }) => {\n          setCustomNativeDragPreview({\n            render: ({ container }) => {\n              return node.renderDragPreview?.(container)\n            },\n            nativeSetDragImage\n          })\n        }\n      : undefined\n  })\n}\n\nif (node.droppable) {\n  usePragmaticDroppable(treeNodeElementGetter, {\n    onDrop: async (event) => {\n      const dndData = event.source.data as TreeExplorerDragAndDropData\n      if (dndData.type === 'tree-explorer-node') {\n        await node.handleDrop?.(dndData as TreeExplorerDragAndDropData<T>)\n        canDrop.value = false\n        if (expandedKeys) {\n          expandedKeys.value = { ...expandedKeys.value, [node.key]: true }\n        }\n      }\n    },\n    onDragEnter: (event) => {\n      const dndData = event.source.data as TreeExplorerDragAndDropData\n      if (dndData.type === 'tree-explorer-node') {\n        canDrop.value = true\n      }\n    },\n    onDragLeave: () => {\n      canDrop.value = false\n    }\n  })\n}\n</script>\n","<template>\n  <TreeRoot\n    v-slot=\"{ flattenItems }\"\n    v-bind=\"forwarded\"\n    v-model=\"selected\"\n    v-model:expanded=\"expanded\"\n    :class=\"cn('m-0 min-h-px min-w-0 list-none p-0', className)\"\n  >\n    <slot :flatten-items />\n  </TreeRoot>\n</template>\n\n<script setup lang=\"ts\" generic=\"T extends object\">\nimport type { TreeRootProps } from 'reka-ui'\nimport { TreeRoot, useForwardProps } from 'reka-ui'\nimport type { HTMLAttributes } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { class: className, ...restProps } = defineProps<\n  Omit<\n    TreeRootProps<T>,\n    | 'bubbleSelect'\n    | 'defaultExpanded'\n    | 'defaultValue'\n    | 'disabled'\n    | 'expanded'\n    | 'modelValue'\n    | 'multiple'\n    | 'propagateSelect'\n  > & {\n    class?: HTMLAttributes['class']\n  }\n>()\n\nconst forwarded = useForwardProps(restProps)\n\nconst expanded = defineModel<string[]>('expanded', { required: true })\nconst selected = defineModel<T>('selected')\n</script>\n","export const treeItemClass =\n  'group/tree-node flex w-full min-w-0 cursor-pointer items-center gap-3 rounded-sm py-(--tree-item-padding,--spacing(2)) pr-2 text-sm text-base-foreground outline-none select-none hover:bg-secondary-background-hover focus-visible:bg-secondary-background-hover data-selected:bg-secondary-background-selected'\n\nexport function treeItemIndent(level: number) {\n  return { paddingLeft: `${8 + (level - 1) * 24}px` }\n}\n","<template>\n  <RekaTreeItem\n    ref=\"item\"\n    v-slot=\"{ isExpanded, handleToggle }\"\n    v-bind=\"forwarded\"\n    :class=\"cn(treeItemClass, className)\"\n    :style=\"treeItemIndent(restProps.level)\"\n    @select=\"emits('select', $event)\"\n    @toggle=\"preventClickToggle\"\n  >\n    <Button\n      v-if=\"hasChildren\"\n      type=\"button\"\n      variant=\"muted-textonly\"\n      size=\"icon-sm\"\n      tabindex=\"-1\"\n      aria-hidden=\"true\"\n      class=\"shrink-0\"\n      @click.stop=\"handleToggle\"\n    >\n      <i\n        :class=\"\n          cn(\n            'icon-[lucide--chevron-right] size-4 shrink-0 transition-transform',\n            isExpanded && 'rotate-90'\n          )\n        \"\n      />\n    </Button>\n    <span v-else class=\"size-5 shrink-0\" />\n    <div class=\"contents\" @keydown=\"keepKeysInEditableContent\">\n      <slot :is-hovered />\n    </div>\n  </RekaTreeItem>\n</template>\n\n<script setup lang=\"ts\" generic=\"T extends object\">\nimport type { TreeItemEmits, TreeItemProps, TreeItemToggleEvent } from 'reka-ui'\nimport {\n  TreeItem as RekaTreeItem,\n  injectTreeRootContext,\n  useForwardProps\n} from 'reka-ui'\nimport { useElementHover } from '@vueuse/core'\nimport type { HTMLAttributes } from 'vue'\nimport { computed, useTemplateRef } from 'vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { treeItemClass, treeItemIndent } from '@/components/ui/tree/treeStyles'\n\nconst { class: className, ...restProps } = defineProps<\n  Omit<TreeItemProps<T>, 'as' | 'asChild'> & {\n    class?: HTMLAttributes['class']\n  }\n>()\n\nconst emits = defineEmits<TreeItemEmits<T>>()\n\nconst forwarded = useForwardProps(restProps)\n\nconst isHovered = useElementHover(useTemplateRef('item'))\n\nconst rootContext = injectTreeRootContext()\nconst hasChildren = computed(() => !!rootContext.getChildren(restProps.value))\n\nconst NAVIGATION_KEYS = new Set([\n  'ArrowDown',\n  'ArrowLeft',\n  'ArrowRight',\n  'ArrowUp',\n  'End',\n  'Home'\n])\n\nfunction isShortcut(event: KeyboardEvent) {\n  return (event.ctrlKey || event.metaKey) && !NAVIGATION_KEYS.has(event.key)\n}\n\nfunction keepKeysInEditableContent(event: KeyboardEvent) {\n  if (\n    event.target instanceof HTMLElement &&\n    event.target.matches('input, textarea') &&\n    !isShortcut(event)\n  ) {\n    event.stopPropagation()\n  }\n}\n\nfunction preventClickToggle(event: TreeItemToggleEvent<T>) {\n  if (!(event.detail.originalEvent instanceof KeyboardEvent)) {\n    event.preventDefault()\n  }\n  emits('toggle', event)\n}\n</script>\n","import { shallowRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport type { RenderedTreeExplorerNode } from '@/types/treeExplorerTypes'\n\n/**\n * Use this to handle folder operations in a tree.\n * @param expandNode - The function to expand a node.\n */\nexport function useTreeFolderOperations<T>(\n  expandNode: (node: RenderedTreeExplorerNode<T>) => void\n) {\n  const { t } = useI18n()\n  const newFolderNode = shallowRef<RenderedTreeExplorerNode<T> | null>(null)\n  const addFolderTargetNode = shallowRef<RenderedTreeExplorerNode<T> | null>(\n    null\n  )\n\n  // Generate a unique temporary key for the new folder\n  const generateTempKey = (parentKey: string) => {\n    return `${parentKey}/new_folder_${Date.now()}`\n  }\n\n  // Handle folder creation after name is confirmed\n  const handleFolderCreation = async (newName: string) => {\n    if (!newFolderNode.value || !addFolderTargetNode.value) return\n\n    try {\n      // Call the handleAddFolder method with the new folder name\n      await addFolderTargetNode.value.handleAddFolder?.(newName)\n    } finally {\n      newFolderNode.value = null\n      addFolderTargetNode.value = null\n    }\n  }\n\n  /**\n   * The command to add a folder to a node via the context menu\n   * @param targetNode - The node where the folder will be added under\n   */\n  const addFolderCommand = (targetNode: RenderedTreeExplorerNode<T>) => {\n    expandNode(targetNode)\n    newFolderNode.value = {\n      key: generateTempKey(targetNode.key),\n      label: '',\n      leaf: false,\n      children: [],\n      icon: 'pi pi-folder',\n      type: 'folder',\n      totalLeaves: 0,\n      badgeText: '',\n      isEditingLabel: true\n    }\n    addFolderTargetNode.value = targetNode\n  }\n\n  // Generate the \"Add Folder\" menu item\n  const getAddFolderMenuItem = (\n    targetNode: RenderedTreeExplorerNode<T> | null\n  ): MenuItem => {\n    return {\n      label: t('g.newFolder'),\n      icon: 'pi pi-folder-plus',\n      command: () => {\n        if (targetNode) addFolderCommand(targetNode)\n      },\n      visible: !!targetNode && !targetNode.leaf && !!targetNode.handleAddFolder\n    }\n  }\n\n  return {\n    newFolderNode,\n    addFolderCommand,\n    getAddFolderMenuItem,\n    handleFolderCreation\n  }\n}\n","<template>\n  <UiTree\n    v-bind=\"$attrs\"\n    v-model:expanded=\"expandedNodeKeys\"\n    v-model:selected=\"selectedNode\"\n    :class=\"cn('tree-explorer px-2', className)\"\n    :items=\"renderedRoot.children ?? []\"\n    :get-key=\"(node) => node.key\"\n    :get-children=\"(node) => (node.leaf ? undefined : (node.children ?? []))\"\n  >\n    <template #default=\"{ flattenItems }\">\n      <UiTreeItem\n        v-for=\"item in flattenItems\"\n        v-slot=\"{ isHovered }\"\n        :key=\"item._id\"\n        class=\"tree-explorer-item\"\n        :value=\"item.value\"\n        :level=\"item.level\"\n        :aria-label=\"item.value.label\"\n        :data-parent-label=\"item.parentItem?.label\"\n        :data-tree-node-type=\"item.value.type\"\n        @select=\"preventUnboundSelection\"\n        @click=\"onNodeContentClick($event, item.value)\"\n        @contextmenu=\"handleContextMenu($event, item.value)\"\n      >\n        <span class=\"relative size-4 shrink-0\">\n          <i\n            :class=\"\n              cn(\n                item.value.icon,\n                'tree-explorer-node-icon size-4 text-muted-foreground'\n              )\n            \"\n            :style=\"{ color: item.value.iconColor }\"\n          />\n          <span\n            v-if=\"item.value.iconImage\"\n            data-testid=\"tree-node-icon-image\"\n            class=\"absolute inset-0 rounded-xs bg-cover bg-center\"\n            :style=\"{ backgroundImage: `url(${item.value.iconImage})` }\"\n          />\n        </span>\n        <div class=\"flex min-w-0 flex-1 items-center\">\n          <slot\n            v-if=\"item.value.type === 'folder'\"\n            name=\"folder\"\n            :node=\"item.value\"\n          >\n            <TreeExplorerTreeNode :node=\"item.value\" />\n          </slot>\n          <slot v-else name=\"node\" :node=\"item.value\">\n            <TreeExplorerTreeNode :node=\"item.value\" />\n          </slot>\n        </div>\n        <div\n          v-if=\"isHovered && item.value.leaf && $slots.preview\"\n          ref=\"preview\"\n          data-testid=\"tree-item-preview\"\n          class=\"pointer-events-none fixed z-1001\"\n          :style=\"previewStyle\"\n        >\n          <slot name=\"preview\" :node=\"item.value\" />\n        </div>\n      </UiTreeItem>\n    </template>\n  </UiTree>\n  <ContextMenu ref=\"menu\" :model=\"menuItems\" />\n</template>\n<script setup lang=\"ts\" generic=\"T\">\nimport { useElementBounding, useElementSize, useWindowSize } from '@vueuse/core'\nimport { computed, provide, ref, shallowRef, useTemplateRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport TreeExplorerTreeNode from '@/components/common/TreeExplorerTreeNode.vue'\nimport ContextMenu from '@/components/ui/menu/ContextMenu.vue'\nimport type { MenuItem, MenuItemCommandEvent } from '@/components/ui/menu/types'\nimport UiTree from '@/components/ui/tree/Tree.vue'\nimport UiTreeItem from '@/components/ui/tree/TreeItem.vue'\nimport { useTreeFolderOperations } from '@/composables/tree/useTreeFolderOperations'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport {\n  InjectKeyExpandedKeys,\n  InjectKeyHandleEditLabelFunction\n} from '@/types/treeExplorerTypes'\nimport type {\n  RenderedTreeExplorerNode,\n  TreeExplorerNode\n} from '@/types/treeExplorerTypes'\nimport { combineTrees, findNodeByKey } from '@/utils/treeUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ndefineOptions({\n  inheritAttrs: false\n})\n\nconst expandedKeys = defineModel<Record<string, boolean>>('expandedKeys', {\n  required: true\n})\nprovide(InjectKeyExpandedKeys, expandedKeys)\nconst selectionKeys = defineModel<Record<string, boolean>>('selectionKeys')\n// Tracks whether the caller has set the selectionKeys model.\nconst storeSelectionKeys = selectionKeys.value !== undefined\n\nfunction preventUnboundSelection(event: Event) {\n  if (!storeSelectionKeys) event.preventDefault()\n}\n\nconst { root, class: className } = defineProps<{\n  root: TreeExplorerNode<T>\n  class?: string\n}>()\nconst emit = defineEmits<{\n  (e: 'nodeClick', node: RenderedTreeExplorerNode<T>, event: MouseEvent): void\n  (e: 'nodeDelete', node: RenderedTreeExplorerNode<T>): void\n  (e: 'contextMenu', node: RenderedTreeExplorerNode<T>, event: MouseEvent): void\n}>()\n\nconst {\n  newFolderNode,\n  getAddFolderMenuItem,\n  handleFolderCreation,\n  addFolderCommand\n} = useTreeFolderOperations<T>(\n  /* expandNode */ (node: TreeExplorerNode<T>) => {\n    expandedKeys.value = { ...expandedKeys.value, [node.key]: true }\n  }\n)\n\nconst renderedRoot = computed<RenderedTreeExplorerNode<T>>(() => {\n  const renderedRoot = fillNodeInfo(root)\n  return newFolderNode.value\n    ? combineTrees(renderedRoot, newFolderNode.value)\n    : renderedRoot\n})\nconst expandedNodeKeys = computed({\n  get: () =>\n    Object.entries(expandedKeys.value)\n      .filter(([, expanded]) => expanded)\n      .map(([key]) => key),\n  set: (keys: string[]) => {\n    expandedKeys.value = Object.fromEntries(keys.map((key) => [key, true]))\n  }\n})\nconst selectedNode = computed({\n  get: () => {\n    const key = Object.keys(selectionKeys.value ?? {}).find(\n      (key) => selectionKeys.value?.[key]\n    )\n    return key\n      ? (findNodeByKey(renderedRoot.value, key) ?? undefined)\n      : undefined\n  },\n  set: (node: RenderedTreeExplorerNode<T> | undefined) => {\n    selectionKeys.value = node ? { [node.key]: true } : {}\n  }\n})\nconst getTreeNodeIcon = (node: TreeExplorerNode<T>) => {\n  if (node.getIcon) {\n    const icon = node.getIcon()\n    if (icon) {\n      return icon\n    }\n  } else if (node.icon) {\n    return node.icon\n  }\n  // node.icon is undefined\n  if (node.leaf) {\n    return 'pi pi-file'\n  }\n  const isExpanded = expandedKeys.value?.[node.key] ?? false\n  return isExpanded ? 'pi pi-folder-open' : 'pi pi-folder'\n}\nconst fillNodeInfo = (\n  node: TreeExplorerNode<T>\n): RenderedTreeExplorerNode<T> => {\n  const children = node.children?.map(fillNodeInfo) ?? []\n  const totalLeaves = node.leaf\n    ? 1\n    : children.reduce((acc, child) => acc + child.totalLeaves, 0)\n  return {\n    ...node,\n    icon: getTreeNodeIcon(node),\n    iconColor: node.getIconColor?.(),\n    iconImage: node.getIconImage?.(),\n    children,\n    type: node.leaf ? 'node' : 'folder',\n    totalLeaves,\n    badgeText: node.getBadgeText ? node.getBadgeText() : undefined,\n    isEditingLabel: node.key === renameEditingNode.value?.key\n  }\n}\nconst onNodeContentClick = async (\n  e: MouseEvent,\n  node: RenderedTreeExplorerNode<T>\n) => {\n  await node.handleClick?.(e)\n  emit('nodeClick', node, e)\n}\nconst menu = ref<InstanceType<typeof ContextMenu> | null>(null)\nconst menuTargetNode = shallowRef<RenderedTreeExplorerNode<T> | null>(null)\nconst extraMenuItems = computed(() => {\n  const node = menuTargetNode.value\n  return node?.contextMenuItems\n    ? typeof node.contextMenuItems === 'function'\n      ? node.contextMenuItems(node)\n      : node.contextMenuItems\n    : []\n})\nconst renameEditingNode = shallowRef<RenderedTreeExplorerNode<T> | null>(null)\nconst errorHandling = useErrorHandling()\nconst handleNodeLabelEdit = async (\n  n: RenderedTreeExplorerNode,\n  newName: string\n) => {\n  const node = n as RenderedTreeExplorerNode<T>\n  await errorHandling.wrapWithErrorHandlingAsync(\n    async () => {\n      if (node.key === newFolderNode.value?.key) {\n        await handleFolderCreation(newName)\n      } else {\n        await node.handleRename?.(newName)\n      }\n    },\n    node.handleError,\n    () => {\n      renameEditingNode.value = null\n    }\n  )()\n}\nprovide(InjectKeyHandleEditLabelFunction, handleNodeLabelEdit)\n\nconst { t } = useI18n()\nconst renameCommand = (node: RenderedTreeExplorerNode<T>) => {\n  renameEditingNode.value = node\n}\nconst deleteCommand = async (node: RenderedTreeExplorerNode<T>) => {\n  await node.handleDelete?.()\n  emit('nodeDelete', node)\n}\n\nconst menuItems = computed<MenuItem[]>(() => {\n  const node = menuTargetNode.value\n  return [\n    getAddFolderMenuItem(node),\n    {\n      label: t('g.rename'),\n      icon: 'pi pi-file-edit',\n      command: () => {\n        if (node) {\n          renameCommand(node)\n        }\n      },\n      visible: node?.handleRename !== undefined\n    },\n    {\n      label: t('g.delete'),\n      icon: 'pi pi-trash',\n      command: async () => {\n        if (node) {\n          await deleteCommand(node)\n        }\n      },\n      visible: node?.handleDelete !== undefined\n    },\n    ...extraMenuItems.value\n  ].map((menuItem: MenuItem) =>\n    menuItem.command\n      ? {\n          ...menuItem,\n          command: wrapCommandWithErrorHandler(menuItem.command)\n        }\n      : menuItem\n  )\n})\n\nconst handleContextMenu = (\n  e: MouseEvent,\n  node: RenderedTreeExplorerNode<T>\n) => {\n  menuTargetNode.value = node\n  emit('contextMenu', node, e)\n  if (menuItems.value.filter((item) => item.visible).length > 0) {\n    menu.value?.show(e)\n  }\n}\n\nconst wrapCommandWithErrorHandler = (\n  command: (event: MenuItemCommandEvent) => unknown\n) => {\n  const node = menuTargetNode.value\n  return errorHandling.wrapWithErrorHandlingAsync(command, node?.handleError)\n}\n\nconst PREVIEW_GAP = 16\n\nconst previews = useTemplateRef<HTMLElement[]>('preview')\nconst previewElement = computed(() => previews.value?.[0])\nconst previewRow = useElementBounding(() =>\n  previewElement.value?.closest<HTMLElement>('[role=\"treeitem\"]')\n)\nconst previewSize = useElementSize(previewElement, undefined, {\n  box: 'border-box'\n})\nconst { height: windowHeight } = useWindowSize()\nconst settingStore = useSettingStore()\nconst previewStyle = computed(() => {\n  const top = Math.max(\n    0,\n    Math.min(\n      previewRow.top.value,\n      windowHeight.value - previewSize.height.value - PREVIEW_GAP\n    )\n  )\n  const left =\n    settingStore.get('Comfy.Sidebar.Location') === 'right'\n      ? previewRow.left.value - previewSize.width.value - PREVIEW_GAP\n      : previewRow.right.value + PREVIEW_GAP\n  return { top: `${top}px`, left: `${left}px` }\n})\n\ndefineExpose({\n  /**\n   * The command to add a folder to a node via the context menu\n   * @param targetNodeKey - The key of the node where the folder will be added under\n   */\n  addFolderCommand: (targetNodeKey: string) => {\n    const targetNode = findNodeByKey(renderedRoot.value, targetNodeKey)\n    if (targetNode) {\n      addFolderCommand(targetNode)\n    }\n  }\n})\n</script>\n","<template>\n  <div class=\"flex flex-col\">\n    <div :id=\"labelId\">\n      {{ getDownloadLabel(download.savePath ?? '') }}\n    </div>\n    <div v-if=\"['cancelled', 'error'].includes(download.status ?? '')\">\n      <Badge\n        variant=\"chip\"\n        severity=\"danger\"\n        class=\"mt-2 h-6 text-sm font-light\"\n        removable\n        @remove=\"handleRemoveDownload\"\n      >\n        {{ t('electronFileDownload.cancelled') }}\n      </Badge>\n    </div>\n    <div\n      v-if=\"\n        ['in_progress', 'paused', 'completed'].includes(download.status ?? '')\n      \"\n      class=\"mt-2 flex flex-row items-center gap-2\"\n    >\n      <div\n        role=\"progressbar\"\n        :aria-labelledby=\"labelId\"\n        :aria-valuenow=\"downloadProgressPercent\"\n        aria-valuemin=\"0\"\n        aria-valuemax=\"100\"\n        class=\"flex-1\"\n      >\n        <div class=\"h-5 overflow-hidden rounded-full bg-secondary-background\">\n          <div\n            class=\"h-full bg-primary-background transition-[width]\"\n            :style=\"{ width: `${downloadProgressPercent}%` }\"\n          />\n        </div>\n        <span v-if=\"(download.progress ?? 0) > 0.1\" class=\"text-xs\">\n          {{ downloadProgressPercent }}%\n        </span>\n      </div>\n\n      <Button\n        v-if=\"download.status === 'in_progress'\"\n        :tooltip=\"t('electronFileDownload.pause')\"\n        class=\"size-[22px] rounded-full\"\n        variant=\"secondary\"\n        size=\"icon-sm\"\n        :aria-label=\"t('electronFileDownload.pause')\"\n        @click=\"triggerPauseDownload\"\n      >\n        <i class=\"icon-[lucide--pause] size-3\" />\n      </Button>\n\n      <Button\n        v-if=\"download.status === 'paused'\"\n        :tooltip=\"t('electronFileDownload.resume')\"\n        class=\"size-[22px] rounded-full\"\n        variant=\"secondary\"\n        size=\"icon-sm\"\n        :aria-label=\"t('electronFileDownload.resume')\"\n        @click=\"triggerResumeDownload\"\n      >\n        <i class=\"icon-[lucide--play] size-3\" />\n      </Button>\n\n      <Button\n        v-if=\"['in_progress', 'paused'].includes(download.status ?? '')\"\n        :tooltip=\"t('electronFileDownload.cancel')\"\n        class=\"size-[22px] rounded-full\"\n        variant=\"destructive\"\n        size=\"icon-sm\"\n        :aria-label=\"t('electronFileDownload.cancel')\"\n        @click=\"triggerCancelDownload\"\n      >\n        <i class=\"icon-[lucide--x-circle] size-3\" />\n      </Button>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, useId } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useElectronDownloadStore } from '@/stores/electronDownloadStore'\nimport type { ElectronDownload } from '@/stores/electronDownloadStore'\n\nconst { t } = useI18n()\nconst labelId = useId()\n\nconst electronDownloadStore = useElectronDownloadStore()\n\nconst { download } = defineProps<{\n  download: ElectronDownload\n}>()\n\nconst downloadProgressPercent = computed(() =>\n  Number(((download.progress ?? 0) * 100).toFixed(1))\n)\n\nconst getDownloadLabel = (savePath: string) => {\n  let parts = savePath.split('/')\n  parts = parts.length === 1 ? parts[0].split('\\\\') : parts\n  const name = parts.pop()\n  const dir = parts.pop()\n  return `${dir}/${name}`\n}\n\nconst triggerCancelDownload = () => electronDownloadStore.cancel(download.url)\nconst triggerPauseDownload = () => electronDownloadStore.pause(download.url)\nconst triggerResumeDownload = () => electronDownloadStore.resume(download.url)\n\nconst handleRemoveDownload = () => {\n  electronDownloadStore.$patch((state) => {\n    state.downloads = state.downloads.filter(({ url }) => url !== download.url)\n  })\n}\n</script>\n","<template>\n  <div v-if=\"inProgressDownloads.length > 0\" class=\"mx-6 mb-4\">\n    <div class=\"my-4 text-lg\">\n      {{ $t('electronFileDownload.inProgress') }}\n    </div>\n\n    <template v-for=\"download in inProgressDownloads\" :key=\"download.url\">\n      <DownloadItem :download=\"download\" />\n    </template>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\n\nimport { useElectronDownloadStore } from '@/stores/electronDownloadStore'\n\nimport DownloadItem from './DownloadItem.vue'\n\nconst electronDownloadStore = useElectronDownloadStore()\nconst { inProgressDownloads } = storeToRefs(electronDownloadStore)\n</script>\n","<template>\n  <div class=\"model_preview\">\n    <div class=\"model_preview_title\">\n      {{ modelDef.title }}\n    </div>\n    <div class=\"model_preview_top_container\">\n      <div class=\"model_preview_filename\">\n        {{ modelDef.file_name }}\n      </div>\n      <div v-if=\"modelDef.architecture_id\" class=\"model_preview_architecture\">\n        <span class=\"model_preview_prefix\">{{ $t('g.architecture') }}: </span>\n        {{ modelDef.architecture_id }}\n      </div>\n      <div v-if=\"modelDef.author\" class=\"model_preview_author\">\n        <span class=\"model_preview_prefix\">{{ $t('g.author') }}: </span>\n        {{ modelDef.author }}\n      </div>\n    </div>\n    <div v-if=\"modelDef.image\" class=\"model_preview_image\">\n      <img :src=\"modelDef.image\" />\n    </div>\n    <div v-if=\"modelDef.usage_hint\" class=\"model_preview_usage_hint\">\n      <span class=\"model_preview_prefix\">{{ $t('g.usageHint') }}: </span>\n      {{ modelDef.usage_hint }}\n    </div>\n    <div v-if=\"modelDef.trigger_phrase\" class=\"model_preview_trigger_phrase\">\n      <span class=\"model_preview_prefix\">{{ $t('g.triggerPhrase') }}: </span>\n      {{ modelDef.trigger_phrase }}\n    </div>\n    <div v-if=\"modelDef.description\" class=\"model_preview_description\">\n      <span class=\"model_preview_prefix\">{{ $t('g.description') }}: </span>\n      {{ modelDef.description }}\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { ComfyModelDef } from '@/stores/modelStore'\n\nconst props = defineProps({\n  modelDef: {\n    type: ComfyModelDef,\n    required: true\n  }\n})\n\nconst modelDef = props.modelDef\n</script>\n<style scoped>\n.model_preview {\n  background-color: var(--comfy-menu-bg);\n  color: var(--descrip-text);\n  border: 1px solid var(--descrip-text);\n  min-width: 300px;\n  max-width: 500px;\n  width: fit-content;\n  height: fit-content;\n  z-index: 9999;\n  border-radius: 12px;\n  overflow: hidden;\n  font-size: 12px;\n  padding: 10px;\n}\n.model_preview_image {\n  margin: auto;\n  width: fit-content;\n}\n.model_preview_image img {\n  max-width: 100%;\n  max-height: 150px;\n  object-fit: contain;\n}\n.model_preview_title {\n  font-weight: 700;\n  text-align: center;\n  font-size: 14px;\n}\n.model_preview_top_container {\n  text-align: center;\n  line-height: 0.5;\n}\n.model_preview_filename,\n.model_preview_author,\n.model_preview_architecture {\n  display: inline-block;\n  text-align: center;\n  margin: 5px;\n  font-size: var(--text-2xs);\n}\n.model_preview_prefix {\n  font-weight: 700;\n}\n</style>\n","import { assetItemSchema } from '@/platform/assets/schemas/assetSchema'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport {\n  MISSING_TAG,\n  MODELS_TAG\n} from '@/platform/assets/services/assetService'\nimport {\n  getAssetFilename,\n  getAssetNodeCategoryCandidates\n} from '@/platform/assets/utils/assetMetadataUtils'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useModelToNodeStore } from '@/stores/modelToNodeStore'\nimport type { ModelNodeProvider } from '@/stores/modelToNodeStore'\n\ntype ResolveErrorCode = 'INVALID_ASSET' | 'NO_PROVIDER'\n\nexport interface ResolveModelNodeError {\n  code: ResolveErrorCode\n  message: string\n  assetId: string\n  details?: Record<string, unknown>\n}\n\ninterface ResolvedModelNode {\n  provider: ModelNodeProvider\n  filename: string\n}\n\ntype Result<T, E> = { success: true; value: T } | { success: false; error: E }\n\n/**\n * Resolves an asset item to the node provider and filename needed to add a\n * model loader node. Validation failures return error results rather than\n * throwing, so callers can degrade gracefully in UI contexts.\n */\nexport function resolveModelNodeFromAsset(\n  asset: AssetItem\n): Result<ResolvedModelNode, ResolveModelNodeError> {\n  const validatedAsset = assetItemSchema.safeParse(asset)\n\n  if (!validatedAsset.success) {\n    const errorMessage = validatedAsset.error.issues\n      .map((e) => `${e.path.join('.')}: ${e.message}`)\n      .join(', ')\n    console.error('Invalid asset item:', errorMessage)\n    return {\n      success: false,\n      error: {\n        code: 'INVALID_ASSET',\n        message: 'Asset schema validation failed',\n        assetId: typeof asset.id === 'string' ? asset.id : 'unknown',\n        details: { validationErrors: errorMessage }\n      }\n    }\n  }\n\n  const validAsset = validatedAsset.data\n\n  const filename = getAssetFilename(validAsset)\n  if (filename.length === 0) {\n    console.error(\n      `Asset ${validAsset.id} has invalid user_metadata.filename (expected non-empty string, got ${typeof filename})`\n    )\n    return {\n      success: false,\n      error: {\n        code: 'INVALID_ASSET',\n        message: `Invalid filename (expected non-empty string, got ${typeof filename})`,\n        assetId: validAsset.id\n      }\n    }\n  }\n\n  if (validAsset.tags.length === 0) {\n    console.error(\n      `Asset ${validAsset.id} has no tags defined (expected at least one category tag)`\n    )\n    return {\n      success: false,\n      error: {\n        code: 'INVALID_ASSET',\n        message: 'Asset has no tags defined',\n        assetId: validAsset.id\n      }\n    }\n  }\n\n  const { flags } = useFeatureFlags()\n  const candidates = getAssetNodeCategoryCandidates(\n    validAsset,\n    flags.supportsModelTypeTags\n  )\n  if (candidates.length === 0) {\n    console.error(\n      `Asset ${validAsset.id} has no valid category tag. Available tags: ${validAsset.tags.join(', ')} (expected tag other than '${MODELS_TAG}' or '${MISSING_TAG}')`\n    )\n    return {\n      success: false,\n      error: {\n        code: 'INVALID_ASSET',\n        message: 'Asset has no valid category tag',\n        assetId: validAsset.id,\n        details: { availableTags: validAsset.tags }\n      }\n    }\n  }\n\n  const modelToNodeStore = useModelToNodeStore()\n  const resolved = candidates\n    .map((category) => ({\n      category,\n      provider: modelToNodeStore.getNodeProvider(category)\n    }))\n    .find((candidate) => candidate.provider !== undefined)\n\n  if (!resolved?.provider) {\n    // Known gap (out of scope for FE-1076): flat `model_type:LLM`-style tags\n    // whose loaders are only registered hierarchically land here until the\n    // backend emits a subtype-carrying tag.\n    console.error(\n      `No node provider registered for category: ${candidates.join(', ')}`\n    )\n    return {\n      success: false,\n      error: {\n        code: 'NO_PROVIDER',\n        message: `No node provider registered for category: ${candidates.join(', ')}`,\n        assetId: validAsset.id,\n        details: { candidates }\n      }\n    }\n  }\n\n  return { success: true, value: { provider: resolved.provider, filename } }\n}\n","import { useNodeDragToCanvas } from '@/composables/node/useNodeDragToCanvas'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { resolveModelNodeFromAsset } from '@/platform/assets/utils/resolveModelNodeFromAsset'\nimport type { ResolveModelNodeError } from '@/platform/assets/utils/resolveModelNodeFromAsset'\nimport type { NodeAddSource } from '@/platform/telemetry/types'\nimport type { ModelNodeProvider } from '@/stores/modelToNodeStore'\n\n/**\n * Arms a ghost drag for a model loader node. Providers with no widget key\n * (auto-load nodes) start the drag without widget values.\n */\nexport function startModelLoaderDrag(\n  provider: ModelNodeProvider,\n  filename: string,\n  source: NodeAddSource = 'sidebar_drag'\n) {\n  const widgetValues = provider.key\n    ? [{ selector: provider.key, value: filename }]\n    : undefined\n  useNodeDragToCanvas().startDrag(provider.nodeDef, { widgetValues, source })\n}\n\n/**\n * Starts a ghost drag for the model loader node described by an asset. The\n * node is created where the user next clicks the canvas, with the asset's\n * filename written into the loader widget.\n *\n * @returns the resolution error when the asset cannot be mapped to a node,\n *   otherwise `undefined`.\n */\nexport function startModelNodeDragFromAsset(\n  asset: AssetItem,\n  source: NodeAddSource = 'sidebar_drag'\n): ResolveModelNodeError | undefined {\n  const resolved = resolveModelNodeFromAsset(asset)\n  if (!resolved.success) return resolved.error\n\n  const { provider, filename } = resolved.value\n  startModelLoaderDrag(provider, filename, source)\n}\n","import type { Ref } from 'vue'\n\nimport type { TreeNode } from '@/types/treeExplorerTypes'\n\nexport function useTreeExpansion(expandedKeys: Ref<Record<string, boolean>>) {\n  const toggleNode = (node: TreeNode) => {\n    if (node.key && typeof node.key === 'string') {\n      if (node.key in expandedKeys.value) {\n        delete expandedKeys.value[node.key]\n      } else {\n        expandedKeys.value[node.key] = true\n      }\n    }\n  }\n\n  const toggleNodeRecursive = (node: TreeNode) => {\n    if (node.key && typeof node.key === 'string') {\n      if (node.key in expandedKeys.value) {\n        collapseNode(node)\n      } else {\n        expandNode(node)\n      }\n    }\n  }\n\n  const expandNode = (node: TreeNode) => {\n    if (node.key && typeof node.key === 'string' && !node.leaf) {\n      expandedKeys.value[node.key] = true\n\n      for (const child of node.children ?? []) {\n        expandNode(child)\n      }\n    }\n  }\n\n  const collapseNode = (node: TreeNode) => {\n    if (node.key && typeof node.key === 'string' && !node.leaf) {\n      delete expandedKeys.value[node.key]\n\n      for (const child of node.children ?? []) {\n        collapseNode(child)\n      }\n    }\n  }\n\n  const toggleNodeOnEvent = (e: MouseEvent | KeyboardEvent, node: TreeNode) => {\n    if (e.ctrlKey) {\n      toggleNodeRecursive(node)\n    } else {\n      toggleNode(node)\n    }\n  }\n\n  return {\n    toggleNode,\n    toggleNodeRecursive,\n    expandNode,\n    collapseNode,\n    toggleNodeOnEvent\n  }\n}\n","<template>\n  <SidebarTabTemplate :title=\"$t('sideToolbar.modelLibrary')\">\n    <template #tool-buttons>\n      <Button\n        :tooltip=\"$t('g.refresh')\"\n        tooltip-side=\"bottom\"\n        variant=\"muted-textonly\"\n        size=\"icon\"\n        :aria-label=\"$t('g.refresh')\"\n        @click=\"withLoadFailureToast(() => modelStore.refresh())\"\n      >\n        <i class=\"icon-[lucide--refresh-cw] size-4\" />\n      </Button>\n      <Button\n        v-if=\"!flags.assetsEnabled\"\n        :tooltip=\"$t('g.loadAllFolders')\"\n        tooltip-side=\"bottom\"\n        variant=\"muted-textonly\"\n        size=\"icon\"\n        :aria-label=\"$t('g.loadAllFolders')\"\n        @click=\"withLoadFailureToast(() => modelStore.loadModels())\"\n      >\n        <i class=\"icon-[lucide--cloud-download] size-4\" />\n      </Button>\n    </template>\n    <template #header>\n      <SidebarTopArea>\n        <SearchInput\n          ref=\"searchBoxRef\"\n          v-model:model-value=\"searchQuery\"\n          :placeholder=\"\n            $t('g.searchPlaceholder', {\n              subject: $t('sideToolbar.labels.models')\n            })\n          \"\n          @search=\"handleSearch\"\n        />\n        <p\n          v-if=\"searchResults.capped\"\n          role=\"status\"\n          class=\"mx-2 my-1 text-xs text-muted\"\n        >\n          {{\n            $t('sideToolbar.searchResultsCapped', {\n              limit: SEARCH_RESULT_LIMIT\n            })\n          }}\n        </p>\n      </SidebarTopArea>\n    </template>\n    <template #body>\n      <ElectronDownloadItems v-if=\"isDesktop\" />\n\n      <TreeExplorer\n        v-model:expanded-keys=\"expandedKeys\"\n        class=\"model-lib-tree-explorer\"\n        :aria-label=\"$t('sideToolbar.modelLibrary')\"\n        :root=\"renderedRoot\"\n      >\n        <template #preview=\"{ node }\">\n          <ModelPreview\n            v-if=\"node.data && hasPreviewDetails(node.data)\"\n            :model-def=\"node.data\"\n          />\n        </template>\n      </TreeExplorer>\n    </template>\n  </SidebarTabTemplate>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, onMounted, ref, toRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport SidebarTopArea from '@/components/sidebar/tabs/SidebarTopArea.vue'\nimport TreeExplorer from '@/components/common/TreeExplorer.vue'\nimport SidebarTabTemplate from '@/components/sidebar/tabs/SidebarTabTemplate.vue'\nimport ElectronDownloadItems from '@/components/sidebar/tabs/modelLibrary/ElectronDownloadItems.vue'\nimport ModelPreview from '@/components/sidebar/tabs/modelLibrary/ModelPreview.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { startModelLoaderDrag } from '@/composables/node/startModelNodeDragFromAsset'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useTreeExpansion } from '@/composables/useTreeExpansion'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useAssetDownloadStore } from '@/stores/assetDownloadStore'\nimport type { ComfyModelDef } from '@/stores/modelStore'\nimport {\n  ModelFolder,\n  ResourceState,\n  getModelPreviewUrl,\n  useModelStore\n} from '@/stores/modelStore'\nimport { useModelToNodeStore } from '@/stores/modelToNodeStore'\nimport type { TreeExplorerNode, TreeNode } from '@/types/treeExplorerTypes'\nimport { isDesktop } from '@/platform/distribution/types'\nimport { buildTree } from '@/utils/treeUtil'\n\nconst modelStore = useModelStore()\nconst modelToNodeStore = useModelToNodeStore()\nconst settingStore = useSettingStore()\nconst toast = useToast()\nconst { t } = useI18n()\nconst { flags } = useFeatureFlags()\nconst assetDownloadStore = useAssetDownloadStore()\nconst searchBoxRef = ref()\nconst searchQuery = ref<string>('')\n/**\n * The committed query the tree derives from. SearchInput debounces its\n * `search` emit, so the full recompute-and-mount cost of a query change runs\n * once per typing pause instead of on every keystroke of `searchQuery`.\n */\nconst activeSearchQuery = ref<string>('')\nconst expandedKeys = ref<Record<string, boolean>>({})\nconst { toggleNodeOnEvent } = useTreeExpansion(expandedKeys)\n\n// Search results render expanded and un-virtualized, and the tree's cost is\n// O(n^2) in mounted rows, so an unbounded result set hangs the tab on large\n// libraries (measured: seconds at 5k models). Cap what renders; refining the\n// query is the path to the tail.\nconst SEARCH_RESULT_LIMIT = 500\n\nconst searchResults = computed<{ models: ComfyModelDef[]; capped: boolean }>(\n  () => {\n    const search = activeSearchQuery.value.toLocaleLowerCase()\n    if (!search) return { models: [], capped: false }\n    const matches: ComfyModelDef[] = []\n    for (const model of modelStore.models) {\n      if (!model.searchable.includes(search)) continue\n      if (matches.length === SEARCH_RESULT_LIMIT) {\n        return { models: matches, capped: true }\n      }\n      matches.push(model)\n    }\n    return { models: matches, capped: false }\n  }\n)\n\nconst handleSearch = async (query: string) => {\n  autoExpandedSearchKeys.clear()\n  activeSearchQuery.value = query\n  if (!query) {\n    expandedKeys.value = {}\n    return\n  }\n  // Load all models to ensure results cover folders not yet opened\n  await modelStore.loadModels()\n}\n\ntype ModelOrFolder = ComfyModelDef | ModelFolder\n\nconst root = computed<TreeNode<ModelOrFolder>>(() => {\n  const allNodes: ModelOrFolder[] = activeSearchQuery.value\n    ? searchResults.value.models\n    : [...modelStore.visibleModelFolders, ...modelStore.models]\n  return buildTree(allNodes, (modelOrFolder: ModelOrFolder) =>\n    modelOrFolder.key.split('/')\n  )\n})\n\n/**\n * Folder keys already auto-expanded for the current query. Expansion runs\n * once per key: the query's initial result set opens on commit, and a\n * background reload (e.g. a scan completing mid-search) opens only folders\n * newly appearing in the results. A folder the user collapsed keeps its key\n * here and stays collapsed, and an unchanged tree costs no expand pass.\n */\nconst autoExpandedSearchKeys = new Set<string>()\n\nfunction expandNewSearchFolders(node: TreeNode<ModelOrFolder>) {\n  if (node.leaf) return\n  if (!autoExpandedSearchKeys.has(node.key)) {\n    autoExpandedSearchKeys.add(node.key)\n    expandedKeys.value[node.key] = true\n  }\n  for (const child of node.children ?? []) {\n    expandNewSearchFolders(child)\n  }\n}\n\nwatch(root, (newRoot) => {\n  if (!activeSearchQuery.value) return\n  expandNewSearchFolders(newRoot)\n})\n\nconst renderedRoot = computed<TreeExplorerNode<ComfyModelDef>>(() => {\n  const nameFormat = settingStore.get('Comfy.ModelLibrary.NameFormat')\n  const fillNodeInfo = (\n    node: TreeNode<ModelOrFolder>\n  ): TreeExplorerNode<ComfyModelDef> => {\n    const children = node.children?.map(fillNodeInfo)\n    const folder = node.data instanceof ModelFolder ? node.data : undefined\n    const model = node.data instanceof ModelFolder ? undefined : node.data\n\n    return {\n      key: node.key,\n      label: model\n        ? nameFormat === 'title'\n          ? model.title\n          : model.simplified_file_name\n        : node.label,\n      leaf: node.leaf,\n      data: model,\n      getIcon() {\n        if (model) {\n          return model.image ? 'pi pi-image' : 'pi pi-file'\n        }\n        if (folder) {\n          return folder.state === ResourceState.Loading\n            ? 'pi pi-spin pi-spinner'\n            : 'pi pi-folder'\n        }\n        return 'pi pi-folder'\n      },\n      getIconImage() {\n        return (model && getModelPreviewUrl(model)) || undefined\n      },\n      getBadgeText() {\n        // Return undefined to apply default badge text\n        // Return empty string to hide badge\n        if (!folder) {\n          return\n        }\n        return folder.state === ResourceState.Loaded ? undefined : ''\n      },\n      children,\n      draggable: node.leaf,\n      handleClick(e: MouseEvent) {\n        if (this.leaf && model) {\n          const provider = modelToNodeStore.getNodeProvider(model.directory)\n          if (provider) {\n            startModelLoaderDrag(provider, model.file_name)\n          }\n        } else {\n          toggleNodeOnEvent(e, node)\n        }\n      }\n    }\n  }\n\n  return fillNodeInfo(root.value)\n})\n\nfunction hasPreviewDetails(model: ComfyModelDef) {\n  return (\n    model.has_loaded_metadata &&\n    Boolean(\n      model.author ||\n      model.simplified_file_name != model.title ||\n      model.description ||\n      model.usage_hint ||\n      model.trigger_phrase ||\n      model.image\n    )\n  )\n}\n\nconst visibleModels = computed(() => {\n  const models: ComfyModelDef[] = []\n  const collect = (node: TreeNode<ModelOrFolder>) => {\n    for (const child of node.children ?? []) {\n      if (child.leaf) {\n        if (child.data && !(child.data instanceof ModelFolder)) {\n          models.push(child.data)\n        }\n      } else if (expandedKeys.value[child.key]) {\n        collect(child)\n      }\n    }\n  }\n  collect(root.value)\n  return models\n})\n\nwatch(visibleModels, (models) => {\n  for (const model of models) void model.load()\n})\n\nwatch(\n  toRef(expandedKeys, 'value'),\n  (newExpandedKeys) => {\n    Object.entries(newExpandedKeys).forEach(([key, isExpanded]) => {\n      if (isExpanded) {\n        const folderPath = key.split('/').slice(1).join('/')\n        if (folderPath && !folderPath.includes('/')) {\n          // Trigger (async) load of model data for this folder\n          void modelStore.getLoadedModelFolder(folderPath)\n        }\n      }\n    })\n  },\n  { deep: true }\n)\n\nwatch(\n  () => assetDownloadStore.lastCompletedDownload,\n  (completed) => {\n    if (!completed) return\n    void modelStore.refreshModelFolder(completed.modelType)\n  }\n)\n\nasync function withLoadFailureToast(action: () => Promise<unknown>) {\n  try {\n    await action()\n  } catch (error) {\n    console.error('Model library load failed', error)\n    toast.error(t('g.error'), {\n      description: t('sideToolbar.modelLibraryLoadFailed'),\n      duration: 5000\n    })\n  }\n}\n\nonMounted(async () => {\n  searchBoxRef.value?.focus()\n  // In asset mode the whole library resolves from one cached walk, so eager\n  // loading is cheap and keeps search and folder badges complete from the\n  // start; AutoLoadAll remains the opt-in for the request-per-folder legacy path.\n  if (\n    flags.assetsEnabled ||\n    settingStore.get('Comfy.ModelLibrary.AutoLoadAll')\n  ) {\n    await withLoadFailureToast(() => modelStore.loadModels())\n  }\n})\n\nwatch(\n  () => flags.assetsEnabled,\n  async (enabled) => {\n    if (enabled) await withLoadFailureToast(() => modelStore.loadModels())\n  }\n)\n</script>\n\n<style scoped>\n:deep(.pi-fake-spacer) {\n  height: 1px;\n  width: 16px;\n}\n</style>\n","import { startModelNodeDragFromAsset } from '@/composables/node/startModelNodeDragFromAsset'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { t } from '@/i18n'\nimport { useAssetBrowserDialog } from '@/platform/assets/composables/useAssetBrowserDialog'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useToast } from '@/components/ui/toast/toastStore'\n\nexport async function openModelLibraryBrowser(): Promise<void> {\n  if (!useFeatureFlags().flags.assetsEnabled) return\n\n  const toast = useToast()\n  const assetBrowserDialog = useAssetBrowserDialog()\n  await assetBrowserDialog.browse({\n    assetType: 'models',\n    title: t('sideToolbar.modelLibrary'),\n    onAssetSelected: (asset) => {\n      const error = startModelNodeDragFromAsset(asset, 'asset_browser')\n      if (error) {\n        reportError(new Error(error.message), {\n          surface: 'assets',\n          errorType: 'model_node_creation_failure',\n          tags: { code: error.code },\n          context: { assetId: error.assetId, details: error.details }\n        })\n        toast.error(t('g.error'), {\n          description: t('assetBrowser.failedToCreateNode')\n        })\n      }\n    }\n  })\n}\n","import { markRaw } from 'vue'\n\nimport ModelLibrarySidebarTab from '@/components/sidebar/tabs/ModelLibrarySidebarTab.vue'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { openModelLibraryBrowser } from '@/platform/assets/composables/openModelLibraryBrowser'\nimport { isDesktop } from '@/platform/distribution/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useElectronDownloadStore } from '@/stores/electronDownloadStore'\nimport type { SidebarTabExtension } from '@/types/extensionTypes'\n\nexport const useModelLibrarySidebarTab = (): SidebarTabExtension => {\n  return {\n    id: 'model-library',\n    icon: 'icon-[comfy--ai-model]',\n    title: 'sideToolbar.modelLibrary',\n    tooltip: 'sideToolbar.modelLibrary',\n    label: 'sideToolbar.labels.models',\n    component: markRaw(ModelLibrarySidebarTab),\n    type: 'vue',\n    onToggle: async () => {\n      const useAssetBrowser =\n        useSettingStore().get('Comfy.ModelLibrary.UseAssetBrowser') &&\n        useFeatureFlags().flags.assetsEnabled\n      if (!useAssetBrowser) return false\n      await openModelLibraryBrowser()\n      return true\n    },\n    iconBadge: () => {\n      if (isDesktop) {\n        const electronDownloadStore = useElectronDownloadStore()\n        if (electronDownloadStore.inProgressDownloads.length > 0) {\n          return electronDownloadStore.inProgressDownloads.length.toString()\n        }\n      }\n\n      return null\n    }\n  }\n}\n","import type { AppContext } from 'vue'\nimport { h, render } from 'vue'\n\nimport NodePreview from '@/components/node/NodePreview.vue'\nimport TooltipProvider from '@/components/ui/tooltip/TooltipProvider.vue'\nimport type { ComfyNodeDef as ComfyNodeDefV2 } from '@/schemas/nodeDef/nodeDefSchemaV2'\n\nexport function renderNodePreview(\n  container: HTMLElement,\n  nodeDef: ComfyNodeDefV2,\n  appContext: AppContext\n): () => void {\n  const vnode = h(\n    TooltipProvider,\n    { disabled: true },\n    { default: () => h(NodePreview, { nodeDef }) }\n  )\n  vnode.appContext = appContext\n  render(vnode, container)\n  return () => render(null, container)\n}\n","<template>\n  <div class=\"flex h-full flex-col overflow-auto\">\n    <div class=\"flex items-center border-b border-interface-stroke px-3 py-2\">\n      <Button\n        :tooltip=\"$t('g.back')\"\n        tooltip-side=\"bottom\"\n        variant=\"muted-textonly\"\n        size=\"icon\"\n        :aria-label=\"$t('g.back')\"\n        @click=\"$emit('close')\"\n      >\n        <i class=\"icon-[lucide--arrow-left] size-4\" />\n      </Button>\n      <span class=\"ml-2 flex-1 truncate font-semibold\">\n        {{ node.display_name }}\n      </span>\n      <SidebarTabCloseButton />\n    </div>\n    <div class=\"grow p-4\">\n      <NodeHelpContent :node />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport NodeHelpContent from '@/components/node/NodeHelpContent.vue'\nimport SidebarTabCloseButton from '@/components/sidebar/tabs/SidebarTabCloseButton.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\n\nconst { node } = defineProps<{ node: ComfyNodeDefImpl }>()\n\ndefineEmits<{\n  (e: 'close'): void\n}>()\n</script>\n","import { defineStore } from 'pinia'\nimport { computed, ref } from 'vue'\n\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\n\nexport const useNodeHelpStore = defineStore('nodeHelp', () => {\n  const currentHelpNode = ref<ComfyNodeDefImpl | null>(null)\n  const isHelpOpen = computed(() => currentHelpNode.value !== null)\n\n  function openHelp(nodeDef: ComfyNodeDefImpl) {\n    currentHelpNode.value = nodeDef\n  }\n\n  function closeHelp() {\n    currentHelpNode.value = null\n  }\n\n  return {\n    currentHelpNode,\n    isHelpOpen,\n    openHelp,\n    closeHelp\n  }\n})\n","<template>\n  <div class=\"color-customization-selector-container flex items-center gap-2\">\n    <ToggleGroup v-model=\"selectedColorName\" type=\"single\" :allow-empty=\"false\">\n      <ToggleGroupItem\n        v-for=\"option in colorOptionsWithCustom\"\n        :key=\"option.name\"\n        :value=\"option.name\"\n        :aria-label=\"\n          option.name === '_custom' ? t('color.custom') : option.name\n        \"\n      >\n        <div\n          v-if=\"option.name !== '_custom'\"\n          :style=\"{\n            width: '20px',\n            height: '20px',\n            backgroundColor: option.value,\n            borderRadius: '50%'\n          }\"\n        />\n        <i v-else class=\"pi pi-palette text-lg\" />\n      </ToggleGroupItem>\n    </ToggleGroup>\n    <ColorPicker\n      v-if=\"selectedColorName === '_custom'\"\n      v-model=\"customColorValue\"\n    />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ColorPicker from '@/components/ui/color-picker/ColorPicker.vue'\nimport { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'\n\nconst { t } = useI18n()\n\nconst {\n  modelValue,\n  colorOptions,\n  allowCustom = true\n} = defineProps<{\n  modelValue: string | null\n  colorOptions: { name: Exclude<string, '_custom'>; value: string }[]\n  allowCustom?: boolean\n}>()\n\nconst customColorOption = { name: '_custom', value: '' }\nconst colorOptionsWithCustom = computed(() => [\n  ...colorOptions,\n  ...(allowCustom ? [customColorOption] : [])\n])\n\nconst emit = defineEmits<{\n  'update:modelValue': [value: string | null]\n}>()\n\nconst initialColorOption = colorOptions.find(\n  (option) => option.value === modelValue\n)\nconst selectedColorName = ref(\n  initialColorOption?.name ?? customColorOption.name\n)\nconst customColorValue = ref(initialColorOption ? '' : (modelValue ?? ''))\n\nwatch(selectedColorName, (newName, oldName) => {\n  const newOption = colorOptionsWithCustom.value.find(\n    (option) => option.name === newName\n  )\n  if (!newOption) return\n\n  if (newName === customColorOption.name) {\n    customColorValue.value =\n      colorOptionsWithCustom.value.find((option) => option.name === oldName)\n        ?.value ?? ''\n  } else {\n    emit('update:modelValue', newOption.value)\n  }\n})\n\nwatch(customColorValue, (newValue) => {\n  if (selectedColorName.value === customColorOption.name) {\n    emit('update:modelValue', newValue || null)\n  }\n})\n</script>\n","<template>\n  <Dialog v-model:open=\"visible\">\n    <DialogPortal>\n      <DialogOverlay />\n      <DialogContent size=\"md\" :aria-labelledby=\"titleId\">\n        <DialogHeader>\n          <DialogTitle :id=\"titleId\">\n            {{ $t('g.customizeFolder') }}\n          </DialogTitle>\n          <DialogClose />\n        </DialogHeader>\n        <div class=\"flex flex-col gap-4 px-4 py-2\">\n          <div class=\"flex flex-col gap-2\">\n            <label for=\"customization-icon\" class=\"text-sm font-medium\">\n              {{ $t('g.icon') }}\n            </label>\n            <ToggleGroup\n              id=\"customization-icon\"\n              v-model=\"selectedIconValue\"\n              type=\"single\"\n              :allow-empty=\"false\"\n              class=\"justify-start\"\n            >\n              <ToggleGroupItem\n                v-for=\"option in iconOptions\"\n                :key=\"option.value\"\n                :value=\"option.value\"\n                :aria-label=\"option.name\"\n                class=\"p-2\"\n              >\n                <i\n                  :class=\"cn('pi text-lg', option.value)\"\n                  :style=\"{ color: finalColor }\"\n                />\n              </ToggleGroupItem>\n            </ToggleGroup>\n          </div>\n          <hr class=\"border-t border-border-subtle\" />\n          <div class=\"flex flex-col gap-2\">\n            <label for=\"customization-color\" class=\"text-sm font-medium\">\n              {{ $t('g.color') }}\n            </label>\n            <ColorCustomizationSelector\n              id=\"customization-color\"\n              v-model=\"finalColor\"\n              :color-options=\"colorOptions\"\n            />\n          </div>\n        </div>\n        <DialogFooter>\n          <Button variant=\"textonly\" @click=\"resetCustomization\">\n            <i class=\"pi pi-refresh\" />\n            {{ $t('g.reset') }}\n          </Button>\n          <Button autofocus @click=\"confirmCustomization\">\n            <i class=\"pi pi-check\" />\n            {{ $t('g.confirm') }}\n          </Button>\n        </DialogFooter>\n      </DialogContent>\n    </DialogPortal>\n  </Dialog>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, useId, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport ColorCustomizationSelector from '@/components/common/ColorCustomizationSelector.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Dialog from '@/components/ui/dialog/Dialog.vue'\nimport DialogClose from '@/components/ui/dialog/DialogClose.vue'\nimport DialogContent from '@/components/ui/dialog/DialogContent.vue'\nimport DialogFooter from '@/components/ui/dialog/DialogFooter.vue'\nimport DialogHeader from '@/components/ui/dialog/DialogHeader.vue'\nimport DialogOverlay from '@/components/ui/dialog/DialogOverlay.vue'\nimport DialogPortal from '@/components/ui/dialog/DialogPortal.vue'\nimport DialogTitle from '@/components/ui/dialog/DialogTitle.vue'\nimport { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group'\nimport { useNodeBookmarkStore } from '@/stores/nodeBookmarkStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\n\nconst { initialIcon, initialColor } = defineProps<{\n  initialIcon?: string\n  initialColor?: string\n}>()\n\nconst visible = defineModel<boolean>({ default: false })\n\nconst emit = defineEmits<{\n  (e: 'confirm', icon: string, color: string): void\n}>()\n\nconst titleId = useId()\n\nconst nodeBookmarkStore = useNodeBookmarkStore()\n\nconst iconOptions = [\n  { name: t('icon.bookmark'), value: nodeBookmarkStore.defaultBookmarkIcon },\n  { name: t('icon.folder'), value: 'pi-folder' },\n  { name: t('icon.star'), value: 'pi-star' },\n  { name: t('icon.heart'), value: 'pi-heart' },\n  { name: t('icon.file'), value: 'pi-file' },\n  { name: t('icon.inbox'), value: 'pi-inbox' },\n  { name: t('icon.box'), value: 'pi-box' },\n  { name: t('icon.briefcase'), value: 'pi-briefcase' }\n]\n\nconst colorOptions = [\n  { name: t('color.default'), value: nodeBookmarkStore.defaultBookmarkColor },\n  { name: t('color.blue'), value: '#007bff' },\n  { name: t('color.green'), value: '#28a745' },\n  { name: t('color.red'), value: '#dc3545' },\n  { name: t('color.pink'), value: '#e83e8c' },\n  { name: t('color.yellow'), value: '#ffc107' }\n]\n\nconst defaultIcon = iconOptions.find(\n  (option) => option.value === nodeBookmarkStore.defaultBookmarkIcon\n)\n\nconst selectedIconValue = ref((defaultIcon ?? iconOptions[0]).value)\nconst finalColor = ref(initialColor || nodeBookmarkStore.defaultBookmarkColor)\n\nconst resetCustomization = () => {\n  selectedIconValue.value =\n    iconOptions.find((option) => option.value === initialIcon)?.value ??\n    iconOptions[0].value\n  finalColor.value = initialColor || nodeBookmarkStore.defaultBookmarkColor\n}\n\nconst confirmCustomization = () => {\n  emit('confirm', selectedIconValue.value, finalColor.value)\n  visible.value = false\n}\n\nwatch(\n  visible,\n  (newValue) => {\n    if (newValue) {\n      resetCustomization()\n    }\n  },\n  { immediate: true }\n)\n</script>\n","<template>\n  <TreeExplorer\n    ref=\"treeExplorerRef\"\n    v-model:expanded-keys=\"expandedKeys\"\n    class=\"node-lib-bookmark-tree-explorer\"\n    data-testid=\"node-library-bookmark-tree\"\n    :root=\"renderedBookmarkedRoot\"\n  >\n    <template #node=\"{ node }\">\n      <TreeExplorerTreeNode :node>\n        <template #before-label>\n          <Badge v-if=\"node.data?.experimental\" severity=\"primary\">\n            {{ $t('g.experimental') }}\n          </Badge>\n          <Badge v-if=\"node.data?.deprecated\" severity=\"danger\">\n            {{ $t('g.deprecated') }}\n          </Badge>\n        </template>\n        <template v-if=\"node.data\" #actions>\n          <template v-if=\"subgraphStore.isUserBlueprint(node.data.name)\">\n            <Button\n              variant=\"destructive\"\n              size=\"icon-sm\"\n              :aria-label=\"$t('g.delete')\"\n              @click.stop=\"void subgraphStore.deleteBlueprint(node.data.name)\"\n            >\n              <i class=\"icon-[lucide--trash-2] size-4\" />\n            </Button>\n            <Button\n              variant=\"muted-textonly\"\n              size=\"icon-sm\"\n              :aria-label=\"$t('g.edit')\"\n              @click.stop=\"void subgraphStore.editBlueprint(node.data.name)\"\n            >\n              <i class=\"icon-[lucide--square-pen] size-4\" />\n            </Button>\n          </template>\n          <template v-else>\n            <Button\n              variant=\"muted-textonly\"\n              size=\"icon-sm\"\n              :aria-label=\"$t('icon.bookmark')\"\n              @click.stop=\"void nodeBookmarkStore.toggleBookmark(node.data)\"\n            >\n              <i\n                :class=\"\n                  cn(\n                    nodeBookmarkStore.isBookmarked(node.data)\n                      ? 'pi pi-bookmark-fill'\n                      : 'pi pi-bookmark',\n                    'size-3.5'\n                  )\n                \"\n              />\n            </Button>\n            <Button\n              :tooltip=\"$t('g.learnMore')\"\n              tooltip-side=\"bottom\"\n              variant=\"muted-textonly\"\n              size=\"icon-sm\"\n              :aria-label=\"$t('g.learnMore')\"\n              @click.stop=\"openNodeHelp(node.data)\"\n            >\n              <i class=\"pi pi-question size-3.5\" />\n            </Button>\n          </template>\n        </template>\n      </TreeExplorerTreeNode>\n    </template>\n    <template #preview=\"{ node }\">\n      <NodePreview v-if=\"node.data\" :node-def=\"node.data\" />\n    </template>\n  </TreeExplorer>\n\n  <FolderCustomizationDialog\n    v-model=\"showCustomizationDialog\"\n    :initial-icon=\"initialIcon\"\n    :initial-color=\"initialColor\"\n    @confirm=\"updateCustomization\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, getCurrentInstance, nextTick, ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport FolderCustomizationDialog from '@/components/common/CustomizationDialog.vue'\nimport TreeExplorer from '@/components/common/TreeExplorer.vue'\nimport TreeExplorerTreeNode from '@/components/common/TreeExplorerTreeNode.vue'\nimport NodePreview from '@/components/node/NodePreview.vue'\nimport { renderNodePreview } from '@/components/node/renderNodePreview'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useTreeExpansion } from '@/composables/useTreeExpansion'\nimport { withNodeAddSource } from '@/platform/telemetry/nodeAdded/nodeAddSource'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport { useNodeBookmarkStore } from '@/stores/nodeBookmarkStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useSubgraphStore } from '@/stores/subgraphStore'\nimport type {\n  RenderedTreeExplorerNode,\n  TreeExplorerDragAndDropData,\n  TreeExplorerNode,\n  TreeNode\n} from '@/types/treeExplorerTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst instance = getCurrentInstance()!\nconst appContext = instance.appContext\nconst { filteredNodeDefs, openNodeHelp } = defineProps<{\n  filteredNodeDefs: ComfyNodeDefImpl[]\n  openNodeHelp: (nodeDef: ComfyNodeDefImpl) => void\n}>()\n\nconst expandedKeys = ref<Record<string, boolean>>({})\nconst { expandNode, toggleNodeOnEvent } = useTreeExpansion(expandedKeys)\n\nconst nodeBookmarkStore = useNodeBookmarkStore()\nconst subgraphStore = useSubgraphStore()\nconst bookmarkedRoot = computed<TreeNode<ComfyNodeDefImpl>>(() => {\n  const filterTree = (\n    node: TreeNode<ComfyNodeDefImpl>\n  ): TreeNode<ComfyNodeDefImpl> | null => {\n    if (node.leaf) {\n      if (!node.data) return null\n      const nodeData = node.data\n      // Check if the node's display_name is in the filteredNodeDefs list\n      return filteredNodeDefs.some((def) => def.name === nodeData.name)\n        ? node\n        : null\n    }\n\n    const filteredChildren = node.children\n      ?.map(filterTree)\n      .filter((child): child is TreeNode<ComfyNodeDefImpl> => child !== null)\n\n    if (filteredChildren && filteredChildren.length > 0) {\n      return {\n        ...node,\n        children: filteredChildren\n      }\n    }\n\n    return null // Remove empty folders\n  }\n\n  return filteredNodeDefs.length\n    ? filterTree(nodeBookmarkStore.bookmarkedRoot) || {\n        key: 'root',\n        label: 'Root',\n        children: []\n      }\n    : nodeBookmarkStore.bookmarkedRoot\n})\nwatch(\n  () => filteredNodeDefs,\n  async (newValue) => {\n    if (newValue.length) {\n      await nextTick()\n      expandNode(bookmarkedRoot.value)\n    }\n  }\n)\n\nconst { t } = useI18n()\nconst extraMenuItems = (\n  menuTargetNode: RenderedTreeExplorerNode<ComfyNodeDefImpl>\n) => [\n  {\n    label: t('g.customize'),\n    icon: 'pi pi-palette',\n    command: () => {\n      if (!menuTargetNode.data) return\n\n      const customization =\n        nodeBookmarkStore.bookmarksCustomization[menuTargetNode.data.nodePath]\n      initialIcon.value =\n        customization?.icon || nodeBookmarkStore.defaultBookmarkIcon\n      initialColor.value =\n        customization?.color || nodeBookmarkStore.defaultBookmarkColor\n\n      showCustomizationDialog.value = true\n      customizationTargetNodePath.value = menuTargetNode.data.nodePath\n    },\n    visible: !menuTargetNode?.leaf\n  }\n]\n\nfunction getCustomization(node: TreeNode<ComfyNodeDefImpl>) {\n  return node.data\n    ? nodeBookmarkStore.bookmarksCustomization[node.data.nodePath]\n    : undefined\n}\n\nconst renderedBookmarkedRoot = computed<TreeExplorerNode<ComfyNodeDefImpl>>(\n  () => {\n    const fillNodeInfo = (\n      node: TreeNode<ComfyNodeDefImpl>\n    ): TreeExplorerNode<ComfyNodeDefImpl> => {\n      const children = node.children?.map(fillNodeInfo)\n\n      // Sort children: non-leaf nodes first, then leaf nodes, both alphabetically\n      const sortedChildren = children?.sort((a, b) => {\n        if (a.leaf === b.leaf) {\n          return a.label.localeCompare(b.label)\n        }\n        return a.leaf ? 1 : -1\n      })\n\n      return {\n        key: node.key,\n        label: node.leaf ? (node.data?.display_name ?? node.label) : node.label,\n        leaf: node.leaf,\n        data: node.data,\n        getIcon() {\n          if (this.leaf) {\n            return 'pi pi-circle-fill'\n          }\n          const customization = getCustomization(node)\n          return customization?.icon\n            ? 'pi ' + customization.icon\n            : 'pi pi-bookmark-fill'\n        },\n        getIconColor() {\n          return this.leaf ? undefined : getCustomization(node)?.color\n        },\n        children: sortedChildren,\n        draggable: node.leaf,\n        async handleAddFolder(newName: string) {\n          if (newName !== '') {\n            await nodeBookmarkStore.addNewBookmarkFolder(this.data, newName)\n          }\n        },\n        renderDragPreview(container) {\n          if (!node.data) return\n          return renderNodePreview(container, node.data, appContext)\n        },\n        droppable: !node.leaf,\n        async handleDrop(data: TreeExplorerDragAndDropData<ComfyNodeDefImpl>) {\n          const folderNodeDef = node.data\n          const nodeDefToAdd = data.data.data\n          if (!folderNodeDef || !nodeDefToAdd) return\n          // Remove bookmark if the source is the top level bookmarked node.\n          if (nodeBookmarkStore.isBookmarked(nodeDefToAdd)) {\n            await nodeBookmarkStore.toggleBookmark(nodeDefToAdd)\n          }\n          const nodePath = folderNodeDef.category + '/' + nodeDefToAdd.name\n          await nodeBookmarkStore.addBookmark(nodePath)\n        },\n        handleClick(e: MouseEvent) {\n          const nodeDef = this.data\n          if (this.leaf && nodeDef) {\n            withNodeAddSource('sidebar_drag', () =>\n              useLitegraphService().addNodeOnGraph(nodeDef)\n            )\n          } else {\n            toggleNodeOnEvent(e, node)\n          }\n        },\n        contextMenuItems: extraMenuItems,\n        ...(node.leaf\n          ? node.data && subgraphStore.isUserBlueprint(node.data.name)\n            ? {\n                async handleDelete() {\n                  if (this.data) {\n                    await subgraphStore.deleteBlueprint(this.data.name)\n                  }\n                }\n              }\n            : {}\n          : {\n              async handleRename(newName: string) {\n                if (this.data && this.data.isDummyFolder) {\n                  await nodeBookmarkStore.renameBookmarkFolder(\n                    this.data,\n                    newName\n                  )\n                }\n              },\n              async handleDelete() {\n                if (!this.data) return\n                await nodeBookmarkStore.deleteBookmarkFolder(this.data)\n              }\n            })\n      }\n    }\n    return fillNodeInfo(bookmarkedRoot.value)\n  }\n)\n\ninterface TreeExplorerExposed {\n  addFolderCommand: (targetNodeKey: string) => void\n}\n\nconst treeExplorerRef = ref<TreeExplorerExposed | null>(null)\ndefineExpose({\n  addNewBookmarkFolder: () => treeExplorerRef.value?.addFolderCommand('root')\n})\n\nconst showCustomizationDialog = ref(false)\nconst initialIcon = ref(nodeBookmarkStore.defaultBookmarkIcon)\nconst initialColor = ref(nodeBookmarkStore.defaultBookmarkColor)\nconst customizationTargetNodePath = ref('')\nconst updateCustomization = async (icon: string, color: string) => {\n  if (customizationTargetNodePath.value) {\n    await nodeBookmarkStore.updateBookmarkCustomization(\n      customizationTargetNodePath.value,\n      { icon, color }\n    )\n  }\n}\n</script>\n","<template>\n  <div class=\"h-full\">\n    <SidebarTabTemplate\n      v-if=\"!isHelpOpen\"\n      :title=\"$t('sideToolbar.nodeLibrary')\"\n    >\n      <template #tool-buttons>\n        <Button\n          :tooltip=\"$t('g.newFolder')\"\n          tooltip-side=\"bottom\"\n          class=\"new-folder-button\"\n          variant=\"muted-textonly\"\n          size=\"icon\"\n          :aria-label=\"$t('g.newFolder')\"\n          @click=\"nodeBookmarkTreeExplorerRef?.addNewBookmarkFolder()\"\n        >\n          <i class=\"icon-[lucide--folder-plus] size-4\" />\n        </Button>\n        <Button\n          :tooltip=\"$t('sideToolbar.nodeLibraryTab.groupBy')\"\n          tooltip-side=\"bottom\"\n          variant=\"muted-textonly\"\n          size=\"icon\"\n          :aria-label=\"$t('sideToolbar.nodeLibraryTab.groupBy')\"\n          @click=\"groupingPopover?.toggle($event)\"\n        >\n          <i :class=\"cn(selectedGroupingIcon, 'size-4')\" />\n        </Button>\n        <Button\n          :tooltip=\"$t('sideToolbar.nodeLibraryTab.sortMode')\"\n          tooltip-side=\"bottom\"\n          variant=\"muted-textonly\"\n          size=\"icon\"\n          :aria-label=\"$t('sideToolbar.nodeLibraryTab.sortMode')\"\n          @click=\"sortingPopover?.toggle($event)\"\n        >\n          <i :class=\"cn(selectedSortingIcon, 'size-4')\" />\n        </Button>\n        <Button\n          :tooltip=\"$t('sideToolbar.nodeLibraryTab.resetView')\"\n          tooltip-side=\"bottom\"\n          variant=\"muted-textonly\"\n          size=\"icon\"\n          :aria-label=\"$t('sideToolbar.nodeLibraryTab.resetView')\"\n          @click=\"resetOrganization\"\n        >\n          <i class=\"icon-[lucide--filter-x] size-4\" />\n        </Button>\n        <Button\n          :tooltip=\"$t('menu.refresh')\"\n          tooltip-side=\"bottom\"\n          variant=\"muted-textonly\"\n          size=\"icon\"\n          :aria-label=\"$t('menu.refresh')\"\n          @click=\"() => commandStore.execute('Comfy.RefreshNodeDefinitions')\"\n        >\n          <i class=\"icon-[lucide--refresh-cw] size-4\" />\n        </Button>\n        <Popover ref=\"groupingPopover\">\n          <div class=\"flex flex-col gap-1 p-2\">\n            <Button\n              v-for=\"option in groupingOptions\"\n              :key=\"option.id\"\n              :variant=\"\n                selectedGroupingId === option.id ? 'primary' : 'textonly'\n              \"\n              class=\"justify-start\"\n              @click=\"selectGrouping(option.id)\"\n            >\n              <i :class=\"cn(option.icon, 'size-4')\" />\n              {{ $t(option.label) }}\n            </Button>\n          </div>\n        </Popover>\n        <Popover ref=\"sortingPopover\">\n          <div class=\"flex flex-col gap-1 p-2\">\n            <Button\n              v-for=\"option in sortingOptions\"\n              :key=\"option.id\"\n              :variant=\"\n                selectedSortingId === option.id ? 'primary' : 'textonly'\n              \"\n              class=\"justify-start\"\n              @click=\"selectSorting(option.id)\"\n            >\n              <i :class=\"cn(option.icon, 'size-4')\" />\n              {{ $t(option.label) }}\n            </Button>\n          </div>\n        </Popover>\n      </template>\n      <template #header>\n        <SidebarTopArea>\n          <SearchInput\n            ref=\"searchBoxRef\"\n            v-model=\"searchQuery\"\n            data-testid=\"node-library-search\"\n            class=\"node-lib-search-box\"\n            :placeholder=\"$t('g.searchPlaceholder', { subject: $t('g.nodes') })\"\n            @search=\"handleSearch\"\n          />\n          <template #actions>\n            <Button\n              variant=\"secondary\"\n              size=\"icon\"\n              class=\"filter-button\"\n              :aria-label=\"$t('g.filter')\"\n              @click=\"(e: Event) => searchFilter?.toggle(e)\"\n            >\n              <i class=\"icon-[lucide--list-filter] size-4\" />\n            </Button>\n          </template>\n        </SidebarTopArea>\n        <div class=\"px-4\">\n          <div\n            v-if=\"filters?.length\"\n            class=\"search-filters flex flex-wrap gap-2 pb-2\"\n          >\n            <SearchFilterChip\n              v-for=\"filter in filters\"\n              :key=\"filter.id\"\n              :text=\"filter.text\"\n              :badge=\"filter.badge\"\n              :badge-class=\"filter.badgeClass\"\n              @remove=\"onRemoveFilter(filter)\"\n            />\n          </div>\n\n          <Popover ref=\"searchFilter\" class=\"ml-[-13px]\">\n            <NodeSearchFilter @add-filter=\"onAddFilter\" />\n          </Popover>\n        </div>\n      </template>\n      <template #body>\n        <div>\n          <NodeBookmarkTreeExplorer\n            ref=\"nodeBookmarkTreeExplorerRef\"\n            :filtered-node-defs\n            :open-node-help=\"openNodeHelp\"\n          />\n          <div\n            v-show=\"nodeBookmarkStore.bookmarks.length > 0\"\n            role=\"separator\"\n            class=\"m-2 border-0 border-t border-dashed border-interface-stroke\"\n          />\n          <TreeExplorer\n            v-model:expanded-keys=\"expandedKeys\"\n            data-testid=\"node-library-tree\"\n            class=\"node-lib-tree-explorer\"\n            :root=\"renderedRoot\"\n          >\n            <template #node=\"{ node }\">\n              <TreeExplorerTreeNode :node>\n                <template #before-label>\n                  <Badge v-if=\"node.data?.experimental\" severity=\"primary\">\n                    {{ $t('g.experimental') }}\n                  </Badge>\n                  <Badge v-if=\"node.data?.deprecated\" severity=\"danger\">\n                    {{ $t('g.deprecated') }}\n                  </Badge>\n                </template>\n                <template v-if=\"node.data\" #actions>\n                  <template\n                    v-if=\"subgraphStore.isUserBlueprint(node.data.name)\"\n                  >\n                    <Button\n                      variant=\"destructive\"\n                      size=\"icon-sm\"\n                      :aria-label=\"$t('g.delete')\"\n                      @click.stop=\"\n                        void subgraphStore.deleteBlueprint(node.data.name)\n                      \"\n                    >\n                      <i class=\"icon-[lucide--trash-2] size-4\" />\n                    </Button>\n                    <Button\n                      variant=\"muted-textonly\"\n                      size=\"icon-sm\"\n                      :aria-label=\"$t('g.edit')\"\n                      @click.stop=\"\n                        void subgraphStore.editBlueprint(node.data.name)\n                      \"\n                    >\n                      <i class=\"icon-[lucide--square-pen] size-4\" />\n                    </Button>\n                  </template>\n                  <template v-else>\n                    <Button\n                      variant=\"muted-textonly\"\n                      size=\"icon-sm\"\n                      :aria-label=\"$t('icon.bookmark')\"\n                      @click.stop=\"\n                        void nodeBookmarkStore.toggleBookmark(node.data)\n                      \"\n                    >\n                      <i\n                        :class=\"\n                          cn(\n                            nodeBookmarkStore.isBookmarked(node.data)\n                              ? 'pi pi-bookmark-fill'\n                              : 'pi pi-bookmark',\n                            'size-3.5'\n                          )\n                        \"\n                      />\n                    </Button>\n                    <Button\n                      :tooltip=\"$t('g.learnMore')\"\n                      tooltip-side=\"bottom\"\n                      variant=\"muted-textonly\"\n                      size=\"icon-sm\"\n                      :aria-label=\"$t('g.learnMore')\"\n                      @click.stop=\"openNodeHelp(node.data)\"\n                    >\n                      <i class=\"pi pi-question size-3.5\" />\n                    </Button>\n                  </template>\n                </template>\n              </TreeExplorerTreeNode>\n            </template>\n            <template #preview=\"{ node }\">\n              <NodePreview v-if=\"node.data\" :node-def=\"node.data\" />\n            </template>\n          </TreeExplorer>\n        </div>\n      </template>\n    </SidebarTabTemplate>\n\n    <NodeHelpPage v-else :node=\"currentHelpNode!\" @close=\"closeHelp\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useLocalStorage } from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\nimport Popover from '@/components/common/ImperativePopover.vue'\nimport type { Ref } from 'vue'\nimport {\n  computed,\n  getCurrentInstance,\n  nextTick,\n  onMounted,\n  onUnmounted,\n  ref\n} from 'vue'\n\nimport SearchFilterChip from '@/components/common/SearchFilterChip.vue'\nimport type { SearchFilter } from '@/components/common/SearchFilterChip.vue'\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport TreeExplorer from '@/components/common/TreeExplorer.vue'\nimport TreeExplorerTreeNode from '@/components/common/TreeExplorerTreeNode.vue'\nimport NodePreview from '@/components/node/NodePreview.vue'\nimport { renderNodePreview } from '@/components/node/renderNodePreview'\nimport NodeSearchFilter from '@/components/searchbox/NodeSearchFilter.vue'\nimport SidebarTabTemplate from '@/components/sidebar/tabs/SidebarTabTemplate.vue'\nimport SidebarTopArea from '@/components/sidebar/tabs/SidebarTopArea.vue'\nimport NodeHelpPage from '@/components/sidebar/tabs/nodeLibrary/NodeHelpPage.vue'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useTreeExpansion } from '@/composables/useTreeExpansion'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { withNodeAddSource } from '@/platform/telemetry/nodeAdded/nodeAddSource'\nimport { useSearchQueryTracking } from '@/platform/telemetry/searchQuery/useSearchQueryTracking'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport {\n  DEFAULT_GROUPING_ID,\n  DEFAULT_SORTING_ID,\n  nodeOrganizationService\n} from '@/services/nodeOrganizationService'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useNodeBookmarkStore } from '@/stores/nodeBookmarkStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { useSubgraphStore } from '@/stores/subgraphStore'\nimport { useNodeHelpStore } from '@/stores/workspace/nodeHelpStore'\nimport type {\n  GroupingStrategyId,\n  SortingStrategyId\n} from '@/types/nodeOrganizationTypes'\nimport type { TreeExplorerNode, TreeNode } from '@/types/treeExplorerTypes'\nimport type { FuseFilterWithValue } from '@/utils/fuseUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport NodeBookmarkTreeExplorer from './nodeLibrary/NodeBookmarkTreeExplorer.vue'\n\nconst instance = getCurrentInstance()!\nconst appContext = instance.appContext\nconst nodeDefStore = useNodeDefStore()\nconst nodeBookmarkStore = useNodeBookmarkStore()\nconst nodeHelpStore = useNodeHelpStore()\nconst subgraphStore = useSubgraphStore()\nconst commandStore = useCommandStore()\nconst expandedKeys = ref<Record<string, boolean>>({})\nconst { expandNode, toggleNodeOnEvent } = useTreeExpansion(expandedKeys)\n\nconst nodeBookmarkTreeExplorerRef = ref<InstanceType<\n  typeof NodeBookmarkTreeExplorer\n> | null>(null)\nconst searchBoxRef = ref()\n\nonMounted(() => {\n  searchBoxRef.value?.focus()\n})\n\nconst searchFilter = ref<InstanceType<typeof Popover> | null>(null)\nconst groupingPopover = ref<InstanceType<typeof Popover> | null>(null)\nconst sortingPopover = ref<InstanceType<typeof Popover> | null>(null)\nconst selectedGroupingId = useLocalStorage<GroupingStrategyId>(\n  'Comfy.NodeLibrary.GroupBy',\n  DEFAULT_GROUPING_ID\n)\nconst selectedSortingId = useLocalStorage<SortingStrategyId>(\n  'Comfy.NodeLibrary.SortBy',\n  DEFAULT_SORTING_ID\n)\n\nconst searchQuery = ref<string>('')\n\nconst { currentHelpNode, isHelpOpen } = storeToRefs(nodeHelpStore)\nconst { openHelp, closeHelp } = nodeHelpStore\n\nonUnmounted(closeHelp)\n\nfunction openNodeHelp(nodeDef: ComfyNodeDefImpl) {\n  useTelemetry()?.trackUiButtonClicked({\n    button_id: 'node_library_help_button',\n    element_group: 'node_library'\n  })\n  openHelp(nodeDef)\n}\n\nconst groupingOptions = computed(() =>\n  nodeOrganizationService.getGroupingStrategies().map((strategy) => ({\n    id: strategy.id,\n    label: strategy.label,\n    icon: strategy.icon\n  }))\n)\nconst sortingOptions = computed(() =>\n  nodeOrganizationService.getSortingStrategies().map((strategy) => ({\n    id: strategy.id,\n    label: strategy.label,\n    icon: strategy.icon\n  }))\n)\n\nconst selectedGroupingIcon = computed(() =>\n  nodeOrganizationService.getGroupingIcon(selectedGroupingId.value)\n)\nconst selectedSortingIcon = computed(() =>\n  nodeOrganizationService.getSortingIcon(selectedSortingId.value)\n)\n\nconst selectGrouping = (groupingId: string) => {\n  selectedGroupingId.value = groupingId as GroupingStrategyId\n  groupingPopover.value?.hide()\n}\nconst selectSorting = (sortingId: string) => {\n  selectedSortingId.value = sortingId as SortingStrategyId\n  sortingPopover.value?.hide()\n}\n\nconst resetOrganization = () => {\n  selectedGroupingId.value = DEFAULT_GROUPING_ID\n  selectedSortingId.value = DEFAULT_SORTING_ID\n}\n\nconst root = computed(() => {\n  // Determine which nodes to use\n  const nodes =\n    filteredNodeDefs.value.length > 0\n      ? filteredNodeDefs.value\n      : nodeDefStore.visibleNodeDefs\n\n  // Use the service to organize nodes\n  return nodeOrganizationService.organizeNodes(nodes, {\n    groupBy: selectedGroupingId.value,\n    sortBy: selectedSortingId.value\n  })\n})\n\nconst renderedRoot = computed<TreeExplorerNode<ComfyNodeDefImpl>>(() => {\n  const fillNodeInfo = (\n    node: TreeNode<ComfyNodeDefImpl>\n  ): TreeExplorerNode<ComfyNodeDefImpl> => {\n    const children = node.children?.map(fillNodeInfo)\n\n    return {\n      key: node.key,\n      label: node.leaf ? (node.data?.display_name ?? node.label) : node.label,\n      leaf: node.leaf,\n      data: node.data,\n      getIcon() {\n        if (this.leaf) {\n          return 'pi pi-circle-fill'\n        }\n      },\n      children,\n      draggable: node.leaf,\n      renderDragPreview(container) {\n        if (!node.data) return\n        return renderNodePreview(container, node.data, appContext)\n      },\n      handleClick(e: MouseEvent) {\n        const nodeDef = this.data\n        if (this.leaf && nodeDef) {\n          withNodeAddSource('sidebar_drag', () =>\n            useLitegraphService().addNodeOnGraph(nodeDef)\n          )\n        } else {\n          toggleNodeOnEvent(e, this)\n        }\n      },\n      ...(node.leaf &&\n      node.data &&\n      subgraphStore.isUserBlueprint(node.data.name)\n        ? {\n            async handleDelete() {\n              if (this.data) await subgraphStore.deleteBlueprint(this.data.name)\n            }\n          }\n        : {})\n    }\n  }\n  return fillNodeInfo(root.value)\n})\n\nconst filteredNodeDefs = ref<ComfyNodeDefImpl[]>([])\nuseSearchQueryTracking('node_sidebar', searchQuery, filteredNodeDefs)\nconst filters: Ref<\n  (SearchFilter & { filter: FuseFilterWithValue<ComfyNodeDefImpl, string> })[]\n> = ref([])\nconst handleSearch = async (query: string) => {\n  // Don't apply a min length filter because it does not make sense in\n  // multi-byte languages like Chinese, Japanese, Korean, etc.\n  if (query.length === 0 && !filters.value.length) {\n    filteredNodeDefs.value = []\n    expandedKeys.value = {}\n    return\n  }\n\n  const f = filters.value.map((f) => f.filter)\n  filteredNodeDefs.value = nodeDefStore.nodeSearchService.searchNode(\n    query,\n    f,\n    {\n      limit: 64\n    },\n    {\n      matchWildcards: false\n    }\n  )\n\n  await nextTick()\n  // Expand the search results tree\n  if (filteredNodeDefs.value.length > 0) {\n    expandNode(root.value)\n  }\n}\n\nconst onAddFilter = async (\n  filterAndValue: FuseFilterWithValue<ComfyNodeDefImpl, string>\n) => {\n  filters.value.push({\n    filter: filterAndValue,\n    badge: filterAndValue.filterDef.invokeSequence.toUpperCase(),\n    badgeClass: filterAndValue.filterDef.invokeSequence + '-badge',\n    text: filterAndValue.value,\n    id: +new Date()\n  })\n\n  await handleSearch(searchQuery.value)\n}\n\nconst onRemoveFilter = async (\n  filterAndValue: SearchFilter & {\n    filter: FuseFilterWithValue<ComfyNodeDefImpl, string>\n  }\n) => {\n  const index = filters.value.findIndex((f) => f === filterAndValue)\n  if (index !== -1) {\n    filters.value.splice(index, 1)\n  }\n  await handleSearch(searchQuery.value)\n}\n</script>\n","<script setup lang=\"ts\">\nimport { mapValues } from 'es-toolkit'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\n\nconst { filterLabels } = defineProps<{\n  filterLabels?: Record<string, string>\n}>()\n\nconst { t } = useI18n()\nconst filters = defineModel<Record<string, boolean>>({ required: true })\nconst allSelected = computed(() =>\n  Object.values(filters.value).every((enabled) => enabled)\n)\nconst items = computed<MenuItem[]>(() => [\n  {\n    label: t('g.all'),\n    checked: allSelected.value,\n    command: () => {\n      filters.value = mapValues(filters.value, () => true)\n    }\n  },\n  ...Object.entries(filters.value).map(([filter, enabled]) => ({\n    label: filterLabels?.[filter] ? t(filterLabels[filter]) : filter,\n    checked: enabled && !allSelected.value,\n    command: () => toggleCategory(filter)\n  }))\n])\n\nfunction toggleCategory(category: string) {\n  if (allSelected.value) {\n    for (const k in filters.value) filters.value[k] = false\n  }\n  filters.value[category] = !filters.value[category]\n  if (Object.values(filters.value).every((enabled) => !enabled)) {\n    for (const k in filters.value) filters.value[k] = true\n  }\n}\n</script>\n<template>\n  <Menu :items>\n    <template #trigger>\n      <Button\n        size=\"icon\"\n        :aria-label=\"$t('g.filter')\"\n        icon=\"icon-[lucide--list-filter]\"\n      />\n    </template>\n  </Menu>\n</template>\n","import type { Ref } from 'vue'\nimport { computed } from 'vue'\n\nexport function usePerTabState<K extends string, V>(\n  selectedTab: Ref<K>,\n  stateByTab: Ref<Record<K, V>>\n) {\n  return computed({\n    get: () => stateByTab.value[selectedTab.value],\n    set: (value) => {\n      stateByTab.value[selectedTab.value] = value\n    }\n  })\n}\n","import type { ComputedRef, CSSProperties, MaybeRefOrGetter, Ref } from 'vue'\nimport { computed, ref, toValue } from 'vue'\n\nimport { useNodeDragToCanvas } from '@/composables/node/useNodeDragToCanvas'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\n\nconst PREVIEW_WIDTH = 200\nconst PREVIEW_MARGIN = 16\n\ninterface UseNodePreviewAndDragReturn {\n  isHovered: Ref<boolean>\n  isDragging: Ref<boolean>\n  showPreview: ComputedRef<boolean>\n  nodePreviewStyle: Ref<CSSProperties>\n  sidebarLocation: ComputedRef<'left' | 'right'>\n  handleMouseEnter: (e: MouseEvent) => void\n  handleMouseLeave: () => void\n  handleDragStart: (e: DragEvent) => void\n  handleDragEnd: (e: DragEvent) => void\n}\n\nexport function useNodePreviewAndDrag(\n  nodeDef: Ref<ComfyNodeDefImpl | undefined>,\n  previewRef: Ref<HTMLElement | null>,\n  panelRef?: MaybeRefOrGetter<HTMLElement | null>\n): UseNodePreviewAndDragReturn {\n  const { startDrag, handleNativeDrop } = useNodeDragToCanvas()\n  const settingStore = useSettingStore()\n  const sidebarLocation = computed<'left' | 'right'>(() =>\n    settingStore.get('Comfy.Sidebar.Location')\n  )\n\n  const isHovered = ref(false)\n  const isDragging = ref(false)\n  const showPreview = computed(() => isHovered.value && !isDragging.value)\n\n  const nodePreviewStyle = ref<CSSProperties>({\n    position: 'fixed',\n    top: '0px',\n    left: '0px',\n    pointerEvents: 'none',\n    zIndex: 1000\n  })\n\n  function calculatePreviewPosition(rect: DOMRect) {\n    const viewportHeight = window.innerHeight\n    const viewportWidth = window.innerWidth\n\n    let left: number\n    if (sidebarLocation.value === 'left') {\n      left = rect.right + PREVIEW_MARGIN\n      if (left + PREVIEW_WIDTH > viewportWidth) {\n        left = rect.left - PREVIEW_MARGIN - PREVIEW_WIDTH\n      }\n    } else {\n      left = rect.left - PREVIEW_MARGIN - PREVIEW_WIDTH\n      if (left < 0) {\n        left = rect.right + PREVIEW_MARGIN\n      }\n    }\n\n    return { left, viewportHeight }\n  }\n\n  function handleMouseEnter(e: MouseEvent) {\n    if (!nodeDef.value) return\n\n    const target = e.currentTarget as HTMLElement\n    const rect = target.getBoundingClientRect()\n    const horizontalRect = toValue(panelRef)?.getBoundingClientRect() ?? rect\n    const { left, viewportHeight } = calculatePreviewPosition(horizontalRect)\n\n    let top = rect.top\n\n    nodePreviewStyle.value = {\n      position: 'fixed',\n      top: `${top}px`,\n      left: `${left}px`,\n      pointerEvents: 'none',\n      zIndex: 1000,\n      opacity: 0\n    }\n    isHovered.value = true\n\n    requestAnimationFrame(() => {\n      if (previewRef.value) {\n        const previewRect = previewRef.value.getBoundingClientRect()\n        const previewHeight = previewRect.height\n\n        const mouseY = rect.top + rect.height / 2\n        top = mouseY - previewHeight * 0.3\n\n        const minTop = PREVIEW_MARGIN\n        const maxTop = viewportHeight - previewHeight - PREVIEW_MARGIN\n        top = Math.max(minTop, Math.min(top, maxTop))\n\n        nodePreviewStyle.value = {\n          ...nodePreviewStyle.value,\n          top: `${top}px`,\n          opacity: 1\n        }\n      }\n    })\n  }\n\n  function handleMouseLeave() {\n    isHovered.value = false\n  }\n\n  function createEmptyDragImage(): HTMLElement {\n    const el = document.createElement('div')\n    el.style.position = 'absolute'\n    el.style.left = '-9999px'\n    el.style.top = '-9999px'\n    el.style.width = '1px'\n    el.style.height = '1px'\n    return el\n  }\n\n  function handleDragStart(e: DragEvent) {\n    if (!nodeDef.value) return\n\n    isDragging.value = true\n    isHovered.value = false\n\n    startDrag(nodeDef.value, { mode: 'native' })\n\n    if (e.dataTransfer) {\n      e.dataTransfer.effectAllowed = 'copy'\n      e.dataTransfer.setData('application/x-comfy-node', nodeDef.value.name)\n\n      const dragImage = createEmptyDragImage()\n      document.body.appendChild(dragImage)\n      e.dataTransfer.setDragImage(dragImage, 0, 0)\n\n      requestAnimationFrame(() => {\n        document.body.removeChild(dragImage)\n      })\n    }\n  }\n\n  function handleDragEnd(e: DragEvent) {\n    isDragging.value = false\n    handleNativeDrop(e.clientX, e.clientY)\n  }\n\n  return {\n    isHovered,\n    isDragging,\n    showPreview,\n    nodePreviewStyle,\n    sidebarLocation,\n    handleMouseEnter,\n    handleMouseLeave,\n    handleDragStart,\n    handleDragEnd\n  }\n}\n","<template>\n  <TreeItem\n    v-slot=\"{ isExpanded, handleToggle, handleSelect }\"\n    :value=\"item.value\"\n    :level=\"item.level\"\n    as-child\n  >\n    <!-- Node -->\n    <div\n      v-if=\"item.value.type === 'node'\"\n      v-bind=\"$attrs\"\n      :class=\"cn(treeItemClass, 'overflow-hidden')\"\n      :style=\"treeItemIndent(item.level)\"\n      draggable=\"true\"\n      @click.stop=\"handleClick($event, handleToggle, handleSelect)\"\n      @contextmenu=\"handleContextMenu\"\n      @pointerdown=\"handleContextMenu\"\n      @mouseenter=\"handleMouseEnter\"\n      @mouseleave=\"handleMouseLeave\"\n      @dragstart=\"handleDragStart\"\n      @dragend=\"handleDragEnd\"\n    >\n      <i class=\"icon-[comfy--node] size-4 shrink-0 text-muted-foreground\" />\n      <span class=\"min-w-0 flex-1 truncate\">\n        <slot name=\"node\" :node=\"item.value\">\n          {{ item.value.label }}\n        </slot>\n      </span>\n      <div class=\"flex shrink-0 items-center gap-0.5\">\n        <Button\n          v-if=\"isUserBlueprint\"\n          variant=\"muted-textonly\"\n          size=\"icon-sm\"\n          class=\"opacity-0 group-hover/tree-node:opacity-100\"\n          :aria-label=\"$t('g.delete')\"\n          @click.stop=\"deleteBlueprint\"\n        >\n          <i class=\"icon-[lucide--trash-2] bg-destructive-background\" />\n        </Button>\n        <Button\n          v-if=\"isUserBlueprint\"\n          variant=\"muted-textonly\"\n          size=\"icon-sm\"\n          class=\"opacity-0 group-hover/tree-node:opacity-100\"\n          :aria-label=\"$t('g.edit')\"\n          @click.stop=\"editBlueprint\"\n        >\n          <i class=\"icon-[lucide--square-pen]\" />\n        </Button>\n        <Button\n          variant=\"muted-textonly\"\n          size=\"icon-sm\"\n          class=\"opacity-0 group-hover/tree-node:opacity-100\"\n          :aria-label=\"$t('icon.bookmark')\"\n          @click.stop=\"toggleBookmark\"\n        >\n          <i :class=\"isBookmarked ? 'pi pi-bookmark-fill' : 'pi pi-bookmark'\" />\n        </Button>\n      </div>\n    </div>\n\n    <!-- Folder -->\n    <div\n      v-else\n      v-bind=\"$attrs\"\n      :class=\"cn(treeItemClass, 'overflow-hidden')\"\n      :style=\"treeItemIndent(item.level)\"\n      @click.stop=\"handleClick($event, handleToggle, handleSelect)\"\n      @contextmenu=\"clearContextMenuNode\"\n      @pointerdown=\"clearContextMenuNode\"\n    >\n      <i\n        v-if=\"item.hasChildren\"\n        :class=\"\n          cn(\n            'icon-[lucide--chevron-down] size-4 shrink-0 text-muted-foreground transition-transform',\n            !isExpanded && '-rotate-90'\n          )\n        \"\n      />\n      <i\n        :class=\"cn(item.value.icon, 'size-4 shrink-0 text-muted-foreground')\"\n      />\n      <span class=\"min-w-0 flex-1 truncate\">\n        <slot name=\"folder\" :node=\"item.value\">\n          {{ item.value.label }}\n        </slot>\n      </span>\n    </div>\n  </TreeItem>\n\n  <Teleport\n    v-if=\"showPreview && item.value.type === 'node' && item.value.data\"\n    to=\"body\"\n  >\n    <div ref=\"previewRef\" :style=\"nodePreviewStyle\">\n      <NodePreviewCard :node-def=\"item.value.data as ComfyNodeDefImpl\" />\n    </div>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nimport type { FlattenedItem } from 'reka-ui'\nimport { TreeItem } from 'reka-ui'\nimport { computed, inject, useTemplateRef } from 'vue'\n\nimport NodePreviewCard from '@/components/node/NodePreviewCard.vue'\nimport { useNodePreviewAndDrag } from '@/composables/node/useNodePreviewAndDrag'\nimport Button from '@/components/ui/button/Button.vue'\nimport { treeItemClass, treeItemIndent } from '@/components/ui/tree/treeStyles'\nimport { useNodeBookmarkStore } from '@/stores/nodeBookmarkStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useSubgraphStore } from '@/stores/subgraphStore'\nimport { InjectKeyContextMenuNode } from '@/types/treeExplorerTypes'\nimport type { RenderedTreeExplorerNode } from '@/types/treeExplorerTypes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\ndefineOptions({\n  inheritAttrs: false\n})\n\nconst { item } = defineProps<{\n  item: FlattenedItem<RenderedTreeExplorerNode<ComfyNodeDefImpl>>\n}>()\n\nconst emit = defineEmits<{\n  nodeClick: [\n    node: RenderedTreeExplorerNode<ComfyNodeDefImpl>,\n    event: MouseEvent\n  ]\n}>()\n\nconst contextMenuNode = inject(InjectKeyContextMenuNode)\nconst nodeBookmarkStore = useNodeBookmarkStore()\nconst subgraphStore = useSubgraphStore()\nconst previewRef = useTemplateRef('previewRef')\n\nconst nodeDef = computed(() => item.value.data)\n\nconst isBookmarked = computed(() => {\n  if (!nodeDef.value) return false\n  return nodeBookmarkStore.isBookmarked(nodeDef.value)\n})\n\nconst isUserBlueprint = computed(() =>\n  subgraphStore.isUserBlueprint(nodeDef.value?.name)\n)\n\nfunction toggleBookmark() {\n  if (nodeDef.value) {\n    nodeBookmarkStore.toggleBookmark(nodeDef.value)\n  }\n}\n\nfunction deleteBlueprint() {\n  if (nodeDef.value) {\n    void subgraphStore.deleteBlueprint(nodeDef.value.name)\n  }\n}\nconst editBlueprint = async () => {\n  if (!nodeDef.value) {\n    console.error('Failed to edit subgraph blueprint lacking backing node data')\n    return\n  }\n  await useSubgraphStore().editBlueprint(nodeDef.value.name)\n}\n\nconst {\n  showPreview,\n  nodePreviewStyle,\n  handleMouseEnter: baseHandleMouseEnter,\n  handleMouseLeave,\n  handleDragStart: baseHandleDragStart,\n  handleDragEnd\n} = useNodePreviewAndDrag(nodeDef, previewRef)\n\nfunction handleClick(\n  e: MouseEvent,\n  handleToggle: () => void,\n  handleSelect: () => void\n) {\n  handleSelect()\n  if (item.value.type === 'folder') {\n    handleToggle()\n  }\n  emit('nodeClick', item.value, e)\n}\n\nfunction handleContextMenu() {\n  if (contextMenuNode) {\n    contextMenuNode.value = item.value\n  }\n}\n\nfunction clearContextMenuNode() {\n  if (contextMenuNode) {\n    contextMenuNode.value = null\n  }\n}\n\nfunction handleMouseEnter(e: MouseEvent) {\n  if (item.value.type !== 'node') return\n  baseHandleMouseEnter(e)\n}\n\nfunction handleDragStart(e: DragEvent) {\n  if (item.value.type !== 'node' || !item.value.data) return\n  baseHandleDragStart(e)\n}\n</script>\n","<template>\n  <ContextMenuRoot :modal=\"false\">\n    <ContextMenuTrigger as-child :disabled=\"!showContextMenu\">\n      <TreeRoot\n        v-model:expanded=\"expandedKeys\"\n        :items=\"root.children ?? []\"\n        :get-key=\"(item) => item.key\"\n        :get-children=\"\n          (item) => (item.children?.length ? item.children : undefined)\n        \"\n        class=\"m-0 min-w-0 p-0 px-2 pb-2\"\n        @contextmenu=\"preventEmptyContextMenu\"\n        @pointerdown=\"\n          $event.pointerType !== 'mouse' && preventEmptyContextMenu($event)\n        \"\n      >\n        <TreeVirtualizer\n          v-slot=\"{ item }\"\n          :estimate-size=\"36\"\n          :text-content=\"(item) => item.value.label ?? ''\"\n        >\n          <TreeExplorerV2Node\n            :item=\"\n              item as FlattenedItem<RenderedTreeExplorerNode<ComfyNodeDefImpl>>\n            \"\n            @node-click=\"\n              (\n                node: RenderedTreeExplorerNode<ComfyNodeDefImpl>,\n                e: MouseEvent\n              ) => emit('nodeClick', node, e)\n            \"\n          >\n            <template #folder=\"{ node }\">\n              <slot name=\"folder\" :node=\"node\" />\n            </template>\n            <template #node=\"{ node }\">\n              <slot name=\"node\" :node=\"node\" />\n            </template>\n          </TreeExplorerV2Node>\n        </TreeVirtualizer>\n      </TreeRoot>\n    </ContextMenuTrigger>\n    <ContextMenuPortal>\n      <ContextMenuContent :class=\"menuContentClass\">\n        <MenuItems :items=\"menuItems\" />\n      </ContextMenuContent>\n    </ContextMenuPortal>\n  </ContextMenuRoot>\n</template>\n\n<script setup lang=\"ts\">\nimport type { FlattenedItem } from 'reka-ui'\nimport {\n  ContextMenuRoot,\n  ContextMenuTrigger,\n  ContextMenuPortal,\n  ContextMenuContent,\n  TreeRoot,\n  TreeVirtualizer\n} from 'reka-ui'\nimport { computed, provide, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport MenuItems from '@/components/ui/menu/MenuItems.vue'\nimport { menuContentClass } from '@/components/ui/menu/menuStyles'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useNodeBookmarkStore } from '@/stores/nodeBookmarkStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useSubgraphStore } from '@/stores/subgraphStore'\nimport type { RenderedTreeExplorerNode } from '@/types/treeExplorerTypes'\nimport { InjectKeyContextMenuNode } from '@/types/treeExplorerTypes'\n\nimport TreeExplorerV2Node from './TreeExplorerV2Node.vue'\n\nconst { showContextMenu = false } = defineProps<{\n  root: RenderedTreeExplorerNode<ComfyNodeDefImpl>\n  showContextMenu?: boolean\n}>()\n\nconst expandedKeys = defineModel<string[]>('expandedKeys', {\n  default: () => []\n})\n\nconst emit = defineEmits<{\n  nodeClick: [\n    node: RenderedTreeExplorerNode<ComfyNodeDefImpl>,\n    event: MouseEvent\n  ]\n}>()\n\nconst contextMenuNode = ref<RenderedTreeExplorerNode<ComfyNodeDefImpl> | null>(\n  null\n)\nprovide(InjectKeyContextMenuNode, contextMenuNode)\n\nconst nodeBookmarkStore = useNodeBookmarkStore()\nconst subgraphStore = useSubgraphStore()\nconst { t } = useI18n()\n\nconst isCurrentNodeBookmarked = computed(() => {\n  const node = contextMenuNode.value\n  if (!node?.data) return false\n  return nodeBookmarkStore.isBookmarked(node.data)\n})\n\nconst isCurrentNodeUserBlueprint = computed(() =>\n  subgraphStore.isUserBlueprint(contextMenuNode.value?.data?.name)\n)\n\nconst menuItems = computed<MenuItem[]>(() => [\n  {\n    label: isCurrentNodeBookmarked.value\n      ? t('sideToolbar.nodeLibraryTab.sections.unfavoriteNode')\n      : t('sideToolbar.nodeLibraryTab.sections.favoriteNode'),\n    icon: isCurrentNodeBookmarked.value\n      ? 'icon-[ph--star-fill]'\n      : 'icon-[lucide--star]',\n    command: handleToggleBookmark\n  },\n  {\n    label: t('g.delete'),\n    icon: 'icon-[lucide--trash-2]',\n    visible: isCurrentNodeUserBlueprint.value,\n    class: 'text-destructive-background',\n    command: handleDeleteBlueprint\n  }\n])\n\nfunction preventEmptyContextMenu(event: Event) {\n  if (!contextMenuNode.value?.data) event.preventDefault()\n}\n\nfunction handleToggleBookmark() {\n  const node = contextMenuNode.value\n  if (node?.data) {\n    nodeBookmarkStore.toggleBookmark(node.data)\n  }\n}\n\nfunction handleDeleteBlueprint() {\n  const name = contextMenuNode.value?.data?.name\n  if (name) {\n    void subgraphStore.deleteBlueprint(name)\n  }\n}\n</script>\n","import type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport type { TreeNode } from '@/types/treeExplorerTypes'\n\nexport type GroupingStrategyId = 'category' | 'module' | 'source'\nexport type SortingStrategyId = 'original' | 'alphabetical'\nexport type TabId = 'essentials' | 'all' | 'blueprints'\n\n/**\n * Strategy for grouping nodes into tree structure\n */\nexport interface NodeGroupingStrategy {\n  /** Unique identifier for the grouping strategy */\n  id: string\n  /** Display name for UI (i18n key) */\n  label: string\n  /** Icon class for the grouping option */\n  icon: string\n  /** Description for tooltips (i18n key) */\n  description?: string\n  /** Function to extract the tree path from a node definition */\n  getNodePath: (nodeDef: ComfyNodeDefImpl) => string[]\n}\n\n/**\n * Strategy for sorting nodes within groups\n */\nexport interface NodeSortStrategy {\n  /** Unique identifier for the sort strategy */\n  id: string\n  /** Display name for UI (i18n key) */\n  label: string\n  /** Icon class for the sort option */\n  icon: string\n  /** Description for tooltips (i18n key) */\n  description?: string\n  /** Compare function for sorting nodes within the same group */\n  compare: (a: ComfyNodeDefImpl, b: ComfyNodeDefImpl) => number\n}\n\n/**\n * Options for organizing nodes\n */\nexport interface NodeOrganizationOptions {\n  groupBy?: string\n  sortBy?: string\n}\n\nexport type NodeCategoryId =\n  | 'blueprints'\n  | 'comfyNodes'\n  | 'extensions'\n  | 'partnerNodes'\n\nexport const NODE_CATEGORY_LABELS: Record<NodeCategoryId, string> = {\n  blueprints: 'sideToolbar.nodeLibraryTab.sections.subgraphBlueprints',\n  comfyNodes: 'sideToolbar.nodeLibraryTab.sections.comfyNodes',\n  extensions: 'sideToolbar.nodeLibraryTab.sections.extensions',\n  partnerNodes: 'sideToolbar.nodeLibraryTab.sections.partnerNodes'\n}\n\nexport interface NodeSection {\n  /** Tree of nodes in this section */\n  tree: TreeNode<ComfyNodeDefImpl>\n  /** Filter category identifier */\n  category?: NodeCategoryId\n  /** Section title (i18n key) for tabs that don't use category-based labels */\n  title?: string\n}\n","<template>\n  <div class=\"h-full flex-1 overflow-y-auto\">\n    <!-- Favorites section -->\n    <h3\n      class=\"mb-0 px-4 py-2 text-xs font-medium tracking-wide text-muted-foreground uppercase\"\n    >\n      {{ $t('sideToolbar.nodeLibraryTab.sections.bookmarked') }}\n    </h3>\n    <TreeExplorerV2\n      v-if=\"hasFavorites\"\n      v-model:expanded-keys=\"expandedKeys\"\n      :root=\"favoritesRoot\"\n      show-context-menu\n      @node-click=\"(node) => emit('nodeClick', node)\"\n    />\n    <div v-else class=\"px-6 py-2 text-xs text-muted-background\">\n      {{ $t('sideToolbar.nodeLibraryTab.noBookmarkedNodes') }}\n    </div>\n\n    <!-- Node sections -->\n    <div v-for=\"(section, index) in sections\" :key=\"section.category ?? index\">\n      <h3\n        v-if=\"section.category && sortOrder !== 'alphabetical'\"\n        class=\"mb-0 px-4 py-2 text-xs font-medium tracking-wide text-muted-foreground uppercase\"\n      >\n        {{ $t(NODE_CATEGORY_LABELS[section.category]) }}\n      </h3>\n      <TreeExplorerV2\n        v-model:expanded-keys=\"expandedKeys\"\n        :root=\"section.root\"\n        show-context-menu\n        @node-click=\"(node) => emit('nodeClick', node)\"\n      />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport TreeExplorerV2 from '@/components/common/TreeExplorerV2.vue'\nimport { useNodeBookmarkStore } from '@/stores/nodeBookmarkStore'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { NODE_CATEGORY_LABELS } from '@/types/nodeOrganizationTypes'\nimport type {\n  NodeLibrarySection,\n  RenderedTreeExplorerNode,\n  TreeNode\n} from '@/types/treeExplorerTypes'\n\nconst { fillNodeInfo, sortOrder = 'original' } = defineProps<{\n  fillNodeInfo: (\n    node: TreeNode<ComfyNodeDefImpl>\n  ) => RenderedTreeExplorerNode<ComfyNodeDefImpl>\n  sections: NodeLibrarySection<ComfyNodeDefImpl>[]\n  sortOrder?: string\n}>()\n\nconst expandedKeys = defineModel<string[]>('expandedKeys', { required: true })\n\nconst emit = defineEmits<{\n  nodeClick: [node: RenderedTreeExplorerNode<ComfyNodeDefImpl>]\n}>()\n\nconst nodeBookmarkStore = useNodeBookmarkStore()\n\nconst hasFavorites = computed(\n  () => (nodeBookmarkStore.bookmarkedRoot.children?.length ?? 0) > 0\n)\n\nconst favoritesRoot = computed(() =>\n  fillNodeInfo(nodeBookmarkStore.bookmarkedRoot)\n)\n</script>\n","import { computed, toValue } from 'vue'\nimport type { MaybeRefOrGetter } from 'vue'\n\nimport type { EssentialTile } from '@/constants/essentialsNodes'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport { BLUEPRINT_TYPE_PREFIX } from '@/utils/blueprintUtils'\n\nexport function resolveEssentialTileNodeDef(\n  tile: EssentialTile,\n  nodeDefStore: ReturnType<typeof useNodeDefStore>\n): ComfyNodeDefImpl | undefined {\n  const name = tile.nodeName\n  if (!name) return undefined\n  if (!name.startsWith(BLUEPRINT_TYPE_PREFIX))\n    return nodeDefStore.allNodeDefsByName[name]\n\n  const subgraphName = name.slice(BLUEPRINT_TYPE_PREFIX.length)\n  return nodeDefStore.allNodeDefsByDisplayName[subgraphName]\n}\n\nexport function useEssentialTileNodeDef(tile: MaybeRefOrGetter<EssentialTile>) {\n  const nodeDefStore = useNodeDefStore()\n  return computed(() =>\n    resolveEssentialTileNodeDef(toValue(tile), nodeDefStore)\n  )\n}\n","<template>\n  <div\n    class=\"@container overflow-hidden mask-[linear-gradient(to_right,black_70%,transparent)] motion-safe:group-hover:mask-none\"\n  >\n    <span\n      class=\"inline-block min-w-full text-center whitespace-nowrap [--_marquee-end:min(calc(-100%+100cqw),0px)] motion-safe:group-hover:animate-[marquee-scroll_2s_linear_infinite_alternate]\"\n    >\n      <slot />\n    </span>\n  </div>\n</template>\n\n<style>\n@keyframes marquee-scroll {\n  0%,\n  20% {\n    transform: translateX(0);\n  }\n  80%,\n  100% {\n    transform: translateX(var(--_marquee-end));\n  }\n}\n</style>\n","export function splitTextAtWordBoundary(\n  text: string,\n  ratio: number\n): [string, string] {\n  if (ratio >= 1) return [text, '']\n  const estimate = Math.floor(text.length * ratio)\n  const before = text.lastIndexOf(' ', estimate)\n  const breakIndex = before > 0 ? before : text.indexOf(' ')\n  if (breakIndex <= 0) return [text, '']\n  return [text.substring(0, breakIndex), text.substring(breakIndex + 1)]\n}\n","<template>\n  <div ref=\"containerRef\" class=\"w-full\">\n    <!-- Hidden single-line measurement element for overflow detection -->\n    <div\n      ref=\"measureRef\"\n      class=\"pointer-events-none invisible absolute inset-x-0 top-0 overflow-hidden whitespace-nowrap\"\n      aria-hidden=\"true\"\n      v-text=\"text\"\n    />\n    <div class=\"flex w-full flex-col\">\n      <MarqueeLine v-for=\"(line, index) in lines\" :key=\"index\">\n        {{ line }}\n      </MarqueeLine>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useElementSize } from '@vueuse/core'\nimport { computed, useTemplateRef } from 'vue'\n\nimport MarqueeLine from './MarqueeLine.vue'\nimport { splitTextAtWordBoundary } from '@/utils/textTickerUtils'\n\nconst { text } = defineProps<{ text: string }>()\n\nconst measureRef = useTemplateRef('measureRef')\nconst containerRef = useTemplateRef('containerRef')\nconst { width: textWidth } = useElementSize(measureRef)\nconst { width: containerWidth } = useElementSize(containerRef)\n\nconst lines = computed(() => {\n  if (!textWidth.value || !containerWidth.value) return [text]\n\n  const safeRenderWidth = containerWidth.value - 30\n  if (textWidth.value <= safeRenderWidth) return [text]\n\n  return splitTextAtWordBoundary(text, safeRenderWidth / textWidth.value)\n})\n</script>\n","<template>\n  <div\n    :class=\"\n      cn(\n        'group @container relative flex aspect-square w-full flex-col items-center justify-center gap-2 rounded-lg bg-secondary-background pt-3 pb-2 transition-colors duration-150 select-none hover:bg-secondary-background-hover',\n        nodeDef ? 'cursor-grab active:cursor-grabbing' : 'cursor-default'\n      )\n    \"\n    :data-node-name=\"tile.nodeName\"\n    :draggable=\"nodeDef != null\"\n    @mouseenter=\"handleMouseEnter\"\n    @mouseleave=\"handleMouseLeave\"\n    @click=\"nodeDef && useNodeDragToCanvas().startDrag(nodeDef)\"\n    @dragstart=\"handleDragStart\"\n    @dragend=\"handleDragEnd\"\n  >\n    <i :class=\"cn('size-7 text-muted-foreground', tile.icon)\" />\n    <span\n      v-if=\"tile.partnerLogo\"\n      aria-hidden=\"true\"\n      class=\"absolute top-1.5 right-1.5 flex size-6 items-center justify-center rounded-md bg-base-background\"\n    >\n      <i :class=\"cn('size-4 text-smoke-600', tile.partnerLogo)\" />\n    </span>\n    <TextTickerMultiLine\n      class=\"flex h-7.5 w-full shrink-0 flex-col justify-center px-2 text-center text-xs/3.75 font-normal text-base-foreground @min-[7rem]:h-9 @min-[7rem]:text-sm/4.5\"\n      :text=\"nodeDef?.display_name ?? tile.nodeName\"\n    />\n  </div>\n\n  <Teleport v-if=\"showPreview && nodeDef\" to=\"body\">\n    <div ref=\"previewRef\" :style=\"nodePreviewStyle\">\n      <NodePreviewCard :node-def :show-inputs-and-outputs=\"false\" />\n    </div>\n  </Teleport>\n</template>\n\n<script setup lang=\"ts\">\nimport { useTemplateRef } from 'vue'\n\nimport TextTickerMultiLine from '@/components/common/TextTickerMultiLine.vue'\nimport NodePreviewCard from '@/components/node/NodePreviewCard.vue'\nimport { useNodeDragToCanvas } from '@/composables/node/useNodeDragToCanvas'\nimport { useNodePreviewAndDrag } from '@/composables/node/useNodePreviewAndDrag'\nimport { useEssentialTileNodeDef } from '@/composables/useEssentialTileNodeDef'\nimport type { EssentialTile } from '@/constants/essentialsNodes'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { previewPanel, tile } = defineProps<{\n  tile: EssentialTile\n  previewPanel?: HTMLElement | null\n}>()\nconst nodeDef = useEssentialTileNodeDef(() => tile)\nconst previewRef = useTemplateRef('previewRef')\n\nconst {\n  showPreview,\n  nodePreviewStyle,\n  handleMouseEnter,\n  handleMouseLeave,\n  handleDragStart,\n  handleDragEnd\n} = useNodePreviewAndDrag(nodeDef, previewRef, () => previewPanel ?? null)\n</script>\n","<template>\n  <div ref=\"previewPanel\">\n    <div\n      v-if=\"filteredSections.length === 0\"\n      class=\"flex min-h-0 flex-1 items-center justify-center px-6 py-8 text-center text-sm text-muted-foreground\"\n    >\n      {{\n        t('sideToolbar.nodeLibraryTab.noMatchingNodes', {\n          query: searchQuery\n        })\n      }}\n    </div>\n    <div\n      v-for=\"section in filteredSections\"\n      :id=\"`essentials-section-${section.key}`\"\n      :key=\"section.key\"\n      class=\"border-b border-border-default last:border-b-0\"\n    >\n      <div\n        class=\"sticky top-0 z-10 flex h-14 w-full items-center justify-between border-0 bg-comfy-menu-bg px-4 text-sm font-bold tracking-wide text-muted-foreground\"\n      >\n        <span class=\"uppercase\">{{ $t(`essentials.${section.key}`) }}</span>\n      </div>\n      <div\n        v-if=\"section.tiles?.length\"\n        class=\"grid grid-cols-[repeat(auto-fill,minmax(96px,1fr))] gap-2 p-4\"\n      >\n        <EssentialNodeCard\n          v-for=\"tile in section.tiles.filter(\n            (tile) => !tile.media || mediaFilters[tile.media]\n          )\"\n          :key=\"tile.nodeName\"\n          :preview-panel\n          :tile\n        />\n      </div>\n      <div v-else class=\"flex flex-col gap-10 px-4\">\n        <div\n          v-for=\"subgroup in section.subgroups?.filter(\n            (s) => mediaFilters[s.media]\n          )\"\n          :id=\"`essentials-subgroup-${subgroup.key}`\"\n          :key=\"subgroup.key\"\n          class=\"scroll-mt-30 last:pb-4\"\n        >\n          <div class=\"text-sm leading-[15px] font-normal text-base-foreground\">\n            {{ $t(`essentials.${subgroup.key}`) }}\n          </div>\n          <div\n            class=\"mt-4 grid grid-cols-[repeat(auto-fill,minmax(96px,1fr))] gap-2\"\n          >\n            <EssentialNodeCard\n              v-for=\"tile in subgroup.tiles\"\n              :key=\"tile.nodeName\"\n              :preview-panel\n              :tile\n            />\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, useTemplateRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { resolveEssentialTileNodeDef } from '@/composables/useEssentialTileNodeDef'\nimport type {\n  EssentialsMediaType,\n  EssentialSection,\n  EssentialTile\n} from '@/constants/essentialsNodes'\nimport { ESSENTIAL_SECTIONS } from '@/constants/essentialsNodes'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\n\nimport EssentialNodeCard from './EssentialNodeCard.vue'\n\nconst { t } = useI18n()\nconst { searchQuery = '' } = defineProps<{\n  searchQuery?: string\n  mediaFilters: Record<EssentialsMediaType, boolean>\n}>()\nconst previewPanel = useTemplateRef('previewPanel')\nconst nodeDefStore = useNodeDefStore()\n\nconst filteredSections = computed<EssentialSection[]>(() => {\n  const query = searchQuery.trim().toLowerCase()\n  if (!query) return ESSENTIAL_SECTIONS\n\n  const matchesQuery = (tile: EssentialTile) => {\n    const name =\n      resolveEssentialTileNodeDef(tile, nodeDefStore)?.display_name ??\n      tile.nodeName\n    return name.toLowerCase().includes(query)\n  }\n  return ESSENTIAL_SECTIONS.flatMap<EssentialSection>((section) => {\n    if (section.tiles?.length) {\n      const tiles = section.tiles.filter(matchesQuery)\n      return tiles.length ? [{ ...section, tiles }] : []\n    }\n\n    const subgroups = section.subgroups\n      ?.map((sg) => ({ ...sg, tiles: sg.tiles.filter(matchesQuery) }))\n      .filter((sg) => sg.tiles.length)\n    return subgroups?.length ? [{ ...section, subgroups }] : []\n  })\n})\n</script>\n","<template>\n  <SidebarTabTemplate :title=\"$t('sideToolbar.nodes')\">\n    <template #header>\n      <div class=\"overflow-x-auto px-4 pt-2 pb-px\">\n        <TabList v-model=\"selectedTab\">\n          <Tab v-for=\"{ value, label } in tabs\" :key=\"value\" :value>\n            {{ label }}\n          </Tab>\n        </TabList>\n      </div>\n      <SidebarTopArea>\n        <SearchInput\n          ref=\"searchBoxRef\"\n          v-model=\"searchQuery\"\n          :placeholder=\"$t('g.searchPlaceholder', { subject: $t('g.nodes') })\"\n          @search=\"handleSearch\"\n        />\n        <template #actions>\n          <FilterDropdown\n            v-if=\"selectedTab === 'essentials'\"\n            v-model=\"essentialsFilters\"\n            :filter-labels=\"essentialsFilterLabels\"\n          />\n          <FilterDropdown\n            v-else\n            v-model=\"nodeFilters\"\n            :filter-labels=\"nodeFilterLabels\"\n          />\n          <Menu\n            v-if=\"selectedTab === 'essentials'\"\n            :items=\"jumpMenuEntries\"\n            :label=\"$t('essentials.jumpTo')\"\n          >\n            <template #trigger>\n              <Button\n                size=\"icon\"\n                :aria-label=\"$t('essentials.jumpTo')\"\n                icon=\"icon-[lucide--list-tree]\"\n              />\n            </template>\n          </Menu>\n          <Menu v-else>\n            <template #trigger>\n              <Button\n                size=\"icon\"\n                :aria-label=\"$t('g.sort')\"\n                icon=\"icon-[lucide--settings-2]\"\n              />\n            </template>\n            <MenuRadioGroup v-model=\"sortOrder\" :options=\"sortingOptions\" />\n          </Menu>\n        </template>\n      </SidebarTopArea>\n    </template>\n    <template #body>\n      <div class=\"flex h-full flex-col\">\n        <div\n          ref=\"scrollContainerRef\"\n          class=\"scrollbar-custom min-h-0 flex-1 scrollbar-gutter-stable overscroll-none pb-2\"\n        >\n          <TabPanel\n            v-if=\"flags.nodeLibraryEssentialsEnabled\"\n            :model-value=\"selectedTab\"\n            value=\"essentials\"\n          >\n            <EssentialNodesPanel\n              :media-filters=\"essentialsFilters\"\n              :search-query\n            />\n          </TabPanel>\n          <TabPanel :model-value=\"selectedTab\" value=\"all\">\n            <div\n              v-if=\"hasNoMatches\"\n              class=\"flex min-h-0 flex-1 items-center justify-center px-6 py-8 text-center text-sm text-muted-foreground\"\n            >\n              {{\n                $t('sideToolbar.nodeLibraryTab.noMatchingNodes', {\n                  query: searchQuery\n                })\n              }}\n            </div>\n            <AllNodesPanel\n              v-else\n              v-model:expanded-keys=\"expandedKeys\"\n              :sections=\"renderedSections\"\n              :fill-node-info=\"fillNodeInfo\"\n              :sort-order=\"sortOrder\"\n              @node-click=\"handleNodeClick\"\n            />\n          </TabPanel>\n        </div>\n      </div>\n    </template>\n  </SidebarTabTemplate>\n</template>\n\n<script setup lang=\"ts\">\nimport { useLocalStorage } from '@vueuse/core'\nimport { mapValues } from 'es-toolkit'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport {\n  computed,\n  nextTick,\n  onMounted,\n  ref,\n  useTemplateRef,\n  watchEffect\n} from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport FilterDropdown from '@/components/common/FilterDropdown.vue'\nimport Tab from '@/components/tab/Tab.vue'\nimport TabList from '@/components/tab/TabList.vue'\nimport TabPanel from '@/components/tab/TabPanel.vue'\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport MenuRadioGroup from '@/components/ui/menu/MenuRadioGroup.vue'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useNodeDragToCanvas } from '@/composables/node/useNodeDragToCanvas'\nimport { usePerTabState } from '@/composables/usePerTabState'\nimport { ESSENTIAL_SECTIONS } from '@/constants/essentialsNodes'\nimport { useSearchQueryTracking } from '@/platform/telemetry/searchQuery/useSearchQueryTracking'\nimport {\n  DEFAULT_SORTING_ID,\n  DEFAULT_TAB_ID,\n  nodeOrganizationService\n} from '@/services/nodeOrganizationService'\nimport type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\nimport { buildNodeDefTree, useNodeDefStore } from '@/stores/nodeDefStore'\nimport type {\n  NodeCategoryId,\n  NodeSection,\n  SortingStrategyId,\n  TabId\n} from '@/types/nodeOrganizationTypes'\nimport type {\n  NodeLibrarySection,\n  RenderedTreeExplorerNode,\n  TreeNode\n} from '@/types/treeExplorerTypes'\nimport { getProviderIcon } from '@/utils/categoryUtil'\nimport { flattenTree, sortedTree, unwrapTreeRoot } from '@/utils/treeUtil'\n\nimport AllNodesPanel from './nodeLibrary/AllNodesPanel.vue'\nimport EssentialNodesPanel from './nodeLibrary/EssentialNodesPanel.vue'\nimport SidebarTabTemplate from './SidebarTabTemplate.vue'\nimport SidebarTopArea from './SidebarTopArea.vue'\n\nconst { flags } = useFeatureFlags()\n\nconst scrollContainerRef = useTemplateRef('scrollContainerRef')\n\nconst selectedTab = useLocalStorage<TabId>(\n  'Comfy.NodeLibrary.Tab',\n  DEFAULT_TAB_ID\n)\n\nwatchEffect(() => {\n  if (selectedTab.value === 'blueprints') selectedTab.value = DEFAULT_TAB_ID\n  if (\n    !flags.nodeLibraryEssentialsEnabled &&\n    selectedTab.value === 'essentials'\n  ) {\n    selectedTab.value = DEFAULT_TAB_ID\n  }\n})\n\nconst sortOrderByTab = useLocalStorage<Record<TabId, SortingStrategyId>>(\n  'Comfy.NodeLibrary.SortByTab',\n  {\n    essentials: DEFAULT_SORTING_ID,\n    all: DEFAULT_SORTING_ID,\n    blueprints: 'alphabetical'\n  }\n)\nconst sortOrder = usePerTabState(selectedTab, sortOrderByTab)\n\nconst sortingOptions = computed(() =>\n  nodeOrganizationService.getSortingStrategies().map((strategy) => ({\n    value: strategy.id,\n    label: t(strategy.label)\n  }))\n)\n\nconst nodeFilterLabels: Record<NodeCategoryId, string> = {\n  blueprints: 'sideToolbar.nodeLibraryTab.filterOptions.blueprints',\n  comfyNodes: 'sideToolbar.nodeLibraryTab.filterOptions.comfyNodes',\n  partnerNodes: 'sideToolbar.nodeLibraryTab.filterOptions.partnerNodes',\n  extensions: 'sideToolbar.nodeLibraryTab.filterOptions.extensions'\n} as const\nconst nodeFilters = ref(mapValues(nodeFilterLabels, () => true))\nconst essentialsFilterLabels = {\n  image: 'sideToolbar.mediaAssets.filterImage',\n  video: 'sideToolbar.mediaAssets.filterVideo',\n  text: 'sideToolbar.mediaAssets.filterText',\n  audio: 'sideToolbar.mediaAssets.filterAudio',\n  '3d': 'sideToolbar.mediaAssets.filter3D'\n} as const\nconst essentialsFilters = ref(mapValues(essentialsFilterLabels, () => true))\n\nconst { t } = useI18n()\n\nconst searchBoxRef = useTemplateRef('searchBoxRef')\nconst searchQuery = ref('')\nconst expandedKeysByTab = ref<Record<TabId, string[]>>({\n  essentials: [],\n  all: [],\n  blueprints: []\n})\nconst expandedKeys = usePerTabState(selectedTab, expandedKeysByTab)\n\nconst nodeDefStore = useNodeDefStore()\nconst { startDrag } = useNodeDragToCanvas()\n\nconst filteredNodeDefs = computed(() => {\n  if (searchQuery.value.length === 0) {\n    return []\n  }\n  return nodeDefStore.nodeSearchService.searchNode(\n    searchQuery.value,\n    [],\n    { limit: 64 },\n    { matchWildcards: false }\n  )\n})\n\nconst activeNodes = computed(() =>\n  searchQuery.value.length === 0\n    ? nodeDefStore.visibleNodeDefs\n    : filteredNodeDefs.value\n)\n\nuseSearchQueryTracking('node_sidebar', searchQuery, filteredNodeDefs)\n\nconst hasNoMatches = computed(\n  () => searchQuery.value.length > 0 && filteredNodeDefs.value.length === 0\n)\n\nconst sections = computed(() => {\n  return nodeOrganizationService.organizeNodesTab(activeNodes.value)\n})\n\nfunction getFolderIcon(node: TreeNode<ComfyNodeDefImpl>): string {\n  const firstLeaf = findFirstLeaf(node)\n  if (\n    firstLeaf?.data?.api_node &&\n    firstLeaf.key?.replace(`${node.key}/`, '') === firstLeaf.label\n  ) {\n    return getProviderIcon(node.label ?? '')\n  }\n  return 'icon-[lucide--folder]'\n}\n\nfunction findFirstLeaf(\n  node: TreeNode<ComfyNodeDefImpl>\n): TreeNode<ComfyNodeDefImpl> | undefined {\n  if (node.leaf) return node\n  for (const child of node.children ?? []) {\n    const leaf = findFirstLeaf(child)\n    if (leaf) return leaf\n  }\n  return undefined\n}\n\nfunction fillNodeInfo(\n  node: TreeNode<ComfyNodeDefImpl>\n): RenderedTreeExplorerNode<ComfyNodeDefImpl> {\n  const children = node.children?.map(fillNodeInfo)\n  const totalLeaves = node.leaf\n    ? 1\n    : (children?.reduce((acc, child) => acc + child.totalLeaves, 0) ?? 0)\n\n  return {\n    key: node.key,\n    label: node.leaf ? (node.data?.display_name ?? node.label) : node.label,\n    leaf: node.leaf,\n    data: node.data,\n    icon: node.leaf ? 'icon-[comfy--node]' : getFolderIcon(node),\n    type: node.leaf ? 'node' : 'folder',\n    totalLeaves,\n    children\n  }\n}\n\nfunction applySorting(\n  tree: TreeNode<ComfyNodeDefImpl>\n): TreeNode<ComfyNodeDefImpl> {\n  if (sortOrder.value === 'alphabetical') {\n    return sortedTree(tree, { groupLeaf: true })\n  }\n  return tree\n}\n\nfunction renderSections(\n  nodeSections: NodeSection[],\n  filter?: (section: NodeSection) => boolean\n): NodeLibrarySection<ComfyNodeDefImpl>[] {\n  const filtered = filter ? nodeSections.filter(filter) : nodeSections\n\n  if (sortOrder.value === 'alphabetical') {\n    const allNodes = filtered.flatMap((section) =>\n      flattenTree<ComfyNodeDefImpl>(section.tree)\n    )\n    const mergedTree = unwrapTreeRoot(buildNodeDefTree(allNodes))\n    return [{ root: fillNodeInfo(applySorting(mergedTree)) }]\n  }\n\n  return filtered.map((section) => ({\n    category: section.category,\n    title: section.title,\n    root: fillNodeInfo(applySorting(section.tree))\n  }))\n}\n\nconst renderedSections = computed(() =>\n  renderSections(\n    sections.value,\n    (section) => !section.category || nodeFilters.value[section.category]\n  )\n)\n\nfunction collectFolderKeys(node: TreeNode<ComfyNodeDefImpl>): string[] {\n  if (node.leaf) return []\n  const keys = [node.key]\n  for (const child of node.children ?? []) {\n    keys.push(...collectFolderKeys(child))\n  }\n  return keys\n}\n\nfunction handleNodeClick(node: RenderedTreeExplorerNode<ComfyNodeDefImpl>) {\n  if (node.type === 'node' && node.data) {\n    startDrag(node.data)\n  }\n}\n\nasync function handleSearch() {\n  await nextTick()\n\n  if (selectedTab.value === 'essentials') return\n\n  if (filteredNodeDefs.value.length === 0) {\n    expandedKeys.value = []\n    return\n  }\n\n  const allKeys: string[] = []\n  for (const section of sections.value) {\n    allKeys.push(...collectFolderKeys(section.tree))\n  }\n  expandedKeys.value = allKeys\n}\n\nfunction smoothScrollTo(\n  container: HTMLElement,\n  target: number,\n  duration = 300\n) {\n  const start = container.scrollTop\n  const distance = target - start\n  if (Math.abs(distance) < 1) return\n  const startTime = performance.now()\n  function step(now: number) {\n    const elapsed = now - startTime\n    const progress = Math.min(elapsed / duration, 1)\n    const eased = 1 - Math.pow(1 - progress, 3)\n    container.scrollTop = start + distance * eased\n    if (progress < 1) requestAnimationFrame(step)\n  }\n  requestAnimationFrame(step)\n}\n\nasync function scrollToId(id: string, marginTop = 0) {\n  await nextTick()\n  const container = scrollContainerRef.value\n  const el = document.getElementById(id)\n  if (!container || !el) return\n  const top =\n    el.getBoundingClientRect().top -\n    container.getBoundingClientRect().top +\n    container.scrollTop -\n    marginTop\n  smoothScrollTo(container, top)\n}\n\nconst STICKY_SECTION_HEADER_HEIGHT = 56\nasync function jumpToSection(sectionKey: string) {\n  await scrollToId(`essentials-section-${sectionKey}`)\n}\n\nasync function jumpToSubgroup(subgroupKey: string) {\n  await scrollToId(\n    `essentials-subgroup-${subgroupKey}`,\n    STICKY_SECTION_HEADER_HEIGHT\n  )\n}\n\nconst jumpMenuEntries = computed<MenuItem[]>(() => {\n  return ESSENTIAL_SECTIONS.map((section) => {\n    if (!section.subgroups)\n      return {\n        label: t(`essentials.${section.key}`),\n        command: () => jumpToSection(section.key)\n      }\n\n    const items = section.subgroups.map((subgroup) => ({\n      label: t(`essentials.${subgroup.key}`),\n      command: () => jumpToSubgroup(subgroup.key)\n    }))\n    return { label: t(`essentials.${section.key}`), items }\n  })\n})\n\nconst tabs = computed<Array<{ value: TabId; label: string }>>(() => {\n  const allNodesTab = {\n    value: 'all',\n    label: t('sideToolbar.nodeLibraryTab.allNodes')\n  } as const\n  if (!flags.nodeLibraryEssentialsEnabled) return [allNodesTab]\n  return [\n    {\n      value: 'essentials',\n      label: t('sideToolbar.nodeLibraryTab.essentials')\n    },\n    allNodesTab\n  ]\n})\n\nonMounted(() => {\n  searchBoxRef.value?.focus()\n})\n</script>\n","import { computed, markRaw, reactive } from 'vue'\n\nimport NodeLibrarySidebarTab from '@/components/sidebar/tabs/NodeLibrarySidebarTab.vue'\nimport NodeLibrarySidebarTabV2 from '@/components/sidebar/tabs/NodeLibrarySidebarTabV2.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type { SidebarTabExtension } from '@/types/extensionTypes'\n\nexport function useNodeLibrarySidebarTab(): SidebarTabExtension {\n  const settingStore = useSettingStore()\n  const component = computed(() =>\n    settingStore.get('Comfy.NodeLibrary.NewDesign')\n      ? markRaw(NodeLibrarySidebarTabV2)\n      : markRaw(NodeLibrarySidebarTab)\n  )\n\n  return reactive({\n    id: 'node-library',\n    icon: 'icon-[comfy--node]',\n    title: 'sideToolbar.nodeLibrary',\n    tooltip: 'sideToolbar.nodeLibrary',\n    label: 'sideToolbar.labels.nodes',\n    component,\n    type: 'vue' as const\n  })\n}\n","<template>\n  <div class=\"flex items-center\">\n    <span v-if=\"position === 'left'\" class=\"mr-2 shrink-0\">{{ text }}</span>\n    <div\n      role=\"separator\"\n      :class=\"\n        cn(\n          'grow border-0 border-t border-interface-stroke',\n          type === 'dashed' && 'border-dashed',\n          type === 'dotted' && 'border-dotted'\n        )\n      \"\n    />\n    <span v-if=\"position === 'right'\" class=\"ml-2 shrink-0\">{{ text }}</span>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  text,\n  position = 'left',\n  type = 'solid'\n} = defineProps<{\n  text: string\n  position?: 'left' | 'right'\n  type?: 'solid' | 'dashed' | 'dotted'\n}>()\n</script>\n","<template>\n  <TreeExplorerTreeNode :node=\"node\">\n    <template #actions>\n      <Button\n        variant=\"muted-textonly\"\n        size=\"icon-sm\"\n        :aria-label=\"$t('icon.bookmark')\"\n        @click.stop=\"handleBookmarkClick\"\n      >\n        <i\n          :class=\"[\n            isBookmarked ? 'pi pi-bookmark-fill' : 'pi pi-bookmark',\n            'size-3.5'\n          ]\"\n        />\n      </Button>\n    </template>\n  </TreeExplorerTreeNode>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport TreeExplorerTreeNode from '@/components/common/TreeExplorerTreeNode.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\nimport { useWorkflowBookmarkStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type { RenderedTreeExplorerNode } from '@/types/treeExplorerTypes'\n\nconst { node } = defineProps<{\n  node: RenderedTreeExplorerNode<ComfyWorkflow>\n}>()\n\nconst workflowBookmarkStore = useWorkflowBookmarkStore()\nconst isBookmarked = computed(\n  () => node.data && workflowBookmarkStore.isBookmarked(node.data.path)\n)\n\nconst handleBookmarkClick = async () => {\n  if (node.data) {\n    await workflowBookmarkStore.toggleBookmarked(node.data.path)\n  }\n}\n</script>\n","<template>\n  <SidebarTabTemplate\n    :title=\"title\"\n    v-bind=\"$attrs\"\n    :data-testid=\"dataTestid\"\n    class=\"workflows-sidebar-tab\"\n  >\n    <template #alt-title>\n      <slot name=\"alt-title\" />\n    </template>\n    <template #tool-buttons>\n      <Button\n        :tooltip=\"$t('g.refresh')\"\n        tooltip-side=\"bottom\"\n        data-testid=\"workflows-refresh-button\"\n        variant=\"muted-textonly\"\n        size=\"icon\"\n        :aria-label=\"$t('g.refresh')\"\n        :aria-busy=\"workflowStore.isSyncLoading\"\n        :disabled=\"workflowStore.isSyncLoading\"\n        @click=\"workflowStore.syncWorkflows()\"\n      >\n        <i\n          aria-hidden=\"true\"\n          data-testid=\"workflows-refresh-icon\"\n          :class=\"\n            cn(\n              'icon-[lucide--refresh-cw] size-4',\n              workflowStore.isSyncLoading && 'animate-spin'\n            )\n          \"\n        />\n      </Button>\n      <slot\n        name=\"header-actions\"\n        :has-results=\"filteredPersistedWorkflows.length > 0\"\n      />\n    </template>\n    <template #header>\n      <SidebarTopArea>\n        <SearchInput\n          ref=\"searchBoxRef\"\n          v-model:model-value=\"searchQuery\"\n          :placeholder=\"$t('g.searchPlaceholder', { subject: searchSubject })\"\n          @search=\"handleSearch\"\n        />\n      </SidebarTopArea>\n    </template>\n    <template #body>\n      <div v-if=\"!isSearching\" class=\"comfyui-workflows-panel\">\n        <div\n          v-if=\"workflowTabsPosition === 'Sidebar'\"\n          class=\"comfyui-workflows-open\"\n        >\n          <TextDivider\n            :text=\"t('sideToolbar.workflowTab.workflowTreeType.open')\"\n            type=\"dashed\"\n            class=\"ml-2\"\n          />\n          <TreeExplorer\n            v-model:expanded-keys=\"dummyExpandedKeys\"\n            :root=\"renderTreeNode(openWorkflowsTree, WorkflowTreeType.Open)\"\n            :selection-keys=\"selectionKeys\"\n          >\n            <template #node=\"{ node }\">\n              <TreeExplorerTreeNode :node=\"node\">\n                <template #before-label=\"{ node: treeNode }\">\n                  <span\n                    v-if=\"\n                      treeNode.data?.isModified || !treeNode.data?.isPersisted\n                    \"\n                    >*</span\n                  >\n                </template>\n                <template #actions=\"{ node: treeNode }\">\n                  <Button\n                    class=\"close-workflow-button\"\n                    :variant=\"\n                      workspaceStore.shiftDown ? 'destructive' : 'textonly'\n                    \"\n                    size=\"icon-sm\"\n                    :aria-label=\"$t('g.close')\"\n                    @click.stop=\"handleCloseWorkflow(treeNode.data)\"\n                  >\n                    <i class=\"icon-[lucide--x] size-3\" />\n                  </Button>\n                </template>\n              </TreeExplorerTreeNode>\n            </template>\n          </TreeExplorer>\n        </div>\n        <div\n          v-show=\"filteredBookmarkedWorkflows.length > 0\"\n          class=\"comfyui-workflows-bookmarks\"\n        >\n          <TextDivider\n            :text=\"t('sideToolbar.workflowTab.workflowTreeType.bookmarks')\"\n            type=\"dashed\"\n            class=\"ml-2\"\n          />\n          <TreeExplorer\n            v-model:expanded-keys=\"dummyExpandedKeys\"\n            :root=\"\n              renderTreeNode(\n                bookmarkedWorkflowsTree,\n                WorkflowTreeType.Bookmarks\n              )\n            \"\n            :selection-keys=\"selectionKeys\"\n          >\n            <template #node=\"{ node }\">\n              <WorkflowTreeLeaf :node=\"node\" />\n            </template>\n          </TreeExplorer>\n        </div>\n        <div class=\"comfyui-workflows-browse\">\n          <TextDivider\n            :text=\"t('sideToolbar.workflowTab.workflowTreeType.browse')\"\n            type=\"dashed\"\n            class=\"ml-2\"\n          />\n          <TreeExplorer\n            v-if=\"filteredPersistedWorkflows.length > 0\"\n            v-model:expanded-keys=\"expandedKeys\"\n            :root=\"renderTreeNode(workflowsTree, WorkflowTreeType.Browse)\"\n            :selection-keys=\"selectionKeys\"\n          >\n            <template #node=\"{ node }\">\n              <WorkflowTreeLeaf :node=\"node\" />\n            </template>\n          </TreeExplorer>\n          <slot v-else name=\"empty-state\">\n            <NoResultsPlaceholder\n              icon=\"pi pi-folder\"\n              :title=\"$t('g.empty')\"\n              :message=\"$t('g.noWorkflowsFound')\"\n            />\n          </slot>\n        </div>\n      </div>\n      <div v-else class=\"comfyui-workflows-search-panel\">\n        <TreeExplorer\n          v-model:expanded-keys=\"expandedKeys\"\n          :root=\"renderTreeNode(filteredRoot, WorkflowTreeType.Browse)\"\n        >\n          <template #node=\"{ node }\">\n            <WorkflowTreeLeaf :node=\"node\" />\n          </template>\n        </TreeExplorer>\n      </div>\n    </template>\n  </SidebarTabTemplate>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, nextTick, onMounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport NoResultsPlaceholder from '@/components/common/NoResultsPlaceholder.vue'\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport SidebarTopArea from '@/components/sidebar/tabs/SidebarTopArea.vue'\nimport TextDivider from '@/components/common/TextDivider.vue'\nimport TreeExplorer from '@/components/common/TreeExplorer.vue'\nimport TreeExplorerTreeNode from '@/components/common/TreeExplorerTreeNode.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport SidebarTabTemplate from '@/components/sidebar/tabs/SidebarTabTemplate.vue'\nimport WorkflowTreeLeaf from '@/components/sidebar/tabs/workflows/WorkflowTreeLeaf.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useTreeExpansion } from '@/composables/useTreeExpansion'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useSearchQueryTracking } from '@/platform/telemetry/searchQuery/useSearchQueryTracking'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport {\n  ComfyWorkflow,\n  useWorkflowBookmarkStore,\n  useWorkflowStore\n} from '@/platform/workflow/management/stores/workflowStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport type { TreeExplorerNode, TreeNode } from '@/types/treeExplorerTypes'\nimport {\n  ensureWorkflowSuffix,\n  getFilenameDetails,\n  getWorkflowSuffix\n} from '@/utils/formatUtil'\nimport { buildTree, sortedTree } from '@/utils/treeUtil'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { title, filter, searchSubject, dataTestid, hideLeafIcon } = defineProps<{\n  title: string\n  filter?: (workflow: ComfyWorkflow) => boolean\n  searchSubject: string\n  dataTestid: string\n  hideLeafIcon?: boolean\n}>()\n\nconst { t } = useI18n()\nconst { isAppMode } = useAppMode()\n\nconst applyFilter = (workflows: ComfyWorkflow[]) =>\n  filter ? workflows.filter(filter) : workflows\n\nconst settingStore = useSettingStore()\nconst workflowTabsPosition = computed(() =>\n  settingStore.get('Comfy.Workflow.WorkflowTabsPosition')\n)\n\nconst searchBoxRef = ref()\n\nconst searchQuery = ref('')\nconst isSearching = computed(() => searchQuery.value.length > 0)\nconst filteredWorkflows = computed(() => {\n  if (searchQuery.value.length === 0) return []\n  const lowerQuery = searchQuery.value.toLocaleLowerCase()\n  return applyFilter(workflowStore.workflows).filter((workflow) =>\n    workflow.path.toLocaleLowerCase().includes(lowerQuery)\n  )\n})\nuseSearchQueryTracking('apps', searchQuery, filteredWorkflows)\nconst filteredRoot = computed<TreeNode<ComfyWorkflow>>(() => {\n  return buildWorkflowTree(filteredWorkflows.value)\n})\nconst handleSearch = async (query: string) => {\n  if (query.length === 0) {\n    expandedKeys.value = {}\n    return\n  }\n  await nextTick()\n  expandNode(filteredRoot.value)\n}\n\nconst workflowStore = useWorkflowStore()\nconst workflowService = useWorkflowService()\nconst workspaceStore = useWorkspaceStore()\nconst expandedKeys = ref<Record<string, boolean>>({})\nconst { expandNode, toggleNodeOnEvent } = useTreeExpansion(expandedKeys)\nconst dummyExpandedKeys = ref<Record<string, boolean>>({})\n\nconst handleCloseWorkflow = async (workflow?: ComfyWorkflow) => {\n  if (workflow) {\n    await workflowService.closeWorkflow(workflow, {\n      warnIfUnsaved: !workspaceStore.shiftDown\n    })\n  }\n}\n\nenum WorkflowTreeType {\n  Open = 'Open',\n  Bookmarks = 'Bookmarks',\n  Browse = 'Browse'\n}\n\nconst buildWorkflowTree = (workflows: ComfyWorkflow[]) => {\n  return buildTree(workflows, (workflow: ComfyWorkflow) =>\n    workflow.key.split('/')\n  )\n}\n\nconst filteredPersistedWorkflows = computed(() =>\n  applyFilter(workflowStore.persistedWorkflows)\n)\nconst filteredBookmarkedWorkflows = computed(() =>\n  applyFilter(workflowStore.bookmarkedWorkflows)\n)\n\nconst workflowsTree = computed(() =>\n  sortedTree(buildWorkflowTree(filteredPersistedWorkflows.value), {\n    groupLeaf: true\n  })\n)\n// Bookmarked workflows tree is flat.\nconst bookmarkedWorkflowsTree = computed(() =>\n  buildTree(filteredBookmarkedWorkflows.value, (workflow) => [workflow.key])\n)\n// Open workflows tree is flat.\nconst openWorkflowsTree = computed(() =>\n  buildTree(applyFilter(workflowStore.openWorkflows), (workflow) => [\n    workflow.key\n  ])\n)\n\nfunction renamedWorkflowPath(\n  workflow: ComfyWorkflow,\n  type: WorkflowTreeType,\n  newName: string\n) {\n  const fileName = ensureWorkflowSuffix(\n    newName,\n    getWorkflowSuffix(workflow.suffix)\n  )\n  if (type === WorkflowTreeType.Browse) {\n    return `${workflow.directory}/${fileName}`\n  }\n  return ComfyWorkflow.basePath + fileName\n}\n\nfunction workflowContextMenuItems(workflow: ComfyWorkflow): MenuItem[] {\n  const duplicate: MenuItem = {\n    label: t('g.duplicate'),\n    icon: 'pi pi-file-export',\n    command: () => workflowService.duplicateWorkflow(workflow)\n  }\n  if (isAppMode.value) return [duplicate]\n\n  const insert: MenuItem = {\n    label: t('g.insert'),\n    icon: 'pi pi-file-export',\n    command: () => workflowService.insertWorkflow(workflow)\n  }\n  return [insert, duplicate]\n}\n\nfunction workflowLeafActions(\n  workflow: ComfyWorkflow,\n  type: WorkflowTreeType\n): Partial<TreeExplorerNode<ComfyWorkflow>> {\n  const actions: Partial<TreeExplorerNode<ComfyWorkflow>> = {\n    contextMenuItems: () => workflowContextMenuItems(workflow),\n    draggable: true,\n    handleRename: (newName: string) =>\n      workflowService.renameWorkflow(\n        workflow,\n        renamedWorkflowPath(workflow, type, newName)\n      )\n  }\n  if (!workflow.isTemporary) {\n    actions.handleDelete = async () => {\n      await workflowService.deleteWorkflow(workflow)\n    }\n  }\n  return actions\n}\n\nconst renderTreeNode = (\n  node: TreeNode<ComfyWorkflow>,\n  type: WorkflowTreeType\n): TreeExplorerNode<ComfyWorkflow> => {\n  const workflow = node.data\n\n  async function handleClick(\n    this: TreeExplorerNode<ComfyWorkflow>,\n    e: MouseEvent\n  ) {\n    if (this.leaf && workflow) {\n      await workflowService.openWorkflow(workflow)\n    } else {\n      toggleNodeOnEvent(e, this)\n    }\n  }\n\n  return {\n    key: node.key,\n    label: node.leaf ? getFilenameDetails(node.label).filename : node.label,\n    children: node.children?.map((child) => renderTreeNode(child, type)),\n    data: workflow,\n    handleClick,\n    icon: node.leaf && hideLeafIcon ? 'hidden' : undefined,\n    leaf: node.leaf,\n    ...(node.leaf && workflow ? workflowLeafActions(workflow, type) : {})\n  }\n}\n\nconst selectionKeys = computed(() => ({\n  [`root/${workflowStore.activeWorkflow?.key}`]: true\n}))\n\nconst workflowBookmarkStore = useWorkflowBookmarkStore()\nonMounted(async () => {\n  searchBoxRef.value?.focus()\n  await workflowBookmarkStore.loadBookmarks()\n})\n</script>\n","<template>\n  <BaseWorkflowsSidebarTab\n    :title=\"$t('linearMode.appModeToolbar.apps')\"\n    :filter=\"isAppWorkflow\"\n    hide-leaf-icon\n    :search-subject=\"$t('linearMode.appModeToolbar.apps')\"\n    data-testid=\"apps-sidebar\"\n  >\n    <template #alt-title>\n      <span\n        class=\"ml-2 flex items-center rounded-full bg-primary-background px-1.5 py-0.5 text-2xs text-base-foreground uppercase\"\n      >\n        {{ $t('g.beta') }}\n      </span>\n    </template>\n    <template #header-actions=\"{ hasResults }\">\n      <Button\n        v-if=\"hasResults\"\n        variant=\"secondary\"\n        size=\"md\"\n        @click=\"createApp\"\n      >\n        <i class=\"icon-[lucide--plus] size-4\" aria-hidden=\"true\" />\n        {{ $t('linearMode.appModeToolbar.create') }}\n      </Button>\n    </template>\n    <template #empty-state>\n      <NoResultsPlaceholder\n        button-variant=\"secondary\"\n        text-class=\"text-muted-foreground text-sm\"\n        :message=\"`${$t('linearMode.appModeToolbar.appsEmptyMessage')}\\n${$t('linearMode.appModeToolbar.appsEmptyMessageAction')}`\"\n        button-icon=\"icon-[lucide--plus]\"\n        :button-label=\"$t('linearMode.appModeToolbar.createApp')\"\n        @action=\"createApp\"\n      />\n    </template>\n  </BaseWorkflowsSidebarTab>\n</template>\n\n<script setup lang=\"ts\">\nimport NoResultsPlaceholder from '@/components/common/NoResultsPlaceholder.vue'\nimport BaseWorkflowsSidebarTab from '@/components/sidebar/tabs/BaseWorkflowsSidebarTab.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCommandStore } from '@/stores/commandStore'\n\nconst commandStore = useCommandStore()\n\nfunction isAppWorkflow(workflow: ComfyWorkflow): boolean {\n  return workflow.suffix === 'app.json'\n}\n\nfunction createApp() {\n  void commandStore.execute('Comfy.NewBlankWorkflow')\n}\n</script>\n","import { markRaw } from 'vue'\n\nimport AppsSidebarTab from '@/components/sidebar/tabs/AppsSidebarTab.vue'\nimport type { SidebarTabExtension } from '@/types/extensionTypes'\n\nexport const useAppsSidebarTab = (): SidebarTabExtension => {\n  return {\n    id: 'apps',\n    icon: 'icon-[lucide--panels-top-left]',\n    title: 'linearMode.appModeToolbar.apps',\n    tooltip: 'linearMode.appModeToolbar.apps',\n    component: markRaw(AppsSidebarTab),\n    type: 'vue'\n  }\n}\n","<template>\n  <BaseWorkflowsSidebarTab\n    :title=\"$t('sideToolbar.workflows')\"\n    :search-subject=\"$t('sideToolbar.workflows')\"\n    data-testid=\"workflows-sidebar\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport BaseWorkflowsSidebarTab from '@/components/sidebar/tabs/BaseWorkflowsSidebarTab.vue'\n</script>\n","import { markRaw } from 'vue'\n\nimport WorkflowsSidebarTab from '@/components/sidebar/tabs/WorkflowsSidebarTab.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type { SidebarTabExtension } from '@/types/extensionTypes'\n\nexport const useWorkflowsSidebarTab = (): SidebarTabExtension => {\n  const settingStore = useSettingStore()\n  const workflowStore = useWorkflowStore()\n  return {\n    id: 'workflows',\n    icon: 'icon-[comfy--workflow]',\n    iconBadge: () => {\n      if (\n        settingStore.get('Comfy.Workflow.WorkflowTabsPosition') !== 'Sidebar'\n      ) {\n        return null\n      }\n      const value = workflowStore.openWorkflows.length.toString()\n      return value === '0' ? null : value\n    },\n    title: 'sideToolbar.workflows',\n    tooltip: 'sideToolbar.workflows',\n    label: 'sideToolbar.labels.workflows',\n    component: markRaw(WorkflowsSidebarTab),\n    type: 'vue'\n  }\n}\n","import { watch } from 'vue'\n\nimport { useAssetsSidebarTab } from '@/composables/sidebarTabs/useAssetsSidebarTab'\nimport { useJobHistorySidebarTab } from '@/composables/sidebarTabs/useJobHistorySidebarTab'\nimport { useModelLibrarySidebarTab } from '@/composables/sidebarTabs/useModelLibrarySidebarTab'\nimport { useNodeLibrarySidebarTab } from '@/composables/sidebarTabs/useNodeLibrarySidebarTab'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useAppsSidebarTab } from '@/platform/workflow/management/composables/useAppsSidebarTab'\nimport { useWorkflowsSidebarTab } from '@/platform/workflow/management/composables/useWorkflowsSidebarTab'\nimport { useMenuItemStore } from '@/stores/menuItemStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\n\nexport function registerCoreSidebarTabs() {\n  const sidebarTabStore = useSidebarTabStore()\n  const settingStore = useSettingStore()\n  const jobHistoryTabId = 'job-history'\n  const syncJobHistoryTab = (enabled: boolean) => {\n    const hasJobHistoryTab = sidebarTabStore.sidebarTabs.some(\n      (tab) => tab.id === jobHistoryTabId\n    )\n    if (enabled && !hasJobHistoryTab) {\n      sidebarTabStore.registerSidebarTab(useJobHistorySidebarTab(), {\n        prepend: true\n      })\n    } else if (!enabled && hasJobHistoryTab) {\n      sidebarTabStore.unregisterSidebarTab(jobHistoryTabId)\n    }\n  }\n\n  syncJobHistoryTab(settingStore.get('Comfy.Queue.QPOV2'))\n  watch(\n    () => settingStore.get('Comfy.Queue.QPOV2'),\n    (enabled) => syncJobHistoryTab(enabled)\n  )\n\n  sidebarTabStore.registerSidebarTab(useAssetsSidebarTab())\n  sidebarTabStore.registerSidebarTab(useNodeLibrarySidebarTab())\n  sidebarTabStore.registerSidebarTab(useModelLibrarySidebarTab())\n  sidebarTabStore.registerSidebarTab(useWorkflowsSidebarTab())\n  sidebarTabStore.registerSidebarTab(useAppsSidebarTab())\n\n  const menuStore = useMenuItemStore()\n\n  menuStore.registerCommands(\n    ['View'],\n    [\n      'Workspace.ToggleBottomPanel',\n      'Comfy.BrowseTemplates',\n      'Workspace.ToggleFocusMode',\n      'Comfy.ToggleCanvasInfo',\n      'Comfy.Canvas.ToggleMinimap',\n      'Comfy.Canvas.ToggleLinkVisibility'\n    ]\n  )\n\n  menuStore.registerCommands(\n    ['View'],\n    ['Comfy.Canvas.ZoomIn', 'Comfy.Canvas.ZoomOut', 'Comfy.Canvas.FitView']\n  )\n}\n","import { useTitle } from '@vueuse/core'\nimport { computed } from 'vue'\n\nimport { t } from '@/i18n'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\n\n// Capture the initial title injected by Vite (e.g. for SEO on cloud.comfy.org)\nconst DEFAULT_TITLE =\n  typeof document !== 'undefined' && document.title ? document.title : 'ComfyUI'\nconst TITLE_SUFFIX = ' - ComfyUI'\n\nexport const useBrowserTabTitle = () => {\n  const executionStore = useExecutionStore()\n  const settingStore = useSettingStore()\n  const workflowStore = useWorkflowStore()\n  const workspaceStore = useWorkspaceStore()\n\n  const executionText = computed(() =>\n    executionStore.isIdle\n      ? ''\n      : `[${Math.round(executionStore.executionProgress * 100)}%]`\n  )\n\n  const newMenuEnabled = computed(\n    () => settingStore.get('Comfy.UseNewMenu') !== 'Disabled'\n  )\n\n  const isAutoSaveEnabled = computed(\n    () => settingStore.get('Comfy.Workflow.AutoSave') === 'after delay'\n  )\n\n  const isActiveWorkflowModified = computed(\n    () => !!workflowStore.activeWorkflow?.isModified\n  )\n  const isActiveWorkflowPersisted = computed(\n    () => !!workflowStore.activeWorkflow?.isPersisted\n  )\n\n  const shouldShowUnsavedIndicator = computed(() => {\n    if (workspaceStore.shiftDown) return false\n    if (isAutoSaveEnabled.value) return false\n    if (!isActiveWorkflowPersisted.value) return true\n    if (isActiveWorkflowModified.value) return true\n    return false\n  })\n\n  const isUnsavedText = computed(() =>\n    shouldShowUnsavedIndicator.value ? ' *' : ''\n  )\n  const workflowNameText = computed(() => {\n    const workflowName = workflowStore.activeWorkflow?.filename\n    return workflowName\n      ? isUnsavedText.value + workflowName + TITLE_SUFFIX\n      : DEFAULT_TITLE\n  })\n\n  const nodeExecutionTitle = computed(() => {\n    // Check if any nodes are in progress\n    const nodeProgressEntries = Object.entries(\n      executionStore.nodeProgressStates\n    )\n    const runningNodes = nodeProgressEntries.filter(\n      ([_, state]) => state.state === 'running'\n    )\n\n    if (runningNodes.length === 0) {\n      return ''\n    }\n\n    // If multiple nodes are running\n    if (runningNodes.length > 1) {\n      return `${executionText.value}[${runningNodes.length} ${t('g.nodesRunning', 'nodes running')}]`\n    }\n\n    // If only one node is running\n    const [, state] = runningNodes[0]\n    const progress = Math.round((state.value / state.max) * 100)\n    const nodeLabel =\n      executionStore.executingNode?.type?.trim() ||\n      executionStore.executingNode?.title?.trim() ||\n      'Node'\n\n    return `${executionText.value}[${progress}%] ${nodeLabel}`\n  })\n\n  const workflowTitle = computed(\n    () =>\n      executionText.value +\n      (newMenuEnabled.value ? workflowNameText.value : DEFAULT_TITLE)\n  )\n\n  const title = computed(() => nodeExecutionTitle.value || workflowTitle.value)\n  useTitle(title)\n}\n","import type { CSSProperties } from 'vue'\n\ninterface GridOptions {\n  /** Minimum width for each grid item (default: 15rem) */\n  minWidth?: string\n  /** Maximum width for each grid item (default: 1fr) */\n  maxWidth?: string\n  /** Padding around the grid (default: 0) */\n  padding?: string\n  /** Gap between grid items (default: 1rem) */\n  gap?: string\n  /** Fixed number of columns (overrides auto-fill with minmax) */\n  columns?: number\n}\n\n/**\n * @deprecated Just use tailwind utilities directly.\n * TODO: Create a common grid layout component if needed.\n * Creates CSS grid styles for responsive grid layouts\n * @param options Grid configuration options\n * @returns CSS properties object for grid styling\n */\nexport function createGridStyle(options: GridOptions = {}): CSSProperties {\n  const {\n    minWidth = '15rem',\n    maxWidth = '1fr',\n    padding = '0',\n    gap = '1rem',\n    columns\n  } = options\n\n  // Runtime validation for columns\n  if (columns !== undefined && columns < 1) {\n    console.warn('createGridStyle: columns must be >= 1, defaulting to 1')\n  }\n\n  const gridTemplateColumns = columns\n    ? `repeat(${Math.max(1, columns)}, 1fr)`\n    : `repeat(auto-fill, minmax(${minWidth}, ${maxWidth}))`\n\n  return {\n    display: 'grid',\n    gridTemplateColumns,\n    padding,\n    gap\n  }\n}\n","<template>\n  <BaseModalLayout :content-title=\"$t('assetBrowser.checkpoints')\">\n    <template #leftPanel>\n      <LeftSidePanel v-model=\"selectedNavItem\" :nav-items=\"tempNavigation\">\n        <template #header-icon>\n          <i class=\"icon-[lucide--puzzle] text-base-foreground\" />\n        </template>\n        <template #header-title>\n          <span class=\"text-base text-base-foreground\">{{\n            $t('g.title')\n          }}</span>\n        </template>\n      </LeftSidePanel>\n    </template>\n\n    <template #header>\n      <SearchInput v-model=\"searchQuery\" size=\"lg\" class=\"max-w-96 flex-1\" />\n    </template>\n\n    <template #header-right-area>\n      <div class=\"flex gap-2\">\n        <Button variant=\"primary\" @click=\"() => {}\">\n          <i class=\"icon-[lucide--upload]\" />\n          <span>{{ $t('g.upload') }}</span>\n        </Button>\n        <Menu :items=\"moreMenuItems\" align=\"end\">\n          <template #trigger>\n            <Button\n              size=\"icon\"\n              variant=\"secondary\"\n              icon=\"icon-[lucide--ellipsis]\"\n              :aria-label=\"$t('g.more')\"\n            />\n          </template>\n        </Menu>\n      </div>\n    </template>\n\n    <template #contentFilter>\n      <div class=\"relative flex gap-2 px-6 pb-4\">\n        <MultiSelect\n          v-model=\"selectedFrameworks\"\n          v-model:search-query=\"searchText\"\n          class=\"w-[250px]\"\n          :label=\"$t('assetBrowser.selectFrameworks')\"\n          :options=\"frameworkOptions\"\n          :show-search-box=\"true\"\n          :show-selected-count=\"true\"\n          :show-clear-button=\"true\"\n        />\n        <MultiSelect\n          v-model=\"selectedProjects\"\n          :label=\"$t('assetBrowser.selectProjects')\"\n          :options=\"projectOptions\"\n        />\n        <SingleSelect\n          v-model=\"selectedSort\"\n          :label=\"$t('assetBrowser.sortingType')\"\n          :options=\"sortOptions\"\n          class=\"w-[135px]\"\n        >\n          <template #icon>\n            <i class=\"icon-[lucide--filter]\" />\n          </template>\n        </SingleSelect>\n      </div>\n    </template>\n\n    <template #content>\n      <!-- Card Examples -->\n      <div :style=\"gridStyle\">\n        <CardContainer v-for=\"i in 100\" :key=\"i\" size=\"regular\">\n          <template #top>\n            <CardTop ratio=\"landscape\">\n              <template #default>\n                <div class=\"size-full bg-blue-500\"></div>\n              </template>\n              <template #top-right>\n                <Button\n                  size=\"icon\"\n                  class=\"bg-white! text-neutral-900!\"\n                  @click=\"() => {}\"\n                >\n                  <i class=\"icon-[lucide--info]\" />\n                </Button>\n              </template>\n              <template #bottom-right>\n                <Tag label=\"png\" shape=\"overlay\" />\n                <Tag label=\"1.2 MB\" shape=\"overlay\" />\n                <Tag label=\"LoRA\" shape=\"overlay\">\n                  <template #icon>\n                    <i class=\"icon-[lucide--folder]\" />\n                  </template>\n                </Tag>\n              </template>\n            </CardTop>\n          </template>\n          <template #bottom>\n            <CardBottom></CardBottom>\n          </template>\n        </CardContainer>\n      </div>\n    </template>\n\n    <template #rightPanel>\n      <div class=\"size-full bg-modal-panel-background pr-6 pb-8 pl-4\"></div>\n    </template>\n  </BaseModalLayout>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, provide, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport CardBottom from '@/components/card/CardBottom.vue'\nimport CardContainer from '@/components/card/CardContainer.vue'\nimport CardTop from '@/components/card/CardTop.vue'\nimport Tag from '@/components/chip/Tag.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport MultiSelect from '@/components/ui/multi-select/MultiSelect.vue'\nimport SingleSelect from '@/components/ui/single-select/SingleSelect.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport BaseModalLayout from '@/components/widget/layout/BaseModalLayout.vue'\nimport LeftSidePanel from '@/components/widget/panel/LeftSidePanel.vue'\nimport type { NavGroupData, NavItemData } from '@/types/navTypes'\nimport { OnCloseKey } from '@/types/widgetTypes'\nimport { createGridStyle } from '@/utils/gridUtil'\n\nconst frameworkOptions = ref([\n  { name: 'Vue', value: 'vue' },\n  { name: 'React', value: 'react' },\n  { name: 'Angular', value: 'angular' },\n  { name: 'Svelte', value: 'svelte' }\n])\n\nconst projectOptions = ref([\n  { name: 'Project A', value: 'proj-a' },\n  { name: 'Project B', value: 'proj-b' },\n  { name: 'Project C', value: 'proj-c' }\n])\n\nconst sortOptions = ref([\n  { name: 'Popular', value: 'popular' },\n  { name: 'Latest', value: 'latest' },\n  { name: 'A → Z', value: 'az' }\n])\n\nconst tempNavigation = ref<(NavItemData | NavGroupData)[]>([\n  { id: 'installed', label: 'Installed', icon: 'icon-[lucide--download]' },\n  {\n    title: 'TAGS',\n    items: [\n      { id: 'tag-sd15', label: 'SD 1.5', icon: 'icon-[lucide--tag]' },\n      { id: 'tag-sdxl', label: 'SDXL', icon: 'icon-[lucide--tag]' },\n      { id: 'tag-utility', label: 'Utility', icon: 'icon-[lucide--tag]' }\n    ]\n  },\n  {\n    title: 'CATEGORIES',\n    items: [\n      { id: 'cat-models', label: 'Models', icon: 'icon-[lucide--layers]' },\n      { id: 'cat-nodes', label: 'Nodes', icon: 'icon-[lucide--grid-3x3]' }\n    ]\n  }\n])\n\nconst { onClose } = defineProps<{\n  onClose: () => void\n}>()\nconst { t } = useI18n()\n\nconst moreMenuItems: MenuItem[] = [\n  {\n    label: () => t('g.settings'),\n    icon: 'icon-[lucide--download]',\n    command: () => {}\n  },\n  {\n    label: () => t('g.profile'),\n    icon: 'icon-[lucide--scroll]',\n    command: () => {}\n  }\n]\n\nprovide(OnCloseKey, onClose)\n\nconst searchQuery = ref<string>('')\nconst searchText = ref<string>('')\nconst selectedFrameworks = ref([])\nconst selectedProjects = ref([])\nconst selectedSort = ref<string>('popular')\n\nconst selectedNavItem = ref<string | null>('installed')\n\nconst gridStyle = computed(() => createGridStyle())\n</script>\n","import SampleModelSelector from '@/components/widget/SampleModelSelector.vue'\nimport { useDialogService } from '@/services/dialogService'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst DIALOG_KEY = 'global-model-selector'\n\nexport const useModelSelectorDialog = () => {\n  const dialogService = useDialogService()\n  const dialogStore = useDialogStore()\n\n  function hide() {\n    dialogStore.closeDialog({ key: DIALOG_KEY })\n  }\n\n  function show() {\n    dialogService.showLayoutDialog({\n      key: DIALOG_KEY,\n      component: SampleModelSelector,\n      props: {\n        onClose: hide\n      }\n    })\n  }\n\n  return {\n    show,\n    hide\n  }\n}\n","import { isCloud } from '@/platform/distribution/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { api } from '@/scripts/api'\nimport { useAuthStore } from '@/stores/authStore'\n\nimport {\n  clearOnboardingReplay,\n  requestOnboardingReplay\n} from './onboardingReplay'\nimport { TOUR_SEEN_SETTING } from './onboardingTours'\n\nexport type OnboardingResetResult =\n  | { status: 'ready' }\n  | { status: 'failed'; cause: unknown }\n\nexport async function resetOnboardingState(): Promise<OnboardingResetResult> {\n  const ownerId = useAuthStore().userId\n  if (isCloud && ownerId === undefined) {\n    return {\n      status: 'failed',\n      cause:\n        'No signed-in account, so the onboarding replay cannot be requested'\n    }\n  }\n  if (!requestOnboardingReplay(ownerId)) {\n    return {\n      status: 'failed',\n      cause:\n        'Session storage is unavailable, so the onboarding replay cannot be requested'\n    }\n  }\n\n  let response: Response\n  try {\n    response = await api.storeSetting(TOUR_SEEN_SETTING, [])\n  } catch (cause) {\n    clearOnboardingReplay(ownerId)\n    return { status: 'failed', cause }\n  }\n\n  if (!response.ok) {\n    clearOnboardingReplay(ownerId)\n    return {\n      status: 'failed',\n      cause:\n        `Failed to clear seen onboarding tours: ${response.status} ${response.statusText}`.trim()\n    }\n  }\n\n  useSettingStore().settingValues[TOUR_SEEN_SETTING] = []\n  return { status: 'ready' }\n}\n","import { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useAuthActions } from '@/composables/auth/useAuthActions'\nimport { useSelectedLiteGraphItems } from '@/composables/canvas/useSelectedLiteGraphItems'\nimport { visibleCanvasViewport } from '@/composables/canvas/visibleCanvasViewport'\nimport { useSubgraphOperations } from '@/composables/graph/useSubgraphOperations'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { useModelSelectorDialog } from '@/composables/useModelSelectorDialog'\nimport { useRunButtonTelemetry } from '@/composables/useRunButtonTelemetry'\nimport {\n  DEFAULT_DARK_COLOR_PALETTE,\n  DEFAULT_LIGHT_COLOR_PALETTE\n} from '@/constants/coreColorPalettes'\n\nimport { tryToggleWidgetPromotion } from '@/core/graph/subgraph/promotionUtils'\nimport { t } from '@/i18n'\nimport {\n  LGraphEventMode,\n  LGraphGroup,\n  LGraphNode,\n  LiteGraph\n} from '@/lib/litegraph/src/litegraph'\nimport type { Point } from '@/lib/litegraph/src/litegraph'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { openModelLibraryBrowser } from '@/platform/assets/composables/openModelLibraryBrowser'\nimport { isSalesManagedTier } from '@/platform/cloud/subscription/constants/tierPricing'\nimport { isCloud } from '@/platform/distribution/types'\nimport { useMissingModelStore } from '@/platform/missingModel/missingModelStore'\nimport { resetOnboardingState } from '@/platform/onboarding/onboardingReset'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { buildSupportUrl } from '@/platform/support/config'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type { ExecutionTriggerSource } from '@/platform/telemetry/types'\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport type { ComfyWorkflow } from '@/platform/workflow/management/stores/workflowStore'\nimport {\n  useCanvasStore,\n  useTitleEditorStore\n} from '@/renderer/core/canvas/canvasStore'\nimport { api } from '@/scripts/api'\nimport { app } from '@/scripts/app'\nimport { useSettingsDialog } from '@/platform/settings/composables/useSettingsDialog'\nimport { useAuthDialogs } from '@/composables/auth/useAuthDialogs'\nimport { useDialogService } from '@/services/dialogService'\nimport { useLitegraphService } from '@/services/litegraphService'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport type { ComfyCommand } from '@/stores/commandStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useModelStore } from '@/stores/modelStore'\nimport { useHelpCenterStore } from '@/stores/helpCenterStore'\nimport { useQueueSettingsStore } from '@/stores/queueSettingsStore'\nimport { useQueueStore, useQueueUIStore } from '@/stores/queueStore'\nimport { useSubgraphNavigationStore } from '@/stores/subgraphNavigationStore'\nimport { useSubgraphStore } from '@/stores/subgraphStore'\nimport { useBottomPanelStore } from '@/stores/workspace/bottomPanelStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { useRightSidePanelStore } from '@/stores/workspace/rightSidePanelStore'\nimport { useSearchBoxStore } from '@/stores/workspace/searchBoxStore'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport { ensureWorkflowSuffix, getWorkflowSuffix } from '@/utils/formatUtil'\nimport {\n  getAllNonIoNodesInSubgraph,\n  getExecutionIdsForSelectedNodes\n} from '@/utils/graphTraversalUtil'\nimport { filterOutputNodes } from '@/utils/nodeFilterUtil'\nimport {\n  ManagerUIState,\n  useManagerState\n} from '@/workbench/extensions/manager/composables/useManagerState'\nimport { ManagerTab } from '@/workbench/extensions/manager/types/comfyManagerTypes'\n\nimport { useWorkflowTemplateSelectorDialog } from './useWorkflowTemplateSelectorDialog'\n\nimport { useMaskEditorStore } from '@/stores/maskEditorStore'\nimport { useDialogStore } from '@/stores/dialogStore'\n\nconst moveSelectedNodesVersionAdded = '1.22.2'\nlet onboardingReplayInProgress: Promise<void> | undefined\n\nexport function useCoreCommands(): ComfyCommand[] {\n  const {\n    canAccessSubscriptionFeatures,\n    showSubscriptionDialog,\n    subscription\n  } = useBillingContext()\n\n  function blockRunWithoutSubscription(): boolean {\n    if (!isCloud || canAccessSubscriptionFeatures.value) return false\n    if (isSalesManagedTier(subscription.value?.tier)) {\n      toast.warning(t('subscription.salesManagedRunBlockedTitle'), {\n        description: t('subscription.salesManagedRunBlockedDetail'),\n        duration: 5000\n      })\n    } else {\n      showSubscriptionDialog({ reason: 'subscribe_to_run' })\n    }\n    return true\n  }\n  const workflowService = useWorkflowService()\n  const workflowStore = useWorkflowStore()\n  const settingsDialog = useSettingsDialog()\n  const dialogService = useDialogService()\n  const { showSignInDialog } = useAuthDialogs()\n  const colorPaletteStore = useColorPaletteStore()\n  const authActions = useAuthActions()\n  const toast = useToast()\n  const canvasStore = useCanvasStore()\n  const executionStore = useExecutionStore()\n  const modelStore = useModelStore()\n  const missingModelStore = useMissingModelStore()\n  const telemetry = useTelemetry()\n  const { trackRunButton } = useRunButtonTelemetry()\n  const { staticUrls, buildDocsUrl } = useExternalLink()\n  const settingStore = useSettingStore()\n\n  const bottomPanelStore = useBottomPanelStore()\n\n  const dialogStore = useDialogStore()\n  const maskEditorStore = useMaskEditorStore()\n\n  const { getSelectedNodes, toggleSelectedNodesMode } =\n    useSelectedLiteGraphItems()\n  const getTracker = () => workflowStore.activeWorkflow?.changeTracker\n\n  function isQueuePanelV2Enabled() {\n    return settingStore.get('Comfy.Queue.QPOV2')\n  }\n\n  async function toggleQueuePanelV2() {\n    await settingStore.set('Comfy.Queue.QPOV2', !isQueuePanelV2Enabled())\n  }\n\n  const moveSelectedNodes = (\n    positionUpdater: (pos: Point, gridSize: number) => Point\n  ) => {\n    const selectedNodes = getSelectedNodes()\n    if (selectedNodes.length === 0) return\n\n    const gridSize = useSettingStore().get('Comfy.SnapToGrid.GridSize')\n    selectedNodes.forEach((node) => {\n      node.pos = positionUpdater(node.pos, gridSize)\n    })\n    app.canvas.setDirty(true, true)\n  }\n\n  const commands = [\n    {\n      id: 'Comfy.NewBlankWorkflow',\n      icon: 'pi pi-plus',\n      label: 'New Blank Workflow',\n      menubarLabel: 'New',\n      category: 'essentials' as const,\n      function: async () => {\n        const previousWorkflowHadNodes = app.rootGraph._nodes.length > 0\n        await workflowService.loadBlankWorkflow()\n        telemetry?.trackWorkflowCreated({\n          workflow_type: 'blank',\n          previous_workflow_had_nodes: previousWorkflowHadNodes\n        })\n      }\n    },\n    {\n      id: 'Comfy.OpenWorkflow',\n      icon: 'pi pi-folder-open',\n      label: 'Open Workflow',\n      menubarLabel: 'Open',\n      category: 'essentials' as const,\n      function: () => {\n        app.ui.loadFile()\n      }\n    },\n    {\n      id: 'Comfy.LoadDefaultWorkflow',\n      icon: 'pi pi-code',\n      label: 'Load Default Workflow',\n      function: async () => {\n        const previousWorkflowHadNodes = app.rootGraph._nodes.length > 0\n        await workflowService.loadDefaultWorkflow()\n        telemetry?.trackWorkflowCreated({\n          workflow_type: 'default',\n          previous_workflow_had_nodes: previousWorkflowHadNodes\n        })\n      }\n    },\n    {\n      id: 'Comfy.SaveWorkflow',\n      icon: 'pi pi-save',\n      label: 'Save Workflow',\n      menubarLabel: 'Save',\n      category: 'essentials' as const,\n      function: async () => {\n        const workflow = useWorkflowStore().activeWorkflow as ComfyWorkflow\n        await workflowService.saveWorkflow(workflow)\n      }\n    },\n    {\n      id: 'Comfy.PublishSubgraph',\n      icon: 'pi pi-save',\n      label: 'Publish Subgraph',\n      menubarLabel: 'Publish',\n      function: async (metadata?: Record<string, unknown>) => {\n        const name = metadata?.name as string | undefined\n        await useSubgraphStore().publishSubgraph(name)\n      }\n    },\n    {\n      id: 'Comfy.SaveWorkflowAs',\n      icon: 'pi pi-save',\n      label: 'Save Workflow As',\n      menubarLabel: 'Save As',\n      category: 'essentials' as const,\n      function: async () => {\n        const workflow = useWorkflowStore().activeWorkflow as ComfyWorkflow\n        await workflowService.saveWorkflowAs(workflow)\n      }\n    },\n    {\n      id: 'Comfy.RenameWorkflow',\n      icon: 'pi pi-pencil',\n      label: 'Rename Workflow',\n      menubarLabel: 'Rename',\n      function: async () => {\n        const workflow = workflowStore.activeWorkflow\n        if (!workflow || !workflow.isPersisted) return\n\n        const newName = await dialogService.prompt({\n          title: t('g.rename'),\n          message: t('workflowService.enterFilenamePrompt'),\n          defaultValue: workflow.filename\n        })\n        if (!newName || newName === workflow.filename) return\n\n        const suffix = getWorkflowSuffix(workflow.suffix)\n        const newPath =\n          workflow.directory + '/' + ensureWorkflowSuffix(newName, suffix)\n        await workflowService.renameWorkflow(workflow, newPath)\n      }\n    },\n    {\n      id: 'Comfy.ExportWorkflow',\n      icon: 'pi pi-download',\n      label: 'Export Workflow',\n      menubarLabel: 'Export',\n      category: 'essentials' as const,\n      function: async () => {\n        await workflowService.exportWorkflow('workflow', 'workflow')\n      }\n    },\n    {\n      id: 'Comfy.ExportWorkflowAPI',\n      icon: 'pi pi-download',\n      label: 'Export Workflow (API Format)',\n      menubarLabel: 'Export (API)',\n      function: async () => {\n        await workflowService.exportWorkflow('workflow_api', 'output')\n      }\n    },\n    {\n      id: 'Comfy.Undo',\n      icon: 'pi pi-undo',\n      label: 'Undo',\n      category: 'essentials' as const,\n      mutatesGraph: () => !dialogStore.isDialogOpen('global-mask-editor'),\n      function: async () => {\n        // If Mask Editor is open, use its history instead of the graph\n        if (dialogStore.isDialogOpen('global-mask-editor')) {\n          maskEditorStore.canvasHistory.undo()\n          return\n        }\n        await getTracker()?.undo()\n      }\n    },\n    {\n      id: 'Comfy.Redo',\n      icon: 'pi pi-refresh',\n      label: 'Redo',\n      category: 'essentials' as const,\n      mutatesGraph: () => !dialogStore.isDialogOpen('global-mask-editor'),\n      function: async () => {\n        if (dialogStore.isDialogOpen('global-mask-editor')) {\n          maskEditorStore.canvasHistory.redo()\n          return\n        }\n        await getTracker()?.redo()\n      }\n    },\n    {\n      id: 'Comfy.ClearWorkflow',\n      icon: 'pi pi-trash',\n      label: 'Clear Workflow',\n      category: 'essentials' as const,\n      mutatesGraph: true,\n      function: () => {\n        const settingStore = useSettingStore()\n        if (\n          !settingStore.get('Comfy.ConfirmClear') ||\n          confirm('Clear workflow?')\n        ) {\n          if (app.canvas.subgraph) {\n            // `clear` is not implemented on subgraphs and the parent class's\n            // (`LGraph`) `clear` breaks the subgraph structure. For subgraphs,\n            // just clear the nodes but preserve input/output nodes and structure\n            const subgraph = app.canvas.subgraph\n            const nonIoNodes = getAllNonIoNodesInSubgraph(subgraph)\n            nonIoNodes.forEach((node) => subgraph.remove(node))\n          } else {\n            app.clean()\n          }\n          api.dispatchCustomEvent('graphCleared')\n        }\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ResetView',\n      icon: 'pi pi-expand',\n      label: 'Reset View',\n      function: () => {\n        useLitegraphService().resetView()\n      }\n    },\n    {\n      id: 'Comfy.OpenClipspace',\n      icon: 'pi pi-clipboard',\n      label: 'Clipspace',\n      function: () => {\n        app.openClipspace()\n      }\n    },\n    {\n      id: 'Comfy.RefreshNodeDefinitions',\n      icon: 'pi pi-refresh',\n      label: 'Refresh Node Definitions',\n      category: 'essentials' as const,\n      function: async () => {\n        await Promise.all([app.refreshComboInNodes(), modelStore.refresh()])\n        await useAssetsStore().invalidateAll()\n        if (!isCloud) {\n          await missingModelStore.refreshMissingModels({ reloadDefs: false })\n        }\n      }\n    },\n    {\n      id: 'Comfy.Interrupt',\n      icon: 'pi pi-stop',\n      label: 'Interrupt',\n      category: 'essentials' as const,\n      function: async () => {\n        await api.interrupt(executionStore.activeJobId)\n        toast.info(t('g.interrupted'), {\n          description: t('toastMessages.interrupted'),\n          duration: 1000\n        })\n      }\n    },\n    {\n      id: 'Comfy.ClearPendingTasks',\n      icon: 'pi pi-stop',\n      label: 'Clear Pending Tasks',\n      category: 'essentials' as const,\n      function: async () => {\n        await useQueueStore().clear(['queue'])\n        toast.info(t('g.confirmed'), {\n          description: t('toastMessages.pendingTasksDeleted'),\n          duration: 3000\n        })\n      }\n    },\n    {\n      id: 'Comfy.BrowseTemplates',\n      icon: 'pi pi-folder-open',\n      label: 'Browse Templates',\n      function: () => {\n        useWorkflowTemplateSelectorDialog().show()\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ZoomIn',\n      icon: 'pi pi-plus',\n      label: 'Zoom In',\n      category: 'view-controls' as const,\n      function: () => {\n        const ds = app.canvas.ds\n        ds.changeScale(ds.scale * 1.1, [\n          ds.element.width / 2,\n          ds.element.height / 2\n        ])\n        app.canvas.setDirty(true, true)\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ZoomOut',\n      icon: 'pi pi-minus',\n      label: 'Zoom Out',\n      category: 'view-controls' as const,\n      function: () => {\n        const ds = app.canvas.ds\n        ds.changeScale(ds.scale / 1.1, [\n          ds.element.width / 2,\n          ds.element.height / 2\n        ])\n        app.canvas.setDirty(true, true)\n      }\n    },\n    {\n      id: 'Experimental.ToggleVueNodes',\n      label: () =>\n        `Experimental: ${\n          useSettingStore().get('Comfy.VueNodes.Enabled') ? 'Disable' : 'Enable'\n        } Nodes 2.0`,\n      function: async () => {\n        const settingStore = useSettingStore()\n        const current = settingStore.get('Comfy.VueNodes.Enabled')\n        await settingStore.set('Comfy.VueNodes.Enabled', !current)\n      }\n    },\n    {\n      id: 'Comfy.Canvas.FitView',\n      icon: 'pi pi-expand',\n      label: 'Fit view to selected nodes',\n      menubarLabel: 'Zoom to fit',\n      category: 'view-controls' as const,\n      function: () => {\n        if (app.canvas.empty) {\n          toast.error(t('toastMessages.emptyCanvas'))\n          return\n        }\n        app.canvas.fitViewToSelectionAnimated({\n          viewport: visibleCanvasViewport(app.canvas)\n        })\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ToggleLock',\n      icon: 'pi pi-lock',\n      label: 'Canvas Toggle Lock',\n      category: 'view-controls' as const,\n      function: () => {\n        app.canvas.read_only = !app.canvas.read_only\n      }\n    },\n    {\n      id: 'Comfy.Canvas.Lock',\n      icon: 'pi pi-lock',\n      label: 'Lock Canvas',\n      category: 'view-controls' as const,\n      function: () => {\n        app.canvas.read_only = true\n      }\n    },\n    {\n      id: 'Comfy.Canvas.Unlock',\n      icon: 'pi pi-lock-open',\n      label: 'Unlock Canvas',\n      function: () => {\n        app.canvas.read_only = false\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ToggleLinkVisibility',\n      icon: 'pi pi-eye',\n      label: 'Canvas Toggle Link Visibility',\n      menubarLabel: 'Node Links',\n      versionAdded: '1.3.6',\n\n      function: (() => {\n        const settingStore = useSettingStore()\n        let lastLinksRenderMode = LiteGraph.SPLINE_LINK\n\n        return async () => {\n          const currentMode = settingStore.get('Comfy.LinkRenderMode')\n\n          if (currentMode === LiteGraph.HIDDEN_LINK) {\n            // If links are hidden, restore the last positive value or default to spline mode\n            await settingStore.set('Comfy.LinkRenderMode', lastLinksRenderMode)\n          } else {\n            // If links are visible, store the current mode and hide links\n            lastLinksRenderMode = currentMode\n            await settingStore.set(\n              'Comfy.LinkRenderMode',\n              LiteGraph.HIDDEN_LINK\n            )\n          }\n        }\n      })(),\n      active: () =>\n        useSettingStore().get('Comfy.LinkRenderMode') !== LiteGraph.HIDDEN_LINK\n    },\n    {\n      id: 'Comfy.Canvas.ToggleMinimap',\n      icon: 'pi pi-map',\n      label: 'Canvas Toggle Minimap',\n      menubarLabel: 'Minimap',\n      versionAdded: '1.24.1',\n      function: async () => {\n        const settingStore = useSettingStore()\n        await settingStore.set(\n          'Comfy.Minimap.Visible',\n          !settingStore.get('Comfy.Minimap.Visible')\n        )\n      },\n      active: () => useSettingStore().get('Comfy.Minimap.Visible')\n    },\n    {\n      id: 'Comfy.Queue.ToggleOverlay',\n      icon: 'pi pi-history',\n      label: () => t('queue.toggleJobHistory'),\n      menubarLabel: () => t('queue.jobHistory'),\n      versionAdded: '1.37.0',\n      category: 'view-controls' as const,\n      function: () => {\n        useQueueUIStore().toggleOverlay()\n      },\n      active: () => useQueueUIStore().isOverlayExpanded\n    },\n    {\n      id: 'Comfy.QueuePrompt',\n      icon: 'pi pi-play',\n      label: 'Queue Prompt',\n      versionAdded: '1.3.7',\n      category: 'essentials' as const,\n      function: async (metadata?: {\n        subscribe_to_run?: boolean\n        trigger_source?: ExecutionTriggerSource\n      }) => {\n        trackRunButton(metadata)\n        if (blockRunWithoutSubscription()) return\n\n        const batchCount = useQueueSettingsStore().batchCount\n\n        useTelemetry()?.trackWorkflowExecution()\n\n        await app.queuePrompt(0, batchCount, { intent: metadata })\n      }\n    },\n    {\n      id: 'Comfy.QueuePromptFront',\n      icon: 'pi pi-play',\n      label: 'Queue Prompt (Front)',\n      versionAdded: '1.3.7',\n      category: 'essentials' as const,\n      function: async (metadata?: {\n        subscribe_to_run?: boolean\n        trigger_source?: ExecutionTriggerSource\n      }) => {\n        trackRunButton(metadata)\n        if (blockRunWithoutSubscription()) return\n\n        const batchCount = useQueueSettingsStore().batchCount\n\n        useTelemetry()?.trackWorkflowExecution()\n\n        await app.queuePrompt(-1, batchCount, { intent: metadata })\n      }\n    },\n    {\n      id: 'Comfy.QueueSelectedOutputNodes',\n      icon: 'pi pi-play',\n      label: 'Queue Selected Output Nodes',\n      versionAdded: '1.19.6',\n      function: async (metadata?: {\n        subscribe_to_run?: boolean\n        trigger_source?: ExecutionTriggerSource\n      }) => {\n        trackRunButton(metadata)\n        if (blockRunWithoutSubscription()) return\n\n        const batchCount = useQueueSettingsStore().batchCount\n        const selectedNodes = getSelectedNodes()\n        const selectedOutputNodes = filterOutputNodes(selectedNodes)\n\n        if (selectedOutputNodes.length === 0) {\n          toast.error(t('toastMessages.nothingToQueue'), {\n            description: t('toastMessages.pleaseSelectOutputNodes')\n          })\n          return\n        }\n\n        // Get execution IDs for all selected output nodes and their descendants\n        const executionIds =\n          getExecutionIdsForSelectedNodes(selectedOutputNodes)\n\n        if (executionIds.length === 0) {\n          toast.error(t('toastMessages.failedToQueue'), {\n            description: t('toastMessages.failedExecutionPathResolution')\n          })\n          return\n        }\n        useTelemetry()?.trackWorkflowExecution()\n        await app.queuePrompt(0, batchCount, {\n          queueNodeIds: executionIds,\n          intent: metadata\n        })\n      }\n    },\n    {\n      id: 'Comfy.ShowSettingsDialog',\n      icon: 'pi pi-cog',\n      label: 'Show Settings Dialog',\n      versionAdded: '1.3.7',\n      category: 'view-controls' as const,\n      function: () => {\n        settingsDialog.show()\n      }\n    },\n    {\n      id: 'Comfy.Graph.GroupSelectedNodes',\n      icon: 'pi pi-sitemap',\n      label: 'Group Selected Nodes',\n      versionAdded: '1.3.7',\n      category: 'essentials' as const,\n      mutatesGraph: true,\n      function: () => {\n        const { canvas } = app\n        if (!canvas.selectedItems.size) {\n          toast.error(t('toastMessages.nothingToGroup'), {\n            description: t('toastMessages.pleaseSelectNodesToGroup')\n          })\n          return\n        }\n        const group = new LGraphGroup()\n        const padding = useSettingStore().get(\n          'Comfy.GroupSelectedNodes.Padding'\n        )\n        group.resizeTo(canvas.selectedItems, padding)\n        canvas.graph?.add(group)\n\n        group.recomputeInsideNodes()\n\n        useTitleEditorStore().titleEditorTarget = group\n      }\n    },\n    {\n      id: 'Workspace.NextOpenedWorkflow',\n      icon: 'pi pi-step-forward',\n      label: 'Next Opened Workflow',\n      versionAdded: '1.3.9',\n      function: async () => {\n        await workflowService.loadNextOpenedWorkflow()\n      }\n    },\n    {\n      id: 'Workspace.PreviousOpenedWorkflow',\n      icon: 'pi pi-step-backward',\n      label: 'Previous Opened Workflow',\n      versionAdded: '1.3.9',\n      function: async () => {\n        await workflowService.loadPreviousOpenedWorkflow()\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ToggleSelectedNodes.Mute',\n      icon: 'pi pi-volume-off',\n      label: 'Mute/Unmute Selected Nodes',\n      versionAdded: '1.3.11',\n      category: 'essentials' as const,\n      mutatesGraph: true,\n      function: () => {\n        toggleSelectedNodesMode(LGraphEventMode.NEVER)\n        app.canvas.setDirty(true, true)\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ToggleSelectedNodes.Bypass',\n      icon: 'pi pi-shield',\n      label: 'Bypass/Unbypass Selected Nodes',\n      versionAdded: '1.3.11',\n      category: 'essentials' as const,\n      mutatesGraph: true,\n      function: () => {\n        toggleSelectedNodesMode(LGraphEventMode.BYPASS)\n        app.canvas.setDirty(true, true)\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ToggleSelectedNodes.Pin',\n      icon: 'pi pi-pin',\n      label: 'Pin/Unpin Selected Nodes',\n      versionAdded: '1.3.11',\n      category: 'essentials' as const,\n      mutatesGraph: true,\n      function: () => {\n        getSelectedNodes().forEach((node) => {\n          node.pin(!node.pinned)\n        })\n        app.canvas.setDirty(true, true)\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ToggleSelected.Pin',\n      icon: 'pi pi-pin',\n      label: 'Pin/Unpin Selected Items',\n      versionAdded: '1.3.33',\n      mutatesGraph: true,\n      function: () => {\n        for (const item of app.canvas.selectedItems) {\n          if (item instanceof LGraphNode || item instanceof LGraphGroup) {\n            item.pin(!item.pinned)\n          }\n        }\n        app.canvas.setDirty(true, true)\n      }\n    },\n    {\n      id: 'Comfy.Canvas.Resize',\n      icon: 'pi pi-minus',\n      label: 'Resize Selected Nodes',\n      versionAdded: '',\n      mutatesGraph: true,\n      function: () => {\n        getSelectedNodes().forEach((node) => {\n          const optimalSize = node.computeSize()\n          node.setSize([optimalSize[0], optimalSize[1]])\n        })\n        app.canvas.setDirty(true, true)\n      }\n    },\n    {\n      id: 'Comfy.Canvas.ToggleSelectedNodes.Collapse',\n      icon: 'pi pi-minus',\n      label: 'Collapse/Expand Selected Nodes',\n      versionAdded: '1.3.11',\n      mutatesGraph: true,\n      function: () => {\n        getSelectedNodes().forEach((node) => {\n          node.collapse()\n        })\n        app.canvas.setDirty(true, true)\n      }\n    },\n    {\n      id: 'Comfy.ToggleTheme',\n      icon: 'pi pi-moon',\n      label: 'Toggle Theme (Dark/Light)',\n      versionAdded: '1.3.12',\n      function: (() => {\n        let previousDarkTheme: string = DEFAULT_DARK_COLOR_PALETTE.id\n        let previousLightTheme: string = DEFAULT_LIGHT_COLOR_PALETTE.id\n\n        return async () => {\n          const settingStore = useSettingStore()\n          const theme = colorPaletteStore.completedActivePalette\n          if (theme.light_theme) {\n            previousLightTheme = theme.id\n            await settingStore.set('Comfy.ColorPalette', previousDarkTheme)\n          } else {\n            previousDarkTheme = theme.id\n            await settingStore.set('Comfy.ColorPalette', previousLightTheme)\n          }\n        }\n      })()\n    },\n    {\n      id: 'Workspace.ToggleBottomPanel',\n      icon: 'pi pi-list',\n      label: 'Toggle Bottom Panel',\n      menubarLabel: 'Bottom Panel',\n      versionAdded: '1.3.22',\n      category: 'view-controls' as const,\n      function: () => {\n        bottomPanelStore.toggleBottomPanel()\n      },\n      active: () => bottomPanelStore.bottomPanelVisible\n    },\n    {\n      id: 'Workspace.ToggleFocusMode',\n      icon: 'pi pi-eye',\n      label: 'Toggle Focus Mode',\n      menubarLabel: 'Focus Mode',\n      versionAdded: '1.3.27',\n      category: 'view-controls' as const,\n      function: () => {\n        useWorkspaceStore().toggleFocusMode()\n      },\n      active: () => useWorkspaceStore().focusMode\n    },\n    {\n      id: 'Comfy.Graph.FitGroupToContents',\n      icon: 'pi pi-expand',\n      label: 'Fit Group To Contents',\n      versionAdded: '1.4.9',\n      mutatesGraph: true,\n      function: () => {\n        for (const group of app.canvas.selectedItems) {\n          if (group instanceof LGraphGroup) {\n            group.recomputeInsideNodes()\n            const padding = useSettingStore().get(\n              'Comfy.GroupSelectedNodes.Padding'\n            )\n            group.resizeTo(group.children, padding)\n            app.canvas.setDirty(false, true)\n          }\n        }\n      }\n    },\n    {\n      id: 'Comfy.Help.OpenComfyUIIssues',\n      icon: 'pi pi-github',\n      label: 'Open ComfyUI Issues',\n      menubarLabel: 'ComfyUI Issues',\n      versionAdded: '1.5.5',\n      function: () => {\n        telemetry?.trackHelpResourceClicked({\n          resource_type: 'github',\n          is_external: true,\n          source: 'menu'\n        })\n        window.open(staticUrls.githubIssues, '_blank')\n      }\n    },\n    {\n      id: 'Comfy.Help.OpenComfyUIDocs',\n      icon: 'pi pi-info-circle',\n      label: 'Open ComfyUI Docs',\n      menubarLabel: 'ComfyUI Docs',\n      versionAdded: '1.5.5',\n      function: () => {\n        telemetry?.trackHelpResourceClicked({\n          resource_type: 'docs',\n          is_external: true,\n          source: 'menu'\n        })\n        window.open(buildDocsUrl('/', { includeLocale: true }), '_blank')\n      }\n    },\n    {\n      id: 'Comfy.Help.OpenComfyOrgDiscord',\n      icon: 'pi pi-discord',\n      label: 'Open Comfy-Org Discord',\n      menubarLabel: 'Comfy-Org Discord',\n      versionAdded: '1.5.5',\n      function: () => {\n        telemetry?.trackHelpResourceClicked({\n          resource_type: 'discord',\n          is_external: true,\n          source: 'menu'\n        })\n        window.open(staticUrls.discord, '_blank')\n      }\n    },\n    {\n      id: 'Workspace.SearchBox.Toggle',\n      icon: 'pi pi-search',\n      label: 'Toggle Search Box',\n      versionAdded: '1.5.7',\n      function: () => {\n        useSearchBoxStore().toggleVisible()\n      }\n    },\n    {\n      id: 'Comfy.Help.AboutComfyUI',\n      icon: 'pi pi-info-circle',\n      label: 'Open About ComfyUI',\n      menubarLabel: 'About ComfyUI',\n      versionAdded: '1.6.4',\n      function: () => {\n        settingsDialog.showAbout()\n      }\n    },\n    {\n      id: 'Comfy.DuplicateWorkflow',\n      icon: 'pi pi-clone',\n      label: 'Duplicate Current Workflow',\n      versionAdded: '1.6.15',\n      function: async () => {\n        await workflowService.duplicateWorkflow(workflowStore.activeWorkflow!)\n      }\n    },\n    {\n      id: 'Workspace.CloseWorkflow',\n      icon: 'pi pi-times',\n      label: 'Close Current Workflow',\n      versionAdded: '1.7.3',\n      function: async () => {\n        if (workflowStore.activeWorkflow)\n          await workflowService.closeWorkflow(workflowStore.activeWorkflow)\n      }\n    },\n    {\n      id: 'Comfy.ContactSupport',\n      icon: 'pi pi-question',\n      label: 'Contact Support',\n      versionAdded: '1.17.8',\n      function: () => {\n        const { userEmail, resolvedUserInfo } = useCurrentUser()\n        const supportUrl = buildSupportUrl({\n          userEmail: userEmail.value,\n          userId: resolvedUserInfo.value?.id\n        })\n        window.open(supportUrl, '_blank', 'noopener,noreferrer')\n      }\n    },\n    {\n      id: 'Comfy.Onboarding.Replay',\n      icon: 'pi pi-refresh',\n      label: 'Replay Onboarding',\n      versionAdded: '1.55.10',\n      function: async () => {\n        if (!settingStore.get('Comfy.DevMode')) return\n        const replay = (onboardingReplayInProgress ??= (async () => {\n          const confirmed = await dialogService.confirm({\n            title: t('onboardingReplay.confirmTitle'),\n            message: t('onboardingReplay.confirmMessage'),\n            type: 'default'\n          })\n          if (!confirmed) return\n\n          const result = await resetOnboardingState()\n          if (result.status === 'failed') {\n            toast.error(t('onboardingReplay.failedSummary'), {\n              description: t('onboardingReplay.failedDetail'),\n              duration: 5000\n            })\n            reportError(result.cause, {\n              surface: 'platform',\n              errorType: 'error_resetting_onboarding_state'\n            })\n            return\n          }\n\n          if (isCloud) {\n            globalThis.location.assign(import.meta.env.BASE_URL || '/')\n          } else {\n            globalThis.location.reload()\n          }\n        })())\n        try {\n          await replay\n        } finally {\n          if (onboardingReplayInProgress === replay) {\n            onboardingReplayInProgress = undefined\n          }\n        }\n      }\n    },\n    {\n      id: 'Comfy.Help.OpenComfyUIForum',\n      icon: 'pi pi-comments',\n      label: 'Open ComfyUI Forum',\n      menubarLabel: 'ComfyUI Forum',\n      versionAdded: '1.8.2',\n      function: () => {\n        telemetry?.trackHelpResourceClicked({\n          resource_type: 'help_feedback',\n          is_external: true,\n          source: 'menu'\n        })\n        window.open(staticUrls.forum, '_blank')\n      }\n    },\n    {\n      id: 'Comfy.Canvas.CopySelected',\n      icon: 'icon-[lucide--copy]',\n      label: 'Copy',\n      function: () => {\n        if (app.canvas.selectedItems.size) {\n          app.canvas.copyToClipboard()\n        }\n      }\n    },\n    {\n      id: 'Comfy.Canvas.PasteFromClipboard',\n      icon: 'icon-[lucide--clipboard-paste]',\n      label: 'Paste',\n      mutatesGraph: true,\n      function: () => {\n        app.canvas.pasteFromClipboard()\n      }\n    },\n    {\n      id: 'Comfy.Canvas.PasteFromClipboardWithConnect',\n      icon: 'icon-[lucide--clipboard-paste]',\n      label: () => t('menuLabels.Paste with Connect'),\n      mutatesGraph: true,\n      function: () => {\n        app.canvas.pasteFromClipboard({ connectInputs: true })\n      }\n    },\n    {\n      id: 'Comfy.Canvas.SelectAll',\n      icon: 'icon-[lucide--lasso-select]',\n      label: 'Select All',\n      function: () => {\n        app.canvas.selectItems()\n      }\n    },\n    {\n      id: 'Comfy.Canvas.DeleteSelectedItems',\n      icon: 'pi pi-trash',\n      label: 'Delete Selected Items',\n      versionAdded: '1.10.5',\n      mutatesGraph: true,\n      function: () => {\n        if (app.canvas.selectedItems.size === 0) {\n          app.canvas.canvas.dispatchEvent(\n            new CustomEvent('litegraph:no-items-selected', { bubbles: true })\n          )\n          return\n        }\n        app.canvas.deleteSelected()\n        app.canvas.setDirty(true, true)\n      }\n    },\n    {\n      id: 'Comfy.Manager.CustomNodesManager.ShowCustomNodesMenu',\n      icon: 'pi pi-puzzle',\n      label: 'Custom Nodes Manager',\n      versionAdded: '1.12.10',\n      function: async () => {\n        await useManagerState().openManager({\n          showToastOnLegacyError: true\n        })\n      }\n    },\n    {\n      id: 'Comfy.Manager.ShowUpdateAvailablePacks',\n      icon: 'pi pi-sync',\n      label: 'Check for Custom Node Updates',\n      versionAdded: '1.17.0',\n      function: async () => {\n        const managerState = useManagerState()\n        const state = managerState.managerUIState.value\n\n        // For DISABLED state, show error toast instead of opening settings\n        if (state === ManagerUIState.DISABLED) {\n          toast.error(t('g.error'), {\n            description: t('manager.notAvailable')\n          })\n          return\n        }\n\n        await managerState.openManager({\n          initialTab: ManagerTab.UpdateAvailable,\n          showToastOnLegacyError: false\n        })\n      }\n    },\n    {\n      id: 'Comfy.Manager.ShowMissingPacks',\n      icon: 'pi pi-exclamation-circle',\n      label: 'Install Missing Custom Nodes',\n      versionAdded: '1.17.0',\n      function: async () => {\n        await useManagerState().openManager({\n          initialTab: ManagerTab.Missing,\n          showToastOnLegacyError: false\n        })\n      }\n    },\n    {\n      id: 'Comfy.User.OpenSignInDialog',\n      icon: 'pi pi-user',\n      label: 'Open Sign In Dialog',\n      versionAdded: '1.17.6',\n      function: async () => {\n        await showSignInDialog()\n      }\n    },\n    {\n      id: 'Comfy.User.SignOut',\n      icon: 'pi pi-sign-out',\n      label: 'Sign Out',\n      versionAdded: '1.18.1',\n      function: async () => {\n        await authActions.logout()\n      }\n    },\n    {\n      id: 'Comfy.Canvas.MoveSelectedNodes.Up',\n      icon: 'pi pi-arrow-up',\n      label: 'Move Selected Nodes Up',\n      versionAdded: moveSelectedNodesVersionAdded,\n      mutatesGraph: true,\n      function: () => moveSelectedNodes(([x, y], gridSize) => [x, y - gridSize])\n    },\n    {\n      id: 'Comfy.Canvas.MoveSelectedNodes.Down',\n      icon: 'pi pi-arrow-down',\n      label: 'Move Selected Nodes Down',\n      versionAdded: moveSelectedNodesVersionAdded,\n      mutatesGraph: true,\n      function: () => moveSelectedNodes(([x, y], gridSize) => [x, y + gridSize])\n    },\n    {\n      id: 'Comfy.Canvas.MoveSelectedNodes.Left',\n      icon: 'pi pi-arrow-left',\n      label: 'Move Selected Nodes Left',\n      versionAdded: moveSelectedNodesVersionAdded,\n      mutatesGraph: true,\n      function: () => moveSelectedNodes(([x, y], gridSize) => [x - gridSize, y])\n    },\n    {\n      id: 'Comfy.Canvas.MoveSelectedNodes.Right',\n      icon: 'pi pi-arrow-right',\n      label: 'Move Selected Nodes Right',\n      versionAdded: moveSelectedNodesVersionAdded,\n      mutatesGraph: true,\n      function: () => moveSelectedNodes(([x, y], gridSize) => [x + gridSize, y])\n    },\n    {\n      id: 'Comfy.Graph.ConvertToSubgraph',\n      icon: 'icon-[lucide--shrink]',\n      label: 'Convert Selection to Subgraph',\n      versionAdded: '1.20.1',\n      category: 'essentials' as const,\n      mutatesGraph: true,\n      function: () => {\n        const canvas = canvasStore.getCanvas()\n        const graph = canvas.subgraph ?? canvas.graph\n        if (!graph) throw new TypeError('Canvas has no graph or subgraph set.')\n\n        const res = graph.convertToSubgraph(canvas.selectedItems)\n        const { node } = res\n        canvas.select(node)\n      }\n    },\n    {\n      id: 'Comfy.Graph.UnpackSubgraph',\n      icon: 'icon-[lucide--expand]',\n      label: 'Unpack the selected Subgraph',\n      versionAdded: '1.26.3',\n      mutatesGraph: true,\n      function: () => {\n        const { unpackSubgraph } = useSubgraphOperations()\n        unpackSubgraph()\n      }\n    },\n    {\n      id: 'Comfy.Graph.EditSubgraphWidgets',\n      label: 'Edit Subgraph Widgets',\n      icon: 'icon-[lucide--settings-2]',\n      versionAdded: '1.28.5',\n      function: () => {\n        useRightSidePanelStore().openPanel('subgraph')\n      }\n    },\n    {\n      id: 'Comfy.Graph.ToggleWidgetPromotion',\n      icon: 'icon-[lucide--arrow-left-right]',\n      label: 'Toggle promotion of hovered widget',\n      versionAdded: '1.30.1',\n      mutatesGraph: true,\n      function: () => {\n        tryToggleWidgetPromotion()\n      }\n    },\n    {\n      id: 'Comfy.OpenManagerDialog',\n      icon: 'mdi mdi-puzzle-outline',\n      label: 'Manager',\n      function: async () => {\n        await useManagerState().openManager({\n          initialTab: ManagerTab.All,\n          showToastOnLegacyError: false\n        })\n      }\n    },\n    {\n      id: 'Comfy.ToggleHelpCenter',\n      icon: 'pi pi-question-circle',\n      label: 'Help Center',\n      function: () => {\n        useHelpCenterStore().toggle()\n      },\n      active: () => useHelpCenterStore().isVisible\n    },\n    {\n      id: 'Comfy.ToggleCanvasInfo',\n      icon: 'pi pi-info-circle',\n      label: 'Canvas Performance',\n      function: async () => {\n        const settingStore = useSettingStore()\n        const currentValue = settingStore.get('Comfy.Graph.CanvasInfo')\n        await settingStore.set('Comfy.Graph.CanvasInfo', !currentValue)\n      },\n      active: () => useSettingStore().get('Comfy.Graph.CanvasInfo')\n    },\n    {\n      id: 'Workspace.ToggleBottomPanel.Shortcuts',\n      icon: 'pi pi-key',\n      label: 'Show Keybindings Dialog',\n      versionAdded: '1.24.1',\n      category: 'view-controls' as const,\n      function: () => {\n        bottomPanelStore.togglePanel('shortcuts')\n      }\n    },\n    {\n      id: 'Comfy.Graph.ExitSubgraph',\n      icon: 'pi pi-arrow-up',\n      label: 'Exit Subgraph',\n      versionAdded: '1.20.1',\n      function: () => {\n        const canvas = useCanvasStore().getCanvas()\n        const navigationStore = useSubgraphNavigationStore()\n        if (!canvas.graph) return\n\n        canvas.setGraph(\n          navigationStore.navigationStack.at(-2) ?? canvas.graph.rootGraph\n        )\n      }\n    },\n    {\n      id: 'Comfy.Subgraph.SetDescription',\n      icon: 'pi pi-pencil',\n      label: 'Set Subgraph Description',\n      versionAdded: '1.39.7',\n      mutatesGraph: true,\n      function: async (metadata?: Record<string, unknown>) => {\n        const canvas = canvasStore.getCanvas()\n        const subgraph = canvas.subgraph\n        if (!subgraph) return\n\n        const extra = subgraph.extra as Record<string, unknown>\n        const currentDescription = extra.BlueprintDescription as string\n\n        let description: string | null | undefined\n        const rawDescription = metadata?.description\n        if (rawDescription != null) {\n          description =\n            typeof rawDescription === 'string'\n              ? rawDescription\n              : String(rawDescription)\n        }\n        description ??= await dialogService.prompt({\n          title: t('g.description'),\n          message: t('subgraphStore.enterDescription'),\n          defaultValue: currentDescription\n        })\n        if (description === null) return\n\n        extra.BlueprintDescription = description.trim() || undefined\n        workflowStore.activeWorkflow?.changeTracker.captureCanvasState()\n      }\n    },\n    {\n      id: 'Comfy.Subgraph.SetSearchAliases',\n      icon: 'pi pi-search',\n      label: 'Set Subgraph Search Aliases',\n      versionAdded: '1.39.7',\n      mutatesGraph: true,\n      function: async (metadata?: Record<string, unknown>) => {\n        const canvas = canvasStore.getCanvas()\n        const subgraph = canvas.subgraph\n        if (!subgraph) return\n\n        const parseAliases = (value: unknown): string[] =>\n          (Array.isArray(value) ? value.map(String) : String(value).split(','))\n            .map((s) => s.trim())\n            .filter(Boolean)\n\n        const extra = subgraph.extra as Record<string, unknown>\n\n        let aliases: string[]\n        const rawAliases = metadata?.aliases\n        if (rawAliases == null) {\n          const input = await dialogService.prompt({\n            title: t('subgraphStore.searchAliases'),\n            message: t('subgraphStore.enterSearchAliases'),\n            defaultValue: parseAliases(extra.BlueprintSearchAliases ?? '').join(\n              ', '\n            )\n          })\n          if (input === null) return\n          aliases = parseAliases(input)\n        } else {\n          aliases = parseAliases(rawAliases)\n        }\n\n        extra.BlueprintSearchAliases = aliases.length > 0 ? aliases : undefined\n        workflowStore.activeWorkflow?.changeTracker.captureCanvasState()\n      }\n    },\n    {\n      id: 'Comfy.Dev.ShowModelSelector',\n      icon: 'pi pi-box',\n      label: 'Show Model Selector (Dev)',\n      versionAdded: '1.26.2',\n      category: 'view-controls' as const,\n      function: () => {\n        const modelSelectorDialog = useModelSelectorDialog()\n        modelSelectorDialog.show()\n      }\n    },\n    {\n      id: 'Comfy.Manager.CustomNodesManager.ShowLegacyCustomNodesMenu',\n      icon: 'pi pi-bars',\n      label: 'Custom Nodes (Legacy)',\n      versionAdded: '1.16.4',\n      function: async () => {\n        await useManagerState().openManager({\n          legacyCommand: 'Comfy.Manager.CustomNodesManager.ToggleVisibility',\n          showToastOnLegacyError: true,\n          isLegacyOnly: true\n        })\n      }\n    },\n    {\n      id: 'Comfy.Manager.ShowLegacyManagerMenu',\n      icon: 'mdi mdi-puzzle',\n      label: 'Manager Menu (Legacy)',\n      versionAdded: '1.16.4',\n      function: async () => {\n        await useManagerState().openManager({\n          showToastOnLegacyError: true,\n          isLegacyOnly: true\n        })\n      }\n    },\n    {\n      id: 'Comfy.Memory.UnloadModels',\n      icon: 'mdi mdi-vacuum-outline',\n      label: 'Unload Models',\n      versionAdded: '1.16.4',\n      function: async () => {\n        if (!useSettingStore().get('Comfy.Memory.AllowManualUnload')) {\n          toast.error(t('g.error'), {\n            description: t('g.commandProhibited', {\n              command: 'Comfy.Memory.UnloadModels'\n            })\n          })\n          return\n        }\n        await api.freeMemory({ freeExecutionCache: false })\n      }\n    },\n    {\n      id: 'Comfy.Memory.UnloadModelsAndExecutionCache',\n      icon: 'mdi mdi-vacuum-outline',\n      label: 'Unload Models and Execution Cache',\n      versionAdded: '1.16.4',\n      function: async () => {\n        if (!useSettingStore().get('Comfy.Memory.AllowManualUnload')) {\n          toast.error(t('g.error'), {\n            description: t('g.commandProhibited', {\n              command: 'Comfy.Memory.UnloadModelsAndExecutionCache'\n            })\n          })\n          return\n        }\n        await api.freeMemory({ freeExecutionCache: true })\n      }\n    },\n    {\n      id: 'Comfy.BrowseModelAssets',\n      icon: 'pi pi-folder-open',\n      label: 'Experimental: Browse Model Assets',\n      versionAdded: '1.28.3',\n      function: async () => {\n        await openModelLibraryBrowser()\n      }\n    },\n    {\n      id: 'Comfy.ToggleQPOV2',\n      icon: 'pi pi-list',\n      label: 'Toggle Queue Panel V2',\n      function: toggleQueuePanelV2\n    },\n    {\n      id: 'Comfy.ToggleLinear',\n      icon: 'pi pi-database',\n      label: 'Toggle App Mode',\n      function: (metadata?: Record<string, unknown>) => {\n        const source =\n          typeof metadata?.source === 'string' ? metadata.source : 'keybind'\n        const newMode = !canvasStore.linearMode\n        if (newMode) useTelemetry()?.trackEnterLinear({ source })\n        canvasStore.linearMode = newMode\n      }\n    }\n  ]\n\n  return commands.map((command) => ({ ...command, source: 'System' }))\n}\n","import { useTimeoutFn } from '@vueuse/core'\nimport { ref, watch } from 'vue'\n\nimport { useQueueStore } from '@/stores/queueStore'\n\nconst BASE_INTERVAL_MS = 8_000\nconst MAX_INTERVAL_MS = 32_000\nconst BACKOFF_MULTIPLIER = 1.5\n\nexport function useQueuePolling() {\n  const queueStore = useQueueStore()\n  const delay = ref(BASE_INTERVAL_MS)\n\n  const { start, stop } = useTimeoutFn(\n    () => {\n      if (queueStore.activeJobsCount !== 1 || queueStore.isLoading) return\n      delay.value = Math.min(delay.value * BACKOFF_MULTIPLIER, MAX_INTERVAL_MS)\n      void queueStore.update()\n    },\n    delay,\n    { immediate: false }\n  )\n\n  function scheduleNextPoll() {\n    if (queueStore.activeJobsCount === 1 && !queueStore.isLoading) start()\n    else stop()\n  }\n\n  watch(\n    () => queueStore.activeJobsCount,\n    () => {\n      delay.value = BASE_INTERVAL_MS\n      scheduleNextPoll()\n    },\n    { immediate: true }\n  )\n\n  // Reschedule after any update completes (whether from polling or\n  // WebSocket events) to avoid redundant requests.\n  watch(\n    () => queueStore.isLoading,\n    (loading, wasLoading) => {\n      if (wasLoading && !loading) scheduleNextPoll()\n    },\n    { flush: 'sync' }\n  )\n}\n","import { useExecutionStore } from '@/stores/executionStore'\nimport { useQueueStore } from '@/stores/queueStore'\n\n/**\n * After a WebSocket reconnect, refresh the queue from the server and clear\n * any active job that finished during the disconnect window. Returns the\n * handler so the caller can wire it to the `reconnected` api event.\n *\n * `update()` preserves the previous queue snapshot when the fetch fails, so\n * if the network is still flaky we reconcile against the last known good\n * state rather than an empty (and falsely \"stale\") set.\n */\nexport function useReconnectQueueRefresh() {\n  const queueStore = useQueueStore()\n  const executionStore = useExecutionStore()\n\n  return async function refreshOnReconnect() {\n    await queueStore.update()\n    const activeJobIds = new Set([\n      ...queueStore.runningTasks.map((t) => t.jobId),\n      ...queueStore.pendingTasks.map((t) => t.jobId)\n    ])\n    executionStore.clearActiveJobIfStale(activeJobIds)\n  }\n}\n","import { useDocumentVisibility, useTimeoutFn } from '@vueuse/core'\nimport { ref, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { createToastId } from '@/types/toastId'\nimport { useSettingStore } from '@/platform/settings/settingStore'\n\nconst RECONNECT_TOAST_DELAY_MS = 2000\n// Backgrounded-tab timer throttling can let disconnect and reconnect both fire right as the tab regains focus, racing past RECONNECT_TOAST_DELAY_MS, so use a longer delay during the grace window below.\nconst VISIBILITY_REGAINED_TOAST_DELAY_MS = 5000\nconst VISIBILITY_REGAINED_GRACE_MS = 10000\n\nexport function useReconnectingNotification() {\n  const { t } = useI18n()\n  const toast = useToast()\n  const settingStore = useSettingStore()\n\n  const toastDelayMs = ref(RECONNECT_TOAST_DELAY_MS)\n  const reconnectingToastId = createToastId()\n\n  const { start, stop, isPending } = useTimeoutFn(\n    () => {\n      toast.error(t('g.reconnecting'), { id: reconnectingToastId })\n    },\n    toastDelayMs,\n    { immediate: false }\n  )\n\n  const { start: startGracePeriod } = useTimeoutFn(\n    () => {\n      toastDelayMs.value = RECONNECT_TOAST_DELAY_MS\n    },\n    VISIBILITY_REGAINED_GRACE_MS,\n    { immediate: false }\n  )\n\n  const visibility = useDocumentVisibility()\n  watch(visibility, (state) => {\n    if (state !== 'visible') return\n\n    toastDelayMs.value = VISIBILITY_REGAINED_TOAST_DELAY_MS\n    startGracePeriod()\n\n    if (isPending.value) start()\n  })\n\n  function onReconnecting() {\n    if (settingStore.get('Comfy.Toast.DisableReconnectingToast')) return\n    start()\n  }\n\n  function onReconnected() {\n    stop()\n\n    if (toast.dismiss(reconnectingToastId)) {\n      toast.success(t('g.reconnected'), { duration: 2000 })\n    }\n  }\n\n  return { onReconnecting, onReconnected }\n}\n","import { useFavicon } from '@vueuse/core'\nimport { watch } from 'vue'\n\nimport { useExecutionStore } from '@/stores/executionStore'\n\nexport const useProgressFavicon = () => {\n  const defaultFavicon = '/assets/images/favicon_progress_16x16/frame_9.png'\n  const favicon = useFavicon(defaultFavicon)\n  const executionStore = useExecutionStore()\n  const totalFrames = 10\n\n  watch(\n    [() => executionStore.executionProgress, () => executionStore.isIdle],\n    ([progress, isIdle]) => {\n      if (isIdle) {\n        favicon.value = defaultFavicon\n      } else {\n        const frame = Math.min(\n          Math.max(0, Math.floor(progress * totalFrames)),\n          totalFrames - 1\n        )\n        favicon.value = `/assets/images/favicon_progress_16x16/frame_${frame}.png`\n      }\n    }\n  )\n}\n","import type { LGraph } from '@/lib/litegraph/src/litegraph'\nimport type { MissingMediaCandidate } from '@/platform/missingMedia/types'\nimport { getNodeByExecutionId } from '@/utils/graphTraversalUtil'\n\nexport function refreshDownloadedTemplateInputBindings(\n  rootGraph: LGraph,\n  candidates: readonly MissingMediaCandidate[],\n  completedInputNames: ReadonlySet<string>\n): void {\n  const refreshedWidgets = new Set<string>()\n\n  for (const candidate of candidates) {\n    if (!completedInputNames.has(candidate.name)) continue\n\n    const widgetId = `${String(candidate.nodeId)}\\0${candidate.widgetName}`\n    if (refreshedWidgets.has(widgetId)) continue\n\n    const node = getNodeByExecutionId(rootGraph, String(candidate.nodeId))\n    const widget = node?.widgets?.find(\n      ({ name }) => name === candidate.widgetName\n    )\n    if (!node || widget?.value !== candidate.name || !widget.callback) continue\n\n    refreshedWidgets.add(widgetId)\n    widget.callback(widget.value, undefined, node)\n  }\n}\n","export enum LatentPreviewMethod {\n  NoPreviews = 'none',\n  Auto = 'auto',\n  Latent2RGB = 'latent2rgb',\n  TAESD = 'taesd'\n}\n\nexport enum LogLevel {\n  DEBUG = 'DEBUG',\n  INFO = 'INFO',\n  WARNING = 'WARNING',\n  ERROR = 'ERROR',\n  CRITICAL = 'CRITICAL'\n}\n\nexport enum HashFunction {\n  MD5 = 'md5',\n  SHA1 = 'sha1',\n  SHA256 = 'sha256',\n  SHA512 = 'sha512'\n}\n\nexport enum CudaMalloc {\n  // Let server decide whether to use CUDA malloc based on the current environment\n  Auto = 'auto',\n  // Disable CUDA malloc\n  Disable = 'disable',\n  // Enable CUDA malloc\n  Enable = 'enable'\n}\n\nexport enum FloatingPointPrecision {\n  AUTO = 'auto',\n  FP64 = 'fp64',\n  FP32 = 'fp32',\n  FP16 = 'fp16',\n  BF16 = 'bf16',\n  FP8E4M3FN = 'fp8_e4m3fn',\n  FP8E5M2 = 'fp8_e5m2'\n}\n\nexport enum CrossAttentionMethod {\n  Auto = 'auto',\n  Split = 'split',\n  Quad = 'quad',\n  Pytorch = 'pytorch'\n}\n\nexport enum VramManagement {\n  Auto = 'auto',\n  GPUOnly = 'gpu-only',\n  HighVram = 'highvram',\n  NormalVram = 'normalvram',\n  LowVram = 'lowvram',\n  NoVram = 'novram',\n  CPU = 'cpu'\n}\n","import type { FormItem } from '@/platform/settings/types'\nimport {\n  CrossAttentionMethod,\n  CudaMalloc,\n  FloatingPointPrecision,\n  HashFunction,\n  LatentPreviewMethod,\n  LogLevel,\n  VramManagement\n} from '@/types/serverArgs'\n\nexport type ServerConfigValue = string | number | boolean | null | undefined\n\nexport interface ServerConfig<T> extends FormItem {\n  id: string\n  defaultValue: T\n  category?: string[]\n  // Override the default value getter with a custom function.\n  getValue?: (value: T) => Record<string, ServerConfigValue>\n}\n\nexport const SERVER_CONFIG_ITEMS = [\n  // Network settings\n  {\n    id: 'listen',\n    name: 'Host: The IP address to listen on',\n    category: ['Network'],\n    type: 'text',\n    defaultValue: '127.0.0.1'\n  },\n  {\n    id: 'port',\n    name: 'Port: The port to listen on',\n    category: ['Network'],\n    type: 'number',\n    // The default launch port for desktop app is 8000 instead of 8188.\n    defaultValue: 8000\n  },\n  {\n    id: 'tls-keyfile',\n    name: 'TLS Key File: Path to TLS key file for HTTPS',\n    category: ['Network'],\n    type: 'text',\n    defaultValue: ''\n  },\n  {\n    id: 'tls-certfile',\n    name: 'TLS Certificate File: Path to TLS certificate file for HTTPS',\n    category: ['Network'],\n    type: 'text',\n    defaultValue: ''\n  },\n  {\n    id: 'enable-cors-header',\n    name: 'Enable CORS header: Use \"*\" for all origins or specify domain',\n    category: ['Network'],\n    type: 'text',\n    defaultValue: ''\n  },\n  {\n    id: 'max-upload-size',\n    name: 'Maximum upload size (MB)',\n    category: ['Network'],\n    type: 'number',\n    defaultValue: 100\n  },\n\n  // CUDA settings\n  {\n    id: 'cuda-device',\n    name: 'CUDA device index to use',\n    category: ['CUDA'],\n    type: 'number',\n    defaultValue: null\n  },\n  {\n    id: 'cuda-malloc',\n    name: 'Use CUDA malloc for memory allocation',\n    category: ['CUDA'],\n    type: 'combo',\n    options: Object.values(CudaMalloc),\n    defaultValue: CudaMalloc.Auto,\n    getValue: (value: CudaMalloc) => {\n      switch (value) {\n        case CudaMalloc.Auto:\n          return {}\n        case CudaMalloc.Enable:\n          return {\n            ['cuda-malloc']: true\n          }\n        case CudaMalloc.Disable:\n          return {\n            ['disable-cuda-malloc']: true\n          }\n      }\n    }\n  },\n\n  // Precision settings\n  {\n    id: 'global-precision',\n    name: 'Global floating point precision',\n    category: ['Inference'],\n    type: 'combo',\n    options: [\n      FloatingPointPrecision.AUTO,\n      FloatingPointPrecision.FP32,\n      FloatingPointPrecision.FP16\n    ],\n    defaultValue: FloatingPointPrecision.AUTO,\n    tooltip: 'Global floating point precision',\n    getValue: (value: FloatingPointPrecision) => {\n      switch (value) {\n        case FloatingPointPrecision.AUTO:\n          return {}\n        case FloatingPointPrecision.FP32:\n          return {\n            ['force-fp32']: true\n          }\n        case FloatingPointPrecision.FP16:\n          return {\n            ['force-fp16']: true\n          }\n        default:\n          return {}\n      }\n    }\n  },\n\n  // UNET precision\n  {\n    id: 'unet-precision',\n    name: 'UNET precision',\n    category: ['Inference'],\n    type: 'combo',\n    options: [\n      FloatingPointPrecision.AUTO,\n      FloatingPointPrecision.FP64,\n      FloatingPointPrecision.FP32,\n      FloatingPointPrecision.FP16,\n      FloatingPointPrecision.BF16,\n      FloatingPointPrecision.FP8E4M3FN,\n      FloatingPointPrecision.FP8E5M2\n    ],\n    defaultValue: FloatingPointPrecision.AUTO,\n    tooltip: 'UNET precision',\n    getValue: (value: FloatingPointPrecision) => {\n      switch (value) {\n        case FloatingPointPrecision.AUTO:\n          return {}\n        default:\n          return {\n            [`${value.toLowerCase()}-unet`]: true\n          }\n      }\n    }\n  },\n\n  // VAE settings\n  {\n    id: 'vae-precision',\n    name: 'VAE precision',\n    category: ['Inference'],\n    type: 'combo',\n    options: [\n      FloatingPointPrecision.AUTO,\n      FloatingPointPrecision.FP16,\n      FloatingPointPrecision.FP32,\n      FloatingPointPrecision.BF16\n    ],\n    defaultValue: FloatingPointPrecision.AUTO,\n    tooltip: 'VAE precision',\n    getValue: (value: FloatingPointPrecision) => {\n      switch (value) {\n        case FloatingPointPrecision.AUTO:\n          return {}\n        default:\n          return {\n            [`${value.toLowerCase()}-vae`]: true\n          }\n      }\n    }\n  },\n  {\n    id: 'cpu-vae',\n    name: 'Run VAE on CPU',\n    category: ['Inference'],\n    type: 'boolean',\n    defaultValue: false\n  },\n\n  // Text Encoder settings\n  {\n    id: 'text-encoder-precision',\n    name: 'Text Encoder precision',\n    category: ['Inference'],\n    type: 'combo',\n    options: [\n      FloatingPointPrecision.AUTO,\n      FloatingPointPrecision.FP8E4M3FN,\n      FloatingPointPrecision.FP8E5M2,\n      FloatingPointPrecision.FP16,\n      FloatingPointPrecision.FP32\n    ],\n    defaultValue: FloatingPointPrecision.AUTO,\n    tooltip: 'Text Encoder precision',\n    getValue: (value: FloatingPointPrecision) => {\n      switch (value) {\n        case FloatingPointPrecision.AUTO:\n          return {}\n        default:\n          return {\n            [`${value.toLowerCase()}-text-enc`]: true\n          }\n      }\n    }\n  },\n\n  // Memory and performance settings\n  {\n    id: 'force-channels-last',\n    name: 'Force channels-last memory format',\n    category: ['Memory'],\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'directml',\n    name: 'DirectML device index',\n    category: ['Memory'],\n    type: 'number',\n    defaultValue: null\n  },\n  {\n    id: 'disable-ipex-optimize',\n    name: 'Disable IPEX optimization',\n    category: ['Memory'],\n    type: 'boolean',\n    defaultValue: false\n  },\n\n  // Preview settings\n  {\n    id: 'preview-method',\n    name: 'Method used for latent previews',\n    category: ['Preview'],\n    type: 'combo',\n    options: Object.values(LatentPreviewMethod),\n    defaultValue: LatentPreviewMethod.NoPreviews\n  },\n  {\n    id: 'preview-size',\n    name: 'Size of preview images',\n    category: ['Preview'],\n    type: 'slider',\n    defaultValue: 512,\n    attrs: {\n      min: 128,\n      max: 2048,\n      step: 128\n    }\n  },\n\n  // Cache settings\n  {\n    id: 'cache-classic',\n    name: 'Use classic cache system',\n    category: ['Cache'],\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'cache-lru',\n    name: 'Use LRU caching with a maximum of N node results cached.',\n    category: ['Cache'],\n    type: 'number',\n    defaultValue: null,\n    tooltip: 'May use more RAM/VRAM.'\n  },\n\n  // Attention settings\n  {\n    id: 'cross-attention-method',\n    name: 'Cross attention method',\n    category: ['Attention'],\n    type: 'combo',\n    options: Object.values(CrossAttentionMethod),\n    defaultValue: CrossAttentionMethod.Auto,\n    getValue: (value: CrossAttentionMethod) => {\n      switch (value) {\n        case CrossAttentionMethod.Auto:\n          return {}\n        default:\n          return {\n            [`use-${value.toLowerCase()}-cross-attention`]: true\n          }\n      }\n    }\n  },\n  {\n    id: 'disable-xformers',\n    name: 'Disable xFormers optimization',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'force-upcast-attention',\n    name: 'Force attention upcast',\n    category: ['Attention'],\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'dont-upcast-attention',\n    name: 'Prevent attention upcast',\n    category: ['Attention'],\n    type: 'boolean',\n    defaultValue: false\n  },\n\n  // VRAM management\n  {\n    id: 'vram-management',\n    name: 'VRAM management mode',\n    category: ['Memory'],\n    type: 'combo',\n    options: Object.values(VramManagement),\n    defaultValue: VramManagement.Auto,\n    getValue: (value: VramManagement) => {\n      switch (value) {\n        case VramManagement.Auto:\n          return {}\n        default:\n          return {\n            [value]: true\n          }\n      }\n    }\n  },\n  {\n    id: 'reserve-vram',\n    name: 'Reserved VRAM (GB)',\n    category: ['Memory'],\n    type: 'number',\n    defaultValue: null,\n    tooltip:\n      'Set the amount of vram in GB you want to reserve for use by your OS/other software. By default some amount is reserved depending on your OS.'\n  },\n\n  // Misc settings\n  {\n    id: 'default-hashing-function',\n    name: 'Default hashing function for model files',\n    type: 'combo',\n    options: Object.values(HashFunction),\n    defaultValue: HashFunction.SHA256\n  },\n  {\n    id: 'disable-smart-memory',\n    name: 'Disable smart memory management',\n    tooltip:\n      'Force ComfyUI to aggressively offload to regular ram instead of keeping models in vram when it can.',\n    category: ['Memory'],\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'deterministic',\n    name: 'Make pytorch use slower deterministic algorithms when it can.',\n    type: 'boolean',\n    defaultValue: false,\n    tooltip: 'Note that this might not make images deterministic in all cases.'\n  },\n  {\n    id: 'fast',\n    name: 'Enable some untested and potentially quality deteriorating optimizations.',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'dont-print-server',\n    name: \"Don't print server output to console.\",\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'disable-metadata',\n    name: 'Disable saving prompt metadata in files.',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'enable-manager-legacy-ui',\n    name: 'Use legacy Manager UI',\n    tooltip: 'Uses the legacy ComfyUI-Manager UI instead of the new UI.',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'disable-all-custom-nodes',\n    name: 'Disable loading all custom nodes.',\n    type: 'boolean',\n    defaultValue: false\n  },\n  {\n    id: 'log-level',\n    name: 'Logging verbosity level',\n    type: 'combo',\n    options: Object.values(LogLevel),\n    defaultValue: LogLevel.INFO,\n    getValue: (value: LogLevel) => {\n      return {\n        verbose: value\n      }\n    }\n  },\n  // Directories\n  {\n    id: 'input-directory',\n    name: 'Input directory',\n    category: ['Directories'],\n    type: 'text',\n    defaultValue: ''\n  },\n  {\n    id: 'output-directory',\n    name: 'Output directory',\n    category: ['Directories'],\n    type: 'text',\n    defaultValue: ''\n  }\n]\n","<template>\n  <div\n    class=\"flex items-center justify-between gap-4 px-6 pt-2 pb-6\"\n    data-component-id=\"asset-filter-bar\"\n  >\n    <div\n      class=\"flex items-center gap-4\"\n      data-component-id=\"asset-filter-bar-left\"\n    >\n      <MultiSelect\n        v-if=\"availableFileFormats.length > 0\"\n        v-model=\"activeFileFormatObjects\"\n        :label=\"$t('assetBrowser.fileFormats')\"\n        :options=\"availableFileFormats\"\n        class=\"min-w-32\"\n        data-component-id=\"asset-filter-file-formats\"\n        @update:model-value=\"handleFilterChange\"\n      />\n\n      <MultiSelect\n        v-if=\"availableBaseModels.length > 0\"\n        v-model=\"activeBaseModelObjects\"\n        :label=\"$t('assetBrowser.baseModels')\"\n        :options=\"availableBaseModels\"\n        class=\"min-w-32\"\n        data-component-id=\"asset-filter-base-models\"\n        @update:model-value=\"handleFilterChange\"\n      />\n\n      <SingleSelect\n        v-if=\"showOwnershipFilter\"\n        v-model=\"ownership\"\n        :label=\"$t('assetBrowser.ownership')\"\n        :options=\"ownershipOptions\"\n        class=\"min-w-32\"\n        data-component-id=\"asset-filter-ownership\"\n        @update:model-value=\"handleFilterChange\"\n      />\n    </div>\n\n    <div class=\"flex items-center\" data-component-id=\"asset-filter-bar-right\">\n      <SingleSelect\n        v-model=\"sortBy\"\n        :label=\"$t('assetBrowser.sortBy')\"\n        :options=\"sortOptions\"\n        class=\"min-w-32\"\n        data-component-id=\"asset-filter-sort\"\n        @update:model-value=\"handleFilterChange\"\n      >\n        <template #icon>\n          <i class=\"icon-[lucide--arrow-up-down]\" />\n        </template>\n      </SingleSelect>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport MultiSelect from '@/components/ui/multi-select/MultiSelect.vue'\nimport type { SelectOption } from '@/components/ui/select/types'\nimport SingleSelect from '@/components/ui/single-select/SingleSelect.vue'\nimport { useAssetFilterOptions } from '@/platform/assets/composables/useAssetFilterOptions'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport type {\n  AssetFilterState,\n  AssetSortOption,\n  OwnershipOption\n} from '@/platform/assets/types/filterTypes'\n\nconst { t } = useI18n()\n\nconst sortOptions = computed(() => [\n  { name: t('assetBrowser.sortRecent'), value: 'recent' as const },\n  { name: t('assetBrowser.sortAZ'), value: 'name-asc' as const },\n  { name: t('assetBrowser.sortZA'), value: 'name-desc' as const }\n])\n\nconst { assets = [], showOwnershipFilter = false } = defineProps<{\n  assets?: AssetItem[]\n  showOwnershipFilter?: boolean\n}>()\n\nconst selectedFileFormats = ref<SelectOption[]>([])\nconst selectedBaseModels = ref<SelectOption[]>([])\nconst sortBy = ref<AssetSortOption>('recent')\nconst ownership = ref<OwnershipOption>('all')\n\nconst { availableFileFormats, availableBaseModels, ownershipOptions } =\n  useAssetFilterOptions(() => assets)\n\n// Only show selected items that exist in the current scope\nconst activeFileFormatObjects = computed({\n  get() {\n    return selectedFileFormats.value.filter((opt) =>\n      availableFileFormats.value.some((a) => a.value === opt.value)\n    )\n  },\n  set(value: SelectOption[]) {\n    selectedFileFormats.value = value\n  }\n})\n\nconst activeBaseModelObjects = computed({\n  get() {\n    return selectedBaseModels.value.filter((opt) =>\n      availableBaseModels.value.some((a) => a.value === opt.value)\n    )\n  },\n  set(value: SelectOption[]) {\n    selectedBaseModels.value = value\n  }\n})\n\nconst emit = defineEmits<{\n  filterChange: [filters: AssetFilterState]\n}>()\n\nfunction handleFilterChange() {\n  emit('filterChange', {\n    fileFormats: activeFileFormatObjects.value.map((opt) => opt.value),\n    baseModels: activeBaseModelObjects.value.map((opt) => opt.value),\n    sortBy: sortBy.value,\n    ownership: ownership.value\n  })\n}\n</script>\n","<template>\n  <div\n    class=\"absolute bottom-2 left-2 flex flex-wrap justify-start gap-1 select-none\"\n  >\n    <span\n      v-for=\"badge in badges\"\n      :key=\"badge.label\"\n      :class=\"\n        cn(\n          'rounded-sm bg-modal-card-tag-background px-2 py-1 text-xs font-bold tracking-wider break-all text-modal-card-tag-foreground uppercase'\n        )\n      \"\n    >\n      {{ badge.label }}\n    </span>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\ntype AssetBadge = {\n  label: string\n  type: 'type' | 'base' | 'size'\n}\n\ndefineProps<{\n  badges: AssetBadge[]\n}>()\n</script>\n","<template>\n  <div\n    data-testid=\"asset-card\"\n    data-component-id=\"AssetCard\"\n    :data-asset-id=\"asset.id\"\n    :aria-labelledby=\"titleId\"\n    :aria-describedby=\"descId\"\n    :tabindex=\"interactive ? 0 : -1\"\n    :class=\"\n      cn(\n        'flex h-full flex-col gap-2 overflow-hidden rounded-2xl bg-modal-card-background p-2 transition-all duration-200 select-none',\n        interactive &&\n          'group m-0 appearance-none border-none bg-transparent text-left outline-4 outline-base-foreground outline-none hover:bg-secondary-background focus:bg-secondary-background focus:outline-solid',\n        focused && 'bg-secondary-background outline-solid'\n      )\n    \"\n    @click.stop=\"interactive && $emit('focus', asset)\"\n    @focus=\"interactive && $emit('focus', asset)\"\n    @keydown.enter.self=\"interactive && $emit('select', asset)\"\n  >\n    <div class=\"relative aspect-square w-full overflow-hidden rounded-xl\">\n      <div\n        v-if=\"isLoading || error\"\n        class=\"flex size-full cursor-pointer items-center justify-center bg-linear-to-br from-smoke-400 via-smoke-800 to-charcoal-400\"\n      />\n      <img\n        v-else\n        :src=\"asset.preview_url\"\n        :alt=\"displayName\"\n        class=\"size-full cursor-pointer object-cover\"\n      />\n\n      <AssetBadgeGroup :badges=\"asset.badges\" />\n      <IconGroup\n        :class=\"\n          cn(\n            'invisible absolute top-2 right-2 group-hover:visible',\n            assetMenuOpen && 'visible'\n          )\n        \"\n      >\n        <Button\n          :tooltip=\"$t('assetBrowser.modelInfo.title')\"\n          tooltip-side=\"bottom\"\n          :aria-label=\"$t('assetBrowser.modelInfo.title')\"\n          variant=\"secondary\"\n          size=\"sm\"\n          @click.stop=\"$emit('showInfo', asset)\"\n        >\n          <i class=\"icon-[lucide--info]\" />\n        </Button>\n        <Menu\n          v-if=\"showAssetOptions\"\n          v-model:open=\"assetMenuOpen\"\n          :items=\"assetMenuItems\"\n          align=\"end\"\n        >\n          <template #trigger>\n            <Button\n              size=\"sm\"\n              variant=\"secondary\"\n              icon=\"icon-[lucide--ellipsis]\"\n              :aria-label=\"$t('g.more')\"\n            />\n          </template>\n        </Menu>\n      </IconGroup>\n    </div>\n    <div class=\"flex max-h-32 flex-auto flex-col justify-between gap-2\">\n      <Tooltip :disabled=\"!displayName\" :delay-duration=\"tooltipDelay\">\n        <TooltipTrigger as-child>\n          <h3\n            :id=\"titleId\"\n            :class=\"\n              cn(\n                'm-0 line-clamp-2 text-sm font-semibold wrap-anywhere',\n                'text-base-foreground'\n              )\n            \"\n          >\n            {{ displayName }}\n          </h3>\n        </TooltipTrigger>\n        <TooltipContent>{{ displayName }}</TooltipContent>\n      </Tooltip>\n      <Tooltip :disabled=\"!asset.secondaryText\" :delay-duration=\"tooltipDelay\">\n        <TooltipTrigger as-child>\n          <p\n            :id=\"descId\"\n            :class=\"\n              cn(\n                'm-0 line-clamp-2 [display:-webkit-box] text-sm text-muted-foreground [-webkit-box-orient:vertical] [-webkit-line-clamp:2]'\n              )\n            \"\n          >\n            {{ asset.secondaryText }}\n          </p>\n        </TooltipTrigger>\n        <TooltipContent>{{ asset.secondaryText }}</TooltipContent>\n      </Tooltip>\n      <div class=\"mt-auto flex items-center justify-between gap-2\">\n        <div class=\"flex gap-3 text-xs text-muted-foreground\">\n          <span v-if=\"asset.stats.stars\" class=\"flex items-center gap-1\">\n            <i class=\"icon-[lucide--star] size-3\" />\n            {{ asset.stats.stars }}\n          </span>\n          <span\n            v-if=\"asset.stats.downloadCount\"\n            class=\"flex items-center gap-1\"\n          >\n            <i class=\"icon-[lucide--download] size-3\" />\n            {{ asset.stats.downloadCount }}\n          </span>\n          <span v-if=\"formattedDate\" class=\"flex items-center gap-1\">\n            <i class=\"icon-[lucide--clock] size-3\" />\n            {{ formattedDate }}\n          </span>\n        </div>\n        <Button\n          v-if=\"interactive\"\n          variant=\"secondary\"\n          size=\"lg\"\n          class=\"relative shrink-0\"\n          @click.stop=\"handleSelect\"\n        >\n          {{ $t('g.use') }}\n          <StatusBadge\n            v-if=\"isNewlyImported\"\n            severity=\"contrast\"\n            class=\"absolute -top-0.5 -right-0.5\"\n          />\n        </Button>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref, toValue, useId } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useImageQuiet } from '@/composables/useImageQuiet'\nimport IconGroup from '@/components/button/IconGroup.vue'\nimport StatusBadge from '@/components/common/StatusBadge.vue'\nimport { showConfirmDialog } from '@/components/dialog/confirm/confirmDialog'\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport AssetBadgeGroup from '@/platform/assets/components/AssetBadgeGroup.vue'\nimport type { AssetDisplayItem } from '@/platform/assets/composables/useAssetBrowser'\nimport { assetService } from '@/platform/assets/services/assetService'\nimport { getAssetCardTitle } from '@/platform/assets/utils/assetMetadataUtils'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useAssetDownloadStore } from '@/stores/assetDownloadStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { asset, interactive, focused } = defineProps<{\n  asset: AssetDisplayItem\n  interactive?: boolean\n  focused?: boolean\n}>()\n\nconst emit = defineEmits<{\n  focus: [asset: AssetDisplayItem]\n  select: [asset: AssetDisplayItem]\n  deleted: [asset: AssetDisplayItem]\n  showInfo: [asset: AssetDisplayItem]\n}>()\n\nconst { t, d } = useI18n()\nconst settingStore = useSettingStore()\nconst { closeDialog } = useDialogStore()\nconst { isDownloadedThisSession, acknowledgeAsset } = useAssetDownloadStore()\n\nconst assetMenuOpen = ref(false)\n\nconst titleId = useId()\nconst descId = useId()\n\nconst displayName = computed(() => getAssetCardTitle(asset))\n\n// Format at render so locale switches re-flow; the upstream WeakMap caches\n// AssetItem -> AssetDisplayItem by reference, which would otherwise pin the\n// formatted string to whichever locale was active when first transformed.\nconst formattedDate = computed(() =>\n  asset.created_at\n    ? d(new Date(asset.created_at), { dateStyle: 'short' })\n    : undefined\n)\n\nconst isNewlyImported = computed(() => isDownloadedThisSession(asset.id))\n\nconst showAssetOptions = computed(() => !(asset.is_immutable ?? true))\n\nconst tooltipDelay = computed<number>(() =>\n  settingStore.get('LiteGraph.Node.TooltipDelay')\n)\n\nconst { isLoading, error } = useImageQuiet({\n  src: asset.preview_url ?? '',\n  alt: displayName.value\n})\n\nfunction handleSelect() {\n  acknowledgeAsset(asset.id)\n  emit('select', asset)\n}\n\nfunction confirmDeletion() {\n  assetMenuOpen.value = false\n  const assetName = toValue(displayName)\n  const promptText = ref<string>(t('assetBrowser.deletion.body'))\n  const optionsDisabled = ref(false)\n  const confirmDialog = showConfirmDialog({\n    headerProps: {\n      title: t('assetBrowser.deletion.header')\n    },\n    props: {\n      promptText\n    },\n    footerProps: {\n      confirmText: t('g.delete'),\n      // TODO: These need to be put into the new Button Variants once we have them.\n      confirmClass: cn(\n        'bg-danger-200 text-base-foreground ring-base-foreground hover:bg-danger-200/80 focus:bg-danger-200/80 focus:ring'\n      ),\n      optionsDisabled,\n      onCancel: () => {\n        closeDialog(confirmDialog)\n      },\n      onConfirm: async () => {\n        optionsDisabled.value = true\n        try {\n          promptText.value = t('assetBrowser.deletion.inProgress', {\n            assetName\n          })\n          await assetService.deleteAsset(asset.id)\n          promptText.value = t('assetBrowser.deletion.complete', {\n            assetName\n          })\n          // Give a second for the completion message\n          await new Promise((resolve) => setTimeout(resolve, 1_000))\n          emit('deleted', asset)\n        } catch (err: unknown) {\n          console.error(err)\n          promptText.value = t('assetBrowser.deletion.failed', {\n            assetName\n          })\n          // Give a second for the completion message\n          await new Promise((resolve) => setTimeout(resolve, 3_000))\n        } finally {\n          closeDialog(confirmDialog)\n        }\n      }\n    }\n  })\n}\n\nconst assetMenuItems = computed<MenuItem[]>(() => [\n  {\n    label: () => t('g.delete'),\n    icon: 'icon-[lucide--trash-2]',\n    command: confirmDeletion\n  }\n])\n</script>\n","<template>\n  <div\n    data-component-id=\"AssetGrid\"\n    class=\"h-full\"\n    role=\"grid\"\n    :aria-label=\"$t('assetBrowser.assetCollection')\"\n    :aria-rowcount=\"-1\"\n    :aria-colcount=\"-1\"\n    :aria-setsize=\"assets.length\"\n  >\n    <div v-if=\"loading\" class=\"flex h-full items-center justify-center py-20\">\n      <i\n        class=\"icon-[lucide--loader] size-12 animate-spin text-muted-foreground\"\n      />\n    </div>\n    <div\n      v-else-if=\"assets.length === 0\"\n      class=\"flex h-full flex-col items-center justify-center py-16 text-muted-foreground select-none\"\n    >\n      <i class=\"mb-4 icon-[lucide--search] size-10\" />\n      <h3 class=\"mb-2 text-lg font-medium\">\n        {{ emptyTitle ?? $t('assetBrowser.noAssetsFound') }}\n      </h3>\n      <p class=\"text-center text-sm whitespace-pre-wrap\">\n        {{ emptyMessage ?? $t('assetBrowser.tryAdjustingFilters') }}\n      </p>\n    </div>\n    <VirtualGrid\n      v-else\n      :items=\"assetsWithKey\"\n      :grid-style\n      :default-item-height=\"320\"\n      :default-item-width=\"240\"\n      :max-columns\n    >\n      <template #item=\"{ item }\">\n        <AssetCard\n          :asset=\"item\"\n          :interactive=\"true\"\n          :focused=\"item.id === focusedAssetId\"\n          @focus=\"$emit('assetFocus', $event)\"\n          @select=\"$emit('assetSelect', $event)\"\n          @deleted=\"$emit('assetDeleted', $event)\"\n          @show-info=\"$emit('assetShowInfo', $event)\"\n        />\n      </template>\n    </VirtualGrid>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { breakpointsTailwind, useBreakpoints } from '@vueuse/core'\nimport type { CSSProperties } from 'vue'\nimport { computed } from 'vue'\n\nimport VirtualGrid from '@/components/common/VirtualGrid.vue'\nimport AssetCard from '@/platform/assets/components/AssetCard.vue'\nimport type { AssetDisplayItem } from '@/platform/assets/composables/useAssetBrowser'\n\nconst { assets, focusedAssetId, emptyTitle, emptyMessage } = defineProps<{\n  assets: AssetDisplayItem[]\n  loading?: boolean\n  focusedAssetId?: string | null\n  emptyTitle?: string\n  emptyMessage?: string\n}>()\n\ndefineEmits<{\n  assetFocus: [asset: AssetDisplayItem]\n  assetSelect: [asset: AssetDisplayItem]\n  assetDeleted: [asset: AssetDisplayItem]\n  assetShowInfo: [asset: AssetDisplayItem]\n}>()\n\nconst assetsWithKey = computed(() =>\n  assets.map((asset) => ({ ...asset, key: asset.id }))\n)\n\nconst breakpoints = useBreakpoints(breakpointsTailwind)\nconst is2Xl = breakpoints.greaterOrEqual('2xl')\nconst isXl = breakpoints.greaterOrEqual('xl')\nconst isLg = breakpoints.greaterOrEqual('lg')\nconst isMd = breakpoints.greaterOrEqual('md')\nconst maxColumns = computed(() => {\n  if (is2Xl.value) return 5\n  if (isXl.value) return 3\n  if (isLg.value) return 3\n  if (isMd.value) return 2\n  return 1\n})\n\nconst gridStyle: CSSProperties = {\n  display: 'grid',\n  gridTemplateColumns: 'repeat(auto-fill, minmax(15rem, 1fr))',\n  gap: '1rem',\n  padding: '0.5rem'\n}\n</script>\n","export default \"__VITE_PUBLIC_ASSET__53f47e52__\"","export default \"__VITE_PUBLIC_ASSET__1c286d41__\"","<template>\n  <div\n    data-component-id=\"ModelInfoPanel\"\n    class=\"flex scrollbar-custom h-full flex-col\"\n  >\n    <PropertiesAccordionItem :class=\"accordionClass\">\n      <template #label>\n        <span class=\"font-inter text-xs uppercase select-none\">\n          {{ t('assetBrowser.modelInfo.basicInfo') }}\n        </span>\n      </template>\n      <ModelInfoField :label=\"t('assetBrowser.modelInfo.displayName')\">\n        <div class=\"group flex justify-between\">\n          <EditableText\n            :model-value=\"displayName\"\n            :is-editing=\"isEditingDisplayName\"\n            :class=\"cn('flex-auto break-all text-muted-foreground')\"\n            @dblclick=\"isEditingDisplayName = !isImmutable\"\n            @edit=\"handleDisplayNameEdit\"\n            @cancel=\"isEditingDisplayName = false\"\n          />\n          <Button\n            v-if=\"!isImmutable && !isEditingDisplayName\"\n            size=\"icon-sm\"\n            variant=\"muted-textonly\"\n            class=\"opacity-0 transition-opacity group-hover:opacity-100\"\n            :aria-label=\"t('assetBrowser.modelInfo.editDisplayName')\"\n            @click=\"isEditingDisplayName = !isImmutable\"\n          >\n            <i class=\"icon-[lucide--square-pen] size-4 self-center\" />\n          </Button>\n        </div>\n      </ModelInfoField>\n      <ModelInfoField :label=\"t('assetBrowser.modelInfo.fileName')\">\n        <span class=\"break-all text-muted-foreground\">{{\n          getAssetFilename(asset)\n        }}</span>\n      </ModelInfoField>\n      <ModelInfoField\n        v-if=\"sourceUrl\"\n        :label=\"t('assetBrowser.modelInfo.source')\"\n      >\n        <a\n          :href=\"sourceUrl\"\n          target=\"_blank\"\n          rel=\"noopener noreferrer\"\n          class=\"inline-flex items-center gap-1.5 text-muted-foreground no-underline transition-colors hover:text-base-foreground\"\n        >\n          <img\n            v-if=\"sourceName === 'Civitai'\"\n            src=\"/assets/images/civitai.svg\"\n            alt=\"\"\n            class=\"size-4 shrink-0\"\n          />\n          <img\n            v-else-if=\"sourceName === 'Hugging Face'\"\n            src=\"/assets/images/hf-logo.svg\"\n            alt=\"\"\n            class=\"size-4 shrink-0\"\n          />\n          {{ t('assetBrowser.modelInfo.viewOnSource', { source: sourceName }) }}\n          <i class=\"icon-[lucide--external-link] size-4 shrink-0\" />\n        </a>\n      </ModelInfoField>\n    </PropertiesAccordionItem>\n\n    <PropertiesAccordionItem :class=\"accordionClass\">\n      <template #label>\n        <span class=\"font-inter text-xs uppercase select-none\">\n          {{ t('assetBrowser.modelInfo.modelTagging') }}\n        </span>\n      </template>\n      <ModelInfoField :label=\"t('assetBrowser.modelInfo.modelType')\">\n        <Select v-if=\"isModelTypeEditable\" v-model=\"selectedModelType\">\n          <SelectTrigger class=\"w-full\">\n            <SelectValue\n              :placeholder=\"t('assetBrowser.modelInfo.selectModelType')\"\n            />\n          </SelectTrigger>\n          <SelectContent>\n            <SelectItem\n              v-for=\"option in modelTypes\"\n              :key=\"option.value\"\n              :value=\"option.value\"\n            >\n              {{ option.name }}\n            </SelectItem>\n          </SelectContent>\n        </Select>\n        <template v-else>\n          <div\n            aria-disabled=\"true\"\n            :aria-describedby=\"modelTypeReadonlyReasonId\"\n            class=\"cursor-not-allowed p-2 text-sm text-muted-foreground\"\n          >\n            {{\n              modelTypes.find((o) => o.value === selectedModelType)?.name ??\n              t('assetBrowser.unknown')\n            }}\n          </div>\n          <span :id=\"modelTypeReadonlyReasonId\" class=\"sr-only\">\n            {{ modelTypeReadonlyReason }}\n          </span>\n        </template>\n      </ModelInfoField>\n      <ModelInfoField :label=\"t('assetBrowser.modelInfo.compatibleBaseModels')\">\n        <TagsInput\n          v-slot=\"{ isEmpty }\"\n          v-model=\"baseModels\"\n          :disabled=\"isImmutable\"\n        >\n          <TagsInputItem\n            v-for=\"model in baseModels\"\n            :key=\"model\"\n            :value=\"model\"\n          >\n            <TagsInputItemText />\n            <TagsInputItemDelete />\n          </TagsInputItem>\n          <TagsInputInput\n            :is-empty=\"isEmpty\"\n            :placeholder=\"\n              isImmutable\n                ? t('assetBrowser.modelInfo.baseModelUnknown')\n                : t('assetBrowser.modelInfo.addBaseModel')\n            \"\n          />\n        </TagsInput>\n      </ModelInfoField>\n      <ModelInfoField :label=\"t('assetBrowser.modelInfo.additionalTags')\">\n        <TagsInput\n          v-slot=\"{ isEmpty }\"\n          v-model=\"additionalTags\"\n          :disabled=\"isImmutable\"\n        >\n          <TagsInputItem v-for=\"tag in additionalTags\" :key=\"tag\" :value=\"tag\">\n            <TagsInputItemText />\n            <TagsInputItemDelete />\n          </TagsInputItem>\n          <TagsInputInput\n            :is-empty=\"isEmpty\"\n            :placeholder=\"\n              isImmutable\n                ? t('assetBrowser.modelInfo.noAdditionalTags')\n                : t('assetBrowser.modelInfo.addTag')\n            \"\n          />\n        </TagsInput>\n      </ModelInfoField>\n    </PropertiesAccordionItem>\n\n    <PropertiesAccordionItem :class=\"accordionClass\">\n      <template #label>\n        <span class=\"font-inter text-xs uppercase select-none\">\n          {{ t('assetBrowser.modelInfo.modelDescription') }}\n        </span>\n      </template>\n      <ModelInfoField\n        v-if=\"triggerPhrases.length > 0\"\n        :label=\"t('assetBrowser.modelInfo.triggerPhrases')\"\n      >\n        <template #label-action>\n          <Button\n            variant=\"muted-textonly\"\n            size=\"icon-sm\"\n            :title=\"t('g.copyAll')\"\n            :aria-label=\"t('g.copyAll')\"\n            class=\"p-0\"\n            @click=\"copyToClipboard(triggerPhrases.join(', '))\"\n          >\n            <i class=\"icon-[lucide--copy] size-4 min-h-4 min-w-4 opacity-60\" />\n          </Button>\n        </template>\n        <div class=\"flex flex-wrap gap-1 pt-1\">\n          <Button\n            v-for=\"phrase in triggerPhrases\"\n            :key=\"phrase\"\n            variant=\"muted-textonly\"\n            size=\"unset\"\n            :title=\"t('g.copyToClipboard')\"\n            class=\"text-left text-xs text-pretty whitespace-normal\"\n            @click=\"copyToClipboard(phrase)\"\n          >\n            {{ phrase }}\n            <i class=\"icon-[lucide--copy] size-4 min-h-4 min-w-4 opacity-60\" />\n          </Button>\n        </div>\n      </ModelInfoField>\n      <ModelInfoField\n        v-if=\"description\"\n        :label=\"t('assetBrowser.modelInfo.description')\"\n      >\n        <p class=\"text-sm whitespace-pre-wrap\">{{ description }}</p>\n      </ModelInfoField>\n      <ModelInfoField :label=\"t('assetBrowser.modelInfo.description')\">\n        <textarea\n          ref=\"descriptionTextarea\"\n          v-model=\"userDescription\"\n          :disabled=\"isImmutable\"\n          :placeholder=\"\n            isImmutable\n              ? t('assetBrowser.modelInfo.descriptionNotSet')\n              : t('assetBrowser.modelInfo.descriptionPlaceholder')\n          \"\n          rows=\"3\"\n          :class=\"\n            cn(\n              'w-full resize-y scrollbar-gutter-stable rounded-lg border border-transparent bg-transparent px-3 py-2 text-sm text-component-node-foreground transition-colors outline-none focus:bg-component-node-widget-background',\n              isImmutable && 'cursor-not-allowed'\n            )\n          \"\n          @keydown.escape.stop=\"descriptionTextarea?.blur()\"\n        />\n      </ModelInfoField>\n    </PropertiesAccordionItem>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useDebounceFn } from '@vueuse/core'\nimport { computed, ref, useId, useTemplateRef, watch } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport EditableText from '@/components/common/EditableText.vue'\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport PropertiesAccordionItem from '@/components/rightSidePanel/layout/PropertiesAccordionItem.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Select from '@/components/ui/select/Select.vue'\nimport SelectContent from '@/components/ui/select/SelectContent.vue'\nimport SelectItem from '@/components/ui/select/SelectItem.vue'\nimport SelectTrigger from '@/components/ui/select/SelectTrigger.vue'\nimport SelectValue from '@/components/ui/select/SelectValue.vue'\nimport TagsInput from '@/components/ui/tags-input/TagsInput.vue'\nimport TagsInputInput from '@/components/ui/tags-input/TagsInputInput.vue'\nimport TagsInputItem from '@/components/ui/tags-input/TagsInputItem.vue'\nimport TagsInputItemDelete from '@/components/ui/tags-input/TagsInputItemDelete.vue'\nimport TagsInputItemText from '@/components/ui/tags-input/TagsInputItemText.vue'\nimport type { AssetDisplayItem } from '@/platform/assets/composables/useAssetBrowser'\nimport { useModelTypes } from '@/platform/assets/composables/useModelTypes'\nimport { isCloud } from '@/platform/distribution/types'\nimport type { AssetUserMetadata } from '@/platform/assets/schemas/assetSchema'\nimport {\n  getAssetAdditionalTags,\n  getAssetBaseModels,\n  getAssetDescription,\n  getAssetDisplayName,\n  getAssetFilename,\n  getAssetSourceUrl,\n  getAssetTriggerPhrases,\n  getAssetUserDescription,\n  getEditableModelType,\n  getSourceName,\n  resolveModelTypeTagUpdate\n} from '@/platform/assets/utils/assetMetadataUtils'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport ModelInfoField from './ModelInfoField.vue'\n\nconst { t } = useI18n()\nconst { copyToClipboard } = useCopyToClipboard()\n\nconst descriptionTextarea = useTemplateRef<HTMLTextAreaElement>(\n  'descriptionTextarea'\n)\n\nconst accordionClass = cn(\n  'border-t border-border-default bg-modal-panel-background'\n)\n\nconst { asset, cacheKey } = defineProps<{\n  asset: AssetDisplayItem\n  cacheKey?: string\n}>()\n\nconst assetsStore = useAssetsStore()\nconst { flags } = useFeatureFlags()\nconst { modelTypes } = useModelTypes()\n\nconst pendingUpdates = ref<AssetUserMetadata>({})\nconst pendingModelType = ref<string | undefined>(undefined)\nconst isEditingDisplayName = ref(false)\n\nconst isImmutable = computed(() => asset.is_immutable ?? true)\n// Retagging a model rewrites its asset tags; core is filesystem-backed and does\n// not yet move the file to match, so the model type is read-only off-cloud.\nconst isModelTypeEditable = computed(() => !isImmutable.value && isCloud)\n// The read-only field is reached for an immutable asset (even on cloud) or on\n// core. Immutability is the more specific, actionable reason, so it wins when\n// both hold rather than blaming \"core\" on a cloud deployment.\nconst modelTypeReadonlyReason = computed(() =>\n  isImmutable.value\n    ? t('assetBrowser.modelInfo.modelTypeImmutableReadonly')\n    : t('assetBrowser.modelInfo.modelTypeCoreReadonly')\n)\nconst modelTypeReadonlyReasonId = useId()\nconst displayName = computed(\n  () => pendingUpdates.value.name ?? getAssetDisplayName(asset)\n)\nconst sourceUrl = computed(() => getAssetSourceUrl(asset))\nconst sourceName = computed(() =>\n  sourceUrl.value ? getSourceName(sourceUrl.value) : ''\n)\nconst description = computed(() => getAssetDescription(asset))\nconst triggerPhrases = computed(() => getAssetTriggerPhrases(asset))\n\nwatch(\n  () => asset.user_metadata,\n  () => {\n    pendingUpdates.value = {}\n  }\n)\n\nwatch(\n  () => asset.tags,\n  () => {\n    pendingModelType.value = undefined\n  }\n)\n\nconst debouncedFlushMetadata = useDebounceFn(() => {\n  if (isImmutable.value) return\n  assetsStore.updateAssetMetadata(\n    asset,\n    { ...asset.user_metadata, ...pendingUpdates.value },\n    cacheKey\n  )\n}, 500)\n\nfunction queueMetadataUpdate(updates: AssetUserMetadata) {\n  pendingUpdates.value = { ...pendingUpdates.value, ...updates }\n  debouncedFlushMetadata()\n}\n\nfunction handleDisplayNameEdit(newName: string) {\n  isEditingDisplayName.value = false\n  if (newName && newName !== displayName.value) {\n    queueMetadataUpdate({ name: newName })\n  }\n}\n\nconst debouncedSaveModelType = useDebounceFn((newModelType: string) => {\n  const newTags = resolveModelTypeTagUpdate(\n    asset,\n    newModelType,\n    isModelTypeEditable.value,\n    flags.supportsModelTypeTags\n  )\n  if (newTags) assetsStore.updateAssetTags(asset, newTags, cacheKey)\n}, 500)\n\nconst baseModels = computed({\n  get: () => pendingUpdates.value.base_model ?? getAssetBaseModels(asset),\n  set: (value: string[]) => queueMetadataUpdate({ base_model: value })\n})\n\nconst additionalTags = computed({\n  get: () =>\n    pendingUpdates.value.additional_tags ?? getAssetAdditionalTags(asset),\n  set: (value: string[]) => queueMetadataUpdate({ additional_tags: value })\n})\n\nconst userDescription = computed({\n  get: () =>\n    pendingUpdates.value.user_description ?? getAssetUserDescription(asset),\n  set: (value: string) => queueMetadataUpdate({ user_description: value })\n})\n\nconst selectedModelType = computed({\n  get: () =>\n    pendingModelType.value ??\n    getEditableModelType(asset, flags.supportsModelTypeTags) ??\n    undefined,\n  set: (value: string | undefined) => {\n    if (!value) return\n    pendingModelType.value = value\n    debouncedSaveModelType(value)\n  }\n})\n</script>\n","import { computed, ref } from 'vue'\nimport type { Ref } from 'vue'\nimport { useFuse } from '@vueuse/integrations/useFuse'\nimport type { UseFuseOptions } from '@vueuse/integrations/useFuse'\nimport { storeToRefs } from 'pinia'\n\nimport { t } from '@/i18n'\nimport type {\n  AssetFilterState,\n  OwnershipOption\n} from '@/platform/assets/types/filterTypes'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { useAssetFilterOptions } from '@/platform/assets/composables/useAssetFilterOptions'\nimport {\n  filterByBaseModels,\n  filterByCategory,\n  filterByFileFormats,\n  filterByOwnership\n} from '@/platform/assets/utils/assetFilterUtils'\nimport {\n  getAssetBaseModels,\n  getAssetCategories,\n  getAssetFilename,\n  getAssetTypeBadges\n} from '@/platform/assets/utils/assetMetadataUtils'\nimport { MODELS_TAG } from '@/platform/assets/services/assetService'\nimport { sortAssets } from '@/platform/assets/utils/assetSortUtils'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useAssetDownloadStore } from '@/stores/assetDownloadStore'\nimport type { NavGroupData, NavItemData } from '@/types/navTypes'\n\ntype NavId = 'all' | 'imported' | (string & {})\n\ntype AssetBadge = {\n  label: string\n  type: 'type' | 'base' | 'size'\n}\n\n// Display properties for transformed assets\nexport interface AssetDisplayItem extends AssetItem {\n  secondaryText: string\n  badges: AssetBadge[]\n  stats: {\n    downloadCount?: string\n    stars?: string\n  }\n}\n\nconst displayItemCache = new WeakMap<\n  AssetItem,\n  { modelTypeMode: boolean; item: AssetDisplayItem }\n>()\n\nfunction buildDisplayItem(\n  asset: AssetItem,\n  modelTypeMode: boolean\n): AssetDisplayItem {\n  const badges: AssetBadge[] = []\n\n  for (const typeBadge of getAssetTypeBadges(asset, modelTypeMode)) {\n    badges.push({ label: typeBadge, type: 'type' })\n  }\n\n  for (const model of getAssetBaseModels(asset)) {\n    badges.push({ label: model, type: 'base' })\n  }\n\n  // Intentionally no formatted date here — the WeakMap caches by AssetItem\n  // reference, so a pre-formatted string would pin the locale active at first\n  // transform. AssetCard formats `created_at` at render via `d()` instead.\n  return {\n    ...asset,\n    secondaryText: getAssetFilename(asset),\n    badges,\n    stats: {\n      downloadCount: undefined,\n      stars: undefined\n    }\n  }\n}\n\nfunction transformAssetForDisplay(\n  asset: AssetItem,\n  modelTypeMode: boolean\n): AssetDisplayItem {\n  const cached = displayItemCache.get(asset)\n  if (cached && cached.modelTypeMode === modelTypeMode) return cached.item\n  const item = buildDisplayItem(asset, modelTypeMode)\n  displayItemCache.set(asset, { modelTypeMode, item })\n  return item\n}\n\n/**\n * Asset Browser composable\n * Manages search, filtering, asset transformation and selection logic\n */\nexport function useAssetBrowser(\n  assetsSource: Ref<AssetItem[] | undefined> = ref<AssetItem[] | undefined>([])\n) {\n  const assets = computed<AssetItem[]>(() => assetsSource.value ?? [])\n  const assetDownloadStore = useAssetDownloadStore()\n  const { sessionDownloadCount } = storeToRefs(assetDownloadStore)\n  const { flags } = useFeatureFlags()\n\n  // State\n  const searchQuery = ref('')\n  const selectedNavItem = ref<NavId>('all')\n  const filters = ref<AssetFilterState>({\n    sortBy: 'recent',\n    fileFormats: [],\n    baseModels: [],\n    ownership: 'all'\n  })\n\n  const selectedOwnership = computed<OwnershipOption>(() => {\n    if (typeCategories.value.length <= 1) return filters.value.ownership\n    if (selectedNavItem.value === 'imported') return 'my-models'\n    if (selectedNavItem.value === 'all') return 'all'\n    return filters.value.ownership\n  })\n\n  const selectedCategory = computed(() => {\n    if (\n      selectedNavItem.value === 'all' ||\n      selectedNavItem.value === 'imported'\n    ) {\n      return 'all'\n    }\n    return selectedNavItem.value\n  })\n\n  const typeCategories = computed<NavItemData[]>(() => {\n    const modelTypeMode = flags.supportsModelTypeTags\n    const categories = assets.value\n      .filter((asset) => asset.tags.includes(MODELS_TAG))\n      .flatMap((asset) => getAssetCategories(asset, modelTypeMode))\n\n    return Array.from(new Set(categories))\n      .sort()\n      .map((category) => ({\n        id: category,\n        label: category.charAt(0).toUpperCase() + category.slice(1),\n        icon: 'icon-[lucide--folder]'\n      }))\n  })\n\n  const navItems = computed<(NavItemData | NavGroupData)[]>(() => {\n    const quickFilters: NavItemData[] = [\n      {\n        id: 'all',\n        label: t('assetBrowser.allModels'),\n        icon: 'icon-[lucide--list]'\n      },\n      {\n        id: 'imported',\n        label: t('assetBrowser.imported'),\n        icon: 'icon-[lucide--folder-input]',\n        badge:\n          sessionDownloadCount.value > 0\n            ? sessionDownloadCount.value\n            : undefined\n      }\n    ]\n\n    if (typeCategories.value.length === 0) {\n      return quickFilters\n    }\n\n    return [\n      ...quickFilters,\n      {\n        title: t('assetBrowser.byType'),\n        items: typeCategories.value,\n        collapsible: false\n      }\n    ]\n  })\n\n  const isImportedSelected = computed(\n    () => selectedNavItem.value === 'imported'\n  )\n\n  // Compute content title from selected nav item\n  const contentTitle = computed(() => {\n    if (selectedNavItem.value === 'all') {\n      return t('assetBrowser.allModels')\n    }\n    if (selectedNavItem.value === 'imported') {\n      return t('assetBrowser.imported')\n    }\n\n    const category = typeCategories.value.find(\n      (cat) => cat.id === selectedNavItem.value\n    )\n    return category?.label || t('assetBrowser.assets')\n  })\n\n  // Category-filtered assets for filter options (before search/format/base model filters)\n  const categoryFilteredAssets = computed(() => {\n    return assets.value.filter(\n      filterByCategory(selectedCategory.value, flags.supportsModelTypeTags)\n    )\n  })\n\n  const { availableFileFormats, availableBaseModels } = useAssetFilterOptions(\n    categoryFilteredAssets\n  )\n\n  const activeFileFormats = computed(() =>\n    filters.value.fileFormats.filter((f) =>\n      availableFileFormats.value.some((opt) => opt.value === f)\n    )\n  )\n\n  const activeBaseModels = computed(() =>\n    filters.value.baseModels.filter((m) =>\n      availableBaseModels.value.some((opt) => opt.value === m)\n    )\n  )\n\n  const fuseOptions: UseFuseOptions<AssetItem> = {\n    fuseOptions: {\n      keys: [\n        { name: 'name', weight: 0.4 },\n        { name: 'tags', weight: 0.3 },\n        { name: 'user_metadata.name', weight: 0.4 },\n        { name: 'user_metadata.additional_tags', weight: 0.3 },\n        { name: 'user_metadata.trained_words', weight: 0.3 },\n        { name: 'user_metadata.user_description', weight: 0.3 },\n        { name: 'metadata.name', weight: 0.4 },\n        { name: 'metadata.trained_words', weight: 0.3 }\n      ],\n      threshold: 0.4, // Higher threshold for typo tolerance (0.0 = exact, 1.0 = match all)\n      ignoreLocation: true, // Search anywhere in the string, not just at the beginning\n      includeScore: true\n    },\n    matchAllWhenSearchEmpty: true\n  }\n\n  const { results: fuseResults } = useFuse(\n    searchQuery,\n    categoryFilteredAssets,\n    fuseOptions\n  )\n\n  const searchFiltered = computed(() =>\n    fuseResults.value.map((result) => result.item)\n  )\n\n  const filteredAssets = computed(() => {\n    const filtered = searchFiltered.value\n      .filter(filterByFileFormats(activeFileFormats.value))\n      .filter(filterByBaseModels(activeBaseModels.value))\n      .filter(filterByOwnership(selectedOwnership.value))\n\n    const sortedAssets = sortAssets(filtered, filters.value.sortBy)\n\n    // Transform to display format\n    const modelTypeMode = flags.supportsModelTypeTags\n    return sortedAssets.map((asset) =>\n      transformAssetForDisplay(asset, modelTypeMode)\n    )\n  })\n\n  function updateFilters(newFilters: AssetFilterState) {\n    filters.value = { ...newFilters }\n  }\n\n  return {\n    searchQuery,\n    selectedNavItem,\n    selectedCategory,\n    navItems,\n    contentTitle,\n    categoryFilteredAssets,\n    filteredAssets,\n    isImportedSelected,\n    updateFilters\n  }\n}\n","<template>\n  <BaseModalLayout\n    v-model:right-panel-open=\"isRightPanelOpen\"\n    data-testid=\"asset-browser-modal\"\n    data-component-id=\"AssetBrowserModal\"\n    class=\"size-full max-h-full max-w-full min-w-0\"\n    :content-title=\"displayTitle\"\n    :right-panel-title=\"$t('assetBrowser.modelInfo.title')\"\n    @close=\"handleClose\"\n  >\n    <template v-if=\"shouldShowLeftPanel\" #leftPanelHeaderTitle>\n      <i class=\"icon-[comfy--ai-model] size-4\" />\n      <h2 class=\"flex-auto text-base font-semibold text-nowrap select-none\">\n        {{ displayTitle }}\n      </h2>\n    </template>\n    <template v-if=\"shouldShowLeftPanel\" #leftPanel>\n      <LeftSidePanel\n        v-model=\"selectedNavItem\"\n        data-component-id=\"AssetBrowserModal-LeftSidePanel\"\n        :nav-items\n      />\n    </template>\n\n    <template #header>\n      <div\n        class=\"flex w-full items-center justify-between gap-2\"\n        @click.self=\"focusedAsset = null\"\n      >\n        <SearchInput\n          v-model=\"searchQuery\"\n          :autofocus=\"true\"\n          size=\"lg\"\n          :aria-label=\"$t('assetBrowser.searchModels')\"\n          :placeholder=\"$t('g.searchPlaceholder', { subject: '' })\"\n          class=\"max-w-lg flex-1\"\n        />\n        <Button\n          v-if=\"isUploadButtonEnabled\"\n          variant=\"primary\"\n          :size=\"breakpoints.md ? 'lg' : 'icon'\"\n          :aria-label=\"$t('assetBrowser.uploadModel')\"\n          data-attr=\"upload-model-button\"\n          @click=\"showUploadDialog\"\n        >\n          <i class=\"icon-[lucide--folder-input]\" />\n          <span class=\"hidden md:inline\">{{\n            $t('assetBrowser.uploadModel')\n          }}</span>\n        </Button>\n      </div>\n    </template>\n\n    <template #contentFilter>\n      <AssetFilterBar\n        :assets=\"categoryFilteredAssets\"\n        :show-ownership-filter\n        @filter-change=\"updateFilters\"\n        @click.self=\"focusedAsset = null\"\n      />\n    </template>\n\n    <template #content>\n      <AssetGrid\n        :assets=\"filteredAssets\"\n        :loading=\"isLoading\"\n        :focused-asset-id=\"focusedAsset?.id\"\n        :empty-message\n        @asset-focus=\"handleAssetFocus\"\n        @asset-select=\"handleAssetSelectAndEmit\"\n        @asset-deleted=\"refreshAssets\"\n        @asset-show-info=\"handleShowInfo\"\n        @click=\"focusedAsset = null\"\n      />\n    </template>\n\n    <template #rightPanel>\n      <ModelInfoPanel v-if=\"focusedAsset\" :asset=\"focusedAsset\" :cache-key />\n      <div\n        v-else\n        class=\"flex h-full items-center justify-center p-6 text-center wrap-break-word text-muted\"\n      >\n        {{ $t('assetBrowser.modelInfo.selectModelPrompt') }}\n      </div>\n    </template>\n  </BaseModalLayout>\n</template>\n\n<script setup lang=\"ts\">\nimport { breakpointsTailwind, useBreakpoints } from '@vueuse/core'\nimport { computed, provide, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport BaseModalLayout from '@/components/widget/layout/BaseModalLayout.vue'\nimport LeftSidePanel from '@/components/widget/panel/LeftSidePanel.vue'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport AssetFilterBar from '@/platform/assets/components/AssetFilterBar.vue'\nimport AssetGrid from '@/platform/assets/components/AssetGrid.vue'\nimport ModelInfoPanel from '@/platform/assets/components/modelInfo/ModelInfoPanel.vue'\nimport type { AssetDisplayItem } from '@/platform/assets/composables/useAssetBrowser'\nimport { useAssetBrowser } from '@/platform/assets/composables/useAssetBrowser'\nimport { useModelTypes } from '@/platform/assets/composables/useModelTypes'\nimport { useModelUpload } from '@/platform/assets/composables/useModelUpload'\nimport type { AssetBrowserModalProps } from '@/platform/assets/types/assetBrowserModalProps'\nimport { getPrimaryCategoryTag } from '@/platform/assets/utils/assetMetadataUtils'\nimport { formatCategoryLabel } from '@/platform/assets/utils/categoryLabel'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { useModelToNodeStore } from '@/stores/modelToNodeStore'\nimport { OnCloseKey } from '@/types/widgetTypes'\n\nconst { t } = useI18n()\nconst { flags } = useFeatureFlags()\nconst assetStore = useAssetsStore()\nconst modelToNodeStore = useModelToNodeStore()\nconst breakpoints = useBreakpoints(breakpointsTailwind)\n\nconst props = defineProps<AssetBrowserModalProps>()\n\nconst emit = defineEmits<{\n  'asset-select': [asset: AssetDisplayItem]\n  close: []\n}>()\n\nprovide(OnCloseKey, props.onClose ?? (() => {}))\n\nconst cacheKey = computed(() => {\n  if (props.nodeType) return props.nodeType\n  if (props.assetType) return `tag:${props.assetType}`\n  return ''\n})\n\nconst fetchedAssets = computed(\n  () => props.overrideAssets ?? assetStore.getAssets(cacheKey.value)\n)\n\nconst isStoreLoading = computed(() => assetStore.isModelLoading(cacheKey.value))\n\nconst isLoading = computed(\n  () => isStoreLoading.value && fetchedAssets.value.length === 0\n)\n\nasync function refreshAssets(): Promise<void> {\n  if (props.overrideAssets) return\n  if (props.nodeType) {\n    await assetStore.updateModelsForNodeType(props.nodeType)\n  } else if (props.assetType) {\n    await assetStore.updateModelsForTag(props.assetType)\n  }\n}\n\nvoid refreshAssets()\n\nconst { fetchModelTypes } = useModelTypes()\nvoid fetchModelTypes()\n\nconst { isUploadButtonEnabled, showUploadDialog } =\n  useModelUpload(refreshAssets)\n\nconst {\n  searchQuery,\n  selectedNavItem,\n  selectedCategory,\n  navItems,\n  categoryFilteredAssets,\n  filteredAssets,\n  isImportedSelected,\n  updateFilters\n} = useAssetBrowser(fetchedAssets)\n\nconst focusedAsset = ref<AssetDisplayItem | null>(null)\nconst isRightPanelOpen = ref(false)\n\nconst primaryCategoryTag = computed(() => {\n  const modelTypeMode = flags.supportsModelTypeTags\n  // A node-typed picker is FOR a category; title off that category rather\n  // than guessing from the first asset, whose first model_type value may be\n  // a different category it shares a root with.\n  if (modelTypeMode && props.nodeType) {\n    const mapped = modelToNodeStore.getCategoryForNodeType(props.nodeType)\n    if (mapped) return mapped\n  }\n\n  const assets = fetchedAssets.value ?? []\n  // Covered assets title off the model_type value they group under (so title\n  // and grouping cannot diverge); uncovered assets keep the legacy verbatim\n  // first tag.\n  const tagFromAssets = assets\n    .map((asset) => getPrimaryCategoryTag(asset, modelTypeMode))\n    .find((tag): tag is string => typeof tag === 'string' && tag.length > 0)\n\n  if (tagFromAssets) return tagFromAssets\n\n  if (props.nodeType) {\n    const mapped = modelToNodeStore.getCategoryForNodeType(props.nodeType)\n    if (mapped) return mapped\n  }\n\n  if (props.assetType) return props.assetType\n\n  return 'models'\n})\n\nconst activeCategoryTag = computed(() => {\n  if (selectedCategory.value !== 'all') {\n    return selectedCategory.value\n  }\n  return primaryCategoryTag.value\n})\n\nconst displayTitle = computed(() => {\n  if (props.title) return props.title\n\n  const label = formatCategoryLabel(activeCategoryTag.value)\n  return t('assetBrowser.allCategory', { category: label })\n})\n\nconst shouldShowLeftPanel = computed(() => {\n  return props.showLeftPanel ?? true\n})\n\nconst showOwnershipFilter = computed(\n  () =>\n    !shouldShowLeftPanel.value ||\n    (selectedNavItem.value !== 'all' && selectedNavItem.value !== 'imported')\n)\n\nconst emptyMessage = computed(() => {\n  if (!isImportedSelected.value) {\n    return isUploadButtonEnabled.value\n      ? t('assetBrowser.noResultsCanImport')\n      : undefined\n  }\n\n  return isUploadButtonEnabled.value\n    ? t('assetBrowser.emptyImported.canImport')\n    : t('assetBrowser.emptyImported.restricted')\n})\n\nfunction handleClose() {\n  props.onClose?.()\n  emit('close')\n}\n\nfunction handleAssetFocus(asset: AssetDisplayItem) {\n  focusedAsset.value = asset\n}\n\nfunction handleShowInfo(asset: AssetDisplayItem) {\n  focusedAsset.value = asset\n  isRightPanelOpen.value = true\n}\n\nfunction handleAssetSelectAndEmit(asset: AssetDisplayItem) {\n  emit('asset-select', asset)\n  props.onSelect?.(asset)\n}\n</script>\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { visible, announcement = '' } = defineProps<{\n  visible: boolean\n  announcement?: string\n}>()\n\nconst isExpanded = defineModel<boolean>('expanded', { default: false })\n\nfunction toggle() {\n  isExpanded.value = !isExpanded.value\n}\n</script>\n\n<template>\n  <div role=\"status\" aria-atomic=\"true\" class=\"sr-only\">\n    <template v-if=\"visible\">{{ announcement }}</template>\n  </div>\n  <Transition\n    enter-active-class=\"transition-all duration-300 ease-out\"\n    enter-from-class=\"translate-y-full opacity-0\"\n    leave-active-class=\"transition-all duration-200 ease-in\"\n    leave-to-class=\"translate-y-full opacity-0\"\n  >\n    <div\n      v-if=\"visible\"\n      data-testid=\"toast-panel\"\n      :class=\"\n        cn(\n          'w-full max-w-3xl overflow-hidden rounded-lg border border-border-default bg-base-background shadow-lg transition-all duration-300',\n          isExpanded ? 'sm:w-[max(400px,40vw)]' : 'sm:w-fit'\n        )\n      \"\n    >\n      <div\n        :class=\"\n          cn(\n            'max-w-full min-w-0 overflow-hidden transition-all duration-300',\n            isExpanded ? 'max-h-100 w-full' : 'max-h-0 w-0'\n          )\n        \"\n      >\n        <slot />\n      </div>\n\n      <slot name=\"footer\" :toggle />\n    </div>\n  </Transition>\n</template>\n","<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Loader from '@/components/loader/Loader.vue'\nimport ToastPanel from '@/components/ui/toast/ToastPanel.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport type { AssetExport } from '@/stores/assetExportStore'\nimport { useAssetExportStore } from '@/stores/assetExportStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\nconst assetExportStore = useAssetExportStore()\n\nconst visible = computed(() => assetExportStore.hasExports)\nconst isExpanded = ref(false)\n\nconst exportJobs = computed(() => assetExportStore.exportList)\nconst failedJobs = computed(() =>\n  assetExportStore.finishedExports.filter((e) => e.status === 'failed')\n)\nconst cancelledJobs = computed(() =>\n  assetExportStore.finishedExports.filter((e) => e.status === 'cancelled')\n)\n\nconst isInProgress = computed(() => assetExportStore.hasActiveExports)\nconst currentJobName = computed(() => {\n  const activeJob = exportJobs.value.find((job) => job.status === 'running')\n  return activeJob?.exportName || t('exportToast.preparingExport')\n})\n\nfunction jobDisplayName(job: AssetExport): string {\n  if (job.status === 'failed') return job.error || t('exportToast.exportError')\n  return job.exportName || t('exportToast.preparingExport')\n}\n\nconst completedCount = computed(() => assetExportStore.finishedExports.length)\nconst totalCount = computed(() => exportJobs.value.length)\n\nconst footerLabel = computed(() => {\n  if (isInProgress.value) return currentJobName.value\n  if (failedJobs.value.length > 0)\n    return t('exportToast.exportFailed', { count: failedJobs.value.length })\n  if (cancelledJobs.value.length > 0) return t('electronFileDownload.cancelled')\n  return t('exportToast.allExportsCompleted')\n})\n\nconst announcement = computed(() =>\n  isInProgress.value ? t('exportToast.exportingAssets') : footerLabel.value\n)\n\nconst footerIconClass = computed(() => {\n  if (isInProgress.value)\n    return 'icon-[lucide--loader-circle] animate-spin text-muted-foreground'\n  if (failedJobs.value.length > 0)\n    return 'icon-[lucide--circle-alert] text-destructive-background'\n  if (cancelledJobs.value.length > 0)\n    return 'icon-[lucide--circle-x] text-muted-foreground'\n  return 'icon-[lucide--check-circle] text-jade-600'\n})\n\nfunction progressPercent(job: AssetExport): number {\n  return Math.round(job.progress * 100)\n}\n\nfunction closeDialog() {\n  assetExportStore.clearFinishedExports()\n  isExpanded.value = false\n}\n</script>\n\n<template>\n  <ToastPanel v-model:expanded=\"isExpanded\" :visible :announcement>\n    <template #default>\n      <div\n        class=\"flex h-12 items-center justify-between border-b border-border-default px-4\"\n      >\n        <h3 class=\"text-sm font-bold text-base-foreground\">\n          {{ t('exportToast.exportingAssets') }}\n        </h3>\n      </div>\n\n      <div class=\"relative max-h-75 overflow-y-auto p-4\">\n        <div class=\"flex flex-col gap-2\">\n          <div\n            v-for=\"job in exportJobs\"\n            :key=\"job.taskId\"\n            :class=\"\n              cn(\n                'flex items-center justify-between rounded-lg bg-modal-card-background px-4 py-3',\n                job.status === 'completed' && 'opacity-50'\n              )\n            \"\n          >\n            <div class=\"min-w-0 flex-1\">\n              <span\n                :class=\"\n                  cn(\n                    'block truncate text-sm',\n                    job.status === 'failed'\n                      ? 'text-destructive-background'\n                      : 'text-base-foreground'\n                  )\n                \"\n              >\n                {{ jobDisplayName(job) }}\n              </span>\n              <span\n                v-if=\"job.assetsTotal > 0\"\n                class=\"text-xs text-muted-foreground\"\n              >\n                {{ job.assetsAttempted }}/{{ job.assetsTotal }}\n              </span>\n            </div>\n\n            <div class=\"flex items-center gap-2\">\n              <template v-if=\"job.status === 'failed'\">\n                <i\n                  class=\"icon-[lucide--circle-alert] size-4 text-destructive-background\"\n                />\n              </template>\n              <template\n                v-else-if=\"job.status === 'completed' && job.downloadError\"\n              >\n                <span\n                  class=\"max-w-32 truncate text-xs text-destructive-background\"\n                >\n                  {{ job.downloadError }}\n                </span>\n                <Button\n                  variant=\"muted-textonly\"\n                  size=\"icon\"\n                  :aria-label=\"t('exportToast.retryDownload')\"\n                  @click.stop=\"assetExportStore.triggerDownload(job, true)\"\n                >\n                  <i\n                    class=\"icon-[lucide--rotate-ccw] size-4 text-destructive-background\"\n                  />\n                </Button>\n              </template>\n              <template v-else-if=\"job.status === 'completed'\">\n                <Button\n                  variant=\"muted-textonly\"\n                  size=\"icon\"\n                  :aria-label=\"t('exportToast.downloadExport')\"\n                  @click.stop=\"assetExportStore.triggerDownload(job, true)\"\n                >\n                  <i\n                    class=\"icon-[lucide--download] size-4 text-success-background\"\n                  />\n                </Button>\n              </template>\n              <template v-else-if=\"job.status === 'cancelled'\">\n                <span class=\"text-xs text-muted-foreground\">\n                  {{ t('electronFileDownload.cancelled') }}\n                </span>\n              </template>\n              <template v-else-if=\"job.status === 'running'\">\n                <Loader size=\"sm\" class=\"text-base-foreground\" />\n                <span class=\"text-xs text-base-foreground\">\n                  {{ progressPercent(job) }}%\n                </span>\n              </template>\n              <template v-else>\n                <span class=\"text-xs text-muted-foreground\">\n                  {{ t('progressToast.pending') }}\n                </span>\n              </template>\n            </div>\n          </div>\n        </div>\n\n        <div\n          v-if=\"exportJobs.length === 0\"\n          class=\"flex flex-col items-center justify-center py-6 text-center\"\n        >\n          <span class=\"text-sm text-muted-foreground\">\n            {{\n              t('exportToast.noExportsInQueue', {\n                filter: t('progressToast.filter.all')\n              })\n            }}\n          </span>\n        </div>\n      </div>\n    </template>\n\n    <template #footer=\"{ toggle }\">\n      <div\n        class=\"flex h-12 min-w-0 flex-1 items-center justify-between gap-2 border-t border-border-default px-4\"\n      >\n        <div class=\"flex min-w-0 flex-1 items-center gap-2 text-sm\">\n          <Tooltip :disabled=\"isExpanded\">\n            <TooltipTrigger as-child>\n              <i :class=\"cn('size-4 shrink-0', footerIconClass)\" />\n            </TooltipTrigger>\n            <TooltipContent>{{ footerLabel }}</TooltipContent>\n          </Tooltip>\n          <span\n            :class=\"\n              cn(\n                'truncate overflow-hidden font-bold text-base-foreground transition-all duration-300',\n                isExpanded ? 'min-w-0 flex-1' : 'w-0'\n              )\n            \"\n          >\n            {{ footerLabel }}\n          </span>\n        </div>\n\n        <div class=\"flex items-center gap-2\">\n          <span\n            v-if=\"isInProgress\"\n            :class=\"\n              cn(\n                'overflow-hidden text-sm text-muted-foreground transition-all duration-300',\n                isExpanded ? 'whitespace-nowrap' : 'w-0'\n              )\n            \"\n          >\n            {{\n              t('progressToast.progressCount', {\n                completed: completedCount,\n                total: totalCount\n              })\n            }}\n          </span>\n\n          <div class=\"flex items-center\">\n            <Button\n              variant=\"muted-textonly\"\n              size=\"icon\"\n              :aria-label=\"\n                isExpanded ? t('contextMenu.Collapse') : t('contextMenu.Expand')\n              \"\n              @click.stop=\"toggle\"\n            >\n              <i\n                :class=\"\n                  cn(\n                    'size-4',\n                    isExpanded\n                      ? 'icon-[lucide--chevron-down]'\n                      : 'icon-[lucide--chevron-up]'\n                  )\n                \"\n              />\n            </Button>\n\n            <Button\n              v-if=\"!isInProgress\"\n              variant=\"muted-textonly\"\n              size=\"icon\"\n              :aria-label=\"t('g.close')\"\n              @click.stop=\"closeDialog\"\n            >\n              <i class=\"icon-[lucide--x] size-4\" />\n            </Button>\n          </div>\n        </div>\n      </div>\n    </template>\n  </ToastPanel>\n</template>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Loader from '@/components/loader/Loader.vue'\nimport StatusBadge from '@/components/common/StatusBadge.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport type { TaskId } from '@/platform/tasks/services/taskService'\nimport type { AssetDownload } from '@/stores/assetDownloadStore'\nimport { isDownloadCancelled } from '@/stores/assetDownloadStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { job, isCancelling = false } = defineProps<{\n  job: AssetDownload\n  isCancelling?: boolean\n}>()\nconst emit = defineEmits<{ cancel: [taskId: TaskId] }>()\n\nconst { t } = useI18n()\n\nconst progressPercent = computed(() => Math.round(job.progress * 100))\nconst isCompleted = computed(() => job.status === 'completed')\nconst isFailed = computed(() => job.status === 'failed')\nconst isRunning = computed(() => job.status === 'running')\nconst isPending = computed(() => job.status === 'created')\nconst isCancelled = computed(() => isDownloadCancelled(job.status))\n</script>\n\n<template>\n  <div\n    class=\"flex items-center justify-between rounded-lg bg-modal-card-background px-4 py-3\"\n  >\n    <div :class=\"cn('min-w-0 flex-1', isCompleted && 'opacity-50')\">\n      <span class=\"block truncate text-sm text-base-foreground\">{{\n        job.assetName\n      }}</span>\n    </div>\n\n    <div class=\"flex shrink-0 items-center gap-2\">\n      <template v-if=\"isFailed\">\n        <i\n          class=\"icon-[lucide--circle-alert] size-4 text-destructive-background\"\n        />\n        <StatusBadge :label=\"t('progressToast.failed')\" severity=\"danger\" />\n      </template>\n\n      <template v-else-if=\"isCompleted\">\n        <StatusBadge :label=\"t('progressToast.finished')\" severity=\"contrast\" />\n      </template>\n\n      <template v-else-if=\"isCancelled\">\n        <StatusBadge\n          :label=\"t('electronFileDownload.cancelled')\"\n          severity=\"secondary\"\n        />\n      </template>\n\n      <template v-else-if=\"isRunning\">\n        <Loader size=\"sm\" class=\"text-base-foreground\" />\n        <span class=\"text-xs text-base-foreground\">\n          {{ progressPercent }}%\n        </span>\n      </template>\n\n      <template v-else-if=\"isPending\">\n        <span class=\"text-xs text-muted-foreground\">\n          {{ t('progressToast.pending') }}\n        </span>\n      </template>\n\n      <Button\n        v-if=\"isRunning || isPending\"\n        variant=\"muted-textonly\"\n        size=\"sm\"\n        :aria-label=\"t('electronFileDownload.cancel')\"\n        :disabled=\"isCancelling\"\n        @click=\"emit('cancel', job.taskId)\"\n      >\n        {{ t('g.cancel') }}\n      </Button>\n    </div>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { whenever } from '@vueuse/core'\nimport Popover from '@/components/common/ImperativePopover.vue'\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Loader from '@/components/loader/Loader.vue'\nimport ToastPanel from '@/components/ui/toast/ToastPanel.vue'\nimport ProgressToastItem from '@/components/toast/ProgressToastItem.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport type { TaskId } from '@/platform/tasks/services/taskService'\nimport {\n  isDownloadCancelled,\n  useAssetDownloadStore\n} from '@/stores/assetDownloadStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\nconst assetDownloadStore = useAssetDownloadStore()\nconst { toastErrorHandler } = useErrorHandling()\n\nconst visible = computed(() => assetDownloadStore.hasDownloads)\n\nconst isExpanded = ref(false)\nconst activeFilter = ref<'all' | 'completed' | 'failed'>('all')\nconst filterPopoverRef = ref<InstanceType<typeof Popover> | null>(null)\n\nwhenever(\n  () => !isExpanded.value,\n  () => filterPopoverRef.value?.hide()\n)\n\nconst filterOptions = [\n  { value: 'all', label: 'all' },\n  { value: 'completed', label: 'completed' },\n  { value: 'failed', label: 'failed' }\n] as const\n\nfunction onFilterClick(event: Event) {\n  filterPopoverRef.value?.toggle(event)\n}\n\nfunction setFilter(filter: typeof activeFilter.value) {\n  activeFilter.value = filter\n  filterPopoverRef.value?.hide()\n}\n\nconst downloadJobs = computed(() => assetDownloadStore.downloadList)\nconst completedJobs = computed(() =>\n  assetDownloadStore.finishedDownloads.filter((d) => d.status === 'completed')\n)\nconst failedJobs = computed(() =>\n  assetDownloadStore.finishedDownloads.filter((d) => d.status === 'failed')\n)\nconst cancelledJobs = computed(() =>\n  assetDownloadStore.downloadList.filter((download) =>\n    isDownloadCancelled(download.status)\n  )\n)\n\nconst isInProgress = computed(() => assetDownloadStore.hasActiveDownloads)\nconst currentJobName = computed(() => {\n  const activeJob = downloadJobs.value.find((job) => job.status === 'running')\n  return activeJob?.assetName || t('progressToast.downloadingModel')\n})\n\nconst outcomeLabel = computed(() => {\n  if (failedJobs.value.length > 0)\n    return t('progressToast.downloadsFailed', {\n      count: failedJobs.value.length\n    })\n  if (cancelledJobs.value.length > 0) return t('electronFileDownload.cancelled')\n  return t('progressToast.allDownloadsCompleted')\n})\n\nconst announcement = computed(() =>\n  isInProgress.value ? t('progressToast.importingModels') : outcomeLabel.value\n)\n\nconst completedCount = computed(\n  () =>\n    completedJobs.value.length +\n    failedJobs.value.length +\n    cancelledJobs.value.length\n)\nconst totalCount = computed(() => downloadJobs.value.length)\n\nconst filteredJobs = computed(() => {\n  switch (activeFilter.value) {\n    case 'completed':\n      return completedJobs.value\n    case 'failed':\n      return failedJobs.value\n    default:\n      return downloadJobs.value\n  }\n})\n\nconst activeFilterLabel = computed(() => {\n  const option = filterOptions.find((f) => f.value === activeFilter.value)\n  return option\n    ? t(`progressToast.filter.${option.label}`)\n    : t('progressToast.filter.all')\n})\n\nfunction closeDialog() {\n  assetDownloadStore.clearDismissibleDownloads()\n  isExpanded.value = false\n}\n\nasync function cancelDownload(taskId: TaskId) {\n  const result = await assetDownloadStore.cancelDownload(taskId)\n  if (result.ok) return\n\n  reportError(result.error, {\n    surface: 'assets',\n    errorType: 'asset_download_cancellation_failure',\n    logToConsole: false\n  })\n  toastErrorHandler(result.error)\n}\n</script>\n\n<template>\n  <ToastPanel v-model:expanded=\"isExpanded\" :visible :announcement>\n    <template #default>\n      <div\n        class=\"flex h-12 items-center justify-between border-b border-border-default px-4\"\n      >\n        <h3 class=\"text-sm font-bold text-base-foreground\">\n          {{ t('progressToast.importingModels') }}\n        </h3>\n        <div class=\"flex items-center gap-2\">\n          <Button\n            variant=\"secondary\"\n            size=\"md\"\n            class=\"gap-1.5 px-2\"\n            @click=\"onFilterClick\"\n          >\n            <i class=\"icon-[lucide--list-filter] size-4\" />\n            <span>{{ activeFilterLabel }}</span>\n            <i class=\"icon-[lucide--chevron-down] size-3\" />\n          </Button>\n          <Popover\n            ref=\"filterPopoverRef\"\n            align=\"end\"\n            content-class=\"border-none bg-transparent p-0 pt-2\"\n          >\n            <div\n              class=\"flex min-w-30 flex-col items-stretch rounded-lg border border-interface-stroke bg-interface-panel-surface px-2 py-3\"\n            >\n              <Button\n                v-for=\"option in filterOptions\"\n                :key=\"option.value\"\n                variant=\"textonly\"\n                size=\"sm\"\n                :class=\"\n                  cn(\n                    'w-full justify-start bg-transparent',\n                    activeFilter === option.value &&\n                      'bg-secondary-background-selected'\n                  )\n                \"\n                @click=\"setFilter(option.value)\"\n              >\n                {{ t(`progressToast.filter.${option.label}`) }}\n              </Button>\n            </div>\n          </Popover>\n        </div>\n      </div>\n\n      <div class=\"relative max-h-75 overflow-y-auto p-4\">\n        <div\n          v-if=\"filteredJobs.length > 3\"\n          class=\"absolute top-4 right-1 h-12 w-1 rounded-full bg-muted-foreground\"\n        />\n\n        <div class=\"flex flex-col gap-2\">\n          <ProgressToastItem\n            v-for=\"job in filteredJobs\"\n            :key=\"job.taskId\"\n            :job=\"job\"\n            :is-cancelling=\"\n              assetDownloadStore.cancellingTaskIds.has(job.taskId)\n            \"\n            @cancel=\"cancelDownload\"\n          />\n        </div>\n\n        <div\n          v-if=\"filteredJobs.length === 0\"\n          class=\"flex flex-col items-center justify-center py-6 text-center\"\n        >\n          <span class=\"text-sm text-muted-foreground\">\n            {{\n              t('progressToast.noImportsInQueue', {\n                filter: activeFilterLabel\n              })\n            }}\n          </span>\n        </div>\n      </div>\n    </template>\n\n    <template #footer=\"{ toggle }\">\n      <div\n        class=\"flex h-12 items-center justify-between gap-2 border-t border-border-default px-4\"\n      >\n        <div class=\"flex min-w-0 flex-1 items-center gap-2 text-sm\">\n          <template v-if=\"isInProgress\">\n            <Loader size=\"sm\" class=\"shrink-0 text-muted-foreground\" />\n            <span\n              class=\"min-w-0 flex-1 truncate font-bold text-base-foreground\"\n            >\n              {{ currentJobName }}\n            </span>\n          </template>\n          <template v-else-if=\"failedJobs.length > 0\">\n            <i\n              class=\"icon-[lucide--circle-alert] size-4 shrink-0 text-destructive-background\"\n            />\n            <span class=\"min-w-0 truncate font-bold text-base-foreground\">\n              {{ outcomeLabel }}\n            </span>\n          </template>\n          <template v-else-if=\"cancelledJobs.length > 0\">\n            <i\n              class=\"icon-[lucide--circle-x] size-4 shrink-0 text-muted-foreground\"\n            />\n            <span class=\"min-w-0 truncate font-bold text-base-foreground\">\n              {{ outcomeLabel }}\n            </span>\n          </template>\n          <template v-else>\n            <i\n              class=\"icon-[lucide--check-circle] size-4 shrink-0 text-jade-600\"\n            />\n            <span class=\"min-w-0 truncate font-bold text-base-foreground\">\n              {{ outcomeLabel }}\n            </span>\n          </template>\n        </div>\n\n        <div class=\"flex shrink-0 items-center gap-2\">\n          <span\n            v-if=\"isInProgress\"\n            class=\"text-sm whitespace-nowrap text-muted-foreground\"\n          >\n            {{\n              t('progressToast.progressCount', {\n                completed: completedCount,\n                total: totalCount\n              })\n            }}\n          </span>\n\n          <div class=\"flex items-center\">\n            <Button\n              variant=\"muted-textonly\"\n              size=\"icon\"\n              :aria-label=\"\n                isExpanded ? t('contextMenu.Collapse') : t('contextMenu.Expand')\n              \"\n              @click.stop=\"toggle\"\n            >\n              <i\n                :class=\"\n                  cn(\n                    'size-4',\n                    isExpanded\n                      ? 'icon-[lucide--chevron-down]'\n                      : 'icon-[lucide--chevron-up]'\n                  )\n                \"\n              />\n            </Button>\n\n            <Button\n              v-if=\"!isInProgress\"\n              variant=\"muted-textonly\"\n              size=\"icon\"\n              :aria-label=\"t('g.close')\"\n              @click.stop=\"closeDialog\"\n            >\n              <i class=\"icon-[lucide--x] size-4\" />\n            </Button>\n          </div>\n        </div>\n      </div>\n    </template>\n  </ToastPanel>\n</template>\n","<script setup lang=\"ts\">\nimport { onMounted, onUnmounted } from 'vue'\n\nimport { isDesktop } from '@/platform/distribution/types'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { useCloudNotificationDialog } from '@/platform/cloud/notification/composables/useCloudNotificationDialog'\nimport { electronAPI } from '@/utils/envUtil'\n\nconst settingStore = useSettingStore()\nconst { showCloudNotification } = useCloudNotificationDialog()\n\nlet isDisposed = false\nlet cloudNotificationTimer: ReturnType<typeof setTimeout> | undefined\n\nfunction reportNotificationFailure(\n  errorType:\n    | 'cloud_notification_state_save_failed'\n    | 'cloud_notification_show_failed'\n    | 'cloud_notification_state_reset_failed',\n  operation: 'save' | 'render',\n  cause: unknown,\n  platform: string\n) {\n  reportError(cause, {\n    surface: 'platform',\n    errorType,\n    tags: {\n      failure_kind: 'caught_unexpected',\n      feature_area: 'cloud',\n      operation,\n      outcome: 'failed',\n      assert_mode: 'soft'\n    },\n    context: { platform, is_disposed: isDisposed },\n    level: 'error'\n  })\n}\n\nasync function resetNotificationState(platform: string) {\n  try {\n    await settingStore.set('Comfy.Desktop.CloudNotificationShown', false)\n  } catch (error) {\n    reportNotificationFailure(\n      'cloud_notification_state_reset_failed',\n      'save',\n      error,\n      platform\n    )\n  }\n}\n\nasync function scheduleCloudNotification() {\n  const platform = electronAPI()?.getPlatform()\n  if (!isDesktop || platform !== 'darwin') return\n\n  await settingStore.load()\n  if (settingStore.error !== undefined) return\n  if (isDisposed) return\n  if (settingStore.get('Comfy.Desktop.CloudNotificationShown')) return\n\n  cloudNotificationTimer = setTimeout(async () => {\n    if (isDisposed) return\n\n    try {\n      await settingStore.set('Comfy.Desktop.CloudNotificationShown', true)\n    } catch (error) {\n      reportNotificationFailure(\n        'cloud_notification_state_save_failed',\n        'save',\n        error,\n        platform\n      )\n      await resetNotificationState(platform)\n      return\n    }\n\n    if (isDisposed) {\n      await resetNotificationState(platform)\n      return\n    }\n\n    try {\n      await showCloudNotification()\n    } catch (error) {\n      reportNotificationFailure(\n        'cloud_notification_show_failed',\n        'render',\n        error,\n        platform\n      )\n      await resetNotificationState(platform)\n    }\n  }, 2000)\n}\n\nonMounted(() => {\n  void scheduleCloudNotification()\n})\n\nonUnmounted(() => {\n  isDisposed = true\n  if (cloudNotificationTimer) clearTimeout(cloudNotificationTimer)\n})\n</script>\n","<template>\n  <div class=\"flex min-w-0 flex-1 items-center gap-3\">\n    <template v-if=\"!collapsed && workspaceName\">\n      <WorkspaceProfilePic\n        :workspace-name=\"workspaceName\"\n        :subscription-tier=\"subscriptionTier\"\n      />\n      <h1\n        class=\"m-0 truncate text-base font-bold text-base-foreground select-none\"\n      >\n        {{ workspaceName }}\n      </h1>\n    </template>\n    <div id=\"settings-header-controls\" class=\"contents\" />\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport WorkspaceProfilePic from '@/platform/workspace/components/WorkspaceProfilePic.vue'\nimport type { SubscriptionTier } from '@/platform/workspace/api/workspaceApi'\n\nconst {\n  workspaceName,\n  subscriptionTier = null,\n  collapsed = false\n} = defineProps<{\n  workspaceName: string\n  subscriptionTier?: SubscriptionTier | null\n  collapsed?: boolean\n}>()\n</script>\n","<!-- A message that displays the current user -->\n<template>\n  <Message\n    v-if=\"userStore.isMultiUserServer\"\n    severity=\"info\"\n    data-testid=\"current-user-indicator\"\n  >\n    <template #icon>\n      <i class=\"pi pi-user\" />\n    </template>\n    <div class=\"flex items-center justify-between\">\n      <div class=\"tabular-nums\">\n        {{ $t('g.currentUser') }}: {{ userStore.currentUser?.username }}\n      </div>\n      <Button\n        class=\"text-inherit\"\n        variant=\"textonly\"\n        size=\"icon\"\n        :aria-label=\"$t('menuLabels.Sign Out')\"\n        @click=\"logout\"\n      >\n        <i class=\"pi pi-sign-out\" />\n      </Button>\n    </div>\n  </Message>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport { useUserStore } from '@/stores/userStore'\n\nconst userStore = useUserStore()\nconst logout = async () => {\n  await userStore.logout()\n  window.location.reload()\n}\n</script>\n","<template>\n  <Message severity=\"info\">\n    <template #icon>\n      <i class=\"pi pi-palette\" />\n    </template>\n    <div class=\"flex items-center justify-between\">\n      <div>\n        {{ $t('settingsCategories.ColorPalette') }}\n      </div>\n      <div class=\"actions\">\n        <SingleSelect\n          v-model=\"activePaletteId\"\n          class=\"w-44\"\n          :options=\"paletteOptions\"\n        />\n        <Button\n          size=\"icon\"\n          variant=\"textonly\"\n          :title=\"$t('g.export')\"\n          @click=\"colorPaletteService.exportColorPalette(activePaletteId)\"\n        >\n          <i class=\"pi pi-file-export\" />\n        </Button>\n        <Button\n          size=\"icon\"\n          variant=\"textonly\"\n          :title=\"$t('g.import')\"\n          @click=\"importCustomPalette\"\n        >\n          <i class=\"pi pi-file-import\" />\n        </Button>\n        <Button\n          size=\"icon\"\n          variant=\"destructive-textonly\"\n          :title=\"$t('g.delete')\"\n          :disabled=\"!colorPaletteStore.isCustomPalette(activePaletteId)\"\n          @click=\"colorPaletteService.deleteCustomColorPalette(activePaletteId)\"\n        >\n          <i class=\"pi pi-trash\" />\n        </Button>\n      </div>\n    </div>\n  </Message>\n</template>\n\n<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport { computed } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Message from '@/components/ui/message/Message.vue'\nimport SingleSelect from '@/components/ui/single-select/SingleSelect.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useColorPaletteService } from '@/services/colorPaletteService'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\n\nconst settingStore = useSettingStore()\nconst colorPaletteStore = useColorPaletteStore()\nconst colorPaletteService = useColorPaletteService()\nconst { palettes, activePaletteId } = storeToRefs(colorPaletteStore)\nconst paletteOptions = computed(() =>\n  palettes.value.map(({ id, name }) => ({ name, value: id }))\n)\n\nconst importCustomPalette = async () => {\n  const palette = await colorPaletteService.importColorPalette()\n  if (palette) {\n    await settingStore.set('Comfy.ColorPalette', palette.id)\n  }\n}\n</script>\n","<template>\n  <FormItem\n    :id=\"setting.id\"\n    :item=\"formItem\"\n    :form-value=\"settingValue\"\n    @update:form-value=\"updateSettingValue\"\n  >\n    <template #name-prefix>\n      <Badge\n        v-if=\"setting.id === 'Comfy.Locale'\"\n        severity=\"primary\"\n        class=\"pi pi-language\"\n      />\n      <Tooltip v-if=\"setting.experimental\">\n        <TooltipTrigger as-child>\n          <Badge severity=\"primary\">\n            <template #icon>\n              <i-material-symbols:experiment-outline />\n            </template>\n          </Badge>\n        </TooltipTrigger>\n        <TooltipContent>{{ $t('g.experimental') }}</TooltipContent>\n      </Tooltip>\n    </template>\n  </FormItem>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport FormItem from '@/components/common/FormItem.vue'\nimport Badge from '@/components/ui/badge/Badge.vue'\nimport Tooltip from '@/components/ui/tooltip/Tooltip.vue'\nimport TooltipContent from '@/components/ui/tooltip/TooltipContent.vue'\nimport TooltipTrigger from '@/components/ui/tooltip/TooltipTrigger.vue'\nimport { st } from '@/i18n'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport type {\n  SettingOption,\n  SettingParams,\n  Settings\n} from '@/platform/settings/types'\nimport { normalizeI18nKey } from '@/utils/formatUtil'\n\nconst props = defineProps<{\n  setting: SettingParams\n}>()\n\nconst { t } = useI18n()\n\nfunction translateOptions(\n  options:\n    | (SettingOption | string)[]\n    | ((value: unknown) => (SettingOption | string)[])\n) {\n  if (typeof options === 'function') {\n    return translateOptions(options(settingValue.value))\n  }\n\n  return options.map((option) => {\n    const optionLabel = typeof option === 'string' ? option : option.text\n    const optionValue = typeof option === 'string' ? option : option.value\n\n    return {\n      text: t(\n        `settings.${normalizeI18nKey(props.setting.id)}.options.${normalizeI18nKey(optionLabel)}`,\n        optionLabel\n      ),\n      value: optionValue\n    }\n  })\n}\n\nconst formItem = computed(() => {\n  const normalizedId = normalizeI18nKey(props.setting.id)\n  return {\n    ...props.setting,\n    name: t(`settings.${normalizedId}.name`, props.setting.name),\n    tooltip: props.setting.tooltip\n      ? st(`settings.${normalizedId}.tooltip`, props.setting.tooltip)\n      : undefined,\n    options: props.setting.options\n      ? translateOptions(props.setting.options)\n      : undefined\n  }\n})\n\nconst settingStore = useSettingStore()\nconst settingValue = computed(() => settingStore.get(props.setting.id))\nasync function updateSettingValue(newValue: unknown) {\n  await settingStore.set(\n    props.setting.id,\n    newValue as Settings[typeof props.setting.id]\n  )\n}\n</script>\n","<template>\n  <div class=\"setting-group\">\n    <div v-if=\"divider\" class=\"my-8 border-t border-border-default\" />\n    <h3 class=\"text-base\">\n      <span v-if=\"group.category\" class=\"text-muted\">\n        {{\n          $t(\n            `settingsCategories.${normalizeI18nKey(group.category)}`,\n            group.category\n          )\n        }}\n        &#8250;\n      </span>\n      {{\n        $t(`settingsCategories.${normalizeI18nKey(group.label)}`, group.label)\n      }}\n    </h3>\n    <div\n      v-for=\"setting in group.settings.filter((s) => !s.deprecated)\"\n      :key=\"setting.id\"\n      :data-setting-id=\"setting.id\"\n      class=\"setting-item mb-3\"\n    >\n      <SettingItem :setting=\"setting\" />\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport SettingItem from '@/platform/settings/components/SettingItem.vue'\nimport type { SettingParams } from '@/platform/settings/types'\nimport { normalizeI18nKey } from '@/utils/formatUtil'\n\ndefineProps<{\n  group: {\n    label: string\n    category?: string\n    settings: SettingParams[]\n  }\n  divider?: boolean\n}>()\n</script>\n","<template>\n  <div v-if=\"props.settingGroups.length > 0\">\n    <SettingGroup\n      v-for=\"(group, i) in props.settingGroups\"\n      :key=\"group.label\"\n      :divider=\"i !== 0\"\n      :group=\"group\"\n    />\n  </div>\n  <NoResultsPlaceholder\n    v-else\n    icon=\"pi pi-search\"\n    :title=\"$t('g.noResultsFound')\"\n    :message=\"$t('g.searchFailedMessage')\"\n  />\n</template>\n\n<script setup lang=\"ts\">\nimport NoResultsPlaceholder from '@/components/common/NoResultsPlaceholder.vue'\nimport SettingGroup from '@/platform/settings/components/SettingGroup.vue'\nimport type { ISettingGroup } from '@/platform/settings/types'\n\nconst props = defineProps<{\n  settingGroups: ISettingGroup[]\n}>()\n</script>\n","import { computed, ref, watch } from 'vue'\n\nimport { st } from '@/i18n'\nimport {\n  getSettingInfo,\n  useSettingStore\n} from '@/platform/settings/settingStore'\nimport type { ISettingGroup, SettingParams } from '@/platform/settings/types'\nimport type { TreeNode } from '@/types/treeExplorerTypes'\nimport { normalizeI18nKey } from '@/utils/formatUtil'\nimport { useVueFeatureFlags } from '@/composables/useVueFeatureFlags'\n\nexport type SettingTreeNode = TreeNode<SettingParams>\n\ninterface SearchableNavItem {\n  key: string\n  label: string\n}\n\nexport function useSettingSearch() {\n  const settingStore = useSettingStore()\n  const { shouldRenderVueNodes } = useVueFeatureFlags()\n\n  const searchQuery = ref<string>('')\n  const filteredSettingIds = ref<string[]>([])\n  const matchedNavItemKeys = ref<Set<string>>(new Set())\n  const searchInProgress = ref<boolean>(false)\n\n  watch(searchQuery, () => (searchInProgress.value = true))\n\n  /**\n   * Settings categories that contains at least one setting in search results.\n   */\n  const searchResultsCategories = computed<Set<string>>(() => {\n    return new Set(\n      filteredSettingIds.value.map(\n        (id) => getSettingInfo(settingStore.settingsById[id]).category\n      )\n    )\n  })\n\n  /**\n   * Check if the search query is empty\n   */\n  const queryIsEmpty = computed(() => searchQuery.value.length === 0)\n\n  /**\n   * Check if we're in search mode\n   */\n  const inSearch = computed(\n    () => !queryIsEmpty.value && !searchInProgress.value\n  )\n\n  /**\n   * Handle search functionality\n   */\n  const handleSearch = (query: string, navItems?: SearchableNavItem[]) => {\n    matchedNavItemKeys.value = new Set()\n\n    if (!query) {\n      filteredSettingIds.value = []\n      return\n    }\n\n    const queryLower = query.toLocaleLowerCase()\n    const allSettings = Object.values(settingStore.settingsById)\n    const filteredSettings = allSettings.filter((setting) => {\n      // Filter out hidden and deprecated settings, just like in normal settings tree\n      if (\n        setting.type === 'hidden' ||\n        setting.deprecated ||\n        (shouldRenderVueNodes.value && setting.hideInVueNodes)\n      ) {\n        return false\n      }\n\n      const idLower = setting.id.toLowerCase()\n      const nameLower = setting.name.toLowerCase()\n      const translatedName = st(\n        `settings.${normalizeI18nKey(setting.id)}.name`,\n        setting.name\n      ).toLocaleLowerCase()\n      const info = getSettingInfo(setting)\n      const translatedCategory = st(\n        `settingsCategories.${normalizeI18nKey(info.category)}`,\n        info.category\n      ).toLocaleLowerCase()\n      const translatedSubCategory = st(\n        `settingsCategories.${normalizeI18nKey(info.subCategory)}`,\n        info.subCategory\n      ).toLocaleLowerCase()\n\n      return (\n        idLower.includes(queryLower) ||\n        nameLower.includes(queryLower) ||\n        translatedName.includes(queryLower) ||\n        translatedCategory.includes(queryLower) ||\n        translatedSubCategory.includes(queryLower)\n      )\n    })\n\n    if (navItems) {\n      for (const item of navItems) {\n        if (\n          item.key.toLocaleLowerCase().includes(queryLower) ||\n          item.label.toLocaleLowerCase().includes(queryLower)\n        ) {\n          matchedNavItemKeys.value.add(item.key)\n        }\n      }\n    }\n\n    filteredSettingIds.value = filteredSettings.map((x) => x.id)\n    searchInProgress.value = false\n  }\n\n  /**\n   * Get search results grouped by category\n   */\n  const getSearchResults = (\n    activeCategory: SettingTreeNode | null\n  ): ISettingGroup[] => {\n    const groupedSettings = new Map<\n      string,\n      { category: string; settings: SettingParams[] }\n    >()\n\n    filteredSettingIds.value.forEach((id) => {\n      const setting = settingStore.settingsById[id]\n      const info = getSettingInfo(setting)\n      const groupKey =\n        activeCategory === null\n          ? `${info.category}/${info.subCategory}`\n          : info.subCategory\n\n      if (activeCategory === null || activeCategory.label === info.category) {\n        let group = groupedSettings.get(groupKey)\n        if (!group) {\n          group = {\n            category: info.category,\n            settings: []\n          }\n          groupedSettings.set(groupKey, group)\n        }\n        group.settings.push(setting)\n      }\n    })\n\n    return [...groupedSettings].map(([key, { category, settings }]) => ({\n      label: activeCategory === null ? key.split('/')[1] : key,\n      ...(activeCategory === null ? { category } : {}),\n      settings\n    }))\n  }\n\n  return {\n    searchQuery,\n    filteredSettingIds,\n    matchedNavItemKeys,\n    searchInProgress,\n    searchResultsCategories,\n    queryIsEmpty,\n    inSearch,\n    handleSearch,\n    getSearchResults\n  }\n}\n","import { computed, defineAsyncComponent, onMounted, ref } from 'vue'\nimport type { Component } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { useFeatureFlags } from '@/composables/useFeatureFlags'\nimport { useVueFeatureFlags } from '@/composables/useVueFeatureFlags'\nimport { isCloud, isDesktop } from '@/platform/distribution/types'\nimport {\n  getSettingInfo,\n  useSettingStore\n} from '@/platform/settings/settingStore'\nimport type { SettingTreeNode } from '@/platform/settings/composables/useSettingSearch'\nimport type { SettingPanelType, SettingParams } from '@/platform/settings/types'\nimport { useWorkspaceUI } from '@/platform/workspace/composables/useWorkspaceUI'\nimport { usePartnerNodeGovernanceStore } from '@/platform/workspace/stores/partnerNodeGovernanceStore'\nimport { useSkillPacksStore } from '@/platform/skills/stores/skillPacksStore'\nimport type { NavGroupData } from '@/types/navTypes'\nimport { normalizeI18nKey } from '@/utils/formatUtil'\nimport { buildTree } from '@/utils/treeUtil'\n\nconst CATEGORY_ICONS: Record<string, string> = {\n  '3D': 'icon-[lucide--box]',\n  about: 'icon-[lucide--info]',\n  Appearance: 'icon-[lucide--palette]',\n  Comfy: 'icon-[lucide--settings]',\n  credits: 'icon-[lucide--coins]',\n  extension: 'icon-[lucide--puzzle]',\n  keybinding: 'icon-[lucide--keyboard]',\n  LiteGraph: 'icon-[lucide--workflow]',\n  'Mask Editor': 'icon-[lucide--pen-tool]',\n  Members: 'icon-[lucide--users]',\n  Other: 'icon-[lucide--ellipsis]',\n  PlanCredits: 'icon-[lucide--receipt-text]',\n  secrets: 'icon-[lucide--key-round]',\n  'skill-packs': 'icon-[lucide--book-open-text]',\n  'server-config': 'icon-[lucide--server]',\n  user: 'icon-[lucide--user]',\n  workspace: 'icon-[lucide--building-2]',\n  'workspace-allowlist': 'icon-[comfy--ai-model]',\n  'workspace-members': 'icon-[lucide--users]'\n}\n\ninterface SettingPanelItem {\n  node: SettingTreeNode\n  component: Component\n  props?: Record<string, unknown>\n}\n\nexport function useSettingUI(\n  defaultPanel?: SettingPanelType,\n  scrollToSettingId?: string\n) {\n  const { t } = useI18n()\n  const { isLoggedIn } = useCurrentUser()\n  const settingStore = useSettingStore()\n  const activeCategory = ref<SettingTreeNode | null>(null)\n\n  const { flags } = useFeatureFlags()\n  const { shouldRenderVueNodes } = useVueFeatureFlags()\n  const { workspaceRole } = useWorkspaceUI()\n  const governanceStore = usePartnerNodeGovernanceStore()\n  const skillPacksStore = useSkillPacksStore()\n\n  const settingRoot = computed<SettingTreeNode>(() => {\n    const root = buildTree(\n      Object.values(settingStore.settingsById).filter(\n        (setting: SettingParams) =>\n          setting.type !== 'hidden' &&\n          !(shouldRenderVueNodes.value && setting.hideInVueNodes)\n      ),\n      (setting: SettingParams) => setting.category || setting.id.split('.')\n    )\n\n    const floatingSettings = (root.children ?? []).filter((node) => node.leaf)\n    if (floatingSettings.length) {\n      root.children = (root.children ?? []).filter((node) => !node.leaf)\n      root.children.push({\n        key: 'Other',\n        label: 'Other',\n        leaf: false,\n        children: floatingSettings\n      })\n    }\n\n    return root\n  })\n\n  const settingCategories = computed<SettingTreeNode[]>(\n    () => settingRoot.value.children ?? []\n  )\n\n  // Core setting categories (built-in to ComfyUI) in display order\n  // 'Other' includes floating settings that don't have a specific category\n  const CORE_CATEGORIES_ORDER = [\n    'Comfy',\n    'LiteGraph',\n    'Appearance',\n    '3D',\n    'Mask Editor',\n    'Other'\n  ]\n  const CORE_CATEGORIES = new Set(CORE_CATEGORIES_ORDER)\n\n  const coreSettingCategories = computed<SettingTreeNode[]>(() => {\n    const categories = settingCategories.value.filter((node) =>\n      CORE_CATEGORIES.has(node.label)\n    )\n    return categories.sort(\n      (a, b) =>\n        CORE_CATEGORIES_ORDER.indexOf(a.label) -\n        CORE_CATEGORIES_ORDER.indexOf(b.label)\n    )\n  })\n\n  const customNodeSettingCategories = computed<SettingTreeNode[]>(() =>\n    settingCategories.value.filter((node) => !CORE_CATEGORIES.has(node.label))\n  )\n\n  // Define panel items\n  const aboutPanel: SettingPanelItem = {\n    node: {\n      key: 'about',\n      label: 'About',\n      children: []\n    },\n    component: defineAsyncComponent(\n      () => import('@/components/dialog/content/setting/AboutPanel.vue')\n    )\n  }\n\n  const creditsPanel: SettingPanelItem = {\n    node: {\n      key: 'credits',\n      label: 'Credits',\n      children: []\n    },\n    component: defineAsyncComponent(\n      () => import('@/components/dialog/content/setting/CreditsPanel.vue')\n    )\n  }\n\n  const userPanel: SettingPanelItem = {\n    node: {\n      key: 'user',\n      label: 'User',\n      children: []\n    },\n    component: defineAsyncComponent(\n      () => import('@/components/dialog/content/setting/UserPanel.vue')\n    )\n  }\n\n  const workspaceSettingsPanelComponent = defineAsyncComponent(\n    () =>\n      import('@/platform/workspace/components/dialogs/settings/WorkspaceSettingsPanelContent.vue')\n  )\n\n  const planCreditsPanel: SettingPanelItem = {\n    node: {\n      key: 'workspace',\n      label: 'PlanCredits',\n      children: []\n    },\n    component: workspaceSettingsPanelComponent,\n    props: { section: 'planCredits' }\n  }\n\n  const membersPanel: SettingPanelItem = {\n    node: {\n      key: 'workspace-members',\n      label: 'Members',\n      children: []\n    },\n    component: workspaceSettingsPanelComponent,\n    props: { section: 'members' }\n  }\n\n  const allowlistPanel: SettingPanelItem = {\n    node: {\n      key: 'workspace-allowlist',\n      label: 'Allowlist',\n      children: []\n    },\n    component: workspaceSettingsPanelComponent,\n    props: { section: 'allowlist' }\n  }\n\n  const shouldShowWorkspacePanel = computed(() => isLoggedIn.value)\n  const shouldShowWorkspaceAllowlist = computed(\n    () =>\n      isCloud &&\n      shouldShowWorkspacePanel.value &&\n      flags.partnerNodeGovernanceEnabled &&\n      workspaceRole.value === 'owner'\n  )\n\n  const visibleWorkspacePanels = computed<SettingPanelItem[]>(() => {\n    if (!shouldShowWorkspacePanel.value) return []\n    const workspacePanels = isCloud\n      ? [planCreditsPanel, membersPanel]\n      : [planCreditsPanel]\n    return shouldShowWorkspaceAllowlist.value\n      ? [...workspacePanels, allowlistPanel]\n      : workspacePanels\n  })\n\n  const secretsPanel: SettingPanelItem = {\n    node: {\n      key: 'secrets',\n      label: 'Secrets',\n      children: []\n    },\n    component: defineAsyncComponent(\n      () => import('@/platform/secrets/components/SecretsPanel.vue')\n    )\n  }\n\n  const shouldShowSecretsPanel = computed(\n    () => flags.userSecretsEnabled && isLoggedIn.value\n  )\n\n  const skillPacksPanel: SettingPanelItem = {\n    node: {\n      key: 'skill-packs',\n      label: 'SkillPacks',\n      children: []\n    },\n    component: defineAsyncComponent(\n      () => import('@/platform/skills/components/SkillPacksPanel.vue')\n    )\n  }\n\n  // Both cohort flags plus a runtime check that the routes have not 404'd.\n  const shouldShowSkillPacksPanel = computed(\n    () => skillPacksStore.enabled && isLoggedIn.value\n  )\n\n  const keybindingPanel: SettingPanelItem = {\n    node: {\n      key: 'keybinding',\n      label: 'Keybinding',\n      children: []\n    },\n    component: defineAsyncComponent(\n      () => import('@/components/dialog/content/setting/KeybindingPanel.vue')\n    )\n  }\n\n  const extensionPanel: SettingPanelItem = {\n    node: {\n      key: 'extension',\n      label: 'Extension',\n      children: []\n    },\n    component: defineAsyncComponent(\n      () => import('@/platform/settings/components/ExtensionPanel.vue')\n    )\n  }\n\n  const serverConfigPanel: SettingPanelItem = {\n    node: {\n      key: 'server-config',\n      label: 'Server-Config',\n      children: []\n    },\n    component: defineAsyncComponent(\n      () => import('@/platform/settings/components/ServerConfigPanel.vue')\n    )\n  }\n\n  const panels = computed<SettingPanelItem[]>(() => [\n    aboutPanel,\n    creditsPanel,\n    userPanel,\n    ...visibleWorkspacePanels.value,\n    keybindingPanel,\n    extensionPanel,\n    ...(isDesktop ? [serverConfigPanel] : []),\n    ...(shouldShowSecretsPanel.value ? [secretsPanel] : []),\n    ...(shouldShowSkillPacksPanel.value ? [skillPacksPanel] : [])\n  ])\n\n  /**\n   * The default category to show when the dialog is opened.\n   */\n  const defaultCategory = computed<SettingTreeNode>(() => {\n    if (defaultPanel) {\n      for (const group of groupedMenuTreeNodes.value) {\n        const found = group.children?.find((node) => node.key === defaultPanel)\n        if (found) return found\n      }\n      const hiddenPanel = panels.value.find(\n        (panel) => panel.node.key === defaultPanel\n      )\n      if (hiddenPanel) return translateCategory(hiddenPanel.node)\n      return settingCategories.value[0]\n    }\n\n    if (scrollToSettingId) {\n      if (Object.hasOwn(settingStore.settingsById, scrollToSettingId)) {\n        const setting = settingStore.settingsById[scrollToSettingId]\n        const { category } = getSettingInfo(setting)\n        const found = settingCategories.value.find((c) => c.label === category)\n        if (found) return found\n      }\n    }\n\n    return settingCategories.value[0]\n  })\n\n  const translateCategory = (node: SettingTreeNode) => ({\n    ...node,\n    translatedLabel: t(\n      `settingsCategories.${normalizeI18nKey(node.label)}`,\n      node.label\n    )\n  })\n\n  const workspaceMenuTreeNodes = computed<SettingTreeNode[]>(() => [\n    translateCategory({\n      key: 'workspace',\n      label: 'Workspace',\n      children: visibleWorkspacePanels.value\n        .map((panel) => panel.node)\n        .map(translateCategory)\n    }),\n    translateCategory({\n      key: 'general',\n      label: 'General',\n      children: [\n        translateCategory(userPanel.node),\n        ...coreSettingCategories.value.slice(0, 1).map(translateCategory),\n        ...(shouldShowSecretsPanel.value\n          ? [translateCategory(secretsPanel.node)]\n          : []),\n        ...(shouldShowSkillPacksPanel.value\n          ? [translateCategory(skillPacksPanel.node)]\n          : []),\n        ...coreSettingCategories.value.slice(1).map(translateCategory),\n        translateCategory(keybindingPanel.node),\n        translateCategory(extensionPanel.node),\n        translateCategory(aboutPanel.node),\n        ...(isDesktop ? [translateCategory(serverConfigPanel.node)] : [])\n      ]\n    }),\n    ...(customNodeSettingCategories.value.length > 0\n      ? [\n          translateCategory({\n            key: 'other',\n            label: 'Other',\n            children: customNodeSettingCategories.value.map(translateCategory)\n          })\n        ]\n      : [])\n  ])\n\n  const groupedMenuTreeNodes = workspaceMenuTreeNodes\n\n  const navGroups = computed<NavGroupData[]>(() =>\n    groupedMenuTreeNodes.value\n      .filter((group) => group.children?.length)\n      .map((group) => ({\n        title:\n          (group as SettingTreeNode & { translatedLabel?: string })\n            .translatedLabel ?? group.label,\n        items: (group.children ?? []).map((child) => ({\n          id: child.key,\n          label:\n            (child as SettingTreeNode & { translatedLabel?: string })\n              .translatedLabel ?? child.label,\n          icon:\n            child.key === 'workspace'\n              ? CATEGORY_ICONS.PlanCredits\n              : (CATEGORY_ICONS[child.key] ?? CATEGORY_ICONS[child.label]),\n          ...(child.key === 'workspace-allowlist' &&\n          governanceStore.status === 'ineligible' &&\n          governanceStore.providers.length > 0\n            ? { suffixIcon: 'icon-[lucide--crown]' }\n            : {})\n        }))\n      }))\n  )\n\n  function findCategoryByKey(key: string): SettingTreeNode | null {\n    for (const group of groupedMenuTreeNodes.value) {\n      const found = group.children?.find((node) => node.key === key)\n      if (found) return found\n    }\n    return null\n  }\n\n  function findPanelByKey(key: string): SettingPanelItem | null {\n    return panels.value.find((p) => p.node.key === key) ?? null\n  }\n\n  onMounted(() => {\n    activeCategory.value = defaultCategory.value\n    void skillPacksStore.startFlagGate()\n  })\n\n  return {\n    panels,\n    activeCategory,\n    defaultCategory,\n    groupedMenuTreeNodes,\n    settingCategories,\n    navGroups,\n    findCategoryByKey,\n    findPanelByKey\n  }\n}\n","<template>\n  <BaseModalLayout\n    content-title=\"\"\n    data-testid=\"settings-dialog\"\n    size=\"md\"\n    :content-padding=\"isWorkspaceCategoryActive ? 'none' : 'default'\"\n    header-padding=\"symmetric\"\n  >\n    <template #leftPanelHeaderTitle>\n      <i class=\"icon-[lucide--settings]\" />\n      <h2 class=\"text-base text-base-foreground\">{{ $t('g.settings') }}</h2>\n    </template>\n\n    <template #leftPanel>\n      <div class=\"px-3\">\n        <SearchInput\n          v-model:model-value=\"searchQuery\"\n          size=\"md\"\n          :placeholder=\"$t('g.searchSettings') + '...'\"\n          :debounce-time=\"128\"\n          :autofocus=\"activeCategoryKey !== 'keybinding'\"\n          @search=\"handleSearch\"\n        />\n      </div>\n\n      <nav\n        ref=\"navRef\"\n        class=\"flex scrollbar-hide flex-1 flex-col gap-1 overflow-y-auto px-3 py-4\"\n      >\n        <div\n          v-for=\"(group, index) in navGroups\"\n          :key=\"index\"\n          class=\"flex flex-col gap-2\"\n        >\n          <NavTitle :title=\"group.title\" />\n          <NavItem\n            v-for=\"item in group.items\"\n            :key=\"item.id\"\n            :data-nav-id=\"item.id\"\n            :icon=\"item.icon\"\n            :badge=\"item.badge\"\n            :suffix-icon=\"item.suffixIcon\"\n            :active=\"activeCategoryKey === item.id\"\n            @click=\"onNavItemClick(item.id)\"\n          >\n            {{ item.label }}\n          </NavItem>\n        </div>\n      </nav>\n    </template>\n\n    <template #header>\n      <div\n        v-if=\"activeCategoryKey === 'keybinding'\"\n        id=\"keybinding-panel-header\"\n        class=\"flex-1\"\n      />\n      <SettingsWorkspaceHeader\n        v-else-if=\"isWorkspaceCategoryActive\"\n        :workspace-name=\"workspaceName\"\n        :subscription-tier=\"activeWorkspace?.subscriptionTier\"\n        :collapsed=\"isHeaderCollapsed\"\n      />\n    </template>\n\n    <template #header-right-area>\n      <div\n        v-if=\"activeCategoryKey === 'keybinding'\"\n        id=\"keybinding-panel-actions\"\n      />\n    </template>\n\n    <template #content>\n      <div\n        :class=\"\n          cn(\n            'flex min-h-0 flex-1 flex-col',\n            isWorkspaceCategoryActive && 'px-6'\n          )\n        \"\n        @scroll.capture=\"handlePanelScroll\"\n      >\n        <template v-if=\"activePanel\">\n          <Suspense>\n            <component :is=\"activePanel.component\" v-bind=\"activePanel.props\" />\n            <template #fallback>\n              <div>\n                {{ $t('g.loadingPanel', { panel: activePanel.node.label }) }}\n              </div>\n            </template>\n          </Suspense>\n        </template>\n        <template v-else-if=\"inSearch\">\n          <SettingsPanel :setting-groups=\"searchResults\" />\n        </template>\n        <template v-else-if=\"activeSettingCategory\">\n          <CurrentUserMessage v-if=\"activeSettingCategory.label === 'Comfy'\" />\n          <ColorPaletteMessage\n            v-if=\"activeSettingCategory.label === 'Appearance'\"\n          />\n          <SettingsPanel\n            :setting-groups=\"sortedGroups(activeSettingCategory)\"\n          />\n        </template>\n      </div>\n    </template>\n  </BaseModalLayout>\n</template>\n\n<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport { computed, nextTick, onBeforeUnmount, provide, ref, watch } from 'vue'\n\nimport SearchInput from '@/components/ui/search-input/SearchInput.vue'\nimport SettingsWorkspaceHeader from '@/platform/settings/components/SettingsWorkspaceHeader.vue'\nimport CurrentUserMessage from '@/components/dialog/content/setting/CurrentUserMessage.vue'\nimport BaseModalLayout from '@/components/widget/layout/BaseModalLayout.vue'\nimport NavItem from '@/components/widget/nav/NavItem.vue'\nimport NavTitle from '@/components/widget/nav/NavTitle.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { useSettingsHeaderCollapse } from '@/platform/settings/composables/useSettingsHeaderCollapse'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useTeamWorkspaceStore } from '@/platform/workspace/stores/teamWorkspaceStore'\nimport ColorPaletteMessage from '@/platform/settings/components/ColorPaletteMessage.vue'\nimport SettingsPanel from '@/platform/settings/components/SettingsPanel.vue'\nimport { useSettingSearch } from '@/platform/settings/composables/useSettingSearch'\nimport { useSettingUI } from '@/platform/settings/composables/useSettingUI'\nimport { useSearchQueryTracking } from '@/platform/telemetry/searchQuery/useSearchQueryTracking'\nimport type { SettingTreeNode } from '@/platform/settings/composables/useSettingSearch'\nimport type {\n  ISettingGroup,\n  SettingDialogProps,\n  SettingParams\n} from '@/platform/settings/types'\nimport { OnCloseKey } from '@/types/widgetTypes'\nimport { flattenTree } from '@/utils/treeUtil'\n\nconst { onClose, defaultPanel, scrollToSettingId } =\n  defineProps<SettingDialogProps>()\n\nprovide(OnCloseKey, onClose)\n\nconst {\n  defaultCategory,\n  settingCategories,\n  navGroups,\n  findCategoryByKey,\n  findPanelByKey\n} = useSettingUI(defaultPanel, scrollToSettingId)\n\nconst {\n  searchQuery,\n  inSearch,\n  searchResultsCategories,\n  matchedNavItemKeys,\n  handleSearch: handleSearchBase,\n  getSearchResults\n} = useSettingSearch()\n\nconst { fetchBalance } = useBillingContext()\n\nconst navRef = ref<HTMLElement | null>(null)\nconst activeCategoryKey = ref<string | null>(defaultCategory.value?.key ?? null)\n\nconst WORKSPACE_CATEGORY_KEYS = new Set([\n  'workspace',\n  'workspace-members',\n  'workspace-allowlist'\n])\nconst isWorkspaceCategoryActive = computed(\n  () =>\n    activeCategoryKey.value !== null &&\n    WORKSPACE_CATEGORY_KEYS.has(activeCategoryKey.value)\n)\nconst { workspaceName, activeWorkspace } = storeToRefs(useTeamWorkspaceStore())\n\nconst { isHeaderCollapsed, handlePanelScroll, resetHeaderCollapse } =\n  useSettingsHeaderCollapse()\n\n// A panel change swaps the scroller out from under the collapse state, and the\n// state outlives the dialog, so a reopen would otherwise start collapsed.\nwatch(activeCategoryKey, resetHeaderCollapse)\nonBeforeUnmount(resetHeaderCollapse)\n\nconst navItems = computed(() => navGroups.value.flatMap((group) => group.items))\nconst searchableNavItems = computed(() =>\n  navItems.value.map((item) => ({\n    key: item.id,\n    label: item.label\n  }))\n)\n\nwatch(navItems, (items) => {\n  const activeKey = activeCategoryKey.value\n  if (!activeKey || items.some(({ id }) => id === activeKey)) return\n  activeCategoryKey.value = items[0]?.id ?? null\n})\n\nwatch(\n  [searchResultsCategories, matchedNavItemKeys],\n  ([categories, navKeys]) => {\n    if (!inSearch.value || (categories.size === 0 && navKeys.size === 0)) return\n    const firstMatch = navGroups.value\n      .flatMap((g) => g.items)\n      .find((item) => {\n        if (navKeys.has(item.id)) return true\n        const node = findCategoryByKey(item.id)\n        return node && categories.has(node.label)\n      })\n    activeCategoryKey.value = firstMatch?.id ?? null\n  }\n)\n\nconst activeSettingCategory = computed<SettingTreeNode | null>(() => {\n  if (!activeCategoryKey.value) return null\n  return (\n    settingCategories.value.find((c) => c.key === activeCategoryKey.value) ??\n    null\n  )\n})\n\nconst activePanel = computed(() => {\n  if (!activeCategoryKey.value) return null\n  return findPanelByKey(activeCategoryKey.value)\n})\n\nconst getGroupSortOrder = (group: SettingTreeNode): number =>\n  Math.max(0, ...flattenTree<SettingParams>(group).map((s) => s.sortOrder ?? 0))\n\nfunction sortedGroups(category: SettingTreeNode): ISettingGroup[] {\n  return [...(category.children ?? [])]\n    .sort((a, b) => {\n      const orderDiff = getGroupSortOrder(b) - getGroupSortOrder(a)\n      return orderDiff !== 0 ? orderDiff : a.label.localeCompare(b.label)\n    })\n    .map((group) => ({\n      label: group.label,\n      settings: flattenTree<SettingParams>(group).sort((a, b) => {\n        const sortOrderA = a.sortOrder ?? 0\n        const sortOrderB = b.sortOrder ?? 0\n        return sortOrderB - sortOrderA\n      })\n    }))\n}\n\nfunction handleSearch(query: string) {\n  handleSearchBase(query.trim(), searchableNavItems.value)\n  if (query) {\n    activeCategoryKey.value = null\n  } else if (!activeCategoryKey.value) {\n    activeCategoryKey.value = defaultCategory.value?.key ?? null\n  }\n}\n\nfunction onNavItemClick(id: string) {\n  activeCategoryKey.value = id\n}\n\nconst searchResults = computed<ISettingGroup[]>(() => getSearchResults(null))\n\nuseSearchQueryTracking('settings', searchQuery, searchResults)\n\n// Scroll to and highlight the target setting once the correct category renders.\nif (scrollToSettingId) {\n  const stopScrollWatch = watch(\n    activeCategoryKey,\n    () => {\n      void nextTick(() => {\n        const el = document.querySelector(\n          `[data-setting-id=\"${CSS.escape(scrollToSettingId)}\"]`\n        )\n        if (!el) return\n        stopScrollWatch()\n        el.scrollIntoView({ behavior: 'smooth', block: 'center' })\n        el.classList.add('setting-highlight')\n        el.addEventListener(\n          'animationend',\n          () => el.classList.remove('setting-highlight'),\n          { once: true }\n        )\n      })\n    },\n    { immediate: true }\n  )\n  onBeforeUnmount(stopScrollWatch)\n}\n\nwatch(activeCategoryKey, (newKey, oldKey) => {\n  if (!newKey && !inSearch.value) {\n    activeCategoryKey.value = oldKey\n  }\n  if (newKey === 'credits') {\n    void fetchBalance()\n  }\n  if (newKey) {\n    void nextTick(() => {\n      navRef.value\n        ?.querySelector(`[data-nav-id=\"${newKey}\"]`)\n        ?.scrollIntoView({ block: 'nearest', behavior: 'smooth' })\n    })\n  }\n})\n</script>\n\n<style>\n@media (prefers-reduced-motion: no-preference) {\n  .setting-highlight {\n    animation: setting-highlight-pulse 1.5s ease-in-out;\n  }\n}\n\n@keyframes setting-highlight-pulse {\n  0%,\n  100% {\n    background-color: transparent;\n  }\n  30% {\n    background-color: color-mix(\n      in srgb,\n      var(--p-primary-color) 15%,\n      transparent\n    );\n  }\n}\n</style>\n","import { until, useStorage } from '@vueuse/core'\nimport { defineStore } from 'pinia'\nimport { coerce, gt } from 'semver'\nimport { computed } from 'vue'\n\nimport config from '@/config'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useSystemStatsStore } from '@/stores/systemStatsStore'\n\ninterface OutdatedComfyPackage {\n  name: string\n  installed: string\n  required: string\n}\n\nconst DISMISSAL_DURATION_MS = 7 * 24 * 60 * 60 * 1000 // 7 days\n\n// Already covered by the dedicated frontend warning, which uses the\n// running bundle's version rather than the installed pip version.\nconst FRONTEND_PACKAGE_NAME = 'comfyui-frontend-package'\n\n// Backend reports PEP 440 versions (e.g. \"0.3.0.post1\", \"1.0.0rc1\");\n// coerce strips the suffix so we can compare with semver. Note: this means\n// \"0.4.0\" vs \"0.4.0.post1\" both coerce to \"0.4.0\" and compare equal — a\n// post-release alone is not treated as outdated.\nfunction isOutdated(installed: string, required: string): boolean {\n  const installedSemver = coerce(installed)\n  const requiredSemver = coerce(required)\n  if (!installedSemver || !requiredSemver) return false\n  return gt(requiredSemver, installedSemver)\n}\n\nexport const useVersionCompatibilityStore = defineStore(\n  'versionCompatibility',\n  () => {\n    const systemStatsStore = useSystemStatsStore()\n    const settingStore = useSettingStore()\n\n    const frontendVersion = computed(() => config.app_version)\n    const backendVersion = computed(\n      () => systemStatsStore.systemStats?.system.comfyui_version ?? ''\n    )\n    const requiredFrontendVersion = computed(\n      () => systemStatsStore.systemStats?.system.required_frontend_version ?? ''\n    )\n\n    const isFrontendOutdated = computed(() => {\n      if (!frontendVersion.value || !requiredFrontendVersion.value) return false\n      return isOutdated(frontendVersion.value, requiredFrontendVersion.value)\n    })\n\n    const isFrontendNewer = computed(() => {\n      // We don't warn about frontend being newer than backend\n      // Only warn when frontend is outdated (behind required version)\n      return false\n    })\n\n    const outdatedComfyPackages = computed<OutdatedComfyPackage[]>(() => {\n      const packages =\n        systemStatsStore.systemStats?.system.comfy_package_versions ?? []\n      const out: OutdatedComfyPackage[] = []\n      for (const pkg of packages) {\n        if (pkg.name === FRONTEND_PACKAGE_NAME) continue\n        if (!pkg.installed || !pkg.required) continue\n        if (!isOutdated(pkg.installed, pkg.required)) continue\n        out.push({\n          name: pkg.name,\n          installed: pkg.installed,\n          required: pkg.required\n        })\n      }\n      return out\n    })\n\n    const hasVersionMismatch = computed(() => {\n      return isFrontendOutdated.value || outdatedComfyPackages.value.length > 0\n    })\n\n    const versionKey = computed(() => {\n      if (!frontendVersion.value) return null\n      if (\n        !backendVersion.value &&\n        !requiredFrontendVersion.value &&\n        outdatedComfyPackages.value.length === 0\n      ) {\n        return null\n      }\n      const baseKey = `${frontendVersion.value}-${backendVersion.value}-${requiredFrontendVersion.value}`\n      if (outdatedComfyPackages.value.length === 0) return baseKey\n      const packageKey = [...outdatedComfyPackages.value]\n        .sort(\n          (a, b) =>\n            a.name.localeCompare(b.name) ||\n            a.installed.localeCompare(b.installed) ||\n            a.required.localeCompare(b.required)\n        )\n        .map((pkg) => `${pkg.name}@${pkg.installed}->${pkg.required}`)\n        .join(',')\n      return `${baseKey}-${packageKey}`\n    })\n\n    // Use reactive storage for dismissals - creates a reactive ref that syncs with localStorage\n    // All version mismatch dismissals are stored in a single object for clean localStorage organization\n    const dismissalStorage = useStorage(\n      'comfy.versionMismatch.dismissals',\n      {} as Record<string, number>,\n      localStorage,\n      {\n        serializer: {\n          read: (value: string) => {\n            try {\n              return JSON.parse(value)\n            } catch {\n              return {}\n            }\n          },\n          write: (value: Record<string, number>) => JSON.stringify(value)\n        }\n      }\n    )\n\n    const isDismissed = computed(() => {\n      if (!versionKey.value) return false\n\n      const dismissedUntil = dismissalStorage.value[versionKey.value]\n      if (!dismissedUntil) return false\n\n      // Check if dismissal has expired\n      return Date.now() < dismissedUntil\n    })\n\n    const warningsDisabled = computed(() =>\n      settingStore.get('Comfy.VersionCompatibility.DisableWarnings')\n    )\n\n    const shouldShowWarning = computed(() => {\n      return (\n        hasVersionMismatch.value &&\n        !isDismissed.value &&\n        !warningsDisabled.value\n      )\n    })\n\n    const warningMessage = computed(() => {\n      if (isFrontendOutdated.value) {\n        return {\n          type: 'outdated' as const,\n          frontendVersion: frontendVersion.value,\n          requiredVersion: requiredFrontendVersion.value\n        }\n      }\n      return null\n    })\n\n    const packageWarningMessages = computed(() =>\n      outdatedComfyPackages.value.map((pkg) => ({\n        name: pkg.name,\n        installedVersion: pkg.installed,\n        requiredVersion: pkg.required\n      }))\n    )\n\n    async function checkVersionCompatibility() {\n      if (!systemStatsStore.systemStats) {\n        await until(systemStatsStore.isInitialized)\n      }\n    }\n\n    function dismissWarning() {\n      if (!versionKey.value) return\n\n      const now = Date.now()\n      const pruned: Record<string, number> = {}\n      for (const [key, until] of Object.entries(dismissalStorage.value)) {\n        if (until > now) pruned[key] = until\n      }\n      pruned[versionKey.value] = now + DISMISSAL_DURATION_MS\n      dismissalStorage.value = pruned\n    }\n\n    async function initialize() {\n      await checkVersionCompatibility()\n    }\n\n    return {\n      frontendVersion,\n      backendVersion,\n      requiredFrontendVersion,\n      hasVersionMismatch,\n      shouldShowWarning,\n      warningMessage,\n      packageWarningMessages,\n      outdatedComfyPackages,\n      isFrontendOutdated,\n      isFrontendNewer,\n      checkVersionCompatibility,\n      dismissWarning,\n      initialize\n    }\n  }\n)\n","import { whenever } from '@vueuse/core'\nimport { computed, nextTick, onMounted, onUnmounted } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useToast } from '@/components/ui/toast/toastStore'\nimport { useVersionCompatibilityStore } from './versionCompatibilityStore'\n\ninterface UseFrontendVersionMismatchWarningOptions {\n  immediate?: boolean\n}\n\n/**\n * Composable for handling frontend version mismatch warnings.\n *\n * Displays toast notifications when the frontend version is incompatible with the backend,\n * either because the frontend is outdated or newer than the backend expects.\n * Automatically dismisses warnings when shown and persists dismissal state for 7 days.\n *\n * @param options - Configuration options\n * @param options.immediate - If true, automatically shows warning when version mismatch is detected\n * @returns Object with methods and computed properties for managing version warnings\n *\n * @example\n * ```ts\n * // Show warning immediately when mismatch detected\n * const { showWarning, shouldShowWarning } = useFrontendVersionMismatchWarning({ immediate: true })\n *\n * // Manual control\n * const { showWarning } = useFrontendVersionMismatchWarning()\n * showWarning() // Call when needed\n * ```\n */\nexport function useFrontendVersionMismatchWarning(\n  options: UseFrontendVersionMismatchWarningOptions = {}\n) {\n  const { immediate = false } = options\n  const { t } = useI18n()\n  const toast = useToast()\n  const versionCompatibilityStore = useVersionCompatibilityStore()\n\n  // Track if we've already shown the warning\n  let hasShownWarning = false\n\n  const emitAlert = (detail: string) => {\n    toast.warning(t('g.versionMismatchWarning'), {\n      description: t('g.versionMismatchUpdateInstructions', { detail })\n    })\n  }\n\n  const showWarning = () => {\n    // Prevent showing the warning multiple times\n    if (hasShownWarning) return\n\n    const message = versionCompatibilityStore.warningMessage\n    const packageMessages = versionCompatibilityStore.packageWarningMessages\n    if (!message && packageMessages.length === 0) return\n\n    if (message) {\n      emitAlert(\n        t('g.frontendOutdated', {\n          frontendVersion: message.frontendVersion,\n          requiredVersion: message.requiredVersion\n        })\n      )\n    }\n\n    for (const pkg of packageMessages) {\n      emitAlert(\n        t('g.comfyPackageOutdated', {\n          name: pkg.name,\n          installedVersion: pkg.installedVersion,\n          requiredVersion: pkg.requiredVersion\n        })\n      )\n    }\n\n    hasShownWarning = true\n\n    // Automatically dismiss the warning so it won't show again for 7 days\n    versionCompatibilityStore.dismissWarning()\n  }\n\n  let stopWatcher: (() => void) | null = null\n\n  onMounted(async () => {\n    if (!immediate) return\n    // Wait for next tick to ensure reactive updates from settings load have propagated\n    await nextTick()\n\n    stopWatcher = whenever(\n      () => versionCompatibilityStore.shouldShowWarning,\n      () => {\n        showWarning()\n      },\n      { immediate: true }\n    )\n  })\n\n  onUnmounted(() => {\n    stopWatcher?.()\n    stopWatcher = null\n  })\n\n  return {\n    showWarning,\n    shouldShowWarning: computed(\n      () => versionCompatibilityStore.shouldShowWarning\n    ),\n    dismissWarning: versionCompatibilityStore.dismissWarning,\n    hasVersionMismatch: computed(\n      () => versionCompatibilityStore.hasVersionMismatch\n    )\n  }\n}\n","import { partnerRunGateBlocksAutoQueue } from '@/composables/billing/usePartnerNodesRunGate'\nimport { api } from '@/scripts/api'\nimport { app } from '@/scripts/app'\nimport {\n  isInstantRunningMode,\n  useQueueSettingsStore\n} from '@/stores/queueSettingsStore'\nimport { useQueuePendingTaskCountStore } from '@/stores/queueStore'\n\nexport function setupAutoQueueHandler() {\n  const queueCountStore = useQueuePendingTaskCountStore()\n  const queueSettingsStore = useQueueSettingsStore()\n\n  let graphHasChanged = false\n  let internalCount = 0 // Use an internal counter here so it is instantly updated when re-queuing\n  api.addEventListener('autoQueueGraphChanged', () => {\n    // Skip the whole submission while gated: never enqueue a prompt the gate\n    // would drop, and never treat queuePrompt's false as gate rejection — it\n    // also means the item was queued behind an active processor.\n    if (partnerRunGateBlocksAutoQueue()) return\n    if (queueSettingsStore.mode === 'change') {\n      if (internalCount) {\n        graphHasChanged = true\n      } else {\n        graphHasChanged = false\n        // Queue the prompt in the background\n        void app.queuePrompt(0, queueSettingsStore.batchCount, {\n          intent: { trigger_source: 'auto_queue' }\n        })\n        internalCount++\n      }\n    }\n  })\n\n  queueCountStore.$subscribe(\n    async () => {\n      internalCount = queueCountStore.count\n      if (\n        !internalCount &&\n        !app.lastExecutionError &&\n        !partnerRunGateBlocksAutoQueue()\n      ) {\n        if (\n          isInstantRunningMode(queueSettingsStore.mode) ||\n          (queueSettingsStore.mode === 'change' && graphHasChanged)\n        ) {\n          graphHasChanged = false\n          await app.queuePrompt(0, queueSettingsStore.batchCount, {\n            intent: { trigger_source: 'auto_queue' }\n          })\n        }\n      }\n    },\n    { detached: true }\n  )\n}\n","<template>\n  <div role=\"radiogroup\" v-bind=\"$attrs\" :class=\"cn('flex flex-col', gapClass)\">\n    <Button\n      v-for=\"option in viewTypeOptions\"\n      :key=\"option.value.toString()\"\n      role=\"radio\"\n      :aria-checked=\"modelValue === option.value\"\n      :class=\"\n        cn(\n          'flex cursor-pointer items-center gap-2 self-stretch rounded-lg border-none bg-transparent py-2 pr-4 pl-2 text-base-foreground transition-colors hover:bg-secondary-background',\n          heightClass,\n          modelValue === option.value && 'bg-secondary-background'\n        )\n      \"\n      variant=\"textonly\"\n      @click=\"\n        modelValue !== option.value && emit('update:modelValue', option.value)\n      \"\n    >\n      <div\n        class=\"flex size-8 min-h-8 items-center justify-center rounded-lg bg-secondary-background-hover\"\n      >\n        <i :class=\"cn(option.icon, 'size-4')\" aria-hidden=\"true\" />\n      </div>\n      <div class=\"mx-2 flex flex-1 flex-col items-start\">\n        <span class=\"text-sm font-medium text-base-foreground\">\n          {{ option.title }}\n        </span>\n        <span class=\"text-xs text-muted-foreground\">\n          {{ option.subtitle }}\n        </span>\n      </div>\n      <i\n        v-if=\"modelValue === option.value\"\n        class=\"icon-[lucide--check] size-4 text-base-foreground\"\n        aria-hidden=\"true\"\n      />\n    </Button>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport Button from '@/components/ui/button/Button.vue'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useI18n } from 'vue-i18n'\n\nconst { t } = useI18n()\n\nconst { size = 'md' } = defineProps<{\n  modelValue: boolean\n  size?: 'sm' | 'md'\n}>()\n\nconst emit = defineEmits<{\n  'update:modelValue': [value: boolean]\n}>()\n\nconst viewTypeOptions = [\n  {\n    value: true,\n    icon: 'icon-[lucide--app-window]',\n    title: t('builderToolbar.app'),\n    subtitle: t('builderToolbar.appDescription')\n  },\n  {\n    value: false,\n    icon: 'icon-[comfy--workflow]',\n    title: t('builderToolbar.nodeGraph'),\n    subtitle: t('builderToolbar.nodeGraphDescription')\n  }\n]\nconst heightClass = size === 'sm' ? 'h-12' : 'h-14'\nconst gapClass = size === 'sm' ? 'gap-1' : 'gap-2'\n</script>\n","<template>\n  <PopoverRoot>\n    <PopoverAnchor as-child>\n      <div\n        data-testid=\"builder-opens-as\"\n        class=\"flex h-8 min-w-64 items-center justify-center gap-2 rounded-t-2xl bg-interface-builder-mode-footer-background px-4 text-sm text-interface-builder-mode-button-foreground\"\n      >\n        <i :class=\"cn(currentModeIcon, 'size-4')\" aria-hidden=\"true\" />\n        <i18n-t\n          :keypath=\"\n            isAppMode\n              ? 'builderFooter.opensAsApp'\n              : 'builderFooter.opensAsGraph'\n          \"\n          tag=\"span\"\n        >\n          <template #mode>\n            <PopoverTrigger as-child>\n              <Button\n                class=\"-ml-0.5 h-6 gap-1 rounded-md border-none bg-transparent px-1.5 text-sm text-interface-builder-mode-button-foreground hover:bg-interface-builder-mode-button-background/70\"\n              >\n                {{\n                  isAppMode\n                    ? t('builderToolbar.app').toLowerCase()\n                    : t('builderToolbar.nodeGraph').toLowerCase()\n                }}\n                <i\n                  class=\"icon-[lucide--chevron-down] size-3.5\"\n                  aria-hidden=\"true\"\n                />\n              </Button>\n            </PopoverTrigger>\n          </template>\n        </i18n-t>\n        <PopoverPortal>\n          <PopoverContent\n            side=\"top\"\n            :side-offset=\"5\"\n            :collision-padding=\"10\"\n            class=\"z-1700 rounded-lg border border-border-subtle bg-base-background p-2 shadow-sm will-change-[transform,opacity]\"\n          >\n            <ViewTypeRadioGroup\n              :model-value=\"isAppMode\"\n              :aria-label=\"t('builderToolbar.defaultViewLabel')\"\n              size=\"sm\"\n              @update:model-value=\"$emit('select', $event)\"\n            />\n          </PopoverContent>\n        </PopoverPortal>\n      </div>\n    </PopoverAnchor>\n  </PopoverRoot>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport {\n  PopoverAnchor,\n  PopoverContent,\n  PopoverPortal,\n  PopoverRoot,\n  PopoverTrigger\n} from 'reka-ui'\nimport { useI18n } from 'vue-i18n'\nimport Button from '@/components/ui/button/Button.vue'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport ViewTypeRadioGroup from './ViewTypeRadioGroup.vue'\n\nconst { isAppMode } = defineProps<{\n  isAppMode: boolean\n}>()\n\ndefineEmits<{\n  select: [openAsApp: boolean]\n}>()\n\nconst { t } = useI18n()\n\nconst currentModeIcon = computed(() =>\n  isAppMode ? 'icon-[lucide--app-window]' : 'icon-[comfy--workflow]'\n)\n</script>\n","import { useTelemetry } from '@/platform/telemetry'\nimport type { LoadedComfyWorkflow } from '@/platform/workflow/management/stores/comfyWorkflow'\nimport { app } from '@/scripts/app'\n\nexport function setWorkflowDefaultView(\n  workflow: LoadedComfyWorkflow,\n  openAsApp: boolean\n) {\n  workflow.initialMode = openAsApp ? 'app' : 'graph'\n  const extra = app.rootGraphOrUndefined?.extra\n  if (!extra) return\n  extra.linearMode = openAsApp\n  workflow.changeTracker.captureCanvasState()\n  useTelemetry()?.trackDefaultViewSet({\n    default_view: openAsApp ? 'app' : 'graph'\n  })\n}\n","<template>\n  <PopoverRoot>\n    <PopoverTrigger as-child>\n      <slot />\n    </PopoverTrigger>\n    <PopoverContent\n      side=\"bottom\"\n      align=\"end\"\n      :side-offset=\"18\"\n      :collision-padding=\"10\"\n      data-testid=\"builder-connect-output-popover\"\n      class=\"z-1001 w-80 rounded-xl border border-border-default bg-base-background shadow-interface will-change-[transform,opacity] data-[side=bottom]:slide-in-from-top-2 data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95\"\n    >\n      <div class=\"flex h-12 items-center justify-between px-4\">\n        <h3 class=\"text-sm font-medium text-base-foreground\">\n          {{ t('builderToolbar.connectOutput') }}\n        </h3>\n        <PopoverClose\n          :aria-label=\"t('g.close')\"\n          class=\"flex cursor-pointer appearance-none items-center justify-center border-none bg-transparent p-0 text-muted-foreground hover:text-base-foreground\"\n        >\n          <i class=\"icon-[lucide--x] size-4\" />\n        </PopoverClose>\n      </div>\n      <div class=\"border-t border-border-default\" />\n      <p class=\"mt-3 px-4 text-xs/relaxed text-muted-foreground\">\n        {{ t('builderToolbar.connectOutputBody1') }}\n      </p>\n      <p\n        v-if=\"!isSelectActive\"\n        class=\"mt-2 px-4 text-xs/relaxed text-muted-foreground\"\n      >\n        {{ t('builderToolbar.connectOutputBody2') }}\n      </p>\n      <div class=\"mt-4 flex items-center justify-end gap-2 px-4 pb-4\">\n        <template v-if=\"isSelectActive\">\n          <PopoverClose as-child>\n            <Button variant=\"secondary\" size=\"md\">\n              {{ t('g.ok') }}\n            </Button>\n          </PopoverClose>\n        </template>\n        <template v-else>\n          <PopoverClose as-child>\n            <Button variant=\"muted-textonly\" size=\"md\">\n              {{ t('g.cancel') }}\n            </Button>\n          </PopoverClose>\n          <PopoverClose as-child>\n            <Button\n              variant=\"secondary\"\n              size=\"md\"\n              data-testid=\"builder-connect-output-switch\"\n              @click=\"emit('switch')\"\n            >\n              {{ t('builderToolbar.switchToOutputs') }}\n            </Button>\n          </PopoverClose>\n        </template>\n      </div>\n    </PopoverContent>\n  </PopoverRoot>\n</template>\n\n<script setup lang=\"ts\">\nimport {\n  PopoverClose,\n  PopoverContent,\n  PopoverRoot,\n  PopoverTrigger\n} from 'reka-ui'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\n\nconst { isSelectActive = false } = defineProps<{\n  isSelectActive?: boolean\n}>()\n\nconst { t } = useI18n()\n\nconst emit = defineEmits<{\n  switch: []\n}>()\n</script>\n","<template>\n  <BuilderDialog @close=\"emit('close')\">\n    <template #title>\n      {{ $t('builderToolbar.saveAs') }}\n    </template>\n\n    <div class=\"flex flex-col gap-2\">\n      <DialogDescription as-child>\n        <label :for=\"inputId\" class=\"text-sm text-muted-foreground\">\n          {{ $t('builderToolbar.filename') }}\n        </label>\n      </DialogDescription>\n      <input\n        :id=\"inputId\"\n        v-model=\"filename\"\n        autofocus\n        type=\"text\"\n        class=\"flex h-10 min-h-8 items-center self-stretch rounded-lg border-none bg-secondary-background pl-4 text-sm text-base-foreground focus-visible:ring-border-default\"\n        @keydown.enter=\"\n          filename.trim() && emit('save', filename.trim(), openAsApp)\n        \"\n      />\n    </div>\n\n    <div class=\"flex flex-col gap-2\">\n      <label :id=\"radioGroupLabelId\" class=\"text-sm text-muted-foreground\">\n        {{ $t('builderToolbar.defaultViewLabel') }}\n      </label>\n      <ViewTypeRadioGroup\n        v-model=\"openAsApp\"\n        :aria-labelledby=\"radioGroupLabelId\"\n      />\n    </div>\n\n    <template #footer>\n      <Button variant=\"muted-textonly\" size=\"lg\" @click=\"emit('close')\">\n        {{ $t('g.cancel') }}\n      </Button>\n      <Button\n        variant=\"secondary\"\n        size=\"lg\"\n        :disabled=\"!filename.trim()\"\n        @click=\"emit('save', filename.trim(), openAsApp)\"\n      >\n        {{ $t('g.save') }}\n      </Button>\n    </template>\n  </BuilderDialog>\n</template>\n\n<script setup lang=\"ts\">\nimport { ref, useId } from 'vue'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport DialogDescription from '@/components/ui/dialog/DialogDescription.vue'\n\nimport BuilderDialog from './BuilderDialog.vue'\nimport ViewTypeRadioGroup from './ViewTypeRadioGroup.vue'\n\nconst { defaultFilename, defaultOpenAsApp = true } = defineProps<{\n  defaultFilename: string\n  defaultOpenAsApp?: boolean\n}>()\n\nconst emit = defineEmits<{\n  save: [filename: string, openAsApp: boolean]\n  close: []\n}>()\n\nconst inputId = useId()\nconst radioGroupLabelId = useId()\nconst filename = ref(defaultFilename)\nconst openAsApp = ref(defaultOpenAsApp)\n</script>\n","import { useAppMode } from '@/composables/useAppMode'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { showConfirmDialog } from '@/components/dialog/confirm/confirmDialog'\nimport { t } from '@/i18n'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useDialogService } from '@/services/dialogService'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport { ref } from 'vue'\n\nimport BuilderSaveDialogContent from './BuilderSaveDialogContent.vue'\n\nconst SAVE_DIALOG_KEY = 'builder-save'\nconst SUCCESS_DIALOG_KEY = 'builder-save-success'\n\nconst isSaving = ref(false)\n\nexport function useBuilderSave() {\n  const { toastErrorHandler } = useErrorHandling()\n  const { setMode } = useAppMode()\n  const workflowStore = useWorkflowStore()\n  const workflowService = useWorkflowService()\n  const dialogService = useDialogService()\n  const appModeStore = useAppModeStore()\n  const dialogStore = useDialogStore()\n\n  function closeDialog(key: string) {\n    dialogStore.closeDialog({ key })\n  }\n\n  async function save() {\n    if (isSaving.value) return\n    const workflow = workflowStore.activeWorkflow\n    if (!workflow) return\n\n    isSaving.value = true\n    try {\n      await workflowService.saveWorkflow(workflow)\n    } catch (e) {\n      toastErrorHandler(e)\n    } finally {\n      isSaving.value = false\n    }\n  }\n\n  function saveAs() {\n    if (isSaving.value) return\n    const workflow = workflowStore.activeWorkflow\n    if (!workflow) return\n\n    dialogService.showLayoutDialog({\n      key: SAVE_DIALOG_KEY,\n      component: BuilderSaveDialogContent,\n      props: {\n        defaultFilename: workflow.filename,\n        defaultOpenAsApp: workflow.initialMode !== 'graph',\n        onSave: handleSaveAs,\n        onClose: () => closeDialog(SAVE_DIALOG_KEY)\n      },\n      dialogComponentProps: { useAutomaticLabeling: true }\n    })\n  }\n\n  async function handleSaveAs(filename: string, openAsApp: boolean) {\n    if (isSaving.value) return\n    isSaving.value = true\n    try {\n      const workflow = workflowStore.activeWorkflow\n      if (!workflow) return\n\n      const saved = await workflowService.saveWorkflowAs(workflow, {\n        filename,\n        isApp: openAsApp\n      })\n\n      if (!saved) return\n      useTelemetry()?.trackDefaultViewSet({\n        default_view: openAsApp ? 'app' : 'graph'\n      })\n      closeDialog(SAVE_DIALOG_KEY)\n      showSuccessDialog(openAsApp ? 'app' : 'graph')\n    } catch (e) {\n      toastErrorHandler(e)\n      closeDialog(SAVE_DIALOG_KEY)\n    } finally {\n      isSaving.value = false\n    }\n  }\n\n  function showSuccessDialog(viewType: 'app' | 'graph') {\n    const promptText =\n      viewType === 'app'\n        ? t('builderSave.successBodyApp')\n        : t('builderSave.successBodyGraph')\n\n    showConfirmDialog({\n      key: SUCCESS_DIALOG_KEY,\n      headerProps: {\n        title: t('builderSave.successTitle'),\n        icon: 'icon-[lucide--circle-check-big] text-green-500'\n      },\n      props: { promptText, preserveNewlines: true },\n      footerProps:\n        viewType === 'graph'\n          ? {\n              cancelText: t('builderToolbar.viewApp'),\n              confirmText: t('linearMode.builder.exit'),\n              confirmVariant: 'secondary' as const,\n              onCancel: () => {\n                closeDialog(SUCCESS_DIALOG_KEY)\n                useTelemetry()?.trackEnterLinear({ source: 'app_builder' })\n                setMode('app')\n              },\n              onConfirm: () => {\n                closeDialog(SUCCESS_DIALOG_KEY)\n                appModeStore.exitBuilder()\n              }\n            }\n          : {\n              cancelText: t('g.close'),\n              confirmText: t('builderToolbar.viewApp'),\n              confirmVariant: 'secondary' as const,\n              onCancel: () => closeDialog(SUCCESS_DIALOG_KEY),\n              onConfirm: () => {\n                closeDialog(SUCCESS_DIALOG_KEY)\n                useTelemetry()?.trackEnterLinear({ source: 'app_builder' })\n                setMode('app')\n              }\n            }\n    })\n  }\n\n  return { save, saveAs, isSaving }\n}\n","import type { Ref } from 'vue'\n\nimport { computed } from 'vue'\n\nimport { useAppMode } from '@/composables/useAppMode'\n\nconst BUILDER_STEPS = [\n  'builder:inputs',\n  'builder:outputs',\n  'builder:arrange'\n] as const\n\nexport type BuilderStepId = (typeof BUILDER_STEPS)[number]\n\nconst ARRANGE_INDEX = BUILDER_STEPS.indexOf('builder:arrange')\n\nexport function useBuilderSteps(options?: { hasOutputs?: Ref<boolean> }) {\n  const { mode, isBuilderMode, setMode } = useAppMode()\n\n  const activeStep = computed<BuilderStepId>(() => {\n    if (isBuilderMode.value) {\n      return mode.value as BuilderStepId\n    }\n    return 'builder:inputs'\n  })\n\n  const activeStepIndex = computed(() =>\n    BUILDER_STEPS.indexOf(activeStep.value)\n  )\n\n  const isFirstStep = computed(() => activeStepIndex.value === 0)\n\n  const isLastStep = computed(() => {\n    if (!options?.hasOutputs?.value)\n      return activeStepIndex.value >= ARRANGE_INDEX\n    return activeStepIndex.value >= BUILDER_STEPS.length - 1\n  })\n\n  const isSelectStep = computed(\n    () =>\n      activeStep.value === 'builder:inputs' ||\n      activeStep.value === 'builder:outputs'\n  )\n\n  function goBack() {\n    if (isFirstStep.value) return\n    setMode(BUILDER_STEPS[activeStepIndex.value - 1])\n  }\n\n  function goNext() {\n    if (isLastStep.value) return\n    setMode(BUILDER_STEPS[activeStepIndex.value + 1])\n  }\n\n  return {\n    activeStep,\n    activeStepIndex,\n    isFirstStep,\n    isLastStep,\n    isSelectStep,\n    navigateToStep: setMode,\n    goBack,\n    goNext\n  }\n}\n","<template>\n  <div\n    class=\"fixed bottom-4 left-1/2 z-1000 flex -translate-x-1/2 flex-col items-center\"\n  >\n    <!-- \"Opens as\" attachment tab -->\n    <BuilderOpensAsPopover\n      v-if=\"isSaved\"\n      :is-app-mode=\"isAppMode\"\n      @select=\"onSetDefaultView\"\n    />\n\n    <!-- Main toolbar -->\n    <nav\n      data-testid=\"builder-footer-nav\"\n      class=\"flex items-center gap-2 rounded-2xl border border-border-default bg-base-background p-2 shadow-interface\"\n    >\n      <Button variant=\"textonly\" size=\"lg\" @click=\"onExitBuilder\">\n        {{ t('builderMenu.exitAppBuilder') }}\n      </Button>\n      <Button variant=\"secondary\" size=\"lg\" @click=\"onViewApp\">\n        {{ t('builderToolbar.viewApp') }}\n      </Button>\n      <Button\n        variant=\"textonly\"\n        size=\"lg\"\n        :disabled=\"isFirstStep\"\n        @click=\"goBack\"\n      >\n        <i class=\"icon-[lucide--chevron-left]\" aria-hidden=\"true\" />\n        {{ t('g.back') }}\n      </Button>\n      <Button size=\"lg\" :disabled=\"isLastStep\" @click=\"goNext\">\n        {{ t('g.next') }}\n        <i class=\"icon-[lucide--chevron-right]\" aria-hidden=\"true\" />\n      </Button>\n      <div class=\"relative min-w-24\">\n        <!--\n          Invisible sizers: both labels rendered with matching button padding\n          so the container's intrinsic width equals the wider label.\n          height:0 + overflow:hidden keeps them invisible without affecting height.\n        -->\n        <div class=\"max-h-0 overflow-y-hidden\" aria-hidden=\"true\">\n          <div class=\"px-4 py-2 text-sm\">{{ t('g.save') }}</div>\n          <div class=\"px-4 py-2 text-sm\">{{ t('builderToolbar.saveAs') }}</div>\n        </div>\n        <ConnectOutputPopover\n          v-if=\"!hasOutputs\"\n          class=\"w-full\"\n          :is-select-active=\"isSelectStep\"\n          @switch=\"navigateToStep('builder:outputs')\"\n        >\n          <Button\n            size=\"lg\"\n            class=\"w-full\"\n            :class=\"disabledSaveClasses\"\n            data-testid=\"builder-save-as-button\"\n          >\n            {{ isSaved ? t('g.save') : t('builderToolbar.saveAs') }}\n          </Button>\n        </ConnectOutputPopover>\n        <ButtonGroup\n          v-else-if=\"isSaved\"\n          data-testid=\"builder-save-group\"\n          class=\"w-full rounded-lg bg-secondary-background has-[[data-save-chevron]:hover]:bg-secondary-background-hover\"\n        >\n          <Button\n            size=\"lg\"\n            :disabled=\"!isModified\"\n            class=\"flex-1\"\n            :class=\"isModified ? activeSaveClasses : disabledSaveClasses\"\n            data-testid=\"builder-save-button\"\n            @click=\"save()\"\n          >\n            {{ t('g.save') }}\n          </Button>\n          <Menu\n            :items=\"saveAsMenuItems\"\n            align=\"end\"\n            :side-offset=\"4\"\n            class=\"min-w-36\"\n          >\n            <template #trigger>\n              <Button\n                size=\"lg\"\n                :aria-label=\"t('builderToolbar.saveAs')\"\n                data-save-chevron\n                data-testid=\"builder-save-as-chevron\"\n                class=\"w-6 rounded-l-none border-l border-border-default px-0\"\n              >\n                <i\n                  class=\"icon-[lucide--chevron-down] size-4\"\n                  aria-hidden=\"true\"\n                />\n              </Button>\n            </template>\n          </Menu>\n        </ButtonGroup>\n        <Button\n          v-else\n          size=\"lg\"\n          class=\"w-full\"\n          :class=\"activeSaveClasses\"\n          data-testid=\"builder-save-as-button\"\n          @click=\"saveAs()\"\n        >\n          {{ t('builderToolbar.saveAs') }}\n        </Button>\n      </div>\n    </nav>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useEventListener } from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport ButtonGroup from '@/components/ui/button-group/ButtonGroup.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useDialogStore } from '@/stores/dialogStore'\nimport BuilderOpensAsPopover from './BuilderOpensAsPopover.vue'\nimport { setWorkflowDefaultView } from './builderViewOptions'\nimport ConnectOutputPopover from './ConnectOutputPopover.vue'\nimport { useBuilderSave } from './useBuilderSave'\nimport { useBuilderSteps } from './useBuilderSteps'\n\nconst { t } = useI18n()\nconst appModeStore = useAppModeStore()\nconst dialogStore = useDialogStore()\nconst workflowStore = useWorkflowStore()\nconst { isBuilderMode, setMode } = useAppMode()\nconst { hasOutputs } = storeToRefs(appModeStore)\nconst {\n  isFirstStep,\n  isLastStep,\n  isSelectStep,\n  navigateToStep,\n  goBack,\n  goNext\n} = useBuilderSteps({\n  hasOutputs\n})\nconst { save, saveAs } = useBuilderSave()\nconst saveAsMenuItems = computed<MenuItem[]>(() => [\n  { label: t('builderToolbar.saveAs'), command: saveAs }\n])\n\nconst isSaved = computed(\n  () => workflowStore.activeWorkflow?.isTemporary === false\n)\n\nconst activeSaveClasses =\n  'bg-interface-builder-mode-button-background text-interface-builder-mode-button-foreground hover:bg-interface-builder-mode-button-background/80'\nconst disabledSaveClasses =\n  'bg-secondary-background text-muted-foreground/50 disabled:opacity-100'\n\nconst isModified = computed(\n  () => workflowStore.activeWorkflow?.isModified === true\n)\n\nconst isAppMode = computed(\n  () => workflowStore.activeWorkflow?.initialMode !== 'graph'\n)\n\nuseEventListener(window, 'keydown', (e: KeyboardEvent) => {\n  if (\n    e.key === 'Escape' &&\n    !e.ctrlKey &&\n    !e.altKey &&\n    !e.metaKey &&\n    dialogStore.dialogStack.length === 0 &&\n    isBuilderMode.value\n  ) {\n    e.preventDefault()\n    e.stopPropagation()\n    onExitBuilder()\n  }\n})\n\nfunction onExitBuilder() {\n  appModeStore.exitBuilder()\n}\n\nfunction onViewApp() {\n  setMode('app')\n}\n\nfunction onSetDefaultView(openAsApp: boolean) {\n  const workflow = workflowStore.activeWorkflow\n  if (!workflow) return\n  setWorkflowDefaultView(workflow, openAsApp)\n}\n</script>\n","<template>\n  <Menu v-model:open=\"open\" :items=\"menuItems\" class=\"min-w-56\">\n    <template #trigger>\n      <button\n        :class=\"\n          cn(\n            'absolute top-[calc(var(--workflow-tabs-height)+16px)] left-4 z-1000 inline-flex h-10 cursor-pointer items-center gap-2.5 rounded-lg border-none py-2 pr-2 pl-3 shadow-interface transition-colors',\n            'bg-secondary-background hover:bg-secondary-background-hover',\n            'data-[state=open]:bg-secondary-background-hover'\n          )\n        \"\n        :aria-label=\"t('linearMode.appModeToolbar.appBuilder')\"\n      >\n        <i class=\"icon-[lucide--hammer] size-4\" />\n        <span class=\"text-sm font-medium\">\n          {{ t('linearMode.appModeToolbar.appBuilder') }}\n        </span>\n        <i class=\"icon-[lucide--chevron-down] size-4 text-muted-foreground\" />\n      </button>\n    </template>\n  </Menu>\n</template>\n\n<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { storeToRefs } from 'pinia'\nimport { useI18n } from 'vue-i18n'\n\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem, MenuItemCommandEvent } from '@/components/ui/menu/types'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\nconst appModeStore = useAppModeStore()\nconst { hasOutputs } = storeToRefs(appModeStore)\nconst { setMode } = useAppMode()\nconst workflowService = useWorkflowService()\nconst workflowStore = useWorkflowStore()\nconst { toastErrorHandler } = useErrorHandling()\nconst open = ref(false)\n\nconst menuItems = computed<MenuItem[]>(() => [\n  {\n    label: t('g.save'),\n    icon: 'icon-[lucide--save]',\n    disabled: !hasOutputs.value,\n    command: onSave\n  },\n  { separator: true },\n  {\n    label: t('builderMenu.enterAppMode'),\n    icon: 'icon-[lucide--panels-top-left]',\n    command: onEnterAppMode\n  },\n  { separator: true },\n  {\n    label: t('builderMenu.exitAppBuilder'),\n    icon: 'icon-[lucide--x]',\n    command: onExitBuilder\n  }\n])\n\nasync function onSave({ originalEvent }: MenuItemCommandEvent) {\n  originalEvent.preventDefault()\n  const workflow = workflowStore.activeWorkflow\n  if (!workflow) return\n  try {\n    const saved = await workflowService.saveWorkflow(workflow)\n    if (saved) open.value = false\n  } catch (error) {\n    toastErrorHandler(error)\n  }\n}\n\nfunction onEnterAppMode() {\n  setMode('app')\n}\n\nfunction onExitBuilder() {\n  appModeStore.exitBuilder()\n}\n</script>\n","<template>\n  <div\n    class=\"flex size-10 shrink-0 items-center justify-center rounded-lg bg-interface-builder-mode-button-background text-interface-builder-mode-button-foreground\"\n  >\n    <i v-if=\"modelValue === step.id\" :class=\"cn(step.icon, 'size-5')\" />\n    <span v-else class=\"text-sm font-bold\">\n      {{ index + 1 }}\n    </span>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport type { BuilderToolbarStep } from './types'\n\ndefineProps<{\n  step: BuilderToolbarStep\n  index: number\n  modelValue: string\n}>()\n</script>\n","<template>\n  <div class=\"flex flex-col gap-0.5 text-left\">\n    <span class=\"text-sm font-medium text-base-foreground\">\n      {{ step.title }}\n    </span>\n    <span\n      class=\"hidden text-xs whitespace-nowrap text-muted-foreground sm:inline\"\n    >\n      {{ step.subtitle }}\n    </span>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport type { BuilderToolbarStep } from './types'\n\nconst { step } = defineProps<{\n  step: BuilderToolbarStep\n}>()\n</script>\n","<template>\n  <nav\n    class=\"fixed top-[calc(var(--workflow-tabs-height)+var(--spacing)*1.5)] left-1/2 z-1000 -translate-x-1/2\"\n    :aria-label=\"t('builderToolbar.label')\"\n  >\n    <div\n      class=\"inline-flex items-center gap-1 rounded-2xl border border-border-default bg-base-background p-2 shadow-interface\"\n    >\n      <template v-for=\"(step, index) in steps\" :key=\"step.id\">\n        <button\n          :class=\"\n            cn(\n              stepClasses,\n              activeStep === step.id\n                ? 'bg-interface-builder-mode-background'\n                : 'bg-transparent hover:bg-secondary-background'\n            )\n          \"\n          :aria-current=\"activeStep === step.id ? 'step' : undefined\"\n          @click=\"navigateToStep(step.id)\"\n        >\n          <StepBadge :step :index :model-value=\"activeStep\" />\n          <StepLabel :step />\n        </button>\n\n        <div\n          v-if=\"index < steps.length - 1\"\n          class=\"mx-1 h-px w-4 bg-border-default\"\n          role=\"separator\"\n        />\n      </template>\n    </div>\n  </nav>\n</template>\n\n<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport StepBadge from './StepBadge.vue'\nimport StepLabel from './StepLabel.vue'\nimport type { BuilderToolbarStep } from './types'\nimport type { BuilderStepId } from './useBuilderSteps'\nimport { useBuilderSteps } from './useBuilderSteps'\n\nconst { t } = useI18n()\nconst { activeStep, navigateToStep } = useBuilderSteps()\n\nconst stepClasses =\n  'inline-flex h-14 min-h-8 cursor-pointer items-center gap-3 rounded-lg py-2 pr-4 pl-2 transition-colors border-none'\n\nconst selectInputsStep: BuilderToolbarStep<BuilderStepId> = {\n  id: 'builder:inputs',\n  title: t('builderToolbar.inputs'),\n  subtitle: t('builderToolbar.inputsDescription'),\n  icon: 'icon-[lucide--mouse-pointer-click]'\n}\n\nconst selectOutputsStep: BuilderToolbarStep<BuilderStepId> = {\n  id: 'builder:outputs',\n  title: t('builderToolbar.outputs'),\n  subtitle: t('builderToolbar.outputsDescription'),\n  icon: 'icon-[lucide--mouse-pointer-click]'\n}\n\nconst arrangeStep: BuilderToolbarStep<BuilderStepId> = {\n  id: 'builder:arrange',\n  title: t('builderToolbar.arrange'),\n  subtitle: t('builderToolbar.arrangeDescription'),\n  icon: 'icon-[lucide--layout-panel-left]'\n}\n\nconst steps = [selectInputsStep, selectOutputsStep, arrangeStep]\n</script>\n","<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport { useI18n } from 'vue-i18n'\n\nimport { useEnterBuilder } from '@/components/builder/useEnterBuilder'\nimport WorkflowActionsDropdown from '@/components/common/WorkflowActionsDropdown.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useAppModeStore } from '@/stores/appModeStore'\n\nconst { t } = useI18n()\nconst { enableAppBuilder } = useAppMode()\nconst appModeStore = useAppModeStore()\nconst { enterBuilder } = useEnterBuilder()\nconst { hasNodes } = storeToRefs(appModeStore)\n</script>\n\n<template>\n  <div class=\"pointer-events-auto flex flex-row items-start gap-2\">\n    <WorkflowActionsDropdown source=\"app_mode_toolbar\" />\n    <Button\n      v-if=\"enableAppBuilder\"\n      variant=\"base\"\n      size=\"unset\"\n      :disabled=\"!hasNodes\"\n      :aria-label=\"t('linearMode.appModeToolbar.buildAnApp')\"\n      class=\"h-10 gap-1.5 rounded-lg px-3 font-normal\"\n      @click=\"enterBuilder\"\n    >\n      <i class=\"icon-[lucide--hammer] size-4\" />\n      <span>{{ t('linearMode.appModeToolbar.buildAnApp') }}</span>\n    </Button>\n  </div>\n</template>\n","export const LINEAR_RUN_ERROR_WARNING_DESCRIPTION_ID =\n  'linear-run-error-warning'\n","<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useErrorOverlayState } from '@/components/error/useErrorOverlayState'\nimport { useViewErrorsInGraph } from '@/composables/useViewErrorsInGraph'\nimport { LINEAR_RUN_ERROR_WARNING_DESCRIPTION_ID } from '@/renderer/extensions/linearMode/linearRunErrorWarningIds'\n\nconst { t } = useI18n()\nconst { viewErrorsInGraph } = useViewErrorsInGraph()\nconst { hasError, overlayMessage, overlayTitle } = useErrorOverlayState()\n</script>\n\n<template>\n  <div\n    role=\"status\"\n    data-testid=\"linear-validation-warning\"\n    :class=\"\n      cn(\n        'mb-3 flex w-full flex-col gap-2 overflow-hidden rounded-lg border border-l-4 border-border-default bg-base-background p-3 shadow-interface transition-colors duration-200 ease-in-out',\n        hasError\n          ? 'border-l-destructive-background'\n          : 'border-l-warning-foreground'\n      )\n    \"\n  >\n    <div\n      :id=\"LINEAR_RUN_ERROR_WARNING_DESCRIPTION_ID\"\n      data-testid=\"linear-validation-warning-description\"\n      class=\"flex flex-col gap-2\"\n    >\n      <div class=\"flex w-full items-start gap-2\">\n        <i\n          aria-hidden=\"true\"\n          :class=\"\n            cn(\n              'mt-0.5 size-4 shrink-0',\n              hasError\n                ? 'icon-[lucide--circle-x] text-destructive-background'\n                : 'icon-[lucide--triangle-alert] text-warning-foreground'\n            )\n          \"\n        />\n        <span class=\"sr-only\">{{ t(hasError ? 'g.error' : 'g.warning') }}</span>\n        <span\n          class=\"min-w-0 flex-1 truncate text-sm text-base-foreground\"\n          :title=\"overlayTitle\"\n        >\n          {{ overlayTitle }}\n        </span>\n      </div>\n\n      <div\n        class=\"flex w-full items-start gap-2\"\n        data-testid=\"linear-validation-warning-message\"\n      >\n        <span class=\"size-4 shrink-0\" aria-hidden=\"true\" />\n        <p\n          class=\"m-0 line-clamp-3 min-w-0 flex-1 text-sm/snug wrap-break-word whitespace-pre-wrap text-muted-foreground\"\n        >\n          {{ overlayMessage }}\n        </p>\n      </div>\n    </div>\n\n    <div class=\"flex w-full items-center justify-end pt-2\">\n      <Button\n        variant=\"secondary\"\n        size=\"unset\"\n        class=\"min-h-8 rounded-lg px-3 py-2 text-xs font-normal\"\n        data-testid=\"linear-view-errors\"\n        @click=\"viewErrorsInGraph\"\n      >\n        {{ t('linearMode.error.goto') }}\n      </Button>\n    </div>\n  </div>\n</template>\n","<script setup lang=\"ts\">\ndefineProps<{ title: string; price: string }>()\n</script>\n<template>\n  <div class=\"not-last:mb-4\">\n    <div class=\"text-muted-foreground\" v-text=\"title\" />\n    <span\n      class=\"mt-2 flex h-5 max-w-max items-center rounded-full bg-component-node-widget-background p-2 py-3\"\n    >\n      <i class=\"mr-1 icon-[lucide--coins] h-4 bg-credit\" />\n      {{ price }}\n    </span>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport {\n  CollapsibleContent,\n  CollapsibleRoot,\n  CollapsibleTrigger\n} from 'reka-ui'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport Popover from '@/components/ui/Popover.vue'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport PartnerNodeItem from '@/renderer/extensions/linearMode/PartnerNodeItem.vue'\nimport { graphCreditsBadges } from '@/systems/badgeSystem'\n\ndefineProps<{ mobile?: boolean }>()\n\nconst { t } = useI18n()\nconst canvasStore = useCanvasStore()\n\nconst creditsBadges = computed(() => {\n  const rootGraph = canvasStore.currentGraph?.rootGraph\n  return rootGraph ? graphCreditsBadges(rootGraph) : []\n})\n</script>\n<template>\n  <Popover v-if=\"mobile && creditsBadges.length\" side=\"top\">\n    <template #button>\n      <Button class=\"mr-2 size-10\">\n        <i class=\"icon-[lucide--coins] bg-credit\" />\n      </Button>\n    </template>\n    <section\n      class=\"max-h-(--reka-popover-content-available-height) scroll-shadows-comfy-menu-bg overflow-y-auto\"\n    >\n      <PartnerNodeItem\n        v-for=\"{ nodeId, title, price } in creditsBadges\"\n        :key=\"nodeId\"\n        :title\n        :price\n      />\n    </section>\n  </Popover>\n  <div v-else-if=\"creditsBadges.length === 1\">\n    <PartnerNodeItem\n      v-for=\"{ nodeId, title, price } in creditsBadges\"\n      :key=\"nodeId\"\n      :title\n      :price\n      class=\"border-t border-border-subtle pt-2\"\n    />\n  </div>\n  <CollapsibleRoot\n    v-else-if=\"creditsBadges.length\"\n    v-slot=\"{ open }\"\n    class=\"flex max-h-1/2 w-full flex-col\"\n  >\n    <div class=\"mb-1 w-full border-b border-border-subtle\" />\n    <CollapsibleTrigger as-child>\n      <Button variant=\"textonly\" class=\"w-full text-sm\">\n        <i class=\"icon-[lucide--coins] size-4 bg-credit\" />\n        {{ t('linearMode.hasCreditCost') }}\n        <i v-if=\"open\" class=\"ml-auto icon-[lucide--chevron-up]\" />\n        <i v-else class=\"ml-auto icon-[lucide--chevron-down]\" />\n      </Button>\n    </CollapsibleTrigger>\n    <CollapsibleContent class=\"scroll-shadows-comfy-menu-bg overflow-y-auto\">\n      <PartnerNodeItem\n        v-for=\"{ nodeId, title, price } in creditsBadges\"\n        :key=\"nodeId\"\n        :title\n        :price\n      />\n    </CollapsibleContent>\n  </CollapsibleRoot>\n</template>\n","<script setup lang=\"ts\">\nimport { useTimeout } from '@vueuse/core'\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { storeToRefs } from 'pinia'\nimport { computed, ref, toValue, useTemplateRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport AppModeWidgetList from '@/components/builder/AppModeWidgetList.vue'\nimport { useErrorOverlayState } from '@/components/error/useErrorOverlayState'\nimport Loader from '@/components/loader/Loader.vue'\nimport ScrubableNumberInput from '@/components/common/ScrubableNumberInput.vue'\nimport { COACH_IDS } from '@/platform/onboarding/onboardingTours'\nimport { useOnboardingTourStore } from '@/platform/onboarding/onboardingTourStore'\nimport { vCoachmark } from '@/platform/onboarding/vCoachmark'\nimport Popover from '@/components/ui/Popover.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useBillingContext } from '@/composables/billing/useBillingContext'\nimport { isCloud } from '@/platform/distribution/types'\nimport FreeTierQuota from '@/platform/cloud/subscription/components/FreeTierQuota.vue'\nimport SubscribeToRunButton from '@/platform/cloud/subscription/components/SubscribeToRun.vue'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport LinearRunErrorWarning from '@/renderer/extensions/linearMode/LinearRunErrorWarning.vue'\nimport { LINEAR_RUN_ERROR_WARNING_DESCRIPTION_ID } from '@/renderer/extensions/linearMode/linearRunErrorWarningIds'\nimport PartnerNodesList from '@/renderer/extensions/linearMode/PartnerNodesList.vue'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useQueueSettingsStore } from '@/stores/queueSettingsStore'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\nimport { useMissingMediaStore } from '@/platform/missingMedia/missingMediaStore'\nimport { useTemplateInputDownloadStore } from '@/stores/templateInputDownloadStore'\n\nconst { t } = useI18n()\nconst commandStore = useCommandStore()\nconst { batchCount } = storeToRefs(useQueueSettingsStore())\nconst settingStore = useSettingStore()\nconst { canRunWorkflows, showsSubscribeToRunPrompt } = useBillingContext()\nconst showsCloudSubscribePrompt = computed(\n  () => isCloud && showsSubscribeToRunPrompt.value\n)\nconst workflowStore = useWorkflowStore()\nconst { isBuilderMode } = useAppMode()\nconst appModeStore = useAppModeStore()\nconst { hasOutputs } = storeToRefs(appModeStore)\nconst { hasAnyError, hasMissingError } = storeToRefs(useExecutionErrorStore())\nconst missingMediaStore = useMissingMediaStore()\nconst templateInputDownloadStore = useTemplateInputDownloadStore()\nconst { overlayMessage } = useErrorOverlayState()\n\nconst { toastTo, mobile } = defineProps<{\n  toastTo?: string | HTMLElement\n  mobile?: boolean\n}>()\ndefineEmits<{ navigateOutputs: [] }>()\ndefineExpose({ runButtonClick, handleDragDrop })\n\n//NOTE: due to batching, will never be greater than 2\nconst pendingJobQueues = ref(0)\nconst { ready: jobToastTimeout, start: resetJobToastTimeout } = useTimeout(\n  8000,\n  { controls: true, immediate: false }\n)\nconst widgetListRef = useTemplateRef('widgetListRef')\nconst linearRunButtonTestId = 'linear-run-button'\nconst linearInputDownloadStatusId = 'linear-input-download-status'\nconst requiredInputDownloads = computed(() => {\n  const requiredFilenames = new Set(\n    (missingMediaStore.missingMediaCandidates ?? []).map(({ name }) => name)\n  )\n  return templateInputDownloadStore.downloads.filter(({ filename }) =>\n    requiredFilenames.has(filename)\n  )\n})\nconst isPreparingInputDownloads = computed(\n  () => requiredInputDownloads.value.length > 0\n)\nconst isFinalizingInputDownloads = computed(() =>\n  requiredInputDownloads.value.every(({ status }) => status === 'completed')\n)\nconst inputDownloadProgress = computed(() => {\n  const progress = requiredInputDownloads.value.map(\n    (download) => download.progress\n  )\n  if (!progress.length || progress.some((value) => value === null)) return null\n  return Math.round(\n    (progress.reduce<number>((sum, value) => sum + (value ?? 0), 0) /\n      progress.length) *\n      100\n  )\n})\nconst inputDownloadLabel = computed(() =>\n  isFinalizingInputDownloads.value\n    ? t('linearMode.inputDownloads.finalizing')\n    : t(\n        'linearMode.inputDownloads.downloading',\n        { count: requiredInputDownloads.value.length },\n        requiredInputDownloads.value.length\n      )\n)\nconst runButtonIconClass = computed(() =>\n  isPreparingInputDownloads.value\n    ? 'icon-[lucide--loader-circle] animate-spin'\n    : hasMissingError.value\n      ? 'icon-[lucide--triangle-alert]'\n      : 'icon-[lucide--play]'\n)\nconst showRunErrorWarning = computed(\n  () =>\n    hasAnyError.value &&\n    toValue(canRunWorkflows) &&\n    toValue(overlayMessage).trim().length > 0\n)\n\n//TODO: refactor out of this file.\n//code length is small, but changes should propagate\nasync function runButtonClick(e: Event) {\n  try {\n    pendingJobQueues.value += 1\n    resetJobToastTimeout()\n    const isShiftPressed = 'shiftKey' in e && e.shiftKey\n    const commandId = isShiftPressed\n      ? 'Comfy.QueuePromptFront'\n      : 'Comfy.QueuePrompt'\n\n    if (batchCount.value > 1) {\n      useTelemetry()?.trackUiButtonClicked({\n        button_id: 'queue_run_multiple_batches_submitted',\n        element_group: 'app_mode'\n      })\n    }\n    await commandStore.execute(commandId, {\n      metadata: {\n        subscribe_to_run: false,\n        trigger_source: 'linear'\n      }\n    })\n  } finally {\n    //TODO: Error state indicator for failed queue?\n    pendingJobQueues.value -= 1\n  }\n}\nfunction handleDragDrop() {\n  return widgetListRef.value?.handleDragDrop()\n}\n\nfunction replayAppModeTour() {\n  useOnboardingTourStore().replayTour('appMode')\n}\n</script>\n<template>\n  <div\n    v-if=\"!isBuilderMode && hasOutputs\"\n    class=\"flex h-full min-w-80 flex-col\"\n    v-bind=\"$attrs\"\n  >\n    <section\n      v-if=\"!mobile\"\n      data-testid=\"linear-workflow-info\"\n      class=\"flex h-12 items-center gap-2 border-x border-border-subtle bg-comfy-menu-bg px-4 py-2 contain-size\"\n    >\n      <span\n        class=\"min-w-0 flex-1 truncate font-bold\"\n        v-text=\"workflowStore.activeWorkflow?.filename\"\n      />\n      <Button\n        :tooltip=\"t('onboardingCoachmarks.appMode.replay')\"\n        tooltip-side=\"bottom\"\n        variant=\"textonly\"\n        size=\"icon\"\n        :aria-label=\"t('onboardingCoachmarks.appMode.replay')\"\n        class=\"rounded-lg border border-solid border-border-default text-muted-foreground hover:border-interface-stroke hover:text-base-foreground\"\n        @click=\"replayAppModeTour\"\n      >\n        <i class=\"icon-[lucide--circle-question-mark] size-4\" />\n      </Button>\n    </section>\n    <div\n      class=\"flex h-full flex-col gap-2 border-x border-interface-stroke bg-comfy-menu-bg px-2 md:border-y\"\n    >\n      <section\n        v-coachmark=\"COACH_IDS.inputsList\"\n        data-testid=\"linear-widgets\"\n        class=\"grow scroll-shadows-comfy-menu-bg overflow-y-auto contain-size\"\n      >\n        <AppModeWidgetList ref=\"widgetListRef\" :mobile />\n      </section>\n      <Teleport\n        v-if=\"!jobToastTimeout || pendingJobQueues > 0\"\n        defer\n        :disabled=\"mobile\"\n        :to=\"toastTo\"\n      >\n        <div\n          class=\"flex h-10 items-center gap-2 rounded-lg bg-base-foreground p-1 pr-2 text-base-background md:h-8 md:bg-secondary-background md:text-base-foreground\"\n        >\n          <template v-if=\"pendingJobQueues === 0\">\n            <i\n              class=\"icon-[lucide--check] size-5 not-md:bg-success-background\"\n            />\n            <span class=\"mr-auto\" v-text=\"t('queue.jobAddedToQueue')\" />\n            <Button\n              v-if=\"mobile\"\n              variant=\"inverted\"\n              @click=\"$emit('navigateOutputs')\"\n            >\n              {{ t('linearMode.viewJob') }}\n            </Button>\n          </template>\n          <template v-else>\n            <Loader size=\"sm\" />\n            <span v-text=\"t('queue.jobQueueing')\" />\n          </template>\n        </div>\n      </Teleport>\n      <section\n        v-if=\"isPreparingInputDownloads\"\n        :id=\"linearInputDownloadStatusId\"\n        role=\"status\"\n        data-testid=\"linear-input-download-status\"\n        class=\"mx-2 flex flex-col gap-2 rounded-lg border border-border-default bg-base-background p-3 text-sm\"\n      >\n        <div class=\"flex items-center gap-2\">\n          <Loader size=\"sm\" />\n          <span class=\"min-w-0 flex-1\" v-text=\"inputDownloadLabel\" />\n          <span\n            v-if=\"inputDownloadProgress !== null\"\n            class=\"text-muted-foreground tabular-nums\"\n            v-text=\"`${inputDownloadProgress}%`\"\n          />\n        </div>\n        <span\n          role=\"progressbar\"\n          :aria-label=\"inputDownloadLabel\"\n          aria-valuemin=\"0\"\n          aria-valuemax=\"100\"\n          :aria-valuenow=\"inputDownloadProgress ?? undefined\"\n          class=\"block h-1 overflow-hidden rounded-full bg-secondary-background\"\n        >\n          <span\n            :class=\"\n              cn(\n                'block h-full rounded-full bg-primary-background transition-[width]',\n                inputDownloadProgress === null && 'w-1/3 animate-pulse'\n              )\n            \"\n            :style=\"\n              inputDownloadProgress === null\n                ? undefined\n                : { width: `${inputDownloadProgress}%` }\n            \"\n          />\n        </span>\n      </section>\n      <PartnerNodesList v-if=\"!mobile\" />\n      <section\n        v-if=\"mobile\"\n        :data-testid=\"linearRunButtonTestId\"\n        class=\"border-t border-node-component-border p-4 pb-6\"\n      >\n        <LinearRunErrorWarning v-if=\"showRunErrorWarning\" />\n        <div v-coachmark=\"COACH_IDS.appRunButton\">\n          <SubscribeToRunButton\n            v-if=\"showsCloudSubscribePrompt\"\n            class=\"mt-4 w-full\"\n          />\n          <div v-else class=\"mt-4 flex\">\n            <PartnerNodesList mobile />\n            <Popover side=\"top\" @open-auto-focus.prevent>\n              <template #button>\n                <Button size=\"lg\" class=\"-mr-3 pr-7\">\n                  <i\n                    v-if=\"batchCount == 1\"\n                    class=\"icon-[lucide--chevron-down]\"\n                  />\n                  <div v-else class=\"tabular-nums\" v-text=\"`${batchCount}x`\" />\n                </Button>\n              </template>\n              <div\n                class=\"m-1 mb-2 text-node-component-slot-text\"\n                v-text=\"t('linearMode.runCount')\"\n              />\n              <ScrubableNumberInput\n                v-model=\"batchCount\"\n                :aria-label=\"t('linearMode.runCount')\"\n                :min=\"1\"\n                :max=\"settingStore.get('Comfy.QueueButton.BatchCountLimit')\"\n                class=\"h-10 min-w-40\"\n              />\n            </Popover>\n            <Button\n              variant=\"inverted\"\n              class=\"grow\"\n              size=\"lg\"\n              :aria-describedby=\"\n                isPreparingInputDownloads\n                  ? linearInputDownloadStatusId\n                  : showRunErrorWarning\n                    ? LINEAR_RUN_ERROR_WARNING_DESCRIPTION_ID\n                    : undefined\n              \"\n              :disabled=\"isPreparingInputDownloads\"\n              @click=\"runButtonClick\"\n            >\n              <i\n                aria-hidden=\"true\"\n                :class=\"runButtonIconClass\"\n                data-testid=\"linear-run-button-icon\"\n              />\n              {{ t('menu.run') }}\n            </Button>\n          </div>\n        </div>\n      </section>\n      <section\n        v-else\n        :data-testid=\"linearRunButtonTestId\"\n        class=\"border-t border-node-component-border p-4 pb-6\"\n      >\n        <LinearRunErrorWarning v-if=\"showRunErrorWarning\" />\n        <div v-coachmark=\"COACH_IDS.appRunButton\">\n          <div\n            class=\"m-1 mb-2 text-node-component-slot-text\"\n            v-text=\"t('linearMode.runCount')\"\n          />\n          <ScrubableNumberInput\n            v-model=\"batchCount\"\n            :aria-label=\"t('linearMode.runCount')\"\n            :min=\"1\"\n            :max=\"settingStore.get('Comfy.QueueButton.BatchCountLimit')\"\n            class=\"h-7 min-w-40\"\n          />\n          <SubscribeToRunButton\n            v-if=\"showsCloudSubscribePrompt\"\n            class=\"mt-4 w-full\"\n          />\n          <Button\n            v-else\n            variant=\"inverted\"\n            class=\"mt-4 w-full text-sm\"\n            size=\"lg\"\n            :aria-describedby=\"\n              isPreparingInputDownloads\n                ? linearInputDownloadStatusId\n                : showRunErrorWarning\n                  ? LINEAR_RUN_ERROR_WARNING_DESCRIPTION_ID\n                  : undefined\n            \"\n            :disabled=\"isPreparingInputDownloads\"\n            @click=\"runButtonClick\"\n          >\n            <i\n              aria-hidden=\"true\"\n              :class=\"runButtonIconClass\"\n              data-testid=\"linear-run-button-icon\"\n            />\n            {{ t('menu.run') }}\n          </Button>\n        </div>\n        <FreeTierQuota />\n      </section>\n    </div>\n  </div>\n  <div\n    v-else-if=\"mobile\"\n    class=\"flex size-full items-center bg-base-background p-4 text-center\"\n    v-text=\"t('linearMode.mobileNoWorkflow')\"\n  />\n</template>\n","<script setup lang=\"ts\">\nimport { computed, ref, useTemplateRef } from 'vue'\n\nconst zoomPane = useTemplateRef('zoomPane')\n\nconst zoom = ref(1.0)\nconst panX = ref(0.0)\nconst panY = ref(0.0)\n\nfunction handleWheel(e: WheelEvent) {\n  const zoomPaneEl = zoomPane.value\n  if (!zoomPaneEl || (e.deltaY < 0 ? zoom.value > 1200 : zoom.value < -500))\n    return\n\n  zoom.value -= e.deltaY\n  const { x, y, width, height } = zoomPaneEl.getBoundingClientRect()\n  const offsetX = e.clientX - x - width / 2\n  const offsetY = e.clientY - y - height / 2\n  const scaler = 1.1 ** (e.deltaY / -30)\n\n  panY.value = panY.value * scaler - offsetY * (scaler - 1)\n  panX.value = panX.value * scaler - offsetX * (scaler - 1)\n}\n\nlet dragging = false\nfunction handleDown(e: PointerEvent) {\n  if (e.button !== 0 && e.button !== 1) return\n\n  const zoomPaneEl = zoomPane.value\n  if (!zoomPaneEl) return\n  zoomPaneEl.parentElement?.focus()\n\n  zoomPaneEl.setPointerCapture(e.pointerId)\n  dragging = true\n}\nfunction handleMove(e: PointerEvent) {\n  if (!dragging) return\n  panX.value += e.movementX\n  panY.value += e.movementY\n}\n\nconst transform = computed(() => {\n  const scale = 1.1 ** (zoom.value / 30)\n  const matrix = [scale, 0, 0, scale, panX.value, panY.value]\n  return `matrix(${matrix.join(',')})`\n})\n</script>\n<template>\n  <div\n    ref=\"zoomPane\"\n    class=\"place-content-center contain-size\"\n    @wheel=\"handleWheel\"\n    @pointerdown.prevent=\"handleDown\"\n    @pointermove=\"handleMove\"\n    @pointerup=\"dragging = false\"\n    @pointercancel=\"dragging = false\"\n  >\n    <slot :style=\"{ transform }\" />\n  </div>\n</template>\n","import type { ComfyNodeDefImpl } from '@/stores/nodeDefStore'\n\ntype ExecutionStatusKey =\n  | 'generating'\n  | 'saving'\n  | 'loading'\n  | 'encoding'\n  | 'decoding'\n  | 'processing'\n  | 'resizing'\n  | 'generatingVideo'\n  | 'processingVideo'\n  | 'training'\n\n/**\n * Specific status messages for nodes that can't be matched by PascalCase\n * identifier patterns (e.g. unconventional naming, spaces).\n */\nconst statusMap: Record<string, ExecutionStatusKey> = {\n  // Video utility nodes with non-standard naming\n  'Video Slice': 'processingVideo',\n  GetVideoComponents: 'processingVideo',\n  CreateVideo: 'processingVideo',\n\n  // Training\n  TrainLoraNode: 'training'\n}\n\n/**\n * Matches a PascalCase identifier within a node type name.\n */\nfunction pascalId(...ids: string[]): RegExp {\n  return new RegExp('(?:' + ids.join('|') + ')(?![a-z])')\n}\n\nconst identifierRules: [RegExp, ExecutionStatusKey][] = [\n  [pascalId('Save', 'Preview'), 'saving'],\n  [pascalId('Load', 'Loader'), 'loading'],\n  [pascalId('Encode'), 'encoding'],\n  [pascalId('Decode'), 'decoding'],\n  [pascalId('Compile', 'Conditioning', 'Merge'), 'processing'],\n  [pascalId('Upscale', 'Resize'), 'resizing'],\n  [pascalId('ToVideo'), 'generatingVideo'],\n  [pascalId('Sampler'), 'generating']\n]\n\nexport function getExecutionStatusMessage(\n  t: (key: string) => string,\n  nodeType: string,\n  nodeDef?: ComfyNodeDefImpl | null,\n  properties?: Record<string, unknown>\n): string | null {\n  const customMessage = properties?.['Execution Message']\n  if (typeof customMessage === 'string' && customMessage.trim()) {\n    return customMessage.trim()\n  }\n\n  if (nodeType in statusMap) return t(`execution.${statusMap[nodeType]}`)\n\n  for (const [pattern, key] of identifierRules) {\n    if (pattern.test(nodeType)) return t(`execution.${key}`)\n  }\n\n  if (nodeDef?.api_node) return t('execution.processing')\n\n  return null\n}\n","import { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { getExecutionStatusMessage } from '@/renderer/extensions/linearMode/getExecutionStatusMessage'\nimport { app } from '@/scripts/app'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useNodeDefStore } from '@/stores/nodeDefStore'\nimport {\n  executionIdToNodeLocatorId,\n  getNodeByLocatorId\n} from '@/utils/graphTraversalUtil'\n\nfunction resolveStatus(\n  t: (key: string) => string,\n  nodeDefStore: ReturnType<typeof useNodeDefStore>,\n  executionId: string | number\n): string | null {\n  const locatorId = executionIdToNodeLocatorId(app.rootGraph, executionId)\n  if (!locatorId) return null\n\n  const node = getNodeByLocatorId(app.rootGraph, locatorId)\n  const nodeType = node?.type\n  if (!nodeType) return null\n\n  const nodeDef = nodeDefStore.nodeDefsByName[nodeType] ?? null\n  return getExecutionStatusMessage(t, nodeType, nodeDef, node.properties)\n}\n\nexport function useExecutionStatus() {\n  const { t } = useI18n()\n  const executionStore = useExecutionStore()\n  const nodeDefStore = useNodeDefStore()\n\n  const executionStatusMessage = computed<string | null>(() => {\n    const executionId = executionStore.executingNodeId\n    if (!executionId) return null\n    return resolveStatus(t, nodeDefStore, executionId) || t('execution.running')\n  })\n\n  return { executionStatusMessage }\n}\n","<script setup lang=\"ts\">\nimport { ref, useTemplateRef } from 'vue'\n\nimport ZoomPane from '@/components/ui/ZoomPane.vue'\nimport { useExecutionStatus } from '@/renderer/extensions/linearMode/useExecutionStatus'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { executionStatusMessage } = useExecutionStatus()\n\ndefineOptions({ inheritAttrs: false })\n\nconst { src, showSize = true } = defineProps<{\n  src: string\n  mobile?: boolean\n  label?: string\n  showSize?: boolean\n}>()\n\nconst imageRef = useTemplateRef('imageRef')\nconst width = ref<number | null>(null)\nconst height = ref<number | null>(null)\n\nfunction onImageLoad() {\n  if (!imageRef.value || !showSize) return\n  width.value = imageRef.value.naturalWidth\n  height.value = imageRef.value.naturalHeight\n}\n</script>\n<template>\n  <ZoomPane\n    v-if=\"!mobile\"\n    v-slot=\"slotProps\"\n    :class=\"cn('w-full flex-1', $attrs.class as string)\"\n  >\n    <img\n      ref=\"imageRef\"\n      :src\n      v-bind=\"slotProps\"\n      class=\"size-full object-contain\"\n      @load=\"onImageLoad\"\n    />\n  </ZoomPane>\n  <img\n    v-else\n    ref=\"imageRef\"\n    class=\"grow object-contain contain-size\"\n    :src\n    @load=\"onImageLoad\"\n  />\n  <span\n    v-if=\"executionStatusMessage\"\n    class=\"animate-pulse self-center text-muted md:z-10\"\n  >\n    {{ executionStatusMessage }}\n  </span>\n  <span v-else-if=\"width && height\" class=\"self-center md:z-10\">\n    {{ `${width} x ${height}` }}\n    <template v-if=\"label\"> | {{ label }}</template>\n  </span>\n</template>\n","<script setup lang=\"ts\">\nimport { useExecutionStatus } from '@/renderer/extensions/linearMode/useExecutionStatus'\n\nconst { executionStatusMessage } = useExecutionStatus()\n</script>\n<template>\n  <div\n    class=\"sz-full flex min-h-0 flex-1 flex-col items-center justify-center gap-3\"\n  >\n    <div class=\"flex h-full items-center justify-center\">\n      <div\n        class=\"skeleton-shimmer aspect-square size-[min(50vw,50vh)] rounded-lg\"\n      />\n    </div>\n\n    <span\n      v-if=\"executionStatusMessage\"\n      class=\"animate-pulse text-sm text-muted\"\n    >\n      {{ executionStatusMessage }}\n    </span>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { storeToRefs } from 'pinia'\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { useEnterBuilder } from '@/components/builder/useEnterBuilder'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useWorkflowTemplateSelectorDialog } from '@/composables/useWorkflowTemplateSelectorDialog'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useAppModeStore } from '@/stores/appModeStore'\n\nconst { t } = useI18n()\nconst { setMode } = useAppMode()\nconst appModeStore = useAppModeStore()\nconst { enterBuilder } = useEnterBuilder()\nconst { hasOutputs, hasNodes } = storeToRefs(appModeStore)\nconst workflowStore = useWorkflowStore()\nconst isAppDefault = computed(\n  () => workflowStore.activeWorkflow?.initialMode === 'app'\n)\nconst templateSelectorDialog = useWorkflowTemplateSelectorDialog()\n</script>\n\n<template>\n  <div\n    role=\"article\"\n    data-testid=\"linear-welcome\"\n    class=\"mx-auto flex h-full max-w-lg flex-col items-center justify-center gap-6 p-8 text-center\"\n  >\n    <div class=\"flex flex-col gap-2\">\n      <h2 class=\"text-3xl font-semibold text-muted-foreground\">\n        {{ t('linearMode.welcome.title') }}\n      </h2>\n    </div>\n\n    <div class=\"flex max-w-md flex-col gap-3 text-[14px] text-muted-foreground\">\n      <p class=\"mt-0\">{{ t('linearMode.welcome.message') }}</p>\n      <p class=\"mt-0\">{{ t('linearMode.welcome.controls') }}</p>\n      <p class=\"mt-0\">{{ t('linearMode.welcome.sharing') }}</p>\n    </div>\n    <div v-if=\"hasOutputs\" class=\"flex flex-row gap-2 text-[14px]\">\n      <p class=\"mt-0 text-base-foreground\">\n        <i18n-t keypath=\"linearMode.welcome.getStarted\" tag=\"span\">\n          <template #runButton>\n            <span\n              class=\"mx-0.5 inline-flex -translate-y-0.5 transform cursor-default items-center rounded-sm bg-base-foreground px-3.5 py-0.5 text-2xs font-medium text-base-background\"\n            >\n              {{ t('menu.run') }}\n            </span>\n          </template>\n        </i18n-t>\n      </p>\n    </div>\n    <template v-else>\n      <p\n        v-if=\"!hasNodes\"\n        data-testid=\"linear-welcome-empty-workflow\"\n        class=\"mt-0 max-w-md text-sm text-base-foreground\"\n      >\n        {{ t('linearMode.emptyWorkflowExplanation') }}\n      </p>\n      <p\n        v-if=\"hasNodes && isAppDefault\"\n        class=\"mt-0 max-w-md text-sm text-base-foreground\"\n      >\n        <i18n-t keypath=\"linearMode.welcome.noOutputs\" tag=\"span\">\n          <template #count>\n            <span class=\"font-bold text-warning-background\">{{\n              t('linearMode.welcome.oneOutput')\n            }}</span>\n          </template>\n        </i18n-t>\n      </p>\n      <div class=\"flex flex-row gap-2\">\n        <Button\n          data-testid=\"linear-welcome-back-to-workflow\"\n          variant=\"textonly\"\n          size=\"lg\"\n          @click=\"setMode('graph')\"\n        >\n          {{ t('linearMode.backToWorkflow') }}\n        </Button>\n        <Button\n          v-if=\"!hasNodes\"\n          data-testid=\"linear-welcome-load-template\"\n          variant=\"secondary\"\n          size=\"lg\"\n          @click=\"templateSelectorDialog.show('appbuilder')\"\n        >\n          {{ t('linearMode.loadTemplate') }}\n        </Button>\n        <Button\n          v-else\n          data-testid=\"linear-welcome-build-app\"\n          variant=\"primary\"\n          size=\"lg\"\n          @click=\"enterBuilder\"\n        >\n          <i class=\"icon-[lucide--hammer]\" />\n          {{ t('linearMode.welcome.buildApp') }}\n          <div\n            class=\"absolute -top-2 -right-2 rounded-full bg-base-foreground px-1 text-2xs text-base-background\"\n          >\n            {{ t('g.experimental') }}\n          </div>\n        </Button>\n      </div>\n    </template>\n  </div>\n</template>\n","import type { NodeExecutionOutput } from '@/platform/remote/comfyui/execution/types'\nimport { parseNodeOutput } from '@/stores/resultItemParsing'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\n\nexport function flattenNodeOutput([nodeId, nodeOutput]: [\n  string | number,\n  NodeExecutionOutput | null | undefined\n]): AugmentedResultItem[] {\n  return parseNodeOutput(nodeId, nodeOutput)\n}\n","<script setup lang=\"ts\">\nimport { ref, useTemplateRef } from 'vue'\n\nconst { src } = defineProps<{\n  src: string\n  label?: string\n}>()\n\nconst videoRef = useTemplateRef('videoRef')\nconst width = ref('')\nconst height = ref('')\n</script>\n<template>\n  <video\n    ref=\"videoRef\"\n    :src\n    controls\n    v-bind=\"$attrs\"\n    @loadedmetadata=\"\n      () => {\n        if (!videoRef) return\n        width = `${videoRef.videoWidth}`\n        height = `${videoRef.videoHeight}`\n      }\n    \"\n  />\n  <span class=\"z-10 self-center\">\n    {{ `${width} x ${height}` }}\n    <template v-if=\"label\"> | {{ label }}</template>\n  </span>\n</template>\n","import { t } from '@/i18n'\n\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { isImageResult, isTextResult, isVideoResult } from '@/utils/resultItem'\n\ntype StatItem = { content?: string; iconClass?: string }\nexport const mediaTypes: Record<string, StatItem> = {\n  '3d': {\n    content: t('sideToolbar.mediaAssets.filter3D'),\n    iconClass: 'icon-[lucide--box]'\n  },\n  audio: {\n    content: t('sideToolbar.mediaAssets.filterAudio'),\n    iconClass: 'icon-[lucide--audio-lines]'\n  },\n  images: {\n    content: t('sideToolbar.mediaAssets.filterImage'),\n    iconClass: 'icon-[lucide--image]'\n  },\n  text: {\n    content: t('sideToolbar.mediaAssets.filterText'),\n    iconClass: 'icon-[lucide--text]'\n  },\n  video: {\n    content: t('sideToolbar.mediaAssets.filterVideo'),\n    iconClass: 'icon-[lucide--video]'\n  }\n}\n\nexport function getMediaType(output?: AugmentedResultItem) {\n  if (!output) return ''\n  if (isVideoResult(output)) return 'video'\n  if (isImageResult(output)) return 'images'\n  if (isTextResult(output)) return 'text'\n  return output.mediaType\n}\n","<script setup lang=\"ts\">\nimport { computed, defineAsyncComponent, useAttrs } from 'vue'\n\nimport { useTextFileContent } from '@/composables/useTextFileContent'\nimport ImagePreview from '@/renderer/extensions/linearMode/ImagePreview.vue'\nimport VideoPreview from '@/renderer/extensions/linearMode/VideoPreview.vue'\nimport { getMediaType } from '@/renderer/extensions/linearMode/mediaTypes'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemUrl } from '@/utils/resultItemUrl'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst Preview3d = defineAsyncComponent(\n  () => import('@/renderer/extensions/linearMode/Preview3d.vue')\n)\n\ndefineOptions({ inheritAttrs: false })\n\nconst { output } = defineProps<{\n  output: AugmentedResultItem\n  mobile?: boolean\n}>()\n\nconst attrs = useAttrs()\nconst mediaType = computed(() => getMediaType(output))\nconst outputLabel = computed(\n  () => output.display_name?.trim() || output.filename\n)\nconst { textContent } = useTextFileContent(() =>\n  mediaType.value === 'text'\n    ? { content: output.content, url: resultItemUrl(output) }\n    : undefined\n)\nconst src = computed(() => resultItemUrl(output))\n</script>\n<template>\n  <template v-if=\"mediaType === 'images' || mediaType === 'video'\">\n    <ImagePreview\n      v-if=\"mediaType === 'images'\"\n      :class=\"attrs.class as string\"\n      :mobile\n      :src\n      :label=\"outputLabel\"\n    />\n    <VideoPreview\n      v-else\n      :src\n      :label=\"outputLabel\"\n      :class=\"\n        cn(\n          'flex-1 object-contain md:p-3 md:contain-size',\n          attrs.class as string\n        )\n      \"\n    />\n  </template>\n  <template v-else>\n    <audio\n      v-if=\"mediaType === 'audio'\"\n      :class=\"cn('m-auto w-full', attrs.class as string)\"\n      controls\n      :src\n    />\n    <article\n      v-else-if=\"mediaType === 'text'\"\n      :class=\"\n        cn(\n          'm-auto my-12 size-full max-w-2xl scroll-shadows-secondary-background overflow-y-auto rounded-lg bg-secondary-background p-4 whitespace-pre-wrap',\n          attrs.class as string\n        )\n      \"\n      v-text=\"textContent\"\n    />\n    <Preview3d\n      v-else-if=\"mediaType === '3d'\"\n      :class=\"attrs.class as string\"\n      :model-url=\"src\"\n    />\n    <span v-if=\"outputLabel\" class=\"self-center text-sm\">\n      {{ outputLabel }}\n    </span>\n  </template>\n</template>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\nimport { storeToRefs } from 'pinia'\n\nimport Button from '@/components/ui/button/Button.vue'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { flattenNodeOutput } from '@/renderer/extensions/linearMode/flattenNodeOutput'\nimport MediaOutputPreview from '@/renderer/extensions/linearMode/MediaOutputPreview.vue'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useNodeOutputStore } from '@/stores/nodeOutputStore'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\n\nconst { t } = useI18n()\nconst { setMode } = useAppMode()\nconst appModeStore = useAppModeStore()\nconst { hasOutputs } = storeToRefs(appModeStore)\nconst nodeOutputStore = useNodeOutputStore()\nconst { nodeIdToNodeLocatorId } = useWorkflowStore()\n\nconst existingOutput = computed(() => {\n  for (const nodeId of appModeStore.selectedOutputs) {\n    const locatorId = nodeIdToNodeLocatorId(nodeId)\n    const nodeOutput = nodeOutputStore.nodeOutputs[locatorId]\n    if (!nodeOutput) continue\n    const results = flattenNodeOutput([nodeId, nodeOutput])\n    if (results.length > 0) return results[0]\n  }\n  return undefined\n})\n</script>\n\n<template>\n  <MediaOutputPreview\n    v-if=\"existingOutput\"\n    :output=\"existingOutput\"\n    class=\"px-12 py-24\"\n  />\n  <div\n    v-else-if=\"hasOutputs\"\n    role=\"article\"\n    data-testid=\"linear-arrange-preview\"\n    class=\"mx-auto flex h-full w-3/4 flex-col items-center justify-center gap-6 p-8\"\n  >\n    <div\n      class=\"flex h-4/5 w-full flex-col items-center justify-center rounded-2xl border-2 border-dashed border-warning-background p-12\"\n    >\n      <p class=\"mb-0 font-bold text-base-foreground\">\n        {{ t('linearMode.arrange.outputs') }}\n      </p>\n      <p class=\"text-center\">{{ t('linearMode.arrange.resultsLabel') }}</p>\n    </div>\n  </div>\n  <div\n    v-else\n    role=\"article\"\n    data-testid=\"linear-arrange-no-outputs\"\n    class=\"mx-auto flex h-full w-lg flex-col items-center justify-center gap-6 p-8 text-center\"\n  >\n    <p class=\"m-0 text-base-foreground\">\n      {{ t('linearMode.arrange.noOutputs') }}\n    </p>\n\n    <div class=\"flex w-lg flex-col gap-1 text-[14px] text-muted-foreground\">\n      <p class=\"mt-0 p-0\">{{ t('linearMode.arrange.switchToOutputs') }}</p>\n\n      <i18n-t keypath=\"linearMode.arrange.connectAtLeastOne\" tag=\"div\">\n        <template #atLeastOne>\n          <span class=\"font-bold italic\">\n            {{ t('linearMode.arrange.atLeastOne') }}\n          </span>\n        </template>\n      </i18n-t>\n\n      <p class=\"mt-0 p-0\">{{ t('linearMode.arrange.outputExamples') }}</p>\n    </div>\n    <div class=\"flex flex-row gap-2\">\n      <Button\n        variant=\"primary\"\n        size=\"lg\"\n        data-testid=\"linear-arrange-switch-to-outputs\"\n        @click=\"setMode('builder:outputs')\"\n      >\n        {{ t('linearMode.arrange.switchToOutputsButton') }}\n      </Button>\n    </div>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { useI18n } from 'vue-i18n'\n\nimport Loader from '@/components/loader/Loader.vue'\nimport Popover from '@/components/ui/Popover.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useQueueStore } from '@/stores/queueStore'\n\nconst { queueCount } = defineProps<{\n  queueCount: number\n}>()\n\nconst { t } = useI18n()\nconst commandStore = useCommandStore()\nconst queueStore = useQueueStore()\n\nfunction clearQueue(close: () => void) {\n  void commandStore.execute('Comfy.ClearPendingTasks')\n  close()\n}\n</script>\n<template>\n  <div\n    class=\"relative shrink-0 border-2 border-transparent p-1\"\n    data-testid=\"linear-job\"\n  >\n    <Popover side=\"top\" :show-arrow=\"false\" @focus-outside.prevent>\n      <template #button>\n        <Button\n          :tooltip=\"t('linearMode.queue.clickToClear')\"\n          :aria-label=\"t('linearMode.queue.clickToClear')\"\n          variant=\"textonly\"\n          size=\"unset\"\n          class=\"flex size-10 items-center justify-center rounded-sm bg-secondary-background\"\n        >\n          <Loader\n            :variant=\"\n              queueStore.runningTasks.length ? 'loader-circle' : 'loader'\n            \"\n            size=\"sm\"\n            class=\"text-muted-foreground\"\n          />\n        </Button>\n      </template>\n      <template #default=\"{ close }\">\n        <Button\n          :disabled=\"queueCount === 0\"\n          variant=\"textonly\"\n          class=\"px-4 text-sm text-destructive-background\"\n          @click=\"clearQueue(close)\"\n        >\n          <i class=\"icon-[lucide--list-x]\" />\n          {{ t('linearMode.queue.clear') }}\n        </Button>\n      </template>\n    </Popover>\n    <div\n      v-if=\"queueCount > 1\"\n      aria-hidden=\"true\"\n      data-testid=\"linear-job-badge\"\n      class=\"absolute top-0 right-0 flex h-4 min-w-4 items-center justify-center rounded-full bg-primary-background text-xs text-text-primary\"\n      v-text=\"queueCount\"\n    />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\n\nimport {\n  getMediaType,\n  mediaTypes\n} from '@/renderer/extensions/linearMode/mediaTypes'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemUrl } from '@/utils/resultItemUrl'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nimport VideoPlayOverlay from '@/platform/assets/components/VideoPlayOverlay.vue'\n\nconst { output } = defineProps<{\n  output: AugmentedResultItem\n}>()\n\nconst src = computed(() => resultItemUrl(output))\n</script>\n<template>\n  <img\n    v-if=\"getMediaType(output) === 'images'\"\n    data-testid=\"linear-image-output\"\n    class=\"block size-10 rounded-sm bg-secondary-background object-cover\"\n    loading=\"lazy\"\n    width=\"40\"\n    height=\"40\"\n    :src\n  />\n  <template v-else-if=\"getMediaType(output) === 'video'\">\n    <video\n      data-testid=\"linear-video-output\"\n      class=\"pointer-events-none block size-10 rounded-sm bg-secondary-background object-cover\"\n      preload=\"metadata\"\n      width=\"40\"\n      height=\"40\"\n      :src\n    />\n    <VideoPlayOverlay size=\"sm\" />\n  </template>\n  <i\n    v-else\n    :class=\"cn(mediaTypes[getMediaType(output)]?.iconClass, 'block size-10')\"\n  />\n</template>\n","import { defineStore } from 'pinia'\nimport { computed, ref, shallowRef, watch } from 'vue'\n\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { flattenNodeOutput } from '@/renderer/extensions/linearMode/flattenNodeOutput'\nimport type { InProgressItem } from '@/renderer/extensions/linearMode/linearModeTypes'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport type {\n  ExecutedWsMessage,\n  JobId\n} from '@/platform/remote/comfyui/execution/types'\nimport { api } from '@/scripts/api'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useJobPreviewStore } from '@/stores/jobPreviewStore'\n\nexport const useLinearOutputStore = defineStore('linearOutput', () => {\n  const { isAppMode } = useAppMode()\n  const appModeStore = useAppModeStore()\n  const executionStore = useExecutionStore()\n  const jobPreviewStore = useJobPreviewStore()\n  const workflowStore = useWorkflowStore()\n\n  const inProgressItems = ref<InProgressItem[]>([])\n  const resolvedOutputsCache = new Map<string, AugmentedResultItem[]>()\n  const selectedId = ref<string | null>(null)\n  const isFollowing = ref(true)\n  const trackedJobId = ref<JobId | null>(null)\n  const pendingResolve = ref(new Set<JobId>())\n  const executedNodeIds = new Set<string>()\n\n  const activeWorkflowInProgressItems = computed(() => {\n    const path = workflowStore.activeWorkflow?.path\n    if (!path) return []\n    const all = inProgressItems.value\n    return all.filter(\n      (i) => executionStore.jobIdToSessionWorkflowPath.get(i.jobId) === path\n    )\n  })\n\n  let nextSeq = 0\n\n  function makeItemId(jobId: JobId): string {\n    return `job-${jobId}-${nextSeq++}`\n  }\n\n  function replaceItem(\n    id: string,\n    updater: (item: InProgressItem) => InProgressItem\n  ) {\n    inProgressItems.value = inProgressItems.value.map((i) =>\n      i.id === id ? updater(i) : i\n    )\n  }\n\n  // --- Actions ---\n\n  const currentSkeletonId = shallowRef<string | null>(null)\n\n  function onJobStart(jobId: JobId) {\n    executedNodeIds.clear()\n\n    const item: InProgressItem = {\n      id: makeItemId(jobId),\n      jobId,\n      state: 'skeleton'\n    }\n    currentSkeletonId.value = item.id\n    inProgressItems.value = [item, ...inProgressItems.value]\n\n    trackedJobId.value = jobId\n    autoSelect(`slot:${item.id}`, jobId)\n  }\n\n  let raf: number | null = null\n  function onLatentPreview(jobId: JobId, url: string, nodeId?: string) {\n    if (nodeId && executedNodeIds.has(nodeId)) return\n\n    // Issue in Firefox where it doesnt seem to always re-render, wrapping in RAF fixes it\n    if (raf) cancelAnimationFrame(raf)\n    raf = requestAnimationFrame(() => {\n      const existing = inProgressItems.value.find(\n        (i) => i.id === currentSkeletonId.value && i.jobId === jobId\n      )\n\n      if (existing) {\n        const wasEmpty = existing.state === 'skeleton'\n        replaceItem(existing.id, (i) => ({\n          ...i,\n          state: 'latent',\n          latentPreviewUrl: url\n        }))\n        if (wasEmpty) autoSelect(`slot:${existing.id}`, jobId)\n        return\n      }\n\n      // Only create on-demand for the tracked job\n      if (jobId !== trackedJobId.value) return\n\n      const item: InProgressItem = {\n        id: makeItemId(jobId),\n        jobId,\n        state: 'latent',\n        latentPreviewUrl: url\n      }\n      currentSkeletonId.value = item.id\n      inProgressItems.value = [item, ...inProgressItems.value]\n      autoSelect(`slot:${item.id}`, jobId)\n    })\n  }\n\n  function onNodeExecuted(jobId: JobId, detail: ExecutedWsMessage) {\n    const nodeId = String(detail.display_node || detail.node)\n    executedNodeIds.add(nodeId)\n    if (raf) {\n      cancelAnimationFrame(raf)\n      raf = null\n    }\n    const newOutputs = flattenNodeOutput([nodeId, detail.output])\n    if (newOutputs.length === 0) return\n\n    // Skip output items for nodes not flagged as output nodes\n    const outputNodeIds = appModeStore.selectedOutputs\n    if (\n      outputNodeIds.length > 0 &&\n      !outputNodeIds.some((id) => String(id) === nodeId)\n    )\n      return\n\n    const skeletonItem = inProgressItems.value.find(\n      (i) => i.id === currentSkeletonId.value && i.jobId === jobId\n    )\n\n    if (skeletonItem) {\n      const imageItem: InProgressItem = {\n        ...skeletonItem,\n        state: 'image',\n        output: newOutputs[0],\n        latentPreviewUrl: undefined\n      }\n      autoSelect(`slot:${imageItem.id}`, jobId)\n\n      const extras: InProgressItem[] = newOutputs.slice(1).map((o) => ({\n        id: makeItemId(jobId),\n        jobId,\n        state: 'image' as const,\n        output: o\n      }))\n\n      const idx = inProgressItems.value.indexOf(skeletonItem)\n      const arr = [...inProgressItems.value]\n      arr.splice(idx, 1, imageItem, ...extras)\n      currentSkeletonId.value = null\n      inProgressItems.value = arr\n      return\n    }\n\n    // No skeleton — create image items directly (only for tracked job)\n    if (jobId !== trackedJobId.value) return\n\n    const newItems: InProgressItem[] = newOutputs.map((o) => ({\n      id: makeItemId(jobId),\n      jobId,\n      state: 'image' as const,\n      output: o\n    }))\n    autoSelect(`slot:${newItems[0].id}`, jobId)\n    inProgressItems.value = [...newItems, ...inProgressItems.value]\n  }\n\n  function onJobComplete(jobId: JobId) {\n    // On any job complete, remove all pending resolve items.\n    if (pendingResolve.value.size > 0) {\n      for (const oldJobId of pendingResolve.value) {\n        removeJobItems(oldJobId)\n      }\n      pendingResolve.value = new Set()\n    }\n\n    if (raf) {\n      cancelAnimationFrame(raf)\n      raf = null\n    }\n    currentSkeletonId.value = null\n    if (trackedJobId.value === jobId) {\n      trackedJobId.value = null\n    }\n\n    const hasImages = inProgressItems.value.some(\n      (i) => i.jobId === jobId && i.state === 'image'\n    )\n\n    if (hasImages) {\n      // Remove non-image items (skeletons, latents), keep images for absorption\n      inProgressItems.value = inProgressItems.value.filter(\n        (i) => i.jobId !== jobId || i.state === 'image'\n      )\n      pendingResolve.value = new Set([...pendingResolve.value, jobId])\n    } else {\n      removeJobItems(jobId)\n    }\n  }\n\n  function removeJobItems(jobId: JobId) {\n    const removed = inProgressItems.value.filter((i) => i.jobId === jobId)\n    inProgressItems.value = inProgressItems.value.filter(\n      (i) => i.jobId !== jobId\n    )\n\n    if (\n      selectedId.value &&\n      removed.some((i) => `slot:${i.id}` === selectedId.value)\n    ) {\n      selectedId.value = null\n    }\n  }\n\n  function resolveIfReady(jobId: JobId, historyLoaded: boolean) {\n    if (!pendingResolve.value.has(jobId)) return\n    if (!historyLoaded) return\n\n    const next = new Set(pendingResolve.value)\n    next.delete(jobId)\n    pendingResolve.value = next\n\n    removeJobItems(jobId)\n  }\n\n  function select(id: string | null) {\n    selectedId.value = id\n    isFollowing.value = false\n  }\n\n  function selectAsLatest(id: string | null) {\n    selectedId.value = id\n    isFollowing.value = true\n  }\n\n  function isJobForActiveWorkflow(jobId: JobId): boolean {\n    return (\n      executionStore.jobIdToSessionWorkflowPath.get(jobId) ===\n      workflowStore.activeWorkflow?.path\n    )\n  }\n\n  function autoSelect(slotId: string, jobId: JobId) {\n    // Only auto-select if the job belongs to the active workflow\n    if (!isJobForActiveWorkflow(jobId)) return\n\n    const sel = selectedId.value\n    if (!sel || isFollowing.value) {\n      selectedId.value = slotId\n      isFollowing.value = true\n      return\n    }\n    // User is browsing history — don't yank\n  }\n\n  // --- Event bindings (only active in app mode) ---\n\n  function handleExecuted({ detail }: CustomEvent<ExecutedWsMessage>) {\n    const jobId = detail.prompt_id\n    if (jobId !== executionStore.activeJobId) return\n    onNodeExecuted(jobId, detail)\n  }\n\n  // Watch both activeJobId and the path mapping together. The path mapping\n  // may arrive after activeJobId due to a race between WebSocket\n  // (execution_start) and the HTTP response (queuePrompt > storeJob).\n  // Watching both ensures onJobStart fires once the mapping is available.\n  watch(\n    [\n      () => executionStore.activeJobId,\n      () => executionStore.jobIdToSessionWorkflowPath\n    ],\n    ([jobId], [oldJobId]) => {\n      if (!isAppMode.value) return\n      if (oldJobId && oldJobId !== jobId) {\n        onJobComplete(oldJobId)\n      }\n      // Guard with trackedJobId to avoid double-starting when the\n      // path mapping arrives after activeJobId was already set.\n      if (\n        jobId &&\n        trackedJobId.value !== jobId &&\n        isJobForActiveWorkflow(jobId)\n      ) {\n        onJobStart(jobId)\n      }\n    }\n  )\n\n  watch(\n    () => jobPreviewStore.nodePreviewsByPromptId,\n    (previews) => {\n      if (!isAppMode.value) return\n      const jobId = executionStore.activeJobId\n      if (!jobId) return\n      const preview = Object.hasOwn(previews, jobId)\n        ? previews[jobId]\n        : undefined\n      if (preview) onLatentPreview(jobId, preview.url, preview.nodeId)\n    },\n    { deep: true }\n  )\n\n  function reconcileOnEnter() {\n    // Complete any tracked job that finished while we were away.\n    // The activeJobId watcher couldn't fire onJobComplete because\n    // isAppMode was false at the time.\n    if (\n      trackedJobId.value &&\n      trackedJobId.value !== executionStore.activeJobId\n    ) {\n      onJobComplete(trackedJobId.value)\n    }\n    // Start tracking the current job only if it belongs to this\n    // workflow — otherwise we'd adopt another tab's job.\n    if (\n      executionStore.activeJobId &&\n      trackedJobId.value !== executionStore.activeJobId &&\n      isJobForActiveWorkflow(executionStore.activeJobId)\n    ) {\n      onJobStart(executionStore.activeJobId)\n    }\n\n    // Clear stale selection from another workflow's job.\n    if (\n      selectedId.value?.startsWith('slot:') &&\n      trackedJobId.value &&\n      !isJobForActiveWorkflow(trackedJobId.value)\n    ) {\n      selectedId.value = null\n      isFollowing.value = true\n    }\n\n    // Re-apply the latest latent preview that may have arrived while\n    // away, but only for a job belonging to the active workflow.\n    const jobId = trackedJobId.value\n    if (jobId && isJobForActiveWorkflow(jobId)) {\n      const previews = jobPreviewStore.nodePreviewsByPromptId\n      const preview = Object.hasOwn(previews, jobId)\n        ? previews[jobId]\n        : undefined\n      if (preview) onLatentPreview(jobId, preview.url, preview.nodeId)\n    }\n  }\n\n  function cleanupOnLeave() {\n    // If the tracked job already finished (no longer the active job),\n    // complete it now to clean up skeletons/latents. If it's still\n    // running, preserve all items for tab switching.\n    if (\n      trackedJobId.value &&\n      trackedJobId.value !== executionStore.activeJobId\n    ) {\n      onJobComplete(trackedJobId.value)\n    }\n  }\n\n  watch(\n    isAppMode,\n    (active, wasActive) => {\n      if (active) {\n        api.addEventListener('executed', handleExecuted)\n        reconcileOnEnter()\n      } else if (wasActive) {\n        api.removeEventListener('executed', handleExecuted)\n        cleanupOnLeave()\n      }\n    },\n    { immediate: true }\n  )\n\n  return {\n    activeWorkflowInProgressItems,\n    resolvedOutputsCache,\n    selectedId,\n    pendingResolve,\n    select,\n    selectAsLatest,\n    resolveIfReady,\n    inProgressItems,\n    onJobStart,\n    onLatentPreview,\n    onNodeExecuted,\n    onJobComplete\n  }\n})\n","<script setup lang=\"ts\">\nimport { useQueueProgress } from '@/composables/queue/useQueueProgress'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst {\n  class: className,\n  overallOpacity = 1,\n  activeOpacity = 1,\n  rounded = false\n} = defineProps<{\n  class?: string\n  overallOpacity?: number\n  activeOpacity?: number\n  rounded?: boolean\n}>()\n\nconst { totalPercent, currentNodePercent } = useQueueProgress()\nconst executionStore = useExecutionStore()\n</script>\n<template>\n  <div\n    :class=\"\n      cn(\n        'relative h-2 bg-secondary-background transition-opacity',\n        !executionStore.isActiveWorkflowRunning && 'opacity-0',\n        rounded && 'rounded-sm',\n        className\n      )\n    \"\n  >\n    <div\n      data-testid=\"linear-progress-overall\"\n      class=\"absolute inset-0 h-full bg-interface-panel-job-progress-primary transition-[width]\"\n      :class=\"cn(rounded && 'rounded-sm')\"\n      :style=\"{ width: `${totalPercent}%`, opacity: overallOpacity }\"\n    />\n    <div\n      data-testid=\"linear-progress-node\"\n      class=\"absolute inset-0 h-full bg-interface-panel-job-progress-secondary transition-[width]\"\n      :class=\"cn(rounded && 'rounded-sm')\"\n      :style=\"{ width: `${currentNodePercent}%`, opacity: activeOpacity }\"\n    />\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport LinearProgressBar from '@/renderer/extensions/linearMode/LinearProgressBar.vue'\n\nconst { latentPreview } = defineProps<{\n  latentPreview?: string\n}>()\n</script>\n<template>\n  <div class=\"w-10\">\n    <img\n      v-if=\"latentPreview\"\n      data-testid=\"linear-latent-preview\"\n      class=\"block size-10 rounded-sm object-cover\"\n      :src=\"latentPreview\"\n    />\n    <div\n      v-else\n      data-testid=\"linear-skeleton\"\n      class=\"skeleton-shimmer size-10 rounded-sm\"\n    />\n    <LinearProgressBar\n      data-testid=\"linear-item-progress-bar\"\n      class=\"mt-1 h-1 w-10\"\n      rounded\n    />\n  </div>\n</template>\n","import { useAsyncState } from '@vueuse/core'\nimport type { ComputedRef } from 'vue'\nimport { computed, toValue, watchEffect } from 'vue'\n\nimport { getOutputAssetMetadata } from '@/platform/assets/schemas/assetMetadataSchema'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { flattenNodeOutput } from '@/renderer/extensions/linearMode/flattenNodeOutput'\nimport { useLinearOutputStore } from '@/renderer/extensions/linearMode/linearOutputStore'\nimport { api } from '@/scripts/api'\nimport { getJobDetail } from '@/services/jobOutputCache'\nimport { WrappedList } from '@/utils/pagedList'\nimport type { PagedList } from '@/utils/pagedList'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useQueueStore } from '@/stores/queueStore'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\n\nexport function useOutputHistory(): {\n  outputs: PagedList<AssetItem>\n  allOutputs: (item?: AssetItem) => AugmentedResultItem[]\n  selectFirstHistory: () => void\n  mayBeActiveWorkflowPending: ComputedRef<boolean>\n  isWorkflowActive: ComputedRef<boolean>\n  cancelActiveWorkflowJobs: () => Promise<void>\n} {\n  const assetsStore = useAssetsStore()\n  void assetsStore.outputAssets.loadMore()\n  const linearStore = useLinearOutputStore()\n  const workflowStore = useWorkflowStore()\n  const executionStore = useExecutionStore()\n  const appModeStore = useAppModeStore()\n  const queueStore = useQueueStore()\n\n  function matchesActiveWorkflow(task: { jobId: string | number }): boolean {\n    const path = workflowStore.activeWorkflow?.path\n    if (!path) return false\n    return (\n      executionStore.jobIdToSessionWorkflowPath.get(String(task.jobId)) === path\n    )\n  }\n\n  function hasActiveWorkflowJobs(): boolean {\n    if (!workflowStore.activeWorkflow?.path) return false\n    return queueStore.runningTasks.some(matchesActiveWorkflow)\n  }\n\n  // True when there are queued/running jobs for the active workflow but no\n  // in-progress output items yet.\n  const mayBeActiveWorkflowPending = computed(() => {\n    if (linearStore.activeWorkflowInProgressItems.length > 0) return false\n    return hasActiveWorkflowJobs()\n  })\n\n  // True when the active workflow has running/pending jobs or in-progress items.\n  const isWorkflowActive = computed(\n    () =>\n      linearStore.activeWorkflowInProgressItems.length > 0 ||\n      hasActiveWorkflowJobs()\n  )\n\n  function filterByOutputNodes(\n    items: AugmentedResultItem[]\n  ): AugmentedResultItem[] {\n    const nodeIds = appModeStore.selectedOutputs\n    if (!nodeIds.length) return []\n    return items.filter((r) =>\n      nodeIds.some((id) => String(id) === String(r.nodeId))\n    )\n  }\n\n  const outputs = new WrappedList(assetsStore.outputAssets, (items) => {\n    const path = workflowStore.activeWorkflow?.path\n    if (!path) return []\n\n    const pathMap = executionStore.jobIdToSessionWorkflowPath\n\n    return items.filter((asset) => {\n      const m = getOutputAssetMetadata(asset.user_metadata)\n      return m ? pathMap.get(m.jobId) === path : false\n    })\n  })\n\n  const resolvedCache = linearStore.resolvedOutputsCache\n  const asyncRefs = new Map<\n    string,\n    ReturnType<typeof useAsyncState<AugmentedResultItem[]>>['state']\n  >()\n\n  function allOutputs(item?: AssetItem): AugmentedResultItem[] {\n    if (!item?.id) return []\n\n    const cached = resolvedCache.get(item.id)\n    if (cached) return filterByOutputNodes(cached)\n\n    const user_metadata = getOutputAssetMetadata(item.user_metadata)\n    if (!user_metadata) return []\n\n    // For recently completed jobs still pending resolve, derive order from\n    // the in-progress items which are in correct execution order.\n    if (linearStore.pendingResolve.has(user_metadata.jobId)) {\n      const ordered = linearStore.inProgressItems\n        .filter((i) => i.jobId === user_metadata.jobId && i.output)\n        .map((i) => i.output!)\n      if (ordered.length > 0) {\n        resolvedCache.set(item.id, ordered)\n        return filterByOutputNodes(ordered)\n      }\n    }\n\n    // Use metadata when all outputs are present. The /jobs list endpoint\n    // only returns preview_output (single item), so outputCount may exceed\n    // allOutputs.length for multi-output jobs.\n    if (\n      user_metadata.allOutputs?.length &&\n      (!user_metadata.outputCount ||\n        user_metadata.outputCount <= user_metadata.allOutputs.length) &&\n      item.preview_url\n    ) {\n      const reversed = [...user_metadata.allOutputs].reverse()\n      resolvedCache.set(item.id, reversed)\n      return filterByOutputNodes(reversed)\n    }\n\n    // Async fallback for multi-output jobs — fetch full /jobs/{id} detail.\n    // This can be hit if the user executes the job then switches tabs.\n    const existing = asyncRefs.get(item.id)\n    if (existing) return filterByOutputNodes(existing.value)\n\n    const itemId = item.id\n    const outputRef = useAsyncState(\n      getJobDetail(user_metadata.jobId).then((jobDetail) => {\n        if (!jobDetail?.outputs) return []\n        const results = Object.entries(jobDetail.outputs)\n          .flatMap(flattenNodeOutput)\n          .reverse()\n        resolvedCache.set(itemId, results)\n        return results\n      }),\n      []\n    ).state\n    asyncRefs.set(item.id, outputRef)\n    return filterByOutputNodes(outputRef.value)\n  }\n\n  function selectFirstHistory() {\n    const first = toValue(outputs.items).at(0)\n    if (first) {\n      linearStore.selectAsLatest(`history:${first.id}:0`)\n    } else {\n      linearStore.selectAsLatest(null)\n    }\n  }\n\n  // Resolve in-progress items when history outputs are loaded.\n  watchEffect(() => {\n    if (linearStore.pendingResolve.size === 0) return\n    for (const jobId of linearStore.pendingResolve) {\n      const asset = toValue(outputs.items).find((a) => {\n        const m = getOutputAssetMetadata(a.user_metadata)\n        return m?.jobId === jobId\n      })\n      if (!asset) continue\n      const loaded = allOutputs(asset).length > 0\n      if (loaded) {\n        linearStore.resolveIfReady(jobId, true)\n        if (!linearStore.selectedId) selectFirstHistory()\n      }\n    }\n  })\n\n  async function cancelActiveWorkflowJobs() {\n    if (!workflowStore.activeWorkflow?.path) return\n\n    // Interrupt the running job if it belongs to this workflow\n    if (queueStore.runningTasks.some(matchesActiveWorkflow)) {\n      void useCommandStore().execute('Comfy.Interrupt')\n    } else {\n      // Delete first pending job for this workflow from the queue\n      for (const task of queueStore.pendingTasks) {\n        if (matchesActiveWorkflow(task)) {\n          await api.deleteItem('queue', task.jobId)\n          break\n        }\n      }\n    }\n  }\n\n  return {\n    outputs,\n    allOutputs,\n    selectFirstHistory,\n    mayBeActiveWorkflowPending,\n    isWorkflowActive,\n    cancelActiveWorkflowJobs\n  }\n}\n","<script setup lang=\"ts\">\nimport {\n  useEventListener,\n  useInfiniteScroll,\n  useResizeObserver\n} from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\nimport type { ComponentPublicInstance } from 'vue'\nimport {\n  computed,\n  nextTick,\n  ref,\n  toValue,\n  useTemplateRef,\n  watch,\n  watchEffect\n} from 'vue'\n\nimport { CanvasPointer } from '@/lib/litegraph/src/CanvasPointer'\nimport OutputHistoryActiveQueueItem from '@/renderer/extensions/linearMode/OutputHistoryActiveQueueItem.vue'\nimport OutputHistoryItem from '@/renderer/extensions/linearMode/OutputHistoryItem.vue'\nimport { useLinearOutputStore } from '@/renderer/extensions/linearMode/linearOutputStore'\nimport type {\n  OutputSelection,\n  SelectionValue\n} from '@/renderer/extensions/linearMode/linearModeTypes'\nimport OutputPreviewItem from '@/renderer/extensions/linearMode/OutputPreviewItem.vue'\nimport { useOutputHistory } from '@/renderer/extensions/linearMode/useOutputHistory'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useQueueStore } from '@/stores/queueStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { outputs, allOutputs, selectFirstHistory, mayBeActiveWorkflowPending } =\n  useOutputHistory()\nconst { hasOutputs } = storeToRefs(useAppModeStore())\nconst queueStore = useQueueStore()\nconst store = useLinearOutputStore()\nconst workflowStore = useWorkflowStore()\n\nconst emit = defineEmits<{\n  updateSelection: [selection: OutputSelection]\n}>()\n\nconst queueCount = computed(\n  () => queueStore.runningTasks.length + queueStore.pendingTasks.length\n)\n\nconst itemClass = cn(\n  'shrink-0 cursor-pointer rounded-lg border-2 border-transparent p-1 outline-none',\n  'relative data-[state=checked]:border-interface-panel-job-progress-border'\n)\n\nconst hasActiveContent = computed(\n  () => store.activeWorkflowInProgressItems.length > 0\n)\n\nconst visibleHistory = computed(() =>\n  toValue(outputs.items).filter((a) => allOutputs(a).length > 0)\n)\n\nconst selectableItems = computed(() => {\n  const items: SelectionValue[] = []\n  if (mayBeActiveWorkflowPending.value) {\n    items.push({ id: 'slot:pending', kind: 'inProgress', itemId: 'pending' })\n  }\n  for (const item of store.activeWorkflowInProgressItems) {\n    items.push({\n      id: `slot:${item.id}`,\n      kind: 'inProgress',\n      itemId: item.id\n    })\n  }\n  for (const asset of toValue(outputs.items)) {\n    const outs = allOutputs(asset)\n    for (let k = 0; k < outs.length; k++) {\n      items.push({\n        id: `history:${asset.id}:${k}`,\n        kind: 'history',\n        assetId: asset.id,\n        key: k\n      })\n    }\n  }\n  return items\n})\n\nconst selectionMap = computed(\n  () => new Map(selectableItems.value.map((v) => [v.id, v]))\n)\n\nconst selectedValue = computed(() => {\n  if (!store.selectedId) return undefined\n  return selectionMap.value.get(store.selectedId)\n})\n\nfunction itemAttrs(id: string) {\n  const selected = store.selectedId === id\n  return {\n    'data-state': selected ? 'checked' : 'unchecked',\n    tabindex: selected ? 0 : -1\n  }\n}\n\nconst selectedItemEl = ref<Element | null>(null)\n\nfunction selectedRef(id: string) {\n  return store.selectedId === id\n    ? (el: Element | ComponentPublicInstance | null) => {\n        selectedItemEl.value = el instanceof Element ? el : null\n      }\n    : undefined\n}\n\nfunction doEmit() {\n  const sel = selectedValue.value\n  if (!sel) {\n    emit('updateSelection', { canShowPreview: true })\n    return\n  }\n  if (sel.kind === 'inProgress') {\n    const item = store.activeWorkflowInProgressItems.find(\n      (i) => i.id === sel.itemId\n    )\n    if (!item || item.state === 'skeleton') {\n      emit('updateSelection', { canShowPreview: true, showSkeleton: true })\n    } else if (item.state === 'latent') {\n      emit('updateSelection', {\n        canShowPreview: true,\n        latentPreviewUrl: item.latentPreviewUrl\n      })\n    } else {\n      emit('updateSelection', {\n        output: item.output,\n        canShowPreview: true\n      })\n    }\n    return\n  }\n  const asset = toValue(outputs.items).find((a) => a.id === sel.assetId)\n  const output = asset ? allOutputs(asset)[sel.key] : undefined\n  const isFirst = toValue(outputs.items)[0]?.id === sel.assetId\n  emit('updateSelection', {\n    asset,\n    output,\n    canShowPreview: isFirst\n  })\n}\n\nwatchEffect(doEmit)\n\n// On load or workflow tab switch, select the most recent item.\n// Prefer in-progress items for this workflow, then history, skipping\n// the global pending slot which may belong to another workflow.\nwatch(\n  () => workflowStore.activeWorkflow?.path,\n  (path) => {\n    if (!path) return\n    const inProgress = store.activeWorkflowInProgressItems\n    if (inProgress.length > 0) {\n      store.selectAsLatest(`slot:${inProgress[0].id}`)\n    } else if (hasOutputs.value) {\n      selectFirstHistory()\n    } else {\n      store.selectAsLatest(null)\n    }\n  },\n  { immediate: true }\n)\n\n// Keep history selection stable on media changes\nwatch(\n  () => toValue(outputs.items),\n  (newAssets, oldAssets) => {\n    if (\n      newAssets.length === oldAssets.length ||\n      (oldAssets.length === 0 && newAssets.length !== 1)\n    )\n      return\n\n    if (store.selectedId?.startsWith('slot:')) return\n\n    const sv = store.selectedId\n      ? selectionMap.value.get(store.selectedId)\n      : undefined\n\n    if (!sv || sv.kind !== 'history') {\n      if (hasOutputs.value) selectFirstHistory()\n      return\n    }\n\n    const wasFirst = sv.assetId === oldAssets[0]?.id\n    if (wasFirst || !newAssets.some((a) => a.id === sv.assetId)) {\n      if (hasOutputs.value) selectFirstHistory()\n    }\n  }\n)\n\nconst outputsRef = useTemplateRef('outputsRef')\n\n// Track scrollWidth so we can compensate when items are prepended on the left.\nlet lastScrollWidth = 0\nuseResizeObserver(outputsRef, () => {\n  lastScrollWidth = outputsRef.value?.scrollWidth ?? 0\n})\nwatch(\n  () => visibleHistory.value[0]?.id,\n  () => {\n    const el = outputsRef.value\n    if (!el || el.scrollLeft === 0) {\n      lastScrollWidth = el?.scrollWidth ?? 0\n      return\n    }\n    nextTick(() => {\n      const delta = el.scrollWidth - lastScrollWidth\n      if (delta !== 0) el.scrollLeft += delta\n      lastScrollWidth = el.scrollWidth\n    })\n  }\n)\n\nuseInfiniteScroll(\n  outputsRef,\n  async () => {\n    await outputs.loadMore()\n  },\n  {\n    canLoadMore: () => toValue(outputs.hasMore)\n  }\n)\n\nfunction navigateToAdjacent(direction: 1 | -1) {\n  const items = selectableItems.value\n  if (items.length === 0) return\n  const currentId = store.selectedId\n  const idx = currentId ? items.findIndex((i) => i.id === currentId) : -1\n  const nextIdx =\n    idx === -1 ? 0 : Math.max(0, Math.min(items.length - 1, idx + direction))\n  store.select(items[nextIdx].id)\n  nextTick(() => {\n    selectedItemEl.value?.scrollIntoView({\n      block: 'nearest',\n      inline: 'nearest'\n    })\n  })\n}\n\nconst pointer = new CanvasPointer(document.body)\nlet scrollOffset = 0\nuseEventListener(\n  document.body,\n  'wheel',\n  function (e: WheelEvent) {\n    if (!e.ctrlKey && !e.metaKey) return\n    e.preventDefault()\n    e.stopPropagation()\n\n    if (!pointer.isTrackpadGesture(e)) {\n      if (e.deltaY > 0) navigateToAdjacent(1)\n      else navigateToAdjacent(-1)\n      return\n    }\n    scrollOffset += e.deltaY\n    while (scrollOffset >= 60) {\n      scrollOffset -= 60\n      navigateToAdjacent(1)\n    }\n    while (scrollOffset <= -60) {\n      scrollOffset += 60\n      navigateToAdjacent(-1)\n    }\n  },\n  { capture: true, passive: false }\n)\n\nuseEventListener(\n  outputsRef,\n  'wheel',\n  function (e: WheelEvent) {\n    if (e.ctrlKey || e.metaKey || e.deltaY === 0) return\n    e.preventDefault()\n    if (outputsRef.value) outputsRef.value.scrollLeft += e.deltaY\n  },\n  { passive: false }\n)\n\nconst keyHandlers: Record<string, 1 | -1> = {\n  ArrowUp: -1,\n  ArrowDown: 1,\n  ArrowLeft: -1,\n  ArrowRight: 1\n}\nuseEventListener(document.body, 'keydown', (e: KeyboardEvent) => {\n  if (\n    !(e.key in keyHandlers) ||\n    e.target instanceof HTMLTextAreaElement ||\n    e.target instanceof HTMLInputElement\n  )\n    return\n\n  e.preventDefault()\n  e.stopPropagation()\n  navigateToAdjacent(keyHandlers[e.key])\n})\n</script>\n<template>\n  <div\n    role=\"group\"\n    class=\"flex h-21 min-w-0 items-start justify-center px-4 py-3 pb-4\"\n  >\n    <div\n      v-if=\"queueCount > 0 || hasActiveContent\"\n      class=\"flex h-15 shrink-0 items-start gap-0.5\"\n    >\n      <OutputHistoryActiveQueueItem\n        v-if=\"queueCount > 1 || queueStore.pendingTasks.length\"\n        class=\"mr-3\"\n        :queue-count=\"queueCount\"\n      />\n\n      <div\n        v-if=\"mayBeActiveWorkflowPending\"\n        :ref=\"selectedRef('slot:pending')\"\n        v-bind=\"itemAttrs('slot:pending')\"\n        :class=\"itemClass\"\n        @click=\"store.select('slot:pending')\"\n      >\n        <OutputPreviewItem />\n      </div>\n\n      <div\n        v-for=\"item in store.activeWorkflowInProgressItems\"\n        :key=\"`${item.id}-${item.state}`\"\n        :ref=\"selectedRef(`slot:${item.id}`)\"\n        v-bind=\"itemAttrs(`slot:${item.id}`)\"\n        data-testid=\"linear-in-progress-item\"\n        :class=\"itemClass\"\n        @click=\"store.select(`slot:${item.id}`)\"\n      >\n        <OutputPreviewItem\n          v-if=\"item.state !== 'image' || !item.output\"\n          :latent-preview=\"item.latentPreviewUrl\"\n        />\n        <OutputHistoryItem v-else :output=\"item.output\" />\n      </div>\n\n      <div\n        v-if=\"hasActiveContent && visibleHistory.length > 0\"\n        class=\"mx-4 h-12 shrink-0 border-l border-border-default\"\n      />\n    </div>\n\n    <article\n      ref=\"outputsRef\"\n      data-testid=\"linear-outputs\"\n      class=\"min-w-0 overflow-x-auto overflow-y-clip\"\n    >\n      <div class=\"flex h-15 w-fit items-start gap-0.5\">\n        <template v-for=\"(asset, aIdx) in visibleHistory\" :key=\"asset.id\">\n          <div\n            v-if=\"aIdx > 0\"\n            class=\"mx-4 h-12 shrink-0 border-l border-border-default\"\n          />\n          <div\n            v-for=\"(output, key) in toValue(allOutputs(asset))\"\n            :key\n            :ref=\"selectedRef(`history:${asset.id}:${key}`)\"\n            v-bind=\"itemAttrs(`history:${asset.id}:${key}`)\"\n            data-testid=\"linear-history-item\"\n            :class=\"itemClass\"\n            @click=\"store.select(`history:${asset.id}:${key}`)\"\n          >\n            <OutputHistoryItem :output=\"output\" />\n          </div>\n        </template>\n      </div>\n    </article>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { computed, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport { downloadFile } from '@/base/common/downloadUtil'\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useMediaAssetActions } from '@/platform/assets/composables/useMediaAssetActions'\nimport type { AssetItem } from '@/platform/assets/schemas/assetSchema'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { extractWorkflowFromAsset } from '@/platform/workflow/utils/workflowExtractionUtil'\nimport ImagePreview from '@/renderer/extensions/linearMode/ImagePreview.vue'\nimport LatentPreview from '@/renderer/extensions/linearMode/LatentPreview.vue'\nimport LinearWelcome from '@/renderer/extensions/linearMode/LinearWelcome.vue'\nimport LinearArrange from '@/renderer/extensions/linearMode/LinearArrange.vue'\nimport MediaOutputPreview from '@/renderer/extensions/linearMode/MediaOutputPreview.vue'\nimport OutputHistory from '@/renderer/extensions/linearMode/OutputHistory.vue'\nimport { useOutputHistory } from '@/renderer/extensions/linearMode/useOutputHistory'\nimport type { OutputSelection } from '@/renderer/extensions/linearMode/linearModeTypes'\nimport { app } from '@/scripts/app'\nimport type { AugmentedResultItem } from '@/utils/resultItem'\nimport { resultItemUrl } from '@/utils/resultItemUrl'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst { t } = useI18n()\nconst mediaActions = useMediaAssetActions()\nconst { isBuilderMode, isArrangeMode } = useAppMode()\nconst { allOutputs, isWorkflowActive, cancelActiveWorkflowJobs } =\n  useOutputHistory()\nconst { runButtonClick, mobile } = defineProps<{\n  runButtonClick?: (e: Event) => void\n  mobile?: boolean\n}>()\n\nconst selectedItem = ref<AssetItem>()\nconst selectedOutput = ref<AugmentedResultItem>()\nconst canShowPreview = ref(true)\nconst latentPreview = ref<string>()\nconst showSkeleton = ref(false)\nconst menuSeparator: MenuItem = { separator: true }\n\nconst selectedItemMenuEntries = computed<MenuItem[]>(() => {\n  const item = selectedItem.value\n  if (!item) return []\n\n  return [\n    ...(allOutputs(item).length > 1\n      ? [\n          {\n            icon: 'icon-[lucide--download]',\n            label: t('linearMode.downloadAll', {\n              count: allOutputs(item).length\n            }),\n            command: () => downloadAsset(item)\n          },\n          menuSeparator\n        ]\n      : []),\n    {\n      icon: 'icon-[lucide--trash-2]',\n      label: t('linearMode.deleteAllAssets'),\n      command: () => mediaActions.deleteAssets(item)\n    }\n  ]\n})\n\nfunction handleSelection(sel: OutputSelection) {\n  selectedItem.value = sel.asset\n  selectedOutput.value = sel.output\n  canShowPreview.value = sel.canShowPreview\n  latentPreview.value = sel.latentPreviewUrl\n  showSkeleton.value = sel.showSkeleton ?? false\n}\n\nfunction downloadAsset(item?: AssetItem) {\n  for (const output of allOutputs(item))\n    downloadFile(resultItemUrl(output), output.filename)\n}\n\nfunction downloadOutput(output?: AugmentedResultItem) {\n  if (!output) return\n  const url = resultItemUrl(output)\n  if (url) downloadFile(url)\n}\n\nasync function loadWorkflow(item: AssetItem | undefined) {\n  if (!item) return\n  const { workflow } = await extractWorkflowFromAsset(item)\n  if (!workflow) return\n\n  if (workflow.id !== app.rootGraph.id) return app.loadGraphData(workflow)\n  //update graph to new version, set old to top of undo queue\n  const changeTracker = useWorkflowStore().activeWorkflow?.changeTracker\n  if (!changeTracker) return app.loadGraphData(workflow)\n  changeTracker.redoQueue = []\n  await changeTracker.updateState([workflow], changeTracker.undoQueue)\n}\n\nasync function rerun(e: Event) {\n  if (!runButtonClick) return\n  await loadWorkflow(selectedItem.value)\n  runButtonClick(e)\n}\n</script>\n<template>\n  <section\n    v-if=\"selectedItem || selectedOutput || showSkeleton || isWorkflowActive\"\n    data-testid=\"linear-output-info\"\n    class=\"flex w-full flex-wrap justify-center gap-2 p-4 text-sm tabular-nums md:z-10\"\n  >\n    <template v-if=\"selectedItem\">\n      <Button size=\"md\" @click=\"rerun\">\n        {{ t('linearMode.rerun') }}\n        <i class=\"icon-[lucide--refresh-cw]\" />\n      </Button>\n      <Button size=\"md\" @click=\"() => loadWorkflow(selectedItem)\">\n        {{ t('linearMode.reuseParameters') }}\n        <i class=\"icon-[lucide--list-restart]\" />\n      </Button>\n      <div class=\"mx-1 border-r border-border-subtle\" />\n    </template>\n    <Button\n      v-if=\"selectedOutput\"\n      :tooltip=\"t('g.download')\"\n      size=\"icon\"\n      :aria-label=\"t('g.download')\"\n      @click=\"() => downloadOutput(selectedOutput)\"\n    >\n      <i class=\"icon-[lucide--download]\" />\n    </Button>\n    <Button\n      v-if=\"isWorkflowActive && !selectedItem\"\n      data-testid=\"linear-cancel-run\"\n      variant=\"destructive\"\n      @click=\"cancelActiveWorkflowJobs()\"\n    >\n      <i class=\"icon-[lucide--x]\" />\n      {{ t('linearMode.cancelThisRun') }}\n    </Button>\n    <Menu v-if=\"selectedItem\" :items=\"selectedItemMenuEntries\">\n      <template #trigger>\n        <Button\n          size=\"icon\"\n          :aria-label=\"t('g.moreOptions')\"\n          icon=\"icon-[lucide--ellipsis]\"\n        />\n      </template>\n    </Menu>\n  </section>\n  <ImagePreview\n    v-if=\"canShowPreview && latentPreview\"\n    :mobile\n    :src=\"latentPreview\"\n    :show-size=\"false\"\n  />\n  <MediaOutputPreview\n    v-else-if=\"selectedOutput\"\n    :output=\"selectedOutput\"\n    :mobile\n  />\n  <LatentPreview v-else-if=\"showSkeleton || isWorkflowActive\" />\n  <LinearArrange v-else-if=\"isArrangeMode\" />\n  <LinearWelcome v-else />\n  <OutputHistory\n    v-if=\"!isBuilderMode\"\n    :class=\"cn(!mobile && 'z-10 min-w-0')\"\n    @update-selection=\"handleSelection\"\n  />\n</template>\n","<script setup lang=\"ts\">\nimport {\n  DialogClose,\n  DialogContent,\n  DialogOverlay,\n  DialogPortal,\n  DialogRoot,\n  DialogTitle,\n  DialogTrigger\n} from 'reka-ui'\nimport { useI18n } from 'vue-i18n'\n\nimport Button from '@/components/ui/button/Button.vue'\n\ndefineProps<{ title?: string; to?: string | HTMLElement }>()\n\nconst { t } = useI18n()\n</script>\n<template>\n  <DialogRoot v-slot=\"{ close }\">\n    <DialogTrigger as-child>\n      <slot name=\"button\" />\n    </DialogTrigger>\n    <DialogPortal :to>\n      <DialogOverlay\n        class=\"fixed inset-0 z-30 bg-black/70 data-[state=open]:animate-in data-[state=open]:fade-in-0\"\n      />\n      <DialogContent\n        v-bind=\"$attrs\"\n        class=\"fixed top-[50%] left-[50%] z-1700 max-h-[85vh] w-[90vw] max-w-[450px] -translate-1/2 rounded-2xl border border-border-subtle bg-base-background p-2 shadow-sm data-[state=open]:animate-in data-[state=open]:fade-in-0 data-[state=open]:zoom-in-95\"\n      >\n        <div\n          v-if=\"title\"\n          class=\"flex w-full items-center justify-between border-b border-border-subtle px-4\"\n        >\n          <DialogTitle class=\"text-sm\">{{ title }}</DialogTitle>\n          <DialogClose as-child>\n            <Button\n              :aria-label=\"t('g.close')\"\n              size=\"icon\"\n              variant=\"muted-textonly\"\n            >\n              <i class=\"icon-[lucide--x]\" />\n            </Button>\n          </DialogClose>\n        </div>\n        <slot :close />\n      </DialogContent>\n    </DialogPortal>\n  </DialogRoot>\n</template>\n","<script setup lang=\"ts\">\nimport { computed } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport Dialogue from '@/components/common/Dialogue.vue'\nimport { useErrorGroups } from '@/components/rightSidePanel/errors/useErrorGroups'\nimport Button from '@/components/ui/button/Button.vue'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useCopyToClipboard } from '@/composables/useCopyToClipboard'\nimport { useExternalLink } from '@/composables/useExternalLink'\nimport { resolveRunErrorMessage } from '@/platform/errorCatalog/errorMessageResolver'\nimport { buildSupportUrl } from '@/platform/support/config'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useExecutionErrorStore } from '@/stores/executionErrorStore'\n\ndefineEmits<{ navigateControls: [] }>()\n\nconst { t } = useI18n()\nconst appModeStore = useAppModeStore()\nconst { setMode } = useAppMode()\nconst executionErrorStore = useExecutionErrorStore()\nconst { buildDocsUrl, staticUrls } = useExternalLink()\nconst { allErrorGroups } = useErrorGroups('')\nconst { copyToClipboard } = useCopyToClipboard()\n\nconst guideUrl = buildDocsUrl('troubleshooting/overview', {\n  includeLocale: true\n})\nconst supportUrl = buildSupportUrl()\n\nconst inputNodeIds = computed(() => {\n  const ids = new Set()\n  for (const [id] of appModeStore.selectedInputs) ids.add(String(id))\n  return ids\n})\n\nconst accessibleNodeErrors = computed(() =>\n  Object.keys(executionErrorStore.surfacedNodeErrors ?? {}).filter((k) =>\n    inputNodeIds.value.has(k)\n  )\n)\nconst accessibleErrors = computed(() =>\n  accessibleNodeErrors.value.flatMap((k) => {\n    const nodeError = executionErrorStore.surfacedNodeErrors?.[k]\n    if (!nodeError) return []\n\n    return nodeError.errors.flatMap((error) => {\n      const { extra_info } = error\n      if (!extra_info) return []\n\n      const selectedInput = appModeStore.selectedInputs.find(\n        ([id, name]) => id == k && extra_info.input_name === name\n      )\n      if (!selectedInput) return []\n\n      const resolvedDisplay = resolveRunErrorMessage({\n        kind: 'node_validation',\n        error,\n        nodeDisplayName: nodeError.class_type\n      })\n\n      return [\n        resolvedDisplay.displayDetails ??\n          resolvedDisplay.displayMessage ??\n          `${selectedInput[1]}: ${error.message}`\n      ]\n    })\n  })\n)\nconst allErrors = computed(() =>\n  allErrorGroups.value.flatMap((group) => {\n    if (group.type !== 'execution') {\n      return [group.displayMessage ?? group.displayTitle]\n    }\n\n    return group.cards.flatMap((c) =>\n      c.errors.map((e) => {\n        const resolvedMessage = e.displayDetails ?? e.displayMessage\n        if (resolvedMessage) return resolvedMessage\n\n        return e.details\n          ? `${c.title} (${e.details}): ${e.message}`\n          : `${c.title}: ${e.message}`\n      })\n    )\n  })\n)\n\nfunction copy(obj: unknown) {\n  copyToClipboard(JSON.stringify(obj))\n}\n</script>\n<template>\n  <section class=\"flex h-full flex-col items-center justify-center gap-2 px-4\">\n    <i class=\"icon-[lucide--circle-alert] size-6 bg-error\" />\n    {{ t('linearMode.error.header') }}\n    <div class=\"p-1 text-muted-foreground\">\n      <i18n-t\n        v-if=\"accessibleErrors.length\"\n        keypath=\"linearMode.error.mobileFixable\"\n      >\n        <Button @click=\"$emit('navigateControls')\">\n          {{ t('linearMode.mobileControls') }}\n        </Button>\n      </i18n-t>\n      <div v-else class=\"text-center\">\n        <p v-text=\"t('linearMode.error.requiresGraph')\" />\n        <p v-text=\"t('linearMode.error.promptVisitGraph')\" />\n        <p class=\"*:text-muted-foreground\">\n          <i18n-t keypath=\"linearMode.error.getHelp\">\n            <a\n              :href=\"guideUrl\"\n              target=\"_blank\"\n              v-text=\"t('linearMode.error.guide')\"\n            />\n            <a\n              :href=\"staticUrls.githubIssues\"\n              target=\"_blank\"\n              v-text=\"t('linearMode.error.github')\"\n            />\n            <a\n              :href=\"supportUrl\"\n              target=\"_blank\"\n              v-text=\"t('linearMode.error.support')\"\n            />\n          </i18n-t>\n        </p>\n        <Dialogue :title=\"t('linearMode.error.log')\">\n          <template #button>\n            <Button variant=\"textonly\">\n              {{ t('linearMode.error.promptShow') }}\n              <i class=\"icon-[lucide--chevron-right] size-5\" />\n            </Button>\n          </template>\n          <template #default=\"{ close }\">\n            <article class=\"flex flex-col gap-2 p-4\">\n              <section class=\"flex max-h-[60vh] flex-col gap-2 overflow-y-auto\">\n                <div\n                  v-for=\"error in allErrors\"\n                  :key=\"error\"\n                  class=\"w-full rounded-lg bg-secondary-background p-2 text-muted-foreground\"\n                  v-text=\"error\"\n                />\n              </section>\n              <div class=\"flex items-center justify-end gap-4\">\n                <Button variant=\"muted-textonly\" size=\"lg\" @click=\"close\">\n                  {{ t('g.close') }}\n                </Button>\n                <Button size=\"lg\" @click=\"copy(allErrors)\">\n                  {{ t('importFailed.copyError') }}\n                  <i class=\"icon-[lucide--copy]\" />\n                </Button>\n              </div>\n            </article>\n          </template>\n        </Dialogue>\n      </div>\n    </div>\n    <div\n      v-if=\"accessibleErrors.length\"\n      class=\"my-8 w-full rounded-lg bg-secondary-background text-muted-foreground\"\n    >\n      <ul>\n        <li\n          v-for=\"error in accessibleErrors\"\n          :key=\"error\"\n          class=\"before:content\"\n          v-text=\"error\"\n        />\n      </ul>\n    </div>\n    <div class=\"flex gap-2\">\n      <Button\n        variant=\"textonly\"\n        size=\"lg\"\n        @click=\"executionErrorStore.dismissErrorOverlay()\"\n      >\n        {{ t('g.dismiss') }}\n      </Button>\n      <Button variant=\"textonly\" size=\"lg\" @click=\"setMode('graph')\">\n        {{ t('linearMode.viewGraph') }}\n      </Button>\n      <Button\n        v-if=\"accessibleErrors.length\"\n        size=\"lg\"\n        @click=\"copy(accessibleErrors)\"\n      >\n        {{ t('importFailed.copyError') }}\n        <i class=\"icon-[lucide--copy]\" />\n      </Button>\n    </div>\n  </section>\n</template>\n","<script setup lang=\"ts\">\nimport type { MenuItem } from '@/components/ui/menu/types'\nimport { useFullscreen, usePointerSwipe } from '@vueuse/core'\nimport { computed, ref, useTemplateRef } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport AssetsSidebarTab from '@/components/sidebar/tabs/AssetsSidebarTab.vue'\nimport CurrentUserButton from '@/components/topbar/CurrentUserButton.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Menu from '@/components/ui/menu/Menu.vue'\nimport MenuRadioGroup from '@/components/ui/menu/MenuRadioGroup.vue'\nimport { useCurrentUser } from '@/composables/auth/useCurrentUser'\nimport { APP_MODE_FEEDBACK_FORM_URL } from '@/platform/surveys/appModeFeedback'\nimport { useWorkflowService } from '@/platform/workflow/core/services/workflowService'\nimport { useWorkflowStore } from '@/platform/workflow/management/stores/workflowStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport LinearControls from '@/renderer/extensions/linearMode/LinearControls.vue'\nimport LinearPreview from '@/renderer/extensions/linearMode/LinearPreview.vue'\nimport MobileError from '@/renderer/extensions/linearMode/MobileError.vue'\nimport { useColorPaletteService } from '@/services/colorPaletteService'\nimport { useErrorOverlayState } from '@/components/error/useErrorOverlayState'\nimport { useQueueStore } from '@/stores/queueStore'\nimport { useMenuItemStore } from '@/stores/menuItemStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { cn } from '@comfyorg/tailwind-utils'\n\nconst tabs = [\n  ['linearMode.mobileControls', 'icon-[lucide--play]', 'control'],\n  ['nodeHelpPage.outputs', 'icon-[comfy--image-ai-edit]', 'preview'],\n  ['sideToolbar.assets', 'icon-[lucide--images]', 'output']\n]\n\nconst canvasStore = useCanvasStore()\nconst colorPaletteService = useColorPaletteService()\nconst colorPaletteStore = useColorPaletteStore()\nconst { isLoggedIn } = useCurrentUser()\nconst { isVisible: isErrorOverlayVisible } = useErrorOverlayState()\nconst { t } = useI18n()\nconst { commandIdToMenuItem } = useMenuItemStore()\nconst queueStore = useQueueStore()\nconst workflowService = useWorkflowService()\nconst workflowStore = useWorkflowStore()\nconst { toggle: toggleFullscreen } = useFullscreen(undefined, {\n  autoExit: true\n})\n\nconst activeIndex = ref(1)\nconst sliderPaneRef = useTemplateRef('sliderPaneRef')\nconst sliderWidth = computed(() => sliderPaneRef.value?.offsetWidth)\n\nconst { distanceX, isSwiping } = usePointerSwipe(sliderPaneRef, {\n  disableTextSelect: true,\n  onSwipeEnd() {\n    if (\n      !sliderWidth.value ||\n      Math.abs(distanceX.value) / sliderWidth.value < 0.4\n    )\n      return\n    if (distanceX.value < 0)\n      activeIndex.value = Math.max(activeIndex.value - 1, 0)\n    else activeIndex.value = Math.min(activeIndex.value + 1, tabs.length - 1)\n  }\n})\n\nconst translate = computed(() => {\n  const slideOffset =\n    isSwiping.value && sliderWidth.value\n      ? distanceX.value / sliderWidth.value\n      : 0\n  const totalOffset = slideOffset + activeIndex.value\n  return `${totalOffset * -100}vw`\n})\n\nfunction onClick(index: number) {\n  if (Math.abs(distanceX.value) > 30) return\n  activeIndex.value = index\n}\n\nconst workflowOptions = computed(() =>\n  workflowStore.openWorkflows.map((workflow) => ({\n    value: workflow.path,\n    label: workflow.filename,\n    icon: workflow.activeState?.extra?.linearMode\n      ? 'icon-[lucide--panels-top-left]'\n      : undefined\n  }))\n)\nconst activeWorkflowPath = computed({\n  get: () => workflowStore.activeWorkflow?.path ?? '',\n  set: (path: string) => {\n    const workflow = workflowStore.getWorkflowByPath(path)\n    if (workflow) void workflowService.openWorkflow(workflow)\n  }\n})\n\nconst menuEntries = computed<MenuItem[]>(() => [\n  {\n    ...commandIdToMenuItem('Comfy.BrowseTemplates'),\n    label: t('sideToolbar.templates'),\n    icon: 'icon-[comfy--template]'\n  },\n  { separator: true },\n  {\n    label: t('icon.file'),\n    items: [\n      commandIdToMenuItem('Comfy.RenameWorkflow'),\n      commandIdToMenuItem('Comfy.DuplicateWorkflow'),\n      { separator: true },\n      commandIdToMenuItem('Comfy.SaveWorkflow'),\n      commandIdToMenuItem('Comfy.SaveWorkflowAs'),\n      { separator: true },\n      commandIdToMenuItem('Comfy.ExportWorkflow'),\n      commandIdToMenuItem('Comfy.ExportWorkflowAPI')\n    ]\n  },\n  {\n    label: t('g.edit'),\n    items: [\n      commandIdToMenuItem('Comfy.Undo'),\n      commandIdToMenuItem('Comfy.Redo'),\n      { separator: true },\n      commandIdToMenuItem('Comfy.RefreshNodeDefinitions'),\n      commandIdToMenuItem('Comfy.Memory.UnloadModels'),\n      commandIdToMenuItem('Comfy.Memory.UnloadModelsAndExecutionCache')\n    ]\n  },\n  {\n    label: t('linearMode.enterNodeGraph'),\n    icon: 'icon-[comfy--workflow]',\n    new: true,\n    command: () => (canvasStore.linearMode = false)\n  },\n  { separator: true },\n  {\n    label: t('menu.theme'),\n    items: colorPaletteStore.palettes.map((palette) => ({\n      label: palette.name,\n      icon:\n        colorPaletteStore.activePaletteId === palette.id\n          ? 'icon-[lucide--check]'\n          : '',\n      command: () => colorPaletteService.loadColorPalette(palette.id)\n    }))\n  },\n  { separator: true },\n  {\n    ...commandIdToMenuItem('Comfy.ShowSettingsDialog'),\n    label: t('menu.settings')\n  },\n  {\n    label: t('linearMode.giveFeedback'),\n    icon: 'icon-[lucide--clipboard-pen]',\n    command: () =>\n      window.open(APP_MODE_FEEDBACK_FORM_URL, '_blank', 'noopener,noreferrer')\n  },\n  {\n    label: t('menu.fullscreen'),\n    icon: 'icon-[lucide--fullscreen]',\n    command: toggleFullscreen\n  }\n])\n</script>\n<template>\n  <section\n    class=\"absolute flex size-full flex-col bg-secondary-background\"\n    data-testid=\"linear-mobile\"\n  >\n    <header\n      class=\"flex h-16 w-full items-center gap-3 border-b border-border-subtle bg-base-background px-4 py-3\"\n    >\n      <Menu :items=\"menuEntries\" :label=\"$t('linearMode.appModeToolbar.apps')\">\n        <template #trigger>\n          <Button\n            size=\"icon\"\n            icon=\"icon-[lucide--menu]\"\n            :aria-label=\"$t('g.more')\"\n          />\n        </template>\n      </Menu>\n      <Menu>\n        <template #trigger>\n          <Button\n            variant=\"secondary\"\n            class=\"min-w-0 flex-1\"\n            data-testid=\"linear-mobile-workflows\"\n            icon=\"icon-[lucide--panels-top-left]\"\n          >\n            <span\n              class=\"min-w-0 flex-1 truncate\"\n              v-text=\"workflowStore.activeWorkflow?.filename\"\n            />\n            <i\n              class=\"icon-[lucide--chevron-down] size-4 shrink-0\"\n              aria-hidden=\"true\"\n            />\n          </Button>\n        </template>\n        <MenuRadioGroup\n          v-model=\"activeWorkflowPath\"\n          :options=\"workflowOptions\"\n        />\n      </Menu>\n      <CurrentUserButton v-if=\"isLoggedIn\" :show-arrow=\"false\" />\n    </header>\n    <div class=\"size-full rounded-b-4xl contain-content\">\n      <div\n        :class=\"\n          cn('relative size-full', !isSwiping && 'transition-[translate]')\n        \"\n        :style=\"{ translate }\"\n      >\n        <div\n          id=\"mobile-app-control-panel\"\n          class=\"absolute h-full w-screen overflow-y-auto contain-size\"\n          role=\"tabpanel\"\n          :aria-hidden=\"activeIndex !== 0\"\n          aria-labelledby=\"mobile-app-control-tab\"\n          :inert=\"activeIndex !== 0\"\n        >\n          <LinearControls mobile @navigate-outputs=\"activeIndex = 1\" />\n        </div>\n        <div\n          id=\"mobile-app-preview-panel\"\n          class=\"absolute top-0 left-[100vw] flex h-full w-screen flex-col bg-base-background\"\n          role=\"tabpanel\"\n          :aria-hidden=\"activeIndex !== 1\"\n          aria-labelledby=\"mobile-app-preview-tab\"\n          :inert=\"activeIndex !== 1\"\n        >\n          <MobileError\n            v-if=\"isErrorOverlayVisible\"\n            @navigate-controls=\"activeIndex = 0\"\n          />\n          <LinearPreview v-else mobile @navigate-controls=\"activeIndex = 0\" />\n        </div>\n        <AssetsSidebarTab\n          id=\"mobile-app-output-panel\"\n          class=\"absolute top-0 left-[200vw] h-full w-screen bg-base-background\"\n          role=\"tabpanel\"\n          :aria-hidden=\"activeIndex !== 2\"\n          aria-labelledby=\"mobile-app-output-tab\"\n          :inert=\"activeIndex !== 2\"\n          :closable=\"false\"\n        />\n      </div>\n    </div>\n    <div\n      ref=\"sliderPaneRef\"\n      class=\"flex h-22 w-full items-center justify-around gap-4 bg-secondary-background p-4\"\n      role=\"tablist\"\n    >\n      <Button\n        v-for=\"([label, icon, id], index) in tabs\"\n        :id=\"`mobile-app-${id}-tab`\"\n        :key=\"label\"\n        :variant=\"index === activeIndex ? 'secondary' : 'muted-textonly'\"\n        class=\"h-14 grow flex-col\"\n        role=\"tab\"\n        :aria-selected=\"index === activeIndex\"\n        :aria-controls=\"`mobile-app-${id}-panel`\"\n        @click=\"onClick(index)\"\n      >\n        <div class=\"relative size-4\">\n          <i :class=\"cn('size-4', icon)\" />\n          <div\n            v-if=\"index === 1 && isErrorOverlayVisible\"\n            class=\"absolute -top-1 -right-1 size-2 rounded-full bg-error\"\n          />\n          <div\n            v-else-if=\"\n              index === 1 &&\n              (queueStore.runningTasks.length > 0 ||\n                queueStore.pendingTasks.length > 0)\n            \"\n            class=\"absolute -top-1 -right-1 size-2 animate-pulse rounded-full bg-primary-background\"\n          />\n        </div>\n        {{ t(label) }}\n      </Button>\n    </div>\n  </section>\n</template>\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport {\n  breakpointsTailwind,\n  unrefElement,\n  useBreakpoints,\n  useElementSize\n} from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\nimport { computed, useTemplateRef } from 'vue'\n\nimport AppBuilder from '@/components/builder/AppBuilder.vue'\nimport AppModeToolbar from '@/components/appMode/AppModeToolbar.vue'\nimport ExtensionSlot from '@/components/common/ExtensionSlot.vue'\nimport SideToolbar from '@/components/sidebar/SideToolbar.vue'\nimport WorkflowTabs from '@/components/topbar/WorkflowTabs.vue'\nimport SplitterGroup from '@/components/ui/splitter/SplitterGroup.vue'\nimport SplitterPanel from '@/components/ui/splitter/SplitterPanel.vue'\nimport SplitterResizeHandle from '@/components/ui/splitter/SplitterResizeHandle.vue'\nimport { usePanelSizing } from '@/composables/usePanelSizing'\nimport { COACH_IDS } from '@/platform/onboarding/onboardingTours'\nimport { vCoachmark } from '@/platform/onboarding/vCoachmark'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport LinearControls from '@/renderer/extensions/linearMode/LinearControls.vue'\nimport LinearPreview from '@/renderer/extensions/linearMode/LinearPreview.vue'\nimport LinearProgressBar from '@/renderer/extensions/linearMode/LinearProgressBar.vue'\nimport MobileDisplay from '@/renderer/extensions/linearMode/MobileDisplay.vue'\nimport { useWorkspaceStore } from '@/stores/workspaceStore'\nimport { useAppMode } from '@/composables/useAppMode'\nimport {\n  BUILDER_MIN_SIZE,\n  SIDEBAR_MIN_SIZE,\n  SIDEBAR_MIN_WIDTH,\n  SIDE_PANEL_SIZE,\n  SIDE_TOOLBAR_WIDTH\n} from '@/constants/splitterConstants'\nimport { useAppModeStore } from '@/stores/appModeStore'\nimport { useAgentDockMount } from '@/workbench/extensions/agent/composables/useAgentDockMount'\n\nconst settingStore = useSettingStore()\nconst { docked: agentDocked, DockedAgentPanel } = useAgentDockMount()\nconst workspaceStore = useWorkspaceStore()\nconst { isBuilderMode, isArrangeMode } = useAppMode()\nconst appModeStore = useAppModeStore()\nconst { hasOutputs } = storeToRefs(appModeStore)\n\nconst mobileDisplay = useBreakpoints(breakpointsTailwind).smaller('md')\n\nconst activeTab = computed(() => workspaceStore.sidebarTab.activeSidebarTab)\nconst assetsPanelCoach = computed(() =>\n  activeTab.value?.id === 'assets' ? COACH_IDS.assetsPanel : undefined\n)\nconst sidebarOnLeft = computed(\n  () => settingStore.get('Comfy.Sidebar.Location') === 'left'\n)\nconst showLeftBuilder = computed(\n  () => !sidebarOnLeft.value && isArrangeMode.value\n)\nconst showRightBuilder = computed(\n  () => sidebarOnLeft.value && isArrangeMode.value\n)\nconst hasLeftPanel = computed(\n  () =>\n    isArrangeMode.value ||\n    (sidebarOnLeft.value && activeTab.value) ||\n    (!sidebarOnLeft.value && !isBuilderMode.value && hasOutputs.value)\n)\nconst hasRightPanel = computed(\n  () =>\n    isArrangeMode.value ||\n    (sidebarOnLeft.value && !isBuilderMode.value && hasOutputs.value) ||\n    (!sidebarOnLeft.value && activeTab.value)\n)\nconst leftPanelVisible = computed(\n  () => hasLeftPanel.value && !(showRightBuilder.value && !activeTab.value)\n)\nconst rightPanelVisible = computed(\n  () => hasRightPanel.value && !(showLeftBuilder.value && !activeTab.value)\n)\n\nfunction sidePanelMinSize(isBuilder: boolean) {\n  return Math.max(\n    isBuilder ? BUILDER_MIN_SIZE : SIDEBAR_MIN_SIZE,\n    availableSplitterWidth.value > 0\n      ? (SIDEBAR_MIN_WIDTH / availableSplitterWidth.value) * 100\n      : 0\n  )\n}\n\nconst workspaceRef = useTemplateRef('workspace')\nconst { width: workspaceWidth } = useElementSize(workspaceRef)\nconst availableSplitterWidth = computed(() =>\n  Math.max(\n    0,\n    workspaceWidth.value -\n      (isBuilderMode.value ? 0 : SIDE_TOOLBAR_WIDTH) -\n      Number(leftPanelVisible.value) -\n      Number(rightPanelVisible.value)\n  )\n)\nconst {\n  panelPercentages,\n  panelRefs,\n  onResizeStart,\n  onResizeDragging,\n  onResizeEnd\n} = usePanelSizing(\n  [\n    {\n      id: 'linear-left-panel',\n      storageKey: 'Comfy.LinearView.LeftPanelWidth',\n      visible: () => Boolean(leftPanelVisible.value),\n      minWidth: SIDEBAR_MIN_WIDTH,\n      defaultWidth: () =>\n        Math.max(SIDEBAR_MIN_WIDTH, (window.innerWidth * SIDE_PANEL_SIZE) / 100)\n    },\n    {\n      id: 'linear-right-panel',\n      storageKey: 'Comfy.LinearView.RightPanelWidth',\n      visible: () => Boolean(rightPanelVisible.value),\n      minWidth: SIDEBAR_MIN_WIDTH,\n      defaultWidth: () =>\n        Math.max(SIDEBAR_MIN_WIDTH, (window.innerWidth * SIDE_PANEL_SIZE) / 100)\n    }\n  ],\n  availableSplitterWidth,\n  () => window.innerWidth * 0.2\n)\n\nconst bottomLeftRef = useTemplateRef('bottomLeftRef')\nconst bottomRightRef = useTemplateRef('bottomRightRef')\nconst linearWorkflowRef = useTemplateRef('linearWorkflowRef')\n\nfunction dragDrop(e: DragEvent) {\n  const { dataTransfer } = e\n  if (dataTransfer) linearWorkflowRef.value?.handleDragDrop()\n}\n</script>\n<template>\n  <MobileDisplay v-if=\"mobileDisplay\" />\n  <div v-else class=\"absolute flex size-full flex-col\" @dragover.prevent>\n    <div\n      class=\"workflow-tabs-container pointer-events-auto h-(--workflow-tabs-height) w-full border-b border-interface-stroke/50 shadow-interface\"\n    >\n      <WorkflowTabs />\n    </div>\n    <div class=\"flex min-h-0 flex-1 flex-row bg-secondary-background\">\n      <div\n        ref=\"workspace\"\n        data-testid=\"linear-workspace-column\"\n        :class=\"\n          cn(\n            'flex min-w-0 flex-1 overflow-hidden',\n            sidebarOnLeft ? 'flex-row' : 'flex-row-reverse'\n          )\n        \"\n      >\n        <SideToolbar\n          v-if=\"!isBuilderMode\"\n          :visible-tab-ids=\"['assets', 'apps']\"\n          force-connected\n          hide-workspace-toggles\n        />\n        <SplitterGroup\n          class=\"h-full flex-1 border-none bg-secondary-background\"\n          @keydown.capture=\"onResizeStart\"\n          @keyup=\"onResizeEnd\"\n          @focusout=\"onResizeEnd\"\n        >\n          <SplitterPanel\n            v-if=\"leftPanelVisible\"\n            id=\"linear-left-panel\"\n            :ref=\"panelRefs.first\"\n            data-testid=\"linear-left-panel\"\n            :order=\"1\"\n            :default-size=\"panelPercentages[0]\"\n            :min-size=\"sidePanelMinSize(showLeftBuilder)\"\n            class=\"arrange-panel min-w-78 overflow-hidden bg-comfy-menu-bg outline-none\"\n          >\n            <AppBuilder v-if=\"showLeftBuilder\" />\n            <div\n              v-else-if=\"sidebarOnLeft && activeTab\"\n              v-coachmark=\"assetsPanelCoach\"\n              class=\"size-full overflow-x-hidden border-r border-border-subtle\"\n            >\n              <ExtensionSlot :extension=\"activeTab\" />\n            </div>\n            <LinearControls\n              v-else-if=\"!isArrangeMode\"\n              ref=\"linearWorkflowRef\"\n              :toast-to=\"unrefElement(bottomLeftRef) ?? undefined\"\n            />\n          </SplitterPanel>\n          <SplitterResizeHandle\n            v-if=\"leftPanelVisible\"\n            @dragging=\"onResizeDragging($event, 'linear-left-panel')\"\n          />\n          <SplitterPanel\n            id=\"linearCenterPanel\"\n            v-coachmark=\"COACH_IDS.outputs\"\n            :order=\"2\"\n            data-testid=\"linear-center-panel\"\n            :default-size=\"panelPercentages[1]\"\n            :min-size=\"\n              availableSplitterWidth > 0\n                ? ((workspaceWidth * 0.2) / availableSplitterWidth) * 100\n                : 0\n            \"\n            class=\"relative flex min-w-[20vw] flex-col gap-4 text-muted-foreground outline-none\"\n            @drop=\"dragDrop\"\n          >\n            <LinearProgressBar\n              data-testid=\"linear-header-progress-bar\"\n              class=\"absolute top-0 left-0 z-21 h-1 w-[calc(100%+16px)]\"\n            />\n            <LinearPreview\n              :run-button-click=\"linearWorkflowRef?.runButtonClick\"\n            />\n            <div class=\"absolute top-2 left-2 z-21\">\n              <AppModeToolbar v-if=\"!isBuilderMode\" />\n            </div>\n            <div ref=\"bottomLeftRef\" class=\"absolute bottom-7 left-4 z-20\" />\n            <div ref=\"bottomRightRef\" class=\"absolute right-4 bottom-7 z-20\" />\n          </SplitterPanel>\n          <SplitterResizeHandle\n            v-if=\"rightPanelVisible\"\n            @dragging=\"onResizeDragging($event, 'linear-right-panel')\"\n          />\n          <SplitterPanel\n            v-if=\"rightPanelVisible\"\n            id=\"linear-right-panel\"\n            :ref=\"panelRefs.last\"\n            data-testid=\"linear-right-panel\"\n            :order=\"3\"\n            :default-size=\"panelPercentages[2]\"\n            :min-size=\"sidePanelMinSize(showRightBuilder)\"\n            class=\"arrange-panel min-w-78 overflow-hidden bg-comfy-menu-bg outline-none\"\n          >\n            <AppBuilder v-if=\"showRightBuilder\" />\n            <LinearControls\n              v-else-if=\"sidebarOnLeft && !isArrangeMode\"\n              ref=\"linearWorkflowRef\"\n              :toast-to=\"unrefElement(bottomRightRef) ?? undefined\"\n            />\n            <div\n              v-else-if=\"activeTab\"\n              v-coachmark=\"assetsPanelCoach\"\n              class=\"h-full overflow-x-hidden border-l border-border-subtle\"\n            >\n              <ExtensionSlot :extension=\"activeTab\" />\n            </div>\n          </SplitterPanel>\n        </SplitterGroup>\n      </div>\n      <!-- App mode hides the canvas, so the panel never meets bare graph. -->\n      <component\n        :is=\"DockedAgentPanel\"\n        v-if=\"agentDocked\"\n        :has-opaque-neighbor=\"true\"\n      />\n    </div>\n  </div>\n</template>\n","<script setup lang=\"ts\">\nimport { cn } from '@comfyorg/tailwind-utils'\nimport { useScroll, whenever } from '@vueuse/core'\nimport type { ComponentPublicInstance } from 'vue'\nimport { computed, onBeforeUnmount, onMounted, ref } from 'vue'\nimport { useI18n } from 'vue-i18n'\n\nimport DotSpinner from '@/components/common/DotSpinner.vue'\nimport ToastPanel from '@/components/ui/toast/ToastPanel.vue'\nimport Button from '@/components/ui/button/Button.vue'\nimport Tabs from '@/components/ui/tabs/Tabs.vue'\nimport TabsContent from '@/components/ui/tabs/TabsContent.vue'\nimport TabsList from '@/components/ui/tabs/TabsList.vue'\nimport TabsTrigger from '@/components/ui/tabs/TabsTrigger.vue'\nimport { useApplyChanges } from '@/workbench/extensions/manager/composables/useApplyChanges'\nimport { useComfyManagerStore } from '@/workbench/extensions/manager/stores/comfyManagerStore'\n\nconst { t } = useI18n()\nconst comfyManagerStore = useComfyManagerStore()\nconst { isRestarting, isRestartCompleted, applyChanges } = useApplyChanges()\n\nconst isExpanded = ref(false)\nconst activeTab = ref('installation')\n\nconst tabs = computed(() => [\n  {\n    value: 'installation',\n    label: t('manager.installationQueue'),\n    logs: comfyManagerStore.succeededTasksLogs\n  },\n  {\n    value: 'failed',\n    label: t('manager.failed', {\n      count: comfyManagerStore.failedTasksIds.length\n    }),\n    logs: comfyManagerStore.failedTasksLogs\n  }\n])\nconst activeTabData = computed(\n  () => tabs.value.find((tab) => tab.value === activeTab.value) ?? tabs.value[0]\n)\n\nconst visible = computed(() => comfyManagerStore.taskLogs.length > 0)\n\nconst isInProgress = computed(\n  () => comfyManagerStore.isProcessingTasks || isRestarting.value\n)\nconst hasSuccessfulTasks = computed(\n  () => comfyManagerStore.succeededTasksIds.length > 0\n)\n\nconst completedTasksCount = computed(() => {\n  return (\n    comfyManagerStore.succeededTasksIds.length +\n    comfyManagerStore.failedTasksIds.length\n  )\n})\n\nconst totalTasksCount = computed(() => {\n  const completedTasks = Object.keys(comfyManagerStore.taskHistory).length\n  const taskQueue = comfyManagerStore.taskQueue\n  const queuedTasks = taskQueue\n    ? (taskQueue.running_queue?.length || 0) +\n      (taskQueue.pending_queue?.length || 0)\n    : 0\n  return completedTasks + queuedTasks\n})\n\nconst currentTaskName = computed(() => {\n  if (isRestarting.value) {\n    return t('manager.restartingBackend')\n  }\n  if (isRestartCompleted.value) {\n    return t('manager.extensionsSuccessfullyInstalled')\n  }\n  if (!comfyManagerStore.taskLogs.length)\n    return t('manager.installingDependencies')\n  const task = comfyManagerStore.taskLogs.at(-1)\n  return task?.taskName ?? t('manager.installingDependencies')\n})\n\nconst announcement = computed(() => {\n  if (comfyManagerStore.queueError && isInProgress.value)\n    return t('manager.queueWaitingToContinue')\n  if (isRestarting.value || isRestartCompleted.value)\n    return currentTaskName.value\n  if (isInProgress.value) return t('manager.installingDependencies')\n  if (hasSuccessfulTasks.value) return t('manager.restartToApplyChanges')\n  if (comfyManagerStore.failedTasksIds.length) return t('g.failed')\n  return t('g.completed')\n})\n\nconst sectionsContainerRef = ref<HTMLElement | null>(null)\nconst { y: scrollY } = useScroll(sectionsContainerRef, {\n  eventListenerOptions: { passive: true }\n})\n\nconst latestLogContainerRef = ref<HTMLElement | null>(null)\nconst isUserScrolling = ref(false)\nconst latestTaskLogLines = computed(\n  () =>\n    tabs.value.find((tab) => tab.value === activeTab.value)?.logs.at(-1)?.logs\n)\n\nfunction setLatestLogContainer(el: Element | ComponentPublicInstance | null) {\n  latestLogContainerRef.value = el instanceof HTMLElement ? el : null\n}\n\nfunction isAtBottom(el: HTMLElement | null) {\n  if (!el) return false\n  const threshold = 20\n  return Math.abs(el.scrollHeight - el.scrollTop - el.clientHeight) < threshold\n}\n\nfunction scrollLatestLogToBottom() {\n  if (!latestLogContainerRef.value || isUserScrolling.value) return\n  latestLogContainerRef.value.scrollTop =\n    latestLogContainerRef.value.scrollHeight\n}\n\nfunction scrollContentToBottom() {\n  scrollY.value = sectionsContainerRef.value?.scrollHeight ?? 0\n}\n\nfunction resetUserScrolling() {\n  isUserScrolling.value = false\n}\n\nfunction handleScroll(e: Event) {\n  if (!(e.target instanceof HTMLElement)) return\n  const target = e.target\n  if (target !== latestLogContainerRef.value) return\n  isUserScrolling.value = !isAtBottom(target)\n}\n\nfunction onLogsAdded() {\n  if (isUserScrolling.value) return\n  scrollLatestLogToBottom()\n}\n\nwhenever(latestTaskLogLines, onLogsAdded, { flush: 'post', deep: true })\nwhenever(\n  () => isExpanded.value,\n  () => {\n    scrollContentToBottom()\n    scrollLatestLogToBottom()\n  },\n  { flush: 'post' }\n)\nwhenever(() => !isExpanded.value, resetUserScrolling)\n\nfunction closeToast() {\n  comfyManagerStore.resetTaskState()\n  isRestartCompleted.value = false\n  isExpanded.value = false\n}\n\nasync function handleRestart() {\n  try {\n    await applyChanges(closeToast)\n  } catch (err) {\n    console.error('[ManagerProgressToast] Restart failed:', err)\n  }\n}\n\nonMounted(() => {\n  scrollContentToBottom()\n})\n\nonBeforeUnmount(() => {\n  isExpanded.value = false\n})\n</script>\n\n<template>\n  <ToastPanel v-model:expanded=\"isExpanded\" :visible :announcement>\n    <template #default>\n      <Tabs\n        v-if=\"isExpanded\"\n        v-model=\"activeTab\"\n        class=\"gap-0\"\n        orientation=\"horizontal\"\n      >\n        <div class=\"flex items-center px-4 py-2\">\n          <TabsList variant=\"flush\" class=\"flex w-full\">\n            <TabsTrigger\n              v-for=\"tab in tabs\"\n              :key=\"tab.value\"\n              :value=\"tab.value\"\n              variant=\"flush\"\n            >\n              {{ tab.label }}\n            </TabsTrigger>\n          </TabsList>\n        </div>\n\n        <TabsContent :value=\"activeTab\" class=\"mt-0\">\n          <div\n            ref=\"sectionsContainerRef\"\n            role=\"region\"\n            :aria-label=\"activeTabData.label\"\n            class=\"scroll-container max-h-[450px] overflow-y-auto px-6 py-4\"\n            :style=\"{\n              scrollbarWidth: 'thin',\n              scrollbarColor: 'rgba(156, 163, 175, 0.5) transparent'\n            }\"\n          >\n            <details\n              v-for=\"(log, index) in activeTabData.logs\"\n              :key=\"log.taskId\"\n              open\n              class=\"group/log mt-2 rounded-lg border border-interface-stroke bg-interface-panel-surface shadow-interface\"\n            >\n              <summary\n                class=\"flex w-full cursor-pointer list-none items-center justify-between px-4 py-2 [&::-webkit-details-marker]:hidden\"\n              >\n                <span class=\"flex flex-col text-sm/normal font-medium\">\n                  <span>{{ log.taskName }}</span>\n                  <span class=\"text-muted\">\n                    {{\n                      comfyManagerStore.isTaskFailed(log.taskId)\n                        ? t('g.failed')\n                        : comfyManagerStore.isTaskInProgress(log.taskId)\n                          ? t('g.inProgress')\n                          : t('g.completedWithCheckmark')\n                    }}\n                  </span>\n                </span>\n                <i\n                  aria-hidden=\"true\"\n                  class=\"icon-[lucide--chevron-right] size-4 text-neutral-300 group-open/log:rotate-90\"\n                />\n              </summary>\n              <div\n                :ref=\"\n                  index === activeTabData.logs.length - 1\n                    ? setLatestLogContainer\n                    : undefined\n                \"\n                role=\"log\"\n                :aria-label=\"log.taskName\"\n                :class=\"\n                  cn(\n                    'h-64 overflow-y-auto rounded-lg bg-black',\n                    index === activeTabData.logs.length - 1 && 'grow'\n                  )\n                \"\n                @scroll=\"handleScroll\"\n              >\n                <div class=\"h-full\">\n                  <div\n                    v-for=\"(logLine, logIndex) in log.logs\"\n                    :key=\"logIndex\"\n                    class=\"text-muted\"\n                  >\n                    <pre class=\"wrap-break-word whitespace-pre-wrap\">{{\n                      logLine\n                    }}</pre>\n                  </div>\n                </div>\n              </div>\n            </details>\n          </div>\n        </TabsContent>\n      </Tabs>\n    </template>\n\n    <template #footer=\"{ toggle }\">\n      <div\n        class=\"flex w-full items-center justify-between gap-4 px-6 py-2 shadow-lg\"\n      >\n        <div class=\"flex min-w-0 items-center text-base leading-none\">\n          <div class=\"flex items-center\">\n            <span v-if=\"comfyManagerStore.queueError && isInProgress\">\n              {{ t('manager.queueWaitingToContinue') }}\n            </span>\n            <template v-else-if=\"isInProgress\">\n              <DotSpinner duration=\"1s\" class=\"mr-2\" />\n              <span>{{ currentTaskName }}</span>\n            </template>\n            <template v-else-if=\"isRestartCompleted\">\n              <span class=\"mr-2\">🎉</span>\n              <span>{{ currentTaskName }}</span>\n            </template>\n            <template v-else-if=\"hasSuccessfulTasks\">\n              <span class=\"mr-2\">✅</span>\n              <span>{{ t('manager.restartToApplyChanges') }}</span>\n            </template>\n            <span\n              v-else-if=\"comfyManagerStore.failedTasksIds.length\"\n              class=\"text-error\"\n              >{{ t('g.failed') }}</span\n            >\n            <span v-else>{{ t('g.completed') }}</span>\n          </div>\n        </div>\n        <div class=\"flex shrink-0 items-center gap-4\">\n          <span\n            v-if=\"isInProgress && !comfyManagerStore.queueError\"\n            class=\"text-sm text-muted-foreground\"\n          >\n            {{ completedTasksCount }} {{ t('g.progressCountOf') }}\n            {{ totalTasksCount }}\n          </span>\n          <div class=\"flex items-center\">\n            <Button\n              v-if=\"comfyManagerStore.queueError && isInProgress\"\n              variant=\"secondary\"\n              @click=\"comfyManagerStore.startQueue\"\n            >\n              {{ t('manager.retryQueueStart') }}\n            </Button>\n            <Button\n              v-if=\"!isInProgress && !isRestartCompleted && hasSuccessfulTasks\"\n              variant=\"secondary\"\n              class=\"mr-4 rounded-full border-2 border-base-foreground px-3 text-base-foreground hover:bg-secondary-background-hover\"\n              @click=\"handleRestart\"\n            >\n              {{ t('manager.applyChanges') }}\n            </Button>\n            <Button\n              v-if=\"!isRestartCompleted\"\n              variant=\"muted-textonly\"\n              size=\"sm\"\n              class=\"rounded-full font-bold\"\n              :aria-label=\"\n                t(isExpanded ? 'contextMenu.Collapse' : 'contextMenu.Expand')\n              \"\n              @click.stop=\"toggle\"\n            >\n              <i\n                :class=\"isExpanded ? 'pi pi-chevron-up' : 'pi pi-chevron-down'\"\n              />\n            </Button>\n            <Button\n              variant=\"muted-textonly\"\n              size=\"sm\"\n              class=\"rounded-full font-bold\"\n              :aria-label=\"t('g.close')\"\n              :disabled=\"isInProgress\"\n              @click.stop=\"closeToast\"\n            >\n              <i class=\"pi pi-times\" />\n            </Button>\n          </div>\n        </div>\n      </div>\n    </template>\n  </ToastPanel>\n</template>\n","<template>\n  <div class=\"comfyui-body grid size-full overflow-hidden\">\n    <div id=\"comfyui-body-top\" class=\"comfyui-body-top\" />\n    <div id=\"comfyui-body-bottom\" class=\"comfyui-body-bottom\" />\n    <div id=\"comfyui-body-left\" class=\"comfyui-body-left\" />\n    <div id=\"comfyui-body-right\" class=\"comfyui-body-right\" />\n    <div\n      v-show=\"!linearMode\"\n      id=\"graph-canvas-container\"\n      ref=\"graphCanvasContainerRef\"\n      class=\"graph-canvas-container\"\n    >\n      <GraphCanvas @ready=\"onGraphReady\" />\n    </div>\n    <LinearView v-if=\"linearMode\" />\n    <template v-if=\"isBuilderMode\">\n      <BuilderToolbar />\n      <BuilderMenu />\n      <BuilderFooterToolbar />\n    </template>\n  </div>\n\n  <Toaster />\n  <ToastDock>\n    <ModelImportProgressDialog />\n    <AssetExportProgressDialog />\n    <ManagerProgressToast />\n  </ToastDock>\n  <PartnerNodesEducationCard v-if=\"!isCloud\" />\n  <DesktopCloudNotificationController />\n  <UnloadWindowConfirmDialog v-if=\"!isDesktop\" />\n  <MenuHamburger />\n  <TourOverlay v-if=\"graphReady\" />\n  <FirstRunTour />\n</template>\n\n<script setup lang=\"ts\">\nimport { useEventListener, useIntervalFn } from '@vueuse/core'\nimport { storeToRefs } from 'pinia'\n\nimport {\n  computed,\n  nextTick,\n  onBeforeUnmount,\n  onMounted,\n  ref,\n  watch,\n  watchEffect\n} from 'vue'\n\nimport { runWhenGlobalIdle } from '@/base/common/async'\nimport MenuHamburger from '@/components/MenuHamburger.vue'\nimport UnloadWindowConfirmDialog from '@/components/dialog/UnloadWindowConfirmDialog.vue'\nimport GraphCanvas from '@/components/graph/GraphCanvas.vue'\nimport PartnerNodesEducationCard from '@/components/actionbar/PartnerNodesEducationCard.vue'\nimport ToastDock from '@/components/ui/toast/ToastDock.vue'\nimport Toaster from '@/components/ui/toast/Toaster.vue'\nimport TourOverlay from '@/platform/onboarding/TourOverlay.vue'\nimport FirstRunTour from '@/renderer/extensions/firstRunTour/FirstRunTour.vue'\nimport { registerCoreBottomPanelTabs } from '@/composables/bottomPanelTabs/registerCoreBottomPanelTabs'\nimport { useProgressTextPreviews } from '@/composables/node/useProgressTextPreviews'\nimport { registerCoreSidebarTabs } from '@/composables/sidebarTabs/registerCoreSidebarTabs'\nimport { useBrowserTabTitle } from '@/composables/useBrowserTabTitle'\nimport { useCoreCommands } from '@/composables/useCoreCommands'\nimport { useQueuePolling } from '@/platform/remote/comfyui/useQueuePolling'\nimport { useErrorHandling } from '@/composables/useErrorHandling'\nimport { useReconnectQueueRefresh } from '@/composables/useReconnectQueueRefresh'\nimport { useReconnectingNotification } from '@/composables/useReconnectingNotification'\nimport { useProgressFavicon } from '@/composables/useProgressFavicon'\nimport { runMissingMediaPipeline } from '@/platform/missingMedia/missingMediaPipeline'\nimport { scanAllMediaCandidates } from '@/platform/missingMedia/missingMediaScan'\nimport { startTemplateInputDownloadGraphSync } from '@/platform/workflow/templates/composables/useTemplateInputDownloadGraphSync'\nimport { refreshDownloadedTemplateInputBindings } from '@/platform/workflow/templates/utils/refreshDownloadedTemplateInputBindings'\nimport { SERVER_CONFIG_ITEMS } from '@/constants/serverConfig'\nimport type { ServerConfig, ServerConfigValue } from '@/constants/serverConfig'\nimport { setActiveLocale } from '@/i18n'\nimport AssetBrowserModal from '@/platform/assets/components/AssetBrowserModal.vue'\nimport AssetExportProgressDialog from '@/platform/assets/components/AssetExportProgressDialog.vue'\nimport ModelImportProgressDialog from '@/platform/assets/components/ModelImportProgressDialog.vue'\nimport { registerAssetBrowserModalComponent } from '@/platform/assets/composables/useAssetBrowserDialog'\nimport DesktopCloudNotificationController from '@/platform/cloud/notification/components/DesktopCloudNotificationController.vue'\nimport { isCloud, isDesktop } from '@/platform/distribution/types'\nimport SettingDialog from '@/platform/settings/components/SettingDialog.vue'\nimport { registerSettingDialogComponent } from '@/platform/settings/composables/useSettingsDialog'\nimport { useSettingStore } from '@/platform/settings/settingStore'\nimport { useTelemetry } from '@/platform/telemetry'\nimport { reportError } from '@/platform/telemetry/reportError'\nimport { getShellLayoutSnapshot } from '@/platform/telemetry/utils/getShellLayoutSnapshot'\nimport { getPageVisibilityMetadata } from '@/workbench/extensions/agent/utils/getPageVisibilityMetadata'\nimport { useFrontendVersionMismatchWarning } from '@/platform/updates/common/useFrontendVersionMismatchWarning'\nimport { useVersionCompatibilityStore } from '@/platform/updates/common/versionCompatibilityStore'\nimport { useCanvasStore } from '@/renderer/core/canvas/canvasStore'\nimport type { StatusWsMessageStatus } from '@/platform/remote/comfyui/execution/types'\nimport { api } from '@/scripts/api'\nimport { app } from '@/scripts/app'\nimport { setupAutoQueueHandler } from '@/services/autoQueueService'\nimport { useKeybindingService } from '@/platform/keybindings/keybindingService'\nimport { useAppMode } from '@/composables/useAppMode'\nimport { useCommandStore } from '@/stores/commandStore'\nimport { useExecutionStore } from '@/stores/executionStore'\nimport { useAuthStore } from '@/stores/authStore'\nimport { useAssetsStore } from '@/stores/assetsStore'\nimport { useMenuItemStore } from '@/stores/menuItemStore'\nimport { useModelStore } from '@/stores/modelStore'\nimport { useNodeDefStore, useNodeFrequencyStore } from '@/stores/nodeDefStore'\nimport {\n  useQueuePendingTaskCountStore,\n  useQueueStore\n} from '@/stores/queueStore'\nimport { useServerConfigStore } from '@/stores/serverConfigStore'\nimport { useTemplateInputDownloadStore } from '@/stores/templateInputDownloadStore'\nimport { useColorPaletteStore } from '@/stores/workspace/colorPaletteStore'\nimport { useSidebarTabStore } from '@/stores/workspace/sidebarTabStore'\nimport { electronAPI } from '@/utils/envUtil'\nimport { createUuidv4 } from '@/utils/uuid'\nimport BuilderFooterToolbar from '@/components/builder/BuilderFooterToolbar.vue'\nimport BuilderMenu from '@/components/builder/BuilderMenu.vue'\nimport BuilderToolbar from '@/components/builder/BuilderToolbar.vue'\nimport LinearView from '@/views/LinearView.vue'\nimport ManagerProgressToast from '@/workbench/extensions/manager/components/ManagerProgressToast.vue'\n\nsetupAutoQueueHandler()\nuseProgressFavicon()\nuseProgressTextPreviews()\nuseBrowserTabTitle()\n\nconst settingStore = useSettingStore()\nconst executionStore = useExecutionStore()\nconst colorPaletteStore = useColorPaletteStore()\nconst queueStore = useQueueStore()\nconst assetsStore = useAssetsStore()\nconst versionCompatibilityStore = useVersionCompatibilityStore()\nconst graphCanvasContainerRef = ref<HTMLDivElement | null>(null)\nconst graphReady = ref(false)\nconst { isBuilderMode, mode, isAppMode } = useAppMode()\nconst { linearMode } = storeToRefs(useCanvasStore())\nconst templateInputDownloadStore = useTemplateInputDownloadStore()\nconst templateInputGraphSync = startTemplateInputDownloadGraphSync({\n  getReferencedInputNames: () =>\n    new Set(scanAllMediaCandidates(app.rootGraph).map(({ name }) => name)),\n  refreshGraphBindings: async (completedInputNames) => {\n    try {\n      await app.reloadNodeDefs()\n      refreshDownloadedTemplateInputBindings(\n        app.rootGraph,\n        scanAllMediaCandidates(app.rootGraph),\n        new Set(completedInputNames)\n      )\n      await runMissingMediaPipeline({ rootGraph: app.rootGraph, silent: true })\n    } finally {\n      // The transfers finished even if rebinding them did not. Releasing them\n      // either way keeps a failed rebind from holding the run action behind a\n      // permanent finalizing state; the failure is reported separately.\n      templateInputDownloadStore.completeGraphSync(completedInputNames)\n    }\n  },\n  reportError: (error) => {\n    reportError(error, {\n      surface: 'graph',\n      errorType: 'workflow_template_input_refresh_failed'\n    })\n  }\n})\nconst stopTemplateInputDownloadTracking =\n  (isDesktop &&\n    window.__comfyDesktop2?.onTemplateInputDownloadProgress?.((progress) => {\n      templateInputDownloadStore.updateProgress(progress)\n      templateInputGraphSync.handleProgress(progress)\n    })) ||\n  (() => undefined)\n\nonBeforeUnmount(() => {\n  stopTemplateInputDownloadTracking()\n  templateInputGraphSync.dispose()\n  templateInputDownloadStore.clear()\n})\n\nwatch(linearMode, (isLinear) => {\n  if (isLinear) {\n    useSidebarTabStore().activeSidebarTabId = null\n  }\n})\n\nconst telemetry = useTelemetry()\nconst authStore = useAuthStore()\nlet hasTrackedLogin = false\n\nwatch(\n  () => colorPaletteStore.completedActivePalette,\n  (newTheme) => {\n    const DARK_THEME_CLASS = 'dark-theme'\n    if (newTheme.light_theme) {\n      document.documentElement.classList.remove(DARK_THEME_CLASS)\n    } else {\n      document.documentElement.classList.add(DARK_THEME_CLASS)\n    }\n    if (isDesktop) {\n      electronAPI().changeTheme({\n        color: 'rgba(0, 0, 0, 0)',\n        symbolColor: newTheme.colors.comfy_base['input-text']\n      })\n    }\n  },\n  { immediate: true }\n)\n\n/**\n * Reports task completion telemetry to Electron analytics when tasks\n * transition from running to history.\n *\n * No `deep: true` needed — `queueStore.tasks` is a computed that spreads\n * three `shallowRef` arrays into a new array on every change, and\n * `TaskItemImpl` instances are immutable (replaced, never mutated).\n */\nif (isDesktop) {\n  watch(\n    () => queueStore.tasks,\n    (newTasks, oldTasks) => {\n      const oldRunningTaskIds = new Set(\n        oldTasks.filter((task) => task.isRunning).map((task) => task.jobId)\n      )\n      newTasks\n        .filter((task) => oldRunningTaskIds.has(task.jobId) && task.isHistory)\n        .forEach((task) => {\n          electronAPI().Events.incrementUserProperty(\n            `execution:${task.displayStatus.toLowerCase()}`,\n            1\n          )\n          electronAPI().Events.trackEvent('execution', {\n            status: task.displayStatus.toLowerCase()\n          })\n        })\n    }\n  )\n}\n\nwatchEffect(() => {\n  const fontSize = settingStore.get('Comfy.TextareaWidget.FontSize')\n  document.documentElement.style.setProperty(\n    '--comfy-textarea-font-size',\n    `${fontSize}px`\n  )\n})\n\nwatchEffect(() => {\n  const padding = settingStore.get('Comfy.TreeExplorer.ItemPadding')\n  document.documentElement.style.setProperty(\n    '--tree-item-padding',\n    `${padding}px`\n  )\n})\n\nwatchEffect(async () => {\n  const locale = settingStore.get('Comfy.Locale')\n  if (!locale) return\n  try {\n    const resolved = await setActiveLocale(locale)\n    // Self-heal: a stored value from an older build (e.g. 'de') would otherwise\n    // leave the language dropdown — derived from SUPPORTED_LOCALE_OPTIONS —\n    // showing nothing selected until the user picks one manually.\n    if (resolved !== locale) {\n      await settingStore.set('Comfy.Locale', resolved)\n    }\n  } catch (error) {\n    con